/** Ported from `cutscene_build_bridge_1.gml`, `Cutscene_SariaBridge_init.gml`, `Cutscene_SariaBridge_update.gml`. */
import { DEPTH_FG3, DEPTH_FG6, dk_BridgeCrumble, PC_LOCK_ALL, TID_ONEWY1, TID_SOLID1 } from '@z2/data'
import { gmBool } from '../../../nes/math8'
import { f, G, g } from '../../../runtime/world'
import { find_clm_solid, find_row_solid } from '../../collision/solid'
import { inRange, sign_ } from '../../math'
import { val } from '../../other'
import { aud_play_sound } from '../../sound/play'
import { get_audio_theme_track } from '../../sound/theme'
import { tile_change_1a } from '../../tile/tileOps'
import type { Cutscene_SariaBridge } from './classes'
import { Cutscene_init } from './cutscene'

/**
 * `cutscene_build_bridge_1(build dir, speed, x base, y base, *bridge clm limit, *depth, *tileset, *tsrc top, *tsrc btm)`
 * _DIR: 0 build from both ends meeting in middle, 1 left→right, -1 right→left.
 */
export function cutscene_build_bridge_1(
  self: Cutscene_SariaBridge,
  dir: number,
  speed: number,
  xBase: number,
  yBase: number,
  clmLimit = 0,
  depth = -1,
  tileset: string | 0 = 0,
  tsrcTop = -1,
  tsrcBtm = -1,
): void {
  if (
    !gmBool(val(f.dm_quests.get(self.BUILD_QUAL_DK))) ||
    g.ChangeRoom_timer > 0 || // g.change_room_tmr is NOT a whole number. Need >0 check.
    gmBool(g.EnterRoom_SpawnGO_timer)
  )
    return
  // 2: Talk to NPC only once and bridge will auto build when PC is close enough.
  if (
    g.mod_BuildBridge_COND === 2 &&
    !gmBool(g.cutscene) &&
    gmBool(val(f.dm_quests.get(self.BUILD_QUAL_DK)))
  ) {
    const _CLMS = 8 // PC proximity to water edge to trigger build
    const _XL = (self.CLM_L - _CLMS) << 3
    const _DIST = (self.CLMS + (_CLMS << 1)) << 3
    if (!inRange(G.pc.x, _XL, _XL + _DIST)) return
  }
  // -------------------------------------------------------------------------------------
  const _DIR = Math.sign(dir)
  const _SPEED = Math.min(Math.max(speed, 1), 8) // build 1 clm every 2,4,8,16,32,64,128,256 frames
  const _TIMING = (1 << _SPEED) - 1
  let _x = (xBase >> 3) << 3
  const _Y = (yBase >> 3) << 3
  let _CLM_LIMIT = 0x10
  if (gmBool(clmLimit)) _CLM_LIMIT = clmLimit
  // +1 to guarantee cutscene_ctr = 8 for the first bridge piece instead of possibly 0 or 8
  if (!gmBool(g.cutscene))
    g.cutscene_ctr = (g.counter1 & _TIMING) + 1 // First frame of cutscene.
  else g.cutscene_ctr++
  g.cutscene = 1
  // A7CD
  if (g.cutscene_ctr & _TIMING) return
  // -------------------------------------------------------------------------------------
  let _DEPTH = DEPTH_FG3
  if (depth !== -1) _DEPTH = depth
  let _TS: string = 'ts_Man_made_1a_WRB'
  if (tileset) _TS = tileset
  let _TSRC_TOP = 0xb0 // $B0: railings
  if (tsrcTop + 1) _TSRC_TOP = tsrcTop
  let _TSRC_BTM = 0xa0 // $A0: new graphic, $B1: OG graphic
  if (tsrcBtm + 1) _TSRC_BTM = tsrcBtm
  // -------------------------------------------------------------------------------------
  const _COUNT1 = g.cutscene_ctr >> _SPEED
  let _COUNT2 = _DIR === 0 && (!(_CLM_LIMIT & 1) || _COUNT1 < _CLM_LIMIT >> 1) ? 1 : 0
  _COUNT2++
  const _XL = (self.CLM_L + (_COUNT1 - 1)) << 3 // _DIR: 0,1
  const _XR = (self.CLM_R - (_COUNT1 - 1)) << 3 // _DIR:  -1
  if (_DIR + 1)
    _x = _XL // _DIR: 0,1
  else _x = _XR // _DIR:  -1
  // _COUNT2 == 1,2.
  for (let _i = 0; _i < _COUNT2; _i++) {
    tile_change_1a(_DEPTH, _x, _Y - 8, _TS, _TSRC_TOP, 0) // bridge top half
    tile_change_1a(_DEPTH, _x, _Y, _TS, _TSRC_BTM, 2) // bridge btm half
    _x = _XR // if _DIR==0, add another segment from the opposite end next _i iteration.
  }
  aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
  if (
    (_DIR === 0 && _COUNT1 >= _CLM_LIMIT >> 1) || // When building from both ends
    (_DIR !== 0 && _COUNT1 >= _CLM_LIMIT) // When building from  one end
  ) {
    // Bridge is complete.
    g.cutscene = 0
    g.pc_lock = 0
  }
}

/** `Cutscene_SariaBridge_init()` — locate the river gap from the solid grid. */
export function Cutscene_SariaBridge_init(self: Cutscene_SariaBridge): void {
  Cutscene_init(self)
  self.scr_step = Cutscene_SariaBridge_update as never
  self.DIR = -1 // The river search dir
  if (gmBool(self.DIR)) self.CLM = 0
  else self.CLM = G.dg_solid_w - 1
  self.ROW = G.dg_solid_h - 2
  //
  self.CLM = find_clm_solid(0, self.CLM, self.ROW, self.DIR, 0, self.CLM)
  self.ROW = find_row_solid(0, self.CLM + -self.DIR, self.ROW, -1, 0, self.ROW - 2)
  self.ROW++
  //
  const _clm = find_clm_solid(
    TID_SOLID1 | TID_ONEWY1,
    self.CLM,
    self.ROW,
    self.DIR,
    0,
    self.CLM + 8 * self.DIR,
  )
  //
  self.CLMS = Math.abs(_clm - self.CLM)
  self.CLM_L = Math.min(_clm, self.CLM) + (gmBool(self.DIR) ? 0 : 1) // left   column
  self.CLM_R = self.CLM_L + (self.CLMS - 1) // right  column
  self.CLM_C = self.CLM_L + (self.CLMS >> 1) // center column
  //
  self.DIR = sign_(G.pc.x < self.CLM_C << 3) // The direction of the build
  if (gmBool(self.DIR)) self.CLM = self.CLM_L
  else self.CLM = self.CLM_R
  //
  if (self.CLMS > 0x10) {
    // Build from both ends, meet in middle.
    self.DIR = 0
    self.CLM = self.CLM_L
  }
  self.SPEED = 3 // 3: Every 8 frames
  self.BUILD_QUAL_DK = f.BuildBridge_QUAL_DK + g.rm_name
}

/** `Cutscene_SariaBridge_update()` */
export function Cutscene_SariaBridge_update(self: Cutscene_SariaBridge): void {
  const _cutscene = g.cutscene
  // DEPTH_FG6: So PI_BGR_2 is used. DEPTH_FG2 is the river, any tiles on it would move also.
  cutscene_build_bridge_1(self, self.DIR, self.SPEED, self.CLM << 3, self.ROW << 3, self.CLMS, DEPTH_FG6)
  if (gmBool(g.cutscene)) g.pc_lock = PC_LOCK_ALL // Lock all
  if (gmBool(_cutscene) && !gmBool(g.cutscene)) {
    // Frame of build completion
    self.destroy() // prevent infinite build
  }
}
