import type { Instance } from '../../runtime/instance'

// biome-ignore lint/suspicious/noExplicitAny: object classes are heterogeneous
export type ObjectClass = abstract new (...args: any[]) => Instance

const classes = new Map<string, ObjectClass>()

/** Register a ported GameMaker object class under its ZALiA object name (`registerObjectClass('Item', Item)`). */
export function registerObjectClass(name: string, cls: ObjectClass): void {
  classes.set(name, cls)
}

/** Look up a registered class; throws if the object has not been ported/registered yet. */
export function objectClass(name: string): ObjectClass {
  const c = classes.get(name)
  if (!c) throw new Error(`object class ${name} is not registered (not ported yet?)`)
  return c
}

export function hasObjectClass(name: string): boolean {
  return classes.has(name)
}

/** Tests only. */
export function _clearObjectClasses(): void {
  classes.clear()
}
