/**
 * Scene palette string maintenance: `change_pal`, `update_scene_palette`, `add_pi_permut`, `get_pi`,
 * `palSpr_changeColors` (→ PaletteImage), `pal_swap_set` / `pal_swap_reset`.
 */
import {
  PI_PERMUTATIONS,
  STR_Color,
  STR_Count,
  STR_Dark,
  STR_Description,
  STR_Index,
  STR_Order,
  STR_Palette,
  STR_Permutation,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { gmBool } from '../../nes/math8'
import { p } from '../../runtime/world'
import {
  COLORS_PER_PALETTE,
  color_str,
  PAL_BASE_COLOR_ORDER,
  PAL_CHAR_PER_COLOR,
  strReplaceAt,
} from './colors'
import { build_pal, get_pal_col_pos, get_pal_color, get_pal_pos, string_copy } from './palString'
import {
  PAL_CHAR_PER_SCENE,
  PAL_PER_SCENE,
  PAL_PER_SET,
  PI_DRK1,
  PI_MOB_BLU,
  PI_MOB_ORG,
  PI_MOB_PUR,
  PI_MOB_RED,
  PI_PERMUT_BASE,
} from './pi'

const DK1 = STR_Palette + STR_Index

/** `change_pal(new palette)` — set the frame's palette and rebuild the permutation palettes. */
export function change_pal(newPalette: string): string {
  p.pal_rm_new = newPalette
  // re-build all the permut pi's in case they've changed in the middle of the frame
  update_scene_palette()
  return p.pal_rm_new
}

/**
 * `update_scene_palette()` — truncate `pal_rm_new` to the scene set and append one rebuilt palette per
 * registered permutation. `rmBrightness` is `g.rm_brightness` (passed in so this file has no `g` dependency).
 * *** pal_rm_new is the current palette WITHIN the current frame; pal_rm_curr is what palette_image holds.
 */
export function update_scene_palette(rmBrightness = currentBrightness()): string {
  p.pal_rm_new = string_copy(p.pal_rm_new, 1, PAL_CHAR_PER_SCENE)
  if (rmBrightness === 1) {
    // When a scene is semi-lit, you can only see the bright colors of enemies. Make sure the palettes they
    // use have the same color from the lit version as this color can depend on the particular scene.
    for (const pi of [PI_MOB_ORG, PI_MOB_RED, PI_MOB_BLU, PI_MOB_PUR]) {
      p.pal_rm_new = strReplaceAt(
        p.pal_rm_new,
        get_pal_col_pos(pi + PI_DRK1, 'W'),
        PAL_CHAR_PER_COLOR,
        color_str(get_pal_color(p.pal_rm_new, pi, 'R')),
      )
    }
  }
  const _COUNT1 = p.dm_pi.val(STR_Permutation + STR_Count) as number
  for (let i = 0; i < _COUNT1; i++) {
    // each pi permut
    const _pi = p.dm_pi.val(STR_Permutation + hexStr(i + 1) + DK1) as number
    const _parent_pi = p.dm_pi.val(`${hexStr(_pi)}_Parent${DK1}`) as number
    const _order = String(p.dm_pi.val(hexStr(_pi) + STR_Color + STR_Order))
    const _parent_pal_pos = get_pal_pos(_parent_pi)
    const cols: (number | string)[] = [
      p.C_WHT0_,
      p.C_RED0_,
      p.C_BLU0_,
      p.C_GRN0_,
      p.C_YLW0_,
      p.C_MGN0_,
      p.C_BLK0_,
      p.C_CYN0_,
    ]
    for (let j = 0; j < COLORS_PER_PALETTE; j++) {
      // each color: the j-th colour of the permutation takes the parent's colour named by _order[j]
      const _char = _order[j] ?? ''
      let _pos = Math.max(0, PAL_BASE_COLOR_ORDER.indexOf(_char) + 1 - 1)
      _pos *= PAL_CHAR_PER_COLOR
      _pos = _parent_pal_pos + _pos
      const _color = string_copy(p.pal_rm_new, _pos, PAL_CHAR_PER_COLOR)
      cols[j] = _color
    }
    p.pal_rm_new += build_pal(...cols)
  }
  return p.pal_rm_new
}

let brightnessProvider: () => number = () => 3
/** The Game port installs `() => g.rm_brightness` here (avoids a hard dependency on `g`'s shape). */
export function setBrightnessProvider(fn: () => number): void {
  brightnessProvider = fn
}
function currentBrightness(): number {
  return brightnessProvider()
}

/**
 * `add_pi_permut(parent pi, color order, description)` — register (or find) a permutation of a base
 * palette: the same colours in a different `WRBGYMKC` order. Returns its (lit) palette index; the dark
 * twin is the next index. Permutations start at PAL_PER_SCENE.
 */
export function add_pi_permut(parentPi: number, colorOrder: string, description: string): number {
  if (colorOrder === PAL_BASE_COLOR_ORDER || parentPi >= PAL_PER_SCENE) return parentPi // not a permutation / already one
  // make sure this isn't a dark palette
  const _PARENT_PI = parentPi % PAL_PER_SET
  const existing = p.dm_pi.val(hexStr(_PARENT_PI) + colorOrder + DK1) as number
  if (existing) return existing
  const _return_pi = PAL_PER_SCENE + (p.dm_pi.val(STR_Permutation + STR_Count) as number)
  p.dm_pi.set(hexStr(_return_pi) + STR_Description, description)
  p.dm_pi.set(hexStr(_return_pi + 1) + STR_Description, `${description + STR_Dark}1`)
  p.dm_pi.set(`${hexStr(_return_pi)}${STR_Dark}1`, _return_pi + 1)
  for (let i = 0; i < 2; i++) {
    const _parent_pi = i ? _PARENT_PI + PI_DRK1 : _PARENT_PI
    const count = (p.dm_pi.val(STR_Permutation + STR_Count) as number) + 1
    p.dm_pi.set(STR_Permutation + STR_Count, count)
    p.dm_pi.set(STR_Permutation + hexStr(count) + DK1, _return_pi + i)
    p.dm_pi.set(hexStr(_parent_pi) + colorOrder + DK1, _return_pi + i) // new palette index
    p.dm_pi.set(`${hexStr(_return_pi + i)}_Parent${DK1}`, _parent_pi) // parent palette index
    p.dm_pi.set(hexStr(_return_pi + i) + STR_Color + STR_Order, colorOrder) // permut color order
  }
  if (p.pal_rm_new.length) update_scene_palette() // if a palette has been built for the scene yet
  return _return_pi
}

/** `get_pi(palette index base, *permutation)` — permutation slots of the `PI_PERMUTATIONS` scheme. */
export function get_pi(paletteIdx: number, permutation = 0): number {
  let pi = paletteIdx
  if (permutation % PI_PERMUTATIONS) {
    pi = PI_PERMUT_BASE + paletteIdx * PI_PERMUTATIONS
    pi += permutation % PI_PERMUTATIONS
  }
  return Math.min(pi, p.palette_image.width - 1)
}

/** `palSpr_changeColors()` — rebuild the palette image when `pal_rm_new` differs from `pal_rm_curr`. */
export function palSpr_changeColors(): void {
  if (p.pal_rm_def === undefined) return
  if (p.pal_rm_new === p.pal_rm_curr) return
  if (p.pal_rm_new === '') p.pal_rm_new = p.pal_rm_DEFAULT
  p.pal_rm_curr = p.pal_rm_new
  p.palette_image.setFromString(p.pal_rm_curr)
}

/** `pal_swap_set(palette_image, palette_index)` — subsequent draw commands carry `palette_index`. */
export function pal_swap_set(paletteIndex: number): void {
  if (!p.use_pal_swap || !gmBool(paletteIndex) || paletteIndex >= p.palette_image.width) return // GML: !(-1) is true
  p.palSwapIdx = paletteIndex
}

/** `pal_swap_reset()` */
export function pal_swap_reset(): void {
  if (!p.use_pal_swap) return
  p.palSwapIdx = -1
}
