/** `TonnA` — ZALiA `enemy/tonn`: large rectangular tank-y enemy with high hp (40x32). Walks until cs3, turns around. */
import { ABL_WALK, CS_BD1 } from '@z2/data'
import { byteNegate, gmBool } from '../../../../../../nes/math8'
import { g, p } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { registerObjectClass } from '../../../../../other/registry'
import { draw_sprite_ } from '../../../../../rooms/draw'
import { Enemy } from '../../../../classes'
import { updateX } from '../../../../go/movement'
import { registerObject, registerScripts } from '../../../../registry'
import { GameObjectB_init, GOB_update_2 } from '../../../GameObjectB'
import { Enemy_update_3 } from '../../shared'

export class TonnA extends Enemy {
  readonly objectName = 'TonnA' as const
  HSPD_1 = 0x08
}
registerObject('TonnA', TonnA)
registerObjectClass('TonnA', TonnA)

/** `TonnA_init1()` */
export function TonnA_init1(self: TonnA): void {
  GameObjectB_init(self)
  self.vspd_grav = 2
  self.abilities |= ABL_WALK
  self.HSPD_1 = 0x08
}

/** `TonnA_init2()` */
export function TonnA_init2(self: TonnA): void {
  self.hspd = (self.HSPD_1 * self.facing_dir) & 0xff
}

/** `TonnA_update()` */
export function TonnA_update(self: TonnA): void {
  if (self.abilities & ABL_WALK) {
    if (self.cs & 0x03) {
      self.facing_dir = -self.facing_dir
      self.hspd = byteNegate(self.hspd)
    }
    updateX(self)
  }
  Enemy_update_3(self) // update vertical
  GO_update_cs(self)
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
}

/** `TonnA_udp()` */
export function TonnA_udp(self: TonnA): void {
  self.can_draw_self = true
  if (gmBool(self.hspd) && g.counter1 & 0x10) self.draw_yoff = 1
  else self.draw_yoff = 0
}

/** `TonnA_draw` */
export function TonnA_draw(self: TonnA): void {
  if (!self.can_draw_self) return
  let _color = p.C_BLK1
  switch ((self.stun_timer >> 1) & 0x03) {
    case 0:
      _color = p.C_PNK1
      break
    case 1:
      _color = p.C_PNK2
      break
    case 2:
      _color = p.C_PNK3
      break
    case 3:
      _color = p.C_PNK4
      break
  }
  draw_sprite_(
    'spr_1x1_WHT',
    0,
    self.drawX - self.ww_,
    self.drawY - self.hh_,
    -1,
    self.ww,
    self.hh - 3,
    _color,
  )
  const _x = self.drawX + (self.ww_ - 6) * self.xScale
  const _y = self.drawY - 0x08
  const _spr = 'spr_Eye_Open_1b_WRB' // open half
  draw_sprite_(_spr, 0, _x, _y, self.palidx)
  draw_sprite_('spr_1x1_WHT', 0, _x - 1, _y - 1, -1, 2, 2, p.C_BLK1)
}

/** `TonnA_end()` — empty in ZALiA. */
export function TonnA_end(_self: TonnA): void {}

registerScripts({ TonnA_init1, TonnA_init2, TonnA_update, TonnA_udp, TonnA_draw, TonnA_end })
