/**
 * Balshot (ZALiA object `Balshot01`, parent `Enemy`; the wall-mounted bullet spitter). Its tiles become solid
 * while alive. `Balshot_init1/init2/update/udp.gml`.
 */
import {
  MAX_GOC1,
  STR_Attack,
  STR_Cooldown,
  STR_Delay,
  STR_Direction,
  STR_Height,
  STR_Index,
  STR_Level,
  STR_Object,
  STR_Palette,
  STR_Projectile,
  STR_Speed,
  STR_Version,
  STR_Width,
  TID_SOLID1,
  UIDX_NULL,
} from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { ocsHV2 } from '../../../../../collision/ocs'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { sign_ } from '../../../../../math/index'
import { tile_change_1a } from '../../../../../tile/tileOps'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import { goData } from '../../../../goData'
import type { ObjectName } from '../../../../objectNames'
import { registerObject, registerScripts } from '../../../../registry'
import { GameObjectB_init, gobCollision, update_EF11 } from '../../../GameObjectB'
import { spawnDataAfter, spawnDataHex } from '../ache/_shared'

export class Balshot01 extends Enemy {
  readonly objectName = 'Balshot01' as const
  readonly sub_state_ENABLED = 1
  readonly sub_state_DISABLED = 2
  sub_state = 1
  projectile_obj: ObjectName = 'Bullet1'
  projectile_pi = -1
  projectile_w = 8
  projectile_h = 8
  projectile_hspd = 0x20
  projectile_attack_level = 0x3
  Shoot_cooldown = 0x5f
  Shoot_timer = 1
}

/** `Balshot_init1()` */
export function Balshot_init1(self: Balshot01): void {
  GameObjectB_init(self)
  GO_set_sprite(self, 'spr_Balshot01a')
  GO_init_palidx(self, G.PI_BGR1)
  self.DRAW_YOFF = 0
  self.sub_state = self.sub_state_ENABLED
  self.projectile_OBJ = 'Bullet1'
  self.projectile_VER = 1
  self.projectile_obj = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.projectile_pi = -1
  self.projectile_w = goData.dm_go_prop.val(self.projectile_obj + STR_Width, 8) as number
  self.projectile_h = goData.dm_go_prop.val(self.projectile_obj + STR_Height, 8) as number
  self.projectile_hspd = 0x20
  self.projectile_attack_level = 0x3
  self.Shoot_cooldown = 0x5f
  self.Shoot_timer = 1
}

/** `Balshot_init2()` — spawn-data overrides, then make the tiles under the body solid. */
export function Balshot_init2(self: Balshot01): void {
  let _delay = 0
  const dk = self.dk_spawn
  if (dk !== undefined) {
    self.facing_dir = g.dm_spawn.val(dk + STR_Direction, self.facing_dir) as number
    self.facing_dir = sign_(self.facing_dir)
    self.projectile_hspd = g.dm_spawn.val(dk + STR_Speed, self.projectile_hspd) as number
    self.Shoot_cooldown = spawnDataHex(dk, STR_Cooldown, self.Shoot_cooldown, 0x11)
    _delay = spawnDataHex(dk, STR_Delay, _delay, 0x11)
    const objName = spawnDataAfter(dk, STR_Projectile + STR_Object, 0x11)
    // FIDELITY: ZALiA maps the name through `g.dm_go_prop[?name+STR_Object+STR_Idx]` to a GM object index;
    // objects are referenced by name here, so the name is used directly when it is a known object.
    if (objName !== undefined && goData.dm_go_prop.has(objName + STR_Object + STR_Index))
      self.projectile_obj = objName as ObjectName
    self.projectile_ver = spawnDataHex(dk, STR_Projectile + STR_Version, self.projectile_ver, 0x11)
    self.projectile_pi = spawnDataHex(dk, STR_Projectile + STR_Palette + STR_Index, self.projectile_pi, 0x11)
    self.projectile_attack_level = spawnDataHex(
      dk,
      STR_Projectile + STR_Attack + STR_Level,
      self.projectile_attack_level,
      0x11,
    )
  }
  self.Shoot_timer += _delay
  self.projectile_w = goData.dm_go_prop.val(self.projectile_obj + STR_Width, self.projectile_w) as number
  self.projectile_h = goData.dm_go_prop.val(self.projectile_obj + STR_Height, self.projectile_h) as number
  // Change tiles to solid
  for (let _i = 0; _i < self.ww >> 3; _i++) {
    for (let _j = 0; _j < self.hh >> 3; _j++) {
      tile_change_1a(0, self.xl + (_i << 3), self.yt + (_j << 3), -1, 0, TID_SOLID1)
    }
  }
}

/** `Balshot_update()` */
export function Balshot_update(self: Balshot01): void {
  if (gmBool(self.Shoot_timer)) self.Shoot_timer--
  else self.Shoot_timer = self.Shoot_cooldown
  if (!gmBool(self.Shoot_timer) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
    let _xl = self.x
    _xl += self.ww_ * self.facing_dir // Balshot XL or XR
    _xl += (self.projectile_w >> 1) * self.facing_dir // projectile XL
    _xl += 0x1 * self.facing_dir
    const _yt = self.y - (self.projectile_h >> 1) // projectile YT
    const proj = GOC1_create(
      _xl,
      _yt,
      self.facing_dir,
      self.projectile_obj,
      self.projectile_ver,
      self,
      self.projectile_pi,
    )
    proj.is_from_spawner = true
    proj.despawn_offscreen_hor = false
    proj.hspd = (self.projectile_hspd * proj.facing_dir) & 0xff
    proj.attack_level = self.projectile_attack_level
  }
  if (ocsHV2(self)) gobCollision.GOB_body_collide_pc_sword(self)
  if (self.hp <= 0) {
    // Remove solids
    for (let _i = 0; _i < self.ww >> 3; _i++) {
      for (let _j = 0; _j < self.hh >> 3; _j++) {
        tile_change_1a(0, self.xl + (_i << 3), self.yt + (_j << 3), -1, 0, 0)
      }
    }
  }
  update_EF11(self)
}

/** `Balshot_udp()` — eye open/closed */
export function Balshot_udp(self: Balshot01): void {
  self.can_draw_self = true
  if (gmBool(self.stun_timer)) {
    GO_set_sprite(self, self.stun_timer & 0x4 ? 'spr_Balshot01b' : 'spr_Balshot01a')
  } else {
    if (self.Shoot_timer < 2 || self.Shoot_timer >= (self.Shoot_cooldown >> 2) * 3)
      GO_set_sprite(self, 'spr_Balshot01b') // eye open
    else GO_set_sprite(self, 'spr_Balshot01a') // eye closed
  }
}

registerObject('Balshot01', Balshot01)
registerScripts({ Balshot_init1, Balshot_init2, Balshot_update, Balshot_udp })
