// Ported from ZALiA scripts/get_spell_cost.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively
import { SPL_FARY } from '@z2/data'
import { gmBool } from '../../nes/math8'
import { f, g } from '../../runtime/world'
import { bitNum } from '../math/index'
import { notPorted } from '../pending'

/** GML: get_spell_cost(spell bit) */
export function get_spell_cost(...argument: any[]) {
  // GML `var` is function-scoped; locals hoisted here:
  let _return: any
  _return = 0
  if (argument[0] === SPL_FARY && gmBool(g.CuccoSpell2_Acquired) && gmBool(g.CuccoSpell2_Option)) {
    if (gmBool(g.CuccoSpell2_Active)) {
      _return = 16 // 16: menu cost will show 08
    } else {
      _return = 32 // 32: menu cost will show 16
    }
  } else {
    _return = g.dg_spell_cost.get(bitNum(argument[0]), f.level_mag - 1)
  }
  return _return
}
