/**
 * `RoomData_Create()` fast path + `RoomData_Create_3()` — load ZALiA's shipped caches (`SceneData01.txt`,
 * `SceneWallData01.txt`) into the runtime maps. In this port the caches are already decoded to JSON by
 * `pnpm tool caches` (`@z2/data` `Caches`), so `ds_map_read`/`ds_grid_read` become plain copies.
 * The slow regeneration path (`_REINITIALIZING`, `rm_data_init_*`) is dev tooling and is not ported.
 */
import type { CacheGridJson, CacheMapJson, Caches } from '@z2/data'
import { DsGrid, type DsList, type DsMap } from '../../runtime/ds'
import { f, G, g, p } from '../../runtime/world'
import { Audio } from '../sound/Audio'

function readInto(target: DsMap<unknown>, src: CacheMapJson | undefined): void {
  if (!src) return
  for (const k in src) target.set(k, src[k])
}
function copyMap(dst: DsMap<unknown>, src: DsMap<unknown>): void {
  dst.clear()
  for (const [k, v] of src) dst.set(k, v)
}
function grid(src: CacheGridJson): DsGrid<number | string> {
  return DsGrid.from(src.cells as (number | string)[][])
}

/** `RoomData_Create()` — the cached branch: scene wall data, then `RoomData_Create_3()`. */
export function RoomData_Create(caches: Caches): void {
  readInto(G.dm_scene_wall_data as DsMap<unknown>, caches.map('scene_wall_data'))
  RoomData_Create_3(caches)
}

/** `RoomData_Create_3()` — get and set data for `g.dm_rm`, `g.dm_spawn`, `g.dm_dungeon`, ... */
export function RoomData_Create_3(caches: Caches): void {
  readInto(G.dm_scene_wh as DsMap<unknown>, caches.map('_Tile_File_Dimensions'))
  readInto(g.dm_rm as DsMap<unknown>, caches.map('scene_data'))
  readInto(g.dm_spawn as DsMap<unknown>, caches.map('spawn_data'))
  copyMap(g.dm_spawn_DEFAULT as DsMap<unknown>, g.dm_spawn as DsMap<unknown>)
  readInto(g.dm_dungeon as DsMap<unknown>, caches.map('dungeon_data'))
  readInto(g.dm_town as DsMap<unknown>, caches.map('town_data'))
  readInto(f.dm_PBags as DsMap<unknown>, caches.map('pbags_data'))
  copyMap(f.dm_PBags_DEFAULT as DsMap<unknown>, f.dm_PBags as DsMap<unknown>)
  readInto(f.dm_1up_doll as DsMap<unknown>, caches.map('1up_data'))
  copyMap(f.dm_1up_doll_DEFAULT as DsMap<unknown>, f.dm_1up_doll as DsMap<unknown>)
  readInto(f.dm_keys as DsMap<unknown>, caches.map('keys_data'))
  copyMap(f.dm_keys_DEFAULT as DsMap<unknown>, f.dm_keys as DsMap<unknown>)
  readInto(f.dm_jars as DsMap<unknown>, caches.map('jars_data'))
  copyMap(f.dm_jars_DEFAULT as DsMap<unknown>, f.dm_jars as DsMap<unknown>)
  readInto(G.dm_scene_rando as DsMap<unknown>, caches.map('scene_rando_data'))
  readInto(p.dm_scene_palette as DsMap<unknown>, caches.map('palette_data'))
  readInto(Audio.dm as DsMap<unknown>, caches.map('audio_data'))
  readInto(g.dm_RandoHints as DsMap<unknown>, caches.map('rando_hint_data'))
  readInto(g.dm_RandoEnemy as DsMap<unknown>, caches.map('rando_enemy_data'))
  // The eight dungeon maps go straight onto the pause menu, as `RoomData_Create_3.gml:202-266` does
  // (`ds_grid_read(g.PAUSE_MENU.dg_dngn_map_N, …)` + a copy into `_DEFAULT`). `obj_start_Create` creates
  // the menus before RoomData, so the instance is here. They were parked in a module-local table while the
  // gui port was outstanding and nothing ever adopted them: `PauseMenu_Create` builds its grids
  // zero-wide, so every palace map page was empty and `update_explored_data` had no cell to mark.
  const pm = g.PAUSE_MENU as unknown as Record<string, DsGrid<number | string>> | 0
  if (!pm) throw new Error('RoomData_Create_3: g.PAUSE_MENU does not exist yet')
  for (let n = 1; n <= 8; n++) {
    const src = caches.grid(`dg_dngn_map_${n}` as Parameters<Caches['grid']>[0])
    pm[`dg_dngn_map_${n}`] = grid(src)
    pm[`dg_dngn_map_${n}_DEFAULT`] = grid(src)
  }
  const ids = caches.list('dl_MapItem_ITEM_IDS') as (number | string)[]
  const list = g.dl_MapItem_ITEM_IDS as DsList<number | string>
  list.clear()
  list.add(...ids)
}
