/** `PC_udp()` — udp: Update Draw Properties (EC0A…). */
import { ITM_FRY1, STR_Current, STR_Datakey, STR_Idx, STR_Sprite, STR_undefined } from '@z2/data'
import { gmBool } from '../../../nes/math8'
import { f, G, g, p, world } from '../../../runtime/world'
import { get_fairy_yoff } from '../../graphics/index'
import { sprite_get_height, sprite_get_width } from '../../graphics/sprites'
import { hex_str, val } from '../../other/index'
import { PI_DRK1 } from '../../palette/pi'
import { rm_pal_qual_lit } from '../../palette/roomStart'
import { Boss } from '../classes'
import { dir_to_pc_ } from '../go/misc'
import { update_draw_xy } from '../go/movement'
import { GO_set_sprite } from '../go/sprite'
import { isHoldBehavior, PC_draw_get_cucco_rot, PC_udp_cucco } from './cucco'
import type { Lonk } from './Lonk'

export function PC_udp(self: Lonk): void {
  self.can_draw_self = true
  self.Draw_can_rando1 = gmBool(g._YwY_) || G.SloofLirpa_ENABLED
  self.Draw_can_rando2 = self.Draw_can_rando1 // random rotation, random behavior
  if (self.Draw_can_rando2) {
    self.Draw_behavior = self.dl_UwU_.get(self.behavior) ?? self.behavior
  } else {
    self.Draw_behavior = self.behavior
    if (self.Disguise_enabled && self.Disguise_dl_behaviors.findIndex(self.Draw_behavior) === -1)
      self.Draw_behavior = self.behavior_CROUCH
  }
  // EC0A
  self.draw_xoff = 0
  self.draw_yoff = self.ogr && self.Draw_behavior === self.behavior_CROUCH ? -4 : 0
  // EC19 --------------------------------------------------------------
  if (self.is_cucco) {
    PC_udp_cucco(self)
    self.Cucco_sprite_is_whole = self.Disguise_enabled || self.Draw_behavior === self.behavior_DAMAGE
    self.Cucco_legs_draw_first =
      self.Cucco_sprite_body === self.Cucco_SPRITE_BODY4 || self.Cucco_sprite_body === self.Cucco_SPRITE_BODY5
  } else if (self.is_fairy) {
    // EBB8. Fairy PC. EBD7
    self.fairy_sprite = (g.dl_Fairy_SPRITES.get(Math.sign(g.counter1 & 0x4)) as string) ?? 0 // spr_FairyA or spr_FairyB
  } else {
    // EC22, EC40
    GO_set_sprite(self, 'spr_Placement_16x32')
    self.palidx = self.palidx_def
    if (isHoldBehavior(self, self.Draw_behavior)) self.HoldItem_x_scale = self.HoldItem_X_SCALE // ED21, 9364
  }
  // -------------------------------------------------------------------------
  const seq = (x: number, y: number) => Number(p.dg_PI_SEQ.get(x, y) ?? 0)
  if (self.stun_timer)
    self.palidx = seq(self.is_cucco ? 1 : 0, (self.stun_timer >> 1) & 0x3) // changes color every 2 frames
  else if (self.is_cucco) self.palidx = seq(0, 0)
  else if (self.is_fairy) self.palidx = seq(0, 1)
  else self.palidx = seq(0, 0)
  const _c1 = !!self.stun_timer || !!p.SpellFlash_PC_timer
  const _c2 = rm_pal_qual_lit()
  if (!(_c1 || _c2)) self.palidx += PI_DRK1
  self.palidx_permut = 0
  self.Draw_palidx = self.palidx
  // ------------------------------------------------------------------------- EC4F, EDF6
  if (self.state === self.state_DROWN)
    self.depth = Math.max(self.depth, self.DrownLiquid_depth + 1) // drowning in water/lava
  else if (self.pipe_sink_timer)
    self.depth = Number(g.TILE_DEPTH_MAX_BACK) + 1 // Pipe sink
  else self.depth = self.depth_def
  // -------------------------------------------------------------------------
  update_draw_xy(self)
  const fairySpr = () => (g.dl_Fairy_SPRITES.get(Math.sign(g.counter1 & 0x4)) as string) ?? 0
  if (self.state === self.state_RESCUE) self.RescueFairy_sprite = fairySpr()
  else if (
    !(f.items & ITM_FRY1) ||
    (self.state === self.state_DROWN && !f.hp) ||
    (self.state !== self.state_DROWN && !self.iframes_timer)
  ) {
    self.RescueFairy_sprite = 0
  } else if (self.RescueFairy_sprite) self.RescueFairy_sprite = fairySpr()
  const _c3 = !self.is_cucco && (self.is_fairy || !!(self.control & self.control_DRAW1 && self.hspd))
  if (self.RescueFairy_sprite || _c3) {
    const _YOFF = get_fairy_yoff(g.counter1, 3 + (self.is_fairy ? 0 : 1))
    if (_c3) self.draw_yoff = _YOFF
    if (self.RescueFairy_sprite) {
      self.RescueFairy_draw_x = self.drawX
      self.RescueFairy_draw_y = self.drawY - self.hh_ - (sprite_get_height(self.RescueFairy_sprite) >> 1)
      self.RescueFairy_draw_y += _YOFF + self.y_change + self.draw_yoff
      self.RescueFairy_draw_y += 8
    }
  }
  // -------------------------  PC SHADOW DURING BOSS EXPLOSION  --------------------------
  self.Shadow_can_draw = false
  self.Shadow_xoff = 8
  for (const b of world.instancesOf(Boss)) {
    if (b.state === b.state_EXPLODE && b.timer < g.BOSS_DEATH_FLASH_CUE) {
      b.facing_dir = dir_to_pc_(b)
      // Blink the shadow to emulate the OG blinking effect that happens due to NES limitations.
      self.Shadow_can_draw = self.can_draw_self && !!(g.counter1 & 0x1)
      self.Shadow_xoff *= b.facing_dir
      break
    }
  }
  if (self.is_fairy) {
    self.Draw_surface_w = sprite_get_width(self.fairy_sprite as string)
    self.Draw_surface_h = sprite_get_height(self.fairy_sprite as string)
  } else if (self.is_cucco) {
    self.Draw_surface_w = sprite_get_width(self.Cucco_sprite_body as string)
    self.Draw_surface_h = sprite_get_height(self.Cucco_sprite_body as string)
  } else {
    self.Draw_surface_w = self.Spritesheet_W
    self.Draw_surface_h = self.Spritesheet_H
  }
  self.Draw_surface_size = Math.max(self.Draw_surface_w, self.Draw_surface_h)
  if (self.HoldItem_timer || isHoldBehavior(self, self.Draw_behavior))
    self.Draw_xscale1 = self.HoldItem_x_scale
  else self.Draw_xscale1 = self.xScale
  self.Draw_yscale1 = self.yScale
  if (self.Draw_can_rando1) {
    self.Draw_xscale2 = Number(self.dg_UwU_.get(self.Draw_behavior, 0) ?? 1)
    self.Draw_yscale2 = Number(self.dg_UwU_.get(self.Draw_behavior, 1) ?? 1)
  } else {
    self.Draw_xscale2 = 1
    self.Draw_yscale2 = 1
  }
  self.Draw_rotation1 = self.is_cucco ? PC_draw_get_cucco_rot(self, self.Draw_xscale1) : 0
  self.Draw_rotation2 = self.Draw_can_rando2 ? Number(self.dg_UwU_.get(self.Draw_behavior, 4) ?? 0) : 0
  self.Draw_surface_xl = self.drawX - (self.Draw_surface_size >> 1)
  self.Draw_surface_yt = self.drawY - (self.Draw_surface_size >> 1)
  // (The GML's surface-corner offset dance for flipped/rotated surfaces is not needed: PC_draw composes the
  //  parts about the centre with the combined transform instead of drawing via a corner-origin surface.)
  const _idx = Number(val(self.dm_skins.get(STR_Current + STR_Idx)))
  const _datakey = String(val(self.dm_skins.get(hex_str(_idx) + STR_Datakey), STR_undefined))
  self.Skin_image = String(val(self.dm_skins.get(_datakey + STR_Sprite), self.PCSkin_DEFAULT_SPRITE))
}
