/** Boss arena gate — ZALiA `gob2/arena_gate` (`ArenaGateA_*`). */
import { dk_EnemyDeath, PC_LOCK_ALL, STR_LockedDoor, STR_Open, TID_SOLID1 } from '@z2/data'
import { G, g } from '../../../../runtime/world'
import { find_row_solid, get_ground_y } from '../../../collision/solid'
import { sprite_get_height } from '../../../graphics/index'
import { pal_swap_reset, pal_swap_set } from '../../../palette/scenePalette'
import { Audio } from '../../../sound/Audio'
import { aud_play_combo1, aud_play_sound } from '../../../sound/play'
import { get_audio_theme_track } from '../../../sound/theme'
import { tile_change_1a } from '../../../tile/tileOps'
import { ViewCatchUp_init } from '../../../view/update_view_1'
import { GO_destroy_1a } from '../../go/lifecycle'
import { set_xy } from '../../go/movement'
import { GameObjectB_init, GameObjectB_step, update_EF11 } from '../GameObjectB'
import type { ArenaGateA } from './classes'
import { draw_sprite_at } from './deps'

/** `ArenaGateA_init1()` */
export function ArenaGateA_init1(self: ArenaGateA): void {
  GameObjectB_init(self)
  self.scr_step = ArenaGateA_step as never
  self.can_draw_self_exception = true
  self.ST_CTRL = self.state_DROP + 1
  self.HEAD_SPR = 'spr_arena_gate_head_1a_WRB'
  self.GATE_SPR = 'spr_arena_gate_piece_1a_WRB'
  self.GATE_SPR_H = sprite_get_height(self.GATE_SPR)
  self.sub_state = self.SUB_STATE_OPEN
  self.GROUND_Y = 0
  self.DOOR_ROWS = 0
  self.DOOR_Y = 0
  self.TIMING = 3
  self.boss = null
}

/** `ArenaGateA_init2()` */
export function ArenaGateA_init2(self: ArenaGateA): void {
  self.facing_dir = 1
  self.GROUND_Y = (((self.spawn_yt >> 8) + 1) << 8) - (0x3 << 3)
  self.GROUND_Y = get_ground_y(self.x, self.GROUND_Y, -1, self.GROUND_Y)
  self.spawn_yt = find_row_solid(
    TID_SOLID1,
    self.xl >> 3,
    (self.GROUND_Y >> 3) - 1,
    -1,
    0,
    self.spawn_yt >> 3,
  )
  self.spawn_yt = (self.spawn_yt << 3) + 8
  self.DOOR_ROWS = (self.GROUND_Y - self.spawn_yt) >> 3 // num of tiles to change solid value
  self.DOOR_Y = self.spawn_yt
  self.hh = self.GROUND_Y - self.spawn_yt // For death explosion positioning
  set_xy(self, self.x, self.spawn_yt + 8) // For death explosion positioning
}

/** `ArenaGateA_step()` */
export function ArenaGateA_step(self: ArenaGateA): void {
  GameObjectB_step(self)
  if (!self.state) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (self.state === self.state_EXPLODE && self.timer <= 1) self.state = self.ST_CTRL
  if (!self.state || self.state === self.ST_CTRL) {
    g.view_lock &= ~g.view_lock_boss
    g.view_lock |= g.view_lock_rm
    g.view_lock_boss = 0
    ViewCatchUp_init()
    switch (G.ViewCatchUp_VER) {
      default:
        g.pc_lock = 0
        break
      case 1:
      case 2:
        if (!G.ViewCatchUp_state) g.pc_lock = 0
        break
    }
    Audio.can_play_mus_rm_body = true
    self.state = 0
    if (g.mod_destroy_go_on_death && !self.state) GO_destroy_1a(self)
  }
}

/** `ArenaGateA_update()` */
export function ArenaGateA_update(self: ArenaGateA): void {
  update_EF11(self)
  switch (self.sub_state) {
    case self.SUB_STATE_OPEN:
      break
    case self.SUB_STATE_TRIG: {
      if (self.timer) break
      for (let _i = 0; _i < self.DOOR_ROWS; _i++) {
        // Change tiles to solid to block pc in.
        tile_change_1a(0, self.xl, self.DOOR_Y + (_i << 3), -1, 0, TID_SOLID1)
      }
      self.timer = ((self.DOOR_ROWS << 1) << self.TIMING) + 1
      self.sub_state = self.SUB_STATE_CLOS
      break
    }
    case self.SUB_STATE_CLOS: {
      // Closing
      if (self.timer) {
        if (!(self.timer & ((0x1 << self.TIMING) - 1))) {
          self.counter++
          aud_play_combo1(2) // 2: SND_BRDG_CRBL + SND_CRSR_MVE1
        }
        break
      }
      self.timer = 8 // Delay DONE
      self.sub_state = self.SUB_STATE_CLSD
      break
    }
    case self.SUB_STATE_CLSD:
      if (self.timer) break
      self.sub_state = self.SUB_STATE_DONE
      break
    case self.SUB_STATE_DONE: {
      if (self.timer) break
      if (!self.boss || !self.boss.exists || !self.boss.state) {
        self.timer = 0x20 // Delay explosion & unlock cam
        self.sub_state = self.SUB_STATE_DSTR
      }
      break
    }
    case self.SUB_STATE_DSTR: {
      if (self.timer) break
      for (let _i = 0; _i < self.DOOR_ROWS; _i++) {
        // Change tiles to non-solid.
        tile_change_1a(0, self.xl, self.DOOR_Y + (_i << 3), -1, 0, 0)
      }
      g.pc_lock = PC_LOCK_ALL
      aud_play_sound(get_audio_theme_track(STR_Open + STR_LockedDoor))
      aud_play_sound(get_audio_theme_track(dk_EnemyDeath))
      self.timer = self.explosion_DURATION1 // $25: 0.617s
      self.state = self.state_EXPLODE
      break
    }
  }
}

/** `ArenaGateA_udp()` */
export function ArenaGateA_udp(self: ArenaGateA): void {
  self.can_draw_self = true
  self.xScale = 1
}

/** `ArenaGateA_draw()` */
export function ArenaGateA_draw(self: ArenaGateA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!self.counter) return
  pal_swap_set(self.palidx)
  const _Y = self.DOOR_Y + (self.GATE_SPR_H >> 1)
  for (let _i = 0; _i < self.counter; _i++)
    draw_sprite_at(self.depth, self.GATE_SPR, 0, self.drawX, _Y + _i * self.GATE_SPR_H)
  pal_swap_reset()
}
