import {
  Audio,
  backgroundState,
  bgrToRgb,
  bootWorld,
  createWorld,
  installGameLoop,
  loadSpriteManifest,
  ogViewWindow,
  p,
  registerEntities,
  setAudioPlayback,
  setDisplaySize,
  setSoundManifest,
  setTilesetNames,
  surfaceClear,
  tileWorld,
  viewXL,
  viewYT,
  type World,
  windowState,
} from '@z2/core'
import { BASE_GAME_RESOLUTION_H, BASE_GAME_RESOLUTION_W } from '@z2/data'
import Phaser from 'phaser'
import type { LoadedAssets } from './assets/BootScene'
import { mapStem, spriteIndex } from './assets/manifest'
import { AudioPlayer } from './audio/audio'
import { InputSampler } from './input/sampler'
import { stepsFor } from './loop'
import { DrawListRenderer } from './render/drawList'
import { uploadPalette } from './render/paletteSwap'
import { RetroPostFx } from './render/postfx'
import { TileRenderer } from './render/tiles'
import { applySavedSkinPreference, installUserSkins } from './skins'
import { BrowserStorage } from './storage/browserStorage'

/**
 * Runs the core `World` at a fixed 60 Hz and renders it: tiles (`TileWorld` diff), the draw list, audio
 * commands, palette texture, and window state (fullscreen). Everything game-logic lives in `@z2/core`.
 */
export class GameScene extends Phaser.Scene {
  private world!: World
  private sampler!: InputSampler
  private drawList!: DrawListRenderer
  private tiles!: TileRenderer
  private audio!: AudioPlayer
  private postfx!: RetroPostFx
  private acc = 0
  private paletteVersion = -1
  private bgColour = -1
  private fullscreen = false
  /** True while presenting the NES 256×240 window at 4:3 instead of ZALiA's masked wide view. */
  private ogMode = false
  private cursorHidden = false
  private debugOverlay = false
  private fpsText!: Phaser.GameObjects.Text
  /** The world only steps once `bootCore()` has run (it waits for the user-skin store). */
  private booted = false

  constructor() {
    super('Game')
  }

  create(): void {
    const assets = this.registry.get('assets') as LoadedAssets
    const { sprites, tilesets, maps, sounds } = assets.manifests
    loadSpriteManifest(sprites, tilesets)
    setTilesetNames(tilesets.map((t) => t.name))
    setSoundManifest(sounds.map((s) => s.name))

    this.world = createWorld({ storage: new BrowserStorage() })
    this.world.caches = assets.caches
    for (const m of maps) {
      const stem = mapStem(m.file)
      const json = this.cache.json.get(`map:${stem}`)
      if (json) this.world.maps.set(stem, json)
    }

    this.sampler = new InputSampler(this)
    this.drawList = new DrawListRenderer(this, spriteIndex(sprites))
    this.tiles = new TileRenderer(this)
    this.audio = new AudioPlayer(this, sounds)
    // GM knew asset lengths (`audio_sound_length`); here the player answers them, through
    // `AudioPlayback.length()`. `wireCore()` binds every length seam (the flute jingle, the mini game's
    // two waits, the fanfare failsafes) to it, so this registration is all the adapter needs to do.
    setAudioPlayback(this.audio)
    this.cameras.main.setRoundPixels(true)
    this.postfx = new RetroPostFx(this.cameras.main)
    // GM `show_debug_overlay(bool)` — the F-key/preference-toggled FPS readout. Pinned to the viewport and
    // above everything the draw list emits.
    this.fpsText = this.add
      .text(2, 2, '', { fontFamily: 'monospace', fontSize: '10px', color: '#00ff00' })
      .setScrollFactor(0)
      .setDepth(1_000_000) // `phaserDepth` is `-gmDepth`, so a large positive value is in front of everything
      .setVisible(false)
    setDisplaySize(window.innerWidth, window.innerHeight)
    this.scale.on(Phaser.Scale.Events.RESIZE, () => setDisplaySize(window.innerWidth, window.innerHeight))
    window.addEventListener('resize', () => {
      if (this.ogMode) this.applyNesAspect()
    })

    // User skins must be registered before `bootWorld` — `PC_init` reads `customSkinProvider()` once
    // while it builds `dm_skins`. IndexedDB is async, so the world boots a few frames later; a storage
    // failure resolves the same way (no user skins) so the game always starts.
    //
    // The world must not start stepping until the player has interacted, either. Browsers refuse to start
    // audio without a gesture, and ZALiA's title screen is built on audio: `update_TitleScreen`'s `_RESET`
    // is gated on `audio_is_playing('snd_Default_Title_no_volume')`, so with the context still suspended
    // `title_y` decrements from -556 forever and the logo, the "THE ADVENTURE OF LINK" text and the story
    // scroll never arrive at all. Waiting also means the title theme is heard from its first note —
    // `mus_Title_Intro_1a` is a separate one-shot intro (the downward arpeggio) before the looping body,
    // and anything played into a suspended context is lost.
    Promise.all([installUserSkins(this), this.waitForStart()])
      .then(() => this.bootCore())
      .catch((err: unknown) => console.error('boot failed', err))
  }

  /** Resolves on the first pointer or key input, after showing a prompt and unlocking audio. */
  private waitForStart(): Promise<void> {
    const label = this.add
      .text(this.scale.width / 2, this.scale.height / 2, 'CLICK OR PRESS ANY KEY TO START', {
        fontFamily: 'monospace',
        fontSize: '14px',
        color: '#ffffff',
      })
      .setOrigin(0.5)
      .setScrollFactor(0)
      .setDepth(1_000_000)
    this.tweens.add({ targets: label, alpha: 0.25, duration: 700, yoyo: true, repeat: -1 })
    return new Promise<void>((resolve) => {
      const go = () => {
        this.input.off('pointerdown', go)
        this.input.keyboard?.off('keydown', go)
        this.tweens.killTweensOf(label)
        label.destroy()
        // Phaser unlocks on the gesture itself, but resume explicitly: a context still `suspended` when the
        // core starts the intro would swallow it.
        const ctx = (this.sound as { context?: AudioContext }).context
        if (ctx?.state === 'suspended') void ctx.resume()
        resolve()
      }
      this.input.once('pointerdown', go)
      this.input.keyboard?.once('keydown', go)
    })
  }

  /** `obj_start` boot, once the user-skin sheets are registered. */
  private bootCore(): void {
    // Every leaf object class + the entity-owned hooks (`item_acquired`, `Torch_ignite`, `BurnableMgr_*`,
    // `pc_sword_colliding_solid_body`). Must precede `bootWorld` or room entry throws on the first spawn.
    registerEntities()
    const splash = bootWorld(this.world)
    installGameLoop(this.world, { splash })
    // `load_game_pref` restored `_PC_Sprite_Set` into `dm_skins`; this swaps `Skin_image` to match
    // (ZALiA did it by re-reading UserPreferences.txt inside `PC_init`).
    applySavedSkinPreference()
    this.booted = true
  }

  /**
   * `windowState` → the page. GameMaker owned an OS window; here the page does, so only part of ZALiA's
   * window model has a meaning: fullscreen, the mouse cursor (`MouseCursor_HideVer`, hidden in fullscreen
   * by default) and APP SCALE. `windowState.x/y` are the desktop centring logic and have no equivalent —
   * see `adapterConsumers.test.ts`, which fails if a field here loses its reader.
   */
  private applyWindowState(): void {
    if (windowState.fullscreen !== this.fullscreen) {
      this.fullscreen = windowState.fullscreen
      if (this.fullscreen) this.scale.startFullscreen()
      else this.scale.stopFullscreen()
    }
    if (windowState.cursorHidden !== this.cursorHidden) {
      this.cursorHidden = windowState.cursorHidden
      this.game.canvas.style.cursor = this.cursorHidden ? 'none' : ''
    }
    if (windowState.debugOverlay !== this.debugOverlay) {
      this.debugOverlay = windowState.debugOverlay
      this.fpsText.setVisible(this.debugOverlay)
    }
    if (this.debugOverlay) this.fpsText.setText(`${Math.round(this.game.loop.actualFps)} fps`)
    // APP SCALE is deliberately NOT applied. `window_set_scale` sizes a desktop window to an exact multiple
    // of the 480×270 base; mapping that to the canvas meant leaving `Scale.FIT` for `Scale.NONE` + a pinned
    // zoom, and on an iPad that produced a canvas larger than the viewport — the game came back cropped to
    // a narrow strip. A page should just fill the space it has, which is what FIT already does, and
    // fullscreen still works. `windowState.width/.height` are in `adapterConsumers.test.ts`'s ALLOWED_UNREAD
    // with that reason. (2026-08-29, reverted after a playtest.)
  }

  /**
   * Size the canvas to the largest 4:3 box that fits, and centre it. A NES put 256×240 pixels on a 4:3
   * screen, so its pixels were not square; stretching the bitmap in CSS reproduces that exactly and costs
   * nothing. Phaser's own FIT mode would preserve 16:15 and letterbox, so this runs under `Scale.NONE`.
   */
  private applyNesAspect(): void {
    const c = this.game.canvas
    const availW = window.innerWidth
    const availH = window.innerHeight
    let w = availW
    let h = w * (3 / 4)
    if (h > availH) {
      h = availH
      w = h * (4 / 3)
    }
    c.style.width = `${Math.floor(w)}px`
    c.style.height = `${Math.floor(h)}px`
    c.style.marginLeft = `${Math.floor((availW - w) / 2)}px`
    c.style.marginTop = `${Math.floor((availH - h) / 2)}px`
  }

  override update(_time: number, delta: number): void {
    if (!this.booted) return
    this.acc += delta
    const { steps, rest } = stepsFor(this.acc)
    this.acc = rest
    for (let i = 0; i < steps; i++) {
      this.world.step(this.sampler.sample())
      this.audio.run(Audio.commands)
      this.world.events.length = 0 // events are a mirror of the audio/room commands; nothing else consumes them yet
    }
    if (steps === 0) return
    if (p.palette_image.version !== this.paletteVersion) {
      this.paletteVersion = p.palette_image.version
      uploadPalette(this, p.palette_image.palettes)
      this.drawList.palette.setPalettes(p.palette_image.palettes, this.paletteVersion)
    }
    // GM clears the room to `background_colour` every frame (`set_background_color` →
    // `background_showcolour`), and the splash room to `g.surf.draw_clear_color`. Both were written by the
    // core and read by nobody: every scene rendered on the hard-coded black of the game config, losing
    // `p.BackgroundColor_scene`, the colour-cycling Ganon arenas, Shadow Link's magenta room, the Game Over
    // red and the death flash. Colours arrive GM-packed ($BBGGRR).
    // GM scrolls the room view (`view_xview`) and every draw is in *room* coordinates — the core computes
    // the view rect (`viewXL`/`viewYT`, `rm_set_cam_1a` → `update_view_1`) and emits room coordinates for
    // sprites, tiles, the HUD and the menus alike. Nothing applied that rect here, so the canvas always
    // showed room 0,0..480,270: in a room wider than the view the player walked off the right of the
    // screen and kept going, invisible, until the scene's own edge handed over to the next one.
    // GameMaker rendered 480×270 and painted black side masks (`MaskWideView`) to letterbox the NES's
    // 256×240 view inside it — on a phone or tablet that leaves the game as a narrow strip in the middle of
    // the screen. When the core says the mask is on, present that window directly instead, at the 4:3 a NES
    // was displayed on (256×240 is 16:15 in square pixels; a real NES stretched it to 4:3). Gameplay turns
    // the mask off and keeps ZALiA's wide view.
    const og = ogViewWindow()
    // The side bars are the wide-view letterbox; presenting the OG window makes them a second, wrong crop.
    this.postfx.suppressWideMask = og !== null
    if (og) {
      if (!this.ogMode) {
        this.ogMode = true
        this.scale.scaleMode = Phaser.Scale.NONE
        // `setGameSize`, not `resize`: `resize` leaves the renderer's projection at the old size, so the
        // whole 480-wide view gets squashed into the narrower canvas — the picture stays complete but comes
        // out 136px wide and centred (136/256 = 256/480, which is how this was spotted).
        this.scale.setGameSize(og.w, og.h)
        this.renderer.resize(og.w, og.h)
        // The camera keeps the size it was built with, so without this the full 480-wide view is squashed
        // into a 256-wide canvas — the picture stays whole but comes out horizontally compressed.
        this.cameras.main.setSize(og.w, og.h)
        this.applyNesAspect()
      }
      this.cameras.main.setScroll(og.x, og.y)
    } else {
      if (this.ogMode) {
        this.ogMode = false
        this.scale.setGameSize(BASE_GAME_RESOLUTION_W, BASE_GAME_RESOLUTION_H)
        this.renderer.resize(BASE_GAME_RESOLUTION_W, BASE_GAME_RESOLUTION_H)
        this.cameras.main.setSize(BASE_GAME_RESOLUTION_W, BASE_GAME_RESOLUTION_H)
        this.scale.scaleMode = Phaser.Scale.FIT
        this.scale.refresh()
      }
      this.cameras.main.setScroll(viewXL(), viewYT())
    }
    const bg = backgroundState.show ? backgroundState.colour : surfaceClear.color
    if (bg !== this.bgColour) {
      this.bgColour = bg
      this.cameras.main.setBackgroundColor(bgrToRgb(bg))
    }
    this.tiles.sync(tileWorld(), this.drawList.palette, this.paletteVersion)
    this.drawList.render(this.world.draw.sorted())
    this.postfx.update()
    this.applyWindowState()
  }
}
