/**
 * Fokka (ZALiA object `FokkA`, parent `Enemy`; the bird knight, v1 red, v2 blue). `Fokka_init2/update/udp/draw/end.gml`.
 */
import { ABL_SHOT, ABL_WALK, CS_BD1, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { abs8b, gmBool } from '../../../../../../nes/math8'
import { DsGrid, DsList } from '../../../../../../runtime/ds'
import { g, input } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { cam_yb_max } from '../../../../../collision/env'
import {
  GOB_shield_collision_1a,
  GOB_sword_collision_1a,
  GOB_sword_collision_2a,
} from '../../../../../collision/gob'
import { GOB_update_shield_offsets, update_shield_hb } from '../../../../../collision/hitbox'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { draw_sprite_, GO_draw_sprite } from '../../../../go/draw'
import { dir_to_pc, GO_update_cam_vars } from '../../../../go/misc'
import { set_xy, updateX, updateY } from '../../../../go/movement'
import { GO_set_sprite } from '../../../../go/sprite'
import { solid_clip_correction } from '../../../../goa/movement'
import { pc, pcInput } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_despawn, GOB_update_1, GOB_update_2a, update_EF11 } from '../../../GameObjectB'
import { projOf, rand } from '../ache/_shared'

export class FokkA extends Enemy {
  readonly objectName = 'FokkA' as const
  readonly BVR_IDLE = 0 // idle
  readonly BVR_DRWH = 1 // draw high
  readonly BVR_ATKH = 2 // stab high
  readonly BVR_DRWL = 3 // draw low
  readonly BVR_ATKL = 4 // stab low
  readonly BVR_THRW = 5 // throw
  SPR_IDLE1 = 'spr_Fokka_Idle1'
  SPR_IDLE2 = 'spr_Fokka_Idle2'
  SPR_WALK1 = 'spr_Fokka_Walk1'
  SPR_WALK2 = 'spr_Fokka_Walk2'
  SPR_JUMP1 = 'spr_Fokka_Jump'
  HSPD_PACE = 8
  HSPD_CHASE = 0x10
  HSPD_JUMP = 0x18
  JUMP_VEL = 0xc8 // og $C8
  INIT_VEL = 0xc8
  VSPD_GRAV = 2
  DUR_PACE = 0
  DUR_ATK_DRAW = 0x18 // $0504,X
  DUR_ATK_STAB = 0x10 // $0504,X
  CUE_ATK_PHASE2 = 0x0c // $0D
  CUE_ATK_PHASE3 = 0x02 // $03
  attack_tokens = 0 // $0401[uIdx].  Num of remaining quick succession attacks
  dl_Arm_SPRITES = new DsList<string | 0>()
  Arm_sprite: string | 0 = 0
  dg_Arm_XOFF = new DsGrid<number>(4, 6, 0)
  Arm_xoff = 0
  ShieldHB_IDX_LOW = 1 // low
  ShieldHB_IDX_HGH = 2 // high
  SwordHB_XOFF = 8
  SwordHB_YOFF = 16
  SwordHB_W = 14
  SwordHB_H = 1
}

/** `Fokka_init2()` — v1(Red), v2(Blue) */
export function Fokka_init2(self: FokkA): void {
  self.behavior = self.BVR_IDLE
  self.HSPD_PACE = 8 // 4
  self.HSPD_CHASE = 0x10
  self.HSPD_JUMP = 0x18
  self.hspd = self.HSPD_PACE // $0071,X
  self.JUMP_VEL = 0xc8 // og $C8
  self.INIT_VEL = self.JUMP_VEL
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.timer = 1 // 1st frame after spawn is 0
  self.DUR_PACE = 0
  self.DUR_ATK_DRAW = 0x18
  self.DUR_ATK_STAB = 0x10
  self.CUE_ATK_PHASE2 = 0x0c
  self.CUE_ATK_PHASE3 = 0x02
  self.attack_tokens = 0
  self.projectile_OBJ = 'SwordBeam'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  // Arm -------------------------------
  self.dl_Arm_SPRITES = new DsList<string | 0>()
  self.dl_Arm_SPRITES.set(self.BVR_IDLE, 0)
  self.dl_Arm_SPRITES.set(self.BVR_DRWH, 'spr_Fokka_Draw_high')
  self.dl_Arm_SPRITES.set(self.BVR_ATKH, 'spr_Fokka_Stab_high')
  self.dl_Arm_SPRITES.set(self.BVR_DRWL, 'spr_Fokka_Draw_low')
  self.dl_Arm_SPRITES.set(self.BVR_ATKL, 'spr_Fokka_Stab_low')
  self.Arm_sprite = self.dl_Arm_SPRITES.get(self.BVR_IDLE) ?? 0
  const dg = new DsGrid<number>(4, 6, 0)
  self.dg_Arm_XOFF = dg
  // facing right: atk high (DRWH ×3, ATKH ×3), atk low; facing left likewise
  const rows: number[][] = [
    [-5, -10, -5, 9, 16, 8],
    [-4, -8, -4, 9, 16, 8],
    [5, 10, 5, -7, -15, -8],
    [4, 8, 4, -7, -15, -8],
  ]
  for (let x = 0; x < rows.length; x++)
    for (let y = 0; y < 6; y++) dg.set(x, y, (rows[x] as number[])[y] as number)
  self.Arm_xoff = dg.get(0, 0) as number
  // ---------------------------------------------------
  self.facing_dir = self.xScale
  self.abilities |= ABL_WALK
  self.abilities |= ABL_SHOT
  // shield hb
  self.ShieldHB_IDX_LOW = 1 // low
  self.ShieldHB_IDX_HGH = 2 // high
  self.ShieldHB_IDX = self.ShieldHB_IDX_LOW
  self.ShieldHB_idx = self.ShieldHB_IDX // 0444,X
  GOB_update_shield_offsets(self)
  update_shield_hb(self)
  // sword hb
  self.SwordHB_XOFF = 8 + g.HB_ADJ_X
  self.SwordHB_YOFF = 16 + g.HB_ADJ_Y
  self.SwordHB_xoff = self.SwordHB_XOFF * self.facing_dir
  self.SwordHB_yoff = self.SwordHB_YOFF
  self.SwordHB_W = 14 + g.HB_ADJ_W
  self.SwordHB_H = 1 + g.HB_ADJ_H
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
}

/** `Fokka_update()` — 9D2C */
export function Fokka_update(self: FokkA): void {
  const P = pc()
  const _RAND = rand(self)
  // 9D2C
  update_EF11(self)
  // 9D2F
  if (gmBool(self.behavior)) {
    // if attacking
    if (self.behavior === self.BVR_ATKH || self.behavior === self.BVR_ATKL) {
      // 9D37
      if (self.abilities & ABL_SHOT && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
        const _XL = self.xl
        const _YT = self.yt + 0xa * +(self.behavior === self.BVR_ATKL)
        GOC1_create(_XL, _YT, self.facing_dir, projOf(self), self.projectile_ver)
        self.behavior = 0
      }
      // GOB sword collision. 9D57: JSR E563: JSR E5F3
      if (!GOB_sword_collision_2a(self)) {
        // handles PC SHIELD collision check & reaction. E579: JSR E5F3
        GOB_sword_collision_1a(self) // handles PC BODY collision check & reaction
      }
    }
    // 9D5A
    if (!gmBool(self.timer)) {
      if (self.behavior === self.BVR_DRWH) self.behavior = self.BVR_ATKH
      else if (self.behavior === self.BVR_DRWL) self.behavior = self.BVR_ATKL
      else self.behavior = 0
      if (gmBool(self.behavior)) self.timer = self.DUR_ATK_STAB // $10
    }
  }
  // 9D77, E617. handles GOB shield collision
  if (GOB_shield_collision_1a(self)) return // PC sword collided enemy shield
  // 9D7A
  GO_update_cs(self)
  GO_update_cam_vars(self)
  // 9D83
  if (self.yt >= cam_yb_max() + 0x18) {
    GOB_despawn(self)
    return
  }
  // 9D8E, 9DA0: JSR E48B (GOB body collision)
  GOB_update_2a(self)
  if (self.pc_sword_collided_solid_body) return
  // 9DA9
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  updateY(self)
  if (self.cs & 0x8) self.vspd = 0x10
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  }
  // 9DC3 JSR: 9E42
  GOB_update_1(self, self.cs & 0x4) // update hspd_pushback
  GO_update_cs(self)
  if (!(self.cs & 0x3)) updateX(self)
  // 9DC6
  if (gmBool(P.ogr)) {
    if (P.yt + 5 >= self.yt)
      self.ShieldHB_idx = self.ShieldHB_IDX_LOW // 1
    else self.ShieldHB_idx = self.ShieldHB_IDX_HGH // 2
  } else if (gmBool(input.Attack_pressed)) {
    if (pcInput.dHeld)
      self.ShieldHB_idx = self.ShieldHB_IDX_LOW // 1
    else self.ShieldHB_idx = self.ShieldHB_IDX_HGH // 2
  }
  // 9DE6
  self.facing_dir = dir_to_pc(self)
  if (self.cs & 0x4 && !(_RAND & 0x1f)) {
    // 1 in 32 chance (3.125%). 9DF8. -------------  JUMP! ---------------
    set_xy(self, self.x, self.y - 1)
    self.hspd = (self.HSPD_JUMP * self.facing_dir) & 0xff // $18, $E8
    self.vspd = self.JUMP_VEL // JUMP_VEL=$C8
  } else {
    if (self.cs & 0x4) {
      // 9E06. -------------- SET hspd -----------------
      if (gmBool(P.hspd)) self.hspd = P.hspd
      else if (g.counter1 & 0x40) self.hspd = self.HSPD_PACE & 0xff
      else self.hspd = -self.HSPD_PACE & 0xff
      self.hspd = (self.hspd >> 1) | (self.hspd & 0x80)
    }
    // Check if can start an attack.
    if (!(self.cs & 0x4) || !gmBool(self.behavior)) {
      // 9E1E
      self.counter = (self.counter + 1) & 0xff
      let _VAL = 0x3f // every 64 frames. 1.067 sec
      if (self.ver === 2) _VAL = 0x1f // every 32 frames. 0.533 sec. Fokka blue
      if (!(self.counter & _VAL)) {
        // 9E29. ------------------ START ATTACK --------------------
        if (_RAND & 0x2)
          self.behavior = self.BVR_DRWL // 3. Low
        else self.behavior = self.BVR_DRWH // 1. High
        self.timer = self.DUR_ATK_DRAW // $18 frames. 0.400 sec
      }
    }
  }
}

/** `Fokka_udp()` */
export function Fokka_udp(self: FokkA): void {
  self.can_draw_self = true
  const high = self.ShieldHB_idx === self.ShieldHB_IDX_HGH
  if (self.cs & 0x4) {
    // ON GROUND
    if (gmBool(self.hspd) && g.counter1 & (0x4 << +(abs8b(self.hspd) < self.HSPD_CHASE))) {
      // 4, 8
      GO_set_sprite(self, high ? self.SPR_WALK2 : self.SPR_WALK1)
    } else GO_set_sprite(self, high ? self.SPR_IDLE2 : self.SPR_IDLE1)
  } else {
    // OFF GROUND
    if (self.vspd & 0x80) GO_set_sprite(self, self.SPR_JUMP1)
    else GO_set_sprite(self, high ? self.SPR_IDLE2 : self.SPR_IDLE1)
  }
  self.Arm_sprite = self.dl_Arm_SPRITES.get(self.behavior) ?? 0 // dl_Arm_SPRITES[|0] = 0;
  if (gmBool(self.behavior)) {
    let _idx1 = 0
    if (self.behavior > self.BVR_ATKH) _idx1 = 1
    if (self.facing_dir === -1) _idx1 += 2
    let _idx2 = 0
    if (!(self.behavior & 0x1)) _idx2 += 3
    if (self.timer <= self.CUE_ATK_PHASE2) _idx2++
    if (self.timer <= self.CUE_ATK_PHASE3) _idx2++
    self.Arm_xoff = self.dg_Arm_XOFF.get(_idx1, _idx2) as number
  }
}

/** `Fokka_draw()` */
export function Fokka_draw(self: FokkA): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  if (self.Arm_sprite)
    draw_sprite_(self.Arm_sprite, 0, self.drawX + self.Arm_xoff, self.drawY, -1, self.xScale, 1, self.depth)
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

/** `Fokka_end()` — freed `dl_Arm_SPRITES`/`dg_Arm_XOFF` in ZALiA; nothing to do here. */
export function Fokka_end(_self: FokkA): void {}

registerObject('FokkA', FokkA)
registerScripts({ Fokka_init2, Fokka_update, Fokka_udp, Fokka_draw, Fokka_end })
