import { CS_BD1 } from '@z2/data'
/** `Wheep` — ZALiA `enemy/wheep`: hovering skull that only bobs and hurts on contact. */
import { g } from '../../../../../../runtime/world'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { get_hover_y_adj } from '../../../../../graphics/index'
import { sign_ } from '../../../../../math/index'
import { registerObjectClass } from '../../../../../other/registry'
import { Enemy } from '../../../../classes'
import { set_xy } from '../../../../go/movement'
import { registerObject, registerScripts } from '../../../../registry'
import { GameObjectB_init, GOB_update_2 } from '../../../GameObjectB'

export class Wheep extends Enemy {
  readonly objectName = 'Wheep' as const
}
registerObject('Wheep', Wheep)
registerObjectClass('Wheep', Wheep)

/** `Wheep_init1()` */
export function Wheep_init1(self: Wheep): void {
  GameObjectB_init(self)
  self.DRAW_YOFF = 0
}

/** `Wheep_init2()` — empty in ZALiA. */
export function Wheep_init2(_self: Wheep): void {}

/** `Wheep_update()` */
export function Wheep_update(self: Wheep): void {
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  GOB_update_2(self)
  set_xy(self, self.x, self.y + get_hover_y_adj(g.counter1, 3))
}

/** `Wheep_udp()` */
export function Wheep_udp(self: Wheep): void {
  self.can_draw_self = true
  self.facing_dir = sign_(g.counter1 & (0x01 << 3))
}

registerScripts({ Wheep_init1, Wheep_init2, Wheep_update, Wheep_udp })
