/**
 * The transient `Rando` GameMaker object (`Rando_Create.gml`, `Rando_Destroy.gml`).
 *
 * ZALiA creates one instance inside `FileSelect_register_file` (`with(instance_create(0,0,Rando)) { … }`),
 * runs the whole generation on it and destroys it again. The port keeps the same shape: one `Rando` value
 * that every `Rando_*` script takes as its explicit `self` (ARCHITECTURE.md "instance script" rule).
 *
 * Every field below is a GML instance variable, declared where the GML first assigns it — the folder's
 * scripts assign instance variables freely, so they are all declared here with their ZALiA names.
 * `Rando_Destroy` only freed ds_* handles; the port relies on GC, so it has no equivalent.
 */

import { DsGrid, DsList, DsMap } from '../../runtime/ds'
import type { GmJsonValue } from '../file/json'

/** ZALiA's `LOCATION` map values: rm names, descriptions, item ids (strings) and location nums (reals). */
export type LocValue = GmJsonValue

export class Rando {
  readonly objectName = 'Rando'

  // ---- Rando_Create ---------------------------------------------------------------------------
  dm_LOCATIONS = new DsMap<LocValue>()

  // ---- Rando_randomize_file: arguments + decoded settings -------------------------------------
  FILE_NUM = 0
  Rando_SEED = 0
  QUEST_NUM = 1

  DEBUG = true
  debug_str = ''
  debug_data_count = 0
  dm_debug_data = new DsMap<string>()

  /** Written to `SaveFile_N_Rando_Data.txt` → `f.dm_rando` on load. */
  dm_save_data = new DsMap<GmJsonValue>()
  /** Written to `SaveFile_N_RandoDungeonTilesetData.txt` → `f.dm_rando_dungeon_tileset`. */
  dm_save_data_dungeon_tileset = new DsMap<GmJsonValue>()

  ItemLocations_LIMIT_OBSCURE = 0
  ItemLocations_DARKROOM_DIFFICULTY = 0
  ItemLocations_NPC_GIVE_HINTS = 0
  ItemLocations_ZELDA_HINT = 0
  ItemLocations_WILL_RANDOMIZE = 0
  ItemLocations_INCLUDE_PBAG = 0
  KeyLocations_WILL_RANDOMIZE = 0
  SkillLocations_WILL_RANDOMIZE = 0
  SpellLocations_WILL_RANDOMIZE = 0
  SpellCosts_WILL_RANDOMIZE = 0
  Enemy_DIFFICULTY = 1
  EnemyChars_WILL_RANDOMIZE = 0
  EnemySpawners_WILL_RANDOMIZE = 0
  EnemyENIGMA_WILL_RANDOMIZE = 0
  EnemyHP_WILL_RANDOMIZE = 0
  EnemyDamage_WILL_RANDOMIZE = 0
  DungeonRooms_WILL_RANDOMIZE = 0
  DungeonLocations_WILL_RANDOMIZE = 0
  DungeonBoss_WILL_RANDOMIZE = 0
  TownLocations_WILL_RANDOMIZE = 0
  LevelCosts_WILL_RANDOMIZE = 0
  XP_WILL_RANDOMIZE = 0
  Scenes_WILL_RANDOMIZE = 0
  OverworldBiomes_WILL_RANDOMIZE = 0
  Palette_WILL_RANDOMIZE = 0
  DungeonTileset_WILL_RANDOMIZE = 0
  Attack_LEVEL = 1
  Magic_LEVEL = 1
  Life_LEVEL = 1
  ContainersHP_START_COUNT = 0
  ContainersMP_START_COUNT = 0

  // ---- Rando_generate: working lists ----------------------------------------------------------
  dl_list1 = new DsList<GmJsonValue>()
  dl_list2 = new DsList<GmJsonValue>()
  dl_list3 = new DsList<GmJsonValue>()
  dl_list4 = new DsList<GmJsonValue>()
  dg_1 = new DsGrid<number>(0, 0, 0)

  dm_quest_puzzles = new DsMap<GmJsonValue>()

  dl_location_NUMS = new DsList<number>()
  dl_qual_locations = new DsList<number>()
  dl_qual_locations_new = new DsList<number>()
  dl_qual_locations_dungeon = new DsList<number>()
  dl_locations_taken = new DsList<number>()
  dl_locations1 = new DsList<number>()
  dl_locations_remaining = new DsList<number>()

  dl_item_locations_remaining = new DsList<number>()
  dl_item_location_NUMS = new DsList<number>()
  dl_ITEMS = new DsList<string>()
  dl_items_placed = new DsList<string>()
  dl_prog_guar_items = new DsList<string>()

  dm_pbag = new DsMap<GmJsonValue>()
  dl_PBAGS = new DsList<string>()
  dl_pbag_location_NUMS = new DsList<number>()

  dm_KEYS = new DsMap<GmJsonValue>()
  dl_KEYS = new DsList<string>()
  dl_keys_placed = new DsList<string>()
  dl_key_location_NUMS = new DsList<number>()

  dm_spells = new DsMap<GmJsonValue>()
  dl_SPELLS = new DsList<string>()
  dl_spell_location_NUMS = new DsList<number>()
  dl_skills_placed = new DsList<string>()
  dl_spells_placed = new DsList<string>()
  dl_START_SPELLS = new DsList<string>()
  dl_spell_sequence_spells = new DsList<string>()

  dl_TOWN_NAMES = new DsList<string>()
  dl_SKILLS = new DsList<string>()

  /** In item rando this is the last location that gets an item, to guarantee the player can reach it. */
  SafeLocation_LOC_NUM = -1
  dl_SAFE_LOCATION_NUMS = new DsList<number>()

  FallingKey_item_placed = false
  FallingKey_LOC_NUM = -1
  FallingKey_LOC_ID: string | undefined = undefined
  FallingKey_RM_NAME: string | undefined = undefined
  FallingKey_ITEM_ID: string | undefined = undefined

  Location_COUNT = 0
  ItemLocation_COUNT = 0
  PBagLocation_COUNT = 0
  SpellLocation_COUNT = 0
  KeyLocation_COUNT = 0

  /** Can't let the player make it to ShadowBoss w/out BOTTLE. */
  INCLUDE_BOTTLE_LOCATION = false

  // Location category ids (`Rando_generate.gml:445-462`) — set before `Rando_init_location_data()`.
  LocCatID_West01 = '' // West North
  LocCatID_West02 = '' // West South
  LocCatID_Nabo01 = '' // Nabooru Area
  LocCatID_Daru01 = '' // Darunia Area
  LocCatID_Kasu01 = '' // Kasuto Area
  LocCatID_DMtn01 = '' // Death Mtn
  LocCatID_Maze01 = '' // Maze Island
  LocCatID_NIsl01 = '' // North Islands
  LocCatID_VOD01 = '' // Valley of Death (VOD)
  LocCatID_Sari01 = '' // Saria River & Lake
  LocCatID_RMtn01 = '' // Ruto Mtns
  LocCatID_SCon01 = '' // South Continent
  LocCatID_DragMr = '' // Dragmire area
  LocCatID_Dngn01 = '' // Dungeons
  LocCatID_Town01 = '' // Towns

  /** Placement order of the locations that unlocked progression — hint assignment walks this. */
  dl_locnum_that_gave_prog = new DsList<number>()

  // ---- Rando_prepare_hints (RandoHints_VER 2) -------------------------------------------------
  dl_hint_loc_nums_shuffled = new DsList<number>()
  dl_hint_items = new DsList<string>()

  // ---- Rando_randomize_items ------------------------------------------------------------------
  placement_num = 0
  CONTAINER_METHOD = 3
  CONTROL_ALLKEY = 2
  ALLKEY_LOC_NUM = 0
  FLUTE_LOC_NUM = 0
  /**
   * Set to 0 before each `Rando_is_qual_location` and set inside it when a spell was required.
   * ZALiA never reads it back (see FIDELITY_NOTES); kept so the scripts read like the GML.
   */
  required_spell = 0
  DEBUG_extra_line1 = false

  dm_spell_quest = new DsMap<GmJsonValue>()
  dl_prog_spells = new DsList<string>()
  dl_prog1 = new DsList<string>()
  dl_prog2 = new DsList<string>()
  dl_remaining_keys = new DsList<string>()
  dl_ItemPool_A = new DsList<string>()
  dl_ItemPool_B = new DsList<string>()
  dl_ItemPool_C = new DsList<string>()

  dl_qualified_locations = new DsList<number>()
  dl_qualified_locations_old = new DsList<number>()
  dl_qualified_locations_new = new DsList<number>()
  dl_loc_cats = new DsList<string>()
  dl_loc_num_options = new DsList<number>()
  dl_placed_containers_hp = new DsList<string>()
  dl_placed_containers_mp = new DsList<string>()

  // ---- port-only ------------------------------------------------------------------------------
  /**
   * FIDELITY: `Rando_is_qual_location` is self-recursive (`:34` and ~30 other sites) with no guard in
   * ZALiA. The port keeps a recursion depth counter and returns `false` past the limit rather than
   * overflowing the stack. See FIDELITY_NOTES.
   */
  qualDepth = 0
  /** Location ids currently on the `Rando_is_qual_location` stack (cycle guard). */
  readonly qualStack = new Set<string>()
}
