/** GameMaker instance model: a numbered object with position, existence, and a class hierarchy. */
export const NOONE = null
/** A reference that may be `noone`. Structural: anything with an `exists` flag qualifies (bodies, instances). */
export type Ref<T = Instance> = T | typeof NOONE

let nextId = 100000

export abstract class Instance {
  readonly id: number = nextId++
  /** `instance_exists(id)` — false after `destroy()`. */
  exists = true
  x = 0
  y = 0

  /** GML `object_get_name(object_index)`. Subclasses set this to their ZALiA object name. */
  abstract readonly objectName: string

  /**
   * GM's per-object `persistent` flag (`objects/<name>.object.gmx` `<persistent>-1</persistent>`). A room
   * change destroys every instance that does not carry it — see `rooms/roomChange.ts`. ZALiA marks 23
   * objects persistent; the ones that exist as `Instance`s in this port set this to `true`.
   */
  readonly persistent: boolean = false

  /** Hook for `scr_inst_end` / `scr_destroy`; runs exactly once. */
  protected onDestroy(): void {}

  destroy(): void {
    if (!this.exists) return
    this.exists = false
    this.onDestroy()
  }
}

/** `instance_exists(x)` with GM's noone/undefined tolerance. */
export function instanceExists<T extends { exists: boolean }>(i: Ref<T> | undefined): i is T {
  return i !== null && i !== undefined && i.exists
}

/** Reset id counter (tests only). */
export function _resetInstanceIds(): void {
  nextId = 100000
}
