const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v))
const saveDataKey = (fileNum: number) => STR_Save + STR_File + hexStr(fileNum) + STR_Encoded
const fileName = (fileNum: number) => f.dl_file_names.get(fileNum - 1) as string
const prefix = (fileNum: number) => f.dl_FILE_NAME_PREFIX.get(fileNum - 1) as string
export const randoDataFileName = (fileNum: number) => `${prefix(fileNum)}${STR_Rando}${STR_Data}.txt`
export const randoSpoilerFileName = (fileNum: number) => `${prefix(fileNum)}${STR_Rando}_Spoiler.txt`
export const dungeonTilesetFileName = (fileNum: number) =>
  `${prefix(fileNum)}${dk_RandoDungeonTilesetData}.txt`

/** GM `date_current_datetime()` — days since 1899-12-30 (fractional). Only stored, never read back. */
export function date_current_datetime(now = Date.now()): number {
  return now / 86400000 + 25569
}

/** `get_file_seed_dk(save file num, quest num)` */
export function get_file_seed_dk(fileNum: number, questNum: number): string {
  return STR_Rando + STR_Seed + STR_File + hexStr(fileNum) + STR_Quest + hexStr(questNum)
}

/** Encoded text of a slot: cached in `dm_save_file_data`, else read from storage. */
function encodedSlot(fileNum: number): string | undefined {
  const cached = f.dm_save_file_data.get(saveDataKey(fileNum))
  if (cached !== undefined) return cached
  const name = fileName(fileNum)
  if (!world.storage.exists(name)) return undefined
  return world.storage.readText(name)
}

/** `get_saved_value(file number, data key, value if undefined)` */
export function get_saved_value<T extends GmJsonValue>(
  fileNum: number,
  datakey: string,
  dflt: T,
): GmJsonValue {
  const FILE_NUM = clamp(fileNum, 1, SAVE_FILE_MAX)
  const data = encodedSlot(FILE_NUM)
  if (data === undefined) return dflt
  const m = json_decode(data)
  if (m === -1) return dflt
  return m.val(String(datakey), dflt)
}

/** `set_saved_value(file num, datakey, new value, *delete)` */
export function set_saved_value(
  fileNum: number,
  datakey: string,
  newValue: GmJsonValue | boolean,
  willDelete = false,
): void {
  const FILE_NUM = clamp(fileNum, 1, SAVE_FILE_MAX)
  const name = fileName(FILE_NUM)
  if (!world.storage.exists(name)) return
  const m = json_decode(encodedSlot(FILE_NUM))
  if (m === -1) return
  if (willDelete) m.delete(String(datakey))
  else m.set(String(datakey), typeof newValue === 'boolean' ? gmNum(newValue) : newValue)
  const encoded = json_encode(m)
  world.storage.writeText(name, encoded)
  f.dm_save_file_data.set(saveDataKey(FILE_NUM), encoded)
}

/** `init_save_data1()` — quest/challenge flags that exist from the start of a file. */
export function init_save_data1(): void {
  const g = gd()
  f.dm_quests.set(STR_Quest + STR_Started, 0) // Set at 1st rm's g_Room_Start()
  f.dm_quests.set(STR_Quest + STR_Puzzles + STR_Set, 0)
  f.dm_quests.set(STR_Boulder + STR_Circle + STR_Complete, 0)
  f.dm_quests.set(STR_ErrorFriend, 0) // boolean: If spoken to Error's friend (Mido)
  f.dm_quests.set(dk_MidoChurch + STR_Open, 0)
  f.dm_quests.set(STR_Scroblin + STR_Open + STR_Path, 0)
  f.dm_quests.set(Zelda_DATAKEY1, 0)
  f.dm_quests.set(STR_Talo + STR_State, 0)
  f.dm_quests.set(STR_Malo + STR_State, 0)
  // 'obj_name(Challenge_Obj)+"01"' is Challenge_Obj.challenge_id
  f.dm_challenges.set(`Challenge_BlockConfiguration01${STR_Complete}`, 0)
  f.dm_challenges.set(`Challenge_SwitchA01${STR_Complete}`, 0)
  f.dm_challenges.set(`Challenge_SwitchB01${STR_Complete}`, 0)
  const tri = g.dm_rm.get(`TriforceBarrier1${dk_SceneName}`)
  if (tri !== undefined) f.dm_quests.set(String(tri) + STR_Barrier + STR_State, 0) // Barrier reset
  const cry = g.dm_rm.get(`CrystalBarrier1${dk_SceneName}`)
  if (cry !== undefined) f.dm_quests.set(String(cry) + STR_Barrier + STR_State, 0) // Barrier reset
  for (let i = Number(g.dm_spawn.val(STR_Merchant + STR_Count)); i >= 1; i--) {
    const dk = STR_Merchant + hexStr(i)
    f.dm_quests.set(`${dk}01${STR_Paid}`, 0)
    f.dm_quests.set(`${dk}02${STR_Paid}`, 0)
    f.dm_quests.set(`${dk}03${STR_Paid}`, 0)
  }
}

/** `set_save_props_def()` — reset everything that gets saved to defaults before registering a new file. */
export function set_save_props_def(): void {
  const g = gd()
  Gd().QuestTimer_time = 0
  f.quest_num = 1
  f.death_count = 0 // og sets to 0 on quest 2
  f.lives = g.STARTING_LIVES
  f.level_atk = 1
  f.level_mag = 1
  f.level_lif = 1
  f.xp = 0
  f.xpNext = 0
  f.xpPending = 0
  f.xpDrain = 0
  f.spells = 0
  g.CuccoSpell2_Acquired = 0
  f.skills = 0
  f.Cucco_skills = 0
  f.crystals = 0 // 0 PLACED
  f.cont_pieces_hp = f.CONT_PIECES_HP_DEF
  f.cont_pieces_mp = f.CONT_PIECES_MP_DEF
  f.hp = get_stat_max(STR_Heart)
  f.mp = get_stat_max(STR_Magic)
  f.items = 0
  f.kakusu_count = 0
  f.dm_kakusu.clear()
  f.key_count = 0
  ds_map_copy(f.dm_keys, f.dm_keys_DEFAULT)
  f.dm_openedLocks.clear()
  ds_map_copy(f.dm_jars, f.dm_jars_DEFAULT)
  ds_map_copy(f.dm_PBags, f.dm_PBags_DEFAULT)
  set_life_doll_data_to_default()
  ds_map_copy(f.dm_1up_doll, f.dm_1up_doll_DEFAULT)
  f.dm_explored.clear()
  f.reen_new_run = f.REEN_NEW_FILE
  f.reen = f.reen_new_run
  f.cont_run_town_num = 0
  g.dm_RandoHintsRecorder.clear()
  f.game_completed_count = 0
  f.dm_challenges.clear()
  f.dm_quests.clear()
  init_save_data1()
}

/** `init_save_files()` — first time running app: create the slot files. */
export function init_save_files(): void {
  const empty = new DsMap<GmJsonValue>()
  empty.set(f.SDNAME_save_name, SAVE_NAME_NULL)
  const saveData = json_encode(empty)
  for (let i = 0; i < SAVE_FILE_MAX; i++) {
    const fileNum = i + 1
    const name = fileName(fileNum)
    if (!world.storage.exists(name)) {
      world.storage.writeText(name, saveData)
      set_save_props_def()
      file_save(fileNum, true)
    }
  }
}

/** `init_new_save_file(file num, *quest num)` */
export function init_new_save_file(fileNum: number, questNum?: number): void {
  const FILE_NUM = clamp(fileNum, 1, SAVE_FILE_MAX)
  set_save_props_def()
  if (questNum !== undefined) f.quest_num = questNum
  // Set at 1st rm's g_Room_Start()
  f.dm_quests.set(STR_Quest + STR_Started, 0) // 0: New quest initialized but not started.
  file_save(FILE_NUM, false)
  set_saved_value(FILE_NUM, STR_Quest + hexStr(f.quest_num) + STR_Duration, 0)
}

/** Build the SaveFile_N.txt contents for the current player state (the write part of `file_save`). */
function buildSaveMap(base: DsMap<GmJsonValue>, saveName: string, isCreated: boolean): DsMap<GmJsonValue> {
  const g = gd()
  const m = new DsMap<GmJsonValue>()
  ds_map_copy(m, base)
  m.set('_DateTimeOfSave', date_current_datetime())
  m.set(STR_Quest + hexStr(f.quest_num) + STR_Duration, Gd().QuestTimer_time)
  m.set(f.SDNAME_saveCreated, gmNum(isCreated))
  m.set(f.SDNAME_save_name, saveName)
  m.set(f.SDNAME_questNum, f.quest_num)
  m.set(STR_Game + STR_Complete + STR_Count, f.game_completed_count)
  m.set(f.SDNAME_deathCount, f.death_count)
  m.set(f.SDNAME_level_atk, f.level_atk)
  m.set(f.SDNAME_level_mag, f.level_mag)
  m.set(f.SDNAME_level_lif, f.level_lif)
  m.set(f.SDNAME_cont_pieces_hp, f.cont_pieces_hp)
  m.set(f.SDNAME_cont_pieces_mp, f.cont_pieces_mp)
  m.set(f.SDNAME_spells, f.spells)
  m.set(f.SDNAME_items, f.items)
  m.set(f.SDNAME_skills, f.skills)
  m.set(STR_Skill + STR_Cucco, f.Cucco_skills)
  m.set(`${STR_Cucco}${STR_Spell}02${STR_Acquired}`, gmNum(g.CuccoSpell2_Acquired))
  m.set(f.SDNAME_crystals, f.crystals)
  m.set(f.SDNAME_kakusu, json_encode(f.dm_kakusu))
  m.set(f.SDNAME_takenKeys, json_encode(f.dm_keys))
  m.set(f.SDNAME_openedLocks, json_encode(f.dm_openedLocks))
  m.set(STR_PBAG, json_encode(f.dm_PBags))
  m.set(f.SDNAME_linkDolls, json_encode(f.dm_1up_doll))
  m.set(f.SDNAME_quests, json_encode(f.dm_quests))
  m.set(f.SDNAME_exploredRooms, json_encode(f.dm_explored))
  return m
}

/**
 * `file_save(file num, will eliminate)` — writes (or, with `willEliminate`, clears) a slot.
 * FIDELITY: all file texts are prepared first and written in one pass; any storage error aborts the whole
 * slot write and is reported by the return value instead of leaving the slot's files out of sync.
 * @returns true when every file was written.
 */
export function file_save(fileNum: number, willEliminate: boolean): boolean {
  const g = gd()
  const FILE_NUM = fileNum
  const FILE_NAME = fileName(FILE_NUM)
  const SAVE_IS_CREATED_STATE = !willEliminate
  let SAVE_NAME = String(f.dl_save_names.get(FILE_NUM - 1) ?? SAVE_NAME_NULL)
  if (willEliminate) SAVE_NAME = SAVE_NAME_NULL // SAVE_NAME_NULL: Indicates save slot is avail for creation.

  const writes: [string, string][] = []
  const store = world.storage
  let base = new DsMap<GmJsonValue>()
  let fileExists = store.exists(FILE_NAME)

  if (willEliminate || !fileExists) {
    base.set(f.SDNAME_save_name, SAVE_NAME_NULL)
    writes.push([FILE_NAME, json_encode(base)])
    writes.push([dungeonTilesetFileName(FILE_NUM), ''])
    g.dm_RandoHintsRecorder.clear()
    writes.push([randoDataFileName(FILE_NUM), ''])
    writes.push([randoSpoilerFileName(FILE_NUM), ''])
    fileExists = true
  }
  if (!willEliminate) {
    const existing = json_decode(store.readText(FILE_NAME))
    if (existing !== -1) base = existing
  }
  const saveMap = buildSaveMap(base, SAVE_NAME, SAVE_IS_CREATED_STATE)
  let SAVE_DATA: string | undefined
  if (fileExists) {
    SAVE_DATA = json_encode(saveMap)
    // replace the eliminate-write of the same file, if any (last write wins, as in the GML)
    const idx = writes.findIndex(([n]) => n === FILE_NAME)
    if (idx >= 0) writes[idx] = [FILE_NAME, SAVE_DATA]
    else writes.push([FILE_NAME, SAVE_DATA])
  }

  if (!willEliminate && f.dm_save_file_settings.val(STR_Randomize + STR_Item + STR_Locations)) {
    if (g.dm_RandoHintsRecorder.size) {
      const RANDO_DATA_FILE_NAME = randoDataFileName(FILE_NUM)
      if (store.exists(RANDO_DATA_FILE_NAME)) {
        const full = json_decode(store.readText(RANDO_DATA_FILE_NAME))
        if (full !== -1) {
          ds_map_copy(f.dm_rando_full, full)
          f.dm_rando_full.set(STR_Found + STR_Hint, json_encode(g.dm_RandoHintsRecorder))
          writes.push([RANDO_DATA_FILE_NAME, json_encode(f.dm_rando_full)])
        }
      }
    }
    const RANDO_SPOILER_FILE_NAME = randoSpoilerFileName(FILE_NUM)
    if (store.exists(RANDO_SPOILER_FILE_NAME)) {
      writes.push([
        RANDO_SPOILER_FILE_NAME,
        markAcquiredInSpoiler(store.readText(RANDO_SPOILER_FILE_NAME) ?? ''),
      ])
    }
  }

  try {
    for (const [name, text] of writes) store.writeText(name, text)
  } catch {
    return false
  }
  if (SAVE_DATA !== undefined) {
    f.dm_save_file_data.set(saveDataKey(FILE_NUM), SAVE_DATA)
    ds_map_copy(f.dm_save_file, saveMap)
  }
  return true
}

/** Spoiler-log rewrite from `file_save`: prefix `*ACQUIRED* ` on item lines whose item the player now owns. */
export function markAcquiredInSpoiler(text: string): string {
  const POS_KEY1 = '#('
  const POS_KEY2 = ')#'
  const STR_ACQUIRED = '*ACQUIRED*'
  // GM file_text_readln keeps the newline; split keeps the same line structure.
  const lines = text.split(/(?<=\n)/)
  return lines
    .map((line) => {
      // Item Data Line Example: "$04. loc_num $2C: #(_CANDLE)#   .  _TownA_5F - Bagu Item location (NOTE)"
      if (line.includes('loc_num') && !line.includes(STR_ACQUIRED)) {
        const p1 = line.indexOf(POS_KEY1)
        const p2 = line.indexOf(POS_KEY2)
        if (p1 >= 0 && p2 > p1) {
          const itemId = line.slice(p1 + POS_KEY1.length, p2)
          if (hooks.item_acquired(itemId)) return `${STR_ACQUIRED} ${line}`
        }
      }
      return line
    })
    .join('')
}

export interface FileLoadResult {
  ok: boolean
  /** Keys that were missing from the save and took `val()` defaults (diagnostics; empty for a healthy file). */
  defaulted: string[]
}

/** `file_load(file num)` — load a slot into `f`/`g` and apply the file's rando settings. */
export function file_load(fileNum: number): FileLoadResult {
  const g = gd()
  const G = Gd()
  const defaulted: string[] = []
  const FILE_NUM = clamp(fileNum, 1, SAVE_FILE_MAX)
  const FILE_NAME = fileName(FILE_NUM)
  const store = world.storage
  if (!store.exists(FILE_NAME)) return { ok: false, defaulted }
  const dm = json_decode(store.readText(FILE_NAME))
  if (dm === -1) return { ok: false, defaulted }
  const val = <T extends GmJsonValue>(key: string, dflt: T | 0 = 0): GmJsonValue => {
    const v = dm.get(key)
    if (v === undefined) {
      defaulted.push(key)
      return dflt
    }
    return v
  }
  const num = (key: string, dflt = 0) => Number(val(key, dflt))

  g.dm_room_history.clear()
  f.quest_num = clamp(num(f.SDNAME_questNum), 1, 2)
  G.QuestTimer_time = num(STR_Quest + hexStr(f.quest_num) + STR_Duration)
  G.QuestTimer_state = 1
  f.game_completed_count = num(STR_Game + STR_Complete + STR_Count)
  f.death_count = num(f.SDNAME_deathCount)
  f.level_atk = clamp(num(f.SDNAME_level_atk), 1, STAT_LEVEL_MAX)
  f.level_mag = clamp(num(f.SDNAME_level_mag), 1, STAT_LEVEL_MAX)
  f.level_lif = clamp(num(f.SDNAME_level_lif), 1, STAT_LEVEL_MAX)
  f.cont_pieces_hp = String(val(f.SDNAME_cont_pieces_hp, f.CONT_PIECES_HP_DEF))
  f.cont_pieces_mp = String(val(f.SDNAME_cont_pieces_mp, f.CONT_PIECES_MP_DEF))
  f.spells = num(f.SDNAME_spells)
  f.items = num(f.SDNAME_items)
  f.skills = num(f.SDNAME_skills)
  f.Cucco_skills = num(STR_Skill + STR_Cucco)
  g.CuccoSpell2_Acquired = num(`${STR_Cucco}${STR_Spell}02${STR_Acquired}`)
  f.crystals = num(f.SDNAME_crystals)
  if (g.mod_ContinueFrom & g.mod_ContinueFrom_TWN2) f.cont_run_town_num = num(STR_Save + STR_Town + STR_Num)
  f.xp = num(STR_XP)
  // FIDELITY: GML `ds_map_clear(map); map = json_decode(...)` orphaned the original maps; fill them in place.
  fillFromJson(f.dm_1up_doll, dm.get(f.SDNAME_linkDolls))
  fillFromJson(f.dm_kakusu, dm.get(f.SDNAME_kakusu))
  fillFromJson(f.dm_keys, dm.get(f.SDNAME_takenKeys))
  fillFromJson(f.dm_openedLocks, dm.get(f.SDNAME_openedLocks))
  fillFromJson(f.dm_PBags, dm.get(STR_PBAG))
  fillFromJson(f.dm_explored, dm.get(f.SDNAME_exploredRooms))
  fillFromJson(f.dm_quests, dm.get(f.SDNAME_quests))
  ds_map_copy(f.dm_save_file, dm)
  f.dm_save_file_settings.clear()
  const settingsEncoded = f.dm_save_file.get(STR_Save + STR_File + STR_Settings)
  if (settingsEncoded !== undefined) {
    const s = json_decode(settingsEncoded)
    if (s !== -1) ds_map_copy(f.dm_save_file_settings, s)
  }
  // ===================================================================
  // RANDO -----------------------------------------------------------
  const QUEST_KEY = STR_Quest + hexStr(f.quest_num)
  f.dm_rando_full.clear()
  f.dm_rando.clear()
  f.dm_rando_dungeon_tileset.clear()
  const DUNGEON_TILESET_FILE_NAME = dungeonTilesetFileName(FILE_NUM)
  if (store.exists(DUNGEON_TILESET_FILE_NAME)) {
    const m = json_decode(store.readText(DUNGEON_TILESET_FILE_NAME))
    if (m !== -1) ds_map_copy(f.dm_rando_dungeon_tileset, m)
  }
  const tiles01 = f.dm_rando_dungeon_tileset.get(`${STR_Randomized}_Tiles01`)
  if (tiles01 !== undefined) hooks.read_randomized_tiles01(String(tiles01))
  const RANDO_DATA_FILE_NAME = randoDataFileName(FILE_NUM)
  if (store.exists(RANDO_DATA_FILE_NAME)) {
    const full = json_decode(store.readText(RANDO_DATA_FILE_NAME))
    if (full !== -1) {
      ds_map_copy(f.dm_rando_full, full)
      const randoEncoded = f.dm_rando_full.get(QUEST_KEY + STR_Rando + STR_Data)
      if (randoEncoded !== undefined) {
        const r = json_decode(randoEncoded)
        if (r !== -1) ds_map_copy(f.dm_rando, r)
      }
    }
  }
  // Hints ---------------------------------------------------------
  g.dm_RandoHintsRecorder.clear()
  const hintsEncoded = f.dm_rando_full.get(STR_Found + STR_Hint)
  if (hintsEncoded !== undefined) {
    const h = json_decode(hintsEncoded)
    if (h !== -1) ds_map_copy(g.dm_RandoHintsRecorder, h)
  }
  // Overworld Biomes ----------------------------------------------
  const tsrc = f.dm_rando.get(STR_Overworld + STR_TSRC + STR_Randomized)
  if (tsrc !== undefined) fillFromJson(G.OVERWORLD.dm_Rando_TSRC, tsrc)
  const settings = f.dm_save_file_settings
  // Enemy HP ----------------------------------------------
  let datakey = STR_Enemy + STR_HP
  if (settings.val(STR_Randomize + datakey)) {
    for (let i = g.dl_HP.size - 1; i >= 0; i--) g.dl_HP.set(i, Number(f.dm_rando.val(datakey + hexStr(i))))
  }
  // Enemy Damage -------------------------------------------
  datakey = STR_Enemy + STR_Damage
  if (settings.val(STR_Randomize + datakey)) {
    const dg = g.dg_enemy_damage
    for (let i = dg.width - 1; i >= 0; i--) {
      // LIFE Level
      for (let j = dg.height - 1; j >= 0; j--) {
        // Enemy Damage Level
        dg.set(i, j, Number(f.dm_rando.val(datakey + hexStr(i) + hexStr(j), dg.get(i, j) ?? 0)))
      }
    }
  }
  // Level Costs ----------------------------------------------
  datakey = STR_Level + STR_Cost
  if (settings.val(STR_Randomize + datakey)) {
    const dg = f.dg_xp_next
    for (let i = 0; i < dg.width; i++)
      for (let j = 0; j < dg.height; j++)
        dg.set(i, j, Number(f.dm_rando.val(datakey + hexStr(i) + hexStr(j), dg.get(i, j) ?? 0)))
  }
  // XP ----------------------------------------------
  datakey = STR_XP
  if (settings.val(STR_Randomize + datakey)) {
    for (let i = g.dl_XP.size - 1; i >= 0; i--) g.dl_XP.set(i, Number(f.dm_rando.val(datakey + hexStr(i))))
  }
  // Spell Costs -------------------------------------------------
  datakey = STR_Spell + STR_Cost
  if (settings.val(STR_Randomize + datakey)) {
    const dg = g.dg_spell_cost
    for (let i = 0; i < dg.width; i++) {
      const spell = Math.sign(i) << Math.max(i - 1, 0) // spell bit
      for (let j = 0; j < dg.height; j++) {
        let v = Number(f.dm_rando.val(datakey + hexStr(i) + hexStr(j)))
        if (v) {
          const v1 = Number(g.dm_Spell.val(hexStr(spell) + STR_Rando + STR_Cost + STR_Max, v))
          v = Math.min(v, v1)
          dg.set(i, j, v)
        }
      }
    }
  }
  // Spell Locations ------------------------------------------------
  if (settings.val(STR_Randomize + STR_Spell + STR_Locations)) {
    let i = 0
    for (;;) {
      const townName = g.dm_town.get(STR_Town + STR_Name + hexStr(++i))
      if (townName === undefined) break
      const spawnDatakey = g.dm_spawn.get(`_Wise_Man${STR_Spawn}${STR_Datakey}${townName}`)
      if (spawnDatakey !== undefined) {
        const spellName = String(f.dm_rando.val(String(townName) + STR_Spell, 'undefined'))
        const bit = Number(g.dm_Spell.val(STR_Bit + spellName))
        if (bit) g.dm_spawn.set(STR_Spell + STR_Bit + String(spawnDatakey), bit)
      }
    }
  }
  // Items ----------------------------------------------------
  if (settings.val(STR_Randomize + STR_Item + STR_Locations)) {
    const COUNT = Number(f.dm_rando.val(STR_Total + STR_Location + STR_Count))
    for (let i = 1; i <= COUNT; i++) {
      // change spawn data to match what was randomized on file creation
      const dk1 = STR_Location + hexStr(i)
      const spawnDatakey = f.dm_rando.get(dk1 + STR_Spawn + STR_Datakey)
      const itemId = f.dm_rando.get(dk1 + STR_Item + STR_ID + STR_Randomized)
      if (spawnDatakey !== undefined && itemId !== undefined) {
        g.dm_spawn.set(String(spawnDatakey) + STR_Item + STR_ID + STR_Randomized, itemId)
        g.dm_spawn.set(String(itemId) + STR_Spawn + STR_Datakey + STR_Randomized, spawnDatakey)
      }
    }
  }
  if (
    settings.val(STR_Randomize + STR_Spell + STR_Locations) ||
    settings.val(STR_Randomize + STR_Item + STR_Locations) ||
    settings.val(STR_Randomize + STR_Spell + STR_Cost)
  ) {
    const dg = g.dg_spell_cost
    for (let i = 0; i < dg.width; i++) {
      // each spell
      const spell = Math.sign(i) << Math.max(i - 1, 0)
      for (let j = 0; j < dg.height; j++) {
        // each magic level
        const v = dg.get(i, j) ?? 0
        const v1 = Number(g.dm_Spell.val(hexStr(spell) + STR_Rando + STR_Cost + STR_Max, v))
        dg.set(i, j, Math.min(v, v1))
      }
    }
  }
  // Spell sequence dialogue (Kings Tomb, Carock 2, Kasuto Cemetery Kakusu) restored from the save
  const dk2 = STR_Spell + STR_Sequence
  const dk1 = dk2 + STR_Dialogue + STR_Datakey
  const count = Number(f.dm_quests.val(dk2 + STR_Dialogue + STR_Count))
  for (let i = 0; i < count; i++) {
    const dkDialogue = g.DIALOGUE_WINDOW.dm_dialogue.get(dk1 + hexStr(i + 1))
    if (dkDialogue !== undefined) {
      const dk3 = dk2 + hexStr(i + 1)
      const v1 = f.dm_quests.get(dk3 + STR_Dialogue + STR_Hylian)
      const v2 = f.dm_quests.get(dk3 + STR_Dialogue)
      const v3 = f.dm_quests.get(dk3)
      if (v1 !== undefined && v2 !== undefined && v3 !== undefined) {
        g.DIALOGUE_WINDOW.dm_dialogue.set(`${dkDialogue}A`, v1)
        g.DIALOGUE_WINDOW.dm_dialogue.set(`${dkDialogue}B`, v2)
        g.DIALOGUE_WINDOW.dm_dialogue.set(String(dkDialogue) + dk2, v3)
      }
    }
  }
  f.file_num = FILE_NUM
  return { ok: true, defaulted }
}
