/** `pc_is_cucco()`, `pc_is_fairy()`, `PC_set_behavior()` — tiny helpers used all over the game. */
import { SPL_FARY } from '@z2/data'
import { gmBool } from '../../../nes/math8'
import { g } from '../../../runtime/world'
import { pc } from './pc'

export function pc_is_cucco(): boolean {
  return gmBool(g.mod_PC_CUCCO_1) && !!(g.spells_active & SPL_FARY)
}

export function pc_is_fairy(): boolean {
  return !pc_is_cucco() && !!(g.spells_active & SPL_FARY)
}

/** `PC_set_behavior(behavior)` — clamps to the behavior range; strings are ignored (GML guard). */
export function PC_set_behavior(behavior: number | string): void {
  if (typeof behavior === 'string') return
  const self = pc()
  self.behavior = Math.min(Math.max(behavior, 0), self.behavior_LAST)
}
