/**
 * Room predicates & lookups — ZALiA IDE folder `room` (14 scripts). Data comes from the string-keyed
 * `g.dm_rm` / `f.dm_rando` maps exactly as in the GML. Dropped: `area_is_town` (dead, but kept as a helper).
 */
import {
  Area_OvrwA,
  Area_PalcA,
  Area_TownA,
  dk_FileName,
  STR_Data,
  STR_Datakey,
  STR_Dungeon,
  STR_Enc_Type,
  STR_Entrance,
  STR_Height,
  STR_Last,
  STR_Num,
  STR_Quest,
  STR_Rm,
  STR_reen,
  STR_Town,
  STR_View,
  STR_Width,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { gmBool } from '../../nes/math8'
import type { TiledMap } from '../../runtime/tiled'
import { f, G, g, world } from '../../runtime/world'
import { Exit_construct } from '../exit/Exit'
import { sdm } from '../other/index'

const clampQuest = (q: number) => Math.min(Math.max(q, 1), 2)
const letters = (s: string) => s.replace(/[^A-Za-z]/g, '')

/** `room_is_type(room types)` — true if `g.room_type` letter is in the given string (e.g. "AC"). */
export function room_is_type(types: string): boolean {
  return types.includes(String(g.room_type))
}

/** `get_scene_tile_file_name(scene name, quest num)` — `PalcA_003`; rando may override. */
export function get_scene_tile_file_name(sceneName: string, questNum: number): string | undefined {
  const _DATAKEY = sceneName + dk_FileName + STR_Quest + hexStr(questNum)
  const fromRando = f.dm_rando.get(_DATAKEY)
  return (fromRando ?? g.dm_rm.get(_DATAKEY)) as string | undefined
}

/**
 * `rm_get_file_data(rm name, *quest num)` — the scene's Tiled map. ZALiA reads
 * `rm_tile_data/<Area>/<file>.json` from disk and returns the JSON text; here the adapter preloads maps into
 * `world.maps` by file stem and this returns the parsed map (callers must not `json_decode` it again).
 */
export function rm_get_file_data(rmName: string, questNum = 1): TiledMap | undefined {
  const _file_name = get_scene_tile_file_name(rmName, clampQuest(questNum))
  if (_file_name === undefined) {
    sdm(
      `!!!! WARNING. rm_get_file_data(). _file_name is undefined because get_scene_tile_file_name('${rmName}', ${questNum}) returned undefined !!!!`,
    )
    return undefined
  }
  const map = world.maps.get(_file_name)
  if (!map) {
    sdm(
      `!!!! WARNING. rm_get_file_data(). File 'rm_tile_data/${_file_name.slice(0, 5)}/${_file_name}.json' does not exist !!!!`,
    )
    return undefined
  }
  return map
}

/** `rm_get_wh(rm name, width 0 OR height 1, *quest num)` — scene pixel size from `global.dm_scene_wh`. */
export function rm_get_wh(rmName: string, whichHeight: number | boolean, questNum = 1): number {
  const _DATAKEY = rmName + dk_FileName + STR_Quest + hexStr(clampQuest(questNum))
  let _file_name = g.dm_rm.get(_DATAKEY) as string | undefined
  if (_file_name === undefined) return 0
  _file_name = (f.dm_rando.get(_DATAKEY) as string | undefined) ?? _file_name
  if (!gmBool(whichHeight)) return Number(G.dm_scene_wh.val(_file_name + STR_Width))
  return Number(G.dm_scene_wh.val(_file_name + STR_Height))
}

/** `rm_is_bottom_page_locked(rm name)` — default $1 (set in set_rm_data()) unless specified. */
export function rm_is_bottom_page_locked(rmName: string): number {
  let _LOCK = Number(g.dm_rm.val(rmName + STR_View + STR_Data))
  _LOCK = Math.min(Math.max(_LOCK, 0x0), 0x3)
  return Math.sign(_LOCK & 0x1)
}

/** `get_dk_dungeon_entrance(dungeon num)` */
export const get_dk_dungeon_entrance = (dungeonNum: number | string): string =>
  STR_Dungeon + STR_Entrance + hexStr(dungeonNum)

/** `get_dungeon_num(rm name)` */
export const get_dungeon_num = (rmName: string): number => Number(g.dm_rm.val(rmName + STR_Dungeon + STR_Num))

/** `get_town_num(rm name)` */
export const get_town_num = (rmName: string): number => Number(g.dm_rm.val(rmName + STR_Town + STR_Num))

/** `rm_get_encounter_types(rm name)` */
export const rm_get_encounter_types = (rmName: string): number => Number(g.dm_rm.val(rmName + STR_Enc_Type))

/** `area_is_dungeon(area)` — string contains "Palc" (position, 0 = no). */
export function area_is_dungeon(area: string): number {
  let _STR = letters(Area_PalcA)
  _STR = _STR.slice(0, -1) // truncate the "A" at the end
  return area.indexOf(_STR) + 1
}
/** `area_is_ow(str area name)` — contains "Ovrw". */
export function area_is_ow(area: string): number {
  let _STR = letters(Area_OvrwA)
  _STR = _STR.slice(0, -1)
  return area.indexOf(_STR) + 1
}
/** `area_is_town(area)` — contains "Town". */
export function area_is_town(area: string): boolean {
  let _STR = letters(Area_TownA)
  _STR = _STR.slice(0, -1)
  return area.includes(_STR)
}

/** Overworld fields `is_safe_encounter_rm` reads (`global.OVERWORLD`). */
interface OverworldEnc {
  pcrc: number
  dg_tsrc: { get(x: number, y: number): number | string | undefined }
  Biome_dm: Map<string, number | string>
  dm_enc: Map<string, number | string>
}

/** `is_safe_encounter_rm()` — true when the biome under the PC does not spawn encounter objects. */
export function is_safe_encounter_rm(): boolean {
  const ow = G.OVERWORLD as OverworldEnc | undefined
  if (!ow) return false
  const _TSRC = ow.dg_tsrc.get((ow.pcrc >> 0) & 0xff, (ow.pcrc >> 8) & 0xff)
  const _BIOME = ow.Biome_dm.get(`${STR_TSRC}${hexStr(_TSRC ?? 0)}${STR_Biome}`)
  if (
    _BIOME !== undefined &&
    ow.Biome_dm.get(`${_BIOME}${STR_Biome}${STR_Num}`) !== undefined &&
    !gmBool((ow.dm_enc.get(`${_BIOME}_Can${STR_Spawn}${dk_EncounterInstance}`) as number | undefined) ?? 0)
  ) {
    return true
  }
  return false
}

import { dk_EncounterInstance, STR_Biome, STR_Spawn, STR_TSRC } from '@z2/data'

/** `is_exiting_rm()` — setting g.exit_leave to an Exit instance triggers a rm change (unless pipe-sinking). */
export function is_exiting_rm(): boolean {
  const pc = G.pc as { pipe_sink_timer?: number } | null
  return g.room_type === 'A' && gmBool(g.exit_leave) && !gmBool(pc?.pipe_sink_timer ?? 0)
}

/** `rm_restart()` — reload/re-enter rm. */
export function rm_restart(): void {
  sdm(' rm_restart()')
  if (gmBool(g.exit_enter)) {
    g.exit_leave = g.exit_enter
  } else {
    const _DATAKEY = g.dm_room_history.get(STR_Last + STR_Rm + STR_Datakey) as string | undefined
    if (_DATAKEY !== undefined) {
      //   REEN: Room Entry Exit Name
      const _REEN = g.dm_room_history.get(_DATAKEY + STR_reen) as string | undefined
      if (_REEN !== undefined) g.exit_leave = Exit_construct(_REEN)
    }
  }
}

/** `is_exiting_ow()` — on the overworld and an exit tile has been reached (`global.OVERWORLD.exit_owrc`). */
export function is_exiting_ow(): boolean {
  const ow = (G as unknown as { OVERWORLD?: { exit_owrc?: number } }).OVERWORLD
  return g.room_type === 'C' && gmBool(ow?.exit_owrc ?? 0)
}
