/**
 * Seams for scripts outside the rooms/screens port: audio (`sound` folder), gui cursor timers (`gui`),
 * randomizer (`rando`), player character (`goa`), tiles (`tile`). Defaults are the smallest faithful
 * behaviour that keeps the screens runnable; the owning ports replace them.
 */
import type { DsMap } from '../../runtime/ds'
import { NOONE } from '../../runtime/instance'
import type { TiledMap } from '../../runtime/tiled'
import { G, world } from '../../runtime/world'
import { notPorted } from '../pending'

// ---- sound ---------------------------------------------------------------------------------------
/** `get_audio_theme_track(theme dk)` — the Audio port resolves themes; until then the theme key is the sound id. */
export let get_audio_theme_track: (theme: string) => string = (theme) => theme
/** `aud_play_sound(sound)` → adapter event. */
export let aud_play_sound: (sound: string | number) => void = (sound) => {
  if (sound) world.emit({ kind: 'sound', sound: String(sound) })
}
/** `aud_play_combo1(theme)` */
export let aud_play_combo1: (theme: string) => void = (theme) => aud_play_sound(get_audio_theme_track(theme))
/** `audio_is_playing(x)` — GM takes a sound asset or a live instance id. */
export let audio_is_playing: (sound: string | number | undefined) => boolean = () => false
/** The `Audio` singleton fields the screens read (title-scroll sync); the sound port owns the real object. */
// biome-ignore lint/suspicious/noExplicitAny: seam
export let Audio: any = { timing_sound_position_curr: 0, timing_sound_position_prev: 0 }
// biome-ignore lint/suspicious/noExplicitAny: seam
export function setAudioObject(a: any): void {
  Audio = a
}
export function setAudioDeps(
  d: Partial<{
    get_audio_theme_track: typeof get_audio_theme_track
    aud_play_sound: typeof aud_play_sound
    aud_play_combo1: typeof aud_play_combo1
    audio_is_playing: typeof audio_is_playing
  }>,
): void {
  if (d.get_audio_theme_track) get_audio_theme_track = d.get_audio_theme_track
  if (d.aud_play_sound) aud_play_sound = d.aud_play_sound
  if (d.aud_play_combo1) aud_play_combo1 = d.aud_play_combo1
  if (d.audio_is_playing) audio_is_playing = d.audio_is_playing
}

// ---- gui -----------------------------------------------------------------------------------------
/** `gui_tmr_cursor_v()` / `_h()` — d-pad cursor auto-repeat direction bits (gui folder). 0 = no move until ported. */
export let gui_tmr_cursor_v: () => number = () => 0
export let gui_tmr_cursor_h: () => number = () => 0
export function setGuiDeps(
  d: Partial<{ gui_tmr_cursor_v: () => number; gui_tmr_cursor_h: () => number }>,
): void {
  if (d.gui_tmr_cursor_v) gui_tmr_cursor_v = d.gui_tmr_cursor_v
  if (d.gui_tmr_cursor_h) gui_tmr_cursor_h = d.gui_tmr_cursor_h
}

// ---- rando ---------------------------------------------------------------------------------------
/** `Rando_get_new_seed()` — `randomize(); return random_get_seed();` */
export let Rando_get_new_seed: () => number = () => world.randomize()
export let Rando_randomize_file: (
  fileNum: number,
  questNum: number,
  seed: number,
  settings: string,
) => unknown = notPorted('Rando_randomize_file')
export let Rando_draw_seed: (...a: unknown[]) => void = notPorted('Rando_draw_seed')
export function setRandoDeps(
  d: Partial<{
    Rando_get_new_seed: typeof Rando_get_new_seed
    Rando_randomize_file: typeof Rando_randomize_file
    Rando_draw_seed: typeof Rando_draw_seed
  }>,
): void {
  if (d.Rando_get_new_seed) Rando_get_new_seed = d.Rando_get_new_seed
  if (d.Rando_randomize_file) Rando_randomize_file = d.Rando_randomize_file
  if (d.Rando_draw_seed) Rando_draw_seed = d.Rando_draw_seed
}

// ---- player character (goa) ----------------------------------------------------------------------
export interface PcScreenView {
  behavior_DAMAGE: number
  behavior_IDLE: number
  fairy_sprite: string
  x: number
  y: number
  x_change: number
  y_change: number
}
export const pcRef = (): PcScreenView | null => (G.pc === NOONE ? null : (G.pc as PcScreenView))
export let pc_is_cucco: () => boolean = () => false
export let pc_is_fairy: () => boolean = () => false
/** `draw_pc_skin(x, y, xscale, yscale, behavior, disguise, ..., palIdx, *color)` */
export let draw_pc_skin: (...a: unknown[]) => void = notPorted('draw_pc_skin')
export function setPcDeps(
  d: Partial<{ pc_is_cucco: () => boolean; pc_is_fairy: () => boolean; draw_pc_skin: typeof draw_pc_skin }>,
): void {
  if (d.pc_is_cucco) pc_is_cucco = d.pc_is_cucco
  if (d.pc_is_fairy) pc_is_fairy = d.pc_is_fairy
  if (d.draw_pc_skin) draw_pc_skin = d.draw_pc_skin
}

// ---- tile ----------------------------------------------------------------------------------------
/**
 * `get_scene_ts_data()` — the current scene file's tilesets (`tile` folder). GML json_encodes the map and
 * its callers decode it again; the port hands the map itself over. `undefined` = no tileset data.
 */
export let get_scene_ts_data: () => DsMap<number | string> | undefined = notPorted('get_scene_ts_data')
/**
 * `set_scene_tile_file(map)` — installs a parsed Tiled map as `g.dm_tile_file` (`tile` folder). GML's
 * callers `json_decode` the file text; `rm_get_file_data` here returns the parsed map, so they install it.
 */
export let set_scene_tile_file: (map: TiledMap) => unknown = notPorted('set_scene_tile_file')
export function setTileDeps(d: {
  get_scene_ts_data: typeof get_scene_ts_data
  set_scene_tile_file: typeof set_scene_tile_file
}): void {
  get_scene_ts_data = d.get_scene_ts_data
  set_scene_tile_file = d.set_scene_tile_file
}
