/**
 * `Tyell` + `TyellManager` — ZALiA `enemy/tyell`: added enemy. A Tyell hides as a 2x2 breakable block, is
 * activated by the manager (at most `Activated_MAX` counting down), aims at the PC, launches, and breaks up.
 */
import {
  CS_BD1,
  CS_PR1,
  CS_SW1,
  DEPTH_BG1,
  DEPTH_ENEMY,
  dk_BlockBreak,
  dk_StrikeEnemy,
  STR_Data,
  STR_Datakey,
  STR_Enemy,
  STR_Randomize,
  STR_Randomized,
  STR_Spawn,
  TID_BREAK1,
  TID_HIDE_1,
  TID_SOLID1,
  TSRC_BREAK1_A,
  TSRC_BREAK1_B,
  TSRC_BREAK1_C,
} from '@z2/data'
import { gmBool, sign8b } from '../../../../../../nes/math8'
import { DsGrid, DsList } from '../../../../../../runtime/ds'
import { f, G, g, world } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { rectInRect } from '../../../../../collision/geometry'
import { ocsHV4 } from '../../../../../collision/ocs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { isVal, sign_ } from '../../../../../math/index'
import { hex_str, val } from '../../../../../other/index'
import { registerObjectClass } from '../../../../../other/registry'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { draw_background_part } from '../../../../../rooms/draw'
import { aud_play_sound, audio_stop_sound } from '../../../../../sound/play'
import { get_audio_theme_track } from '../../../../../sound/theme'
import { tile_change_1a } from '../../../../../tile/tileOps'
import { cam_x_range, cam_xl_min, cam_y_range, cam_yt_min } from '../../../../../view/camera'
import { Enemy } from '../../../../classes'
