const point_distance = (x1: number, y1: number, x2: number, y2: number) => Math.hypot(x2 - x1, y2 - y1)

export class Tyell extends Enemy {
  readonly objectName = 'Tyell' as const
  DEPTH_BG = DEPTH_BG1
  SUB_STATE_IDLE1 = 1
  SUB_STATE_LAUNCH_COUNTDOWN = 2
  SUB_STATE_AIM = 3
  SUB_STATE_ATK1 = 4
  SUB_STATE_ATK2 = 5
  SUB_STATE_BREAK = 6
  SUB_STATE_DONE1 = 7
  SUB_STATE_DONE = 8
  sub_state = 1
  use_tiles = true
  UNIQUE = TID_BREAK1
  anim_frame = 0
  anim_ctr = 0
  /** dg_anim[frame, 0..2] = duration, tileset, packed tsrc */
  dg_anim = new DsGrid<number | string>(4, 3, 0)
  IDL1_DUR = 0x80
  AGRO_DUR = 0x00
  HOVR_DUR = 0xc0
  ATK_DELAY1_DUR = 0x10
  LaunchCountdown_DUR = 0x50
  LaunchCountdown_timer = 0x50
  RISE_DIST = 0x06
  RISE_VSPD_MAX = 0x10
  RISE_VSPD_INC = 0x02
  aim_move_dir = 1
  aim_axis = 0
  AIM_SPD = 0x10
  AGRO_DIST = 0xc0
  ATCK_SPD = 0x30
  ATK_LEVEL = 0
}
registerObject('Tyell', Tyell)
registerObjectClass('Tyell', Tyell)

export class TyellManager extends Enemy {
  readonly objectName = 'TyellManager' as const
  AGRO_DIST = 0x0100
  Activated_MAX = 1
  dl_inst = new DsList<Tyell>()
}
registerObject('TyellManager', TyellManager)
registerObjectClass('TyellManager', TyellManager)

/** `Tyell_init1()` */
export function Tyell_init1(self: Tyell): void {
  GameObjectB_init(self)
  GO_depth_init(self, DEPTH_ENEMY)
  self.DEPTH_BG = DEPTH_BG1
  self.DRAW_YOFF = 0
  let _a = 1
  self.SUB_STATE_IDLE1 = _a++
  self.SUB_STATE_LAUNCH_COUNTDOWN = _a++
  self.SUB_STATE_AIM = _a++
  self.SUB_STATE_ATK1 = _a++
  self.SUB_STATE_ATK2 = _a++
  self.SUB_STATE_BREAK = _a++
  self.SUB_STATE_DONE1 = _a++
  self.SUB_STATE_DONE = _a++
  self.sub_state = self.SUB_STATE_IDLE1
  self.use_tiles = true
  self.UNIQUE = TID_BREAK1
  self.anim_frame = 0
  self.anim_ctr = 0
  self.dg_anim = new DsGrid<number | string>(4, 3, 0)
  self.IDL1_DUR = 0x80
  self.AGRO_DUR = 0x00
  self.HOVR_DUR = 0xc0
  self.ATK_DELAY1_DUR = 0x10
  self.LaunchCountdown_DUR = 0x50 + world.irandom(0x40)
  self.LaunchCountdown_timer = self.LaunchCountdown_DUR
  self.RISE_DIST = 0x06
  self.RISE_VSPD_MAX = 0x10
  self.RISE_VSPD_INC = 0x02
  self.aim_move_dir = 1 // 1: RGT, 2: LFT, 4: DWN, 8: UP
  self.aim_axis = 0 // 0: Horizontal, 1: Vertical
  self.AIM_SPD = 0x10
  self.AGRO_DIST = 0xc0
  self.ATCK_SPD = 0x30
  self.ATK_LEVEL = world.irandom(1) // 0 High, 1 Low
}

/** `Tyell_init2()` */
export function Tyell_init2(self: Tyell): void {
  for (const m of instancesOfName<TyellManager>('TyellManager')) self.AGRO_DIST = m.AGRO_DIST
  let _spawn_datakey = self.dk_spawn
  if (self.dk_spawn !== undefined) {
    _spawn_datakey = val(
      f.dm_rando.get(
        STR_Randomize + STR_Enemy + STR_Spawn + self.dk_spawn + STR_Spawn + STR_Datakey + STR_Randomized,
      ),
      self.dk_spawn,
    ) as string
  }
  if (_spawn_datakey !== undefined) {
    const _dk = `${STR_Data}01`
    for (let _i = 1; _i <= 0x0f; _i++) {
      const _val = val(g.dm_spawn.get(_spawn_datakey + STR_Data + hex_str(_i)))
      if (typeof _val === 'string') {
        const _pos = _val.indexOf(_dk)
        if (_pos >= 0) {
          self.DEPTH_BG = Number(_val.slice(_pos + _dk.length))
          break
        }
      }
    }
  }
  const _ts = 'ts_Man_made_1a_WRB'
  const A = self.dg_anim
  // Unbroken
  A.set(0x00, 0, 1) // Duration
  A.set(0x00, 1, _ts) // Tileset
  A.set(0x00, 2, TSRC_BREAK1_A) // tsrc.  TSRC_BREAK1_A: ('90' + '91' + '92' + '93')
  // Cracked
  A.set(0x01, 0, 8)
  A.set(0x01, 1, _ts)
  A.set(0x01, 2, TSRC_BREAK1_B)
  // Dust
  A.set(0x02, 0, 8)
  A.set(0x02, 1, _ts)
  A.set(0x02, 2, TSRC_BREAK1_C)
  // Nothing
  A.set(0x03, 0, 1)
  A.set(0x03, 1, 0)
  A.set(0x03, 2, 0)
  for (let _i = A.width - 1; _i >= 0; _i--) {
    const _data = A.get(_i, 2)
    if (_data === 0 || typeof _data !== 'string') continue
    A.set(_i, 2, 0)
    for (let _j = (_data.length >> 1) - 1; _j >= 0; _j--) {
      A.set(_i, 2, ((A.get(_i, 2) as number) | (str_hex(_data.substr(_j << 1, 2)) << (_j << 3))) >>> 0)
    }
  }
  const _HIDDEN = TID_HIDE_1 & 0x0f // TID_HIDE_1: Hidden when rm is NOT lit.
  for (let _i = 0; _i < 4; _i++) {
    const _tsrc = ((A.get(0, 2) as number) >>> (_i << 3)) & 0xff
    const _x = self.xl + ((_i & 1) << 3)
    const _y = self.yt + ((_i > 1 ? 1 : 0) << 3)
    tile_change_1a(self.DEPTH_BG, _x, _y, _ts, _tsrc, TID_SOLID1, self.UNIQUE, _HIDDEN)
  }
  self.timer = self.IDL1_DUR
}

/** `Tyell_update_1()` — Remove tile's solid, unique, hidden */
export function Tyell_update_1(self: Tyell): void {
  for (let _i = 0; _i < 4; _i++) {
    const _x = self.spawn_xl + ((_i & 1) << 3)
    const _y = self.spawn_yt + ((_i > 1 ? 1 : 0) << 3)
    tile_change_1a(self.DEPTH_BG, _x, _y, 0, 0, 0, 0, 0)
  }
}

/** `Tyell_udp()` */
export function Tyell_udp(self: Tyell): void {
  self.can_draw_self =
    isVal(self.sub_state, self.SUB_STATE_ATK1, self.SUB_STATE_ATK2, self.SUB_STATE_BREAK) &&
    self.anim_frame < self.dg_anim.width
}

/** `Tyell_update()` */
export function Tyell_update(self: Tyell): void {
  const P = pc()
  const A = self.dg_anim
  GO_update_cs(self)
  if (isVal(self.sub_state, self.SUB_STATE_IDLE1, self.SUB_STATE_LAUNCH_COUNTDOWN)) {
    if (((g.dg_RmTile_Break.get(self.xl >> 3, self.yt >> 3) as number) & 0xff) !== self.UNIQUE) {
      // PC broke block before attack.
      self.timer = 0
      self.sub_state = self.SUB_STATE_DONE1
      return
    }
  } else if (isVal(self.sub_state, self.SUB_STATE_ATK1, self.SUB_STATE_ATK2)) {
    GOB_update_2(self)
    if (
      self.state !== self.state_NORMAL ||
      !rectInRect(
        self.xl,
        self.yt,
        self.ww,
        self.hh,
        cam_xl_min(),
        cam_yt_min(),
        cam_x_range(),
        cam_y_range(),
      )
    ) {
      self.sub_state = self.SUB_STATE_DONE1
      return
    }
    if (self.cs & (CS_BD1 | CS_SW1 | CS_PR1)) {
      if (self.cs & CS_BD1) enemy_collide_pc_body(self)
      self.stun_timer = 0 // prevent stun flash
      audio_stop_sound(get_audio_theme_track(dk_StrikeEnemy))
      aud_play_sound(get_audio_theme_track(dk_BlockBreak))
      self.anim_frame = 0
      self.timer = A.get(self.anim_frame, 0) as number
      self.sub_state = self.SUB_STATE_BREAK
      return
    }
    if (self.sub_state === self.SUB_STATE_ATK2) {
      const _CLMS = G.dg_solid_w
      const _ROWS = G.dg_solid_h
      // 9 points. 3 TOP, 3 MID, 3 BTM
      for (let _i = 0; _i < 9; _i++) {
        let _x = _i % 3
        let _y = Math.trunc(_i / 3)
        _x = self.xl + (_x << 3) - (_x === 2 ? 1 : 0)
        _y = self.yt + (_y << 3) - (_y === 2 ? 1 : 0)
        _x = _x >> 3
        _y = _y >> 3
        if (!gmBool(_x) || _x >= _CLMS || !gmBool(_y) || _y >= _ROWS) continue
        if (gmBool(G.dg_solid.get(_x, _y)) && !gmBool(g.dg_RmTile_Break.get(_x, _y))) {
          aud_play_sound(get_audio_theme_track(dk_BlockBreak))
          self.anim_frame = 0
          self.timer = A.get(self.anim_frame, 0) as number
          self.sub_state = self.SUB_STATE_BREAK
          return
        }
      }
    }
  } else if (self.sub_state === self.SUB_STATE_BREAK) {
    update_EF11(self)
  }
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE1:
      // TyellManager will activate.
      break
    case self.SUB_STATE_LAUNCH_COUNTDOWN: {
      if (gmBool(self.timer)) break
      if (point_distance(self.x, self.y, P.x, P.y) > self.AGRO_DIST) break
      if (gmBool(self.LaunchCountdown_timer)) {
        self.LaunchCountdown_timer--
        break
      }
      self.hspd = 0
      self.vspd = 0
      switch (self.ver) {
        case 1:
          self.vspd = (self.AIM_SPD * -sign_(self.y - P.y)) & 0xff
          break
        case 2:
          self.hspd = (self.AIM_SPD * -sign_(self.x - P.x)) & 0xff
          break
        case 3:
          self.vspd = (self.AIM_SPD * -sign_(self.y - P.y)) & 0xff
          break // ZALiA's `hspd = …` after this break is unreachable
      }
      Tyell_update_1(self) // Remove tile's solid, unique, hidden
      self.can_draw_self = true
      self.timer = self.AGRO_DUR
      self.sub_state = self.SUB_STATE_ATK1
      break
    }
    case self.SUB_STATE_ATK1: {
      // Aim
      if (gmBool(self.timer)) break
      if (gmBool(self.hspd)) {
        updateX(self)
        if (!gmBool((P.x - self.x) * sign8b(self.hspd))) {
          set_xy(self, P.x, self.y)
          self.hspd = 0
          self.vspd = (self.ATCK_SPD * -sign_(self.y - P.y)) & 0xff
          self.timer = self.ATK_DELAY1_DUR
          self.sub_state = self.SUB_STATE_ATK2
        }
      } else if (gmBool(self.vspd)) {
        let _PC_Y = P.y - 8
        if (gmBool(self.ATK_LEVEL)) _PC_Y += 0x10
        if (!gmBool((_PC_Y - self.y) * sign8b(self.vspd))) {
          self.hspd = (self.ATCK_SPD * -sign_(self.x - P.x)) & 0xff
          self.vspd = 0
          self.timer = self.ATK_DELAY1_DUR
          self.sub_state = self.SUB_STATE_ATK2
        } else {
          updateY(self)
        }
      }
      break
    }
    case self.SUB_STATE_ATK2: {
      if (gmBool(self.timer)) break
      if (gmBool(self.hspd)) updateX(self)
      if (gmBool(self.vspd)) updateY(self)
      break
    }
    case self.SUB_STATE_BREAK: {
      if (gmBool(self.timer)) break
      self.anim_frame++
      if (self.anim_frame >= A.width) {
        self.timer = 0x20 // Delays opening door (if one is waiting)
        self.sub_state = self.SUB_STATE_DONE1
      } else {
        self.timer = A.get(self.anim_frame, 0) as number
      }
      break
    }
    case self.SUB_STATE_DONE1: {
      if (gmBool(self.timer)) break
      self.can_draw_self = false
      GOB_update_data_defeated(self)
      self.sub_state = self.SUB_STATE_DONE
      break
    }
    case self.SUB_STATE_DONE: {
      if (gmBool(self.timer)) break
      self.can_draw_self = false
      Tyell_update_1(self) // Remove tile's solid, unique, hidden
      self.state = 0
      if (gmBool(g.mod_destroy_go_on_death)) GO_destroy_1a(self)
      break
    }
  }
}

/** `Tyell_draw()` */
export function Tyell_draw(self: Tyell): void {
  if (!self.can_draw_self) return
  const A = self.dg_anim
  if (self.anim_frame >= A.width) return
  if (!gmBool(A.get(self.anim_frame, 0x01))) return
  if (self.use_tiles) {
    const _TS = A.get(self.anim_frame, 0x01) as string
    const _TSRC = A.get(self.anim_frame, 0x02) as number
    pal_swap_set(self.palidx)
    for (let _i = 0; _i < 4; _i++) {
      const _ts_x = ((_TSRC >>> ((_i << 3) + 0x00)) & 0x0f) << 3
      const _ts_y = ((_TSRC >>> ((_i << 3) + 0x04)) & 0x0f) << 3
      const _x = self.drawX - ((_i & 0x01 ? 0 : 1) << 3)
      const _y = self.drawY - ((_i < 0x02 ? 1 : 0) << 3)
      draw_background_part(_TS, _ts_x, _ts_y, 8, 8, _x, _y)
    }
    pal_swap_reset()
  }
}

/** `Tyell_end()` — dg_anim is a plain grid here; nothing to free. */
export function Tyell_end(_self: Tyell): void {}

/** `TyellManager_init1()` */
export function TyellManager_init1(self: TyellManager): void {
  GameObjectB_init(self)
  self.AGRO_DIST = 0x0100
  self.Activated_MAX = 1
  self.dl_inst = new DsList<Tyell>()
}

/** `TyellManager_init2()` — empty in ZALiA. */
export function TyellManager_init2(_self: TyellManager): void {}

/** `TyellManager_update()` */
export function TyellManager_update(self: TyellManager): void {
  if (!instanceExistsNamed('Tyell')) {
    if (gmBool(g.mod_destroy_go_on_death)) GO_destroy_1a(self)
    return
  }
  const P = pc()
  let _LaunchCountdown_COUNT = 0
  const _dl_delete: number[] = []
  for (let _i = self.dl_inst.size - 1; _i >= 0; _i--) {
    const _inst = self.dl_inst.get(_i)
    if (
      !_inst ||
      !_inst.exists ||
      _inst.state !== _inst.state_NORMAL ||
      _inst.sub_state !== _inst.SUB_STATE_LAUNCH_COUNTDOWN
    ) {
      _dl_delete.push(_i)
    } else {
      _LaunchCountdown_COUNT += point_distance(_inst.x, _inst.y, P.x, P.y) <= self.AGRO_DIST ? 1 : 0
    }
  }
  for (let _i = _dl_delete.length - 1; _i >= 0; _i--) self.dl_inst.delete(_dl_delete[_i] as number)
  const _COUNT1 = self.Activated_MAX - _LaunchCountdown_COUNT
  if (gmBool(_COUNT1)) {
    const _dl_options: Tyell[] = []
    for (const t of instancesOfName<Tyell>('Tyell')) {
      // if ALL w and ALL h in ocs area
      if (
        t.state === t.state_NORMAL &&
        t.sub_state === t.SUB_STATE_IDLE1 &&
        ocsHV4(t) &&
        point_distance(t.x, t.y, P.x, P.y) <= self.AGRO_DIST
      )
        _dl_options.push(t)
    }
    if (_dl_options.length) {
      // ds_list_shuffle
      for (let i = _dl_options.length - 1; i > 0; i--) {
        const j = world.irandom(i)
        const tmp = _dl_options[i] as Tyell
        _dl_options[i] = _dl_options[j] as Tyell
        _dl_options[j] = tmp
      }
      for (let _i = _COUNT1 - 1; _i >= 0; _i--) {
        const t = _dl_options[_i]
        if (!t) continue
        self.dl_inst.add(t)
        t.sub_state = t.SUB_STATE_LAUNCH_COUNTDOWN
      }
    }
  }
}

registerScripts({
  Tyell_init1,
  Tyell_init2,
  Tyell_update,
  Tyell_update_1,
  Tyell_udp,
  Tyell_draw,
  Tyell_end,
  TyellManager_init1,
  TyellManager_init2,
  TyellManager_update,
})
