/**
 * The player's projectiles — ZALiA object `ProjectileFriendly` (sword beam / fire): `PCProj_init_vars`,
 * `PCProj_init`, `spawn_pc_proj`, `spawn_pc_proj_2a`, `update_pc_proj`, `update_pc_proj_1a/1b/2a`,
 * `usd_pc_proj_1a/1b`, `PCProj_draw`. The manager pre-fills `dl_goc2` with MAX_GOC2 dormant instances; the
 * GML made them `ProjectileFriendly`, so `ensurePCProjSlots()` replaces any plain placeholder with a `PCProj`.
 */
import {
  Container_AMT,
  DEPTH_PC_SWORD_BEAM,
  ITM_SWRD,
  PC_LOCK_PRJ1,
  PC_LOCK_PRJ2,
  SPL_FIRE,
  STR_Beam,
  STR_Heart,
  STR_Sword,
  VIEW_W_OG,
} from '@z2/data'
import { gmBool } from '../../../../nes/math8'
import { NOONE, type Ref } from '../../../../runtime/instance'
import { f, g, goMgr, p, world } from '../../../../runtime/world'
import { wINw } from '../../../collision/geometry'
import { update_body_hb } from '../../../collision/hitbox'
import { ocsH4 } from '../../../collision/ocs'
import { get_stat_max } from '../../../file/stats'
import { PI_LIT1, PI_MOB_BLU, PI_MOB_ORG, PI_PC1 } from '../../../palette/pi'
import { rm_pal_qual_lit } from '../../../palette/roomStart'
import { aud_play_fire, aud_play_sound } from '../../../sound/play'
import { get_audio_theme_track } from '../../../sound/theme'
import { PlainProjectileFriendly, ProjectileFriendly } from '../../classes'
import { GameObject_draw_1a } from '../../go/draw'
import { installInstanceEnd } from '../../go/lifecycle'
import { GO_update_cam_vars } from '../../go/misc'
import { GO_udp_1, set_xlyt, update_draw_xy, updateX } from '../../go/movement'
import { GO_init_palidx } from '../../go/palette'
import { GO_depth_init, GO_set_sprite, GO_sprite_init } from '../../go/sprite'
import { devDraw } from '../../goa/deps'
import { pc, pc_is_cucco } from '../../goa/index'
import { registerObject, registerScripts } from '../../registry'

export class PCProj extends ProjectileFriendly {
  readonly objectName = 'ProjectileFriendly' as const
  // ---- PCProj_init_vars ---------------------------------------------------------------------
  DURATION0 = 0x0e
  DURATION1 = 0x20
  CUE1 = 0x100 - this.DURATION0 // $F2
  timeout_BEAM1 = this.CUE1 - this.DURATION1
  timeout_BEAM2 = this.CUE1 - (this.DURATION1 + 0x1c)
  timeout_FIRE1 = 0x00
  timeout = this.timeout_BEAM1 // 05CA
  CUE2 = this.timeout_BEAM2 + (this.DURATION1 + (this.DURATION0 >> 2))
  readonly TypeID_BEAM = 1
  readonly TypeID_FIRE = 2
  TypeID = this.TypeID_BEAM

  constructor() {
    super()
    PCProj_init(this)
  }
}

/** `PCProj_init_vars()` */
export function PCProj_init_vars(self: PCProj): void {
  self.update_idx = 0
  self.disintegrate_counter = 0 // counter disintegrate
  self.DURATION0 = 0x0e
  self.DURATION1 = 0x20
  self.CUE1 = 0x100 - self.DURATION0 // $F2
  self.timeout_BEAM1 = self.CUE1 - self.DURATION1
  self.timeout_BEAM2 = self.CUE1 - (self.DURATION1 + 0x1c)
  self.timeout_FIRE1 = 0x00
  self.timeout = self.timeout_BEAM1 // 05CA
  self.CUE2 = self.timeout_BEAM2 + (self.DURATION1 + (self.DURATION0 >> 2))
  self.type_bits = self.BIT_BEM1
  self.TypeID = self.TypeID_BEAM
}

/** `PCProj_init()` — create event. */
export function PCProj_init(self: PCProj): void {
  PCProj_init_vars(self)
  self.DRAW_YOFF = 0 // default GameObject draw YOff
  GO_depth_init(self, DEPTH_PC_SWORD_BEAM)
  self.dl_sprites?.set(1, 'spr_Fireball1')
  self.dl_sprites?.set(0, 'spr_Link_sword_beam')
  GO_sprite_init(self, 'spr_Link_sword_beam')
  GO_init_palidx(self, PI_MOB_ORG)
  self.BodyHB_xoff = 2 + g.HB_ADJ_X
  self.BodyHB_yoff = 4 + g.HB_ADJ_Y
  self.BodyHB_w = 4 + g.HB_ADJ_W
  self.BodyHB_h = 6 + g.HB_ADJ_H
}

/** Make every `dl_goc2` slot a `PCProj` (the manager fills them with plain placeholders). */
export function ensurePCProjSlots(): void {
  const list = goMgr.dl_goc2
  for (let i = 0; i < list.size; i++) {
    const cur = list.get(i)
    if (cur instanceof PCProj) continue
    if (cur?.exists && !(cur instanceof PlainProjectileFriendly)) continue
    if (cur?.exists) cur.destroy()
    const inst = new PCProj()
    installInstanceEnd(inst)
    inst.state = 0
    list.set(i, world.register(inst))
  }
}

const slot = (i: number): PCProj | null => {
  const p = goMgr.dl_goc2.get(i)
  return p instanceof PCProj && p.exists ? p : NOONE
}

/** `spawn_pc_proj(GO_Mgr dl_goc2 index)` — fire the projectile in that slot; returns it or noone. */
export function spawn_pc_proj(idx: number): Ref<PCProj> {
  if (!(idx + 1) || idx >= goMgr.dl_goc2.size) return NOONE
  const self = slot(idx)
  if (!self) return NOONE
  const P = pc()
  let _CUCCO_BEAM = 0
  let _CUCCO_FIRE = 0
  const _CUCCO = pc_is_cucco()
  if (_CUCCO) {
    _CUCCO_BEAM = (f.CuccoSkill_PROJ1 * Number(g.CUCCO_CAN_BEAM)) & f.Cucco_skills
    _CUCCO_FIRE = (f.CuccoSkill_PROJ2 * Number(g.CUCCO_CAN_FIRE)) & f.Cucco_skills
    if (!(_CUCCO_BEAM | _CUCCO_FIRE)) return NOONE
  }
  const _FIRE = !!(g.spells_active & SPL_FIRE) && (!_CUCCO || !!_CUCCO_FIRE)
  if (!_FIRE && g.pc_lock & PC_LOCK_PRJ1) return NOONE
  if (_FIRE && g.pc_lock & PC_LOCK_PRJ2) return NOONE
  self.state = self.state_NORMAL
  self.disintegrate_counter = 0
  self.type_bits = _FIRE ? self.BIT_FIR1 : self.BIT_BEM1
  self.TypeID = _FIRE ? self.TypeID_FIRE : self.TypeID_BEAM
  switch (self.TypeID) {
    case self.TypeID_BEAM:
      self.timeout = f.items & ITM_SWRD ? self.timeout_BEAM2 : self.timeout_BEAM1 // $C2 / $D2
      break
    case self.TypeID_FIRE:
      self.timeout = self.timeout_FIRE1 // $00
      break
    default:
      self.timeout = 0
  }
  const _XOFF = -3
  let _YOFF = 0
  if (_FIRE) {
    _YOFF = P.stab_type ? 4 : 13 // Stab high / low
    if (_CUCCO) _YOFF = 13 - 16 + 2
  } else {
    _YOFF = P.stab_type ? 0 : 10
    if (_CUCCO) _YOFF = 10 - 16 + 2
  }
  set_xlyt(self, P.x + _XOFF, P.yt + _YOFF)
  self.facing_dir = P.xScale
  self.xScale = self.facing_dir
  self.hspd = (0x20 * self.facing_dir) & 0xff
  update_body_hb(self)
  update_draw_xy(self)
  if (!_FIRE) aud_play_sound(get_audio_theme_track(STR_Sword + STR_Beam))
  else aud_play_fire(true)
  return self
}

/** `spawn_pc_proj_2a()` — on the stab frame, spawn a beam/fire if a slot and a token are available. */
export function spawn_pc_proj_2a(): Ref<PCProj> {
  const P = pc()
  if (P.attack_phase - 1 !== P.stab_type || P.attack_timer !== P.attack_phase_DURATION1 - 1) return NOONE // 5
  ensurePCProjSlots()
  let _idx = -1
  let _tokens = 1
  if (g.spells_active & SPL_FIRE) {
    if (f.level_atk >= 4) {
      if (!pc_is_cucco() || (gmBool(g.CUCCO_CAN_FIRE) && f.Cucco_skills & f.CuccoSkill_PROJ2)) _tokens++
    }
  } else if (f.items & ITM_SWRD) {
    for (let _i = goMgr.dl_goc2.size - 1; _i >= 0; _i--) {
      const _proj = slot(_i)
      if (!_proj) continue
      if (_proj.state && _proj.timeout >= _proj.CUE2) {
        _tokens++
        break
      }
    }
  }
  for (let _i = goMgr.dl_goc2.size - 1; _i >= 0; _i--) {
    if (!_tokens) return NOONE
    const _proj = slot(_i)
    if (!_proj) continue
    if (!_proj.state) {
      _idx = _i
      continue // keep updating _tokens
    }
    if (wINw(_proj.BodyHB_xl, _proj.BodyHB_w, g.view_xl_og, VIEW_W_OG)) _tokens--
  }
  if (_tokens && _idx + 1) return spawn_pc_proj(_idx) // limit NOT reached && an instance was available
  return NOONE
}

/** `update_pc_proj()` — 9878 */
export function update_pc_proj(): void {
  for (let _i = goMgr.dl_goc2.size - 1; _i >= 0; _i--) {
    const self = slot(_i)
    if (!self?.state) continue
    if (self.state && self.timeout) self.timeout = (self.timeout + 1) & 0xff
    switch (self.state) {
      case self.state_NORMAL: {
        self.BodyHB_can_draw = true
        // 9895
        switch (self.TypeID) {
          case self.TypeID_BEAM:
            if (self.timeout === self.CUE1) {
              // 98BD
              self.disintegrate_counter = self.timeout
              self.state = self.state_EXPLODE
            } else update_pc_proj_1b(self) // 98A6
            break
          case self.TypeID_FIRE:
            aud_play_fire(true) // Fireball
            update_pc_proj_1b(self)
            break
        }
        break
      }
      case self.state_EXPLODE: {
        // 9908: JSR 98A6
        update_pc_proj_1b(self)
        usd_pc_proj_1b(self)
        self.disintegrate_counter = (self.disintegrate_counter + 2) & 0xff
        if (!self.disintegrate_counter) {
          self.disintegrate_counter = 0
          self.state = 0
        }
        break
      }
    }
  }
}

/** `update_pc_proj_1a()` — SPAWN BEAM. D50D: JSR 9847 */
export function update_pc_proj_1a(): void {
  let _qual = false
  const _MAX = get_stat_max(STR_Heart)
  let _MIN = _MAX
  if (gmBool(g.mod_PCBeamHP) && f.items & ITM_SWRD && f.level_atk >= 4) _MIN = _MAX - Container_AMT
  if (f.hp >= _MIN && f.hp <= _MAX) {
    _qual = !(g.spells_active & SPL_FIRE)
    if (!_qual && pc_is_cucco()) {
      // if cucco has only beam ability and NOT fire ability
      const _BEAM = f.CuccoSkill_PROJ1 * Number(g.CUCCO_CAN_BEAM)
      const _FIRE = f.CuccoSkill_PROJ2 * Number(g.CUCCO_CAN_FIRE)
      _qual = (f.Cucco_skills & (_BEAM | _FIRE)) === f.CuccoSkill_PROJ1
    }
  }
  if (_qual) spawn_pc_proj_2a()
}

/** `update_pc_proj_1b()` — 98A6, 98AB: JSR D1CE */
export function update_pc_proj_1b(self: PCProj): void {
  updateX(self)
  GO_update_cam_vars(self) // 98B0: JSR F27D
  // 98B3. 230707: changed 'if (ocsHV3(id))' to 'if (ocsH4(id))' to prevent extra beam sound when above view
  if (ocsH4(self))
    usd_pc_proj_1a(self) // 98C0
  else {
    // 98BB
    self.disintegrate_counter = 0
    self.state = 0
  }
}

/** `update_pc_proj_2a()` — update PC projectile hitboxes (after camera, before go_mgr updates). */
export function update_pc_proj_2a(): void {
  for (let _i = goMgr.dl_goc2.size - 1; _i >= 0; _i--) {
    const self = slot(_i)
    if (!self?.state) continue
    update_body_hb(self)
  }
}

/** `usd_pc_proj_1a()` — 98C0 */
export function usd_pc_proj_1a(self: PCProj): void {
  GO_udp_1(self) // drawX=x; drawY=y; xScale=facingDir;
  self.can_draw_self = true
  const _BEAM = self.type_bits & self.BIT_BEM1
  const _FIRE = self.type_bits & self.BIT_FIR1
  if (_BEAM)
    GO_set_sprite(self, self.dl_sprites?.get(0) ?? 'spr_Link_sword_beam') // Beam
  else if (_FIRE)
    GO_set_sprite(self, self.dl_sprites?.get(1) ?? 'spr_Fireball1') // Fire
  else GO_set_sprite(self, self.dl_sprites?.get(0) ?? 'spr_Link_sword_beam') // Default(Beam)
  self.yScale = _FIRE && g.counter1 & 0x4 ? -1 : 1
  if (!_FIRE && g.counter1 & 0x2) self.palidx_base = rm_pal_qual_lit() ? PI_MOB_BLU : PI_PC1
  else self.palidx_base = self.palidx_def // PI_MOB1: orange
  if (rm_pal_qual_lit()) self.palidx_base += PI_LIT1
  else if (!_FIRE) self.palidx_base += p.PI_DRK1
  self.palidx = self.palidx_base
  update_draw_xy(self)
}

/** `usd_pc_proj_1b()` — disintegrating. 990B */
export function usd_pc_proj_1b(self: PCProj): void {
  self.can_draw_self = true
  self.palidx_base = self.palidx_def
  self.palidx_base += PI_LIT1
  self.palidx = self.palidx_base
  if (self.disintegrate_counter & 0x8) GO_set_sprite(self, 'spr_Projectile_Disintegrate2')
  else GO_set_sprite(self, 'spr_Projectile_Disintegrate1')
}

/** `PCProj_draw()` */
export function PCProj_draw(self: PCProj): void {
  if (!self.state) return
  if (self.can_draw_self) GameObject_draw_1a(self, self.sprite as string, self.palidx)
  devDraw.GO_draw_body_hb(self) // Toggle with 'N'
  devDraw.GO_draw_sprite_outline(self) // Sequence with 'K'
}

registerObject('ProjectileFriendly', PCProj)
registerScripts({ PCProj_init, PCProj_draw })
