/** Moby (`MobyA`) — the diving bird. Ported from `Moby_init2/update/udp.gml`. */
import { CS_BD1, DEPTH_FLYER } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G } from '../../../../../../runtime/world'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { Enemy } from '../../../../classes'
import { updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_depth_init } from '../../../../go/sprite'
import { pc } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_udp_1, GOB_update_2 } from '../../../GameObjectB'

export class MobyA extends Enemy {
  readonly objectName = 'MobyA' as const
}

/** `Moby_init2()` */
export function Moby_init2(self: MobyA): void {
  self.dl_sprites?.add('spr_Moby1')
  self.dl_sprites?.add('spr_Moby2')
  GO_init_palidx(self, G.PI_MOB_ORG)
  GO_depth_init(self, DEPTH_FLYER)
}

/** `Moby_update()` */
export function Moby_update(self: MobyA): void {
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // 9B94: JSR DA02, 9B97
  if (self.yt >= pc().yt) {
    self.hspd = (0x20 * self.facing_dir) & 0xff
    self.vspd = 0
  }
  // 9BA7, 9BAA
  updateY(self)
  updateX(self)
  // 9BAD: JSR DE40
  GOB_update_2(self)
  // E2EF
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
}

/** `Moby_udp()` */
export function Moby_udp(self: MobyA): void {
  self.can_draw_self = true
  GOB_udp_1(self, 8)
}

export function registerMoby(): void {
  registerObject('MobyA', MobyA)
  registerScripts({ Moby_init2, Moby_update, Moby_udp })
}
registerMoby()
