// init_vars_MiniGame speed/delay symbols (resolved from the data table)
const SYMS: Record<string, number> = {
  HSPD_0: 0x00,
  HSPD_1: 0x08,
  HSPD_2: 0x10,
  HSPD_3: 0x18,
  HSPD_4: 0x20,
  HSPD_5: 0x28,
  HSPD_6: 0x30,
  HSPD_7: 0x38,
  HSPD_8: 0x40,
  HSPD_A: 0xff,
  HSPD_B: 0xfe,
  VSPD_0: 0x00,
  VSPD_A: 0xff,
  VSPD_B: 0xfe,
  VSPD_C: 0xfd,
  VSPD_D: 0xfc,
  VSPD_E: 0xfb,
  VSPD_F: 0xfa,
  VSPD_G: 0xf9,
  VSPD_H: 0xf8,
  DELAY_0: 0x00,
  DELAY_1: 0x05,
  DELAY_2: 0x0a,
  DELAY_3: 0x10,
  DELAY_4: 0x20,
  DELAY_5: 0x40,
  DELAY_6: 0x80,
  DELAY_7: 0xc0,
  _DIR_RGT: 1,
  _DIR_LFT: -1,
}

export function init_vars_MiniGame(self: MiniGame_A): void {
  self.timer = 0
  self.sub_state = self.ST_SUB1_PRE1
  self.SND_GAME_START = get_audio_theme_track(STR_Encounter + STR_Enter)
  self.SND_GAME_DONE = get_audio_theme_track(STR_Encounter + STR_Leave)
  self.MUS_GAME_THEME = `${dk_Minigame}01`
  self.MUS_GAME_PLAY = get_audio_theme_track(self.MUS_GAME_THEME)
  self.pc_allow = 0 // What actions pc allowed to do.
  self.points = 0
  self.DUR_DELAY_START = 0x20
  self.DUR_DELAY_FIRST = 0x40
  self.tmr_next = 0
  self.seq_idx = -1
  self.GROUND_Y = 0
  self.PC_START_GAME_X = 0
  self.points_can_draw = 0
  self.POINTS_X_OFF = 0x08 << 3 // dist from camXL
  self.POINTS_Y_OFF = 0x08 << 3 // dist from camYT
  self.dl_SEQ = new DsList<number>()
  self.dg_SEQ = new DsGrid<GameObject | number | null>(0, 6, 0)
}
export function init_MiniGame(self: MiniGame_A): void {
  init_vars_MiniGame(self)
  GO_depth_init(self, DEPTH_HUD)
  self.DRAW_YOFF = 0
}

/**
 * `MiniGameA_init.gml`'s case-2 block declares its own `var _X_00.._X_0A` (spawn tile columns) and — note —
 * a **local** `_VSPD_A = $C0` that shadows the file-level `VSPD_A`. Resolved separately so the shadow
 * cannot leak into the ver-1 tables.
 */
function resolveVer2(sym: string): number {
  if (sym === '_VSPD_A') return 0xc0 // local to case 2; the outer VSPD_A is $FF
  const x = /^_X_([0-9A-F]{2})$/.exec(sym)
  if (x) return Number.parseInt(x[1] as string, 16)
  if (sym in SYMS) return SYMS[sym] as number
  return str_hex(sym)
}

function resolve(self: MiniGame_A, sym: string): number {
  if (sym in SYMS) return SYMS[sym] as number
  const y = (self as unknown as Record<string, number>)[sym]
  if (sym.startsWith('Y_') && typeof y === 'number') return y
  const m = /^(HSPD_\d)\+\$([0-9A-F]+)$/.exec(sym)
  if (m) return (SYMS[m[1] as string] as number) + Number.parseInt(m[2] as string, 16)
  return str_hex(sym)
}

/** `MiniGameA_init()` — Mini Game A. Target game 1 */
export function MiniGameA_init(self: MiniGame_A): void {
  GO_depth_init(self, DEPTH_HUD)
  self.sub_state = self.ST_SUB1_PRE1
  self.SND_GAME_START = get_audio_theme_track(STR_Encounter + STR_Enter)
  self.SND_GAME_DONE = get_audio_theme_track(STR_Encounter + STR_Leave)
  self.MUS_GAME_THEME = `${dk_Minigame}01`
  self.MUS_GAME_PLAY = get_audio_theme_track(self.MUS_GAME_THEME)
  self.PC_START_GAME_X = self.x
  update_body_hb_1a(self)
  self.GROUND_Y = (((viewYC() >> 8) + 1) << 8) - (0x3 << 3)
  self.GROUND_Y = get_ground_y(self.PC_START_GAME_X, self.GROUND_Y, -1, self.GROUND_Y)
  const _ADD = 0x02
  let _a = 0x04
  self.Y_00 = self.GROUND_Y - (_a << 3)
  _a += _ADD // $20
  self.Y_01 = self.GROUND_Y - (_a << 3)
  _a += _ADD // $30
  self.Y_02 = self.GROUND_Y - (_a << 3)
  _a += _ADD // $40
  self.Y_03 = self.GROUND_Y - (_a << 3)
  _a += _ADD // $50
  self.Y_08 = self.GROUND_Y - (2 << 3)
  self.Y_09 = self.GROUND_Y - (4 << 3)
  self.POINTS_X_OFF = 0x08 << 3
  self.POINTS_Y_OFF = 0x10 << 3
  switch (self.ver) {
    case 1: {
      self.TARGET_OBJ = 'TargA'
      self.TARGET_VER = 1
      self.TARGET_W = 0x02 << 3
      self.SPAWN_DIST_HOR = viewW_() + (self.TARGET_W >> 1)
      self.pc_allow = PC_LOCK_ATK1 | PC_LOCK_ATK2
      const _SPAWN_COUNT = 30
      const _PROP_COUNT = 6
      const _Dir_IDX = 1
      const _Y_IDX = 2
      const _HSPD_IDX = 3
      const _Delay_IDX = 5
      // difficulty 1: $2,$6,$9,$A,$B; 2: $4,$5,$8; 3: $3,$7,$D
      let _CASE = gp().TargetGame_case // for testing cases
      if (!gmBool(_CASE)) {
        const _DATAKEY = STR_Target + STR_Game + STR_Order
        const _data = fp().dm_quests.get(_DATAKEY)
        if (typeof _data === 'string' && _data.length) {
          _CASE = str_hex(_data.substr(0, 2))
          fp().dm_quests.set(_DATAKEY, _data.substr(2))
        } else fp().dm_quests.set(_DATAKEY, fp().dm_quests.val(_DATAKEY + STR_Reset, '00') as string)
      }
      const table = MINI_GAME_A_CASES[_CASE] ?? MINI_GAME_A_CASES[1]
      if (!table) break
      const rows = table.rows
      self.dg_SEQ = new DsGrid<GameObject | number | null>(rows.length, _PROP_COUNT, 0)
      rows.forEach((r, i) => {
        for (let c = 0; c < 5; c++) self.dg_SEQ.set(i, c + 1, resolve(self, r[c] as string))
      })
      self.Targets_COUNT = self.dg_SEQ.width
      self.POINTS_MAX = self.Targets_COUNT
      const seq = self.dg_SEQ
      const num = (i: number, c: number) => seq.get(i, c) as number
      if (_CASE === 1) {
        // Each game attempt will be randomized: shuffle every column except the delays.
        for (let _i = 0; _i < _PROP_COUNT; _i++) {
          if (_i === _Delay_IDX) continue
          const _dl_RAND: number[] = []
          for (let _j = 0; _j < _SPAWN_COUNT; _j++) _dl_RAND.push(num(_j, _i))
          shuffle(_dl_RAND)
          for (let _j = 0; _j < _SPAWN_COUNT; _j++) seq.set(_j, _i, _dl_RAND[_j] as number)
        }
        // Attemping to make game less difficult: remove any delay smaller than DELAY_4
        for (let _i = 0; _i < self.Targets_COUNT; _i++)
          seq.set(_i, _Delay_IDX, Math.max(num(_i, _Delay_IDX), SYMS.DELAY_4 as number))
        // if 2 next to each other are same speed and dir, adjust one speed for variance
        const _val = 0x4
        for (let _i = 1; _i < self.Targets_COUNT; _i++) {
          if (num(_i, _Dir_IDX) === num(_i - 1, _Dir_IDX) && num(_i, _HSPD_IDX) === num(_i - 1, _HSPD_IDX)) {
            let v = num(_i, _HSPD_IDX) + _val * sign_(world.irandom(1))
            v = Math.min(Math.max(v, (SYMS.HSPD_1 as number) + _val), (SYMS.HSPD_5 as number) - _val)
            seq.set(_i, _HSPD_IDX, v)
          }
        }
        const _MAX = 0x4
        let _count = 0
        let _dir = num(0, _Dir_IDX)
        let _y = num(0, _Y_IDX)
        for (let _i = 1; _i < self.Targets_COUNT; _i++) {
          if (num(_i, _Dir_IDX) === _dir && num(_i, _Y_IDX) === _y) {
            _count++
            if (_count === _MAX) {
              _count = 0
              _i -= _MAX >> 1
              seq.set(_i, _Dir_IDX, -num(_i, _Dir_IDX))
              _i++
              _dir = num(_i, _Dir_IDX)
              _y = num(_i, _Y_IDX)
            }
          }
        }
        if (num(self.Targets_COUNT - 1, _HSPD_IDX) === SYMS.HSPD_1) {
          const pick = [SYMS.HSPD_3, SYMS.HSPD_4, SYMS.HSPD_5] as number[]
          seq.set(self.Targets_COUNT - 1, _HSPD_IDX, pick[world.irandom(2)] as number)
        }
      }
      break
    }
    case 2: {
      self.TARGET_OBJ = 'TargA'
      self.TARGET_VER = 2
      self.pc_allow = 0x13e
      // `MiniGameA_init.gml:3396-3612` — a fixed 0x20-row table written by explicit hex index. It was
      // never extracted, so `dg_SEQ` stayed 0 wide: `POINTS_MAX` was 0 and the heart-container water game
      // completed itself with 0 points the moment it started.
      self.dg_SEQ = new DsGrid<GameObject | number | null>(MINI_GAME_A_VER2.length, 6, 0)
      MINI_GAME_A_VER2.forEach((r, i) => {
        for (let c = 0; c < 5; c++) self.dg_SEQ.set(i, c + 1, resolveVer2(r[c] as string))
      })
      self.POINTS_MAX = self.dg_SEQ.width
      break
    }
    case 3:
      break
  }
}

function shuffle(a: number[]): void {
  for (let i = a.length - 1; i > 0; i--) {
    const j = world.irandom(i)
    const t = a[i] as number
    a[i] = a[j] as number
    a[j] = t
  }
}

export function MiniGameA_update(self: MiniGame_A): void {
  const player = pc()
  switch (self.sub_state) {
    // Waiting for PC to get in position
    case self.ST_SUB1_PRE1: {
      self.points = 0
      if (pc_is_fairy() || pc_is_cucco()) {
        gp().spells_active &= ~SPL_FARY
        const _DURATION = pp().SpellFlash_DURATION1 // $20. bit $80 mean flash bgr
        pp().Flash_Pal_timer = _DURATION
        pp().SpellFlash_PC_timer = _DURATION
      }
      if (!gmBool(player.ogr)) {
        set_xy(player, player.x, player.yb - (0x10 >> (pc_is_cucco() ? 1 : 0)))
        gp().pc_lock = PC_LOCK_ALL // Lock all
        self.sub_state = self.ST_SUB1_PRE2
      }
      break
    }
    // Adjusting PC into position
    case self.ST_SUB1_PRE2: {
      gp().pc_lock = PC_LOCK_ALL
      player.WalkTo_active = true
      player.WalkTo_x = self.PC_START_GAME_X
      player.WalkTo_hspd_max = player.HSPD_MAX1
      if (player.x === self.PC_START_GAME_X) {
        player.WalkTo_active = false
        player.hspd = 0
        player.attack_phase = 0
        gp().pc_lock = PC_LOCK_ALL ^ self.pc_allow
        set_camera_xy(self.x - viewW_(), viewYT()) // Center cam on game center
        gp().view_lock = 0x3 | gp().view_lock_rm
        self.timer = 1 // Delay game start sound
        self.sub_state = self.ST_SUB1_PRE3
      }
      break
    }
    // Waiting for start timer
    case self.ST_SUB1_PRE3: {
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      aud_play_sound(self.SND_GAME_START)
      goeHooks.audio_group_stop_all_mus()
      Audio.can_play_mus_rm_body = false
      Audio.can_play_boss_music = false
      self.timer = round(goeHooks.audioLengthFrames(self.SND_GAME_START)) + 2
      self.sub_state = self.ST_SUB1_PRE4
      break
    }
    // Waiting for enter battle sound to finish
    case self.ST_SUB1_PRE4: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer) && Audio.audio_is_playing(self.SND_GAME_START as string)) break
      self.timer = 0
      aud_play_sound(self.MUS_GAME_PLAY, Audio.PRIORITY_TOP, true, -1, self.MUS_GAME_THEME)
      self.tmr_next = self.DUR_DELAY_FIRST
      self.sub_state = self.ST_SUB1_PLY1
      break
    }
    // -------------- GAME TIME -----------------
    case self.ST_SUB1_PLY1: {
      self.points_can_draw = true
      if (gmBool(self.tmr_next)) {
        self.tmr_next--
        break
      }
      self.seq_idx++
      if (self.seq_idx < self.dg_SEQ.width) {
        const i = self.seq_idx
        const seq = self.dg_SEQ
        switch (self.ver) {
          case 1: {
            const _DIR = sign_(seq.get(i, 1) as number) // Target movement direction
            let _XL = viewXC()
            _XL += (viewW_() + (self.TARGET_W >> 1)) * -_DIR
            _XL -= self.TARGET_W >> 1
            _XL += _DIR
            const _YT = seq.get(i, 2) as number
            const _HSPD = seq.get(i, 3) as number
            const _VSPD = seq.get(i, 4) as number
            const t = GameObject_create(_XL, _YT, self.TARGET_OBJ, self.TARGET_VER, -1, GG().PI_MOB_PUR) as
              | (GameObjectC & TargetLike)
              | null
            seq.set(i, 0, t)
            if (t) {
              t.hspd = (_HSPD * _DIR) & 0xff
              t.vspd = _VSPD
              t.source_inst = self
              set_hspd_dir(t)
              t.hspd_dir_spawn = t.hspd_dir
              t.facing_dir = t.hspd_dir
              if (!t.dl_sprites?.size) t.dl_sprites?.add('spr_Moby1', 'spr_Moby2')
              t.TARGET_NUM = self.seq_idx + 1
            }
            break
          }
          case 2: {
            const _DIR = seq.get(i, 1) as number
            const _PAD = 5 // min tiles from pc
            let _XL = ((seq.get(i, 2) as number) + _PAD) << 3
            _XL = self.x + _XL * _DIR
            _XL -= 8
            const _YT = 0xd8
            const _HSPD = ((seq.get(i, 3) as number) * -_DIR) & 0xff
            const _VSPD = seq.get(i, 4) as number
            const t = GameObject_create(_XL, _YT, self.TARGET_OBJ, self.TARGET_VER) as
              | (GameObjectC & TargetLike)
              | null
            seq.set(i, 0, t)
            if (t) {
              t.hspd = _HSPD
              t.vspd = _VSPD
              t.source_inst = self
              set_hspd_dir(t)
              t.hspd_dir_spawn = t.hspd_dir
              t.facing_dir = t.hspd_dir
              t.dl_sprites?.set(1, 'spr_Bagin_1b')
              t.dl_sprites?.set(0, 'spr_Bagin_1a')
              t.TARGET_NUM = self.seq_idx + 1
            }
            break
          }
          case 3:
            break
        }
        self.tmr_next = seq.get(i, 5) as number
      } else {
        self.sub_state = self.ST_SUB1_PLY2
      }
      break
    }
    // All Targets spawned. Checking if game finished
    case self.ST_SUB1_PLY2: {
      self.points_can_draw = true
      for (let _i = self.dg_SEQ.width - 1; _i >= 0; _i--) {
        const _inst = self.dg_SEQ.get(_i, 0) as TargetLike | number | null
        if (
          typeof _inst !== 'number' &&
          instanceExists(_inst) &&
          !gmBool(_inst.target_hit) &&
          isVal(_inst.behavior, _inst.BVR_STRT, _inst.BVR_VULN)
        ) {
          return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
        }
      }
      self.timer = 8 // Delay game done sound
      self.sub_state = self.ST_SUB1_PST1
      break
    }
    // Game finished
    case self.ST_SUB1_PST1: {
      self.points_can_draw = true
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      aud_play_sound(self.SND_GAME_DONE)
      aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
      goeHooks.audio_group_stop_all_mus()
      self.timer = round(goeHooks.audioLengthFrames(self.SND_GAME_DONE)) + 2
      self.sub_state = self.ST_SUB1_PST2
      break
    }
    case self.ST_SUB1_PST2: {
      self.points_can_draw = true
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer) && Audio.audio_is_playing(self.SND_GAME_DONE as string)) break
      self.timer = 0x10 // 0.267s Let rm music play some before opening dlg
      self.sub_state = self.ST_SUB1_PST3
      break
    }
    // Delay restart rm music
    case self.ST_SUB1_PST3: {
      self.points_can_draw = true
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      Audio.can_play_mus_rm_body = true
      self.timer = 4 // Give chance for dlg to open
      self.sub_state = self.ST_SUB1_NPC1 // will trigger npc to open dlg
      break
    }
    // Result dlg
    case self.ST_SUB1_NPC1: {
      self.points_can_draw = true
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      if (gp().gui_state === gp().gui_state_NONE) self.sub_state = self.ST_SUB1_END1
      break
    }
    // Clean up
    case self.ST_SUB1_END1: {
      for (const t of instancesNamed('Target')) {
        t.state = 0
        if (gmBool(gp().mod_destroy_go_on_death) && !gmBool(t.state)) GO_destroy_1a(t)
      }
      gp().view_lock &= ~0x3
      gp().view_lock |= gp().view_lock_rm
      gp().pc_lock = 0
      self.state = 0
      self.destroy() // bc is Challege obj
      break
    }
  }
}

export function MiniGameA_draw(self: MiniGame_A): void {
  if (gmBool(self.points_can_draw)) {
    self.points_can_draw = false
    let _TEXT = String(self.points)
    if (self.points < 10) _TEXT = `0${_TEXT}`
    const _X = self.x - ((_TEXT.length << 3) >> 1)
    const _Y = viewYT() + self.POINTS_Y_OFF
    draw_text_(_X, _Y, _TEXT)
  }
  // Debug draw
  if (gp().TargetGame_case > 1) {
    for (const t of instancesNamed<TargetLike>('Target')) {
      let _text = String(t.TARGET_NUM)
      if (t.TARGET_NUM < 10) _text = `0${_text}`
      draw_text_(t.x - 8, t.yt - 9, _text)
    }
  }
  goeHooks.GO_draw_body_hb(self)
}

export function MiniGame_end(self: MiniGame_A): void {
  self.dl_SEQ.clear()
  self.dg_SEQ = new DsGrid<GameObject | number | null>(0, 6, 0)
}
