/**
 * App window — ported from `update_game_window_1a`, `window_set_scale`, `window_get_scale`,
 * `window_set_position_`, `draw_view_og_outline`. The core keeps the window model in `windowState`
 * (the adapter injects the display size with `setDisplaySize()` and applies `windowState` each frame);
 * GM's `window_*` builtins are the functions below.
 */
import { BASE_GAME_RESOLUTION_H, BASE_GAME_RESOLUTION_W, VIEW_H_OG, VIEW_W_OG } from '@z2/data'
import { gmBool, gmRound as round } from '../../nes/math8'
import { G, g, input } from '../../runtime/world'
import { save_game_pref } from '../file/prefs'
import { bit_dir, sign_ } from '../math/index'
import { gui_tmr_cursor_h, gui_tmr_cursor_v } from '../rooms/deps'
import { draw_rect_ } from '../rooms/draw'
import { C_AQUA } from './colors'

export const windowState = {
  width: BASE_GAME_RESOLUTION_W,
  height: BASE_GAME_RESOLUTION_H,
  x: 0,
  y: 0,
  fullscreen: false,
  /** GM `show_debug_overlay(bool)` — the adapter may render an FPS/debug overlay when true. */
  debugOverlay: false,
  /** true = `cr_none` */
  cursorHidden: false,
  display: { w: 1920, h: 1080 },
}
export function setDisplaySize(w: number, h: number): void {
  windowState.display.w = w
  windowState.display.h = h
}
export const window_get_width = () => windowState.width
export const window_get_height = () => windowState.height
export const window_get_x = () => windowState.x
export const window_get_y = () => windowState.y
export const window_get_fullscreen = () => windowState.fullscreen
export const window_set_fullscreen = (v: boolean) => {
  windowState.fullscreen = v
}
export const window_set_size = (w: number, h: number) => {
  windowState.width = w
  windowState.height = h
}
export const window_set_position = (x: number, y: number) => {
  windowState.x = x
  windowState.y = y
}
export const display_get_width = () => windowState.display.w
export const display_get_height = () => windowState.display.h

/** `window_get_scale()` */
export function window_get_scale(): number {
  return window_get_width() / g.VIEW_W
}

/** `window_set_scale(scale)` — returns true if the scale changed. */
export function window_set_scale(scale: number): boolean {
  let _scale = Math.max(g.WindowScale_MIN, Math.abs(round(scale)))
  // Allow room for Windows border
  if (
    BASE_GAME_RESOLUTION_W * _scale > display_get_width() - g.WINDOW_PAD ||
    BASE_GAME_RESOLUTION_H * _scale > display_get_height() - g.WINDOW_PAD
  ) {
    _scale = Math.max(g.WindowScale_MIN, _scale - 1)
  }
  if (window_get_scale() !== _scale) {
    // if requested scale != current scale
    g.WindowScale_scale = _scale
    window_set_size(BASE_GAME_RESOLUTION_W * _scale, BASE_GAME_RESOLUTION_H * _scale)
    return true
  }
  return false
}

/** `window_set_position_(left x, top y)` */
export function window_set_position_(left: number, top: number): void {
  window_set_position(
    clamp(left, g.WINDOW_PAD, display_get_width() - window_get_width()),
    clamp(top, g.WINDOW_PAD, display_get_height() - window_get_height()),
  )
  g.window_center_x = window_get_x() + (window_get_width() >> 1)
  g.window_center_y = window_get_y() + (window_get_height() >> 1)
}

const clamp = (v: number, lo: number, hi: number) => Math.min(Math.max(v, lo), hi)

/** Seams for scripts outside this folder (gui cursor timers, room warper dev tool). */
export const windowDeps = {
  gui_tmr_cursor_v: (): number => gui_tmr_cursor_v(),
  gui_tmr_cursor_h: (): number => gui_tmr_cursor_h(),
  /** `Dev_RmWarper.state==Dev_RmWarper.STATE_IDLE` */
  rmWarperIdle: (): boolean => true,
}

/** `update_game_window_1a()` — cursor, positioning, fullscreen toggle, scaling. */
export function update_game_window_1a(): void {
  switch (g.MouseCursor_HideVer) {
    case 1: // Always hide
      windowState.cursorHidden = true
      break
    case 2: // Hide for fullscreen only
      windowState.cursorHidden = window_get_fullscreen()
      break
    default: // Never hide
      windowState.cursorHidden = false
      break
  }
  // ----------------------------------------------------------------------------------------
  //  POSITIONING  -----------------------------------------------------------------------
  if (!window_get_fullscreen()) {
    const _WINDOW_W = window_get_width()
    const _WINDOW_H = window_get_height()
    if (g.Fullscreen_toggled || g.WindowScale_changed) {
      if (
        window_get_x() + (_WINDOW_W >> 1) !== g.window_center_x ||
        window_get_y() + (_WINDOW_H >> 1) !== g.window_center_y
      ) {
        window_set_position_(g.window_center_x - (_WINDOW_W >> 1), g.window_center_y - (_WINDOW_H >> 1))
      }
    } else {
      // Track g.window_center_x/y if window has been moved/dragged
      // and so toggling fullscreen doesn't re-center the window.
      if (
        g.window_center_x !== window_get_x() + (_WINDOW_W >> 1) ||
        g.window_center_y !== window_get_y() + (_WINDOW_H >> 1)
      ) {
        g.window_center_x = window_get_x() + (_WINDOW_W >> 1)
        g.window_center_y = window_get_y() + (_WINDOW_H >> 1)
      }
    }
  }
  // ----------------------------------------------------------------------------------------
  if (g.Fullscreen_toggled || g.WindowScale_changed) {
    g.Fullscreen_toggled = false
    g.WindowScale_changed = false
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // ----------------------------------------------------------------------------------------
  //  FULLSCREEN  --------------------------------------------------------------------
  let _will_toggle_fullscreen = false
  const keypressedPrev = (input as unknown as { keypressed_prev?: number }).keypressed_prev ?? 0
  if (
    keypressedPrev === 0 &&
    (input.keyboard_check_pressed(g.Fullscreen_KEY) ||
      (input.keyboard_check_pressed('vk_escape') && window_get_fullscreen()))
  ) {
    if (input.keyboard_check_pressed('vk_escape')) {
      // As of 2025/06/11, the following app states will close with `vk_escape`
      if (
        !g.app_paused &&
        g.gui_state !== g.gui_state_OPTIONS &&
        g.gui_state !== g.gui_state_QUIT_APP &&
        g.gui_state !== g.gui_state_EDIT_PAL &&
        g.gui_state !== g.gui_state_GEE &&
        windowDeps.rmWarperIdle()
      ) {
        _will_toggle_fullscreen = true
      }
    } else {
      _will_toggle_fullscreen = true
    }
  }
  const om = G.OPTIONS_MENU
  if (!_will_toggle_fullscreen) {
    if (
      g.gui_state === g.gui_state_OPTIONS &&
      om?.menu_state === om?.menu_state_MAIN &&
      om?.MainOption === om?.MainOption_FULLSCREEN &&
      !Math.abs(bit_dir(windowDeps.gui_tmr_cursor_v()))
    ) {
      if (
        gmBool(input.Jump_pressed) ||
        gmBool(input.Pause_pressed) ||
        input.keyboard_check_pressed('vk_enter') ||
        input.keyboard_check_pressed('vk_space') ||
        Math.abs(bit_dir(windowDeps.gui_tmr_cursor_h()))
      ) {
        _will_toggle_fullscreen = true
      }
    }
  }
  if (_will_toggle_fullscreen) {
    g.Fullscreen_toggled = true
    window_set_fullscreen(!window_get_fullscreen()) // Toggle fullscreen
    if (!window_get_fullscreen()) g.WindowScale_changed = window_set_scale(g.WindowScale_scale)
    save_game_pref()
  }
  // ----------------------------------------------------------------------------------------
  //  SCALING  -----------------------------------------------------------------------
  if (!_will_toggle_fullscreen) {
    let _SCALE_DIR = 0
    if (input.keyboard_check('vk_control') && input.keyboard_check_pressed(g.WindowScale_KEY)) {
      _SCALE_DIR = sign_(!input.keyboard_check('vk_shift'))
    } else if (
      g.gui_state === g.gui_state_OPTIONS &&
      om?.menu_state === om?.menu_state_MAIN &&
      om?.MainOption === om?.MainOption_APP_SCALE &&
      !Math.abs(bit_dir(windowDeps.gui_tmr_cursor_v()))
    ) {
      _SCALE_DIR = bit_dir(windowDeps.gui_tmr_cursor_h())
    }
    if (_SCALE_DIR !== 0) {
      // scale window
      if (window_set_scale(window_get_scale() + _SCALE_DIR)) {
        // if scale changed
        g.WindowScale_changed = true // For positioning the window on the NEXT frame
        window_set_fullscreen(false)
        save_game_pref()
      }
    }
  }
}

/** `draw_view_og_outline()` — toggle with 'L'. Outline representing the og camera. */
export function draw_view_og_outline(): void {
  if (!g.can_draw_og_cam_outline) return
  draw_rect_(C_AQUA, g.view_xl_og, g.view_yt_og, VIEW_W_OG, VIEW_H_OG, 1, true)
}
