/**
 * Overworld tile refresh/changes and the water sparkle tables — ported from `Overworld_refresh_tiles.gml`,
 * `Overworld_tile_change_1a/2a/3.gml`, `WaterSparkle_refresh.gml`, `WaterSparkle_get_new_rc.gml`.
 * Tiles go through the core `TileWorld` (`game/tile`), depth `Tile_DEPTH1` (main overworld layer) and the
 * two anarkhya layers.
 */
import {
  ITM_BOOT,
  TSRC_GRAS01,
  TSRC_GRAS02,
  TSRC_GRAS03,
  TSRC_GRAS04,
  TSRC_SWAM01,
  TSRC_SWAM02,
  TSRC_SWAM03,
  TSRC_SWAM04,
  TSRC_TREE01,
  TSRC_TREE02,
  TSRC_TREE03,
  TSRC_TREE04,
  TSRC_VOLC01,
} from '@z2/data'
import { gmBool } from '../../nes/math8'
import { f, g, world } from '../../runtime/world'
import { is_in_grid } from '../collision/geometry'
import { hex_str } from '../other'
import {
  tile_change_2a,
  tile_change_3a,
  tile_delete_,
  tile_exists,
  tile_layer_delete,
  tile_layer_delete_,
  tile_set_scale,
} from '../tile'
import { shuffleInPlace } from './deps'
import type { Overworld } from './Overworld'

/** `Overworld_refresh_tiles(ow x, ow y)` — (re)build the visible DRAW_CLMS×DRAW_ROWS tile window. */
export function Overworld_refresh_tiles(self: Overworld, owX: number, owY: number): void {
  const SHIFT = self.SHIFT
  if (g.anarkhyaOverworld_MAIN && g.anarkhyaOverworld_enabled) {
    tile_layer_delete(self.anarkhya_TILE_DEPTH1)
    tile_layer_delete(self.anarkhya_TILE_DEPTH2)
    // each row
    for (let _i = 0; _i < self.DRAW_ROWS; _i++) {
      // each clm
      for (let _j = 0; _j < self.DRAW_CLMS; _j++) {
        const _x = _j << SHIFT
        const _y = _i << SHIFT
        const _ow_clm = (owX + _x) >> SHIFT
        const _ow_row = (owY + _y) >> SHIFT
        // MAIN layer
        let _tile_data = self.dg_anarkhya_tsrc.get(_ow_clm, _ow_row) ?? 0
        if (_tile_data !== 0) Overworld_tile_change_3(self, _tile_data, _x, _y, self.anarkhya_TILE_DEPTH1, 0)
        // DETAILS layer
        _tile_data = self.dg_anarkhya_tsrc_detail.get(_ow_clm, _ow_row) ?? 0
        if (_tile_data !== 0) Overworld_tile_change_3(self, _tile_data, _x, _y, self.anarkhya_TILE_DEPTH2, 0)
      }
    }
  } else {
    tile_layer_delete_(self.Tile_DEPTH1)
    // each row
    for (let _i = 0; _i < self.DRAW_ROWS; _i++) {
      // each clm
      for (let _j = 0; _j < self.DRAW_CLMS; _j++) {
        let _x = _j << SHIFT
        let _y = _i << SHIFT
        const _ow_clm = (owX + _x) >> SHIFT
        const _ow_row = (owY + _y) >> SHIFT
        let _scale_x = 1
        let _scale_y = 1
        let _tile_data = self.dg_tsrc.get(_ow_clm, _ow_row) ?? 0
        if (self.RandoTSRC_active) {
          const _val = self.dm_Rando_TSRC.get(hex_str(_tile_data))
          if (_val !== undefined) _tile_data = ((_val as number) >> 2) << 2
        }
        const _tsrc0 = _tile_data & 0xff
        if (g._YxY_) {
          if (
            _tsrc0 === TSRC_TREE01 ||
            _tsrc0 === TSRC_TREE02 ||
            _tsrc0 === TSRC_TREE03 ||
            _tsrc0 === TSRC_TREE04 ||
            _tsrc0 === TSRC_GRAS01 ||
            _tsrc0 === TSRC_GRAS02 ||
            _tsrc0 === TSRC_GRAS03 ||
            _tsrc0 === TSRC_GRAS04 ||
            _tsrc0 === TSRC_SWAM01 ||
            _tsrc0 === TSRC_SWAM02 ||
            _tsrc0 === TSRC_SWAM03 ||
            _tsrc0 === TSRC_SWAM04 ||
            _tsrc0 === TSRC_VOLC01
          ) {
            if (world.irandom(1)) {
              _scale_x = -1
              _x += 0x01 << SHIFT
            }
            if (world.irandom(1)) {
              _scale_y = -1
              _y += 0x01 << SHIFT
            }
          }
        }
        const _ts = g.dl_tileset.get((_tile_data >> 8) & 0xff) as string
        const _tid = tile_change_2a(self.T_SIZE, _ts, _tsrc0, _x, _y, self.Tile_DEPTH1, 0)
        self.dg_tid.set(_j, _i, _tid)
        if (tile_exists(_tid)) tile_set_scale(_tid, _scale_x, _scale_y)
      }
    }
  }
}

/** `Overworld_tile_change_1a(rm clm, rm row, ow clm, ow row, tsrc, *solid)` — change one overworld tile. */
export function Overworld_tile_change_1a(
  self: Overworld,
  _RM_CLM: number,
  _RM_ROW: number,
  _OW_CLM: number,
  _OW_ROW: number,
  _TSRC: number,
  solid = 0,
): number {
  //               rm clm      rm row
  if (!is_in_grid(_RM_CLM, _RM_ROW, self.DRAW_CLMS, self.DRAW_ROWS)) return 0
  const _SOLID = gmBool(solid) ? solid : 0
  self.dg_tsrc.set(_OW_CLM, _OW_ROW, _TSRC)
  self.dg_solid.set(_OW_CLM, _OW_ROW, _SOLID)
  const _X = _RM_CLM << self.SHIFT
  const _Y = _RM_ROW << self.SHIFT
  let _tid = self.dg_tid.get(_RM_CLM, _RM_ROW) ?? -1
  tile_delete_(_tid)
  _tid = tile_change_2a(
    self.T_SIZE,
    g.dl_tileset.get((_TSRC >> 8) & 0xff) as string,
    _TSRC,
    _X,
    _Y,
    self.Tile_DEPTH1,
    0,
  )
  self.dg_tid.set(_RM_CLM, _RM_ROW, _tid)
  return _tid
}

/** `Overworld_tile_change_2a(change type)` — apply a tile-change event to the overworld grids. */
export function Overworld_tile_change_2a(self: Overworld, changeType: string): void {
  switch (changeType) {
    case self.TileChangeEvent_TYPE_BOOT1: {
      for (let _i = self.dg_ChangeTiles_Boots.width - 1; _i >= 0; _i--) {
        const owrc = self.dg_ChangeTiles_Boots.get(_i, 0) as number
        const _clm = (owrc >> 0) & 0xff
        const _row = (owrc >> 8) & 0xff
        self.dg_solid.set(_clm, _row, self.dg_ChangeTiles_Boots.get(_i, 1) as number)
        self.dg_tsrc.set(_clm, _row, self.dg_ChangeTiles_Boots.get(_i, 2) as number)
      }
      break
    } //case TileChangeEvent_TYPE_BOOT1:{
  }
}

/** `Overworld_tile_change_3(tile data, x, y, depth, 1:add -1:delete 0:both)` — anarkhya layers (Tiled gids incl. flip bits). */
export function Overworld_tile_change_3(
  self: Overworld,
  _TILE_DATA: number,
  x: number,
  y: number,
  _DEPTH: number,
  _CHANGE: number,
): void {
  let _X = x
  let _Y = y
  let _SCALE_X = 1
  if (_TILE_DATA & 0x80000000) _SCALE_X = -1
  if (!gmBool(_SCALE_X)) _X += self.T_SIZE
  let _SCALE_Y = 1
  if (_TILE_DATA & 0x40000000) _SCALE_Y = -1
  if (!gmBool(_SCALE_Y)) _Y += self.T_SIZE
  let _tsrc = _TILE_DATA - 1 // Tiled app adds 1 so it can't be 0
  _tsrc &= 0x3fffffff // truncate the scale xy data
  _tsrc = Math.abs(_tsrc)
  let _TS: string
  switch ((_tsrc >> 8) & 0xff) {
    case 0:
      _TS = 'ts_Overworld_anark02'
      break
    case 1:
      _TS = 'ts_Overworld_anark01'
      break
    case 2:
      _TS = 'ts_OverworldAnim01'
      break
    default:
      _TS = 'ts_Overworld_anark01'
      break
  }
  _tsrc &= 0xff
  const _TILE_ID = tile_change_3a(self.T_SIZE, _TS, _tsrc, _X, _Y, _DEPTH, _CHANGE)
  if (tile_exists(_TILE_ID)) tile_set_scale(_TILE_ID, _SCALE_X, _SCALE_Y)
}

/** `WaterSparkle_refresh(pcrc)` — pick this cycle's sparkle pixels around the PC (BOOTS only). */
export function WaterSparkle_refresh(self: Overworld, _PCRC: number): void {
  for (const row of self.dg_WaterSparkle.cells) row.fill(-1)
  self.WaterSparkle_timer = 0
  if (!(f.items & ITM_BOOT)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const _dl1 = [...self.dl_WaterSparkle_RC.items]
  const _dl2 = [0x00, 0x08, 0x80, 0x88]
  for (let _i = self.dg_WaterSparkle.width - 1; _i >= 0; _i--) {
    let _owrc: number
    switch (_i) {
      case 1:
        _owrc = _PCRC + 1 // east  of pc (right)
        break
      case 2:
        _owrc = _PCRC - 1 // west  of pc (left)
        break
      case 3:
        _owrc = _PCRC + self.OW_CLMS // south of pc (down)
        break
      case 4:
        _owrc = _PCRC - self.OW_CLMS // north of pc (up)
        break
      default:
        _owrc = _PCRC // pc's tile
        break
    }
    if (_owrc >= 0 && _owrc < self.OW_CLMS * self.OW_ROWS) {
      const _ow_clm = (_owrc >> 0) & 0xff
      const _ow_row = (_owrc >> 8) & 0xff
      const _tsrc = (self.dg_tsrc.get(_ow_clm, _ow_row) ?? 0) & 0xff
      if (_tsrc === self.TSRC_WATER01 && !gmBool(self.dg_solid.get(_ow_clm, _ow_row))) {
        shuffleInPlace(_dl1) // sparkle pixel rc w/in an 8x8 area
        shuffleInPlace(_dl2) // offset to determine the sparkle pixel's overworld tile quadrant
        self.dg_WaterSparkle.set(_i, 0, _owrc)
        // pixel rc w/in its overworld tile
        self.dg_WaterSparkle.set(_i, 1, (_dl1[0] as number) + (_dl2[0] as number))
        self.dg_WaterSparkle.set(_i, 2, (_dl1[1] as number) + (_dl2[1] as number))
        self.dg_WaterSparkle.set(_i, 3, (_dl1[2] as number) + (_dl2[2] as number))
        self.dg_WaterSparkle.set(_i, 4, (_dl1[3] as number) + (_dl2[3] as number))
        self.WaterSparkle_timer = self.WaterSparkle_DURATION0
      }
    }
  }
}

/** `WaterSparkle_get_new_rc()` — four sparkle pixel positions packed into one 32-bit value. */
export function WaterSparkle_get_new_rc(self: Overworld): number {
  const _dl_RC = shuffleInPlace([...self.dl_WaterSparkle_RC2.items])
  let _return = 0x00
  _return |= ((_dl_RC[0] as number) + 0x00) << 0x00
  _return |= ((_dl_RC[1] as number) + 0x08) << 0x08
  _return |= ((_dl_RC[2] as number) + 0x80) << 0x10
  _return |= ((_dl_RC[3] as number) + 0x88) << 0x18
  return _return
}
