// Ported from ZALiA scripts/update_cast_spell.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively
import { PC_LOCK_SPEL } from '@z2/data'
import { gmBool } from '../../nes/math8'
import { f, G, g, input } from '../../runtime/world'
import { adjust_stat } from '../file/stats'
import { notPorted } from '../pending'
import { cast_spell } from './cast_spell'
import { get_spell_cost } from './get_spell_cost'
import { min } from './gm'

/** GML: update_cast_spell() */
export function update_cast_spell() {
  // GML `var` is function-scoped; locals hoisted here:
  let _COST: any
  // D3EC: JSR 8DC3.  cast spell, spell effects, spellFlashTimer
  if (
    gmBool(input.Magic_pressed) &&
    gmBool(f.spells & g.spell_ready) &&
    gmBool(G.pc.state) &&
    !gmBool(g.pc_lock & PC_LOCK_SPEL)
  ) {
    // ---------  A SPELL WAS REQUESTED THIS FRAME  ---------------------
    _COST = get_spell_cost(g.spell_ready)
    if (f.mp - _COST >= 0) {
      adjust_stat(0, -min(f.mp, _COST))
      cast_spell(g.spell_ready)
    }
  }
}
