/** `PC_create(object_index, x, y)` — creates the player, sets `global.pc`, runs `PC_init`. */
import { G, world } from '../../../runtime/world'
import { installInstanceEnd } from '../go/lifecycle'
import { installPcCollisionEnv } from './collisionEnv'
import { Lonk } from './Lonk'
import { PC_init } from './PC_init'

export function PC_create(_obj: string, x: number, y: number): Lonk {
  const inst = new Lonk()
  inst.x = x
  inst.y = y
  world.register(inst)
  installInstanceEnd(inst)
  G.pc = inst
  PC_init(inst)
  installPcCollisionEnv()
  return inst
}
