// Ported from ZALiA scripts: Ganon_init_1, Ganon_update_xy (generated by boss/_port/convert.py, then hand-finished).
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML state, typed progressively
// biome-ignore-all lint/correctness/noConstantCondition: GML `if (1)` blocks kept as written
// biome-ignore-all lint/correctness/noUnreachable: GML code after exit/return kept for fidelity review

import { dk_WalkWater } from '@z2/data'
import { gmBool } from '../../../../../nes/math8'
import { G, g } from '../../../../../runtime/world'
import { sprite_get_height, sprite_get_width } from '../../../../graphics/sprites'
import { get_audio_theme_track } from '../../../../sound/theme'
import { updateX, updateY } from '../../../go/movement'
import { resolveScript } from '../../../registry'
import { Boss_init_1, BossObject } from './BossObject'

export abstract class Ganon extends BossObject {
  CrystalAura_PI: any = undefined
  CrystalAura_SPRITE: any = undefined
  CrystalAura_pi: any = undefined
  CrystalSlot_SPRITE: any = undefined
  Crystal_PI: any = undefined
  Crystal_SPRITE1: any = undefined
  Crystal_SPRITE2: any = undefined
  Crystal_can_draw: any = undefined
  Crystal_fade_state: any = undefined
  Crystal_pi: any = undefined
  Crystal_position: any = undefined
  Crystal_sprite: any = undefined
  Crystal_sprite_state: any = undefined
  Crystal_state: any = undefined
  Crystal_timer: any = undefined
  Crystal_x: any = undefined
  Crystal_xoff: any = undefined
  Crystal_y: any = undefined
  Crystal_yoff: any = undefined
  Jump_SOUND1: any = undefined
  Jump_SOUND2: any = undefined
  PALIDX1: any = undefined
  PALIDX2: any = undefined
  Slime_H_: any = undefined
  Slime_W_: any = undefined
  off_ground_reason: any = undefined
  timer1: any = undefined
  timer2: any = undefined
  timerA: any = undefined
  x_prev: any = undefined
  y_prev: any = undefined
}

/** GML: Ganon_init_1() */
export function Ganon_init_1(self: any) {
  let _i: any, _a: any

  Boss_init_1(self)
  self.can_draw_self_exception = true
  self.off_ground_reason = 0
  self.Slime_W_ = sprite_get_width(g.Ganon3_SPRITE1) >> 1
  self.Slime_H_ = sprite_get_height(g.Ganon3_SPRITE1) >> 1
  self.PALIDX1 = G.PI_BGR4
  self.PALIDX2 = G.PI_MOB_RED
  self.timer1 = 0
  self.timer2 = 0
  self.timerA = 0
  self.x_prev = self.x
  self.y_prev = self.y
  self.Crystal_sprite_state = 0 // 0: can't draw, 1: empty spr, 2: full, 3: full & flashing spr
  self.Crystal_fade_state = 0 // 0: Opaque, 1: Fade In, 2: Fade Out,
  self.Crystal_state = 0 // 0: dead, 1: normal
  self.Crystal_position = 0 // 0: home, 1: attack1, 2: attack2, 3: attack3
  self.Crystal_timer = 0
  self.Crystal_can_draw = true
  self.Crystal_SPRITE1 = 'spr_Crystal_1b' // empty/clear
  self.Crystal_SPRITE2 = 'spr_Crystal_1a' // colored & flashing
  self.Crystal_sprite = self.Crystal_SPRITE1
  self.Crystal_PI = G.PI_MOB_RED
  self.Crystal_pi = self.Crystal_PI
  self.Crystal_xoff = 0
  self.Crystal_yoff = 0
  self.Crystal_x = self.x
  self.Crystal_y = self.y
  self.CrystalAura_SPRITE = 'spr_Aura_2a_WRB'
  self.CrystalAura_PI = G.PI_MOB_ORG
  self.CrystalAura_pi = self.CrystalAura_PI
  self.CrystalSlot_SPRITE = 'spr_Stone_Crystal_Slot_1a'
  self.Jump_SOUND1 = get_audio_theme_track(`${dk_WalkWater}01`) // A: lower pitched than B
  self.Jump_SOUND2 = get_audio_theme_track(`${dk_WalkWater}02`) // B: higher pitched than A
}

/** GML: Ganon_update_xy() */
export function Ganon_update_xy(self: any) {
  // if not colliding wall
  // FIXED: GML runs `Ganon3_update_battle_2a()` in the caller's scope — the instance must be passed
  if (!gmBool((resolveScript('Ganon3_update_battle_2a') as (s: unknown) => unknown)(self))) {
    updateX(self)
  }
  updateY(self)
  //
}
