/**
 * `Overworld_init_data_1()` — the Tiled overworld parser: builds `dm`, the `dg_*` grids and the
 * `g.dm_rm` scene↔overworld links from `OvrwA_00.json` (`world.maps`). In ZALiA this script also
 * printed the pre-baked code / wrote `OverworldData01.txt` (`_C0`/`_C1` branches, `sdm(...)`); those
 * side effects are dropped — the structures are filled directly, which is what method 1 did.
 * Used by tests to prove the shipped cache and the parser agree.
 */
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML state
import {
  Area_OvrwA,
  AreaID_LEN,
  dk_NO_ENCOUNTER,
  dk_RauruPass,
  MapAreaName_DEF,
  RmName_LEN,
  STR_AccessOw,
  STR_AccessRm,
  STR_BG,
  STR_Biome,
  STR_Boulder,
  STR_Circle,
  STR_Clm,
  STR_Clms,
  STR_Count,
  STR_CutScene,
  STR_Default,
  STR_Encounter,
  STR_Exit,
  STR_Fast,
  STR_Forest,
  STR_goto_reen,
  STR_Hammer,
  STR_Height,
  STR_Info,
  STR_Monster,
  STR_Num,
  STR_Open,
  STR_OWRC,
  STR_ow_dir,
  STR_Palace,
  STR_Raft,
  STR_Rando,
  STR_Rauru,
  STR_River_Devil,
  STR_RmName,
  STR_Row,
  STR_Rows,
  STR_Scene,
  STR_Solid,
  STR_Special,
  STR_State,
  STR_Tile,
  STR_Town,
  STR_Travel,
  STR_TSRC,
  STR_Under,
  STR_undefined,
  STR_Width,
  TSRC_PATH02,
} from '@z2/data'
import type { TiledMap, TiledObject, TiledProperty, TiledTileLayer } from '../../runtime/tiled'
import { G, g, world } from '../../runtime/world'
import { sign_ } from '../math'
import { hex_str, sdm, str_hex, strR, val } from '../other'
import { string_count, string_lettersdigits } from './deps'
import { gridClear, gridCopy, gridResize, gridSetRegion, type Overworld } from './Overworld'

// NOTE: 19 characters(including spaces) fits, but is tight.
// Therefore, 18 characters will be the limit.
export const OW_AREA_NAMES: readonly string[] = [
  'NORTH CASTLE FIELD',
  'NORTH CASTLE WOODS', // 18 characters
  'NORTH CASTLE LAKE',
  'RAURU WOODS',
  'TANTARI DESERT',
  'PARAPA DESERT',
  'RUTO MOUNTAINS',
  'SARIA FIELD',
  'SARIA WOODS',
  'SARIA BAY',
  'SARIA CEMETERY',
  'MORUGE SWAMP',
  'MIDORO FIELD',
  'MIDORO SWAMP',
  'ROYAL CEMETERY',
  'DEATH MOUNTAIN',
  'NABOORU FIELD',
  'NABOORU BAY',
  'DARUNIA FIELD',
  'DARUNIA FOREST',
  'DARUNIA MOUNTAINS',
  'KASUTO CEMETERY',
  'KASUTO FOREST',
  'KASUTO SWAMP',
  'SEASHORE',
  'VALLEY OF DEATH',
  'MAZE ISLAND',
  'WHALE ISLAND',
  'SARIA RIVER',
  'NABOORU WOODS',
  'MAKARRHA',
  'DRAGMIRE', // DRAGMIRE A
  'DRAGMIRE', // DRAGMIRE B (Island behind Dragmire)
  MapAreaName_DEF,
]

const propsOf = (props: TiledProperty[] | undefined): Map<string, any> => {
  const m = new Map<string, any>()
  if (props) for (const p of props) m.set(p.name, p.value)
  return m
}

/** `Overworld_init_data_1()` on the Tiled map `stem` (default `OvrwA_00`). Returns false if the map is missing. */
export function Overworld_init_data_1(self: Overworld, stem = 'OvrwA_00'): boolean {
  const _dm_Tiled_file_data: TiledMap | undefined = world.maps.get(stem)
  if (!_dm_Tiled_file_data) {
    sdm(
      `!!!! WARNING! Overworld_init_data_1(). \`_dm_Tiled_file_data\` failed to get data from 'ow_tile_data/${stem}.json' !!!!`,
    )
    return false // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  const dm = self.dm
  const SHIFT = self.SHIFT
  const _STR_IDX = '_idx'
  const _STR_NAME = '_name'
  const _dm_ts_info = new Map<string, any>()
  const _STR_AREA = 'AREA'
  const _dl_AreaNames = OW_AREA_NAMES
  let _tsrc0 = 0
  // --------------------------------------------------------------
  self.OW_CLMS = _dm_Tiled_file_data.width
  self.OW_ROWS = _dm_Tiled_file_data.height
  self.OW_W = self.OW_CLMS << SHIFT
  self.OW_H = self.OW_ROWS << SHIFT
  // --------------------------------------------------------------
  // Get tileset info
  const _dl_ts_data = _dm_Tiled_file_data.tilesets
  for (let _i = 0; _i < _dl_ts_data.length; _i++) {
    const tsRef = _dl_ts_data[_i] as { name?: string; source?: string; firstgid: number }
    // "source" Example: "..\/..\/..\/Tilesets\/Z2_Remake_1a\/ts_Overworld_1a.tsx" — the asset pipeline
    // already normalised it to a bare `name`; fall back to scanning the path like the GML did.
    let _name = tsRef.name ?? ''
    if (!_name && tsRef.source) {
      const _str = tsRef.source
      for (let _j = _str.length; _j >= 1; _j--) {
        if (_str.charAt(_j - 1) !== '/') continue
        _name = _str.substr(_j, _str.length - _j - 4) // (- 4): truncates the file ext
        break
      }
    }
    let _ts = val(g.dm_tileset.get(_name)) as string | 0
    if (!_ts) {
      _ts = self.TILESET1
      _name = _ts
    }
    _dm_ts_info.set(hex_str(_i) + _STR_NAME, _name) // ts name
    _dm_ts_info.set(hex_str(_i) + _STR_IDX, _ts) // ts index
  }
  // --------------------------------------------------------------
  gridResize(self.dg_tsrc_def, self.OW_CLMS, self.OW_ROWS)
  gridClear(self.dg_tsrc_def, self.TSRC_WATER01)
  gridCopy(self.dg_tsrc, self.dg_tsrc_def)
  gridResize(self.dg_solid_def, self.OW_CLMS, self.OW_ROWS)
  gridClear(self.dg_solid_def, 0)
  gridCopy(self.dg_solid, self.dg_solid_def)
  gridResize(self.dg_area, self.OW_CLMS, self.OW_ROWS)
  gridClear(self.dg_area, -1)
  gridResize(self.dg_AreaNames, self.OW_CLMS, self.OW_ROWS)
  gridClear(self.dg_AreaNames, MapAreaName_DEF)
  gridResize(self.HiddenExitIndicator_dg, 0, self.HiddenExitIndicator_dg.height)
  gridClear(self.HiddenExitIndicator_dg, 0)
  gridResize(self.dg_ChangeTiles_Boots, 0, self.dg_ChangeTiles_Boots.height)
  gridResize(self.dg_boulders, 0, self.dg_boulders.height)
  const _dg_tsrcub: [number, number][] = []
  // each layer
  for (const layer of _dm_Tiled_file_data.layers) {
    const _layer_name = layer.name
    const _layer_type = layer.type
    const tileData = _layer_type === 'tilelayer' ? layer.data : undefined
    const objects = _layer_type === 'objectgroup' ? layer.objects : undefined
    const _count_j = tileData ? tileData.length : (objects?.length ?? 0)
    // each tile or obj of this layer
    for (let _j = 0; _j < _count_j; _j++) {
      let _list_idx_of_ts = 0
      const _str_j = hex_str(_j)
      const _dm_obj_data: TiledObject | undefined = objects?.[_j]
      let _ow_clm: number
      let _ow_row: number
      if (tileData) {
        _ow_clm = _j % self.OW_CLMS
        _ow_row = Math.trunc(_j / self.OW_CLMS)
      } else if (_dm_obj_data) {
        _ow_clm = _dm_obj_data.x >> SHIFT
        _ow_row = _dm_obj_data.y >> SHIFT
        // Tiled issue. Objs with "gid" are +1 y offset.
        // Tiled obj y origin point is btm-left of obj instead of top-left.
        if (_dm_obj_data.gid !== undefined) _ow_row--
      } else {
        _ow_clm = 0
        _ow_row = 0
      }
      const _owrc = (_ow_row << 8) | _ow_clm
      const _owrc_ = hex_str(_owrc, 4)
      // _layer_name for AREA example: AREA_WestA_01
      // Each layer contains 1 or more rectangle objects (var _j)
      // that outline the areas for an area.
      if (_layer_name.includes(_STR_AREA) && !_layer_name.includes('AREA_NAMES')) {
        const _area = _layer_name.substr(_STR_AREA.length, AreaID_LEN)
        const _idx = g.dl_AREA_NAME.findIndex(_area)
        if (_idx + 1 && _dm_obj_data) {
          // AREAS ----------------------------------------------
          const _clms = _dm_obj_data.width >> SHIFT
          const _rows = _dm_obj_data.height >> SHIFT
          const _str = _layer_name.substr(_layer_name.length - 2, 2)
          const _count1 = val(self.Biome_dm.get(STR_Biome + STR_Count)) as number
          // Each biome
          for (let _k = 0; _k < _count1; _k++) {
            const _val1 = val(self.Biome_dm.get(STR_Biome + hex_str(_k + 1)), STR_undefined) as string
            //  _dk example:  '_FIELD'  + '_WestA_' + '02' + '03'
            const _dk = _val1 + _area + _str + _str_j
            dm.set(_dk + STR_Clm, _ow_clm)
            dm.set(_dk + STR_Row, _ow_row)
            dm.set(_dk + STR_Clms, _clms)
            dm.set(_dk + STR_Rows, _rows)
          }
          // Area areas. -------------------------------------------
          // _val is 2 bytes. $(FF)FF: the sub area (Example: West 1: West-North, West 2: West-South). $FF(FF): the index of g.dl_area_name
          const _val = (str_hex(_str) << 8) | _idx
          gridSetRegion(self.dg_area, _ow_clm, _ow_row, _ow_clm + _clms - 1, _ow_row + _rows - 1, _val)
        }
        continue //_j
      }
      const _dm_prop_value = propsOf(tileData ? layer.properties : _dm_obj_data?.properties)
      if (_layer_name.includes(STR_Scene + STR_OWRC)) {
        const _data = _dm_prop_value.get(STR_RmName) as string | undefined
        if (_data !== undefined) {
          // This is an exit obj that's soley here to indicate the owrc of a scene so pause menu
          // map will acurately show the ow position of PC.
          // _data Example: "_WestA_FF" or "_WestA_FA,_WestA_F4,_WestA_F3"  (all share same owrc)
          const _len1 = RmName_LEN // g.rm_name length
          const _len2 = _len1 + 1 // +1 for the comma separation
          const _count = string_count(',', _data) + 1
          for (let _k = 0; _k < _count; _k++) {
            const _rm_name = _data.substr(_len2 * _k, _len1)
            g.dm_rm.set(_rm_name + STR_OWRC, _owrc)
          }
        }
        continue //_j
      }
      const _info = val(_dm_prop_value.get(STR_Info), '') as string
      let _tsrc_raw = 0
      if (tileData) _tsrc_raw = tileData[_j] as number
      else if (_dm_obj_data) _tsrc_raw = _dm_obj_data.gid ?? 0
      let _tsrc = _tsrc_raw
      let _name = ''
      if (_tsrc !== 0) {
        _tsrc-- // Tiled app adds 1 so it can't be 0
        _tsrc &= 0x3fffffff // in case x/y scale is negative
        _tsrc = Math.abs(_tsrc)
        const _val = hex_str(_tsrc >> 8)
        const _ts = _dm_ts_info.get(_val + _STR_IDX) as string | undefined
        _name = (_dm_ts_info.get(_val + _STR_NAME) as string | undefined) ?? ''
        _list_idx_of_ts = Math.max(g.dl_tileset.findIndex(_ts), self.TILESET1_TS_IDX)
        _tsrc &= 0xff
        if (_layer_name.includes('CHANGE')) {
          if (_layer_name.includes('BOOTS01')) {
            const _idx = self.dg_ChangeTiles_Boots.width
            gridResize(self.dg_ChangeTiles_Boots, _idx + 1, self.dg_ChangeTiles_Boots.height)
            let _val2 = 0x00
            const _str = 'SOLID_'
            const _pos = _layer_name.indexOf(_str) + 1
            if (_pos) _val2 = str_hex(_layer_name.substr(_pos - 1 + _str.length, 2))
            self.dg_ChangeTiles_Boots.set(_idx, 0, _owrc)
            self.dg_ChangeTiles_Boots.set(_idx, 1, _val2) // solid bits
            self.dg_ChangeTiles_Boots.set(_idx, 2, self.TSRC_WATER01)
            self.dg_ChangeTiles_Boots.set(_idx, 3, _ts as any)
            continue //_j
          }
        } else {
          if (
            _name.includes('tile_marker') &&
            !_layer_name.includes('AREA_NAMES') &&
            !_layer_name.includes('_Hidden_Exits_Help') &&
            _tsrc & 0x80
          ) {
            _tsrc = -1
          }
        }
        // $FF is a marker image
        if (_tsrc === 0xff) _tsrc = -1
        _tsrc++
      }
      if (_tsrc !== 0) {
        _tsrc--
        if (_layer_name.includes('_Hidden_Exits_Help')) {
          const _idx = self.HiddenExitIndicator_dg.width
          gridResize(self.HiddenExitIndicator_dg, _idx + 1, self.HiddenExitIndicator_dg.height)
          self.HiddenExitIndicator_dg.set(_idx, 0, _ow_clm)
          self.HiddenExitIndicator_dg.set(_idx, 1, _ow_row)
          continue //_j
        }
        if (_layer_name.includes('AREA_NAMES')) {
          _tsrc &= 0xff
          const _idx = _tsrc - 0xa0
          self.dg_AreaNames.set(_ow_clm, _ow_row, _dl_AreaNames[_idx] as string)
          continue //_j
        }
        if (_layer_name === STR_Solid) {
          self.dg_solid_def.set(_ow_clm, _ow_row, _tsrc & 0xff)
          continue //_j
        }
        // Should be the 1st, and only, obj of 1st layer
        if (_layer_name.includes(STR_BG)) {
          _tsrc0 = (_list_idx_of_ts << 8) | _tsrc
          // Clear with whatever tsrc was on the 'BG' layer. $0580 == (($05<<8)|TSRC_WATE01) == `TSRC_WATER01`
          gridClear(self.dg_tsrc_def, _tsrc0)
          break //_j
        }
        switch (_layer_name) {
          case STR_Boulder: {
            dm.set(_owrc_ + STR_TSRC + STR_Under + STR_Boulder, self.dg_tsrc_def.get(_ow_clm, _ow_row))
            _dg_tsrcub.push([_owrc, self.dg_tsrc_def.get(_ow_clm, _ow_row) as number])
            break
          }
          case STR_Monster: {
            dm.set(_owrc_ + STR_TSRC + STR_Under + STR_River_Devil, self.dg_tsrc_def.get(_ow_clm, _ow_row))
            break
          }
        } //switch(_layer_name)
        if (_layer_name === STR_Boulder) {
          const _idx = self.dg_boulders.width
          gridResize(self.dg_boulders, _idx + 1, self.dg_boulders.height)
          self.dg_boulders.set(_idx, 0, _owrc)
          self.dg_boulders.set(_idx, 1, 1) // boulder state
          self.dg_boulders.set(_idx, 2, self.dg_tsrc_def.get(_ow_clm, _ow_row) as number) // tsrc under boulder
        }
        _tsrc0 = (_list_idx_of_ts << 8) | _tsrc
        if (!_list_idx_of_ts) _tsrc0 = (self.TILESET1_TS_IDX << 8) | _tsrc // (_C1 branch)
        self.dg_tsrc_def.set(_ow_clm, _ow_row, _tsrc0)
      }
      if (_dm_obj_data) {
        // Allows an object to set what solid value it needs.
        // An example is a cave exit which sits on top of a
        // solid mountain tile, needs to set the solid value to 0.
        const _Solid = _dm_prop_value.get(STR_Solid)
        // property value should be 0 or one of the OST_XXXXXX values
        if (_Solid !== undefined) self.dg_solid_def.set(_ow_clm, _ow_row, Number(_Solid))
      }
      // -------------------------------------------------------------------
      if (_layer_name === STR_Boulder) {
        if (_info.includes(STR_Rauru + STR_Boulder)) {
          dm.set(dk_RauruPass + STR_OWRC, _owrc)
          switch (G.Rando_RauruPass_VER) {
            case 2: {
              dm.set(STR_Rando + STR_River_Devil + STR_OWRC, _owrc)
              dm.set(STR_Rando + STR_River_Devil + STR_TSRC, (self.TILESET2_TS_IDX << 8) | 0xf8)
              dm.set(
                _owrc_ + STR_TSRC + STR_Under + STR_River_Devil,
                (self.TILESET1_TS_IDX << 8) | TSRC_PATH02,
              )
              break
            }
            case 3: {
              break
            }
          }
        }
      } else if (_layer_name === STR_Monster) {
        if (_info.includes(STR_River_Devil)) {
          // _info example: '0001_River_Devil'
          const _str = _info.substr(2, 2) // + "01"
          dm.set(_owrc_ + STR_River_Devil + STR_State, 1)
          dm.set(STR_OWRC + STR_River_Devil + _str, _owrc)
          dm.set(_owrc_ + STR_River_Devil, str_hex(_str))
        }
      } else if (_layer_name.includes(STR_Raft)) {
        // Raft data examples: '0101', '0102'
        // Raft tiles are in pairs: (01)01 Set num, 01(01) Member num 1 or 2
        // Member 1 is always N or W of member 2
        const _prop_value = str_hex(_dm_prop_value.get(STR_Raft))
        dm.set(_owrc_ + STR_Raft, _prop_value)
        dm.set(STR_Raft + hex_str(_prop_value) + STR_OWRC, _owrc)
      } else if (_layer_name.includes(STR_Exit) && !_layer_name.includes('_Hidden_Exits_Help')) {
        let _Open = _dm_prop_value.get(STR_Open)
        let _CutScene = _dm_prop_value.get(STR_CutScene)
        const _RmName = _dm_prop_value.get(STR_RmName) as string | undefined
        let _AccessRm = _dm_prop_value.get(STR_AccessRm) as string | undefined
        const _AccessOw = _dm_prop_value.get(STR_AccessOw) as string | undefined
        if (_Open === undefined) _Open = 0
        if (_CutScene === undefined) _CutScene = 0
        if (_RmName !== undefined && _AccessRm !== undefined && _AccessOw !== undefined) {
          // _AccessRm raw data example: "20 10 20 10"
          _AccessRm = string_lettersdigits(String(_AccessRm))
          const _AccessOw_len = String(_AccessOw).length
          // _AccessRm is either "0" or 4 byte string data.
          // "0" means there's a rm exit that needs to know where
          // to put the PC in the overworld, but there's no
          // overworld exit that goes to that rm exit
          if (_AccessRm !== '0') {
            dm.set(_owrc_ + STR_Open, _Open)
            dm.set(_owrc_ + STR_Open + STR_Default, _Open)
            // _CutScene example: '_Fall_04'
            dm.set(_owrc_ + STR_CutScene, _CutScene)
            dm.set(_owrc_ + STR_RmName, _RmName)
            dm.set(_owrc_ + STR_AccessRm, _AccessRm)
            if (_info.includes(STR_Special + STR_Encounter))
              dm.set(_owrc_ + STR_Special + STR_Encounter, _RmName)
            // dk_NO_ENCOUNTER:  Can't use encounter skip exploit for this exit
            if (_info.includes(dk_NO_ENCOUNTER)) dm.set(_owrc_ + dk_NO_ENCOUNTER, 1)
            //          _move_dir   1      2      4      8
            // _AccessRm Example: "20" + "10" + "20" + "10"
            for (let _k = (_AccessRm.length >> 1) - 1; _k >= 0; _k--) {
              const _exit_num = _AccessRm.substr(_k << 1, 2)
              if (_exit_num !== 'FF') {
                // _datakey Example: "50C3" + "04" + STR_Exit
                const _exit_name = _RmName + _exit_num // rm exit name
                const _datakey = hex_str(0x01 << _k) // pc overworld movement direction
                dm.set(_owrc_ + _datakey + STR_Exit, _exit_name) // goto rm exit
              }
            }
          }
          //  _AccessOw Example: "20-01+00_8, " + "10+01+00_4, " (Do not input " char in Tiled prop field)
          if (_AccessOw_len) {
            const ow = String(_AccessOw)
            const _pos = ow.indexOf(',') + 1
            const _len = _pos + 1 // because of space after comma
            const _count = Math.trunc(_AccessOw_len / _len)
            // each set of data representing an exit
            for (let _k = _count - 1; _k >= 0; _k--) {
              const _str = ow.substr(_k * _len, _len) // one set. "20-01+00_8, "
              const _exit_num = _str.substr(0, 2) // "(20)-01+00_8, "
              const _exit_name = _RmName + _exit_num // rm exit name
              // _roff & _coff: Row off, Clm off
              const _roff = str_hex(_str.substr(3, 2)) * sign_(_str.charAt(2) === '+') // "20(-01)+00_8, "
              const _coff = str_hex(_str.substr(6, 2)) * sign_(_str.charAt(5) === '+') // "20-01(+00)_8, "
              const _val = ((_ow_row + _roff) << 8) | (_ow_clm + _coff)
              if (g.dm_rm.get(_RmName + STR_OWRC) === undefined) g.dm_rm.set(_RmName + STR_OWRC, _owrc) // scene owrc
              g.dm_rm.set(_exit_name + STR_OWRC, _val) // goto owrc
              g.dm_rm.set(_exit_name + STR_ow_dir, str_hex(_str.charAt(_pos - 2))) // goto ow facing dir
              g.dm_rm.set(_exit_name + STR_goto_reen, Area_OvrwA + _owrc_) // goto ow exit
            }
          }
          if (_info.length && _info.includes(STR_Rando)) {
            dm.set(
              STR_Rando + STR_Exit + STR_Count,
              (val(dm.get(STR_Rando + STR_Exit + STR_Count)) as number) + 1,
            )
            const _num = val(dm.get(STR_Rando + STR_Exit + STR_Count)) as number
            dm.set(STR_Rando + STR_Exit + hex_str(_num) + STR_OWRC, _owrc)
            dm.set(_owrc_ + STR_Rando + STR_Exit + STR_Num, _num)
          }
        }
      }
      // -------------------------------------------------------------------
      // _info Example: "0001_Palace_Three_Eye_Rock", "0001_Town_New_Kasuto", "0001_Fast_Travel_03", "0001_Palace_North_Palace"
      if (_info.length) {
        const _strFT = STR_Fast + STR_Travel
        if (_info.includes(_strFT)) {
          const _pos = _info.indexOf(_strFT) + 1 + _strFT.length
          const _datakey = strR(_info, _pos)
          // _datakey example: "_OWRC_Fast_Travel_03"
          dm.set(STR_OWRC + _datakey, _owrc)
        } else {
          const _str1 = STR_Boulder + STR_Circle
          const _str2 = STR_Forest + STR_Hammer
          let _str: string | 0
          if (_info.includes(STR_Town)) _str = STR_Town
          else if (_info.includes(STR_Palace)) _str = STR_Palace
          else if (_info.includes(_str2)) _str = _str2
          else if (_info.includes(_str1)) _str = _str1
          else _str = 0
          if (typeof _str === 'string') {
            let _datakey: string
            if (_str === _str1) {
              // STR_Boulder+STR_Circle. example: _Boulder_Circle_02_NORTH_EAST
              _datakey = _info.substr(0, _str1.length + 3) // "_Boulder_Circle_02"
              _datakey = STR_OWRC + _datakey // "_OWRC_Boulder_Circle_02"
              const _pos = str_hex(_info.substr(_str1.length + 1, 2))
              self.dl_BoulderCircle_OWRC.set(_pos - 1, _owrc)
              if (_pos === 1) self.BoulderCircle_center_OWRC = _owrc + 0x0300
            } else if (_str === _str2) {
              // STR_Forest+STR_Hammer. _info example: '_Forest_Hammer_0101'
              dm.set(_str2 + _owrc_, _info)
              _datakey = STR_OWRC + _info
            } else {
              // STR_Town, STR_Palace
              // Note: The datakeys have been macro'd. Example: MK_OWRC_TWN_RAUR1, MK_OWRC_PAL_PRPA1
              const _pos = _info.indexOf(_str) + 1 + _str.length
              _datakey = STR_OWRC
              _datakey += strR(_info, _pos)
              _datakey += _info.substr(2, 2)
            }
            // _datakey example: '_OWRC_Parapa_Palace01', STR_OWRC + STR_New_Kasuto + '01'
            dm.set(_datakey, _owrc)
          }
        }
      } //if (string_length(_info))
    } //for(_j) each tile or obj of this layer
  } //for each layer
  void _dg_tsrcub
  // FIXED: the GML continues past the layer loop with `if (g.anarkhyaOverworld_MAIN) { … }`
  // (`Overworld_init_data_1.gml:1802-1897`) — an inline copy of `Overworld_init_data_anarkhya.gml`,
  // identical to it line for line. The port stopped here, so the re-bake path left every
  // `dg_anarkhya_*` grid at 0×0 and the alternate overworld would have rendered all-zero tsrc. Only
  // reachable on `OVERWORLD_INIT_METHOD === 1` or `_REINITIALIZING` (the shipped method is 3, which
  // calls the same builder from `Overworld_init_data`), so this was latent — but a parser path that
  // silently builds less than the cache path is exactly the seam a re-bake would trip over.
  if (g.anarkhyaOverworld_MAIN) Overworld_init_data_anarkhya(self)
  return true
}

/** `Overworld_init_data_anarkhya()` — the alternate community overworld (`anarkhya_OvrwA_00.json`). */
export function Overworld_init_data_anarkhya(self: Overworld): void {
  const map = world.maps.get('anarkhya_OvrwA_00')
  if (!map) {
    sdm(
      "!!!! WARNING! Overworld_init_data_anarkhya(). file 'ow_tile_data/anarkhya_OvrwA_00.json' does not exist !!!!",
    )
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  gridResize(self.dg_anarkhya_tsrc_def, self.OW_CLMS, self.OW_ROWS)
  gridClear(self.dg_anarkhya_tsrc_def, 0)
  gridResize(self.dg_anarkhya_tsrc, self.OW_CLMS, self.OW_ROWS)
  gridClear(self.dg_anarkhya_tsrc, 0)
  gridResize(self.dg_anarkhya_tsrc_detail_def, self.OW_CLMS, self.OW_ROWS)
  gridClear(self.dg_anarkhya_tsrc_detail_def, 0)
  gridResize(self.dg_anarkhya_tsrc_detail, self.OW_CLMS, self.OW_ROWS)
  gridClear(self.dg_anarkhya_tsrc_detail, 0)
  // each layer
  for (const layer of map.layers) {
    if (layer.type !== 'tilelayer') continue
    const _layer_name = layer.name
    const _dl_data = (layer as TiledTileLayer).data
    // each tile or obj of this layer
    for (let _j = 0; _j < _dl_data.length; _j++) {
      const _ow_clm = _j % self.OW_CLMS
      const _ow_row = Math.trunc(_j / self.OW_CLMS)
      const _owrc = (_ow_row << 8) | _ow_clm
      const _tile_data = _dl_data[_j] as number
      if (_tile_data !== 0) {
        if (_layer_name.includes('BOOTS')) {
          const _idx = self.dg_anarkhya_tsrc_boots.width
          gridResize(self.dg_anarkhya_tsrc_boots, _idx + 1, self.dg_anarkhya_tsrc_boots.height)
          self.dg_anarkhya_tsrc_boots.set(_idx, 0, _owrc)
          self.dg_anarkhya_tsrc_boots.set(_idx, 1, _tile_data)
        } else if (_layer_name.includes('DETAIL')) {
          self.dg_anarkhya_tsrc_detail_def.set(_ow_clm, _ow_row, _tile_data)
        } else {
          self.dg_anarkhya_tsrc_def.set(_ow_clm, _ow_row, _tile_data)
        }
      }
    }
  }
  for (let _i = self.dg_boulders.width - 1; _i >= 0; _i--) {
    const _owrc = self.dg_boulders.get(_i, 0) as number
    const _clm = (_owrc >> 0) & 0xff
    const _row = (_owrc >> 8) & 0xff
    self.dg_anarkhya_tsrc_detail_def.set(_clm, _row, self.anarkhya_TSRC_BOULDER)
  }
  gridCopy(self.dg_anarkhya_tsrc, self.dg_anarkhya_tsrc_def)
  gridCopy(self.dg_anarkhya_tsrc_detail, self.dg_anarkhya_tsrc_detail_def)
}

/** Tile size lookups the GML did through `g.dm_tileset` (kept for parity with the parser's `_dg_ts_data`). */
export function tilesetTileSize(name: string, dflt: number): { w: number; h: number } {
  return {
    w: val(g.dm_tileset.get(name + STR_Tile + STR_Width), dflt) as number,
    h: val(g.dm_tileset.get(name + STR_Tile + STR_Height), dflt) as number,
  }
}
