/** GML: FileSelect_RandoOTHER_REQUIRE_update(self) */
export function FileSelect_RandoOTHER_REQUIRE_update(self: FileSelect) {
  let _InputConfirm_pressed2: any, _DIR: any, _val: any, _KAKUSU_MAX: any

  _InputConfirm_pressed2 = gmb(self.InputConfirm_pressed) || gmb(input.pressedH)
  // -------------------------------------------------------------------------------
  if (
    gmb(self.InputBack_pressed) ||
    (self.RandoOTHER_REQUIRE_cursor === self.RandoOTHER_REQUIRE_cursor_BACK && gmb(self.InputConfirm_pressed))
  ) {
    aud_play_sound(get_audio_theme_track(self.BACK_SOUND_THEME1))
    self.RandoOTHER_state = self.RandoOTHER_state_MAIN
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // -------------------------------------------------------------------------------
  if (gmb(self.input_select_pressed) || gmb(input.pressedV)) {
    _DIR = sign_(gmb(self.input_select_pressed) || gmb(self.input_down_pressed))
    self.RandoOTHER_REQUIRE_cursor += _DIR
    self.RandoOTHER_REQUIRE_cursor += self.RandoOTHER_REQUIRE_cursor_COUNT
    self.RandoOTHER_REQUIRE_cursor = self.RandoOTHER_REQUIRE_cursor % self.RandoOTHER_REQUIRE_cursor_COUNT
    aud_play_sound(get_audio_theme_track(self.CURSOR_SOUND_THEME2))
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }

  switch (self.RandoOTHER_REQUIRE_cursor) {
    // ============================================================================
    // -------------------------------------------------------------------
    case self.RandoOTHER_REQUIRE_cursor_CRYSTALS: {
      if (gmb(self.input_start_pressed) || gmb(input.pressedH)) {
        _DIR = sign_(gmb(self.input_start_pressed) || gmb(self.input_right_pressed))
        _val = self.dg_RandoOTHER_REQUIRE.get(self.RandoOTHER_REQUIRE_cursor_CRYSTALS, 2)
        _val += _DIR
        if (_val < G.RandoDungeonRequirement_MIN) {
          _val = G.RandoDungeonRequirement_MAX
        } else if (_val > G.RandoDungeonRequirement_MAX) {
          _val = G.RandoDungeonRequirement_MIN
        }
        /*
        _val--;
        _val  = (_val+_DIR+global.RandoDungeonRequirement_MAX) mod global.RandoDungeonRequirement_MAX;
        _val++;
        _val  = clamp(_val, global.RandoDungeonRequirement_MIN,global.RandoDungeonRequirement_MAX);
        */
        self.dg_RandoOTHER_REQUIRE.set(self.RandoOTHER_REQUIRE_cursor_CRYSTALS, 2, _val)
        aud_play_sound(Audio.sound('SND_TYPE_CHR2'))
      }
      break
    }
    // ============================================================================
    // -------------------------------------------------------------------
    case self.RandoOTHER_REQUIRE_cursor_KAKUSU: {
      if (gmb(self.input_start_pressed) || gmb(input.pressedH)) {
        _KAKUSU_MAX = val(g.dm_spawn.get(STR_Kakusu + STR_Count))
        _DIR = sign_(gmb(self.input_a_pressed) || gmb(self.input_right_pressed))
        _val = self.dg_RandoOTHER_REQUIRE.get(self.RandoOTHER_REQUIRE_cursor_KAKUSU, 2)
        _val--
        _val = (_val + _DIR + _KAKUSU_MAX) % _KAKUSU_MAX
        _val++
        _val = clamp(_val, 1, _KAKUSU_MAX)
        self.dg_RandoOTHER_REQUIRE.set(self.RandoOTHER_REQUIRE_cursor_KAKUSU, 2, _val)
        aud_play_sound(Audio.sound('SND_TYPE_CHR2'))
      }
      break
    }
    // ============================================================================
    // -------------------------------------------------------------------
    case self.RandoOTHER_REQUIRE_cursor_BACK: {
      if (gmb(self.InputConfirm_pressed)) {
        aud_play_sound(get_audio_theme_track(self.BACK_SOUND_THEME1))
        self.RandoOTHER_state = self.RandoOTHER_state_MAIN
      }
      break
    }
  }
}

