/** GML: FileSelect_build_surfaces_1(self) */
export function FileSelect_build_surfaces_1(self: FileSelect, ...argument: any[]) {
  let _i: any,
    _j: any,
    _idx: any,
    _x: any,
    _y: any,
    _x1: any,
    _y1: any,
    _dist1: any,
    _dist2: any,
    _clms: any,
    _rows: any,
    _tsrc: any,
    _ts_x: any,
    _ts_y: any,
    _text: any,
    _len: any,
    _char_w: any,
    _DrawArea_XL: any,
    _DrawArea_XC: any,
    _DrawArea_YT: any,
    _DrawArea_W: any,
    _Y1: any,
    _Y2: any,
    _Y3: any,
    _r: any

  switch (argument[0]) {
    default: {
      return
    }
    case STR_Register: {
      if (surface_exists(self.REGISTER_surf)) {
        return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
      }
      break
    }
    case STR_Eliminate: {
      if (surface_exists(self.ELIMINATE_surf)) {
        return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
      }
      break
    }
  }
  // ---------------------------------------------------------------------------------

  _idx = 0

  switch (argument[0]) {
    case STR_Register: {
      _DrawArea_XL = self.REGISTER_surf_DrawArea_XL
      _DrawArea_XC = self.REGISTER_surf_DrawArea_XC
      _DrawArea_YT = self.REGISTER_surf_DrawArea_YT
      break
    }
    case STR_Eliminate: {
      _DrawArea_XL = self.ELIMINATE_surf_DrawArea_XL
      _DrawArea_XC = self.ELIMINATE_surf_DrawArea_XC
      _DrawArea_YT = self.ELIMINATE_surf_DrawArea_YT
      break
    }
  }
  _DrawArea_W = (_DrawArea_XC - _DrawArea_XL) << 1
  _Y1 = 0x03 << 3 // YT of save files
  _Y1 += (0x03 << 3) * SAVE_FILE_MAX // + total height of save files for YT of "RANDO"/"END"
  _Y1 += 0x01 << 3 // + extra "RANDO"/"END" pad
  _Y1 += _DrawArea_YT
  // YT of "END"
  switch (argument[0]) {
    case STR_Register: {
      _Y2 = _Y1 + (0x02 << 3)
      break
    }
    case STR_Eliminate: {
      _Y2 = _Y1
      break
    }
  }
  _Y3 = _Y2 // YT of "END"
  _Y3 += 0x02 << 3 // YT of window border
  //
  switch (argument[0]) {
    case STR_Register: {
      self.REGISTER_surf = surface_create(self.REGISTER_surf_W, self.REGISTER_surf_H)
      surface_set_target(self.REGISTER_surf)
      draw_clear_alpha(c_black, 0)
      break
    }
    case STR_Eliminate: {
      self.ELIMINATE_surf = surface_create(self.ELIMINATE_surf_W, self.ELIMINATE_surf_H)
      surface_set_target(self.ELIMINATE_surf)
      draw_clear_alpha(c_black, 0)
      break
    }
  }
  pal_swap_set(self.PI_MENU1)
  // HEADER =======================
  switch (argument[0]) {
    case STR_Register: {
      _text = ' REGISTER YOUR NAME '
      break
    }
    case STR_Eliminate: {
      _text = ' ELIMINATION MODE '
      break
    }
  }
  _char_w = 8
  _len = string_length(_text)
  _dist1 = _len * _char_w
  // Horizontal bar
  _tsrc = g.dl_MenuFrame_TSRC.get(0) // 0: Horizontal bar
  _ts_x = ((_tsrc >> 0) & 0x0f) << 3
  _ts_y = ((_tsrc >> 4) & 0x0f) << 3
  _dist2 = _DrawArea_W >> 1 // half w of header
  _dist2 -= _dist1 >> 1 // w available for an end bar
  _clms = _dist2 >> 3 // Number of horizontal bar tiles on each side of header text
  _clms -= _clms & 0x01 // round down to even
  _dist2 = _DrawArea_W >> 1 // half w of header
  _x1 = _DrawArea_XC - _dist2 // XL of header
  _x = _x1 // XL of left end bar (XL of header)
  _y = _DrawArea_YT // YT of header
  for (_r = 0; _r < 2; _r++) {
    for (_i = 0; _i < _clms; _i++) {
      draw_background_part(g.TS_MENU, _ts_x, _ts_y, 8, 8, _x + (_i << 3), _y)
    }
    _x = _DrawArea_XC + _dist2 // XR of right end bar
    _x -= _clms << 3 // XL of right end bar
  }
  // Header text
  _x = _DrawArea_XC - (_dist1 >> 1)
  draw_text_(_x, _y, _text)
  // "RANDO" & "END" =======================
  _x = self.SAVE_NAME_X2
  _y = self.REGISTER_RANDO_TEXT_YT
  //_y  = _Y1;
  //_y += RandoOptions_YOFF1;
  if (argument[0] === STR_Register) {
    draw_text_(_x, _y, 'RANDO')
  }
  _y = _Y2
  _y += self.RandoOptions_YOFF1
  draw_text_(_x, _y, 'DONE')
  // CHAR TABLE =======================
  _clms = self.CharTable_Window_CLMS // number of window clms
  _dist2 = (_clms << 3) >> 1 // half w of the table window
  _x1 = _DrawArea_XC - _dist2 // XL of window border
  _x1 = (_x1 >> 3) << 3 // make sure window is aligned w/ the grid
  _x = _x1 // XL of window border
  _x += 0x01 << 3 // + left window border
  _x += 0x01 << 3 // + left text pad to get XL of text area
  _y1 = _Y3 // YT of window border
  _y1 += 0x01 << 3 // + top window border
  _y1 += 0x01 << 3 // + top text pad to get YT of text area
  for (_i = ds_list_size(self.CharTable_dl) - 1; _i >= 0; _i--) {
    _y = _y1 // 1st line text YT
    _y += (0x02 << 3) * _i // + dist between text rows
    draw_text_(_x, _y, self.CharTable_dl.get(_i))
  }
  // CHAR TABLE WINDOW BORDER =======================
  _idx = 2 // 2: Corner tile
  _y1 = _Y3 // YT of window border
  _rows = ds_list_size(self.CharTable_dl) // text rows
  // biome-ignore lint/suspicious/noMisrefactoredShorthandAssign: GML `_rows += _rows+1` (rows + the gaps between them)
  _rows += _rows + 1 // + space inbetween text rows
  _rows += 0x02 // + top & bottom window borders
  for (_i = 0; _i < _rows; _i++) {
    for (_j = 0; _j < _clms; _j++) {
      if (_i === 0 || _i === _rows - 1) {
        // Top & Bottom rows
        if (_j === 0 || _j === _clms - 1) {
          _idx = 2
        } /* 2: Corner */ else {
          _idx = 0 // 0: Horizontal bar
        }
      } else {
        // Sides
        if (_j === 0 || _j === _clms - 1) {
          _idx = 1
        } /* 1: Vertical bar */ else {
          continue // _j
        }
      }
      _tsrc = g.dl_MenuFrame_TSRC.get(_idx)
      _ts_x = ((_tsrc >> 0) & 0x0f) << 3
      _ts_y = ((_tsrc >> 4) & 0x0f) << 3
      _x = _x1 + (_j << 3)
      _y = _y1 + (_i << 3)
      draw_background_part(g.TS_MENU, _ts_x, _ts_y, 8, 8, _x, _y)
    }
  }
  pal_swap_reset()
  surface_reset_target()
  switch (argument[0]) {
    case STR_Register: {
      if (surface_exists(self.REGISTER_surf)) {
      }
      break
    }
    case STR_Eliminate: {
      if (surface_exists(self.ELIMINATE_surf)) {
      }
      break
    }
  }
}

