/** GML: FS_set_stats(self) */
export function FS_set_stats(self: FileSelect) {
  let _i: any, _file_name: any, _file: any, _dm_data: any, _file_data: any

  // File Select screen

  // Each save file
  for (_i = 0; _i < SAVE_FILE_MAX; _i++) {
    _file_name = f.dl_file_names.get(_i)
    if (file_exists(_file_name)) {
      _file = file_text_open_read(working_directory + _file_name)
      _file_data = file_text_read_string(_file)
      file_text_close(_file)
      //_file_data = base64_decode(_file_data);
      _dm_data = json_decode(_file_data)
      if (_dm_data !== -1) {
        G.dm_save_file_data.set(STR_Save + STR_File + hex_str(_i + 1) + STR_Encoded, _file_data)
        self.dg_stats.set(_i, 0, val(_dm_data.get(f.SDNAME_saveCreated)))
        self.dg_stats.set(_i, 1, val(_dm_data.get(f.SDNAME_questNum)))
        self.dg_stats.set(_i, 2, val(_dm_data.get(f.SDNAME_deathCount)))
        self.dg_stats.set(_i, 3, val(_dm_data.get(f.SDNAME_level_atk)))
        self.dg_stats.set(_i, 4, val(_dm_data.get(f.SDNAME_level_mag)))
        self.dg_stats.set(_i, 5, val(_dm_data.get(f.SDNAME_level_lif)))
        self.dg_stats.set(_i, 6, val(_dm_data.get(f.SDNAME_crystals)))
        ds_map_destroy(_dm_data)
        _dm_data = undefined
      }
    }
  }
}

/** GML: FS_cursor_char_move(self) */
export function FS_cursor_char_move(self: FileSelect) {
  let _diff: any, _LENGTH: any, _i: any

  if (!gmb(input.pressedHV)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  _diff = 0
  if (gmb(input.Up_pressed)) {
    _diff = -self.CharTable_Text_CLMS
  } else if (gmb(input.Right_pressed)) {
    _diff = 1
  } else if (gmb(input.Down_pressed)) {
    _diff = self.CharTable_Text_CLMS
  } else if (gmb(input.Left_pressed)) {
    _diff = -1
  }
  self.CharTable_cursor_char += _diff
  _LENGTH = string_length(self.CharTable_CHARS)
  if (
    inRange(self.CharTable_cursor_char, 0, _LENGTH) &&
    string_char_at(self.CharTable_CHARS, self.CharTable_cursor_char + 1) === self.CharTable_CHAR_NULL
  ) {
    for (_i = 0; _i < 5; _i++) {
      self.CharTable_cursor_char += _diff
      if (string_char_at(self.CharTable_CHARS, self.CharTable_cursor_char + 1) !== self.CharTable_CHAR_NULL) {
        break
      }
    }
  }
  if (self.CharTable_cursor_char < 0) {
    self.CharTable_cursor_char += _LENGTH
  }
  if (self.CharTable_cursor_char >= _LENGTH) {
    self.CharTable_cursor_char -= _LENGTH
  }
  aud_play_sound(get_audio_theme_track(dk_CursorRegisterName))
}

/** GML: FileSelect_get_file_seed(self) */
export function FileSelect_get_file_seed(self: FileSelect, ...argument: any[]) {
  let _arg: any, _FILE_NUM: any, _QUEST_NUM: any, _DEFAULT: any

  _arg = 0
  _FILE_NUM = argument[_arg++]
  _QUEST_NUM = argument[_arg++]
  _DEFAULT = RUN_RANDOMIZATION_SEED
  if (argument.length > _arg) {
    _DEFAULT = argument[_arg++]
  }
  // dm_RandoSeeds belongs to FileSelect
  const _found = withInstance(self, (self) => {
    return val(self.dm_RandoSeeds.get(get_file_seed_dk(_FILE_NUM, _QUEST_NUM)), _DEFAULT)
  })
  if (_found !== undefined) {
    return _found
  }
  return _DEFAULT
}

