/** GML: FileSelect_change_rando_seed(self) */
export function FileSelect_change_rando_seed(self: FileSelect, ...argument: any[]) {
  let _i: any, _arg: any, _FILE_NUM: any, _SEED1: any, _DATAKEY1: any, _DATAKEY2: any, _CASE: any, _SEED2: any

  _arg = 0
  _FILE_NUM = argument[_arg++]
  _SEED1 = argument[_arg++]
  _DATAKEY1 = get_file_seed_dk(_FILE_NUM, 1)
  _DATAKEY2 = get_file_seed_dk(_FILE_NUM, 2)
  _CASE = 1
  switch (_CASE) {
    // Leaving options here bc I'm not sure which method to use yet
    // ------------------------------------------------------------------------
    default: {
      // Quest 2 seed is simply Quest 1 seed's bits flipped
      self.dm_RandoSeeds.set(_DATAKEY1, _SEED1) // Quest 1
      // `>>> 0`: GM's bitwise ops are not signed 32-bit, so the flipped seed stays positive there.
      self.dm_RandoSeeds.set(_DATAKEY2, (_SEED1 ^ 0xffffffff) >>> 0) // Quest 2
      //dm_RandoSeeds[?_DATAKEY2] = ~_SEED1; // Quest 2
      break
    }
    // ------------------------------------------------------------------------
    case 2: {
      // User won't know what Quest 2 seed is?
      // Quest 1
      self.dm_RandoSeeds.set(_DATAKEY1, _SEED1)
      // Quest 2
      random_set_seed(_SEED1) // Quest 2 seed is based off Quest 1 seed
      _SEED2 = 0
      for (_i = 0; _i < 8; _i++) {
        _SEED2 |= irandom(0x0f) << (_i << 2)
      }
      self.dm_RandoSeeds.set(_DATAKEY2, _SEED2)
      break
    }
  }
  setSaved(_FILE_NUM, _DATAKEY1, self.dm_RandoSeeds.get(_DATAKEY1))
  setSaved(_FILE_NUM, _DATAKEY2, self.dm_RandoSeeds.get(_DATAKEY2))
}
