/** Boomerang (Goriya): init_Boomerang, update_Boomerang, usd_Boomerang, draw_Boomerang. */
import { dk_Boomerang } from '@z2/data'
import { byte, gmBool, isVal } from '../../../../nes/math8'
import { instanceExists } from '../../../../runtime/instance'
import { g } from '../../../../runtime/world'
import { rectInRect } from '../../../collision/geometry'
import { update_body_hb_1a } from '../../../collision/hitbox'
import { byte_dir } from '../../../math/index'
import { draw_rect_ } from '../../../rooms/draw'
import { Audio } from '../../../sound/Audio'
import { aud_play_sound } from '../../../sound/play'
import { get_audio_theme_track } from '../../../sound/theme'
import { GameObject_draw_1a } from '../../go/draw'
import { GO_init_palidx } from '../../go/palette'
import { GO_sprite_init } from '../../go/sprite'
import { GG, gp } from '../../pending'
import { Projectile_udd_1a, Projectile_update_3a } from '../Projectile'
import type { Boomerang } from './classes'

const c_lime = 0x00ff00

export function init_Boomerang(self: Boomerang): void {
  GO_sprite_init(self, 'spr_Boomerang1')
  GO_init_palidx(self, GG().PI_MOB_BLU)
  self.vspd_adj = 2
  self.counter = 0x20
  self.facing_dir_spawn = 1 // 0452,X. set in creation
  self.isHighAttack = false // 0458,X. set in creation
  // for debug
  self.can_draw_catch_hb = true
  self.CATCH_W = 0x0c
  self.CATCH_H = 0x17
  self.catchX = 0
  self.catchY = 0
}

export function update_Boomerang(self: Boomerang): void {
  const _COLLIDED_SHIELD = byte_dir(self.hspd) !== self.facing_dir
  if (!_COLLIDED_SHIELD) {
    // if havn't bounced off shield.  9667
    if (g.counter1 & 0x1) {
      const track = get_audio_theme_track(dk_Boomerang)
      if (!Audio.audio_is_playing(track)) aud_play_sound(track)
      if (gmBool(self.vspd)) self.vspd = (self.vspd + -byte_dir(self.vspd)) & 0xff
    }
    // 9680.  counter=$20 at spawn
    if (self.counter < 0x80) {
      if (!gmBool(self.counter)) {
        // In process of reversing dir.  9687
        self.vspd = self.isHighAttack ? byte(4) : byte(-4)
        self.hspd = (self.hspd + -self.facing_dir_spawn) & 0xff
        self.facing_dir = byte_dir(self.hspd)
        // 96A4
        if ((self.hspd & 0x3f) === 0x20) self.counter = 0xff // Finished reversing dir
      } else {
        // 96B1
        self.counter--
      }
    }
    // 96B4: JSR 96FF
  }
  // 96F9, 96FF: JSR DED4, 9702
  if (!_COLLIDED_SHIELD) self.vspd = (self.vspd - self.vspd_adj) & 0xff // vspd_adj == 2;
  Projectile_update_3a(self, self.despawn_offscreen_hor)
  if (!_COLLIDED_SHIELD) {
    // if havn't bounced off shield.  96B7.  counter=$20 at spawn
    const src = self.source_inst
    if (isVal(self.counter, 0, 0xff) && instanceExists(src) && src.state === src.state_NORMAL) {
      // if has($FF) OR is(0) reversing dir
      update_body_hb_1a(self)
      // 96C7: Goriya catch boomerang
      self.can_draw_catch_hb = true
      self.catchX = src.xl + 2
      self.catchY = src.yt + 3
      if (
        rectInRect(
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_w,
          self.BodyHB_h,
          self.catchX,
          self.catchY,
          self.CATCH_W,
          self.CATCH_H,
        )
      ) {
        self.state = 0
      }
    }
  }
}

export function usd_Boomerang(self: Boomerang): void {
  Projectile_udd_1a(self)
}

export function draw_Boomerang(self: Boomerang): void {
  if (self.can_draw_self && self.sprite) GameObject_draw_1a(self, self.sprite, self.palidx) // draw self
  // draw catch hb
  if (!gmBool(gp().DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!gp().can_draw_hb) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!self.can_draw_catch_hb || !gmBool(self.state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  self.can_draw_catch_hb = false
  draw_rect_(c_lime, self.catchX, self.catchY, self.CATCH_W, self.CATCH_H, 0.5)
}
