/**
 * `PC_update_1c()` — E070: collision sides, then the tile interactions under the feet — insta-kill liquid
 * (E098), spikes, crumble ground (E0FC), viscous liquid (E0B0) — and the exit checks (E0C5, E14A, E19E).
 */
import {
  Container_AMT,
  dk_BridgeCrumble,
  ITM_FRY1,
  STR_Damage,
  STR_Heart,
  STR_PC,
  TID_BREAK2,
  TID_BREAK4,
  TID_LQUID1,
  TID_LQUID2,
  TID_SPIKE1,
  TID_SPIKE2,
} from '@z2/data'
import { gmBool, isVal } from '../../../nes/math8'
import { NOONE } from '../../../runtime/instance'
import { g, input, world } from '../../../runtime/world'
import { GO_update_cs, updateCSPoints } from '../../collision/cs'
import { is_in_grid, rectInRect, wINwAll } from '../../collision/geometry'
import { ocsH4 } from '../../collision/ocs'
import { Exit, is_exit_type } from '../../exit/Exit'
import { adjust_stat, get_stat_max } from '../../file/stats'
import { inRange } from '../../math/index'
import { sdm } from '../../other/index'
import { aud_play_sound } from '../../sound/play'
import { get_audio_theme_track } from '../../sound/theme'
import { cam_yb_max, cam_yt_min } from '../../view/camera'
import { set_xy } from '../go/movement'
import { PC_take_damage } from './attack'
import { pc_is_fairy } from './form'
import type { Lonk } from './Lonk'
import { pcInput } from './pc'

const cell = (grid: { get(x: number, y: number): unknown }, c: number, r: number) =>
  Number(grid.get(c, r) ?? 0)

export function PC_update_1c_impl(self: Lonk): void {
  GO_update_cs(self)
  // --------------------------------------------------------------------------------
  let _clm = 0
  let _row = 0
  self.control = 0
  // E098. INSTA-KILL LIQUID ---------------------------------------------
  const L = g.dg_RmTile_Liquid
  if (L.width) {
    _clm = self.cp1X >> 3
    _row = self.cp1Y >> 3
    if (
      is_in_grid(_clm, _row, L.width, L.height) &&
      (cell(L, _clm, _row) & 0xff) === TID_LQUID1 &&
      !(self.cs & 0x4)
    ) {
      // E0A4
      aud_play_sound(get_audio_theme_track(STR_PC + STR_Damage))
      let _damage = get_stat_max(STR_Heart)
      const _FAIRY1 = world.f.items & ITM_FRY1
      if (_FAIRY1) _damage = Container_AMT << 1
      if (g.DevTools_state && g.dev_invState & 0x3) _damage = 0 // 2: skip all, 1 skip dmg, 0 regular
      adjust_stat(-_damage, 0)
      if (_FAIRY1 && world.f.hp)
        self.RescueFairy_sprite = (g.dl_Fairy_SPRITES.get(Math.sign(g.counter1 & 0x4)) as string) ?? 0
      self.DrownLiquid_y = _row << 3
      self.DrownLiquid_depth = (cell(L, _clm, _row) >> 8) & 0xff
      self.DrownLiquid_depth = Number(g.dl_TILE_DEPTHS.get(self.DrownLiquid_depth) ?? 0)
      self.stun_timer = 0x10
      self.state = self.state_DROWN
      return
    }
  }
  // SPIKES ----------------------------------------------------------
  const S = g.dg_RmTile_Spike
  if (!self.iframes_timer && S.width) {
    if (!g.DevTools_state || (g.dev_invState & 0x3) !== 2) {
      const _HB_CLMS = ((self.csTop2X - self.csTop1X) >> 3) + 2
      const _HB_ROWS = ((self.csBtm1Y - self.csTop1Y) >> 3) + 2
      for (let _i = 0; _i < _HB_CLMS; _i++) {
        for (let _j = 0; _j < _HB_ROWS; _j++) {
          const _hb_clm = Math.min(self.csTop2X - 1, self.csTop1X + (_i << 3)) >> 3
          const _hb_row = Math.min(self.csBtm1Y, self.csTop1Y + (_j << 3)) >> 3
          if (is_in_grid(_hb_clm, _hb_row, S.width, S.height)) {
            const t = cell(S, _hb_clm, _hb_row) & 0xff
            if (t === TID_SPIKE1 || t === TID_SPIKE2) {
              let _damage = 0x10
              if (g.DevTools_state && g.dev_invState & 0x3) _damage = 0
              PC_take_damage(NOONE, _damage) // Spike Damage
              return
            }
          }
        }
      }
    }
  }
  // E0FC. CRUMBLE GROUND --------------------------------------
  const B = g.dg_RmTile_Break
  if (B.width) {
    const isCrumble = (c: number, r: number) => isVal(cell(B, c, r) & 0xff, TID_BREAK2, TID_BREAK4)
    if (g.mod_CRUMBLE_TILES === 1) {
      // check both csBtm
      _clm = self.csBtm1X >> 3
      _row = self.csBtm1Y >> 3
      if (!is_in_grid(_clm, _row, B.width, B.height) || !isCrumble(_clm, _row)) {
        _clm = self.csBtm2X >> 3
        _row = self.csBtm2Y >> 3
      }
    }
    if (is_in_grid(_clm, _row, B.width, B.height) && isCrumble(_clm, _row)) {
      // crumble bridge. E102: JSR E292
      const A = g.dg_tile_anim
      const _COUNT = A.width
      for (let _i = 0; _i < _COUNT; _i++) {
        if (isVal(Number(A.get(_i, 0)), TID_BREAK2, TID_BREAK4) && !Number(A.get(_i, 1))) {
          // find the top-left of the 2x2 tile group
          let _clm2 = 0
          let _row2 = 0
          if (_clm) {
            _clm2 = _clm - 1
            while (is_in_grid(_clm2, _row, B.width, B.height) && isCrumble(_clm2, _row)) {
              _clm2--
              if (!(_clm2 + 1)) break
            }
            _clm2++
            _clm -= (_clm & 0x1) !== (_clm2 & 0x1) ? 1 : 0
          }
          if (_row) {
            _row2 = _row - 1
            while (is_in_grid(_clm, _row2, B.width, B.height) && isCrumble(_clm, _row2)) {
              _row2--
              if (!(_row2 + 1)) break
            }
            _row2++
            _row -= (_row & 0x1) !== (_row2 & 0x1) ? 1 : 0
          }
          A.set(_i, 0, cell(B, _clm, _row) & 0xff)
          A.set(_i, 1, 1) // set counter. starts anim
          A.set(_i, 3, 1) // set frame num
          A.set(_i, 5, (_row << 8) | _clm)
          A.set(_i, 6, g.dl_TILE_DEPTHS.get(cell(B, _clm, _row) >> 8))
          if ((cell(B, _clm, _row) & 0xff) === TID_BREAK4) A.set(_i, 8, 1) // Regenerating tile: anim in reverse once
          // remove unique right away
          for (let _j = 0; _j < 4; _j++) {
            _clm2 = _clm + (_j & 1)
            _row2 = _row + (_j > 1 ? 1 : 0)
            if (is_in_grid(_clm2, _row2, B.width, B.height)) {
              // E105
              B.set(_clm2, _row2, 0)
              aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
            }
          }
          break
        }
      }
    }
  }
  // E0B0. VISCOUS LIQUID (SWAMP WATER) --------------------------------------
  if (L.width) {
    _clm = self.cp1X >> 3
    _row = (self.cp1Y - 4) >> 3
    if (is_in_grid(_clm, _row, L.width, L.height) && (cell(L, _clm, _row) & 0xff) === TID_LQUID2) {
      self.control |= self.control_MOVE1 | self.control_DRAW1 | self.control_SOUND1
    }
  }
  // ----------------------------  EXIT CHECKS  ------------------------------
  if (self.state !== self.state_NORMAL) return
  if (g.exit_leave) return
  let _exit: Exit | null = NOONE
  const _CARRY = !self.colliding_elevator?.exists
  const _W = 0x10
  const _H = self.hh + (_CARRY ? 1 : 0)
  const _XL = self.x - (_W >> 1)
  const _YT = self.yt
  for (const e of world.instancesOf(Exit)) {
    if (gmBool(e.open) && rectInRect(e.BodyHB_xl, e.BodyHB_yt, e.BodyHB_w, e.BodyHB_h, _XL, _YT, _W, _H)) {
      _exit = e
      break
    }
  }
  const enter = g.exit_enter as Exit
  if (!_exit && g.in_safe_encounter && (enter.exitNum & 0xf0) === g.EXIT_DIR_MID) {
    // Shorter walk distance to get back to ow
    const _DIST = 0xa0
    if (self.x < enter.xc - _DIST || self.x >= enter.xc + _DIST) {
      for (const e of world.instancesOf(Exit)) {
        if (e.exitNum & (g.EXIT_DIR_LEFT | g.EXIT_DIR_RIGHT)) {
          _exit = e
          break
        }
      }
      if (_exit) {
        self.hspd = 0
        g.exit_leave = _exit
        sdm('exit side')
        return
      }
    }
  }
  // Just in case player is outside of exit hb once they get low enough
  const pending = g.exit_leave_pending as Exit | null
  if (!_exit && !g.exit_leave && pending && gmBool(pending.open) && pending.side & 0x4) {
    if (self.yb < cam_yb_max() - 0x08) {
      // Just in case player somehow moves back upward before getting low enough
      g.exit_leave_pending = NOONE
    } else if (
      (pc_is_fairy() && self.yb >= cam_yb_max() + 0x1c) ||
      (!pc_is_fairy() && self.yb >= cam_yb_max() + 0x38)
    ) {
      _exit = pending
      g.exit_leave = _exit
      sdm('exit down')
      return
    }
  }
  if (_exit) {
    updateCSPoints(self)
    switch (_exit.exit_type & 0xf0) {
      case g.EXIT_TYPE_ELEVATOR: {
        if (self.colliding_elevator && !g.EnterRoom_control_timer) {
          const _DIST = (self.hh >> 2) * 3 - 1
          if (
            (_exit.side & pcInput.vHeld && !inRange(self.yb, cam_yt_min(), cam_yb_max() + _DIST)) ||
            (_exit.side & pcInput.hHeld && !ocsH4(self))
          ) {
            // D901
            set_xy(self, 0x78, self.y)
            g.exit_leave = _exit
            sdm('exit elevator')
          }
        }
        break
      }
      case g.EXIT_TYPE_PIPE: {
        // E0C5. Darunia roof chimney exit.
        if (
          pcInput.dHeld &&
          !(input.held_0 & input.D) && // Has released 'down' since spawning
          !self.ogr && // is on ground
          wINwAll(self.x - 8, 0x10, _exit.xl, _exit.ww) // MOD. So spr won't stick out sides of chimney
        ) {
          // E0E2
          self.pipe_sink_timer = 37 // timer. Will exit rm at 0
          g.exit_leave = _exit
          sdm('exit pipe')
        }
        break
      }
      case g.EXIT_TYPE_DOOR: {
        if (
          input.Up_held && // is holding up
          !self.ogr && // is on ground
          !(input.held_0 & input.U) && // Has released 'up' since spawning
          self.cp1Y >> 3 === (_exit.yt + _exit.hh) >> 3 && // PC level with door bottom
          inRange(self.x, _exit.xl + 3, _exit.xl + _exit.ww - 3) // PC center x enough inside door
        ) {
          g.exit_leave = _exit
          sdm('exit door')
        }
        break
      }
      case g.EXIT_TYPE_STANDARD: {
        // E14A. No condition to use exit
        if (_exit.side & 0x3) {
          // SIDE (RIGHT & LEFT)
          if (!(g.view_lock_boss & (_exit.side & 0x3)) && !g.EnterRoom_control_timer) {
            if (!ocsH4(self) || !inRange(self.x, 0, g.rm_w - 1)) {
              // E173
              self.hspd = 0
              g.exit_leave = _exit
              sdm('exit side')
            }
          }
          break
        }
        if (_exit.side & 0x4) {
          // E19E.  BOTTOM
          if (!g.exit_leave_pending) g.exit_leave_pending = _exit
          if (
            (pc_is_fairy() && self.yb >= cam_yb_max() + 0x1c) ||
            (!pc_is_fairy() && self.yb >= cam_yb_max() + 0x38)
          ) {
            g.exit_leave = g.exit_leave_pending ? g.exit_leave_pending : _exit
            sdm('exit down')
          }
          break
        }
        break
      }
    }
  }
}

export { is_exit_type }
