/**
 * Seams for the player port: scripts owned by folders not ported yet, and the dev-only debug draws.
 * Each is `notPorted` (throws) or a no-op hook that later ports/tests replace.
 */

import { g } from '../../../runtime/world'
import { update_explored_data as gui_update_explored_data } from '../../gui/PauseMenu'
import { type AnyFn, notPorted } from '../../pending'
import type { GameObject } from '../classes'

/** Cross-folder scripts the player calls; owners re-point these when ported (tests may stub). */
export const pcHooks = {
  /** `Elevator_update_1()` — runs in the colliding elevator's scope (gob2/elevator, not ported). */
  Elevator_update_1: notPorted('Elevator_update_1') as (elevator: GameObject) => void,
  /** `update_explored_data()` (pause-menu map data, not ported). */
  update_explored_data: (() => gui_update_explored_data(g.PAUSE_MENU as never)) as AnyFn,
}

/** Dev-only overlays called from `PC_draw` when `g.DevTools_state` (dev folder, ported later). */
export const devDraw = {
  GO_draw_body_hb: (_self: GameObject): void => {},
  GO_draw_sword_hb: (_self: GameObject): void => {},
  GO_draw_shield_hb: (_self: GameObject): void => {},
  GO_draw_ocs: (_self: GameObject): void => {},
  GO_draw_cs_points: (_self: GameObject): void => {},
  PC_draw_scs: (_self: GameObject): void => {},
  PC_draw_hp: (_self: GameObject): void => {},
  GO_draw_sprite_outline: (_self: GameObject): void => {},
}
