/** GML: udp_OptionsMenu() */
export function udp_OptionsMenu(self: OptionsMenu) {
  switch (self.menu_state) {
    default: {
      self.draw_clms_count = self.Main_CLMS
      break
    }
    case self.menu_state_INPUT_CONFIG: {
      self.draw_clms_count = self.InputConfig_CLMS
      break
    }
  }
  switch (self.menu_state) {
    default: {
      self.draw_rows_max = self.Main_ROWS
      break
    }
    case self.menu_state_INPUT_CONFIG: {
      self.draw_rows_max = self.InputConfig_ROWS
      break
    }
  }
  if (self.anim_frame === self.ANIM_FRAMES_DEF) {
    self.draw_rows_count = self.draw_rows_max
  } else {
    self.draw_rows_count = self.anim_frame << 1
  }
  self.drawX = ((g.view_xl_og + 0x28) >> 4) << 4
  self.drawX = clamp(
    self.drawX,
    ((viewXL() >> 3) << 3) + (0x04 << 3),
    ((viewXR() >> 3) << 3) - (0x04 << 3) - (self.draw_clms_count << 3),
  )
  self.drawY = viewYT() + self.viewYT_OFF
  self.MenuWindow_w = self.draw_clms_count << 3
  self.MenuWindow_h = self.draw_rows_count << 3
  self.MenuWindow_xl = self.drawX
  self.MenuWindow_xr = self.MenuWindow_xl + self.MenuWindow_w
  self.MenuWindow_yt = self.drawY
  self.MenuWindow_yb = self.MenuWindow_yt + self.MenuWindow_h
  self.Cursor_xl = self.drawX
  self.Cursor_xl += 0x08 // window border
  self.Cursor_xl += 0x04 // pad
  self.Cursor_xl -= 0x02 // micro adjustment
  self.TextArea1_xl = self.Cursor_xl
  self.TextArea1_xl += 0x08 // bottle sprite width
  self.TextArea1_xl += 0x02 // pad
  //TextArea1_xr  = TextArea1_xl;
  //TextArea1_xr += 0;
  self.TextArea2_xr = self.drawX + self.MenuWindow_w
  self.TextArea2_xr -= 0x08 // window border
  self.TextArea2_xr -= 0x04 // pad
  //TextArea2_xl  = TextArea2_xr;
  //TextArea2_xl -= Font2_CHAR_SIZE * 4; // dist of 4 chars
  self.Info_Divider_can_draw =
    self.menu_state === self.menu_state_MAIN ||
    self.menu_state === self.menu_state_DEV_TOOLS ||
    self.menu_state === self.menu_state_RANDO ||
    self.menu_state === self.menu_state_OTHER
  self.Info_Divider_row = self.draw_rows_max - 0x06
  self.Info_Divider_yt = self.drawY + (self.Info_Divider_row << 3)
  self.Info_xl = self.TextArea1_xl
  self.Info_xr = self.MenuWindow_xr
  self.Info_xr -= 0x08 // window border
  self.Info_xr -= 0x08 // pad
  self.Info_yt = self.Info_Divider_yt
  self.Info_yt += 0x08 // divider bar
  self.Info_yt += 0x01 // pad
}

