/** GML: OptionsMenu_AudioCustom_refresh_indicator_states() */
export function OptionsMenu_AudioCustom_refresh_indicator_states(self: OptionsMenu) {
  let _i: any, _j: any, _count1: any, _count2: any, _theme: any, _set: any, _DK1: any, _dm: any

  withOther(Audio, self, (_audio, other) => {
    _DK1 = `_Indicator${STR_State}`
    _dm = ds_map_create()
    _dm.set('_All_On', 1)
    _dm.set('_All_Off', 1)
    for (_i = 0; _i < Audio.AudioSets_COUNT; _i++) {
      _set = Audio.dl_AUDIO_SETS.get(_i)
      _dm.set(`${_set}_All_On`, 1)
      _dm.set(`${_set}_All_Off`, 1)
    }
    _count1 = val(Audio.dm.get(STR_Theme + STR_Count + STR_Music))
    // Each theme with at least 1 mus track
    for (_i = 1; _i <= _count1; _i++) {
      _theme = Audio.dm.get(STR_Theme + STR_Music + hex_str(_i))
      if (!is_undefined(_theme)) {
        _dm.set(`${_theme}_All_On`, 1)
        _dm.set(`${_theme}_All_Off`, 1)
      }
      _count2 = val(Audio.dm.get(_theme + STR_Track + STR_Count + STR_Music))
      for (_j = 1; _j <= _count2; _j++) {
        _set = Audio.dm.get(_theme + STR_Track + STR_Music + hex_str(_j) + STR_Set)
        if (gmb(val(Audio.dm_random_custom.get(_theme + hex_str(_j) + STR_Qualified)))) {
          _dm.set('_All_Off', 0)
          if (!is_undefined(_set) && is_string(_set)) {
            _dm.set(`${_set}_All_Off`, 0)
          }
          if (!is_undefined(_theme)) {
            _dm.set(`${_theme}_All_Off`, 0)
            other.dm_AudioCustom.set(_DK1 + _theme + hex_str(_j), 2)
          }
        } else {
          _dm.set('_All_On', 0)
          if (!is_undefined(_set) && is_string(_set)) {
            _dm.set(`${_set}_All_On`, 0)
          }
          if (!is_undefined(_theme)) {
            _dm.set(`${_theme}_All_On`, 0)
            other.dm_AudioCustom.set(_DK1 + _theme + hex_str(_j), 0)
          }
        }
      }
    }
    for (_i = 0; _i < Audio.AudioSets_COUNT; _i++) {
      _set = Audio.dl_AUDIO_SETS.get(_i)
      other.dm_AudioCustom.set(
        _DK1 + _set,
        +!gmb(val(_dm.get(`${_set}_All_Off`))) + val(_dm.get(`${_set}_All_On`)),
      )
    }
    _count1 = val(Audio.dm.get(STR_Theme + STR_Count + STR_Music))
    for (_i = 1; _i <= _count1; _i++) {
      _theme = Audio.dm.get(STR_Theme + STR_Music + hex_str(_i))
      if (!is_undefined(_theme)) {
        other.dm_AudioCustom.set(
          _DK1 + _theme,
          +!gmb(val(_dm.get(`${_theme}_All_Off`))) + val(_dm.get(`${_theme}_All_On`)),
        )
      }
    }
    other.dm_AudioCustom.set(`${_DK1}_ToggleAll`, +!gmb(val(_dm.get('_All_Off'))) + val(_dm.get('_All_On')))
    ds_map_destroy(_dm)
    _dm = undefined
  })
}
