/**
 * Ported from ZALiA's `tile` IDE folder: `tile_add_`, `tile_add_2a`, `tile_delete_`, `tile_layer_delete_`,
 * `tile_layer_get_tsrc`, `tile_find_depth_by_tsrc`, `tile_change_1a/2a/3a`, `tile_anim_change_frame`,
 * `tile_hidden_update_1a/1b/2a`, `tile_visibility`, `tile_delete_all`, `break_block`.
 *
 * "tsrc" = tile source: `((top>>3)<<4) | (left>>3)` — row/column of an 8×8 tile inside a 16×16-tile
 * tileset image (256 tiles, matching Tiled's firstgid spacing of 256).
 *
 * Dropped: `dev_update_tile_marker_layer` (dev-only tile-marker overlay maintenance in `tile_change_1a`);
 * the marker tiles added on scene load are kept (hidden) so the dev tools can still show them.
 */
import {
  dk_BlockBreak,
  STR_Anim,
  STR_Depth,
  STR_HIDDEN,
  STR_rc_offset,
  STR_Solid,
  STR_Tileset,
  STR_TSRC,
  STR_unique,
  TID_BREAK1,
  TID_BREAK2,
  TID_BREAK3,
  TID_BREAK4,
  TID_HIDE_1,
  TID_HIDE_2,
  TID_LQUID1,
  TID_LQUID2,
} from '@z2/data'
import { hexStr as hex_str } from '../../nes/hexStr'
import { gmBool, isVal } from '../../nes/math8'
import { G, g, world } from '../../runtime/world'
import { is_in_grid } from '../collision/geometry'
import type { TileAnimFrame } from './tileData'
import {
  background_exists,
  background_get_name,
  tile_add,
  tile_delete,
  tile_exists,
  tile_get_background,
  tile_get_depth,
  tile_get_ids,
  tile_get_ids_at_depth,
  tile_get_left,
  tile_get_top,
  tile_layer_delete,
  tile_layer_find,
  tile_set_visible,
} from './tileWorld'

/** Seams for scripts outside this folder. `play_theme_sound` defaults to emitting the theme datakey. */
export const tileHooks = {
  /** `aud_play_sound(get_audio_theme_track(dk))` */
  play_theme_sound: (dk: string): void => {
    world.emit({ kind: 'sound', sound: dk })
  },
}

const sortDesc = (l: { items: number[] }) => l.items.sort((a, b) => b - a)

/** `tile_add_(background, left, top, width, height, x, y, depth)` — GM tile_add + pal-swap/anim bookkeeping. */
export function tile_add_(
  bg: string,
  left: number,
  top: number,
  w: number,
  h: number,
  x: number,
  y: number,
  depth: number,
): number {
  if (g.tile_pal_swap_ver === 1) {
    if (g.dl_TILE_DEPTHS.findIndex(depth) !== -1 && g.dl_pal_swap_depths.findIndex(depth) === -1) {
      g.dl_pal_swap_depths.add(depth)
      sortDesc(g.dl_pal_swap_depths) // false: descending
    }
  }
  if (gmBool(g.BackgroundTileAnimations_VER)) {
    const _TS_NAME = background_get_name(bg)
    if (g.dm_TILE_ANIM.val(_TS_NAME + STR_Tileset) === bg && g.dl_scene_anims.findIndex(_TS_NAME) === -1) {
      g.dl_scene_anims.add(_TS_NAME)
    }
  }
  return tile_add(bg, left, top, w, h, x, y, depth) // returns tile id
}

/**
 * `tile_add_2a(depth, room x, room y, tileset, tileset rc, *hidden type)` — lightweight `tile_change_1a`
 * for room entry.
 */
export function tile_add_2a(
  depth: number,
  x: number,
  y: number,
  tileset: string,
  tsrc: number,
  hidden = -1,
): number {
  const _TILE_ID = tile_add_(tileset, ((tsrc >> 0) & 0xf) << 3, ((tsrc >> 4) & 0xf) << 3, 8, 8, x, y, depth)
  if (hidden !== -1 && _TILE_ID !== -1 && tile_exists(_TILE_ID)) {
    tile_hidden_update_1a(_TILE_ID, hidden)
  }
  return _TILE_ID
}

/** `tile_delete_(tile id)` — also retires the depth from the pal-swap list when it empties. */
export function tile_delete_(id: number): void {
  if (!tile_exists(id)) return
  if (g.tile_pal_swap_ver === 1) {
    const _DEPTH = tile_get_depth(id)
    if (g.dl_TILE_DEPTHS.findIndex(_DEPTH) !== -1 && g.dl_pal_swap_depths.findIndex(_DEPTH) !== -1) {
      if (tile_get_ids_at_depth(_DEPTH).length === 1) {
        g.dl_pal_swap_depths.delete(g.dl_pal_swap_depths.findIndex(_DEPTH))
        sortDesc(g.dl_pal_swap_depths)
      }
    }
  }
  tile_delete(id)
}

/** `tile_layer_delete_(depth)` */
export function tile_layer_delete_(depth: number): void {
  if (g.tile_pal_swap_ver === 1) {
    if (g.dl_TILE_DEPTHS.findIndex(depth) !== -1 && g.dl_pal_swap_depths.findIndex(depth) !== -1) {
      g.dl_pal_swap_depths.delete(g.dl_pal_swap_depths.findIndex(depth))
      sortDesc(g.dl_pal_swap_depths)
    }
  }
  tile_layer_delete(depth)
}

const tsrcOf = (id: number) => ((tile_get_top(id) >> 3) << 4) | (tile_get_left(id) >> 3)

/** `tile_layer_get_tsrc(depth, x, y)` — tsrc of the tile at the position, or -1. */
export function tile_layer_get_tsrc(depth: number, x: number, y: number): number {
  const id = tile_layer_find(depth, x, y)
  return id + 1 ? tsrcOf(id) : id
}

/** `tile_find_depth_by_tsrc(clm, row, tileset, tsrc, *tsrc..)` — first pal-swap depth holding one of the tsrcs. */
export function tile_find_depth_by_tsrc(
  clm: number,
  row: number,
  tileset: string,
  ...tsrcs: number[]
): number {
  const _X = clm << 3
  const _Y = row << 3
  for (let _i = g.dl_pal_swap_depths.size - 1; _i >= 0; _i--) {
    const _depth = g.dl_pal_swap_depths.get(_i) as number
    const _tile_id = tile_layer_find(_depth, _X, _Y)
    if (_tile_id === -1 || tile_get_background(_tile_id) !== tileset) continue
    const _tsrc = tsrcOf(_tile_id)
    for (const t of tsrcs) if (_tsrc === t) return _depth
  }
  return -1
}

/**
 * `tile_change_1a(depth, x, y, tileset, tileset grid xy, *solid type, *unique type, *hidden type)`
 * changes 1 8x8 tile in the room. `tileset` -1 = don't touch the graphic, 0 = no graphic.
 */
export function tile_change_1a(
  depth: number,
  x: number,
  y: number,
  tileset: string | number,
  tsrc: number,
  _SOLID = -1,
  _unique = -1,
  _HIDDEN = -1,
): number {
  if (x >> 3 < 0 || x >> 3 >= g.rm_clms || y >> 3 < 0 || y >> 3 >= g.rm_rows) return -1
  if (_SOLID !== -1) G.dg_solid.set(x >> 3, y >> 3, _SOLID)
  if (gmBool(_unique) && !(_unique >> 8)) {
    const _IDX = g.dl_TILE_DEPTHS.findIndex(depth)
    if (_IDX !== -1) _unique = (_IDX << 8) | (_unique & 0xff)
  }
  if (_unique !== -1 && _unique & 0xff) {
    if (isVal(_unique & 0xff, TID_BREAK1, TID_BREAK2, TID_BREAK3, TID_BREAK4))
      g.dg_RmTile_Break.set(x >> 3, y >> 3, _unique)
    else if (isVal(_unique & 0xff, TID_LQUID1, TID_LQUID2)) g.dg_RmTile_Liquid.set(x >> 3, y >> 3, _unique)
  }
  let _tile_id = -1
  if (tileset !== -1) {
    // tileset: -1 means don't delete or add tile
    // ** NOTE ** tile_layer_find() seems to be a big contributor to the delay when entering a large rm.
    _tile_id = tile_layer_find(depth, x, y)
    tile_delete_(_tile_id)
    if (background_exists(tileset)) {
      // tileset: 0 means no graphic
      _tile_id = tile_add_(tileset, ((tsrc >> 0) & 0xf) << 3, ((tsrc >> 4) & 0xf) << 3, 8, 8, x, y, depth)
    }
  }
  if (_tile_id !== -1 && _HIDDEN !== -1) tile_hidden_update_1a(_tile_id, _HIDDEN)
  return _tile_id
}

/** `tile_change_2a(size 8 or 16, ts, tsrc, x, y, depth, 1:add -1:delete 0:both)` */
export function tile_change_2a(
  size: number,
  ts: string,
  tsrc: number,
  x: number,
  y: number,
  depth: number,
  mode: number,
): number {
  if (!gmBool(mode)) {
    // mode: if <= 0, will delete underlying tile
    const _TILE_ID = tile_layer_find(depth, x, y)
    tile_delete_(_TILE_ID)
    if (mode < 0) return _TILE_ID // < 0 will skip add tile
  }
  size = Math.min(0x10, Math.max(0x08, size & 0x18)) // TILE SIZE
  const shift = (size >> 3) + 2 // 3 or 4
  const _TS_X = ((tsrc >> 0) & 0xf) << shift
  const _TS_Y = ((tsrc >> 4) & 0xf) << shift
  return tile_add_(ts, _TS_X, _TS_Y, size, size, x, y, depth)
}

/** `tile_change_3a(...)` — as 2a but with the raw GM builtins (no pal-swap bookkeeping). */
export function tile_change_3a(
  size: number,
  ts: string,
  tsrc: number,
  x: number,
  y: number,
  depth: number,
  mode: number,
): number {
  if (!gmBool(mode)) {
    const _TILE_ID = tile_layer_find(depth, x, y)
    if (tile_exists(_TILE_ID)) tile_delete(_TILE_ID)
    if (mode < 0) return _TILE_ID
  }
  size = Math.min(0x10, Math.max(0x08, size & 0x18))
  const shift = (size >> 3) + 2
  return tile_add(ts, ((tsrc >> 0) & 0xf) << shift, ((tsrc >> 4) & 0xf) << shift, size, size, x, y, depth)
}

/** `tile_anim_change_frame(anim num, map key, rm clm, rm row)` — apply one animation frame's tiles. */
export function tile_anim_change_frame(_ANIM_NUM: number, mapKey: string, _CLM: number, _ROW: number): void {
  const _dm_frame = g.dm_tile.get(mapKey) as TileAnimFrame | undefined
  if (_dm_frame === undefined) return
  for (let _i = 0; _i < g.rm_tile_count; _i++) {
    const _datakey = hex_str(_i)
    let _depth = _dm_frame[_datakey + STR_Depth] as number | undefined
    if (_depth === undefined) break
    if (_depth === -1) _depth = g.dg_tile_anim.get(_ANIM_NUM, 6) as number
    const _rc_off = (_dm_frame[_datakey + STR_rc_offset] ?? 0) as number
    const _ts = (_dm_frame[_datakey + STR_Tileset] ?? 0) as string | number
    const _tsrc = (_dm_frame[_datakey + STR_TSRC] ?? 0) as number
    const _solid = (_dm_frame[_datakey + STR_Solid] ?? 0) as number
    let _unique = (_dm_frame[_datakey + STR_unique] ?? 0) as number
    const _hide = (_dm_frame[_datakey + STR_HIDDEN] ?? 0) as number
    const _idx = g.dl_TILE_DEPTHS.findIndex(_depth)
    if (_idx !== -1) _unique = (_idx << 8) | (_unique & 0xff)
    const _clm = _CLM + ((_rc_off >> 0) & 0xff)
    const _row = _ROW + ((_rc_off >> 8) & 0xff)
    tile_change_1a(_depth, _clm << 3, _row << 3, _ts, _tsrc, _solid, _unique, _hide)
  }
}

/** `tile_hidden_update_1a(tile id, hide value)` — register/clear a tile's conditional-hide value. */
export function tile_hidden_update_1a(_TILE_ID: number, _HIDE_NEW: number): void {
  if (_TILE_ID < 0) return
  const _DATAKEY = String(_TILE_ID)
  const _IDX = g.dl_hidden_tiles.findIndex(_TILE_ID)
  if (!tile_exists(_TILE_ID) || _HIDE_NEW === 0) {
    // tid doesn't exist, or give it NO hidden value
    if (g.dm_hidden_tiles.get(_DATAKEY) !== undefined) g.dm_hidden_tiles.delete(_DATAKEY)
    if (_IDX !== -1) g.dl_hidden_tiles.delete(_IDX)
    if (tile_exists(_TILE_ID)) tile_set_visible(_TILE_ID, true)
  } else if (gmBool(_HIDE_NEW)) {
    g.dm_hidden_tiles.set(_DATAKEY, _HIDE_NEW)
    if (_IDX === -1) g.dl_hidden_tiles.add(_TILE_ID)
    tile_hidden_update_1b(_TILE_ID, _HIDE_NEW)
  }
}

/** `tile_hidden_update_1b(tile id, hide value)` */
export function tile_hidden_update_1b(id: number, hide: number): void {
  if (tile_exists(id)) tile_set_visible(id, tile_visibility(hide))
}

/** `tile_hidden_update_2a()` — re-evaluate every tile with a hide value (e.g. after room brightness changes). */
export function tile_hidden_update_2a(): void {
  const copy = [...g.dl_hidden_tiles] as number[]
  for (const _tile_id of copy) {
    if (tile_exists(_tile_id))
      tile_hidden_update_1a(_tile_id, g.dm_hidden_tiles.val(String(_tile_id)) as number)
    else tile_hidden_update_1a(_tile_id, 0)
  }
}

/**
 * `tile_visibility(hide value)` — bits: `TID_HIDE_1&$F` hidden if room is NOT lit, `TID_HIDE_2&$F` hidden
 * if room IS lit.
 */
export function tile_visibility(hide: number): boolean {
  if (g.rm_brightness >= 1) return !(hide & (TID_HIDE_2 & 0xf)) // Hidden when room IS lit
  return !(hide & (TID_HIDE_1 & 0xf)) // Hidden when room is NOT lit
}

/** `tile_delete_all()` — delete all tiles in the room. */
export function tile_delete_all(): void {
  const ids = tile_get_ids()
  for (let _i = ids.length - 1; _i >= 0; _i--) tile_delete_(ids[_i] as number)
}

/** `break_block(clm, row)` — E23A. break block: start the break animation in a free anim slot. */
export function break_block(_CLM: number, _ROW: number): void {
  if (!is_in_grid(_CLM, _ROW, g.rm_clms, g.rm_rows)) return
  const _DEPTH = g.dl_TILE_DEPTHS.get((g.dg_RmTile_Break.get(_CLM, _ROW) as number) >> 8)
  for (let _i = g.dg_tile_anim.width - 1; _i >= 0; _i--) {
    if (
      isVal(g.dg_tile_anim.get(_i, 0), TID_BREAK1, TID_BREAK3) && // 0: anim num/type
      !gmBool(g.dg_tile_anim.get(_i, 1) as number) // 1: counter
    ) {
      g.dg_tile_anim.set(_i, 0, (g.dg_RmTile_Break.get(_CLM, _ROW) as number) & 0xff) // should only be TID_BREAK1 or TID_BREAK3
      g.dg_tile_anim.set(_i, 1, 1) // set counter
      g.dg_tile_anim.set(_i, 3, 1) // set frame num
      g.dg_tile_anim.set(_i, 5, (_ROW << 8) | _CLM)
      g.dg_tile_anim.set(_i, 6, _DEPTH)
      // remove solid & unique right away
      for (let _j = 0; _j < 4; _j++) {
        const _clm = _CLM + (_j & 1)
        const _row = _ROW + (_j > 1 ? 1 : 0)
        G.dg_solid.set(_clm, _row, 0)
        g.dg_RmTile_Break.set(_clm, _row, 0)
      }
      break
    }
  }
  tileHooks.play_theme_sound(dk_BlockBreak)
}
