// Ported from ZALiA scripts/cast_spell.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively

import {
  SPL_FARY,
  SPL_RFLC,
  SPL_SPEL,
  SPL_SUMM,
  SPL_THUN,
  STR_Cast,
  STR_Spell,
  TID_ONEWY1,
  TID_SOLID1,
} from '@z2/data'
import { gmBool } from '../../nes/math8'
import { G, g, p } from '../../runtime/world'
import { GO_update_cs } from '../collision/cs'
import { collide_solid_grid, find_row_solid } from '../collision/solid'
import { set_xy } from '../game_object/go/movement'
import { frameHooks } from '../hooks'
import { notPorted } from '../pending'
import { aud_play_combo1, aud_play_sound, get_audio_theme_track } from '../sound'
import { ds_list_add, withInstance } from './gm'

const PC_update_1a = (...a: unknown[]) => (frameHooks.PC_update_1a as (...x: unknown[]) => unknown)(...a)

/** GML: cast_spell(spell) */
export function cast_spell(...argument: any[]) {
  // GML `var` is function-scoped; locals hoisted here:
  let _DURATION: any, _ROW_ABOVE: any, _ROW_UNDER: any, _SPELL_CAST: any, _TO_HUMAN: any
  /* TODO with */ withInstance(g, (_self) => {
    _SPELL_CAST = argument[0]
    g.spell_cast_this_frame = _SPELL_CAST
    g.spell_selected = _SPELL_CAST
    g.spells_active |= _SPELL_CAST
    ds_list_add(g.dl_spell_history, _SPELL_CAST)
    g.spell_ready = 0
    _DURATION = p.SpellFlash_DURATION1 // SpellFlash_DURATION1=$20
    p.Flash_Pal_timer = _DURATION
    if (gmBool(_SPELL_CAST & (SPL_RFLC | SPL_SPEL | SPL_THUN | SPL_SUMM))) {
      p.Flash_Bgr_timer = _DURATION
    }
    p.SpellReady_flash_timer = _DURATION
    p.SpellFlash_PC_timer = _DURATION
    if (gmBool(_SPELL_CAST & SPL_FARY)) {
      _TO_HUMAN = false
      if (gmBool(g.CuccoSpell2_Acquired) && gmBool(g.CuccoSpell2_Option)) {
        g.CuccoSpell2_Active = !g.CuccoSpell2_Active
        if (!gmBool(g.CuccoSpell2_Active)) {
          _TO_HUMAN = true
          /* TODO with */ withInstance(G.pc, (self) => {
            _ROW_UNDER = self.yb >> 3
            _ROW_UNDER = find_row_solid(TID_SOLID1 | TID_ONEWY1, self.x >> 3, _ROW_UNDER, 1, 0, _ROW_UNDER)
            _ROW_ABOVE = find_row_solid(TID_SOLID1, self.x >> 3, _ROW_UNDER - 1, -1, 0, 0)
            //sdm("_ROW_UNDER $"+hex_str(_ROW_UNDER)+", _ROW_ABOVE $"+hex_str(_ROW_ABOVE)+", _ROW_UNDER-_ROW_ABOVE $"+hex_str(_ROW_UNDER-_ROW_ABOVE));
            if (_ROW_UNDER - _ROW_ABOVE <= 4) {
              //sdm("yb>>3 $"+hex_str(yb>>3)+", _ROW_UNDER $"+hex_str(_ROW_UNDER)+", _ROW_ABOVE $"+hex_str(_ROW_ABOVE));
              self.TransformHumanClipCorrect_timer = 0x18
            }
            set_xy(self, self.x, self.y - 8) // FIXED: bare `x`/`y` inside a GML `with(...)` is the *scoped instance's*, not `g`'s
          })
          g.spells_active &= ~SPL_FARY
        }
      }
      /* TODO with */ withInstance(G.pc, (self) => {
        // set properties specific to PC's form(cucco, fairy, Lonk)
        self.is_cucco = true
        PC_update_1a()
        self.Cucco_damage_taken = 0
        self.Cucco_damaged_count = 0
        self.Cucco_rage_timer = 0
        self.Cucco_rage_state = 0
        if (
          !gmBool(g.CuccoSpell2_SolidClip_exploit) &&
          gmBool(_TO_HUMAN) &&
          !gmBool(self.TransformHumanClipCorrect_timer)
        ) {
          GO_update_cs(self)
          if (
            gmBool(collide_solid_grid(self.csRgt1X, self.csRgt1Y)) ||
            gmBool(collide_solid_grid(self.csRgt2X, self.csRgt2Y))
          ) {
            if (
              gmBool(collide_solid_grid(self.csBtm2X, self.csBtm2Y)) &&
              gmBool(collide_solid_grid(self.csBtm2X, self.csBtm2Y - 8))
            ) {
              set_xy(self, self.x - ((self.csBtm2X & 0x07) + 1), self.y)
              GO_update_cs(self)
            }
          } else {
            if (
              gmBool(collide_solid_grid(self.csLft1X, self.csLft1Y)) ||
              gmBool(collide_solid_grid(self.csLft2X, self.csLft2Y))
            ) {
              if (
                gmBool(collide_solid_grid(self.csBtm1X, self.csBtm1Y)) &&
                gmBool(collide_solid_grid(self.csBtm1X, self.csBtm1Y - 8))
              ) {
                set_xy(self, self.x + (8 - (self.csBtm1X & 0x07)), self.y)
                GO_update_cs(self)
              }
            }
          }
        }
      })
    }
    // NOTE: This snd should be interrupted when casting a spell.
    aud_play_sound(get_audio_theme_track(STR_Cast + STR_Spell))
    // MOD. Give THUNDER a sound
    if (gmBool(_SPELL_CAST & SPL_THUN)) {
      aud_play_combo1(0x10)
    }
  })
}
