/**
 * Draw wrappers used by the screen controllers — ported from ZALiA `scripts/draw/draw_sprite_.gml`,
 * `draw_text_.gml`, `draw_rect_.gml`, `draw_text_plus.gml`, `draw_spr_aligned.gml` (the `draw` IDE folder
 * has no owner yet; these live here until it is ported). Commands go to the current *surface target* if one
 * is set (see `surface.ts`), else to `world.draw`.
 *
 * DrawCmd extensions the adapter must honour (added as optional fields via cast, runtime types are shared):
 *  - sprite `tint?: number` — GM `draw_sprite_ext` colour (used for black silhouettes)
 *  - `{ kind: 'tile', tileset, left, top, w, h, x, y, xscale, yscale, palIdx, depth }` — `draw_background_part(_ext)`
 *  - `{ kind: 'point', x, y, color, depth }` — `draw_point_colour`
 * Text: `'#'` in a string is a newline (two rows) and unknown glyphs draw `spr_Text_WrongChar`, as in `draw_text_`.
 *
 * Colour: these wrappers take colours in GameMaker's `$BBGGRR` packing, exactly as the GML passes them
 * (`c_red = $0000FF`, `p.C_GRN2 = $48DC4C`), and convert with `bgrToRgb()` on the way into the command list —
 * `DrawCmd.color` / `DrawCmd.tint` are 24-bit RGB, the same contract `palette_image.palettes` already keeps.
 * The conversion cannot live in `pushCmd`: `draw_surface()` replays recorded commands through it (surface.ts).
 */
import { FONT_LAYOUT } from '@z2/data'
import type { DrawCmd } from '../../runtime/draw'
import { G, p, world } from '../../runtime/world'
import { spr_x_at_x, spr_y_at_y } from '../graphics/index'
import { sprite_get_height, sprite_get_width } from '../graphics/sprites'
import { bgrToRgb } from '../palette/colors'
import { pal_swap_reset, pal_swap_set } from '../palette/scenePalette'
import { currentSurface } from './surface'

/** Depth used for screen-controller draws (screen objects have depth 0 in ZALiA). */
export const drawState = { depth: 0 }

export type AnyDrawCmd = DrawCmd | Record<string, unknown>

/**
 * Record one draw command, filling in the *global* palette swap.
 *
 * GML's `pal_swap_set` sets shader state, not a per-draw argument: everything drawn until `pal_swap_reset`
 * goes through it, which is why `GO_draw_sprite.gml:12` passes `-1` for the palette index and why
 * `draw_text_plus.gml` sets the swap once around a whole paragraph. The port carries the index on each
 * command instead, so a command that names none (`palIdx === -1`) inherits whatever swap is active — the
 * same rule `draw_surface` was already applying by hand at replay time.
 */
export function pushCmd(cmd: AnyDrawCmd): void {
  const c = cmd as { palIdx?: number }
  if (c.palIdx === -1 && p.palSwapIdx >= 0) c.palIdx = p.palSwapIdx
  const s = currentSurface()
  if (s) s.cmds.push(cmd)
  else world.draw.push(cmd as DrawCmd)
}

/** `draw_sprite_(sprite, sub image, x, y, *pal index, *xscale, *yscale, *color, *alpha, *rotation)` */
export function draw_sprite_(
  sprite: string | 0 | undefined,
  subimg: number,
  x: number,
  y: number,
  palIdx = -1,
  xscale = 1,
  yscale = 1,
  color = -1,
  alpha = 1,
): void {
  if (!sprite) return // !!!!!!!!!!!!!!!!!!!!!!
  // GML: `if (argument[4] && argument[4] < global.palette_image_w) pal_swap_set(...)` … draw …
  // `if (argument[4] && …) pal_swap_reset()`. Both halves matter: an in-range index goes through the global
  // shader state (so `use_pal_swap` can switch it off) and *clears* it afterwards, while a `-1` neither
  // sets nor resets — the sprite is drawn through whatever swap the caller set, which is the idiom 16
  // enemy draw scripts use (`pal_swap_set(palidx); GO_draw_sprite(spr)`).
  const swap = palIdx > 0.5 && (G.palette_image_w === undefined || palIdx < G.palette_image_w)
  if (swap) pal_swap_set(palIdx)
  pushCmd({
    kind: 'sprite',
    sprite,
    frame: subimg,
    x,
    y,
    xscale,
    yscale,
    palIdx: -1,
    depth: drawState.depth,
    alpha,
    ...(color >= 0 ? { tint: bgrToRgb(color) } : {}),
  })
  if (swap) pal_swap_reset()
}

/** `draw_sprite(sprite, subimg, x, y)` — GM builtin without palette swap. */
export function draw_sprite(sprite: string, subimg: number, x: number, y: number): void {
  pushCmd({
    kind: 'sprite',
    sprite,
    frame: subimg,
    x,
    y,
    xscale: 1,
    yscale: 1,
    palIdx: -1,
    depth: drawState.depth,
    alpha: 1,
  })
}

/** `draw_rect_(color, x, y, w, h, *alpha, *outline)` — x2/y2 are inclusive-1 as in ZALiA. */
export function draw_rect_(
  color: number,
  x: number,
  y: number,
  w: number,
  h: number,
  alpha = 1,
  outline: boolean | number = false,
): void {
  pushCmd({
    kind: 'rect',
    x1: x,
    y1: y,
    x2: x + w - 1,
    y2: y + h - 1,
    color: bgrToRgb(color),
    depth: drawState.depth,
    alpha,
    outline: !!outline,
  })
}

/** `draw_point_colour(x, y, colour)` */
export function draw_point_colour(x: number, y: number, color: number): void {
  pushCmd({ kind: 'point', x, y, color: bgrToRgb(color), depth: drawState.depth })
}

/** `draw_background_part_ext(ts, left, top, w, h, x, y, xscale, yscale, colour, alpha)` (tileset tile draw) */
export function draw_background_part_ext(
  tileset: string,
  sx: number,
  sy: number,
  w: number,
  h: number,
  x: number,
  y: number,
  xscale = 1,
  yscale = 1,
  _color = -1,
  alpha = 1,
): void {
  pushCmd({
    kind: 'tile',
    tileset,
    left: sx,
    top: sy,
    w,
    h,
    x,
    y,
    xscale,
    yscale,
    palIdx: -1,
    depth: drawState.depth,
    alpha,
  })
}
export function draw_background_part(
  tileset: string,
  sx: number,
  sy: number,
  w: number,
  h: number,
  x: number,
  y: number,
): void {
  draw_background_part_ext(tileset, sx, sy, w, h, x, y)
}

/** Current font sprite: `global.dl_game_font[|global.game_font_idx]`. */
export function currentFont(): string {
  return (G.dl_game_font.get(G.game_font_idx ?? 0) as string | undefined) ?? 'spr_Font2'
}

/**
 * `draw_text_(XL, YT, text str, *text spr, *palette idx, *color)` — sprite-font text. Uppercased like the GML;
 * `-1` for the text sprite means the current game font; palette index defaults to `global.PI_GUI1`; a colour
 * disables the palette swap.
 */
export function draw_text_(
  XL: number,
  YT: number,
  text: string | number,
  textSpr: string | number = -1,
  palIdx?: number,
  color?: number,
): void {
  const _TEXT = String(text).toUpperCase()
  if (!_TEXT.length) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const font = typeof textSpr === 'string' && textSpr ? textSpr : currentFont()
  let _TEXT_PI: number = palIdx === undefined ? G.PI_GUI1 : palIdx
  let _TEXT_COLOR = -1
  if (color !== undefined) {
    _TEXT_COLOR = color
    _TEXT_PI = -1
  }
  // GML draws each glyph through `draw_sprite_`, so the index follows the same rule: 0 (and -1) mean "no
  // swap of my own" — `draw_text_.gml:17` "Pass -1 to not pal swap (pal swap may have been set outside of
  // draw_text_())" — and an index that *is* used is set and reset per glyph, clearing the ambient swap.
  const swap = _TEXT_PI > 0.5 && (G.palette_image_w === undefined || _TEXT_PI < G.palette_image_w)
  if (swap) pal_swap_set(_TEXT_PI)
  const cmd = {
    kind: 'text',
    font,
    text: _TEXT,
    x: XL,
    y: YT,
    palIdx: -1,
    depth: drawState.depth,
  }
  pushCmd(_TEXT_COLOR >= 0 ? { ...cmd, tint: bgrToRgb(_TEXT_COLOR) } : cmd)
  if (swap) pal_swap_reset()
}

/** Width in pixels `draw_text_` would use for a single-line string with the given font. */
export function textWidth(text: string, font = currentFont()): number {
  return text.length * sprite_get_width(font)
}

/** `draw_text_plus(xl, xr, yt, text, font, *palette idx, *adjust line spacing)` — draw_text_ with word wrap; returns the y below. */
export function draw_text_plus(
  XL: number,
  XR: number,
  YT: number,
  text: string,
  FONT: string,
  PI = 0,
  adjustLineSpacing = 0,
): number {
  const _FONT_W = sprite_get_width(FONT)
  const _FONT_H = sprite_get_height(FONT)
  let _DIST1 = _FONT_H // Leading (vertical dist between yt of each line)
  _DIST1 += 2 // Line padding
  _DIST1 += adjustLineSpacing
  let _xl = XL
  let _yt = YT
  let _text = text
  const END_LINE = (G as unknown as { CHAR_END_LINE3?: string }).CHAR_END_LINE3 ?? '#'
  if (PI) pal_swap_set(PI)
  for (;;) {
    const _len = _text.length
    if (!_len) break
    const _pos_space = _text.indexOf(' ') + 1
    const _pos_end_line = _text.indexOf(END_LINE) + 1
    let _pos: number
    if (_pos_space && _pos_end_line) _pos = Math.min(_pos_space, _pos_end_line)
    else if (_pos_space || _pos_end_line) _pos = Math.max(_pos_space, _pos_end_line)
    else _pos = 0
    if (_pos !== 1) {
      const _word = !_pos ? _text : _text.substring(0, _pos - 1) // This truncates the 'space'/'end line' at _pos
      const _dist1 = _word.length * _FONT_W
      if (_xl + _dist1 >= XR) {
        _xl = XL
        _yt += _DIST1
      }
      draw_text_(_xl, _yt, _word, FONT, PI ? -1 : undefined)
      _xl += _dist1
    }
    // Add the 'space' after the word. An 'end line' character turns into a 'space'.
    _xl += _FONT_W
    if (_pos && _pos < _len) {
      _text = _text.substring(_pos) // The remaining text beyond _pos
      if (_pos === _pos_end_line || _xl >= XR) {
        _xl = XL
        _yt += _DIST1
      }
    } else break
  }
  if (PI) pal_swap_reset()
  _yt += _FONT_H
  return _yt
}

/** `draw_spr_aligned(sprite, x, y, alignx 0_cen 1_rgt -1_lft, aligny 0_cen 1_btm -1_top, *palette index, *x scale, *y scale)` */
export function draw_spr_aligned(
  sprite: string,
  x: number,
  y: number,
  alignX: number,
  alignY: number,
  palIdx = -1,
  xscale = 1,
  yscale = 1,
): void {
  draw_sprite_(
    sprite,
    0,
    spr_x_at_x(sprite, x, alignX),
    spr_y_at_y(sprite, y, alignY),
    palIdx,
    xscale,
    yscale,
  )
}

export { FONT_LAYOUT }
