/** Grunt (`MoblB`) — the spear-walking moblin variant. Ported from `Grunt_init2/update/udp/draw.gml`. */
import { CS_BD1, CS_LFT, CS_RGT } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { GOB_sword_collision_1a, GOB_sword_collision_2a } from '../../../../../collision/gob'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { byte_dir, byte_negate } from '../../../../../math/index'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { draw_sprite_, drawState } from '../../../../../rooms/draw'
import { Enemy } from '../../../../classes'
import { GO_draw_sprite } from '../../../../go/draw'
import { updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { solid_clip_correction } from '../../../../goa/movement'
import { gp } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'

export class MoblB extends Enemy {
  readonly objectName = 'MoblB' as const
  Legs_sprite = 'spr_Grunt_legs1'
  VSPD_GRAV = 2
  spear_xoff1 = 8
  spear_xoff2 = -12
  spear_yoff = -8
  SwordHB_XOFF1 = 4
  SwordHB_XOFF2 = 8
  SwordHB_YOFF = 9
  SwordHB_W = 14
  SwordHB_H = 1
}

/** `Grunt_init2()` */
export function Grunt_init2(self: MoblB): void {
  const g = gp()
  GO_init_palidx(self, G.PI_MOB_ORG)
  self.dl_sprites?.set(1, 'spr_Grunt_body2')
  self.dl_sprites?.set(0, 'spr_Grunt_body1')
  self.Legs_sprite = 'spr_Grunt_legs1'
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  // sword draw xyoff
  self.spear_xoff1 = 8
  self.spear_xoff2 = -12
  self.spear_yoff = -8
  // sword hb
  self.SwordHB_XOFF1 = 4 + g.HB_ADJ_X
  self.SwordHB_XOFF2 = 8 + g.HB_ADJ_X
  self.SwordHB_YOFF = 9 + g.HB_ADJ_Y
  self.SwordHB_W = 14 + g.HB_ADJ_W
  self.SwordHB_H = 1 + g.HB_ADJ_H
  self.SwordHB_xoff = self.SwordHB_XOFF1 * self.facing_dir
  self.SwordHB_yoff = self.SwordHB_YOFF
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
}

/** `Grunt_update()` — 994F */
export function Grunt_update(self: MoblB): void {
  self.timer = 8
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // 9957: JSR DE3D
  GO_update_cs(self)
  GOB_update_2(self)
  // 995A: JSR E563: JSR E5F3
  if (!GOB_sword_collision_2a(self)) GOB_sword_collision_1a(self) // E579: JSR E5F3
  // 995D. body to body collision
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // Turn around if run into wall
  if ((self.hspd < 0x80 && self.cs & 0x1) || (self.hspd & 0x80 && self.cs & 0x2)) {
    self.hspd = byte_negate(self.hspd)
    self.facing_dir = byte_dir(self.hspd)
    self.cs &= ~(CS_RGT | CS_LFT)
  }
  // 9960
  if (!(self.cs & 0x3)) updateX(self)
  updateY(self)
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  }
}

/** `Grunt_udp()` — 9C43 */
export function Grunt_udp(self: MoblB): void {
  const g = gp()
  self.can_draw_self = true
  self.behavior = ((g.counter1 & 0x10) >> 4) + 3 // 3,4
  if (self.behavior === 4) self.sprite = self.dl_sprites?.get(1) ?? 0
  else self.sprite = self.dl_sprites?.get(0) ?? 0
  if (g.counter1 & 0x8) self.Legs_sprite = 'spr_Grunt_legs2'
  else self.Legs_sprite = 'spr_Grunt_legs1'
  // sword draw xoff
  if (self.behavior === 4) {
    self.spear_xoff1 = 20
    self.spear_xoff2 = 12
  } else {
    self.spear_xoff1 = 8
    self.spear_xoff2 = -12
  }
  self.spear_xoff1 *= self.facing_dir
  self.spear_xoff2 *= self.facing_dir
}

/** `Grunt_draw()` */
export function Grunt_draw(self: MoblB): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawState.depth = self.depth
  pal_swap_set(self.palidx)
  draw_sprite_(
    'spr_Spear_piece1',
    0,
    self.drawX + self.spear_xoff1,
    self.drawY + self.spear_yoff,
    -1,
    self.xScale,
  )
  draw_sprite_(
    'spr_Spear_piece2',
    0,
    self.drawX + self.spear_xoff2,
    self.drawY + self.spear_yoff,
    -1,
    self.xScale,
  )
  GO_draw_sprite(self, self.Legs_sprite)
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

export function registerGrunt(): void {
  registerObject('MoblB', MoblB)
  registerScripts({ Grunt_init2, Grunt_update, Grunt_udp, Grunt_draw })
}
registerGrunt()
