/**
 * `GameObjectMgr` (`g.go_mgr`): the NES-style update slot lists. Ported from `GameObjectMgr_Create.gml`,
 * `GameObjectMgr_Room_Start.gml`. `dl_gob1` (enemies/bosses) and `dl_goc1` (hostile projectiles) are fixed
 * MAX_GOB1/MAX_GOC1 slot lists holding `noone`(null) when free; `dl_goc2` holds MAX_GOC2 friendly projectile
 * instances; `dl_gob2` is unbounded (NPC, Item, Elevator, …).
 */
import { MAX_GOB1, MAX_GOC1, MAX_GOC2, UIDX_NULL } from '@z2/data'
import { DsList } from '../../runtime/ds'
import type { Ref } from '../../runtime/instance'
import { world } from '../../runtime/world'
import type { GameObject, GameObjectC } from '../game_object/classes'
import { PlainGameObject, PlainProjectileFriendly } from '../game_object/classes'
import { installInstanceEnd } from '../game_object/go/lifecycle'
import { gp } from '../game_object/pending'

export class GameObjectMgr {
  readonly objectName = 'GameObjectMgr'
  update_idx = 0
  readonly UPDATE_COUNT = Math.max(MAX_GOB1, MAX_GOC1)
  counter = 0 // 0485
  uIdxSwap_gob = -1 // if != -1, addToEntityList() will use eIndexSwap value
  uIdxSwap_goc = -1 // if != -1, addToProjectileList() will use pIndexSwap value
  dl_gob1 = new DsList<Ref<GameObject>>(MAX_GOB1, null) // Enemy, Boss, ...
  dl_gob2 = new DsList<Ref<GameObject>>() // NPC, Item, ...
  dl_goc1 = new DsList<Ref<GameObject>>(MAX_GOC1, null) // GOC (projectiles hostile)
  dl_goc2 = new DsList<Ref<GameObjectC>>(MAX_GOC2, null) // Projectile Friendly

  /** `GameObjectMgr_Create()` */
  GameObjectMgr_Create(): void {
    gp().go_mgr = this // `GameObjectMgr_Create.gml:13` — every `with(go_mgr)` resolves through this
    this.update_idx = 0
    this.counter = 0
    this.uIdxSwap_gob = -1
    this.uIdxSwap_goc = -1
    this.dl_gob1 = new DsList<Ref<GameObject>>(MAX_GOB1, null)
    this.dl_gob2 = new DsList<Ref<GameObject>>()
    this.dl_goc1 = new DsList<Ref<GameObject>>(MAX_GOC1, null)
    this.dl_goc2 = new DsList<Ref<GameObjectC>>(MAX_GOC2, null)
  }

  /**
   * `GameObjectMgr_Room_Start()` — reset slots for a new room. With `g.mod_destroy_go_on_death` the slots
   * are cleared to noone; otherwise ZALiA pre-filled them with dormant placeholder instances (the OG had a
   * fixed table). Friendly projectile slots always get MAX_GOC2 dormant ProjectileFriendly instances.
   */
  GameObjectMgr_Room_Start(): void {
    this.counter = 0 // 0485
    this.update_idx = UIDX_NULL
    this.uIdxSwap_gob = UIDX_NULL
    this.uIdxSwap_goc = UIDX_NULL
    const placeholder = <T extends GameObject>(inst: T): T => {
      installInstanceEnd(inst)
      inst.state = 0
      return world.register(inst)
    }
    if (gp().mod_destroy_go_on_death) {
      this.dl_gob1 = new DsList<Ref<GameObject>>(MAX_GOB1, null)
      this.dl_goc1 = new DsList<Ref<GameObject>>(MAX_GOC1, null)
    } else {
      this.dl_gob1 = new DsList<Ref<GameObject>>()
      for (let _i = MAX_GOB1 - 1; _i >= 0; _i--) this.dl_gob1.set(_i, placeholder(new PlainGameObject()))
      this.dl_goc1 = new DsList<Ref<GameObject>>()
      for (let _i = 0; _i < MAX_GOC1; _i++) this.dl_goc1.set(_i, placeholder(new PlainGameObject()))
    }
    this.dl_goc2 = new DsList<Ref<GameObjectC>>()
    for (let _i = MAX_GOC2 - 1; _i >= 0; _i--)
      this.dl_goc2.set(_i, placeholder(new PlainProjectileFriendly()))
    this.dl_gob2 = new DsList<Ref<GameObject>>()
  }

  /** `GameObjectMgr_Game_End()` — lists are garbage-collected; nothing to free. */
  GameObjectMgr_Game_End(): void {
    this.dl_gob1.clear()
    this.dl_gob2.clear()
    this.dl_goc1.clear()
    this.dl_goc2.clear()
  }
}
