import { type SpriteInfo, setSpriteManifest } from '../graphics/sprites'
import { setBackgroundMeta } from './gm'

export interface TilesetManifestEntry {
  name: string
  width: number
  height: number
}

/** Feed the asset manifests into the metadata registries (`sprite_get_width`, `background_get_width`…). */
export function loadSpriteManifest(sprites: SpriteInfo[], tilesets: TilesetManifestEntry[] = []): void {
  setSpriteManifest(sprites)
  for (const t of tilesets) setBackgroundMeta(t.name, { width: t.width, height: t.height })
}
