/**
 * `dev/game_object` — the debug overlays every GameObject draw event calls when `g.DevTools_state`:
 * hitbox rectangles, collide-solid probe points, ocs lines, sprite outlines, xy markers, HP text.
 *
 * `dev_create_pc_skin_sprite` / `_1` are **dropped**: a 19 208-line generated table that rebuilt the
 * built-in skin sheets pixel-row by pixel-row inside the IDE. The port ships the sheets as atlases.
 */
import { f, g } from '../../runtime/world'
import {
  c_lime,
  c_purple,
  c_white,
  draw_circ_,
  draw_sprite_index_outline,
  drawPointCross,
  drawSprOutline,
} from '../draw/index'
import { c_aqua, c_fuchsia, c_yellow } from '../Game/gmConsts'
import type { GameObject } from '../game_object/classes'
import { gmBool } from '../math/index'
import { hex_str } from '../other/index'
import { bgrToRgb } from '../palette/colors'
import { draw_rect_, draw_text_, drawState, pushCmd } from '../rooms/draw'

/** Structural view of the optional debug fields; not every GameObject subclass declares all of them. */
type Dbg = GameObject & Record<string, unknown>

/** `GO_draw_body_hb()` — Toggle with 'R' (`g.can_draw_hb`). */
export function GO_draw_body_hb(self: GameObject): void {
  if (!gmBool(g.DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!g.can_draw_hb) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!self.BodyHB_can_draw) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (gmBool(self.BodyHB_r))
    draw_circ_(self.BodyHB_color, self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_r, 1, true)
  else draw_rect_(self.BodyHB_color, self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h, 1, true)
}

/** `GO_draw_shield_hb()` */
export function GO_draw_shield_hb(self: GameObject): void {
  if (!gmBool(g.DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!g.can_draw_hb) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // GML: `variable_instance_exists(id, "ShieldHB_can_draw")` — every ported GameObject declares it.
  if (!self.ShieldHB_can_draw) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!gmBool(self.ShieldHB_w)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!self.ShieldHB_collidable) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  draw_rect_(self.ShieldHB_color, self.ShieldHB_x, self.ShieldHB_y, self.ShieldHB_w, self.ShieldHB_h, 1, true)
}

/** `GO_draw_sword_hb()` — the PC also gets its second (up/down thrust) sword box. */
export function GO_draw_sword_hb(self: GameObject): void {
  if (!gmBool(g.DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!g.can_draw_hb) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (self.SwordHB_can_draw && gmBool(self.SwordHB_w))
    draw_rect_(self.SwordHB_color, self.SwordHB_x, self.SwordHB_y, self.SwordHB_w, self.SwordHB_h, 1, true)
  const s = self as Dbg
  if (s.SwordHB2_can_draw === true)
    draw_rect_(
      c_white,
      s.SwordHB2_xl as number,
      s.SwordHB2_yt as number,
      s.SwordHB2_w as number,
      s.SwordHB2_h as number,
      1,
      true,
    )
}

/** `GO_draw_trig_hb_1()` — trigger boxes (Magnot). Ported inline in `enemy/magnot/Magnot.ts`. */

/** `GO_draw_cs_points()` — CS: Collide Solid probe points. Toggle with 'H'. */
export function GO_draw_cs_points(self: GameObject): void {
  if (!gmBool(g.DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!g.can_draw_cs) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!self.canDrawCSHB) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const _COLOR1 = c_lime
  const _COLOR2 = c_purple
  drawPointCross(self.csRgt1X, self.csRgt1Y, _COLOR1, _COLOR2) // CS_RGT top
  drawPointCross(self.csRgt2X, self.csRgt2Y, _COLOR1, _COLOR2) // CS_RGT bottom
  drawPointCross(self.csLft1X, self.csLft1Y, _COLOR1, _COLOR2) // CS_LFT top
  drawPointCross(self.csLft2X, self.csLft2Y, _COLOR1, _COLOR2) // CS_LFT bottom
  drawPointCross(self.csBtm1X, self.csBtm1Y, _COLOR1, _COLOR2) // CS_BOT
  drawPointCross(self.csTop1X, self.csTop1Y, _COLOR1, _COLOR2) // CS_TOP
  drawPointCross(self.csBtm2X, self.csBtm2Y, _COLOR1, _COLOR2) // CS_BOT right
  drawPointCross(self.csTop2X, self.csTop2Y, _COLOR1, _COLOR2) // CS_TOP right
  drawPointCross(self.cp1X, self.cp1Y, _COLOR1, _COLOR2) // CS_BOT mid
  drawPointCross(self.cp2X, self.cp2Y, _COLOR1, _COLOR2) // CS_TOP mid
}

/** `GO_draw_ocs()` — the object-collide-solid scan lines. Toggle with 'C' (`g.can_draw_ocs`). */
export function GO_draw_ocs(self: GameObject): void {
  if (!gmBool(g.DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!g.can_draw_ocs) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (self.ocs_draw_y[0] !== undefined) {
    const _h = 0x10
    for (const _x of self.ocs_draw_x) {
      const _y = self.y - (_h >> 1)
      line(_x, _y, _x, _y + _h)
    }
    const _w = self.ww
    for (const _y of self.ocs_draw_y) line(self.xl, _y, self.xl + _w, _y)
  }
  self.ocs_draw_y[0] = undefined as unknown as number
}

function line(x1: number, y1: number, x2: number, y2: number): void {
  pushCmd({ kind: 'line', x1, y1, x2, y2, color: bgrToRgb(c_lime), depth: drawState.depth })
}

/** `GO_draw_xy_point()` — Toggle with 'J'. Points representing xl,yt and x,y. */
export function GO_draw_xy_point(self: GameObject): void {
  if (!g.canDraw_ogXY) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawPointCross(self.xl, self.yt, c_aqua, c_fuchsia)
  drawPointCross(self.x, self.y, c_white, c_fuchsia)
}

/** `GO_draw_sprite_outline()` — Sequence with 'K'. Outline of `sprite` or `sprite_index`. */
export function GO_draw_sprite_outline(self: GameObject): void {
  if (!gmBool(g.canDrawSprOutline)) return
  if (g.canDrawSprOutline & 0x1) {
    if (self.sprite) drawSprOutline(self.drawX, self.drawY, self.sprite, c_yellow, 1)
  } else draw_sprite_index_outline(self)
}

/** `GO_debug_draw_1a()` — sprite outline ('K') + xy point ('J'). */
export function GO_debug_draw_1a(self: GameObject): void {
  GO_draw_sprite_outline(self)
  GO_draw_xy_point(self)
}

/** `PC_draw_scs()` — SCS: Sword Collide Solid probe point. */
export function PC_draw_scs(self: GameObject): void {
  const s = self as Dbg
  if (!g.can_draw_hb) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (s.SCS_can_draw !== true) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawPointCross(s.SCS_draw_x as number, s.SCS_draw_y as number, c_yellow, s.SCS_COLOR as number)
}

/** `PC_draw_hp()` — draws the PC's HP above the head. Toggle with 'V'. */
export function PC_draw_hp(self: GameObject): void {
  if (!gmBool(g.DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!g.can_draw_hp) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawHpText(self, f.hp)
}

/** `GOB_draw_hp()` — draws the entity's HP above the head. Toggle with 'V'. */
export function GOB_draw_hp(self: GameObject): void {
  if (!gmBool(g.DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!g.can_draw_hp) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // GOB_draw_hp draws at drawY - (hh>>1); PC_draw_hp subtracts a further 8+2 for the taller sprite.
  drawHpText(self, (self as Dbg).hp as number, 0)
}

function drawHpText(self: GameObject, hp: number, extraYOff = -10): void {
  let _text = hex_str(Math.abs(hp))
  let _x = self.drawX - ((8 * _text.length) >> 1)
  _x -= 8 * +(hp < 0) // For negative char
  const _y = self.drawY - (self.hh >> 1) + extraYOff
  if (hp < 0) _text = `-${_text}`
  draw_text_(_x, _y, _text)
}

/** `GameObjectB_debug_draw_1a()` — body/shield/sword hitboxes, cs points, ocs lines. */
export function GameObjectB_debug_draw_1a(self: GameObject): void {
  if (!gmBool(g.DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  GO_draw_body_hb(self)
  GO_draw_shield_hb(self)
  GO_draw_sword_hb(self)
  GO_draw_cs_points(self)
  GO_draw_ocs(self)
}

/** `GameObjectB_debug_draw_2a()` — HP over the entity. Toggle with 'V'. */
export function GameObjectB_debug_draw_2a(self: GameObject): void {
  GOB_draw_hp(self)
}
