/** `Item_init()` — see the ZALiA iID table in the GML header. */
export function Item_init(self: ItemObject): void {
  // init_vars_go_A / init_vars_Item are class fields
  GO_depth_init(self, DEPTH_ITEM)
  // default GameObject draw YOff
  self.DRAW_YOFF = 1 // +1 for 1 pixel in ground
  self.scr_step = GameObjectB_step as never
}

/** `Item_init_2()` */
export function Item_init_2(self: ItemObject): void {
  if (
    !audio_is_playing(get_audio_theme_track(dk_ItemDrop)) &&
    isVal(self.ITEM_TYPE, STR_KEY, STR_JAR, STR_PBAG, STR_1UP) &&
    rectInView(self.xl, self.yt, self.ww, self.hh) &&
    !((G.dg_solid.get(self.x >> 3, (self.yb + 1) >> 3) ?? 0) & 0xff) // If not on ground
  ) {
    aud_play_sound(get_audio_theme_track(dk_ItemDrop))
  }
  if (self.ITEM_TYPE === STR_PBAG) {
    self.DRAW_YOFF = 0
  }
  if (self.ITEM_TYPE === STR_HEART) {
    const _PAL = build_pal(p.C_WHT1, p.C_RED3, p.C_ORG4, p.C_BLK1, -2, -2, -2, -2)
    change_pal(strReplaceAt(p.pal_rm_new, get_pal_pos(G.PI_MOB_RED), _PAL.length, _PAL))
  }
  if (self.ITEM_TYPE === STR_RFAIRY) {
    self.GROUND_Y = get_ground_y(self.x, self.y, 1, self.yb, TID_SOLID1 | TID_ONEWY1)
    set_xy(self, self.x, self.GROUND_Y - 0x10 - self.hh_)
  }
  // So super cucco can grab the falling key
  if (
    gmBool(g.CuccoSpell2_Active) &&
    self.ITEM_TYPE === STR_KEY &&
    self.dk_spawn !== undefined &&
    self.dk_spawn === val(g.dm_spawn.get(`FallingKey1${dk_SpawnDatakey}`))
  ) {
    set_xy(self, self.x, self.y - (0x05 << 3))
  }
}

/** `Item_update()` */
export function Item_update(self: ItemObject): void {
  const P = pc()
  switch (self.sub_state) {
    // ---------------------------------------------------------------------
    case self.sub_state_IDLE: {
      // RESCUE FAIRY
      if (self.ITEM_BIT === ITM_FRY1) {
        self.vspd = 0
        self.vspd_grav = 0
        // if all w and all h in ocs area
        if (!self.greeting_played && ocsHV4(self)) {
          self.greeting_played = true // Prevent sound from playing again
          aud_play_sound(get_audio_theme_track(STR_Fairy + STR_Greeting))
        }
      }
      // D959: JSR DE3D
      GO_update_cs(self)
      GOB_update_2(self)
      // E51E. ITEM_TYPE: "A":Major items, "B":Heart/Magic containers, "C":Quest items, "G":Extra Life Doll
      if (
        gmBool(self.IS_HOLD_ITEM) &&
        gmBool(self.cs & CS_BD1) &&
        !gmBool(P.ogr) &&
        !gmBool(P.HoldItem_timer)
      ) {
        // E726, E538: JSR E771
        Item_update_1(self) // E771
        P.HoldItem_timer = P.HoldItem_DURATION // $70
        P.vspd = 0 // og
        P.HoldItem_inst = self
        P.HoldItem_object = self.objectName // 049D
        if (self.objectName === CONT_PIECE_OBJ_MP) {
          GO_sprite_init(self, g.dl_cont_spr_mp.get(0) as string)
        }
        self.sub_state = self.sub_state_HELD
        return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
      }
      if (!gmBool(self.IS_HOLD_ITEM) && !gmBool(self.stun_timer)) {
        // Note: TYPE1's react_swrd value does NOT collide w/ PC swrd
        if (
          gmBool(self.cs & CS_SW1) ||
          (P.SwordHB2_colliding === self && isVal(self.ITEM_TYPE, STR_KEY, STR_JAR, STR_PBAG))
        ) {
          Item_update_1(self) // E771
          self.stun_timer = self.STUN_DURATION1 // $30
          aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
          if (self.ITEM_TYPE === STR_PBAG) {
            self.state = self.state_DROP
          } else {
            self.state = 0
          }
          return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
        }
      }
      // D95C
      Item_update_vertical(self)
      break
    }
    // ---------------------------------------------------------------------
    case self.sub_state_HELD: {
      if (gmBool(P.HoldItem_timer)) {
        let _X = P.x
        if (self.ww < 0x10) {
          if (pc_is_cucco()) {
            _X += self.ww_ * -P.xScale
          } else {
            _X -= self.ww_
          }
        }
        let _Y = P.yt - self.hh_
        _Y -= pc_is_cucco() ? 1 : 0
        set_xy(self, _X, _Y)
        update_EF11(self)
      } else {
        P.HoldItem_inst = NOONE
        self.state = 0
        return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
      }
      break
    }
    // ---------------------------------------------------------------------
    case self.sub_state_NONI: {
      // Non-Interactive. isVer(id,ItmC0,2) // Returned TROPHY in Ruto
      update_EF11(self)
      break
    }
  }
}

/** `Item_update_1()` — E771, E77B. Acquiring item */
export function Item_update_1(self: ItemObject): void {
  const _MUSIC_THEME1 = `${dk_GetItem}01`
  const _MUSIC_THEME2 = `${dk_GetItem}02`
  let _can_flash = false
  const majorItem = () => {
    f.items = gmOr(f.items, self.ITEM_BIT) // 64-bit: ITEM_SPELL is bit 32
    _can_flash = true
    aud_play_sound(get_audio_theme_track(_MUSIC_THEME1), -1, false, -1, _MUSIC_THEME1)
  }
  const idStr = self.ITEM_ID ?? ''
  switch (self.ITEM_TYPE) {
    case STR_CANDLE:
    case STR_GLOVE:
    case STR_RAFT:
    case STR_HAMMER:
    case STR_FLUTE:
    case STR_BRACELET:
    case STR_CROSS:
    case STR_BOOK:
    case STR_MEAT:
    case STR_PENDANT:
    case STR_SHIELD:
    case STR_SWORD:
    case STR_RING:
    case STR_ALLKEY:
    case STR_MASK:
    case STR_FEATHER:
    case STR_TROPHY:
    case STR_NOTE:
    case STR_MIRROR:
    case STR_FLOWER:
    case STR_CHILD:
    case STR_BOTTLE:
      majorItem()
      break
    case STR_BOOTS:
      majorItem()
      Overworld_tile_change_2a(overworld(), overworld().TileChangeEvent_TYPE_BOOT1)
      break
    case STR_RFAIRY:
      majorItem()
      g.StatRestore_timer_hp = get_stat_max(STR_Heart)
      break
    case STR_MAP1:
    case STR_MAP2:
      f.items = gmOr(f.items, self.ITEM_BIT) // 64-bit: ITEM_SPELL is bit 32
      aud_play_sound(get_audio_theme_track(_MUSIC_THEME2), -1, false, -1, _MUSIC_THEME2)
      break
    case STR_HEART: {
      f.cont_pieces_hp += idStr.substring(idStr.length - 4)
      g.StatRestore_timer_hp = get_stat_max(STR_Heart)
      // if this completes a container
      if (!(cont_piece_cnt_hp() % f.CONT_PIECE_PER)) {
        aud_play_sound(get_audio_theme_track(_MUSIC_THEME1), -1, false, -1, _MUSIC_THEME1)
      } else {
        aud_play_sound(get_audio_theme_track(_MUSIC_THEME2), -1, false, -1, _MUSIC_THEME2)
      }
      break
    }
    case STR_MAGIC: {
      f.cont_pieces_mp += idStr.substring(idStr.length - 4)
      g.StatRestore_timer_mp = get_stat_max(STR_Magic)
      // if this completes a container
      if (!(cont_piece_cnt_mp() % f.CONT_PIECE_PER)) {
        aud_play_sound(get_audio_theme_track(_MUSIC_THEME1), -1, false, -1, _MUSIC_THEME1)
      } else {
        aud_play_sound(get_audio_theme_track(_MUSIC_THEME2), -1, false, -1, _MUSIC_THEME2)
      }
      break
    }
    case STR_KEY: {
      // E79A. key_datakey example: "0203", "0601"
      if (typeof self.ITEM_ID === 'string') f.dm_keys.set(self.ITEM_ID + STR_Acquired, 1)
      f.key_count = get_key_count(g.dungeon_num)
      aud_play_sound(get_audio_theme_track(dk_StabItem))
      break
    }
    case STR_JAR: {
      // E847
      g.StatRestore_timer_mp += get_jar_restore_dur(self.ver)
      if (self.ver === 1 || self.ver === 3) {
        if (typeof self.ITEM_ID === 'string') f.dm_jars.set(self.ITEM_ID + STR_Acquired, 1)
      }
      aud_play_sound(get_audio_theme_track(dk_StabItem))
      break
    }
    case STR_PBAG: {
      // E7F4: JSR E880. For those that have a spawn datakey (not ones dropped by an enemy)
      if (typeof self.ITEM_ID === 'string') f.dm_PBags.set(self.ITEM_ID + STR_Acquired, 1)
      aud_play_sound(get_audio_theme_track(dk_StabItem))
      self.timer = g.XP_RISE_DURATION + 2 // $20 + 2
      self.state = self.state_DROP // for xp rise
      break
    }
    case STR_1UP: {
      // E80C
      f.lives++
      if (typeof self.ITEM_ID === 'string') f.dm_1up_doll.set(self.ITEM_ID + STR_Acquired, 1)
      aud_play_sound(get_audio_theme_track(_MUSIC_THEME2), -1, false, -1, _MUSIC_THEME2)
      break
    }
  }
  if (_can_flash) {
    const _DURATION = p.SpellFlash_DURATION1 // SpellFlash_DURATION1=$20. bit $80 means flash background
    p.Flash_Pal_timer = _DURATION
    p.Flash_Bgr_timer = _DURATION
    p.SpellFlash_PC_timer = _DURATION
  }
}

/** `Item_update_vertical()` — D95C */
export function Item_update_vertical(self: ItemObject): void {
  // if NOT RESCUE FAIRY
  if (self.ITEM_TYPE !== STR_RFAIRY) {
    if (self.cs & 0x04) {
      solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
      if (self.ITEM_TYPE !== STR_PBAG && self.vspd >= 0x0e) {
        // Bounce ---------------------------
        if (self.vspd >= 0x30) self.vspd = 0xf0
        else self.vspd = 0xf7
        set_xy(self, self.x, self.y - 1)
      } else {
        self.vspd = 0xff
      }
    }
    self.vspd = (self.vspd + 1) & 0xff
  }
  updateY(self)
}

/** `Item_udp()` */
export function Item_udp(self: ItemObject): void {
  self.can_draw_self = true
  // ItmD0: Key
  if (gmBool(self.IS_HOLD_ITEM) || self.objectName === 'ItmD0') {
    self.draw_yoff = self.sub_state === self.sub_state_HELD ? 0 : -1
  }
  switch (self.objectName) {
    case CONT_PIECE_OBJ_HP: {
      if (self.sub_state === self.sub_state_HELD) {
        let _IDX = Math.max(cont_piece_cnt_hp() - 1, 0)
        _IDX = _IDX % f.CONT_PIECE_PER_HP
        _IDX++
        _IDX -= can_blink_container_piece(pc()) ? 1 : 0
        GO_set_sprite(self, g.dl_cont_spr_hp.get(_IDX) as string)
      } else {
        // 0: SMALL, 1: BIG. Small for $28-2F,$38-3F every $40
        const _IDX = 0x28
        const big = (g.counter0 & _IDX) === _IDX ? 1 : 0
        GO_set_sprite(self, g.dl_HeartPiece_SPR.get(big) as string)
      }
      break
    }
    case CONT_PIECE_OBJ_MP: {
      if (self.sub_state === self.sub_state_HELD) {
        let _IDX = Math.max(cont_piece_cnt_mp() - 1, 0)
        _IDX = _IDX % f.CONT_PIECE_PER_MP
        _IDX++
        _IDX -= can_blink_container_piece(pc()) ? 1 : 0
        GO_set_sprite(self, g.dl_cont_spr_mp.get(_IDX) as string)
      } else {
        GO_set_sprite(self, g.SPR_CONT_PIECE_MP)
      }
      break
    }
    case 'ItmA7': {
      // ItmK6: ITM_SWRD
      self.depth = self.depth_def
      self.draw_yoff = 0
      self.yScale = 1
      if (self.sub_state !== self.sub_state_HELD) {
        self.draw_yoff = 1
        self.yScale = -1
        if (self.dk_spawn !== undefined) {
          const _OBJ = val(g.dm_spawn_DEFAULT.get(self.dk_spawn + STR_obj_idx))
          // `_obj_idx` is a *numeric* GM object index in the decoded caches; comparing it with the
          // instance's object *name* was always false, so no item ever took its vanilla-location depth.
          if (gmBool(_OBJ as number) && gmObjectNameOf(_OBJ as number) === self.objectName) {
            // if it's in its vanilla location
            self.depth = DEPTH_BG6 + 1 // DEPTH_BG6+1: Behind bg but in front of bg wall
            self.draw_yoff = -4
          }
        }
      }
      break
    }
  }
  // RESCUE FAIRY
  if (self.objectName === 'ItmA8') {
    if (g.counter1 & 0x04)
      GO_set_sprite(self, g.dl_Fairy_SPRITES.get(0) as string) // wings up
    else GO_set_sprite(self, g.dl_Fairy_SPRITES.get(1) as string) // wings down
    self.draw_yoff = get_fairy_yoff(g.counter1, 3)
  }
  if (gmBool(g.mod_MedicinePlantItem) && self.ITEM_BIT === ITM_MEDI) {
    GO_set_sprite(self, g.FlowerItemAnim_SPR1)
  }
}

/** `Item_draw()` */
export function Item_draw(self: ItemObject): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (
    self.objectName === CONT_PIECE_OBJ_MP ||
    (self.objectName === val(g.dm_ITEM.get(hexStr(ITM_MEDI) + STR_Object)) &&
      !gmBool(g.mod_MedicinePlantItem))
  ) {
    // Bubbling Liquid in Bottles
    let _SPR: string | 0 = 0
    const frame = get_bottle_bubbling_frame()
    if (self.objectName !== CONT_PIECE_OBJ_MP) {
      _SPR =
        (['spr_Bottle_7a_Liquid_1a', 'spr_Bottle_7a_Liquid_1b', 'spr_Bottle_7a_Liquid_1c'] as const)[frame] ??
        0
    } else if (self.sub_state !== self.sub_state_HELD) {
      _SPR =
        (['spr_Bottle_6a_Liquid_1a', 'spr_Bottle_6a_Liquid_1b', 'spr_Bottle_6a_Liquid_1c'] as const)[frame] ??
        0
    }
    if (_SPR)
      draw_sprite_at(self.depth, _SPR, 0, self.drawX, self.drawY, self.palidx, self.xScale, self.yScale)
  } else {
    // Key
    if (
      self.objectName === 'ItmD0' &&
      self.ITEM_ID !== undefined &&
      gmBool(val(G.dm_save_file_settings.get(STR_Randomize + STR_Key + STR_Locations)) as number)
    ) {
      // Example: _KEY0402. This would take just the 4 _KEY0(4)02, which is the dungeon num
      const _TEXT = self.ITEM_ID.substring(self.ITEM_ID.length - 3, self.ITEM_ID.length - 2)
      const _XL = self.drawX - ((_TEXT.length << 3) >> 1)
      const _YT = self.drawY - self.hh_ - 8
      draw_text_(_XL, _YT, _TEXT, -1, G.PI_GUI1)
    }
  }
  GameObject_draw_1a(self, self.sprite as string, self.palidx) // draw self
}

/** `item_acquired(item id)` — examples: "_CANDLE", "_HEART0602", "_1UP02", "_KEY0501", "_PBAG1B" */
export function item_acquired(itemId: string | number): boolean {
  const _ITEM_ID = String(itemId)
  let _ITEM_TYPE = _ITEM_ID
  if (_ITEM_ID.includes(STR_HEART)) _ITEM_TYPE = STR_Container
  else if (_ITEM_ID.includes(STR_MAGIC)) _ITEM_TYPE = STR_Container
  else if (_ITEM_ID.includes(STR_1UP)) _ITEM_TYPE = STR_1UP
  else if (_ITEM_ID.includes(STR_PBAG)) _ITEM_TYPE = STR_PBAG
  else if (_ITEM_ID.includes(STR_KEY)) _ITEM_TYPE = STR_KEY
  else if (_ITEM_ID.includes(STR_JAR)) _ITEM_TYPE = STR_JAR
  switch (_ITEM_TYPE) {
    default: {
      // main items
      const _ITEM_BIT = val(g.dm_ITEM.get(_ITEM_ID + STR_Bit)) as number
      // `gmAnd`, not `&`: `ITEM_SPELL` is bit 32 and a JS `&` against it is always 0, so `item_acquired`
      // said false for every spell item — including the randomizer's reachability checks.
      if (gmAnd(f.items, _ITEM_BIT) !== 0) return true
      break
    }
    case STR_Container: {
      const _CONTAINER_ID = _ITEM_ID.substring(_ITEM_ID.length - 4)
      const _acquired_pieces = _ITEM_ID.includes(STR_HEART) ? f.cont_pieces_hp : f.cont_pieces_mp
      for (let _i = (_acquired_pieces.length >> 2) - 1; _i >= 0; _i--) {
        if (_acquired_pieces.substr(_i << 2, 4) === _CONTAINER_ID) return true
      }
      break
    }
    case STR_1UP:
      if (gmBool(val(f.dm_1up_doll.get(_ITEM_ID + STR_Acquired)) as number)) return true
      break
    case STR_PBAG:
      if (gmBool(val(f.dm_PBags.get(_ITEM_ID + STR_Acquired)) as number)) return true
      break
    case STR_KEY:
      if (gmBool(val(f.dm_keys.get(_ITEM_ID + STR_Acquired)) as number)) return true
      break
    case STR_JAR:
      if (gmBool(val(f.dm_jars.get(_ITEM_ID + STR_Acquired)) as number)) return true
      break
  }
  return false
}

/** `get_bottle_bubbling_frame()` */
export function get_bottle_bubbling_frame(): 0 | 1 | 2 {
  const _VAL = g.counter0 & 0x3f
  if (_VAL < 0x15) return 0
  if (_VAL < 0x2a) return 1
  return 2
}
