/**
 * Settings side of the retro post-processing chain — the pure, browser-free half.
 *
 * ZALiA keeps this state in two places: `global.RetroShaders_*` (Options menu / `UserPreferences.txt`)
 * and the `GraphicsEffectsEditor` parameter grids (`GEE.dg_<Effect>[#<Effect>_<ROW>, $5]`).
 * `Surface_Step.gml:181-209` folds them into the per-frame `RetroShaders_*_can_draw` / `_amount`
 * values that `Surface_Draw_GUI_Begin.gml` hands to the shaders. `packRetroUniforms()` below is that
 * fold, kept pure so it can be unit-tested without a GPU.
 */

/**
 * Minimal read-only shape of a core `DsGrid` lookup.
 * GML `dg_Bloom[#Bloom_A, $5]` is `dg_Bloom.get(Bloom_A, 0x5)` in the port
 * (`packages/core/src/runtime/ds.ts`; the same call `prefs.ts` uses to persist these).
 */
export interface GeeValueGrid {
  get(x: number, y: number): number | undefined
}

/**
 * The slice of the core's `GraphicsEffectsEditor` state this module reads.
 *
 * Deliberately declared here rather than imported: the core's own `GraphicsEffectsEditorDeps`
 * lives in `packages/core/src/game/file/deps.ts`, which the `@z2/core` barrel does not re-export.
 * This interface is structurally assignable *from* it, so once the GEE object port lands and
 * populates `g.surf.GEE`, it drops in with no change here.
 */
export interface GraphicsEffectsGrids {
  dg_Brightness: GeeValueGrid
  dg_Saturation: GeeValueGrid
  dg_Scanlines: GeeValueGrid
  dg_Bloom: GeeValueGrid
  dg_Blur: GeeValueGrid
  Brightness_ENABLE: number
  Brightness_EDIT: number
  Saturation_ENABLE: number
  Saturation_EDIT: number
  Scanlines_ENABLE: number
  Scanlines_EDIT: number
  Bloom_ENABLE: number
  Bloom_A: number
  Bloom_B: number
  Bloom_C: number
  Bloom_D: number
  Bloom_E: number
  Bloom_F: number
  Bloom_G: number
  Blur_ENABLE: number
  Blur_EDIT: number
}

/** ZALiA GEE grid column holding the *current* value of a row (`dg[#row, $5]`). */
export const GEE_VALUE_COL = 0x5

/** `shd_SaturationBrightness.u_effect_type` — 1: `hsv.z + brightness` (the only mode ZALiA ships). */
export const SB_EFFECT_TYPE_ADD = 1

/** ZALiA's shipped render size, `BASE_GAME_RESOLUTION_W/H`. Mirrors `packages/game/src/index.ts`. */
export const BASE_SURFACE_W = 480
export const BASE_SURFACE_H = 270

/** `p.C_BLK1` — ZALiA's "black", one step off `$000000` so palette swap ignores it. */
export const C_BLK1 = 0x010101

/** Bloom's seven `u_a`..`u_g` knobs, in GEE row order (`Bloom_A`..`Bloom_G`). */
export type BloomParams = readonly [number, number, number, number, number, number, number]

/**
 * One frame's worth of retro-shader settings, read out of the core.
 * Every field maps 1:1 onto a ZALiA setting; nothing here is derived.
 */
export interface RetroSettings {
  /** `global.RetroShaders_IS_LIVE` — false disables every RetroShaders action. */
  live: boolean
  /** `global.RetroShaders_enabled` — the Options-menu master toggle. */
  enabled: boolean
  /** `global.RetroShaders_surface_scale` — ZALiA renders at `BASE * scale`. See `scanlineHeightFor()`. */
  surfaceScale: number
  /** `GEE.dg_Saturation[#Saturation_ENABLE, $5]`. */
  saturationEnabled: boolean
  /** `GEE.dg_Saturation[#Saturation_EDIT, $5]` → `u_saturation`. */
  saturation: number
  /** `GEE.dg_Brightness[#Brightness_ENABLE, $5]`. */
  brightnessEnabled: boolean
  /** `GEE.dg_Brightness[#Brightness_EDIT, $5]` → `u_brightness`. */
  brightness: number
  /** `GEE.dg_Scanlines[#Scanlines_ENABLE, $5]`. */
  scanlinesEnabled: boolean
  /** `GEE.dg_Scanlines[#Scanlines_EDIT, $5]` → `u_line_brightness`. */
  scanlineBrightness: number
  /** `GEE.dg_Bloom[#Bloom_ENABLE, $5]`. */
  bloomEnabled: boolean
  /** `GEE.dg_Bloom[#Bloom_A..G, $5]` → `u_a`..`u_g`. */
  bloom: BloomParams
  /** `GEE.dg_Blur[#Blur_ENABLE, $5]`. */
  blurEnabled: boolean
  /** `GEE.dg_Blur[#Blur_EDIT, $5]` — alpha the blurred copy is composited over the base with. */
  blurAlpha: number
  /** `window_get_width()` / `window_get_height()` — feeds `u_pixel_scale`. */
  windowWidth: number
  windowHeight: number
  /** `g.MaskWideView` — 0: no bars, 1: hold, 2: animating. */
  maskWideView: number
  /** `g.MaskWideView_w` — current bar width per side, in view pixels. */
  maskWidth: number
  /** `g.VIEW_W` — the view the bar width is measured against. */
  viewWidth: number
}

/**
 * ZALiA's shipped defaults, from `GraphicsEffectsEditor_Create.gml` (the `val(pref, default)` fallbacks)
 * and `globals.ts`. Note the `// default:` comments in `Surface_Draw_GUI_Begin.gml:64-70` are stale —
 * these are the live values.
 */
export const RETRO_DEFAULTS: RetroSettings = {
  live: true,
  enabled: false,
  surfaceScale: 2,
  saturationEnabled: true,
  saturation: -0.075,
  brightnessEnabled: true,
  brightness: 0.05,
  scanlinesEnabled: true,
  scanlineBrightness: 0.5,
  bloomEnabled: true,
  bloom: [0.1655, 0.006, 0.02, 0.013, 0.44, 0.51, 0.16],
  blurEnabled: true,
  blurAlpha: 0.85,
  windowWidth: BASE_SURFACE_W,
  windowHeight: BASE_SURFACE_H,
  maskWideView: 0,
  maskWidth: 0,
  viewWidth: BASE_SURFACE_W,
}

/** Per-pass uniform values, resolved exactly as `Surface_Step.gml:181-209` resolves them. */
export interface RetroUniforms {
  /** `RetroShaders_can_draw` — false means the whole shader chain is skipped. */
  anyEnabled: boolean
  saturationBrightness: {
    /** `RetroShaders_SaturationBrightness_can_draw`. */
    enabled: boolean
    /** `RetroShaders_Saturation_amount`. */
    saturation: number
    /** `RetroShaders_Brightness_amount`. */
    brightness: number
    /** `u_effect_type`, hardcoded to 1 at the ZALiA call site (`Surface_Draw_GUI_Begin.gml:24`). */
    effectType: number
  }
  scanlines: {
    /** `RetroShaders_Scanlines_can_draw`. */
    enabled: boolean
    /** `u_line_brightness`. */
    brightness: number
    /** `RetroShaders_Scanlines_line_height`, in *application-surface* rows. */
    lineHeight: number
  }
  bloom: {
    /** `RetroShaders_Bloom_can_draw`. */
    enabled: boolean
    /** `u_a`..`u_g`. */
    params: BloomParams
  }
  blur: {
    /** `RetroShaders_Blur_can_draw`. */
    enabled: boolean
    /** `GEE.dg_Blur[#Blur_EDIT, $5]`. */
    alpha: number
  }
  mask: {
    /** `g.MaskWideView && g.MaskWideView_w > 0` — independent of the shader toggles. */
    enabled: boolean
    /** Bar width per side as a fraction of the view, ready for the mask shader's UV compare. */
    frac: number
  }
}

/**
 * `Surface_Step.gml:181-209`, as a pure function.
 *
 * The two non-obvious bits, both faithful to the GML:
 * - Saturation and Brightness share one pass, so a disabled half contributes `0` rather than
 *   disabling the pass (`amount = EDIT * (ENABLE > 0)`).
 * - The widescreen mask is *not* gated by `RetroShaders_*`; ZALiA draws it in `Surface_Draw_End.gml`
 *   regardless of whether any shader runs.
 */
export function packRetroUniforms(s: RetroSettings): RetroUniforms {
  const satBright = s.saturationEnabled || s.brightnessEnabled
  const anyEnabled =
    s.live && s.enabled && (satBright || s.scanlinesEnabled || s.bloomEnabled || s.blurEnabled)
  return {
    anyEnabled,
    saturationBrightness: {
      enabled: anyEnabled && satBright,
      saturation: s.saturationEnabled ? s.saturation : 0,
      brightness: s.brightnessEnabled ? s.brightness : 0,
      effectType: SB_EFFECT_TYPE_ADD,
    },
    scanlines: {
      enabled: anyEnabled && s.scanlinesEnabled,
      brightness: s.scanlineBrightness,
      lineHeight: Math.max(1, s.surfaceScale / 2),
    },
    bloom: { enabled: anyEnabled && s.bloomEnabled, params: s.bloom },
    blur: { enabled: anyEnabled && s.blurEnabled, alpha: s.blurAlpha },
    mask: {
      enabled: s.maskWideView !== 0 && s.maskWidth > 0,
      frac: s.viewWidth > 0 ? Math.min(0.5, s.maskWidth / s.viewWidth) : 0,
    },
  }
}

/**
 * Convert ZALiA's `u_line_height` into rows of the *actual* Phaser render target.
 *
 * ZALiA sizes `application_surface` to `BASE_H * surface_scale` (`update_shaders_surf_resize.gml`),
 * so `max(1, scale/2)` is in scaled-surface rows. Phaser renders the camera at the game size
 * (480x270, `packages/game/src/index.ts`), so the value has to be rescaled — and clamped to >= 1,
 * because the shader's `mod(floor(h*v), lh*2.0) < lh` degenerates to "every row" once `lh < 1`.
 *
 * When the render target really is `BASE_H * scale` this is the identity, so the function stays
 * correct if the surface scale is ever honoured for real.
 */
export function scanlineHeightFor(
  lineHeight: number,
  targetHeight: number,
  surfaceScale: number,
  baseHeight = BASE_SURFACE_H,
): number {
  const surfaceHeight = baseHeight * Math.max(1, surfaceScale)
  if (surfaceHeight <= 0 || targetHeight <= 0) return 1
  return Math.max(1, Math.round((lineHeight * targetHeight) / surfaceHeight))
}

/** GML truthiness for the `number | boolean` fields the core carries. */
const truthy = (v: unknown): boolean => v !== 0 && v !== false && v !== undefined && v !== null

/** Source of the core state `readRetroSettings()` reads. Injected so tests can drive it. */
export interface RetroSettingsSource {
  /** `G` — undefined before `createWorld()` has run. */
  globals?:
    | {
        RetroShaders_IS_LIVE?: boolean | undefined
        RetroShaders_enabled?: boolean | number | undefined
        RetroShaders_surface_scale?: number | undefined
      }
    | null
    | undefined
  /** `g` — undefined before `createWorld()`; `g.surf` is `NOONE` (null) until the Surface port lands. */
  game?:
    | {
        surf?: { GEE?: GraphicsEffectsGrids | null | undefined } | null | undefined
        MaskWideView?: number | undefined
        MaskWideView_w?: number | undefined
        VIEW_W?: number | undefined
      }
    | null
    | undefined
  /** `windowState`. */
  window?: { width?: number | undefined; height?: number | undefined } | null | undefined
}

/**
 * Read one frame of settings out of the core (`G`, `g`, `windowState`).
 *
 * Every field falls back to `RETRO_DEFAULTS` when absent. That is the normal case today: the
 * `GraphicsEffectsEditor` and `Surface` object ports have not landed, so `g.surf` is `NOONE` (null)
 * and `g.surf.GEE` never exists — the chain runs on ZALiA's shipped defaults until it does.
 */
export function readRetroSettings(src: RetroSettingsSource): RetroSettings {
  const G = src.globals
  const g = src.game
  const gee = g?.surf?.GEE ?? null
  const cell = (grid: GeeValueGrid | undefined, row: number | undefined, fallback: number): number =>
    (grid && row !== undefined ? grid.get(row, GEE_VALUE_COL) : undefined) ?? fallback
  const on = (grid: GeeValueGrid | undefined, row: number | undefined, fallback: boolean): boolean =>
    grid && row !== undefined ? truthy(grid.get(row, GEE_VALUE_COL)) : fallback
  const d = RETRO_DEFAULTS
  return {
    live: G?.RetroShaders_IS_LIVE ?? d.live,
    enabled: truthy(G?.RetroShaders_enabled ?? d.enabled),
    surfaceScale: G?.RetroShaders_surface_scale ?? d.surfaceScale,
    saturationEnabled: on(gee?.dg_Saturation, gee?.Saturation_ENABLE, d.saturationEnabled),
    saturation: cell(gee?.dg_Saturation, gee?.Saturation_EDIT, d.saturation),
    brightnessEnabled: on(gee?.dg_Brightness, gee?.Brightness_ENABLE, d.brightnessEnabled),
    brightness: cell(gee?.dg_Brightness, gee?.Brightness_EDIT, d.brightness),
    scanlinesEnabled: on(gee?.dg_Scanlines, gee?.Scanlines_ENABLE, d.scanlinesEnabled),
    scanlineBrightness: cell(gee?.dg_Scanlines, gee?.Scanlines_EDIT, d.scanlineBrightness),
    bloomEnabled: on(gee?.dg_Bloom, gee?.Bloom_ENABLE, d.bloomEnabled),
    bloom: [
      cell(gee?.dg_Bloom, gee?.Bloom_A, d.bloom[0]),
      cell(gee?.dg_Bloom, gee?.Bloom_B, d.bloom[1]),
      cell(gee?.dg_Bloom, gee?.Bloom_C, d.bloom[2]),
      cell(gee?.dg_Bloom, gee?.Bloom_D, d.bloom[3]),
      cell(gee?.dg_Bloom, gee?.Bloom_E, d.bloom[4]),
      cell(gee?.dg_Bloom, gee?.Bloom_F, d.bloom[5]),
      cell(gee?.dg_Bloom, gee?.Bloom_G, d.bloom[6]),
    ],
    blurEnabled: on(gee?.dg_Blur, gee?.Blur_ENABLE, d.blurEnabled),
    blurAlpha: cell(gee?.dg_Blur, gee?.Blur_EDIT, d.blurAlpha),
    windowWidth: src.window?.width ?? d.windowWidth,
    windowHeight: src.window?.height ?? d.windowHeight,
    maskWideView: g?.MaskWideView ?? d.maskWideView,
    maskWidth: g?.MaskWideView_w ?? d.maskWidth,
    viewWidth: g?.VIEW_W ?? d.viewWidth,
  }
}
