/**
 * `PC_draw()` and `draw_pc_skin()`. ZALiA drew the composed character into a temporary surface and then drew
 * the surface scaled/rotated/tinted; here the parts are emitted as sprite draw commands about the same centre
 * with the combined scale/rotation (`Draw_xscale1*Draw_xscale2`, `Draw_rotation1+Draw_rotation2`), which is
 * what the surface achieved. The boss-explosion shadow is the same set of parts tinted black at `Shadow_DEPTH`.
 */
import {
  ITM_SHLD,
  ITM_SWRD,
  STR_Body,
  STR_Clm,
  STR_Current,
  STR_Idx,
  STR_Row,
  STR_Shield,
  STR_Sword,
} from '@z2/data'
import { gmBool } from '../../../nes/math8'
import { f, g, p } from '../../../runtime/world'
import { hex_str, val } from '../../other/index'
import { bgrToRgb } from '../../palette/colors'
import { PI_MOB_RED } from '../../palette/pi'
import { pal_swap_reset, pal_swap_set } from '../../palette/scenePalette'
import { draw_point_colour, draw_sprite_, drawState, pushCmd } from '../../rooms/draw'
import { draw_view_og_outline } from '../../view/window'
import { devDraw } from './deps'
import type { Lonk } from './Lonk'
import { pc } from './pc'

const C_WHITE = 0xffffff

interface Xform {
  xscale: number
  yscale: number
  rotation: number
  tint: number
}

/** One composed part of the character at the PC centre (+offset), with the frame's combined transform. */
function part(
  self: Lonk,
  sprite: string | 0,
  frame: number,
  xoff: number,
  yoff: number,
  palIdx: number,
  t: Xform,
): void {
  if (!sprite) return
  pushCmd({
    kind: 'sprite',
    sprite,
    frame,
    x: self.drawX + xoff,
    y: self.drawY + yoff,
    xscale: t.xscale,
    yscale: t.yscale,
    palIdx,
    depth: drawState.depth,
    alpha: 1,
    rotation: t.rotation,
    ...(t.tint !== C_WHITE ? { tint: bgrToRgb(t.tint) } : {}),
  })
}

function drawComposed(self: Lonk, t: Xform, palIdx: number): void {
  if (self.is_cucco) {
    if (self.Cucco_sprite_is_whole) {
      part(self, self.Cucco_sprite_body, 0, 0, 0, palIdx, t)
    } else {
      pal_swap_set(palIdx)
      if (self.Cucco_legs_draw_first) {
        // draw legs behind body
        part(self, self.Cucco_sprite_legs, 0, 0, 0, palIdx, t)
        part(self, self.Cucco_sprite_body, 0, 0, 0, palIdx, t)
      } else {
        part(self, self.Cucco_sprite_body, 0, 0, 0, palIdx, t)
        part(self, self.Cucco_sprite_legs, 0, 0, 0, palIdx, t)
      }
      if (self.Cucco_eye_can_draw && t.tint === C_WHITE) {
        draw_point_colour(
          self.drawX + self.Cucco_eye_xoff,
          self.drawY + self.Cucco_eye_yoff,
          self.Cucco_eye_color,
        )
      }
      part(self, self.Cucco_sprite_wing, 0, 0, self.Cucco_sprite_wing_yoff, palIdx, t)
      pal_swap_reset()
    }
  } else if (self.is_fairy) {
    part(self, self.fairy_sprite, 0, 0, 0, palIdx, t)
  } else {
    draw_pc_skin(
      self.drawX,
      self.drawY,
      t.xscale,
      t.yscale,
      self.Draw_behavior,
      self.Disguise_enabled,
      -1,
      -1,
      palIdx,
      t.tint,
      t.rotation,
    )
  }
}

/**
 * `draw_falling_scene.gml:67-81` — the cucco fall pose: a black body/legs/wing shadow at (+4,-5), the same
 * three sprites palette-swapped at (x, y), then the eye pixel. Lives here because the sprite names and the
 * eye colour are `global.pc` fields; the palette folder reaches it through `pcSeams.draw_pc_cucco_fall`.
 */
export function draw_pc_cucco_fall(_x: number, _y: number, _X_SCALE: number, _pi: number): void {
  const self = pc()
  const shadow = p.C_BLK1
  for (const spr of [
    self.CuccoFallScene_SPRITE_BODY,
    self.CuccoFallScene_SPRITE_LEGS,
    self.CuccoFallScene_SPRITE_WING,
  ])
    draw_sprite_(spr, 0, _x + 4, _y - 5, -1, _X_SCALE, 1, shadow)
  pal_swap_set(_pi)
  for (const spr of [
    self.CuccoFallScene_SPRITE_BODY,
    self.CuccoFallScene_SPRITE_LEGS,
    self.CuccoFallScene_SPRITE_WING,
  ])
    draw_sprite_(spr, 0, _x, _y, -1, _X_SCALE)
  pal_swap_reset()
  // GML: `_x += (_X_SCALE*2) - !_X_SCALE` — `!_X_SCALE` is 1 only when the scale is 0 or negative. The
  // eye is a 1×1 sprite, not `draw_point_colour`: the GML's own comment says the point does not draw here.
  draw_sprite_(
    'spr_1x1_WHT',
    0,
    _x + (_X_SCALE * 2 - (gmBool(_X_SCALE) ? 0 : 1)),
    _y - 5,
    -1,
    1,
    1,
    self.Cucco_eye_color,
  )
}

export function PC_draw(self: Lonk): void {
  const depthCopy = drawState.depth
  drawState.depth = self.depth
  if (self.can_draw_self) {
    if (self.RescueFairy_sprite)
      draw_sprite_(
        self.RescueFairy_sprite,
        0,
        self.RescueFairy_draw_x,
        self.RescueFairy_draw_y,
        PI_MOB_RED,
        1,
      )
    const t: Xform = {
      xscale: self.Draw_xscale1 * self.Draw_xscale2,
      yscale: self.Draw_yscale1 * self.Draw_yscale2,
      rotation: self.Draw_rotation1 + self.Draw_rotation2,
      tint: C_WHITE,
    }
    if (self.Shadow_can_draw) {
      // PC Shadow During Boss Explosion
      self.Shadow_can_draw = false
      drawState.depth = self.Shadow_DEPTH
      const shadowX = self.drawX
      self.drawX += self.Shadow_xoff
      drawComposed(self, { ...t, tint: p.C_BLK1 }, self.Draw_palidx)
      self.drawX = shadowX
      drawState.depth = self.depth
    }
    drawComposed(self, t, self.Draw_palidx)
  }
  if (g.DevTools_state) {
    devDraw.GO_draw_body_hb(self) // Body. Toggle with 'N'
    devDraw.GO_draw_sword_hb(self) // Sword. Toggle with 'N'
    devDraw.GO_draw_shield_hb(self) // Shield. Toggle with 'N'
    devDraw.GO_draw_ocs(self) // draw ocs lines. Toggle with 'C'
    devDraw.GO_draw_cs_points(self) // CS: Collide Solid points. Toggle with 'H'
    devDraw.PC_draw_scs(self) // SCS: Sword Collide Solid. Toggle with 'N'
    devDraw.PC_draw_hp(self) // Draw PC hp. Toggle with 'V'
    draw_view_og_outline() // Toggle with 'L'. Outline representing the og camera
  }
  drawState.depth = depthCopy
}

/**
 * `draw_pc_skin(x, y, xscale, yscale, *behavior, *use disguise, *shield level, *sword level, *palette idx,
 * *color, *rotation)` — shield, body, (disguise head), sword from the 16×6 spritesheet. Negative optional
 * args mean "use the PC's current value", as in the GML.
 */
export function draw_pc_skin(
  _X: number,
  _Y: number,
  _X_SCALE: number,
  _Y_SCALE: number,
  behavior = -1,
  useDisguise: boolean | number = -1,
  shieldLevel = 0,
  swordLevel = 0,
  palIdx = -1,
  color = -1,
  rotation = -1,
): void {
  const self = pc()
  const dm = self.dm_skins
  let _BEHAVIOR = self.behavior
  if (behavior >= 0) _BEHAVIOR = behavior
  _BEHAVIOR = Number(val(dm.get(STR_Clm + hex_str(_BEHAVIOR))))
  const _USE_DISGUISE = useDisguise === -1 ? self.Disguise_enabled : !!useDisguise
  // FIXED: GML tests these two with bare truthiness (`real > 0.5`), so every caller's `-1` sentinel is
  // FALSE and the computed default is kept. JS `||` treats -1 as truthy, so `-1` survived; `hex_str(-1)`
  // is "FFFFFFFF", both `dm_skins` row lookups missed, `val()` gave 0, and **the sword strip drew row 0 —
  // the shield** — so Link was rendered without a sword every frame, and the level-2 art was unreachable.
  const _SHIELD_LEVEL = gmBool(shieldLevel) ? shieldLevel : 1 + Math.sign(f.items & ITM_SHLD)
  const _SWORD_LEVEL = gmBool(swordLevel) ? swordLevel : 1 + Math.sign(f.items & ITM_SWRD)
  const _PALIDX = palIdx >= 0 ? palIdx : self.Draw_palidx
  const _COLOR = color >= 0 ? color : C_WHITE
  const _ROTATION = rotation >= 0 ? rotation : 0
  const t: Xform = { xscale: _X_SCALE, yscale: _Y_SCALE, rotation: _ROTATION, tint: _COLOR }
  const at = (sprite: string, frame: number) =>
    pushCmd({
      kind: 'sprite',
      sprite,
      frame,
      x: _X,
      y: _Y,
      xscale: t.xscale,
      yscale: t.yscale,
      palIdx: _PALIDX,
      depth: drawState.depth,
      alpha: 1,
      rotation: t.rotation,
      ...(t.tint !== C_WHITE ? { tint: bgrToRgb(t.tint) } : {}),
    })
  const isFile = !!val(dm.get(`${hex_str(Number(val(dm.get(STR_Current + STR_Idx))))}_source_is_file`))
  if (!isFile) {
    pal_swap_set(_PALIDX)
    const row = (key: string) => Number(val(dm.get(key)))
    // Shield
    if (!_USE_DISGUISE)
      at(self.Skin_image, row(STR_Row + STR_Shield + hex_str(_SHIELD_LEVEL)) * 0x10 + _BEHAVIOR)
    // Body
    at(self.Skin_image, row(STR_Row + STR_Body + hex_str(1 + (_USE_DISGUISE ? 1 : 0))) * 0x10 + _BEHAVIOR)
    // Head
    if (_USE_DISGUISE) {
      const _val = 0x5 + self.Disguise_Head_idx * 0x5
      at(self.Skin_image, row(`${STR_Row + STR_Body}02`) * 0x10 + _val + _BEHAVIOR)
    }
    // Sword
    at(self.Skin_image, row(STR_Row + STR_Sword + hex_str(_SWORD_LEVEL)) * 0x10 + _BEHAVIOR)
    pal_swap_reset()
  } else {
    // From 'custom_playercharacter_graphics' folder: one full-sheet image, cells addressed by (column, row).
    const W = self.Spritesheet_W
    const H = self.Spritesheet_H
    const _Sheet_X = _BEHAVIOR * W
    let _x = _X - (W >> 1) + W * (t.xscale > 0.5 ? 0 : 1)
    const _y = _Y - (H >> 1) + H * (t.yscale > 0.5 ? 0 : 1)
    const cell = (rowIdx: number, pal: number) =>
      pushCmd({
        kind: 'sheet',
        sprite: self.Skin_image,
        sx: _Sheet_X,
        sy: rowIdx * H,
        w: W,
        h: H,
        x: _x,
        y: _y,
        xscale: t.xscale,
        yscale: t.yscale,
        palIdx: pal,
        depth: drawState.depth,
        ...(t.tint !== C_WHITE ? { tint: bgrToRgb(t.tint) } : {}),
      })
    _x = _x + 0
    pal_swap_set(_PALIDX)
    if (!_USE_DISGUISE) cell(0 + (_SHIELD_LEVEL > 1 ? 1 : 0), _PALIDX) // Shield
    cell(2 + (_USE_DISGUISE ? 1 : 0), _PALIDX) // Body
    cell(_USE_DISGUISE ? 5 + self.Disguise_Head_idx : 4, _PALIDX) // Head
    pal_swap_reset()
    cell(8 + (_SWORD_LEVEL > 1 ? 1 : 0), -1) // Sword
    pal_swap_reset()
  }
}
