// Ported from ZALiA scripts/update_spell_effects.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively

import {
  dk_MagicalKeyHouse,
  dk_SceneName,
  PC_LOCK_ALL,
  SPL_FARY,
  SPL_FIRE,
  SPL_JUMP,
  SPL_LIFE,
  SPL_PRTC,
  SPL_RFLC,
  SPL_SPEL,
  SPL_SUMM,
  SPL_THUN,
  STR_Count,
  STR_Difficulty,
  STR_ENIGMA,
  STR_Enemy,
  STR_Object,
  STR_pal_idx,
  STR_Randomize,
  STR_Version,
} from '@z2/data'
import { hexStr as hex_str } from '../../nes/hexStr'
import { gmBool } from '../../nes/math8'
import { f, G, g } from '../../runtime/world'
import { ocsHV1, ocsHV3 } from '../collision/ocs'
import { GameObject_create } from '../game_object/create'
import { GO_update_cam_vars, is_ver } from '../game_object/go/misc'
import { damage_gob } from '../game_object/gob/GameObjectB'
import { despawn_all_goc } from '../game_object/goc/Projectile'
import { frameHooks } from '../hooks'
import { notPorted } from '../pending'
import { clamp, ds_list_size, irandom, max, min, object_get_name, val, withInstance } from './gm'

const pc_is_cucco = (...a: unknown[]) => (frameHooks.pc_is_cucco as (...x: unknown[]) => unknown)(...a)
const spawn_pc_proj_2a = (...a: unknown[]) =>
  (frameHooks.spawn_pc_proj_2a as (...x: unknown[]) => unknown)(...a)

/** GML: update_spell_effects() */
export function update_spell_effects() {
  // GML `var` is function-scoped; locals hoisted here:
  let _DAMAGE: any,
    _DIFFICULTY: any,
    _PI: any,
    _count: any,
    _datakey: any,
    _difficulty: any,
    _i: any,
    _idx: any,
    _num: any,
    _obj: any,
    _objver: any,
    _ver: any
  // 8E26
  if (!gmBool(g.spells_active)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // -------------------- SPL_SUMM ----------------------------
  // ----------------------------------------------------
  if (gmBool(g.spells_active & SPL_SUMM)) {
    // SUMMON SPELL
    g.spells_active &= ~SPL_SUMM
  }
  // -------------------- SPL_THUN ----------------------------
  // ----------------------------------------------------
  if (gmBool(g.spells_active & SPL_THUN)) {
    g.spells_active &= ~SPL_THUN
    if (gmBool(g.mod_ScreenShake)) {
      g.ScreenShake_timer = g.ScreenShake_DUR1
      g.ScreenShake_strength_x = 3
      g.ScreenShake_strength_y = 3
    }
    despawn_all_goc()
    // BEC7
    for (let _i = ds_list_size(g.go_mgr.dl_gob1) - 1; _i >= 0; _i--) {
      if (!gmBool(g.go_mgr.dl_gob1.get(_i) + 1)) {
        continue
      }
      /* TODO with */ withInstance(g.go_mgr.dl_gob1.get(_i), (self) => {
        // if NOT vulnerable to THUNDER
        if (self.state !== self.state_NORMAL || !gmBool(self.react_thunder)) {
          return //with(g.go_mgr.dl_gob1[|_i])
        }
        _DAMAGE = 0
        switch (self.react_thunder) {
          case 1: {
            // All hp ------------------------------------
            if (ocsHV1(self)) {
              _DAMAGE = max(0, self.hp)
            }
            break
          }
          case 2: {
            // BEE2: JSR E726 ----------------------------
            if (ocsHV1(self)) {
              _DAMAGE = 0x32
            }
            break
          }
          case 3: {
            // E66D: $02 ---------------------------------
            _DAMAGE = 0x02 // OG: Only Thunderbird
            break
          }
        } //switch(react_thunder)
        if (gmBool(_DAMAGE)) {
          damage_gob(self, _DAMAGE, false)
        }
      })
    }
  }
  // -------------------- SPL_SPEL ----------------------------
  // ----------------------------------------------------
  if (gmBool(g.spells_active & SPL_SPEL)) {
    g.spells_active &= ~SPL_SPEL
    // let _i: any, _idx, _num, _obj, _ver, _objver, _difficulty: any;
    // let _datakey: any;
    _DIFFICULTY = val(G.dm_save_file_settings.get(STR_Randomize + STR_Enemy + STR_Difficulty), 1)
    //if (g.rm_name==g.MKH_RM_NAME
    if (
      g.rm_name === val(g.dm_rm.get(dk_MagicalKeyHouse + dk_SceneName)) &&
      !gmBool(g.cutscene_house_built)
    ) {
      // Build MagicalKey house
      g.pc_lock = PC_LOCK_ALL // Lock all
    }
    // TURN ALL SUSCEPTIBLE ENEMIES INTO Bot
    for (_i = ds_list_size(g.go_mgr.dl_gob1) - 1; _i >= 0; _i--) {
      if (!gmBool(g.go_mgr.dl_gob1.get(_i) + 1)) {
        continue //_i
      }
      /* TODO with */ withInstance(g.go_mgr.dl_gob1.get(_i), (self) => {
        // react_spel: 1: turn into Bot, 2: Turn into Ache, 3: Turn into RestoreFairy
        if (!gmBool(self.state) || !gmBool(self.react_spell)) {
          return //with(g.go_mgr.dl_gob1[|_i])
        }
        GO_update_cam_vars(self)
        // if (less than half width AND NO height) are in ocs area
        if (!ocsHV3(self)) {
          return //with(g.go_mgr.dl_gob1[|_i])
        }
        self.timer = 0
        self.state = 0
        switch (self.react_spell) {
          default: {
            _obj = 'Bot_A'
            _ver = 1
            break
          }
          case 2: {
            _obj = 'Ache01'
            _ver = 1
            break
          }
          case 3: {
            _obj = 'ReFaA'
            _ver = 1
            break
          }
        }
        if (
          _obj !== 'ReFaA' &&
          gmBool(val(G.dm_save_file_settings.get(STR_Randomize + STR_Enemy + STR_ENIGMA)))
        ) {
          //_difficulty = RandoEnemy_difficulty_MAX;
          _difficulty = 0
          if (!gmBool(_difficulty) && _DIFFICULTY >= 4 && !gmBool(irandom(0x7f))) {
            _difficulty = 4
          }
          if (!gmBool(_difficulty) && _DIFFICULTY >= 3 && !gmBool(irandom(0x3f))) {
            _difficulty = 3
          }
          if (!gmBool(_difficulty) && _DIFFICULTY >= 2 && !gmBool(irandom(0x07))) {
            _difficulty = 2
          }
          _difficulty = clamp(_difficulty, 1, g.RandoEnemy_difficulty_MAX)
          _datakey = STR_ENIGMA + STR_Difficulty + hex_str(_difficulty)
          _count = val(g.dm_RandoEnemy.get(_datakey + STR_Count))
          if (_count > 1) {
            _idx = irandom(_count - 1)
            _datakey += hex_str(_idx)
            _obj = val(g.dm_RandoEnemy.get(_datakey + STR_Object), _obj)
            _ver = val(g.dm_RandoEnemy.get(_datakey + STR_Version), 1)
          }
          /* // keeping this as backup
                var                             _dl_CHANCES=ds_list_create();
                if (_DIFFICULTY>=1) ds_list_add(_dl_CHANCES,1,1,1,1,1,1,1,1);
                if (_DIFFICULTY>=2) ds_list_add(_dl_CHANCES,2,2,2,2,2);
                if (_DIFFICULTY>=3) ds_list_add(_dl_CHANCES,3,3);
                if (_DIFFICULTY>=4) ds_list_add(_dl_CHANCES,4);
                ds_list_shuffle(_dl_CHANCES);
                _difficulty =   _dl_CHANCES[|0];
                ds_list_destroy(_dl_CHANCES); _dl_CHANCES=undefined;
                */
          /* // keeping this as backup
                switch(irandom($1A)){
                case $00:{_obj=Bot_A; _ver=1; break;}
                case $01:{_obj=Bot_A; _ver=2; break;}
                case $02:{_obj=BoBoA; _ver=1; break;}
                case $03:{_obj=Ache01; _ver=1; break;}
                case $04:{_obj=Ache01; _ver=2; break;} // Acheman
                case $05:{_obj=Wheep; _ver=1; break;}
                case $06:{_obj=LowdA; _ver=1; break;}
                case $07:{_obj=MegmA; _ver=1; break;}
                case $08:{_obj=Myu_A; _ver=1; break;}
                case $09:{_obj=OctoA; _ver=1; break;}
                case $0A:{_obj=OctoA; _ver=2; break;} // walking Octorok
                case $0B:{_obj=AnerA; _ver=1; break;}
                case $0C:{_obj=AnerA; _ver=2; break;} // walking Aneru
                case $0D:{_obj=AnerA; _ver=3; break;} // fire Aneru
                case $0E:{_obj=BubbA; _ver=1; break;}
                case $0F:{_obj=BubbA; _ver=2; break;} // fast Bubble
                case $10:{_obj=BubbA; _ver=8; break;} // King Bubble
                case $11:{_obj=Moa_A; _ver=1; break;} // red Moa
                case $12:{_obj=Moa_B; _ver=3; break;} // fire Moa
                case $13:{_obj=AttaA; _ver=1; break;}
                case $14:{_obj=BoonA; _ver=1; break;}
                case $15:{_obj=GiruA; _ver=1; break;}
                case $16:{_obj=Stallakk; _ver=1; break;}
                case $17:{_obj=BlazA; _ver=1; break;}
                case $18:{_obj=BlazA; _ver=2; break;} // hopping Blaze
                case $19:{_obj=FiRoA; _ver=1; break;} // spinning fire rope
                case $1A:{_obj=SpTrC; _ver=1; break;}
                }
                */
        }
        _objver = object_get_name(_obj) + hex_str(_ver)
        _PI = val(g.dm_go_prop.get(_objver + STR_pal_idx), self.palidx_def)
        g.go_mgr.uIdxSwap_gob = self.update_idx
        /* TODO with */ withInstance(GameObject_create(self.xl, self.yt, _obj, _ver, -1, _PI), (self) => {
          if (gmBool(is_ver(self, 'Bot_A', 1))) {
            self.hp = 0
          }
        })
      })
    }
  }
  // -------------------- SPL_RFLC ----------------------------
  // ----------------------------------------------------
  if (gmBool(g.spells_active & SPL_RFLC)) {
    //
  }
  // -------------------- SPL_FIRE ----------------------------
  // ----------------------------------------------------
  if (gmBool(g.spells_active & SPL_FIRE)) {
    if (!gmBool(pc_is_cucco()) || (gmBool(g.CUCCO_CAN_FIRE) && gmBool(f.Cucco_skills & f.CuccoSkill_PROJ2))) {
      spawn_pc_proj_2a()
    }
  }
  // -------------------- SPL_FARY ----------------------------
  // ----------------------------------------------------
  if (gmBool(g.spells_active & SPL_FARY)) {
    //
  }
  // -------------------- SPL_LIFE ----------------------------
  // ----------------------------------------------------
  if (gmBool(g.spells_active & SPL_LIFE)) {
    g.spells_active &= ~SPL_LIFE
    g.StatRestore_timer_hp += g.StatRestore_DURATION1 // g.StatRestore_DURATION1: $30;
    g.StatRestore_timer_hp = min(g.StatRestore_timer_hp, f.HP_MAX)
  }
  // -------------------- SPL_JUMP ----------------------------
  // ----------------------------------------------------
  if (gmBool(g.spells_active & SPL_JUMP)) {
    //
  }
  // -------------------- SPL_SHLD ----------------------------
  // ----------------------------------------------------
  if (gmBool(g.spells_active & SPL_PRTC)) {
    //
  }
}
