import {
  Area_FileS,
  Area_OvrwA,
  Area_Title,
  dk_ContinueSave,
  dk_Credits,
  dk_DeathMountain,
  dk_FileSelect,
  dk_Intro_CanPlay,
  dk_MazeIsland,
  dk_SceneMusicThemeException,
  dk_ShadowBoss,
  dk_ThunderBird,
  dk_ValleyOfDeath,
  dk_WakeZelda,
  STR_Basement,
  STR_Battle,
  STR_Boss,
  STR_Bulblin,
  STR_Darunia,
  STR_Dragmire,
  STR_Dungeon,
  STR_Ganon,
  STR_Halloween,
  STR_House,
  STR_Intro,
  STR_Makarrha,
  STR_Mido,
  STR_Music,
  STR_Nabooru,
  STR_New_Kasuto,
  STR_Old_Kasuto,
  STR_Outside,
  STR_Overworld,
  STR_Rauru,
  STR_Ruto,
  STR_Saria,
  STR_Standard,
  STR_Title,
  STR_Town,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { world } from '../../runtime/world'
import { Audio } from './Audio'
import { fd, Gd, gd } from './deps'
import { aud_play_sound, audio_stop_sound } from './play'
import { get_audio_theme_track, get_audio_theme_track_random } from './theme'

const val = <T>(v: T | undefined, dflt?: T): T | 0 => (v === undefined ? (dflt === undefined ? 0 : dflt) : v)

/**
 * `Audio_Room_Start()` — decide the music theme for the room being entered, resolve its track in the
 * current audio set, and reset the intro "can play" flags. Ported from `Audio_Room_Start.gml`.
 */
export function Audio_Room_Start(): void {
  const A = Audio
  const dm = A.dm
  const g = gd()
  const f = fd()
  const G = Gd()

  const _ROOM_A = g.room_type === 'A'
  const _ROOM_B = g.room_type === 'B'
  const _ROOM_C = g.room_type === 'C'

  let _RM_NAME = g.rm_name ?? ''
  if (!_ROOM_A) _RM_NAME = g.room
  switch (g.room) {
    case 'rmB_Title':
      _RM_NAME = `${Area_Title}00`
      break
    case 'rmB_FileSelect':
      _RM_NAME = `${Area_FileS}00`
      break
    case 'rmC_Overworld_A':
      _RM_NAME = `${Area_OvrwA}00`
      break
  }

  const ow = G.OVERWORLD
  const _AREA_NAME = ow ? String(ow.dg_AreaNames.get(ow.pcrc & 0xff, (ow.pcrc >> 8) & 0xff) ?? '') : ''

  // ----------------------------------------------------------------
  A.can_play_boss_music = false

  // ----------------------------------------------------------------
  A.mus_rm_body_prev = A.mus_rm_body
  A.rm_music_theme_prev = A.rm_music_theme
  let rm_music_theme = val(g.dm_rm.get(_RM_NAME + STR_Music) as string | undefined, 'undefined') as string
  rm_music_theme = val(f.dm_rando.get(_RM_NAME + STR_Music) as string | undefined, rm_music_theme) as string

  if (g.room === 'rmB_ContinueSave') {
    rm_music_theme = dk_ContinueSave
  } else if (!_ROOM_B) {
    if (_ROOM_A && g.town_name === STR_Bulblin && !G.pc?.Disguise_enabled) {
      // set in g.Room_Start()
      rm_music_theme = `${STR_Battle}02` // only difference is Niko's audio set will be a fuller variation of battle theme
    } else if (
      _ROOM_A &&
      g.rm_name === val(g.dm_rm.get('GameEnd1B_RM_NAME')) &&
      rm_music_theme === dk_WakeZelda &&
      f.quest_num >= 2
    ) {
      rm_music_theme = `${dk_WakeZelda}2`
    } else {
      // _c1 is for: Most Death Mtn caves, Restore Fairy scenes, encounters, falling scenes.
      // This is to prevent scenarios where certain tracks can be annoying when they're cut off and then
      // restarted often (like in Death Mtn)
      let _c1 = false
      if (_ROOM_A && dm.get(`${dk_SceneMusicThemeException}01${_RM_NAME}`) !== undefined) {
        if (
          dm.get(`${dk_SceneMusicThemeException}01${A.audio_set}`) !== undefined ||
          (A.audio_set.toUpperCase().includes('RANDOM') &&
            dm.get(`${dk_SceneMusicThemeException}01${A.audio_get_name(A.mus_rm_body_prev)}`) !== undefined)
        ) {
          _c1 = true
        }
      }
      if (_c1 && (g.town_num || g.dungeon_num)) {
        if (g.town_num) rm_music_theme = g.town_name ?? rm_music_theme
        else if (g.dungeon_num) rm_music_theme = STR_Dungeon + hexStr(g.dungeon_num)
      } else if (_c1 || _ROOM_C) {
        if (_AREA_NAME.includes('DEATH MOUNTAIN'))
          rm_music_theme = STR_Overworld + dk_DeathMountain // Death Mtn
        else if (_AREA_NAME.includes('MAZE ISLAND'))
          rm_music_theme = STR_Overworld + dk_MazeIsland // Maze Isl
        else if (_AREA_NAME.includes('VALLEY OF DEATH'))
          rm_music_theme = STR_Overworld + dk_ValleyOfDeath // Valley of Death
        else if (_AREA_NAME.includes('DRAGMIRE'))
          rm_music_theme = STR_Overworld + STR_Dragmire // Dragmire
        else if (_AREA_NAME.includes('MAKARRHA'))
          rm_music_theme = STR_Overworld + STR_Makarrha // Makarrha
        else rm_music_theme = STR_Overworld + STR_Standard // Normal
      }
    }
  }
  rm_music_theme = String(rm_music_theme)

  const _dl_halloween_music_towns = [
    STR_Rauru,
    STR_Ruto,
    STR_Saria,
    STR_Mido,
    STR_Nabooru,
    STR_Darunia,
    STR_New_Kasuto,
  ]
  if (g.coming_from === g.coming_from_FILE || g.coming_from === g.coming_from_CONT) {
    const _dl = [...G.dl_Halloween_TOWN_MUSIC].filter((x): x is string => typeof x === 'string')
    for (let i = _dl.length - 1; i > 0; i--) {
      const j = world.irandom(i)
      const t = _dl[i] as string
      _dl[i] = _dl[j] as string
      _dl[j] = t
    }
    const _SIZE = _dl.length
    // FIDELITY: GML did `_dl[|_i mod _SIZE]` unguarded; with no Halloween tracks in the build that divides by 0
    if (_SIZE)
      for (let _i = _dl_halloween_music_towns.length - 1; _i >= 0; _i--)
        dm.set(STR_Halloween + STR_Music + _dl_halloween_music_towns[_i], _dl[_i % _SIZE] as string)
  }

  let _use_town_halloween_music = false
  if (
    _ROOM_A &&
    G.Halloween1_enabled &&
    g.town_name !== undefined &&
    _dl_halloween_music_towns.includes(g.town_name)
  ) {
    if (rm_music_theme === `${STR_House}01` || _dl_halloween_music_towns.includes(rm_music_theme)) {
      if (
        val(g.dm_rm.get(`${g.rm_name}${STR_Town}${STR_Outside}`)) ||
        val(g.dm_rm.get(`${g.rm_name}${STR_Town}${STR_House}`))
      ) {
        _use_town_halloween_music = true
        rm_music_theme = g.town_name
      }
    }
  }
  A.rm_music_theme = rm_music_theme
  const _IS_DIFF_THEME = rm_music_theme !== A.rm_music_theme_prev

  // ----------------------------------------------------------------
  A.can_play_mus_rm_body = true
  if (A.audio_set.toUpperCase().includes('RANDOM')) {
    if (_IS_DIFF_THEME) A.mus_rm_body = get_audio_theme_track_random(rm_music_theme)
  } else {
    A.mus_rm_body = get_audio_theme_track(rm_music_theme)
  }
  if (_use_town_halloween_music) {
    A.mus_rm_body = val(
      dm.get(STR_Halloween + STR_Music + g.town_name) as string | undefined,
      A.mus_rm_body,
    ) as typeof A.mus_rm_body
  }
  const _IS_DIFF_BODY = A.mus_rm_body !== A.mus_rm_body_prev

  if (_IS_DIFF_THEME && _IS_DIFF_BODY) {
    A.mus_rm_intr = val(
      dm.get(A.audio_get_name(A.mus_rm_body) + STR_Intro) as string | undefined,
    ) as typeof A.mus_rm_intr
  } else {
    A.mus_rm_intr = 0
    if (dm.get(rm_music_theme + dk_Intro_CanPlay) !== undefined)
      dm.set(rm_music_theme + dk_Intro_CanPlay, false)
  }

  // ----------------------------------------------------------------
  if (_IS_DIFF_BODY) {
    if (g.ChangeRoom_timer > 0) A.can_play_mus_rm_body = false
    A.dm_music_inst.clear()
    A.push({ kind: 'stopGroup', group: 'mus' })
    world.emit({ kind: 'music', theme: null })
    A.mus_rm_inst = aud_play_sound('snd_0')
    A.mus_rm_pos_prev = 0
    A.mus_rm_pos_curr = 0
    A.mus_rm_body_last_pos = 0
  }
  // (the `else if (0)` encounter-interruption block in the GML is permanently disabled — dropped)

  // ----------------------------------------------------------------
  audio_stop_sound('snd_Default_Title_Intro_no_volume')
  audio_stop_sound('snd_Default_Title_no_volume')
  A.timing_sound_inst = 0
  A.timing_sound_position_prev = 0
  A.timing_sound_position_curr = 0

  // ----------------------------------------------------------------
  // I believe the following "_CanPlay" lines should run regardless if the set is STR_Random
  const canPlay = (theme: string) => dm.set(theme + dk_Intro_CanPlay, true)
  if (_ROOM_B) {
    if (g.room === 'rmB_Title') canPlay(STR_Title)
    if (g.room === 'rmB_FileSelect') canPlay(dk_FileSelect)
    if (g.room === 'rmB_ContinueSave') canPlay(dk_ContinueSave)
    if (g.room === 'rmB_FileSelect' || g.room === 'rmB_ContinueSave') {
      canPlay(STR_Overworld + STR_Standard) // Normal Overworld theme
      canPlay(STR_Overworld + dk_DeathMountain) // Death Mtn
      canPlay(STR_Overworld + dk_MazeIsland) // Maze Isl
      canPlay(STR_Overworld + dk_ValleyOfDeath) // Valley of Death
      canPlay(STR_Overworld + STR_Dragmire) // Dragmire
      canPlay(STR_Overworld + STR_Makarrha) // Makarrha
    }
  }
  if (!_AREA_NAME.includes('DEATH MOUNTAIN')) canPlay(STR_Overworld + dk_DeathMountain)
  else if (!_AREA_NAME.includes('MAZE ISLAND')) canPlay(STR_Overworld + dk_MazeIsland)
  else if (!_AREA_NAME.includes('VALLEY OF DEATH')) canPlay(STR_Overworld + dk_ValleyOfDeath)
  else if (!_AREA_NAME.includes('DRAGMIRE')) canPlay(STR_Overworld + STR_Dragmire)
  else if (!_AREA_NAME.includes('MAKARRHA')) canPlay(STR_Overworld + STR_Makarrha)
  else canPlay(STR_Overworld + STR_Standard)

  const _ROOM_B1 =
    _ROOM_B && (g.room === 'rmB_Title' || g.room === 'rmB_FileSelect' || g.room === 'rmB_ContinueSave')
  if (_ROOM_B1 || _ROOM_C || (_ROOM_A && !g.town_num)) {
    for (const t of [
      STR_Rauru,
      STR_Ruto,
      STR_Saria,
      STR_Mido,
      STR_Nabooru,
      STR_Darunia,
      STR_New_Kasuto,
      STR_Old_Kasuto,
      STR_Bulblin,
    ])
      canPlay(t)
  }
  if (_ROOM_B1 || _ROOM_C || (_ROOM_A && !g.dungeon_num)) {
    for (let d = 1; d <= 8; d++) canPlay(`${STR_Dungeon}0${d}`)
  }
  const canPlayIfOther = (theme: string) => {
    if (rm_music_theme !== theme && dm.get(theme + dk_Intro_CanPlay) !== undefined)
      dm.set(theme + dk_Intro_CanPlay, true)
  }
  canPlayIfOther(`${STR_Boss}01`) // Normal boss music
  canPlayIfOther(`${STR_Ganon}1`)
  canPlayIfOther(`${STR_Ganon}2`)
  canPlayIfOther(`${STR_Ganon}3`)
  canPlayIfOther(dk_ThunderBird)
  canPlayIfOther(`${dk_ShadowBoss}01`) // Dark Lonk 1st Quest
  canPlayIfOther(`${dk_ShadowBoss}02`) // Dark Lonk 2nd Quest
  canPlayIfOther(`${STR_Battle}01`)
  canPlayIfOther(`${STR_Battle}02`)
  canPlayIfOther(`${STR_House}01`)
  canPlayIfOther(`${STR_Basement}01`)
  canPlayIfOther(dk_Credits)
}
