/**
 * `Overworld_Step()` — overworld movement on the 16 px grid, hammer/flute actions, boulder circle,
 * River Devil, Three-Eye-Rock palace reveal, raft, exits, flute warp state machine, water sparkles and
 * the boots-tile indicator, tile scrolling. Ported from `scripts/Overworld_Step.gml`.
 */
import {
  dk_BlockBreak,
  dk_Fanfare,
  ITM_BOOT,
  ITM_FLUT,
  ITM_HAMM,
  ITM_RAFT,
  MK_OWRC_PAL_THRE1,
  MK_OWRC_TWN_NEWK1,
  OST_BOOTS1,
  OST_BOOTS2,
  OST_SOLID1,
  OST_SOLID2,
  STR_Boulder,
  STR_Circle,
  STR_Complete,
  STR_Dungeon,
  STR_Exit,
  STR_Fairy,
  STR_Flute,
  STR_Forest,
  STR_Greeting,
  STR_Hammer,
  STR_Item,
  STR_Locations,
  STR_Open,
  STR_Order,
  STR_OWRC,
  STR_Qualified,
  STR_Raft,
  STR_Randomize,
  STR_River_Devil,
  STR_RmName,
  STR_Secret,
  STR_Spell,
  STR_State,
  STR_Town,
  STR_TSRC,
  STR_Under,
  STR_Warp,
  TSRC_BOUL01,
  TSRC_BRDG1B,
  TSRC_GRAS01,
  TSRC_HOUSE04,
  TSRC_PALA02,
  TSRC_PATH02,
  TSRC_PATH03,
  TSRC_SWAM01,
  TSRC_SWAM02,
  TSRC_SWAM03,
  TSRC_SWAM04,
  TSRC_TOWN08,
  TSRC_TREE01,
} from '@z2/data'
import { gmBool } from '../../nes/math8'
import { f, G, g, input, p } from '../../runtime/world'
import { is_in_grid } from '../collision/geometry'
import { bit_dir, bitNum, inRange, isVal } from '../math'
import { hex_str, str_hex, strR, val } from '../other'
import { aud_play_sound, audio_stop_sound } from '../sound/play'
import { get_audio_theme_track } from '../sound/theme'
import { background_assign, tile_layer_shift } from '../tile'
import { audio_sound_length_frames, frac } from './deps'
import { Overworld_enc_inst_update, Overworld_enc_spawn_update } from './encounters'
import type { Overworld } from './Overworld'
import {
  Overworld_refresh_tiles,
  Overworld_tile_change_1a,
  Overworld_tile_change_3,
  WaterSparkle_get_new_rc,
  WaterSparkle_refresh,
} from './tiles'
import { Overworld_udp } from './udp'

/** `Overworld_Step()` */
export function Overworld_Step(self: Overworld): void {
  const SHIFT = self.SHIFT
  const T_SIZE = self.T_SIZE
  const dm = self.dm
  let _i: number
  let _idx: number
  let _val: number | string | undefined
  let _val1: unknown
  let _count: number
  let _rm_clm: number
  let _rm_row: number
  let _pc_clm: number
  let _pc_row: number
  let _owrc: number
  let _ow_clm: number
  let _ow_row: number
  let _tsrc: number
  let _tsrc1: number
  let _datakey: string
  let _data: string | number
  const _C1 = !self.dest_dist && !self.exit_owrc && !self.flute_timer
  // -------------------------------------------------------------------
  self.RandoTSRC_active = G.can_rando_ow_tsrc && self.dm_Rando_TSRC.size > 0
  self.move_x = 0
  self.move_y = 0
  if (_C1) {
    if (input.heldHV & 0x01)
      self.pc_dir = 0x01 // Right
    else if (input.heldHV & 0x02)
      self.pc_dir = 0x02 // Left
    else if (input.heldHV & 0x04)
      self.pc_dir = 0x04 // Down
    else if (input.heldHV & 0x08) self.pc_dir = 0x08 // Up
  }
  const _PC_DIR_SIGN_X = bit_dir(self.pc_dir & 0x03)
  const _PC_DIR_SIGN_Y = bit_dir(self.pc_dir & 0x0c)
  const _area = self.dg_area.get((self.pcrc >> 0) & 0xff, (self.pcrc >> 8) & 0xff) ?? -1 // -1: No area
  if (_area + 1 && (_area & 0xff) < g.dl_AREA_NAME.size) g.area_name = g.dl_AREA_NAME.get(_area & 0xff)
  // --------------------------------------------------------------------------------
  // _C1 = !dest_dist && !exit_owrc && !flute_timer;
  if (_C1 && !self.Warp_is_warping && input.heldHV) {
    // Checking to see if move will still be in permitted area
    _pc_clm = ((self.pcrc >> 0) & 0xff) + _PC_DIR_SIGN_X
    _pc_row = ((self.pcrc >> 8) & 0xff) + _PC_DIR_SIGN_Y
    _ow_clm = _pc_clm + _PC_DIR_SIGN_X * self.OW_CLMS_PAD // pad=$B
    _ow_row = _pc_row + _PC_DIR_SIGN_Y * self.OW_ROWS_PAD // pad=$A
    // if view after move will be w/in allowable ow area
    if (is_in_grid(_ow_clm, _ow_row, self.OW_CLMS, self.OW_ROWS)) {
      const _solid = self.dg_solid.get(_pc_clm, _pc_row) ?? 0
      // OST_SOLID1 = $01, OST_SOLID2 = OST_SOLID1+1
      // OST_BOOTS1 = $11, OST_BOOTS2 = OST_BOOTS1+1
      if (!_solid || !isVal(_solid, OST_SOLID1, OST_SOLID2)) {
        if (f.items & ITM_BOOT || !isVal(_solid, OST_BOOTS1, OST_BOOTS2)) {
          self.dest_dist = T_SIZE // T_SIZE: $10
          self.mot = self.MOT_WALK
          self.move_distance = 0
          _tsrc = self.dg_tsrc.get(_pc_clm, _pc_row) ?? 0
          _tsrc1 = _tsrc & 0xff
          if (
            _tsrc1 === TSRC_SWAM01 ||
            _tsrc1 === TSRC_SWAM02 ||
            _tsrc1 === TSRC_SWAM03 ||
            _tsrc1 === TSRC_SWAM04
          ) {
            self.move_spd = self.MOVE_SPD_2
            self.move_speed = self.move_SPEED2
            if (self.RandoTSRC_active) {
              self.move_spd = self.MOVE_SPD_1
              self.move_speed = self.move_SPEED1
            }
          } else {
            self.move_spd = self.MOVE_SPD_1
            self.move_speed = self.move_SPEED1
          }
        }
      }
    }
  }
  // pressedC: 'a' or 'b' pressed
  if (!self.dest_dist && input.pressedC) {
    if (input.Jump_pressed) {
      // var _C1 = !dest_dist && !exit_owrc && !flute_timer;
      if (f.items & ITM_HAMM && _C1) {
        _pc_clm = (self.pcrc >> 0) & 0xff
        _pc_row = (self.pcrc >> 8) & 0xff
        _ow_clm = (_pc_clm + _PC_DIR_SIGN_X) & 0xff
        _ow_row = (_pc_row + _PC_DIR_SIGN_Y) & 0xff
        _owrc = (_ow_row << 8) | _ow_clm
        _rm_clm = (self.DRAW_CLMS >> 1) + _PC_DIR_SIGN_X
        _rm_row = (self.DRAW_ROWS >> 1) + _PC_DIR_SIGN_Y
        _tsrc = self.dg_tsrc.get(_ow_clm, _ow_row) ?? 0
        _tsrc1 = _tsrc & 0xff
        if (self.RandoTSRC_active) {
          _val1 = self.dm_Rando_TSRC.get(hex_str(_tsrc))
          if (_val1 !== undefined) _tsrc = ((_val1 as number) >> 2) << 2
        }
        // New Kasuto
        if (_owrc === val(dm.get(MK_OWRC_TWN_NEWK1))) {
          if (!gmBool(val(dm.get(hex_str(_owrc) + STR_Open)))) {
            dm.set(hex_str(_owrc) + STR_Open, 1)
            _tsrc = (self.TILESET1_TS_IDX << 8) | TSRC_TOWN08 // $72: town w/ grass bg & green roofs
            Overworld_tile_change_1a(self, _rm_clm, _rm_row, _ow_clm, _ow_row, _tsrc)
            aud_play_sound(get_audio_theme_track(dk_BlockBreak))
            aud_play_sound(get_audio_theme_track(dk_Fanfare), -1, false, -1, dk_Fanfare)
            if (g.anarkhyaOverworld_MAIN && g.anarkhyaOverworld_enabled) {
              Overworld_tile_change_3(
                self,
                self.anarkhya_TSRC_NEWKAS,
                _rm_clm << SHIFT,
                _rm_row << SHIFT,
                self.anarkhya_TILE_DEPTH1,
                0,
              )
              self.dg_anarkhya_tsrc.set(_ow_clm, _ow_row, self.anarkhya_TSRC_NEWKAS)
            }
          }
        } else if (dm.get(STR_Forest + STR_Hammer + hex_str(_owrc)) !== undefined) {
          // CUCCO spell secret
          _datakey = STR_Forest + STR_Hammer
          _data = dm.get(_datakey + hex_str(_owrc)) as string
          // _data example: "_Forest_Hammer_0101"
          _data = strR(_data, _datakey.length + 2)
          _data = str_hex(_data)
          switch (_data) {
            case 0x0101: {
              if (!gmBool(val(dm.get(hex_str(_owrc) + STR_Open)))) {
                dm.set(hex_str(_owrc) + STR_Open, 1)
                _tsrc = (self.TILESET1_TS_IDX << 8) | TSRC_HOUSE04 // HOUSE04: Single house on grass
                aud_play_sound(get_audio_theme_track(STR_Secret))
                Overworld_tile_change_1a(self, _rm_clm, _rm_row, _ow_clm, _ow_row, _tsrc)
                aud_play_sound(get_audio_theme_track(dk_BlockBreak))
              }
              break
            }
            default: {
              _tsrc = (self.TILESET1_TS_IDX << 8) | TSRC_GRAS01 // $20: field
              Overworld_tile_change_1a(self, _rm_clm, _rm_row, _ow_clm, _ow_row, _tsrc)
              aud_play_sound(get_audio_theme_track(dk_BlockBreak))
              break
            }
          }
        } else if (_tsrc1 === TSRC_TREE01) {
          // Forest
          _tsrc = (self.TILESET1_TS_IDX << 8) | TSRC_GRAS01 // $20: field
          Overworld_tile_change_1a(self, _rm_clm, _rm_row, _ow_clm, _ow_row, _tsrc)
          aud_play_sound(get_audio_theme_track(dk_BlockBreak))
        } else if (inRange(_tsrc1, TSRC_BOUL01, TSRC_BOUL01 + 7)) {
          // Boulder
          _tsrc = val(
            dm.get(hex_str(_owrc) + STR_TSRC + STR_Under + STR_Boulder),
            (self.TILESET1_TS_IDX << 8) | TSRC_PATH03,
          ) as number
          Overworld_tile_change_1a(self, _rm_clm, _rm_row, _ow_clm, _ow_row, _tsrc)
          aud_play_sound(get_audio_theme_track(dk_BlockBreak))
          if (g.anarkhyaOverworld_MAIN && g.anarkhyaOverworld_enabled) {
            if (self.dl_BoulderCircle_OWRC.findIndex(_owrc) === -1) {
              Overworld_tile_change_3(
                self,
                self.anarkhya_TSRC_RUBBLE,
                _rm_clm << SHIFT,
                _rm_row << SHIFT,
                self.anarkhya_TILE_DEPTH2,
                0,
              )
              self.dg_anarkhya_tsrc_detail.set(_ow_clm, _ow_row, self.anarkhya_TSRC_RUBBLE)
            } else {
              // No rubble for boulder circle boulders
              Overworld_tile_change_3(
                self,
                0,
                _rm_clm << SHIFT,
                _rm_row << SHIFT,
                self.anarkhya_TILE_DEPTH2,
                -1,
              )
              self.dg_anarkhya_tsrc_detail.set(_ow_clm, _ow_row, 0)
            }
          }
          _datakey = STR_Boulder + STR_Circle
          if (!gmBool(val(f.dm_quests.get(_datakey + STR_Complete)))) {
            _idx = self.dl_BoulderCircle_OWRC.findIndex(_owrc)
            if (_idx + 1) {
              self.dl_BoulderCircle_broke_order.add(_idx + 1)
              _count = self.dl_BoulderCircle_broke_order.size
              if (_count === 8) {
                let _complete = true
                for (_i = 0; _i < _count; _i++) {
                  _val = f.dm_quests.get(_datakey + STR_Order + hex_str(_i + 1)) as number | undefined
                  if (_val === undefined || _val !== self.dl_BoulderCircle_broke_order.get(_i)) {
                    _complete = false
                    break
                  }
                }
                if (_complete) {
                  // Break order was correct
                  f.dm_quests.set(_datakey + STR_Complete, 1)
                  _owrc = self.BoulderCircle_center_OWRC
                  _ow_clm = (_owrc >> 0) & 0xff
                  _ow_row = (_owrc >> 8) & 0xff
                  _pc_clm = (self.pcrc >> 0) & 0xff
                  _pc_row = (self.pcrc >> 8) & 0xff
                  _rm_clm = (self.DRAW_CLMS >> 1) + (_ow_clm - _pc_clm)
                  _rm_row = (self.DRAW_ROWS >> 1) + (_ow_row - _pc_row)
                  _tsrc = self.BoulderCircle_center_TSRC // $C8: Hole in ground
                  Overworld_tile_change_1a(self, _rm_clm, _rm_row, _ow_clm, _ow_row, _tsrc)
                  aud_play_sound(get_audio_theme_track(STR_Secret))
                  if (g.anarkhyaOverworld_MAIN && g.anarkhyaOverworld_enabled) {
                    Overworld_tile_change_3(
                      self,
                      self.anarkhya_TSRC_HOLE,
                      _rm_clm << SHIFT,
                      _rm_row << SHIFT,
                      self.anarkhya_TILE_DEPTH1,
                      0,
                    )
                    self.dg_anarkhya_tsrc.set(_ow_clm, _ow_row, self.anarkhya_TSRC_HOLE)
                  }
                }
              }
            }
          }
        }
      }
    } else if (input.Attack_pressed) {
      if (f.items & ITM_FLUT) {
        let _warp_qualified = false
        // if any warp locations have been opened
        if (
          g.Rando_FLUTE_WARPING &&
          input.Magic_held &&
          gmBool(val(f.dm_quests.get(STR_Warp + STR_Qualified)))
        ) {
          const S = f.dm_save_file_settings
          if (
            gmBool(val(S.get(STR_Randomize + STR_Item + STR_Locations))) ||
            gmBool(val(S.get(STR_Randomize + STR_Spell + STR_Locations))) ||
            gmBool(val(S.get(STR_Randomize + STR_Dungeon + STR_Locations))) ||
            gmBool(val(S.get(STR_Randomize + STR_Town + STR_Locations)))
          ) {
            _warp_qualified = true
          }
        }
        if (_warp_qualified) {
          if (!self.exit_owrc) {
            if (
              !self.Warp_state ||
              self.Warp_state === self.Warp_state_FLUTE ||
              self.Warp_state === self.Warp_state_SPIN_UP
            ) {
              if (!self.Warp_state) {
                const _INST = aud_play_sound(get_audio_theme_track(self.Warp_FLUTE_THEME))
                self.flute_timer = audio_sound_length_frames(_INST, self.FLUTE_DURATION1) + 8
                self.Warp_timer = self.flute_timer
                self.Warp_owrc = self.pcrc
                self.Warp_state = self.Warp_state_FLUTE
              }
              // change destination
              _count = self.Warp_dg_DESTINATIONS.width
              for (_i = 0; _i < _count; _i++) {
                self.Warp_destination_num++
                if (self.Warp_destination_num > _count) self.Warp_destination_num = 1
                _val = self.Warp_dg_DESTINATIONS.get(self.Warp_destination_num - 1, 0) as string
                if (gmBool(val(f.dm_quests.get(STR_Warp + STR_Qualified + _val)))) break //_i
              }
            }
          }
        } else {
          // var _C1 = !dest_dist && !exit_owrc && !flute_timer;
          if (_C1 && !self.Warp_is_warping) {
            const _INST = aud_play_sound(get_audio_theme_track(STR_Flute))
            self.flute_timer = audio_sound_length_frames(_INST, self.FLUTE_DURATION1) + 8
          }
        }
      }
    }
  }
  // --------------------------------------------------------------------------------
  if (!self.flute_timer) {
    // For using spritesheets
    self.pc_sprite_idx = bitNum(self.pc_dir) - 1
    self.pc_sprite_idx += 4 * +(self.mot === self.MOT_RAFT)
    self.pc_sprite_idx = self.pc_sprite_idx << 1
    self.pc_sprite_idx += +(gmBool(self.dest_dist) && self.dest_dist < T_SIZE >> 1)
    //  mot: Mode Of Transportation
    if (self.mot === self.MOT_RAFT) {
      if (self.pc_dir & 0x03) self.pc_x_scale = _PC_DIR_SIGN_X
      else self.pc_x_scale = 1
    } else {
      self.pc_x_scale = 1
    }
  }
  // --------------------------------------------------------------------------------
  if (self.dest_dist) self.move_distance += self.move_speed
  let _IS_MOVE_FRAME: boolean
  if (self.move_SYS === 2) _IS_MOVE_FRAME = gmBool(self.dest_dist) && self.move_distance >= 1
  else _IS_MOVE_FRAME = gmBool(self.dest_dist) && !(g.counter1 & (self.move_spd - 1)) // move_spd-1 = 0,1,3
  self.move_distance = frac(self.move_distance)
  if (self.dest_dist) self.exit_owrc = 0
  if (_IS_MOVE_FRAME) {
    self.dest_dist--
    self.move_x = -_PC_DIR_SIGN_X // + 0, 1, -1
    self.move_y = -_PC_DIR_SIGN_Y // + 0, 1, -1
    // T_SIZE-1 = $F
    if (!(self.dest_dist & (T_SIZE - 1))) {
      _pc_clm = (self.pcrc >> 0) & 0xff
      _pc_row = (self.pcrc >> 8) & 0xff
      _pc_clm += -self.move_x
      _pc_row += -self.move_y
      self.pcrc = (_pc_row << 8) | _pc_clm
      self.pcrc_map = self.pcrc
      if (f.items & ITM_BOOT && !self.dest_dist) WaterSparkle_refresh(self, self.pcrc)
    }
  }
  // --------------------------------------------------------------------------------
  // UPDATE ENCOUNTER OBJS --------------------------------------------------
  Overworld_enc_spawn_update(self)
  Overworld_enc_inst_update(self)
  // --------------------------------------------------------------------------------
  if (_IS_MOVE_FRAME) {
    if (self.mot === self.MOT_WALK) self.pc_step_counter = (self.pc_step_counter + 1) & 0xff
    // if finished moving to destination
    if (!self.dest_dist) {
      self.mot = 0
      self.move_speed = 0
      self.move_distance = 0
      const _PCRC_ = hex_str(self.pcrc)
      const _raft = val(dm.get(_PCRC_ + STR_Raft)) as number
      if (_raft && f.items & ITM_RAFT) {
        // Data Examples: $0101, $0102
        // Raft tiles are in pairs: (01)01 Set num, 01(01) Member num 1 or 2
        // Member 1 is always N or W of member 2
        const _rc1 = self.pcrc
        const _rc2 = val(dm.get(STR_Raft + hex_str(_raft ^ 0x03) + STR_OWRC)) as number
        if (_rc2) {
          const _dist = Math.abs(_rc2 - _rc1) // end_rc - start_rc
          const _dir = (1 + +(_rc1 > _rc2)) << (+(_dist > 0xff) << 1) // RAFT travel dir = 1,2,4,8
          // if NOT currently moving in opposite dir of RAFT travel dir
          if (
            (_dir & 0x03 && self.pc_dir !== (_dir ^ 0x03)) ||
            (_dir & 0x0c && self.pc_dir !== (_dir ^ 0x0c))
          ) {
            self.mot = self.MOT_RAFT
            self.pc_dir = _dir
            const _SHIFT = +(_dist > 0xff) << 3 // =        0,8
            self.dest_dist = _dist >> _SHIFT // = _val >>0,8
            self.dest_dist = self.dest_dist << SHIFT
            self.move_spd = self.MOVE_SPD_1
            self.move_speed = self.move_SPEED1
            self.move_distance = 0
            aud_play_sound(get_audio_theme_track(STR_Fairy + STR_Greeting))
          }
        }
      } else if (dm.get(_PCRC_ + STR_RmName) !== undefined) {
        if (gmBool(val(dm.get(_PCRC_ + STR_Open)))) {
          // ----- CHECK LEAVE OVERWORLD TO RM ------
          _datakey = _PCRC_ + hex_str(self.pc_dir) + STR_Exit
          // Setting exit_owrc triggers the room change process.
          if (dm.get(_datakey) !== undefined) self.exit_owrc = self.pcrc
        }
      }
    }
  }
  // --------------------------------------------------------------------------------
  if (self.flute_timer) {
    self.flute_timer--
    if (!self.flute_timer && self.Warp_state !== self.Warp_state_FLUTE) {
      _pc_clm = (self.pcrc >> 0) & 0xff
      _pc_row = (self.pcrc >> 8) & 0xff
      // River Devil ------------------------------------------------
      _ow_clm = _pc_clm + _PC_DIR_SIGN_X
      _ow_row = _pc_row + _PC_DIR_SIGN_Y
      _owrc = (_ow_row << 8) | _ow_clm
      _tsrc = self.dg_tsrc.get(_ow_clm, _ow_row) ?? 0
      if (gmBool(val(dm.get(hex_str(_owrc) + STR_River_Devil + STR_State)))) {
        dm.set(hex_str(_owrc) + STR_River_Devil + STR_State, 0)
        aud_play_sound(get_audio_theme_track(dk_Fanfare), -1, false, -1, dk_Fanfare)
        _rm_clm = (self.DRAW_CLMS >> 1) + _PC_DIR_SIGN_X
        _rm_row = (self.DRAW_ROWS >> 1) + _PC_DIR_SIGN_Y
        _tsrc = val(dm.get(hex_str(_owrc) + STR_TSRC + STR_Under + STR_River_Devil), -1) as number
        if (_tsrc === -1) {
          switch (val(dm.get(hex_str(_owrc) + STR_River_Devil))) {
            case 1:
              _tsrc = (self.TILESET1_TS_IDX << 8) | TSRC_BRDG1B // $B3. Vertically aligned bridge
              break
            default:
              _tsrc = (self.TILESET1_TS_IDX << 8) | TSRC_PATH02
              break
          }
        }
        Overworld_tile_change_1a(self, _rm_clm, _rm_row, _ow_clm, _ow_row, _tsrc)
        if (g.anarkhyaOverworld_MAIN && g.anarkhyaOverworld_enabled) {
          Overworld_tile_change_3(self, 0, _rm_clm << SHIFT, _rm_row << SHIFT, self.anarkhya_TILE_DEPTH2, -1)
          self.dg_anarkhya_tsrc_detail.set(_ow_clm, _ow_row, 0)
        }
      } else {
        // Three-Eye-Rock-Palace ---------------------------
        _ow_clm = _pc_clm
        _ow_row = _pc_row + 2
        _owrc = (_ow_row << 8) | _ow_clm
        if (_owrc === val(dm.get(MK_OWRC_PAL_THRE1)) && !gmBool(val(dm.get(hex_str(_owrc) + STR_Open)))) {
          aud_play_sound(get_audio_theme_track(dk_Fanfare), -1, false, -1, dk_Fanfare)
          dm.set(hex_str(_owrc) + STR_Open, 1)
          _rm_clm = self.DRAW_CLMS >> 1
          _rm_row = (self.DRAW_ROWS >> 1) + 2
          _tsrc = (self.TILESET1_TS_IDX << 8) | (TSRC_PALA02 + 1) // TSRC_PALA02: $90-95: Palace w/ biom bg's
          Overworld_tile_change_1a(self, _rm_clm, _rm_row, _ow_clm, _ow_row, _tsrc)
          if (g.anarkhyaOverworld_MAIN && g.anarkhyaOverworld_enabled) {
            Overworld_tile_change_3(
              self,
              self.anarkhya_TSRC_PALACE,
              _rm_clm << SHIFT,
              _rm_row << SHIFT,
              self.anarkhya_TILE_DEPTH2,
              0,
            )
            self.dg_anarkhya_tsrc_detail.set(_ow_clm, _ow_row, self.anarkhya_TSRC_PALACE)
          }
        }
      }
    }
  }
  // -------------------------------------------------------------------
  if (self.Warp_timer) self.Warp_timer--
  switch (self.Warp_state) {
    // -------------------------------------------------------------
    case self.Warp_state_FLUTE: {
      if (self.Warp_timer) break
      self.Warp_timer = self.Warp_DURATION2 // chance to cancel/avoid warp during this time
      self.Warp_state = self.Warp_state_SPIN_UP
      break
    }
    // -------------------------------------------------------------
    case self.Warp_state_SPIN_UP: {
      if (self.Warp_timer) break // chance to cancel/avoid warp during this time
      if (self.pcrc === self.Warp_owrc && !self.exit_owrc) self.Warp_is_warping = true
      self.Warp_timer = self.Warp_DURATION3
      self.Warp_state = self.Warp_state_VANISH
      break
    }
    // -------------------------------------------------------------
    case self.Warp_state_VANISH: {
      if (self.Warp_timer) break
      if (self.Warp_is_warping && !self.exit_owrc) {
        self.Warp_timer = 0x20
        self.Warp_state = self.Warp_state_OWRC_CHANGE
      } else {
        self.Warp_owrc = 0x00
        self.Warp_destination_num = 0
        self.Warp_is_warping = false
        self.Warp_timer = 0x00
        self.Warp_state = 0
      }
      break
    }
    // -------------------------------------------------------------
    case self.Warp_state_OWRC_CHANGE: {
      if (g.surf) g.surf.draw_clear_color = p.C_BLK1
      if (self.Warp_timer) break // solid black screen during this time
      _idx = Math.min(Math.max(self.Warp_destination_num - 1, 0), self.Warp_dg_DESTINATIONS.width - 1)
      self.pcrc = self.Warp_dg_DESTINATIONS.get(_idx, 1) as number
      let _OW_X = ((self.pcrc >> 0) & 0xff) << SHIFT
      let _OW_Y = ((self.pcrc >> 8) & 0xff) << SHIFT
      _OW_X += T_SIZE >> 1
      _OW_Y += T_SIZE >> 1
      _OW_X -= self.DRAW_W_
      _OW_Y -= self.DRAW_H_
      Overworld_refresh_tiles(self, _OW_X, _OW_Y)
      self.BAIT_timer = 0
      self.BAIT_owrc = 0x00
      self.BAIT_ow_x = 0
      self.BAIT_ow_y = 0
      // enc_spawn_timer decrements every $14 frames when g.timer_b reaches -1 in update_game_timers()
      self.enc_spawn_timer = 8
      self.enc_spawn_timer += self.enc_spawn_timer_add // 12/05/22. Attempting to balance enc difficulty
      self.enc_spawn_timer_add = 0
      for (const row of self.dg_enc_inst.cells) row.fill(0)
      self.Warp_owrc = self.pcrc
      self.Warp_timer = self.Warp_DURATION3
      self.Warp_state = self.Warp_state_APPEAR
      break
    }
    // -------------------------------------------------------------
    case self.Warp_state_APPEAR: {
      if (self.Warp_timer) break
      self.Warp_timer = self.Warp_DURATION1
      self.Warp_state = self.Warp_state_SPIN_DOWN
      break
    }
    // -------------------------------------------------------------
    case self.Warp_state_SPIN_DOWN: {
      if (self.Warp_timer) break
      self.Warp_owrc = 0x00
      self.Warp_destination_num = 0
      self.Warp_is_warping = false
      self.Warp_timer = 0x00
      self.Warp_state = 0
      break
    }
  }
  // -------------------------------------------------------------------
  if (!self.flute_timer) {
    if (self.WaterSparkle_timer) {
      self.WaterSparkle_timer--
      if (!self.WaterSparkle_timer) {
        self.WaterSparkle_timer = self.WaterSparkle_DURATION0
        WaterSparkle_refresh(self, self.pcrc)
      }
    }
  }
  if (f.items & ITM_BOOT) {
    const _clm = (self.pcrc >> 0) & 0xff
    const _row = (self.pcrc >> 8) & 0xff
    const _dl_OWRC: number[] = []
    const consider = (o: number) => {
      if (self.dl_BTI_OWRC.findIndex(o) !== -1) _dl_OWRC.push(o)
    }
    consider(self.pcrc) // ON pc's tile
    if (_clm + 1 < self.OW_CLMS) consider((_row << 8) | (_clm + 1)) // RIGHT-OF pc's tile
    if (_clm - 1 >= 0) consider((_row << 8) | (_clm - 1)) // LEFT-OF of pc's tile
    if (_row + 1 < self.OW_ROWS) consider(((_row + 1) << 8) | _clm) // BELOW pc's tile
    if (_row - 1 >= 0) consider(((_row - 1) << 8) | _clm) // ABOVE pc's tile
    self.dl_WaterSparkle_idx.clear()
    const B = self.dg_BTI
    for (_i = B.width - 1; _i >= 0; _i--) {
      _owrc = B.get(_i, 0) as number
      if (_dl_OWRC.includes(_owrc)) {
        B.set(_i, 1, (B.get(_i, 1) as number) + 1)
        const _over = (B.get(_i, 1) as number) - self.BTI_DURATION2
        if (_over) {
          B.set(_i, 1, self.BTI_DURATION2)
          B.set(_i, 1, (B.get(_i, 1) as number) + (_over % self.BTI_DURATION4))
        }
      } else {
        if (B.get(_i, 1)) {
          B.set(_i, 1, (B.get(_i, 1) as number) - 1)
          if ((B.get(_i, 1) as number) < self.BTI_DURATION2) B.set(_i, 1, 0)
        }
      }
      const _val1n = (B.get(_i, 1) as number) - self.BTI_DURATION2
      if (_val1n >= 0) {
        // A list of dg_BTI indices that should draw the indication
        self.dl_WaterSparkle_idx.add(_i)
        // sparkle groups for this owrc
        for (let _j = 0; _j < 3; _j++) {
          _idx = 2 + (_j << 1)
          let _val2 = self.BTI_DURATION0 * _j
          const _phase = (G.App_frame_count - _val2) % self.BTI_DURATION3
          if (!_phase) B.set(_i, _idx + 1, WaterSparkle_get_new_rc(self))
          B.set(_i, _idx, 0)
          _val2 = (self.BTI_DURATION3 + self.BTI_DURATION0) * _j
          if (_val1n >= _val2) {
            if (_phase >= self.BTI_DURATION1) B.set(_i, _idx, 0)
            else if (_phase >= self.BTI_DURATION1 - (self.BTI_DURATION1 >> 2)) B.set(_i, _idx, 2)
            else B.set(_i, _idx, 1)
          }
        }
        // 11111111    11111111    1111
        //     11111111    11111111
        // 1111    11111111    11111111
      }
    }
  }
  // -------------------------------------------------------------------
  self.pc_ow_x = ((self.pcrc >> 0) & 0xff) << SHIFT
  self.pc_ow_y = ((self.pcrc >> 8) & 0xff) << SHIFT
  self.pc_ow_x += T_SIZE >> 1
  self.pc_ow_y += T_SIZE >> 1
  const _rem = self.dest_dist & (T_SIZE - 1)
  if (_rem) {
    const _left = T_SIZE - _rem
    self.pc_ow_x += _left * _PC_DIR_SIGN_X
    self.pc_ow_y += _left * _PC_DIR_SIGN_Y
  }
  if (self.exit_owrc) {
    g.overworld_paused = false
    audio_stop_sound(self.Pause_SOUND1)
    audio_stop_sound(self.Pause_SOUND2)
  }
  // -------------------------------------------------------------------
  switch ((g.counter0 & 0x7f) >> 5) {
    case 0:
      background_assign('ts_OverworldAnim01', 'ts_OverworldAnim01_00')
      break
    case 1:
      background_assign('ts_OverworldAnim01', 'ts_OverworldAnim01_01')
      break
    case 2:
      background_assign('ts_OverworldAnim01', 'ts_OverworldAnim01_02')
      break
    case 3:
      background_assign('ts_OverworldAnim01', 'ts_OverworldAnim01_03')
      break
  }
  // -------------------------------------------------------------------
  // if movement happened this frame
  if (
    g.room_type === 'C' &&
    !self.exit_owrc &&
    !g.overworld_paused &&
    (self.move_x !== 0 || self.move_y !== 0)
  ) {
    const _OFF = T_SIZE - 1
    _pc_clm = (self.pcrc >> 0) & 0xff
    _pc_row = (self.pcrc >> 8) & 0xff
    let _ow_x = (_pc_clm << SHIFT) + (T_SIZE >> 1)
    let _ow_y = (_pc_row << SHIFT) + (T_SIZE >> 1)
    _ow_x -= self.DRAW_W_
    _ow_y -= self.DRAW_H_
    //
    tile_layer_shift(self.Tile_DEPTH1, self.move_x, self.move_y)
    if (g.anarkhyaOverworld_MAIN && g.anarkhyaOverworld_enabled) {
      tile_layer_shift(self.anarkhya_TILE_DEPTH1, self.move_x, self.move_y)
      tile_layer_shift(self.anarkhya_TILE_DEPTH2, self.move_x, self.move_y)
    }
    // if lined up with the grid this frame after moving, relative to T_SIZE
    if (!(self.dest_dist & _OFF)) Overworld_refresh_tiles(self, _ow_x, _ow_y)
  }
  Overworld_udp(self)
}
