/**
 * Player movement: `PC_update_horizontal`, `PC_update_vertical`, `PC_set_jump`, `PC_update_walk`, plus
 * `solid_clip_correction` (a `go` script only the player and a few GOBs use; ported here).
 */
import {
  CS_TOP,
  ITM_FTHR,
  OGR_JUMP,
  OGR_OTHR,
  PC_LOCK_ATK3,
  PC_LOCK_ATK4,
  PC_LOCK_FLOT,
  PC_LOCK_HSPD,
  PC_LOCK_JUMP,
  PC_LOCK_VSPD,
  SKILL_THD,
  SKILL_THU,
  SPL_JUMP,
  TID_BREAK1,
  TID_BREAK2,
  TID_BREAK3,
  TID_BREAK4,
} from '@z2/data'
import { abs8b, byte, byteNegate, byteToInt, gmBool, isVal } from '../../../nes/math8'
import { f, G, g, input } from '../../../runtime/world'
import { csBtmColliding_1a, updateCSPoints } from '../../collision/cs'
import { bit_dir, byte_dir, sign_ } from '../../math/index'
import { cam_yt_range } from '../../view/camera'
import { type GameObject, Item } from '../classes'
import { set_xlyt, set_xy, updateY2 } from '../go/movement'
import { pcHooks } from './deps'
import { PC_set_behavior } from './form'
import type { Lonk } from './Lonk'
import { pcInput } from './pc'
import { PC_update_1b } from './update1'

/** `PC_update_horizontal()` — 93CD */
export function PC_update_horizontal(self: Lonk): void {
  const _C0 = gmBool(g.mod_StabFrenzy) && self.StabFrenzy_charge_counter > 0x80 && gmBool(input.Attack_held)
  const _HSPD_MAX = self.hspd_max >> (_C0 ? 1 : 0)
  const _HSPD = byteToInt(self.hspd)
  if (
    self.ogr || // NOT on ground
    !self.attack_phase || // NOT attacking
    g.control1_timer || // stab does NOT inhibit hspd
    _C0 // is frenzy stabbing
  ) {
    const _C1 = self.is_cucco && abs8b(self.hspd) <= self.hspd_max && pcInput.dHeld // cucco slow walk while crouching
    // 93DC
    if (
      !(g.pc_lock & PC_LOCK_HSPD) && // horizontal control NOT locked
      pcInput.hHeld && // left || right held
      (!pcInput.dHeld || _C1) && // down NOT held || cucco crawl
      (!_C0 || self.attack_phase === 2) // NOT frenzy stabbing || in stab phase of attack
    ) {
      // 93FD. (left || right held) && down NOT held
      const _HELD_DIR = bit_dir(pcInput.hHeld) // 1,-1
      const _C2 = _HELD_DIR !== self.hspd_dir
      let _hspd_maxL = -_HSPD_MAX
      let _hspd_maxR = _HSPD_MAX
      // 2024/12/10. Maintain faster than normal max hspd from stabbing Bloobys.
      _hspd_maxL = Math.min(_HSPD, _hspd_maxL)
      _hspd_maxR = Math.max(_HSPD, _hspd_maxR)
      let _amount = 1
      if (Math.abs(_HSPD) > _HSPD_MAX && (!self.ogr || _C2)) {
        // 2024/12/28. Smooth deceleration towards _HSPD_MAX when faster than it.
        if (!self.ogr) self.hyper_hspd_friction += _amount / 2
        if (_C2) self.hyper_hspd_friction += _amount
        _amount = Math.floor(self.hyper_hspd_friction)
        _amount *= -self.hspd_dir
        self.hyper_hspd_friction = self.hyper_hspd_friction - Math.floor(self.hyper_hspd_friction)
      } else {
        _amount += _C2 ? 1 : 0
        _amount *= _HELD_DIR
      }
      self.hspd = Math.min(Math.max(_HSPD + _amount, _hspd_maxL), _hspd_maxR)
      self.hspd &= 0xff
      self.hspd_impel = _HELD_DIR
    } else {
      // 93E6. left and right NOT held || down held
      if (!self.ogr && self.hspd) {
        self.hspd += -self.hspd_dir
        self.hspd &= 0xff
      }
    }
    // 943A: JSR 9610
    if (!(self.cs & 0x3)) PC_update_1b(self) // updateX()
    PC_update_walk(self)
    // 9420
    if (pcInput.dHeld && !self.ogr && self.cs & 0x4) PC_set_behavior(self.behavior_CROUCH)
  }
  if (Math.abs(_HSPD) <= _HSPD_MAX) self.hyper_hspd_friction = 0.0 // NOT moving faster than the normal max
}

/** `PC_update_vertical()` — 94C5 */
export function PC_update_vertical(self: Lonk): void {
  if (self.colliding_elevator?.exists) {
    pcHooks.Elevator_update_1(self.colliding_elevator)
    return
  }
  // keep backups
  const _cs4_COPY = self.cs & 0x4
  const _vspd_COPY = self.vspd
  const _ogr_COPY = self.ogr // ogr: Off Ground Reason
  const _C1 = !self.HoldItem_timer && !g.EnterRoom_control_timer
  // 94CA
  if (self.cs & 0x4) {
    let _is_landing = false
    // 94DA
    if (self.ogr && self.vspd < 0x80) {
      // 94E4.  LANDING
      _is_landing = true
      self.landing_timer = self.LANDING_DURATION * (self.vspd >= self.TERMINAL_VELOCITY ? 1 : 0) // LANDING_DUR = 8
      self.ogr = 0
      self.vspd = 0
      self.attack_phase = 0
      // Attempt to prevent landing-slide when PC and cs_btm_inst both have momentum..
      const inst = self.cs_btm_inst
      if (inst?.exists && inst.solid_type && inst.hspd) {
        let _HSPD = inst.hspd
        _HSPD = Math.max(abs8b(_HSPD) - 4, Math.min(_HSPD, 4))
        _HSPD = (_HSPD * byte_dir(inst.hspd)) & 0xff
        self.hspd += byteNegate(_HSPD)
        self.hspd &= 0xff
        self.hspd = byteToInt(self.hspd)
        self.hspd = Math.min(Math.max(self.hspd, -self.hspd_max), self.hspd_max)
        self.hspd &= 0xff
        self.hspd_dir = byte_dir(self.hspd)
      }
    }
    if (_vspd_COPY < 0x80) {
      // if NOT moving upwards
      self.jump_tokens = 1
      if (g.DoubleJump_state && f.items & ITM_FTHR) self.jump_tokens++
      // 94F8
      solid_clip_correction(self, _is_landing)
      // 94FE.  JUMP! ---------------------------
      if (_C1) PC_set_jump(self, _is_landing)
    }
  } else if (!self.ogr) {
    // PC is not on solid but has not jumped
    self.ogr = OGR_OTHR
    self.jump_tokens = 0
    if (g.DoubleJump_state && f.items & ITM_FTHR) self.jump_tokens++
  } else if (_C1) {
    // !HoldItem_timer && !g.EnterRoom_control_timer
    if (self.ogr === OGR_OTHR || self.ogr === OGR_JUMP) {
      // Can jump again if have double jump
      PC_set_jump(self, false)
    }
  }
  // ------------------------------------------------------------
  // It is possible for cs4()==true while moving upward
  const _C2 =
    (gmBool(_ogr_COPY) && !!(_vspd_COPY & 0x80)) || // is off ground && moving up
    self.ogr === OGR_JUMP || // is off ground bc of jumping
    !_cs4_COPY // btm NOT colliding with solid
  const _QUAL_DOWNTHRUST =
    pcInput.dHeld &&
    !!(f.skills & SKILL_THD) &&
    !(g.pc_lock & PC_LOCK_ATK3) &&
    !self.Disguise_enabled &&
    (!self.is_cucco || !!(f.Cucco_skills & f.CuccoSkill_THRUST_D))
  if (_C2) {
    // 952D.  *** NOTE: Don't use _vspd_COPY beyond here
    let _grav_add = self.GRAVITY2 // $48
    if (input.Jump_held && self.vspd & 0x80 && _C1) _grav_add = self.GRAVITY1 // $30
    // 9544
    // In OG, csTop can collide w/ solid tiles above the screen if (yy <= -$11) — the cs check sees yy as $EF.
    if (self.vspd & 0x80 && self.cs & 0x8) {
      // 954F
      if (self.vspd !== 0xff) {
        // if vspd < $FF (if moving up faster than -1)
        self.vspd = 0xff
        self.vspd_grav = 0
      }
      // This is just to update vspd_grav and vspd to get vspd from $FF to $00
      self.vspd_grav += _grav_add
      self.vspd += self.vspd_grav > 0xff ? 1 : 0
      self.vspd_grav &= 0xff
      self.vspd &= 0xff
    } else {
      let _term_vel = self.TERMINAL_VELOCITY
      if (self.is_cucco) _term_vel = 3
      if (self.is_cucco && self.vspd < 0x80) {
        _grav_add = self.GRAVITY1 // GRAVITY1=$30
        if (
          input.Jump_held &&
          !self.stun_timer &&
          !_QUAL_DOWNTHRUST &&
          (!self.Disguise_enabled || G.Halloween1_enabled) &&
          _C1 && // !HoldItem_timer && !g.EnterRoom_control_timer
          !(g.pc_lock & PC_LOCK_FLOT)
        ) {
          self.Cucco_is_slowfalling = 1
          if (self.vspd > 1 && self.vspd_prev > 1 && self.vspd_prev < 0x80) {
            self.vspd = self.vspd_prev - 1 // slow down
          } else self.vspd = self.vspd_prev ? 0 : 1 // 0 or 1 (1 pixel every other frame)
        } else {
          self.Cucco_counter2 = 0x11 // set at $11 to make first flap of slowfall and jump quick
        }
      }
      if (self.is_cucco && !self.stun_timer && input.Jump_released && self.Cucco_is_slowfalling_prev) {
        // Prevent a sudden drop motion after releasing jump button
        if (self.vspd_prev) {
          self.vspd = 0
          self.vspd_grav = 0x100 - _grav_add
        } else {
          self.vspd = 1
          self.vspd_grav = 0
        }
      }
      self.vspd_prev = self.vspd
      // 9569: JSR D19B
      if (!(g.pc_lock & PC_LOCK_VSPD)) updateY2(self, _grav_add, _term_vel) // $4: vspd
      // Prevent view from moving too much or stuttering: anticipate solid_clip_correction() next frame and
      // adjust y_change for the diff. (ZALiA TODO "Anticipate solid pixels that could change" — resolved: the
      // anticipation is only a camera smoothing hint; y is put back, so a wrong guess costs one frame of
      // camera catch-up, never a position error. Left as ZALiA has it.)
      if (self.y_change !== 0 && self.vspd < 0x80) {
        if (!(g.view_lock & 0xc) && cam_yt_range()) {
          updateCSPoints(self)
          if (csBtmColliding_1a(self)) {
            const _Y = self.y
            self.y_change += solid_clip_correction(self, true) // This is just to get diff, yy put back after
            set_xy(self, self.x, _Y)
          }
        }
      }
    }
  }
  if (!self.ogr) self.drop_y = self.y // is on ground
  // ------------------------------------------------------------
  if (_C1 && _C2) {
    // 956C
    if (self.ogr !== OGR_OTHR) {
      if (self.vspd & 0x80) {
        if (
          input.Up_held &&
          f.skills & SKILL_THU &&
          !(g.pc_lock & PC_LOCK_ATK4) &&
          !self.Disguise_enabled &&
          (!self.is_cucco || f.Cucco_skills & f.CuccoSkill_THRUST_U)
        ) {
          // Tested it. Can't upthrust if ogr==OGR_OTHR, even when vspd<0
          PC_set_behavior(self.behavior_STAB_UP)
        } else PC_set_behavior(self.behavior_CROUCH)
      } else PC_set_behavior(self.behavior_WALK3)
    }
    // 958C
    if (_QUAL_DOWNTHRUST) PC_set_behavior(self.behavior_STAB_DOWN)
  }
}

/** `PC_set_jump(is landing frame)` — 950D */
export function PC_set_jump(self: Lonk, isLanding: boolean | number): void {
  if (!input.Jump_pressed || !self.jump_tokens || g.pc_lock & PC_LOCK_VSPD || g.pc_lock & PC_LOCK_JUMP) return
  // -----------------------------------------------------------------------
  let _case = 0 // 0: JUMP REGULAR
  if (g.spells_active & SPL_JUMP) _case = 2 // 2: JUMP SPELL
  if (!(self.cs & 0x4) && self.ogr === OGR_JUMP) _case = 0 // Can't use JUMP spell height until land on ground again.
  const _CARRY = isLanding ? 1 : 0 // if landing_timer was set this frame
  // This line makes you jump higher if hspd is high enough. OG favours moving right.
  if (gmBool(g.mod_PCJumpDirBalancing)) {
    if (abs8b(self.hspd) + _CARRY >= self.HSPD_JUMP_HIGH) _case++ // 1,3 RUNNING
  } else if (byte(self.hspd + _CARRY + self.HSPD_JUMP_HIGH) >= self.HSPD_JUMP_HIGH << 1) _case++ // 1,3 RUNNING. OG
  switch (_case) {
    case 0: // 0: JUMP REGULAR
      self.vspd = self.VSPD_JUMP1 // $FC. Regular velocity
      self.vspd_grav = self.GRAVITY_JUMP1 // $F0. Regular gravity
      break
    case 1: // 1: JUMP REGULAR RUNNING
      self.vspd = self.VSPD_JUMP1 // $FC. Regular velocity
      self.vspd_grav = self.GRAVITY_JUMP1_RUN // $80. Less gravity
      break
    case 2: // 2: JUMP SPELL
      self.vspd = self.VSPD_JUMP2 // $FB. More velocity
      self.vspd_grav = self.GRAVITY_JUMP2 // $80. Regular gravity
      break
    case 3: // 3: JUMP SPELL RUNNING
      self.vspd = self.VSPD_JUMP2 // $FB. More velocity
      self.vspd_grav = self.GRAVITY_JUMP2_RUN // $00. No gravity
      break
  }
  // Maintain momentum when on something moving (the GML adds, not subtracts, here)
  const inst = self.cs_btm_inst
  if (inst?.exists && inst.solid_type && inst.hspd) {
    let _hspd = inst.hspd
    _hspd = Math.max(abs8b(_hspd) - 4, Math.min(_hspd, 4))
    _hspd = (_hspd * byte_dir(inst.hspd)) & 0xff
    self.hspd += _hspd
    self.hspd &= 0xff
    self.hspd = byteToInt(self.hspd)
    self.hspd = Math.min(Math.max(self.hspd, -self.hspd_max), self.hspd_max)
    self.hspd &= 0xff
    self.hspd_dir = byte_dir(self.hspd)
  }
  // 9505
  self.attack_phase = 0
  self.landing_timer = 0
  self.Cucco_counter2 = 0x11 // set at $11 to make first flap of slowfall and jump quick
  if (!self.ogr) {
    if (input.Attack_held)
      self.StabFrenzy_charge_counter = 0x80 // Must release 'B' first to start charging again
    else self.StabFrenzy_charge_counter = 0
  }
  self.jump_tokens--
  self.ogr = OGR_JUMP
}

/** `PC_update_walk()` — 943D, 943F. Walk animation frame + behavior. */
export function PC_update_walk(self: Lonk): void {
  let _val1 = 1
  if (!self.ogr) {
    _val1 = self.hspd
    if (self.cs & 0x3 && !self.stun_timer && !g.EnterRoom_control_timer) {
      if (input.heldH) _val1 = 5
      else _val1 = 0
    }
    // 9444, 9448, 9453
    if (_val1 && !g.WalkAnim_timer) {
      const _IDX = (abs8b(_val1) >> 3) & 0x3 // = 0,1,2,3
      g.WalkAnim_timer = Number(g.dl_WalkAnim_DURATION.get(_IDX) ?? 0) // [8,7,5,4]
      const _HSPD = abs8b(self.hspd)
      if (_HSPD > self.HSPD_MAX1) {
        g.WalkAnim_timer -= Math.floor(g.WalkAnim_timer * ((_HSPD - self.HSPD_MAX1) / self.HSPD_MAX1))
        g.WalkAnim_timer = Math.max(1, g.WalkAnim_timer)
      }
      if (self.walk_frame < 2) self.walk_frame++
      else self.walk_frame = 0
    }
  }
  // 9468
  if (!self.ogr && !_val1) PC_set_behavior(self.behavior_IDLE)
  else PC_set_behavior(self.behavior_WALK1 + self.walk_frame)
}

/**
 * `solid_clip_correction(is landing)` (go folder) — snap a falling body onto the solid under its bottom
 * sensors, or onto the solid instance it stands on. Returns the y delta.
 */
export function solid_clip_correction(self: GameObject, isLanding: boolean | number): number {
  const _y_PREV = self.y
  const inst = self.cs_btm_inst
  if (inst?.exists) {
    let _y = self.y
    // case 3 of the GML's "Not sure yet the right way to do this" switch
    if (self.csBtm1Y < inst.BodyHB_yt + 8) _y = inst.BodyHB_yt - self.hh_
    set_xy(self, self.x, _y)
    updateCSPoints(self)
    return self.y - _y_PREV
  }
  updateCSPoints(self)
  const _CS_Y = self.csBtm1Y
  const _Y1 = _CS_Y - 1
  if (!(_Y1 + 1)) return self.y - _y_PREV // Not in solids grid.
  const _X0 = (G.dg_solid_w << 3) - 1 // last x pixel of solid grid area
  const _X1 = Math.min(Math.max(self.csBtm1X, 0), _X0) // clamp in case csBtm1X outside of solid grid
  const _X2 = Math.min(Math.max(self.csBtm2X, 0), _X0)
  const solid = (x: number, y: number) => (Number(G.dg_solid.get(x >> 3, y >> 3) ?? 0) & 0xff) !== 0
  if (!solid(_X1, _Y1) && !solid(_X2, _Y1)) return self.y - _y_PREV
  // --------------------------------------------------------------------------------------------------
  if (self.csBtm1Y >> 3 >= 0 && self.csBtm1Y >> 3 < G.dg_solid_h) {
    const _C1 = self.csBtm1Y & 0x7 // amount UNaligned w/ grid
    if (_C1 || self.csBtm1Y) {
      // Added 2022/05/18. Prevent GO from zooming upward with clip adj when pushed back into wall.
      if (!_C1 && !isLanding) return self.y - _y_PREV
      // For certain objects (Key, Magic Jar, pBag), adj should NOT be made if colliding w/ break blocks.
      const _C2 = self instanceof Item && isVal(self.objectName, 'ItmD0', 'ItmE0', 'ItmF0')
      const brk = (x: number, y: number) =>
        isVal(
          Number(g.dg_RmTile_Break.get(x >> 3, y >> 3) ?? 0) & 0xff,
          TID_BREAK1,
          TID_BREAK2,
          TID_BREAK3,
          TID_BREAK4,
        )
      let _c3 = false
      if (_C2) _c3 = brk(_X1, _Y1) || brk(_X2, _Y1)
      if (_c3 && !_C1) return self.y - _y_PREV // already aligned w/ grid
      // -------------------------------------------------
      let _yt = (self.csBtm1Y >> 3) << 3
      _yt -= (self.csBtm1Y & 0x7 ? 0 : 1) << 3
      _yt -= self.csBtm1Y - self.yt // important if sprite_index height is shorter than cs height (Tektites)
      set_xlyt(self, self.xl, _yt)
      updateCSPoints(self)
      if (isLanding) {
        _c3 = false
        if (_C2) _c3 = brk(_X1, self.csBtm1Y - 1) || brk(_X2, self.csBtm2Y - 1)
        if (!_c3) {
          self.csBtm1Y--
          self.csBtm2Y--
          if (csBtmColliding_1a(self)) set_xy(self, self.x, self.y - 8)
          updateCSPoints(self)
        }
      }
    }
  }
  return self.y - _y_PREV
}

export { CS_TOP, sign_ }
