/** GML: Gooma_init2() */
export function Gooma_init2(self: Gooma01) {
  let _i: any, _a: any, _val: any, _PAL: any

  self.debug1 = false

  Boss_init_2(self)
  Boss_init_2b(self, -1)
  // attack_state 0: idle/walk
  // attack_state 1: twirl/draw
  // attack_state 2: attack
  _a = 0
  self.attack_state_IDLE = _a++
  self.attack_state_DRAWBACK = _a++
  self.attack_state_SWING = _a++
  self.attack_state = self.attack_state_IDLE // 0080
  // sprite_index: spr_Gooma_Placement: 24x48
  GO_set_sprite(self, 'spr_Gooma_1a')
  self.Weapon_PALIDX = G.PI_MOB_BLU
  self.Weapon_Ball_sprite = 0
  self.Weapon_Ball_x = 0
  self.Weapon_Ball_y = 0
  self.Weapon_Chain_sprite = 0
  self.Weapon_Chain_x = 0
  switch (self.ver) {
    case 1: {
      if (f.quest_num === 1) {
        self.HP_IDX = 0x19 // $19: $90(144)
      } else {
        self.HP_IDX = 0x1b // $1B: $C0(192)
      }
      //else                HP_IDX=$1C; // $1C: $D8(216)
      break
    }
    case 2: {
      if (f.quest_num === 1) {
        self.HP_IDX = 0x24 // $24: $240(560)
      } else {
        self.HP_IDX = 0x24 // $25: $2B0(688)
      }
      //else                HP_IDX=$25; // $25: $2B0(688)
      break
    }
  }
  self.hp = g.dl_HP.get(self.HP_IDX) as number
  if (f.quest_num > 1) {
    self.XP_IDX += 0x01
    self.xp = g.dl_XP.get(self.XP_IDX) as number
  }
  if (self.ver === 2) {
    GO_init_palidx(self, G.PI_MOB_RED)
    _PAL = build_pal(p.C_WHT1, p.C_RED3, p.C_BLK1, p.C_BLK1, -2, -2, -2, -2)
    change_pal(strReplaceAt(p.pal_rm_new, get_pal_pos(self.palidx_base), string_length(_PAL), _PAL))
  }
  if (gmBool(g.mod_Gooma_Projectile_1) && self.ver === 2) {
    switch (g.mod_Gooma_Projectile_1) {
      case 1: {
        self.projectile_OBJ = 'Flame2'
        self.projectile_VER = 1
        break
      }
      case 2: {
        self.projectile_OBJ = 'Fireball2'
        self.projectile_VER = 3
        break
      }
    }
    self.projectile = self.projectile_OBJ
    self.projectile_ver = self.projectile_VER
    self.projectile_timer = 0
    self.projectile_tokens = 1
  }
  self.BodyHB_color = c_yellow
  self.ShieldHB_color = c_white
  self.ShieldHB_IDX = 7
  self.ShieldHB_idx = self.ShieldHB_IDX
  self.SwordHB_W = 14 + g.HB_ADJ_W
  self.SwordHB_H = 1 + g.HB_ADJ_H
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
  Boss_set_MusicBattle_props(self, `${STR_Boss}01`)
}

/** GML: Gooma_update() */
export function Gooma_update(self: Gooma01) {
  let _DIR: any, _XL: any, _YT: any, _DIRX: any, _DIRY: any, _SPEED: any

  // BAC3, BAC8: JMP B4AD, B4B2: JSR BE8B
  // check battle start/end/qualify
  if (!gmBool(Boss_update_1(self))) {
    update_EF11(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // -----------------------------------------------------------
  // B4C0: JSR 9C45
  Boss_HPBar_udp(self)
  // Arena gate
  if (!gmBool(Boss_update_4(self))) {
    update_EF11(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // MOD. Delay 1st attack -----------------------------------------------
  if (gmBool(self.start_timer)) {
    self.start_timer--
    update_EF11(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // ------------------------------------------------------------
  // B4B5: JSR BC4E. EF11, hspdPB, updateX, shld coll, DE3D, body coll, check & set pending death
  Boss_update_2(self)
  if (gmBool(self.pending_death)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // ------------------------------------------------------------
  // B4B8: JSR E579
  if (gmBool(self.attack_state)) {
    GOB_sword_collision_1a(self) // handles BODY collision check & reaction
  }
  // B4BB: JSR B53B
  if (gmBool(self.attack_state) && !gmBool(self.timer)) {
    //  attack_state 0: NOT attacking
    //  attack_state 1: Drawing back
    //  attack_state 2: Swing weapon
    switch (self.attack_state) {
      case self.attack_state_DRAWBACK: {
        self.attack_state = self.attack_state_SWING
        self.timer = 0x0f // attack melee
        break
      }
      case self.attack_state_SWING: {
        self.attack_state = self.attack_state_IDLE
        self.timer = 0x20 // attack cooldown
        break
      }
    }
  }
  // -----------------------------------------------------------
  // B4C3
  _DIR = dir_to_pc(self)
  if (!gmBool(g.counter1 & 0x1f)) {
    self.facing_dir = _DIR
  }
  // B4D6. if (counter&$7F){hspd = +-8, updates counter}
  if (!gmBool(Boss_update_3b(self, _DIR))) {
    self.hspd = 0
  }
  // -----------------------------------------------------------
  // B4EC. Check & set move dir.
  // Returns true if in atk dist && !attack_state
  if (gmBool(Boss_update_3a(self, 0x40)) && !gmBool(self.timer)) {
    // B51F: JSR B557
    self.attack_state = self.attack_state_DRAWBACK // start attack
    self.timer = 0x2f // atk twirl timer
  }
  // -----------------------------------------------------------
  // -----------------------------------------------------------
  // -----------------------------------------------------------
  if (gmBool(g.mod_Gooma_Projectile_1) && self.ver === 2) {
    switch (g.mod_Gooma_Projectile_1) {
      // ----------------------------------------
      case 1: {
        if (self.attack_state === self.attack_state_IDLE) {
          self.projectile_tokens = 1
        }
        // Spikeball furthest out at 5
        if (
          gmBool(self.projectile_tokens) &&
          self.attack_state === self.attack_state_SWING &&
          ((g.counter1 >> 1) & 0x07) === 5
        ) {
          _XL = self.Weapon_Ball_x - 0x04
          _YT = self.Weapon_Ball_y - 0x0c
          // Flame2
          /* TODO with */ {
            const _w1: any = GOC1_create(
              _XL,
              _YT,
              self.facing_dir,
              self.projectile as ObjectName,
              self.projectile_ver,
              self,
              G.PI_MOB_ORG,
            )
            if (_w1) {
              _w1.hspd = (0x20 * _w1.facing_dir) & 0xff
              _w1.vspd = 0xff
            }
          }
          self.projectile_tokens--
        }
        break
      }
      // ----------------------------------------
      case 2: {
        if (self.attack_state === self.attack_state_SWING) {
          self.projectile_tokens = 0
          self.projectile_timer = 0
        }
        if (
          self.attack_state === self.attack_state_IDLE &&
          !gmBool(self.projectile_tokens) &&
          self.hp < g.dl_HP.get(self.HP_IDX) >> 1
        ) {
          self.projectile_tokens = 1
          self.projectile_tokens += self.hp < Math.trunc(g.dl_HP.get(self.HP_IDX) / 3) << 1
          self.projectile_tokens += self.hp < Math.trunc(g.dl_HP.get(self.HP_IDX) / 3)
        }
        if (self.attack_state === self.attack_state_IDLE && !gmBool(self.projectile_timer)) {
          self.projectile_timer = world.irandom(7) + 8
        }
        if (self.attack_state === self.attack_state_DRAWBACK && gmBool(self.projectile_timer)) {
          self.projectile_timer--
        }
        if (
          self.attack_state === self.attack_state_DRAWBACK &&
          gmBool(self.projectile_tokens) &&
          !gmBool(self.projectile_timer)
        ) {
          _DIRX = sign_(inRange((self.timer >> 1) & 0x07, 3, 6))
          _DIRY = sign_(inRange((self.timer >> 1) & 0x07, 1, 4))
          _DIRX *= self.facing_dir
          _DIRY *= self.facing_dir
          //
          _XL = self.Weapon_Ball_x - 4
          _YT = self.Weapon_Ball_y - 8
          // Fireball2 v3: Bounces
          /* TODO with */ {
            const _w2: any = GOC1_create(
              _XL,
              _YT,
              _DIRX,
              self.projectile as ObjectName,
              self.projectile_ver,
              self,
              G.PI_MOB_ORG,
            )
            if (_w2) {
              _SPEED = 0x30
              _w2.hspd = (_SPEED * _DIRX) & 0xff
              _w2.vspd = (_SPEED * _DIRY) & 0xff
            }
          }
          self.projectile_tokens--
          self.projectile_timer = world.irandom(7) + 8
        }
        break
      }
    } //switch(g.mod_Gooma_Projectile_1)
  }
  Boss_Roar_update(self)
}

/** GML: Gooma_udp() */
export function Gooma_udp(self: Gooma01) {
  let _idx: any, _data: any, _DATA: any, _DIFF: any, _XOFF: any

  // BD75
  self.can_draw_self = true
  // B5C7
  self.palidx = self.palidx_def
  // ----------------------------------------------------
  if (gmBool(g.view_lock_boss) && (gmBool(self.hspd) || gmBool(self.attack_state))) {
    // B5D4
    if ((self.counter & 0x07) >= 3 && (self.counter & 0x07) <= 5) {
      GO_set_sprite(self, 'spr_Gooma_2b')
    } /* walk */ else {
      GO_set_sprite(self, 'spr_Gooma_2a') // walk
    }
    // B5E7
    if (!gmBool(self.pending_death) && gmBool(self.attack_state)) {
      if (self.attack_state === self.attack_state_SWING) {
        GO_set_sprite(self, 'spr_Gooma_3a') // attack
      } else if (gmBool(g.counter1 & 0x08)) {
        GO_set_sprite(self, 'spr_Gooma_1b') // twirl weapon
      } else {
        GO_set_sprite(self, 'spr_Gooma_1a') // twirl weapon
      }
    }
  } else {
    GO_set_sprite(self, 'spr_Gooma_1a')
  }
  // ----------------------------------------------------
  self.Weapon_Ball_sprite = 0
  self.Weapon_Chain_sprite = 0
  // 1,2. draw, attack
  if (!gmBool(self.pending_death) && gmBool(self.attack_state)) {
    switch (self.attack_state) {
      // -----------------------------------------------
      case self.attack_state_DRAWBACK: {
        self.Weapon_Ball_sprite = 'spr_Boss_Spike_ball_1a'
        _idx = self.timer >> 1
        _idx &= 0x07
        if (gmBool(self.facing_dir)) {
          _idx ^= 0x07
        }
        //  04 FC F8 FC   04 0C 10 0C
        _data = '04FCF8FC' + '040C100C'
        self.SwordHB_xoff = str_hex(_data, _idx)
        self.SwordHB_xoff -= (self.SwordHB_xoff & 0x80) << 1
        //  08 0C 14 1C   20 1C 14 0C
        _data = '080C141C' + '201C140C'
        self.SwordHB_yoff = str_hex(_data, _idx)
        self.SwordHB_xoff += g.HB_ADJ_X
        self.SwordHB_yoff += g.HB_ADJ_Y
        break
      }
      // -----------------------------------------------
      case self.attack_state_SWING: {
        // B656. sprite_index is 24x48
        // if Gooma far enough away from camera edge
        if (gmBool(wINwAll(self.x - self.ww_ - 8, self.ww + 8, viewXL(), viewW()))) {
          // B69B
          _DATA = '24' + '28' + '2C' + '30' + '34' + '38' + '2C' + '20' //  24 28 2C 30 34 38 2C 20
          _DATA += 'E4' + 'E0' + 'DC' + 'D8' + 'D4' + 'D0' + 'DC' + 'E8' //  E4 E0 DC D8 D4 D0 DC E8
          _DIFF = str_hex(_DATA, ((g.counter1 >> 1) & 0x07) + (+!gmBool(self.facing_dir) << 3))
          _DIFF -= (_DIFF & 0x80) << 1
          //
          if (self.xl + _DIFF >= viewXL() && self.xl + _DIFF <= viewXR()) {
            // B6C5
            self.Weapon_Ball_sprite = 'spr_Boss_Spike_ball_1a'
            self.Weapon_Chain_sprite = 'spr_Boss_Spike_ball_Chain_1a'
            self.SwordHB_xoff = _DIFF
            self.SwordHB_yoff = 18
            _XOFF = 16
            if (gmBool(self.facing_dir)) {
              _XOFF = -24
            }
            self.Weapon_Chain_x = self.xl + self.SwordHB_xoff + _XOFF
            self.Weapon_Chain_x += (g.counter1 & 0x01) << 3
            self.Weapon_Chain_x += 4
          }
        }
        break
      }
    } //switch(attack_state)
    if (self.SwordHB_yoff !== 0) {
      self.SwordHB_yoff += 9
    }
    self.Weapon_Ball_x = self.xl + self.SwordHB_xoff + 8
    self.Weapon_Ball_y = self.yt + self.SwordHB_yoff - 1
    //if (attack_state==attack_state_DRAWBACK && timer&$1) sdm(", x-Weapon_Ball_x "+string(x-Weapon_Ball_x)+", y-Weapon_Ball_y "+string(y-Weapon_Ball_y));
    //if (attack_state==attack_state_DRAWBACK && timer&$1) sdm(", Weapon_Ball_x $"+hex_str(Weapon_Ball_x)+", Weapon_Ball_y $"+hex_str(Weapon_Ball_y));
  }
}

/** GML: Gooma_draw() */
export function Gooma_draw(self: Gooma01) {
  let _can_draw: any

  if (!gmBool(self.can_draw_self)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  draw_sprite_(self.Weapon_Chain_sprite, 0, self.Weapon_Chain_x, self.drawY, self.Weapon_PALIDX, self.xScale)
  draw_sprite_(
    self.Weapon_Chain_sprite,
    0,
    self.Weapon_Chain_x + 0x10,
    self.drawY,
    self.Weapon_PALIDX,
    self.xScale,
  )
  GO_draw_sprite(self, self.sprite, self.palidx)
  draw_sprite_(
    self.Weapon_Ball_sprite,
    0,
    self.Weapon_Ball_x,
    self.Weapon_Ball_y,
    self.Weapon_PALIDX,
    self.xScale,
  )
  if (
    gmBool(g.mod_Gooma_Projectile_1) &&
    self.ver === 2 &&
    gmBool(self.projectile_tokens) &&
    gmBool(self.Weapon_Ball_sprite)
  ) {
    _can_draw = false
    switch (g.mod_Gooma_Projectile_1) {
      // ---------------------------------------------------
      case 1: {
        if (
          self.attack_state === self.attack_state_DRAWBACK ||
          (self.attack_state === self.attack_state_SWING && ((g.counter1 >> 1) & 0x07) < 6)
        ) {
          _can_draw = true
        }
        break
      }
      // ---------------------------------------------------
      case 2: {
        if (self.attack_state === self.attack_state_DRAWBACK) {
          _can_draw = true
        }
        break
      }
    }
    if (gmBool(_can_draw)) {
      draw_sprite_(
        'spr_Flame1',
        0,
        self.Weapon_Ball_x,
        self.Weapon_Ball_y - 4,
        G.PI_MOB_ORG,
        sign_(g.counter1 & 0x04),
      )
    }
  }
}
