/** Enemy-side reactions to the player's sword, projectiles and body (E4D9…E726). */
import { BODY_HB_IDX_DYNAMIC, CS_BD1, CS_BTM, CS_PR1, CS_SW1, ITM_SWRD } from '@z2/data'
import { gmBool, isVal } from '../../nes/math8'
import { NOONE } from '../../runtime/instance'
import type { GoBody } from './body'
import { env } from './env'
import { rectInRect, rectInView } from './geometry'
import {
  GO_can_collide_this_frame,
  GOB_update_shield_offsets,
  GOB_update_sword_hb_1a,
  GOB_update_sword_offsets,
  isKind,
  PC_update_sword_hb,
  update_body_hb_1a,
  update_shield_hb,
} from './hitbox'
import { ocsH2 } from './ocs'
import {
  collide_pc_body,
  collide_pc_proj,
  collide_pc_shield,
  collide_pc_sword,
  enemy_collide_pc_body,
} from './pc'

/**
 * `GOB_body_collide_pc_proj()` — E48B: PC projectile vs enemy body. stun_timer + CS_PR1/CS_SW1 ensure
 * damage cannot occur more than once from the same attack.
 */
export function GOB_body_collide_pc_proj(self: GoBody): void {
  if (!self.react_proj) return // 0: NO INTERACTION
  if (self.stun_timer) return // stops damage every frame while proj still colliding
  if (self.state !== self.state_NORMAL) return
  update_body_hb_1a(self)
  const p = collide_pc_proj(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h, self.BodyHB_r)
  if (!p) {
    // E6A6
    self.cs &= ~CS_PR1
    return
  }
  const pc = env.pc()
  // E6AE, E6CF. react_proj: $0000FF body vulnerable, $00FF00 disintegrate on body. BIT_BEM1 $01, BIT_FIR1 $02
  let canPushBack = false
  const BITS = p.type_bits & (p.BIT_BEM1 | p.BIT_FIR1)
  if (self.react_proj & BITS) {
    // E6F3: PC behavior dictating projectile pushback is in the OG code (E6F3-E6F7 → E70C → E4AB).
    canPushBack =
      !(self.cs & (CS_PR1 | CS_SW1)) ||
      isVal(
        pc.behavior,
        pc.behavior_STAB_UP,
        pc.behavior_STAB_DOWN,
        pc.behavior_DAMAGE,
        pc.behavior_HOLD_ITEM1,
        pc.behavior_HOLD_ITEM2,
        pc.behavior_HOLD_ITEM3,
        pc.behavior_HOLD_ITEM4,
      )
    // Proj can only collide when stunTimer is clear, CS_PR1 is clear, CS_SW1 is clear
    if (!(self.cs & (CS_PR1 | CS_SW1))) {
      // E70E
      self.cs |= CS_PR1
      env.fn.damage_gob(self, pc.dl_ATTACK_DAMAGE[env.file().level_atk] ?? 0, true)
    }
  }
  if ((self.react_proj >> 8) & BITS) {
    // E6E6: disintegrate
    canPushBack = true
    p.hspd = 0
    p.disintegrate_counter = 0xf2 // 008D,Y = $F2. Start disintegrate
    p.state = p.state_EXPLODE
  }
  if (canPushBack) {
    // E4AB. pushback = $F4 when facing left, $0C when facing right
    env.fn.set_go_hspd_pushbback(self, (0xc * p.facing_dir) & 0xff)
  }
}

/**
 * `GOB_body_collide_pc_sword()` — E677: PC sword vs enemy body.
 * react_sword: each byte a reaction type, each bit a sword attack type ($01 stab high, $02 stab low,
 * $04 downthrust, $08 upthrust): $0000FF take damage, $00FF00 body is solid, $FF0000 handled elsewhere.
 */
export function GOB_body_collide_pc_sword(self: GoBody): void {
  const pc = env.pc()
  if (!pc.SwordHB_collidable || !self.react_sword || self.state !== self.state_NORMAL) {
    self.cs &= ~CS_SW1
    pc.SwordHB2_colliding = NOONE
    return
  }
  let reactSword = self.react_sword
  update_body_hb_1a(self)
  PC_update_sword_hb()
  // SwordHB2_colliding is for keys, pbags, jars
  if (
    self.cs & CS_BTM &&
    !self.vspd &&
    !pc.ogr &&
    pc.SwordHB2_collidable &&
    rectInRect(
      self.BodyHB_xl,
      self.BodyHB_yt,
      self.BodyHB_w,
      self.BodyHB_h,
      pc.SwordHB2_xl,
      pc.SwordHB2_yt,
      pc.SwordHB2_w,
      pc.SwordHB2_h,
    )
  ) {
    pc.SwordHB2_colliding = self
  } else pc.SwordHB2_colliding = NOONE
  const HB1_COLLIDING = collide_pc_sword(
    self.BodyHB_xl,
    self.BodyHB_yt,
    self.BodyHB_w,
    self.BodyHB_h,
    self.BodyHB_r,
  )
  if (!HB1_COLLIDING && pc.SwordHB2_colliding !== self) {
    self.cs &= ~CS_SW1
    return
  }
  // E6AE. global.pc.attack_bits is from PREVIOUS frame's behavior
  const ATK_BITS = pc.attack_bits
  // ** OG data shows only Tektite & Zora have solid body ($00FF00)
  if ((reactSword >> 8) & ATK_BITS) {
    // ITM_SWRD can pierce solid body
    if (
      env.file().items & ITM_SWRD &&
      (!env.fn.pc_is_cucco() || env.game().CuccoSpell2_Active) &&
      !isKind(self, 'SpikeTrap')
    ) {
      reactSword |= (reactSword >> 8) & ATK_BITS
    } else {
      self.pc_sword_collided_solid_body = true // skip parts of GOB update this frame
      env.fn.pc_sword_colliding_solid_body(self) // E654: SND_STRK_SLD1, bounce for DWTH or pushback
      return
    }
  }
  const REACT_BITS = reactSword & ATK_BITS
  if (!REACT_BITS) {
    // NOT vulnerable to current attack type
    self.cs &= ~CS_SW1
    pc.SwordHB2_colliding = NOONE
    return
  }
  // E6BE: a stunned Item (red bottle from SpawnByStab) gets a chance to drop first
  if (isKind(self, 'Item') && self.stun_timer) {
    pc.SwordHB2_colliding = NOONE
    return
  }
  // E6FD: upthrust only counts against a GO's underside (OG uses CURRENT frame's behavior here)
  if (pc.behavior === pc.behavior_STAB_UP && pc.yt < self.yt) {
    self.cs &= ~CS_SW1
    pc.SwordHB2_colliding = NOONE
    return
  }
  if (!HB1_COLLIDING) {
    self.cs &= ~CS_SW1
    return
  }
  if (pc.behavior === pc.behavior_STAB_UP) pc.vspd = 0
  // E708
  if (!(self.cs & CS_SW1)) {
    self.cs |= CS_SW1
    if (pc.behavior === pc.behavior_STAB_DOWN) env.fn.PC_set_bounce() // Downthrust
    // E726. $FF000000 bits: only `cs |= CS_SW1`, the object reacts later in its update (e.g. FaBlA).
    if (!((reactSword >> 0x18) & REACT_BITS)) {
      env.fn.damage_gob(self, env.fn.get_pc_attack_damage(), false)
    }
  }
}

/** `GOB_body_collide_pc_body_1a()` — E4D9: player body vs enemy body → CS_BD1. */
export function GOB_body_collide_pc_body_1a(self: GoBody): void {
  const pc = env.pc()
  // GML: `BodyHB_idx || BodyHB_idx==BODY_HB_IDX_DYNAMIC` — GML truthiness, so -1 is false here and -2 is
  // true only through the explicit test. JS `!!` let `-1` (SwitchB, FireRope) into a test ZALiA excludes
  // them from.
  const C1 = gmBool(self.BodyHB_idx) || self.BodyHB_idx === BODY_HB_IDX_DYNAMIC
  const C2 = GO_can_collide_this_frame(self.update_idx) || isKind(self, 'NPC') // NPC OR every other frame
  update_body_hb_1a(self)
  self.BodyHB_can_draw = (C1 && C2) || (C1 && !!self.react_sword && pc.SwordHB_collidable)
  if (
    C1 &&
    C2 &&
    !self.stun_timer &&
    ocsH2(self) && // at least 8 pixels of gob on screen
    !(pc.ocs & 0x4) && // pc center x is on screen
    self.state === self.state_NORMAL &&
    collide_pc_body(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h, self.BodyHB_r)
  ) {
    self.cs |= CS_BD1
  } else {
    self.cs &= ~CS_BD1
  }
}

/**
 * `GOB_shield_collision_1a()` — E617: enemy shield vs PC projectile/sword. Returns true when the sword hit
 * the shield. (Aruroda, Fokka, Geru, Girubokku, IronKnuckle, Stalfos, Horsehead, Helmethead, Gooma, Rebonack)
 */
export function GOB_shield_collision_1a(self: GoBody): boolean {
  GOB_update_shield_offsets(self)
  update_shield_hb(self)
  self.ShieldHB_can_draw = self.ShieldHB_idx !== 0
  if (rectInView(self.ShieldHB_x, self.ShieldHB_y, self.ShieldHB_w, self.ShieldHB_h)) {
    const p = collide_pc_proj(
      self.ShieldHB_x,
      self.ShieldHB_y,
      self.ShieldHB_w,
      self.ShieldHB_h,
      self.ShieldHB_r,
    )
    if (p) {
      p.hspd = 0
      p.disintegrate_counter = 0xf2 // 008D,Y = $F2. Start disintegrate
      p.state = p.state_EXPLODE
      env.fn.aud_play_sound(env.fn.get_audio_theme_track('dk_HitShield')) // *ding*
    }
    if (
      collide_pc_sword(self.ShieldHB_x, self.ShieldHB_y, self.ShieldHB_w, self.ShieldHB_h, self.ShieldHB_r)
    ) {
      env.fn.pc_sword_colliding_solid_body(self) // plays Audio.SND_STRK_SLD1
      self.pc_sword_collided_solid_body = true
      return true
    }
  }
  return false
}

/** `GOB_sword_collision_1a()` — E579: enemy sword vs PC body (boss swords launch the PC further). */
export function GOB_sword_collision_1a(self: GoBody): void {
  GOB_update_sword_offsets(self)
  GOB_update_sword_hb_1a(self)
  self.SwordHB_can_draw = self.SwordHB_collidable
  if (
    self.SwordHB_collidable &&
    collide_pc_body(self.SwordHB_x, self.SwordHB_y, self.SwordHB_w, self.SwordHB_h)
  ) {
    // E582: JSR E2EF
    const pc = env.pc()
    const invulnerable = pc.iframes_timer
    enemy_collide_pc_body(self) // damage pc
    // E587: BOSS SWORD HIT
    if (isKind(self, 'Boss') && !invulnerable) {
      const g = env.game()
      if (!g.DevTools_state || (g.dev_invState & 0x3) !== 0x2) {
        // Boss sword makes the PC damage-hop higher & further
        pc.vspd = (pc.vspd << 1) & 0xff
        self.facing_dir = env.fn.dir_to_pc(self)
        pc.hspd = (0x18 * self.facing_dir) & 0xff
      }
    }
  }
}

/** `GOB_sword_collision_2a()` — E563: enemy sword vs PC shield → pushback both. */
export function GOB_sword_collision_2a(self: GoBody): boolean {
  GOB_update_sword_offsets(self)
  GOB_update_sword_hb_1a(self)
  self.SwordHB_can_draw = self.SwordHB_collidable
  if (
    self.SwordHB_collidable &&
    collide_pc_shield(self.SwordHB_x, self.SwordHB_y, self.SwordHB_w, self.SwordHB_h)
  ) {
    // E371
    env.fn.pushback_pc_and_go(self)
    env.fn.aud_play_sound(env.fn.get_audio_theme_track('dk_StrikeSolid'))
    return true
  }
  return false
}
