/**
 * Registration entry for the gob1 ports in this fork: enemies myu–zora, kakusu, spawners, spike traps, fire rope.
 * Importing this module registers the object classes and their data-bound scripts.
 */
export * from './enemy/myu/Myu'
export * from './enemy/octorok/Octorok'
export * from './enemy/ra/Ra'
export * from './enemy/snaraa/Snaraa'
export * from './enemy/stalfoon/Stalfoon'
export * from './enemy/stalfos/Stalfos'
export * from './enemy/stallakk/Stallakk'
export * from './enemy/tektite/Tektite'
export * from './enemy/tonn/TonnA'
export * from './enemy/tyell/Tyell'
export * from './enemy/wheep/Wheep'
export * from './enemy/wizard/Wizard'
export * from './enemy/wosu/Wosu'
export * from './enemy/zora/Zora'
export * from './fire_rope/FireRope'
export * from './kakusu/Kakusu'
export * from './shared'
export * from './spawner/spawners'
export * from './spike_trap/spikeTraps'

import type { ScriptFn } from '../../classes'
import { objectClasses, registerObject, registerScripts, scriptRegistry } from '../../registry'

/**
 * The modules above register their classes and scripts at import time (no per-module `register*()` in this
 * wave). Snapshot what is in the registries once this module has been imported so `registerEnemies()` can
 * replay it after a test clears `objectClasses` — replaying another group's rows is a harmless no-op.
 */
const CLASSES = new Map(objectClasses)
const SCRIPTS = new Map(scriptRegistry)

/** Re-registers myu…zora, kakusu, spawners, spike traps and the fire rope after a registry reset. */
export function registerMyuToZora(): void {
  for (const [name, cls] of CLASSES) registerObject(name, cls)
  registerScripts(Object.fromEntries(SCRIPTS) as Record<string, ScriptFn<never>>)
}
