const clamp = (v: number, lo: number, hi: number) => Math.min(Math.max(v, lo), hi)

/** 1x1 stone block of `ts_Man_made_4a_WRB` — the fill both tsrc grids start from. */
const DEFAULT_TSRC = (): number => (Math.max(0, g.dl_tileset.findIndex('ts_Man_made_4a_WRB')) << 8) | 0xb4

/**
 * `tile_layer_delete_at(depth, x, y)` — GM builtin that is not part of the tile port; expressed with the
 * primitives that are (GM removes every tile of that layer under the point).
 */
function tile_layer_delete_at(depth: number, x: number, y: number): void {
  for (;;) {
    const _tile_id = tile_layer_find(depth, x, y)
    if (_tile_id === -1) break
    tile_delete(_tile_id)
  }
}

