/**
 * `SmasherTrapManager_init2()` — reads one `_Trap_Data` blob of $B four-char properties per trap and creates
 * a SmasherTrap01 for each. ZALiA's `_Delay` parse writes a local the script never reads; dropped.
 */
export function SmasherTrapManager_init2(self: SmasherTrapManager): void {
  let _trap_data: string | undefined
  if (self.dk_spawn !== undefined) {
    for (let _i = 1; _i <= 0x10; _i++) {
      const _raw = g.dm_spawn.get(self.dk_spawn + STR_Data + hex_str(_i))
      if (_raw === undefined) break //_i
      const _data = String(_raw)
      let _str: string = STR_Trap + STR_Data
      let _pos = _data.indexOf(_str)
      if (_pos >= 0) _trap_data = _data.slice(_pos + _str.length)
      _str = STR_Trigger + STR_Position
      _pos = _data.indexOf(_str)
      if (_pos >= 0) {
        const _val1 = _data.slice(_pos + _str.length)
        self.trigger_x = str_hex(_val1.slice(0, 4))
        self.trigger_y = str_hex(_val1.slice(4, 8))
      }
    }
  }
  if (_trap_data === undefined) return
  const _PROP_COUNT = 0xb
  const _CHAR_COUNT = 0x4
  const _trap_count = Math.trunc(_trap_data.length / (_PROP_COUNT * _CHAR_COUNT))
  // ZALiA grew Trap_dg a column at a time inside the loop; the final width is _trap_count either way.
  self.Trap_dg = new DsGrid<TrapCell>(_trap_count, 0x3, 0)
  for (let _i = 0; _i < _trap_count; _i++) {
    const _data = _trap_data.substr(_i * (_PROP_COUNT * _CHAR_COUNT), _PROP_COUNT * _CHAR_COUNT)
    const _idx = _i
    self.Trap_dg.set(_idx, 0x1, self.sub_state_IDLE) // state
    let _j = -1
    const _next = () => str_hex(_data.substr(++_j * _CHAR_COUNT, _CHAR_COUNT))
    self.Trap_dg.set(_idx, 0x2, _next()) // delay
    const _w = _next()
    const _h = _next()
    const _x_ax = _next()
    const _x_ay = _next()
    const _x_bx = _next()
    const _x_by = _next()
    const _y_ax = _next()
    const _y_ay = _next()
    const _y_bx = _next()
    const _y_by = _next()
    let _xl: number
    let _yt: number
    if (_x_ax !== _x_bx) {
      _xl = _x_ax + (_w >> 1) * sign_(_x_ax > _x_bx) - (_w >> 1)
      _yt = _x_ay - (_h >> 1)
    } else {
      _xl = _y_ax - (_w >> 1)
      _yt = _y_ay + (_h >> 1) * sign_(_y_ay > _y_by) - (_h >> 1)
    }
    const _inst = GameObject_create(_xl, _yt, 'SmasherTrap01', 1, -1, self.palidx) as Ref<SmasherTrap01>
    if (!instanceExists(_inst)) continue // with(noone) — nothing runs
    self.Trap_dg.set(_idx, 0x0, _inst)
    GO_sprite_init(_inst, _inst.Smasher_SPRITE1)
    SmasherTrap01_init3(_inst, _inst.attack_speed, _x_ax, _x_ay, _x_bx, _x_by, _y_ax, _y_ay, _y_bx, _y_by)
  }
}

/** `SmasherTrapManager_update()` */
export function SmasherTrapManager_update(self: SmasherTrapManager): void {
  const P = pc()
  switch (self.sub_state) {
    case self.sub_state_IDLE: {
      if (!gmBool(P.ogr)) {
        // if pc on ground
        if (pointInRect(P.cp1X, P.cp1Y, self.trigger_x - 0x10, self.trigger_y - 0x8, 0x20, 0x10)) {
          const _TRAP_COUNT = self.Trap_dg.width
          for (let _i = 0; _i < _TRAP_COUNT; _i++) {
            const _trap = self.Trap_dg.get(_i, 0x0)
            if (typeof _trap === 'number' || !instanceExists(_trap)) continue
            _trap.sub_state = _trap.sub_state_DELAY
            // ZALiA seeds `timer`; SmasherTrap01's DELAY state counts `DELAY_timer`. Kept as written —
            // this manager is never spawned or stepped, so the mismatch is unreachable.
            _trap.timer = self.Trap_dg.get(_i, 0x2) as number
          }
          self.sub_state = self.sub_state_DONE
          break //case sub_state_IDLE
        }
      }
      break
    }
    case self.sub_state_TELL: {
      if (gmBool(self.timer)) break
      self.sub_state = self.sub_state_ATTACK
      break
    }
    case self.sub_state_ATTACK:
      break
    case self.sub_state_DONE:
      break
  }
}

