/** `SmasherTrap01_init2()` */
export function SmasherTrap01_init2(self: SmasherTrap01): void {
  let _trap_data: string | undefined
  GO_sprite_init(self, self.Smasher_SPRITE1)
  self.facing_dir = 1
  if (self.dk_spawn !== undefined) {
    self.attack_speed = val(g.dm_spawn.get(self.dk_spawn + STR_Speed), self.attack_speed) as number
    for (let _i = 1; _i <= 0x10; _i++) {
      const _raw = g.dm_spawn.get(self.dk_spawn + STR_Data + hex_str(_i))
      if (_raw === undefined) break //_i
      const _data = String(_raw)
      let _datakey0: string = STR_Delay
      let _pos = _data.indexOf(_datakey0)
      if (_pos >= 0) self.DELAY_timer = str_hex(_data.slice(_pos + _datakey0.length))
      _datakey0 = STR_Trap + STR_Data
      _pos = _data.indexOf(_datakey0)
      if (_pos >= 0) _trap_data = _data.slice(_pos + _datakey0.length)
      _datakey0 = STR_Trigger + STR_Type
      _pos = _data.indexOf(_datakey0)
      if (_pos >= 0) self.Trigger_type = str_hex(_data.slice(_pos + _datakey0.length))
      _datakey0 = STR_Trigger + STR_Depth
      _pos = _data.indexOf(_datakey0)
      if (_pos >= 0) self.Trigger_depth = Number(_data.slice(_pos + _datakey0.length))
      _datakey0 = STR_Trigger + STR_Position
      _pos = _data.indexOf(_datakey0)
      if (_pos >= 0) {
        const _val1 = _data.slice(_pos + _datakey0.length)
        self.Trigger_xl = str_hex(_val1.slice(0, 4))
        self.Trigger_yt = str_hex(_val1.slice(4, 8))
      }
      _datakey0 = STR_Trigger + STR_Size
      _pos = _data.indexOf(_datakey0)
      if (_pos >= 0) {
        const _val1 = _data.slice(_pos + _datakey0.length)
        self.Trigger_w = str_hex(_val1.slice(0, 4))
        self.Trigger_h = str_hex(_val1.slice(4, 8))
      }
    }
  }

  switch (self.Trigger_type) {
    case 2: {
      if (self.Trigger_depth !== 0 && gmBool(self.Trigger_w >> 3) && gmBool(self.Trigger_h >> 3)) {
        self.TriggerHB_w = self.Trigger_w
        self.TriggerHB_h = self.Trigger_h
        self.TriggerHB_xl = self.Trigger_xl
        self.TriggerHB_yt = self.Trigger_yt
        self.TriggerHB_yt += self.Trigger_OFFSET1
        const _idx = g.dl_TILE_DEPTHS.findIndex(self.Trigger_depth)
        if (_idx !== -1) self.Trigger_dg_depth_pi_idx = _idx
        // p.dg_depth_pi[#_idx,0/1] pi default/current, [#_idx,2/3] permut default/current (00-05)
        self.Trigger_dg_tsrc = new DsGrid<number>(
          self.Trigger_w >> 3,
          self.Trigger_h >> 3,
          DEFAULT_TSRC(), // 1x1 stone block
        )
        for (let _i = 0; _i < self.Trigger_dg_tsrc.width; _i++) {
          for (let _j = 0; _j < self.Trigger_dg_tsrc.height; _j++) {
            const _tile_id = tile_layer_find(
              self.Trigger_depth,
              self.Trigger_xl + (_i << 3),
              self.Trigger_yt + (_j << 3),
            )
            if (_tile_id !== -1) {
              const _ts = tile_get_background(_tile_id)
              const _ts_idx = g.dl_tileset.findIndex(_ts)
              if (_ts_idx !== -1) {
                const _tsrc = ((tile_get_top(_tile_id) >> 3) << 4) | (tile_get_left(_tile_id) >> 3)
                self.Trigger_dg_tsrc.set(_i, _j, (_ts_idx << 8) | _tsrc)
              }
            }
          }
        }
      }
      break
    }
    default: {
      self.TriggerHB_w = 0x20
      self.TriggerHB_h = 0x10
      self.TriggerHB_xl = self.Trigger_xl
      self.TriggerHB_yt = self.Trigger_yt
      self.TriggerHB_yt += self.Trigger_OFFSET1
      break
    }
  }

  if (_trap_data !== undefined) {
    const _CHAR_COUNT = 0x4
    let _i = -1
    const _next = () => str_hex((_trap_data as string).substr(++_i * _CHAR_COUNT, _CHAR_COUNT))
    const _W = _next()
    const _H = _next()
    if (gmBool(_W)) {
      self.ww = _W
      self.ww_ = self.ww >> 1
    }
    if (gmBool(_H)) {
      self.hh = _H
      self.hh_ = self.hh >> 1
    }
    self.attack_x_head_start_x = _next()
    self.attack_x_head_start_y = _next()
    self.attack_x_head_end_x = _next()
    self.attack_x_head_end_y = _next()
    self.attack_y_head_start_x = _next()
    self.attack_y_head_start_y = _next()
    self.attack_y_head_end_x = _next()
    self.attack_y_head_end_y = _next()
    SmasherTrap01_init3(
      self,
      self.attack_speed,
      self.attack_x_head_start_x,
      self.attack_x_head_start_y,
      self.attack_x_head_end_x,
      self.attack_x_head_end_y,
      self.attack_y_head_start_x,
      self.attack_y_head_start_y,
      self.attack_y_head_end_x,
      self.attack_y_head_end_y,
    )
  }

  spawnXYFromHeadStart(self)

  switch (self.ver) {
    case 1:
      break
    case 2: {
      self.Wall_dg_tsrc = new DsGrid<number>(0, 0, 0)
      // so `set_xy` sets correct values
      self.sprite_index_xoff = self.ww_
      self.sprite_index_yoff = self.hh_
      spawnXYFromHeadStart(self)
      set_xy(self, self.spawn_xl + self.ww_, self.spawn_yt + self.hh_)
      for (let _i = g.dl_TILE_DEPTH_NAMES.size - 1; _i >= 0; _i--) {
        const _datakey0 = g.dl_TILE_DEPTH_NAMES.get(_i) as string // "BG01", "BG02", ...
        const _depth = g.dm_TILE_DEPTH.get(_datakey0) as number | undefined
        const _layer_name = g.dm_tile_file?.get?.(_datakey0 + STR_Depth + STR_Layer + STR_Name) as
          | string
          | undefined
        if (_depth !== undefined && _layer_name !== undefined && String(_layer_name).includes('FGWALL')) {
          if (
            (self.attack_x_direction !== 0 &&
              tile_layer_find(
                _depth,
                self.attack_x_head_start_x - self.attack_x_direction,
                self.attack_x_head_start_y,
              ) !== -1) ||
            (self.attack_y_direction !== 0 &&
              tile_layer_find(
                _depth,
                self.attack_y_head_start_x,
                self.attack_y_head_start_y - self.attack_y_direction,
              ) !== -1)
          ) {
            self.FGWALL_depth = _depth
            GO_depth_init(self, self.FGWALL_depth - 3)
            break //_i
          }
        }
      }

      if (self.FGWALL_depth !== 0) {
        const _tile_id =
          self.attack_x_direction !== 0
            ? tile_layer_find(
                self.FGWALL_depth,
                self.attack_x_head_start_x - self.attack_x_direction,
                self.attack_x_head_start_y,
              )
            : tile_layer_find(
                self.FGWALL_depth,
                self.attack_y_head_start_x,
                self.attack_y_head_start_y - self.attack_y_direction,
              )
        // ZALiA logs "Did not find tile at head start xy" when this misses; dropped with the DEV blocks.
        if (_tile_id !== -1) {
          const _CLMS0 = self.ww >> 3
          const _ROWS0 = self.hh >> 3
          self.Wall_dg_tsrc = new DsGrid<number>(_CLMS0, _ROWS0, DEFAULT_TSRC())
          // Whether this will be accurate positioning of a repeating tile block depends on the
          // tileset/texture-style used. clm/row count of the repeating tile block.
          // FIDELITY: `max(1, ...)` — a trap under $30 wide/tall made this 0 and the `mod` below undefined.
          const _COUNT1 = Math.max(
            1,
            (self.attack_x_direction !== 0 ? Math.min(4, _CLMS0 - 2) : Math.min(4, _ROWS0 - 2)) & 0xe,
          )
          // first (or first+_COUNT1) clm/row, local to the Smasher, of a repeating tile block
          let _CLMA: number
          let _ROWA: number
          if (self.attack_x_direction !== 0) {
            let _x = g.rm_w * (gmBool(self.attack_x_direction) ? 0 : 1)
            _x = clamp(_x, self.spawn_xl, self.spawn_xl + self.ww)
            _CLMA = Math.abs(_x - self.spawn_xl) >> 3
            _ROWA = 0
          } else {
            let _y = g.rm_h * (gmBool(self.attack_y_direction) ? 0 : 1)
            _y = clamp(_y, self.spawn_yt, self.spawn_yt + self.hh)
            _CLMA = 0
            _ROWA = Math.abs(_y - self.spawn_yt) >> 3
          }
          // first (or first+_COUNT1) clm/row, local to the room, of a repeating tile block
          const _CLMB = (self.spawn_xl + (_CLMA << 3)) >> 3
          const _ROWB = (self.spawn_yt + (_ROWA << 3)) >> 3
          for (let _i = 0; _i < _CLMS0; _i++) {
            for (let _j = 0; _j < _ROWS0; _j++) {
              let _xl = self.spawn_xl + (_i << 3)
              if (_xl < 0 || _xl >= g.rm_w) {
                const _clms = _COUNT1 - (Math.abs(_i - _CLMA) % _COUNT1)
                // _CLMB is either 0 or the first clm outside the room
                _xl = (_CLMB << 3) + (_clms << 3) * sign_(_xl < 0)
              }
              let _yt = self.spawn_yt + (_j << 3)
              if (_yt < 0 || _yt >= g.rm_h) {
                const _rows = _COUNT1 - (Math.abs(_j - _ROWA) % _COUNT1)
                // _ROWB is either 0 or the first row outside the room
                _yt = (_ROWB << 3) + (_rows << 3) * sign_(_yt < 0)
              }
              const _id = tile_layer_find(self.FGWALL_depth, _xl, _yt)
              if (_id !== -1) {
                const _ts = tile_get_background(_id)
                const _ts_idx = g.dl_tileset.findIndex(_ts)
                if (_ts_idx !== -1) {
                  const _tsrc = ((tile_get_top(_id) >> 3) << 4) | (tile_get_left(_id) >> 3)
                  self.Wall_dg_tsrc.set(_i, _j, (_ts_idx << 8) | _tsrc)
                }
              }
            }
          }
        }
      }
      break
    }
  }

  set_xy(self, self.spawn_xl + self.ww_, self.spawn_yt + self.hh_)

  self.BodyHB_w = self.ww
  self.BodyHB_h = self.hh

  self.solid_type = TID_SOLID1
  add_to_solid_inst_list(self)
}

/** The spawn_xl/spawn_yt block `SmasherTrap01_init2` runs twice (once before, once inside `case ver 2`). */
function spawnXYFromHeadStart(self: SmasherTrap01): void {
  if (self.attack_x_direction !== 0) {
    self.spawn_xl = self.attack_x_head_start_x + self.ww_ * -self.attack_x_direction - self.ww_
    self.spawn_yt = self.attack_x_head_start_y - self.hh_
  } else {
    self.spawn_xl = self.attack_y_head_start_x - self.ww_
    self.spawn_yt = self.attack_y_head_start_y + self.hh_ * -self.attack_y_direction - self.hh_
  }
}

/** `SmasherTrap01_init3(speed, x start_x, x start_y, x end_x, x end_y, y start_x, y start_y, y end_x, y end_y)` */
export function SmasherTrap01_init3(
  self: SmasherTrap01,
  speed: number,
  x_start_x: number,
  x_start_y: number,
  x_end_x: number,
  x_end_y: number,
  y_start_x: number,
  y_start_y: number,
  y_end_x: number,
  y_end_y: number,
): void {
  self.attack_speed = speed
  self.attack_x_head_start_x = x_start_x
  self.attack_x_head_start_y = x_start_y
  self.attack_x_head_end_x = x_end_x
  self.attack_x_head_end_y = x_end_y
  self.attack_y_head_start_x = y_start_x
  self.attack_y_head_start_y = y_start_y
  self.attack_y_head_end_x = y_end_x
  self.attack_y_head_end_y = y_end_y
  if (self.attack_x_head_end_x !== self.attack_x_head_start_x) {
    self.attack_x_head_x = self.attack_x_head_start_x
    self.attack_x_head_y = self.attack_x_head_start_y
    self.attack_x_direction = sign_(self.attack_x_head_end_x > self.attack_x_head_start_x)
  }
  if (self.attack_y_head_end_y !== self.attack_y_head_start_y) {
    self.attack_y_head_x = self.attack_y_head_start_x
    self.attack_y_head_y = self.attack_y_head_start_y
    self.attack_y_direction = sign_(self.attack_y_head_end_y > self.attack_y_head_start_y)
  }
}

/** `SmasherTrap01_update()` */
export function SmasherTrap01_update(self: SmasherTrap01): void {
  const P = pc()
  const _X_PREV = self.x
  const _Y_PREV = self.y
  self.hspd = 0
  self.vspd = 0

  switch (self.sub_state) {
    // ------------------------------------------------------------------------------------
    case self.sub_state_IDLE: {
      if (
        self.Trigger_state === 0 &&
        self.Trigger_xl >= 0 &&
        self.Trigger_yt >= 0 &&
        !gmBool(P.ogr) // if pc on ground
      ) {
        if (
          rectInRect(
            P.csBtm1X,
            P.csBtm1Y - self.TriggerHB_h,
            P.csBtm2X - P.csBtm1X,
            self.TriggerHB_h,
            self.TriggerHB_xl,
            self.TriggerHB_yt,
            self.TriggerHB_w,
            self.TriggerHB_h,
          )
        ) {
          self.Trigger_state = 1
          if (self.Trigger_type === 2) aud_play_combo1(0x13)
          self.sub_state = self.sub_state_DELAY
          break //case sub_state_IDLE
        }
      }
      break
    }

    // ------------------------------------------------------------------------------------
    case self.sub_state_DELAY: {
      if (gmBool(self.DELAY_timer)) {
        self.DELAY_timer--
        break //case sub_state_DELAY
      }
      self.sub_state = self.sub_state_TELL
      break
    }

    // ------------------------------------------------------------------------------------
    case self.sub_state_TELL: {
      if (gmBool(self.TELL_timer)) {
        self.TELL_timer--
        break //case sub_state_TELL
      }
      self.sub_state = self.sub_state_ATTACK
      break
    }

    // ------------------------------------------------------------------------------------
    case self.sub_state_ATTACK: {
      SmasherTrap01_update_ATTACK(self)
      // GML `instance_destroy(); exit;` only left the ATTACK script; here destroy() is immediate, so the
      // rest of the update is skipped for a trap that left the room.
      if (!self.exists) return
      break
    }

    // ------------------------------------------------------------------------------------
    case self.sub_state_DONE:
      break
  }

  self.BodyHB_can_draw = true
  update_body_hb(self)

  // updates all GameObject instances on top of trap
  update_go_xy_on_moving_platform(self, self.x - _X_PREV, self.y - _Y_PREV)

  update_EF11(self)
}

/** `SmasherTrap01_update_ATTACK()` */
export function SmasherTrap01_update_ATTACK(self: SmasherTrap01): void {
  const P = pc()
  let _collided_solid = false
  let _progress = 0
  let _x_change = 0
  let _y_change = 0

  // ------------------------------------------------------------------------------------
  // x movement -----------------------------------------------------------
  if (self.attack_x_direction !== 0) {
    const _HEAD_X_PREV = self.attack_x_head_x
    _progress = Math.min(1.0, self.attack_x_time / self.attack_x_ACCEL_TIME)
    self.attack_x_speed = self.attack_x_speed_MAX * (_progress * _progress * _progress)
    self.attack_x_head_x += Math.floor(self.attack_x_speed) * self.attack_x_direction
    self.attack_x_time++

    set_xy(self, self.attack_x_head_x + self.ww_ * -self.attack_x_direction, self.y)

    _x_change = self.attack_x_head_x - _HEAD_X_PREV

    if (_x_change !== 0) {
      if (!_collided_solid) {
        const _count = Math.max(2, Math.abs(_x_change) >> 3)
        for (let _i = 0; _i < _count; _i++) {
          let _x = _HEAD_X_PREV + (_i << 3) * self.attack_x_direction
          _x = clamp(
            _x,
            Math.min(_HEAD_X_PREV, self.attack_x_head_x),
            Math.max(_HEAD_X_PREV, self.attack_x_head_x),
          )
          for (let _j = 0; _j < self.hh >> 3; _j++) {
            if (gmBool(collide_solid_grid(_x + self.attack_x_direction, self.yt + (_j << 3)))) {
              _collided_solid = true
              _x += self.ww_ * -self.attack_x_direction
              _x = (_x >> 3) << 3
              set_xy(self, _x, self.y)
              _i = _count
              break //_j
            }
          }
        }
      }

      if (!_collided_solid) {
        for (const inst of world.instancesOf(SmasherTrap01)) {
          if (
            inst !== self &&
            rectInRect(
              inst.xl,
              inst.yt,
              inst.ww,
              inst.hh,
              self.attack_x_head_x + self.attack_x_direction,
              self.yt,
              Math.max(1, Math.abs(_x_change)),
              self.hh,
            )
          ) {
            _collided_solid = true
            let _x = inst.x + inst.ww_ * -self.attack_x_direction
            _x += self.ww_ * -self.attack_x_direction
            set_xy(self, _x, self.y)
            break //with(SmasherTrap01)
          }
        }
      }
    }

    self.attack_x_head_x = self.x + self.ww_ * self.attack_x_direction
    _x_change = self.attack_x_head_x - _HEAD_X_PREV
    if (_x_change !== 0) {
      self.hspd = Math.abs(_x_change) << 4
      self.hspd = (self.hspd * self.attack_x_direction) & 0xff
    }
  }

  // ------------------------------------------------------------------------------------
  // y movement -----------------------------------------------------------
  if (self.attack_y_direction !== 0) {
    const _HEAD_Y_PREV = self.attack_y_head_y
    _progress = Math.min(1.0, self.attack_y_time / self.attack_y_ACCEL_TIME)
    self.attack_y_speed = self.attack_y_speed_MAX * (_progress * _progress * _progress)
    self.attack_y_head_y += Math.floor(self.attack_y_speed) * self.attack_y_direction
    self.attack_y_time++

    set_xy(self, self.x, self.attack_y_head_y + self.hh_ * -self.attack_y_direction)

    _y_change = self.attack_y_head_y - _HEAD_Y_PREV

    if (_y_change !== 0) {
      if (!_collided_solid) {
        const _count = Math.max(2, Math.abs(_y_change) >> 3)
        for (let _i = 0; _i < _count; _i++) {
          let _y = _HEAD_Y_PREV + (_i << 3) * self.attack_y_direction
          _y = clamp(
            _y,
            Math.min(_HEAD_Y_PREV, self.attack_y_head_y),
            Math.max(_HEAD_Y_PREV, self.attack_y_head_y),
          )
          for (let _j = 0; _j < self.ww >> 3; _j++) {
            if (gmBool(collide_solid_grid(self.xl + (_j << 3), _y + self.attack_y_direction))) {
              _collided_solid = true
              _y += self.hh_ * -self.attack_y_direction
              _y = (_y >> 3) << 3
              set_xy(self, self.x, _y)
              _i = _count
              break //_j
            }
          }
        }
      }

      if (!_collided_solid) {
        for (const inst of world.instancesOf(SmasherTrap01)) {
          if (
            inst !== self &&
            rectInRect(
              inst.xl,
              inst.yt,
              inst.ww,
              inst.hh,
              self.xl,
              self.attack_y_head_y + self.attack_y_direction,
              self.ww,
              Math.max(1, Math.abs(_y_change)),
            )
          ) {
            _collided_solid = true
            let _y = inst.y + inst.hh_ * -self.attack_y_direction
            _y += self.hh_ * -self.attack_y_direction
            set_xy(self, self.x, _y)
            break //with(SmasherTrap01)
          }
        }
      }
    }

    self.attack_y_head_y = self.y + self.hh_ * self.attack_y_direction
    _y_change = self.attack_y_head_y - _HEAD_Y_PREV
    if (_y_change !== 0) {
      self.vspd = Math.abs(_y_change) << 4
      self.vspd = (self.vspd * self.attack_y_direction) & 0xff
    }
  }

  if (!rectInRect(self.xl, self.yt, self.ww, self.hh, 0, 0, g.rm_w, g.rm_h)) {
    self.destroy()
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }

  // ------------------------------------------------------------------------------------
  // PC interaction --------------------------------------------------------------
  update_body_hb(self)

  if (_x_change !== 0 && hINh(P.csLft1Y, P.csLft2Y - P.csLft1Y, self.BodyHB_yt, self.BodyHB_h)) {
    let _pc_x_change = 0
    updateCSPoints(P)

    if (gmBool(_x_change)) {
      if (
        pointInRect(P.csLft1X, P.csLft1Y, self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h) ||
        pointInRect(P.csLft2X, P.csLft2Y, self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h)
      ) {
        _pc_x_change = self.attack_x_head_x - P.csLft1X
      }
    } else {
      if (
        pointInRect(P.csRgt1X, P.csRgt1Y, self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h) ||
        pointInRect(P.csRgt2X, P.csRgt2Y, self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h)
      ) {
        _pc_x_change = self.attack_x_head_x - P.csRgt1X
      }
    }

    if (_pc_x_change !== 0) {
      set_xy(P, P.x + _pc_x_change, P.y) // push PC
      P.x_change += _pc_x_change
      updateCSPoints(P)

      // Smash PC --------------------------------
      if (gmBool(f.hp) && !gmBool(P.iframes_timer)) {
        let _qualifies = false
        const _1X = gmBool(_pc_x_change) ? P.csRgt1X : P.csLft1X
        const _1Y = gmBool(_pc_x_change) ? P.csRgt1Y : P.csLft1Y
        const _2X = gmBool(_pc_x_change) ? P.csRgt2X : P.csLft2X
        const _2Y = gmBool(_pc_x_change) ? P.csRgt2Y : P.csLft2Y

        if (gmBool(collide_solid_grid(_1X, _1Y)) || gmBool(collide_solid_grid(_2X, _2Y))) {
          _qualifies = true
        } else {
          for (let _i = g.dl_solid_inst.size - 1; _i >= 0; _i--) {
            const _si = g.dl_solid_inst.get(_i) as GameObject | undefined
            if (_si !== undefined && instanceExists(_si) && gmBool(_si.state) && _si !== self) {
              if (
                pointInRect(_1X, _1Y, _si.BodyHB_xl, _si.BodyHB_yt, _si.BodyHB_w, _si.BodyHB_h) ||
                pointInRect(_2X, _2Y, _si.BodyHB_xl, _si.BodyHB_yt, _si.BodyHB_w, _si.BodyHB_h)
              ) {
                _qualifies = true
                break //_i
              }
            }
          }
        }

        // Smash PC
        if (_qualifies) {
          let _damage = get_stat_max(STR_Heart)
          // TODO: `solid_clip_correction` will also put pc above trap. Should that qualify for half damage?
          if (P.cp1Y - self.yt < 4) _damage = _damage >> 1 // Because damage boost will put pc above of trap
          PC_take_damage(self, _damage)
        }
      }
    }
  }

  if (
    _y_change !== 0 &&
    gmBool(f.hp) &&
    !gmBool(P.iframes_timer) &&
    wINw(P.csTop1X, P.csTop2X - P.csTop1X, self.BodyHB_xl, self.BodyHB_w)
  ) {
    if (
      (inRange(P.csTop1Y, self.BodyHB_yt, self.BodyHB_yt + self.BodyHB_h - 1) && P.cs & 0x4) ||
      (inRange(P.csBtm1Y, self.BodyHB_yt, self.BodyHB_yt + self.BodyHB_h - 1) && P.cs & 0x8)
    ) {
      // Smash PC
      let _damage = get_stat_max(STR_Heart)
      if (
        sign_(P.x < self.x) === P.xScale && // if knockback will be AWAY from trap
        Math.abs(P.x - self.x) >= (self.BodyHB_w >> 1) + (((P.csTop2X - P.csTop1X) >> 1) - 4)
      ) {
        _damage = _damage >> 1 // Because damage boost will put pc outside of trap
      }
      PC_take_damage(self, _damage)
    }
  }

  // ------------------------------------------------------------------------------------
  if (_collided_solid) {
    aud_play_combo1(0xf)
    g.ScreenShake_timer = 0x10
    if (self.attack_x_direction !== 0) g.ScreenShake_strength_x = 1
    else g.ScreenShake_strength_y = 1

    self.sub_state = self.sub_state_DONE
  }
}

/** `SmasherTrap01_udp()` */
export function SmasherTrap01_udp(self: SmasherTrap01): void {
  self.can_draw_self = true

  self.draw_xoff = 0
  self.draw_yoff = 0

  if (self.Trigger_state === 0) self.Trigger_draw_yoff = self.Trigger_OFFSET1
  else self.Trigger_draw_yoff = 0

  switch (self.sub_state) {
    case self.sub_state_IDLE:
      break
    case self.sub_state_DELAY:
      break
    case self.sub_state_TELL: {
      if (!(self.TELL_timer & 0x3)) {
        if (self.attack_x_direction !== 0) self.draw_xoff = sign_(self.TELL_timer & 0x8)
        if (self.attack_y_direction !== 0) self.draw_yoff = sign_(self.TELL_timer & 0x8)
      }
      break
    }
    case self.sub_state_ATTACK:
      break
    case self.sub_state_DONE:
      break
  }
}

/** `SmasherTrap01_draw()` — ZALiA caches the trigger plate and the wall block in surfaces. */
export function SmasherTrap01_draw(self: SmasherTrap01): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const _depth_prev = drawState.depth
  drawState.depth = self.depth

  if (self.Trigger_type === 2 && self.Trigger_dg_tsrc !== undefined) {
    const _dg = self.Trigger_dg_tsrc
    if (!surface_exists(self.Trigger_surf)) {
      const _CLMS = _dg.width
      const _ROWS = _dg.height

      if (self.Trigger_surf === -1) {
        // First creation of surface. Remove tiles under Trigger
        for (let _i = 0; _i < _CLMS; _i++) {
          for (let _j = 0; _j < _ROWS; _j++) {
            const _x = self.Trigger_xl + (_i << 3)
            const _y = self.Trigger_yt + (_j << 3)
            if (_x >= 0 && _x < g.rm_w && _y >= 0 && _y < g.rm_h) {
              tile_layer_delete_at(self.Trigger_depth, _x, _y)
            }
          }
        }
      }

      // Create surface
      const _surf = surface_create(_CLMS << 3, _ROWS << 3)
      self.Trigger_surf = _surf
      surface_set_target(_surf)
      for (let _i = 0; _i < _CLMS; _i++) {
        for (let _j = 0; _j < _ROWS; _j++) {
          const _cell = _dg.get(_i, _j) ?? 0
          const _ts = g.dl_tileset.get((_cell >> 8) & 0xff) as string
          const _tsrc = (_cell >> 0) & 0xff
          draw_background_part(
            _ts,
            ((_tsrc >> 0) & 0xf) << 3,
            ((_tsrc >> 4) & 0xf) << 3,
            8,
            8,
            _i << 3,
            _j << 3,
          )
        }
      }
      surface_reset_target()
    }

    // p.dg_depth_pi[#idx,1] is the pi the trigger's tile layer currently uses.
    // FIDELITY: fall back to the instance's own pi when the depth was not in g.dl_TILE_DEPTHS.
    const _pi =
      self.Trigger_dg_depth_pi_idx !== -1
        ? (p.dg_depth_pi.get(self.Trigger_dg_depth_pi_idx, 1) ?? self.palidx)
        : self.palidx
    pal_swap_set(_pi)
    draw_surface(self.Trigger_surf, self.Trigger_xl, self.Trigger_yt + self.Trigger_draw_yoff)
    pal_swap_reset()
  }

  if (self.ver === 2) {
    if (self.Wall_dg_tsrc !== undefined) {
      const _dg = self.Wall_dg_tsrc
      if (!surface_exists(self.Wall_surf)) {
        const _CLMS = _dg.width
        const _ROWS = _dg.height

        if (self.Wall_surf === -1) {
          // First creation of surface. Remove wall tiles under trap
          for (let _i = 0; _i < _CLMS; _i++) {
            for (let _j = 0; _j < _ROWS; _j++) {
              const _x = self.spawn_xl + (_i << 3)
              const _y = self.spawn_yt + (_j << 3)
              if (_x >= 0 && _x < g.rm_w && _y >= 0 && _y < g.rm_h) {
                tile_layer_delete_at(self.FGWALL_depth, _x, _y)
              }
            }
          }
        }

        // Create surface
        const _surf = surface_create(_CLMS << 3, _ROWS << 3)
        self.Wall_surf = _surf
        surface_set_target(_surf)
        for (let _i = 0; _i < _CLMS; _i++) {
          for (let _j = 0; _j < _ROWS; _j++) {
            const _cell = _dg.get(_i, _j) ?? 0
            const _ts = g.dl_tileset.get((_cell >> 8) & 0xff) as string
            const _tsrc = (_cell >> 0) & 0xff
            draw_background_part(
              _ts,
              ((_tsrc >> 0) & 0xf) << 3,
              ((_tsrc >> 4) & 0xf) << 3,
              8,
              8,
              _i << 3,
              _j << 3,
            )
          }
        }
        surface_reset_target()
      }

      pal_swap_set(self.palidx)
      draw_surface(self.Wall_surf, self.drawX - self.ww_, self.drawY - self.hh_)
      pal_swap_reset()
    }
  } else {
    GO_draw_sprite(self, self.sprite, self.palidx)
  }

  drawState.depth = _depth_prev
}

/** `registerSmasherTrap()` — object classes + the `data_go_scr` slots of GameObjectData_Create.gml. */
export function registerSmasherTrap(): void {
  registerObject('SmasherTrapManager', SmasherTrapManager)
  registerObject('SmasherTrap01', SmasherTrap01)
  registerScripts({
    SmasherTrapManager_init1,
    SmasherTrapManager_init2,
    SmasherTrapManager_update,
    SmasherTrapManager_udp,
    SmasherTrapManager_draw,
    SmasherTrap01_init1,
    SmasherTrap01_init2,
    SmasherTrap01_update,
    SmasherTrap01_udp,
    SmasherTrap01_draw,
    // Not a `data_go_scr` slot; called from SmasherTrap01_update.
    // (`SmasherTrap01_init3` takes 9 arguments, so it is not registerable as a script slot.)
    SmasherTrap01_update_ATTACK,
  })
}
