/**
 * ZALiA `other` IDE folder: debug print, `val`, string helpers, ancestry checks, misc.
 * Dead scripts (`is_vals`, `strL`, `string_delete_all`, `hexStr`, `obj_name`, `get_random_lorem_words`,
 * `ease_in`) were dropped.
 */
import { HEX_CHARS } from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { byteToInt } from '../../nes/math8'
import type { Instance } from '../../runtime/instance'
import { type ObjectClass, objectClass } from './registry'

export { hasObjectClass, objectClass, registerObjectClass } from './registry'

/** `sdm(string)` — Show Debug Message. Routed through a replaceable sink (silent by default). */
export let debugSink: (msg: string) => void = () => {}
export function setDebugSink(fn: (msg: string) => void): void {
  debugSink = fn
}
export function sdm(msg: string): void {
  debugSink(msg)
}

/**
 * `val(value, *value if undefined)` — 0, or the default when one is *supplied*.
 *
 * GML branches on `argument_count > 1`, so `val(x, undefined)` returns `undefined`, not 0. Testing the
 * default for `undefined` instead turned every "no value here" read into a 0 (`Overworld_Room_Start`
 * recorded a bogus `_OWRC = 0` for the 162 scenes that have none).
 */
export function val<T>(v: T | undefined): T | 0
export function val<T, D>(v: T | undefined, dflt: D): T | D
export function val<T, D>(v: T | undefined, ...dflt: [D?]): T | D | 0 {
  if (v !== undefined) return v
  if (dflt.length > 0) return dflt[0] as D
  return 0
}

/** `hex_str(number, *char count)` */
export const hex_str = hexStr

/** `strR(str, pos)` — substring from 1-based `pos` to the end. */
export function strR(str: string, pos: number): string {
  return str.substring(pos - 1)
}

/** `strReplaceAt(str, position, delete count, insert str)` — 1-based, clamps like the GML. */
export function strReplaceAt(str: string, position: number, deleteCount: number, insert: string): string {
  const len = str.length
  if (!len) return str
  const pos = Math.min(position, len)
  const del = Math.min(deleteCount, len + 1 - pos)
  const deleted = str.slice(0, pos - 1) + str.slice(pos - 1 + del)
  return deleted.slice(0, pos - 1) + insert + deleted.slice(pos - 1)
}

/**
 * `str_hex(str of bytes, *byte index)` — parse a hex string as a number; non-hex chars count as 0.
 * Without an index the last 8 chars are used; with an index the string is treated as an array of
 * 2-char bytes and only that byte is returned.
 */
export function str_hex(str: unknown, byteIndex?: number): number {
  if (typeof str !== 'string') return 0
  let s = str
  let len = s.length
  if (!len) return 0
  if (byteIndex !== undefined) {
    if (len & 1) {
      s = `0${s}`
      len++
    }
    const idx = Math.max(0, Math.min(byteIndex, (len >> 1) - 1))
    s = s.substr(idx << 1, 2)
    len = 2
  } else if (len > 8) {
    s = s.substr(len - 8, 8)
    len = 8
  }
  let out = 0
  for (let i = 0; i < len; i++) {
    out = out << 4
    out |= Math.max(0, HEX_CHARS.indexOf(s[i] as string))
  }
  return out >>> 0
}

/** `is_ancestor(child, parent)` — child is the class or a subclass (instances accepted). */
export function is_ancestor(child: Instance | ObjectClass, parent: ObjectClass | string): boolean {
  const p = typeof parent === 'string' ? objectClass(parent) : parent
  if (typeof child === 'function')
    return child === p || Object.prototype.isPrototypeOf.call(p.prototype, child.prototype)
  return child instanceof p
}

/** `is_ancestor_(child, parent, *parent..)` — any of the parents. */
export function is_ancestor_(child: Instance | ObjectClass, ...parents: (ObjectClass | string)[]): boolean {
  return parents.some((p) => is_ancestor(child, p))
}

/** `simulate_position_change(speed, speed_sub)` — pixels x/y will change on the next update. */
export function simulate_position_change(speed: number, speedSub: number): number {
  let s = speed & 0xff
  const carry = ((s & 0xf) << 4) + speedSub > 0xff ? 1 : 0
  if (s & 0x80) s = (s >> 4) | 0xf0
  else s = s >> 4
  return byteToInt((s + carry) & 0xff)
}

/** `ease_in_out(start, change, time, duration)` — quadratic ease (Code Workshop). */
export function ease_in_out(start: number, distance: number, time: number, duration: number): number {
  let t = time / (duration / 2)
  if (t < 1) return (distance / 2) * t * t + start
  t--
  return (-distance / 2) * (t * (t - 2) - 1) + start
}

export interface LoremEnv {
  /** `g.dl_LOREM` */
  words: readonly string[]
  /** `g.DIALOGUE_WINDOW.MAX_LINES`, `.CHAR_PER_LINE_MAX` */
  maxLines: number
  charPerLineMax: number
  /** `g.CHAR_END_LINE1` */
  endLine: string
  /** ds_list_shuffle source of randomness (0..1) */
  random: () => number
}

/** `get_random_lorem_dlg(lines, *single word per line)` — dev/test dialogue filler. */
export function get_random_lorem_dlg(env: LoremEnv, lines: number, single = false): string {
  const n = Math.max(1, Math.min(lines, env.maxLines))
  const pool = [...env.words]
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(env.random() * (i + 1))
    ;[pool[i], pool[j]] = [pool[j] as string, pool[i] as string]
  }
  let idx = 0
  let dlg = ''
  for (let i = 0; i < n; i++) {
    let str = ''
    if (single) str = pool[i] ?? ''
    else {
      for (;;) {
        str += pool[idx++] ?? ''
        if ((str + (pool[idx] ?? '')).length + 1 > env.charPerLineMax) break
        str += ' '
      }
    }
    dlg += str
    if (i + 1 < n) dlg += env.endLine
  }
  return dlg
}

export interface SpellSequenceSelf {
  SpellHist_COUNT1: number
  SpellSeq_COUNT: number
}

/** `spell_sequence_is_complete(str spell bits)` — last N entries of `g.dl_spell_history` match the sequence. */
export function spell_sequence_is_complete(
  self: SpellSequenceSelf,
  spellHistory: readonly number[],
  seq: string,
): boolean {
  const count1 = spellHistory.length
  if (count1 - self.SpellHist_COUNT1 < self.SpellSeq_COUNT) return false
  const idx = count1 - self.SpellSeq_COUNT
  for (let i = 0; i < self.SpellSeq_COUNT; i++) {
    if (str_hex(seq, i) !== spellHistory[idx + i]) return false
  }
  return true
}
