/** Megmat (`MegmA`) — the hopper. Ported from `Megmat_init2/update/udp.gml`. */
import { CS_BD1 } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { Enemy } from '../../../../classes'
import { dir_to_pc } from '../../../../go/misc'
import { set_xy, updateX, updateY2 } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'
import { rand } from '../iron_knuckle/common'

export class MegmA extends Enemy {
  readonly objectName = 'MegmA' as const
}

/** `Megmat_init2()` */
export function Megmat_init2(self: MegmA): void {
  self.dl_sprites?.set(1, 'spr_Megmat2')
  self.dl_sprites?.set(0, 'spr_Megmat1')
  GO_init_palidx(self, G.PI_MOB_BLU)
  self.uses_vspd_sub = false
}

/** `Megmat_update()` */
export function Megmat_update(self: MegmA): void {
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // 987E: JSR DA02, 9881
  if (self.cs & 0x8) {
    self.vspd = 0
    set_xy(self, self.x, self.y + 1)
  }
  // 988C
  if (self.cs & 0x3) {
    self.facing_dir = -self.facing_dir
    self.hspd = -self.hspd & 0xff
  }
  updateX(self)
  // 9898
  if (self.cs & 0x4) {
    self.facing_dir = dir_to_pc(self)
    self.hspd = (0x8 * self.facing_dir) & 0xff
    self.vspd = 0xfb + (rand(self) & 0x1)
  }
  // 98B2
  updateY2(self, 0x30, 0x30)
  GO_update_cs(self)
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
}

/** `Megmat_udp()` */
export function Megmat_udp(self: MegmA): void {
  self.can_draw_self = true
  if ((self.vspd - 2) & 0xff & 0x80) GO_set_sprite(self, self.dl_sprites?.get(1) as string)
  else GO_set_sprite(self, self.dl_sprites?.get(0) as string)
}

export function registerMegmat(): void {
  registerObject('MegmA', MegmA)
  registerScripts({ Megmat_init2, Megmat_update, Megmat_udp })
}
registerMegmat()
