/**
 * Item placement primitives — `Rando_set_data_1a.gml`, `Rando_set_loc_num_options.gml`,
 * `Rando_place_keys.gml`, `Rando_place_container_pieces.gml` and the four `Rando_sweep_*.gml` scripts.
 *
 * `Rando_set_data_1a` is the only writer of the randomized item placement into `dm_save_data`; everything
 * else decides *which* location a given item goes to. `Rando_sweep_*` re-run the reachability logic after
 * each placement so spells/skills/keys that just became reachable are collected before the next item.
 *
 * Dropped as dead code (noted per PORTING.md rule 8):
 * - `Rando_set_data_1a.gml:~126` `_OBJ_NAME` / `_OBJ` / `_ITEM_BIT` are computed from `g.dm_ITEM` and then
 *   never read anywhere in the script (leftover of an older placement path).
 * - `Rando_set_loc_num_options.gml:119-136` (an alternative `switch(ItemLocations_RANDO_METHOD)` weighting)
 *   and `:152-277` (two earlier revisions of the whole script) are `/* *​/` blocks.
 * - `Rando_place_keys.gml:33-36` a commented-out `dl_locations_remaining` delete inside the non-rando path.
 */
import {
  dk_ChosenHintDialogue,
  STR_1UP,
  STR_ALLKEY,
  STR_BRACELET,
  STR_Category,
  STR_Count,
  STR_Datakey,
  STR_Description,
  STR_Dialogue,
  STR_FLUTE,
  STR_HEART,
  STR_Hint,
  STR_ID,
  STR_Item,
  STR_KEY,
  STR_Location,
  STR_MAGIC,
  STR_MASK,
  STR_Name,
  STR_Num,
  STR_Obscure,
  STR_PBAG,
  STR_Rando,
  STR_Randomized,
  STR_Rm,
  STR_Scene,
  STR_Spawn,
  STR_Spell,
  STR_Town,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { G, g, world } from '../../runtime/world'
import { sdm, val } from '../other/index'
import {
  clamp,
  debugData,
  debugLine,
  ds_list_copy,
  ds_list_remove,
  ds_list_shuffle,
  inList,
  isVal,
  string_delete,
  string_insert,
  string_letters,
  string_pos,
  string_repeat,
  ZELDA_HINT_OPTIONS,
} from './helpers'
import { Rando_is_qual_hint_location } from './hints'
import { Rando_is_qual_location } from './qualLocation'
import type { Rando } from './Rando'
import { Rando_is_spell } from './reach'

const locKey = (locNum: number): string => hexStr(locNum)

/**
 * `Rando_set_data_1a(loc num, item id)` — record `item id` at `loc num`.
 * @returns true when the item was placed (false when it had already been placed elsewhere).
 */
export function Rando_set_data_1a(self: Rando, LOC_NUM: number, itemId: string | number): boolean {
  const _ITEM_ID = String(itemId)

  let _ITEM_TYPE = _ITEM_ID
  if (string_pos(STR_HEART, _ITEM_ID)) _ITEM_TYPE = STR_HEART
  else if (string_pos(STR_MAGIC, _ITEM_ID)) _ITEM_TYPE = STR_MAGIC
  else if (string_pos(STR_1UP, _ITEM_ID)) _ITEM_TYPE = STR_1UP
  else if (string_pos(STR_PBAG, _ITEM_ID)) _ITEM_TYPE = STR_PBAG
  else if (string_pos(STR_KEY, _ITEM_ID)) _ITEM_TYPE = STR_KEY

  let _is_already_placed = false

  const _IS_SPELL = Rando_is_spell(_ITEM_ID)
  if (_IS_SPELL) {
    if (!inList(self.dl_spells_placed, _ITEM_ID)) self.dl_spells_placed.add(_ITEM_ID)
    else _is_already_placed = true
  } else if (string_pos(STR_KEY, _ITEM_ID)) {
    if (!inList(self.dl_keys_placed, _ITEM_ID)) self.dl_keys_placed.add(_ITEM_ID)
    else _is_already_placed = true
  } else {
    if (!inList(self.dl_items_placed, _ITEM_ID)) self.dl_items_placed.add(_ITEM_ID)
    else _is_already_placed = true

    if (!_is_already_placed) {
      switch (_ITEM_ID) {
        case STR_FLUTE:
          self.FLUTE_LOC_NUM = LOC_NUM
          break
        case STR_ALLKEY:
          if (self.CONTROL_ALLKEY === 1) self.ALLKEY_LOC_NUM = LOC_NUM
          break
      }
    }
  }

  if (_is_already_placed) {
    sdm(`*** ${_ITEM_ID} HAS ALREADY BEEN PLACED!! ***`)
    return false
  }

  if (_ITEM_TYPE === STR_HEART && !inList(self.dl_placed_containers_hp, _ITEM_ID)) {
    self.dl_placed_containers_hp.add(_ITEM_ID)
  }
  if (_ITEM_TYPE === STR_MAGIC && !inList(self.dl_placed_containers_mp, _ITEM_ID)) {
    self.dl_placed_containers_mp.add(_ITEM_ID)
  }

  const _DATAKEY = STR_Location + hexStr(LOC_NUM)
  const _SPAWN_DATAKEY = String(self.dm_LOCATIONS.val(locKey(LOC_NUM) + STR_Spawn + STR_Datakey, 'undefined'))
  const _RM_NAME = String(self.dm_LOCATIONS.val(locKey(LOC_NUM) + STR_Rm + STR_Name, 'undefined'))

  self.dm_save_data.set(_DATAKEY + STR_Spawn + STR_Datakey, _SPAWN_DATAKEY)
  self.dm_save_data.set(_DATAKEY + STR_Item + STR_ID + STR_Randomized, _ITEM_ID)
  self.dm_save_data.set(_SPAWN_DATAKEY + STR_Item + STR_ID + STR_Randomized, _ITEM_ID)
  self.dm_save_data.set(_ITEM_ID + STR_Location + STR_Num + STR_Randomized, LOC_NUM)

  if (_IS_SPELL) {
    const _TOWN_NAME = String(val(g.dm_rm.get(_RM_NAME + STR_Town + STR_Name)))
    if (inList(self.dl_TOWN_NAMES, _TOWN_NAME)) {
      self.dm_save_data.set(
        _DATAKEY + STR_Spell,
        String(self.dm_save_data.val(_TOWN_NAME + STR_Spell, 'undefined')),
      )
      self.dm_save_data.set(_ITEM_ID + STR_Location, _TOWN_NAME)
      self.dm_save_data.set(_ITEM_ID + STR_Town + STR_Name, _TOWN_NAME)
      self.dm_save_data.set(_DATAKEY + STR_Town + STR_Name, _TOWN_NAME)
    }
    debugLine(self, '')
    debugLine(self, `SPELL  ${_ITEM_ID}  PLACED!`)
    debugLine(self, '')
    return true
  }

  self.placement_num++

  // The spoiler-log line. `_CAN_PRINT_DEBUG` only gates the console print; the line always goes to
  // `dm_debug_data`, which `Rando_randomize_file` writes to `SaveFile_N_Rando_Spoiler.txt`.
  const _CAN_PRINT_DEBUG = _ITEM_TYPE === STR_KEY || Boolean(self.KeyLocations_WILL_RANDOMIZE)
  if (self.DEBUG) {
    let debug_str = `$${hexStr(self.placement_num)}. `
    debug_str += `loc_num $${hexStr(LOC_NUM)}: `
    debug_str += '#('
    debug_str += _ITEM_ID
    debug_str += ')#'
    debug_str += string_repeat(' ', Math.max(0, 0xa - _ITEM_ID.length))
    debug_str += '.  '
    debug_str += _RM_NAME
    debug_str += ` - ${String(self.dm_LOCATIONS.val(locKey(LOC_NUM) + STR_Description, 'location?'))}`
    if (_CAN_PRINT_DEBUG) sdm(debug_str)
    debugData(self, debug_str)
  }

  // ---- hints (RandoHints_VER 2): give this item's hint to a location the player can already reach ----
  if (G.RandoHints_VER === 2 && inList(self.dl_hint_items, _ITEM_ID)) {
    if (!self.KeyLocations_WILL_RANDOMIZE || _ITEM_ID !== STR_ALLKEY) {
      if (self.QUEST_NUM === 2 || _ITEM_ID !== STR_MASK) {
        if (
          self.ItemLocations_ZELDA_HINT === ZELDA_HINT_OPTIONS.NONE ||
          self.ItemLocations_ZELDA_HINT === ZELDA_HINT_OPTIONS.JUMP ||
          (self.ItemLocations_ZELDA_HINT === ZELDA_HINT_OPTIONS.FLUTE && _ITEM_ID !== STR_FLUTE) ||
          (self.ItemLocations_ZELDA_HINT === ZELDA_HINT_OPTIONS.ALLKEY && _ITEM_ID !== STR_ALLKEY)
        ) {
          const _HINT_LOCATION_COUNT = self.dl_hint_loc_nums_shuffled.size
          if (_HINT_LOCATION_COUNT) {
            let _hint_was_set = false
            for (let _i = 0; _i < _HINT_LOCATION_COUNT; _i++) {
              const _hint_num = self.dl_hint_loc_nums_shuffled.get(_i) as number
              const _hint_scene = g.dm_RandoHints.get(hexStr(_hint_num) + STR_Rm + STR_Name)
              const _scene_hint_num = g.dm_RandoHints.get(hexStr(_hint_num) + STR_Scene + STR_Hint + STR_Num)
              // datakey for the NPC's normal (non-rando) dialogue
              const _normal_dialogue_dk = g.dm_RandoHints.get(hexStr(_hint_num) + STR_Dialogue + STR_Datakey)
              let _hint_dialogue = self.dm_LOCATIONS.get(locKey(LOC_NUM) + dk_ChosenHintDialogue)
              if (
                _hint_scene !== undefined &&
                _scene_hint_num !== undefined &&
                _normal_dialogue_dk !== undefined &&
                _hint_dialogue !== undefined
              ) {
                // Remove `_ITEM_ID` from `dl_items_placed` first, otherwise `Rando_is_qual_hint_location()`
                // could lock the hint behind the very item it hints at.
                ds_list_remove(self.dl_items_placed, _ITEM_ID)

                if (Rando_is_qual_hint_location(self, String(_hint_scene), _scene_hint_num as number)) {
                  // "&" marks where the item name goes
                  const _pos = string_pos('&', String(_hint_dialogue))
                  if (_pos) {
                    const _val = string_letters(_ITEM_ID).toUpperCase()
                    _hint_dialogue = string_delete(String(_hint_dialogue), _pos, 1)
                    _hint_dialogue = string_insert(_val, String(_hint_dialogue), _pos)
                  }

                  const _count = Number(self.dm_save_data.val(STR_Rando + STR_Hint + STR_Count)) + 1
                  self.dm_save_data.set(STR_Rando + STR_Hint + STR_Count, _count)

                  const dk = STR_Rando + STR_Hint + hexStr(_count)
                  self.dm_save_data.set(dk + STR_Dialogue + STR_Datakey, String(_normal_dialogue_dk))
                  self.dm_save_data.set(dk + STR_Dialogue, String(_hint_dialogue))
                  self.dm_save_data.set(dk + STR_Item, _ITEM_ID)
                  self.dm_save_data.set(
                    STR_Rando + STR_Hint + String(_normal_dialogue_dk) + STR_Hint + STR_Num,
                    _count,
                  )
                  self.dm_save_data.set(
                    STR_Rando + STR_Hint + String(_normal_dialogue_dk),
                    String(_hint_dialogue),
                  )

                  _hint_was_set = true
                  self.dl_hint_loc_nums_shuffled.delete(_i)

                  let debug_str = _ITEM_ID + string_repeat(' ', STR_BRACELET.length - _ITEM_ID.length)
                  debug_str += ` hint dialogue '${String(_hint_dialogue)}' set to datakey ${String(
                    _normal_dialogue_dk,
                  )}. Hint location id: ${String(_hint_scene)}${hexStr(_scene_hint_num as number)}`
                  debugLine(self, debug_str)
                  debugLine(self, '')
                }

                // Add `_ITEM_ID` back to `dl_items_placed`
                if (!inList(self.dl_items_placed, _ITEM_ID)) self.dl_items_placed.add(_ITEM_ID)

                if (_hint_was_set) break
              }
            }

            /* If somehow there was no qualified hint location for the item, should an unqualified one be
               used? The player could still reach the hint if they break logic. — ZALiA leaves it unhinted. */
            if (!_hint_was_set) {
              sdm('')
              sdm(`!!! WARNING !!!  [${_ITEM_ID}]  DID NOT GET A HINT !!!`)
              sdm('')
            }
          }
        }
      }
    }
  }

  if (self.DEBUG && self.DEBUG_extra_line1) {
    const _count = self.dl_items_placed.size + self.dl_keys_placed.size
    if (_count && !(_count & 0x3)) {
      if (_CAN_PRINT_DEBUG) sdm('')
      debugData(self, '')
    }
  }

  // ---- ALLKEY follow-ups -----------------------------------------------------------------------
  if (
    self.CONTROL_ALLKEY === 2 &&
    self.ALLKEY_LOC_NUM &&
    !self.KeyLocations_WILL_RANDOMIZE &&
    _ITEM_ID !== STR_ALLKEY &&
    !inList(self.dl_items_placed, STR_ALLKEY)
  ) {
    const _loc_num = self.ALLKEY_LOC_NUM
    const _loc_id = String(self.dm_LOCATIONS.val(locKey(_loc_num) + STR_Location + STR_ID, 'undefined'))
    if (Rando_is_qual_location(self, _loc_id) && Rando_set_data_1a(self, _loc_num, STR_ALLKEY)) {
      ds_list_remove(self.dl_locations_remaining, _loc_num)
    }
  }

  if (
    self.KeyLocations_WILL_RANDOMIZE &&
    _ITEM_ID !== STR_ALLKEY &&
    !inList(self.dl_items_placed, STR_ALLKEY)
  ) {
    const _loc_num = Number(self.dm_LOCATIONS.val(STR_ALLKEY + STR_Location + STR_Num))
    const _loc_id = String(self.dm_LOCATIONS.val(locKey(_loc_num) + STR_Location + STR_ID, 'undefined'))
    if (Rando_is_qual_location(self, _loc_id)) Rando_set_data_1a(self, _loc_num, STR_ALLKEY)
  }

  // ---- the P6 falling key: whatever lands there must be reachable from the room it falls into ----
  if (
    self.KeyLocations_WILL_RANDOMIZE &&
    !self.FallingKey_item_placed &&
    self.FallingKey_LOC_NUM !== LOC_NUM &&
    self.FallingKey_ITEM_ID !== _ITEM_ID
  ) {
    let _FallingKey_item_id: string | undefined

    if (self.ItemLocations_INCLUDE_PBAG && world.irandom(1)) {
      for (let _i = self.dl_ItemPool_C.size - 1; _i >= 0; _i--) {
        const cand = self.dl_ItemPool_C.get(_i) as string
        if (inList(self.dl_PBAGS, cand)) {
          _FallingKey_item_id = cand
          break
        }
      }
    }

    // *** dl_remaining_keys has already been shuffled
    if (_FallingKey_item_id === undefined && self.dl_remaining_keys.size) {
      _FallingKey_item_id = self.dl_remaining_keys.get(0)
    }

    if (
      _FallingKey_item_id === undefined &&
      self.FallingKey_ITEM_ID !== undefined &&
      self.dl_remaining_keys.size &&
      inList(self.dl_remaining_keys, self.FallingKey_ITEM_ID)
    ) {
      _FallingKey_item_id = self.FallingKey_ITEM_ID
    }

    if (
      _FallingKey_item_id !== undefined &&
      Rando_is_qual_location(self, self.FallingKey_LOC_ID, _FallingKey_item_id) &&
      Rando_set_data_1a(self, self.FallingKey_LOC_NUM, _FallingKey_item_id)
    ) {
      self.FallingKey_item_placed = true
      ds_list_remove(self.dl_ItemPool_C, _FallingKey_item_id)
      ds_list_remove(self.dl_remaining_keys, _FallingKey_item_id)
    }
  }

  if (inList(self.dl_ItemPool_A, _ITEM_ID)) {
    ds_list_copy(self.dl_qualified_locations_old, self.dl_qualified_locations)
  }

  return true
}

/**
 * `Rando_set_loc_num_options(item id, *location decision method)` — fills `dl_qualified_locations`
 * (every remaining location this item may go to), `dl_loc_cats` and `dl_loc_num_options` (the weighted
 * draw pool the callers shuffle and take `[0]` from).
 *
 * Method 1: every qualified location is one option. Method 2 (the default): one option per location
 * *category*, so every region gets an even chance no matter how many rooms it has, with obscure
 * locations (obscurity 2/3) appended afterwards under their own `_Obscure<n>` pseudo-categories.
 */
export function Rando_set_loc_num_options(self: Rando, ITEM_ID: string, method = 2): void {
  const _METHOD = clamp(method, 1, 2)
  const _GIVE_NEW_LOC_HIGHER_CHANCE = inList(self.dl_ItemPool_A, ITEM_ID)

  self.dl_qualified_locations.clear() // Qualified locations for THIS ITEM ONLY
  self.dl_loc_cats.clear() // Location Categories
  self.dl_loc_num_options.clear()

  for (let _i = self.dl_locations_remaining.size - 1; _i >= 0; _i--) {
    const _loc_num = self.dl_locations_remaining.get(_i) as number
    const _loc_id = val(self.dm_LOCATIONS.get(locKey(_loc_num) + STR_Location + STR_ID))

    if (Rando_is_qual_location(self, String(_loc_id), ITEM_ID)) {
      // Need ITEM_ID here
      self.dl_qualified_locations.add(_loc_num)

      switch (_METHOD) {
        case 1:
          self.dl_loc_num_options.add(_loc_num)
          break

        case 2: {
          const _loc_cat = self.dm_LOCATIONS.get(locKey(_loc_num) + STR_Category)
          const _val = Number(self.dm_LOCATIONS.val(locKey(_loc_num) + STR_Obscure, -1))
          if (!isVal(_val, 2, 3)) {
            if (_loc_cat !== undefined && !inList(self.dl_loc_cats, String(_loc_cat))) {
              self.dl_loc_cats.add(String(_loc_cat))
              self.dl_loc_num_options.add(_loc_num)
            }
          }
          break
        }
      }
    }
  }

  if (_METHOD === 2) {
    for (let _i = self.dl_qualified_locations.size - 1; _i >= 0; _i--) {
      const _loc_num = self.dl_qualified_locations.get(_i) as number
      const _loc_cat = self.dm_LOCATIONS.get(locKey(_loc_num) + STR_Category)
      const _obscure = Number(self.dm_LOCATIONS.val(locKey(_loc_num) + STR_Obscure, -1))
      if (isVal(_obscure, 2, 3)) {
        const _val = STR_Obscure + hexStr(_obscure)
        if (
          _loc_cat !== undefined &&
          !inList(self.dl_loc_cats, String(_loc_cat)) &&
          !inList(self.dl_loc_cats, _val) &&
          !inList(self.dl_loc_num_options, _loc_num)
        ) {
          self.dl_loc_cats.add(_val)
          self.dl_loc_num_options.add(_loc_num)
        }
      }
    }
  }

  self.dl_qualified_locations_new.clear()
  if (self.dl_qualified_locations.size > self.dl_qualified_locations_old.size) {
    for (let _i = self.dl_qualified_locations.size - 1; _i >= 0; _i--) {
      const _loc_num = self.dl_qualified_locations.get(_i) as number
      if (!inList(self.dl_qualified_locations_old, _loc_num)) self.dl_qualified_locations_new.add(_loc_num)
    }
  }

  if (self.dl_loc_num_options.size) {
    const _dl_OPTIONS = [...self.dl_loc_num_options.items]
    self.dl_loc_num_options.clear()
    for (let _i = _dl_OPTIONS.length - 1; _i >= 0; _i--) {
      const _loc_num = _dl_OPTIONS[_i] as number
      const _val = Number(self.dm_LOCATIONS.val(locKey(_loc_num) + STR_Obscure, -1))

      let _count = 1
      if (self.ItemLocations_LIMIT_OBSCURE) {
        switch (_val) {
          case 2:
            _count = 3
            break
          case 3:
            _count = 1
            break
          default:
            _count =
              10 + (_GIVE_NEW_LOC_HIGHER_CHANCE && inList(self.dl_qualified_locations_new, _loc_num) ? 1 : 0)
            break
        }
      } else if (_GIVE_NEW_LOC_HIGHER_CHANCE) {
        _count = 10 + (inList(self.dl_qualified_locations_new, _loc_num) ? 1 : 0)
      }

      for (let _r = 0; _r < _count; _r++) self.dl_loc_num_options.add(_loc_num)
    }
  }
}

/** `Rando_sweep_spells()` — place every spell whose town has become reachable. */
export function Rando_sweep_spells(self: Rando): void {
  const _COUNT = self.dl_SPELLS.size
  for (let _i = 0; _i < _COUNT; _i++) {
    if (self.dl_spells_placed.size >= _COUNT) break

    const _spell_id = self.dl_SPELLS.get(_i) as string
    if (!inList(self.dl_spells_placed, _spell_id)) {
      const _loc_num = Number(self.dm_save_data.val(_spell_id + STR_Location + STR_Num))
      const _rm_name = String(self.dm_LOCATIONS.val(locKey(_loc_num) + STR_Rm + STR_Name, 'undefined'))
      const _loc_id = _rm_name + STR_Spell
      if (Rando_is_qual_location(self, _loc_id)) {
        Rando_set_data_1a(self, _loc_num, _spell_id)
      }
    }
  }
}

/** `Rando_sweep_skills()` — downthrust/upthrust become "placed" as soon as their town is reachable. */
export function Rando_sweep_skills(self: Rando): void {
  const _COUNT = self.dl_SKILLS.size
  for (let _i = 0; _i < _COUNT; _i++) {
    if (self.dl_skills_placed.size >= _COUNT) break

    const _skill = self.dl_SKILLS.get(_i) as string
    if (!inList(self.dl_skills_placed, _skill) && Rando_is_qual_location(self, _skill)) {
      self.dl_skills_placed.add(_skill)

      if (self.DEBUG) {
        debugLine(self, '')
        debugLine(self, `SKILL  '${_skill}'  PLACED!`)
        debugLine(self, '')
      }
    }
  }
}

/**
 * `Rando_sweep_keys(will add to save data)` — dead in ZALiA (no callers; `Rando_place_keys`'s else-branch
 * does the same work). Kept because it is the vanilla-key-locations sweep the sweep family implies.
 */
export function Rando_sweep_keys(self: Rando, WILL_ADD_TO_SAVE_DATA: boolean): void {
  const _COUNT = self.dl_KEYS.size
  for (let _i = 0; _i < _COUNT; _i++) {
    if (self.dl_keys_placed.size >= _COUNT) break

    const _item_id = self.dl_KEYS.get(_i) as string
    if (!inList(self.dl_keys_placed, _item_id)) {
      const _loc_num = Number(self.dm_LOCATIONS.val(_item_id + STR_Location + STR_Num))
      const _loc_id = String(self.dm_LOCATIONS.val(locKey(_loc_num) + STR_Location + STR_ID, 'undefined'))
      if (Rando_is_qual_location(self, _loc_id, _item_id)) {
        if (WILL_ADD_TO_SAVE_DATA) Rando_set_data_1a(self, _loc_num, _item_id)
        // This is temporary and only being done to check for progression
        else self.dl_keys_placed.add(_item_id)
      }
    }
  }
}

/** `Rando_sweep_combo(iterations)` */
export function Rando_sweep_combo(self: Rando, COUNT: number): void {
  for (let _i = 0; _i < COUNT; _i++) {
    Rando_sweep_spells(self)
    Rando_sweep_skills(self)
    Rando_place_keys(self, _i === 0 ? 1 : 0, true)
  }
}

/** `Rando_place_keys(number of keys to place, will add to save data)` */
export function Rando_place_keys(self: Rando, PLACEMENT_COUNT: number, WILL_ADD_TO_SAVE_DATA: boolean): void {
  if (self.KeyLocations_WILL_RANDOMIZE) {
    if (PLACEMENT_COUNT) {
      for (let _i = 0; _i < PLACEMENT_COUNT; _i++) {
        for (let _j = self.dl_remaining_keys.size - 1; _j >= 0; _j--) {
          const _item_id = self.dl_remaining_keys.get(_j) as string
          Rando_set_loc_num_options(self, _item_id)

          if (self.dl_loc_num_options.size) {
            ds_list_shuffle(self.dl_loc_num_options)
            const _loc_num = self.dl_loc_num_options.get(0) as number

            // returns true if it was able to place the item
            if (Rando_set_data_1a(self, _loc_num, _item_id)) {
              ds_list_remove(self.dl_remaining_keys, _item_id)
              ds_list_remove(self.dl_locations_remaining, _loc_num)

              if (!self.dl_remaining_keys.size || !self.dl_locations_remaining.size) {
                _i = PLACEMENT_COUNT
              }
              break // _j
            }
          }
        }
      }
    }
  } else {
    const _COUNT = self.dl_KEYS.size
    for (let _i = 0; _i < _COUNT; _i++) {
      if (self.dl_keys_placed.size >= _COUNT) break

      const _item_id = self.dl_KEYS.get(_i) as string
      if (!inList(self.dl_keys_placed, _item_id) && inList(self.dl_remaining_keys, _item_id)) {
        const _loc_num = Number(self.dm_LOCATIONS.val(_item_id + STR_Location + STR_Num))
        const _loc_id = String(self.dm_LOCATIONS.val(locKey(_loc_num) + STR_Location + STR_ID, 'undefined'))
        if (Rando_is_qual_location(self, _loc_id, _item_id)) {
          if (WILL_ADD_TO_SAVE_DATA) {
            if (Rando_set_data_1a(self, _loc_num, _item_id)) {
              ds_list_remove(self.dl_remaining_keys, _item_id)
              if (_item_id === self.FallingKey_ITEM_ID) self.FallingKey_item_placed = true
            }
          } else {
            // This is temporary and only being done to check for progression
            self.dl_keys_placed.add(_item_id)
          }
        }
      }
    }
  }
}

/** `Rando_place_container_pieces(heart piece count, magic piece count)` */
export function Rando_place_container_pieces(self: Rando, HEART_COUNT: number, MAGIC_COUNT: number): void {
  for (let _i = 0; _i < 2; _i++) {
    const _type = _i ? STR_MAGIC : STR_HEART
    const _count = _i ? MAGIC_COUNT : HEART_COUNT

    for (let _j = 0; _j < _count; _j++) {
      if (!self.dl_locations_remaining.size || !self.dl_ItemPool_C.size) {
        _i = 2
        break // _j
      }

      const _dl_remaining_items = [...self.dl_ItemPool_C.items]
      for (let _k = _dl_remaining_items.length - 1; _k >= 0; _k--) {
        const _item_id = _dl_remaining_items[_k] as string

        if (string_pos(_type, _item_id)) {
          // populates dl_qualified_locations, dl_loc_cats, dl_loc_num_options
          Rando_set_loc_num_options(self, _item_id, 1)
          if (self.dl_loc_num_options.size) {
            ds_list_shuffle(self.dl_loc_num_options)
            const _loc_num = self.dl_loc_num_options.get(0) as number

            if (Rando_set_data_1a(self, _loc_num, _item_id)) {
              // if item got placed
              ds_list_remove(self.dl_ItemPool_C, _item_id)
              ds_list_remove(self.dl_locations_remaining, _loc_num)

              if (self.DEBUG) {
                const _rm_name = String(
                  self.dm_LOCATIONS.val(locKey(_loc_num) + STR_Rm + STR_Name, 'undefined'),
                )
                const _item_num = Number(
                  self.dm_LOCATIONS.val(locKey(_loc_num) + STR_Rm + STR_Location + STR_Num),
                )
                const _loc_id = _rm_name + hexStr(_item_num)
                if (!Rando_is_qual_location(self, _loc_id, _item_id)) {
                  sdm(`Rando_is_qual_location() THINKS YOU CANT GET TO:  ${_loc_id} FOR ITEM ${_item_id}`)
                }
              }
              break // _k
            }
          }
        }
      }
    }
  }
}
