/** Bago / Bago-Bago (ZALiA object `Bago01`, parent `Enemy`; the flying fish). `Bago_init2/update/udp.gml`. */
import { Area_WestA, CS_BD1, DEPTH_FLYER } from '@z2/data'
import { byte, gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { ocsH1 } from '../../../../../collision/ocs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { dir_to_pc, is_facing_pc } from '../../../../go/misc'
import { updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_depth_init } from '../../../../go/sprite'
import { solid_clip_correction } from '../../../../goa/movement'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_udp_1, GOB_update_2 } from '../../../GameObjectB'
import { projOf, rand } from '../ache/_shared'

export class Bago01 extends Enemy {
  readonly objectName = 'Bago01' as const
  HSPD1 = 0x10 // Normal
  HSPD2 = 0x20 // Launch speed only
  VSPD_GRAV = 1
  VSPD1 = 0xc1 // Bago spawner sets vspd using VSPD1
  has_landed = false
}

/** `Bago_init2()` */
export function Bago_init2(self: Bago01): void {
  switch (self.ver) {
    case 1:
      self.projectile_OBJ = 'Rock2'
      self.projectile_VER = 1
      break
    case 2:
      self.projectile_OBJ = 'Fireball1'
      self.projectile_VER = 1
      break
  }
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.dl_sprites?.add('spr_Bago1', 'spr_Bago2')
  GO_init_palidx(self, G.PI_MOB_BLU)
  GO_depth_init(self, DEPTH_FLYER)
  self.HSPD1 = 0x10 // Normal
  self.HSPD2 = 0x20 // Launch speed only
  self.hspd = self.HSPD1
  self.VSPD_GRAV = 1
  self.vspd_grav = self.VSPD_GRAV
  self.VSPD1 = 0xc0 + self.vspd_grav // Bago spawner sets vspd using VSPD1
  self.has_landed = false
  self.is_from_spawner = false
  if (g.area_name === Area_WestA) {
    self.ATTACK_LEVEL = 0x02
    self.attack_level = self.ATTACK_LEVEL
    self.XP_IDX = 0x03
    self.xp = g.dl_XP.get(self.XP_IDX) as number
  }
}

/** `Bago_update()` — D7E4 */
export function Bago_update(self: Bago01): void {
  if (!gmBool(self.stun_timer) && !ocsH1(self)) {
    // if NO w in ocs area
    self.state = 0
    return
  }
  if (gmBool(self.stun_timer)) {
    // DE40
    GOB_update_2(self)
    return
  }
  // D7E4, D7F1
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // D7F4
  let _carry: boolean | number = 0
  if (self.vspd < 0x80 && self.cs & 0x4) {
    // NOT moving up, btm on ground. D803
    if (!self.has_landed) {
      self.facing_dir = dir_to_pc(self)
      solid_clip_correction(self, true)
    }
    self.has_landed = true
    self.hspd = (self.HSPD1 * self.facing_dir) & 0xff // $10.  hspd $20 until first landing
    self.vspd = 0
  } else {
    // D812
    self.has_landed = false
    _carry = updateY(self) // vspd at launch is $C0
  }
  // D818
  if (!gmBool(self.timer) && byte(byte(self.yt) - byte(pc().yt) + +_carry) < 0x11) {
    // D825
    self.timer = 0x70 // $70: 1.867s
    if (rand(self) < 0x80 && is_facing_pc(self)) {
      const proj = GOC1_create(self.xl, self.yt, self.facing_dir, projOf(self), self.projectile_ver)
      GO_depth_init(proj, self.depth)
    }
  }
  // D832
  updateX(self)
  GO_update_cs(self)
  GOB_update_2(self)
}

/** `Bago_udp()` */
export function Bago_udp(self: Bago01): void {
  self.can_draw_self = true
  GOB_udp_1(self, 8)
}

registerObject('Bago01', Bago01)
registerScripts({ Bago_init2, Bago_update, Bago_udp })
