import type { SoundEntry } from '../assets/manifest'

/**
 * Music track resolution. ZALiA (`Audio_Create.gml:40-56`) loops tracks with an intro by playing an
 * `<name>_Intro` asset then a `<name>_Body` asset seamlessly (it worked around a GameMaker seek crackle by
 * shipping uncompressed audio; Web Audio schedules sample-accurately, so OGG is fine here).
 */
export interface MusicPlan {
  intro: string | null
  loop: string
}

export function resolveMusic(name: string, sounds: ReadonlyMap<string, SoundEntry>): MusicPlan | null {
  if (sounds.has(`${name}_Body`)) {
    return { intro: sounds.has(`${name}_Intro`) ? `${name}_Intro` : null, loop: `${name}_Body` }
  }
  if (name.endsWith('_Body') || name.endsWith('_Intro')) {
    const base = name.replace(/_(Body|Intro)$/, '')
    return resolveMusic(base, sounds)
  }
  if (sounds.has(name)) return { intro: null, loop: name }
  return null
}

export function soundIndex(sounds: readonly SoundEntry[]): Map<string, SoundEntry> {
  return new Map(sounds.map((s) => [s.name, s]))
}
