/**
 * Single registration entry point for every ported entity: gob1 enemies + bosses + kakusu/spawners/spike
 * traps/fire rope, gob2 interactables, hostile projectiles (goc), platforms (god), challenges (goe) and the
 * burnable manager. Importing the module registers all object classes and data-bound scripts (each leaf does
 * it at import time); `registerEntities()` re-runs the registration after a registry reset (tests) and
 * installs the cross-subsystem seams these ports own — the frame/boot/room hooks and `env.fn` entries that
 * `g_Step_A2`, `g_Room_Start`, `obj_start` and the collision layer call by GML name.
 *
 * The adapter must call `registerEntities()` once before `bootWorld()` (`GameScene.bootCore`, and
 * `smoke.test.ts`); without it `instance_create` throws for every leaf object and the entity hooks stay
 * `notPorted`. It cannot be called from `wire.ts`: `entities` → `obj_start/boot` → `wire` is a cycle, and
 * the module-eval-time registration below would hit `bootHooks` in its TDZ.
 */

import { world } from '../../runtime/world'
import { BurnableMgr_Create, BurnableMgr_Room_Start, BurnableMgr_update } from '../burnable/index'
import { setCollisionEnv } from '../collision/env'
import {
  GOB_body_collide_pc_body_1a,
  GOB_body_collide_pc_proj,
  GOB_body_collide_pc_sword,
} from '../collision/gob'
import { GOB_update_shield_offsets } from '../collision/hitbox'
import { hooks as fileDeps } from '../file/deps'
import { guiSeams } from '../gui/deps'
import { frameHooks } from '../hooks'
import { bootHooks } from '../obj_start/boot'
import { setOverworldDeps } from '../overworld/deps'
import { roomHooks } from '../rooms/roomChange'
import type { GameObject } from './classes'
import { deps as goDeps } from './deps'
import { pushback_pc_and_go, set_go_hspd_pushbback } from './go/pushback'
import { pcHooks } from './goa/deps'
import { damage_gob, gobCollision, pc_sword_colliding_solid_body } from './gob/GameObjectB'
import { Boss_play_battle_music } from './gob/gob1/boss/BossObject'
import { Ganon1 } from './gob/gob1/boss/ganon1'
import { registerBosses } from './gob/gob1/boss/registry'
import { ShadowBoss_udp } from './gob/gob1/boss/shadowBoss'
import { registerEnemies } from './gob/gob1/enemy/index'
import { registerSmasherTrap } from './gob/gob1/various/smasherTrap'
import type { TorchA } from './gob/gob2/classes'
import { crystal_is_placed } from './gob/gob2/crystalHolder'
import { Elevator_update_1 } from './gob/gob2/elevator'
import { item_acquired } from './gob/gob2/item'
import { Zelda_update_talk_sound } from './gob/gob2/npc'
import { registerGob2 } from './gob/gob2/registry'
import { Torch_ignite } from './gob/gob2/torch'
import { gobShield } from './goc/Projectile'
import { registerProjectileHostile } from './goc/projectile_hostile/index'
import { registerPlatforms } from './god/index'
import { registerChallenges } from './goe/index'
import { gofDeps } from './gof/deps'

export { registerBosses } from './gob/gob1/boss/registry'
export { registerEnemies } from './gob/gob1/enemy/index'
export { registerSmasherTrap } from './gob/gob1/various/smasherTrap'
export { registerGob2 } from './gob/gob2/registry'
export { registerProjectileHostile } from './goc/projectile_hostile/index'
export { registerPlatforms } from './god/index'
export { registerChallenges } from './goe/index'

/** Registers every entity class/script and installs the hooks the entity ports own. Idempotent. */
export function registerEntities(): void {
  registerEnemies()
  registerBosses()
  registerGob2()
  registerSmasherTrap()
  registerProjectileHostile()
  registerPlatforms()
  registerChallenges()
  installEntitySeams()
}

/** The hooks/seams other subsystems call by GML name and the entity ports fill in. */
export function installEntitySeams(): void {
  // gob2/item — `item_acquired(item)` (has the player got this item?)
  frameHooks.item_acquired = item_acquired
  goDeps.item_acquired = item_acquired
  fileDeps.item_acquired = item_acquired
  // …and the gui folder asks the same question when a shop/NPC line mentions an item the player may own.
  guiSeams.item_acquired = item_acquired
  // gob2/crystal_holder — `Overworld_Room_Start` asks it whether each palace crystal is placed
  setOverworldDeps({ item_acquired, crystal_is_placed })
  // gob2/torch — `with(GameObject_create(..., TorchA, ...)) Torch_ignite()`
  frameHooks.Torch_ignite = (self: unknown) => Torch_ignite(self as TorchA)
  // burnable — `BurnableMgr` singleton (Create / Room Start / per-frame update in g_Step_A2)
  bootHooks.BurnableMgr_Create = () => {
    BurnableMgr_Create()
  }
  roomHooks.roomStart.BurnableMgr = () => BurnableMgr_Room_Start()
  roomHooks.roomEnd.BurnableMgr = () => {}
  frameHooks.BurnableMgr_update = () => BurnableMgr_update()
  // goa — `PC_update_vertical` runs `with(colliding_elevator) Elevator_update_1()`. Unbound, the first
  // frame the player stood on an elevator threw, so palace vertical traversal was dead.
  pcHooks.Elevator_update_1 = (e) => Elevator_update_1(e as never)
  // gof — the cutscene folder calls back into the boss and NPC ports on the endgame path. Unbound, the
  // Great Palace's Shadow Link cutscene and the ending's Zelda dialogue both threw.
  gofDeps.ShadowBoss_udp = (self) => ShadowBoss_udp(self as never)
  gofDeps.Boss_play_battle_music = (self) => Boss_play_battle_music(self as never)
  gofDeps.Zelda_update_talk_sound = () => Zelda_update_talk_sound()
  // goc — `Projectile_collision_2a` asks the shield-carrying enemy to refresh its shield hitbox (E677).
  // Unbound, the first projectile to reach a shielded enemy threw.
  gobShield.GOB_update_shield_offsets = (self) => GOB_update_shield_offsets(self as never)
  // gob — the three `GOB_update_2a` body-collision checks (E48B / E677 / E4D9). They live in
  // `collision/gob.ts` because they read the PC; without this binding every enemy threw the moment the
  // player came within collision range.
  gobCollision.GOB_body_collide_pc_proj = (self) => GOB_body_collide_pc_proj(self as never)
  gobCollision.GOB_body_collide_pc_sword = (self) => GOB_body_collide_pc_sword(self as never)
  gobCollision.GOB_body_collide_pc_body_1a = (self) => GOB_body_collide_pc_body_1a(self as never)
  // gob — `pc_sword_colliding_solid_body()` (E654), called from the collision layer's sword/shield checks
  // `GO_update_cs.gml:77` `if (instance_exists(Ganon1) && !Ganon1.pc_is_inside)` — the PC's wall sensors
  // treat Ganon 1's body as solid geometry, over and above the `dl_solid_inst` entry his hitbox provides.
  setCollisionEnv({
    ganon1: () => {
      for (const i of world.instancesOf(Ganon1)) if (i.exists) return i as never
      return null
    },
  })
  setCollisionEnv({
    fn: {
      pc_sword_colliding_solid_body: (self) => pc_sword_colliding_solid_body(self as unknown as GameObject),
      // E726 / E4D9: the collision layer damages and pushes the entity it just hit. Unbound, every sword
      // connect and every enemy touch threw `collision env: <name> is not provided`.
      damage_gob: (self, damage, fromProjectile) =>
        damage_gob(self as unknown as GameObject, damage, fromProjectile),
      set_go_hspd_pushbback: (self, hspd) => set_go_hspd_pushbback(self as unknown as GameObject, hspd),
      pushback_pc_and_go: (self) => pushback_pc_and_go(self as unknown as GameObject),
    },
  })
}

registerEntities()
