/** TogglingPathDirectionA (4 doors) and TogglingPathDirectionB (elevator on a 4-point loop). */
import { DEPTH_BASE_HUD, STR_Count, STR_Direction, STR_Door } from '@z2/data'
import { hexStr } from '../../../nes/hexStr'
import { gmBool, isVal } from '../../../nes/math8'
import { g, input } from '../../../runtime/world'
import { cam_xl_min, cam_xr_max, cam_yb_max, cam_yt_min } from '../../collision/env'
import { pointInRect } from '../../collision/geometry'
import { drawPointCross } from '../../draw/index'
import { spriteInfo } from '../../graphics/sprites'
import { draw_sprite_rot } from '../../gui/deps'
import { bit_dir } from '../../math/index'
import { simulate_position_change } from '../../other/index'
import { draw_sprite_ } from '../../rooms/draw'
import type { GameObjectB } from '../classes'
import { GameObject_create } from '../create'
import { set_xlyt } from '../go/movement'
import { GO_init_palidx } from '../go/palette'
import { GameObjectB_step, update_EF11 } from '../gob/GameObjectB'
import { GG, gp, pc, pp } from '../pending'
import { sign_ } from '../util'
import { init_vars_Challenge_1a } from './challenge'
import type { ElevatorLike, TogglingPathDirectionA, TogglingPathDirectionB } from './classes'

const c_lime = 0x00ff00
const c_purple = 0x800080
const c_white = 0xffffff
const c_orange = 0xffa500

// ================================================================================================
// TogglingPathDirectionA
// ================================================================================================
export function TogglingPathDirectionA_init1(self: TogglingPathDirectionA): void {
  init_vars_Challenge_1a(self)
  self.SUB_STATE_1 = 1
  self.SUB_STATE_2 = 2
  self.SUB_STATE_3 = 3
  self.sub_state = self.SUB_STATE_1
  self.path_dir = 1 // 1: Forward, -1: Backward
  self.door_spr = gp().Doorway1_SPR
  self.PI_FRWD = GG().PI_MOB_RED // Red
  self.PI_BKWD = GG().PI_MOB_BLU // Blue
  if (gmBool(self.path_dir)) GO_init_palidx(self, self.PI_FRWD)
  else GO_init_palidx(self, self.PI_BKWD)
  GO_init_palidx(self, GG().PI_BGR2)
  self.DOOR_SPR_W = spriteInfo(self.door_spr).width
  self.DOOR_SPR_H = spriteInfo(self.door_spr).height
  self.DOOR_BGR_W = self.DOOR_SPR_W
  self.DOOR_BGR_H = self.DOOR_SPR_H
  self.ARROW_SPR1 = 'spr_arrow_2a_RWB'
  self.ARROW_SPR2 = 'spr_arrow_2a_BRW'
  self.arrow_pi = gmBool(self.path_dir) ? self.PI_FRWD : self.PI_BKWD
  self.dg_doors = new (
    self.dg_doors.constructor as new (
      w: number,
      h: number,
      f: number,
    ) => typeof self.dg_doors
  )(0, 3, 0)
  self.DOOR_HB_W = self.DOOR_SPR_W - 6
}
export function TogglingPathDirectionA_init2(self: TogglingPathDirectionA): void {
  const spawn = gp().dm_spawn
  const dk = self.dk_spawn ?? ''
  self.path_dir = spawn.get(dk + STR_Direction) as number
  const _count = spawn.get(dk + STR_Door + STR_Count) as number
  self.dg_doors = new (
    self.dg_doors.constructor as new (
      w: number,
      h: number,
      f: number,
    ) => typeof self.dg_doors
  )(_count, 3, 0)
  for (let i = 0; i < _count; i++) {
    // Set all closed. Will set as open when confirmed PC is NOT colliding w/ door hb.
    self.dg_doors.set(i, 0, 0) // state. 0: closed, 1: open
    // xy is at the bottom center of the door in case I change door dimensions in the future.
    self.dg_doors.set(i, 1, spawn.get(`${dk + STR_Door + hexStr(i + 1)}_x`) as number)
    self.dg_doors.set(i, 2, spawn.get(`${dk + STR_Door + hexStr(i + 1)}_y`) as number)
  }
}
export function TogglingPathDirectionA_update(self: TogglingPathDirectionA): void {
  update_EF11(self)
  switch (self.sub_state) {
    case self.SUB_STATE_1: {
      const player = pc()
      const _COUNT = self.dg_doors.width
      for (let i = 0; i < _COUNT; i++) {
        let _x = self.dg_doors.get(i, 1) as number
        let _y = self.dg_doors.get(i, 2) as number
        const _colliding = pointInRect(
          player.x,
          player.cp1Y,
          _x - (self.DOOR_HB_W >> 1),
          _y - 2,
          self.DOOR_HB_W,
          4,
        )
        if (!gmBool(self.dg_doors.get(i, 0))) {
          if (_colliding) continue
          self.dg_doors.set(i, 0, 1)
        }
        if (!_colliding) continue
        if (
          gmBool(input.Up_held) && // is holding up
          !gmBool(player.ogr) && // is on ground
          !(input.held_0 & input.U) && // Has released 'up' since spawning
          _colliding
        ) {
          // assumes there are 4 doors
          _x = self.dg_doors.get((i + self.path_dir) & 3, 1) as number
          _y = self.dg_doors.get((i + self.path_dir) & 3, 2) as number
          set_xlyt(player, _x - player.ww_, _y - player.hh)
          player.hspd = 0
          player.vspd = 0
          self.path_dir = -self.path_dir
          gp().dm_spawn.set((self.dk_spawn ?? '') + STR_Direction, self.path_dir)
          for (let j = 0; j < _COUNT; j++) self.dg_doors.set(j, 0, 0) // Set all closed.
          self.sub_state = self.SUB_STATE_2
          break
        }
      }
      break
    }
    case self.SUB_STATE_2:
      self.sub_state = self.SUB_STATE_3
      break
    case self.SUB_STATE_3:
      self.sub_state = self.SUB_STATE_1
      break
  }
}
export function TogglingPathDirectionA_udp(self: TogglingPathDirectionA): void {
  self.arrow_pi = gmBool(self.path_dir) ? self.PI_FRWD : self.PI_BKWD
}
export function TogglingPathDirectionA_draw(self: TogglingPathDirectionA): void {
  for (let i = self.dg_doors.width - 1; i >= 0; i--) {
    let _x = (self.dg_doors.get(i, 1) as number) - (self.DOOR_BGR_W >> 1)
    let _y = (self.dg_doors.get(i, 2) as number) - self.DOOR_BGR_H
    draw_sprite_('spr_1x1_WHT', 0, _x, _y, -1, self.DOOR_BGR_W, self.DOOR_BGR_H, pp().C_BLK1)
    _x = self.dg_doors.get(i, 1) as number
    _y = (self.dg_doors.get(i, 2) as number) - (self.DOOR_SPR_H >> 1)
    draw_sprite_(self.door_spr, 0, _x, _y, self.palidx)
    // ** NOTE: assumes there are 4 doors.
    let _idx = (g.counter1 >> 4) & 0x3
    if (!gmBool(self.path_dir)) _idx ^= 0x3
    const _spr = _idx === i ? self.ARROW_SPR2 : self.ARROW_SPR1
    let _rot = (i ^ 3) + (gmBool(self.path_dir) ? 1 : 0)
    _rot &= 3
    _rot *= 90
    _y = (self.dg_doors.get(i, 2) as number) - self.DOOR_SPR_H - 3
    draw_sprite_rot(_spr, 0, _x, _y, self.arrow_pi, 1, 1, c_white, 1, _rot)
  }
}
export function TogglingPathDirectionA_end(self: TogglingPathDirectionA): void {
  self.dg_doors = new (
    self.dg_doors.constructor as new (
      w: number,
      h: number,
      f: number,
    ) => typeof self.dg_doors
  )(0, 3, 0)
}

// ================================================================================================
// TogglingPathDirectionB
// ================================================================================================
export function TogglingPathDirectionB_init1(self: TogglingPathDirectionB): void {
  init_vars_Challenge_1a(self)
  self.SUB_STATE_1 = 1 // PC controls Elevator
  self.SUB_STATE_2 = 2 // self controls Elevator
  self.SUB_STATE_3 = 3
  self.SUB_STATE_4 = 4
  self.sub_state = self.SUB_STATE_1
  self.DUR_DELAY_1 = 0x14
  self.DUR_SELF_CONTROL1_DELAY = 0x20 - self.DUR_DELAY_1
  self.DUR_SELF_CONTROL2_DELAY = 0x00
  self.DUR_PLYR_CONTROL1_DELAY = 0x08
  self.RADIUS = 0x07 << 3
  self.path_dir = 1 // 1: Forward, -1: Backward
  self.LOC_TOP = 1
  self.LOC_RGT = 2
  self.LOC_BTM = 3
  self.LOC_LFT = 4
  self.location_a = self.LOC_TOP // The current location(out of 4).
  self.location_b = self.LOC_RGT // Which location the current one will take you to.
  self.loc_b_reached = false
  self.SPEED1 = 0x10
  self.PI_FRWD = GG().PI_MOB_RED // Red
  self.PI_BKWD = GG().PI_MOB_BLU // Blue
  if (gmBool(self.path_dir)) GO_init_palidx(self, self.PI_FRWD)
  else GO_init_palidx(self, self.PI_BKWD)
  self.ARROW_SPR_A1 = 'spr_arrow_4a_BWR'
  self.ARROW_SPR_A2 = 'spr_arrow_4a_WRB'
  self.ARROW_CNT = ((self.RADIUS >> 3) - 2) << 2
  const Grid = self.dg_arrows.constructor as new (w: number, h: number, f: number) => typeof self.dg_arrows
  self.dg_arrows = new Grid(self.ARROW_CNT, 3, 0)
  self.arrow_lit_idx = 0
  self.ARROW_SPR_B1 = 'spr_arrow_5a_BWR'
  self.ARROW_SPR_B2 = 'spr_arrow_5a_WRB'
  self.dg_a = new Grid(4, 3, 0)
}
export function TogglingPathDirectionB_init2(self: TogglingPathDirectionB): void {
  self.path_dir = gp().dm_spawn.get((self.dk_spawn ?? '') + STR_Direction) as number
  set_xlyt(self, self.spawn_xl - (self.ww >> 1), self.spawn_yt - (self.hh >> 1))
  // TOP 1, RGT 2, BTM 3, LFT 4
  self.dg_a.set(0, 1, self.x)
  self.dg_a.set(0, 2, self.y - self.RADIUS)
  self.dg_a.set(1, 1, self.x + self.RADIUS)
  self.dg_a.set(1, 2, self.y)
  self.dg_a.set(2, 1, self.x)
  self.dg_a.set(2, 2, self.y + self.RADIUS)
  self.dg_a.set(3, 1, self.x - self.RADIUS)
  self.dg_a.set(3, 2, self.y)
  const exitEnter = gp().exit_enter as { side: number } | null
  switch ((exitEnter?.side ?? 0) & 0xf) {
    case 1:
      self.location_a = self.LOC_RGT
      break // RGT 2
    case 2:
      self.location_a = self.LOC_LFT
      break // LFT 4
    case 4:
      self.location_a = self.LOC_BTM
      break // BTM 3
    case 8:
      self.location_a = self.LOC_TOP
      break // TOP 1
  }
  self.location_b = ((self.location_a - 1 + self.path_dir) & 3) + 1
  let _XX = 0
  let _YY = 0
  const _OFFSET = 0x10
  const _WW = 0x18 // Elevator ww
  const ELEV_H = 0x10 // FIDELITY: ZALiA reads an undefined `ELEV_H`; the elevator sprite is 16 px tall.
  switch (self.location_a) {
    case self.LOC_TOP:
      _XX = self.x - (_WW >> 1)
      _YY = cam_yt_min() - _OFFSET
      break
    case self.LOC_RGT:
      _XX = cam_xr_max() + _OFFSET - _WW
      _YY = self.y - (ELEV_H >> 1)
      break
    case self.LOC_BTM:
      _XX = self.x - (_WW >> 1)
      _YY = cam_yb_max() + _OFFSET - ELEV_H
      break
    case self.LOC_LFT:
      _XX = cam_xl_min() - _OFFSET
      _YY = self.y - (ELEV_H >> 1)
      break
  }
  const elev = GameObject_create(_XX, _YY, 'ElevatorB', 1) as ElevatorLike | null
  self.elev = elev
  if (elev) {
    elev.spawn_xl = _XX
    elev.spawn_yt = _YY
    set_xlyt(elev, elev.spawn_xl, elev.spawn_yt)
    elev.dl_exit.add(gp().exit_enter)
    elev.scr_step = undefined
  }
  const _QUAR_CNT = self.ARROW_CNT >> 2
  for (let i = 0; i < _QUAR_CNT; i++) {
    // UP-RGT, UP-LFT, DWN-LFT, DWN-RGT quadrants
    const _y = -(((i + 1) << 3) + 4)
    const _x = ((_QUAR_CNT - i) << 3) + 4
    self.dg_arrows.set(0 * _QUAR_CNT + i, 1, self.x + _x)
    self.dg_arrows.set(0 * _QUAR_CNT + i, 2, self.y + _y)
    self.dg_arrows.set(1 * _QUAR_CNT + i, 1, self.x + _y)
    self.dg_arrows.set(1 * _QUAR_CNT + i, 2, self.y + -_x)
    self.dg_arrows.set(2 * _QUAR_CNT + i, 1, self.x + -_x)
    self.dg_arrows.set(2 * _QUAR_CNT + i, 2, self.y + -_y)
    self.dg_arrows.set(3 * _QUAR_CNT + i, 1, self.x + -_y)
    self.dg_arrows.set(3 * _QUAR_CNT + i, 2, self.y + _x)
  }
}
export function TogglingPathDirectionB_update(self: TogglingPathDirectionB): void {
  update_EF11(self)
  const elev = self.elev
  if (!elev) return
  // pc_lock: $1: hspd, $2: jump, $10: stab high, $20: stab low, $40: thrust down, $80: thrust up
  gp().pc_lock |= elev.pc_lock_bits
  if (gmBool(gp().EnterRoom_control_timer)) {
    GameObjectB_step(elev as unknown as GameObjectB)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  let _amt = 0
  let _dist = 0
  let _colliding = false
  let _X = 0
  let _Y = 0
  const la = self.location_a
  const lb = self.location_b
  switch (self.sub_state) {
    case self.SUB_STATE_1: {
      _X = self.dg_a.get(la - 1, 1) as number
      _Y = self.dg_a.get(la - 1, 2) as number
      self.loc_b_reached = false
      elev.hspd1 = elev.HSPD
      elev.vspd1 = elev.VSPD
      elev.moving_dir = 0
      if (isVal(la, self.LOC_TOP, self.LOC_BTM)) {
        elev.moving_dir = input.heldV & 0xc
        if (gmBool(elev.moving_dir)) {
          _amt = (elev.vspd1 * bit_dir(elev.moving_dir & 0xc)) & 0xff // vspd
          _amt = simulate_position_change(_amt, elev.vspd_sub) // y change
          _dist = Math.abs(elev.y - _Y)
          _colliding = _dist <= Math.abs(_amt)
          if (_colliding) {
            if (_dist) elev.vspd1 = (_dist << 4) & 0xf0
            else elev.moving_dir = 0
          }
        }
      } else {
        elev.moving_dir = input.heldH & 0x3
        if (gmBool(elev.moving_dir)) {
          _amt = (elev.hspd1 * bit_dir(elev.moving_dir & 0x3)) & 0xff // hspd
          _amt = simulate_position_change(_amt, elev.hspd_sub) // x change
          _dist = Math.abs(elev.x - _X)
          _colliding = _dist <= Math.abs(_amt)
          if (_colliding) {
            if (_dist) elev.hspd1 = (_dist << 4) & 0xf0
            else elev.moving_dir = 0
          }
        }
      }
      if (_colliding) {
        self.timer = self.DUR_DELAY_1 // Delay set pc xScale
        self.sub_state = self.SUB_STATE_2
      }
      break
    }
    case self.SUB_STATE_2: {
      elev.moving_dir = 0
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      pc().xScale = sign_((self.dg_a.get(lb - 1, 1) as number) - (self.dg_a.get(la - 1, 1) as number))
      self.timer = self.DUR_SELF_CONTROL1_DELAY
      self.sub_state = self.SUB_STATE_3
      break
    }
    case self.SUB_STATE_3: {
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      elev.hspd1 = self.SPEED1
      elev.vspd1 = self.SPEED1
      const _DIST = (0x05 + (isVal(lb, self.LOC_RGT, self.LOC_LFT) ? 1 : 0)) << 3
      if (isVal(lb, self.LOC_TOP, self.LOC_BTM)) {
        // --------------------- going to: TOP or BTM ------------------------------------
        elev.moving_dir = 4 << (lb === self.LOC_TOP ? 1 : 0) // 4(DWN) or 8(UP)
        if (!self.loc_b_reached) elev.moving_dir |= 1 << (la === self.LOC_RGT ? 1 : 0) // 5(RGT-DWN) or $A(LFT-UP)
        if (!self.loc_b_reached) {
          _amt = (elev.hspd1 * bit_dir(elev.moving_dir & 0x3)) & 0xff // hspd
          _amt = simulate_position_change(_amt, elev.hspd_sub) // x change
          _X = self.dg_a.get(lb - 1, 1) as number
          _dist = Math.abs(elev.x - _X)
          self.loc_b_reached = _dist <= Math.abs(_amt)
          if (self.loc_b_reached) {
            // FIDELITY: ZALiA does `moving_dir &= ~_dir` with `_dir` always 0 (a no-op); the intent is to
            // stop the horizontal component once the column is reached.
            if (_dist) elev.hspd1 = (_dist << 4) & 0xf0
            else elev.moving_dir &= ~0x3
          }
        } else {
          _amt = (elev.vspd1 * bit_dir(elev.moving_dir & 0xc)) & 0xff // vspd
          _amt = simulate_position_change(_amt, elev.vspd_sub) // y change
          _Y = self.dg_a.get(lb - 1, 2) as number
          _colliding = (elev.y + _amt - _Y) * sign_(lb === self.LOC_BTM) >= _DIST
        }
      } else {
        // --------------------- going to: RGT or LFT ------------------------------------
        elev.moving_dir = 1 << (lb === self.LOC_LFT ? 1 : 0) // 1(RGT) or 2(LFT)
        if (!self.loc_b_reached) elev.moving_dir |= 4 << (la === self.LOC_BTM ? 1 : 0) // 5(RGT-DWN) or $A(LFT-UP)
        if (!self.loc_b_reached) {
          _amt = (elev.vspd1 * bit_dir(elev.moving_dir & 0xc)) & 0xff // vspd
          _amt = simulate_position_change(_amt, elev.vspd_sub) // y change
          _Y = self.dg_a.get(lb - 1, 2) as number
          _dist = Math.abs(elev.y - _Y)
          self.loc_b_reached = _dist <= Math.abs(_amt)
          if (self.loc_b_reached) {
            if (_dist) elev.vspd1 = (_dist << 4) & 0xf0
            else elev.moving_dir &= ~0xc
          }
        } else {
          _amt = (elev.hspd1 * bit_dir(elev.moving_dir & 0x3)) & 0xff // hspd
          _amt = simulate_position_change(_amt, elev.hspd_sub) // x change
          _X = self.dg_a.get(lb - 1, 1) as number
          _colliding = (elev.x + _amt - _X) * sign_(lb === self.LOC_RGT) >= _DIST
        }
      }
      if (_colliding) {
        elev.moving_dir = 0
        self.path_dir = -self.path_dir
        gp().dm_spawn.set((self.dk_spawn ?? '') + STR_Direction, self.path_dir)
        self.location_a = self.location_b
        self.location_b = ((self.location_a - 1 + self.path_dir) & 3) + 1
        self.timer = self.DUR_PLYR_CONTROL1_DELAY
        self.sub_state = self.SUB_STATE_4
      }
      break
    }
    case self.SUB_STATE_4: {
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      self.sub_state = self.SUB_STATE_1
      break
    }
  }
  GameObjectB_step(elev as unknown as GameObjectB)
}
export function TogglingPathDirectionB_udp(self: TogglingPathDirectionB): void {
  self.can_draw_self = true
  self.palidx = gmBool(self.path_dir) ? self.PI_FRWD : self.PI_BKWD
  if (!(g.counter1 & 0x1f)) {
    self.arrow_lit_idx += -self.path_dir
    if (self.arrow_lit_idx >= self.ARROW_CNT >> 2) self.arrow_lit_idx = 0
    else if (self.arrow_lit_idx < 0) self.arrow_lit_idx = (self.ARROW_CNT >> 2) - 1
  }
}
export function TogglingPathDirectionB_draw(self: TogglingPathDirectionB): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const quarter = self.ARROW_CNT >> 2
  for (let i = self.dg_arrows.width - 1; i >= 0; i--) {
    const _spr = i % quarter === self.arrow_lit_idx ? self.ARROW_SPR_A2 : self.ARROW_SPR_A1
    const _x = self.dg_arrows.get(i, 1) as number
    const _y = self.dg_arrows.get(i, 2) as number
    let _rot = (Math.trunc(i / quarter) & 3) * 90
    if (gmBool(self.path_dir)) _rot = (_rot + 180) % 360
    draw_sprite_rot(_spr, 0, _x, _y, self.palidx, 1, 1, c_white, 1, _rot)
  }
  if (!gmBool(gp().DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!gp().can_draw_cs) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  self.depth = DEPTH_BASE_HUD
  for (let i = self.dg_a.width - 1; i >= 0; i--)
    drawPointCross(self.dg_a.get(i, 1) as number, self.dg_a.get(i, 2) as number, c_lime, c_purple)
  if (self.elev) drawPointCross(self.elev.x, self.elev.y, c_white, c_orange)
}
export function TogglingPathDirectionB_end(self: TogglingPathDirectionB): void {
  const Grid = self.dg_arrows.constructor as new (w: number, h: number, f: number) => typeof self.dg_arrows
  self.dg_a = new Grid(4, 3, 0)
  self.dg_arrows = new Grid(0, 3, 0)
}
