/**
 * Deeler (ZALiA object `DeelA`, parent `Enemy`; the spider that hangs from a web, v2 drops and hops).
 * `Deeler_init2/update/udp/draw/end.gml` (`Deeler_update_OG` is dead).
 */
import { Area_EastA, CS_BD1, STR_Distance } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { DsList } from '../../../../../../runtime/ds'
import { g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { Enemy } from '../../../../classes'
import { draw_sprite_, GO_draw_sprite } from '../../../../go/draw'
import { DC91_carry, dir_to_pc } from '../../../../go/misc'
import { set_xlyt, updateX, updateY } from '../../../../go/movement'
import { solid_clip_correction } from '../../../../goa/movement'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'
import { rand, randoSpawnDatakey, spawnDataHex } from '../ache/_shared'

export class DeelA extends Enemy {
  readonly objectName = 'DeelA' as const
  drawYOff_DROPPED = 2
  HANG_DIST_DEF = 0x60 // $5E: $8E - $30(spawnY)
  hangDist = 0x60
  SPAWN_Y = 0
  targetY_up = 0 // 05DD. spawnY
  targetY_dw = 0 // 05DC. spawnY + $60
  Web_can_draw = false
  dl_Web_y = new DsList<number>()
}

/** `Deeler_init2()` */
export function Deeler_init2(self: DeelA): void {
  self.dl_sprites?.set(0, 'spr_Deeler1')
  self.counter = 0
  self.drawYOff_DROPPED = 2
  self.HANG_DIST_DEF = 0x60
  const _spawn_datakey = randoSpawnDatakey(self.dk_spawn)
  self.HANG_DIST_DEF = spawnDataHex(_spawn_datakey, STR_Distance, self.HANG_DIST_DEF)
  self.HANG_DIST_DEF -= self.drawYOff_DROPPED
  self.hangDist = self.HANG_DIST_DEF
  self.SPAWN_Y = self.yt
  self.targetY_up = self.SPAWN_Y // 05DD. spawnY
  self.targetY_dw = self.targetY_up + self.hangDist // 05DC. spawnY + $60
  set_xlyt(self, self.xl, self.targetY_up)
  self.Web_can_draw = false
  self.dl_Web_y = new DsList<number>()
  self.dl_Web_y.add(self.targetY_up, self.targetY_up, self.targetY_up)
  switch (self.ver) {
    case 1:
      if (g.area_name === Area_EastA) {
        self.ATTACK_LEVEL = 0x03
        self.attack_level = self.ATTACK_LEVEL
        self.HP_IDX = 0x08
        self.hp = g.dl_HP.get(self.HP_IDX) as number
        self.XP_IDX = 0x05
        self.xp = g.dl_XP.get(self.XP_IDX) as number
      }
      break
    case 2:
      if (g.area_name === Area_EastA) {
        self.HP_IDX = 0x08
        self.hp = g.dl_HP.get(self.HP_IDX) as number
        self.XP_IDX = 0x0a
        self.xp = g.dl_XP.get(self.XP_IDX) as number
      }
      break
  }
}

/** `Deeler_update()` — D6DF: JSR DA02 */
export function Deeler_update(self: DeelA): void {
  const P = pc()
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return
  }
  // D6E2: JSR D6C1
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  const _RAND = rand(self)
  // D6E5
  if (self.counter < 0x80) {
    // if has NOT dropped. D6EC
    self.facing_dir = dir_to_pc(self)
    const _IN_DIST_ATK = Math.abs(P.x - self.x) + +DC91_carry(self) < 0x40 + self.ww_
    const _C1 = _IN_DIST_ATK && !(_RAND & 0x1f) && !self.ocs
    if (gmBool(self.counter) || _C1) {
      // D70F
      if (!self.counter) self.counter = 1 // 1: move down
      let _targetY = self.targetY_dw // home Y + hangDist
      if (self.counter === 2) _targetY = self.targetY_up // home Y
      if (self.yt === _targetY && self.counter === 2) {
        // at home Y, climbing up
        self.counter = 0 // idle
      } else {
        // mod
        let _qual_drop = false
        if (self.yt === _targetY || self.cs & 0x4) {
          self.counter = 2 // 2: climbing up
          _qual_drop = true
        }
        if (self.ver === 2 && _qual_drop) {
          // D734 - Drop
          self.counter = 0x80
          self.hspd = 0
          self.vspd = 0x20
          self.timer = 0x20
        } else {
          // D744
          if (self.counter === 2)
            self.vspd = 0xf0 // 2: climbing up
          else self.vspd = 0x20
          // D74A. mod: only move while not standing on ground (or when climbing up)
          if (!(self.cs & 0x4) || self.counter === 2) updateY(self)
        }
      }
    } else {
      // D6FB
      self.hspd = (8 * self.facing_dir) & 0xff
      if (!(self.cs & 0x3)) updateX(self)
    }
    // mod
    GO_update_cs(self)
    // DE40
    GOB_update_2(self)
  }
  // ------------------------------------------------------------------------------------
  if (self.counter & 0x80) {
    // if has dropped. D750
    if (!gmBool(self.timer)) {
      // =-----------  JUMP  -------------------
      self.timer = 0x40 | (_RAND & 0x3f)
      self.facing_dir = dir_to_pc(self)
      self.hspd = (0x20 * self.facing_dir) & 0xff
      self.vspd = 0xe8 | (_RAND & 0x7)
    }
    // D773 (mod)
    if (!(self.cs & 0x3)) updateX(self)
    updateY(self)
    self.vspd = (self.vspd + 1) & 0xff
    GO_update_cs(self)
    // mod
    if (self.cs & 0x8) self.vspd = 1
    GOB_update_2(self)
    // D77F
    if (self.cs & 0x4) {
      // DAC1
      solid_clip_correction(self, false)
      self.vspd = 0
      // D788
      self.hspd = 0
    }
  }
}

/** `Deeler_udp()` — F027 */
export function Deeler_udp(self: DeelA): void {
  self.can_draw_self = true
  self.Web_can_draw = false
  self.xScale = g.counter1 & 0x8 ? -1 : 1
  self.yScale = gmBool(self.counter) ? 1 : -1 // moving down or up / idle
  self.draw_yoff = self.counter & 0x80 ? self.drawYOff_DROPPED : 0 // has dropped
  // F04B
  let _dist = self.yt - self.targetY_up
  if (self.counter < 0x80 && gmBool(_dist)) {
    // has NOT dropped
    self.Web_can_draw = true
    // F05F
    let _separation = 0xff
    while (_dist >= 0) {
      _separation = (_separation + 1) & 0xff
      _dist -= 3
    }
    let _Web_Y = self.targetY_up + 1 // + 1 because _Web_Y is drawY, not ogY
    if (!(g.counter1 & 0x1)) _Web_Y += _separation >> 1
    for (let _i = self.dl_Web_y.size - 1; _i >= 0; _i--) self.dl_Web_y.set(_i, _Web_Y + _separation * _i)
  }
}

/** `Deeler_draw()` */
export function Deeler_draw(self: DeelA): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  if (self.Web_can_draw) {
    for (let _i = self.dl_Web_y.size - 1; _i >= 0; _i--)
      draw_sprite_('spr_Deeler_web1', 0, self.drawX, self.dl_Web_y.get(_i) as number, -1, 1, 1, self.depth)
  }
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

/** `Deeler_end()` — freed `dl_Web_y` in ZALiA; nothing to do here. */
export function Deeler_end(self: DeelA): void {
  self.dl_Web_y.clear()
}

registerObject('DeelA', DeelA)
registerScripts({ Deeler_init2, Deeler_update, Deeler_udp, Deeler_draw, Deeler_end })
