/** Tiled JSON map subset ZALiA's scene/overworld files use (see zalia-data-model KB). */
export interface TiledTileLayer {
  type: 'tilelayer'
  name: string
  width: number
  height: number
  /** 1-based global tile ids, 0 = empty ("Tiled app adds 1 so it can't be 0"). */
  data: number[]
  properties?: TiledProperty[]
}
export interface TiledObject {
  id: number
  name: string
  type?: string
  x: number
  y: number
  width: number
  height: number
  gid?: number
  properties?: TiledProperty[]
}
export interface TiledObjectLayer {
  type: 'objectgroup'
  name: string
  objects: TiledObject[]
  properties?: TiledProperty[]
}
export interface TiledProperty {
  name: string
  type?: string
  value: string | number | boolean
}
export type TiledLayer = TiledTileLayer | TiledObjectLayer
export interface TiledTilesetRef {
  firstgid: number
  /** Bare tileset name (`ts_Natural_1a_WRB`); the asset pipeline normalises Tiled's `.tsx` paths. */
  name: string
  source?: string
}
export interface TiledMap {
  width: number
  height: number
  tilewidth: number
  tileheight: number
  layers: TiledLayer[]
  tilesets: TiledTilesetRef[]
  backgroundcolor?: string
}

export function tileLayer(map: TiledMap, name: string): TiledTileLayer | undefined {
  return map.layers.find((l): l is TiledTileLayer => l.type === 'tilelayer' && l.name === name)
}

/** Tiled property lookup (`_AccessOw`, `depth`, …). */
export function prop(
  o: { properties?: TiledProperty[] },
  name: string,
): string | number | boolean | undefined {
  return o.properties?.find((p) => p.name === name)?.value
}

/**
 * Scene/overworld maps by file stem (`PalcA_003`, `OvrwA_00`). The adapter preloads what a room needs;
 * tests load from `apps/web/public/assets/maps` or `../ZALiA/datafiles`.
 */
export class MapStore {
  private readonly maps = new Map<string, TiledMap>()
  set(stem: string, map: TiledMap): void {
    this.maps.set(stem, map)
  }
  get(stem: string): TiledMap | undefined {
    return this.maps.get(stem)
  }
  has(stem: string): boolean {
    return this.maps.has(stem)
  }
}
