/**
 * Randomizer entry point and seed helpers — `Rando_randomize_file.gml`, `Rando_get_new_seed.gml`,
 * `Rando_draw_seed.gml`.
 *
 * `FileSelect_register_file` calls `Rando_randomize_file(file num, quest num, seed, encoded settings)`
 * for every registered save (also when rando is off — palette/dungeon-tileset rando still run). It decodes
 * the ~35 settings, runs `Rando_generate`, and persists three files through `world.storage`, under exactly
 * the names ZALiA writes into `%localappdata%`:
 *   `SaveFile_N_Rando_Data.txt`               → `f.dm_rando_full`, whose `_Quest<h>_Rando_Data` is `f.dm_rando`
 *   `SaveFile_N_RandoDungeonTilesetData.txt`  → `f.dm_rando_dungeon_tileset`
 *   `SaveFile_N_Rando_Spoiler.txt`            → the human-readable spoiler log
 *
 * Dropped: `show_debug_message`-only lines and the commented-out `get_saved_value` seed lookup at `:44`.
 */
import {
  dk_DarkRoom,
  dk_LimitObscure,
  STR_Attack,
  STR_Biome,
  STR_Boss,
  STR_Container,
  STR_Cost,
  STR_Damage,
  STR_Data,
  STR_Debug,
  STR_Difficulty,
  STR_Dungeon,
  STR_ENIGMA,
  STR_Enemy,
  STR_File,
  STR_Hint,
  STR_HP,
  STR_Item,
  STR_Key,
  STR_Level,
  STR_Life,
  STR_Location,
  STR_Locations,
  STR_Magic,
  STR_Method,
  STR_MP,
  STR_Overworld,
  STR_Palette,
  STR_PBAG,
  STR_Quest,
  STR_Rando,
  STR_Randomize,
  STR_Room,
  STR_Scene,
  STR_Skill,
  STR_Spawner,
  STR_Spell,
  STR_Start,
  STR_Tileset,
  STR_Town,
  STR_XP,
  STR_Zelda,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { f, g, p, world } from '../../runtime/world'
import { type GmJsonValue, json_decode, json_encode } from '../file/json'
import { dungeonTilesetFileName, randoDataFileName, randoSpoilerFileName } from '../file/save'
import { sdm } from '../other/index'
import { pal_swap_reset, pal_swap_set } from '../palette/scenePalette'
import { draw_sprite_ } from '../rooms/draw'
import { Rando_generate } from './generate'
import { clamp } from './helpers'
import { Rando } from './Rando'

/** `Rando_get_new_seed()` — `randomize(); return random_get_seed();` (the `switch(1)` case-2 form is dead). */
export function Rando_get_new_seed(): number {
  return world.randomize()
}

/**
 * `Rando_draw_seed(base x, base y, seed, *sprite padding)` — the seed as 8 item sprites, most significant
 * nybble first.
 */
export function Rando_draw_seed(X: number, Y: number, SEED: number, PAD = 0x04): void {
  pal_swap_set(p.PI_MOB_ORG)
  for (let _i = g.RandoSeedChar_COUNT - 1; _i >= 0; _i--) {
    let _x = 0x08 + PAD
    _x *= g.RandoSeedChar_COUNT - 1 - _i
    _x = X + _x
    const _y = Y
    const _idx = (SEED >>> (_i << 2)) & 0xf
    draw_sprite_(g.dl_rando_seed_SPRITES.get(_idx) as string, 0, _x, _y)
  }
  pal_swap_reset()
}

/**
 * `Rando_randomize_file(save file num, quest num, seed, encoded rando settings)`
 * @returns the `Rando` state after generation (ZALiA destroys the instance; the port hands it back so
 *   tests and the debug tools can inspect `dm_save_data` without re-running generation). `undefined` when
 *   the save file does not exist, matching the GML's early `exit`.
 */
export function Rando_randomize_file(
  FILE_NUM: number,
  QUEST_NUM: number,
  SEED: number,
  RANDO_SETTINGS: string,
): Rando | undefined {
  const self = new Rando()
  self.FILE_NUM = FILE_NUM
  self.Rando_SEED = SEED

  const _FILE_NAME = String(f.dl_file_names.get(FILE_NUM - 1))
  const _SAVE_NAME = String(f.dl_save_names.get(FILE_NUM - 1))

  if (!world.storage.exists(_FILE_NAME)) {
    sdm(`!!! Rando Failed.  File: ${_FILE_NAME}  does NOT exist. !!!`)
    return undefined
  }

  self.DEBUG = true
  self.debug_str = ''
  self.debug_data_count = 0
  self.dm_debug_data.clear()

  self.dm_save_data.clear()
  self.dm_save_data_dungeon_tileset.clear()

  // So the code below doesn't error when trying to get map data
  const decoded = json_decode(RANDO_SETTINGS)
  const _dm_SETTINGS = decoded === -1 ? new Map<string, GmJsonValue>() : decoded
  const num = (key: string, dflt = 0): number => {
    const v = _dm_SETTINGS.get(key)
    return v === undefined ? dflt : Number(v)
  }

  self.ItemLocations_LIMIT_OBSCURE = num(dk_LimitObscure)
  self.ItemLocations_DARKROOM_DIFFICULTY = num(dk_DarkRoom + STR_Difficulty)
  self.ItemLocations_NPC_GIVE_HINTS = num(STR_Item + STR_Location + STR_Hint)
  self.ItemLocations_ZELDA_HINT = num(STR_Zelda + STR_Hint)
  self.ItemLocations_WILL_RANDOMIZE = num(STR_Randomize + STR_Item + STR_Locations)
  self.ItemLocations_INCLUDE_PBAG = num(STR_Randomize + STR_PBAG + STR_Locations)
  self.KeyLocations_WILL_RANDOMIZE = num(STR_Randomize + STR_Key + STR_Locations)

  self.SkillLocations_WILL_RANDOMIZE = num(STR_Randomize + STR_Skill + STR_Locations)
  self.SpellLocations_WILL_RANDOMIZE = num(STR_Randomize + STR_Spell + STR_Locations)
  self.SpellCosts_WILL_RANDOMIZE = num(STR_Randomize + STR_Spell + STR_Cost)

  self.Enemy_DIFFICULTY = clamp(
    num(STR_Randomize + STR_Enemy + STR_Difficulty),
    1,
    g.RandoEnemy_difficulty_MAX,
  )
  self.EnemyChars_WILL_RANDOMIZE = num(STR_Randomize + STR_Enemy + STR_Method)
  self.EnemySpawners_WILL_RANDOMIZE = num(STR_Randomize + STR_Enemy + STR_Spawner)
  self.EnemyENIGMA_WILL_RANDOMIZE = num(STR_Randomize + STR_Enemy + STR_ENIGMA)
  self.EnemyHP_WILL_RANDOMIZE = num(STR_Randomize + STR_Enemy + STR_HP)
  self.EnemyDamage_WILL_RANDOMIZE = num(STR_Randomize + STR_Enemy + STR_Damage)

  self.DungeonRooms_WILL_RANDOMIZE = num(STR_Randomize + STR_Dungeon + STR_Room)
  self.DungeonLocations_WILL_RANDOMIZE = num(STR_Randomize + STR_Dungeon + STR_Locations)
  self.DungeonBoss_WILL_RANDOMIZE = num(STR_Randomize + STR_Dungeon + STR_Boss)

  self.TownLocations_WILL_RANDOMIZE = num(STR_Randomize + STR_Town + STR_Locations)

  self.LevelCosts_WILL_RANDOMIZE = num(STR_Randomize + STR_Level + STR_Cost)
  self.XP_WILL_RANDOMIZE = num(STR_Randomize + STR_XP)

  self.Scenes_WILL_RANDOMIZE = num(STR_Randomize + STR_Scene)
  self.OverworldBiomes_WILL_RANDOMIZE = num(STR_Randomize + STR_Overworld + STR_Biome)
  self.Palette_WILL_RANDOMIZE = num(STR_Randomize + STR_Palette)
  self.DungeonTileset_WILL_RANDOMIZE = num(STR_Randomize + STR_Dungeon + STR_Tileset)

  self.Attack_LEVEL = num(STR_File + STR_Start + STR_Level + STR_Attack, 1)
  self.Magic_LEVEL = num(STR_File + STR_Start + STR_Level + STR_Magic, 1)
  self.Life_LEVEL = num(STR_File + STR_Start + STR_Level + STR_Life, 1)

  self.ContainersHP_START_COUNT = num(STR_File + STR_Start + STR_Container + STR_HP, f.CONT_MIN_HP)
  self.ContainersMP_START_COUNT = num(STR_File + STR_Start + STR_Container + STR_MP, f.CONT_MIN_MP)

  // ==========================================================================
  Rando_generate(self, QUEST_NUM, self.Rando_SEED)
  // ==========================================================================

  // ---- SAVE THE DATA ---------------------------------------------------------------------------
  const _dm_save_data = new Map<string, GmJsonValue>()
  const _RANDO_DATA_FILE_NAME = randoDataFileName(FILE_NUM)
  if (world.storage.exists(_RANDO_DATA_FILE_NAME)) {
    const _dm_rando_full = json_decode(world.storage.readText(_RANDO_DATA_FILE_NAME))
    if (_dm_rando_full !== -1) for (const [k, v] of _dm_rando_full) _dm_save_data.set(k, v)
  }

  const _datakey = STR_Quest + hexStr(QUEST_NUM)
  _dm_save_data.set(_datakey + STR_Rando + STR_Data, json_encode(self.dm_save_data))
  _dm_save_data.set(_datakey + STR_Rando + STR_Debug + STR_Data, json_encode(self.dm_debug_data))

  world.storage.writeText(_RANDO_DATA_FILE_NAME, json_encode(_dm_save_data))

  world.storage.writeText(dungeonTilesetFileName(FILE_NUM), json_encode(self.dm_save_data_dungeon_tileset))

  // Spoiler log: every non-blank `dm_debug_data` line, in the order it was recorded.
  const lines: string[] = []
  for (let _i = 0; _i < self.debug_data_count; _i++) {
    const _val = self.dm_debug_data.get(STR_Data + '01' + hexStr(_i + 1))
    if (_val !== undefined && _val !== '' && _val !== ' ') lines.push(_val)
  }
  world.storage.writeText(randoSpoilerFileName(FILE_NUM), lines.length ? `${lines.join('\n')}\n` : '')

  sdm(`Save File  '${_FILE_NAME}', Save Name  '${_SAVE_NAME}',  rando data saved!`)

  return self
}
