/** Screen objects per `rmB_*` room, registered for `gotoRoom`. */
import { ContinueSaveScreen } from './ContinueSaveScreen'
import { DeathScreen } from './DeathScreen'
import { FileSelect } from './FileSelect'
import { GameOverScreen } from './GameOverScreen'
import { RM } from './goto'
import { NextLifeScreen } from './NextLifeScreen'
import { screenFactories } from './roomChange'
import { TitleScreen } from './TitleScreen'

screenFactories.set(RM.TITLE, () => new TitleScreen())
screenFactories.set(RM.CONTINUE_SAVE, () => new ContinueSaveScreen())
screenFactories.set(RM.DEATH, () => new DeathScreen())
screenFactories.set(RM.NEXT_LIFE, () => new NextLifeScreen())
screenFactories.set(RM.GAME_OVER, () => new GameOverScreen())

export { ContinueSaveScreen, DeathScreen, FileSelect, GameOverScreen, NextLifeScreen, TitleScreen }
