/**
 * Backwall (ZALiA object `Backwall01`, parent `Enemy`; the advancing wall/water that drowns the player).
 * `Backwall_init1/init2/update/udp/draw.gml`. Uses `GameObjectB_step2` (state NORMAL only).
 */
import {
  DEPTH_BG1,
  PC_LOCK_ALL,
  STR_Damage,
  STR_Delay,
  STR_Direction,
  STR_Heart,
  STR_Max,
  STR_Min,
  STR_PC,
  STR_Speed,
} from '@z2/data'
import { abs8b, bit1st, byteToInt, gmBool } from '../../../../../../nes/math8'
import { G, g, p, world } from '../../../../../../runtime/world'
import { viewW, viewXL, viewYB } from '../../../../../collision/env'
import { adjust_stat, get_stat_max } from '../../../../../file/stats'
import { sign_ } from '../../../../../math/index'
import { str_hex } from '../../../../../other/index'
import { bgrToRgb } from '../../../../../palette/colors'
import { get_pal_color } from '../../../../../palette/palString'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { draw_background_part, draw_sprite_ } from '../../../../../rooms/draw'
import { play_theme_sound } from '../../../../../sound/play'
import { Enemy, type GameObject } from '../../../../classes'
import { set_xy, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_depth_init } from '../../../../go/sprite'
import { PC_set_behavior } from '../../../../goa/form'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GameObjectB_step2 } from '../../../GameObjectB'
import { spawnDataAfter, spawnDataHex } from '../ache/_shared'

export class Backwall01 extends Enemy {
  readonly objectName = 'Backwall01' as const
  readonly sub_state_IDLE = 0
  readonly sub_state_MOVING = 1
  readonly sub_state_DROWNING = 2
  sub_state = 0
  /** Movement Direction. $1-RIGHT, $2-LEFT, $4-DOWN, $8-UP */
  DIRECTION = 0x8
  SPEED1 = 0x20
  speed1 = 0
  acceleration = 0
  HSPD1 = 0
  VSPD1 = 0
  X_MIN = 0
  X_MAX = 0
  Y_MIN = 0
  Y_MAX = 0
  pc_is_drowning = false
}

/** `Backwall_init1()` — init_vars are class fields; depth, step script and draw offset. */
export function Backwall_init1(self: Backwall01): void {
  GO_depth_init(self, DEPTH_BG1)
  self.scr_step = GameObjectB_step2 as (self: GameObject) => void
  self.DRAW_YOFF = 0
}

/** `Backwall_init2()` */
export function Backwall_init2(self: Backwall01): void {
  self.sub_state = self.sub_state_IDLE
  GO_init_palidx(self, G.PI_BGR3)
  // Delay Start Moving
  self.timer = 0x40
  self.timer = spawnDataHex(self.dk_spawn, STR_Delay, self.timer)
  // Movement Direction. $1-RIGHT, $2-LEFT, $4-DOWN, $8-UP
  self.DIRECTION = 0x8
  if (self.dk_spawn !== undefined)
    self.DIRECTION = g.dm_spawn.val(self.dk_spawn + STR_Direction, self.DIRECTION) as number
  self.DIRECTION = bit1st(self.DIRECTION)
  // Movement Speed
  self.SPEED1 = 0x20
  if (self.dk_spawn !== undefined)
    self.SPEED1 = g.dm_spawn.val(self.dk_spawn + STR_Speed, self.SPEED1) as number
  self.SPEED1 = Math.max(0x01, Math.min(0x7f, self.SPEED1))
  self.speed1 = (self.SPEED1 * sign_(self.DIRECTION & 0x5)) & 0xff
  self.acceleration = sign_(self.DIRECTION & 0x5)
  self.HSPD1 = self.SPEED1
  self.VSPD1 = self.SPEED1
  self.hspd = 0
  self.vspd = 0
  self.X_MIN = 0
  self.X_MAX = g.rm_w
  self.Y_MIN = 0
  self.Y_MAX = g.rm_h
  if (self.DIRECTION & 0x1) self.X_MIN = self.spawn_xl
  if (self.DIRECTION & 0x2) self.X_MAX = self.spawn_xl
  if (self.DIRECTION & 0x4) self.Y_MIN = self.spawn_yt
  if (self.DIRECTION & 0x8) self.Y_MAX = self.spawn_yt
  const minMax = (key: string, dflt: number) => {
    const s = spawnDataAfter(self.dk_spawn, key)
    return s === undefined ? dflt : str_hex(s)
  }
  self.X_MIN = minMax(`${STR_Min}_X`, self.X_MIN)
  self.X_MAX = minMax(`${STR_Max}_X`, self.X_MAX)
  self.Y_MIN = minMax(`${STR_Min}_Y`, self.Y_MIN)
  self.Y_MAX = minMax(`${STR_Max}_Y`, self.Y_MAX)
  self.pc_is_drowning = false
}

/** `Backwall_update()` */
export function Backwall_update(self: Backwall01): void {
  const P = pc()
  switch (self.sub_state) {
    case self.sub_state_IDLE: {
      if (gmBool(self.timer)) break
      self.timer = 0
      self.sub_state = self.sub_state_MOVING
      break
    }
    case self.sub_state_MOVING: {
      if (gmBool(self.timer)) break
      if (self.DIRECTION & 0x3) {
        self.hspd = byteToInt(self.hspd)
        self.hspd += self.acceleration * 2
        self.hspd = Math.max(-self.SPEED1, Math.min(self.SPEED1, self.hspd))
        self.hspd &= 0xff
        self.hspd_impel = Math.sign(self.acceleration)
      } else {
        self.vspd = byteToInt(self.vspd)
        self.vspd += self.acceleration * 2
        self.vspd = Math.max(-self.SPEED1, Math.min(self.SPEED1, self.vspd))
        self.vspd &= 0xff
        self.vspd_impel = Math.sign(self.acceleration)
      }
      if (gmBool(self.hspd)) updateX(self)
      if (gmBool(self.vspd)) updateY(self)
      set_xy(
        self,
        Math.max(self.X_MIN, Math.min(self.X_MAX, self.x)),
        Math.max(self.Y_MIN, Math.min(self.Y_MAX, self.y)),
      )
      self.timer = 0
      break
    }
    case self.sub_state_DROWNING: {
      if (gmBool(self.timer)) break
      self.timer = 0
      break
    }
  }
  // Slow down to stop when not moving.
  if (self.DIRECTION & 0x3) {
    if (gmBool(self.hspd)) {
      self.hspd = abs8b(self.hspd)
      self.hspd -= self.acceleration
      self.hspd = Math.max(0x00, Math.min(0x7f, self.hspd))
      self.hspd *= sign_(self.DIRECTION & 0x1)
      self.hspd &= 0xff
    }
  } else {
    if (gmBool(self.vspd)) {
      self.vspd = abs8b(self.vspd)
      self.vspd -= self.acceleration
      self.vspd = Math.max(0x00, Math.min(0x7f, self.vspd))
      self.vspd *= sign_(self.DIRECTION & 0x4)
      self.vspd &= 0xff
    }
  }
  switch (self.ver) {
    case 1: {
      if (!gmBool(P.is_dead)) {
        if (self.pc_is_drowning) {
          const _CHANGE = sign_(self.DIRECTION & 0xa)
          if (self.DIRECTION & 0x3) set_xy(P, P.x + _CHANGE, P.y)
          else set_xy(P, P.x, P.y + _CHANGE)
          let _qual = false
          switch (self.DIRECTION) {
            case 0x1:
              _qual = P.x < self.x - P.ww_
              break
            case 0x2:
              _qual = P.x > self.x + P.ww_
              break
            case 0x4:
              _qual = P.y < self.y - P.hh_
              break
            case 0x8:
              _qual = P.y > self.y + P.hh_
              break
          }
          if (_qual) P.is_dead = true
        } else {
          const _DIST = 0x4 << Math.sign(self.DIRECTION & 0xc)
          switch (self.DIRECTION) {
            case 0x1:
              self.pc_is_drowning = P.xl + _DIST < self.x
              break
            case 0x2:
              self.pc_is_drowning = P.xr - _DIST > self.x
              break
            case 0x4:
              self.pc_is_drowning = P.yt + _DIST < self.y
              break
            case 0x8:
              self.pc_is_drowning = P.yb - _DIST > self.y
              break
          }
          if (self.pc_is_drowning) {
            const _damage = get_stat_max(STR_Heart)
            adjust_stat(-_damage, 0)
            g.pc_lock = PC_LOCK_ALL
            PC_set_behavior(P.behavior_DAMAGE)
            P.stun_timer = 0x10
            play_theme_sound(STR_PC + STR_Damage)
          }
        }
      }
      break
    }
    case 2:
      break
  }
}

/** `Backwall_udp()` — empty in ZALiA. */
export function Backwall_udp(_self: Backwall01): void {}

/** `Backwall_draw()` — a scrolling row of water tiles plus a solid colour fill below it (ver 1). */
export function Backwall_draw(self: Backwall01): void {
  switch (self.ver) {
    case 1: {
      const _DIR = 1
      let _X = viewXL()
      if (_DIR) _X -= 8
      _X += ((g.counter0 >> 3) & 0x7) * _DIR
      let _y = self.y
      let _count = viewW() >> 3
      _count += Math.sign(Math.abs(_DIR))
      pal_swap_set(self.palidx)
      for (let _i = _count - 1; _i >= 0; _i--) {
        const _x = _X + (_i << 3)
        draw_background_part('ts_Natural_1a_WRB', 0x0 << 3, 0xf << 3, 8, 8, _x, _y)
        draw_background_part('ts_Natural_1a_WRB', 0x8 << 3, 0xf << 3, 8, 8, _x, _y + 8)
      }
      pal_swap_reset()
      const _x = _X
      _y = self.y
      _y += 0x2 << 3
      // GML: `draw_sprite_(spr_1x1_WHT,0, _x,_y, -1, _count<<3,(viewYB()+8)-_y, get_pal_color(...))`.
      // Through the wrapper it follows the surface target and takes its depth from the dispatcher; the raw
      // `world.draw.push` it replaces did neither (and the colour conversion now happens in one place).
      draw_sprite_(
        'spr_1x1_WHT',
        0,
        _x,
        _y,
        -1,
        _count << 3,
        viewYB() + 8 - _y,
        get_pal_color(p.pal_rm_curr, self.palidx, 'R'),
      )
      break
    }
    case 2:
      break
  }
}

registerObject('Backwall01', Backwall01)
registerScripts({ Backwall_init1, Backwall_init2, Backwall_update, Backwall_udp, Backwall_draw })
