/** Update-slot allocation: available_update_idx_gob, add_to_update_list_b1, avail_uidx_goc, addToProjectileList. */
import { MAX_GOB1, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { instanceExists } from '../../runtime/instance'
import { goMgr } from '../../runtime/world'
import { type GameObject, ProjectileHostile } from '../game_object/classes'
import { deps } from '../game_object/deps'

const alive = (v: unknown): v is GameObject => instanceExists(v as GameObject | null | undefined)

/** `available_update_idx_gob(check count)` — first free or dead slot in dl_gob1, else UIDX_NULL. */
export function available_update_idx_gob(checkCount: number): number {
  const list = goMgr.dl_gob1
  const _COUNT = Math.min(checkCount, list.size)
  for (let _i = 0; _i < _COUNT; _i++) {
    const cur = list.get(_i)
    if (!alive(cur)) list.set(_i, null)
    if (list.get(_i) === null) return _i
    if (!(list.get(_i) as GameObject).state) return _i
  }
  return UIDX_NULL
}

/** `add_to_update_list_b1(id)` — claim a GOB1 slot (honouring uIdxSwap_gob), returns the slot or UIDX_NULL. */
export function add_to_update_list_b1(inst: GameObject): number {
  let _update_idx = UIDX_NULL
  if (goMgr.uIdxSwap_gob + 1 && goMgr.uIdxSwap_gob < MAX_GOB1) {
    _update_idx = goMgr.uIdxSwap_gob
    const cur = goMgr.dl_gob1.get(_update_idx)
    if (alive(cur)) cur.update_idx = UIDX_NULL
  } else {
    _update_idx = available_update_idx_gob(MAX_GOB1)
  }
  if (_update_idx + 1 && _update_idx < MAX_GOB1) {
    goMgr.dl_gob1.set(_update_idx, inst)
  } else {
    deps.sdm(`!!! WARNING. ${inst.objectName} was NOT added to g.go_mgr.dl_gob1.`)
  }
  goMgr.uIdxSwap_gob = UIDX_NULL
  return _update_idx
}

/** `avail_uidx_goc(check count)` — first free/dead hostile projectile slot. */
export function avail_uidx_goc(checkCount: number): number {
  const list = goMgr.dl_goc1
  const n = Math.min(Math.max(checkCount, 1), list.size)
  for (let _i = 0; _i < n; _i++) {
    const cur = list.get(_i)
    if (cur === undefined || cur === null) return _i
    if (!alive(cur)) return _i
    if (!cur.state) return _i
  }
  return UIDX_NULL
}

/**
 * `addToProjectileList(projectile instance id)` — claim a GOC1 slot, honouring uIdxSwap_goc.
 * FIDELITY: the GML swap branch tested `!instance_exists(dl_goc1[|_i])` with an undeclared `_i` (always
 * undefined → the whole condition false), so the displaced projectile never had its update_idx cleared;
 * intent (mirroring add_to_update_list_b1) is to clear it.
 */
export function addToProjectileList(inst: GameObject): number {
  let _uIdx = UIDX_NULL
  if (goMgr.uIdxSwap_goc + 1 && goMgr.uIdxSwap_goc < MAX_GOC1) {
    _uIdx = goMgr.uIdxSwap_goc
    const cur = goMgr.dl_goc1.get(_uIdx)
    if (alive(cur) && cur instanceof ProjectileHostile) cur.update_idx = UIDX_NULL
  } else {
    _uIdx = avail_uidx_goc(MAX_GOC1)
  }
  if (_uIdx + 1 && _uIdx < MAX_GOC1) goMgr.dl_goc1.set(_uIdx, inst)
  goMgr.uIdxSwap_goc = UIDX_NULL
  return _uIdx
}
