import { DsMap } from '../runtime/ds'
import type { GpButton, RawInput } from '../runtime/rawInput'
import { type KeyAction, keyboardBindings } from './keyboardBindings'

/**
 * The `Input` singleton — ported from `Input_Create.gml`, `Input_update1.gml`, `Input_update2*.gml`,
 * `gamepad_set_default.gml`. NES buttons are bits: R $01, L $02, D $04, U $08, START $10, SELECT $20,
 * B $40, A $80. Field names are ZALiA's so ported code reads unchanged.
 */
export class Input {
  readonly objectName = 'Input'
  // Bit values that represent NES buttons
  readonly R = 0x01
  readonly L = 0x02
  readonly D = 0x04
  readonly U = 0x08
  readonly S = 0x10 // START
  readonly E = 0x20 // SELECT
  readonly B = 0x40
  readonly A = 0x80

  gamepad_slot = -1 // -1: No gamepad connected
  gamepad_name: string | undefined = undefined

  // Rebindable gamepad mapping (GP_*_DEFAULT is the Xbox layout)
  readonly GP_right_DEFAULT: GpButton = 'gp_padr'
  readonly GP_left_DEFAULT: GpButton = 'gp_padl'
  readonly GP_down_DEFAULT: GpButton = 'gp_padd'
  readonly GP_up_DEFAULT: GpButton = 'gp_padu'
  readonly GP_jump_DEFAULT: GpButton = 'gp_face1' // Xbox A button
  readonly GP_other1_DEFAULT: GpButton = 'gp_face2' // Xbox B button
  readonly GP_attack_DEFAULT: GpButton = 'gp_face3' // Xbox X button
  readonly GP_other2_DEFAULT: GpButton = 'gp_face4' // Xbox Y button
  readonly GP_pause_DEFAULT: GpButton = 'gp_start'
  readonly GP_magic_DEFAULT: GpButton = 'gp_select'
  readonly GP_other3_DEFAULT: GpButton = 'gp_shoulderl' // Bumper Left
  readonly GP_other4_DEFAULT: GpButton = 'gp_shoulderr' // Bumper Right
  readonly GP_other5_DEFAULT: GpButton = 'gp_shoulderlb' // Trigger Left
  readonly GP_other6_DEFAULT: GpButton = 'gp_shoulderrb' // Trigger Right
  GP_right = this.GP_right_DEFAULT
  GP_left = this.GP_left_DEFAULT
  GP_down = this.GP_down_DEFAULT
  GP_up = this.GP_up_DEFAULT
  GP_magic = this.GP_magic_DEFAULT
  GP_pause = this.GP_pause_DEFAULT
  GP_jump = this.GP_jump_DEFAULT
  GP_attack = this.GP_attack_DEFAULT
  GP_other1 = this.GP_other1_DEFAULT
  GP_other2 = this.GP_other2_DEFAULT
  GP_other3 = this.GP_other3_DEFAULT
  GP_other4 = this.GP_other4_DEFAULT
  GP_other5 = this.GP_other5_DEFAULT
  GP_other6 = this.GP_other6_DEFAULT
  /** Persisted per-controller bindings (`_Input_Preferences` in UserPreferences). */
  dm_UserInputConfig = new DsMap<number | string>()

  // Raw gamepad state this frame (Input_update1): GP_<Button>_{pressed,held,released}
  private gpHeld = new Set<GpButton>()
  private gpPressed = new Set<GpButton>()
  private gpReleased = new Set<GpButton>()
  GP_pressed = false
  GP_held = false
  GP_released = false

  // Mapped gamepad actions (derived from the raw sets through GP_* bindings)
  GP_Right_held = false
  GP_Left_held = false
  GP_Down_held = false
  GP_Up_held = false
  GP_Magic_held = false
  GP_Pause_held = false
  GP_Attack_held = false
  GP_Jump_held = false
  GP_Other1_held = false
  GP_Other2_held = false
  GP_Other3_held = false
  GP_Other4_held = false
  GP_Other5_held = false
  GP_Other6_held = false

  // NES button edges (Input_update2a). Values are the bit ($01..$80) or 0.
  Right_pressed = 0
  Left_pressed = 0
  Down_pressed = 0
  Up_pressed = 0
  Pause_pressed = 0
  Magic_pressed = 0
  Attack_pressed = 0
  Jump_pressed = 0
  Right_released = 0
  Left_released = 0
  Down_released = 0
  Up_released = 0
  Pause_released = 0
  Magic_released = 0
  Attack_released = 0
  Jump_released = 0
  Right_held = 0
  Left_held = 0
  Down_held = 0
  Up_held = 0
  Pause_held = 0
  Magic_held = 0
  Attack_held = 0
  Jump_held = 0
  Other1_pressed = false
  Other1_released = false
  Other1_held = false
  Other2_pressed = false
  Other2_released = false
  Other2_held = false
  Other3_pressed = false
  Other3_released = false
  Other3_held = false
  Other4_pressed = false
  Other4_released = false
  Other4_held = false
  Other5_pressed = false
  Other5_released = false
  Other5_held = false
  Other6_pressed = false
  Other6_released = false
  Other6_held = false

  // Bitmasks (Input_update2b/c/d)
  held = 0
  heldV = 0
  heldH = 0
  heldHV = 0
  heldS = 0
  heldC = 0
  heldSC = 0
  pressed = 0
  pressedV = 0
  pressedH = 0
  pressedHV = 0
  pressedS = 0
  pressedC = 0
  pressedSC = 0
  released = 0
  releasedV = 0
  releasedH = 0
  releasedHV = 0
  releasedS = 0
  releasedC = 0
  releasedSC = 0
  /** what was held previous frame */
  heldPrev = 0
  /** first direction pressed while a direction is held (right/left win over down/up) */
  heldHV_first = 0
  /** held_0 is set to held in PC_spawn(); latched copy that resets on room change */
  held_0 = 0

  /** Keyboard state this frame (the keyboard is always active — see Input_update2a comment). */
  private keys: ReadonlySet<string> = new Set()
  private keysPressed: ReadonlySet<string> = new Set()

  keyboard_check(key: string): boolean {
    return this.keys.has(key)
  }
  keyboard_check_pressed(key: string): boolean {
    return this.keysPressed.has(key)
  }

  /** `gamepad_set_default()` — reset bindings to the Xbox layout and persist for the current controller. */
  gamepad_set_default(): void {
    this.GP_right = this.GP_right_DEFAULT
    this.GP_left = this.GP_left_DEFAULT
    this.GP_down = this.GP_down_DEFAULT
    this.GP_up = this.GP_up_DEFAULT
    this.GP_magic = this.GP_magic_DEFAULT
    this.GP_pause = this.GP_pause_DEFAULT
    this.GP_jump = this.GP_jump_DEFAULT
    this.GP_attack = this.GP_attack_DEFAULT
    this.GP_other1 = this.GP_other1_DEFAULT
    this.GP_other2 = this.GP_other2_DEFAULT
    this.GP_other3 = this.GP_other3_DEFAULT
    this.GP_other4 = this.GP_other4_DEFAULT
    this.GP_other5 = this.GP_other5_DEFAULT
    this.GP_other6 = this.GP_other6_DEFAULT
    // FIDELITY: GML tested `if (gamepad_slot)` which is true for slot -1 (no pad); intent is "a pad is connected".
    if (this.gamepad_slot !== -1 && this.gamepad_name !== undefined) this.saveBindings(this.gamepad_name)
  }

  private saveBindings(gpName: string): void {
    const num = this.dm_UserInputConfig.get(`${gpName}_gamepad_num`)
    if (num === undefined) return
    const dk = `gamepad${typeof num === 'number' ? num.toString(16).toUpperCase().padStart(2, '0') : num}_gp_`
    const m = this.dm_UserInputConfig
    m.set(`${dk}right`, this.GP_right)
    m.set(`${dk}left`, this.GP_left)
    m.set(`${dk}down`, this.GP_down)
    m.set(`${dk}up`, this.GP_up)
    m.set(`${dk}magic`, this.GP_magic)
    m.set(`${dk}pause`, this.GP_pause)
    m.set(`${dk}jump`, this.GP_jump)
    m.set(`${dk}attack`, this.GP_attack)
    m.set(`${dk}other1`, this.GP_other1)
    m.set(`${dk}other2`, this.GP_other2)
    m.set(`${dk}other3`, this.GP_other3)
    m.set(`${dk}other4`, this.GP_other4)
    m.set(`${dk}other5`, this.GP_other5)
    m.set(`${dk}other6`, this.GP_other6)
    this.onPrefsChanged?.()
  }
  /** Hook: `save_game_pref()` — wired by the File singleton. */
  onPrefsChanged: (() => void) | undefined

  /** `Input_update1()` — sample the raw devices for this frame. */
  Input_update1(raw: RawInput): void {
    this.keys = raw.keysHeld
    this.keysPressed = raw.keysPressed
    const gp = raw.gamepad
    this.gamepad_slot = gp?.connected ? 0 : -1
    this.gamepad_name = gp?.connected ? gp.description : undefined
    this.gpHeld = new Set()
    this.gpPressed = new Set()
    this.gpReleased = new Set()
    this.GP_pressed = false
    this.GP_held = false
    this.GP_released = false
    if (!gp?.connected) return
    if (gp.axisCount) {
      for (const b of gp.held) this.gpHeld.add(b)
      for (const b of gp.pressed) this.gpPressed.add(b)
      for (const b of gp.released) this.gpReleased.add(b)
    } else {
      // Unverified (ZALiA): controllers without analog sticks report the d-pad as the left stick.
      for (const b of gp.held) if (!b.startsWith('gp_pad')) this.gpHeld.add(b)
      for (const b of gp.pressed) if (!b.startsWith('gp_pad')) this.gpPressed.add(b)
      for (const b of gp.released) if (!b.startsWith('gp_pad')) this.gpReleased.add(b)
      if (gp.axisLH > 0) this.gpHeld.add('gp_padr')
      if (gp.axisLH < 0) this.gpHeld.add('gp_padl')
      if (gp.axisLV > 0) this.gpHeld.add('gp_padd')
      if (gp.axisLV < 0) this.gpHeld.add('gp_padu')
    }
    this.GP_held = this.gpHeld.size > 0
    this.GP_pressed = this.gpPressed.size > 0
    this.GP_released = this.gpReleased.size > 0
    // mapped actions
    const h = (b: GpButton) => this.gpHeld.has(b)
    this.GP_Right_held = h(this.GP_right)
    this.GP_Left_held = h(this.GP_left)
    this.GP_Down_held = h(this.GP_down)
    this.GP_Up_held = h(this.GP_up)
    this.GP_Magic_held = h(this.GP_magic)
    this.GP_Pause_held = h(this.GP_pause)
    this.GP_Attack_held = h(this.GP_attack)
    this.GP_Jump_held = h(this.GP_jump)
    this.GP_Other1_held = h(this.GP_other1)
    this.GP_Other2_held = h(this.GP_other2)
    this.GP_Other3_held = h(this.GP_other3)
    this.GP_Other4_held = h(this.GP_other4)
    this.GP_Other5_held = h(this.GP_other5)
    this.GP_Other6_held = h(this.GP_other6)
  }

  /** Raw gamepad button query for menus (`gamepad_button_check_pressed(gamepad_slot, b)`). */
  gamepad_button_check_pressed(b: GpButton): boolean {
    return this.gpPressed.has(b)
  }
  gamepad_button_check(b: GpButton): boolean {
    return this.gpHeld.has(b)
  }

  /**
   * `Input_update2()` minus the overworld-pause toggle, which needs `g` and is applied by the caller
   * (`Input_update2_overworldPause`). C132.
   */
  Input_update2(): void {
    this.heldPrev = this.held // store what was held previous frame
    this.Input_update2a()
    this.Input_update2b()
    this.Input_update2c()
    this.Input_update2d()
    if (this.pressedHV && !this.heldHV_first) {
      if (this.pressedHV & 0x3)
        this.heldHV_first = this.pressedHV & 0x3 // right/left
      else this.heldHV_first = this.pressedHV & 0xc // down/up
    } else if (!this.heldHV) this.heldHV_first = 0
  }

  /** Second half of `Input_update2()`: `held_0` latch. Called by the game loop with `g.ChangeRoom_timer`. */
  Input_update2_held0(changeRoomTimer: number): void {
    if (changeRoomTimer > 0) this.held_0 = 0
    else if (this.held_0) this.held_0 = this.held
  }

  /** `Input_update2a()` — resolve keyboard + mapped gamepad into NES button edges. */
  Input_update2a(): void {
    // Temporary until controller support is implemented. Certain players need the keyboard inputs so
    // they can bind controller buttons through 3rd party controller support app.
    // Rebindable (ZALiA TODO completed): defaults are the GML's literal keys (D/→, A/←, S/↓, W/↑, Enter, T, Ctrl, Space).
    const key = (a: KeyAction) => keyboardBindings[a].some((k) => this.keys.has(k))
    const _R_KEY = key('right')
    const _L_KEY = key('left')
    const _D_KEY = key('down')
    const _U_KEY = key('up')
    const _S_KEY = key('pause')
    const _E_KEY = key('magic')
    const _B_KEY = key('attack')
    const _A_KEY = key('jump')
    const { R, L, D, U, S, E, B, A } = this
    const _R_NEW = R * +(this.GP_Right_held || _R_KEY) // $01 NES d-pad  RIGHT
    const _L_NEW = L * +(this.GP_Left_held || _L_KEY) // $02 NES d-pad  LEFT
    const _D_NEW = D * +(this.GP_Down_held || _D_KEY) // $04 NES d-pad  DOWN
    const _U_NEW = U * +(this.GP_Up_held || _U_KEY) // $08 NES d-pad  UP
    const _S_NEW = S * +(this.GP_Pause_held || _S_KEY) // $10 NES button START
    const _E_NEW = E * +(this.GP_Magic_held || _E_KEY) // $20 NES button SELECT
    const _B_NEW = B * +(this.GP_Attack_held || _B_KEY) // $40 NES button B
    const _A_NEW = A * +(this.GP_Jump_held || _A_KEY) // $80 NES button A
    // Pressed
    this.Right_pressed = R * +(!!_R_NEW && !this.Right_held)
    this.Left_pressed = L * +(!!_L_NEW && !this.Left_held)
    this.Down_pressed = D * +(!!_D_NEW && !this.Down_held)
    this.Up_pressed = U * +(!!_U_NEW && !this.Up_held)
    this.Pause_pressed = S * +(!!_S_NEW && !this.Pause_held)
    this.Magic_pressed = E * +(!!_E_NEW && !this.Magic_held)
    this.Attack_pressed = B * +(!!_B_NEW && !this.Attack_held)
    this.Jump_pressed = A * +(!!_A_NEW && !this.Jump_held)
    // Released
    this.Right_released = R * +(!_R_NEW && !!this.Right_held)
    this.Left_released = L * +(!_L_NEW && !!this.Left_held)
    this.Down_released = D * +(!_D_NEW && !!this.Down_held)
    this.Up_released = U * +(!_U_NEW && !!this.Up_held)
    this.Pause_released = S * +(!_S_NEW && !!this.Pause_held)
    this.Magic_released = E * +(!_E_NEW && !!this.Magic_held)
    this.Attack_released = B * +(!_B_NEW && !!this.Attack_held)
    this.Jump_released = A * +(!_A_NEW && !!this.Jump_held)
    // Held.  *** Held MUST be AFTER Pressed and Released
    this.Right_held = _R_NEW
    this.Left_held = _L_NEW
    this.Down_held = _D_NEW
    this.Up_held = _U_NEW
    this.Pause_held = _S_NEW
    this.Magic_held = _E_NEW
    this.Attack_held = _B_NEW
    this.Jump_held = _A_NEW
    // Xbox B/Y, bumpers, triggers
    this.Other1_pressed = this.GP_Other1_held && !this.Other1_held
    this.Other1_released = !this.GP_Other1_held && this.Other1_held
    this.Other1_held = this.GP_Other1_held
    this.Other2_pressed = this.GP_Other2_held && !this.Other2_held
    this.Other2_released = !this.GP_Other2_held && this.Other2_held
    this.Other2_held = this.GP_Other2_held
    this.Other3_pressed = this.GP_Other3_held && !this.Other3_held
    this.Other3_released = !this.GP_Other3_held && this.Other3_held
    this.Other3_held = this.GP_Other3_held
    this.Other4_pressed = this.GP_Other4_held && !this.Other4_held
    this.Other4_released = !this.GP_Other4_held && this.Other4_held
    this.Other4_held = this.GP_Other4_held
    this.Other5_pressed = this.GP_Other5_held && !this.Other5_held
    this.Other5_released = !this.GP_Other5_held && this.Other5_held
    this.Other5_held = this.GP_Other5_held
    this.Other6_pressed = this.GP_Other6_held && !this.Other6_held
    this.Other6_released = !this.GP_Other6_held && this.Other6_held
    this.Other6_held = this.GP_Other6_held
  }

  private masks(r: number, l: number, d: number, u: number, s: number, e: number, b: number, a: number) {
    const all = r | l | d | u | s | e | b | a
    return { all, V: d | u, H: r | l, HV: r | l | d | u, S: s | e, C: b | a, SC: s | e | b | a }
  }

  /** `Input_update2b()` — held, heldV, heldH, heldHV, heldS, heldC, heldSC */
  Input_update2b(): void {
    const m = this.masks(
      this.Right_held,
      this.Left_held,
      this.Down_held,
      this.Up_held,
      this.Pause_held,
      this.Magic_held,
      this.Attack_held,
      this.Jump_held,
    )
    this.held = m.all
    this.heldV = m.V
    this.heldH = m.H
    this.heldHV = m.HV
    this.heldS = m.S
    this.heldC = m.C
    this.heldSC = m.SC
  }

  /** `Input_update2c()` — pressed masks */
  Input_update2c(): void {
    const m = this.masks(
      this.Right_pressed,
      this.Left_pressed,
      this.Down_pressed,
      this.Up_pressed,
      this.Pause_pressed,
      this.Magic_pressed,
      this.Attack_pressed,
      this.Jump_pressed,
    )
    this.pressed = m.all
    this.pressedV = m.V
    this.pressedH = m.H
    this.pressedHV = m.HV
    this.pressedS = m.S
    this.pressedC = m.C
    this.pressedSC = m.SC
  }

  /** `Input_update2d()` — released masks */
  Input_update2d(): void {
    const m = this.masks(
      this.Right_released,
      this.Left_released,
      this.Down_released,
      this.Up_released,
      this.Pause_released,
      this.Magic_released,
      this.Attack_released,
      this.Jump_released,
    )
    this.released = m.all
    this.releasedV = m.V
    this.releasedH = m.H
    this.releasedHV = m.HV
    this.releasedS = m.S
    this.releasedC = m.C
    this.releasedSC = m.SC
  }
}
