// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively

import { gmBool } from '../../../nes/math8'
import { is_ancestor_ } from '../../other/index'

/** GML: g_Room_Start_1b(object) */
export function g_Room_Start_1b(...argument: any[]) {
  // GML `var` is function-scoped; locals hoisted here:
  let _OBJECT: any
  _OBJECT = argument[0]
  if (gmBool(_OBJECT) && !gmBool(is_ancestor_(_OBJECT, 'Item', 'Torch'))) {
    if (
      gmBool(is_ancestor_(_OBJECT, 'Spawner_Boggnipp', 'SpDrA', 'Spawner_FallingBlock', 'SpawnerStab')) ||
      gmBool(
        is_ancestor_(
          _OBJECT,
          'ElevA',
          'LoDoA',
          'ReFaA',
          'BlckB',
          'SpikeTrap',
          'Switch',
          'PushA',
          'Blooby',
          'Eyenocc',
          'SmasherTrap',
        ),
      ) ||
      gmBool(is_ancestor_(_OBJECT, 'Bagin01', 'Balshot01', 'Boggnipp01', 'MagnA', 'Snaraa'))
    ) {
      return true
    }
  }
  return false
}
