/** Body / shield / sword hitbox maintenance for game objects and the player. */
import { BIT_ATK1, BIT_ATK2, BIT_ATK3, BODY_HB_IDX_DYNAMIC, ITM_SWRD } from '@z2/data'
import { gmBool, inRange } from '../math'
import { hasObjectClass, is_ancestor_ } from '../other'
import type { GoBody, PcBody } from './body'
import { env, viewXL } from './env'

/** `is_ancestor` against a class that may not be ported yet — an unregistered object is never that kind. */
export function isKind(self: { objectName: string }, ...names: string[]): boolean {
  const known = names.filter(hasObjectClass)
  return known.length > 0 && is_ancestor_(self as never, ...known)
}

/** `update_body_hb()` */
export function update_body_hb(self: GoBody): void {
  self.BodyHB_xl = self.xl + self.BodyHB_xoff
  self.BodyHB_xr = self.BodyHB_xl + self.BodyHB_w
  self.BodyHB_yt = self.yt + self.BodyHB_yoff
  self.BodyHB_yb = self.BodyHB_yt + self.BodyHB_h
}

/** `update_body_hb_1a()` — load the hitbox row from `g.dg_BODY_HB` (E8FA-E941) and position it. */
export function update_body_hb_1a(self: GoBody): void {
  // BodyHB_idx. 0: row 0 is all 0,  BODY_HB_IDX_DYNAMIC (-2): inst sets its box manually in its update.
  // GML truthiness: `!BodyHB_idx` is true for 0, -1 *and* -2, so a manually maintained box is preserved.
  // With JS truthiness the negatives fell through and `dg_BODY_HB.get(-1|-2, …) ?? 0` zeroed the box: the
  // player fell through every cloud platform (`PlatformCloud_update` sets its own box) and Gellzem and
  // Growkke could not be hit at all.
  if (!gmBool(self.BodyHB_idx)) {
    self.BodyHB_can_draw = self.BodyHB_idx !== BODY_HB_IDX_DYNAMIC
    return
  }
  if (isKind(self, 'ProjectileHostile')) self.BodyHB_can_draw = true
  else self.BodyHB_can_draw = self.state === self.state_NORMAL
  const g = env.game()
  self.BodyHB_xoff = g.dg_BODY_HB.get(self.BodyHB_idx, 0) ?? 0
  self.BodyHB_yoff = g.dg_BODY_HB.get(self.BodyHB_idx, 1) ?? 0
  self.BodyHB_w = g.dg_BODY_HB.get(self.BodyHB_idx, 2) ?? 0
  self.BodyHB_h = g.dg_BODY_HB.get(self.BodyHB_idx, 3) ?? 0
  self.BodyHB_r = g.dg_BODY_HB.get(self.BodyHB_idx, 4) ?? 0 // radius
  update_body_hb(self)
}

/** `update_body_hb_2a()` */
export function update_body_hb_2a(self: GoBody): void {
  self.BodyHB_can_draw = self.state === self.state_NORMAL
  update_body_hb(self)
}

/** `update_body_hb_3a()` — hitbox relative to x/y instead of xl/yt. */
export function update_body_hb_3a(self: GoBody): void {
  self.BodyHB_can_draw = self.state === self.state_NORMAL
  self.BodyHB_xl = self.x + self.BodyHB_xoff
  self.BodyHB_xr = self.BodyHB_xl + self.BodyHB_w
  self.BodyHB_yt = self.y + self.BodyHB_yoff
  self.BodyHB_yb = self.BodyHB_yt + self.BodyHB_h
}

/** `update_shield_hb()` */
export function update_shield_hb(self: GoBody): void {
  self.ShieldHB_can_draw = true
  self.ShieldHB_x = self.xl + self.ShieldHB_xoff
  self.ShieldHB_y = self.yt + self.ShieldHB_yoff
}

/** `qual_SwordHB_xoff_bug()` — PC facing right with xl inside the page to the left (OG sword x-offset bug). */
export function qual_SwordHB_xoff_bug(pc: PcBody): boolean {
  return gmBool(pc.x_scale_prev) && (pc.x_prev & 0xff) < 0x18
}

/**
 * `PC_update_sword_hb()` — sword hitbox from the previous frame's position (1-frame lag as in OG:
 * swrdX_base/swrdY_base/swrd_collidable are set at the very end of the update).
 */
export function PC_update_sword_hb(): void {
  const pc = env.pc()
  const g = env.game()
  const f = env.file()
  const DIST1 = 8
  pc.SwordHB_w_ = pc.SwordHB_w >> 1
  pc.SwordHB_h_ = pc.SwordHB_h >> 1
  if (pc.attack_bits & (BIT_ATK1 | BIT_ATK2)) {
    // high & low stab
    pc.SwordHB_xoff = (DIST1 + pc.SwordHB_w_) * pc.x_scale_prev - pc.SwordHB_w_
  } else if (pc.attack_bits & BIT_ATK3)
    pc.SwordHB_xoff = -1 - pc.SwordHB_w_ // down thrust
  else if (gmBool(pc.x_scale_prev))
    pc.SwordHB_xoff = 3 - pc.SwordHB_w_ // up thrust right
  else pc.SwordHB_xoff = -9 - pc.SwordHB_w_ // up thrust left
  if (!g.mod_fix_og_swordhb_exploit && qual_SwordHB_xoff_bug(pc) && !(f.items & ITM_SWRD)) {
    pc.SwordHB_xoff += 2
  }
  if (pc.behavior === pc.behavior_STAB_DOWN || pc.behavior === pc.behavior_STAB_UP) pc.SwordHB_yoff = 0
  else pc.SwordHB_yoff = 7
  pc.SwordHB_xoff += g.HB_ADJ_X
  pc.SwordHB_yoff += g.HB_ADJ_Y
  // view_xl_dist (= x - viewXL()) is updated at the end of the main update, so it is last frame's x.
  pc.SwordHB_x = viewXL() + pc.view_xl_dist + pc.SwordHB_xoff // XL of the hitbox
  pc.SwordHB_y = pc.SwordHB_y_base + pc.SwordHB_yoff // YT of the hitbox
  pc.SwordHB_can_draw = pc.SwordHB_collidable
  pc.SwordHB2_collidable = pc.SwordHB_collidable && !!(pc.attack_bits & (BIT_ATK1 | BIT_ATK2))
  pc.SwordHB2_can_draw = pc.SwordHB2_collidable
  if (pc.is_cucco) {
    pc.SwordHB2_w = pc.Cucco_SwordHB_W
    pc.SwordHB2_h = pc.Cucco_SwordHB_H
  } else {
    pc.SwordHB2_w = pc.SwordHB2_W
    pc.SwordHB2_h = pc.SwordHB2_H
  }
  const w2_ = pc.SwordHB2_w >> 1
  const YOFF = 3 // added height
  if (pc.attack_bits & (BIT_ATK1 | BIT_ATK2)) pc.SwordHB2_h += YOFF
  const XOFF = (DIST1 + w2_) * pc.x_scale_prev - w2_
  pc.SwordHB2_xl = viewXL() + pc.view_xl_dist + XOFF
  pc.SwordHB2_yt = pc.y_prev + pc.SwordHB2_YOFF // stabType. 0: low, 1: high
  pc.SwordHB2_yt += 10 * Math.sign(pc.attack_bits & BIT_ATK2)
  if (pc.attack_bits & BIT_ATK2) pc.SwordHB2_yt -= YOFF
}

/** `PC_update_shield_hb()` — `dHeld` is the Input down-held flag (passed in: `input.Down_held`). */
export function PC_update_shield_hb(downHeld: boolean): void {
  const pc = env.pc()
  let IDX = pc.ShieldHB_IDX
  if (pc.is_cucco) IDX = pc.Cucco_ShieldHB_IDX
  else if (pc.is_fairy) IDX = pc.Fairy_ShieldHB_IDX
  const t = (col: number) => pc.dg_ShieldHB.get(IDX, col) ?? 0
  if (gmBool(pc.xScale)) pc.ShieldHB_xoff = t(pc.ShieldHB_IDX_XOFF_RIGHT)
  else pc.ShieldHB_xoff = t(pc.ShieldHB_IDX_XOFF_LEFT)
  const CROUCHING = (!pc.is_cucco && downHeld) || (pc.is_cucco && pc.Cucco_crouching_state)
  pc.ShieldHB_yoff = !CROUCHING ? t(pc.ShieldHB_IDX_YOFF_STAND) : t(pc.ShieldHB_IDX_YOFF_CROUCH)
  pc.ShieldHB_h = !CROUCHING ? t(pc.ShieldHB_IDX_H1) : t(pc.ShieldHB_IDX_H2)
  pc.ShieldHB_w = t(pc.ShieldHB_IDX_W1)
  pc.ShieldHB_collidable = true
  if (pc.is_cucco) {
    pc.ShieldHB_collidable = false
    pc.ShieldHB_w = 0
    pc.ShieldHB_h = 0
  }
  update_shield_hb(pc)
  if (pc.is_cucco && pc.attack_bits & (BIT_ATK1 | BIT_ATK2)) {
    pc.ShieldHB_collidable = true
    pc.ShieldHB_h = !CROUCHING ? t(pc.ShieldHB_IDX_H1) : t(pc.ShieldHB_IDX_H2)
    pc.ShieldHB_w = 0xc
    pc.ShieldHB_x = 4 + (pc.ShieldHB_w >> 1)
    pc.ShieldHB_x = pc.x + pc.ShieldHB_x * pc.xScale
    pc.ShieldHB_x -= pc.ShieldHB_w >> 1
    pc.ShieldHB_y = pc.yt + pc.ShieldHB_yoff
  }
}

/** `PC_update_body_offsets()` — pick the body hitbox row for stand/crouch/cucco/fairy. */
export function PC_update_body_offsets(downHeld: boolean): void {
  const pc = env.pc()
  if (env.fn.pc_is_cucco())
    pc.BodyHB_idx = pc.Cucco_crouching_state ? pc.Cucco_BodyHB_IDX2 : pc.Cucco_BodyHB_IDX1
  else if (env.fn.pc_is_fairy()) pc.BodyHB_idx = pc.Fairy_BodyHB_IDX1
  else pc.BodyHB_idx = downHeld ? pc.BodyHB_IDX2 : pc.BodyHB_IDX1
}

/** `PC_update_hitboxes_1a()` */
export function PC_update_hitboxes_1a(downHeld: boolean): void {
  PC_update_body_offsets(downHeld) // sets body_hb_idx
  update_body_hb_1a(env.pc())
  PC_update_shield_hb(downHeld)
  PC_update_sword_hb()
}

/** `GO_can_collide_this_frame(uIdx)` — odd slots on even frames, even slots on odd frames. */
export function GO_can_collide_this_frame(uIdx: number): boolean {
  const c = env.game().counter1
  return (!!(uIdx & 0x1) && !(c & 0x1)) || (!(uIdx & 0x1) && !!(c & 0x1))
}

/** `GOB_update_sword_hb_1a()` */
export function GOB_update_sword_hb_1a(self: GoBody): void {
  self.SwordHB_collidable = true
  self.SwordHB_x = self.xl + self.SwordHB_xoff
  self.SwordHB_y = self.yt + self.SwordHB_yoff
}

/** `GOB_update_sword_offsets()` — per-enemy sword hitbox offsets (OG tables). */
export function GOB_update_sword_offsets(self: GoBody): void {
  const facingRight = gmBool(self.facing_dir)
  if (isKind(self, 'DairA')) {
    self.SwordHB_xoff = (self.SwordHB_XOFF ?? 0) * self.facing_dir
    self.SwordHB_yoff = self.SwordHB_YOFF ?? 0
  } else if (isKind(self, 'FokkA', 'IrKnA', 'Rebonack01B')) {
    // OG: since swrdW = 14, an equal abs(xoff) for both facing dirs gives facing left 2 px extra reach.
    // Only called for BVR_ATKH: 2, BVR_ATKL: 4
    self.SwordHB_xoff = (self.SwordHB_XOFF ?? 0) << +inRange(self.timer, 3, 12) // $08,$10
    self.SwordHB_xoff *= self.facing_dir
    // IrKnA & Rebonack01B at certain points don't clear the carry like Fokka does.
    // facing right: 8, 16, 9 / facing left: -8, -15, -7
    if (isKind(self, 'IrKnA', 'Rebonack01B')) {
      if (self.timer >= 13 || (self.timer >= 3 && !facingRight)) self.SwordHB_xoff++
    }
    self.SwordHB_yoff = self.behavior === (self.BVR_ATKL ?? 0) ? 25 : 9
  } else if (isKind(self, 'GeruA')) {
    // 9F35
    self.SwordHB_xoff = (self.SwordHB_XOFF ?? 0) * self.facing_dir // 6
    if (self.ver === 2 || inRange(self.timer, 3, 8)) self.SwordHB_xoff *= 2 // v2 Geru red
    // 9F4F, 9F57, E5F5
    self.SwordHB_yoff = self.SwordHB_YOFF ?? 0
    if (self.behavior === 5) self.SwordHB_yoff += 8 // Low atk. Lance Geru (orange)
  } else if (isKind(self, 'MoblA', 'MoblB')) {
    // Moblin & Grunt
    if (self.behavior & 1 || (self.behavior === 2 && self.timer < 8))
      self.SwordHB_xoff = (self.SwordHB_XOFF1 ?? 0) * -self.facing_dir // 4
    else self.SwordHB_xoff = (self.SwordHB_XOFF2 ?? 0) * self.facing_dir // 8
    if (inRange(self.timer, 3, 12)) self.SwordHB_xoff *= 2
    self.SwordHB_yoff = self.SwordHB_YOFF ?? 0
    if (self.behavior < 3) self.SwordHB_yoff += 8
  } else if (isKind(self, 'StalA')) {
    // BE66
    self.SwordHB_xoff = (self.SwordHB_XOFF ?? 0) * self.facing_dir
    self.SwordHB_yoff = self.SwordHB_YOFF ?? 0
  } else if (isKind(self, 'Horsehead01')) {
    if (self.attack_state ?? 0) {
      // 983B (in sprite update). SwordHB_XOFF = 16 + g.HB_ADJ_X
      self.SwordHB_xoff =
        self.attack_state === (self.attack_state_SWING ?? 0)
          ? (self.SwordHB_XOFF ?? 0) * self.facing_dir
          : -(self.SwordHB_XOFF ?? 0) * self.facing_dir
      self.SwordHB_yoff = (self.SwordHB_YOFF ?? 0) + 9 // SwordHB_YOFF = 16 + g.HB_ADJ_Y
    }
  } else if (isKind(self, 'Rebonack01A')) {
    // updated in usd_RebonackA()
  }
}

/** `GOB_update_shield_offsets()` — E5BA shield tables (`g.dg_ShieldHB`); $FF = use the body hitbox. */
export function GOB_update_shield_offsets(self: GoBody): void {
  const g = env.game()
  if (!inRange(self.ShieldHB_idx, 0, g.dg_ShieldHB.width - 1) && self.ShieldHB_idx !== 0xff) return
  if (self.ShieldHB_idx === 0xff) {
    self.ShieldHB_xoff = self.BodyHB_xoff
    self.ShieldHB_yoff = self.BodyHB_yoff
    self.ShieldHB_w = self.BodyHB_w
    self.ShieldHB_h = self.BodyHB_h
  } else {
    const t = (col: number) => g.dg_ShieldHB.get(self.ShieldHB_idx, col) ?? 0
    self.ShieldHB_xoff = t(gmBool(self.facing_dir) ? 0 : 1) // xoff RGT(0), LFT(1)
    self.ShieldHB_yoff = t(2)
    self.ShieldHB_w = t(3)
    self.ShieldHB_h = t(4)
  }
  // 0005 shldYOff: E59C-E5A2: 12 00 05 10 05 02 02 / 0007 shldH: E5A3-E5A9: 08 0D 20 10 20 0D 10
  // 0004 shldXOff: E5AA-E5B0: 00 00 00 FC 00 FF 02 / 0006 shldW: E5B1-E5B7: 02 02 10 18 0F 12 14
}
