/** Registers the 21 classes and their scripts. Idempotent; tests call it again after registry resets. */
export function registerProjectileHostile(): void {
  // `data_go_scr` gives every ProjectileHostile row `Projectile_init` as its ini1 (goc root script)
  registerScripts({ Projectile_init } as Record<string, (self: never) => unknown>)
  for (const [name, cls] of Object.entries(PROJECTILE_HOSTILE_CLASSES))
    registerObject(name as keyof typeof PROJECTILE_HOSTILE_CLASSES, cls)
  registerScripts(projectileHostileScripts as Record<string, (self: never) => unknown>)
}
registerProjectileHostile()
