/** RNG access for projectile scripts: GML `irandom()` (world PRNG) and `rand()` (OG shift register by slot). */
import { world } from '../../../../runtime/world'
import type { GameObject } from '../../classes'

export const rand = {
  irandom: (n: number): number => world.irandom(n),
  /** `rand()` — the OG random byte for this instance's update slot (falls back to irandom($FF)). */
  og: (self: GameObject): number => world.ogRandom.rand(self.update_idx, () => world.irandom(0xff)),
}
