/** `Stallakk` — ZALiA `enemy/stallakk`: added enemy; paces, then charges with an arm-forward hitbox. */
import { CS_BD1, CS_PR1, CS_SW1 } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { g, world } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { hINh } from '../../../../../collision/geometry'
import { GOB_sword_collision_1a } from '../../../../../collision/gob'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { registerObjectClass } from '../../../../../other/registry'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { Enemy } from '../../../../classes'
import { GO_draw_sprite } from '../../../../go/draw'
import { dir_to_pc_, GO_update_cam_vars } from '../../../../go/misc'
import { updateX, updateY } from '../../../../go/movement'
import { solid_clip_correction } from '../../../../goa/movement'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import {
  GameObjectB_init,
  GOB_despawn,
  GOB_is_out_of_bounds_y,
  GOB_update_1,
  GOB_update_2a,
  update_EF11,
} from '../../../GameObjectB'

export class Stallakk extends Enemy {
  readonly objectName = 'Stallakk' as const
  sub_state_IDLE1 = 1
  sub_state_IDLE2 = 2
  sub_state_ATTACK0 = 3
  sub_state_ATTACK = 4
  sub_state = 1
  Top_SPR1: string = 'spr_Stallakk_Top_1a'
  Top_SPR2: string = 'spr_Stallakk_Top_1b'
  Top_spr: string = 'spr_Stallakk_Top_1a'
  Btm_SPR1: string = 'spr_Stallakk_Bottom_1a'
  Btm_SPR2: string = 'spr_Stallakk_Bottom_1b'
  Btm_spr: string = 'spr_Stallakk_Bottom_1a'
  Idle_HSPD = 0x08
  Idle_Still_DUR = 0x80
  Idle_Still_DUR2 = 0x60
  Idle_Move_DUR = 0xc0
  Attack_DIST = 0x60
  Attack_HSPD = 0x0c
  Attack_Delay_DUR = 0x08
  VSPD_GRAV = 2
  SwordHB_W = 13
  SwordHB_H = 2
  SwordHB_XOFF = 14
  SwordHB_YOFF = 9
}
registerObject('Stallakk', Stallakk)
registerObjectClass('Stallakk', Stallakk)

/** `Stallakk_init1()` */
export function Stallakk_init1(self: Stallakk): void {
  GameObjectB_init(self)
  let _a = 1
  self.sub_state_IDLE1 = _a++
  self.sub_state_IDLE2 = _a++
  self.sub_state_ATTACK0 = _a++
  self.sub_state_ATTACK = _a++
  self.sub_state = self.sub_state_IDLE1
  self.Top_SPR1 = 'spr_Stallakk_Top_1a' // idle
  self.Top_SPR2 = 'spr_Stallakk_Top_1b' // attack
  self.Top_spr = self.Top_SPR1
  self.Btm_SPR1 = 'spr_Stallakk_Bottom_1a' // legs closed
  self.Btm_SPR2 = 'spr_Stallakk_Bottom_1b' // legs open
  self.Btm_spr = self.Btm_SPR1
  self.Idle_HSPD = 0x08
  self.Idle_Still_DUR = 0x80
  self.Idle_Still_DUR2 = self.Idle_Still_DUR - (self.Idle_Still_DUR >> 2)
  self.Idle_Move_DUR = 0xc0
  self.Attack_DIST = 0x60
  self.Attack_HSPD = self.Idle_HSPD + 0x04
  self.Attack_Delay_DUR = 0x08
  switch (self.sub_state) {
    case self.sub_state_IDLE1:
      self.timer = self.Idle_Still_DUR
      break
    case self.sub_state_IDLE2:
      self.timer = self.Idle_Move_DUR
      break
  }
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  // arm forward hb (copy of Stalfos swrd hb)
  self.SwordHB_W = 13
  self.SwordHB_H = 2
  self.SwordHB_XOFF = self.SwordHB_W + 1
  self.SwordHB_YOFF = 9
  self.SwordHB_xoff = self.SwordHB_XOFF * self.facing_dir
  self.SwordHB_yoff = self.SwordHB_YOFF
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
}

/** `Stallakk_init2()` — empty in ZALiA. */
export function Stallakk_init2(_self: Stallakk): void {}

/** `Stallakk_udp()` */
export function Stallakk_udp(self: Stallakk): void {
  self.can_draw_self = true
  switch (self.sub_state) {
    case self.sub_state_IDLE1:
      self.Top_spr = self.Top_SPR1
      self.Btm_spr = self.Btm_SPR1
      break
    case self.sub_state_IDLE2:
    case self.sub_state_ATTACK0:
      self.Top_spr = self.Top_SPR1
      if (g.counter1 & 0x10)
        self.Btm_spr = self.Btm_SPR1 // legs closed
      else if (gmBool(self.hspd)) self.Btm_spr = self.Btm_SPR2 // legs open
      break
    case self.sub_state_ATTACK:
      self.Top_spr = self.Top_SPR2
      if (g.counter1 & 0x08) self.Btm_spr = self.Btm_SPR1
      else if (gmBool(self.hspd)) self.Btm_spr = self.Btm_SPR2
      break
  }
}

/** `Stallakk_update()` */
export function Stallakk_update(self: Stallakk): void {
  const P = pc()
  GO_update_cam_vars(self)
  update_EF11(self)
  // Same as OG: if (yy > $FF)
  if (GOB_is_out_of_bounds_y(self)) {
    GOB_despawn(self) // DD3D
    return
  }
  if (self.sub_state === self.sub_state_ATTACK) {
    self.SwordHB_xoff = self.x
    self.SwordHB_xoff += (self.SwordHB_w >> 1) * self.facing_dir
    self.SwordHB_xoff -= self.SwordHB_w >> 1
    self.SwordHB_xoff -= self.xl
    self.SwordHB_yoff = self.SwordHB_YOFF
    GOB_sword_collision_1a(self) // handles GOB SWRD to PC BODY collision check & reaction
  }
  GOB_update_2a(self) // DE54 & DE63 collision
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  GO_update_cs(self)
  if (self.cs & 0x04) {
    GOB_update_1(self, true) // update hspdPB
    GO_update_cs(self)
  }
  if (!(self.cs & 0x03)) updateX(self)
  if (self.cs & 0x04) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  }
  updateY(self)
  if (self.state !== self.state_NORMAL) return
  if (self.sub_state === self.sub_state_IDLE1 || self.sub_state === self.sub_state_IDLE2) {
    let _C1: boolean | number = self.cs & (CS_SW1 | CS_PR1)
    if (!gmBool(_C1)) {
      _C1 =
        self.facing_dir === dir_to_pc_(self) &&
        Math.abs(self.x - P.x) <= self.Attack_DIST &&
        hINh(self.yt, self.hh, P.yt - 0x04, P.hh + 0x08)
    }
    if (gmBool(_C1)) {
      self.timer = self.Attack_Delay_DUR // $08
      self.sub_state = self.sub_state_ATTACK0
    }
  }
  switch (self.sub_state) {
    case self.sub_state_IDLE1: {
      // Stand still
      self.hspd = 0
      if (self.timer === 0x08) self.facing_dir = -self.facing_dir
      if (gmBool(self.timer)) break
      if (!(self.cs & 0x04)) break
      self.timer = self.Idle_Move_DUR
      self.sub_state = self.sub_state_IDLE2
      break
    }
    case self.sub_state_IDLE2: {
      // Walk/Pace
      self.hspd = (self.Idle_HSPD * self.facing_dir) & 0xff
      if (gmBool(self.timer)) break
      if (!(self.cs & 0x04)) break
      if (gmBool(world.irandom(1))) self.timer = self.Idle_Still_DUR
      else self.timer = self.Idle_Still_DUR2 // shorter duration
      self.sub_state = self.sub_state_IDLE1
      break
    }
    case self.sub_state_ATTACK0: {
      // attack delay
      if (gmBool(self.timer)) break
      self.facing_dir = dir_to_pc_(self)
      if (!(self.cs & 0x04)) break
      self.timer = 0
      self.sub_state = self.sub_state_ATTACK
      break
    }
    case self.sub_state_ATTACK: {
      if (gmBool(self.timer)) break
      if (!(g.counter1 & 0x3f)) self.facing_dir = dir_to_pc_(self)
      self.hspd = (self.Attack_HSPD * self.facing_dir) & 0xff
      break
    }
  }
}

/** `Stallakk_draw()` */
export function Stallakk_draw(self: Stallakk): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  GO_draw_sprite(self, self.Btm_spr)
  GO_draw_sprite(self, self.Top_spr)
  pal_swap_reset()
}

registerScripts({ Stallakk_init1, Stallakk_init2, Stallakk_update, Stallakk_udp, Stallakk_draw })
