// FIXED: `ELEV_H` is the project macro `PC_H + $10` = 48, not `$20`. At 32 the body sprite sat 24 px too
// high (`BODY_SPR_YOFF`) and two of the five chain links were missing, while collision still used 48.

/** `Elevator_end()` */
export function Elevator_end(self: ElevatorObject): void {
  self.dl_exit = undefined
}

/** `ElevatorA_init1()` */
export function ElevatorA_init1(self: ElevatorObject): void {
  GameObjectB_init(self)
  ElevatorA_init_1(self)
}

/** `Elevator_init2()` */
export function Elevator_init2(self: ElevatorObject): void {
  const P = pc()
  let _exit_data: string | number = 0
  if (self.dk_spawn !== undefined) {
    self.spawn_xl = ((val(g.dm_spawn.get(`${self.dk_spawn}_x`), g.rm_clms >> 1) as number) << 3) - self.ww_
    self.spawn_yt = (val(g.dm_spawn.get(`${self.dk_spawn}_y`), g.rm_rows >> 1) as number) << 3
    set_xlyt(self, self.spawn_xl, self.spawn_yt)
    _exit_data = val(g.dm_spawn.get(self.dk_spawn + STR_ExitData)) as string | number
  }
  self.facing_dir = 1
  // ---------------------------------------------------------
  self.dl_exit = new DsList<Ref<GameObject> | 0>()
  self.dl_exit.add(0)
  self.exit_dirs = 0x0
  if (self.dk_spawn !== undefined && g.dm_spawn.get(self.dk_spawn + STR_ExitData) !== undefined) {
    // _data = "": Means Elevator has solid tiles above and below it and is just meant to move up & down through the room.
    if (_exit_data === 0) {
      // if elevator is confined in scene and doesn't go to an exit
      let _yt: number
      if (P.y < self.y) {
        _yt = find_row_solid(TID_SOLID1, (self.x >> 3) << 3, self.y >> 3, -1, -1, self.yt >> 3)
        _yt = _yt << 3
      } else {
        _yt = get_ground_y(self.x, self.yb, 1, self.yt)
        _yt -= self.hh
      }
      self.spawn_yt = _yt
      set_xlyt(self, self.spawn_xl, self.spawn_yt)
    } else {
      const data = String(_exit_data)
      const _COUNT = data.length >> 1
      for (let _i = 0; _i < _COUNT; _i++) {
        // Each exit of the ElevA shaft
        let _exit: Exit | 0 = 0
        const _exit_num = str_hex(data.substr(_i << 1, 2))
        for (const e of world.instancesOf(Exit)) {
          if (e.exitNum !== _exit_num) continue
          _exit = e
          break
        }
        if (!_exit) continue
        self.exit_dirs |= _exit.side & 0xf
        self.dl_exit.add(_exit)
        if (_exit === g.exit_enter) {
          let _xl = self.xl
          let _yt = self.yt
          const _OFFSET = 0x02 << 3 // MOD. For auto elevator on enter rm
          switch (_exit.side & 0xf) {
            case 0x1:
              _xl = cam_xr_max() + _OFFSET - self.ww
              break
            case 0x2:
              _xl = cam_xl_min() - _OFFSET
              break
            case 0x4:
              _yt = cam_yb_max() + _OFFSET - self.hh
              break
            case 0x8:
              _yt = cam_yt_min() - _OFFSET
              break
          }
          self.spawn_xl = _xl
          self.spawn_yt = _yt
          set_xlyt(self, self.spawn_xl, self.spawn_yt)
        }
      }
    }
  }
  // Trying different method for positioning
  if (g.exit_enter && self.dk_spawn !== undefined && _exit_data === 0) {
    // 0 means the elevator is confined w/in the scene and doesn't go to an exit
    let _i = 1
    for (;;) {
      const _exit_num_ = g.dm_spawn.get(
        self.dk_spawn + STR_Elevator + STR_Spawn + STR_Row + STR_Exit + hexStr(_i++),
      )
      if (_exit_num_ === undefined) break
      if (hexStr((g.exit_enter as Exit).exitNum) === _exit_num_) {
        const _spawn_row = g.dm_spawn.get(
          self.dk_spawn + STR_Elevator + STR_Spawn + STR_Row + String(_exit_num_),
        )
        if (_spawn_row !== undefined) {
          self.spawn_yt = (_spawn_row as number) << 3
          set_xlyt(self, self.xl, self.spawn_yt)
          break
        }
      }
    }
  }
}

/** `ElevatorA_init_1()` */
export function ElevatorA_init_1(self: ElevatorObject): void {
  self.TYPE = self.objectName.charAt(self.objectName.length - 1)
  self.can_draw_self_exception = true
  self.exit_dirs = 0x0 // bits of which dirs the elev can exit.
  self.BODY_SPR = 'spr_Elevator_2a_WRB'
  self.BODY_SPR_YOFF = (ELEV_H >> 1) - 4
  self.CHAIN_SPR = 'spr_Elevator_chain_2a_WRB'
  self.CHAIN_CNT = (ELEV_H >> 3) - 1
  self.chain_yoff_1 = 0
  self.chain_yoff_2 = 0
  self.CHAIN_TIMING = 2 // $F.  1 pixel every 4 frames
  self.GEAR_SPR = 'spr_Elevator_gear_1a_WRB'
  self.HSPD = 0x18
  self.VSPD = 0x18
  self.hspd1 = self.HSPD
  self.vspd1 = self.VSPD
  self.pc_xoff = 0
  // pc_lock: $1: hspd, $2: jump, $10: stab high, $20: stab low, $40: thrust down, $80: thrust up,
  const _LOCK_BITS1 = PC_LOCK_JUMP | PC_LOCK_ATK3 | PC_LOCK_ATK4
  switch (self.TYPE) {
    case 'A':
      self.pc_lock_bits = _LOCK_BITS1
      break
    case 'B':
      self.pc_lock_bits = _LOCK_BITS1 | PC_LOCK_HSPD
      break
  }
}

/** `Elevator_update()` — D8C2 */
export function Elevator_update(self: ElevatorObject): void {
  if (self.state !== self.state_NORMAL) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  GO_update_cam_vars(self)
  GO_update_cs(self) // mod
  update_EF11(self)
  self.can_draw_self = true
  // E4D9 - PC_body collide GOB_body
  update_body_hb_1a(self)
  self.cs &= ~CS_BD1 // remove CS_BD1 from cs
  if (collide_pc_body(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h)) {
    self.cs |= CS_BD1
    pc().colliding_elevator = self
  }
}

/** `Elevator_update_1()` — the PC is riding this elevator (called from PC_update). */
export function Elevator_update_1(self: ElevatorObject): void {
  const P = pc()
  let _dir = 0
  const _ELEVB = self.TYPE === 'B'
  P.ogr = 0
  P.vspd = 0
  if (_ELEVB) P.hspd = 0
  let _DIR_RQST = pcInput.vHeld
  if (_ELEVB) _DIR_RQST = self.moving_dir
  if (gmBool(g.EnterRoom_control_timer)) {
    const ex = g.exit_enter as Exit
    if (ex.side & 0x3) _DIR_RQST = (ex.side & 0x3) ^ 0x3
    if (ex.side & 0xc) _DIR_RQST = (ex.side & 0xc) ^ 0xc
  }
  let _PC_CS = P.cs & 0xf
  for (let _i = (self.ww >> 3) - 1; _i >= 0; _i--) {
    const _x = self.xl + 4 + (_i << 3)
    if ((collide_solid_grid(_x, self.yt + 8) & 0xff) === TID_SOLID1) {
      _PC_CS |= 0x8 // So cucco can't get under elevator. Cucco's csTop is shorter and elevator can go too high, leaving gap under it.
      break
    }
  }
  let _DIR_MOVE = 0
  if (_DIR_RQST & 0x3) _DIR_MOVE |= (_DIR_RQST & 0x3) ^ (_PC_CS & 0x3 & (_DIR_RQST & 0x3))
  if (_DIR_RQST & 0xc) _DIR_MOVE |= (_DIR_RQST & 0xc) ^ (_PC_CS & 0xc & (_DIR_RQST & 0xc))
  self.hspd = (abs8b(self.hspd1) * bit_dir(_DIR_MOVE & 0x3)) & 0xff // hspd1=$18
  self.vspd = (abs8b(self.vspd1) * bit_dir(_DIR_MOVE & 0xc)) & 0xff // vspd1=$18
  if (!self.hspd && !self.vspd) _DIR_MOVE = 0
  const _X_PREV = self.x
  const _Y_PREV = self.y
  if (_DIR_MOVE) {
    // D8ED
    if (_DIR_MOVE & 0x3 && self.hspd) updateX(self)
    if (_DIR_MOVE & 0xc && self.vspd) updateY(self)
    if (g.rm_name !== `${Area_MazIs}F8`) {
      // For the "Lost Dungeon" YouTube vid
      // This sounds better but still has issues.
      if (!audio_is_playing(get_audio_theme_track(dk_ElevatorMove)))
        aud_play_sound(get_audio_theme_track(dk_ElevatorMove))
    }
  }
  // D8F4
  const _C1 = gmBool(_DIR_MOVE) || !gmBool(_DIR_RQST)
  const _C2 = _ELEVB && gmBool(g.pc_lock & PC_LOCK_HSPD)
  if (_C1) {
    _dir = 0
    let _DIFF = self.x + self.pc_xoff - P.x
    if (_DIFF !== 0 && _C2) {
      P.x_change = _DIFF
      _dir = Math.sign(_DIFF)
    }
    _DIFF = self.yt + self.hh - 8 - (P.yt + P.hh)
    if (_DIFF !== 0) {
      P.y_change = _DIFF
      _dir = Math.sign(_DIFF)
    }
    // (x!=_X_PREV || y!=_Y_PREV): added to prevent chains from moving on frame PC steps onto elevator
    if (_dir !== 0 && (self.x !== _X_PREV || self.y !== _Y_PREV)) {
      const _TIMING = (4 << self.CHAIN_TIMING) - 1 // 3, 7, $F, $1F, ..
      self.chain_yoff_1 = (self.chain_yoff_1 - _dir) & _TIMING
      self.chain_yoff_2 = self.chain_yoff_1 ^ _TIMING
    }
  }
  let _X = P.x
  if (_C2) _X = self.x + self.pc_xoff
  const _Y = self.yt + self.hh - 8 - P.hh_
  set_xy(P, _X, _Y)
  if (gmBool(g.EnterRoom_control_timer)) {
    let _C3: number | boolean = 0
    const side = (g.exit_enter as Exit).side & 0xf
    if (!_C1) {
      switch (side) {
        case 0x1:
          _C3 = _PC_CS & CS_LFT // From RGT exit, moving LFT
          break
        case 0x2:
          _C3 = _PC_CS & CS_RGT // From LFT exit, moving RGT
          break
        case 0x4:
          _C3 = _PC_CS & CS_TOP // From BTM exit, moving UP
          break
        case 0x8:
          _C3 = _PC_CS & CS_BTM // From TOP exit, moving DWN
          break
      }
    } else {
      const _OFFSET = 8
      switch (side) {
        case 0x1:
          _C3 = self.xr <= cam_xr_max() - _OFFSET
          break
        case 0x2:
          _C3 = self.xl >= cam_xl_min() + _OFFSET
          break
        case 0x4:
          _C3 = self.yb <= cam_yb_max() - _OFFSET
          break
        case 0x8:
          _C3 = self.yt >= cam_yt_min() + _OFFSET
          break
      }
    }
    if (gmBool(_C3)) g.EnterRoom_control_timer = 0
  }
}

/** `Elevator_udp()` */
export function Elevator_udp(self: ElevatorObject): void {
  self.can_draw_self = true
  self.yScale = sign_(self.yt & (0x4 << self.CHAIN_TIMING))
}

/** `Elevator_draw()` */
export function Elevator_draw(self: ElevatorObject): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  pal_swap_set(self.palidx)
  const d = self.depth
  const _Y = self.drawY - self.hh_ + 8
  const _Y1 = _Y + (self.chain_yoff_1 >> self.CHAIN_TIMING)
  const _Y2 = _Y + (self.chain_yoff_2 >> self.CHAIN_TIMING)
  for (let _i = 0; _i < self.CHAIN_CNT; _i++) {
    draw_sprite_at(d, self.CHAIN_SPR, 0, self.drawX - self.ww_ + 4, _Y1 + (_i << 3))
    draw_sprite_at(d, self.CHAIN_SPR, 0, self.drawX + self.ww_ - 4, _Y2 + (_i << 3), -1, -1)
  }
  // Top
  draw_sprite_at(
    d,
    self.GEAR_SPR,
    0,
    self.drawX - self.ww_ + 4,
    self.drawY - self.BODY_SPR_YOFF,
    -1,
    1,
    self.yScale,
  )
  draw_sprite_at(
    d,
    self.GEAR_SPR,
    0,
    self.drawX + self.ww_ - 4,
    self.drawY - self.BODY_SPR_YOFF,
    -1,
    -1,
    self.yScale,
  )
  // Bottom
  draw_sprite_at(
    d,
    self.GEAR_SPR,
    0,
    self.drawX - self.ww_ + 4,
    self.drawY + self.BODY_SPR_YOFF,
    -1,
    1,
    -self.yScale,
  )
  draw_sprite_at(
    d,
    self.GEAR_SPR,
    0,
    self.drawX + self.ww_ - 4,
    self.drawY + self.BODY_SPR_YOFF,
    -1,
    -1,
    -self.yScale,
  )
  draw_sprite_at(d, self.BODY_SPR, 0, self.drawX, self.drawY - self.BODY_SPR_YOFF, -1, 1, 1)
  draw_sprite_at(d, self.BODY_SPR, 0, self.drawX, self.drawY + self.BODY_SPR_YOFF, -1, 1, -1)
  pal_swap_reset()
}

/** `ElevatorB_init1()` */
export function ElevatorB_init1(self: ElevatorObject): void {
  GameObjectB_init(self)
  ElevatorA_init_1(self)
  self.BODY_SPR = 'spr_Elevator_3a_WRB'
  // Current moving dir. 0: Not moving, 1: RGT, 2: LFT, 4: DWN, 8: UP
  self.moving_dir = 0
}
/** `ElevatorB_init2()` */
export const ElevatorB_init2 = (self: ElevatorObject): void => Elevator_init2(self)
/** `ElevatorB_update()` */
export function ElevatorB_update(self: ElevatorObject): void {
  const _COLLIDING = self.cs & CS_BD1
  Elevator_update(self)
  if (!_COLLIDING && self.cs & CS_BD1) {
    // 1st frame ONLY of collision (empty in ZALiA)
  }
}
/** `ElevatorB_udp()` */
export function ElevatorB_udp(self: ElevatorObject): void {
  self.can_draw_self = true
  Elevator_udp(self)
}
/** `ElevatorB_draw()` */
export function ElevatorB_draw(self: ElevatorObject): void {
  if (!self.can_draw_self) return
  Elevator_draw(self)
}
export { NOONE }
