/** Restore fairy — ZALiA `gob2/restore_fairy` (`ReFaA`). */
import { CS_BD1, PAGE_ROWS, PC_LOCK_ALL, STR_Fairy, STR_Greeting, STR_Heart } from '@z2/data'
import { G, g, p } from '../../../../runtime/world'
import { ocsH1 } from '../../../collision/ocs'
import { get_ground_y } from '../../../collision/solid'
import { get_stat_max } from '../../../file/stats'
import { rm_get_encounter_types } from '../../../room/index'
import { aud_play_sound } from '../../../sound/play'
import { get_audio_theme_track } from '../../../sound/theme'
import { set_xlyt } from '../../go/movement'
import { GO_init_palidx } from '../../go/palette'
import { GO_set_sprite } from '../../go/sprite'
import { GOB_update_2 } from '../GameObjectB'
import type { ReFaA } from './classes'

/** `RestoreFairy_init2()` */
export function RestoreFairy_init2(self: ReFaA): void {
  self.dl_sprites?.set(1, g.dl_Fairy_SPRITES.get(1) as string) // spr_FairyB
  self.dl_sprites?.set(0, g.dl_Fairy_SPRITES.get(0) as string) // spr_FairyA
  GO_init_palidx(self, G.PI_MOB_ORG)
  self.facing_dir = 1
  self.greeting_played = false
  self.sub_state = self.SUB_STATE_IDLE
  self.scr_inst_end = RestoreFairy_end as (s: unknown) => void
  if (rm_get_encounter_types(g.rm_name) & g.ENC_FARY) {
    const _Y = (g.rm_rows - PAGE_ROWS) << 3
    self.spawn_yt = _Y + (0x1c << 3) // common ground y
    self.spawn_yt = get_ground_y(self.x, _Y, 1, self.spawn_yt)
    self.spawn_yt -= 0xa << 3
    set_xlyt(self, self.xl, self.spawn_yt)
  }
}

/**
 * FIXED (no counterpart in ZALiA): the fairy takes `g.pc_lock = PC_LOCK_ALL` when the body collision starts
 * the restore and gives it back from `SUB_STATE_RSTR` when `g.StatRestore_timer_hp` runs out — so the
 * release only happens if the fairy is still running that state. Anything that removes it first (a sword
 * hit, an out-of-bounds despawn, a room change) leaves the PC locked out of every input for the rest of the
 * session: a total freeze, and one that only shows at partial health, because a full-health restore ends on
 * the very next odd frame and closes the window. The lock is this instance's to hold, so hand it back when
 * the instance ends.
 */
export function RestoreFairy_end(self: ReFaA): void {
  if (self.sub_state === self.SUB_STATE_RSTR) g.pc_lock = 0
}

/** `RestoreFairy_update()` — D91E */
export function RestoreFairy_update(self: ReFaA): void {
  if (!self.greeting_played && ocsH1(self)) {
    // if (any of width) are in ocs area width
    self.greeting_played = true // Prevent sound from playing again
    aud_play_sound(get_audio_theme_track(STR_Fairy + STR_Greeting))
  }
  // D931: JSR DE40
  GOB_update_2(self)
  // D934
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE: {
      if (!(self.cs & CS_BD1)) break
      g.pc_lock = PC_LOCK_ALL
      g.StatRestore_timer_hp = get_stat_max(STR_Heart)
      self.sub_state = self.SUB_STATE_RSTR
      break
    }
    case self.SUB_STATE_RSTR: {
      const _DURATION = p.Flash_Pal_timer | 0x10
      p.Flash_Pal_timer = _DURATION
      p.SpellFlash_PC_timer = _DURATION
      if (!g.StatRestore_timer_hp) {
        // Restoration complete.
        g.pc_lock = 0
        self.state = 0
      }
      break
    }
  }
}

/** `RestoreFairy_udp()` — F0DD */
export function RestoreFairy_udp(self: ReFaA): void {
  self.can_draw_self = true
  // yoff for hover.  _data = "0102030403020100", 1,2,3,4,3,2,1,0
  const _val = (g.counter1 & 0x38) >> 3 // leaves bits $7
  if (!(_val & 0x4))
    self.draw_yoff = (_val & 0x3) + 1 // 1, 2, 3, 4
  else self.draw_yoff = (_val & 0x3) ^ 0x3 // 3, 2, 1, 0
  self.draw_yoff += 8
  self.draw_xoff = 0
  GO_set_sprite(self, self.dl_sprites?.get(g.counter1 & 0x4 ? 1 : 0) as string)
  self.facing_dir = 1
}
