/** Ported from `Cutscene_FloorTrap_1_init_1.gml`, `_update.gml`, `_update_1a.gml`, `_draw.gml`, `_end.gml`. */
import { DEPTH_BG2, DEPTH_BG3, PAGE_ROWS, PC_LOCK_ALL, PC_LOCK_VSPD } from '@z2/data'
import { gmBool } from '../../../nes/math8'
import { DsGrid } from '../../../runtime/ds'
import { G, g } from '../../../runtime/world'
import { inRange, sign_ } from '../../math'
import { pal_swap_reset, pal_swap_set } from '../../palette/scenePalette'
import { draw_background_part, draw_sprite_ } from '../../rooms/draw'
import { aud_play_combo1 } from '../../sound/play'
import { tile_change_1a } from '../../tile/tileOps'
import type { Cutscene_FloorTrap_1 } from './classes'
import { Cutscene_init } from './cutscene'

/** `Cutscene_FloorTrap_1_init_1()` — Zelda lures the PC onto crumbling ground. */
export function Cutscene_FloorTrap_1_init_1(self: Cutscene_FloorTrap_1): void {
  Cutscene_init(self)
  self.sub_state = self.sub_state_IDLE
  self.Zelda_SPR1 = 'spr_Zelda_Pose_2a'
  self.Zelda_SPR2 = 'spr_Zelda_Pose_3a'
  self.Zelda_X = (0x25 << 3) + 4
  self.Zelda_Y = (g.rm_rows - PAGE_ROWS + 0x18) << 3
  self.Zelda_XSCALE = sign_(g.exit_enter.side & 1)
  self.Zelda_PI = G.PI_MOB_RED
  self.Trigger_DIST = 0x14 << 3
  self.timer = 0
  self.PC_LOCK = PC_LOCK_ALL & ~PC_LOCK_VSPD
  self.CrumbleGround_state = 1
  self.CrumbleGround_DEPTH = DEPTH_BG2 - 1
  self.CrumbleGround_CLM = 0x08
  self.CrumbleGround_CLMS = 0x4a - self.CrumbleGround_CLM
  self.CrumbleGround_ROW = g.rm_rows - PAGE_ROWS + 0x1c
  self.CrumbleGround_ROWS = g.rm_rows - self.CrumbleGround_ROW
  self.CrumbleGround_Block_CLMS = self.CrumbleGround_CLMS >> 1
  self.CrumbleGround_Block_ROWS = self.CrumbleGround_ROWS >> 1
  self.CrumbleGround1_DUR = 0x08
  self.CrumbleGround2_DUR = 0x08
  self.CrumbleGround1_TS = 'ts_Man_made_6a_WRB'
  self.CrumbleGround2_TS = 'ts_Man_made_6a_WRB'
  self.MetalBlock_COUNT = 0x10
  self.MetalBlock_CLM = self.CrumbleGround_CLM
  self.MetalBlock_ROW = self.CrumbleGround_ROW - 0x2
  const dg = new DsGrid<number>(2, 4, 0)
  dg.set(0, 0, 0xdf)
  dg.set(0, 1, 0xed)
  dg.set(0, 2, 0xfa)
  dg.set(0, 3, 0xef)
  dg.set(1, 0, 0xeb)
  dg.set(1, 1, 0xec)
  dg.set(1, 2, dg.get(1, 1) as number)
  dg.set(1, 3, dg.get(1, 0) as number)
  self.dg_TSRC = dg
}

/** `Cutscene_FloorTrap_1_update()` */
export function Cutscene_FloorTrap_1_update(self: Cutscene_FloorTrap_1): void {
  if (gmBool(self.timer)) self.timer--
  switch (self.sub_state) {
    case self.sub_state_IDLE: {
      if (gmBool(self.timer)) break
      if (inRange(G.pc.x, self.Zelda_X - self.Trigger_DIST, self.Zelda_X + self.Trigger_DIST)) {
        g.pc_lock = self.PC_LOCK
        self.CrumbleGround_state = 1
        self.timer = 0
        self.sub_state = self.sub_state_ACTIVE
      }
      break
    }
    case self.sub_state_ACTIVE: {
      if (gmBool(self.timer)) break
      switch (self.CrumbleGround_state) {
        case 1: {
          if (gmBool(G.pc.ogr)) break
          // Remove ground tiles
          Cutscene_FloorTrap_1_update_1a(self, 1)
          aud_play_combo1(7)
          self.timer = self.CrumbleGround1_DUR // CrumbleGround1_DUR=$08
          self.CrumbleGround_state++
          break
        }
        case 2: {
          // Remove solids
          Cutscene_FloorTrap_1_update_1a(self, 2)
          self.timer = self.CrumbleGround2_DUR // CrumbleGround2_DUR=$08
          self.CrumbleGround_state++
          break
        }
        case 3: {
          self.CrumbleGround_state = 0
          self.timer = 0
          self.sub_state = self.sub_state_DONE
          break
        }
      }
      break
    }
    case self.sub_state_DONE: {
      if (gmBool(self.timer)) break
      break
    }
  }
}

/** `Cutscene_FloorTrap_1_update_1a(phase)` — 1: remove tiles, 2: remove solids. */
export function Cutscene_FloorTrap_1_update_1a(self: Cutscene_FloorTrap_1, phase: number): void {
  let _count = self.CrumbleGround_CLMS * self.CrumbleGround_ROWS
  for (let _i = 0; _i < _count; _i++) {
    const _clm = self.CrumbleGround_CLM + (_i % self.CrumbleGround_CLMS)
    const _row = self.CrumbleGround_ROW + Math.trunc(_i / self.CrumbleGround_CLMS)
    switch (phase) {
      case 1:
        tile_change_1a(DEPTH_BG2, _clm << 3, _row << 3, 0, 0)
        break // remove tiles
      case 2:
        G.dg_solid.set(_clm, _row, 0)
        break // remove solids
    }
  }
  _count = self.MetalBlock_COUNT << 1
  for (let _i = 0; _i < _count; _i++) {
    const _clm = self.MetalBlock_CLM + _i
    const _row = self.MetalBlock_ROW
    if (_clm >= g.rm_clms) break
    switch (phase) {
      case 1:
        tile_change_1a(DEPTH_BG3, _clm << 3, _row << 3, 0, 0)
        tile_change_1a(DEPTH_BG3, _clm << 3, (_row + 1) << 3, 0, 0)
        break // remove tiles
      case 2:
        G.dg_solid.set(_clm, _row, 0)
        G.dg_solid.set(_clm, _row + 1, 0)
        break // remove solids
    }
  }
}

/** `Cutscene_FloorTrap_1_draw()` — Zelda pose + the crumbling tile animation. */
export function Cutscene_FloorTrap_1_draw(self: Cutscene_FloorTrap_1): void {
  if (self.sub_state !== self.sub_state_DONE) {
    const _DIST = self.Trigger_DIST + (0x03 << 3)
    let _SPR: string
    if (inRange(G.pc.x, self.Zelda_X - _DIST, self.Zelda_X + _DIST)) _SPR = self.Zelda_SPR1
    else _SPR = self.Zelda_SPR2
    draw_sprite_(_SPR, 0, self.Zelda_X, self.Zelda_Y, self.Zelda_PI, self.Zelda_XSCALE)
  }
  if (self.sub_state !== self.sub_state_ACTIVE) return
  if (self.CrumbleGround_state === 2 || self.CrumbleGround_state === 3) {
    self.depth = self.CrumbleGround_DEPTH
    const dg = self.dg_TSRC as DsGrid<number>
    const _IDX = self.CrumbleGround_state === 3 ? 1 : 0 // 0,1
    let _ts: string
    if (self.CrumbleGround_state === 2) _ts = self.CrumbleGround1_TS
    else _ts = self.CrumbleGround2_TS
    const mixed = self.CrumbleGround_state === 3 && self.timer <= self.CrumbleGround2_DUR >> 1 // mix them around 2nd half of their time
    const drawBlock = (_clm: number, _row: number) => {
      for (let _j = 0; _j < 4; _j++) {
        const _x = (_clm + (_j & 1)) << 3
        const _y = (_row + (_j > 1 ? 1 : 0)) << 3
        const _idx = mixed ? (_j ^ 1) | (_j & 2) : _j
        const _tsrc = dg.get(_IDX, _idx) as number
        const _ts_x = ((_tsrc >> 0) & 0xf) << 3
        const _ts_y = ((_tsrc >> 4) & 0xf) << 3
        draw_background_part(_ts, _ts_x, _ts_y, 8, 8, _x, _y)
      }
    }
    pal_swap_set(G.PI_BGR1)
    const _count = self.CrumbleGround_Block_CLMS * self.CrumbleGround_Block_ROWS
    for (let _i = 0; _i < _count; _i++) {
      const _clm = self.CrumbleGround_CLM + ((_i % self.CrumbleGround_Block_CLMS) << 1)
      const _row = self.CrumbleGround_ROW + (Math.trunc(_i / self.CrumbleGround_Block_CLMS) << 1)
      drawBlock(_clm, _row)
    }
    pal_swap_reset()
    pal_swap_set(G.PI_BGR2)
    for (let _i = 0; _i < self.MetalBlock_COUNT; _i++) {
      const _clm = self.MetalBlock_CLM + (_i << 1)
      const _row = self.MetalBlock_ROW
      if (_clm > g.rm_clms - 0x2) break
      drawBlock(_clm, _row)
    }
    pal_swap_reset()
  }
}

/** `Cutscene_FloorTrap_1_end()` */
export function Cutscene_FloorTrap_1_end(self: Cutscene_FloorTrap_1): void {
  self.dg_TSRC = undefined
}
