/**
 * `Rando_randomize_enemies()` — enemy chars / spawns / HP / damage rando. Everything lands in
 * `self.dm_save_data` (persisted by `Rando_randomize_file` to `SaveFile_N_Rando_Data.txt` → `f.dm_rando`):
 *
 *  - `_Randomize_Enemy_Method`, `_Randomize_Enemy_Difficulty` — the chosen mode and difficulty cap.
 *  - method 1 (SPAWNS): `_Randomize_Enemy_Spawn<spawn datakey>_Spawn_Datakey_Randomized` and
 *    `_Randomize_Enemy_Spawn<spawn datakey>_OBJVER_Randomized` — each spawn point is paired with a shuffled
 *    one of the same class. Read back by `g_Room_Start_1c` and the per-enemy create scripts.
 *  - method 2 (TYPES): `_Randomize_Enemy_Type<objver>_OBJVER_Randomized` — a global objver↔objver swap,
 *    written in both directions.
 *  - `_Enemy_HP<hex(i)>` — one entry per `g.dl_HP` slot, ±25% of the original (min 1).
 *  - `_Enemy_Damage<hex(life lvl)><hex(enemy dmg lvl)>` — `g.dg_enemy_damage` cell, ±10% (min 1).
 *
 * Candidate pools come from `g.dm_RandoEnemy` / `g.dl_RandoEnemy_OBJVER1..3` (see `rando/enemyData.ts`,
 * the ported `Rando_init_enemy_data`); the spawn list itself is `g.dm_RandoEnemy`'s shipped
 * `_Randomize_Enemy_Spawn*` cache and `g.dm_spawn`. Nothing here writes `g.dm_spawn`.
 *
 * `EnemyENIGMA_WILL_RANDOMIZE` is decoded by `Rando_randomize_file` and only used for the debug string in
 * `Rando_generate`; this script never reads it (ENIGMA picks its enemies live in `update_spell_effects`).
 *
 * Dropped: the `var _DEBUG1=0;` blocks (`:40-45`, `:118-121`, `:132-148`) — a disabled dev dump of the
 * spawn pairing. Dead local `_datakey1 = _datakey+STR_Type` in case 2 (`:157`), never read.
 */
import {
  Area_MazIs,
  AreaID_LEN,
  dk_EnemyRandoOmit,
  STR_Count,
  STR_Damage,
  STR_Datakey,
  STR_Difficulty,
  STR_Enemy,
  STR_HP,
  STR_Method,
  STR_Name,
  STR_OBJVER,
  STR_Randomize,
  STR_Randomized,
  STR_Rm,
  STR_Spawn,
  STR_Type,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { DsList } from '../../runtime/ds'
import { G, g, world } from '../../runtime/world'
import { save_game_pref } from '../file/prefs'
import { ds_grid_height, ds_grid_width, round } from '../Game/gm'
import { gmBool } from '../math/index'
import { str_hex, val } from '../other/index'
import { ds_list_copy, ds_list_shuffle, inList, string_copy } from './helpers'
import type { Rando } from './Rando'

/** `Rando_randomize_enemies()` */
export function Rando_randomize_enemies(self: Rando): void {
  if (gmBool(self.EnemyChars_WILL_RANDOMIZE)) {
    G.EnemyRando_enabled = true
    save_game_pref()

    //if (DEBUG){sdm(" "); dm_debug_data[?STR_Data+'01'+hex_str(++debug_data_count)]=" ";}
    world.random_set_seed(self.Rando_SEED)

    self.dl_list1.clear()
    self.dl_list2.clear()

    const _datakey = STR_Randomize + STR_Enemy

    self.dm_save_data.set(_datakey + STR_Method, self.EnemyChars_WILL_RANDOMIZE)
    self.dm_save_data.set(_datakey + STR_Difficulty, self.Enemy_DIFFICULTY)

    switch (self.EnemyChars_WILL_RANDOMIZE) {
      // ====================================================================
      case 1: {
        // SPAWNS --------------------------------------------
        const _datakey1 = _datakey + STR_Spawn

        const _count = Number(g.dm_RandoEnemy.val(_datakey1 + STR_Count))
        if (_count < 2) break

        const _dl_SPAWN_DATAKEY_A1 = new DsList<string>()
        const _dl_SPAWN_DATAKEY_A2 = new DsList<string>()
        const _dl_SPAWN_DATAKEY_A3 = new DsList<string>()
        const _dl_SPAWN_DATAKEY_b1 = new DsList<string>()
        const _dl_SPAWN_DATAKEY_b2 = new DsList<string>()

        for (let _i = 0; _i < _count; _i++) {
          //_datakey1 = STR_Randomize+STR_Enemy+STR_Spawn;
          const _spawn_datakey1 = String(
            val(g.dm_RandoEnemy.get(_datakey1 + hexStr(_i + 1) + STR_Spawn + STR_Datakey)),
          )
          const _objver1 = g.dm_spawn.get(_spawn_datakey1 + STR_OBJVER)
          const _scene_name = g.dm_spawn.get(_spawn_datakey1 + STR_Rm + STR_Name)
          if (
            typeof _objver1 === 'string' &&
            typeof _scene_name === 'string' &&
            g.dm_rm.get(_scene_name + dk_EnemyRandoOmit) === undefined &&
            g.dm_spawn.get(_spawn_datakey1 + dk_EnemyRandoOmit) === undefined
          ) {
            // FIDELITY: the GML reads the scene number at `AreaID_LEN+2` (`:67`), one character too far —
            // `str_hex()` then only ever saw the low digit, so `<$40` was always true and the Maze Island
            // exclusion never fired (131 of the 142 `_MazIs_*` scenes are >= $40). Every other site reads it
            // at `AreaID_LEN+1` (`g_Room_Start.gml:124`, `set_rm_data.gml:15`); corrected here.
            if (
              string_copy(_scene_name, 1, AreaID_LEN) !== Area_MazIs ||
              str_hex(string_copy(_scene_name, AreaID_LEN + 1, 2)) < 0x40
            ) {
              const _difficulty = Number(g.dm_RandoEnemy.val(_objver1 + STR_Difficulty, 1))
              if (_difficulty <= self.Enemy_DIFFICULTY) {
                //RandoEnemy_difficulty_MAX
                if (inList(g.dl_RandoEnemy_OBJVER1, _objver1)) {
                  _dl_SPAWN_DATAKEY_A1.add(_spawn_datakey1)
                  continue
                }
                if (inList(g.dl_RandoEnemy_OBJVER2, _objver1)) {
                  // Flying enemies
                  _dl_SPAWN_DATAKEY_A2.add(_spawn_datakey1)
                  continue
                }
                if (inList(g.dl_RandoEnemy_OBJVER3, _objver1)) {
                  // Spawners
                  _dl_SPAWN_DATAKEY_A3.add(_spawn_datakey1)
                }
              }
            }
          }
        }

        for (let _i = 1; _i <= 3; _i++) {
          switch (_i) {
            case 1:
              ds_list_copy(_dl_SPAWN_DATAKEY_b1, _dl_SPAWN_DATAKEY_A1)
              break
            case 2:
              ds_list_copy(_dl_SPAWN_DATAKEY_b1, _dl_SPAWN_DATAKEY_A2) // Flying enemies
              break
            case 3:
              ds_list_copy(_dl_SPAWN_DATAKEY_b1, _dl_SPAWN_DATAKEY_A3) // Spawners
              break
          }

          if (
            _dl_SPAWN_DATAKEY_b1.get(0) === _dl_SPAWN_DATAKEY_A3.get(0) && // if it's a spawner
            !gmBool(self.EnemySpawners_WILL_RANDOMIZE) // if NOT randomizing spawners
          ) {
            continue
          }

          ds_list_copy(_dl_SPAWN_DATAKEY_b2, _dl_SPAWN_DATAKEY_b1)
          ds_list_shuffle(_dl_SPAWN_DATAKEY_b2)
          const _count1 = _dl_SPAWN_DATAKEY_b2.size
          for (let _j = 0; _j < _count1; _j++) {
            const _spawn_datakey1 = String(_dl_SPAWN_DATAKEY_b1.get(_j)) // original
            const _spawn_datakey2 = String(_dl_SPAWN_DATAKEY_b2.get(_j)) // shuffled
            const _objver1 = g.dm_spawn.get(_spawn_datakey1 + STR_OBJVER)
            const _objver2 = g.dm_spawn.get(_spawn_datakey2 + STR_OBJVER)
            if (typeof _objver1 === 'string' && typeof _objver2 === 'string') {
              self.dm_save_data.set(
                _datakey1 + _spawn_datakey1 + STR_Spawn + STR_Datakey + STR_Randomized,
                _spawn_datakey2,
              )
              self.dm_save_data.set(_datakey1 + _spawn_datakey1 + STR_OBJVER + STR_Randomized, _objver2)
              //dm_save_data[?_datakey1+_spawn_datakey2+STR_OBJVER+STR_Randomized] = _objver1; // This is overwriting data and causing too many or too little of an objver
            }
          }
        }
        break
      } //case 1:

      // ====================================================================
      case 2: {
        // TYPES ---------------------------------------------
        for (let _i = 1; _i <= 3; _i++) {
          self.dl_list1.clear()

          switch (_i) {
            default:
              ds_list_copy(self.dl_list2, g.dl_RandoEnemy_OBJVER1)
              break
            case 2:
              ds_list_copy(self.dl_list2, g.dl_RandoEnemy_OBJVER2) // Flying
              break
            case 3:
              ds_list_copy(self.dl_list2, g.dl_RandoEnemy_OBJVER3) // Spawners
              break
          }

          if (
            self.dl_list2.get(0) === g.dl_RandoEnemy_OBJVER3.get(0) &&
            !gmBool(self.EnemySpawners_WILL_RANDOMIZE)
          ) {
            continue
          }

          const _count = self.dl_list2.size
          for (let _j = 0; _j < _count; _j++) {
            const _objver1 = self.dl_list2.get(_j)
            if (typeof _objver1 === 'string') {
              const _difficulty = Number(g.dm_RandoEnemy.val(_objver1 + STR_Difficulty, 1))
              if (_difficulty <= self.Enemy_DIFFICULTY && self.dl_list1.findIndex(_objver1) === -1) {
                self.dl_list1.add(_objver1)
              }
            }
          }

          if (self.dl_list1.size >= 2) {
            ds_list_copy(self.dl_list2, self.dl_list1)
            ds_list_shuffle(self.dl_list2)
            for (let _j = self.dl_list2.size - 1; _j >= 0; _j--) {
              const _objver1 = self.dl_list1.get(_j)
              const _objver2 = self.dl_list2.get(_j)
              if (typeof _objver1 === 'string' && typeof _objver2 === 'string') {
                //            _datakey = STR_Randomize+STR_Enemy
                self.dm_save_data.set(_datakey + STR_Type + _objver1 + STR_OBJVER + STR_Randomized, _objver2)
                self.dm_save_data.set(_datakey + STR_Type + _objver2 + STR_OBJVER + STR_Randomized, _objver1)
              }
            }
          }
        }
        break
      } //case 2:
    } //switch(EnemyChars_WILL_RANDOMIZE)
  }

  if (gmBool(self.EnemyHP_WILL_RANDOMIZE)) {
    //if (DEBUG){sdm(" "); dm_debug_data[?STR_Data+'01'+hex_str(++debug_data_count)]=" ";}

    world.random_set_seed(self.Rando_SEED)

    const _datakey = STR_Enemy + STR_HP

    const _count = g.dl_HP.size
    for (let _i = 0; _i < _count; _i++) {
      let _val = Number(g.dl_HP.get(_i))
      if (gmBool(_val)) {
        const _val0 = Math.max(round(_val * 0.25), 1)
        const _max = _val + _val0
        const _min = _val - _val0
        _val = _min + world.irandom(_max - _min)
        _val = Math.max(_val, 1)
      }

      self.dm_save_data.set(_datakey + hexStr(_i), _val)
    }
  }

  if (gmBool(self.EnemyDamage_WILL_RANDOMIZE)) {
    //if (DEBUG){sdm(" "); dm_debug_data[?STR_Data+'01'+hex_str(++debug_data_count)]=" ";}

    world.random_set_seed(self.Rando_SEED)

    const _datakey = STR_Enemy + STR_Damage

    const _EnemyDamage_level_COUNT = ds_grid_height(g.dg_enemy_damage)
    for (let _i = ds_grid_width(g.dg_enemy_damage) - 1; _i >= 0; _i--) {
      // LIFE Level
      for (let _j = _EnemyDamage_level_COUNT - 1; _j >= 0; _j--) {
        // Enemy Damage Level
        let _val = Number(g.dg_enemy_damage.get(_i, _j))
        if (gmBool(_val)) {
          const _val0 = Math.max(round(_val * 0.1), 1)
          const _max = _val + _val0
          const _min = _val - _val0
          _val = _min + world.irandom(_max - _min)
          _val = Math.max(_val, 1)
        }

        self.dm_save_data.set(_datakey + hexStr(_i) + hexStr(_j), _val)
      }
    }
  }
}
