/**
 * `PC_init()` — one-time player initialisation (runs inside `PC_create`). The constant fields live on the
 * `Lonk` class; this sets everything that depends on `g`/`f`/`p` and registers the skins.
 * Dropped: `DEV` logging; the `UserPreferences.txt` re-read (the File port's `load_game_pref` restores
 * `_PC_Sprite_Set` — see `applySkinPreference`).
 */
import {
  DEPTH_PC_MAIN,
  ITM_FTHR,
  PC_PLACEMENT_SPR,
  STR_Body,
  STR_Clm,
  STR_Count,
  STR_Current,
  STR_Datakey,
  STR_Frame,
  STR_Height,
  STR_Idx,
  STR_Row,
  STR_Set,
  STR_Shield,
  STR_Sprite,
  STR_Sword,
  STR_undefined,
  STR_Width,
} from '@z2/data'
import { f, g, p } from '../../../runtime/world'
import { sprite_get_height, sprite_get_width } from '../../graphics/sprites'
import { hex_str, val } from '../../other/index'
import { PI_MOB_ORG, PI_PC1 } from '../../palette/pi'
import { GameObject_create_1a } from '../create'
import { GO_init_palidx } from '../go/palette'
import { GO_depth_init, GO_set_sprite, GO_sprite_init } from '../go/sprite'
import type { Lonk } from './Lonk'
import { PC_draw } from './PC_draw'
import { PC_end } from './PC_end'
import { BUILTIN_SKINS, customSkinProvider, PC_init_add_spritesheet } from './skins'

export function PC_init(self: Lonk): void {
  GO_depth_init(self, DEPTH_PC_MAIN)
  GO_sprite_init(self, PC_PLACEMENT_SPR)
  // default GameObject draw YOff
  self.DRAW_YOFF = 1 // +1 for 1 pixel in ground
  // get scripts from data, run scr_vars, run scr_ini1
  GameObject_create_1a(self)
  self.scr_draw = PC_draw as (s: unknown) => void
  self.scr_inst_end = PC_end as (s: unknown) => void
  // ---------------------------------------------------------------------------------------------
  self.behavior = self.behavior_IDLE // 0080
  self.dl_UwU_.clear()
  for (let _i = 0; _i <= self.behavior_LAST; _i++) self.dl_UwU_.add(_i)
  // skins ---------------------------------------------------------------------------------------
  const dm = self.dm_skins
  dm.set(STR_Current + STR_Idx, 0)
  dm.set(STR_Frame + STR_Width, self.Spritesheet_W)
  dm.set(STR_Frame + STR_Height, self.Spritesheet_H)
  const clm = (behavior: number, col: number) => dm.set(STR_Clm + hex_str(behavior), col)
  clm(self.behavior_WALK1, 0x02)
  clm(self.behavior_WALK2, 0x03)
  clm(self.behavior_WALK3, 0x04)
  clm(self.behavior_IDLE, 0x00)
  clm(self.behavior_DRAWBACK, 0x05)
  clm(self.behavior_STAB_STAND, 0x06)
  clm(self.behavior_CROUCH, 0x01)
  clm(self.behavior_STAB_CROUCH, 0x07)
  clm(self.behavior_STAB_UP, 0x09)
  clm(self.behavior_STAB_DOWN, 0x08)
  clm(self.behavior_DAMAGE, 0x0a)
  clm(self.behavior_HOLD_ITEM4, 0x0d)
  clm(self.behavior_HOLD_ITEM1, 0x0c)
  clm(self.behavior_HOLD_ITEM2, 0x0c)
  clm(self.behavior_HOLD_ITEM3, 0x0b)
  clm(self.behavior_HOLD_ITEM5, 0x0e)
  clm(self.behavior_POSE1, 0x0f)
  dm.set(`${STR_Row + STR_Shield}01`, 0x00)
  dm.set(`${STR_Row + STR_Shield}02`, 0x01)
  dm.set(`${STR_Row + STR_Body}01`, 0x02)
  dm.set(`${STR_Row + STR_Body}02`, 0x03) // Disguise
  dm.set(`${STR_Row + STR_Sword}01`, 0x04)
  dm.set(`${STR_Row + STR_Sword}02`, 0x05)
  for (const [sprite, name, creator] of BUILTIN_SKINS) PC_init_add_spritesheet(self, sprite, name, creator)
  self.Skin_image = self.PCSkin_DEFAULT_SPRITE
  // Users can add their own PC spritesheets (ZALiA: %localappdata%\ZALiA\custom_playercharacter_graphics).
  for (const skin of customSkinProvider())
    PC_init_add_spritesheet(self, skin.key, skin.name, skin.creator, -1, true)
  // disguise ------------------------------------------------------------------------------------
  self.Disguise_enabled = false
  self.Disguise_Head_idx = 0
  self.Disguise_Head_COUNT = 2
  self.Disguise_dl_behaviors.clear()
  self.Disguise_dl_behaviors.add(
    self.behavior_IDLE,
    self.behavior_WALK1,
    self.behavior_WALK2,
    self.behavior_WALK3,
    self.behavior_CROUCH,
  )
  GO_set_sprite(self, (self.dl_sprites?.get(self.behavior) as string | undefined) ?? PC_PLACEMENT_SPR)
  GO_init_palidx(self, PI_PC1)
  // cucco ---------------------------------------------------------------------------------------
  if (g.mod_PC_CUCCO_1) {
    self.Cucco_eye_color = p.C_BLK1
    const dg = self.dg_Cucco_DISGUISE_SPRITES
    const pairs: [string, string][] = [
      ['spr_Octorok_Idle', 'spr_Octorok_Mouth'],
      ['spr_Aneru1', 'spr_Aneru2'],
      ['spr_Lowder1', 'spr_Lowder2'],
    ]
    for (const [a, b] of pairs) {
      const x = dg.width
      ;(dg as { width: number }).width = x + 1
      for (const row of dg.cells) row.push(0)
      dg.set(x, 0, a)
      dg.set(x, 1, b)
    }
    self.Cucco_W = sprite_get_width(self.Cucco_SPRITE_BODY1)
    self.Cucco_H = sprite_get_height(self.Cucco_SPRITE_BODY1)
  }
  self.Draw_behavior = self.behavior
  self.x_scale_prev = self.xScale
  // attack --------------------------------------------------------------------------------------
  self.StabFrenzy_charge_counter_DURATION = self.attack_phase_DURATION1 * 3 + self.attack_phase_DURATION2
  self.hspd_dir = self.xScale // 005F
  self.hspd_dir_spawn = self.hspd_dir
  self.vspd_grav = self.GRAVITY2 // $03E6
  self.vspd_prev = self.vspd
  self.vspd_dir = 1
  self.vspd_dir_spawn = self.vspd_dir
  self.uses_vspd_sub = false // PC uses updateY2()
  self.jump_tokens = 1 + (f.items & ITM_FTHR ? 1 : 0)
  self.HoldItem_palidx = PI_MOB_ORG // 5: MOB3 orange
  // shield hb table -----------------------------------------------------------------------------
  // MOD. _adj1: In OG, shield hb facing right is 2 pixels further away from pc center than facing left.
  const _adj1 = -1 // 0: OG, -1: mod
  const S = self.dg_ShieldHB
  const I = self.ShieldHB_IDX
  const FI = self.Fairy_ShieldHB_IDX
  const CI = self.Cucco_ShieldHB_IDX
  const X = g.HB_ADJ_X
  S.set(I, self.ShieldHB_IDX_W1, 5 + X) // SHLD_W1
  S.set(I, self.ShieldHB_IDX_H1, 12 + X) // SHLD_H1
  S.set(I, self.ShieldHB_IDX_W2, S.get(I, self.ShieldHB_IDX_W1) ?? 0)
  S.set(I, self.ShieldHB_IDX_H2, S.get(I, self.ShieldHB_IDX_H1) ?? 0)
  S.set(I, self.ShieldHB_IDX_XOFF_RIGHT, 14 + X + _adj1) // SHLD_XOFF_RGT
  S.set(I, self.ShieldHB_IDX_XOFF_LEFT, -1 + X + _adj1) // SHLD_XOFF_LFT
  S.set(I, self.ShieldHB_IDX_YOFF_STAND, 2 + X) // SHLD_YOFF_HGH
  S.set(I, self.ShieldHB_IDX_YOFF_CROUCH, 17 + X) // SHLD_YOFF_LOW
  for (let c = 0; c < 8; c++) S.set(FI, c, S.get(I, c) ?? 0)
  for (let c = 0; c < 8; c++) S.set(CI, c, S.get(I, c) ?? 0)
  // Cucco crouching height/yoff follow the cucco body hb difference
  const crouchDiff =
    (g.dg_BODY_HB.get(self.Cucco_BodyHB_IDX2, 0x3) ?? 0) -
    (g.dg_BODY_HB.get(self.Cucco_BodyHB_IDX1, 0x3) ?? 0)
  S.set(CI, self.ShieldHB_IDX_H2, (S.get(CI, self.ShieldHB_IDX_H2) ?? 0) + crouchDiff)
  S.set(CI, self.ShieldHB_IDX_YOFF_CROUCH, S.get(CI, self.ShieldHB_IDX_YOFF_STAND) ?? 0)
  S.set(
    CI,
    self.ShieldHB_IDX_YOFF_CROUCH,
    (S.get(CI, self.ShieldHB_IDX_YOFF_CROUCH) ?? 0) +
      ((S.get(CI, self.ShieldHB_IDX_H1) ?? 0) - (S.get(CI, self.ShieldHB_IDX_H2) ?? 0)),
  )
  self.ShieldHB_can_draw = true
  self.ShieldHB_color = g.ShieldHB_COLOR // c_yellow
  self.ShieldHB_xoff = S.get(I, self.ShieldHB_IDX_XOFF_RIGHT) ?? 0
  self.ShieldHB_yoff = S.get(I, self.ShieldHB_IDX_YOFF_STAND) ?? 0
  self.ShieldHB_w = S.get(I, self.ShieldHB_IDX_W1) ?? 0
  self.ShieldHB_h = S.get(I, self.ShieldHB_IDX_H1) ?? 0
  // sword hb -------------------------------------------------------------------------------------
  self.SwordHB_collidable = false
  self.SwordHB_can_draw = self.SwordHB_collidable
  self.SwordHB_color = 0x00ff00 // c_lime, debug
  self.SwordHB_W = 14 + g.HB_ADJ_W // 14,15
  self.SwordHB_H = 3 + g.HB_ADJ_H //  3, 4
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
  self.SwordHB_w_ = self.SwordHB_w >> 1
  self.SwordHB_h_ = self.SwordHB_h >> 1
  self.SwordHB2_W = self.SwordHB_W
  self.SwordHB2_W_ = self.SwordHB2_W >> 1
  self.SwordHB2_w = self.SwordHB2_W
  self.SwordHB2_h = self.SwordHB2_H
  self.SwordHB2_XOFF = self.GraphicSwordPoint_DIST - self.SwordHB2_W_
  self.SwordHB2_xl = self.x + self.SwordHB2_XOFF * self.xScale - self.SwordHB2_W_
  self.SwordHB2_yt = self.y + self.SwordHB2_YOFF + 10 * (self.stab_type ? 0 : 1) // stabType. 0: low, 1: high
}

/** The `_PC_Sprite_Set` preference (ZALiA read `UserPreferences.txt` inline in `PC_init`). */
export function applySkinPreference(self: Lonk, spriteSetIdx: number): void {
  const dm = self.dm_skins
  const count = Number(val(dm.get(STR_Set + STR_Count)))
  dm.set(STR_Current + STR_Idx, Math.min(Math.max(spriteSetIdx, 0), count - 1))
  const _idx = Number(val(dm.get(STR_Current + STR_Idx)))
  const _datakey = String(val(dm.get(hex_str(_idx) + STR_Datakey), STR_undefined))
  self.Skin_image = String(val(dm.get(_datakey + STR_Sprite), self.PCSkin_DEFAULT_SPRITE))
}
