/** Locked door — ZALiA `gob2/locked_door` (`LoDoA`). */
import {
  CS_BD1,
  CS_BTM,
  ITM_SKEY,
  MAX_GOC1,
  PC_LOCK_ALL,
  STR_Acquired,
  STR_Count,
  STR_Data,
  STR_Dungeon,
  STR_KEY,
  STR_Key,
  STR_LockedDoor,
  STR_Open,
  STR_Respawn,
  STR_Side,
  STR_Spawn_Permission,
  STR_Used,
  UIDX_NULL,
} from '@z2/data'
import { hexStr } from '../../../../nes/hexStr'
import { gmBool, isVal } from '../../../../nes/math8'
import { f, G, g } from '../../../../runtime/world'
import { get_ground_y } from '../../../collision/solid'
import { get_key_count } from '../../../file/stats'
import { avail_uidx_goc } from '../../../game_object_mgr/slots'
import { str_hex, val } from '../../../other/index'
import { pal_swap_reset, pal_swap_set } from '../../../palette/scenePalette'
import { aud_play_sound } from '../../../sound/play'
import { get_audio_theme_track } from '../../../sound/theme'
import { GOC1_create } from '../../create'
import { GO_draw_sprite } from '../../go/draw'
import { dir_to_pc } from '../../go/misc'
import { set_xy } from '../../go/movement'
import { GO_init_palidx } from '../../go/palette'
import { pushback_pc_and_go } from '../../go/pushback'
import { pc_is_fairy } from '../../goa/form'
