import type { LoDoA } from './classes'
import { draw_sprite_at } from './deps'

/** `LockedDoor_init2()` */
export function LockedDoor_init2(self: LoDoA): void {
  GO_init_palidx(self, G.PI_MOB_ORG)
  self.SPR_1A = 'spr_Locked_Door1B' // Mid, key hole
  self.SPR_1B = 'spr_Locked_Door_2a' // Mid, NO key hole
  self.SPR_2A = 'spr_Locked_Door1A' // Top & Btm
  self.SPR_3A = 'spr_Locked_Door_2b' // Switch
  self.facing_dir = 1
  self.YOFF = 0x10
  self.DRAW_YOFF += self.YOFF
  self.openYOff = 0
  self.SWITCH_XOFF = 0xc
  self.can_draw_self_exception = true
  self.counter = 0 // 0: idle, > 0: opening
  self.GROUND_Y = self.spawn_yt + self.hh
  self.GROUND_Y = get_ground_y(self.x, self.GROUND_Y - 8, 1, self.GROUND_Y)
  self.spawn_yt = self.GROUND_Y - 0x30
  set_xy(self, self.x, self.spawn_yt + 8)
  self.switch_side = 0
  // 0: does not respawn. 1: respawns with room refresh
  self.respawn_type = 0
  if (self.dk_spawn !== undefined) {
    for (let _i = 0x1; _i <= 0xf; _i++) {
      const _val = val(g.dm_spawn.get(self.dk_spawn + STR_Data + hexStr(_i)))
      if (typeof _val === 'string') {
        let _pos = _val.indexOf(STR_Side)
        if (_pos >= 0) self.switch_side = str_hex(_val.substring(_pos + STR_Side.length))
        _pos = _val.indexOf(STR_Respawn)
        if (_pos >= 0) self.respawn_type = str_hex(_val.substring(_pos + STR_Respawn.length))
      }
    }
  }
  // 0: neither, 1: right, 2: left, 3: both
  self.switch_side &= 0x3
  if (self.dk_spawn !== undefined && f.dm_openedLocks.get(self.dk_spawn) !== undefined) {
    // Already opened.
    self.state = 0
  }
}

/** `LockedDoor_update()` — D991 */
export function LockedDoor_update(self: LoDoA): void {
  const P = pc()
  GOB_update_2(self)
  // D994
  // FIXED: GML truthiness (`real > 0.5`) makes the `counter = -1` "start opening" trigger FALSE here, so
  // control reaches the ver-3 case below that converts -1 → 1. JS treats -1 as truthy, so `counter++`
  // took it to 0 and the door never opened — paying the map merchant or the pogo fee froze the player.
  if (gmBool(self.counter)) {
    // Opening
    self.counter++
    if (self.counter >= 0x12) {
      if (avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
        const proj = GOC1_create(self.xl, self.yt + 0x10 - 3, P.xScale, 'ProjectileHostile')
        if (proj) {
          proj.state = proj.state_EXPLODE
          ;(proj as unknown as { disintegrate_counter: number }).disintegrate_counter = 0xf0 // Disintegrate
        }
      }
      g.pc_lock = 0
      switch (self.respawn_type) {
        default:
          if (self.dk_spawn !== undefined) f.dm_openedLocks.set(self.dk_spawn, 1)
          break
        case 1: // respawns with room refresh
          if (self.dk_spawn !== undefined) g.dm_spawn.set(self.dk_spawn + STR_Spawn_Permission, 1)
          break
      }
      self.state = 0
    }
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // D9BA
  P.colliding_locked_door = 0x0 // 05E7
  if (self.cs & CS_BD1) {
    // D9C3
    if (!pc_is_fairy()) pushback_pc_and_go(self)
    if (self.x < P.x) P.colliding_locked_door = 0x2
    else P.colliding_locked_door = 0x1
    self.facing_dir = dir_to_pc(self)
  } else if (isVal(self.ver, 1, 2)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  switch (self.ver) {
    case 1: {
      // Need key -----------------------
      let _qual = false
      if (f.items & ITM_SKEY) {
        _qual = true
      } else if (f.key_count) {
        const _DATAKEY = STR_Dungeon + hexStr(g.dungeon_num)
        const _COUNT = val(g.dm_spawn.get(_DATAKEY + STR_Key + STR_Count)) as number
        for (let _i = 0; _i < _COUNT; _i++) {
          // key_datakey example: "0203", "0601"
          const _key_id = STR_KEY + hexStr(g.dungeon_num) + hexStr(_i + 1)
          if (
            gmBool(val(f.dm_keys.get(_key_id + STR_Acquired)) as number) &&
            !gmBool(val(f.dm_keys.get(_key_id + STR_Used)) as number)
          ) {
            // Doesn't matter which room the key was obtained.
            f.dm_keys.set(_key_id + STR_Used, 1)
            f.key_count = get_key_count(g.dungeon_num)
            _qual = true
            break
          }
        }
      }
      if (_qual) self.counter = 1 // Starts opening process
      break
    }
    case 2: {
      // Switch --------------------------
      const _C1 =
        self.switch_side === (0x1 | 0x2) || // $1: right, 2: left
        (self.switch_side === 0x1 && self.x < P.x) ||
        (self.switch_side === 0x2 && self.x >= P.x)
      if (_C1 && P.cs & CS_BTM) self.counter = 1 // Starts opening process
      break
    }
    case 3: {
      if (self.counter === -1) self.counter = 1 // Starts opening process
      break
    }
  }
  if (!self.counter) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (self.cs & CS_BD1) {
    P.hspd = 0
    P.vspd = 0
    g.pc_lock = PC_LOCK_ALL // Lock all
  }
  switch (self.respawn_type) {
    default:
      if (self.dk_spawn !== undefined) f.dm_openedLocks.set(self.dk_spawn, 1)
      break
    case 1: // respawns with room refresh
      if (self.dk_spawn !== undefined) g.dm_spawn.set(self.dk_spawn + STR_Spawn_Permission, 1)
      break
  }
  aud_play_sound(get_audio_theme_track(STR_Open + STR_LockedDoor))
}

/** `LockedDoor_udp()` */
export function LockedDoor_udp(self: LoDoA): void {
  self.can_draw_self = true
  switch (self.ver) {
    case 1:
      self.sprite = self.SPR_1A // Need key
      break
    case 2:
    case 3:
      self.sprite = self.SPR_1B // Switch / Challenge
      break
  }
  self.xScale = 1
  self.openYOff = self.YOFF
  if (self.counter) self.openYOff -= self.counter
}

/** `LockedDoor_draw()` */
export function LockedDoor_draw(self: LoDoA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  pal_swap_set(self.palidx)
  draw_sprite_at(self.depth, self.SPR_2A, 0, self.drawX, self.drawY - self.openYOff, -1, 1)
  draw_sprite_at(self.depth, self.SPR_2A, 0, self.drawX, self.drawY + self.openYOff, -1, 1)
  GO_draw_sprite(self, self.sprite)
  if (self.ver === 2 && self.switch_side && self.counter < 2) {
    if (self.switch_side & 0x1)
      draw_sprite_at(self.depth, self.SPR_3A, 0, self.drawX + self.SWITCH_XOFF, self.drawY + self.YOFF, -1, 1)
    if (self.switch_side & 0x2)
      draw_sprite_at(self.depth, self.SPR_3A, 0, self.drawX - self.SWITCH_XOFF, self.drawY + self.YOFF, -1, 1)
  }
  pal_swap_reset()
}
