/** GameMaker gamepad button constants used by ZALiA's rebindable gamepad mapping. */
export type GpButton =
  | 'gp_padr'
  | 'gp_padl'
  | 'gp_padd'
  | 'gp_padu'
  | 'gp_face1'
  | 'gp_face2'
  | 'gp_face3'
  | 'gp_face4'
  | 'gp_start'
  | 'gp_select'
  | 'gp_shoulderl'
  | 'gp_shoulderr'
  | 'gp_shoulderlb'
  | 'gp_shoulderrb'
  | 'gp_axislh'
  | 'gp_axislv'

/** Keyboard keys ZALiA reads directly (`keyboard_check`). */
export type Key =
  | 'D'
  | 'A'
  | 'S'
  | 'W'
  | 'T'
  | 'vk_right'
  | 'vk_left'
  | 'vk_down'
  | 'vk_up'
  | 'vk_enter'
  | 'vk_control'
  | 'vk_backspace'
  | 'vk_space'
  | 'vk_escape'
  | 'vk_shift'
  | 'F'
  | 'M'
  | 'N'
  | 'O'
  | 'G'
  | 'I'
  | 'K'
  | 'J'
  | 'L'
  | 'H'
  | 'R'
  | 'Z'
  | 'E'
  | 'U'
  | 'V'
  | 'F1'
  | 'F2'
  | 'F3'
  | 'F8'

/**
 * One frame's raw device state, sampled by the adapter before `world.step()`.
 * `pressed`/`released` are edge flags for this frame (GM `*_check_pressed/released`).
 */
export interface RawInput {
  keysHeld: ReadonlySet<Key>
  keysPressed: ReadonlySet<Key>
  gamepad: {
    connected: boolean
    /** `gamepad_get_description()` — used as the per-controller rebinding key. */
    description: string
    held: ReadonlySet<GpButton>
    pressed: ReadonlySet<GpButton>
    released: ReadonlySet<GpButton>
    /** -1..1 for gp_axislh / gp_axislv. */
    axisLH: number
    axisLV: number
    axisCount: number
  } | null
}

export const EMPTY_RAW_INPUT: RawInput = { keysHeld: new Set(), keysPressed: new Set(), gamepad: null }

/** Helper for tests and adapters. */
export function rawInput(
  opts: { keys?: Key[]; pressed?: Key[]; gp?: Partial<NonNullable<RawInput['gamepad']>> } = {},
): RawInput {
  return {
    keysHeld: new Set(opts.keys ?? []),
    keysPressed: new Set(opts.pressed ?? []),
    gamepad: opts.gp
      ? {
          connected: true,
          description: 'Test Pad',
          held: new Set(),
          pressed: new Set(),
          released: new Set(),
          axisLH: 0,
          axisLV: 0,
          axisCount: 2,
          ...opts.gp,
        }
      : null,
  }
}
