import { gmBool } from '../../../nes/math8'
import { G, g } from '../../../runtime/world'
import { frameHooks } from '../../hooks'
import { notPorted } from '../../pending'
import { withInstance } from '../gm'
import { update_out_of_bounds_fail_safe } from '../update_out_of_bounds_fail_safe'

const update_menus = (...a: unknown[]) => (frameHooks.update_menus as (...x: unknown[]) => unknown)(...a)

/** GML: g_Step_A1() */
export function g_Step_A1() {
  G.pc.x_change_prev = G.pc.x_change1 + G.pc.x_change2
  G.pc.x_change = 0
  G.pc.x_change1 = 0 // x_change right before 1st update_Camera_1a()
  G.pc.x_change2 = 0 // x_change right before 2nd update_Camera_1a()
  G.pc.y_change_prev = G.pc.y_change1 + G.pc.y_change2
  G.pc.y_change = 0
  G.pc.y_change1 = 0 // y_change right before 1st update_Camera_1a()
  G.pc.y_change2 = 0 // y_change right before 2nd update_Camera_1a()
  /* TODO with */ withInstance('GameObject', (self) => {
    self.x_change = 0
    self.y_change = 0
  })
  // --------------------------------------------------------
  update_out_of_bounds_fail_safe()
  // --------------------------------------------------------
  if (!gmBool(g.EnterRoom_SpawnGO_timer)) {
    if (
      !gmBool(g.cutscene) ||
      g.gui_state === g.gui_state_DIALOGUE1 ||
      g.gui_state === g.gui_state_DIALOGUE2 ||
      g.gui_state === g.gui_state_DIALOGUE3
    ) {
      // C13A, C14B: JSR C1CD
      update_menus()
    }
  }
}
