/**
 * GM surfaces as cached draw-command lists. ZALiA's screens draw static text/frames into a surface once and
 * blit it every frame (`surface_create/set_target/…/draw_surface`). Here a `Surface` records the commands
 * drawn while it is the target and `draw_surface(s, x, y)` replays them offset by (x, y).
 * Palette swaps set while blitting apply to commands that had no swap of their own (approximation of GM
 * re-mapping already-drawn pixels — see FIDELITY_NOTES).
 */
import { type AnyDrawCmd, pushCmd } from './draw'

export class Surface {
  readonly cmds: AnyDrawCmd[] = []
  freed = false
  constructor(
    readonly width: number,
    readonly height: number,
  ) {}
}

let target: Surface | null = null
export const currentSurface = (): Surface | null => target

export const surface_create = (w: number, h: number): Surface => new Surface(w, h)
export const surface_exists = (s: unknown): s is Surface => s instanceof Surface && !s.freed
export function surface_free(s: unknown): void {
  if (surface_exists(s)) {
    s.freed = true
    s.cmds.length = 0
  }
}
export function surface_set_target(s: Surface): void {
  target = s
}
export function surface_reset_target(): void {
  target = null
}
/** `draw_clear_alpha(colour, alpha)` on a target surface — starts the surface over. */
export function draw_clear_alpha(_color: number, _alpha: number): void {
  if (target) target.cmds.length = 0
}

const OFFSET_KEYS = ['x', 'y', 'x1', 'y1', 'x2', 'y2'] as const

/** `draw_surface(surface, x, y)` — replay with offset; `pushCmd` fills the active swap into `palIdx: -1`. */
export function draw_surface(s: unknown, x: number, y: number, xscale = 1, yscale = 1): void {
  if (!surface_exists(s)) return
  for (const c of s.cmds) {
    const out: Record<string, unknown> = { ...c }
    for (const k of OFFSET_KEYS) {
      if (typeof out[k] === 'number') {
        const isX = k.startsWith('x')
        out[k] = (isX ? x : y) + (out[k] as number) * (isX ? xscale : yscale)
      }
    }
    if (xscale !== 1 && typeof out.xscale === 'number') out.xscale = (out.xscale as number) * xscale
    if (yscale !== 1 && typeof out.yscale === 'number') out.yscale = (out.yscale as number) * yscale
    pushCmd(out)
  }
}

/** `draw_surface_ext(surface, x, y, xscale, yscale, rot, colour, alpha)` — rotation/colour/alpha are ignored (unused by ZALiA screens). */
export function draw_surface_ext(
  s: unknown,
  x: number,
  y: number,
  xscale: number,
  yscale: number,
  _rot = 0,
  _col = -1,
  _alpha = 1,
): void {
  draw_surface(s, x, y, xscale, yscale)
}

const num = (c: AnyDrawCmd, k: string): number | undefined =>
  (c as Record<string, unknown>)[k] as number | undefined
const cmdX = (c: AnyDrawCmd): number => num(c, 'x') ?? num(c, 'x1') ?? 0
const cmdY = (c: AnyDrawCmd): number => num(c, 'y') ?? num(c, 'y1') ?? 0

/** Commands of `s` whose anchor lies inside the part rectangle, re-based to (0,0) of the part. */
function partCmds(s: Surface, left: number, top: number, w: number, h: number): AnyDrawCmd[] {
  const out: AnyDrawCmd[] = []
  for (const c of s.cmds) {
    const px = cmdX(c)
    const py = cmdY(c)
    if (px < left || px >= left + w || py < top || py >= top + h) continue
    const o: Record<string, unknown> = { ...c }
    for (const k of OFFSET_KEYS)
      if (typeof o[k] === 'number') o[k] = (o[k] as number) - (k.startsWith('x') ? left : top)
    out.push(o)
  }
  return out
}

/**
 * `surface_copy_part(dest, x, y, src, xs, ys, w, h)` — copies a rectangle of commands into `dest` at (x, y).
 *
 * GM's copy is a straight blit: it *replaces* the destination rectangle (alpha included), it does not
 * compose over it. The command-list analogue drops every destination command anchored inside the target
 * rectangle before appending the source's. Appending alone let `TitleScreen_Draw`'s single scratch surface
 * accumulate all four star-sky frames on top of each other.
 */
export function surface_copy_part(
  dest: Surface,
  x: number,
  y: number,
  src: unknown,
  xs: number,
  ys: number,
  w: number,
  h: number,
): void {
  if (!surface_exists(src)) return
  const copied = partCmds(src, xs, ys, w, h)
  const kept = dest.cmds.filter((c) => {
    const px = cmdX(c)
    const py = cmdY(c)
    return px < x || px >= x + w || py < y || py >= y + h
  })
  dest.cmds.length = 0
  dest.cmds.push(...kept)
  for (const c of copied) {
    const o: Record<string, unknown> = { ...c }
    for (const k of OFFSET_KEYS)
      if (typeof o[k] === 'number') o[k] = (o[k] as number) + (k.startsWith('x') ? x : y)
    dest.cmds.push(o)
  }
}

/** `draw_surface_part_ext(surface, left, top, w, h, x, y, xscale, yscale, colour, alpha)` */
export function draw_surface_part_ext(
  s: unknown,
  left: number,
  top: number,
  w: number,
  h: number,
  x: number,
  y: number,
  xscale = 1,
  yscale = 1,
  _col = -1,
  _alpha = 1,
): void {
  if (!surface_exists(s)) return
  const tmp = new Surface(w, h)
  tmp.cmds.push(...partCmds(s, left, top, w, h))
  draw_surface(tmp, x, y, xscale, yscale)
}

export const surface_get_width = (s: unknown): number => (surface_exists(s) ? s.width : 0)
export const surface_get_height = (s: unknown): number => (surface_exists(s) ? s.height : 0)

/** `surface_copy(destination, x, y, source)` — the source's recorded commands are appended, offset. */
export function surface_copy(dst: unknown, x: number, y: number, src: unknown): void {
  if (!surface_exists(dst) || !surface_exists(src)) return
  for (const c of src.cmds) {
    const out: Record<string, unknown> = { ...c }
    for (const k of OFFSET_KEYS)
      if (typeof out[k] === 'number') out[k] = (k.startsWith('x') ? x : y) + (out[k] as number)
    dst.cmds.push(out)
  }
}
