/**
 * `Input_GameTesting()` — the `DEV` hotkey block that toggles the debug overlays (`g.DevTools_state`
 * flags) plus the dev-dash gamepad modifier. Called every frame from `g_Step` through
 * `devHooks.Input_GameTesting`.
 *
 * Dropped: the commented-out `FileCleaning01` exit cycler, the cucco-knockback and `TargetGame_case`
 * experiment blocks, and the `vk_numpad2` frame-counter toggle (all `/* *\/`-commented in ZALiA).
 * The `DEV` macro is `true` in ZALiA's project file, so the hotkeys are live here too.
 */
import { g, input } from '../../runtime/world'
import { save_game_pref } from '../file/prefs'
import { keyboard_check, keyboard_check_pressed } from '../Game/gm'
import { pc } from '../game_object/goa/pc'
import { show_debug_overlay } from '../gui/deps'
import { gmBool } from '../math/index'

export function Input_GameTesting(): void {
  const _CTL = keyboard_check('vk_control')
  const _SHF = keyboard_check('vk_shift')
  // 'vk_alt' is not in `RawInput`'s `Key` union yet, so this reads false: the hotkeys stay reachable
  // while Alt is held. Add 'vk_alt' to runtime/rawInput.ts + the adapter's KEY_CODES to restore it.
  const _ALT = keyboard_check('vk_alt')

  // --------------------------------------------------------------------
  // Give PC faster hspd
  // GP_Other6: trig R;  g.DevDash_state: toggle in options menu;  pc.ogr: pc on ground
  if (
    input.GP_Other6_held &&
    gmBool(g.DevTools_state) &&
    gmBool(g.DevDash_state) &&
    !g.app_paused &&
    !gmBool(pc().ogr)
  ) {
    g.DevDash_state = 2 // 0: Off, 1: On, 2: On and dash input held
  } else {
    g.DevDash_state = Math.sign(g.DevDash_state) // 0 or 1
  }

  // --------------------------------------------------------------------
  // DEV: the following is for making these debug tools more accessible.
  if (_CTL || _SHF || _ALT) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!

  // Sequence through invulnerable state
  if (keyboard_check_pressed('I')) {
    g.dev_invState = (g.dev_invState & 0xf) + 1 // removes display timer bits
    g.dev_invState *= +(g.dev_invState < 3)
    g.dev_invState |= 0x800 // include display timer bit
    // Display timer bit starts at $800 and shifts right once every 8 frames until bit $008,
    // which signals the end of the display.
    if (g.dev_invState & 0xff) g.DevTools_state = 1
  }

  // Toggle show sprite outline
  if (keyboard_check_pressed('K')) {
    g.DevTools_state = 1
    g.canDrawSprOutline = (g.canDrawSprOutline + 1) % 3 // Sequences 0, 1, 2
  }

  // Toggle show xl,yt && xc,yc coords point
  if (keyboard_check_pressed('J')) {
    g.DevTools_state = 1
    g.canDraw_ogXY = !g.canDraw_ogXY
  }

  // Toggle show og cam outline
  if (keyboard_check_pressed('L')) {
    g.DevTools_state = 1
    g.can_draw_og_cam_outline = !g.can_draw_og_cam_outline
  }

  // Toggle show cs points
  if (keyboard_check_pressed('H')) {
    g.DevTools_state = 1
    g.can_draw_cs = !g.can_draw_cs
  }

  // Toggle show hitboxes
  if (keyboard_check_pressed('R')) {
    g.DevTools_state = 1
    g.can_draw_hb = !g.can_draw_hb
  }

  // Toggle show highlighted solid tiles
  if (keyboard_check_pressed('Z')) {
    g.DevTools_state = 1
    g.can_show_t_solid = !g.can_show_t_solid
  }

  // Toggle show Exit hb
  if (keyboard_check_pressed('E')) {
    g.DevTools_state = 1
    g.can_draw_Exit_hb = !g.can_draw_Exit_hb
  }

  // Toggle show debug overlay
  if (keyboard_check_pressed('U')) {
    g.DevTools_state = 1
    g.can_show_debug_overlay = !g.can_show_debug_overlay
    show_debug_overlay(g.can_show_debug_overlay)
    save_game_pref()
  }

  // Display Entity hp
  if (keyboard_check_pressed('V')) {
    g.DevTools_state = 1
    g.can_draw_hp = !g.can_draw_hp
  }
}
