// Ported from ZALiA scripts/g_Step_A2.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively

import { gmBool } from '../../../nes/math8'
import { G, g, p } from '../../../runtime/world'
import { frameHooks } from '../../hooks'
import { notPorted } from '../../pending'

const pc_is_cucco = (...a: unknown[]) => (frameHooks.pc_is_cucco as (...x: unknown[]) => unknown)(...a)

import { PC_update_hitboxes_1a } from '../../collision/hitbox'
import { update_stat_restore, update_xp } from '../../file/stats'
import { set_go_can_draw_self } from '../../game_object/go/misc'
import { pcInput } from '../../game_object/goa/pc'
import { update_GameObjectMgr } from '../../game_object_mgr/update'
import { update_Pallete_1a } from '../../palette/roomStart'
import { update_low_hp_sound } from '../../sound'
import { update_view_1 } from '../../view/update_view_1'
import { instance_exists, is_undefined, NOONE, withInstance } from '../gm'
import { update_cast_spell } from '../update_cast_spell'
import { update_Platforms } from '../update_Platforms'
import { update_spell_effects } from '../update_spell_effects'
import { update_tile_anims } from '../update_tile_anims'

const BurnableMgr_update = (...a: unknown[]) =>
  (frameHooks.BurnableMgr_update as (...x: unknown[]) => unknown)(...a)
const PC_update_1 = (...a: unknown[]) => (frameHooks.PC_update_1 as (...x: unknown[]) => unknown)(...a)
const PC_update_2 = (...a: unknown[]) => (frameHooks.PC_update_2 as (...x: unknown[]) => unknown)(...a)
const PC_update_death = (...a: unknown[]) =>
  (frameHooks.PC_update_death as (...x: unknown[]) => unknown)(...a)
const update_NIAO = (...a: unknown[]) => (frameHooks.update_NIAO as (...x: unknown[]) => unknown)(...a)
const update_pc_proj = (...a: unknown[]) => (frameHooks.update_pc_proj as (...x: unknown[]) => unknown)(...a)
const update_pc_proj_1a = (...a: unknown[]) =>
  (frameHooks.update_pc_proj_1a as (...x: unknown[]) => unknown)(...a)
const update_pc_proj_2a = (...a: unknown[]) =>
  (frameHooks.update_pc_proj_2a as (...x: unknown[]) => unknown)(...a)

/** GML: g_Step_A2() */
export function g_Step_A2() {
  // --------------------------------------------------------------------
  //var _PC_CAN_DRAW_SELF = global.pc.can_draw_self;
  // C1A2: JSR D250       - set all GO.canDrawSelf = false
  set_go_can_draw_self(false)
  // --------------------------------------------------------------------
  // C2D5: JSR D385, C2E9: JSR D385, D3CC
  // goes to rmB_Death if PC dead
  if (PC_update_death()) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // D3E9: JSR FFC5
  // D3EC: JSR 8DC3       - Cast spell
  update_cast_spell()
  // 8E26                 - Spell effects
  update_spell_effects()
  // D3EF                 - Life & Magic restoration
  update_stat_restore()
  // D433                 - XP Uptick/Drain, D4CE Activate Level-up menu
  update_xp()
  // 8E23: JSR 9235       - PC pallete and background color
  /* TODO with */ withInstance(p, (_self) => {
    update_Pallete_1a(pc_is_cucco() as boolean)
  })
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  update_Platforms()
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // D4D1                 - Low hp beep
  update_low_hp_sound()
  /* TODO with */ withInstance(G.pc, (self) => {
    // D4F3: JSR 903A       - PC
    PC_update_1()
    // D4F6                 - colliding_elevator & colliding_locked_door
    if (!is_undefined(self.colliding_elevator) && instance_exists(self.colliding_elevator)) {
      g.pc_lock &= ~self.colliding_elevator.pc_lock_bits
    }
    self.colliding_elevator = NOONE
    self.colliding_locked_door = 0x00
  })
  G.pc.x_change1 = G.pc.x_change
  G.pc.y_change1 = G.pc.y_change
  // D4FE: JSR 9925       - Camera    (OG update order)
  update_view_1()
  //if (view_update_order==1) update_view_1();
  // GML: `with(global.pc) PC_update_hitboxes_1a();` — the script takes *no* argument; it reads `Input.dHeld`
  // itself (`PC_update_body_offsets.gml:16`). The port's signature is `(downHeld: boolean)`, and passing the
  // PC instance into it made `downHeld` permanently truthy: the standing player got the crouch body box for
  // every collision test of the frame (this runs before `update_GameObjectMgr`) and his shield sat at
  // crouch height. `withInstance`'s callback parameter is `any`, so tsc could not see it.
  PC_update_hitboxes_1a(pcInput.dHeld) // 2023/10/31. Added so hb draw has right info
  //                      - PC projectile hb update
  update_pc_proj_2a()
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // D504: JSR D5A7       - Entities & projectiles
  if (gmBool(G.pc.state)) {
    /* TODO with */ withInstance(g.go_mgr, (_self) => {
      update_GameObjectMgr()
    })
  }
  //with(SmasherTrapManager) SmasherTrapManager_update();
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  G.pc.x_change2 = G.pc.x_change
  G.pc.y_change2 = G.pc.y_change
  // D4FE: JSR 9925       - Camera    (MOD: Moved cam update to here)
  // Added 2023/11/01. Because some GO can move PC
  if (G.pc.x_change !== 0 || G.pc.y_change !== 0) {
    update_view_1()
  }
  /*
if (view_update_order==2)
{
    update_view_1();
}
else
{
    // Added 2023/11/01. Because some GO can move PC
    if (global.pc.x_change!=0 
    ||  global.pc.y_change!=0 )
    {
        update_view_1();
    }
}
*/
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // D50A: JSR 80E5       - Animate fire in North Palace & other animations
  update_NIAO()
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // D50D: JSR 9847       - PC beam spawn
  update_pc_proj_1a()
  // 9878                 - PC projectile update
  update_pc_proj()
  BurnableMgr_update() // GML: with(BurnableMgr) BurnableMgr_update() — the manager singleton is the hook's own scope
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // D510: JSR A6D2       - breakable blocks
  update_tile_anims()
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // D513                 - PC landingTimer
  // D52D: JSR EBF0       - PC camX, ocs, udp, update_swrdXY
  // D530                 - PC scs (sword collide solid)
  /* TODO with */ withInstance(G.pc, (_self) => {
    PC_update_2()
  })
}
