/** `Overworld_init_data()` */
export function Overworld_init_data(self: Overworld): void {
  if (self.OVERWORLD_INIT_METHOD === 1) {
    // Code automation will not happen in Overworld_init_data_1() if OVERWORLD_INIT_METHOD==1
    Overworld_init_data_1(self)
  } else {
    const _REINITIALIZING = false // *** SET true WHEN ANY OF THIS DATA HAS CHANGED ***
    if (_REINITIALIZING) {
      // In ZALiA this printed the code for Overworld_init_data_2() and wrote OverworldData01.txt;
      // here the parser just fills the same structures directly.
      Overworld_init_data_1(self)
    } else {
      Overworld_init_data_2(self)
      if (g.anarkhyaOverworld_MAIN) Overworld_init_data_anarkhya(self)
    }
  }
  // -------------------------------------------------------------------------
  const _DEFAULT = val(self.dm.get(MK_OWRC_NPAL1), OWRC_DFL) as number
  g.OWRC_TOWN_RAUR1 = val(self.dm.get(MK_OWRC_TWN_RAUR1), _DEFAULT)
  g.OWRC_TOWN_RUTO1 = val(self.dm.get(MK_OWRC_TWN_RUTO1), _DEFAULT)
  g.OWRC_TOWN_SARI1 = val(self.dm.get(MK_OWRC_TWN_SARI1), _DEFAULT)
  g.OWRC_TOWN_SARI2 = val(self.dm.get(MK_OWRC_TWN_SARI2), _DEFAULT)
  g.OWRC_TOWN_MIDO1 = val(self.dm.get(MK_OWRC_TWN_MIDO1), _DEFAULT)
  g.OWRC_TOWN_NABO1 = val(self.dm.get(MK_OWRC_TWN_NABO1), _DEFAULT)
  g.OWRC_TOWN_DARU1 = val(self.dm.get(MK_OWRC_TWN_DARU1), _DEFAULT)
  g.OWRC_TOWN_NEWK1 = val(self.dm.get(MK_OWRC_TWN_NEWK1), _DEFAULT)
  g.OWRC_TOWN_OLDK1 = val(self.dm.get(MK_OWRC_TWN_OLDK1), _DEFAULT)
  g.OWRC_TOWN_BULB1 = val(self.dm.get(MK_OWRC_TWN_BULB1), _DEFAULT)
  //                                                          //
  g.OWRC_DNGN_PRPA1 = val(self.dm.get(MK_OWRC_PAL_PRPA1), _DEFAULT)
  g.OWRC_DNGN_MDRO1 = val(self.dm.get(MK_OWRC_PAL_MDRO1), _DEFAULT)
  g.OWRC_DNGN_ISLD1 = val(self.dm.get(MK_OWRC_PAL_ISLD1), _DEFAULT)
  g.OWRC_DNGN_MAZE1 = val(self.dm.get(MK_OWRC_PAL_MAZE1), _DEFAULT)
  g.OWRC_DNGN_POTS1 = val(self.dm.get(MK_OWRC_PAL_POTS1), _DEFAULT)
  g.OWRC_DNGN_THRE1 = val(self.dm.get(MK_OWRC_PAL_THRE1), _DEFAULT)
  g.OWRC_DNGN_GRET1 = val(self.dm.get(MK_OWRC_PAL_GRET1), _DEFAULT)
  g.OWRC_DNGN_DRAG1 = val(self.dm.get(MK_OWRC_PAL_DRAG1), _DEFAULT)
  g.dm_dungeon.set(`${STR_Dungeon}01${STR_OWRC}`, g.OWRC_DNGN_PRPA1)
  g.dm_dungeon.set(`${STR_Dungeon}02${STR_OWRC}`, g.OWRC_DNGN_MDRO1)
  g.dm_dungeon.set(`${STR_Dungeon}03${STR_OWRC}`, g.OWRC_DNGN_ISLD1)
  g.dm_dungeon.set(`${STR_Dungeon}04${STR_OWRC}`, g.OWRC_DNGN_MAZE1)
  g.dm_dungeon.set(`${STR_Dungeon}05${STR_OWRC}`, g.OWRC_DNGN_POTS1)
  g.dm_dungeon.set(`${STR_Dungeon}06${STR_OWRC}`, g.OWRC_DNGN_THRE1)
  g.dm_dungeon.set(`${STR_Dungeon}07${STR_OWRC}`, g.OWRC_DNGN_GRET1)
  //dm_dungeon[?STR_Dungeon+"08"+STR_OWRC] = ;
  g.OWRC_NO_EXIT_DATA = _DEFAULT + 0x10
}

/** `Overworld_init_data_biome(biome id, tsrc data, *is rando biome, *rando tsrc special, *primary, *secondary, *tertiary)` */
export function Overworld_init_data_biome(
  self: Overworld,
  _BIOME: string,
  _TSRC_DATA: string,
  isRandoBiome?: boolean,
  tsrcSpecial?: number,
  tsrcPrimary?: number,
  tsrcSecondary?: number,
  tsrcTertiary?: number,
): string {
  const Biome_dm = self.Biome_dm
  Biome_dm.set(STR_Biome + STR_Count, (val(Biome_dm.get(STR_Biome + STR_Count)) as number) + 1)
  const _BIOME_NUM = Biome_dm.get(STR_Biome + STR_Count) as number
  Biome_dm.set(STR_Biome + hex_str(_BIOME_NUM), _BIOME)
  Biome_dm.set(_BIOME + STR_Biome + STR_Num, _BIOME_NUM)
  for (let _i = (_TSRC_DATA.length >> 2) - 1; _i >= 0; _i--) {
    const _tsrc_ = _TSRC_DATA.substr(_i << 2, 4)
    Biome_dm.set(STR_TSRC + _tsrc_ + STR_Biome, _BIOME)
  }
  const _dk = STR_Rando + STR_Biome + _BIOME
  self.dm_enc.set(_dk, isRandoBiome ?? false)
  // GML: each optional tsrc is stored only when `>= 0` (-1 = "none")
  if (tsrcSpecial !== undefined && tsrcSpecial >= 0)
    self.dm_enc.set(_dk + STR_TSRC + STR_Special, tsrcSpecial)
  if (tsrcPrimary !== undefined && tsrcPrimary >= 0)
    self.dm_enc.set(_dk + STR_TSRC + STR_Primary, tsrcPrimary)
  if (tsrcSecondary !== undefined && tsrcSecondary >= 0)
    self.dm_enc.set(_dk + STR_TSRC + STR_Secondary, tsrcSecondary)
  if (tsrcTertiary !== undefined && tsrcTertiary >= 0)
    self.dm_enc.set(_dk + STR_TSRC + STR_Tertiary, tsrcTertiary)
  return _BIOME
}

/** `Overworld_init_data_encounter1(biome, *has enc scene, *can spawn enc inst, *spawn cooldown, *enc inst duration, *spawn chance data)` */
export function Overworld_init_data_encounter1(
  self: Overworld,
  _BIOME: string,
  hasEncScene?: boolean,
  canSpawnEncInst?: boolean,
  spawnCooldown?: number,
  encInstDuration?: number,
  spawnChanceData?: string,
): void {
  const dm_enc = self.dm_enc
  dm_enc.set(`${_BIOME}_Has${STR_Encounter}${STR_Scene}`, hasEncScene === true)
  dm_enc.set(`${_BIOME}_Can${STR_Spawn}${dk_EncounterInstance}`, canSpawnEncInst === true)
  if (spawnCooldown !== undefined) dm_enc.set(_BIOME + STR_Spawn + STR_Cooldown, spawnCooldown)
  if (encInstDuration !== undefined) dm_enc.set(_BIOME + dk_EncounterInstance + STR_Duration, encInstDuration)
  if (spawnChanceData !== undefined) {
    const _CHAR_COUNT = 2
    const _COUNT = Math.trunc(spawnChanceData.length / _CHAR_COUNT)
    for (let _i = 0; _i < _COUNT; _i++) {
      const _val = str_hex(spawnChanceData.substr(_CHAR_COUNT * _i, _CHAR_COUNT))
      dm_enc.set(_BIOME + STR_Spawn + STR_Chance + hex_str(_i + 1), _val)
    }
    // FIDELITY: the GML never wrote `<biome>_Spawn_Chance_Count`, so `Overworld_enc_spawn_update`'s
    // `_COUNT1` loop read 0 and always picked object index 0; the intent (the NES spawn-chance table
    // $824D-8264) needs the count — recorded here.
    dm_enc.set(_BIOME + STR_Spawn + STR_Chance + STR_Count, _COUNT)
  }
}

/** `Overworld_init_data_1a(owrc)` — the GML printed a code line; nothing to do here. */
export function Overworld_init_data_1a(_owrc: number): void {}

const gridFromCache = (dst: DsGrid<any>, src: CacheGridJson | undefined): void => {
  if (!src) return
  gridResize(dst, src.width, src.height)
  for (let y = 0; y < src.height; y++)
    for (let x = 0; x < src.width; x++) dst.set(x, y, (src.cells[y] as any[])[x])
}

/**
 * `Overworld_init_data_2()` — method 3: load the pre-baked overworld data. Reads the decoded
 * `OverworldData01` cache from `world.caches` (`_Map0` = `dm`, plus the grids).
 */
export function Overworld_init_data_2(self: Overworld): void {
  const caches = world.caches
  if (!caches) {
    sdm(
      '!!!! WARNING! Overworld_init_data_2(). File  `ow_tile_data/OverworldData01.txt`  does not exist !!!!',
    )
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  let map0: CacheMapJson
  try {
    map0 = caches.map(dk_Map0 as '_Map0')
  } catch {
    sdm('!!!! WARNING! Overworld_init_data_2(). `dm_file_data[?dk_Map0]` is undefined !!!!')
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  self.dm = DsMap.from(map0 as Record<string, any>)
  self.OW_CLMS = 0x0100
  self.OW_ROWS = 0x0100
  self.OW_W = self.OW_CLMS << self.SHIFT
  self.OW_H = self.OW_ROWS << self.SHIFT
  // (the g.dm_rm scene-owrc / goto-owrc / ow_dir / goto_reen entries come from the scene_data cache)
  const grid = (name: string): CacheGridJson | undefined => {
    try {
      return caches.grid(name as 'dg_area')
    } catch {
      return undefined
    }
  }
  gridFromCache(self.dg_boulders, grid('dg_boulders'))
  self.BoulderCircle_center_OWRC = 0xc13e
  const circle = [0xbe3e, 0xbf40, 0xc141, 0xc340, 0xc43e, 0xc33c, 0xc13b, 0xbf3c]
  for (let i = 0; i < circle.length; i++) self.dl_BoulderCircle_OWRC.set(i, circle[i] as number)
  gridFromCache(self.HiddenExitIndicator_dg, grid('HiddenExitIndicator_dg'))
  gridFromCache(self.dg_ChangeTiles_Boots, grid('dg_ChangeTiles_Boots'))
  gridFromCache(self.dg_tsrc_def, grid('dg_tsrc_def'))
  gridCopy(self.dg_tsrc, self.dg_tsrc_def)
  gridFromCache(self.dg_solid_def, grid('dg_solid_def'))
  gridCopy(self.dg_solid, self.dg_solid_def)
  gridFromCache(self.dg_area, grid('dg_area'))
  gridFromCache(self.dg_AreaNames, grid('dg_AreaNames'))
}
