/** GML: Ganon1_update_battle_1() */
export function Ganon1_update_battle_1(self: Ganon1) {
  if (!gmBool(Ganon1_cs4(self))) {
    if (self.vspd < 0x80) {
      self.vspd = min(self.vspd, self.TERMINAL_VELOCITY)
    }
    updateY(self)
    GO_update_cs(self)
    if (!gmBool(self.off_ground_reason)) {
      self.off_ground_reason = OGR_OTHR
    }
    if (self.off_ground_reason === OGR_JUMP && self.vspd < 0x80) {
      Ganon1_update_battle_2(self) // pc body-to-body damage
    }
  } else {
    if (gmBool(self.vspd & 0x80)) {
      updateY(self)
      GO_update_cs(self)
    } else {
      set_xy(self, self.x, self.Ground_y - self.hh_)
      if (gmBool(self.off_ground_reason)) {
        self.off_ground_reason = 0
        return true
      }
    }
  }
  return false
}

/** GML: Ganon1_update_battle_2() */
export function Ganon1_update_battle_2(self: Ganon1) {
  switch (self.Collision_VER) {
    // ------------------------------------------------------------
    case 1: {
      update_body_hb_1a(self)
      if (
        gmBool(GO_can_collide_this_frame(self.update_idx)) &&
        !gmBool(self.stun_timer) &&
        !gmBool(G.pc.iframes_timer) &&
        G.pc.yt >= self.yt &&
        gmBool(collide_pc_body(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h, self.BodyHB_r))
      ) {
        PC_take_damage(self)
      }
      break
    }
    // ------------------------------------------------------------
    case 2: {
      Ganon1_update_battle_2a(self)
      break
    }
  } //switch(Collision_VER)
}

