/** GML: Ganon1_update_battle_3() */
export function Ganon1_update_battle_3(self: Ganon1) {
  if (!gmBool(Ganon1_cs4(self))) {
    if (!gmBool(self.off_ground_reason)) {
      self.off_ground_reason = OGR_OTHR
    }
    self.vspd_grav = 2
    if (self.vspd < 0x80) {
      self.vspd = min(self.vspd, self.TERMINAL_VELOCITY)
    }
    updateY(self)
    GO_update_cs(self)
    return false
  } else {
    self.off_ground_reason = 0
    set_xy(self, self.x, self.Ground_y - self.hh_)
    GO_update_cs(self)
    return true
  }
  return true
}

/** GML: Ganon1_cs4() */
export function Ganon1_cs4(self: Ganon1) {
  let _i: any

  for (_i = (self.ww >> 3) - 1; _i >= 0; _i--) {
    if (gmBool(collide_solid_grid(self.xl + 3 + (_i << 3), self.yb) & TID_SOLID1)) {
      return true
    }
  }
  return false
}

/** GML: Ganon1_udp() */
export function Ganon1_udp(self: Ganon1) {
  self.can_draw_self = true
  self.Crystal_can_draw = true
  self.Crystal_x = self.x + self.Crystal_xoff
  self.Crystal_y = self.y + self.Crystal_yoff
}

/** GML: Ganon1_draw() */
export function Ganon1_draw(self: Ganon1) {
  if (gmBool(self.can_draw_self)) {
    GameObject_draw_1a(self, self.sprite as string, self.palidx) // draw self
  }
  if (gmBool(self.Blood_can_draw)) {
    draw_sprite_('spr_1x1_WHT', 0, self.Blood_x - 1, self.Blood_yt, -1, 1, self.Blood_h, self.Blood_COLOR)
    draw_sprite_('spr_1x1_WHT', 0, self.Blood_x, self.Blood_yt - 1, -1, 1, self.Blood_h, self.Blood_COLOR)
  }
  if (gmBool(self.Crystal_can_draw)) {
    self.Crystal_can_draw = false
    switch (self.Crystal_sprite_state) {
      case 1: {
        self.Crystal_sprite = self.Crystal_SPRITE1
        self.Crystal_pi = G.PI_MOB_BLU
        break
      }
      case 2: {
        self.Crystal_sprite = self.Crystal_SPRITE2
        self.Crystal_pi = G.PI_MOB_RED
        break
      }
      case 3: {
        self.Crystal_sprite = self.Crystal_SPRITE2
        self.Crystal_pi = G.PI_MOB_ORG + ((g.counter1 >> 1) & 0x03)
        break
      }
    }
    //draw_sprite_(CrystalAura_sprite,0, Crystal_x,Crystal_y, CrystalAura_pi);
    draw_sprite_(self.Crystal_sprite, 0, self.Crystal_x, self.Crystal_y, self.Crystal_pi)
  }
  pal_swap_set(G.PI_MOB_RED)
  if (gmBool(self.BottleLiquid_can_draw) && gmBool(self.BottleLiquid_level)) {
    draw_sprite_(
      self.dl_BottleLiquid_SPRITES.get(self.BottleLiquid_level - 1),
      0,
      self.Bottle_x,
      self.Bottle_y,
    )
  }
  if (gmBool(self.Bottle_can_draw)) {
    draw_sprite_(self.Bottle_sprite, 0, self.Bottle_x, self.Bottle_y, -1, 1, self.Bottle_yscale)
  }
  pal_swap_reset()
  GameObjectB_debug_draw_1a(self) // body hb, shield hb, sword hb, cs points, ocs
  GO_debug_draw_1a(self) // xl/yt point, spr outline
  GOB_draw_hp(self) // Toggle with 'V'
}

