/**
 * Cross-references to scripts that are not ported yet. Each subsystem port declares what it needs here
 * with `notPorted('<gml script>')`; when the real implementation lands the declaration is deleted and the
 * import re-pointed. Calling a pending function throws, so nothing silently no-ops.
 */
// biome-ignore lint/suspicious/noExplicitAny: pending signatures are intentionally loose
export type AnyFn = (...args: any[]) => any

/**
 * Marker every unbound-seam placeholder carries, so `seams.test.ts` can walk the hook tables after a real
 * boot and fail on any that is still a placeholder — without calling it. Finding these one crash at a time
 * is how `g.go_mgr`, `installRando` and the whole `gobCollision` table stayed broken for a wave.
 */
export const PENDING = Symbol.for('z2.pendingSeam')

/** Tag `fn` as the not-yet-bound default for `name`. */
export function markPending<T>(fn: T, name: string): T {
  ;(fn as { [PENDING]?: string })[PENDING] = name
  return fn
}

/** The seam name if `v` is still an unbound placeholder, else undefined. */
export function pendingName(v: unknown): string | undefined {
  return typeof v === 'function' ? (v as { [PENDING]?: string })[PENDING] : undefined
}

export function notPorted(name: string): AnyFn {
  return markPending(() => {
    throw new Error(`GML script ${name} is not ported yet`)
  }, name)
}
