export class Thunderbird01 extends BossObject {
  override readonly objectName = 'Thunderbird01' as const
  Face_sprite: any = undefined
  HP: any = undefined
  Wings_yoff: any = undefined
  hp_CUE1: any = undefined
}

/** GML: Thunderbird_init2() */
export function Thunderbird_init2(self: Thunderbird01) {
  let _i: any, _a: any, _idx: any, _DIST: any

  Boss_init_2(self)
  _DIST = viewW_() + self.ww_ + (0x02 << 3)
  Boss_init_2b(self, _DIST)
  self.projectile_OBJ = 'Fireball2'
  self.projectile_VER = 2
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  GO_init_palidx(self, G.PI_MOB_RED)
  self.behavior = 0
  self.Face_sprite = 0
  self.Wings_yoff = 0
  // A349
  self.vspd = 8
  self.counter = 0
  self.HP = g.dl_HP.get(self.HP_IDX) as number
  self.hp_CUE1 = min(0x60, self.HP)
  // Setting react_thunder=0 so THUNDER
  // can't damage until the battle starts
  // react_thunder will be set back to REACT_THUNDER when the battle starts
  self.react_thunder = 0
  self.BodyHB_color = c_yellow
  Boss_set_MusicBattle_props(self, dk_ThunderBird)
}

/** GML: Thunderbird_update() */
export function Thunderbird_update(self: Thunderbird01) {
  let _TIMING: any

  // A359
  // check battle start/end/qualify
  if (!gmBool(Boss_update_1(self))) {
    update_EF11(self)
    g.go_mgr.update_idx = g.go_mgr.UPDATE_COUNT
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // Delay 1st attack
  if (gmBool(self.start_timer)) {
    self.start_timer--
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  } else {
    // Thunderbird_init_2 sets react_thunder=0 so
    // THUNDER can't damage until the battle starts
    self.react_thunder = self.REACT_THUNDER
  }
  // ------------------------------------------------------------
  // A3CC
  GO_update_cam_vars(self)
  self.cs &= 0xf0 // So sword can't hit multiple times in 1 stab.
  // if THUNDER has been cast
  if (self.hp < self.HP) {
    update_body_hb_1a(self)
    // At least 8 of body hb need to be on screen
    if (
      gmBool(
        borderInRect(
          8,
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_w,
          self.BodyHB_h,
          viewXL(),
          viewYT(),
          viewW(),
          viewH(),
        ),
      )
    ) {
      // A3C2 - Prevent taking dmg if Link is up/downthrust
      if (G.pc.behavior !== G.pc.behavior_STAB_DOWN && G.pc.behavior !== G.pc.behavior_STAB_UP) {
        // E48B - Link projectiles to enemy body
        GOB_body_collide_pc_proj(self)
        // E677 - Link sword to enemy body
        GOB_body_collide_pc_sword(self)
      }
      if (!gmBool(self.pc_sword_collided_solid_body)) {
        // E4D9 - Link body to enemy body
        GOB_body_collide_pc_body_1a(self)
      }
    }
  }
  // A3DB
  Boss_update_5(self) // check & set pending death
  // A3D2: JSR EF11
  update_EF11(self)
  // A3F7: JSR A4E9
  Boss_HPBar_udp(self)
  if (!gmBool(self.pending_death)) {
    Boss_Roar_update(self)
  }
  // ----------------------------------------------------------------
  // A3FA
  _TIMING = 0x1f >> +(self.hp < self.hp_CUE1) // $1F or $0F. Fireball spawn rate
  if (!gmBool(g.counter1 & _TIMING) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
    // A40B: JSR DBCE.                     Fireball2, ver 2
    /* TODO with */ {
      const _w1: any = GOC1_create(
        self.xl + 0x0c,
        self.yt,
        self.facing_dir,
        self.projectile as ObjectName,
        self.projectile_ver,
      )
      if (_w1) {
        // _data = "02040810FEFCF8F0"; // 02,04,08,10  FE,FC,F8,F0
        _w1.hspd = 0x02 << (g.dl_RandomOG.get(2) & 0x03)
        if (gmBool(g.dl_RandomOG.get(2) & 0x04)) {
          _w1.hspd = -_w1.hspd & 0xff
        }
        _w1.vspd = 0xf0
        GO_depth_init(_w1, self.depth - 1)
      }
    }
  }
  // ----------------------------------------------------------------
  // A436: JSR DEB8
  updateX(self)
  // A439: JSR DEC8
  updateY(self)
  // ----------------------------------------------------------------
  // A43C
  if (!gmBool(g.counter1 & 0x03)) {
    // A442
    // At spawn: vspd = 8, counter = 0
    // When counter is even: vspd decrements from $10 to $F0
    // When counter is odd:  vspd increments from $F0 to $10
    if (abs8b(self.vspd) === 0x10) {
      self.counter = (self.counter + 1) & 0xff // $10,$F0
    }
    if (gmBool(self.counter & 0x01)) {
      self.vspd = (self.vspd + 1) & 0xff
    } else {
      self.vspd = (self.vspd - 1) & 0xff
    }
  }
  // A45D
  if (!gmBool(g.counter1 & 0x1f)) {
    // A463: JSR DC91
    self.facing_dir = dir_to_pc(self)
    self.hspd = (0x10 * self.facing_dir) & 0xff
  }
}

/** GML: Thunderbird_udp() */
export function Thunderbird_udp(self: Thunderbird01) {
  // 9EBF
  self.can_draw_self = true
  self.Face_sprite = 0
  if (self.hp < self.HP) {
    if (!gmBool(g.counter1 & 0x18)) {
      self.Face_sprite = 'spr_Thunderbird_Face_1a'
    } else {
      self.Face_sprite = 'spr_Thunderbird_Face_1b'
    }
    if (self.palidx_def !== G.PI_MOB_BLU) {
      GO_init_palidx(self, G.PI_MOB_BLU)
    }
  }
  self.Wings_yoff = (g.counter1 & 0x06) >> 1 // $0,1,2,3
  self.Wings_yoff += 0x0c
}

/** GML: Thunderbird_draw() */
export function Thunderbird_draw(self: Thunderbird01) {
  if (!gmBool(self.can_draw_self)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  pal_swap_set(self.palidx)
  draw_sprite_('spr_Thunderbird_Wings_1a', 0, self.drawX, self.drawY + self.Wings_yoff, -1, self.xScale)
  draw_sprite_(
    'spr_Thunderbird_Wings_1b',
    0,
    self.drawX,
    self.drawY + (self.Wings_yoff << 1),
    -1,
    self.xScale,
  )
  GO_draw_sprite(self, 'spr_Thunderbird_Body_1a')
  GO_draw_sprite(self, self.Face_sprite)
  pal_swap_reset()
}
