/** `WosuA` — ZALiA `enemy/wosu`: hopping Wosu; v2 explodes into a Flame. B362 */
import {
  CS_BD1,
  PC_W_,
  STR_Datakey,
  STR_Direction,
  STR_Enemy,
  STR_Randomize,
  STR_Randomized,
  STR_Spawn,
  STR_Spawn_x,
} from '@z2/data'
import { byteNegate, gmBool } from '../../../../../../nes/math8'
import { f, G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { sign_ } from '../../../../../math/index'
import { val } from '../../../../../other/index'
import { registerObjectClass } from '../../../../../other/registry'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { GO_vspd_update1, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import { solid_clip_correction } from '../../../../goa/movement'
import type { ObjectName } from '../../../../objectNames'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'
import { dl } from '../../shared'

export class WosuA extends Enemy {
  readonly objectName = 'WosuA' as const
  HSPD1 = 0x10
  VSPD_GRAV = 2
}
registerObject('WosuA', WosuA)
registerObjectClass('WosuA', WosuA)

/** `Wosu_init2()` */
export function Wosu_init2(self: WosuA): void {
  const s = dl(self)
  s.set(1, 'spr_Wosu2')
  s.set(0, 'spr_Wosu1')
  GO_init_palidx(self, G.PI_MOB_ORG)
  // if not from a spawner
  if (self.dk_spawn !== undefined) {
    // If this is a rm enter spawn, PC.x may not be set yet.
    let _PC_X = (val(g.dm_rm.get(f.reen + STR_Spawn_x)) as number) << 3
    _PC_X += PC_W_
    self.facing_dir = sign_(self.x < _PC_X)
    const _spawn_datakey = val(
      f.dm_rando.get(
        STR_Randomize + STR_Enemy + STR_Spawn + self.dk_spawn + STR_Spawn + STR_Datakey + STR_Randomized,
      ),
      self.dk_spawn,
    ) as string
    const _val = val(g.dm_spawn.get(_spawn_datakey + STR_Direction))
    if (typeof _val !== 'string' && _val !== 0) self.facing_dir = _val as number
  }
  self.facing_dir = sign_(self.facing_dir)
  self.HSPD1 = 0x10
  self.hspd = (self.HSPD1 * self.facing_dir) & 0xff
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.projectile_OBJ = 'Flame1'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
}

/** `Wosu_udp()` */
export function Wosu_udp(self: WosuA): void {
  self.can_draw_self = true
  GO_set_sprite(self, dl(self).get(self.counter & 0x01) as string)
}

/** `Wosu_update()` — B362: JSR DE3D */
export function Wosu_update(self: WosuA): void {
  GO_update_cs(self)
  GOB_update_2(self) // DE40
  // B365
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  if (self.cs & 0x04) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0xf0 // JUMP!!
    self.counter = gmBool(self.counter) ? 0 : 1 // 0,1. determines sprite
  }
  // MOD. Prevent clip into ceiling
  GO_vspd_update1(self)
  // B37B
  updateY(self)
  if (self.cs & 0x03) {
    self.facing_dir = -self.facing_dir
    self.hspd = byteNegate(self.hspd)
  }
  updateX(self)
  if (self.ver === 2 && self.state === self.state_EXPLODE) {
    const flame = GOC1_create(
      self.x - 4,
      self.yt,
      self.facing_dir,
      self.projectile as ObjectName,
      self.projectile_ver,
    )
    flame.hspd = 0
  }
}

registerScripts({ Wosu_init2, Wosu_update, Wosu_udp })
