/**
 * `rand()` — the OG random byte for this object's update slot (`g.dl_RandomOG[|1+update_idx]`), or a plain
 * random byte when the slot is outside the register.
 */
export function rand(self: GameObject): number {
  const i = self.update_idx
  if (i >= 0 && i < g.dl_RandomOG_SIZE - 1) return (g.dl_RandomOG.get(1 + i) as number) ?? 0
  return world.irandom(0xff)
}

/** `goDist1()` — distance between global.pc.xl and this.xl mimicking the value stored in 000F at DCA1. */
export function goDist1(self: GameObject): number {
  const p = pc()
  let _return = p.xl & 0xff
  _return += ~(self.xl & 0xff) & 0xff
  _return += p.xl >= 0 && p.xl <= 7 ? 1 : 0 // carry
  return _return & 0xff
}

/** The rando-substituted spawn datakey (`f.dm_rando[?STR_Randomize+STR_Enemy+STR_Spawn+dk+…]`). */
export function randoSpawnDatakey(dk: string | undefined): string | undefined {
  if (dk === undefined) return undefined
  const v = f.dm_rando.get(
    STR_Randomize + STR_Enemy + STR_Spawn + dk + STR_Spawn + STR_Datakey + STR_Randomized,
  )
  return typeof v === 'string' ? v : dk
}

/**
 * The `for(_i=1; _i<$10; _i++) _val = g.dm_spawn[?dk+STR_Data+hex_str(_i)] … string_pos(key,_val)` idiom:
 * returns the text after `key` in the first `_DataNN` entry containing it, or undefined.
 */
export function spawnDataAfter(dk: string | undefined, key: string, maxIdx = 0x10): string | undefined {
  if (dk === undefined) return undefined
  for (let _i = 1; _i < maxIdx; _i++) {
    const _val = g.dm_spawn.get(dk + STR_Data + hexStr(_i))
    if (typeof _val !== 'string') continue
    const _pos = _val.indexOf(key)
    if (_pos !== -1) return _val.slice(_pos + key.length)
  }
  return undefined
}

/** `spawnDataAfter` parsed with `str_hex`, or the default. */
export function spawnDataHex(dk: string | undefined, key: string, dflt: number, maxIdx = 0x10): number {
  const s = spawnDataAfter(dk, key, maxIdx)
  return s === undefined ? dflt : str_hex(s)
}

/** Every existing instance whose ZALiA object name matches (`with (ObjName)`). */
export function* instancesNamed(name: string): Generator<GameObject> {
  for (const i of world.instances) {
    if (i.exists && (i as GameObject).objectName === name) yield i as GameObject
  }
}

/** `instance_exists(Obj)` by object name, returning the first live one. */
export function firstNamed(name: string): GameObject | null {
  for (const i of instancesNamed(name)) if (instanceExists(i)) return i
  return null
}

/** `projectile` typed for `GOC1_create`. */
export function projOf(self: GameObjectB): ObjectName {
  return self.projectile as ObjectName
}

// ---------------------------------------------------------------------------------------------------
// Enemy-root shared scripts

/** Fields the shared enemy scripts read beyond GameObject (present on the enemies that use them). */
export interface EnemyShared extends GameObjectB {
  attack_dist: number
  frwd_bkwd: number
}

/**
 * `Enemy_update_1()` — 9A2C. Used by Moblin v1/2/3, Goriya v1/2/3, Daira v1/2: gravity, push-back, pacing,
 * the attack-timing table and the attack-start decision.
 */
export function Enemy_update_1(self: EnemyShared): void {
  const p = pc()
  // 9A2C
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  updateY(self)
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  }
  // 9A3B
  const _hspdPB_COPY = self.hspd_pushback
  GOB_update_1(self, true) // update hspd_pushback
  GO_update_cs(self)
  if (!(self.cs & 0x3)) updateX(self)
  if (gmBool(_hspdPB_COPY)) return
  // 9A3E
  self.facing_dir = dir_to_pc(self)
  // ------------------------------------------------------------------------------------
  let _D1 = false // Daira  v1(orange)
  let _D2 = false // Daira  v2(red)
  let _G1 = false // Goriya v1(orange)
  let _G2 = false // Goriya v2(red)
  let _G3 = false // Goriya v3(blue)
  let _M1 = false // Moblin v1(orange)
  let _M2 = false // Moblin v2(red)
  let _M3 = false // Moblin v3(blue)
  switch (self.objectName) {
    case 'DairA':
      _D1 = self.ver === 1
      _D2 = self.ver === 2
      break
    case 'GoriA':
      _G1 = self.ver === 1
      _G2 = self.ver === 2
      _G3 = self.ver === 3
      break
    case 'MoblA':
      _M1 = self.ver === 1
      _M2 = self.ver === 2
      _M3 = self.ver === 3
      break
  }
  const _InAttackDist_ORIG = ((goDist1(self) + self.attack_dist) & 0xff) < ((self.attack_dist << 1) & 0xff)
  const _InAttackDist_WIDE = Math.abs(self.x - p.x) < self.attack_dist
  const _InAggroDist_WIDE = ocsH1(self)
  const _CAN_AGGRO = (_D1 || _M1 || _M2 || _M3) && _InAggroDist_WIDE && !gmBool(self.behavior)
  const _RAND = rand(self)
  let _val = 0x1
  if (_InAttackDist_ORIG) {
    // 9A6B
    self.counter = (self.counter + 1) & 0xff
    // $1F: every 32 frames = 0.533s, $3F: every 64 frames = 1.067s, $7F: every 128 frames = 2.133s
    _val = 0x3f // m1,m2, g2,g3, d1,d2. 1.067s
    if (_M3) _val = 0x1f // m3.  0.533s
    if (_G1) _val = 0x7f // g1.  2.133s
    _val &= self.counter
    if (!_val) {
      // A chance to time the next atk with the shortest duration (32 frames) instead of the normal 64/128.
      let _num = 0x1 // m2, m3        50%   1/2  chance
      if (_M1 || _G3 || _D1) _num = 0x3 // g3, d1, m1    25%   1/4  chance
      if (_G2 || _D2) _num = 0x7 // g2, d2        12.5% 1/8  chance
      if (_G1) _num = 0xf // g1            6.25% 1/16 chance
      if (!(_RAND & _num)) self.counter = 0xe0 // Next atk in 32 frames (about .5 seconds)
    }
  }
  if (_InAttackDist_ORIG || _CAN_AGGRO) {
    if (!_val || _CAN_AGGRO) {
      // 9982 -------------- START ATTACK --------------------------
      if (_D1 || _D2) {
        self.behavior = 1 // 1. atk high for Daira
      } else if (_M1) {
        // 9AA2
        self.behavior = 3 // 3. atk high
      } else {
        // m2,m3, g1,g2,g3: if PC crouching, high has a better chance; standing, low has a better chance
        if (pcInput.dHeld) {
          // 9AA2
          if ((_RAND & 0x7) === 0 || (_RAND & 0x7) === 2)
            self.behavior = 1 // 25%. 1: atk low
          else self.behavior = 3 // 75%. 3: atk high
        } else {
          if ((_RAND & 0x7) === 4 || (_RAND & 0x7) === 6)
            self.behavior = 3 // 25%. 3: atk high
          else self.behavior = 1 // 75%. 1: atk low
        }
      }
      // 9AA6
      self.timer = 0x18 // $18: 0.400s.  Attack delay
    }
  }
  const _HSPD1 = (0x04 * sign_(g.counter1 & 0x40)) & 0xff // Attack mode pacing
  if (!_InAggroDist_WIDE) {
    self.hspd = _HSPD1
    self.facing_dir = byte_dir(self.hspd)
  } else {
    if (_InAttackDist_WIDE) {
      // 9AAB. ------------------- SET hspd ---------------------------------
      if (p.cs & (CS_RGT | CS_LFT)) self.hspd = 0
      else if (gmBool(pcInput.hHeld) && gmBool(p.hspd)) self.hspd = p.hspd
      else self.hspd = _HSPD1
      self.hspd = (self.hspd >> 1) | (self.hspd & 0x80)
    } else {
      self.facing_dir = dir_to_pc_(self)
      self.hspd = (0x10 * self.facing_dir) & 0xff
    }
  }
}

/** `Enemy_update_2()` — 9B09. Used by Aruroda, Zora: forward/backward pacing decided every move period. */
export function Enemy_update_2(self: EnemyShared): void {
  // 9B09. $00-3F, 80-BF
  if (self.counter & 0x40) return // $40: 1.067s. During every other quarter of a byte
  if (!(self.counter & 0x3f)) {
    // 1st frame of move period: decide hspd for this move period
    let _C1 = 0x18
    // GML `if(!facing_dir)` is true for -1 (facing left) under GML truthiness — kept.
    if (!gmBool(self.facing_dir)) _C1 += 0x10
    const _c1 = wINwAll(self.x - _C1, 0x30, 0, cam_x_range())
    if (self.counter & 0x80 && _c1)
      self.frwd_bkwd = -self.facing_dir // go backwards
    else self.frwd_bkwd = self.facing_dir // go forwards
  }
  // GML `if (frwd_bkwd)`: -1 is false under GML truthiness, i.e. "forwards" only when facing right.
  if (gmBool(self.frwd_bkwd))
    self.hspd = (0x08 * self.facing_dir) & 0xff // go forwards
  else self.hspd = ((0x10 * self.facing_dir) & 0xff) ^ 0xff // go backwards
}

/** `Enemy_update_3()` — 9B45. Used by Aruroda, Tonne, Zora: vertical update + floor clip. */
export function Enemy_update_3(self: GameObject): void {
  if (self.vspd < 0x80 && self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
    return
  }
  if (self.vspd & 0x80 || !(self.cs & 0x4)) {
    if (self.vspd & 0x80 && self.cs & 0x8) self.vspd = 0 // MOD
    updateY(self)
  }
}

/** `Octorok_update()` — D888 (moving), D842 (still). Used by Octorok, Aneru. */
export function Octorok_update(self: GameObjectB): void {
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return
  }
  // D845: JSR DC91 (still)
  if (!(self.abilities & ABL_WALK)) self.facing_dir = dir_to_pc(self)
  // D88B: JSR D848 (moving). counter: Jump is on $00,80. Face PC on $40,C0
  self.counter = (self.counter + 1) & 0xff
  if (self.abilities & ABL_JUMP && !(self.counter & 0x7f)) {
    self.vspd = 0xe0 // Jump!!
  }
  updateY(self)
  // D858
  GO_update_cs(self)
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // D85E
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  } else {
    // MOD. Prevent clip into ceiling
    GO_vspd_update1(self)
    // at peak of jump
    if (!self.vspd || self.vspd < self.vspd_grav) {
      if (self.abilities & ABL_SHOT && is_facing_pc(self) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
        GOC1_create(self.xl, self.yt, self.facing_dir, projOf(self), self.projectile_ver)
      }
    }
  }
  // moving Octorok (v2)
  if (self.abilities & ABL_WALK) {
    // D88E
    if (self.cs & 0x3) {
      self.facing_dir = -self.facing_dir
      self.hspd = byteNegate(self.hspd)
    }
    updateX(self)
    // D89A:  Face and move towards PC
    if (((self.counter << 1) & 0xff) === 0x80) {
      // on $40,C0
      self.facing_dir = dir_to_pc(self)
      self.hspd = (0x08 * self.facing_dir) & 0xff
    }
  }
  // D8A9
  if (self.abilities & ABL_SHOT && self.ver === 2 && !self.timer) {
    self.timer = rand(self) | 0x80
    if (self.cs & 0x4 && is_facing_pc(self) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
      GOC1_create(self.xl, self.yt, self.facing_dir, projOf(self), self.projectile_ver)
    }
  }
}

// Base scripts referenced by name in GameObjectData_Create rows (`data_go_scr(o, 'GameObjectB_init', …)`).
registerScripts({ GameObjectB_init, GameObjectB_step2 })
