/** Atta (ZALiA object `Atta01`, parent `Enemy`; the hovering flame spitter). `Atta_init2/update/udp.gml`. */
import { CS_BD1, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { sign_ } from '../../../../../math/index'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { set_xy } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'
import { projOf } from '../ache/_shared'

export class Atta01 extends Enemy {
  readonly objectName = 'Atta01' as const
  DUR_COOLDOWN = 0xc0
}

/** `Atta_init2()` */
export function Atta_init2(self: Atta01): void {
  GO_init_palidx(self, G.PI_MOB_RED)
  self.DRAW_YOFF = 0
  self.dl_sprites?.set(1, 'spr_Atta_1b_2')
  self.dl_sprites?.set(0, 'spr_Atta_1a_1')
  GO_set_sprite(self, self.dl_sprites?.get(0) as string)
  self.projectile_OBJ = 'Flame2'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.facing_dir = 1
  self.DUR_COOLDOWN = 0xc0
}

/** `Atta_update()` */
export function Atta_update(self: Atta01): void {
  const _DUR = 0x30
  if (self.counter === self.DUR_COOLDOWN + _DUR) self.counter = _DUR
  else self.counter = (self.counter + 1) & 0xff
  if (self.counter === self.DUR_COOLDOWN) {
    for (let _i = 0; _i < 2; _i++) {
      if (avail_uidx_goc(MAX_GOC1) === UIDX_NULL) continue
      const p = GOC1_create(self.x - 4, self.yt - 4, sign_(_i), projOf(self), self.projectile_ver)
      p.vspd = 0xe0
      // FIXED: inside GML's `with(GOC1_create(...))` the bare `facing_dir` is the *projectile's*, set by
      // `GOC1_create` to `sign_(_i)` — so the pair splits left/right. Reading Atta's own `facing_dir`
      // (pinned at 1) sent both flames right.
      p.hspd = (0x10 * p.facing_dir) & 0xff
    }
  }
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  GO_update_cs(self) // solids collision
  GOB_update_2(self) // body/shield/sword collision
  GO_update_cs(self)
  if (!(g.counter1 & 0x7)) {
    const _Y_OFF = 1
    if (g.counter1 & 0x20) set_xy(self, self.x, self.y - _Y_OFF)
    else set_xy(self, self.x, self.y + _Y_OFF)
  }
}

/** `Atta_udp()` */
export function Atta_udp(self: Atta01): void {
  self.can_draw_self = true
  if (self.counter >= self.DUR_COOLDOWN - 0x04 && self.counter <= self.DUR_COOLDOWN + 0x20)
    GO_set_sprite(self, self.dl_sprites?.get(1) as string)
  else GO_set_sprite(self, self.dl_sprites?.get(0) as string)
}

registerObject('Atta01', Atta01)
registerScripts({ Atta_init2, Atta_update, Atta_udp })
