/** `Overworld_udp()` — per-frame draw preparation (positions, sprites, palette indices). */
import {
  dk_can_draw,
  ITM_BOOT,
  ITM_MAP1,
  ITM_MAP2,
  STR_1UP,
  STR_Acquired,
  STR_Count,
  STR_Current,
  STR_HEART,
  STR_ID,
  STR_Idx,
  STR_Item,
  STR_Kakusu,
  STR_KEY,
  STR_Key,
  STR_Location,
  STR_Locations,
  STR_MAGIC,
  STR_OWRC,
  STR_PBAG,
  STR_Randomize,
  STR_Randomized,
  STR_Sprite,
  STR_Text,
  STR_Total,
  STR_Varied,
} from '@z2/data'
import { byte, gmBool } from '../../nes/math8'
import { f, G, g, p, world } from '../../runtime/world'
import { rectInRect } from '../collision/geometry'
import { isVal, sign_ } from '../math'
import { hex_str, val } from '../other'
import { viewH, viewW, viewXC, viewXL, viewYC, viewYT } from '../view/camera'
import { get_bottle_bubbling_frame, pcView } from './deps'
import { ow_pc_xy } from './helpers'
import type { Overworld } from './Overworld'

const rectInView = (x: number, y: number, w: number, h: number) =>
  rectInRect(x, y, w, h, viewXL(), viewYT(), viewW(), viewH())

/** `Overworld_udp()` */
export function Overworld_udp(self: Overworld): void {
  const SHIFT = self.SHIFT
  const T_SIZE = self.T_SIZE
  let _val: number
  let _x: number
  let _y: number
  const _C1 = g.room_type === 'C' && !self.exit_owrc
  // [ZALiA: `if (false)` — the 1-pixel movement offset correction is disabled]
  self.draw_move_offset_x = 0
  self.draw_move_offset_y = 0
  self.Pause_xl = viewXC() - (self.Pause_TEXT_W >> 1)
  self.Pause_yt = viewYC() - 4
  self.PC_can_draw =
    _C1 &&
    (self.Warp_owrc !== self.pcrc ||
      !isVal(self.Warp_state, self.Warp_state_VANISH, self.Warp_state_OWRC_CHANGE, self.Warp_state_APPEAR))
  self.PC_draw_image_idx = 0x60 | (self.pc_sprite_idx & 0x0f)
  self.PC_draw_xoff = self.PC_draw_XOFF
  self.PC_draw_yoff = self.PC_draw_YOFF
  self.PC_draw_x_base = ow_pc_xy(0) // pc view x
  self.PC_draw_y_base = ow_pc_xy(1) // pc view y
  self.PC_draw_x = self.PC_draw_x_base + self.PC_draw_xoff
  self.PC_draw_y = self.PC_draw_y_base + self.PC_draw_yoff
  const pc = pcView()
  const _idx = val(pc.dm_skins.get(STR_Current + STR_Idx)) as number
  self.PC_draw_is_sheet = val(pc.dm_skins.get(`${hex_str(_idx)}_source_is_file`)) as number | boolean
  self.PC_draw_sheet_xl = pc.Spritesheet_W * self.pc_sprite_idx
  self.PC_draw_sheet_yt = pc.Spritesheet_H * 0x0e
  if (gmBool(self.PC_draw_is_sheet)) {
    self.PC_draw_x -= pc.Spritesheet_W >> 1
    self.PC_draw_y -= pc.Spritesheet_H >> 1
  }
  self.Encounters_can_draw = _C1
  self.BAIT_can_draw = _C1 && gmBool(self.BAIT_timer)
  self.BAIT_draw_x = self.PC_draw_x_base + (self.BAIT_ow_x - self.pc_ow_x)
  self.BAIT_draw_x += self.draw_move_offset_x
  self.BAIT_draw_y = self.PC_draw_y_base + (self.BAIT_ow_y - self.pc_ow_y)
  self.BAIT_draw_y += self.draw_move_offset_y
  self.Warp_can_draw = false
  self.Warp_sprite = 0
  self.Warp_xscale = 1
  self.Warp_yscale = 1
  self.WarpText_can_draw = false
  if (_C1 && self.Warp_state) {
    switch (self.Warp_state) {
      // -----------------------------------------
      case self.Warp_state_FLUTE: {
        if (self.flute_timer & 0x01) {
          self.Warp_sprite = 'spr_Tornado01'
          self.Warp_xscale = sign_(self.flute_timer & 0x10)
        }
        break
      }
      // -----------------------------------------
      case self.Warp_state_SPIN_UP: {
        self.Warp_sprite = 'spr_Tornado01'
        // Duration: $40
        if (self.Warp_timer < 0x08) self.Warp_xscale = sign_(self.Warp_timer & 0x01)
        else if (self.Warp_timer < 0x14) self.Warp_xscale = sign_(self.Warp_timer & 0x02)
        else if (self.Warp_timer < 0x28) self.Warp_xscale = sign_(self.Warp_timer & 0x04)
        else self.Warp_xscale = sign_(self.Warp_timer & 0x08)
        break
      }
      // -----------------------------------------
      case self.Warp_state_SPIN_DOWN: {
        if (self.Warp_timer > 0x18 || self.Warp_timer & 0x01) self.Warp_sprite = 'spr_Tornado01'
        // Duration: $60
        if (self.Warp_timer > self.Warp_DURATION1 - 0x0c) self.Warp_xscale = sign_(self.Warp_timer & 0x01)
        else if (self.Warp_timer > self.Warp_DURATION1 - 0x24)
          self.Warp_xscale = sign_(self.Warp_timer & 0x02)
        else if (self.Warp_timer > self.Warp_DURATION1 - 0x40)
          self.Warp_xscale = sign_(self.Warp_timer & 0x04)
        else self.Warp_xscale = sign_(self.Warp_timer & 0x08)
        break
      }
    }
    if (
      self.Warp_sprite ||
      (self.Warp_state === self.Warp_state_VANISH && self.Warp_timer > self.Warp_DURATION3 - 0x10) ||
      (self.Warp_state === self.Warp_state_APPEAR && self.Warp_timer < 0x10)
    ) {
      self.Warp_can_draw = true
      self.Warp_draw_x = ((self.Warp_owrc >> 0) & 0xff) << SHIFT
      self.Warp_draw_x += T_SIZE >> 1
      self.Warp_draw_x = self.PC_draw_x_base + (self.Warp_draw_x - self.pc_ow_x)
      self.Warp_draw_x += self.draw_move_offset_x
      self.Warp_draw_y = ((self.Warp_owrc >> 8) & 0xff) << SHIFT
      self.Warp_draw_y += T_SIZE >> 1
      self.Warp_draw_y = self.PC_draw_y_base + (self.Warp_draw_y - self.pc_ow_y)
      self.Warp_draw_y += self.draw_move_offset_y
      if (self.Warp_sprite) {
        self.Warp_pi = (p.dg_PI_SEQ.get(0, (self.Warp_timer >> 2) & 0x03) as number) + p.PI_LIT1
        if (self.Warp_state === self.Warp_state_FLUTE || self.Warp_state === self.Warp_state_SPIN_UP) {
          self.WarpText_can_draw = true
          self.WarpText_text = self.Warp_dg_DESTINATIONS.get(self.Warp_destination_num - 1, 2) as string
          self.WarpText_draw_xl = self.Warp_draw_x
          self.WarpText_draw_xl -= (self.WarpText_FONT_W * self.WarpText_text.length) >> 1
          self.WarpText_draw_yt = self.Warp_draw_y
          self.WarpText_draw_yt -= 0x0a + self.WarpText_FONT_W
        }
      } else {
        // FIDELITY: GML `_val = Warp_timer - Warp_state==Warp_state_VANISH; _val &= $F` compared (timer-state)
        // with the VANISH constant, so `_val` was always 0/1 and the pop always drew frame 3. Intent (see
        // the `$B-$F`, `$7-$A`, `$0-$6` comments): the low nybble of the timer selects the pop frame.
        _val = self.Warp_timer & 0x0f
        if (_val > 0x0a)
          self.Warp_sprite = 'spr_pop01_1' // $B-$F
        else if (_val > 0x06)
          self.Warp_sprite = 'spr_pop01_2' // $7-$A
        else self.Warp_sprite = 'spr_pop01_3' // $0-$6
        self.Warp_pi = G.PI_GUI1
      }
    }
  }
  self.TreasureMaps_can_draw = false
  if (_C1 && f.items & (ITM_MAP1 | ITM_MAP2)) {
    if (g.counter1 & 0x10) self.TreasureMaps_Kakusu_sprite = 'spr_Slime_Small_1a_1'
    else self.TreasureMaps_Kakusu_sprite = 'spr_Slime_Small_1b_1'
    _val = 0x28 // timing for beating heart anim
    if ((g.counter0 & _val) === _val) self.TreasureMaps_Heart_sprite = 'spr_Heart_1a'
    else self.TreasureMaps_Heart_sprite = 'spr_Heart_1b'
    self.TreasureMaps_Magic_sprite0 = 'spr_Bottle_6a' // empty bottle
    switch (get_bottle_bubbling_frame()) {
      case 0:
        self.TreasureMaps_Magic_sprite1 = 'spr_Bottle_6a_Liquid_1a'
        break
      case 1:
        self.TreasureMaps_Magic_sprite1 = 'spr_Bottle_6a_Liquid_1b'
        break
      case 2:
        self.TreasureMaps_Magic_sprite1 = 'spr_Bottle_6a_Liquid_1c'
        break
    }
    if (g.counter1 & 0x10) self.TreasureMaps_1up_sprite = 'spr_Item_LifeDoll_1a'
    else self.TreasureMaps_1up_sprite = 'spr_Item_LifeDoll_1b'
    self.TreasureMaps_Key_sprite = val(g.dm_ITEM.get(STR_KEY + STR_Sprite), 'spr_0') as string
    const TM = self.TreasureMaps_dg
    for (let _i = TM.width - 1; _i >= 0; _i--) {
      _x = self.PC_draw_x_base // 2: ow x
      _x += (TM.get(_i, 0x02) as number) - self.pc_ow_x
      _x += self.draw_move_offset_x
      _y = self.PC_draw_y_base // 3: ow y
      _y += (TM.get(_i, 0x03) as number) - self.pc_ow_y
      _y += self.draw_move_offset_y
      // $9: can draw
      TM.set(_i, 0x09, rectInView((_x >> SHIFT) << SHIFT, (_y >> SHIFT) << SHIFT, T_SIZE, T_SIZE))
      if (TM.get(_i, 0x09)) {
        self.TreasureMaps_can_draw = true
        let _spr: string
        let _pi: number
        let _yoff: number
        switch (TM.get(_i, 0x08)) {
          // $8: item type
          case STR_Kakusu:
            _spr = self.TreasureMaps_Kakusu_sprite
            _pi = self.TreasureMaps_Kakusu_PI
            _yoff = self.TreasureMaps_Kakusu_YOFF // because graphic is aligned to bottom of image
            break
          case STR_HEART:
            _spr = self.TreasureMaps_Heart_sprite
            _pi = self.TreasureMaps_Heart_PI
            _yoff = self.TreasureMaps_Heart_YOFF
            break
          case STR_MAGIC:
            _spr = self.TreasureMaps_Magic_sprite0
            _pi = self.TreasureMaps_Magic_PI
            _yoff = self.TreasureMaps_Magic_YOFF
            break
          case STR_1UP:
            _spr = self.TreasureMaps_1up_sprite
            _pi = self.TreasureMaps_1up_PI
            _yoff = self.TreasureMaps_1up_YOFF
            break
          case STR_KEY:
            _spr = self.TreasureMaps_Key_sprite
            _pi = self.TreasureMaps_Key_PI
            _yoff = self.TreasureMaps_Key_YOFF
            break
          default:
            _spr = 'spr_0'
            _pi = G.PI_MOB_ORG
            _yoff = 0
            break
        }
        TM.set(_i, 0x0a, _x) // $A: draw x
        TM.set(_i, 0x0b, _y + _yoff) // $B: draw y
        TM.set(_i, 0x0c, _spr) // $C: sprite
        TM.set(_i, 0x0d, _pi) // $D: palette index
      }
    }
  }
  self.BootsTileIndicator_can_draw = g.room_type === 'C' && gmBool(f.items & ITM_BOOT)
  self.HiddenExitIndicator_can_draw = false
  self.HiddenExitIndicator_sprite = 0
  self.HiddenExitIndicator_xscale = 1
  self.HiddenExitIndicator_yscale = 1
  // _C1:  g.room_type=="C" && !exit_grid_xy
  if (_C1 && g.HiddenExitIndicator_enabled) {
    self.HiddenExitIndicator_counter = (self.HiddenExitIndicator_counter + 1) & 0xff
    if (self.HiddenExitIndicator_counter & 0x20) {
      if (!(self.HiddenExitIndicator_counter & 0x1f)) {
        const choose = (...v: number[]) => v[world.irandom(v.length - 1)] as number
        self.HiddenExitIndicator_xoff = choose(0, 1, -1)
        self.HiddenExitIndicator_yoff = choose(0, 1, -1)
      }
      _val = self.HiddenExitIndicator_counter & 0x1f
      // fade effect
      if (_val < 0x18 || !(_val & 0x01)) {
        const H = self.HiddenExitIndicator_dg
        for (let _i = H.width - 1; _i >= 0; _i--) {
          const _clm = H.get(_i, 0x00) as number // $0: ow clm
          const _row = H.get(_i, 0x01) as number // $1: ow row
          _x = ow_pc_xy(0) + ((_clm << 4) - self.pc_ow_x)
          _x += self.draw_move_offset_x
          _x += 8
          _y = ow_pc_xy(1) + ((_row << 4) - self.pc_ow_y)
          _y += self.draw_move_offset_y
          _y += 8
          if (rectInView((_x >> 4) << 4, (_y >> 4) << 4, T_SIZE, T_SIZE)) {
            self.HiddenExitIndicator_can_draw = true
            H.set(_i, 0x02, true) // $2: can draw
            H.set(_i, 0x03, _x + self.HiddenExitIndicator_xoff) // $3: draw x
            H.set(_i, 0x04, _y + self.HiddenExitIndicator_yoff) // $4: draw y
          }
        }
        if (self.HiddenExitIndicator_can_draw) {
          if (_val < 0x08) self.HiddenExitIndicator_sprite = 'spr_pop01_1'
          else if (_val < 0x10) self.HiddenExitIndicator_sprite = 'spr_pop01_2'
          else self.HiddenExitIndicator_sprite = 'spr_pop01_3'
          if (_val >= 0x10) {
            if (_val & 0x04) self.HiddenExitIndicator_xscale = -1
            if (_val & 0x08) self.HiddenExitIndicator_yscale = -1
          }
        }
      }
    } else {
      if (!(self.HiddenExitIndicator_counter & 0x1f) && !world.irandom(0x01)) {
        self.HiddenExitIndicator_counter = (self.HiddenExitIndicator_counter + 0x10) & 0xff
      }
    }
  }
  self.ItemAcquiredIndicator_can_draw = false
  // _C1:  g.room_type=="C" && !exit_grid_xy
  if (_C1 && G.MarkItemLocations_state && g.counter1 & 0x40) {
    const S = f.dm_save_file_settings
    if (
      gmBool(val(S.get(STR_Randomize + STR_Item + STR_Locations))) ||
      gmBool(val(S.get(STR_Randomize + STR_PBAG + STR_Locations))) ||
      gmBool(val(S.get(STR_Randomize + STR_Key + STR_Locations)))
    ) {
      const RL = self.dm_rando_locations
      const _count = val(f.dm_rando.get(STR_Total + STR_Location + STR_Count)) as number
      for (let _i = 1; _i <= _count; _i++) {
        const _datakey1 = STR_Location + hex_str(_i)
        const _owrc = val(RL.get(_datakey1 + STR_OWRC), -1) as number
        if (_owrc !== -1) {
          if (G.MarkItemLocations_state === 2 || gmBool(val(RL.get(_datakey1 + STR_Acquired)))) {
            const _item_id = f.dm_rando.get(_datakey1 + STR_Item + STR_ID + STR_Randomized) as
              | string
              | undefined
            if (_item_id !== undefined) {
              _x = ow_pc_xy(0)
              _x += (byte(_owrc >> 0) << SHIFT) - self.pc_ow_x
              _x += self.draw_move_offset_x
              _x += 8
              RL.set(`${_datakey1}_X`, _x)
              _y = ow_pc_xy(1)
              _y += (byte(_owrc >> 8) << SHIFT) - self.pc_ow_y
              _y += self.draw_move_offset_y
              _y += 8
              RL.set(`${_datakey1}_Y`, _y)
              if (rectInView((_x >> SHIFT) << SHIFT, (_y >> SHIFT) << SHIFT, T_SIZE, T_SIZE)) {
                self.ItemAcquiredIndicator_can_draw = true
                RL.set(_datakey1 + dk_can_draw, true)
                const _owrc_ = hex_str(_owrc)
                const _count1 = val(RL.get(_owrc_ + STR_Item + STR_Count)) as number
                const _count2 = val(RL.get(_owrc_ + STR_Acquired + STR_Count)) as number
                let _spr: string
                if (gmBool(val(RL.get(_owrc_ + STR_Varied)))) {
                  _spr = _count2 < _count1 ? 'spr_CheckMark2_0' /* white */ : 'spr_CheckMark2_4' // magenta
                } else if (_item_id.includes(STR_PBAG)) {
                  _spr = _count2 < _count1 ? 'spr_CheckMark2_0' /* white */ : 'spr_CheckMark2_3' // blue
                } else if (_item_id.includes(STR_KEY)) {
                  _spr = _count2 < _count1 ? 'spr_CheckMark2_0' /* white */ : 'spr_CheckMark2_2' // yellow
                } else {
                  _spr = _count2 < _count1 ? 'spr_CheckMark2_0' /* white */ : 'spr_CheckMark2_1' // green
                }
                RL.set(_datakey1 + STR_Sprite, _spr)
                if (G.MarkItemLocations_state === 2 || (_count1 > 1 && _count2)) {
                  const _text = `${_count2}/${_count1}`
                  _x -= (_text.length * self.ItemAcquiredIndicator_FONT_W) >> 1
                  _y += 5
                  RL.set(_datakey1 + STR_Text, _text)
                  RL.set(`${_datakey1 + STR_Text}_XL`, _x)
                  RL.set(`${_datakey1 + STR_Text}_YT`, _y)
                }
              }
            }
          }
        }
      }
    }
  }
}
