/**
 * Object class registry and the data-bound script table (`g.dm_go_scr`, filled by `data_go_scr`).
 * Scripts are referenced by *name*; leaf ports register their functions with `registerScripts`, so the
 * table (generated from GameObjectData_Create.gml) links lazily and the port can proceed piecemeal.
 */
import { registerObjectClass } from '../other/registry'
import { GameObject, type ScriptFn } from './classes'
import type { ObjectName } from './objectNames'

export type GameObjectClass = new () => GameObject

/** Object name → concrete class. Leaf ports call `registerObject`. */
export const objectClasses = new Map<ObjectName, GameObjectClass>()

export function registerObject(name: ObjectName, cls: GameObjectClass): void {
  objectClasses.set(name, cls)
  registerObjectClass(name, cls as never) // also visible to `instancesNamed`/`with(Name)` in the GM shims
}

/** Script name → implementation (`script_execute` by name). */
export const scriptRegistry = new Map<string, ScriptFn>()

export function registerScripts(scripts: Record<string, ScriptFn<never>>): void {
  for (const [name, fn] of Object.entries(scripts)) scriptRegistry.set(name, fn as ScriptFn)
}

export function resolveScript(name: string | 0 | undefined): ScriptFn | undefined {
  if (!name) return undefined
  const fn = scriptRegistry.get(name)
  if (!fn)
    throw new Error(`GML script ${name} is referenced by object data but not registered (not ported yet)`)
  return fn
}

/** The 8 slots of `data_go_scr(obj name, *init1, *init2, *update, *udp, *draw, *instance end, *destroy, *room end)`. */
export interface ScriptSlots {
  ini1?: string
  ini2?: string
  updt?: string
  udp?: string
  draw?: string
  iend?: string
  dstr?: string
  rmen?: string
}

/** `g.dm_go_scr` — per object name (not objver), as in ZALiA. */
export const objectScripts = new Map<string, ScriptSlots>()

/** `data_go_scr(obj name, *init 1, *init 2, *update, *udp, *draw, *instance end, *destroy, *room end)` */
export function data_go_scr(objName: string, ...scripts: (string | number | undefined)[]): void {
  const keys: (keyof ScriptSlots)[] = ['ini1', 'ini2', 'updt', 'udp', 'draw', 'iend', 'dstr', 'rmen']
  const slots = objectScripts.get(objName) ?? {}
  scripts.forEach((s, i) => {
    const k = keys[i]
    if (typeof s === 'string' && s && k) slots[k] = s
  })
  objectScripts.set(objName, slots)
}

/** `is_ancestor(object_index, X)` for class references. */
export function isAncestor(self: GameObject, cls: abstract new () => GameObject): boolean {
  return self instanceof cls
}
/** `is_ancestor_(object_index, A, B, ...)` */
export function isAncestor_(self: GameObject, ...cls: (abstract new () => GameObject)[]): boolean {
  return cls.some((c) => self instanceof c)
}

export function resetRegistries(): void {
  objectScripts.clear()
}
export { GameObject }
