/** Renderer-agnostic draw commands produced by the core each frame, consumed by the Phaser adapter. */
export type DrawCmd =
  | {
      kind: 'sprite'
      sprite: string
      frame: number
      x: number
      y: number
      xscale: number
      yscale: number
      /** Palette index for the palette-swap shader (`p.PI_*`); -1 = none. */
      palIdx: number
      depth: number
      alpha: number
      /** GM `draw_sprite_ext` colour (24-bit RGB); used for silhouettes. Omit for none. */
      tint?: number
      /** GM `draw_sprite_ext` rotation in degrees (counter-clockwise). Omit for 0. */
      rotation?: number
    }
  | {
      /** `draw_sprite_part(_ext)`: a rectangle of a sprite frame. */
      kind: 'spritePart'
      sprite: string
      frame: number
      left: number
      top: number
      width: number
      height: number
      x: number
      y: number
      xscale: number
      yscale: number
      palIdx: number
      depth: number
      alpha?: number
      tint?: number
    }
  | {
      /** A cell of a user-supplied player-skin sheet (`sprite_add`ed at runtime, sliced manually). */
      kind: 'sheet'
      sprite: string
      sx: number
      sy: number
      w: number
      h: number
      x: number
      y: number
      xscale: number
      yscale: number
      palIdx: number
      depth: number
      tint?: number
    }
  | {
      kind: 'circle'
      x: number
      y: number
      radius: number
      color: number
      alpha: number
      outline: boolean
      depth: number
    }
  | { kind: 'line'; x1: number; y1: number; x2: number; y2: number; color: number; depth: number }
  | {
      /** A core-owned surface (e.g. the procedurally generated StarSky pages) drawn by the adapter. */
      kind: 'surface'
      surface: string
      index: number
      x: number
      y: number
      depth: number
    }
  | {
      /** `draw_background_part(_ext)`: a rectangle of a tileset image. */
      kind: 'tile'
      tileset: string
      left: number
      top: number
      w: number
      h: number
      x: number
      y: number
      xscale: number
      yscale: number
      palIdx: number
      depth: number
      alpha: number
    }
  | { kind: 'point'; x: number; y: number; color: number; depth: number }
  | {
      kind: 'rect'
      x1: number
      y1: number
      x2: number
      y2: number
      color: number
      depth: number
      alpha: number
      outline: boolean
    }
  | { kind: 'text'; font: string; text: string; x: number; y: number; palIdx: number; depth: number }

export class DrawList {
  readonly cmds: DrawCmd[] = []
  clear(): void {
    this.cmds.length = 0
  }
  push(cmd: DrawCmd): void {
    this.cmds.push(cmd)
  }
  /** Stable sort by depth descending (GM draws high depth first). */
  sorted(): DrawCmd[] {
    return this.cmds
      .map((c, i) => [c, i] as const)
      .sort((a, b) => b[0].depth - a[0].depth || a[1] - b[1])
      .map(([c]) => c)
  }
}
