/** `ow_pc_xy.gml`, `is_exiting_ow.gml` (`area_is_ow` lives in `game/room`). */

import { gmBool } from '../../nes/math8'
import { G, g } from '../../runtime/world'
import { viewXC, viewYC } from '../view/camera'
import type { Overworld } from './Overworld'

export { area_is_ow } from '../room'

/** `ow_pc_xy(0 for x OR 1 for y)` — the PC's view position on the overworld, snapped to 8 px. */
export function ow_pc_xy(axis: number): number {
  if (!gmBool(axis)) return (viewXC() >> 3) << 3
  return (viewYC() >> 3) << 3
}

/** `is_exiting_ow()` */
export function is_exiting_ow(): boolean {
  const ow = G.OVERWORLD as Overworld | undefined
  return g.room_type === 'C' && gmBool(ow?.exit_owrc)
}
