/** `PC_update_1b()` — 9610: water-walk sound and `updateX()` on the frame the water slow-walk allows. */
import { dk_WalkWater } from '@z2/data'
import { g } from '../../../runtime/world'
import { Audio } from '../../sound/Audio'
import { aud_play_sound } from '../../sound/play'
import { get_audio_theme_track } from '../../sound/theme'
import { updateX } from '../go/movement'
import type { Lonk } from './Lonk'

export function PC_update_1b_(self: Lonk): void {
  if (self.control & self.control_SOUND1 && self.hspd && (g.counter1 & 0x7) === 1) {
    Audio.walk_water_played_count++
    if (Audio.walk_water_played_count & 0x1)
      aud_play_sound(get_audio_theme_track(`${dk_WalkWater}02`)) // higher pitch
    else aud_play_sound(get_audio_theme_track(`${dk_WalkWater}01`))
  }
  let _timing = 0x0 // every   frame
  if (self.control & self.control_MOVE1)
    _timing = 0x1 // every 2 frame
  else if (self.control & self.control_MOVE2) _timing = 0x3 // every 4 frame
  if (!(g.counter1 & _timing)) updateX(self) // 9628: JSR D1CE
}
