export class Challenge_IntermittentPlatformSequence extends ChallengeBase {
  readonly objectName = 'Challenge_IntermittentPlatformSequence' as const
  State_SLEEP = 1 // not solid, no graphic
  State_TELL = 2 // not solid, appear tell/hint graphic
  State_ANIM_IN = 3 // not solid, animation in
  State_ANIM_OUT = 4 //     solid, animation out
  State_FULL = 5 //     solid, static graphic
  TELL_COLOR = 0xff0000
  DUR_TELL = 0x18
  DUR_ANIM = 0x18
  DUR_FULL = 0x90
  DUR_START = 0x80 // Restart delay
  DUR_SLEEP = 0xff
  SPR_PLAT_1A = 'spr_Platform_Rock_01a'
  SPR_PLAT_1B = 'spr_Platform_Rock_01b'
  SPR_PLAT_1C = 'spr_Platform_Rock_01c'
  HIDDEN_TYPE = 0
  /** seq_dir: iteration dir through dg_platform (which adjacent platform a platform activates from). */
  seq_dir = 1
  /** columns: restart hitboxes; rows: 0 sequence dir, 1 x, 2 y, 3 w, 4 h */
  dg_restart = new DsGrid<number>(0, 5, 0)
  PLATFORMS = 1
  /** columns: platforms; rows: 0 state, 1 timer, 2 clm, 3 row, 4 clms, 5 rows, 6 SOLID state */
  dg_platform = new DsGrid<number>(1, 7, 0)
}

