  ST_SUB1_PST2 = 8
  ST_SUB1_PST3 = 9
  ST_SUB1_END1 = 10
  ST_SUB1_NPC1 = 11 // Result dlg
  SND_GAME_START: SoundId = 0
  SND_GAME_DONE: SoundId = 0
  MUS_GAME_THEME = ''
  MUS_GAME_PLAY: SoundId = 0
