/** Fields the challenges read/write on the un-ported ElevatorB object. */
export interface ElevatorLike extends GameObject {
  HSPD: number
  VSPD: number
  hspd1: number
  vspd1: number
  moving_dir: number
  pc_lock_bits: number
  dl_exit: DsList<unknown>
}
