    Zelda_udp,
    Zelda_draw,
    Spawner_NPC_init2,
    Spawner_NPC_update,
    NPC_B_end,
    NPC_B_init,
    NPC_B_update,
    NPC_B_update_1,
    NPC_B_draw,
    NPC_D_init2,
    NPC_D_update,
    NPC_D_udp,
    Elevator_end,
