const DEV = false

/** `NPC_init1()` */
export function NPC_init1(self: NpcObject): void {
  if (self.objectName === 'NPC_0') self.can_draw_self_exception = true
  self.DRAW_YOFF = 1 // +1 for 1 pixel in ground
  GO_depth_init(self, DEPTH_NPC)
  self.scr_step = GameObjectB_step as never
}

/** `NPC_init2()` — see the version table in the GML header. */
export function NPC_init2(self: NpcObject): void {
  const P = pc()
  if (gmBool(g.town_num) && g.town_name === STR_Bulblin && !P.Disguise_enabled) {
    self.state = 0
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (
    self.dialogue_datakey === val(g.dm_rm.get(`MidoChurchDoor${dk_DialogueDatakey}`)) &&
    gmBool(val(f.dm_quests.get(dk_MidoChurch + STR_Open)) as number)
  ) {
    self.state = 0
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (is_ver(self, 'NPC_0', 3) && f.items & ITM_MIRR) {
    // MIRROR item, already has mirror
    self.state = 0
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // -----------------------------------------------------------------------------
  let _xl = self.xl
  let _yt = self.yt
  self.hspd = 0 // Most NPC don't move.
  self.GROUND_Y = (((self.spawn_yt >> 8) + 1) << 8) - (0x3 << 3)
  self.GROUND_Y = get_ground_y(self.x, self.GROUND_Y, -1, self.GROUND_Y)
  // -----------------------------------------------------------------------------
  const _BAGU = is_ver(self, 'NPC_9', 0x1) // Bagu
  const _TALO = is_ver(self, 'NPC_9', 0xc) // Talo
  const _BOT = is_ver(self, 'NPC_9', 0x5) // Bot  NPC
  const _MOBLN = is_ver(self, 'NPC_9', 0x3) // Friendly Moblin NPC
  const _SCROB = is_ver(self, 'NPC_9', 0x8) // Scroblin, monster town
  const _FAIRY = is_ver(self, 'NPC_8', 0x1) // Fairy NPC
  const _INVIS = is_ver(self, 'NPC_0', 0x1) // Invisible
  const _SIGN = is_ver(self, 'NPC_0', 0x2) // town sign
  const _SPLSQ = self.objectName === 'NPC_C' // Spell Sequence. King's Tomb, Passage to NECKLACE item, Kasuto Cemetery Kakusu
  if (_SIGN)
    GO_depth_init(self, DEPTH_BG2 - 1) // town sign
  else if (!isVal(self.objectName, 'NPC_4', 'NPC_5')) GO_depth_init(self, DEPTH_NPC - 1) // So door anim for $49-4E doesn't draw on top
  let _sprite = NPC_get_init_sprite(self)
  if (_SIGN) _sprite = 'spr_Placement_16x32' // Sign
  if (_INVIS) _sprite = 'spr_Placement_16x32' // Invisible dialogue
  if (_SPLSQ) _sprite = 'spr_Placement_16x32'
  if (_MOBLN) _sprite = 'spr_NPC_Moblin_1a_1' // Friendly Moblin NPC
  if (_FAIRY) _sprite = g.dl_Fairy_SPRITES.get(0) as string // Fairy NPC
  GO_sprite_init(self, _sprite)
  update_body_hb_1a(self)
  // -------------------------------------------------------------------------
  // D6D8
  if (_BAGU || _TALO || _FAIRY) {
    NPC_catch_item(self)
    if (_TALO && gmBool(val(f.dm_quests.get(STR_Talo + STR_State)) as number)) {
      if (self.Item_SPAWN_DATAKEY !== undefined)
        f.dm_quests.set(STR_Talo + STR_State, 1) // dlg: Take item
      else f.dm_quests.set(STR_Talo + STR_State, 2) // dlg: I have nothing else
    }
  } else if (_SIGN) {
    if (
      gmBool(val(G.dm_save_file_settings.get(STR_Randomize + STR_Town + STR_Locations)) as number) &&
      gmBool(g.town_num) &&
      g.town_name !== undefined &&
      val(f.dm_rando.get(`${STR_Town + STR_Rando + g.town_name}A`), g.town_name) !== g.town_name &&
      !gmBool(val(g.dm_rm.get(g.rm_name + STR_Rando + dk_LandLocked)) as number)
    ) {
      const _datakey = STR_Town + STR_Sign + STR_Dialogue + STR_Datakey
      self.dialogue_datakey = val(f.dm_rando.get(_datakey + g.town_name), self.dialogue_datakey) as string
      const DW = g.DIALOGUE_WINDOW
      if (self.dialogue_datakey === DW.dm_dialogue.get(_datakey + STR_Old_Kasuto)) {
        self.dialogue_datakey = val(
          DW.dm_dialogue.get(`${_datakey + STR_Old_Kasuto}B`),
          self.dialogue_datakey,
        ) as string
      }
    }
  } else if (_SPLSQ) {
    // Spell Sequence
    self.HylianText_read = false
    self.SUB_STATE_SEQ = 1 // Listening for spell sequence
    self.SUB_STATE_CMPL1 = 2 // CMP1: CoMPlete 1.  Waiting for end of spell flash.
    self.SUB_STATE_CMPL2 = 3
    self.SUB_STATE_CMPL3 = 4
    self.SUB_STATE_DONE = 5
    self.sub_state = self.SUB_STATE_SEQ
    const _datakey = self.dialogue_datakey + STR_Spell + STR_Sequence
    let _val = hexStr(SPL_THUN) + hexStr(SPL_THUN) + hexStr(SPL_THUN) + hexStr(SPL_THUN)
    _val = val(g.DIALOGUE_WINDOW.dm_dialogue.get(_datakey), _val) as string
    self.SPELL_SEQ = _val
    self.SpellHist_COUNT1 = g.dl_spell_history.size
    self.SpellSeq_COUNT = self.SPELL_SEQ.length >> 1
    if (self.ver === 3) {
      // Kasuto Cemetery
      for (let _i = g.dg_spawn_prio.width - 1; _i >= 0; _i--) {
        const objName = g.dg_spawn_prio.get(_i, 1)
        if (typeof objName === 'string' && objName.startsWith('Kakusu')) {
          if (gmBool(g.dg_spawn_prio.get(_i, 0xd))) {
            // defeated count
            self.sub_state = self.SUB_STATE_DONE
          }
          break
        }
      }
    } else {
      // King's Tomb, PENDANT Tomb
      self.Block_XL = self.xl
      self.Block_YT = self.yt + self.hh
      if (
        self.dk_spawn !== undefined &&
        !gmBool(val(f.dm_quests.get(self.dk_spawn + STR_Complete)) as number)
      ) {
        for (let _i = 0; _i < 4; _i++) {
          // Change tiles to solid to obstruct shaft.
          const _x = self.Block_XL + ((_i & 1) << 3)
          const _y = self.Block_YT + ((_i > 1 ? 1 : 0) << 3)
          tile_change_1a(0, _x, _y, -1, 0, TID_SOLID1)
        }
      } else {
        self.sub_state = self.SUB_STATE_DONE
      }
    }
  } else if (self.objectName === 'NPC_3') {
    // walker special. old $53-56, $1D-20. 9743
    let _PC_X = (val(g.dm_rm.get(f.reen + STR_Spawn_x)) as number) << 3
    _PC_X += PC_W >> 1
    if (Math.abs(_PC_X - self.x) >= 0xd0)
      self.facing_dir = sign_(self.x < _PC_X) // Face trwd PC
    else self.facing_dir = sign_(self.x < g.rm_w_) // Face trwd rm center
    // ($1D-20 <<1) + 0,1 = $3A,3B, 3C,3D, 3E,3F, 40,41  → $3A-41: 10,F0, 0C,F4, 08,F8, 0C,F4
    if (!(self.ver & 0x1)) self.hspd = 0xc
    else self.hspd = 0x8 << (self.ver === 1 ? 1 : 0)
    self.hspd = (self.hspd * self.facing_dir) & 0xff
    // Just in case. Sprite might be short.
    let _Y = self.yt
    _Y = get_ground_y(self.x, _Y, 1, _Y, TID_SOLID1 | TID_ONEWY1)
    _Y -= self.hh
    if (isVal(self.sprite_datakey, STR_Moa, STR_Girubokku)) _Y -= self.hh // Flying types
    _yt = _Y
  } else if (isVal(self.objectName, 'NPC_4', 'NPC_5')) {
    // Healer, Saver, Quest
    self.DOOR_XL = self.xl - (self.DOOR_W - self.ww)
    self.DOOR_XR = self.DOOR_XL + self.DOOR_W
    self.DOOR_XC = self.DOOR_XL + (self.DOOR_W >> 1) // center of door
    self.DOOR_YT = self.GROUND_Y - 8 - self.DOOR_H
    self.DOOR_YB = self.DOOR_YT + self.DOOR_H
    self.DOOR_YC = self.DOOR_YT + (self.DOOR_H >> 1)
    // The animated door
    self.door_draw_x = self.DOOR_XC // center of door
    self.door_draw_y = self.DOOR_YC // center of door
    const _TSRC1 = 0xd8 // door tsrc
    const _TSRC2 = _TSRC1 + 1 // door knob tsrc
    const _DEPTH = tile_find_depth_by_tsrc(
      (self.DOOR_XC >> 3) - 1,
      self.DOOR_YC >> 3,
      'ts_Man_made_1a_WRB',
      _TSRC1,
      _TSRC2,
    )
    const _IDX = g.dl_TILE_DEPTHS.findIndex(_DEPTH)
    if (_IDX + 1 && _IDX < p.dg_depth_pi.width) {
      self.DOOR_PI = p.dg_depth_pi.get(_IDX, 1) as number
      self.DOOR_PI_PERMUT = p.dg_depth_pi.get(_IDX, 3) as number
    } else {
      self.DOOR_PI = G.PI_BGR2
      self.DOOR_PI_PERMUT = 0
    }
    // A hitbox used by NPC cs left/right to trigger the counter for stepping inside house.
    // Also used by PC to enter Healer house.
    self.DoorHB_XL = self.DOOR_XC - (self.DOOR_W >> 1)
    self.DoorHB_YT = self.GROUND_Y + 8 - self.DOOR_H
    if (self.objectName === 'NPC_5') {
      // Quest NPC
      const hit = collideRect(
        self.BodyHB_xl,
        self.BodyHB_yt,
        self.BodyHB_w,
        self.BodyHB_h,
        world.instancesOf(Exit),
      )
      self.door_exit_inst = hit === NOONE ? 0 : (hit as unknown as Exit)
      // 9756
      self.spawn_xl = self.xl
      self.spawn_yt = self.yt - 8
      _xl = self.spawn_xl
      _yt = self.spawn_yt
      self.counter = 0x80 // $80: Waiting in house.
      self.timer_a1 = 0x90 // Delay permission to exit house.
    }
  } else if (self.objectName === 'NPC_6') {
    // Skill Knight
    GO_init_palidx(self, G.PI_MOB_PUR)
    change_pal(strReplaceAt(p.pal_rm_new, get_pal_pos(self.palidx), p.PAL_NPC_PUR4.length, p.PAL_NPC_PUR4))
  } else if (self.objectName === 'NPC_7') {
    // Spell Giver
    if (self.dk_spawn !== undefined)
      self.give_spell = val(g.dm_spawn.get(STR_Spell + STR_Bit + self.dk_spawn)) as number
    else self.give_spell = SPL_SUMM
    self.give_spell_name = val(g.dm_Spell.get(hexStr(self.give_spell) + STR_Name), '_SUMMON') as string
    self.dialogue_datakey = val(
      g.dm_spawn.get(STR_Spell + STR_Dialogue + STR_Datakey + self.give_spell_name),
      self.dialogue_datakey,
    ) as string
    self.use_cucco_dlg = 0
    if (gmBool(g.mod_PC_CUCCO_1) && self.give_spell === SPL_FARY) {
      switch (self.ver) {
        case 1: {
          // NPC embarassed his magic turned cucco instead of fairy
          if (f.spells & self.give_spell) {
            self.state = 0
            return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
          }
          break
        }
        case 2: {
          // FAIRY spell wiseman attempts spell again, makes it worse
          if (!(f.spells & self.give_spell) || gmBool(g.CuccoSpell2_Acquired)) {
            // Event already happened
            self.state = 0
            return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
          }
          self.dialogue_datakey = val(
            g.dm_spawn.get(STR_Spell + STR_Dialogue + STR_Datakey + STR_Cucco),
            self.dialogue_datakey,
          ) as string
          break
        }
      }
    }
  } else if (_BOT) {
    gob2Deps.Bot_init2(self)
    self.is_idle = true // So I can use usd_Bot()
    self.abilities = 0
  } else if (_SCROB) {
    if ((val(f.dm_quests.get(Scroblin_DATAKEY1)) as number) >= 2) {
      for (const e of world.instancesOf(Exit)) {
        if (e.exitName === `${g.rm_name}00`) {
          e.open = true
          e.doorway_spr = g.Doorway1_SPR
          break
        }
      }
    }
  } else if (is_ver(self, 'NPC_A', 1)) {
    // Triforce Keeper --------------------------------------
    self.SPR_IDLE = 'spr_Triforce_Keeper_1a'
    self.SPR_MOVE = 'spr_Triforce_Keeper_1b' // action/mouth open
    GO_sprite_init(self, self.SPR_IDLE)
    self.tri_can_draw = 0
    self.TRI_SPR = 'spr_Triforce_1a'
    self.tri_xOff = 0
    self.tri_yOff = 0
    self.arena_x = g.rm_w_
    // `NPC_init2.gml:427` — `with(Boss) other.arena_x = arena_x`: inside the `with`, `other` is the NPC
    // and the bare `arena_x` is the *boss's*, so the boss's arena centre is copied onto the NPC.
    for (const b of world.instancesOf(Boss)) self.arena_x = (b as Boss & { arena_x: number }).arena_x
    self.GROUND_Y = (((self.spawn_yt >> 8) + 1) << 8) - (0x3 << 3)
    self.GROUND_Y = get_ground_y(self.arena_x, self.GROUND_Y, -1, self.GROUND_Y)
    if (f.quest_num > 1) {
      _xl = self.xl - 0x10
      _yt = self.yt
    }
    self.sub_state = 0
  }
  if (
    self.sprite_datakey === STR_Girubokku &&
    isVal(self.objectName, 'NPC_2', 'NPC_3') &&
    gmBool(self.hspd)
  ) {
    self.hspd = (0x10 * self.facing_dir) & 0xff
  }
  if (self.dialogue_datakey !== undefined) {
    const _DIALOGUE = g.DIALOGUE_WINDOW.dm_dialogue.get(`${self.dialogue_datakey}A`)
    if (typeof _DIALOGUE === 'string' && _DIALOGUE.includes('WITH BOOTS') && !world.irandom(0x7)) {
      // crazy guy standing in Nabooru fountain
      GO_depth_init(self, DEPTH_BG8 + 3)
    }
  }
  if (
    G.RandoHints_enabled &&
    gmBool(val(G.dm_save_file_settings.get(STR_Randomize + STR_Item + STR_Locations)) as number)
  ) {
    if (self.objectName !== 'Zelda') {
      self.RandoHint_hint_num = val(
        f.dm_rando.get(STR_Rando + STR_Hint + self.dialogue_datakey + STR_Hint + STR_Num),
      ) as number
      if (
        g.dm_RandoHintsRecorder.get(STR_Hint + hexStr(self.RandoHint_hint_num) + STR_Dialogue) !== undefined
      ) {
        self.RandoHint_hint_num = 0 // 0: tells draw not to draw the question mark
      }
    }
  }
  // 976B
  set_xlyt(self, _xl, _yt)
  if (DEV && self.objectName !== 'NPC_2') gob2Deps.db_NPC_create_1a(self)
}

/** `NPC_udp_1(sub sprite idx)` */
export function NPC_udp_1(self: NpcObject, subSpriteIdx: number): void {
  if (self.sprite_datakey !== undefined) {
    const _SUB = hexStr(subSpriteIdx + 1)
    const _SPRITE = val(g.dm_NPC.get(STR_Sprite + self.sprite_datakey + _SUB), self.sprite) as string
    GO_set_sprite(self, _SPRITE)
  }
}

/** `NPC_udp_2()` — update `RandoHint_hint_num` */
export function NPC_udp_2(self: NpcObject): void {
  if (
    gmBool(self.RandoHint_hint_num) &&
    g.dm_RandoHintsRecorder.get(STR_Hint + hexStr(self.RandoHint_hint_num) + STR_Dialogue) !== undefined
  ) {
    self.RandoHint_hint_num = 0 // 0: tells draw not to draw the question mark
  }
}

/** `NPC_udp_Girubokku()` */
export function NPC_udp_Girubokku(self: NpcObject): void {
  NPC_udp_1(self, self.is_talking ? 1 : 0)
  NPC_udp_2(self) // update `RandoHint_hint_num`
  self.draw_yoff = -0x06
}

/** `NPC_draw()` */
export function NPC_draw(self: NpcObject): void {
  NPC_draw_door(self)
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // Draw "?" over head of NPC that has an undiscovered hint
  if (G.RandoHints_enabled && gmBool(self.RandoHint_hint_num)) {
    draw_text_(self.x - 4, self.yt + self.RandoHint_ytoff, '?')
  }
  if (self.sprite_datakey === STR_Zant) {
    // Bulblin wiseman
    const _WING_SPR =
      g.counter1 & (0x1 << 3) || gmBool(self.CastSpellSprite_timer) ? 'spr_Wing_1b_1' : 'spr_Wing_1a_1'
    pal_swap_set(self.palidx)
    draw_sprite_at(self.depth, _WING_SPR, 0, self.drawX, self.drawY, -1, 1)
    draw_sprite_at(self.depth, _WING_SPR, 0, self.drawX, self.drawY, -1, -1)
    GO_draw_sprite(self, self.sprite)
    pal_swap_reset()
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (self.objectName === 'NPC_0' && self.ver === 2) {
    // NPC_0,2: sign
    const _SPRITE = 'spr_Pole01Segment'
    const _H = sprite_get_height(_SPRITE)
    const _ROWS = Math.max((self.hh >> 3) - 1, 1)
    let _Y1 = self.drawY + self.hh_ // yb(ground)
    _Y1 = (_Y1 >> 3) << 3 // align w/ grid
    _Y1 -= _ROWS << 3 // sign graphic yt
    _Y1 += _H >> 1 // sign board yc
    for (let _i = 0; _i < _ROWS; _i++)
      draw_sprite_at(self.depth, _SPRITE, 0, self.drawX, _Y1 + _H * _i, self.palidx)
    draw_sprite_at(self.depth, 'spr_SignBoard01', 0, self.drawX, _Y1, self.palidx)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (self.objectName === 'NPC_9' && self.ver === 5) {
    // NPC_9,5: Bagu's Bot
    gob2Deps.Bot_draw(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (self.objectName === 'NPC_9' && self.ver === 1) {
    // NPC_9,1: Bagu. Draw Riverman portrait
    draw_sprite_at(
      DEPTH_BG5 + 1,
      'spr_Riverman_portrait_1a_1',
      0,
      ((self.drawX >> 3) << 3) + (6 << 3),
      ((self.drawY >> 3) << 3) - (3 << 3) - 4,
      G.PI_BGR4,
    )
  }
  GameObject_draw_1a(self, self.sprite as string, self.palidx)
}

