/** `NPC_4_update()` — NPC_4 Healer, Saver; NPC_5 Quest */
export function NPC_4_update(self: NpcObject): void {
  const P = pc()
  // 97D4: JSR 9A9B
  if (self.is_talking) {
    if (g.dialogue_source === self) {
      if (g.gui_state === g.gui_state_DIALOGUE1 && self.counter !== -1) {
        // Regular dlg state
        switch (self.objectName) {
          case 'NPC_4': {
            // Delay face toward door. timer set to 6 at frame of dlg initiate in NPC_activate_dialogue()
            if (self.timer_a1) {
              self.timer_a1--
              if (!self.timer_a1) {
                self.facing_dir = sign_(self.DOOR_XC - self.x) // face torwards door
                self.counter = -1 // Indicates move torwards door to enter house
              }
            }
            break
          }
          case 'NPC_5': {
            if (
              self.dk_spawn !== undefined &&
              quest_is_complete(val(g.dm_spawn.get(`${self.dk_spawn}_Quest_ID`), STR_undefined) as string)
            ) {
              self.counter = -1 // Indicates move torwards door to enter house
            }
            break
          }
        }
      }
      self.hspd = 0
      // g.GWIN_D2(restore house dlg) doesn't draw PC nor NPC
      if (g.gui_state === g.gui_state_DIALOGUE1) {
        P.xScale = sign_(self.x - P.x) // Face PC torwards NPC
        update_EF11(self)
      }
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
    self.is_talking = false
    // DO NOT exit script here bc this is the first frame of MOVING TORWARDS DOOR(counter == -1)
  }
  // MOVING TORWARDS DOOR to enter house ----------------------------------------
  if (self.counter === -1) {
    self.facing_dir = sign_(self.DOOR_XC - self.x) // face door
    self.hspd = (self.hspd_PACE * self.facing_dir) & 0xff // set hspd toward door
    updateX(self)
    update_EF11(self)
    GO_update_cs(self)
    const _X = self.hspd & 0x80 ? self.csLft2X : self.csRgt2X
    if (wINw(_X, 1, self.DoorHB_XL, self.DOOR_W)) self.counter = 1
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // ENTERING house ------------------------------------------------
  if (self.counter && self.counter < 0x80) {
    NPC_update_2(self) // collision, enter restore house, start dlg
    // 98BC. c: condition
    const _C0 = self.counter === 0x01
    const _C1 = self.counter === 0x10
    const _C2 = self.counter === 0x20
    const _C3 = self.counter >= 0x21 && self.counter <= 0x3f
    const _C4 = self.counter === 0x40
    const _C5 = self.counter === 0x70
    const _C6 = self.counter === 0x7e
    if (_C0)
      self.door_draw_state = self.door_draw_state_CLOSE // $01. FULL CLOSED.   Making sure door is closed
    else if (_C1)
      self.door_draw_state = self.door_draw_state_OPEN1 // $10. HALF OPEN. Start open.
    else if (_C2)
      self.door_draw_state = self.door_draw_state_OPEN2 // $20. FULL OPEN
    else if (_C5)
      self.door_draw_state = self.door_draw_state_OPEN1 // $70. HALF OPEN. Start close
    else if (_C6) self.door_draw_state = self.door_draw_state_CLOSE // $7E. FULL CLOSED
    // Making sure facing the correct dir
    if (_C0) self.facing_dir = sign_(self.DOOR_XC - self.x) // face door
    if (!_C3) self.hspd = 0 // So walk spr doesn't draw while not moving
    if (self.counter < 0x40) update_EF11(self)
    if (_C3) {
      // $20-$3F. IS MOVING & Stepping up stairs
      if (!isVal(self.sprite_datakey, STR_Moa, STR_Girubokku) && (self.counter & 0xf) === 0x7) {
        set_xy(self, self.x, self.y - 4) // Take 1 step
      }
      self.hspd = (self.hspd_PACE * self.facing_dir) & 0xff // set hspd toward door
      updateX(self)
    } else if (_C4) {
      // $40. INSIDE HOUSE
      self.pc_can_enter = true // PC CAN now enter house.
      if (self.door_exit_inst) (self.door_exit_inst as Exit).open = true
    } else if (_C6) {
      // $7E. INSIDE HOUSE. END entering house process
      self.counter = 0x80 // Indicate waiting to exit house.
      self.timer_a1 = 0xff // Timer to exit house.
      self.pc_can_enter = false // PC CANNOT enter house anymore.
      if (self.door_exit_inst) (self.door_exit_inst as Exit).open = false
      return // exit so counter stays at $80 !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
    self.counter++
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // Keep Quest NPCs waiting in house if too far away (instead of despawning)
  if (self.objectName === 'NPC_5' && self.counter !== 0x80) {
    if (in_despawn_dist(self)) {
      self.counter = 0x80 // Indicate waiting to exit house.
      self.timer_a1 = 0xff // timer to exit house
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
  }
  // WAITING TO LEAVE house ----------------------------------
  if (self.counter === 0x80) {
    if (self.timer_a1) self.timer_a1--
    if (!self.timer_a1 && Math.abs(P.x - self.x) < 0x60) {
      // 97F5
      GO_update_cs(self)
      if (isVal(self.sprite_datakey, STR_Moa, STR_Girubokku))
        set_xlyt(self, self.DOOR_XC - self.ww_, self.DOOR_YT + 8)
      else set_xlyt(self, self.DOOR_XC - self.ww_, self.GROUND_Y - 8 - self.hh)
      if (self.objectName === 'NPC_5') self.facing_dir = dir_to_pc(self)
      self.hspd = 0
      self.door_draw_state = self.door_draw_state_OPEN1 // OPENING. Half open
      self.counter++
    }
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // LEAVING house ------------------------------------------------------------
  if (self.counter > 0x80) {
    self.counter++
    // Opening and closing door ----------------------------------
    if (self.counter === 0x82)
      self.door_draw_state = self.door_draw_state_OPEN1 // OPENING. Half open
    else if (self.counter === 0x90)
      self.door_draw_state = self.door_draw_state_OPEN2 // OPENING. Full open
    else if (self.counter === 0xa0)
      self.door_draw_state = self.door_draw_state_OPEN1 // CLOSING. Half closed
    else if (self.counter === 0xb0) self.door_draw_state = self.door_draw_state_CLOSE // CLOSING. Full closed
    // Stepping down stairs -----------------------------------
    if (self.counter > 0xb0) {
      // NPC doesn't start moving until frame after door fully closed
      if (self.counter === 0xb1) self.hspd = (self.hspd_PACE * self.facing_dir) & 0xff
      updateX(self)
      if (!(g.counter1 & 0xf)) {
        if (isVal(self.sprite_datakey, STR_Moa, STR_Girubokku)) {
          if (self.counter > 0xc0) self.counter = 0 // END LEAVING house process
        } else {
          const _y = self.GROUND_Y - self.hh
          if (self.yt < _y) {
            set_xlyt(self, self.xl, Math.min(self.yt + 4, _y)) // Step down 1 step
            if (self.yt >= _y) self.counter = 0 // END LEAVING house process
          }
        }
      }
    }
    // Start drawing the frame after door is fully open.
    if (self.counter > 0x90 || self.counter === 0) update_EF11(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // PACING IN FRONT OF HOUSE ----------------------------------------
  if (self.counter === 0) {
    // 9851
    const _DIFF = self.x - self.DOOR_XC
    let _C1 = Math.abs(_DIFF) >= 0x28
    _C1 = _C1 && Math.sign(_DIFF) === self.facing_dir // if facing away from door
    if (_C1 && !self.timer_a1) self.timer_a1 = 0x40 // Stand still duration
    if (self.timer_a1) self.hspd = 0
    else self.hspd = (self.hspd_PACE * self.facing_dir) & 0xff // set hspd toward door
    if (self.timer_a1) {
      // Stand still, waiting to turn around.
      self.timer_a1--
      if (!self.timer_a1) self.facing_dir = sign_(self.DOOR_XC - self.x) // face door
    }
    updateX(self)
    update_EF11(self)
    NPC_update_2(self) // collision, enter restore house, start dlg
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
}

