/** `NPC_7_update()` — NPC_6 Skill Knight, NPC_7 Wise Man */
export function NPC_7_update(self: NpcObject): void {
  const P = pc()
  // 97A9: JSR 9A9B
  if (NPC_update_1(self)) return // if in dialogue with this instance !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // 97AC: JSR 9A8D,   9A8D: JSR EF11
  update_EF11(self)
  // 97AF,   97B3: DC91
  self.facing_dir = dir_to_pc(self)
  // 97B6, 97CA, 97CD: JMP 9A33
  // --- Auto dialogue Spell Giver, Skill Knight --- Activate dialogue when PC is close enough
  if (self.talked_to_count) {
    // This is so player doesn't have to re-enter rm to talk again, like for Boulder Circle dialogue
    if (self.objectName !== 'NPC_7' || self.give_spell !== SPL_FARY) {
      // Any wise man except the FAIRY/CUCCO ones
      NPC_update_2(self)
    }
  } else {
    const _EXTRA = 0x10
    const _Y = self.yt - _EXTRA
    if (
      !gmBool(P.ogr) && // if PC on ground
      hINh(_Y, Math.abs(self.GROUND_Y + _EXTRA - _Y), P.yt, P.hh) &&
      Math.abs(self.x - P.x) < 0x20
    ) {
      NPC_activate_dialogue(self) // activate dialogue
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
  }
  // For FAIRY and CUCCO wise men
  if (
    gmBool(g.mod_PC_CUCCO_1) &&
    gmBool(g.mod_WISEMEN_CAST_SPELL) &&
    self.objectName === 'NPC_7' &&
    gmBool(self.use_cucco_dlg) &&
    g.gui_state === g.gui_state_NONE
  ) {
    switch (self.use_cucco_dlg) {
      case 1: {
        // Special "whoops" dlg for turning PC into a cucco.
        NPC_activate_dialogue(self) // activate dlg
        self.talked_to_count-- // because talkedToCount++ in NPC_activate_dialogue()
        self.timer_a1 = 0x18 // Delay Audio.SND_CAST_SPEL so it doesn't conflict w/ dlg closing sound.
        self.use_cucco_dlg = 2
        break
      }
      case 2: {
        // NPC teleports away in embarassment
        if (self.timer_a1) {
          self.timer_a1--
          break
        }
        self.CastSpellSprite_timer = self.CastSpellSprite_DURATION
        aud_play_sound(get_audio_theme_track(STR_Cast + STR_Spell))
        self.use_cucco_dlg = 3
        break
      }
      case 3: {
        // Fade out
        if (self.timer_a1) {
          self.timer_a1--
          break
        }
        if (self.CastSpellSprite_timer) {
          // Fade effect.
          self.can_draw_self = !!(self.CastSpellSprite_timer & 0x1)
          break
        }
        GOB_despawn(self)
        // Set the spawn permission to -1 so NPC cannot spawn again, otherwise, NPC will respawn if area is refreshed.
        g.dm_spawn.set(self.dk_spawn + STR_Spawn_Permission, -1)
        break
      }
    }
  }
}

