/** `NPC_C_update()` — spell-sequence NPC (King's Tomb, PENDANT tomb, Kasuto Cemetery) */
export function NPC_C_update(self: NpcObject): void {
  if (self.is_talking) {
    if (g.dialogue_source === self) {
      if (
        f.items & ITM_BOOK &&
        self.dk_spawn !== undefined &&
        !gmBool(val(f.dm_quests.get(self.dk_spawn + STR_Translated)) as number)
      ) {
        f.dm_quests.set(self.dk_spawn + STR_Translated, 1)
      }
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
    self.is_talking = false
  }
  if (!self.is_talking) self.HylianText_read = false
  // 9AC2: JSR 99B9
  let _qual = true
  if (self.ver === 3) {
    // Kasuto Cemetery. Disable dialogue trigger during Kakusu battle
    for (const k of world.instancesOf(Kakusu)) {
      const kk = k as Kakusu & { sub_state?: number; SUB_STATE_SEQU?: number }
      // SUB_STATE_SEQU is only sub_state the Kakusu is hiding
      if (kk.sub_state !== kk.SUB_STATE_SEQU) _qual = false
    }
  }
  if (_qual) NPC_update_2(self) // collision, enter restore house, start dlg
  switch (self.sub_state) {
    case self.SUB_STATE_SEQ: {
      if (self.timer) break
      if (self.is_talking) break
      if (spell_sequence_is_complete(self, [...g.dl_spell_history] as number[], self.SPELL_SEQ)) {
        f.dm_quests.set(self.dk_spawn + STR_Complete, 1)
        self.timer = p.SpellFlash_PC_timer + 4
        self.sub_state = self.SUB_STATE_CMPL1
      }
      break
    }
    case self.SUB_STATE_CMPL1: {
      if (self.timer) break
      if (self.ver === 3) {
        // Kasuto Cemetery
        let any = false
        for (const k of world.instancesOf(Kakusu)) {
          const kk = k as Kakusu & { sub_state?: number; SUB_STATE_CMPL1?: number }
          kk.timer = 0
          kk.sub_state = kk.SUB_STATE_CMPL1 ?? 0
          any = true
        }
        self.timer = 0
        self.sub_state = self.SUB_STATE_DONE
        if (any) aud_play_sound(get_audio_theme_track(STR_Secret))
      } else {
        // King's Tomb, PENDANT Tomb
        aud_play_sound(get_audio_theme_track(STR_Open + STR_LockedDoor))
        aud_play_sound(get_audio_theme_track(dk_BlockBreak))
        self.timer = 0
        self.sub_state = self.SUB_STATE_CMPL2
      }
      break
    }
    case self.SUB_STATE_CMPL2: {
      if (self.timer) break
      aud_play_sound(get_audio_theme_track(STR_Secret))
      self.timer = 0
      self.sub_state = self.SUB_STATE_CMPL3
      break
    }
    case self.SUB_STATE_CMPL3: {
      if (self.timer) break
      for (let _i = 0; _i < 4; _i++) {
        // Change tiles to NON-solid to UN-block shaft.
        const _xl = self.Block_XL + ((_i & 0x1) << 3)
        const _yt = self.Block_YT + ((_i > 0x1 ? 1 : 0) << 3)
        tile_change_1a(0, _xl, _yt, -1, 0, 0)
      }
      self.timer = 0
      self.sub_state = self.SUB_STATE_DONE
      break
    }
    case self.SUB_STATE_DONE:
      break
  }
}

