// ---------------------------------------------------------------- Zelda
/** `Zelda_init2()` */
export function Zelda_init2(self: Zelda): void {
  const P = pc()
  self.can_draw_self_exception = true
  // Two Zelda's are spawned to this room, only 1 can remain..
  if (g.rm_name !== val(g.dm_rm.get('GameEnd1B_RM_NAME'))) {
    if ((self.ver === 1 && f.quest_num >= 2) || (self.ver === 2 && f.quest_num === 1)) {
      self.state = 0
      self.destroy()
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
  }
  GO_set_sprite(self, self.SPR_SLEP)
  GO_init_palidx(self, G.PI_BGR3)
  self.DRAW_YOFF = 0
  self.xScale = 1
  self.sub_state = self.SUB_STATE_SLEP
  self.dialogue_datakey = '0Z_00_'
  self.dialogue_ver = 'A'
  NPC_catch_item(self) // catch the BOTTLE item
  if (
    f.quest_num === 1 &&
    G.RandoHints_enabled &&
    gmBool(val(G.dm_save_file_settings.get(STR_Zelda + STR_Hint)) as number)
  ) {
    const hint = GameObject_create(self.x - 8, self.y - 4, 'NPC_0', 0x1)
    if (hint) hint.dialogue_datakey = STR_Zelda + STR_Hint
  }
  if (self.ver === 2) {
    // 2nd quest. for typical npc settings
    self.sub_state = self.SUB_STATE_IDLE
    GO_sprite_init(self, 'spr_Placement_16x32')
    GO_set_sprite(self, self.SPR_POSE1)
    const _DIST = 0x03 << 3
    set_xy(self, g.rm_w_ + _DIST, self.y)
    set_xy(P, g.rm_w_ - _DIST, self.y)
    P.spawn_xl = P.xl
    P.spawn_yt = P.yt
    self.dialogue_datakey = '0Z_01_'
    self.dialogue_ver = '01' // 01: "GOOD LUCK"/HINT dialogue
    if (!gmBool(val(f.dm_quests.get(Zelda_DATAKEY1)) as number)) {
      self.dialogue_ver = '02' // 02: BOTTLE instructions
      NPC_activate_dialogue(self) // start dialogue
    }
  }
}

/** `Zelda_update()` */
export function Zelda_update(self: Zelda): void {
  const P = pc()
  if (self.ver === 2) {
    // 2nd Quest Zelda
    if (
      !gmBool(val(f.dm_quests.get(Zelda_DATAKEY1)) as number) &&
      self.Item_ITEM_ID !== undefined &&
      item_acquired(self.Item_ITEM_ID)
    ) {
      f.dm_quests.set(Zelda_DATAKEY1, 1)
    }
    if (!gmBool(val(f.dm_quests.get(Zelda_DATAKEY1)) as number)) {
      // I'm having trouble setting a custom pos for pc so this is an attempt to resolve it.
      set_xy(P, g.rm_w_ - Math.abs(self.x - g.rm_w_), self.y)
    }
    self.dialogue_ver = gmBool(val(f.dm_quests.get(Zelda_DATAKEY1)) as number) ? '01' : '02'
    // update give item
    NPC_update_3(self, P.x, P.y) // Spawn item
    // 9793: JSR 9A9B
    if (NPC_update_1(self)) {
      // if talking
      Zelda_update_talk_sound()
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
    // 9796: JSR 9A8D: JSR EF11
    update_EF11(self)
    if (!(g.counter1 & 0x3f)) self.facing_dir = dir_to_pc_(self)
    self.counter = 0 // Just in case. Necessary for dlg
    NPC_update_2(self) // collision, enter restore house, start dlg
  } else {
    update_EF11(self)
  }
  switch (self.sub_state) {
    case self.SUB_STATE_SLEP: {
      // Bounce off sleeping Zelda w/ downthrust
      update_body_hb_1a(self)
      if (
        self.state === self.state_NORMAL &&
        P.SwordHB_collidable &&
        P.attack_bits & BIT_ATK3 && // BIT_ATK3: downthrust
        collide_pc_sword(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h) &&
        !(self.cs & CS_SW1)
      ) {
        self.cs |= CS_SW1
        PC_set_bounce()
      } else self.cs &= ~CS_SW1
      break
    }
  }
}

/** `Zelda_update_talk_sound()` — snd plays every other char written */
export function Zelda_update_talk_sound(): boolean {
  const DW = g.DIALOGUE_WINDOW
  if (!DW) return false
  if (DW.writ_char_pos < String(DW.dialogue).length) {
    if (DW.writ_char_pos) {
      const _LEN = DW.writ_char_pos - (String(DW.writ_dlg).split(' ').length - 1)
      if (_LEN & 0x1) aud_play_fairy1()
    }
    return true
  }
  return false
}

/** `Zelda_udp()` */
export function Zelda_udp(self: Zelda): void {
  self.can_draw_self = true
  NPC_udp_2(self) // update `RandoHint_hint_num`
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE:
      GO_set_sprite(self, self.is_talking ? self.SPR_TALK : self.SPR_POSE1)
      break
    case self.SUB_STATE_SLEP:
      GO_set_sprite(self, self.SPR_SLEP)
      self.xScale = 1
      self.draw_yoff = 0
      break
    case self.SUB_STATE_WAKE:
      GO_set_sprite(self, self.SPR_WAKE)
      self.xScale = 1
      self.draw_yoff = 0
      break
    case self.SUB_STATE_TALK1:
      GO_set_sprite(self, self.SPR_TALK)
      self.draw_yoff = 1 // 1 in the floor
      break
    case self.SUB_STATE_TALK2:
      GO_set_sprite(self, self.SPR_TALK)
      break
    case self.SUB_STATE_KISS:
      GO_set_sprite(self, self.SPR_TALK)
      self.draw_yoff = 1 // 1 in the floor
      break
  }
}

/** `Zelda_draw()` */
export function Zelda_draw(self: Zelda): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // Draw "?" over head of NPC that has an undiscovered hint
  if (G.RandoHints_enabled && gmBool(self.RandoHint_hint_num))
    draw_text_(self.x - 4, self.yt + self.RandoHint_ytoff, '?')
  GO_draw_sprite(self, self.sprite, self.palidx)
}

// ---------------------------------------------------------------- shared
/** `NPC_update_1()` — returns true while this instance is the dialogue source. 9AA0 */
export function NPC_update_1(self: NpcObject): boolean {
  if (self.is_talking) {
    if (g.dialogue_source !== self) {
      self.is_talking = false
    } else {
      self.facing_dir = dir_to_pc(self)
      pc().xScale = -self.facing_dir
      update_EF11(self)
      return true
    }
  }
  return false
}

/** `NPC_update_2()` — collision, start dlg, enter restore house. 99B9 */
export function NPC_update_2(self: NpcObject): void {
  const P = pc()
  if (g.DevTools_state) update_body_hb_1a(self) // So that bodyhb still draws even if it doesn't make it to the collision check.
  if (!input.Attack_pressed && !input.Up_held) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (self.is_talking) return
  if (P.state !== P.state_NORMAL || gmBool(P.HoldItem_timer) || gmBool(g.EnterRoom_control_timer)) return // MOD
  // 99B9
  GOB_body_collide_pc_body_1a(self)
  if (!(self.cs & CS_BD1)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // RESTORE HOUSE DIALOGUE -----------------------
  if (self.objectName === 'NPC_4' && self.pc_can_enter) {
    // NPC waiting in house for UP held
    if (
      input.Up_held &&
      g.gui_state === g.gui_state_NONE &&
      !gmBool(P.ogr) &&
      pointInRect(P.cp1X, P.cp1Y, self.DoorHB_XL, self.DoorHB_YT, self.DOOR_W, self.DOOR_H)
    ) {
      // 99D4. Start dialogue
      g.gui_state = g.gui_state_DIALOGUE2
      g.dialogue_source = self
      P.in_restore_house = true
      g.pc_lock = PC_LOCK_ALL // Lock all
      self.is_talking = true // 05C3[eIndex]++;
      self.pc_can_enter = false
    }
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // STANDARD DIALOGUE ---------------------------
  if (input.Attack_pressed && self.counter === 0) {
    // Is pacing/waiting for input
    let _qualifies = false
    if (self.objectName === 'NPC_4' || self.objectName === 'NPC_5') {
      // 4: healer, saver; 5: quest
      if (!gmBool(P.ogr) && Math.abs(self.x - self.DOOR_XC) >= 0x14) _qualifies = true // PC on ground, spr at least 4 away from door
    } else if (is_ver(self, 'NPC_9', 4) || is_ver(self, 'NPC_8', 1) || self.sprite_datakey === STR_Ache) {
      // Ache NPC, Fairy NPC
      _qualifies = true
    } else {
      // For anyone else, PC must be on ground
      _qualifies = !gmBool(P.ogr)
    }
    if (_qualifies && g.gui_state !== g.gui_state_NONE) {
      _qualifies = false
      // Give a chance for higher priority NPC to interupt a dialogue that was started this frame.
      if (g.gui_state === g.gui_state_DIALOGUE1 && g.dialogue_started_this_frame && g.dialogue_source) {
        const src = g.dialogue_source as NpcObject
        if (isVal(self.objectName, 'NPC_3', 'NPC_4', 'NPC_5')) {
          if (src.objectName === 'NPC_2' || src.objectName === 'NPC_3') {
            if (src.objectName === 'NPC_2' || self.objectName === 'NPC_4' || self.objectName === 'NPC_5') {
              src.is_talking = false
              src.talked_to_count--
              _qualifies = true
            }
          }
        }
      }
    }
    if (_qualifies) NPC_activate_dialogue(self) // 99D4. Start dialogue.
  }
}

/** `NPC_update_3(x,y)` — For Mido fairy, Bagu, Talo: spawn the caught item after dialogue */
export function NPC_update_3(self: NpcObject, x: number, y: number): boolean {
  if (self.is_talking) {
    // Right after this inst's dialogue window closes
    if (g.gui_state === g.gui_state_NONE || g.menu_state === g.DIALOGUE_WINDOW.SUB_STATE_CLOS1) {
      // prevents pc from jumping away before they can pick up item
      if (self.Item_SPAWN_DATAKEY !== undefined && self.Item_OBJ) {
        const item = GameObject_create(
          x,
          y,
          self.Item_OBJ,
          self.Item_VER,
          self.Item_SPAWN_DATAKEY,
        ) as ItemObject | null
        if (item) {
          if (gmBool(item.IS_HOLD_ITEM)) {
            set_xy(item, item.xl, item.yt) // because x,y are x,y, not xl,yt
          } else {
            // So the NPC does not obstruct the item. If stabbing activates dialogue, the player will have to
            // stab the item in mid air so dialogue does not activate.
            GO_depth_init(item, self.depth - 1)
          }
          item.vspd = 1
          item.ITEM_ID = self.Item_ITEM_ID
        }
        aud_play_sound(get_audio_theme_track(dk_ItemDrop))
        self.Item_SPAWN_DATAKEY = undefined // so item wont spawn again if player talks to NPC again
        return true
      }
    }
  }
  return false
}

/** `Merchant_update_1()` — update_EF11(), set facingDir, counter = 0 */
export function Merchant_update_1(self: NpcObject): void {
  update_EF11(self)
  if (!(g.counter1 & 0x3f)) self.facing_dir = dir_to_pc(self)
  self.counter = 0 // Just in case. Necessary for dlg
}

/** `NPC_get_sub_sprite_idx()` — 0: primary sprite, 1: secondary sprite (walk anim every 8 or $10 frames). 9B0A */
export function NPC_get_sub_sprite_idx(self: NpcObject): 0 | 1 {
  if (!self.is_talking && gmBool(self.hspd) && !(g.counter1 & (0x8 << (abs8b(self.hspd) < 0x10 ? 1 : 0))))
    return 1
  return 0
}

/** `NPC_get_init_sprite(instance)` */
export function NPC_get_init_sprite(inst: NPC): string {
  if (inst.dk_spawn !== undefined) {
    inst.sprite_datakey = g.dm_spawn.get(inst.dk_spawn + STR_Sprite + STR_Datakey) as string | undefined
  }
  if (inst.sprite_datakey !== undefined) {
    return val(g.dm_NPC.get(`${STR_Sprite + inst.sprite_datakey}01`), 'spr_0') as string
  }
  return 'spr_0'
}

/** `NPC_catch_item()` — the NPC takes the room's Item; it will spawn after dialogue */
export function NPC_catch_item(self: NpcObject): void {
  self.Item_SPAWN_DATAKEY = undefined
  self.Item_OBJ = 0
  self.Item_VER = 1
  self.Item_ITEM_ID = undefined
  for (const item of world.instancesOf(Item)) {
    if (!item.state) break // FIDELITY: GML `break` inside with() — see FIDELITY_NOTES (kept)
    self.Item_SPAWN_DATAKEY = item.dk_spawn
    self.Item_OBJ = item.objectName
    self.Item_VER = item.ver
    self.Item_ITEM_ID = item.ITEM_ID
    item.state = 0 // NPC will spawn after dialogue.
    break // just in case more than one item spawns in the room
  }
}

/** `NPC_draw_door()` — animated house door for NPC_4/NPC_5 */
export function NPC_draw_door(self: NpcObject): void {
  if (!self.state) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (self.objectName !== 'NPC_4' && self.objectName !== 'NPC_5') return
  if (self.door_draw_state !== self.door_draw_state_CLOSE) {
    const _xl = self.door_draw_x - (self.DOOR_W >> 1)
    const _yt = self.door_draw_y - (self.DOOR_H >> 1)
    draw_sprite_at(
      self.depth,
      'spr_1x1_WHT',
      0,
      _xl,
      _yt,
      -1,
      self.DOOR_W,
      self.DOOR_H,
      get_pal_color(p.pal_rm_curr, self.DOOR_PI, 'B'),
    )
    if (self.door_draw_state === self.door_draw_state_OPEN1) {
      // half open
      pal_swap_set(self.DOOR_PI)
      draw_sprite_part_(g.TownDoor1_SPR, 0, 0, 0, self.DOOR_W >> 1, self.DOOR_H, _xl + 8, _yt, self.DOOR_PI)
      pal_swap_reset()
    }
  }
  if (g.DevTools_state && g.can_draw_hb && self.DoorHB_can_draw) {
    draw_rect_at(self.depth, p.C_ORG2, self.DoorHB_XL, self.DoorHB_YT, self.DOOR_W, self.DOOR_H, 0.7)
  }
}

/** `NPC_activate_dialogue()` — 9A33 */
export function NPC_activate_dialogue(self: NpcObject): void {
  const P = pc()
  g.dialogue_source = self
  g.gui_state = g.gui_state_DIALOGUE1
  g.pc_lock = PC_LOCK_ALL // Lock all
  g.dialogue_started_this_frame = true
  P.attack_phase = 0
  PC_set_behavior(P.behavior_IDLE)
  solid_clip_correction(P, false)
  /* *** When you press 'B' to start dialogue w/ an NPC, pc attack is started. This sets hspd = 0, then
     attack_phase is stopped right here. */
  self.is_talking = true
  self.talked_to_count++
  if (gmBool(g.mod_HEAL_NPC_DELAY1) && self.objectName === 'NPC_4') {
    // Healer/Saver: Delay face toward door.
    self.timer_a1 = 6
  }
}

// ---------------------------------------------------------------- Spawner_NPC (SpNPA)
/** `Spawner_NPC_init2()` — 96B2 */
export function Spawner_NPC_init2(self: SpNPA): void {
  self.LIMIT = 8
  if (gmBool(g.town_num) && g.town_name === STR_Bulblin && !pc().Disguise_enabled) {
    self.state = 0
  }
}

/** `Spawner_NPC_update()` — 96E0 */
export function Spawner_NPC_update(self: SpNPA): void {
  self.counter = (self.counter + 1) & 0xff
  if (self.counter) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  let _count = 0
  for (const n of world.instancesOf(NPC)) {
    _count += n.state ? 1 : 0
    if (_count >= self.LIMIT) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // 96F0
  const _VER = (OgRandomRead(self) & 0x3) + 1 // 1,2,3,4
  let _dir = input.held & 0x3 // 0,1,2
  if (!_dir) _dir = _VER - 1 // Neither dir held
  _dir &= 0x1 // 0: Left held, 1: Right held, 0 or 1 randomly if neither held
  let dir: 1 | -1
  if (_dir)
    dir = -1 // Walk left
  else dir = 1 // Walk right
  // FIDELITY: GML `if(!_dir)` after `_dir = -1/1` is never true (-1 is falsy → left branch when dir==-1). See notes.
  let _xl: number
  if (dir === -1)
    _xl = viewXR() - 1 + (0x1 << 3) // Spawn right of screen & walk left
  else _xl = viewXL() - (0x4 << 3) // Spawn left  of screen & walk right
  let _yt = cam_yb_max() - (0x1 << 3)
  _yt = get_ground_y(_xl + 8, _yt, -1, _yt, TID_SOLID1 | TID_ONEWY1)
  _yt -= 0x4 << 3
  const n = GameObject_create(_xl, _yt, 'NPC_2', 1) as NpcObject | null
  if (!n) return
  const _use_costume = G.Halloween1_enabled && !world.irandom(0x3)
  n.counter = 0
  n.facing_dir = dir
  const costume = (i: string) => {
    if (world.irandom(0x1)) n.sprite_datakey = `${STR_Castlevania}02${STR_NPC}${i}`
    else n.sprite_datakey = `${STR_Castlevania}02${STR_Enemy}${i}`
  }
  switch (_VER) {
    case 1: {
      // sprIndex 2: Large man
      if (g.town_name === STR_Bulblin) {
        GO_init_palidx(n, G.PI_MOB_BLU)
        n.sprite_datakey = STR_Geru
      } else {
        GO_init_palidx(n, G.PI_MOB_PUR)
        n.sprite_datakey = STR_Jack
        if (_use_costume) costume('01')
      }
      n.hspd = 0x4 << 2
      break
    }
    case 2: {
      // sprIndex 1: Pot lady
      GO_init_palidx(n, G.PI_MOB_RED)
      if (g.town_name === STR_Bulblin) n.sprite_datakey = STR_Goriya
      else {
        n.sprite_datakey = STR_Zoey
        if (_use_costume) costume('02')
      }
      n.hspd = 0x3 << 2
      break
    }
    case 3: {
      // sprIndex 3: Old Woman
      GO_init_palidx(n, G.PI_MOB_RED)
      if (g.town_name === STR_Bulblin) n.sprite_datakey = STR_Daira
      else {
        n.sprite_datakey = STR_Barb
        if (_use_costume) costume('03')
      }
      n.hspd = 0x2 << 2
      break
    }
    case 4: {
      // sprIndex 0: Thin lady
      if (g.town_name === STR_Bulblin) {
        GO_init_palidx(n, G.PI_MOB_BLU)
        n.sprite_datakey = STR_Moblin
      } else {
        GO_init_palidx(n, G.PI_MOB_PUR)
        n.sprite_datakey = STR_Jill
        if (_use_costume) costume('04')
      }
      n.hspd = 0x3 << 2
      break
    }
  }
  if (n.sprite_datakey !== undefined) {
    GO_sprite_init(n, val(g.dm_NPC.get(`${STR_Sprite + n.sprite_datakey}01`), 'spr_0') as string)
  }
  if (n.sprite_datakey === STR_Girubokku) n.hspd = 0x10
  n.hspd = (n.hspd * n.facing_dir) & 0xff
  set_hspd_dir(n)
  n.hspd_dir_spawn = n.hspd_dir
  n.dialogue_datakey = '02_'
  if (g.town_name === STR_Bulblin) n.dialogue_datakey += '4'
  else n.dialogue_datakey += '0'
  let _val =
    g.town_name !== undefined && isVal(g.town_name, STR_Nabooru, STR_Darunia, STR_New_Kasuto, STR_Old_Kasuto)
      ? 1
      : 0
  _val = _val << 2 // 0,4
  const digit = hexStr(_VER - 1 + _val).substring(1, 2) // West: 0,1,2,3, East: 4,5,6,7, Monster: 8,9,A,B
  n.dialogue_datakey += `${digit}_`
  if (G.Halloween1_enabled) {
    n.dialogue_datakey = val(
      g.DIALOGUE_WINDOW.dm_dialogue.get(STR_Halloween + n.dialogue_datakey),
      n.dialogue_datakey,
    ) as string
  }
  // Just in case. Sprite might be short.
  let _Y = n.yt
  _Y = get_ground_y(n.x, _Y, 1, _Y, TID_SOLID1 | TID_ONEWY1)
  _Y -= n.hh_
  set_xy(n, n.x, _Y)
}
