/**
 * Scene rando — ported from `Rando_randomize_scenes.gml` (51 lines).
 *
 * `data_scene_rando()` groups every scene by its exit topology (how many exits, their types and the
 * paths between them). Each group's scene list is shuffled against itself, so a scene is only ever
 * replaced by another scene the player can traverse the same way. `g_Room_Start` reads the result back
 * through `dk_SceneRando+STR_Scene+STR_Randomized+<scene>`.
 *
 * Dropped: nothing. The GML has no dead blocks — only the commented-out `show_debug_message` at `:39`.
 */
import {
  dk_SceneRando,
  STR_Count,
  STR_Group,
  STR_ID,
  STR_Index,
  STR_List,
  STR_Randomized,
  STR_Scene,
} from '@z2/data'
import { DsList } from '../../runtime/ds'
import { G, world } from '../../runtime/world'
import { save_game_pref } from '../file/prefs'
import { gmBool } from '../math/index'
import { hex_str } from '../other/index'
import { ds_list_copy, ds_list_shuffle } from './helpers'
import type { Rando } from './Rando'

export function Rando_randomize_scenes(self: Rando): void {
  G.SceneRando_enabled = gmBool(self.Scenes_WILL_RANDOMIZE)
  save_game_pref()

  world.random_set_seed(self.Rando_SEED)

  const _dl_group_scenes1 = new DsList<string>()
  const _dl_group_scenes2 = new DsList<string>()

  const _GROUP_COUNT = G.dm_scene_rando.val(STR_Group + STR_Count) as number
  for (let _i = 0; _i < _GROUP_COUNT; _i++) {
    _dl_group_scenes1.clear()
    // ZALiA stores the group's scene list as a `ds_list_write` string and `ds_list_read`s it here; the
    // decoded cache (`scene_rando_data.json`) already holds it as an array, so this is a plain copy.
    const _data = G.dm_scene_rando.get(STR_Group + STR_ID + STR_Index + hex_str(_i) + STR_Scene + STR_List) as
      | string[]
      | undefined
    if (_data !== undefined) {
      _dl_group_scenes1.add(..._data)
      const _count = _dl_group_scenes1.size
      if (_count > 1) {
        ds_list_copy(_dl_group_scenes2, _dl_group_scenes1)
        ds_list_shuffle(_dl_group_scenes2)
        for (let _j = 0; _j < _count; _j++) {
          const _scene_name1 = _dl_group_scenes1.get(_j) as string
          const _scene_name2 = _dl_group_scenes2.get(_j) as string
          self.dm_save_data.set(dk_SceneRando + STR_Scene + STR_Randomized + _scene_name1, _scene_name2)
        }
      }
    }
  }
}
