/** Torches — ZALiA `gob2/torch` (`TorchA`, `Torch_ignite`). */
import {
  CS_PR1,
  CS_SW1,
  DEPTH_NIAO,
  DEPTH_PAD,
  dk_SceneRando,
  ITM_CAND,
  STR_Brightness,
  STR_Lit,
  STR_Randomized,
  STR_Scene,
} from '@z2/data'
import { hexStr } from '../../../../nes/hexStr'
import { gmBool } from '../../../../nes/math8'
import { f, G, g, world } from '../../../../runtime/world'
import { rectInRect } from '../../../collision/geometry'
import { sprite_get_height } from '../../../graphics/index'
import { sign_ } from '../../../math/index'
import { val } from '../../../other/index'
import { aud_play_fire } from '../../../sound/play'
import { type GameObject, GameObjectB, ProjectileHostile } from '../../classes'
import { GameObject_draw_1a, GO_draw_sprite } from '../../go/draw'
import { GO_update_cam_vars } from '../../go/misc'
import { GO_depth_init, GO_sprite_init } from '../../go/sprite'
import { pc } from '../../goa/pc'
import { goData } from '../../goData'
import { isAncestorName } from '../../objectNames'
import { GameObjectB_init, GOB_update_2, update_EF11 } from '../GameObjectB'
import type { TorchA } from './classes'
import { draw_sprite_at, gob2Deps } from './deps'

/** `Torch_ignite()` */
export function Torch_ignite(self: TorchA): void {
  self.is_lit = true
  self.brightness = self.BRIGHTNESS
  self.HP_IDX = 0x1f // g.dl_HP_DEFAULT[|$1F] = $FF
  self.hp = g.dl_HP.get(self.HP_IDX) as number
  self.stun_timer = 0
  // prevent any further collision
  self.react_proj = 0
  self.react_sword = 0
  self.cs &= ~(CS_PR1 | CS_SW1)
}

/** `TorchA_init1()` */
export function TorchA_init1(self: TorchA): void {
  GameObjectB_init(self)
  self.can_draw_self_exception = true
  GO_sprite_init(self, 'spr_Torch_1a')
  self.FIRE_SPR = 'spr_Flame1'
  self.FIRE_PI = G.PI_MOB_ORG
  self.FIRE_YOFF = -(self.hh_ + (sprite_get_height(self.FIRE_SPR) >> 1))
  self.FIRE_YOFF--
  self.fire_xscale = 1
  self.is_lit = false
  self.brightness = 0
  self.FireSound_DUR = 0x14
  self.FireSound_tmr = 0
}

/** `TorchA_init2()` */
export function TorchA_init2(self: TorchA): void {
  const _OBJVER = self.objectName + hexStr(self.ver)
  GO_depth_init(self, DEPTH_NIAO - (DEPTH_PAD >> 1))
  self.facing_dir = 1
  self.brightness = 0 // need this here because GO_set_prop_values() sets brightness=1 AFTER init1
  self.BRIGHTNESS = val(goData.dm_go_prop.get(_OBJVER + STR_Brightness), 1) as number // 1,2,..
  if (self.dk_spawn !== undefined)
    self.BRIGHTNESS = val(g.dm_spawn.get(self.dk_spawn + STR_Brightness), self.BRIGHTNESS) as number
  self.BRIGHTNESS = Math.min(2, Math.max(1, self.BRIGHTNESS))
  self.is_lit = false
  if (self.dk_spawn !== undefined)
    self.is_lit = gmBool(val(g.dm_spawn.get(self.dk_spawn + STR_Lit), self.is_lit) as number)
  if (
    G.SceneRando_enabled &&
    G.SceneRando_scene_brightness_control === 1 &&
    g.rm_name !== val(f.dm_rando.get(dk_SceneRando + STR_Scene + STR_Randomized + g.rm_name), g.rm_name)
  ) {
    self.is_lit = true
  }
  if (self.is_lit) Torch_ignite(self)
  if (self.ver === 3) {
    // This torches fire cup is much lower
    GO_sprite_init(self, 'spr_Torch_2a')
    self.FIRE_YOFF = -5
    self.FIRE_YOFF -= (sprite_get_height(self.FIRE_SPR) >> 1) - self.hh_ // (- 4 or - 0) In case I change the image height
    self.FIRE_YOFF--
  }
}

/** `TorchA_update()` */
export function TorchA_update(self: TorchA): void {
  const P = pc()
  if (!self.is_lit) {
    GOB_update_2(self)
    const _HB_X = self.BodyHB_xl
    const _HB_Y = self.BodyHB_yt
    const _HB_W = self.BodyHB_w
    const _HB_H = self.BodyHB_h
    let _C1 = gmBool(self.cs & CS_PR1) || (gmBool(self.cs & CS_SW1) && gmBool(f.items & ITM_CAND)) // Only happens when FIRE proj collides
    if (!_C1 && f.items & ITM_CAND && g.torch_lighting_method === 1) {
      const _W = 6
      const _H = _W
      if (rectInRect(_HB_X, _HB_Y, _HB_W, _HB_H, P.x - (_W >> 1), P.y - 4, _W, _H)) _C1 = true
    }
    if (!_C1) {
      for (const pr of world.instancesOf(ProjectileHostile)) {
        if (
          pr.state === pr.state_NORMAL &&
          (['Fireball1', 'Fireball2', 'Flame1', 'Flame2'] as const).some((n) =>
            isAncestorName(pr.objectName, n),
          ) &&
          rectInRect(_HB_X, _HB_Y, _HB_W, _HB_H, pr.BodyHB_xl, pr.BodyHB_yt, pr.BodyHB_w, pr.BodyHB_h)
        ) {
          self.cs |= CS_PR1
          _C1 = true
          break
        }
      }
    }
    if (!_C1) {
      for (const fr of world.instances) {
        if (!fr.exists) continue // GM's `with(Obj)` skips instances destroyed earlier this frame
        const inst = fr as GameObject
        if (inst.objectName !== 'FiRoA') continue
        if (
          inst.state === inst.state_NORMAL &&
          gob2Deps.colliding_FireRope(inst, _HB_X, _HB_Y, _HB_W, _HB_H)
        ) {
          _C1 = true
          break
        }
      }
    }
    if (!_C1) {
      for (const b of world.instancesOf(GameObjectB)) {
        if (
          b.state === b.state_NORMAL &&
          isAncestorName(b.objectName, 'Blaze01') &&
          rectInRect(_HB_X, _HB_Y, _HB_W, _HB_H, b.BodyHB_xl, b.BodyHB_yt, b.BodyHB_w, b.BodyHB_h)
        ) {
          _C1 = true
          break
        }
      }
    }
    if (_C1) {
      Torch_ignite(self) // set is_lit=true and prevent any further collision
      aud_play_fire(true)
      self.FireSound_tmr = self.FireSound_DUR
    }
  } else {
    if (self.FireSound_tmr) {
      self.FireSound_tmr--
      aud_play_fire(self.FireSound_tmr > 0)
    }
    GO_update_cam_vars(self)
    update_EF11(self)
  }
}

/** `TorchA_udp()` */
export function TorchA_udp(self: TorchA): void {
  self.can_draw_self = true
  self.fire_xscale = sign_(g.counter1 & 0x4)
}

/** `TorchA_draw()` */
export function TorchA_draw(self: TorchA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  GO_draw_sprite(self, self.sprite, self.palidx)
  if (self.is_lit)
    draw_sprite_at(
      self.depth,
      self.FIRE_SPR,
      0,
      self.drawX,
      self.drawY + self.FIRE_YOFF,
      self.FIRE_PI,
      self.fire_xscale,
    )
}
export { GameObject_draw_1a }
