import {
  dk_BlockBreak,
  dk_Boomerang,
  dk_BridgeCrumble,
  dk_ChooseChar,
  dk_CursorSpellMenu,
  dk_ElevatorMove,
  dk_EnemyDeath,
  dk_FairyFly,
  dk_ItemDrop,
  dk_SceneMusicThemeException,
  dk_StrikeEnemy,
  dk_TypeChar,
  dk_WalkWater,
  STR_Asset,
  STR_Audio,
  STR_Beam,
  STR_LockedDoor,
  STR_Loop,
  STR_Name,
  STR_Open,
  STR_Stab,
  STR_Sword,
  STR_Theme,
  STR_Volume,
} from '@z2/data'
import { world } from '../../runtime/world'
import { Audio, type SoundId, type SoundInst } from './Audio'
import { hasSound } from './deps'
import type { AudioGroup } from './playback'
import { get_audio_theme_track as get_audio_theme_track_, sound_is_audio_group } from './theme'

/**
 * `aud_play_sound(sound id, *priority, *loop, *volume, *theme)` — plays a sound; music (group `mus`) stops
 * whatever music is playing first and records the instance as `mus_rm_inst`. Returns the instance (0 = none).
 * FIDELITY: a sound id of 0 / a missing asset plays nothing (GML would have played sound index 0).
 */
export function aud_play_sound(
  sound: SoundId,
  priority = -1,
  loop: boolean | -1 = -1,
  volume = -1,
  theme?: string,
): SoundInst {
  if (!sound || !hasSound(sound)) return 0
  const A = Audio
  const dm = A.dm
  const _PRIORITY = priority !== -1 ? priority : 0xff
  const _LOOP = loop !== -1 ? loop : false
  let _VOLUME = volume !== -1 ? volume : (dm.val(sound + STR_Volume, 1) as number)
  _VOLUME = Math.min(1, Math.max(0, _VOLUME))
  const group: AudioGroup = sound_is_audio_group(sound, 'mus') ? 'mus' : 'snd'
  let _inst: SoundInst
  if (group === 'mus') {
    // MUSIC
    if (
      A.mus_rm_body &&
      A.audio_is_playing(A.mus_rm_body) &&
      dm.val(`${dk_SceneMusicThemeException}02${A.audio_get_name(A.mus_rm_body)}`) &&
      theme !== undefined &&
      dm.val(`${dk_SceneMusicThemeException}02${theme}`) &&
      A.audio_get_name(A.mus_rm_body) !== sound
    ) {
      A.mus_asset_name_interrupted = A.audio_get_name(A.mus_rm_body)
    }
    A.push({ kind: 'stopGroup', group: 'mus' })
    world.emit({ kind: 'music', theme: null })
    _inst = A.newInst(sound)
    A.push({ kind: 'play', inst: _inst, sound, group, loop: _LOOP, priority: _PRIORITY, gain: _VOLUME })
    world.emit({ kind: 'sound', sound, loop: _LOOP })
    A.mus_rm_inst = _inst
    if (theme !== undefined) {
      if (A.dm_music_inst.size > 0xff) A.dm_music_inst.clear() // Just in case dm_music_inst gets too big
      A.dm_music_inst.set(String(_inst) + STR_Theme, theme)
      A.dm_music_inst.set(String(_inst) + STR_Loop, _LOOP)
      A.dm_music_inst.set(String(_inst) + STR_Audio + STR_Asset + STR_Name, sound)
    }
  } else {
    // SOUND
    A.push({ kind: 'stop', sound })
    _inst = A.newInst(sound)
    A.push({ kind: 'play', inst: _inst, sound, group, loop: _LOOP, priority: _PRIORITY, gain: _VOLUME })
    world.emit({ kind: 'sound', sound, loop: _LOOP })
  }
  // gain is applied at play time (the GML set it right after audio_play_sound)
  return _inst
}

/** `audio_stop_sound(sound)` */
export function audio_stop_sound(sound: SoundId): void {
  if (sound) Audio.push({ kind: 'stop', sound })
}

/** `aud_play_sound(get_audio_theme_track(dk))` — the most common ZALiA idiom, exported for other ports. */
export function play_theme_sound(dk: string, priority = -1, loop: boolean | -1 = -1, volume = -1): SoundInst {
  return aud_play_sound(get_audio_theme_track_(dk), priority, loop, volume)
}

/** `aud_play_AdvanceDialogue()` — the sound that plays when advancing to more dialogue w/in the same convo. */
export function aud_play_AdvanceDialogue(): void {
  play_theme_sound(`${dk_WalkWater}02`)
  play_theme_sound(dk_CursorSpellMenu)
  play_theme_sound(dk_CursorSpellMenu)
}

/** `aud_play_fairy1()` */
export function aud_play_fairy1(): void {
  const t = get_audio_theme_track_(dk_FairyFly)
  if (!Audio.audio_is_playing(t)) aud_play_sound(t)
}

/** `aud_play_fire(play or stop, *volume)` — sets the per-frame flags read by `Audio_update_1`. */
export function aud_play_fire(play: boolean | number, volume?: number): void {
  Audio.dl_snd_fire.set(1, play ? 1 : 0) // dl_snd_fire[| 1]: can play
  Audio.dl_snd_fire.set(2, volume === undefined ? -1 : Math.min(1, Math.max(0, volume))) // -1: use default volume
}

/** `aud_toggle_mus()` — mute/un-mute the music group (intent: group gain > 0 means audible). */
export function aud_toggle_mus(): void {
  if (Audio.playback.groupGain('mus') > 0) Audio.audio_group_set_gain('mus', 0)
  else Audio.audio_group_set_gain('mus', Audio.mus_vol / 10)
}

/** `aud_toggle_snd()` */
export function aud_toggle_snd(): void {
  if (Audio.playback.groupGain('snd') > 0) Audio.audio_group_set_gain('snd', 0)
  else Audio.audio_group_set_gain('snd', Audio.snd_vol / 10)
}

/** `aud_play_combo1(combo num)` — sound combinations used by items, menus, cutscenes. */
export function aud_play_combo1(combo: number): void {
  const T = get_audio_theme_track_
  const p = aud_play_sound
  const opt = (name: string) => (hasSound(name) ? name : 0) // max(0, asset_get_index(name)) — FIDELITY: missing → nothing
  switch (combo) {
    case 0x00:
      p(T(STR_Stab))
      p(T(dk_StrikeEnemy))
      break
    case 0x01:
      p(T(dk_BridgeCrumble))
      p(T(dk_TypeChar))
      break
    case 0x02:
      p(T(dk_BridgeCrumble))
      p(T(dk_CursorSpellMenu))
      break
    case 0x03:
      p(T(dk_BridgeCrumble))
      p(T(dk_ElevatorMove))
      break
    case 0x04:
      p(T(dk_BridgeCrumble))
      p(T(dk_ItemDrop))
      break
    case 0x05:
      p(T(STR_Stab))
      p(T(dk_TypeChar))
      break
    case 0x06:
      p(T(dk_BridgeCrumble))
      p(T(dk_CursorSpellMenu))
      p(T(dk_ElevatorMove))
      break
    case 0x07:
      p(T(dk_BridgeCrumble))
      p(T(dk_BlockBreak))
      break
    case 0x08:
      p(T(dk_BridgeCrumble))
      p(T(dk_ElevatorMove))
      p(T(`${dk_WalkWater}02`))
      p(T(dk_ChooseChar), 0, false, 0.2)
      break
    case 0x09:
      p(T(dk_ElevatorMove))
      p(T(`${dk_WalkWater}02`))
      break
    case 0x0a:
      p('snd_Cast_Spell_1a')
      p(T(dk_ItemDrop))
      break
    case 0x0b:
      p(T(dk_StrikeEnemy))
      p(T(dk_EnemyDeath))
      break
    case 0x0c:
      p(T(dk_StrikeEnemy))
      p(T(dk_EnemyDeath))
      p(T(STR_Open + STR_LockedDoor))
      break
    case 0x0d:
      p(T(dk_BlockBreak))
      p(T(dk_StrikeEnemy), 0, false, 0.5)
      break
    case 0x0e:
      p(T(dk_ItemDrop))
      p(T(STR_Sword + STR_Beam))
      break
    case 0x0f:
      p('snd_ZeldaII_BassNote01')
      p('snd_SuperMarioBros3_CanonFiring_2ndPart', 0xff, false, 0.7)
      p(T(dk_BlockBreak), 0xff, false, 0.4)
      p('snd_Z1_Step_1a')
      break
    case 0x10:
      p('snd_Boomerang_1a')
      p('snd_Strike_Enemy_1a')
      break
    case 0x11:
      p(opt('snd_ZeldaII_FDS_EncounterEnter'), 0xff, false, 0.6)
      p('snd_Z1_Secret')
      break
    case 0x12:
      p(opt('snd_ZeldaII_FDS_Flute'), 0xff, false, 0.6)
      p('snd_Flute_Item_1a')
      break
    case 0x13:
      p(T(dk_BridgeCrumble))
      p(T(dk_Boomerang))
      break
    case 0x14:
      p('snd_Z1_Step_1a')
      p(T(STR_Stab))
      break
    case 0x15:
      p('snd_Z1_Step_1a')
      p(T(dk_StrikeEnemy))
      break
    case 0x16:
      p(T(dk_BridgeCrumble))
      p(T(dk_Boomerang))
      p(T(STR_Stab))
      break
    default:
      break
  }
}
