/**
 * Line-by-line GLSL ports of ZALiA's retro shaders (`/home/jk/code/ZALiA/shaders/`).
 *
 * Translation rules applied uniformly, per Phaser 4's `BaseFilterShader` conventions
 * (see the built-in `FilterBarrel.frag` / `FilterBlurLow.frag` in the phaser package):
 * - GM `gm_BaseTexture` and the shaders' own `u_texture` sampler both become `uMainSampler`
 *   (Phaser binds the filter input as texture unit 0 under that name).
 * - GM `v_vTexcoord` becomes `outTexCoord`.
 * - GM `v_vColour` is dropped. It is the vertex tint of the quad; ZALiA draws every one of these
 *   passes with `c_white` at alpha 1, so `v_vColour == vec4(1.0)` and the multiply is a no-op.
 *   The single exception is Blur's `_color *= v_vColour`, which ZALiA *does* use to carry the
 *   composite alpha — that is folded into `uBlurAlpha` below, see `RETRO_BLUR_FRAG`.
 * - GM's passthrough vertex shaders are dropped; Phaser supplies the filter quad's vertex stage.
 * - Uniforms are renamed to Phaser's lowerCamel convention; each declaration names its GM original.
 *
 * `shd_grayscale`, `shd_sepia` and `shd_thermal` are not ported: a repo-wide grep of ZALiA's
 * `.gml`/`.yy`/`.yyp` finds zero references to them. They are dead assets.
 */

/**
 * `shd_SaturationBrightness.shader`.
 * HSV round-trip lifted verbatim; only the uniform names change.
 * `u_effect_type` is declared `int` in GM but set with `shader_set_uniform_f`
 * (`Surface_Draw_GUI_Begin.gml:24`), so `float` here is if anything closer to the original.
 */
export const RETRO_SATURATION_BRIGHTNESS_FRAG = /* glsl */ `
precision mediump float;
uniform sampler2D uMainSampler;   // gm_BaseTexture
uniform float uSaturation;        // u_saturation
uniform float uBrightness;        // u_brightness
uniform float uEffectType;        // u_effect_type
varying vec2 outTexCoord;         // v_vTexcoord

vec3 to_hsv(vec3 _COLOR) // _COLOR: rgb
{
  vec4 _K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
  vec4 _P = mix(vec4(_COLOR.b,_COLOR.g, _K.w,    _K.z), vec4(_COLOR.g,_COLOR.b, _K.x,_K.y), step(_COLOR.b,_COLOR.g));
  vec4 _Q = mix(vec4(    _P.x,    _P.y, _P.w,_COLOR.r), vec4(_COLOR.r,    _P.y, _P.z,_P.x), step(    _P.x,_COLOR.r));

  float _D = _Q.x - min(_Q.w,_Q.y);
  float _E = 0.00001;

  return vec3(abs(_Q.z+(_Q.w-_Q.y) / ((6.0*_D)+_E)), _D/(_Q.x+_E), _Q.x); // hsv
}

vec3 to_rgb(vec3 _COLOR) // _COLOR: hsv
{
  vec4 _K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);

  vec3 _a = vec3(_COLOR.x+_K.x, _COLOR.x+_K.y, _COLOR.x+_K.z);
  vec3 _P = abs((fract(_a)*6.0) - vec3(_K.www));

  _a = clamp(_P-vec3(_K.xxx), vec3(0.0), vec3(1.0));
  return mix(vec3(_K.xxx), _a, _COLOR.y) * _COLOR.z; // rgb
}

vec3 adjust_saturation_and_brightness(vec3 _COLOR) // _COLOR: rgb
{
  vec3 _hsv = to_hsv(_COLOR);
  _hsv.y = clamp(_hsv.y+uSaturation, 0.0,1.0);

       if (uEffectType==1.0) _hsv.z = clamp(_hsv.z+uBrightness, 0.0,1.0);
  else if (uEffectType==2.0) _hsv.z = clamp(_hsv.z*uBrightness, 0.0,1.0);
  else if (uEffectType==3.0)
  {
    if (_hsv.z>=0.65)        _hsv.z = clamp(_hsv.z*uBrightness, 0.0,1.0);
  }
  return to_rgb(_hsv);
}

void main()
{
  gl_FragColor = texture2D(uMainSampler, outTexCoord);
  gl_FragColor.rgb = adjust_saturation_and_brightness(gl_FragColor.rgb);
}
`

/**
 * `shd_ScanLines01.shader`.
 * ZALiA also declares `u_texture_w` and feeds it, but the fragment stage never reads it; dropped.
 * `uTextureH` is fed from `drawingContext.height`, the exact analogue of `application_surface_h`.
 */
export const RETRO_SCANLINES_FRAG = /* glsl */ `
precision mediump float;
uniform sampler2D uMainSampler;   // gm_BaseTexture
uniform float uTextureH;          // u_texture_h
uniform float uLineBrightness;    // u_line_brightness
uniform float uLineHeight;        // u_line_height
varying vec2 outTexCoord;         // v_vTexcoord

void main()
{
  vec4 _color = texture2D(uMainSampler, outTexCoord);

  if (mod(floor(uTextureH*outTexCoord.y), uLineHeight*2.0) < uLineHeight)
  {
    _color.rgb *= vec3(uLineBrightness);
  }

  gl_FragColor = _color;
}
`

/**
 * `shd_Bloom01.shader`.
 *
 * ZALiA unrolls 48 taps by hand: x offsets -4..3, y offsets -3..2, each weighted `u_g` and
 * displaced by `vec2(u_dist_x*x, u_dist_y*y) * u_a`. The double loop below has constant bounds
 * (legal in GLSL ES 1.00, and unrolled by the compiler), so it emits the identical 48 samples in
 * the identical order. The threshold ladder tests `_COLOR.r` only — that is ZALiA's, not a typo.
 */
export const RETRO_BLOOM_FRAG = /* glsl */ `
precision mediump float;
uniform sampler2D uMainSampler;   // u_texture
uniform float uDistX;             // u_dist_x (texel width)
uniform float uDistY;             // u_dist_y (texel height)
uniform float uA;                 // u_a
uniform float uB;                 // u_b
uniform float uC;                 // u_c
uniform float uD;                 // u_d
uniform float uE;                 // u_e
uniform float uF;                 // u_f
uniform float uG;                 // u_g
varying vec2 outTexCoord;         // v_vTexcoord

void main()
{
  vec4 _sum = vec4(0.0);
  for (int _y = -3; _y <= 2; _y++)
  {
    for (int _x = -4; _x <= 3; _x++)
    {
      _sum += texture2D(uMainSampler, outTexCoord+(vec2(uDistX*float(_x), uDistY*float(_y))*uA)) * uG;
    }
  }

  vec4     _COLOR = texture2D(uMainSampler, outTexCoord);
       if (_COLOR.r<uE) gl_FragColor = _sum*_sum*uB + _COLOR;
  else if (_COLOR.r<uF) gl_FragColor = _sum*_sum*uC + _COLOR;
  else                  gl_FragColor = _sum*_sum*uD + _COLOR;
}
`

/**
 * `shd_Blur01.shader` (the live branch; the file's two large commented-out alternatives are dead).
 *
 * ZALiA cannot composite this in one pass: it renders the blur to `_srf_blur`, draws the unblurred
 * `application_surface`, then draws `_srf_blur` over it at alpha `GEE.dg_Blur[#Blur_EDIT, $5]`
 * (`Surface_Draw_GUI_Begin.gml:118-122`, with the comment explaining that blending to a surface
 * target misbehaves). With GM's default `bm_normal` that composite is
 * `out.rgb = blurred.rgb*alpha + base.rgb*(1-alpha)` — `_color *= v_vColour` scales only alpha,
 * since the tint is `c_white`. So the same result is one `mix()` here, in a single pass.
 *
 * `uPixelScale` is declared and fed exactly as ZALiA declares and feeds `u_pixel_scale`; the live
 * fragment branch never reads it there either.
 */
export const RETRO_BLUR_FRAG = /* glsl */ `
precision mediump float;
uniform sampler2D uMainSampler;   // u_texture
uniform vec2 uTexelSize;          // u_texel_size
uniform vec2 uPixelScale;         // u_pixel_scale (declared and fed by ZALiA; unread)
uniform float uBlurAlpha;         // GEE.dg_Blur[#Blur_EDIT,$5]
varying vec2 outTexCoord;         // v_vTexcoord

void main()
{
  float _distx = uTexelSize.x;
  float _disty = uTexelSize.y;
  vec4 _base  = texture2D(uMainSampler, outTexCoord);
  vec4 _color = _base;

  _color += texture2D(uMainSampler, vec2(outTexCoord.x+_distx, outTexCoord.y));        // right
  _color += texture2D(uMainSampler, vec2(outTexCoord.x-_distx, outTexCoord.y));        // left
  _color += texture2D(uMainSampler, vec2(outTexCoord.x,        outTexCoord.y+_disty)); // down
  _color += texture2D(uMainSampler, vec2(outTexCoord.x,        outTexCoord.y-_disty)); // up

  _color += texture2D(uMainSampler, vec2(outTexCoord.x+_distx, outTexCoord.y-_disty)); // right up
  _color += texture2D(uMainSampler, vec2(outTexCoord.x-_distx, outTexCoord.y+_disty)); // left  down
  _color += texture2D(uMainSampler, vec2(outTexCoord.x+_distx, outTexCoord.y+_disty)); // right down
  _color += texture2D(uMainSampler, vec2(outTexCoord.x-_distx, outTexCoord.y-_disty)); // left  up

  _color /= 9.0;

  gl_FragColor = vec4(mix(_base.rgb, _color.rgb, uBlurAlpha), _base.a);
}
`

/**
 * Widescreen black bars — `Surface_Draw_End.gml:22-27`.
 *
 * ZALiA draws two `spr_1x1_WHT` rects tinted `p.C_BLK1`, `g.MaskWideView_w` wide, at `viewXL()` and
 * `viewXR()-w`, full view height. It does this in the room's Draw End, i.e. *into*
 * `application_surface`, before `Surface_Draw_GUI_Begin` runs the shader chain — so the bars are
 * scanlined and bloomed along with everything else. Placing this filter first in the internal list
 * reproduces that ordering exactly.
 */
export const RETRO_WIDE_MASK_FRAG = /* glsl */ `
precision mediump float;
uniform sampler2D uMainSampler;
uniform float uBarFrac;           // g.MaskWideView_w / g.VIEW_W
uniform vec3 uBarColor;           // p.C_BLK1
varying vec2 outTexCoord;

void main()
{
  vec4 _color = texture2D(uMainSampler, outTexCoord);

  if (outTexCoord.x < uBarFrac || outTexCoord.x > 1.0-uBarFrac)
  {
    _color.rgb = uBarColor;
  }

  gl_FragColor = _color;
}
`
