/**
 * Palette indices (`global.PI_*`) and the `global.dm_pi` registry, ported from the middle of `p_init.gml`.
 * Indices are assigned sequentially; the layout is BASE, GUI1-4, PC1-3, DISGUISE_PC, SPELL_PC1-3,
 * CUCCO1-3, DISGUISE_CUCCO, BGR1-4, MOB_ORG/RED/BLU/PUR → PAL_PER_SET palettes per set, two sets per
 * scene (lit, dark), permutations appended after PAL_PER_SCENE.
 */
import { STR_Count, STR_Dark, STR_Index, STR_Palette, STR_Position } from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { DsMap } from '../../runtime/ds'
import { COLORS_PER_PALETTE, PAL_CHAR_PER_COLOR } from './colors'
import { get_pal_pos } from './palString'

let _pi = -1
export const PI_BASE = ++_pi
export const PI_GUI1 = ++_pi
export const PI_GUI2 = ++_pi
export const PI_GUI3 = ++_pi
export const PI_GUI4 = ++_pi
export const PI_PC1 = ++_pi
export const PI_PC2 = ++_pi
export const PI_PC3 = ++_pi
export const PI_DISGUISE_PC = ++_pi
export const PI_SPELL_PC1 = ++_pi
export const PI_SPELL_PC2 = ++_pi
export const PI_SPELL_PC3 = ++_pi
export const PI_CUCCO1 = ++_pi
export const PI_CUCCO2 = ++_pi
export const PI_CUCCO3 = ++_pi
export const PI_DISGUISE_CUCCO = ++_pi
export const PI_BGR1 = ++_pi
export const PI_BGR2 = ++_pi
export const PI_BGR3 = ++_pi
export const PI_BGR4 = ++_pi
/** `global.PI_BGR5` — looked up as "BGR5" which is never registered → -1 in ZALiA; kept for parity. */
export const PI_BGR5 = -1
export const PI_MOB_ORG = ++_pi
export const PI_MOB_RED = ++_pi
export const PI_MOB_BLU = ++_pi
export const PI_MOB_PUR = ++_pi
/** `global.PI_MOB_A` — never registered → -1 in ZALiA; kept for parity. */
export const PI_MOB_A = -1
export const PAL_PER_SET = _pi + 1

export const GUI_COUNT = 4
export const PC_COUNT = 3
export const SPELL_PC_COUNT = 3
export const CUCCO_COUNT = 3
export const BGR_COUNT = 4
export const MOB_COUNT = 4

export const PI_DARKLONK = PI_GUI2
export const PI_CLOUD_1 = PI_BGR4
export const FIRE_PI_SYSTEM_VER = 1 // 1: Normal/Non-modded
export const PI_FIRE_HOSTILE1 = FIRE_PI_SYSTEM_VER >= 4 ? PI_MOB_RED : PI_MOB_ORG

export const PAL_SETS_PER_SCENE = 2 // scene lit set, scene dark set
export const PAL_PER_SCENE = PAL_PER_SET * PAL_SETS_PER_SCENE
export const COL_PER_SET = PAL_PER_SET * COLORS_PER_PALETTE
export const COL_PER_SCENE = PAL_PER_SCENE * COLORS_PER_PALETTE
export const PAL_CHAR_PER_SET = COL_PER_SET * PAL_CHAR_PER_COLOR
export const PAL_CHAR_PER_SCENE = COL_PER_SCENE * PAL_CHAR_PER_COLOR
export const SET_IDX_LIT = 0
export const SET_IDX_DRK = 1
export const PI_LAST_LIT = (SET_IDX_LIT + 1) * PAL_PER_SET - 1
export const PI_LAST_DRK = (SET_IDX_DRK + 1) * PAL_PER_SET - 1
export const PI_LAST = PAL_SETS_PER_SCENE * PAL_PER_SET - 1
export const PI_PERMUT_BASE = PI_LAST + 1
export const PI_LIT1 = SET_IDX_LIT * PAL_PER_SET
export const PI_DRK1 = SET_IDX_DRK * PAL_PER_SET
export const PI_ERR0 = PI_BASE
export const TRIFORCE_PI = PI_MOB_BLU

const DK1 = STR_Palette + STR_Index

/**
 * `global.dm_pi` with the entries p_init registers: `<Group><n>_Palette_Index`, `<Group>_Count`,
 * `<hexPi>_Dark1` (lit → dark index) plus the permutation bookkeeping added by `add_pi_permut`.
 */
export function createPiRegistry(): DsMap<number | string> {
  const m = new DsMap<number | string>()
  m.set(`BASE${DK1}`, PI_BASE)
  const group = (name: string, first: number, count: number) => {
    m.set(name + STR_Count, count)
    for (let i = 0; i < count; i++) m.set(`${name}${i + 1}${DK1}`, first + i)
  }
  group('GUI', PI_GUI1, GUI_COUNT)
  group('PC', PI_PC1, PC_COUNT)
  m.set(`DISGUISE_PC${DK1}`, PI_DISGUISE_PC)
  group('SPELL_PC', PI_SPELL_PC1, SPELL_PC_COUNT)
  group('CUCCO', PI_CUCCO1, CUCCO_COUNT)
  m.set(`DISGUISE_CUCCO${DK1}`, PI_DISGUISE_CUCCO)
  group('BGR', PI_BGR1, BGR_COUNT)
  m.set(`MOB${STR_Count}`, MOB_COUNT)
  m.set(`MOB_ORG${DK1}`, PI_MOB_ORG)
  m.set(`MOB_RED${DK1}`, PI_MOB_RED)
  m.set(`MOB_BLU${DK1}`, PI_MOB_BLU)
  m.set(`MOB_PUR${DK1}`, PI_MOB_PUR)
  for (let i = 0; i < PAL_PER_SET; i++) m.set(`${hexStr(i)}${STR_Dark}1`, PI_DRK1 + i)
  return m
}

/** `dm_pal_data[?hex(pi)+"_Palette_Position"]` for pi 1..PAL_PER_SCENE (as p_init fills it). */
export function createPalPositions(): DsMap<number | string> {
  const m = new DsMap<number | string>()
  for (let i = 0; i < PAL_PER_SCENE; i++)
    m.set(hexStr(i + 1) + STR_Palette + STR_Position, get_pal_pos(i + 1))
  return m
}

/**
 * Publish the palette names ZALiA keeps on `global.` onto `Globals`.
 *
 * `p_init.gml` assigns `global.PI_*`, `global.PAL_*`, `global.C_ALPHA0`, `global.palette_image_w` and the
 * spell-cost permutation indices, and ~30 ported files read them as `G.PI_BGR1`, `G.PI_GUI1`, … . This port
 * also exposes the same values on the `Palette` singleton, and the `Globals` fields were left declared but
 * never assigned — so every one of those reads was `undefined`. Nothing crashed: `draw_sprite_` treats a
 * non-numeric palette index as "no swap" (`palIdx > 0.5` is false for `undefined`), so the sprites simply
 * drew in their source palette instead of the scene's. Called from the `World` constructor so `G.PI_*` is
 * correct before any script runs (FIDELITY_NOTES).
 */
export function installPaletteGlobals(G: Record<string, unknown>, p: Record<string, unknown>): void {
  const names = [
    'C_ALPHA0',
    'PAL_BASE_COLOR_ORDER',
    'PAL_CHAR_PER_COLOR',
    'PAL_CHAR_PER_PAL',
    'COLORS_PER_PALETTE',
    'PI_BASE',
    'PI_GUI1',
    'PI_GUI2',
    'PI_GUI3',
    'PI_GUI4',
    'PI_PC1',
    'PI_PC2',
    'PI_PC3',
    'PI_DISGUISE_PC',
    'PI_SPELL_PC1',
    'PI_SPELL_PC2',
    'PI_SPELL_PC3',
    'PI_CUCCO1',
    'PI_CUCCO2',
    'PI_CUCCO3',
    'PI_DISGUISE_CUCCO',
    'PI_BGR1',
    'PI_BGR2',
    'PI_BGR3',
    'PI_BGR4',
    'PI_BGR5',
    'PI_MOB_ORG',
    'PI_MOB_RED',
    'PI_MOB_BLU',
    'PI_MOB_PUR',
    'PI_CLOUD_1',
    'PI_FIRE_HOSTILE1',
  ]
  for (const n of names) if (n in p) G[n] = p[n]
  G.FIRE_PI_SYSTEM_VER = FIRE_PI_SYSTEM_VER
  // `global.palette_image_w = global.palette_image_W` (`p_init.gml:443`) — the palette texture's width in
  // palettes, i.e. the number of registered indices. Draw sites use it as the "is this index in range" bound.
  Object.defineProperty(G, 'palette_image_w', {
    configurable: true,
    get: () => (p.palette_image as { palettes?: unknown[] } | undefined)?.palettes?.length,
  })
  // `global.use_pal_swap` is one variable in ZALiA: `obj_start_Create.gml:44` writes it and
  // `pal_swap_set` / `_reset` / `_set_tiles` read it. The port wrote `G` and read `p`, so the graphics
  // option could never actually switch the swap off.
  Object.defineProperty(G, 'use_pal_swap', {
    configurable: true,
    get: () => p.use_pal_swap,
    set: (v: unknown) => {
      p.use_pal_swap = v
    },
  })
  // The two spell-cost permutations are registered per room by `p_Room_Start`, so mirror them live.
  for (const n of ['spell_futile_pi', 'spell_unaffordable_pi'] as const)
    Object.defineProperty(G, n, { configurable: true, get: () => p[n] })
}
