/**
 * Phaser 4 Filter controllers + RenderNodes for ZALiA's retro chain.
 *
 * Follows the same pattern as `render/paletteSwapFilter.ts`: one `Phaser.Filters.Controller`
 * subclass holding plain mutable fields, one `Renderer.WebGL.RenderNodes.BaseFilterShader`
 * subclass that copies those fields into uniforms in `setupUniforms()`.
 *
 * Every resolution-dependent uniform (`u_texture_h`, `u_dist_x/y`, `u_texel_size`) is derived from
 * `drawingContext.width/height` inside `setupUniforms`, which Phaser calls once per filter pass.
 * That is what makes the chain follow the viewport across resizes and fullscreen toggles with no
 * resize listener of its own — the same approach Phaser's own `FilterBlurLow` node uses.
 *
 * Phaser 4.2.1 APIs used, verified against the installed package and the 4.0.0-rc.6 docs:
 * - `Phaser.Filters.Controller(camera, renderNodeId)`
 *   https://docs.phaser.io/api-documentation/4.0.0-rc.6/class/filters-controller
 *   (`active` toggles a filter in place; `paddingOverride` defaults to a zero Rectangle, which is
 *   what a full-screen post effect wants — no padding, output the same size as input.)
 * - `Phaser.Renderer.WebGL.RenderNodes.BaseFilterShader(name, manager, fragKey?, fragSource?)`
 *   and its `setupUniforms(controller, drawingContext)` override
 *   https://docs.phaser.io/api-documentation/4.0.0-rc.6/class/renderer-webgl-rendernodes-basefiltershader
 * - `ProgramManager#setUniform(name, value)`
 *   https://docs.phaser.io/api-documentation/4.0.0-rc.6/class/renderer-webgl-programmanager
 *   (stores into a dict; names the compiled program dropped are ignored, so feeding ZALiA's
 *   unread `u_pixel_scale` is harmless.)
 * - `camera.filters.internal` / `.external` (`Phaser.GameObjects.Components.FilterList#add`)
 *   https://docs.phaser.io/api-documentation/4.0.0-rc.6/class/gameobjects-components-filterlist
 */
import Phaser from 'phaser'
import type { BloomParams } from './settings'
import {
  RETRO_BLOOM_FRAG,
  RETRO_BLUR_FRAG,
  RETRO_SATURATION_BRIGHTNESS_FRAG,
  RETRO_SCANLINES_FRAG,
  RETRO_WIDE_MASK_FRAG,
} from './shaders'

export const RETRO_NODE_WIDE_MASK = 'RetroWideMask'
export const RETRO_NODE_SATURATION_BRIGHTNESS = 'RetroSaturationBrightness'
export const RETRO_NODE_SCANLINES = 'RetroScanlines'
export const RETRO_NODE_BLOOM = 'RetroBloom'
export const RETRO_NODE_BLUR = 'RetroBlur'

type Camera = Phaser.Cameras.Scene2D.Camera
type DrawingContext = Phaser.Renderer.WebGL.DrawingContext
type NodeManager = Phaser.Renderer.WebGL.RenderNodes.RenderNodeManager

/** `shd_SaturationBrightness` — `RetroShaders_Saturation_amount` / `_Brightness_amount`. */
export class SaturationBrightnessController extends Phaser.Filters.Controller {
  saturation = 0
  brightness = 0
  /** `u_effect_type`; ZALiA always passes 1. */
  effectType = 1
  constructor(camera: Camera) {
    super(camera, RETRO_NODE_SATURATION_BRIGHTNESS)
  }
}

/** `shd_ScanLines01` — `u_line_brightness` and `u_line_height` (already in target rows). */
export class ScanlinesController extends Phaser.Filters.Controller {
  lineBrightness = 0.5
  lineHeight = 1
  constructor(camera: Camera) {
    super(camera, RETRO_NODE_SCANLINES)
  }
}

/** `shd_Bloom01` — `u_a`..`u_g`; `u_dist_x/y` come from the render target. */
export class BloomController extends Phaser.Filters.Controller {
  params: BloomParams = [0, 0, 0, 0, 0, 0, 0]
  constructor(camera: Camera) {
    super(camera, RETRO_NODE_BLOOM)
  }
}

/** `shd_Blur01` — `u_texel_size` from the render target, `u_pixel_scale` from the window. */
export class BlurController extends Phaser.Filters.Controller {
  alpha = 0.85
  windowWidth = 0
  windowHeight = 0
  constructor(camera: Camera) {
    super(camera, RETRO_NODE_BLUR)
  }
}

/** `g.MaskWideView` black bars — `barFrac` is the per-side width as a fraction of the view. */
export class WideMaskController extends Phaser.Filters.Controller {
  barFrac = 0
  /** `p.C_BLK1`, as normalised rgb. */
  barColor: [number, number, number] = [1 / 255, 1 / 255, 1 / 255]
  constructor(camera: Camera) {
    super(camera, RETRO_NODE_WIDE_MASK)
  }
}

class SaturationBrightnessNode extends Phaser.Renderer.WebGL.RenderNodes.BaseFilterShader {
  constructor(manager: NodeManager) {
    super(RETRO_NODE_SATURATION_BRIGHTNESS, manager, undefined, RETRO_SATURATION_BRIGHTNESS_FRAG)
  }
  override setupUniforms(controller: Phaser.Filters.Controller, _ctx: DrawingContext): void {
    const c = controller as SaturationBrightnessController
    const pm = this.programManager
    pm.setUniform('uSaturation', c.saturation)
    pm.setUniform('uBrightness', c.brightness)
    pm.setUniform('uEffectType', c.effectType)
  }
}

class ScanlinesNode extends Phaser.Renderer.WebGL.RenderNodes.BaseFilterShader {
  constructor(manager: NodeManager) {
    super(RETRO_NODE_SCANLINES, manager, undefined, RETRO_SCANLINES_FRAG)
  }
  override setupUniforms(controller: Phaser.Filters.Controller, ctx: DrawingContext): void {
    const c = controller as ScanlinesController
    const pm = this.programManager
    // ZALiA's `application_surface_h`.
    pm.setUniform('uTextureH', ctx.height)
    pm.setUniform('uLineBrightness', c.lineBrightness)
    pm.setUniform('uLineHeight', c.lineHeight)
  }
}

class BloomNode extends Phaser.Renderer.WebGL.RenderNodes.BaseFilterShader {
  constructor(manager: NodeManager) {
    super(RETRO_NODE_BLOOM, manager, undefined, RETRO_BLOOM_FRAG)
  }
  override setupUniforms(controller: Phaser.Filters.Controller, ctx: DrawingContext): void {
    const c = controller as BloomController
    const pm = this.programManager
    // `RetroShaders_u_dist_x/y = 1.0/application_surface_w/h` (Surface_Step.gml:194-195).
    pm.setUniform('uDistX', ctx.width > 0 ? 1 / ctx.width : 0)
    pm.setUniform('uDistY', ctx.height > 0 ? 1 / ctx.height : 0)
    const [a, b, cc, d, e, f, g] = c.params
    pm.setUniform('uA', a)
    pm.setUniform('uB', b)
    pm.setUniform('uC', cc)
    pm.setUniform('uD', d)
    pm.setUniform('uE', e)
    pm.setUniform('uF', f)
    pm.setUniform('uG', g)
  }
}

class BlurNode extends Phaser.Renderer.WebGL.RenderNodes.BaseFilterShader {
  constructor(manager: NodeManager) {
    super(RETRO_NODE_BLUR, manager, undefined, RETRO_BLUR_FRAG)
  }
  override setupUniforms(controller: Phaser.Filters.Controller, ctx: DrawingContext): void {
    const c = controller as BlurController
    const pm = this.programManager
    const tx = ctx.width > 0 ? 1 / ctx.width : 0
    const ty = ctx.height > 0 ? 1 / ctx.height : 0
    // `texture_get_texel_width/height(application_surface)` (Surface_Draw_GUI_Begin.gml:93).
    pm.setUniform('uTexelSize', [tx, ty])
    // `RetroShaders_u_pixel_scale_x/y = Window_w/h / application_surface_w/h` (Surface_Step.gml:196-197).
    pm.setUniform('uPixelScale', [c.windowWidth * tx, c.windowHeight * ty])
    pm.setUniform('uBlurAlpha', c.alpha)
  }
}

class WideMaskNode extends Phaser.Renderer.WebGL.RenderNodes.BaseFilterShader {
  constructor(manager: NodeManager) {
    super(RETRO_NODE_WIDE_MASK, manager, undefined, RETRO_WIDE_MASK_FRAG)
  }
  override setupUniforms(controller: Phaser.Filters.Controller, _ctx: DrawingContext): void {
    const c = controller as WideMaskController
    const pm = this.programManager
    pm.setUniform('uBarFrac', c.barFrac)
    pm.setUniform('uBarColor', c.barColor)
  }
}

/**
 * Register every retro RenderNode on the renderer. Call once, after `Phaser.Core.Events.READY`.
 * No-ops on the Canvas renderer, which has no `renderNodes` manager (and therefore no filters).
 */
export function registerRetroPostFxNodes(
  renderer: Phaser.Renderer.WebGL.WebGLRenderer | Phaser.Renderer.Canvas.CanvasRenderer,
): void {
  if (!('renderNodes' in renderer)) return
  const manager = renderer.renderNodes
  const add = (id: string, make: () => Phaser.Renderer.WebGL.RenderNodes.BaseFilterShader) => {
    if (!manager.hasNode(id)) manager.addNode(id, make())
  }
  add(RETRO_NODE_WIDE_MASK, () => new WideMaskNode(manager))
  add(RETRO_NODE_SATURATION_BRIGHTNESS, () => new SaturationBrightnessNode(manager))
  add(RETRO_NODE_SCANLINES, () => new ScanlinesNode(manager))
  add(RETRO_NODE_BLOOM, () => new BloomNode(manager))
  add(RETRO_NODE_BLUR, () => new BlurNode(manager))
}
