/** Minigame targets — ZALiA `gob2/target` (`Target_init`, `TargA_*`). */
import { CS_PR1, CS_SW1, DEPTH_ENEMY } from '@z2/data'
import { G } from '../../../../runtime/world'
import { GOB_body_collide_pc_proj, GOB_body_collide_pc_sword } from '../../../collision/gob'
import { ocsH1 } from '../../../collision/ocs'
import { cam_yb_max } from '../../../view/camera'
import { GO_update_cam_vars } from '../../go/misc'
import { updateX, updateY } from '../../go/movement'
import { GO_init_palidx } from '../../go/palette'
import { GO_depth_init } from '../../go/sprite'
import { GameObjectB_step, GOB_udp_1, update_EF11 } from '../GameObjectB'
import type { TargA } from './classes'

/** `Target_init()` */
export function Target_init(self: TargA): void {
  self.DRAW_YOFF = 0
  GO_depth_init(self, DEPTH_ENEMY)
  self.scr_step = GameObjectB_step as never
  self.source_inst = 0
  self.BVR_STRT = 1
  self.BVR_VULN = 2
  self.BVR_FAIL = 3
  self.behavior = self.BVR_STRT
  self.target_hit = false
}

/** `TargetA_init2()` */
export function TargetA_init2(self: TargA): void {
  self.dl_sprites?.add('spr_Moby1', 'spr_Moby2')
  switch (self.ver) {
    case 2:
      GO_init_palidx(self, G.PI_MOB_ORG)
      self.vspd_grav = 1
      break
  }
}

/** `TargetA_update()` */
export function TargetA_update(self: TargA): void {
  updateX(self)
  updateY(self)
  GO_update_cam_vars(self)
  update_EF11(self)
  self.can_draw_self = true
  switch (self.behavior) {
    case self.BVR_STRT: // STRT: STaRT
      if (ocsH1(self)) self.behavior = self.BVR_VULN // if any w in ocs area
      break
    case self.BVR_VULN: {
      // VULN: VULNerable
      if ((self.ver === 1 && !ocsH1(self)) || (self.ver === 2 && self.y >= cam_yb_max() + 0x18)) {
        self.behavior = self.BVR_FAIL
        break
      }
      if (self.ver === 1) GOB_body_collide_pc_sword(self)
      if (self.ver === 2) GOB_body_collide_pc_proj(self)
      if (self.cs & (CS_PR1 | CS_SW1) && !self.target_hit) {
        const src = self.source_inst
        if (src && src.exists) src.points++
        self.target_hit = true
        self.timer = self.explosion_DURATION1
        self.state = self.state_EXPLODE
      }
      break
    }
    case self.BVR_FAIL:
      self.state = 0
      break
  }
}

/** `TargetA_udp()` */
export function TargetA_udp(self: TargA): void {
  self.can_draw_self = true
  switch (self.ver) {
    case 1:
      GOB_udp_1(self, 8)
      break
    case 2:
      GOB_udp_1(self, 8)
      self.yScale = self.vspd & 0x80 ? 1 : -1
      break
  }
}
