/** Typed access to `global.pc` (`G.pc`) for the player port. */
import { G, world } from '../../../runtime/world'
import type { GameObject } from '../classes'
import type { Lonk } from './Lonk'

/** `global.pc` as the player class. Throws if the player was not created (`PC_create`). */
export function pc(): Lonk {
  const p = G.pc as Lonk | null
  if (!p) throw new Error('global.pc is not created yet (call PC_create)')
  return p
}

/** `instance_exists(<ObjectName>)` by object name, for objects whose classes are not ported yet. */
export function instanceNamed(objectName: string): GameObject | null {
  for (const i of world.instances)
    if (i.exists && (i as GameObject).objectName === objectName) return i as GameObject
  return null
}

/**
 * ZALiA stored these on the `Input` object (`Input.hHeld/vHeld/cPres/dHeld`), written by the PC update and
 * read by the PC/collision scripts. They are PC-owned state, so they live here.
 */
export const pcInput = {
  hHeld: 0, // held right $1 or left $2
  vHeld: 0, // held down  $4 or up   $8
  cPres: 0, // pressed b $40 and/or a $80
  dHeld: false, // 0: down NOT held, 1: down held
}
