/**
 * Renders the core's `TileWorld` (GM room tiles) with Phaser 4 Images: one Image per tile, one frame per
 * distinct source rect of a tileset texture (`ts:<name>` keys loaded by BootScene). Layers are rebuilt only
 * when their `version` changes (or a `background_assign` alias / `clear()` happened).
 *
 * Phaser 4 APIs used (verified against docs.phaser.io 4.0.0-rc.6): `scene.textures.get(key)`, `Texture.has`,
 * `Texture.add(name, sourceIndex, x, y, w, h)`, `scene.add.image`, `Image.setOrigin/setFrame/setFlipX/
 * setFlipY/setDepth/setVisible/setAlpha/destroy`. Blitter/Bob was not used because Bobs cannot flip.
 */
import type Phaser from 'phaser'
import type { PaletteSwapCache } from './paletteSwap'
import { phaserDepth } from './text'

/** Structural view of `@z2/core`'s `TileWorld` (kept structural so this module has no core import). */
export interface TileLike {
  tileset: string
  left: number
  top: number
  width: number
  height: number
  x: number
  y: number
  visible: boolean
  alpha: number
  xscale: number
  yscale: number
}
export interface TileLayerLike {
  visible: boolean
  version: number
  /** Palette index the whole layer is swapped with (`color_tiles` / `pal_swap_set_tiles`); -1 = none. */
  palIdx: number
  tiles: Map<number, TileLike>
}
export interface TileWorldLike {
  layers: Map<number, TileLayerLike>
  aliasVersion: number
  clearVersion: number
  resolveTileset(name: string): string
}

interface LayerView {
  version: number
  aliasVersion: number
  images: Phaser.GameObjects.Image[]
}

export const tilesetTextureKey = (name: string) => `ts:${name}`

export class TileRenderer {
  private readonly layers = new Map<number, LayerView>()
  private clearVersion = -1
  private paletteVersion = -1

  constructor(private readonly scene: Phaser.Scene) {}

  /** Frame name for a source rect; created on first use. */
  private frameFor(textureKey: string, left: number, top: number, w: number, h: number): string | undefined {
    const tex = this.scene.textures.get(textureKey)
    if (!tex || tex.key === '__MISSING') return undefined
    const name = `${left},${top},${w},${h}`
    if (!tex.has(name)) tex.add(name, 0, left, top, w, h)
    return name
  }

  private destroyLayer(view: LayerView): void {
    for (const img of view.images) img.destroy()
    view.images.length = 0
  }

  /**
   * `palette`/`paletteVersion`: a layer with `palIdx >= 0` draws through palette-swapped copies of its
   * tileset frames, which is how ZALiA colours every room background (`color_tiles` → `pal_swap_set_tiles`).
   * A new palette version invalidates the cache's textures, so every layer is rebuilt with it.
   */
  sync(tw: TileWorldLike, palette: PaletteSwapCache, paletteVersion: number): void {
    if (paletteVersion !== this.paletteVersion) {
      for (const view of this.layers.values()) this.destroyLayer(view)
      this.layers.clear()
      this.paletteVersion = paletteVersion
    }
    if (tw.clearVersion !== this.clearVersion) {
      for (const view of this.layers.values()) this.destroyLayer(view)
      this.layers.clear()
      this.clearVersion = tw.clearVersion
    }
    // drop layers that vanished
    for (const [depth, view] of this.layers) {
      if (!tw.layers.has(depth)) {
        this.destroyLayer(view)
        this.layers.delete(depth)
      }
    }
    for (const [depth, layer] of tw.layers) {
      let view = this.layers.get(depth)
      if (view && view.version === layer.version) {
        // Only an *aliased* tileset changes what this layer draws (`background_assign`, the animated
        // water/mountain frames): rebuilding every layer on each step of that cycle re-created hundreds of
        // images a second for layers whose tiles never move.
        if (view.aliasVersion === tw.aliasVersion) continue
        view.aliasVersion = tw.aliasVersion
        let aliased = false
        for (const t of layer.tiles.values())
          if (tw.resolveTileset(t.tileset) !== t.tileset) {
            aliased = true
            break
          }
        if (!aliased) continue
      }
      if (!view) {
        view = { version: -1, aliasVersion: -1, images: [] }
        this.layers.set(depth, view)
      }
      this.destroyLayer(view)
      if (layer.visible) {
        const pDepth = phaserDepth(depth)
        for (const t of layer.tiles.values()) {
          if (!t.visible) continue
          const key = tilesetTextureKey(tw.resolveTileset(t.tileset))
          const frame = this.frameFor(key, t.left, t.top, t.width, t.height)
          if (frame === undefined) continue
          const x0 = t.xscale < 0 ? t.x - t.width : t.x
          const y0 = t.yscale < 0 ? t.y - t.height : t.y
          const img =
            layer.palIdx >= 0
              ? this.scene.add.image(x0, y0, palette.get(key, frame, layer.palIdx))
              : this.scene.add.image(x0, y0, key, frame)
          img.setOrigin(0, 0).setDepth(pDepth)
          if (t.xscale < 0) img.setFlipX(true)
          if (t.yscale < 0) img.setFlipY(true)
          if (t.alpha !== 1) img.setAlpha(t.alpha)
          view.images.push(img)
        }
      }
      view.version = layer.version
      view.aliasVersion = tw.aliasVersion
    }
  }

  destroy(): void {
    for (const view of this.layers.values()) this.destroyLayer(view)
    this.layers.clear()
  }
}
