/** Growable grid helper (GM `ds_grid_resize` keeps the grid identity). */
export function gridResize(gr: DsGrid<any>, w: number, h: number, fill: any = 0): void {
  const cells: any[][] = Array.from({ length: h }, (_, y) =>
    Array.from({ length: w }, (_, x) => (y < gr.height && x < gr.width ? (gr.cells[y] as any[])[x] : fill)),
  )
  const m = gr as unknown as { width: number; height: number; cells: any[][] }
  m.width = w
  m.height = h
  m.cells = cells
}
export function gridClear(gr: DsGrid<any>, v: any): void {
  for (const row of gr.cells) row.fill(v)
}
export function gridCopy(dst: DsGrid<any>, src: DsGrid<any>): void {
  gridResize(dst, src.width, src.height)
  for (let y = 0; y < src.height; y++) for (let x = 0; x < src.width; x++) dst.set(x, y, src.get(x, y))
}
/** GM `ds_grid_set_region` (inclusive bounds). */
export function gridSetRegion(gr: DsGrid<any>, x1: number, y1: number, x2: number, y2: number, v: any): void {
  for (let y = Math.max(0, y1); y <= Math.min(gr.height - 1, y2); y++)
    for (let x = Math.max(0, x1); x <= Math.min(gr.width - 1, x2); x++) gr.set(x, y, v)
}

