/** State of the one-shot `GameObjectData` initializer object: `g.dm_go_prop`, `g.dl_Enemy_OBJVER`. */
import { DsList, DsMap } from '../../runtime/ds'

export const goData = {
  /** `g.dm_go_prop` — per objver properties written by data_go_prop1/2/3, data_REFLECT_vuln. */
  dm_go_prop: new DsMap<number | string | boolean>(),
  /** `g.dl_Enemy_OBJVER` — every non-boss, non-kakusu enemy objver (for enemy rando). */
  dl_Enemy_OBJVER: new DsList<string>(),
  reset(): void {
    this.dm_go_prop = new DsMap()
    this.dl_Enemy_OBJVER = new DsList()
  },
}
