/**
 * Registration entry for every gob1 enemy port. The three waves that ported them each kept their own entry:
 * `ache/registerA.ts` (ache…fokkeru + Bot/Bubble/Capper/Daira/Deeler/Doomknocker/Fokka/Fokkeru),
 * one `register<Name>()` per folder for geldarm…moby + iron_knuckle, and `../index.myu-zora` (myu…zora plus
 * the gob1 extras: kakusu, spawners, spike traps, fire rope), which registers at import time.
 * `registerEnemies()` re-runs all of them, which is what tests need after `resetRegistries()`.
 */
import '../index.myu-zora' // myu…zora, kakusu, spawner, spike_trap, fire_rope (module-scope registration)
import { registerMyuToZora } from '../index.myu-zora'
import { registerEnemiesA } from './ache/registerA'
import { registerBossBot } from './bot/BossBot'
import { registerGeldarm } from './geldarm/Geldarm'
import { registerGellzem } from './gellzem/Gellzem'
import { registerGeru } from './geru/Geru'
import { registerGirubokku } from './girubokku/Girubokku'
import { registerGoriya } from './goriya/Goriya'
import { registerGrowkke } from './growkke/Growkke'
import { registerGrunt } from './grunt/Grunt'
import { registerGuma } from './guma/Guma'
import { registerIronKnuckle } from './iron_knuckle/IronKnuckle'
import { registerLeever } from './leever/Leever'
import { registerLowder } from './lowder/Lowder'
import { registerMagnot } from './magnot/Magnot'
import { registerMago } from './mago/Mago'
import { registerMau } from './mau/Mau'
import { registerMegmat } from './megmat/Megmat'
import { registerMoa } from './moa/Moa'
import { registerMoblin } from './moblin/Moblin'
import { registerMoby } from './moby/Moby'

/** Registers every enemy class and its data-bound scripts. Idempotent; safe after a registry reset. */
export function registerEnemies(): void {
  registerEnemiesA()
  registerBossBot()
  registerGeldarm()
  registerGellzem()
  registerGeru()
  registerGirubokku()
  registerGoriya()
  registerGrowkke()
  registerGrunt()
  registerGuma()
  registerIronKnuckle()
  registerLeever()
  registerLowder()
  registerMagnot()
  registerMago()
  registerMau()
  registerMegmat()
  registerMoa()
  registerMoblin()
  registerMoby()
  registerMyuToZora()
}

registerEnemies()
