/**
 * Helpers shared by the gob1 entity ports in this folder (myu–zora, kakusu, spawner, spike_trap, fire_rope):
 * the OG random byte (`rand()`), GM `lengthdir_*`, `goDist1`, `Enemy_update_2/3` (shared by Aruroda/Tonn/Zora
 * in ZALiA's `enemy` root folder), spawn-data string parsing, and instance lookup by object name.
 */
import { gmBool } from '../../../../nes/math8'
import { DsList } from '../../../../runtime/ds'
import { g, world } from '../../../../runtime/world'
import { wINwAll } from '../../../collision/geometry'
import { hex_str, str_hex, val } from '../../../other/index'
import { cam_x_range } from '../../../view/camera'
import type { GameObject } from '../../classes'
import { updateY } from '../../go/movement'
import { solid_clip_correction } from '../../goa/movement'
import { pc } from '../../goa/pc'

/** `rand()` — this object's byte of the OG random register (`g.dl_RandomOG[|1+update_idx]`), else `irandom($FF)`. */
export function rand(self: GameObject): number {
  const size = g.dl_RandomOG.size
  if (self.update_idx >= 0 && self.update_idx < size - 1)
    return (g.dl_RandomOG.get(1 + self.update_idx) as number) ?? 0
  return world.irandom(0xff)
}

/** GM `lengthdir_x/y` (degrees, y axis down). */
export const lengthdir_x = (len: number, dir: number): number => len * Math.cos((dir * Math.PI) / 180)
export const lengthdir_y = (len: number, dir: number): number => -len * Math.sin((dir * Math.PI) / 180)

/** `goDist1()` — distance between global.pc.xl and this.xl mimicking $000F at DCA1 (DC91). */
export function goDist1(self: GameObject): number {
  const p = pc()
  let _return = p.xl & 0xff
  _return += ~(self.xl & 0xff) & 0xff
  _return += p.xl >= 0 && p.xl <= 7 ? 1 : 0 // carry
  return _return & 0xff
}

/** `Enemy_update_2()` — used by Aruroda, Zora. 9B09 */
export function Enemy_update_2(self: GameObject & { frwd_bkwd: number }): void {
  // $40: 1.067s. During every other quarter of a byte
  if (self.counter & 0x40) return
  if (!(self.counter & 0x3f)) {
    // 1st frame of move period: decide hspd for this move period
    let _C1 = 0x18
    if (!gmBool(self.facing_dir)) _C1 += 0x10
    const c1 = wINwAll(self.x - _C1, 0x30, 0, cam_x_range())
    if (self.counter & 0x80 && c1)
      self.frwd_bkwd = -self.facing_dir // go backwards
    else self.frwd_bkwd = self.facing_dir // go forwards
  }
  if (gmBool(self.frwd_bkwd))
    self.hspd = (0x08 * self.facing_dir) & 0xff // go forwards
  else self.hspd = ((0x10 * self.facing_dir) & 0xff) ^ 0xff // go backwards
}

/** `Enemy_update_3()` — used by Aruroda, Tonne, Zora. 9B45 (update vertical) */
export function Enemy_update_3(self: GameObject): void {
  if (self.vspd < 0x80 && self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
    return
  }
  if (self.vspd & 0x80 || !(self.cs & 0x4)) {
    if (self.vspd & 0x80 && self.cs & 0x8) self.vspd = 0 // MOD
    updateY(self)
  }
}

/** The `dl_sprites` list of an instance (created lazily as ZALiA's init_vars does). */
export function dl(self: GameObject): DsList<string> {
  if (!self.dl_sprites) self.dl_sprites = new DsList<string>()
  return self.dl_sprites
}

/**
 * ZALiA's recurring spawn-data scan: `g.dm_spawn[?dk_spawn+STR_Data+hex_str(i)]` for i in 1..max, returning the
 * text after `key` in the first entry containing it (`undefined` when absent).
 */
export function spawnDataAfter(dkSpawn: string | undefined, key: string, max = 0x0f): string | undefined {
  if (dkSpawn === undefined) return undefined
  for (let _i = 1; _i <= max; _i++) {
    const _val = g.dm_spawn.get(`${dkSpawn}_Data${hex_str(_i)}`)
    if (typeof _val !== 'string') continue
    const _pos = _val.indexOf(key)
    if (_pos >= 0) return _val.slice(_pos + key.length)
  }
  return undefined
}

/** Same scan returning whether any entry *contains* `key`. */
export function spawnDataHas(dkSpawn: string | undefined, key: string, max = 0x0f): boolean {
  return spawnDataAfter(dkSpawn, key, max) !== undefined
}

export { str_hex, val }

/** `with (ObjName)` over live instances of one object name (leaf classes may live in other ports). */
export function* instancesOfName<T extends GameObject = GameObject>(name: string): Generator<T> {
  for (const i of world.instances) if (i.exists && (i as GameObject).objectName === name) yield i as T
}

/** `instance_number(ObjName)` */
export function instanceNumberOf(name: string): number {
  let n = 0
  for (const _ of instancesOfName(name)) n++
  return n
}

/** `instance_exists(ObjName)` for a class name. */
export function instanceExistsNamed(name: string): boolean {
  for (const _ of instancesOfName(name)) return true
  return false
}

/** GM `sign()` */
export const sign = (v: number): -1 | 0 | 1 => (v > 0 ? 1 : v < 0 ? -1 : 0)
/** GM `frac()` */
export const frac = (v: number): number => v - Math.trunc(v)
