import {
  MapAreaName_BULBLIN,
  MapAreaName_DARUNIA,
  MapAreaName_DATAKEY,
  MapAreaName_KASUTO,
  MapAreaName_MIDO,
  MapAreaName_NABOORU,
  MapAreaName_NEW_KASUTO,
  MapAreaName_RAURU,
  MapAreaName_RUTO,
  MapAreaName_SARIA,
  STR_Bulblin,
  STR_Count,
  STR_Darunia,
  STR_Mido,
  STR_Nabooru,
  STR_Name,
  STR_New_Kasuto,
  STR_Num,
  STR_Old_Kasuto,
  STR_Rauru,
  STR_Ruto,
  STR_Saria,
  STR_Town,
} from '@z2/data'
import { hexStr as hex_str } from '../../../nes/hexStr'
import { g } from '../../../runtime/world'

/** GML: init_data_town_1a() */
export function init_data_town_1a() {
  // GML `var` is function-scoped; locals hoisted here:
  let _town_name: any, _town_num: any
  // let _town_name: any;
  _town_num = 0
  _town_num++
  _town_name = STR_Rauru
  g.dm_town.set(STR_Town + STR_Name + hex_str(_town_num), _town_name)
  g.dm_town.set(STR_Town + STR_Num + _town_name, _town_num)
  g.dm_town.set(_town_name + MapAreaName_DATAKEY, MapAreaName_RAURU)
  _town_num++
  _town_name = STR_Ruto
  g.dm_town.set(STR_Town + STR_Name + hex_str(_town_num), _town_name)
  g.dm_town.set(STR_Town + STR_Num + _town_name, _town_num)
  g.dm_town.set(_town_name + MapAreaName_DATAKEY, MapAreaName_RUTO)
  _town_num++
  _town_name = STR_Saria
  g.dm_town.set(STR_Town + STR_Name + hex_str(_town_num), _town_name)
  g.dm_town.set(STR_Town + STR_Num + _town_name, _town_num)
  g.dm_town.set(_town_name + MapAreaName_DATAKEY, MapAreaName_SARIA)
  _town_num++
  _town_name = STR_Mido
  g.dm_town.set(STR_Town + STR_Name + hex_str(_town_num), _town_name)
  g.dm_town.set(STR_Town + STR_Num + _town_name, _town_num)
  g.dm_town.set(_town_name + MapAreaName_DATAKEY, MapAreaName_MIDO)
  _town_num++
  _town_name = STR_Nabooru
  g.dm_town.set(STR_Town + STR_Name + hex_str(_town_num), _town_name)
  g.dm_town.set(STR_Town + STR_Num + _town_name, _town_num)
  g.dm_town.set(_town_name + MapAreaName_DATAKEY, MapAreaName_NABOORU)
  _town_num++
  _town_name = STR_Darunia
  g.dm_town.set(STR_Town + STR_Name + hex_str(_town_num), _town_name)
  g.dm_town.set(STR_Town + STR_Num + _town_name, _town_num)
  g.dm_town.set(_town_name + MapAreaName_DATAKEY, MapAreaName_DARUNIA)
  _town_num++
  _town_name = STR_New_Kasuto
  g.dm_town.set(STR_Town + STR_Name + hex_str(_town_num), _town_name)
  g.dm_town.set(STR_Town + STR_Num + _town_name, _town_num)
  g.dm_town.set(_town_name + MapAreaName_DATAKEY, MapAreaName_NEW_KASUTO)
  _town_num++
  _town_name = STR_Old_Kasuto
  g.dm_town.set(STR_Town + STR_Name + hex_str(_town_num), _town_name)
  g.dm_town.set(STR_Town + STR_Num + _town_name, _town_num)
  g.dm_town.set(_town_name + MapAreaName_DATAKEY, MapAreaName_KASUTO)
  _town_num++
  _town_name = STR_Bulblin
  g.dm_town.set(STR_Town + STR_Name + hex_str(_town_num), _town_name)
  g.dm_town.set(STR_Town + STR_Num + _town_name, _town_num)
  g.dm_town.set(_town_name + MapAreaName_DATAKEY, MapAreaName_BULBLIN)
  g.dm_town.set(STR_Town + STR_Count, _town_num)
}
