/** `rand()` for gob2 objects: the OG shift-register byte for this update slot, `irandom($FF)` outside it. */
import { world } from '../../../../runtime/world'
import type { GameObject } from '../../classes'

export function OgRandomRead(self: GameObject): number {
  return world.ogRandom.rand(self.update_idx, () => world.irandom(0xff))
}
