/** `audio_stop_sound(Audio.mus_rm_inst)` — stop by playing instance. */
function stopMusInst(): void {
  if (Audio.mus_rm_inst) Audio.push({ kind: 'stopInst', inst: Audio.mus_rm_inst })
}

// biome-ignore lint/suspicious/noExplicitAny: NPC_A / ShadowLonk01 are not ported yet; fields are ZALiA's
const first = (name: string): any => {
  for (const i of instancesNamed(name)) return i
  return undefined
}

/** `Cutscene_ShadowBoss_init()` — class field defaults (`TK_OBJ = NPC_A`, `BOSS_OBJ = ShadowLonk01`). */
export function Cutscene_ShadowBoss_init(self: CutsceneShadowBoss): void {
  self.TK_OBJ = 'NPC_A'
  self.BOSS_OBJ = 'ShadowLonk01'
}

/** `Cutscene_ShadowBoss_update_1a()` — true if the boss of this room was already defeated. */
export function Cutscene_ShadowBoss_update_1a(self: CutsceneShadowBoss): boolean {
  if (self.BOSS_SPAWN_DK === undefined) {
    const b = first(self.BOSS_OBJ)
    if (b) self.BOSS_SPAWN_DK = b.dk_spawn
  }
  let _SB_DEFEATED = false
  if (self.BOSS_SPAWN_DK !== undefined)
    _SB_DEFEATED = gmBool(val(f.dm_quests.get(get_defeated_dk() + self.BOSS_SPAWN_DK)))
  return _SB_DEFEATED
}

/** The `Cutscene_ShadowBoss_2` spawn datakey is this cutscene's datakey with its index + 1. */
function nextSpawnDk(dk: string): string {
  return dk.slice(0, dk.length - 2) + hexStr(str_hex(dk.slice(dk.length - 2)) + 1)
}

/** `Cutscene_ShadowBoss_1_init()` */
export function Cutscene_ShadowBoss_1_init(self: Cutscene_ShadowBoss_1): void {
  Cutscene_init(self)
  Cutscene_ShadowBoss_init(self)
  self.scr_step = Cutscene_ShadowBoss_1_update as never
  self.BOSS_SPAWN_DK = undefined
  const b = first(self.BOSS_OBJ)
  if (b) self.BOSS_SPAWN_DK = b.dk_spawn
  const _GO_COUNT = g.dg_spawn_prxm.width
  for (let _i = 0; _i < _GO_COUNT; _i++) {
    const _spawn_dk = g.dg_spawn_prxm.get(_i, 0) as string
    const _obj = g.dg_spawn_prxm.get(_i, 1)
    if (_obj === self.BOSS_OBJ) {
      self.BOSS_SPAWN_DK = _spawn_dk
      break
    }
  }
  if (Cutscene_ShadowBoss_update_1a(self)) {
    // if boss already defeated
    const sb2 = GameObject_create(
      0,
      0,
      'Cutscene_ShadowBoss_2',
      1,
      nextSpawnDk(self.dk_spawn as string),
    ) as Cutscene_ShadowBoss_2 | null
    if (sb2) {
      if (sb2.BOSS_SPAWN_DK === undefined && self.BOSS_SPAWN_DK !== undefined)
        sb2.BOSS_SPAWN_DK = self.BOSS_SPAWN_DK
      sb2.ARENA_X = g.rm_w_
      sb2.sub_state = sb2.sub_state_DONE
    }
    self.destroy()
  }
}

/** `Cutscene_ShadowBoss_1_update()` — 97DE: Shadow Link appears out of Link. */
export function Cutscene_ShadowBoss_1_update(self: Cutscene_ShadowBoss_1): void {
  if (g.ChangeRoom_timer > 0 || gmBool(g.EnterRoom_SpawnGO_timer)) return
  const pc = G.pc
  if (!gmBool(g.cutscene) && !Cutscene_ShadowBoss_update_1a(self)) {
    // if Boss NOT defeated yet. 97DE, 97E0: JSR EF11
    for (const tk of instancesNamed(self.TK_OBJ)) {
      if (f.quest_num >= 2) set_xlyt(tk, tk.spawn_xl - 0x10, tk.spawn_yt)
      tk.counter = (tk.counter + 1) & 0xff
      if (f.quest_num === 1) tk.tri_can_draw = 1
      // canDrawSelf gets set to false before draw so changing sub_state will give the indication.
      tk.sub_state = 1
    }
    // 97E3
    let _ARENA_X: number = g.rm_w_
    const boss = first(self.BOSS_OBJ)
    if (boss) _ARENA_X = boss.arena_x
    if (viewXC() >= _ARENA_X) {
      set_camera_xy(_ARENA_X - viewW_(), viewYT()) // Snap to section
      g.view_lock_boss = 0x3
      g.view_lock |= g.view_lock_boss | g.view_lock_rm
      pc.hspd = 0
      if (!gmBool(pc.ogr)) {
        gofDeps.solid_clip_correction(pc, false)
        gofDeps.PC_set_behavior(pc, pc.behavior_IDLE)
        pc.xScale = 1
        g.pc_lock = PC_LOCK_ALL // Lock all
        g.cutscene = 1
        g.cutscene_part = 1
        g.cutscene_timer = 0xff
        for (const tk of instancesNamed(self.TK_OBJ)) tk.sub_state++
      }
    }
  }
  // 97C6: JSR A4C4.  Triforce flash
  triforce_pal_update() // pi here is PI_MOB_BLU
  if (!gmBool(g.cutscene)) return
  switch (g.cutscene_part) {
    case 1: {
      // ShadowBoss-982C
      for (const tk of instancesNamed(self.TK_OBJ)) tk.sub_state = 0 // TK: Triforce Keeper
      if (g.cutscene_timer >= 0x50) {
        // 9830
        if (g.cutscene_timer >= 0xc0 || g.cutscene_timer & 1) {
          // translucent/fade effect
          for (const tk of instancesNamed(self.TK_OBJ)) {
            tk.counter = (tk.counter + (g.cutscene_timer >= 0xc0 ? 1 : 0)) & 0xff
            if (f.quest_num === 1) tk.tri_can_draw = 1
            tk.sub_state = 1
          }
        }
      }
      // 980D
      if (!gmBool(g.cutscene_timer)) {
        // 9812
        for (const b of instancesNamed(self.BOSS_OBJ)) set_xy(b, pc.x, b.GROUND_Y - b.hh_)
        const _DURATION = 0x40
        p.Flash_Pal_timer = _DURATION
        p.Flash_Bgr_timer = _DURATION
        p.SpellFlash_PC_timer = _DURATION
        g.cutscene_timer = 0xff
        p.BackgroundColor_scene = p.C_MGN3 // 0751 = $14; // room bg color
        aud_play_sound(get_audio_theme_track(STR_Cast + STR_Spell))
        for (const tk of instancesNamed(self.TK_OBJ)) tk.sub_state = 0 // Make sure TK doesn't update.
        g.cutscene_part++
      }
      break
    }
    case 2: {
      // ShadowBoss-983E
      if (p.Flash_Bgr_timer >= 0x01) break
      let _PI_DEF: number = G.PI_MOB_PUR
      const boss = first(self.BOSS_OBJ)
      if (boss) _PI_DEF = boss.palidx_def
      // Change ShadowBoss and background palettes to black
      const _pal = build_pal(p.C_BLK1, p.C_BLK1, p.C_BLK1, p.C_BLK1, p.C_BLK1, p.C_BLK1, p.C_BLK1, p.C_BLK1)
      change_pal(strReplaceAt(p.pal_rm_new, get_pal_pos(_PI_DEF), _pal.length, _pal))
      for (let _i = (val(G.dm_pi.get(`BGR${STR_Count}`), 1) as number) - 1; _i >= 0; _i--) {
        const _pos = get_pal_pos(
          val(G.dm_pi.get(`BGR${_i + 1}${STR_Palette}${STR_Index}`), G.PI_BGR1 + _i) as number,
        )
        change_pal(strReplaceAt(p.pal_rm_new, _pos, _pal.length, _pal))
      }
      aud_play_sound(get_audio_theme_track(STR_Cast + STR_Spell))
      stopMusInst()
      Audio.mus_rm_intr = 0
      Audio.mus_rm_body = 0
      g.cutscene_part++
      break
    }
    case 3: {
      // ShadowBoss-9852
      for (const b of instancesNamed(self.BOSS_OBJ)) {
        const _CUE = 0x80
        if (g.cutscene_timer <= _CUE) {
          if (g.cutscene_timer === _CUE) {
            set_xy(b, pc.x, b.GROUND_Y - b.hh_)
            b.facing_dir = -1
            b.vspd = 0xfc
            b.hspd = 0x13
            b.ogr = OGR_OTHR // project constant, not an instance field
            b.sub_state++ // So update_ShadowBoss() can run udp_ShadowBoss()
          }
          // 9864: JSR 9A0F
          updateX(b)
          updateY2(b, b.GRAV_ADD, b.TERMINAL_VELOCITY)
          if (b.yb >= b.GROUND_Y) {
            g.cutscene_timer = 0x70 + 1
            GO_set_sprite(b, pc.sprite as string)
            set_xy(b, b.x, b.GROUND_Y - b.hh_) // mod
            g.cutscene_part++
          }
          b.behavior = pc.behavior_DAMAGE // $0A: BVR_DAMG
        }
      }
      break
    }
    case 4: {
      // ShadowBoss-987B
      if (gmBool(g.cutscene_timer)) {
        // Fight not started yet. 9887
        for (const b of instancesNamed(self.BOSS_OBJ)) {
          b.behavior = pc.behavior_CROUCH
          gofDeps.ShadowBoss_udp(b)
        }
      }
      if (g.cutscene_timer === 1)
        for (const b of instancesNamed(self.BOSS_OBJ)) gofDeps.Boss_play_battle_music(b)
      if (!gmBool(g.cutscene_timer)) {
        g.pc_lock = 0
        for (const b of instancesNamed(self.BOSS_OBJ)) b.sub_state++ // START FIGHT
        g.cutscene = 0
        g.cutscene_part = 0
        const sb2 = GameObject_create(
          0,
          0,
          'Cutscene_ShadowBoss_2',
          1,
          nextSpawnDk(self.dk_spawn as string),
        ) as Cutscene_ShadowBoss_2 | null
        if (sb2 && sb2.BOSS_SPAWN_DK === undefined && self.BOSS_SPAWN_DK !== undefined)
          sb2.BOSS_SPAWN_DK = self.BOSS_SPAWN_DK
        self.destroy()
      }
      break
    }
  }
}

/** `Cutscene_ShadowBoss_2_init()` */
export function Cutscene_ShadowBoss_2_init(self: Cutscene_ShadowBoss_2): void {
  Cutscene_init(self)
  Cutscene_ShadowBoss_init(self)
  self.scr_step = Cutscene_ShadowBoss_2_update as never
  self.scr_draw = Cutscene_ShadowBoss_2_draw as never
  self.triforce_can_draw = 0
  self.TRIFORCE_SPR = 'spr_Triforce_1a'
  p.triforce_pi = p.TRIFORCE_PI
  self.BOSS_SPAWN_DK = undefined
  const b = first(self.BOSS_OBJ)
  if (b) self.BOSS_SPAWN_DK = b.dk_spawn
  self.ARENA_X = 0
  self.Boss_can_draw = false
  self.Boss_SPR = 0
  self.Boss_PI = G.PI_GUI4 // Greyscale, like PI_GUI2
  self.Boss_pi = self.Boss_PI
  self.Boss_x = 0
  self.Boss_y = 0
  self.Boss_Raise_DIST = 0x20
  self.Boss_Target_y = 0
  self.Boss_vspd = 0
  if (f.quest_num >= 2) {
    self.Blood_can_draw = false
    self.Blood_COLOR = p.C_RED3
    self.Blood_x = 0
    self.Blood_yt = 0
    self.Blood_yb = 0
    self.Blood_yb_MAX = 0
    self.Blood_h = 2
    self.Bottle_can_draw = false
    self.Bottle_SPR1 = 'spr_Item_Bottle_8d' // No top
    self.Bottle_SPR2 = 'spr_Item_Bottle_8c' // full, including liquid
    self.Bottle_spr = self.Bottle_SPR1
    self.BottleTop_SPRITE = 'spr_Item_Bottle_8_Top'
    self.Bottle_x = 0
    self.Bottle_y = 0
    self.BottleLiquid_level = 0
    self.BottleLiquid_SPR = 'spr_Item_Bottle_8_Liquid_1a_1'
  }
  self.sub_state = self.sub_state_BATTLE1
}

/** `Cutscene_ShadowBoss_2_update()` */
export function Cutscene_ShadowBoss_2_update(self: Cutscene_ShadowBoss_2): void {
  if (g.ChangeRoom_timer > 0 || gmBool(g.EnterRoom_SpawnGO_timer)) return
  const pc = G.pc
  if (!gmBool(self.ARENA_X)) {
    const b = first(self.BOSS_OBJ)
    if (b) self.ARENA_X = b.arena_x
  }
  if (f.quest_num >= 2) {
    self.Boss_can_draw = false
    self.Bottle_can_draw = false
    self.Blood_can_draw = false
  }
  // 97C6: JSR A4C4.  Triforce flash
  triforce_pal_update()
  const blink = (timing: number) => {
    if (g.counter1 & timing && g.counter1 & (timing >> 1)) self.Boss_pi = G.PI_MOB_PUR
    else self.Boss_pi = self.Boss_PI
  }
  switch (self.sub_state) {
    case self.sub_state_BATTLE1: {
      if (!Cutscene_ShadowBoss_update_1a(self)) break // if boss IS NOT defeated
      // ShadowBoss-98BA. Audio will be 1 frame late. Normally played in boss update.
      aud_play_sound(get_audio_theme_track(STR_Cast + STR_Spell))
      stopMusInst()
      Audio.can_play_boss_music = false
      const _DURATION = 0x30 - 1
      p.Flash_Pal_timer = _DURATION
      p.Flash_Bgr_timer = _DURATION
      p.SpellFlash_PC_timer = _DURATION
      g.cutscene_timer = 0x40 - 1
      g.cutscene_part = 1
      g.cutscene = 1
      self.sub_state = self.sub_state_POST_BATTLE1
      break
    }
    case self.sub_state_POST_BATTLE1: {
      // ShadowBoss-9B3A
      if (p.Flash_Bgr_timer === 0x01) {
        change_pal(p.pal_rm_def as string)
        const _PAL = build_pal(p.C_GRY1, p.C_GRY4, p.C_BLK1, p.C_BLK1, -2, -2, -2, -2)
        change_pal(strReplaceAt(p.pal_rm_new, get_pal_pos(self.Boss_PI), _PAL.length, _PAL))
        p.BackgroundColor_scene = p.C_BLK1
      }
      if (gmBool(g.cutscene_timer)) break
      if (!gmBool(pc.ogr)) {
        gofDeps.solid_clip_correction(pc, false) // Make sure not in ground
        pc.hspd = 0 // mod
        g.pc_lock = PC_LOCK_ALL // Lock all
        G.QuestTimer_state = 2
        g.cutscene_timer = 0x80
        g.cutscene_part++
        self.sub_state = self.sub_state_WALK_PC
      }
      break
    }
    case self.sub_state_WALK_PC: {
      // ShadowBoss-9B53
      if (gmBool(g.cutscene_timer)) {
        if (pc.behavior !== pc.behavior_CROUCH) gofDeps.PC_set_behavior(pc, pc.behavior_IDLE)
        break
      }
      let _TARGET_X: number
      if (f.quest_num >= 2) _TARGET_X = self.ARENA_X - (0x02 << 3)
      else _TARGET_X = self.ARENA_X
      g.pc_lock = PC_LOCK_ALL
      pc.WalkTo_active = true
      pc.WalkTo_x = _TARGET_X
      pc.WalkTo_hspd_max = 0x10 // $10 max hspd. Should limit speed to 1 pixel per frame
      if (pc.x === _TARGET_X) {
        pc.WalkTo_active = false
        set_xy(pc, _TARGET_X, pc.y)
        pc.hspd = 0
        gofDeps.PC_set_behavior(pc, pc.behavior_IDLE)
        pc.xScale = 1
        let _X: number
        if (f.quest_num >= 2) _X = self.ARENA_X + (self.ARENA_X - pc.x)
        else _X = pc.x + (0x03 << 3)
        for (const tk of instancesNamed(self.TK_OBJ)) {
          // TK: Triforce Keeper
          set_xy(tk, _X, tk.GROUND_Y - tk.hh_)
          update_draw_xy(tk)
        }
        g.cutscene_timer = 0xd4 + g.timer_b // 2 + (6 * 21) + (4 * 21) = 212($D4)
        g.cutscene_part++
        self.sub_state = self.sub_state_REVEAL_TK
      }
      break
    }
    case self.sub_state_REVEAL_TK: {
      // ShadowBoss-9B98
      const _CUE1 = 0x03
      for (const tk of instancesNamed(self.TK_OBJ)) {
        // 9B9C
        tk.tri_can_draw = 0
        tk.sub_state = 0
        if (inRange(g.cutscene_timer, _CUE1, 0x81)) {
          const _CUE2 = 0x43
          if (g.cutscene_timer < _CUE2 || g.counter1 & 0x1) {
            // Fade-in effect. Need to update these here. Cutscenes update after GO
            if (f.quest_num === 1 && g.cutscene_timer < _CUE2) {
              tk.tri_can_draw = 2 // 2: position over TK head
              tk.tri_xOff = 2 * tk.xScale // centers on keeper body mass looks better
              tk.tri_yOff = -tk.hh // should sit right on top of keeper
            }
            GO_set_sprite(tk, tk.SPR_IDLE)
            tk.sub_state = 1 // will draw TriforceKeeper. See NPC_step_6a()
          }
        }
      }
      // 9B91
      if (g.cutscene_timer >= _CUE1) break
      // 9B74
      const _DURATION = 0x40
      p.Flash_Pal_timer = _DURATION
      p.Flash_Bgr_timer = _DURATION
      p.SpellFlash_PC_timer = _DURATION
      g.timer_b1 = 0x15 // decrements every $15 frames. $15 * $15 = $1B9(441)
      stopMusInst()
      if (f.quest_num === 1) aud_play_sound(get_audio_theme_track(dk_GameClear), -1, false, -1, dk_GameClear)
      for (const tk of instancesNamed(self.TK_OBJ)) {
        tk.tri_can_draw = 0
        tk.sub_state = 0
      }
      g.cutscene_part++
      if (f.quest_num === 1) {
        self.sub_state = self.sub_state_HOLD_TRIFORCE
      } else {
        self.Boss_x = self.ARENA_X
        self.Boss_y = pc.y - 0x10 - 0x8
        self.Boss_Target_y = self.Boss_y - self.Boss_Raise_DIST
        self.Bottle_x = self.Boss_x
        self.Bottle_y = pc.y - 0x16
        p.Flash_Pal_timer = 0
        p.Flash_Bgr_timer = 0
        p.SpellFlash_PC_timer = 0
        p.SpellFlash_GOB_timer = 0
        p.SpellReady_flash_timer = 0
        aud_play_sound(get_audio_theme_track(STR_Cast + STR_Spell))
        g.cutscene_timer = 0x40
        self.sub_state = self.sub_state_FILL_BOTTLE1
      }
      break
    }
    case self.sub_state_HOLD_TRIFORCE: {
      // ShadowBoss-9BA8
      pc.xScale = 1
      // 9BB1
      for (const tk of instancesNamed(self.TK_OBJ)) {
        tk.tri_can_draw = 0
        tk.counter = (tk.counter + 1) & 0xff // for sprite frames
        tk.sub_state = 1
      }
      // MOD
      g.pc_lock = PC_LOCK_ALL
      self.triforce_can_draw = 1
      gofDeps.PC_set_behavior(pc, pc.behavior_HOLD_ITEM4)
      if (gofDeps.pc_is_cucco()) pc.HoldItem_timer = 0xff
      // Triforce fills hp & mp. w/out this, low hp beep will continue for rest of game.
      const _HP_MAX = get_stat_max(STR_Heart)
      const _MP_MAX = get_stat_max(STR_Magic)
      if (_HP_MAX !== f.hp) g.StatRestore_timer_hp = Math.max(0xff, _HP_MAX)
      if (_MP_MAX !== f.mp) g.StatRestore_timer_mp = Math.max(0xff, _MP_MAX)
      if (gmBool(g.timer_b1)) break
      // 9BBA
      for (const ex of instancesNamed('Exit')) {
        if ((ex.exitNum & 0xf0) === g.EXIT_DIR_MID) {
          g.exit_leave = ex
          g.cutscene_part = 0
          g.game_end_state = 1
          G.QuestTimer_state = 0
          self.sub_state = self.sub_state_DONE
          break
        }
      }
      break
    }
    case self.sub_state_DONE: {
      if (f.quest_num === 1) {
        if (g.exit_leave === null) self.sub_state = self.sub_state_WALK_PC
      } else {
        for (const tk of instancesNamed(self.TK_OBJ)) {
          const _X = self.ARENA_X + (0x02 << 3)
          if (tk.x !== _X) {
            const _Y = get_ground_y(_X, viewYC(), 1) - 8
            set_xy(tk, _X, _Y)
          }
        }
      }
      break
    }
    // %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%  2ND QUEST  %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    case self.sub_state_FILL_BOTTLE1: {
      g.pc_lock = PC_LOCK_ALL
      if (self.Boss_y <= self.Boss_Target_y + (self.Boss_Raise_DIST - (self.Boss_Raise_DIST >> 2)))
        self.Boss_can_draw = true
      else self.Boss_can_draw = g.counter1 & 0x1 // fade in
      if (gmBool(g.cutscene_timer)) {
        // Reveal ShadowBoss Corpse flash
        const _IDX = (g.cutscene_timer >> 1) & 0x3
        if (!_IDX) self.Boss_pi = self.Boss_PI
        else self.Boss_pi = p.dg_PI_SEQ.get(4, _IDX) as number // 4: pc spell flash pi's
      } else {
        // Blink slow then increase frequency as corpse slowly raises
        let _TIMING = 0x8
        if (self.Boss_y < self.Boss_Target_y + (self.Boss_Raise_DIST >> 2)) _TIMING = _TIMING >> 1
        blink(_TIMING)
      }
      if (!(g.counter1 & 0xf)) self.Boss_y--
      if (self.Boss_y <= self.Boss_Target_y) {
        self.Boss_y = self.Boss_Target_y
        g.cutscene_timer = 0x20
        self.sub_state = self.sub_state_FILL_BOTTLE2
      }
      break
    }
    case self.sub_state_FILL_BOTTLE2: {
      g.pc_lock = PC_LOCK_ALL
      self.Boss_can_draw = true
      self.Bottle_can_draw = true
      blink(0x4) // Blink fast during bleeding delay
      if (gmBool(g.cutscene_timer)) break
      aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
      g.cutscene_timer = 0x30 // stun flash timer
      self.sub_state = self.sub_state_FILL_BOTTLE3
      break
    }
    case self.sub_state_FILL_BOTTLE3: {
      g.pc_lock = PC_LOCK_ALL
      self.Boss_can_draw = true
      self.Bottle_can_draw = true
      // Damage flash to indicate skin has been cut
      if (gmBool(g.cutscene_timer)) {
        switch ((g.cutscene_timer >> 1) & 0x3) {
          case 0:
            self.Boss_pi = self.Boss_PI
            break
          case 1:
            self.Boss_pi = G.PI_MOB_ORG
            break
          case 2:
            self.Boss_pi = G.PI_MOB_RED
            break
          case 3:
            self.Boss_pi = G.PI_MOB_BLU
            break
        }
      }
      if (gmBool(g.cutscene_timer)) break
      self.Boss_pi = self.Boss_PI
      self.Blood_x = self.Boss_x
      self.Blood_yt = self.Boss_y
      self.Blood_h = 0x2
      self.Blood_yb = self.Blood_yt + self.Blood_h
      self.Blood_yb_MAX = self.Bottle_y + 0x07
      self.sub_state = self.sub_state_FILL_BOTTLE4
      break
    }
    case self.sub_state_FILL_BOTTLE4: {
      g.pc_lock = PC_LOCK_ALL
      self.Blood_can_draw = true
      self.Boss_can_draw = true
      self.Bottle_can_draw = true
      blink(0x2) // Flash during bleeding
      if (gmBool(g.cutscene_timer)) break
      if (!(g.counter1 & 0x7)) self.Blood_yb = Math.min(self.Blood_yb + 0x2, self.Blood_yb_MAX)
      if (self.Blood_yb >= self.Blood_yb_MAX) {
        self.Blood_yb = self.Blood_yb_MAX
        self.BottleLiquid_level++
        f.dm_quests.set(`${STR_Bottle}01${STR_State}`, 1) // Indicates bottle has been filled w/ blood.
        self.sub_state = self.sub_state_FILL_BOTTLE5
      }
      self.Blood_h = self.Blood_yb - self.Blood_yt
      break
    }
    case self.sub_state_FILL_BOTTLE5: {
      g.pc_lock = PC_LOCK_ALL
      self.Blood_can_draw = true
      self.Boss_can_draw = true
      self.Bottle_can_draw = true
      if (gmBool(g.cutscene_timer)) break
      if (!(g.counter1 & 0xf)) self.BottleLiquid_level++
      if (self.BottleLiquid_level >= 6) {
        g.cutscene_timer = 0x20
        self.sub_state = self.sub_state_FILL_BOTTLE6
      }
      break
    }
    case self.sub_state_FILL_BOTTLE6: {
      g.pc_lock = PC_LOCK_ALL
      self.Blood_can_draw = !(g.counter1 & 0x1)
      self.Boss_can_draw = true
      self.Bottle_can_draw = true
      if (gmBool(g.cutscene_timer)) break
      self.Blood_can_draw = false
      self.BottleLiquid_level = 0
      self.Bottle_spr = self.Bottle_SPR2
      self.sub_state = self.sub_state_FILL_BOTTLE7
      break
    }
    case self.sub_state_FILL_BOTTLE7: {
      g.pc_lock = PC_LOCK_ALL
      self.Boss_can_draw = true
      self.Bottle_can_draw = true
      if (gmBool(g.cutscene_timer)) break
      if (!(g.counter1 & 0x7)) self.Boss_vspd = Math.min(self.Boss_vspd + 1, 7)
      self.Boss_y += self.Boss_vspd
      if (self.Boss_y >= viewYB() + 0x30) {
        if (gofDeps.pc_is_cucco()) pc.HoldItem_timer = 0xff
        self.Bottle_spr = self.Bottle_SPR2
        self.Bottle_x = pc.x
        self.Bottle_y = pc.y - 0x17
        gofDeps.PC_set_behavior(pc, pc.behavior_HOLD_ITEM2)
        stopMusInst()
        aud_play_sound(get_audio_theme_track(`${dk_GetItem}01`), -1, false, -1, `${dk_GetItem}01`)
        g.cutscene_timer = 0xc0
        self.sub_state = self.sub_state_HOLD_BOTTLE
      }
      break
    }
    case self.sub_state_HOLD_BOTTLE: {
      self.Bottle_can_draw = true
      if (gmBool(g.cutscene_timer)) break
      const _HP_MAX = get_stat_max(STR_Heart)
      const _MP_MAX = get_stat_max(STR_Magic)
      if (_HP_MAX !== f.hp) g.StatRestore_timer_hp = Math.max(0xff, _HP_MAX)
      if (_MP_MAX !== f.mp) g.StatRestore_timer_mp = Math.max(0xff, _MP_MAX)
      gofDeps.PC_set_behavior(pc, pc.behavior_IDLE)
      g.pc_lock = 0
      pc.hspd = 0
      g.cutscene = 0
      g.cutscene_ctr = 0
      g.view_lock &= ~g.view_lock_boss
      g.view_lock_boss = 0 // need this or view edges act as solids (can't leave rm)
      self.sub_state = self.sub_state_DONE
      break
    }
  }
  if (f.quest_num >= 2 && self.sub_state > self.sub_state_REVEAL_TK) {
    for (const tk of instancesNamed(self.TK_OBJ)) {
      if (self.sub_state < self.sub_state_HOLD_BOTTLE)
        tk.counter = (tk.counter + 1) & 0xff // for sprite frames
      else tk.counter = 0x18 // idle/mouth closed
      if (self.sub_state === self.sub_state_DONE)
        tk.sub_state = 2 // For dialogue
      else tk.sub_state = 1
    }
  }
}

/** `Cutscene_ShadowBoss_2_draw()` */
export function Cutscene_ShadowBoss_2_draw(self: Cutscene_ShadowBoss_2): void {
  const pc = G.pc
  if (f.quest_num === 1) {
    if (gmBool(self.triforce_can_draw))
      draw_sprite_(self.TRIFORCE_SPR, 0, pc.drawX, pc.drawY - pc.hh_ - 8, p.triforce_pi)
    return
  }
  if (gmBool(self.Boss_can_draw))
    gofDeps.draw_pc_skin(self.Boss_x + 4, self.Boss_y, 1, 1, pc.behavior_DAMAGE, false, 1, 1, self.Boss_pi)
  if (gmBool(self.Blood_can_draw)) {
    draw_sprite_('spr_1x1_WHT', 0, self.Blood_x - 1, self.Blood_yt, -1, 1, self.Blood_h - 1, self.Blood_COLOR)
    draw_sprite_('spr_1x1_WHT', 0, self.Blood_x, self.Blood_yt, -1, 1, self.Blood_h, self.Blood_COLOR)
  }
  pal_swap_set(G.PI_MOB_RED)
  if (gmBool(self.BottleLiquid_level)) {
    // draw_sprite_part(BottleLiquid_SPR,0, 0,$10-(level+1), 8,level, x-4, y+8-(level+1))
    pushCmd({
      kind: 'spritePart',
      sprite: self.BottleLiquid_SPR,
      frame: 0,
      left: 0,
      top: 0x10 - (self.BottleLiquid_level + 1),
      width: 8,
      height: self.BottleLiquid_level,
      x: self.Bottle_x - 4,
      y: self.Bottle_y + 0x8 - (self.BottleLiquid_level + 1),
      palIdx: p.palSwapIdx,
      depth: self.depth,
    })
  }
  if (self.Bottle_can_draw) draw_sprite_(self.Bottle_spr, 0, self.Bottle_x, self.Bottle_y)
  pal_swap_reset()
}
