/** Ported from `Cloud_1_init.gml`, `Cloud_1_Step.gml`, `Cloud_1_Draw.gml`, `Cloud_1_end.gml`, `CloudCover1_*.gml`. */
import { dk_BackgroundColor, STR_Data } from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { gmBool } from '../../nes/math8'
import { DsGrid } from '../../runtime/ds'
import { G, g, p } from '../../runtime/world'
import { rectInView, wINw } from '../collision/geometry'
import { GO_init_palidx } from '../game_object/go/palette'
import { GO_depth_init } from '../game_object/go/sprite'
import { sprite_get_height, sprite_get_width } from '../graphics/sprites'
import { sign_ } from '../math'
import { val } from '../other'
import { get_color_brightness } from '../palette/colors'
import { add_pi_permut, pal_swap_reset, pal_swap_set } from '../palette/scenePalette'
import { draw_sprite_ } from '../rooms/draw'
import { cam_yb_max, cam_yt_min, viewW, viewXC, viewXL } from '../view/camera'
import type { NiaoObject } from './NiaoObject'

/** `Cloud_1_init()` */
export function Cloud_1_init(self: NiaoObject): void {
  GO_depth_init(self, g.DEPTH_CLOUD)
  GO_init_palidx(self, G.PI_CLOUD_1) // PI_CLOUD_1==PI_BGR_4(@040921).
  let _SCENE_BGR_COLOR: number = p.C_BLK1
  // ** `global.BackgroundColor_scene` has not been set yet because `p_Room_Start()` has not happened yet.
  if (g.room_type === 'A')
    _SCENE_BGR_COLOR = val(g.dm_rm.get(g.rm_name + dk_BackgroundColor), _SCENE_BGR_COLOR) as number
  if (get_color_brightness(_SCENE_BGR_COLOR) < 0x40) self.palidx_permut = 5 // 5: SMH/BRW
  if (self.dk_spawn !== undefined) {
    const v = g.dm_rm.get(`${self.dk_spawn + STR_Data}01`)
    if (v !== undefined) self.palidx_permut = v as number
  }
  if (gmBool(self.palidx_permut)) {
    let _pi = self.palidx_def
    switch (self.palidx_permut) {
      case 1:
        _pi = add_pi_permut(_pi, 'WBRGYKMC', 'cloud permut WBRGYKMC')
        break
      case 2:
        _pi = add_pi_permut(_pi, 'RWBGMYKC', 'cloud permut RWBGMYKC')
        break
      case 3:
        _pi = add_pi_permut(_pi, 'RBWGMKYC', 'cloud permut RBWGMKYC')
        break
      case 4:
        _pi = add_pi_permut(_pi, 'BWRGKYMC', 'cloud permut BWRGKYMC')
        break
      case 5:
        _pi = add_pi_permut(_pi, 'BRWGKMYC', 'cloud permut BRWGKMYC')
        break
    }
    GO_init_palidx(self, _pi)
  }
  self.scr_update = Cloud_1_Step as never
  self.scr_draw = Cloud_1_Draw as never
  self.scr_inst_end = Cloud_1_end as never
  const _val = val(g.dm_rm.get(`${self.dk_spawn}_xy`), 0x0000) as number
  self.xl = ((_val >> 0) & 0xff) << 3
  self.yt = ((_val >> 8) & 0xff) << 3
  self.DRAW_XOFF += self.xl
  self.DRAW_YOFF += self.yt
  self.DIST1 = 0x02 << 8 // Dist to travel from start x before reseting to start x.
  self.DIST2 = 0x01 << 8 // For v1. Vertical dist between yt of each set
  self.DIST3 = 0x03 << 3 // For v2. Vertical dist between each set
  self.can_move = !!g.mod_CLOUD_MOVEMENT
  self.hspd = -1
  // num of same cloud gets drawn, each 2 pages apart
  self.COPY_COUNT = g.rm_pages_x + (g.rm_pages_x & 0x1)
  // Lower the value, the faster.
  const _DELAY_MOVE_1 = 2 // 1
  const _DELAY_MOVE_2 = 3 // 2
  const _DELAY_MOVE_3 = 4 // 4, 3
  // ----------------------------------------------------------
  self.SPR_1A = 'spr_cloud_1a' // short
  self.SPR_2A = 'spr_cloud_2a' // long
  self.CLOUD_COUNT = 6
  const dg = new DsGrid<number | string>(self.CLOUD_COUNT, 9, 0)
  self.dg_cloud = dg
  // x (left edge), y (top edge), timer reset(speed), timer, sprite, width, height, start x, start y
  const rows: [number, number, number, string][] = [
    [0x00 << 3, 0x00 << 3, _DELAY_MOVE_2, self.SPR_2A],
    [0x08 << 3, 0x06 << 3, _DELAY_MOVE_3, self.SPR_2A],
    [0x0c << 3, 0x0a << 3, _DELAY_MOVE_2, self.SPR_1A],
    [0x1c << 3, 0x08 << 3, _DELAY_MOVE_1, self.SPR_2A],
    [0x28 << 3, 0x04 << 3, _DELAY_MOVE_3, self.SPR_1A],
    [0x38 << 3, 0x0c << 3, _DELAY_MOVE_1, self.SPR_2A],
  ]
  rows.forEach(([x, y, delay, spr], _a) => {
    dg.set(_a, 0, x)
    dg.set(_a, 1, y)
    dg.set(_a, 2, delay) // timer reset(speed)
    dg.set(_a, 3, delay) // timer
    dg.set(_a, 4, spr) // sprite
    dg.set(_a, 5, sprite_get_width(spr)) // cloud width
    dg.set(_a, 6, sprite_get_height(spr)) // cloud height
    dg.set(_a, 7, x) // start x
    dg.set(_a, 8, y) // start y
  })
  self.CloudArea_W = self.DIST1
  self.CloudArea_H = 0
  self.CloudArea_XL = 0
  self.CloudArea_XR = self.CloudArea_XL + self.CloudArea_W
  self.CloudArea_YT = g.rm_h
  self.CloudArea_YB = 0
  for (let _i = 0; _i < self.CLOUD_COUNT; _i++) {
    // each cloud
    const y = dg.get(_i, 1) as number
    const h = dg.get(_i, 6) as number
    if (self.CloudArea_YT > y) self.CloudArea_YT = y
    if (self.CloudArea_YB < y + h) self.CloudArea_YB = y + h
  }
  self.CloudArea_H = self.CloudArea_YB - self.CloudArea_YT
  self.CloudArea_YT = ((g.rm_pages_y - 1) << 8) + (self.CloudArea_YT & 0xff)
  self.CloudArea_YB = self.CloudArea_YT + self.CloudArea_H
}

/** `Cloud_1_step()` */
export function Cloud_1_Step(self: NiaoObject): void {
  if (!self.can_move) return
  if (self.hspd === 0) return
  const dg = self.dg_cloud as DsGrid<number | string>
  for (let _i = 0; _i < self.CLOUD_COUNT; _i++) {
    let t = (dg.get(_i, 3) as number) - 1 // 3: timer
    if (t) {
      dg.set(_i, 3, t)
      continue
    }
    t = dg.get(_i, 2) as number // 2: timer reset
    dg.set(_i, 3, t)
    let x = (dg.get(_i, 0) as number) + self.hspd
    // if far enough from starting x
    if (Math.abs(x - (dg.get(_i, 7) as number)) >= self.DIST1) x += -Math.sign(self.hspd) * self.DIST1
    dg.set(_i, 0, x)
  }
}

/** `Cloud_1_Draw()` */
export function Cloud_1_Draw(self: NiaoObject): void {
  const dg = self.dg_cloud as DsGrid<number | string>
  switch (self.ver) {
    case 1: {
      const _COPY_COUNT = self.COPY_COUNT + 1
      const _PAGES_Y = g.rm_pages_y
      pal_swap_set(self.palidx)
      for (let _i = 0; _i < _PAGES_Y; _i++) {
        // each vertical map page
        for (let _j = 0; _j < self.CLOUD_COUNT; _j++) {
          // each cloud
          const _copy_count = _COPY_COUNT + (_i & 1)
          for (let _k = 0; _k < _copy_count; _k++) {
            // each copy
            let _x = (dg.get(_j, 0) as number) + _k * self.DIST1 // x left
            let _y = (dg.get(_j, 1) as number) + (_i << 8)
            _x -= self.DIST1
            // To mix it up; clouds in odd vert pages will swap odd and even horz pages
            if (_i & 1) _x -= self.DIST1 >> 1
            const w = dg.get(_j, 5) as number
            const h = dg.get(_j, 6) as number
            if (rectInView(_x, _y, w, h)) {
              _x += w >> 1 // draw_x
              _x += self.DRAW_XOFF
              _y += h >> 1 // draw_y
              _y += self.DRAW_YOFF
              draw_sprite_(dg.get(_j, 4) as string, 0, _x, _y)
              continue
            }
            // Skip rest of copies bc they would NOT be in view.
            if (_x > viewXC()) break
          }
        }
      }
      pal_swap_reset()
      break
    }
    case 2: {
      const _COPY_COUNT = self.COPY_COUNT + 1
      const _DIST1 = self.CloudArea_H + self.DIST3
      let _COUNT1 = Math.trunc(self.CloudArea_YB / _DIST1)
      _COUNT1++
      const _YOFF = -(self.CloudArea_YT & 0xff)
      pal_swap_set(self.palidx)
      for (let _i = 0; _i < _COUNT1; _i++) {
        // each template set, vertical
        const _y_base = self.CloudArea_YT - _i * _DIST1 // the top of this set
        for (let _j = 0; _j < self.CLOUD_COUNT; _j++) {
          // each cloud template
          let _y = _y_base + ((dg.get(_j, 1) as number) + _YOFF)
          const _copy_count = _COPY_COUNT + (_i & 1)
          for (let _k = 0; _k < _copy_count; _k++) {
            // each copy, horizontal
            let _x = (dg.get(_j, 0) as number) + _k * self.DIST1 // x left
            _x -= self.DIST1
            if (_i & 1) _x -= self.DIST1 >> 1
            const w = dg.get(_j, 5) as number
            const h = dg.get(_j, 6) as number
            if (rectInView(_x, _y, w, h)) {
              _x += w >> 1 // draw_x
              _y += h >> 1 // draw_y
              _y += self.DRAW_YOFF
              draw_sprite_(dg.get(_j, 4) as string, 0, _x, _y)
              continue
            }
            if (_x > viewXC()) break
          }
        }
      }
      pal_swap_reset()
      break
    }
  }
}

/** `Cloud_1_end()` — grid cleanup. */
export function Cloud_1_end(self: NiaoObject): void {
  self.dg_cloud = undefined
}

/** `CloudCover1_init()` */
export function CloudCover1_init(self: NiaoObject): void {
  self.scr_update = CloudCover1_update as never
  self.scr_draw = CloudCover1_draw as never
  self.scr_inst_end = CloudCover1_end as never
  let _depth: number = g.DEPTH_CLOUD
  if (self.dk_spawn !== undefined) {
    let _i = 1
    self.palidx_permut = val(
      g.dm_rm.get(self.dk_spawn + STR_Data + hexStr(_i++)),
      self.palidx_permut,
    ) as number
    _depth = val(g.dm_rm.get(self.dk_spawn + STR_Data + hexStr(_i++)), _depth) as number
    self.DRAW_YOFF += val(g.dm_rm.get(self.dk_spawn + STR_Data + hexStr(_i++))) as number
  }
  GO_init_palidx(self, G.PI_CLOUD_1, self.palidx_permut)
  GO_depth_init(self, _depth)
  self.CloudSpr1 = g.CloudLarge1_SPR1
  self.CloudSpr1_W = sprite_get_width(self.CloudSpr1)
  self.CloudSpr1_W_ = self.CloudSpr1_W >> 1
  self.CloudSpr1_CLMS = self.CloudSpr1_W >> 3
  self.CloudSpr1_H = sprite_get_height(self.CloudSpr1)
  self.CloudSpr1_H_ = self.CloudSpr1_H >> 1
  self.CloudSpr1_ROWS = self.CloudSpr1_H >> 3
  self.CloudSpr1_COUNT_X = Math.trunc(g.rm_w / self.CloudSpr1_W) + 2
  self.Clouds_DIR = -1
  let _SPEED = 0x20
  let layers = 0
  switch (self.ver) {
    case 1:
      layers = 3
      _SPEED = 0x18
      break
    case 2:
      layers = 3
      _SPEED = 0x20
      break
  }
  const dg = new DsGrid<number>(layers, 8, 0)
  self.dg_CloudLayers = dg
  self.CloudLayers_COUNT = layers
  const _XOFF = self.xl
  let _YOFF = self.yt
  if (g.view_lock_rm & 0xc) _YOFF -= g.rm_row0 << 3
  let _X1 = self.CloudSpr1_W_ * self.Clouds_DIR // sprite center x
  _X1 += _XOFF // add xoffset(xl)
  const _a = 0x09
  let _Y1 = cam_yt_min() + _a
  if (self.ver === 2) _Y1 = cam_yb_max() - _a
  let _y = _Y1 // sprite center y
  _y += _YOFF // add yoffset(yt)
  const _DISTX = 5
  const _DISTY = self.CloudSpr1_H_ - 2
  let _disty = _DISTY
  for (let _i = 0; _i < self.CloudLayers_COUNT; _i++) {
    dg.set(_i, 0, _X1 + _DISTX * _i)
    dg.set(_i, 1, _y)
    dg.set(_i, 2, dg.get(_i, 0) as number)
    dg.set(_i, 3, dg.get(_i, 1) as number)
    dg.set(_i, 4, self.Clouds_DIR)
    dg.set(_i, 5, Math.max(_SPEED - (_i << 3), 0x01))
    dg.set(_i, 6, 0)
    dg.set(_i, 7, self.palidx_def)
    _y += _disty * sign_(self.ver === 1)
    _disty -= (_disty >> 1) - 4
  }
}

/** `CloudCover1_update()` */
export function CloudCover1_update(self: NiaoObject): void {
  const dg = self.dg_CloudLayers as DsGrid<number>
  for (let _i = 0; _i < self.CloudLayers_COUNT; _i++) {
    const _x0 = dg.get(_i, 0) as number
    let _x = dg.get(_i, 2) as number
    const _dir = dg.get(_i, 4) as number
    const _speed0 = dg.get(_i, 5) as number
    let _speed = dg.get(_i, 6) as number
    _speed += _speed0
    _x += (_speed >> 4) * _dir
    _speed &= 0x0f
    const _dist = Math.abs(_x0 - _x) % self.CloudSpr1_W
    _x = _x0 + _dist * _dir
    dg.set(_i, 2, _x)
    dg.set(_i, 6, _speed)
  }
}

/** `CloudCover1_draw()` */
export function CloudCover1_draw(self: NiaoObject): void {
  const dg = self.dg_CloudLayers as DsGrid<number>
  for (let _i = self.CloudLayers_COUNT - 1; _i >= 0; _i--) {
    pal_swap_set(dg.get(_i, 7) as number)
    const _x0 = dg.get(_i, 2) as number
    const _y = (dg.get(_i, 3) as number) + self.DRAW_YOFF
    for (let _j = 0; _j < self.CloudSpr1_COUNT_X; _j++) {
      const _x = _x0 + self.CloudSpr1_W * _j
      if (wINw(_x - self.CloudSpr1_W_, self.CloudSpr1_W, viewXL(), viewW()))
        draw_sprite_(self.CloudSpr1, 0, _x, _y)
    }
  }
  pal_swap_reset()
}

/** `CloudCover1_end()` */
export function CloudCover1_end(self: NiaoObject): void {
  self.dg_CloudLayers = undefined
}
