/**
 * Boggnipp (ZALiA object `Boggnipp01`, parent `Enemy`; the water-dwelling charger that leaps at the player).
 * `Boggnipp_init1/init2/update/udp.gml`.
 */
import { CS_BD1, DEPTH_BG1, TID_SOLID1 } from '@z2/data'
import { abs8b, byteToInt, gmBool } from '../../../../../../nes/math8'
import { NOONE } from '../../../../../../runtime/instance'
import { g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { wINwAll } from '../../../../../collision/geometry'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { collide_solid_grid } from '../../../../../collision/solid'
import { sign_ } from '../../../../../math/index'
import { Enemy, Platform } from '../../../../classes'
import { dir_to_pc_ } from '../../../../go/misc'
import { set_xlyt, updateX, updateY } from '../../../../go/movement'
import { GO_depth_init, GO_sprite_init } from '../../../../go/sprite'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GameObjectB_init, GOB_udp_1, GOB_update_2 } from '../../../GameObjectB'
import { firstNamed, randoSpawnDatakey } from '../ache/_shared'

export class Boggnipp01 extends Enemy {
  readonly objectName = 'Boggnipp01' as const
  readonly sub_state_IDLE = 1
  readonly sub_state_CHARGE = 2
  readonly sub_state_JUMP = 3
  readonly sub_state_RESET = 4
  readonly sub_state_LAND = 5
  sub_state = 1
  HSPD_PACE = 0x0c
  HSPD_CHARGE = 0x20
  VSPD_JUMP = 0xea // Jump speed (initial velocity)
  ATTACK_DIST = 0x50
  AGRO_DIST = 0x50 + 0x80
  RESET_DIST = 0x50 + 0x20
  YT_IDLE = -0x05 // offset on spawn_y
  RM_PAD = 0x10
}

/** `Boggnipp_init1()` */
export function Boggnipp_init1(self: Boggnipp01): void {
  GameObjectB_init(self)
  self.dl_sprites?.add('spr_Boggnipp_1a', 'spr_Boggnipp_1b')
  GO_sprite_init(self, self.dl_sprites?.get(0) as string)
  self.sub_state = self.sub_state_IDLE
  self.HSPD_PACE = 0x0c
  self.HSPD_CHARGE = 0x20
  self.VSPD_JUMP = 0xea
  self.ATTACK_DIST = 0x50
  self.AGRO_DIST = self.ATTACK_DIST + 0x80
  self.RESET_DIST = self.ATTACK_DIST + 0x20
  self.YT_IDLE = -0x05 // offset on spawn_y
  self.counter = 0x00
  self.RM_PAD = 0x10
}

/** `Boggnipp_init2()` */
export function Boggnipp_init2(self: Boggnipp01): void {
  randoSpawnDatakey(self.dk_spawn) // computed in ZALiA but unused afterwards
  GO_depth_init(self, DEPTH_BG1)
  self.YT_IDLE = self.spawn_yt + self.YT_IDLE
  set_xlyt(self, self.xl, self.YT_IDLE)
  self.hspd_impel = dir_to_pc_(self)
  self.hspd = (self.HSPD_PACE * self.hspd_impel) & 0xff
  self.hspd_dir = sign_(self.hspd < 0x80)
}

/** Accelerate `hspd` one step towards `target * hspd_impel` (the repeated block in Boggnipp_update). */
function approachHspd(self: Boggnipp01, target: number): void {
  if (self.hspd !== ((target * self.hspd_impel) & 0xff)) {
    self.hspd += sign_(byteToInt(self.hspd) < target * self.hspd_impel)
    self.hspd &= 0xff
    self.hspd_dir = sign_(self.hspd < 0x80)
  }
}

/** `Boggnipp_update()` */
export function Boggnipp_update(self: Boggnipp01): void {
  const P = pc()
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return
  }
  GO_update_cs(self)
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  const _C1 =
    !wINwAll(self.xl - self.RM_PAD, self.ww + (self.RM_PAD << 1), 0, g.rm_w) &&
    self.hspd_impel === sign_(self.x > g.rm_w_)
  let _C2 = false
  if (!_C1) {
    _C2 =
      !!(collide_solid_grid(self.csRgt1X, self.csRgt1Y) & TID_SOLID1) ||
      !!(collide_solid_grid(self.csRgt2X, self.csRgt2Y) & TID_SOLID1) ||
      !!(collide_solid_grid(self.csLft1X, self.csLft1Y) & TID_SOLID1) ||
      !!(collide_solid_grid(self.csLft2X, self.csLft2Y) & TID_SOLID1)
  }
  if (_C1 || _C2) {
    self.hspd_impel = -self.hspd_impel
    self.hspd = (Math.min(abs8b(self.hspd), self.HSPD_PACE) * self.hspd_impel) & 0xff
    self.counter = 0
  }
  const _YT_PREV = self.yt
  updateX(self)
  updateY(self)
  self.facing_dir = self.hspd_impel
  switch (self.sub_state) {
    case self.sub_state_IDLE: {
      self.counter++
      if (!(self.counter & 0xff)) self.hspd_impel = -self.hspd_impel
      approachHspd(self, self.HSPD_PACE)
      const _DIST = Math.abs(self.x - P.x)
      if (_DIST <= self.AGRO_DIST && Math.abs(self.y - P.y) <= P.hh - self.hh_ + 0x10) {
        self.counter = 0
        self.hspd_impel = dir_to_pc_(self)
        self.sub_state = self.sub_state_CHARGE
      }
      break
    }
    case self.sub_state_CHARGE: {
      approachHspd(self, self.HSPD_CHARGE)
      let _DIST = self.ATTACK_DIST
      const raft = firstNamed('PlatformRaft')
      if (
        (raft && sign_(raft.hspd < 0x80) === self.hspd_dir) ||
        (gmBool(P.hspd) && sign_(P.hspd < 0x80) === self.hspd_dir)
      ) {
        _DIST = self.ATTACK_DIST >> 1
      }
      if (Math.abs(self.x - P.x) <= _DIST) {
        if (abs8b(self.hspd) >= self.HSPD_CHARGE >> 1) {
          set_xlyt(self, self.xl, self.YT_IDLE - 1)
          self.vspd = self.VSPD_JUMP
          self.sub_state = self.sub_state_JUMP
        } else {
          // Get better speed before attacking
          self.sub_state = self.sub_state_RESET
        }
      }
      break
    }
    case self.sub_state_JUMP: {
      if (self.yt !== self.YT_IDLE) {
        if (sign_(self.YT_IDLE - _YT_PREV) !== sign_(self.YT_IDLE - self.yt)) {
          set_xlyt(self, self.xl, self.YT_IDLE)
          self.vspd = 0
          self.sub_state = self.sub_state_RESET
        } else {
          self.vspd += sign_(self.yt < self.YT_IDLE)
          self.vspd &= 0xff
        }
      }
      break
    }
    case self.sub_state_RESET: {
      // need to get far enough away before charging again
      approachHspd(self, self.HSPD_CHARGE)
      if (Math.abs(self.x - P.x) >= self.RESET_DIST) {
        self.hspd_impel = dir_to_pc_(self)
        self.sub_state = self.sub_state_CHARGE
      }
      break
    }
  }
  // So that the platforms don't change momentum
  const b = self.cs_btm_inst
  if (b && b.exists && b instanceof Platform) self.cs_btm_inst = NOONE
}

/** `Boggnipp_udp()` */
export function Boggnipp_udp(self: Boggnipp01): void {
  self.can_draw_self = true
  const _VAL = 0x08 << +(self.sub_state === self.sub_state_IDLE)
  GOB_udp_1(self, _VAL)
}

registerObject('Boggnipp01', Boggnipp01)
registerScripts({ Boggnipp_init1, Boggnipp_init2, Boggnipp_update, Boggnipp_udp })
