export const STEP_MS = 1000 / 60
export const MAX_STEPS_PER_FRAME = 3

/** Fixed-step accumulator: how many 60 Hz steps to run this frame (capped; backlog dropped after a stall). */
export function stepsFor(accumulatorMs: number): { steps: number; rest: number } {
  let steps = Math.floor(accumulatorMs / STEP_MS)
  let rest = accumulatorMs - steps * STEP_MS
  if (steps > MAX_STEPS_PER_FRAME) {
    steps = MAX_STEPS_PER_FRAME
    rest = 0
  }
  return { steps, rest }
}
