/** cs: Colliding Sides. Sensor points around the object tested against solid tiles / solid instances. */
import { CS_BTM, CS_LFT, CS_RGT, CS_TOP, TID_ONEWY1, TID_SOLID1 } from '@z2/data'
import { instanceExists, NOONE } from '../../runtime/instance'
import { dir8b_, gmBool, sign_ } from '../math'
import type { GoBody, PcBody } from './body'
import { env, viewXL, viewXR, viewYB, viewYT } from './env'
import { point_in_rect } from './geometry'
import { collide_solid_inst, inst_collide_solid_type } from './solid'

function isPc(self: GoBody): self is PcBody {
  return self === (env.pc() as GoBody)
}

/** `setCSOffsets()` — load the 16 sensor offsets for `cs_off_idx` from `g.dg_CS_OFF`. */
export function setCSOffsets(self: GoBody): void {
  const t = env.game().dg_CS_OFF
  const v = (col: number) => t.get(self.cs_off_idx, col) ?? 0
  self.csTop1_xoff = v(0)
  self.csTop1_yoff = v(1)
  self.csTop2_xoff = v(2)
  self.csTop2_yoff = v(3)
  self.csBtm1_xoff = v(4)
  self.csBtm1_yoff = v(5)
  self.csBtm2_xoff = v(6)
  self.csBtm2_yoff = v(7)
  self.csRgt1_xoff = v(8)
  self.csRgt1_yoff = v(9)
  self.csRgt2_xoff = v(10)
  self.csRgt2_yoff = v(11)
  self.csLft1_xoff = v(12)
  self.csLft1_yoff = v(13)
  self.csLft2_xoff = v(14)
  self.csLft2_yoff = v(15)
  if (isPc(self)) {
    // Same values for fairy.
    self.cp1_xoff = 7
    if (env.fn.pc_is_cucco()) self.cp1_yoff = self.hh
    else if (env.fn.pc_is_fairy())
      self.cp1_yoff = 23 // MOD
    else self.cp1_yoff = self.hh
    // Top center x collision point
    self.cp2_xoff = self.cp1_xoff
    self.cp2_yoff = 0
  }
}

/** `update_cs_points_1()` */
export function update_cs_points_1(self: GoBody): void {
  self.csTop1X = self.xl + self.csTop1_xoff
  self.csTop1Y = self.yt + self.csTop1_yoff
  self.csTop2X = self.xl + self.csTop2_xoff
  self.csTop2Y = self.yt + self.csTop2_yoff
  self.csBtm1X = self.xl + self.csBtm1_xoff
  self.csBtm1Y = self.yt + self.csBtm1_yoff
  self.csBtm2X = self.xl + self.csBtm2_xoff
  self.csBtm2Y = self.yt + self.csBtm2_yoff
  self.csRgt1X = self.xl + self.csRgt1_xoff
  self.csRgt1Y = self.yt + self.csRgt1_yoff
  self.csRgt2X = self.xl + self.csRgt2_xoff
  self.csRgt2Y = self.yt + self.csRgt2_yoff
  self.csLft1X = self.xl + self.csLft1_xoff
  self.csLft1Y = self.yt + self.csLft1_yoff
  self.csLft2X = self.xl + self.csLft2_xoff
  self.csLft2Y = self.yt + self.csLft2_yoff
  if (isPc(self)) {
    // cp: Colliding Point
    self.cp1X = self.xl + self.cp1_xoff
    self.cp1Y = self.yt + self.cp1_yoff
    self.cp2X = self.xl + self.cp2_xoff
    self.cp2Y = self.yt + self.cp2_yoff
  }
}

/** `updateCSPoints()` */
export function updateCSPoints(self: GoBody): void {
  self.canDrawCSHB = true
  setCSOffsets(self)
  update_cs_points_1(self)
}

/** `csTopColliding()` — 0 or a combo of TID bits (0..3). */
export const csTopColliding = (s: GoBody): number =>
  inst_collide_solid_type(s, s.csTop1X, s.csTop1Y) | inst_collide_solid_type(s, s.csTop2X, s.csTop2Y)
export const csRgtColliding = (s: GoBody): number =>
  inst_collide_solid_type(s, s.csRgt1X, s.csRgt1Y) | inst_collide_solid_type(s, s.csRgt2X, s.csRgt2Y)
export const csLftColliding = (s: GoBody): number =>
  inst_collide_solid_type(s, s.csLft1X, s.csLft1Y) | inst_collide_solid_type(s, s.csLft2X, s.csLft2Y)
/** `csBtmColliding()` — x clamped to the room so a GO can't fall past room bounds. */
export function csBtmColliding(s: GoBody): number {
  const rw = env.roomWidth() - 1
  const cl = (x: number) => Math.max(0, Math.min(x, rw))
  return (
    inst_collide_solid_type(s, cl(s.csBtm1X), s.csBtm1Y) |
    inst_collide_solid_type(s, cl(s.csBtm2X), s.csBtm2Y)
  )
}

/** `csBtm_qual_oneway(inst, dist in tile)` — moving down, and in the tile's upper half or fast enough. */
export function csBtm_qual_oneway(inst: GoBody, dist: number): boolean {
  if (inst.vspd & 0x80) return false // moving upward
  const DIST = dist & 0x7 // 0-7. How far into tile.
  if (DIST < 4) return true
  if (inst.uses_vspd_sub) {
    if (DIST - 1 <= inst.vspd >> 4) return true // faster than 8 would mean vspd > $7F
  } else if (DIST - 1 <= inst.vspd) return true // obj uses vspd as 'pixels per frame'
  return false
}

/** `update_cs_btm_inst()` — solid instance under the bottom sensors (not self; one-way only if qualified). */
export function update_cs_btm_inst(self: GoBody): void {
  let inst = collide_solid_inst(self.csBtm1X, self.csBtm1Y)
  if (!inst) inst = collide_solid_inst(self.csBtm2X, self.csBtm2Y)
  if ((inst as unknown) === self) inst = NOONE
  if (inst && inst.solid_type === TID_ONEWY1) {
    if (self.solid_type === TID_ONEWY1 || !csBtm_qual_oneway(self, (self.csBtm1Y - (inst.yt & 0x7)) & 0x7))
      inst = NOONE
  }
  self.cs_btm_inst = inst
}

/** `csBtmColliding_1a()` — solid type under the feet, honouring one-way platforms/instances. */
export function csBtmColliding_1a(self: GoBody): number {
  let VAL = 0
  update_cs_btm_inst(self)
  const inst = self.cs_btm_inst
  if (instanceExists(inst) && inst.solid_type) {
    VAL = inst.solid_type
    if (VAL & TID_SOLID1) return VAL // Full Solid trumps One-way
    if (VAL & TID_ONEWY1 && csBtm_qual_oneway(self, (self.csBtm1Y - (inst.yt & 0x7)) & 0x7)) return VAL
  }
  if (VAL === 0) VAL = csBtmColliding(self)
  if (VAL === 0) return 0
  if (VAL & TID_SOLID1) return VAL
  if (VAL & TID_ONEWY1 && csBtm_qual_oneway(self, self.csBtm1Y & 0x7)) return VAL
  return 0
}

/** `GO_update_cs_1()` — top, bottom, and the side the object moves toward. */
export function GO_update_cs_1(self: GoBody): void {
  const IS_PC = isPc(self)
  let HSPD_DIR = -sign_(self.hspd & 0x80) // +1 right, -1 left
  if (IS_PC) HSPD_DIR = self.hspd_dir
  self.cs &= 0xf0
  if (IS_PC) self.cs = 0x00
  if (csTopColliding(self) & TID_SOLID1) self.cs |= CS_TOP
  if (csBtmColliding_1a(self)) self.cs |= CS_BTM
  if (gmBool(HSPD_DIR)) {
    if (csRgtColliding(self) & TID_SOLID1) self.cs |= CS_RGT
  } else if (csLftColliding(self) & TID_SOLID1) self.cs |= CS_LFT
}

/** `GO_update_cs()` — full sensor update plus the PC-only extras (mid-side sensors, cam lock, elevator, Ganon). */
export function GO_update_cs(self: GoBody): void {
  updateCSPoints(self)
  GO_update_cs_1(self)
  if (!isPc(self)) return
  const pc = self
  const g = env.game()
  if (!(pc.cs & 0x3) && !env.fn.pc_is_cucco()) {
    // TODO(ZALiA): Do this for all GO?
    if (gmBool(pc.hspd_dir)) {
      const VAL =
        inst_collide_solid_type(pc, pc.csRgt1X, pc.csRgt1Y + 0x08) |
        inst_collide_solid_type(pc, pc.csRgt2X, pc.csRgt1Y + 0x10)
      if (VAL & TID_SOLID1) pc.cs |= CS_RGT
    } else {
      const VAL =
        inst_collide_solid_type(pc, pc.csLft1X, pc.csLft1Y + 0x08) |
        inst_collide_solid_type(pc, pc.csLft2X, pc.csLft1Y + 0x10)
      if (VAL & TID_SOLID1) pc.cs |= CS_LFT
    }
  }
  if (g.view_lock_boss && !g.EnterRoom_control_timer) {
    let cs = 0
    if (pc.csRgt1X >= viewXR()) cs |= CS_RGT
    if (pc.csLft1X < viewXL()) cs |= CS_LFT
    if (pc.csBtm1Y >= viewYB()) cs |= CS_BTM
    if (pc.csTop1Y < viewYT()) cs |= CS_TOP
    cs &= g.view_lock_boss // cam_lock: 0, bits 1,2,4,8
    if (cs) {
      // When cam is locked, cs treats the edges of screen as solid
      if ((cs & (CS_RGT | CS_LFT)) === dir8b_(pc.hspd_dir)) pc.cs |= cs & (CS_RGT | CS_LFT)
      if (cs & CS_TOP && pc.vspd & 0x80) pc.cs |= CS_TOP
      // if (cs & CS_BTM) // Don't know what should happen for bottom
    }
  }
  // So that player cannot get on top or under a rm by elevator.
  if ((pc.yt < 0 || pc.yb > g.rm_h) && instanceExists(pc.colliding_elevator)) {
    const Y1 = g.rm_h - 1
    const cl = (v: number) => Math.max(0, Math.min(v, Y1))
    if (gmBool(pc.hspd_dir)) {
      pc.csRgt1Y = cl(pc.csRgt1Y)
      pc.csRgt2Y = cl(pc.csRgt2Y)
      if (csRgtColliding(pc) & TID_SOLID1) pc.cs |= CS_RGT
    } else {
      pc.csLft1Y = cl(pc.csLft1Y)
      pc.csLft2Y = cl(pc.csLft2Y)
      if (csLftColliding(pc) & TID_SOLID1) pc.cs |= CS_LFT
    }
    updateCSPoints(pc)
  }
  const ganon = env.ganon1()
  if (ganon && !ganon.pc_is_inside) {
    const GX = ganon.xl
    const GY = ganon.yt
    const GW = ganon.ww
    const GH = ganon.hh
    const inG = (x: number, y: number) => point_in_rect(x, y, GX, GY, GW, GH)
    if (gmBool(pc.hspd_dir)) {
      if (inG(pc.csRgt1X, pc.csRgt1Y) || inG(pc.csRgt2X, pc.csRgt2Y)) pc.cs |= CS_RGT
    } else if (inG(pc.csLft1X, pc.csLft1Y) || inG(pc.csLft2X, pc.csLft2Y)) pc.cs |= CS_LFT
    if (inG(pc.csTop1X, pc.csTop1Y) || inG(pc.csTop2X, pc.csTop2Y)) pc.cs |= CS_TOP
    if (pc.csBtm1Y <= GY + 2) {
      if (inG(pc.csBtm1X, pc.csBtm1Y) || inG(pc.csBtm2X, pc.csBtm2Y)) pc.cs |= CS_BTM
    }
  }
}

/** `GOB_update_cs_2a()` — also check the side NOT moved toward (Moa2 spawning a Flame in a solid). */
export function GOB_update_cs_2a(self: GoBody): void {
  GO_update_cs(self)
  if (self.hspd & 0x80) {
    if (csRgtColliding(self) & TID_SOLID1) self.cs |= CS_RGT
  } else if (csLftColliding(self) & TID_SOLID1) self.cs |= CS_LFT
}
