/**
 * `Exit` object — ZALiA IDE folder `exit`: `Exit_Create`, `Exit_construct`, `Exit_Draw`, `is_exit_type`,
 * `get_exit_rm_name`. An Exit is an invisible GameObject whose body box is scaled to the exit's tile rect.
 */
import {
  DEPTH_NIAO,
  dk_FastTravel,
  dk_MidoChurch,
  REEN_DEFAULT,
  RmName_LEN,
  STR_Door,
  STR_Exit,
  STR_Exit_x,
  STR_Exit_y,
  STR_goto_reen,
  STR_Height,
  STR_ID,
  STR_Idx,
  STR_Name,
  STR_Open,
  STR_Palette,
  STR_Type,
  STR_Width,
} from '@z2/data'
import { gmBool } from '../../nes/math8'
import { NOONE, type Ref } from '../../runtime/instance'
import { f, G, g, p, world } from '../../runtime/world'
import { GameObject } from '../game_object/classes'
import { update_draw_xy } from '../game_object/go/movement'
import { GO_init_palidx } from '../game_object/go/palette'
import { GO_depth_init, GO_sprite_init } from '../game_object/go/sprite'
import { registerObject } from '../game_object/registry'
import { sprite_get_xoffset, sprite_get_yoffset } from '../graphics/sprites'
import { str_hex, strR } from '../other/index'
import { registerObjectClass } from '../other/registry'
import { draw_rect_, draw_sprite_ } from '../rooms/draw'

export class Exit extends GameObject {
  readonly objectName = 'Exit' as const
  image_xscale = 1
  image_yscale = 1
  doorway_spr: string | 0 = 0
  doorway_spr_xoff = 0
  doorway_spr_yoff = 0
  side = 0 // 0: inside room, 1: right, 2: left, 4: down, 8: up
  open: boolean | number = true
  exitName: string | undefined = undefined
  exitNum = 0
  exit_type = 0
  page_x = 0
  page_y = 0
  goToExitName: string | 0 = 0
  goToRoom: string | 0 = 0
  goToExitNum = 0
  is_draw_open_exit = false

  constructor() {
    super()
    Exit_Create(this)
  }
}
registerObject('Exit', Exit)
registerObjectClass('Exit', Exit)

/** `Exit_Create()` */
export function Exit_Create(self: Exit): void {
  // init_vars_draw_1a / coll_1a / go_1a / go_4a: field initializers on GameObject
  GO_depth_init(self, DEPTH_NIAO) // sets depth & depth_def
  GO_sprite_init(self, 'spr_Placement_01x01')
  GO_init_palidx(self, G.PI_BGR1)
  self.doorway_spr = 0
  self.doorway_spr_xoff = 0
  self.doorway_spr_yoff = 0
  self.side = 0
  self.open = true
  self.exitName = undefined
  self.exitNum = 0
  self.exit_type = 0
  self.page_x = 0
  self.page_y = 0
  self.goToExitName = 0
  self.goToRoom = 0
  self.goToExitNum = 0
  self.is_draw_open_exit = false
}

/** `is_exit_type(int Exit exit_type, int g EXIT_TYPE)` — GML precedence: `(exit_type & $F0) == type`. */
export const is_exit_type = (exitType: number, type: number): boolean => (exitType & 0xf0) === type

/** `get_exit_rm_name(rm Exit_exitName)` — the rm name of an exit name. */
export const get_exit_rm_name = (exitName: string): string => exitName.substring(0, RmName_LEN)

/** PC fields read here. */
const pcDisguise = (): boolean =>
  gmBool((G.pc as { Disguise_enabled?: boolean } | null)?.Disguise_enabled ?? false)

/** `Exit_construct(exit name)` — builds an Exit instance from `g.dm_rm` (rando overrides) and returns it. */
export function Exit_construct(exitName: string): Ref<Exit> {
  const self = world.register(new Exit())
  self.exitName = exitName // exit name example: "_WestA_0010"
  self.exitNum = str_hex(exitName.substring(exitName.length - 2, exitName.length))
  // exit_type: Contains data bits. $00 Standard, $10 Doorway, $20 Elevator, $40 Pipe, ...
  // Can include bits that give info like falling scene type. See g.EXIT_TYPE_ for details
  self.exit_type = Number(g.dm_rm.val(exitName + STR_Type))
  let goTo = (g.dm_rm.get(exitName + STR_goto_reen) as string | undefined) ?? REEN_DEFAULT
  goTo = (f.dm_rando.get(exitName + STR_goto_reen) as string | undefined) ?? goTo
  self.goToExitName = goTo
  self.goToRoom = get_exit_rm_name(goTo)
  self.goToExitNum = str_hex(strR(goTo, goTo.length - 1))
  self.ww = Number(g.dm_rm.val(exitName + STR_Width, 2)) << 3
  self.ww_ = self.ww >> 1
  self.hh = Number(g.dm_rm.val(exitName + STR_Height, 2)) << 3
  self.hh += Math.sign(self.exit_type & g.EXIT_TYPE_DOOR) // EXIT_TYPE_DR y scale down 1 extra pixel so GO csMid can detect
  self.hh_ = self.hh >> 1
  // sprite_index size = 1x1 and is transparent, it just needs to be scaled so that collideRect() in
  // pc_collide_exit() has correct sprite_width & sprite_height
  self.image_xscale = self.ww
  self.image_yscale = self.hh
  self.xl = Number(g.dm_rm.val(exitName + STR_Exit_x)) << 3
  self.xr = self.xl + self.ww
  self.xc = self.xl + self.ww_
  self.x = self.xl
  self.yt = Number(g.dm_rm.val(exitName + STR_Exit_y)) << 3
  self.yb = self.yt + self.hh
  self.yc = self.yt + self.hh_
  self.y = self.yt
  update_draw_xy(self)
  self.side = (self.exitNum >> 4) & 0xf
  self.page_x = self.xl >> 8
  if (self.side & 0x2) self.page_x++
  else if (self.side & 0x1) self.page_x--
  self.page_y = self.yt >> 8
  self.BodyHB_w = self.ww
  self.BodyHB_h = self.hh
  self.BodyHB_xl = self.xl
  self.BodyHB_xr = self.BodyHB_xl + self.BodyHB_w
  self.BodyHB_yt = self.yt
  self.BodyHB_yb = self.BodyHB_yt + self.BodyHB_h
  let open = gmBool(g.dm_rm.val(exitName + STR_Open))
  const rOpen = f.dm_rando.get(exitName + STR_Open)
  if (rOpen !== undefined) open = gmBool(rOpen)
  // Quest-opened exits (Mido church, fast-travel 2/3): open once reached from them or flagged in dm_quests
  for (const _datakey of [dk_MidoChurch, `${dk_FastTravel}02`, `${dk_FastTravel}03`]) {
    if (
      !open &&
      exitName === g.dm_rm.val(_datakey + STR_Exit + STR_Name) &&
      (exitName === f.reen || gmBool(f.dm_quests.val(_datakey + STR_Open)))
    ) {
      open = true
      f.dm_quests.set(_datakey + STR_Open, 1)
    }
  }
  if (gmBool(g.dm_rm.val(`${exitName}_Draw${STR_Open}${STR_Exit}`))) self.is_draw_open_exit = true
  self.doorway_spr = 0
  if (
    (self.exit_type & g.EXIT_TYPE_DOOR) === g.EXIT_TYPE_DOOR &&
    open &&
    g.town_name === STR_Bulblin &&
    !pcDisguise()
  ) {
    open = false
    self.doorway_spr = g.TownDoor1_SPR as string | 0
    self.doorway_spr_yoff = -0x08
  } else {
    switch (Number(g.dm_rm.val(exitName + STR_Door + STR_ID, -1))) {
      case 0:
        self.doorway_spr = g.Doorway1_SPR
        break
      case 1:
        self.doorway_spr = 'spr_Doorway01_Closed01'
        break
      default:
        break
    }
  }
  self.open = open
  GO_init_palidx(self, Number(g.dm_rm.val(exitName + STR_Palette + STR_Idx, self.palidx)))
  return self
}

import { STR_Bulblin } from '@z2/data'

/** `Exit_Draw()` */
export function Exit_Draw(self: Exit): void {
  if (self.doorway_spr) {
    const _x = self.xl + sprite_get_xoffset(self.doorway_spr)
    let _y = self.yb - sprite_get_yoffset(self.doorway_spr)
    _y = (_y >> 2) << 2
    _y += self.doorway_spr_yoff
    draw_sprite_(self.doorway_spr, 0, _x, _y, self.palidx)
    void _x
  }
  if (self.open && self.is_draw_open_exit) {
    // This just covers the door graphic solid black so it looks open.
    const _H = 0x04 << 3
    const _x = self.xl
    let _y = ((self.yb >> 3) - 1) << 3
    _y -= _H
    draw_sprite_('spr_1x1_WHT', 0, _x, _y, -1, self.ww, _H, p.C_BLK1)
  }
  if (g.DevTools_state && g.can_draw_Exit_hb) {
    const _COL = self.open ? p.C_GRN0 : p.C_RED0
    draw_rect_(_COL, self.drawX, self.drawY, self.ww, self.hh, 0.5)
  }
}

export const NO_EXIT: Ref<Exit> = NOONE
