/** state_DROP_step, state_EXPLODE_step (scripts/game_object/go) — the shared death/drop state machines. */
import { MAX_GOC1, STR_Boss, STR_Explode, UIDX_NULL } from '@z2/data'
import { Boss, type GameObject } from '../classes'
import { deps } from '../deps'
import { fp, gp, pp } from '../pending'
import { spriteMeta } from '../sprites'
import { sign_ } from '../util'
import { set_xy } from './movement'

/** Hooks into the projectile layer; set by goc/Projectile.ts to avoid an import cycle. */
export const stateHooks = {
  avail_uidx_goc: (_count: number): number => UIDX_NULL,
  GOC1_create: (
    _xl: number,
    _yt: number,
    _facing: number,
    _obj: string,
    _ver: number,
    _src: GameObject,
  ): void => {},
  update_EF11: (_self: GameObject): void => {},
}

/** `state_DROP_step(inst id)` — DD6C: the rising XP number and the XP payout. */
export function state_DROP_step(inst: GameObject): void {
  inst.can_draw_self = false
  // DD6C
  if (inst.timer) {
    if (inst.timer <= gp().XP_RISE_DURATION) {
      inst.xp_can_draw = inst.xp
      set_xy(inst, inst.x, inst.y - (gp().counter1 & 0x1))
    }
  }
  // DDEC
  else {
    if (inst.xp && !inst.drop_item_obj) {
      let _XP = inst.xp
      _XP += inst.xp === 300 && inst.objectName === 'Rebonack01B' ? 1 : 0
      fp().xpPending += _XP
      fp().xpPending &= 0xffff
      inst.xp = Math.max(0, inst.xp - _XP)
    }
  }
}

/** `state_EXPLODE_step(inst id)` — DCAE. Boss death flash/shake/explosions or the enemy explosion sprite. */
export function state_EXPLODE_step(inst: GameObject): void {
  const g = gp()
  // DCAE
  if (!inst.timer) {
    if (!inst.drop_item_obj) inst.timer = g.XP_RISE_DURATION // $20
    g.ScreenShake_timer = 0
    g.ScreenShake_strength_x = 0
    g.ScreenShake_strength_y = 0
    inst.state = inst.state_DROP // Drop XP or item
    return
  }
  // DCC2. Boss  ------------------------------------------------
  if (inst instanceof Boss) {
    // DCBD
    if (inst.timer === g.BOSS_DEATH_FLASH_CUE) {
      // g.BOSS_DEATH_FLASH_CUE==$68
      const _DURATION = g.BOSS_DEATH_FLASH_CUE
      pp().Flash_Pal_timer = _DURATION // 074B. SpellFlash_DURATION1=$20. bit $80 mean flash bgr
      pp().SpellFlash_PC_timer = _DURATION
      pp().Flash_Bgr_timer2 = _DURATION // this will guarantee the red bgr(if flashing is turned off)
      deps.play_theme_sound(STR_Boss + STR_Explode)
    }
    g.ScreenShake_timer = 0
    g.ScreenShake_strength_x = 0
    g.ScreenShake_strength_y = 0
    if (
      g.mod_ScreenShake &&
      inst.timer < g.BOSS_DEATH_FLASH_CUE - 0x8 &&
      inst.timer & 0x1 &&
      inst.timer > 0xf
    ) {
      const _ADD = (inst.timer & 0xf) === 0x1 ? 1 : 0 // stronger jolt, matching the start of each loop in the sound
      g.ScreenShake_timer = 1 // Set to 0 to turn off
      g.ScreenShake_strength_x = 2 + _ADD
      g.ScreenShake_strength_y = 2 + _ADD
    }
    if (inst.timer >= g.BOSS_DEATH_FLASH_CUE) stateHooks.update_EF11(inst) // $68
    // DD27, 9A46 & 9764. Boss explosions
    if (!(g.counter1 & 0x1) && stateHooks.avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
      // 9A4B: JSR DBCE
      const r2 = (g.dl_RandomOG.get(2 + inst.update_idx) as number) ?? 0
      const r1 = (g.dl_RandomOG.get(1 + inst.update_idx) as number) ?? 0
      let _XL: number
      let _YT: number
      if (g.mod_BossExplosionsCenteredOnBoss) {
        // Center explosions on boss
        _XL = inst.x - 0x08 + (r2 & 0x0f) - 8 // range $0F
        _YT = inst.y - 0x10 + (r1 & 0x1f) - 7 // range $20
      } else {
        // OG. explosions centered around upper left of boss
        _XL = inst.xl + (r2 & 0x0f) - 8 // range $0F
        _YT = inst.yt + (r1 & 0x1f) - 7 // range $20
      }
      stateHooks.GOC1_create(_XL, _YT, inst.facing_dir, 'BossExplosion', 1, inst)
    }
    return
  }
  // EEB2. NOT Boss  -----------------------------------------------------------
  // Need explosion_count & explosion_y before EF11 for Geldarm and posibly future others.
  inst.explosion_count = Math.max(inst.hh >> 4, 1)
  inst.explosion_y = inst.drawY - (inst.sprite ? spriteMeta(inst.sprite).yorig : 0) + 8
  const _C1 = inst.timer >= 0x18
  if (_C1) inst.stun_timer = inst.timer // for pal flash in EF11
  stateHooks.update_EF11(inst)
  inst.stun_timer = 0
  inst.can_draw_self = _C1
  inst.explosion_can_draw_self = true
  if (inst.timer >= 0x08 && inst.timer <= 0x17)
    inst.explosion_sprite = 'spr_Explosion1B' // B: Big
  else inst.explosion_sprite = 'spr_Explosion1A' // A: Small
  inst.explosion_yscale = sign_(g.counter1 & 0x4)
}
