// Ported from ZALiA scripts/g_Step.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively

import { gmBool } from '../../../nes/math8'
import { G, g, input } from '../../../runtime/world'
import { update_QuestTimer } from '../../file/stats'
import { go_spawn_enter_room } from '../../game_object_mgr/spawn'
import { devHooks, frameHooks } from '../../hooks'
import { notPorted } from '../../pending'
import { room_goto_ } from '../../rooms/goto'
import { Audio_update, aud_play_sound } from '../../sound'
import { update_game_window_1a } from '../../view/window'
import { can_update_frame } from '../can_update_frame'
import {
  delta_time,
  keyboard_check,
  room_speed,
  scheduler_resolution_get,
  scheduler_resolution_set,
  vk_backspace,
  vk_control,
  withInstance,
} from '../gm'
import { update_change_room } from '../update_change_room'
import { update_game_timers } from '../update_game_timers'
import { update_og_rand } from '../update_og_rand'
import { g_Step_A1 } from './g_Step_A1'
import { g_Step_A2 } from './g_Step_A2'
import { g_Step_B1 } from './g_Step_B1'

const Input_GameTesting = () => devHooks.Input_GameTesting?.()
const Overworld_Step = (...a: unknown[]) => (frameHooks.Overworld_Step as (...x: unknown[]) => unknown)(...a)
const cutscene_update = (...a: unknown[]) =>
  (frameHooks.cutscene_update as (...x: unknown[]) => unknown)(...a)
const d_l0__oo__0l_b = (...a: unknown[]) => (frameHooks.d_l0__oo__0l_b as (...x: unknown[]) => unknown)(...a)
const update_OptionsMenu = (...a: unknown[]) =>
  (frameHooks.update_OptionsMenu as (...x: unknown[]) => unknown)(...a)
const update_QuitAppMenu = (...a: unknown[]) =>
  (frameHooks.update_QuitAppMenu as (...x: unknown[]) => unknown)(...a)

/** GML: g_Step() */
export function g_Step() {
  // GML `var` is function-scoped; locals hoisted here:
  let _GUI_CONDITION: any
  // An Extension so that Windows Sleep Margin in
  // Global Game Settings doesn't need to be maxed at 15
  // to get smooth performance and avoid stuttering/jittering.
  if (scheduler_resolution_get() !== 1) {
    scheduler_resolution_set(1)
  }
  // Added this to help decrease large room loading times.
  G.delta_target = 1 / room_speed
  G.delta_actual = delta_time / 1000000
  G.delta_multiplier = G.delta_actual / G.delta_target
  //show_debug_message('delta_time: '+string(delta_time)+', delta_target: '+string(delta_target)+', delta_actual: '+string(delta_actual)+', delta_multiplier: '+string(delta_multiplier));
  G.App_frame_count++
  // --------------------------------------------------------------------
  /* TODO with */ withInstance(input, (_self) => {
    // Input_update1(): raw device sampling already ran in World.step() before this hook
  })
  /* TODO with */ withInstance(input, (_self) => {
    Input_GameTesting()
  })
  update_game_window_1a() // app window scale and positioning
  update_QuestTimer()
  // for pausing during dev
  if (!can_update_frame()) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  G.App_frame_count_unpaused++
  G.Room_frame_count++
  g.counter0 = (g.counter0 + 1) & 0xff
  // --------------------------------------------------------------------
  g.spell_cast_this_frame = 0
  g.dialogue_started_this_frame = false
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  // C12F: JSR C1C1,   C1C6
  Audio_update()
  // C132  - Input
  /* TODO with */ withInstance(input, (_self) => {
    input.Input_update2() // determine inputs for this frame
    input.Input_update2_held0(g.ChangeRoom_timer)
    // Input_update2.gml (tail): overworld pause toggle on Start
    if (g.room_type === 'C' && g.ChangeRoom_timer <= 0 && g.gui_state === g.gui_state_NONE) {
      if (gmBool(input.Pause_pressed)) {
        g.overworld_paused = !g.overworld_paused
        aud_play_sound(g.overworld_paused ? G.OVERWORLD.Pause_SOUND1 : G.OVERWORLD.Pause_SOUND2)
      }
    } else {
      g.overworld_paused = false
    }
  })
  if (g.room_type === 'C' && gmBool(g.overworld_paused)) {
    // Other5: LT, Other6: RT, Other1: Xbox B
    if (
      (gmBool(input.GP_Other5_held) && gmBool(input.GP_Other6_held) && gmBool(input.GP_Other1_held)) ||
      (keyboard_check(vk_control) && keyboard_check(vk_backspace))
    ) {
      if (!gmBool(G.OverworldSoftlock_timer)) {
        G.OverworldSoftlock_timer = G.OverworldSoftlock_DURATION0
      } else {
        G.OverworldSoftlock_timer--
        if (!gmBool(G.OverworldSoftlock_timer)) {
          room_goto_('rmB_ContinueSave')
        }
      }
    } else {
      G.OverworldSoftlock_timer = 0
    }
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // --------------------------------------------------------------------
  // --------------------------------------------------------------------
  if (!update_QuitAppMenu() && !update_OptionsMenu()) {
    // if not changing rm
    if (!update_change_room()) {
      // --------------------------------------------------------------------
      switch (g.room_type) {
        case 'A': {
          g_Step_A1()
          break
        }
        case 'B': {
          g_Step_B1()
          break
        }
        case 'C': {
          /* TODO with */ withInstance(G.OVERWORLD, (_self) => {
            Overworld_Step()
          })
          break
        }
      }
      d_l0__oo__0l_b()
      // --------------------------------------------------------------------
      // C14E
      _GUI_CONDITION =
        g.gui_state === g.gui_state_NONE ||
        g.gui_state === g.gui_state_DIALOGUE1 ||
        g.gui_state === g.gui_state_DIALOGUE2 ||
        g.gui_state === g.gui_state_DIALOGUE3
      //
      // g.gui_state is 0 or dialogue
      if (gmBool(_GUI_CONDITION) && !gmBool(G.OVERWORLD.flute_timer)) {
        // C169  - Timers
        update_game_timers()
        // C185  - Random numbers
        update_og_rand()
      }
      // --------------------------------------------------------------------
      if (gmBool(g.EnterRoom_SpawnGO_timer)) {
        g.EnterRoom_SpawnGO_timer--
        if (!gmBool(g.EnterRoom_SpawnGO_timer)) {
          go_spawn_enter_room()
        }
      }
      // --------------------------------------------------------------------
      // Main update
      // g.gui_state is 0 or dialogue
      if (g.room_type === 'A' && !gmBool(g.EnterRoom_SpawnGO_timer) && gmBool(_GUI_CONDITION)) {
        g_Step_A2()
      }
    }
    // --------------------------------------------------------------------
    // --------------------------  CUTSCENES  -----------------------------
    cutscene_update()
  }
}
