/**
 * BossBot (ZALiA object `BoBoA`, parent `Enemy`); OG eID $1E. A180. Sits hidden until Link walks inside
 * `ATK_DIST`, then reveals itself and hops at him; once it dies — or has taken more than 8 damage — it bursts
 * into five Bots. Ported from `BossBot_init2.gml`, `BossBot_update.gml`, `BossBot_update_1.gml`,
 * `BossBot_update_2.gml`, `BossBot_udp.gml`.
 *
 * `data_go_scr` fills ini1 = `GameObjectB_init` (shared), ini2 = `BossBot_init2`, updt = `BossBot_update`,
 * udp = `BossBot_udp`; no draw/iend/dstr/rmen slot. `BossBot_update_1/2` are plain calls from `BossBot_update`.
 * The `BoBoA` Create event is commented out apart from `eID = $1E`, so nothing is folded in from it; the
 * commented-out "MOD 2023/12/02" re-check at the end of `BossBot_update.gml` is dropped.
 */
import { CS_BD1, STR_Enemy, STR_HP, STR_Randomize } from '@z2/data'
import { byte, gmBool, isVal } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { val } from '../../../../../other/index'
import { Enemy } from '../../../../classes'
import { GameObject_create } from '../../../../create'
import { DC91_carry, dir_to_pc } from '../../../../go/misc'
import { updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import { solid_clip_correction } from '../../../../goa/movement'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'
import { dl } from '../../shared'
import { rand } from '../ache/_shared'

/** Fields set by `BossBot_init2`. */
export class BoBoA extends Enemy {
  readonly objectName = 'BoBoA' as const
  VSPD_GRAV = 2
  ATK_DIST = 0x30 // OG $30
}

/** `BossBot_init2()` — eID = $1E */
export function BossBot_init2(self: BoBoA): void {
  dl(self).set(1, 'spr_BossBot2')
  dl(self).set(0, 'spr_BossBot1')
  GO_set_sprite(self, dl(self).get(0) as string)
  GO_init_palidx(self, G.PI_MOB_BLU)
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.ATK_DIST = 0x30
  // ATK_DIST = $20 + (ww_ + 8); // +8 for half pc spr w.  OG $30
  // MOD 2023/12/02. With enemy hp rando, it's possible to kill
  // BossBot before it gets a chance to spawn the Bots.
  // Therefor, BossBot's hp must be greater than PC's max possible damage.
  // BossBot's vanilla hp: g.dl_HP[|$1C]=$38
  // PC's max damage: dl_ATTACK_DAMAGE[|$09]=$1C; // attack level 9
  if (gmBool(val(G.dm_save_file_settings.get(STR_Randomize + STR_Enemy + STR_HP)))) {
    const _dl_ATTACK_DAMAGE = pc().dl_ATTACK_DAMAGE
    const _MAX_PC_DAMAGE = _dl_ATTACK_DAMAGE[_dl_ATTACK_DAMAGE.length - 1] ?? 0
    if (((g.dl_HP.get(self.HP_IDX) as number) ?? 0) <= _MAX_PC_DAMAGE) {
      const _COUNT = g.dl_HP.size
      for (let _i = self.HP_IDX + 1; _i < _COUNT; _i++) {
        if (((g.dl_HP.get(_i) as number) ?? 0) > _MAX_PC_DAMAGE) {
          self.HP_IDX = _i
          self.hp = g.dl_HP.get(self.HP_IDX) as number
          break // _i
        }
      }
    }
  }
}

/** `BossBot_update()` — A180 */
export function BossBot_update(self: BoBoA): void {
  const P = pc()
  // A180.  OG: spawns w/ $38 hp
  if (!gmBool(self.hp) || self.hp < ((g.dl_HP.get(self.HP_IDX) as number) ?? 0) - 8) {
    self.state = 0
    BossBot_update_2(self) // spawn Bots
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // -------------------------------------------------------------------
  // A1CA
  let _carry = 0
  if (!gmBool(self.behavior)) {
    // 0: HIDING
    self.facing_dir = dir_to_pc(self)
    _carry = DC91_carry(self) ? 1 : 0
  }
  let _ATTACK_DIST = self.ATK_DIST
  // MOD. Added this because enemy rando has BossBot spawning too close to PC
  if (Math.abs(self.y - P.y) - (self.hh_ + P.hh_) < 0x3 << 3) _ATTACK_DIST += 0x08
  const _IN_DIST = Math.abs(self.x - P.x) + _carry < _ATTACK_DIST
  if (!gmBool(self.behavior) && _IN_DIST) self.behavior = 1 // 1: REVEAL!!
  if (gmBool(self.behavior) || _IN_DIST) {
    // A1DF.  ATTACK!!
    if (self.cs & 0x4) {
      solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
      self.vspd = 0
    }
    BossBot_update_1(self)
  }
}

/** `BossBot_update_1()` — A1EB */
export function BossBot_update_1(self: BoBoA): void {
  // A1EB
  updateY(self)
  GO_update_cs(self)
  GOB_update_2(self)
  // A1F1
  if (self.cs & 0x4 && !(rand(self) & 0x7)) {
    // A1FE: JSR DC91
    self.facing_dir = dir_to_pc(self)
    self.hspd = (0x10 * self.facing_dir) & 0xff
    self.vspd = 0xe8 // JUMP!!
    // A1EB
    updateY(self)
    GO_update_cs(self)
    GOB_update_2(self)
  }
  // mod. Prevent clip into solid
  if (!(self.cs & 0x4) && !(self.cs & 0x3)) updateX(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
}

/**
 * `BossBot_update_2()` — burst into five Bots. The two `_carry` lines replay the OG's 16-bit x add, whose
 * leftover carry falls through into the y add (so a Bot can land 1 px lower). Kept exactly as ZALiA wrote it:
 * the high-byte constant `byte($FF + (_i<4))` yields $00 for the four negative x offsets and $FF for the
 * positive one, which is the opposite of a straight two's-complement sign extension — no comment or address
 * in ZALiA says which way the OG went, so it is reproduced rather than "corrected" (worth 1 px at most).
 */
export function BossBot_update_2(self: BoBoA): void {
  for (let _i = 0; _i < 5; _i++) {
    let _xOff = 0
    if (isVal(_i, 4)) _xOff = 8
    else if (isVal(_i, 3, 2)) _xOff = -8
    else if (isVal(_i, 1, 0)) _xOff = -24
    const _x = self.xl + _xOff + 1

    let _carry = byte(self.xl) + byte(_xOff) > 0xff ? 1 : 0
    _carry = (self.xl >> 8) + byte(0xff + (_i < 4 ? 1 : 0)) + _carry > 0xff ? 1 : 0

    let _yOff = 0
    if (isVal(_i, 2)) _yOff = 0
    else if (isVal(_i, 0, 4)) _yOff = 4
    else if (isVal(_i, 1, 3)) _yOff = 8
    const _y = self.yt + _yOff + _carry

    const _bot = GameObject_create(_x, _y, 'Bot_A', 1)
    if (!_bot) continue // with (noone)
    _bot.hspd = ((((g.dl_RandomOG.get(2 + _bot.update_idx) as number) ?? 0) & 0x1f) + 0xf0) & 0xff
    _bot.vspd = 0xd0
    _bot.HP_IDX = 0x1c // g.dl_HP_DEFAULT[|$1C] = $D8
    _bot.hp = g.dl_HP.get(_bot.HP_IDX) as number
    _bot.stun_timer = 1
  }
}

/** `BossBot_udp()` — two-frame idle animation off `g.counter1` bit $10 */
export function BossBot_udp(self: BoBoA): void {
  self.can_draw_self = true
  GO_set_sprite(self, dl(self).get((g.counter1 & 0x10) >> 4) as string)
}

export function registerBossBot(): void {
  registerObject('BoBoA', BoBoA)
  registerScripts({ BossBot_init2, BossBot_update, BossBot_update_1, BossBot_update_2, BossBot_udp })
}
registerBossBot()
