/**
 * What the palette system reads from the other singletons (`g`, `f`, `global.pc`, view). These are
 * ZALiA field names; the owning ports declare the real classes. Typed here as narrow interfaces so this
 * folder typechecks independently of their progress — the casts below are the only coupling point.
 */
import type { DsList, DsMap } from '../../runtime/ds'
import { f as fBinding, g as gBinding, world } from '../../runtime/world'
import { GameObject } from '../game_object/classes'
import { notPorted } from '../pending'

export { viewH, viewW, viewYC, viewYT } from '../collision/env'
export { set_background_color } from '../graphics/index'
export { is_exiting_rm, rm_get_file_data } from '../room/index'
export { tile_layer_hide, tile_layer_show } from '../tile/tileWorld'

export interface TiledLayerLike {
  name?: string
  data?: number[]
}
export interface TiledMapLike {
  width?: number
  height?: number
  layers?: TiledLayerLike[]
}

export interface PaletteGameDeps {
  rm_name: string
  room_type: 'A' | 'B' | 'C'
  /** current GM room name (`room_get_name(room)`), e.g. `rmB_Title` */
  room: string
  area_name: string
  dungeon_num: number
  town_name: string
  file_data_quest_num: number
  rm_brightness: number
  RM_BRIGHTNESS_MAX: number
  mod_RM_BRIGHTNESS_SYS: number
  mod_MedicinePlantItem: boolean | number
  EnterRoom_SpawnGO_timer: number
  counter1: number
  game_end_state: number
  FallScene_timer: number
  FallScene_INACTIVE: number
  FallScene_BITS: number
  FallScene_BITS_SHIFT: number
  spells_active: number
  all_bg_black_only: boolean | number
  RandoPalette_state: number
  view_y_page_min: number
  view_y_page_max: number
  FileCleaning01_STATE: boolean | number
  FileCleaning01_rm_name: string
  dm_rm: DsMap<number | string>
  dm_ITEM: DsMap<number | string>
  dm_cut_scene: DsMap<number | string>
  dm_tile_file: TiledMapLike | undefined
  dm_TILE_DEPTH: DsMap<number | string>
  dl_TILE_DEPTHS: DsList<number>
  dl_TILE_DEPTH_NAMES: DsList<string>
  dl_pal_swap_depths: DsList<number>
  TILE_LAYER_COUNT: number
  exit_leave: { exit_type: number } | null | undefined
  burnable_mgr:
    | { scene_has_burnable: boolean | number; Burnable_pi: number; Burnable_PAL: string }
    | undefined
  can_show_t_solid: boolean | number
  can_show_t_unique: boolean | number
}
export interface PaletteFileDeps {
  items: number
  dm_rando: DsMap<number | string>
}
export interface PalettePcDeps {
  state: number
  x: number
  Disguise_enabled: boolean | number
  dm_skins: DsMap<number | string>
  colliding_elevator: unknown
}
export interface PaletteGlobalDeps {
  SceneRando_enabled: boolean | number
  SceneRando_scene_brightness_control: number
  Halloween1_enabled: boolean | number
  pc: PalettePcDeps
  OVERWORLD: { dm: DsMap<number | string>; exit_owrc: number; enc_reen: unknown; flute_timer: number }
}

export const gd = (): PaletteGameDeps => gBinding as unknown as PaletteGameDeps
export const fd = (): PaletteFileDeps => fBinding as unknown as PaletteFileDeps
/** `global.*` fields the palette reads that belong to other ports; stored on World.G by their owners. */
export const Gd = (): PaletteGlobalDeps => world.G as unknown as PaletteGlobalDeps

export { NIAO_create2 } from '../niao/niao'
// Scripts from other folders, resolved when they land (see PORTING.md rule 5).
export { tile_hidden_update_2a } from '../tile'
/** Player seams (goa) — installed by `wireCore()` (lazy to avoid the palette↔goa import cycle). */
export const pcSeams = {
  pc_is_cucco: notPorted('pc_is_cucco') as () => boolean,
  /**
   * `draw_pc_skin(x, y, xscale, yscale, *behavior, *use disguise, *shield lvl, *sword lvl, *pal idx, *colour)`.
   * Typed, not `(...a: unknown[])`: the loose signature hid a call that passed `'cucco'` in the `x` slot
   * and the string `'DAMAGE'` where the GML passes `global.pc.behavior_DAMAGE` (10).
   */
  draw_pc_skin: notPorted('draw_pc_skin') as (
    x: number,
    y: number,
    xScale: number,
    yScale: number,
    behavior?: number,
    useDisguise?: boolean | number,
    shieldLevel?: number,
    swordLevel?: number,
    palIdx?: number,
    color?: number,
  ) => void,
  /** `draw_falling_scene`'s cucco branch (`draw_falling_scene.gml:67-81`) — body/legs/wing + eye. */
  draw_pc_cucco_fall: notPorted('draw_pc_cucco_fall') as (
    x: number,
    y: number,
    xScale: number,
    palIdx: number,
  ) => void,
  /** `global.pc.behavior_DAMAGE` (10) — the pose the falling PC is drawn in. */
  behavior_DAMAGE: 10,
}
export const pc_is_cucco = (): boolean => pcSeams.pc_is_cucco()
export { viewH_, viewW_, viewXC } from '../collision/env'
export { is_exiting_ow } from '../room'
export const draw_pc_skin: typeof pcSeams.draw_pc_skin = (...a) => pcSeams.draw_pc_skin(...a)
export const draw_pc_cucco_fall: typeof pcSeams.draw_pc_cucco_fall = (...a) =>
  pcSeams.draw_pc_cucco_fall(...a)
/** Room-brightness contributors: `with(GameObject) if (state && brightness) …`. */
export const eachBrightnessContributor = (): Iterable<{ state: number; brightness: number }> =>
  world.instancesOf(GameObject)
