/** Ported from `Cutscene_GameEnd_1A_init.gml`, `_update.gml`, `_draw.gml`, `_end.gml` — waking Zelda with the Triforce. */
import { DEPTH_ITEM, dk_WakeZelda, PC_LOCK_ALL, STR_Cast, STR_Heart, STR_Magic, STR_Spell } from '@z2/data'
import { gmBool } from '../../../nes/math8'
import { DsGrid } from '../../../runtime/ds'
import { f, G, g, p } from '../../../runtime/world'
import { get_stat_max } from '../../file/stats'
import { instancesNamed } from '../../Game/gm'
import { sign_ } from '../../math'
import { triforce_pal_update } from '../../palette/roomStart'
import { draw_sprite_ } from '../../rooms/draw'
import { Audio } from '../../sound/Audio'
import { aud_play_sound } from '../../sound/play'
import { get_audio_theme_track } from '../../sound/theme'
import type { Cutscene_GameEnd_1A } from './classes'
import { Cutscene_init } from './cutscene'
import { gofDeps } from './deps'

/** `audio_stop_sound(Audio.mus_rm_inst)` — stop by playing instance. */
function stopMusInst(): void {
  if (Audio.mus_rm_inst) Audio.push({ kind: 'stopInst', inst: Audio.mus_rm_inst })
}

/** `Cutscene_GameEnd_1A_init()` */
export function Cutscene_GameEnd_1A_init(self: Cutscene_GameEnd_1A): void {
  // need this bc this is RM_NAME_NPALACE
  if (!gmBool(g.game_end_state)) {
    self.destroy()
    return
  }
  g.cutscene = g.CUTSCENE_GAME_END_1A
  Cutscene_init(self)
  self.scr_step = Cutscene_GameEnd_1A_update as never
  self.scr_draw = Cutscene_GameEnd_1A_draw as never
  self.scr_inst_end = Cutscene_GameEnd_1A_end as never
  self.depth = DEPTH_ITEM
  for (const h of instancesNamed('HUD')) h.destroy()
  stopMusInst()
  Audio.mus_rm_intr = 0
  Audio.mus_rm_body = 0
  self.TRIFORCE_SPR = 'spr_Triforce_1a'
  p.triforce_pi = G.PI_MOB_PUR
  self.dg_triforce = new DsGrid<number | string>(3, 3, 0)
  f.hp = get_stat_max(STR_Heart) // Prevent low hp beep
  f.mp = get_stat_max(STR_Magic)
}

/** `Cutscene_GameEnd_1A_update()` */
export function Cutscene_GameEnd_1A_update(self: Cutscene_GameEnd_1A): void {
  if (g.cutscene !== g.CUTSCENE_GAME_END_1A || g.ChangeRoom_timer > 0) return
  const pc = G.pc
  g.pc_lock = PC_LOCK_ALL
  pc.xScale = 1
  gofDeps.PC_set_behavior(pc, pc.behavior_HOLD_ITEM5) // back towards screen, both arms raised
  triforce_pal_update()
  for (const z of instancesNamed('Zelda')) z.xScale = 1
  const IDX_X = 1
  const IDX_Y = IDX_X + 1
  const dg = self.dg_triforce as DsGrid<number | string>
  // ------------------------------------------------------------------------
  if (!gmBool(g.cutscene_part)) {
    const _X = pc.spawn_xl + pc.ww_
    const _Y = pc.spawn_yt - 8 // OG
    for (let _i = dg.width - 1; _i >= 0; _i--) {
      dg.set(_i, 0, self.TRIFORCE_SPR) // can draw
      dg.set(_i, IDX_X, _X)
      dg.set(_i, IDX_Y, _Y)
    }
    stopMusInst()
    Audio.mus_rm_intr = 0
    Audio.mus_rm_body = 0
    g.cutscene_timer = self.DUR1 // DUR1: $5F 1.583s
    g.cutscene_part = 1
  }
  switch (g.cutscene_part) {
    case 1: {
      if (gmBool(g.cutscene_timer)) break
      let _THEME: string
      if (f.quest_num >= 2) _THEME = `${dk_WakeZelda}02`
      else _THEME = dk_WakeZelda
      Audio.mus_rm_body = get_audio_theme_track(_THEME)
      aud_play_sound(Audio.mus_rm_body, Audio.PRIORITY_TOP, true, -1, _THEME)
      g.cutscene_timer = self.DUR1
      g.cutscene_part++
      break
    }
    case 2: {
      // MOVE TRIFORCE
      if (gmBool(g.cutscene_timer)) break
      if (g.counter1 & 0x7) break // Every 8 frames
      // TODO(ZALiA): Find better triforce resting position
      const _C1 = !(g.counter1 & 0x1f) && (dg.get(1, IDX_Y) as number) > pc.yt - (0x03 << 3) - 4
      for (let _i = 2; _i >= 0; _i--) {
        // one moves vertical, the others move horizontal
        if (_i)
          dg.set(_i, IDX_X, (dg.get(_i, IDX_X) as number) + sign_(_i & 0x01)) // move RGT/LFT
        else dg.set(_i, IDX_Y, (dg.get(_i, IDX_Y) as number) - 1) // move UP
        if (_C1) dg.set(_i, IDX_Y, (dg.get(_i, IDX_Y) as number) - 1) // MOD. move UP
      }
      if (Math.abs(pc.x - (dg.get(1, IDX_X) as number)) >= 0x4c) {
        // (OG: >= $40).  if triforce has moved far enough
        g.cutscene_timer = self.DUR1 // Delay spell flash.
        g.cutscene_part++
      }
      break
    }
    case 3: {
      // DELAY WAKE UP ZELDA SPELL FLASH
      if (gmBool(g.cutscene_timer)) break
      const _DURATION = 0x60
      p.Flash_Pal_timer = _DURATION
      p.Flash_Bgr_timer = _DURATION
      p.SpellFlash_PC_timer = _DURATION
      aud_play_sound(get_audio_theme_track(STR_Cast + STR_Spell))
      g.cutscene_part++
      break
    }
    case 4: {
      // WAKE UP ZELDA SPELL FLASH
      if (gmBool(p.Flash_Bgr_timer)) break
      if (gmBool(g.cutscene_timer)) break
      g.cutscene_timer = self.DUR1 // Zelda Sit Up delay.
      g.cutscene_part++
      break
    }
    case 5: {
      // DELAY ZELDA SIT UP
      if (gmBool(g.cutscene_timer)) break
      for (const z of instancesNamed('Zelda')) z.sub_state = z.SUB_STATE_WAKE // wake up
      g.cutscene_timer = self.DUR1
      g.cutscene_part++
      break
    }
    case 6: {
      // ZELDA AWAKE, SITS UP
      if (gmBool(g.cutscene_timer)) break
      g.cutscene_timer = self.DUR1 // Delay change rm.
      g.cutscene_part++
      break
    }
    case 7: {
      // CHANGE RM
      if (gmBool(g.cutscene_timer)) break
      for (const ex of instancesNamed('Exit')) {
        if (ex.exitNum !== 0x01) continue
        g.exit_leave = ex
        pc.HoldItem_timer = 0
        g.cutscene_part = 0
        g.cutscene = 1
        return
      }
      break
    }
  }
}

/** `Cutscene_GameEnd_1A_draw()` */
export function Cutscene_GameEnd_1A_draw(self: Cutscene_GameEnd_1A): void {
  for (const z of instancesNamed('Zelda')) self.depth = z.depth - 1
  const dg = self.dg_triforce as DsGrid<number | string>
  for (let _i = dg.width - 1; _i >= 0; _i--) {
    draw_sprite_(dg.get(_i, 0) as string, 0, dg.get(_i, 1) as number, dg.get(_i, 2) as number, p.triforce_pi)
  }
}

/** `Cutscene_GameEnd_1A_end()` */
export function Cutscene_GameEnd_1A_end(self: Cutscene_GameEnd_1A): void {
  self.dg_triforce = undefined
}
