/** `RandoData_enemy(obj, ver, difficulty, *ENIGMA difficulty, *Dripper difficulty)` */
export function RandoData_enemy(
  obj: string,
  ver: number,
  difficulty: number,
  difficultyEnigma = 0,
  difficultyDripper = 0,
): void {
  const dm = g.dm_RandoEnemy
  const _OBJVER = obj + hexStr(ver)
  let _difficulty = 0
  let _datakey1 = ''
  let _datakey2 = ''
  // 0: Normal enemy rando, 1: Enigma enemy rando, 2: Dripper enemy rando
  for (let _i = 0; _i < 3; _i++) {
    switch (_i) {
      default:
        _difficulty = difficulty
        _datakey1 = STR_Difficulty + hexStr(_difficulty)
        _datakey2 = _OBJVER + STR_Difficulty
        break
      case 1:
        if (difficultyEnigma) {
          _difficulty = difficultyEnigma
          _datakey1 = STR_ENIGMA + STR_Difficulty + hexStr(_difficulty)
          _datakey2 = STR_ENIGMA + _OBJVER + STR_Difficulty
        }
        break
      case 2:
        if (difficultyDripper) {
          _difficulty = difficultyDripper
          _datakey1 = STR_Dripper + STR_Difficulty + hexStr(_difficulty)
          _datakey2 = STR_Dripper + _OBJVER + STR_Difficulty
        }
        break
    }
    // GML quirk kept: when a mode cannot spawn this objver, `_datakey1/2` keep the previous mode's keys, which
    // are already defined, so nothing is written.
    if (dm.get(_datakey2) === undefined) {
      dm.set(_datakey2, _difficulty)
      const _count = Number(dm.val(`${_datakey1}${STR_Count}`)) + 1
      dm.set(`${_datakey1}${STR_Count}`, _count)
      const _datakey3 = _datakey1 + hexStr(_count - 1)
      dm.set(_datakey3 + STR_Object, obj)
      dm.set(_datakey3 + STR_Version, ver)
      dm.set(_datakey3 + STR_OBJVER, _OBJVER)
      g.RandoEnemy_difficulty_MAX = Math.max(g.RandoEnemy_difficulty_MAX, _difficulty)
    }
  }
}

/** `Rando_init_enemy_data()` */
export function Rando_init_enemy_data(): void {
  for (const [obj, ver, d, e, dr] of RANDO_ENEMY_TABLE) RandoData_enemy(obj, ver, d, e, dr)
}
