import { loadCaches } from '@z2/data'
import Phaser from 'phaser'
import { ASSET_URL, atlasPages, type Manifests, mapStem } from './manifest'

/** Everything loaded before the game starts; stored in the registry for other scenes. */
export interface LoadedAssets {
  manifests: Manifests
  caches: Awaited<ReturnType<typeof loadCaches>>
}

/**
 * Loads manifests, every atlas page, every tileset image and the 33 data caches, then starts `GameScene`.
 * Audio is loaded lazily per audio set by `AudioPlayer`.
 */
export class BootScene extends Phaser.Scene {
  constructor() {
    super('Boot')
  }

  preload(): void {
    for (const name of ['sprites', 'tilesets', 'maps', 'sounds'] as const) {
      this.load.json(`manifest:${name}`, ASSET_URL.manifest(name))
    }
  }

  create(): void {
    const manifests: Manifests = {
      sprites: this.cache.json.get('manifest:sprites'),
      tilesets: this.cache.json.get('manifest:tilesets'),
      maps: this.cache.json.get('manifest:maps'),
      sounds: this.cache.json.get('manifest:sounds'),
    }
    for (const page of atlasPages(manifests.sprites)) {
      this.load.atlas(`atlas:${page}`, ASSET_URL.atlasPng(page), ASSET_URL.atlasJson(page))
    }
    for (const ts of manifests.tilesets) this.load.image(`ts:${ts.name}`, ASSET_URL.tileset(ts.name))
    // All 666 Tiled scene/overworld maps are loaded up front (~47 MB raw, ~5 MB gzipped): room changes are
    // synchronous in the core (`g_Room_Start` reads the map immediately), so lazy loading would need a
    // prediction step. Revisit if startup time becomes a problem.
    for (const m of manifests.maps) this.load.json(`map:${mapStem(m.file)}`, ASSET_URL.map(m.area, m.file))

    const cachesPromise = loadCaches((name) => fetch(ASSET_URL.cache(name)).then((r) => r.text()))
    this.load.once(Phaser.Loader.Events.COMPLETE, () => {
      cachesPromise.then((caches) => {
        const loaded: LoadedAssets = { manifests, caches }
        this.registry.set('assets', loaded)
        this.scene.start('Game')
      })
    })
    this.load.start()
  }
}
