/** `TektA` — ZALiA `enemy/tektite`: Tektite_init2, Tektite_update, Tektite_udp, Tektite_draw. 9805 */
import { CS_BD1, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { registerObjectClass } from '../../../../../other/registry'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { draw_sprite_ } from '../../../../../rooms/draw'
import { cam_yb_max } from '../../../../../view/camera'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { GO_draw_sprite } from '../../../../go/draw'
import { DC91_carry, dir_to_pc } from '../../../../go/misc'
import { GO_vspd_update1, set_xy, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import { solid_clip_correction } from '../../../../goa/movement'
import type { ObjectName } from '../../../../objectNames'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_despawn, GOB_update_2, GOB_update_2a, update_EF11 } from '../../../GameObjectB'
import { dl, rand } from '../../shared'

export class TektA extends Enemy {
  readonly objectName = 'TektA' as const
  Legs_sprite: string | 0 = 0
  legsYOff = 0x10
  VSPD_GRAV = 2
  BODY_HB_IDX_TALL = 0x02
  BODY_HB_IDX_SHRT = 0x0a
}
registerObject('TektA', TektA)
registerObjectClass('TektA', TektA)

/** `Tektite_init2()` */
export function Tektite_init2(self: TektA): void {
  self.projectile_OBJ = 'Bullet2'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  const s = dl(self)
  s.set(1, 'spr_Tektite2')
  s.set(0, 'spr_Tektite1')
  GO_init_palidx(self, G.PI_MOB_BLU)
  self.Legs_sprite = 'spr_Tektite_legs'
  self.draw_yoff = 0
  self.legsYOff = 0x10
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.BODY_HB_IDX_TALL = 0x02
  self.BODY_HB_IDX_SHRT = 0x0a
  self.BodyHB_idx = self.BODY_HB_IDX_TALL
}

/** `Tektite_update()` — 9805 */
export function Tektite_update(self: TektA): void {
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self) // DE40
    return
  }
  // 9808
  const _RAND = rand(self)
  update_EF11(self)
  const _yt_PREV = self.yt
  // 980B. every 4 frames in the air, every frame on the ground
  if (self.vspd & 0x02 || !gmBool(self.vspd)) {
    if (self.counter === 0x10) self.counter = 0xf1
    else self.counter = (self.counter + 1) & 0xff
    // 9820
    if (self.counter === 0xf8 && !(_RAND & 0x01) && self.cs & 0x04) {
      // --- JUMP -----
      self.vspd = 0xc5
      set_xy(self, self.x, self.y - 1)
    }
  }
  // 9837
  GO_update_cs(self)
  // 9B45
  let _carry = 0
  if (self.cs & 0x04 && self.vspd < 0x80) {
    // 9B50.  Landing
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  } else {
    // 9B53.  Moving Vertical
    _carry = updateY(self) ? 1 : 0
  }
  // MOD. Prevent clip into ceiling
  GO_vspd_update1(self)
  // 983A
  const _facingDir_COPY = self.facing_dir
  if (!gmBool(self.vspd)) {
    self.facing_dir = dir_to_pc(self)
    _carry = DC91_carry(self) ? 1 : 0
  }
  if (gmBool(self.vspd) || !(self.cs & 0x04)) {
    if (gmBool(self.vspd)) self.hspd = (0x10 * _facingDir_COPY) & 0xff
    else self.hspd = (0x10 * self.facing_dir) & 0xff
    _carry = updateX(self) ? 1 : 0
  }
  // 985C
  if (!(g.counter1 & 0x3f) && !(_RAND & 0x01)) {
    // 9869
    if (avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
      // Create Bullet2, pID $11. PI_MOB2: red
      GOC1_create(
        self.xl,
        _yt_PREV,
        self.facing_dir,
        self.projectile as ObjectName,
        self.projectile_ver,
        self,
        G.PI_MOB_RED,
      )
    } else {
      _carry = 1
    }
  }
  // 987F
  if (((self.counter + 8 + _carry) & 0xff) >= 0x10)
    self.BodyHB_idx = self.BODY_HB_IDX_SHRT // short
  else self.BodyHB_idx = self.BODY_HB_IDX_TALL // tall
  if (self.yt < cam_yb_max() + 0x18) {
    GOB_update_2a(self) // DE54 & DE63 collision
    if (!gmBool(self.pc_sword_collided_solid_body) && self.cs & CS_BD1) enemy_collide_pc_body(self)
  } else {
    GOB_despawn(self) // DD3D
  }
}

/** `Tektite_udp()` */
export function Tektite_udp(self: TektA): void {
  self.can_draw_self = true
  if (self.BodyHB_idx === self.BODY_HB_IDX_TALL)
    GO_set_sprite(self, dl(self).get(0) as string) // tall
  else GO_set_sprite(self, dl(self).get(1) as string) // short
  if (self.counter & 0x80) self.draw_yoff = self.counter ^ 0xff
  else self.draw_yoff = self.counter
}

/** `Tektite_draw()` */
export function Tektite_draw(self: TektA): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  draw_sprite_(self.Legs_sprite, 0, self.drawX, self.drawY - self.draw_yoff + self.legsYOff, -1, self.xScale)
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

registerScripts({ Tektite_init2, Tektite_update, Tektite_udp, Tektite_draw })
