/**
 * Falling-scene transition visuals: `qual_fall_scene`, `get_fall_scene_type`, `fall_scene_get_y_base`,
 * the stripe images ZALiA pre-rendered to surfaces in `p_Draw_1`, and `draw_falling_scene`.
 *
 * Surfaces don't exist in core: `fallSceneImage(type)` describes the stripes as rectangles and
 * `draw_falling_scene` pushes them as `rect` draw commands with the palette-swapped colours already
 * resolved (so no shader pass is needed for them). The 8×8 dithered stripe ends drawn from
 * `ts_Natural_1a_WRB` are not reproduced yet — needs a tile-part draw command (runtime owner).
 */
import {
  dk_can_draw,
  dk_PI,
  STR_Base,
  STR_Current,
  STR_Height,
  STR_Image,
  STR_PC,
  STR_ScaleX,
  STR_Type,
  STR_Width,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { bit1st } from '../../nes/math8'
import { p, world } from '../../runtime/world'
import { bgrToRgb, C_BLK1, C_BLU0, C_RED0, C_WHT0 } from './colors'
import {
  draw_pc_cucco_fall,
  draw_pc_skin,
  Gd,
  gd,
  is_exiting_ow,
  is_exiting_rm,
  pc_is_cucco,
  pcSeams,
  viewH,
  viewW,
  viewXC,
  viewYC,
  viewYT,
} from './deps'
import { get_pal_color } from './palString'
import { PI_BGR1, PI_PC1 } from './pi'
import { pal_swap_reset, pal_swap_set } from './scenePalette'

/** `qual_fall_scene()` */
export function qual_fall_scene(): boolean {
  const g = gd()
  const pc = Gd().pc
  const inactive = g.FallScene_timer === g.FallScene_INACTIVE
  const elev = pc.colliding_elevator as { exists?: boolean } | null | undefined
  return (
    (is_exiting_rm() &&
      inactive &&
      !!get_fall_scene_type() &&
      (elev === undefined || elev === null || !elev.exists)) ||
    (is_exiting_ow() && inactive && !!get_fall_scene_type() && Gd().OVERWORLD.enc_reen === undefined)
  )
}

/** `get_fall_scene_type()` — fall direction bits ($1 R, $2 L, $4 D, $8 U), one axis each. */
export function get_fall_scene_type(): number {
  const g = gd()
  let _direction: number | string = 0
  if (is_exiting_rm()) _direction = (g.exit_leave?.exit_type ?? 0) & g.FallScene_BITS
  else if (is_exiting_ow()) _direction = Gd().OVERWORLD.dm.val(`${hexStr(Gd().OVERWORLD.exit_owrc)}_CutScene`)
  if (typeof _direction === 'string') _direction = g.dm_cut_scene.val(`${_direction}_ID`) as number
  // Cannot have (both DOWN and UP) nor (both RIGHT and LEFT)
  _direction = (_direction >> g.FallScene_BITS_SHIFT) & 0xff
  return bit1st(_direction & (0x4 | 0x8)) | bit1st(_direction & (0x1 | 0x2))
}

/** `fall_scene_get_y_base()` */
export function fall_scene_get_y_base(): number {
  return viewYT() + (p.FallScene_dm.val(`${STR_Base}_Y`) as number)
}

export interface StripeRect {
  x: number
  y: number
  w: number
  h: number
  /** which base colour the stripe is drawn in (W/R/B), swapped by the fall scene's pi */
  base: 'W' | 'R' | 'B'
}
export interface FallSceneImage {
  width: number
  height: number
  stripes: StripeRect[]
}

/** The stripe layout `p_Draw_1` rendered into the type-1 (vertical, blue) / type-2 (horizontal, red) surfaces. */
export function fallSceneImage(type: '1' | '2'): FallSceneImage {
  const dm = p.FallScene_dm
  const _STRIPE_W = dm.val(`_Stripe${STR_Width}`, 8) as number
  const bases: ('W' | 'R' | 'B')[] = ['W', 'R', 'B']
  const _w1 = dm.val(`${type}${STR_Image}${STR_Width}`) as number
  const _h1 = dm.val(`${type}${STR_Image}${STR_Height}`) as number
  const stripes: StripeRect[] = []
  if (type === '1') {
    let _w = viewW()
    _w -= Math.trunc(_w / 3)
    _w -= 0x4 << 3 // adjustment
    const _x = (_w1 >> 1) - (_w >> 1)
    for (let i = Math.trunc(_h1 / _STRIPE_W) - 1; i >= 0; i--)
      stripes.push({ x: _x, y: _STRIPE_W * i, w: _w, h: _STRIPE_W, base: bases[i % 3] as 'W' })
  } else {
    let _h = viewH()
    _h -= Math.trunc(_h / 3)
    _h -= 0x4 << 3 // adjustment
    const _y = (_h1 >> 1) - (_h >> 1)
    for (let i = Math.trunc(_w1 / _STRIPE_W) - 1; i >= 0; i--)
      stripes.push({ x: _STRIPE_W * i, y: _y, w: _STRIPE_W, h: _h, base: bases[i % 3] as 'W' })
  }
  return { width: _w1, height: _h1, stripes }
}

/** `draw_falling_scene()` — background stripes (palette-resolved rects) and the falling PC. */
export function draw_falling_scene(depth = 0): void {
  const dm = p.FallScene_dm
  const type = String(dm.val(STR_Current + STR_Type, '1')) as '1' | '2'
  if (dm.get(`${type}${STR_Image}${STR_Width}`) !== undefined) {
    const img = fallSceneImage(type)
    let _x = viewXC() - ((dm.val(STR_Current + STR_Image + STR_Width) as number) >> 1)
    let _y = viewYC() - ((dm.val(STR_Current + STR_Image + STR_Height) as number) >> 1)
    const _pi = dm.val(STR_Current + dk_PI, PI_BGR1) as number
    const pal = p.pal_rm_curr || p.pal_rm_new
    const swapped = (base: string) =>
      bgrToRgb(pal ? get_pal_color(pal, _pi, base) : base === 'W' ? C_WHT0 : base === 'R' ? C_RED0 : C_BLU0)
    const bg = bgrToRgb(p.FallScene_BACKGROUND_COLOR)
    world.draw.push({
      kind: 'rect',
      x1: _x,
      y1: _y,
      x2: _x + img.width,
      y2: _y + img.height,
      color: bg,
      depth,
      alpha: 1,
      outline: false,
    })
    for (const s of img.stripes) {
      world.draw.push({
        kind: 'rect',
        x1: _x + s.x,
        y1: _y + s.y,
        x2: _x + s.x + s.w,
        y2: _y + s.y + s.h,
        color: swapped(s.base),
        depth,
        alpha: 1,
        outline: false,
      })
    }
    // Artifact fix from ZALiA (surface slivers): background bars just outside the image on the fall axis
    const _AMT1 = 0x8
    if (type === '1') {
      const _W = _AMT1 << 1
      const _H = img.height + (_AMT1 << 1)
      world.draw.push({
        kind: 'rect',
        x1: _x - _AMT1,
        y1: _y - _AMT1,
        x2: _x - _AMT1 + _W,
        y2: _y - _AMT1 + _H,
        color: bg,
        depth,
        alpha: 1,
        outline: false,
      })
      _x += img.width
      world.draw.push({
        kind: 'rect',
        x1: _x - _AMT1,
        y1: _y - _AMT1,
        x2: _x - _AMT1 + _W,
        y2: _y - _AMT1 + _H,
        color: bg,
        depth,
        alpha: 1,
        outline: false,
      })
    } else {
      const _W = img.width + (_AMT1 << 1)
      const _H = _AMT1 << 1
      world.draw.push({
        kind: 'rect',
        x1: _x - _AMT1,
        y1: _y - _AMT1,
        x2: _x - _AMT1 + _W,
        y2: _y - _AMT1 + _H,
        color: bg,
        depth,
        alpha: 1,
        outline: false,
      })
      _y += img.height
      world.draw.push({
        kind: 'rect',
        x1: _x - _AMT1,
        y1: _y - _AMT1,
        x2: _x - _AMT1 + _W,
        y2: _y - _AMT1 + _H,
        color: bg,
        depth,
        alpha: 1,
        outline: false,
      })
    }
  }
  // Draw PC and PC-Shadow
  if (dm.val(STR_PC + dk_can_draw)) {
    dm.set(STR_PC + dk_can_draw, 0)
    const _X_SCALE = dm.val(STR_Current + STR_ScaleX, -1) as number
    const _x = dm.val(`${STR_Current}_x`) as number
    const _y = dm.val(`${STR_Current}_y`) as number
    const _pi = dm.val(STR_PC + dk_PI, PI_PC1) as number
    if (pc_is_cucco()) {
      // cucco fall sprites: body/legs/wing shadow, then the palette-swapped trio and the eye pixel.
      // The sprite names and the eye colour live on `global.pc`, so this goes through the goa seam.
      draw_pc_cucco_fall(_x, _y + 8, _X_SCALE, _pi)
    } else {
      // `draw_falling_scene.gml:86-87` passes `global.pc.behavior_DAMAGE` (10), not a name, and the port's
      // untyped seam let the string `'DAMAGE'` through: `hex_str('DAMAGE')` cannot select a skin column.
      const _DAMAGE = pcSeams.behavior_DAMAGE
      draw_pc_skin(_x + 8, _y - 9, _X_SCALE, 1, _DAMAGE, false, -1, -1, -1, C_BLK1) // shadow
      pal_swap_set(_pi)
      draw_pc_skin(_x, _y, _X_SCALE, 1, _DAMAGE, false, -1, -1, _pi)
      pal_swap_reset()
    }
  }
}
