/**
 * The burnable-tile grids ZALiA keeps on the `BurnableMgr` object (`dg_RmTile_Burnable*`, `dg_Burnable`,
 * `scene_has_burnable`, `Burnable_pi`). `scene_enter_add_tiles` fills them; the future `BurnableMgr` port
 * should adopt this object as its state rather than redeclare the grids.
 */
import { BURNABLE_A, BURNABLE_B, BURNABLE_C } from '@z2/data'
import { DsGrid } from '../../runtime/ds'

export const burnableTiles = {
  BURNABLE_A,
  BURNABLE_B,
  BURNABLE_C,
  /** 8x8 room grid. Values represent burnables: (depth idx << 8) | BURNABLE_*. */
  dg_RmTile_Burnable: new DsGrid<number>(0, 0, 0),
  dg_RmTile_Burnable_def: new DsGrid<number>(0, 0, 0),
  /** Active burnables (9 rows of data per column). */
  dg_Burnable: new DsGrid<number>(0, 9, 0),
  scene_has_burnable: false,
  /** Palette index burnable tiles use; defaults to the scene's BURNABLE layer palette (else `p.PI_BGR4`). */
  Burnable_pi: -1,
}
