/**
 * Capper (ZALiA object `CappA`, parent `Enemy`; a purple Bot that lurks upside-down on the ceiling (v1) or on
 * the ground (v2) and drops/aggros when the player runs past). `Capper_init/update/udp/draw.gml`.
 */
import { ABL_JUMP, ABL_WALK, CS_BD1 } from '@z2/data'
import { byte, gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { dir_to_pc, dir_to_pc_ } from '../../../../go/misc'
import { set_xlyt, set_xy, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'
import { Bot_draw, Bot_init2, Bot_udp, Bot_update, BotObject } from '../bot/Bot'

export class CappA extends BotObject {
  readonly objectName = 'CappA' as const
  VSPD_BOUNCE = -0x20 & 0xff
  readonly ST_SUB1_LURK = 1
  readonly ST_SUB1_DROP = 2
  readonly ST_SUB1_ATCK = 3
  sub_state = 1
  AGRO_DIST = 0x06 << 3
  DRAW_YOFF_FLIPPED = 2
  yy_ceil = 0
}

/** `Capper_init()` */
export function Capper_init(self: CappA): void {
  // v1. Waits UPSIDE-DOWN on ceiling and falls on PC when w/in range
  // v2. Waits RIGHTSIDE-UP on ground and aggros when w/in range
  Bot_init2(self)
  GO_init_palidx(self, G.PI_MOB_PUR)
  self.VSPD_BOUNCE = -0x20 & 0xff
  self.abilities = ABL_WALK
  self.abilities |= ABL_JUMP
  self.sub_state = self.ST_SUB1_LURK
  self.AGRO_DIST = 0x06 << 3
  self.DRAW_YOFF_FLIPPED = 2
  self.yy_ceil = (self.yt >> 3) << 3
  switch (self.ver) {
    case 1:
      self.AGRO_DIST = 0x06 << 3
      self.DRAW_YOFF_FLIPPED = 2
      self.yy_ceil = (self.yt >> 3) << 3
      set_xlyt(self, self.xl, self.yy_ceil - (self.DRAW_YOFF_FLIPPED + 1))
      break
    case 2:
      self.AGRO_DIST = 0x06 << 3
      break
  }
}

/** `Capper_update()` */
export function Capper_update(self: CappA): void {
  const P = pc()
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return
  }
  switch (self.sub_state) {
    case self.ST_SUB1_LURK: {
      GO_update_cs(self)
      GOB_update_2(self) // DE40
      if (self.cs & CS_BD1) enemy_collide_pc_body(self) // E2EF
      if (gmBool(P.hspd) && P.hspd_dir === -dir_to_pc_(self) && Math.abs(P.x - self.x) <= self.AGRO_DIST) {
        switch (self.ver) {
          case 1:
            self.sub_state = self.ST_SUB1_DROP
            break
          case 2:
            self.sub_state = self.ST_SUB1_ATCK
            break
        }
      }
      break
    }
    case self.ST_SUB1_DROP: {
      updateY(self)
      GO_update_cs(self)
      GOB_update_2(self) // DE40
      if (self.cs & CS_BD1) enemy_collide_pc_body(self) // E2EF
      if (self.cs & 0x4) {
        set_xy(self, self.x, (self.y >> 3) << 3)
        self.facing_dir = dir_to_pc(self)
        self.hspd = byte(self.hspd_jump * self.facing_dir)
        self.vspd = self.VSPD_BOUNCE
        self.sub_state = self.ST_SUB1_ATCK
      }
      break
    }
    case self.ST_SUB1_ATCK:
      Bot_update(self)
      break
  }
}

/** `Capper_udp()` */
export function Capper_udp(self: CappA): void {
  Bot_udp(self)
  self.can_draw_self = true
  switch (self.sub_state) {
    case self.ST_SUB1_LURK:
      GO_set_sprite(self, g.counter1 & 0xc ? self.SPR_NORM : self.SPR_BALL)
      switch (self.ver) {
        case 1:
          self.yScale = -1
          break
        case 2:
          self.yScale = 1
          break
      }
      break
    case self.ST_SUB1_DROP:
      GO_set_sprite(self, self.SPR_BALL)
      // GML `!yScale` — -1 is falsy under GML truthiness
      if (self.yt - self.yy_ceil < 8 && !gmBool(self.yScale)) self.yScale = -1
      else self.yScale = 1
      break
    case self.ST_SUB1_ATCK:
      self.yScale = 1
      break
  }
  if (!gmBool(self.yScale)) self.draw_yoff = self.DRAW_YOFF_FLIPPED
  else self.draw_yoff = 0
  if (self.sub_state === self.ST_SUB1_LURK || self.sub_state === self.ST_SUB1_DROP) {
    if (self.spr_eyes) self.spr_eyes = self.SPR_EYE1
    self.eyes_yoff = self.sprite === self.SPR_BALL ? -2 : 0
    self.eyes_yoff *= self.yScale
    self.mouth_yoff = self.sprite === self.SPR_BALL ? 1 : 3
    self.mouth_yoff *= self.yScale
    if (!gmBool(self.yScale)) self.mouth_yoff -= 2
  }
}

/** `Capper_draw()` */
export function Capper_draw(self: CappA): void {
  Bot_draw(self)
}

registerObject('CappA', CappA)
registerScripts({ Capper_init, Capper_update, Capper_udp, Capper_draw })
