export class Helmethead01 extends BossObject {
  override readonly objectName = 'Helmethead01' as const
  BodyHB_IDX2: any = undefined
  CEILING_Y: any = undefined
  Head_COUNT: any = undefined
  Head_DURATION1: any = undefined
  Head_DURATION2: any = undefined
  Head_DURATION3: any = undefined
  Head_num: any = undefined
  Head_spawn_timer: any = undefined
  Head_sprite: any = undefined
  Head_xoff: any = undefined
  Head_xscale: any = undefined
  Head_yoff: any = undefined
  Legs_sprite: any = undefined
  dl_Head_SPRITES: any = undefined
  is_from_HelmetHead: any = undefined
}

/** GML: Helmethead_init1() */
export function Helmethead_init1(self: Helmethead01) {
  Boss_init_1(self)
  Boss_set_MusicBattle_props(self, `${STR_Boss}01`)
}

/** GML: Helmethead_init2() */
export function Helmethead_init2(self: Helmethead01) {
  let _i: any, _a: any, _COUNT: any, _CLMS1: any, _CLMS2: any, _CLM: any, _dl_CLM: any

  Boss_init_2(self)
  Boss_init_2b(self, -1) // Determine & set the side of the arena to start on.
  GO_init_palidx(self, G.PI_MOB_BLU)
  self.dl_Head_SPRITES = ds_list_create()
  ds_list_add(self.dl_Head_SPRITES, 'spr_Helmethead_head_1')
  ds_list_add(self.dl_Head_SPRITES, 'spr_Helmethead_head_2')
  if (gmBool(g.mod_HelmetHead_MoreHead)) {
    ds_list_add(self.dl_Head_SPRITES, 'spr_Helmethead_head_4') // 4: Added Content: Extra head
  }
  ds_list_add(self.dl_Head_SPRITES, 'spr_Helmethead_head_3') // Last head. No helmet
  self.Head_sprite = self.dl_Head_SPRITES.get(0)
  self.Head_COUNT = ds_list_size(self.dl_Head_SPRITES)
  self.Head_num = 1 // 0081[eIndex]
  self.Head_DURATION1 = 0x10 // OG
  self.Head_DURATION2 = self.Head_DURATION1 + 0x10 // $20. MOD. For f.quest_num==1
  self.Head_DURATION3 = self.Head_DURATION2 + 0x18 // $38. MOD. For f.quest_num==2
  self.Head_spawn_timer = 0 // 05DE
  self.Head_xoff = 0
  self.Head_yoff = 0
  self.Head_xscale = 1
  self.Legs_sprite = 'spr_Boss_legs1A'
  self.projectile_OBJ = 'Bullet1'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  // HelmetHead doesn't have a melee attack so
  // attack_state is here just so Boss_update_3a()
  // doesn't crash the game when it doesn't find the variable
  self.attack_state = 0
  self.CEILING_Y = g.rm_rows - PAGE_ROWS + 0x06
  self.CEILING_Y =
    find_row_solid(TID_SOLID1, self.arena_x >> 3, (self.GROUND_Y >> 3) - 1, -1, 0, self.CEILING_Y) + 1 // search for ceiling
  self.CEILING_Y = self.CEILING_Y << 3
  self.DISTANCE1 = 0x20
  // body hb
  self.BodyHB_color = c_blue
  self.BodyHB_IDX2 = self.BodyHB_IDX + 1
  // shield hb
  self.ShieldHB_color = c_white
  self.ShieldHB_IDX = 3
  self.ShieldHB_idx = self.ShieldHB_IDX
  if (f.quest_num > 1) {
    // 1st quest: $11: $28
    self.HP_IDX = 0x16 // $16: $60
    //HP_IDX  = $14; // $14: $48
    //HP_IDX  = $1B; // $1B: $C0
    self.hp = g.dl_HP.get(self.HP_IDX) as number
    self.XP_IDX = 0x1a
    //XP_IDX  = $1D;
    self.xp = g.dl_XP.get(self.XP_IDX) as number
    self.ATTACK_LEVEL = 0x06
    self.attack_level = self.ATTACK_LEVEL
    // Drop Spawner(s)
    _COUNT = clamp(1, 0, 4)
    if (gmBool(_COUNT)) {
      _CLMS1 = 0x07
      _CLMS2 = 0x15
      _CLM = self.arena_x >> 3
      _dl_CLM = ds_list_create()
      ds_list_add(_dl_CLM, _CLM - _CLMS2 - 1)
      ds_list_add(_dl_CLM, _CLM - _CLMS1 - 1)
      ds_list_add(_dl_CLM, _CLM + _CLMS1 - 1)
      ds_list_add(_dl_CLM, _CLM + _CLMS2 - 1)
      //ds_list_add(    _dl_CLM, $1A, $28, $36, $44);
      ds_list_shuffle(_dl_CLM)
      for (_i = 0; _i < _COUNT; _i++) {
        GameObject_create(_dl_CLM.get(_i) << 3, self.CEILING_Y, 'SpDrA', 1)
      }
      ds_list_destroy(_dl_CLM)
      _dl_CLM = undefined
    }
  }
  set_xy(self, self.x, self.GROUND_Y - self.hh_)
}

/** GML: Helmethead_update() */
export function Helmethead_update(self: Helmethead01) {
  let _C1: any, _TIMING: any

  // D250,   D254
  self.SwordHB_collidable = false
  self.SwordHB_yoff = 0
  // BAC3,   BACB: JSR BE8B
  // check battle start/end/qualify
  if (!gmBool(Boss_update_1(self))) {
    update_EF11(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // ------------------------------------------------------------
  // BAD1,   BADA: JSR BB71,   BB71: JSR 9C45
  Boss_HPBar_udp(self)
  // Arena gate
  if (!gmBool(Boss_update_4(self))) {
    update_EF11(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // MOD. Delay 1st attack -----------------------------------------------
  if (gmBool(self.start_timer)) {
    self.start_timer--
    update_EF11(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // ------------------------------------------------------------
  //        g.mod_HelmetHead_Vulnerability: Only vulnerable once new head fully grown
  _C1 = gmBool(g.mod_HelmetHead_Vulnerability) && gmBool(self.Head_spawn_timer)
  if (gmBool(_C1)) {
    self.BodyHB_idx = self.BodyHB_IDX2
  } else {
    self.BodyHB_idx = self.BodyHB_IDX
  }
  if (gmBool(_C1)) {
    self.react_sword = 0
  } else {
    self.react_sword = self.REACT_SWORD
  }
  // BACE: JSR BC4E.  EF11,hspdPB,updateX,shld coll,cs,DE40.dmg pc,death check
  Boss_update_2(self)
  if (gmBool(self.pending_death)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // ------------------------------------------------------------
  // BB74.  facing_dir,hspd,counter,behavior
  Boss_update_3(self)
  Boss_Roar_update(self)
  // BADD
  if (gmBool(self.Head_spawn_timer)) {
    _TIMING = 0xff
  } else {
    _TIMING = 0x7f
  }
  if (!gmBool(g.counter1 & _TIMING) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
    // BAE3: JSR DBCE
    /* TODO with */ {
      const _w1: any = GOC1_create(
        self.xl,
        self.yt - 9,
        self.facing_dir,
        self.projectile as ObjectName,
        self.projectile_ver,
        self,
        G.PI_MOB_RED,
      )
      if (_w1) {
        _w1.vspd = 2
        _w1.pal_flash_time = 1
        _w1.ATTACK_LEVEL = 4
        _w1.attack_level = _w1.ATTACK_LEVEL
      }
    }
  }
  // BAFA
  if (gmBool(self.Head_spawn_timer)) {
    // BB55
    if (!gmBool(g.counter1 & 0x03)) {
      self.Head_spawn_timer--
    }
  } /* BAFF */ else {
    if (gmBool(self.cs & CS_SW1) && self.Head_num < self.Head_COUNT) {
      // g.mod_HelmetHead_Vulnerability: Only vulnerable once new head fully grown
      if (gmBool(g.mod_HelmetHead_Vulnerability)) {
        self.Head_spawn_timer = self.Head_DURATION2
      } /* Head_DURATION2 = $20 */ else {
        self.Head_spawn_timer = self.Head_DURATION1 // Head_DURATION1 = $10
      }
      if (gmBool(g.mod_Quest2BossDifficulty) && f.quest_num > 1) {
        self.Head_spawn_timer += 0x18 // $28 or $38
      }
      // g.mod_HelmetHead_Vulnerability: Only vulnerable once new head fully grown
      if (gmBool(g.mod_HelmetHead_Vulnerability)) {
        // Do only a little damage
        self.hp = g.dl_HP.get(self.HP_IDX) as number
        self.hp -= min(3, G.pc.dl_ATTACK_DAMAGE[f.level_atk] ?? 0) * self.Head_num
      }
      // BB10: JSR B869,  B876
      // Spawn Head ----------------------------------------------
      /* TODO with */ {
        const _w2: any = GameObject_create(self.xl, self.yt - 0x0d, 'HelmetheadHead01', 1)
        if (_w2) {
          _w2.state = _w2.state_NORMAL
          _w2.facing_dir = self.facing_dir
          GO_set_sprite(_w2, self.dl_Head_SPRITES.get(self.Head_num - 1))
          _w2.HP_IDX = 0x1c // g.dl_HP.get(|$1C) = $D8
          _w2.hp = g.dl_HP.get(_w2.HP_IDX) as number
          _w2.stun_timer = 0
          _w2.counter = 0
          _w2.hspd = (0x10 * -_w2.facing_dir) & 0xff
          _w2.hspd_dir = sign_(_w2.hspd < 0x80)
          _w2.vspd = 0xd0
          _w2.vspd_dir = sign_(_w2.vspd < 0x80)
          _w2.is_from_HelmetHead = true
        }
      }
      // BB52
      self.Head_num++
    }
  }
}

/** GML: Helmethead_udp() */
export function Helmethead_udp(self: Helmethead01) {
  // BD75
  self.can_draw_self = true
  // BD7D
  if (inRange(self.counter & 0x07, 0x03, 0x05)) {
    self.Legs_sprite = 'spr_Boss_legs1B'
  } else {
    self.Legs_sprite = 'spr_Boss_legs1A' // open
  }
  // BD98
  self.Head_sprite = self.dl_Head_SPRITES.get(self.Head_num - 1)
  if (!gmBool(self.pending_death)) {
    self.Head_xscale = dir_to_pc(self)
  }
  // 4: Added Content: Extra head
  if (self.Head_sprite === 'spr_Helmethead_head_4') {
    self.Head_xoff = -self.Head_xscale
  } else {
    self.Head_xoff = 0
  }
  self.Head_yoff = -7 + -12 + min(self.Head_spawn_timer, 0x10) // when $10 frames to go
}

/** GML: Helmethead_draw() */
export function Helmethead_draw(self: Helmethead01) {
  if (!gmBool(self.can_draw_self)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  pal_swap_set(self.palidx)
  draw_sprite_(
    self.Head_sprite,
    0,
    self.drawX + self.Head_xoff,
    self.drawY + self.Head_yoff,
    -1,
    self.Head_xscale,
  )
  GO_draw_sprite(self, self.sprite)
  GO_draw_sprite(self, self.Legs_sprite)
  pal_swap_reset()
}

