/**
 * Town-location rando — ported from `Rando_randomize_town_locations.gml` (523 lines).
 *
 * The eight towns are shuffled against their overworld locations: `_town_name2` moves into the overworld
 * spot that vanilla `_town_name1` occupied. Everything else in the script re-wires the exits so the swap
 * is seamless:
 * - `STR_Town+STR_Rando+<town>+"A"/"B"` — the two directions of the mapping.
 * - the fast-travel tunnel pair (`_FastTravel_Exit` "A"/"B") is re-linked and opened/closed.
 * - the backside-house exits (`_Backside_Exit` "A".."D") are re-linked, flipping the link when both exits
 *   face the same way, and the inside-house scene file is swapped between the single/double variants.
 * - the town's left/right overworld entrances (`_Rando_Town_End_Exit_Right/_Left`) are re-pointed, and
 *   `hex_str(owrc1)+hex_str(dir)+STR_Exit` records which town exit each overworld approach direction lands on.
 * - every `_TownA_` scene of `_town_name2` gets `_OWRC` = town1's overworld coordinate and
 *   `_Overworld_Town_Name` = town1, unless the scene is flagged `_Rando_LandLocked`.
 *
 * Dropped:
 * - the `if (0){…}` sign-dialogue block at `:492-500` (would need `g.DIALOGUE_WINDOW`, never runs).
 * - the `_Z1/_Z2/_Z3/_z1/_z2/_z3` DEV `show_debug_message` blocks (`:46-56`, `:94`, `:109-131`,
 *   `:166-215`, `:306-347`, `:368-375`) — every one of those flags is a `var … = false` literal.
 *   The `if (DEBUG)` blocks at `:24-27` and `:503-518` are the spoiler log and are kept verbatim.
 * - dead stores `_exit_name1/_exit_name2` (`:137-138`, overwritten at `:439-440` before any read) and the
 *   exit reads whose only consumers were those DEV prints (`_exit_name1a`/`_exit_name2b` of the
 *   fast-travel block, `_exit_name2b`/`_exit_name2d` of the town-end block).
 * - `_map_area_name1`/`_map_area_name2` (`:97-98`) — their only consumer is the commented-out `:481`.
 * - `_owrc2` (`:82-93`) — computed for every pair but only ever printed by the dead `_Z3` line at `:94`.
 *
 * GML quirks: `_datakey3` (`:236`) is never `var`-declared, so ZALiA leaks it onto the `Rando` instance;
 * it is a plain local here. `dg_1` (`:424-435`) is `ds_grid_resize`d to 2x2 scratch holding exit *names*
 * while `Rando.dg_1` is typed `DsGrid<number>` and the port's `DsGrid` has no resize — it is a local grid
 * here (nothing reads it outside the iteration).
 */
import {
  Area_OvrwA,
  Area_TownA,
  dk_FastTravel,
  dk_FileName,
  dk_LandLocked,
  OWRC_DFL,
  RmName_LEN,
  STR_Bulblin,
  STR_Darunia,
  STR_Exit,
  STR_Game,
  STR_goto_reen,
  STR_Mido,
  STR_Nabooru,
  STR_Name,
  STR_New_Kasuto,
  STR_Num,
  STR_Old_Kasuto,
  STR_Open,
  STR_Overworld,
  STR_OWRC,
  STR_Quest,
  STR_Rando,
  STR_Rauru,
  STR_Rm,
  STR_Ruto,
  STR_Saria,
  STR_Town,
} from '@z2/data'
import { DsGrid } from '../../runtime/ds'
import { g, world } from '../../runtime/world'
import { gmNum } from '../file/json'
import { gmBool } from '../math/index'
import { hex_str, str_hex, val } from '../other/index'
import {
  debugBlank,
  debugLine,
  ds_list_copy,
  ds_list_shuffle,
  isVal,
  string_copy,
  string_pos,
  string_repeat,
} from './helpers'
import type { Rando } from './Rando'

/** The `switch(_town_name)` → `g.OWRC_TOWN_*` tables at `:70-93`. */
function town_owrc(_town_name: string): number {
  switch (_town_name) {
    case STR_Rauru:
      return g.OWRC_TOWN_RAUR1 as number
    case STR_Ruto:
      return g.OWRC_TOWN_RUTO1 as number
    case STR_Saria:
      return g.OWRC_TOWN_SARI1 as number
    case STR_Mido:
      return g.OWRC_TOWN_MIDO1 as number
    case STR_Nabooru:
      return g.OWRC_TOWN_NABO1 as number
    case STR_Darunia:
      return g.OWRC_TOWN_DARU1 as number
    case STR_New_Kasuto:
      return g.OWRC_TOWN_NEWK1 as number
    case STR_Old_Kasuto:
      return g.OWRC_TOWN_OLDK1 as number
    case STR_Bulblin:
      return g.OWRC_TOWN_BULB1 as number
    default:
      return OWRC_DFL
  }
}

export function Rando_randomize_town_locations(self: Rando): void {
  if (self.DEBUG) {
    debugBlank(self, 3)
    debugLine(self, '--- TOWN LOCATION RANDO ---')
  }

  world.random_set_seed(self.Rando_SEED)

  self.dl_list1.clear()
  self.dl_list1.add(STR_Rauru)
  self.dl_list1.add(STR_Ruto)
  self.dl_list1.add(STR_Saria)
  self.dl_list1.add(STR_Mido)
  self.dl_list1.add(STR_Nabooru)
  self.dl_list1.add(STR_Darunia)
  self.dl_list1.add(STR_New_Kasuto)
  self.dl_list1.add(STR_Old_Kasuto)
  //ds_list_add(dl_list1,STR_Bulblin);

  ds_list_copy(self.dl_list2, self.dl_list1)
  ds_list_shuffle(self.dl_list2)

  const _dl_list1_COUNT = self.dl_list1.size
  for (let _i = 0; _i < _dl_list1_COUNT; _i++) {
    const _town_name1 = self.dl_list1.get(_i) as string // The overworld location for _town_name2
    const _town_name2 = self.dl_list2.get(_i) as string // What will inhabit the _town_name1's overworld location

    // "A": Get what the overworld town is for _town_name2
    self.dm_save_data.set(`${STR_Town + STR_Rando + _town_name2}A`, _town_name1)
    // "B": Get what town inhabits the overworld town of _town_name1
    self.dm_save_data.set(`${STR_Town + STR_Rando + _town_name1}B`, _town_name2)

    if (_town_name1 !== _town_name2) {
      const _owrc1 = town_owrc(_town_name1)

      // ---------------------------------------------------------------------------
      // ---------------------------------------------------------------------------
      {
        const _datakey1 = dk_FastTravel + STR_Exit
        // "B": exit-leave fast-travel-tunnel
        const _exit_name1b = g.dm_rm.get(`${_town_name1}${_datakey1}B`) as string | undefined
        // "A": exit-enter fast-travel-tunnel
        const _exit_name2a = g.dm_rm.get(`${_town_name2}${_datakey1}A`) as string | undefined

        if (_exit_name2a !== undefined) {
          if (_exit_name1b !== undefined) {
            self.dm_save_data.set(_exit_name2a + STR_goto_reen, _exit_name1b)
            self.dm_save_data.set(_exit_name1b + STR_goto_reen, _exit_name2a)
            self.dm_save_data.set(_exit_name2a + STR_Open, gmNum(true))
          }

          if (_exit_name1b === undefined) {
            self.dm_save_data.set(_exit_name2a + STR_Open, gmNum(false))
          }
        }
      }

      // ---------------------------------------------------------------------------
      // ---------------------------------------------------------------------------
      // a-b are linked, c-d are linked
      {
        const _datakey1 = `_Backside${STR_Exit}`

        // front door - enter house. linked to ("B")
        const _exit_name1a = g.dm_rm.get(`${_town_name1}${_datakey1}A`) as string | undefined
        // front door - leave house. linked to ("A")
        const _exit_name1b = g.dm_rm.get(`${_town_name1}${_datakey1}B`) as string | undefined
        //  back door - leave house. linked to ("D")
        const _exit_name1c = g.dm_rm.get(`${_town_name1}${_datakey1}C`) as string | undefined
        //  back door - enter house. linked to ("C")
        const _exit_name1d = g.dm_rm.get(`${_town_name1}${_datakey1}D`) as string | undefined

        const _exit_name2a = g.dm_rm.get(`${_town_name2}${_datakey1}A`) as string | undefined
        const _exit_name2b = g.dm_rm.get(`${_town_name2}${_datakey1}B`) as string | undefined
        const _exit_name2c = g.dm_rm.get(`${_town_name2}${_datakey1}C`) as string | undefined
        const _exit_name2d = g.dm_rm.get(`${_town_name2}${_datakey1}D`) as string | undefined

        if (
          _exit_name1a !== undefined &&
          _exit_name1b !== undefined &&
          _exit_name1c !== undefined &&
          _exit_name1d !== undefined &&
          _exit_name2a !== undefined &&
          _exit_name2b !== undefined &&
          _exit_name2c !== undefined &&
          _exit_name2d !== undefined
        ) {
          // true: _town_name1 has a backside because exit-d is set to exit-b or exit-c if there's no backside
          const _val1 = !isVal(_exit_name1d, _exit_name1b, _exit_name1c)
          // true: _town_name2 has a backside because exit-d is set to exit-b or exit-c if there's no backside
          const _val2 = !isVal(_exit_name2d, _exit_name2b, _exit_name2c)

          if (_val1 !== _val2) {
            // if only 1 of these 2 towns has a backside
            const _rm_name2 = string_copy(_exit_name2b, 1, RmName_LEN)
            const _datakey2 = _rm_name2 + dk_FileName + STR_Quest
            const _datakey3 = _datakey2 + hex_str(self.QUEST_NUM)
            // _town_name2's inside house. `val(x, dflt)` returns the default verbatim, undefined included.
            let _file_name2 = g.dm_rm.get(`${_datakey2}01`) as string | undefined
            _file_name2 = (g.dm_rm.get(_datakey3) as string | undefined) ?? _file_name2
            let _file_name: string | undefined // what _town_name2 will use for rando
            if (_file_name2 !== undefined) {
              if (_val1)
                _file_name = 'TownA_086' // double
              else _file_name = 'TownA_066' // single

              switch (_file_name2) {
                case 'TownA_064':
                  if (_val1) _file_name = 'TownA_065'
                  break // single to double
                case 'TownA_065':
                  if (!_val1) _file_name = 'TownA_064'
                  break // double to single
                case 'TownA_089':
                  if (_val1) _file_name = 'TownA_086'
                  break // single to double
                case 'TownA_086':
                  if (!_val1) _file_name = 'TownA_069'
                  break // double to single
                case 'TownA_066':
                  if (_val1) _file_name = 'TownA_086'
                  break // single to double
                case 'TownA_069':
                  if (_val1) _file_name = 'TownA_086'
                  break // single to double
              }
              //RAUR - TownA_41 - area_TA+'064' - area_TA+'065'
              //RUTO - TownA_42 - area_TA+'086' - area_TA+'066'
              //SARI - TownA_46 - area_TA+'066' - area_TA+'086'
              //MIDO - TownA_6F - area_TA+'089' - area_TA+'086'
              //NABO - TownA_49 - area_TA+'086' - area_TA+'066'
              //DARU - TownA_4A - area_TA+'064' - area_TA+'065'
              //NEWK - TownA_4C - area_TA+'064' - area_TA+'065'
              //OLDK - TownA_4F - area_TA+'064' - area_TA+'065'

              if (_file_name !== undefined) {
                self.dm_save_data.set(_datakey3, _file_name)
              }
            }
          }

          if (_val1) {
            // if _town_name1 has a backside
            const _dir1 = str_hex(_exit_name1d.charAt(_exit_name1d.length - 2))
            const _dir2 = str_hex(_exit_name2c.charAt(_exit_name2c.length - 2))
            if (
              (_dir1 & 0x3) !== 0 && // right or left exit
              _dir1 === _dir2 // linked exit is same dir. This makes it look awkward when you enter a room from the opposite side you exited previous room
            ) {
              // Flipping exit links here so it doesn't look awkward.
              self.dm_save_data.set(_exit_name2a + STR_goto_reen, _exit_name2c)
              self.dm_save_data.set(_exit_name2c + STR_goto_reen, _exit_name2a)

              self.dm_save_data.set(_exit_name2b + STR_goto_reen, _exit_name1d)
              self.dm_save_data.set(_exit_name1d + STR_goto_reen, _exit_name2b)
            } else {
              self.dm_save_data.set(_exit_name2c + STR_goto_reen, _exit_name1d)
              self.dm_save_data.set(_exit_name1d + STR_goto_reen, _exit_name2c)
            }

            self.dm_save_data.set(_exit_name2a + STR_Open, gmNum(true))
          }
        }
      }

      // ---------------------------------------------------------------------------
      // ---------------------------------------------------------------------------
      // a-b are linked, c-d are linked
      const _datakey1 = `${STR_Rando + STR_Town}_End${STR_Exit}`

      const _exit_name1a = g.dm_rm.get(`${_town_name1 + _datakey1}_Right`) as string | undefined
      const _exit_name1b = g.dm_rm.get(String(val(_exit_name1a)) + STR_goto_reen) as string | undefined

      const _exit_name1c = g.dm_rm.get(`${_town_name1 + _datakey1}_Left`) as string | undefined
      const _exit_name1d = g.dm_rm.get(String(val(_exit_name1c)) + STR_goto_reen) as string | undefined

      const _exit_name2a = g.dm_rm.get(`${_town_name2 + _datakey1}_Right`) as string | undefined
      const _exit_name2c = g.dm_rm.get(`${_town_name2 + _datakey1}_Left`) as string | undefined

      const _datakey2 = dk_FileName + STR_Quest + hex_str(self.QUEST_NUM)
      switch (_town_name2) {
        case STR_New_Kasuto:
          if (_exit_name2a !== undefined) {
            self.dm_save_data.set(string_copy(_exit_name2a, 1, RmName_LEN) + _datakey2, 'TownA_028')
          }
          break
      }

      for (let _j = 0; _j < 4; _j++) {
        // each pc move dir($1,2,4,8)
        const _dir = 0x1 << _j // pc movement dir when entering town from overworld. $1,2,4,8
        const _dk = hex_str(_owrc1) + hex_str(_dir) + STR_Exit

        if (_dir === 0x1 || _dir === 0x4) {
          // _dir=$1: moving right / approaching town from its left
          // _dir=$4: moving down  / approaching town from its top
          if (
            _exit_name2c !== undefined && // town's "_Left" entrance
            (_exit_name1d === undefined || string_pos(Area_OvrwA, _exit_name1d) !== 0)
          ) {
            self.dm_save_data.set(_dk, _exit_name2c)
            continue //_j
          }

          if (
            _exit_name2a !== undefined && // town's "_Right" entrance
            (_exit_name1b === undefined || string_pos(Area_OvrwA, _exit_name1b) !== 0)
          ) {
            self.dm_save_data.set(_dk, _exit_name2a)
          }
        } else {
          // _dir=$2: moving left / approaching town from its right
          // _dir=$8: moving up   / approaching town from its bottom
          if (
            _exit_name2a !== undefined && // town's "_Right" entrance
            (_exit_name1b === undefined || string_pos(Area_OvrwA, _exit_name1b) !== 0)
          ) {
            self.dm_save_data.set(_dk, _exit_name2a)
            continue //_j
          }

          if (
            _exit_name2c !== undefined && // town's "_Left" entrance
            (_exit_name1d === undefined || string_pos(Area_OvrwA, _exit_name1d) !== 0)
          ) {
            self.dm_save_data.set(_dk, _exit_name2c)
          }
        }
      }

      const _dg_1 = new DsGrid<string | undefined>(2, 2, undefined)
      // "_Right"
      _dg_1.set(0, 0, _exit_name1b)
      _dg_1.set(0, 1, _exit_name2a)
      // "_Left"
      _dg_1.set(1, 0, _exit_name1d)
      _dg_1.set(1, 1, _exit_name2c)

      for (let _j = _dg_1.width - 1; _j >= 0; _j--) {
        const _exit_name1 = _dg_1.get(_j, 0)
        const _exit_name2 = _dg_1.get(_j, 1)

        if (_exit_name2 !== undefined) {
          if (_exit_name1 !== undefined) {
            if (string_pos(Area_OvrwA, _exit_name1) === 0) {
              self.dm_save_data.set(_exit_name1 + STR_goto_reen, _exit_name2)
            }
            self.dm_save_data.set(_exit_name2 + STR_goto_reen, _exit_name1)
          }

          if (_exit_name1 === undefined || string_pos(Area_OvrwA, _exit_name1) !== 0) {
            // `_exit_name2+STR_OWRC` value for this datakey is the owrc _exit_name2 will take you to.
            self.dm_save_data.set(_exit_name2 + STR_OWRC, _owrc1)
          }
        }
      }

      // ---------------------------------------------------------------------------
      // ---------------------------------------------------------------------------
      for (let _j = 0; _j < 0x100; _j++) {
        // Each town scene
        const _rm_name2 = Area_TownA + hex_str(_j)
        if (g.dm_rm.get(_rm_name2 + STR_Rm + STR_Num + STR_Game) !== undefined) {
          // if _rm_name2 exists
          const _town_name = g.dm_rm.get(_rm_name2 + STR_Town + STR_Name) as string | undefined
          if (
            _town_name !== undefined &&
            _town_name === _town_name2 &&
            !gmBool(val(g.dm_rm.get(_rm_name2 + STR_Rando + dk_LandLocked)) as number)
          ) {
            self.dm_save_data.set(_rm_name2 + STR_OWRC, _owrc1)
            self.dm_save_data.set(_rm_name2 + STR_Overworld + STR_Town + STR_Name, _town_name1)
          }
        }
      }
    }

    if (self.DEBUG) {
      let debug_str = _town_name1
      //debug_str  = "OW "+_town_name1;
      debug_str += string_repeat(' ', STR_Old_Kasuto.length - _town_name1.length)
      debug_str += ` - ${_town_name2}`
      debug_str += string_repeat(' ', STR_Old_Kasuto.length - _town_name2.length)
      debug_str += ` (${_town_name2}`
      debug_str += string_repeat(' ', STR_Old_Kasuto.length - _town_name2.length)
      debug_str += ' inhabits '
      debug_str += _town_name1
      debug_str += string_repeat(' ', STR_Old_Kasuto.length - _town_name1.length)
      debug_str += ' vanilla overworld location)'
      debugLine(self, debug_str)
      debugBlank(self, 1)
    }
  }
}
