/** Cucco-form scripts: `PC_udp_cucco`, `PC_draw_get_cucco_rot`, `PC_cucco_fury_update` (unfinished in ZALiA). */
import { gmBool, isVal, gmRound as round } from '../../../nes/math8'
import { NOONE, type Ref } from '../../../runtime/instance'
import { f, g, world } from '../../../runtime/world'
import { viewH, viewH_, viewW, viewW_, viewXC, viewXL, viewYC, viewYT } from '../../collision/env'
import { rectInRect, rectInView } from '../../collision/geometry'
import { sign_ } from '../../math/index'
import { Enemy, type GameObject } from '../classes'
import { damage_gob } from '../gob/GameObjectB'
import type { Lonk } from './Lonk'

export function PC_udp_cucco(self: Lonk): void {
  const _CROUCHING = !!self.Cucco_crouching_state
  const _HEAD_FWRD = !!self.hspd && self.walk_frame === 0 // af_walk==0: LEGS WIDE
  let _ATTACKING = false
  switch (self.Draw_behavior) {
    case self.behavior_STAB_STAND:
    case self.behavior_STAB_CROUCH:
      _ATTACKING = true
      break
    case self.behavior_STAB_DOWN:
      _ATTACKING = gmBool(g.CUCCO_CAN_THRUST_D) && !!(f.Cucco_skills & f.CuccoSkill_THRUST_D)
      break
    case self.behavior_STAB_UP:
      _ATTACKING = gmBool(g.CUCCO_CAN_THRUST_U) && !!(f.Cucco_skills & f.CuccoSkill_THRUST_U)
      break
  }
  self.draw_yoff = 0
  self.Cucco_disguise_sprite = 0
  if (self.Disguise_enabled) {
    const _IDX = g.counter1 & 0x10 ? 0 : 1
    self.Cucco_disguise_sprite =
      self.dg_Cucco_DISGUISE_SPRITES.get(self.dg_Cucco_DISGUISE_SPRITES_idx1, _IDX) ?? 0
    self.Cucco_sprite_body = self.Cucco_disguise_sprite
    return
  }
  if (self.Draw_behavior === self.behavior_DAMAGE) {
    self.Cucco_sprite_body = 'spr_chicken_1a_damage_1a'
    return
  }
  self.Cucco_eye_can_draw = true
  self.Cucco_eye_xoff = 2
  self.Cucco_eye_yoff = -5
  // ---------------------  HOLD ITEM  ------------------------ ED21
  if (self.HoldItem_timer || isHoldBehavior(self, self.Draw_behavior)) {
    self.HoldItem_x_scale = self.xScale // 9364
    self.Cucco_eye_can_draw = true
    self.Cucco_eye_xoff = 2 * self.HoldItem_x_scale
    self.Cucco_eye_xoff -= gmBool(self.HoldItem_x_scale) ? 0 : 1
    self.Cucco_eye_yoff = -5
    self.Cucco_sprite_body = self.Cucco_SPRITE_BODY1
    self.Cucco_sprite_legs = self.Cucco_SPRITE_LEGS1
    self.Cucco_sprite_wing = self.Cucco_SPRITE_WING2 // 2: up
    self.Cucco_sprite_wing_yoff = 0
    return
  }
  // ---------------------  BODY  --------------------------
  self.Cucco_sprite_body = self.Cucco_SPRITE_BODY1 // Normal/Idle
  if (_HEAD_FWRD && !self.ogr) self.Cucco_sprite_body = self.Cucco_SPRITE_BODY2 // Stand, Head frwd
  if (self.Cucco_crouching_state) {
    if (self.Cucco_crouching_state === 2)
      self.Cucco_sprite_body = _HEAD_FWRD ? self.Cucco_SPRITE_BODY8 : self.Cucco_SPRITE_BODY7
    else self.Cucco_sprite_body = _HEAD_FWRD ? self.Cucco_SPRITE_BODY5 : self.Cucco_SPRITE_BODY4
  }
  if (_ATTACKING) self.Cucco_sprite_body = self.Cucco_SPRITE_BODY3
  if (
    self.Draw_behavior === self.behavior_DRAWBACK &&
    self.attack_phase &&
    self.attack_phase < 4 &&
    self.stab_type === 1
  ) {
    self.Cucco_sprite_body = self.Cucco_SPRITE_BODY6 // Atk-high Draw
  }
  // ---------------------  LEGS  --------------------------
  let _frame = 0
  if (!self.ogr) {
    if (
      _CROUCHING ||
      isVal(self.Draw_behavior, self.behavior_WALK1, self.behavior_WALK2, self.behavior_WALK3)
    )
      _frame = self.walk_frame + 1
  } else {
    _frame = 1 // Legs wide
    if (self.Cucco_is_slowfalling) {
      if (self.Cucco_counter1 < (3 << 2) - 1) self.Cucco_counter1++
      else self.Cucco_counter1 = 0
      _frame = (self.Cucco_counter1 >> 2) + 1
    }
  }
  self.Cucco_sprite_legs = 0
  switch (_frame) {
    case 0:
      self.Cucco_sprite_legs = self.Cucco_SPRITE_LEGS1 // Idle
      break
    case 1:
      self.Cucco_sprite_legs = self.Cucco_SPRITE_LEGS4 // Walk frame 1
      break
    case 2:
      self.Cucco_sprite_legs = self.Cucco_SPRITE_LEGS3 // Walk frame 2
      break
    case 3:
      self.Cucco_sprite_legs = self.Cucco_SPRITE_LEGS2 // Walk frame 3
      break
  }
  // ---------------------  EYE  --------------------------
  self.Cucco_eye_can_draw = true
  if (!self.ogr && !self.attack_phase && !self.hspd && self.Draw_behavior === self.behavior_IDLE) {
    if (!(self.Cucco_counter4 & 0xff)) self.Cucco_counter4 += world.irandom(0xc0)
    self.Cucco_counter4 = (self.Cucco_counter4 + 1) & 0x3ff
    if (self.Cucco_counter4 & 0x100 && (self.Cucco_counter4 & 0xff) > 0xf8) self.Cucco_eye_can_draw = 0 // blink
  }
  self.Cucco_eye_xoff = 2
  self.Cucco_eye_yoff = -5
  const eye: Record<string, [number, number]> = {
    [self.Cucco_SPRITE_BODY1]: [2, -5], // idle
    [self.Cucco_SPRITE_BODY2]: [3, -5], // stand, head frwd
    [self.Cucco_SPRITE_BODY3]: [9, 0], // atk
    [self.Cucco_SPRITE_BODY4]: [3, -1], // crouch
    [self.Cucco_SPRITE_BODY5]: [4, -1], // crouch, head fwrd
    [self.Cucco_SPRITE_BODY6]: [1, -4], // atk draw
    [self.Cucco_SPRITE_BODY7]: [4, 1], // crouch low
    [self.Cucco_SPRITE_BODY8]: [5, 1], // crouch low, head fwrd
  }
  const e = eye[self.Cucco_sprite_body as string]
  if (e) [self.Cucco_eye_xoff, self.Cucco_eye_yoff] = e
  if (self.Cucco_sprite_body === self.Cucco_SPRITE_BODY3) {
    if (self.Draw_behavior === self.behavior_STAB_UP) [self.Cucco_eye_xoff, self.Cucco_eye_yoff] = [0, -10]
    if (self.Draw_behavior === self.behavior_STAB_DOWN) [self.Cucco_eye_xoff, self.Cucco_eye_yoff] = [-1, 9]
  }
  self.Cucco_eye_xoff *= self.xScale
  self.Cucco_eye_xoff -= gmBool(self.xScale) ? 0 : 1
  self.Cucco_eye_yoff *= self.yScale
  self.Cucco_eye_yoff -= gmBool(self.yScale) ? 0 : 1
  // ---------------------  WINGS  --------------------------
  self.Cucco_sprite_wing = self.Cucco_SPRITE_WING1 // 1: down
  if (self.Draw_behavior === self.behavior_STAB_STAND || self.Draw_behavior === self.behavior_STAB_CROUCH) {
    self.Cucco_sprite_wing = self.Cucco_SPRITE_WING2 // 2: up
  } else {
    if (self.ogr) {
      // if NOT on the ground
      self.Cucco_counter2++
      self.Cucco_sprite_wing = self.Cucco_SPRITE_WING2 // 2: up
      if (self.vspd & 0x80 && self.Cucco_counter2 & 0x04) self.Cucco_sprite_wing = self.Cucco_SPRITE_WING1
      else if (self.Cucco_is_slowfalling) {
        if (self.Cucco_counter2 & 0x10 && self.Cucco_counter2 & 0x04)
          self.Cucco_sprite_wing = self.Cucco_SPRITE_WING1 // every other 16 frames, 4 of them
      }
    } else {
      self.Cucco_counter2 = 0x11 // set at $11 so first flap happens quick for slowfall and jump
    }
    // RANDOM FLAP
    if (!self.ogr && isVal(self.Cucco_sprite_body, self.Cucco_SPRITE_BODY1, self.Cucco_SPRITE_BODY2)) {
      const _TIMING = 0x100
      if (!self.Cucco_counter3) self.Cucco_counter3 = world.irandom(_TIMING >> 2)
      self.Cucco_counter3 = (self.Cucco_counter3 + 1) & (_TIMING - 1)
      if (self.Cucco_counter3 === _TIMING - 0x10 && !world.irandom(0x04)) self.Cucco_counter3 += 0x08 // only 1 wing flap instead of 2
      if (self.Cucco_counter3 >= _TIMING - 0x10 && self.Cucco_counter3 & 0x04)
        self.Cucco_sprite_wing = self.Cucco_SPRITE_WING2
    } else {
      self.Cucco_counter3 = 0
    }
  }
  // WING Y OFF
  self.Cucco_sprite_wing_yoff = 0
  if (self.Cucco_sprite_wing === self.Cucco_SPRITE_WING1) {
    if (_ATTACKING) self.Cucco_sprite_wing_yoff = -1
    else {
      const yoff: Record<string, number> = {
        [self.Cucco_SPRITE_BODY1]: 0,
        [self.Cucco_SPRITE_BODY2]: -1,
        [self.Cucco_SPRITE_BODY3]: -1,
        [self.Cucco_SPRITE_BODY4]: 1,
        [self.Cucco_SPRITE_BODY5]: 0,
        [self.Cucco_SPRITE_BODY6]: 1,
        [self.Cucco_SPRITE_BODY7]: 1,
        [self.Cucco_SPRITE_BODY8]: 0,
      }
      self.Cucco_sprite_wing_yoff += yoff[self.Cucco_sprite_body as string] ?? 0
    }
  }
}

export function isHoldBehavior(self: Lonk, b: number): boolean {
  return isVal(
    b,
    self.behavior_HOLD_ITEM1,
    self.behavior_HOLD_ITEM2,
    self.behavior_HOLD_ITEM3,
    self.behavior_HOLD_ITEM4,
    self.behavior_HOLD_ITEM5,
  )
}

/** `PC_draw_get_cucco_rot(x scale)` — 90° rotations for cucco up/down thrust. */
export function PC_draw_get_cucco_rot(self: Lonk, xscale: number): number {
  if (self.Disguise_enabled || self.Draw_behavior === self.behavior_DAMAGE) return 0
  const _THRUST_D =
    self.Draw_behavior === self.behavior_STAB_DOWN &&
    !!(f.Cucco_skills & f.CuccoSkill_THRUST_D) &&
    gmBool(g.CUCCO_CAN_THRUST_D)
  const _THRUST_U =
    self.Draw_behavior === self.behavior_STAB_UP &&
    !!(f.Cucco_skills & f.CuccoSkill_THRUST_U) &&
    gmBool(g.CUCCO_CAN_THRUST_U)
  if (_THRUST_D || _THRUST_U) {
    const right = gmBool(xscale)
    if ((_THRUST_D && !right) || (_THRUST_U && right)) return 90
    if ((_THRUST_D && right) || (_THRUST_U && !right)) return 90 * 3
  }
  return 0
}

/**
 * `PC_cucco_fury_update()` — the Cucco-Fury attack. ZALiA: "TODO: Finish Cucco-Fury attack." — ported as-is:
 * the state machine spawns ghost cuccos from the screen edges that damage the nearest enemy; nothing draws
 * them yet (no draw script exists in ZALiA either).
 */
export function PC_cucco_fury_update(self: Lonk): void {
  if (!gmBool(g.mod_PC_CUCCO_3)) return
  // TODO (ZALiA): Finish Cucco-Fury attack.
  if (!self.Cucco_rage_state && !self.Cucco_rage_timer && self.Cucco_rage_tokens) {
    self.Cucco_rage_tokens--
    self.Cucco_rage_timer = 0
    self.Cucco_rage_state = self.Cucco_RAGE_STATE_STRT1
  }
  if (self.Cucco_rage_timer) self.Cucco_rage_timer--
  if (!self.Cucco_rage_state) return
  // ----------------------------------------------------------------------------
  let _timing = 1 << 3 // 1<<3 == every 8
  let _dur = 0
  switch (self.Cucco_rage_state) {
    case self.Cucco_RAGE_STATE_STRT1:
    case self.Cucco_RAGE_STATE_STRT2:
    case self.Cucco_RAGE_STATE_ATK1:
      _dur = self.Cucco_RAGE_DUR1 // $100
      _timing = 1 << 6 // spawn every 64
      break
    case self.Cucco_RAGE_STATE_ATK2:
      _dur = self.Cucco_RAGE_DUR3 // $20
      _timing = 1 << 5 // spawn every 32
      break
    case self.Cucco_RAGE_STATE_END1:
      self.Cucco_rage_timer = 2 // Keep it going until all cucco are off screen.
      break
    case self.Cucco_RAGE_STATE_END2:
      break
  }
  if (self.Cucco_rage_timer <= 0) self.Cucco_rage_timer = _dur // 0: cue set timer, first frame of this case/state.
  if (self.Cucco_rage_timer === 1) {
    // 1: cue change state
    self.Cucco_rage_timer = 0
    self.Cucco_rage_state = (self.Cucco_rage_state + 1) % self.Cucco_RAGE_STATE_CNT
  }
  if (!self.Cucco_rage_state) return
  const _DIST = viewW_()
  let _complete = true
  _timing = self.Cucco_rage_timer & (_timing - 1)
  const R = self.dg_Cucco_rage
  const num = (x: number, y: number) => Number(R.get(x, y) ?? 0)
  for (let _i = R.width - 1; _i >= 1; _i--) {
    if (num(_i, 0)) {
      // if is spawned
      R.set(_i, 1, round(num(_i, 1) + self.hspd)) // update x
      let _x = num(_i, 1) - (self.Cucco_W >> 1)
      R.set(_i, 2, round(num(_i, 2) + self.vspd)) // update y
      let _y = num(_i, 2) - (self.Cucco_H >> 1)
      if (rectInView(_x, _y, self.Cucco_W, self.Cucco_H)) {
        let _inst = R.get(_i, 6) as Ref<GameObject> | number | undefined
        if (typeof _inst !== 'object' || !_inst?.exists || !_inst.state) {
          // pick a new target: the nearest enemy
          let _dist = _DIST
          _inst = NOONE
          for (const e of world.instancesOf(Enemy)) {
            const d = Math.hypot(_x - e.x, _y - e.y)
            if (e.state === e.state_NORMAL && _dist > d) {
              _dist = d
              _inst = e
            }
          }
          R.set(_i, 6, _inst)
        }
        if (_inst?.hp && !_inst.stun_timer) {
          const _w = 0xc
          const _h = 0xa
          _x = num(_i, 1) - (_w >> 1)
          _y = num(_i, 2) - (_h >> 1)
          if (rectInRect(_x, _y, _w, _h, _inst.BodyHB_xl, _inst.BodyHB_yt, _inst.BodyHB_w, _inst.BodyHB_h)) {
            damage_gob(_inst, self.dl_ATTACK_DAMAGE[f.level_atk] ?? 0, false)
          }
        }
      } else {
        R.set(_i, 0, 0) // Despawn
      }
    }
    if (num(_i, 0)) _complete = false
    if (!num(_i, 0) && !_timing) {
      // !_timing: is spawn frame.
      R.set(_i, 0, 1)
      const _val = world.irandom(3) // 0:RGT, 1:LFT, 2:BTM, 3:TOP
      let _x: number
      let _y: number
      if (_val < 2) {
        _x = viewXC() + (viewW_() + (self.Cucco_W >> 1)) * -sign_(_val & 1)
        _y = viewYT() - (self.Cucco_H >> 1) + world.irandom(viewH() + self.Cucco_H)
      } else {
        _y = viewYC() + (viewH_() + (self.Cucco_H >> 1)) * -sign_(_val & 1)
        _x = viewXL() - (self.Cucco_W >> 1) + world.irandom(viewW() + self.Cucco_W)
      }
      R.set(_i, 1, _x)
      R.set(_i, 2, _y)
    }
  }
  if (_complete) self.Cucco_rage_state = 0 // END CUCCO FURY ATTACK
}
