/** Growkke (`Growkke`) — the segmented stalk that loses segments. Ported from `Growkke_init1/init2/update/udp/draw.gml`. */
import {
  CS_BD1,
  CS_PR1,
  CS_SW1,
  STR_Datakey,
  STR_Enemy,
  STR_Length,
  STR_Randomize,
  STR_Randomized,
  STR_Spawn,
} from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { DsGrid } from '../../../../../../runtime/ds'
import { world } from '../../../../../../runtime/world'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { get_ground_y } from '../../../../../collision/solid'
import { choose } from '../../../../../Game/gm'
import { sign_ } from '../../../../../math/index'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { draw_sprite_, drawState } from '../../../../../rooms/draw'
import { aud_play_combo1 } from '../../../../../sound/play'
import { Enemy } from '../../../../classes'
import { set_xlyt } from '../../../../go/movement'
import { fp, gp } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GameObjectB_init, GOB_update_2 } from '../../../GameObjectB'

export class Growkke extends Enemy {
  readonly objectName = 'Growkke' as const
  LoseSegmentSound_NUM = 2
  Segment_SPR1 = 'spr_0'
  Segment_SPR2 = 'spr_0'
  SEGMENT_MIN = 0x01 + 0x03
  SEGMENT_MAX = 0x10
  SEGMENT_CNT = 4
  Segment_CanDraw_cnt = 4
  FLIP_DELAY1 = 1 << 8 // min time until next xscale flip
  FLIP_DELAY2 = (1 << 6) - 1
  GROUND_Y = 0
  IDX_STATE = 0
  IDX_SPR = 1
  IDX_XSCALE = 2
  IDX_TMR = 3
  dg_segments = new DsGrid<number | string>(1, 4, 0)
}

/** `Growkke_init1()` */
export function Growkke_init1(self: Growkke): void {
  GameObjectB_init(self)
  self.LoseSegmentSound_NUM = 2
  self.Segment_SPR1 = 'spr_0'
  self.Segment_SPR2 = 'spr_0'
  self.SEGMENT_MIN = 0x01 + 0x03
  self.SEGMENT_MAX = 0x10
  self.SEGMENT_CNT = world.irandom(self.SEGMENT_MAX - self.SEGMENT_MIN) + self.SEGMENT_MIN
  self.Segment_CanDraw_cnt = self.SEGMENT_CNT
  self.FLIP_DELAY1 = 1 << 8
  self.FLIP_DELAY2 = (1 << 6) - 1
}

/** `Growkke_init2()` */
export function Growkke_init2(self: Growkke): void {
  const g = gp()
  self.GROUND_Y = self.spawn_yt + self.hh
  self.GROUND_Y = get_ground_y(self.x, self.GROUND_Y - self.hh, 1, self.GROUND_Y)
  self.spawn_yt = self.GROUND_Y - self.hh
  set_xlyt(self, self.xl, self.spawn_yt)
  let _spawn_datakey = self.dk_spawn
  if (self.dk_spawn !== undefined) {
    const r = fp().dm_rando.get(
      STR_Randomize + STR_Enemy + STR_Spawn + self.dk_spawn + STR_Spawn + STR_Datakey + STR_Randomized,
    )
    _spawn_datakey = r !== undefined ? String(r) : self.dk_spawn
  }
  if (_spawn_datakey !== undefined && g.dm_spawn.get(_spawn_datakey + STR_Length) !== undefined) {
    self.SEGMENT_CNT = Number(g.dm_spawn.get(_spawn_datakey + STR_Length) ?? 0)
  }
  self.SEGMENT_CNT = Math.max(self.SEGMENT_MIN, Math.min(self.SEGMENT_CNT, self.SEGMENT_MAX))
  self.Segment_CanDraw_cnt = self.SEGMENT_CNT
  let _a = 0
  self.IDX_STATE = _a++
  self.IDX_SPR = _a++
  self.IDX_XSCALE = _a++
  self.IDX_TMR = _a++
  const dg = new DsGrid<number | string>(self.SEGMENT_CNT, _a, 0)
  self.dg_segments = dg
  dg.set(0, self.IDX_STATE, 1) // first segment
  dg.set(self.SEGMENT_CNT - 1, self.IDX_STATE, 1) // last  segment
  dg.set(0, self.IDX_SPR, self.Segment_SPR1) // first segment
  dg.set(self.SEGMENT_CNT - 1, self.IDX_SPR, dg.get(0, self.IDX_SPR) as string) // last  segment
  dg.set(0, self.IDX_XSCALE, sign_(world.irandom(1)))
  for (let _i = 1; _i < self.SEGMENT_CNT - 1; _i++) {
    dg.set(_i, self.IDX_STATE, 1)
    dg.set(_i, self.IDX_SPR, choose(self.Segment_SPR1, self.Segment_SPR2))
    dg.set(_i, self.IDX_XSCALE, -sign_(dg.get(_i - 1, self.IDX_XSCALE) as number)) // xscale
    dg.set(_i, self.IDX_TMR, (0x20 << (_i & 1)) + world.irandom(self.FLIP_DELAY1 >> 1))
  }
}

/** `Growkke_update()` */
export function Growkke_update(self: Growkke): void {
  const _PAD = 3
  self.BodyHB_w = 8
  self.BodyHB_h = (self.Segment_CanDraw_cnt << 3) - (_PAD << 1)
  self.BodyHB_xl = self.x - (self.BodyHB_w >> 1)
  self.BodyHB_xr = self.BodyHB_xl + self.BodyHB_w
  self.BodyHB_yt = self.GROUND_Y - _PAD - self.BodyHB_h + self.draw_yoff
  self.BodyHB_yb = self.BodyHB_yt + self.BodyHB_h
  GOB_update_2(self)
  if (self.cs & (CS_SW1 | CS_PR1)) {
    // Remove a random segment. The first and last are locked
    let _idx = -1
    let _val = world.irandom(self.Segment_CanDraw_cnt - 2 - 1) + 1
    for (let _i = self.dg_segments.width - 2; _i >= 1; _i--) {
      if (gmBool(self.dg_segments.get(_i, self.IDX_STATE))) {
        _val--
        if (!_val) {
          self.dg_segments.set(_i, self.IDX_STATE, 0)
          _idx = _i
          aud_play_combo1(self.LoseSegmentSound_NUM)
          break
        }
      }
    }
    if (self.Segment_CanDraw_cnt === self.SEGMENT_MIN || _idx === -1) {
      self.hp = 0
      self.state = self.state_EXPLODE
    }
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
}

/** `Growkke_udp()` */
export function Growkke_udp(self: Growkke): void {
  self.can_draw_self = true
  self.Segment_CanDraw_cnt = 0
  for (let _i = self.dg_segments.width - 1; _i >= 0; _i--) {
    self.Segment_CanDraw_cnt += gmBool(self.dg_segments.get(_i, self.IDX_STATE)) ? 1 : 0
    const tmr = self.dg_segments.get(_i, self.IDX_TMR) as number
    if (gmBool(tmr)) {
      self.dg_segments.set(_i, self.IDX_TMR, tmr - 1)
    } else {
      let _val = self.FLIP_DELAY1
      _val -= (self.FLIP_DELAY1 >> 2) * world.irandom(2)
      self.dg_segments.set(_i, self.IDX_TMR, _val + world.irandom(self.FLIP_DELAY2))
      self.dg_segments.set(_i, self.IDX_XSCALE, -(self.dg_segments.get(_i, self.IDX_XSCALE) as number))
    }
  }
  if (self.state === self.state_EXPLODE) {
    self.explosion_count = 2
    self.explosion_count = 1 + ((self.GROUND_Y - self.yt) >> 4 >= 2 ? 1 : 0)
    self.explosion_y = self.GROUND_Y - (self.explosion_count << 4)
    self.explosion_y += 8 // centered like drawY
    if (self.timer === 1) set_xlyt(self, self.xl, self.explosion_y - 8) // So rising xp not so high
  }
}

/** `Growkke_end()` — empty in ZALiA (instance-end slot). */
export function Growkke_end(_self: Growkke): void {}

/** `Growkke_draw()` */
export function Growkke_draw(self: Growkke): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!self.Segment_CanDraw_cnt) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawState.depth = self.depth
  pal_swap_set(self.palidx)
  let _y = self.GROUND_Y - 4 + self.draw_yoff
  for (let _i = self.dg_segments.width - 1; _i >= 0; _i--) {
    if (!gmBool(self.dg_segments.get(_i, self.IDX_STATE))) continue
    draw_sprite_(
      self.dg_segments.get(_i, self.IDX_SPR) as string,
      0,
      self.drawX,
      _y,
      -1,
      self.dg_segments.get(_i, self.IDX_XSCALE) as number,
    )
    _y -= 8
  }
  pal_swap_reset()
}

export function registerGrowkke(): void {
  registerObject('Growkke', Growkke)
  registerScripts({ Growkke_init1, Growkke_init2, Growkke_update, Growkke_udp, Growkke_draw, Growkke_end })
}
registerGrowkke()
