/** Fields of the `ArenaGate` leaf (gob2 port) that the boss scripts touch. */
export interface ArenaGateLike extends GameObject {
  sub_state: number
  SUB_STATE_TRIG: number
  SUB_STATE_DONE: number
  boss: Ref<GameObject>
}

// FIXED: was a local `0xff`, shadowing the `$FFFFFF` project macro — `g.pc_lock === PC_LOCK_ALL`
// never matched, so the LOCKED branch never fired on a gated boss and the bits above `$FF`
// (SPEL/MENU/PRJ1/PRJ2/CSTB) were lost: spells, sword beams and the pause menu stayed available.
/** `CS_BD1` collision-side bit (body). */
const CS_BD1 = 0x10

export abstract class BossObject extends Boss {
  // ---- Boss_init_1()
  GROUND_Y = 0
  // Boss vars
  arena_w = 0
  /** arena_x is the CENTER of the arena */
  arena_x = 0x180
  arena_xl = 0
  arena_xr = 0
  arena_y = 0
  arena_yt = 0
  arena_yb = 0
  HPBar_can_draw = false
  HPBar_hp_color = 0
  HPBar_unit_COUNT = 8
  HPBar_units_full = 0
  HPBar_XPAD = 0x2 << 3
  /** x offset from viewXL(). Set in Boss_init_2() after arena_xl is set */
  HPBar_XOFF = this.HPBar_XPAD
  /** y offset from viewYT() (+$10 because VIEW_H_OG used to erroneously be 224 instead of 240) */
  HPBar_YOFF = VIEW_H_WD - VIEW_H_OG + 0x40 + 0x10
  /** delay Boss battle */
  start_timer = 0
  pending_death = false
  Roar_DELAY = 0xff
  Roar_timer = this.Roar_DELAY
  MusicBattle_THEME: string = `${STR_Boss}01`
  MusicBattle_INTRO: string | 0 = 0
  MusicBattle_BODY: string | 0 = 0
  MusicBattle_SOUND_OBJECT_DK = ''
  // ---- common leaf fields (set in the *_init2 scripts; declared here so shared Boss_* scripts can read them)
  attack_state = 0
  attack_state_IDLE = 0
  attack_state_DRAWBACK = 1
  attack_state_SWING = 2
  DISTANCE1 = 0x20
  DISTANCE2 = 0x30
  DURATION1 = 0xf
  DURATION2 = 0x60
  DURATION3 = 0x50
  /** phase/sub-state machine index used by most bosses */
  sub_state = 0
}

/** `Boss_init_1()` */
export function Boss_init_1(self: BossObject): void {
  GameObjectB_init(self)
  self.GROUND_Y = (((viewYC() >> 8) + 1) << 8) - (0x03 << 3)
  // Boss vars
  self.arena_w = viewW() - 0x20
  self.arena_x = 0x180 // arena_x is the CENTER of the arena
  self.arena_xl = self.arena_x - (self.arena_w >> 1)
  self.arena_xr = self.arena_xl + self.arena_w
  self.arena_y = 0
  self.arena_yt = 0
  self.arena_yb = self.GROUND_Y
  self.HPBar_timer = 0
  self.HPBar_can_draw = false
  self.HPBar_hp_color = p.C_RED3
  self.HPBar_unit_COUNT = 8
  self.HPBar_units_full = 0
  self.HPBar_XPAD = 0x2 << 3
  self.HPBar_XOFF = self.HPBar_XPAD
  self.HPBar_YOFF = VIEW_H_WD - VIEW_H_OG + 0x40 + 0x10
  self.start_timer = 0 // delay Boss battle
  self.pending_death = false
  self.Roar_DELAY = 0xff
  self.Roar_timer = self.Roar_DELAY
  self.MusicBattle_THEME = `${STR_Boss}01`
  self.MusicBattle_INTRO = 0
  self.MusicBattle_BODY = 0
}

/** Bosses that fight without arena gates / camera snap (`is_ancestor_(object_index, Thunderbird01, ShadowLonk01, Ganon)`). */
export function isGatelessBoss(self: GameObject): boolean {
  const n = self.objectName
  return n === 'Thunderbird01' || n === 'ShadowLonk01' || n === 'Ganon1' || n === 'Ganon2' || n === 'Ganon3'
}

/** `Boss_init_2()` — arena bounds from the solid grid, HP bar x offset, arena gates. */
export function Boss_init_2(self: BossObject): void {
  self.arena_x = g.rm_w_
  if (self.dk_spawn !== undefined) {
    self.arena_x = g.dm_spawn.val(`${self.dk_spawn + STR_Arena}_x`, self.arena_x) as number
  }
  if (self.objectName === 'Ganon2') {
    self.arena_xl = find_clm_solid(0, 0x00, g.rm_row0 + 0x08, 1, 0, 0x05)
    self.arena_xl = self.arena_xl << 3
    self.arena_xr = g.rm_w
    self.arena_w = self.arena_xr - self.arena_xl
  } else {
    let _default = g.rm_rows - 0x02
    let _row = find_row_solid(TID_SOLID1, self.arena_x >> 3, viewYC() >> 3, -1, 0, _default) + 1 // search for ceiling
    if (_row >= _default) {
      // if didnt find ceiling
      _row = Math.max(0, viewYT() >> 3)
    }
    _default = (viewXR() >> 3) - 0x02
    self.arena_xl = find_clm_solid(TID_SOLID1, self.arena_x >> 3, _row, -1, 0, _default)
    if (self.arena_xl >= _default) {
      // if didn't find left wall
      self.arena_xl = self.arena_x - viewW_()
    } else self.arena_xl = (self.arena_xl + 0x01) << 3
    self.arena_xl = clamp(self.arena_xl, self.arena_x - viewW_(), self.arena_x - 8)
    self.arena_w = Math.min((self.arena_x - self.arena_xl) << 1, viewW())
    self.arena_xl = self.arena_x - (self.arena_w >> 1)
    self.arena_xr = self.arena_xl + self.arena_w
  }
  Boss_init_2a(self) // set GROUND_Y
  // HPBar_XOFF: x offset from viewXL()
  self.HPBar_XOFF = Math.max(0, (viewW() - self.arena_w) >> 1)
  self.HPBar_XOFF += self.HPBar_XPAD
  self.HPBar_XOFF = clamp(self.HPBar_XOFF, self.HPBar_XPAD, viewW_() - 4)
  if (!isGatelessBoss(self)) {
    const gl = GameObject_create(self.arena_xl - 8, self.y, 'ArenaGateA', 1) as ArenaGateLike | null
    if (gl) gl.boss = self
    const gr = GameObject_create(self.arena_xr, self.y, 'ArenaGateA', 1) as ArenaGateLike | null
    if (gr) gr.boss = self
  }
}

/** `Boss_init_2a()` — GROUND_Y from the solid grid below the arena centre. */
export function Boss_init_2a(self: BossObject): void {
  self.GROUND_Y = ((viewYC() >> 8) + 1) << 8
  self.GROUND_Y -= 0x3 << 3
  self.GROUND_Y = get_ground_y(self.arena_x, self.GROUND_Y, -1, self.GROUND_Y)
}

/** `Boss_init_2b(dist from arena center)` — determine & set the side of the arena to start on. */
export function Boss_init_2b(self: BossObject, dist: number): void {
  let _dist = dist
  if (_dist === -1) {
    _dist = (self.arena_w >> 1) - ((self.arena_w >> 1) - Math.abs(self.x - self.arena_x))
  }
  const _DIR = sign_(pc().x < self.arena_x) // Determines which side of arena to start on
  set_xy(self, self.arena_x + _dist * _DIR, self.y)
}

/** `Boss_set_MusicBattle_props(theme)` */
export function Boss_set_MusicBattle_props(self: BossObject, theme: string): void {
  self.MusicBattle_THEME = theme
  self.MusicBattle_SOUND_OBJECT_DK = self.MusicBattle_THEME + get_audio_set_by_theme(self.MusicBattle_THEME)
  // [dropped: `if (0)` branch reading Audio.dm STR_Body/STR_Intro]
  self.MusicBattle_BODY = get_audio_theme_track(self.MusicBattle_THEME)
  self.MusicBattle_INTRO = get_audio_theme_track_intro(self.MusicBattle_BODY)
  if (self.MusicBattle_INTRO) {
    const _NAME = Audio.audio_get_name(self.MusicBattle_INTRO)
    if (_NAME.includes('Wyng')) {
      self.MusicBattle_INTRO = 0
    }
  }
}

/** `Boss_HPBar_udp()` */
export function Boss_HPBar_udp(self: BossObject): void {
  self.HPBar_can_draw = true
  if (self.HPBar_timer) {
    self.HPBar_timer--
  }
  if (self.HPBar_timer & 0x4)
    self.HPBar_hp_color = p.C_ORG4 // damage flash
  else self.HPBar_hp_color = p.C_RED3
  if (self.hp) {
    let _HP_PER_UNIT: number
    if (self.objectName === 'ShadowLonk01' || self.objectName === 'Ganon3') {
      // Some enemy hp should not be randomized
      _HP_PER_UNIT = (g.dl_HP_DEFAULT.get(self.HP_IDX) ?? 0) as number
    } else {
      _HP_PER_UNIT = (g.dl_HP.get(self.HP_IDX) ?? 0) as number
    }
    _HP_PER_UNIT = Math.trunc(_HP_PER_UNIT / self.HPBar_unit_COUNT)
    // GML `div` by 0 would error; hp tables < 8 never occur for bosses, guard keeps the clamp semantics
    self.HPBar_units_full = _HP_PER_UNIT ? Math.trunc(self.hp / _HP_PER_UNIT) : self.HPBar_unit_COUNT
    self.HPBar_units_full = clamp(self.HPBar_units_full, 1, self.HPBar_unit_COUNT)
  } else {
    self.HPBar_units_full = 0
  }
}

/** `Boss_HPBar_draw()` */
export function Boss_HPBar_draw(self: BossObject): void {
  if (!self.state) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!self.HPBar_can_draw) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  self.HPBar_can_draw = false
  let _X = viewXL() + self.HPBar_XOFF
  const _Y = viewYT() + self.HPBar_YOFF
  let _UNITS_EMPTY = self.HPBar_unit_COUNT - self.HPBar_units_full
  if (self.objectName === 'Ganon2') {
    _X = viewXL() + self.HPBar_XPAD
    // Chat member 'alterna4091' had idea to keep hp bar at one during fight
    _UNITS_EMPTY = self.HPBar_unit_COUNT - Math.sign(self.hp)
  }
  for (let _i = 0; _i < self.HPBar_unit_COUNT; _i++) {
    const _color = _i >= _UNITS_EMPTY ? self.HPBar_hp_color : p.C_WHT1
    let _y = _Y + 7 * _i // 7 apart from each other
    _y += +(_i === self.HPBar_unit_COUNT - 1) // Bottom most one is an extra pixel apart
    draw_sprite_('spr_1x1_WHT', 0, _X, _y, -1, 8, 5, _color)
  }
}

/** `Boss_update_start()` — snap the camera to the arena, lock it, trigger the gates, start the music. */
export function Boss_update_start(self: BossObject): void {
  if (g.view_lock_boss) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (viewXC() >> 3 !== (self.arena_x >> 3) - +!gmBool(g.view_dir_x)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // ------------------------------------------------------------------------------
  set_camera_xy(self.arena_x - viewW_(), viewYT()) // Snap to arena
  g.view_lock_boss = 0x3
  g.view_lock |= g.view_lock_boss // 3: cam left & right locked
  self.start_timer = 0
  switch (self.objectName) {
    case 'Rebonack01A':
      self.start_timer = 0xff
      break
    case 'Carock01':
      self.start_timer = 0x40
      break
    case 'Barba01':
      self.start_timer = 0xff
      break
    case 'Thunderbird01':
      self.start_timer = 0x90
      break
  }
  if (!isGatelessBoss(self)) {
    const _pc = pc()
    for (const gate of world.instancesOf(ArenaGate) as Iterable<ArenaGateLike>) {
      let _clm = 0
      let _row = 0
      gate.sub_state = gate.SUB_STATE_TRIG
      g.pc_lock = PC_LOCK_ALL // Only lock PC if there are gates?
      // --------------------------------------------
      if (_pc.RescueDropOff_rc < 0) {
        _clm = self.arena_x >> 3
        _row = viewYC() >> 3
      } else {
        _clm = (_pc.RescueDropOff_rc >> 0) & 0xff
        _row = (_pc.RescueDropOff_rc >> 8) & 0xff
      }
      _clm = clamp(_clm, ((self.arena_xl + _pc.ww_) >> 3) + 1, ((self.arena_xr - _pc.ww_) >> 3) - 1)
      _clm = clamp(_clm, ((cam_xl_min() + _pc.ww_) >> 3) + 1, ((cam_xr_max() - _pc.ww_) >> 3) - 1)
      _row = clamp(_row, ((cam_yt_min() + _pc.hh) >> 3) + 0, (cam_yb_max() >> 3) - 1)
      _pc.RescueDropOff_rc = (_row << 8) | _clm
    }
  }
  Boss_play_battle_music(self)
}

function clamp(v: number, lo: number, hi: number): number {
  return Math.min(Math.max(v, lo), hi)
}

/** `Boss_update_end()` — the boss explodes: strike sound, music off, every other GOB1/Spawner is killed. */
export function Boss_update_end(self: BossObject): void {
  if (g.view_lock_boss && self.pending_death && !self.stun_timer) {
    despawn_all_goc()
    aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
    world.emit({ kind: 'music', theme: null }) // audio_group_stop_all(audiogroup_mus)
    Audio.can_play_mus_rm_body = false // Prevent music until take key
    Audio.can_play_boss_music = false
    self.state = self.state_EXPLODE
    // Call the following AFTER changing state to state_EXPLODE so timer won't get changed.
    for (let _i = MAX_GOB1 - 1; _i >= 0; _i--) {
      const inst = goMgr.dl_gob1.get(_i) as Ref<GameObject> | undefined
      if (!instanceExists(inst)) continue
      if (inst.state === inst.state_NORMAL) {
        damage_gob(inst, Math.max(inst.hp, 0), false)
      }
    }
    for (const sp of world.instancesOf(Spawner)) {
      if (sp.state === sp.state_NORMAL) {
        damage_gob(sp, Math.max(sp.hp, 0), false)
      }
    }
  }
}

/** `Boss_update_1()` — HorseHead, HelmetHead, Gooma, Thunderbird, Carock, Barba. Returns true in battle mode. */
export function Boss_update_1(self: BossObject): boolean {
  if (!g.view_lock_boss) {
    // battle has NOT started. BE8B
    Boss_update_start(self)
  }
  if (g.view_lock_boss && !self.pending_death) {
    return true // qualify battle mode
  }
  if (self.pending_death) {
    // BEB1, BEB3, BEA8
    Boss_update_end(self)
  }
  return false
}

/** `Boss_update_2()` — HorseHead, HelmetHead, Gooma: EF11, pushback, updateX, shield collision, cs, DE40, dmg pc, death check. */
export function Boss_update_2(self: BossObject): void {
  // BC4E: JSR EF11
  update_EF11(self)
  // BC51: JSR 9E17.  update hspdPB
  GOB_update_1(self, true)
  GO_update_cs(self)
  if (!(self.cs & 0x3)) updateX(self)
  // BC54: JSR E617
  if (GOB_shield_collision_1a(self)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // BC57: JSR DE3D
  GO_update_cs(self)
  // DE40.  camXX,ocs,vertical despawn,update_EF11,body collision
  GOB_update_2(self)
  // BC5A: JSR D6C1.  dmg pc
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // BC5D.  check & set pending death
  Boss_update_5(self)
}

/** `Boss_update_3()` — Horsehead, Helmethead: face the PC on a 32-frame cue, pace, decide to attack. */
export function Boss_update_3(self: BossObject): void {
  const _HORSE = self.objectName === 'Horsehead01'
  const _HELMET = self.objectName === 'Helmethead01'
  // BB74
  const _DIR_TO_PC = dir_to_pc(self)
  if (!(g.counter1 & 0x1f)) {
    // face towards PC cue
    if (_HELMET || (_HORSE && !self.attack_state)) {
      self.facing_dir = _DIR_TO_PC // Face towards PC
    }
  }
  // BB94
  self.hspd = 0
  if (self.counter & 0x7f && self.facing_dir !== _DIR_TO_PC) {
    // No moving unless facing PC
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  Boss_update_3b(self, _DIR_TO_PC) // if (counter&$7F){hspd = +-8}, updates counter
  // BBB2
  if (Boss_update_3a(self, self.DISTANCE1) && _HORSE && self.facing_dir === _DIR_TO_PC) {
    // BBF5: JSR BC23
    self.attack_state = self.attack_state_DRAWBACK // ATTACK!!!
    self.timer = self.DURATION1 // DURATION1=$F
  }
}

/** `Boss_update_3a(dist)` — Horsehead, Helmethead, Gooma. Check & set move dir. Returns true if in atk dist && !attack_state. */
export function Boss_update_3a(self: BossObject, dist: number): boolean {
  // BBB2, B4EC
  let _DIST = goDist1(self)
  if (_DIST & 0x80) {
    _DIST ^= 0xff
  }
  if (_DIST >= 0x60 || _DIST >= dist) {
    // BBC9
    if (_DIST >= 0x60 || (!(g.counter1 & 0x3f) && rand(self) & 0x3)) {
      // BBBC. Walk toward pc
      self.counter = (self.counter & 0x7f) | 0x10
    }
    return false
  }
  // ---------------------------------------------------------------
  // BBD7, B511
  const _RAND = rand(self)
  if (!(_RAND & 0x7)) {
    // B522, B52E: JSR B4F6, B531, BBF8, BC04: JSR BBBC, BC07
    // result $10 or $90, $80 bit means back away from pc
    if (!(self.counter & 0x7f)) self.counter = 0x10 | (_RAND & 0x80)
    return !self.attack_state // true if not attacking
  }
  return false
}

/** `Boss_update_3b(direction to pc)` — Horsehead, Helmethead, Gooma. */
export function Boss_update_3b(self: BossObject, dirToPc: number): boolean {
  if (self.counter & 0x7f) {
    if (self.counter & 0x80)
      self.hspd = (8 * -dirToPc) & 0xff // back away from pc
    else self.hspd = (8 * dirToPc) & 0xff // move toward pc
    self.counter = (self.counter - (g.counter1 & 0x1)) & 0xff // decrement every other frame
    return true
  }
  return false
}

/** `Boss_update_4()` — true once the arena gate is done (or the boss has no gates); unlocks the PC. */
export function Boss_update_4(_self: BossObject): boolean {
  let _GATE: ArenaGateLike | null = NOONE
  for (const gate of world.instancesOf(ArenaGate) as Iterable<ArenaGateLike>) {
    _GATE = gate
    break
  }
  if (!_GATE || _GATE.sub_state === _GATE.SUB_STATE_DONE) {
    g.pc_lock = 0
    return true
  }
  return false
}

/** `Boss_update_5()` — BC5D & B1F6 & A3DB: check & set pending death. */
export function Boss_update_5(self: BossObject): void {
  if (self.state !== self.state_NORMAL) {
    self.state = self.state_NORMAL
    self.pending_death = true
    self.timer = 0xff
    self.stun_timer = self.EXPLODE_DELAY1 // $7F
  }
}

/** `Boss_play_battle_music()` */
export function Boss_play_battle_music(self: BossObject): void {
  if (self.MusicBattle_INTRO || self.MusicBattle_BODY) {
    if (self.MusicBattle_INTRO && self.MusicBattle_INTRO !== self.MusicBattle_BODY) {
      aud_play_sound(self.MusicBattle_INTRO, Audio.PRIORITY_TOP, false, -1, self.MusicBattle_THEME)
    } else if (self.MusicBattle_BODY) {
      aud_play_sound(self.MusicBattle_BODY, Audio.PRIORITY_TOP, true, -1, self.MusicBattle_THEME)
    }
    Audio.can_play_boss_music = true
  }
}

/** `Boss_Roar_update()` */
export function Boss_Roar_update(self: BossObject): void {
  if (!gmBool(g.mod_BossRoar)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!1
  if (self.Roar_timer) {
    self.Roar_timer--
    if (!self.Roar_timer) {
      self.Roar_timer = self.Roar_DELAY
      aud_play_sound(Audio.sound('SND_BOSS_ROAR'))
    }
  }
}

/** `Boss_end()` — nothing to free in the port (the GML only destroyed ds structures). */
export function Boss_end(_self: BossObject): void {}

/** `f.quest_num` helper used by several init2 scripts. */
export const questNum = (): number => f.quest_num
