/** GO_set_prop_values (scripts/game_object/go) — copies objver defaults from g.dm_go_prop onto the instance. */
import {
  dk_AttackLevel,
  dk_ReactBody,
  dk_ReactEnigma,
  dk_ReactProj,
  dk_ReactShield,
  dk_ReactSword,
  dk_ReactThun,
  STR_BodyHB,
  STR_Brightness,
  STR_CS_Off,
  STR_Drop,
  STR_HP,
  STR_Respawn,
  STR_XP,
  STR_XP_Drain,
} from '@z2/data'
import { hexStr } from '../../../nes/hexStr'
import type { GameObject } from '../classes'
import { goData } from '../goData'
import { gp } from '../pending'

/** `GO_set_prop_values()` → the objver key */
export function GO_set_prop_values(self: GameObject): string {
  const m = goData.dm_go_prop
  const n = (k: string, dflt = 0) => m.val(k, dflt) as number
  const _OBJVER = self.objectName + hexStr(self.ver)
  self.brightness = n(_OBJVER + STR_Brightness, self.brightness)
  self.BodyHB_IDX = n(_OBJVER + STR_BodyHB)
  self.BodyHB_idx = self.BodyHB_IDX
  self.CS_OFF_IDX = n(_OBJVER + STR_CS_Off)
  self.cs_off_idx = self.CS_OFF_IDX
  self.ATTACK_LEVEL = n(_OBJVER + dk_AttackLevel)
  self.attack_level = self.ATTACK_LEVEL
  self.RESPAWN_TYPE = n(_OBJVER + STR_Respawn)
  self.respawn_type = self.RESPAWN_TYPE
  self.DROP_BITS = n(_OBJVER + STR_Drop)
  self.drop_bits = self.DROP_BITS
  self.REACT_SWORD = n(_OBJVER + dk_ReactSword)
  self.react_sword = self.REACT_SWORD
  self.REACT_PROJ = n(_OBJVER + dk_ReactProj)
  self.react_proj = self.REACT_PROJ
  self.REACT_THUNDER = n(_OBJVER + dk_ReactThun)
  self.react_thunder = self.REACT_THUNDER
  self.REACT_SPELL = n(_OBJVER + dk_ReactEnigma)
  self.react_spell = self.REACT_SPELL
  self.XP_DRAIN = n(_OBJVER + STR_XP_Drain)
  self.xp_drain = self.XP_DRAIN
  self.HP_IDX = n(_OBJVER + STR_HP)
  self.hp = (gp().dl_HP.get(self.HP_IDX) as number) ?? 0
  self.XP_IDX = n(_OBJVER + STR_XP)
  self.xp = (gp().dl_XP.get(self.XP_IDX) as number) ?? 0
  // Typically for Projectile
  self.REACT_BODY = n(_OBJVER + dk_ReactBody)
  self.react_body = self.REACT_BODY
  self.REACT_SHIELD = n(_OBJVER + dk_ReactShield)
  self.react_shield = self.REACT_SHIELD
  return _OBJVER
}
