import { STR_Layer, STR_Name } from '@z2/data'
import { G } from '../../runtime/world'
import { TILE_LAYER_DATA as data } from './tileLayerData.data'

/** `init_tile_layer_data()` — pre-baked Tiled layer names per scene file into `global.dm_tile_layer_data`. */
export function init_tile_layer_data(): void {
  const dm = G.dm_tile_layer_data
  for (const [scene, layers] of Object.entries(data as Record<string, string[]>)) {
    for (let i = 0; i < layers.length; i++) {
      const name = layers[i]
      if (name === undefined) continue
      dm.set(`${scene}${STR_Layer}${(i + 1).toString(16).toUpperCase().padStart(2, '0')}${STR_Name}`, name)
    }
  }
}

/** Layer names of one scene file (`'WestA_008'` → `['BG0201, FGWALL01_01', …]`). */
export function sceneLayerNames(fileStem: string): readonly string[] {
  return (data as Record<string, string[]>)[fileStem] ?? []
}
