// Ported from ZALiA scripts: GameOverScreen_Create, GameOverScreen_Step, GameOverScreen_Draw (generated by rooms/_port/convert.py, then hand-finished).
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML state, typed progressively

import { dk_GannonLaugh, XP_MAX } from '@z2/data'
import { Instance } from '../../runtime/instance'
import { f, G, g, p } from '../../runtime/world'
import { clamp, round, sprite_get_height, sprite_get_width, string_length } from '../Game/gm'
import { set_background_color } from '../graphics/index'
import { gmBool } from '../math/index'
import { viewXC, viewYB } from '../view/camera'
import { aud_play_sound, get_audio_theme_track } from './deps'
import { draw_sprite_, draw_text_ } from './draw'
import { gmb } from './gmExtra'
import { room_goto_ } from './goto'
import { roomName } from './roomChange'

export class GameOverScreen extends Instance {
  readonly objectName = 'GameOverScreen'
  GANON_SPR: any = undefined
  LINE1_X: any = undefined
  LINE1_Y: any = undefined
  LINE2_X: any = undefined
  LINE2_Y: any = undefined
  TEXT_LINE1: any = undefined
  TEXT_LINE2: any = undefined
  TEXT_PI: any = undefined
  timer: any = undefined
  constructor() {
    super()
    GameOverScreen_Create(this)
  }
  step(): void {
    GameOverScreen_Step(this)
  }
  draw(): void {
    GameOverScreen_Draw(this)
  }
}

/** GML: GameOverScreen_Create(self) */
export function GameOverScreen_Create(self: GameOverScreen) {
  self.GANON_SPR = 'spr_Game_Over_Screen'
  self.x = viewXC() - (sprite_get_width(self.GANON_SPR) >> 1) // centered
  self.y = viewYB() - sprite_get_height(self.GANON_SPR) // bottom aligned
  self.timer = 0xf2 // $0501
  self.TEXT_LINE1 = 'GAME  OVER'
  self.TEXT_LINE2 = 'RETURN OF GANON'
  self.LINE1_X = viewXC() - ((string_length(self.TEXT_LINE1) << 3) >> 1)
  self.LINE2_X = viewXC() - ((string_length(self.TEXT_LINE2) << 3) >> 1)
  self.LINE1_Y = self.y + (0x0a << 3)
  self.LINE2_Y = self.LINE1_Y + (0x03 << 3)
  /* OG
TEXT_LINE1 =    "GAME  OVER";
TEXT_LINE2 = "RETURN OF GANON ";

LINE1_X = viewXC() - ((string_length(TEXT_LINE1)>>1)<<3);
LINE2_X = viewXC() - ((string_length(TEXT_LINE2)>>1)<<3);
LINE1_Y =       y + ($A<<3);
LINE2_Y = LINE1_Y + ($3<<3);
*/
  // p.Room_Start() changes PI_MOB_RED pal to CI_BLK1_+CI_WHT1_+CI_RED3_+CI_BLK1_
  // I'm not sure why it doesn't work changing the palette here.
  self.TEXT_PI = G.PI_MOB_RED
  aud_play_sound(get_audio_theme_track(dk_GannonLaugh))
  f.xp = round(f.xp * g.mod_Gameover_XP_PENALTY)
  f.xp = clamp(f.xp, 0, XP_MAX)
}

/** GML: GameOverScreen_Step(self) */
export function GameOverScreen_Step(self: GameOverScreen) {
  self.timer--
  if (!gmb(self.timer)) {
    set_background_color(p.C_BLK1) // MOD. Avoid 1 frame of solid red screen w/ no spr drawn.
    room_goto_('rmB_ContinueSave')
  }
}

/** GML: GameOverScreen_Draw(self) */
export function GameOverScreen_Draw(self: GameOverScreen) {
  set_background_color(p.GameOverScreen_BGR_COLOR)
  if (self.timer > 2) {
    draw_sprite_(self.GANON_SPR, 0, self.x, self.y, G.PI_MOB_ORG)
  }
  draw_text_(self.LINE1_X, self.LINE1_Y, self.TEXT_LINE1, -1, self.TEXT_PI)
  draw_text_(self.LINE2_X, self.LINE2_Y, self.TEXT_LINE2, -1, self.TEXT_PI)
}
