/**
 * Drop (Dripper drop): falls, then spawns a Bot (or a rando-selected enemy) where it lands — `update_Drop`
 * is the OG B876 spawn routine. Enemy-specific spawn fields are read structurally (leaf enemies live elsewhere).
 */
import {
  MAX_GOB1,
  STR_Count,
  STR_Difficulty,
  STR_Dripper,
  STR_Enemy,
  STR_Object,
  STR_Randomize,
  STR_Spawner,
  STR_Version,
  UIDX_NULL,
} from '@z2/data'
import { hexStr } from '../../../../nes/hexStr'
import { gmBool, gmRound as round } from '../../../../nes/math8'
import { input } from '../../../../runtime/world'
import { ocsH1 } from '../../../collision/ocs'
import { get_ground_y } from '../../../collision/solid'
import { available_update_idx_gob } from '../../../game_object_mgr/slots'
import type { GameObject } from '../../classes'
import { GameObject_create } from '../../create'
import { deps } from '../../deps'
import { dir_to_pc, dir_to_pc_, from_spawner_count, GO_update_cam_vars } from '../../go/misc'
import { set_xlyt, set_xy, updateX, updateY } from '../../go/movement'
import { GO_init_palidx } from '../../go/palette'
import { GO_sprite_init } from '../../go/sprite'
import { isAncestorName, type ObjectName } from '../../objectNames'
import { GG, gp, pc } from '../../pending'
import { sign_ } from '../../util'
import { collisionProjCS, Projectile_collision_1a, Projectile_udd } from '../Projectile'
import type { Drop } from './classes'
import { rand } from './rand'

/** Fields the spawned enemy sets that only exist on the leaf enemy classes. */
interface SpawnedEnemy extends GameObject {
  HSPD?: number
  VSPD_CHANGE?: number
  VSPD_MAX?: number
  SPAWN_YOFF?: number
  vspd_change?: number
}

export function init_Drop(self: Drop): void {
  GO_sprite_init(self, 'spr_Drop1')
  GO_init_palidx(self, GG().PI_MOB_RED)
  self.vspd_adj = 1
  self.control = 7 // 044C[pIndex]
}

export function update_Drop(self: Drop): void {
  // 98F8 & 98FB
  if (collisionProjCS(self, 0, 0)) {
    if (
      !gmBool(self.control) &&
      available_update_idx_gob(MAX_GOB1) !== UIDX_NULL &&
      from_spawner_count() < 6
    ) {
      let _obj: ObjectName = 'Bot_A'
      let _ver = 1
      const _DATAKEY = STR_Randomize + STR_Enemy
      const settings = GG().dm_save_file_settings
      const _IS_RANDO = gmBool(settings.val(_DATAKEY + STR_Spawner))
      if (_IS_RANDO) {
        const _DIFFICULTY = settings.val(_DATAKEY + STR_Difficulty, 1) as number
        let _difficulty = 0
        if (!_difficulty && _DIFFICULTY >= 4 && !rand.irandom(0x7f)) _difficulty = 4
        if (!_difficulty && _DIFFICULTY >= 3 && !rand.irandom(0x3f)) _difficulty = 3
        if (!_difficulty && _DIFFICULTY >= 2 && !rand.irandom(0x7)) _difficulty = 2
        _difficulty = Math.min(Math.max(_difficulty, 1), gp().RandoEnemy_difficulty_MAX)
        let _datakey = STR_Dripper + STR_Difficulty + hexStr(_difficulty)
        const _COUNT = gp().dm_RandoEnemy.val(_datakey + STR_Count) as number
        if (_COUNT > 1) {
          _datakey += hexStr(rand.irandom(_COUNT - 1))
          _obj = gp().dm_RandoEnemy.val(_datakey + STR_Object, _obj) as ObjectName
          _ver = gp().dm_RandoEnemy.val(_datakey + STR_Version, 1) as number
        }
      }
      // B876 - spawn Bot
      const inst = GameObject_create(0, 0, _obj, _ver) as SpawnedEnemy | null
      if (inst) {
        const player = pc()
        const _OBJVER = inst.objectName + hexStr(inst.ver)
        inst.is_from_spawner = true
        let _dir = input.heldH
        // `update_Drop.gml:155` runs inside `with(GameObject_create(...))`, so `rand()` draws from the
        // *spawned* enemy's OG stream, not the Drop's.
        if (!gmBool(_dir)) _dir = rand.og(inst)
        _dir &= 0x1
        _dir = !gmBool(_dir) ? 1 : -1
        const _CARRY = (player.yt & 0xff) > 2 ? 1 : 0
        let _xl = gp().view_xl_og + ((8 * _dir) & 0xff) + _CARRY
        let _yt = player.yt - 2
        set_xlyt(inst, _xl, _yt)
        inst.facing_dir = dir_to_pc(inst)
        // 9910
        _xl = self.xl
        _yt = (self.y >> 3) << 3
        _yt = get_ground_y(self.x, self.y, -1, _yt)
        _yt -= inst.hh
        set_xlyt(inst, _xl, _yt)
        if (_IS_RANDO) set_xy(inst, self.x, inst.y)
        if (_IS_RANDO) inst.facing_dir = dir_to_pc_(inst)
        if (isAncestorName(inst.objectName, 'Ra__A')) {
          const _Y1 = player.yt + inst.hh_ // where VSPD_MAX should occur
          const _dirY = sign_(inst.y < _Y1)
          inst.hspd = ((inst.HSPD ?? 0) * inst.facing_dir) & 0xff
          inst.vspd = 0
          inst.vspd_change = (inst.VSPD_CHANGE ?? 0) * _dirY
          let _val = Math.abs(inst.y - _Y1)
          const SPAWN_YOFF = inst.SPAWN_YOFF ?? 0
          if (_val < SPAWN_YOFF) {
            _val = SPAWN_YOFF - _val // dist to _Y1
            _val = _val / SPAWN_YOFF // dist to _Y1 percentage
            inst.vspd = round((inst.VSPD_MAX ?? 0) * _val)
            inst.vspd = (inst.vspd >> 1) << 1 // keep it an even value
            inst.vspd = (inst.vspd * _dirY) & 0xff
            inst.vspd_change = (inst.VSPD_CHANGE ?? 0) * _dirY
          }
        } else {
          if (
            gp().dl_RandoEnemy_OBJVER2.findIndex(_OBJVER) === -1 && // if NOT a flying enemy
            !isAncestorName(inst.objectName, 'FokuA') &&
            !isAncestorName(inst.objectName, 'WosuA')
          ) {
            inst.hspd = (0x08 * inst.facing_dir) & 0xff
            inst.vspd = 0xe0
            if (!inst.uses_vspd_sub) inst.vspd = 0xfe // Lowder, Megmat
            if (isAncestorName(inst.objectName, 'MegmA')) inst.vspd = 0xfb + (rand.og(inst) & 0x1)
            if (_IS_RANDO) set_xy(inst, inst.x, inst.y - 1)
          }
          if (isAncestorName(inst.objectName, 'Bot_A')) {
            inst.HP_IDX = 0x04 // g.dl_HP_DEFAULT[|$04] = $04
            inst.hp = gp().dl_HP.get(inst.HP_IDX) as number
            inst.counter = 0xff
          } else if (isAncestorName(inst.objectName, 'StalA')) {
            // Stalfos
            inst.spawn_xl = inst.xl
            inst.spawn_yt = inst.yt
            inst.counter = 1 // has detached from chain
          }
        }
      }
      // 995A
      self.state = 0
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!1
    }
    // 993C
    self.state = self.state_EXPLODE
    self.disintegrate_counter = 0xf2
  } else {
    // 9640, 9943
    self.vspd = (self.vspd + self.vspd_adj) & 0xff
    // DED4
    updateX(self)
    updateY(self)
    GO_update_cam_vars(self)
    if (!ocsH1(self) || self.yt + 8 > deps.cam_yb_max()) {
      // if NO width is w/in ocs area width
      self.state = 0
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!1
    }
    Projectile_udd(self)
    Projectile_collision_1a(self)
  }
}

export function usd_Drop(self: Drop): void {
  self.can_draw_self = true
  self.xScale = 1
  self.palidx_base = gmBool(self.control) ? GG().PI_MOB_RED : GG().PI_MOB_BLU
}
