/**
 * `obj_start` — the boot object of `rmB_Start_Wide`: `obj_start_Create` creates every singleton in ZALiA's
 * order, `obj_start_Step` counts a splash timer then `goto_title_rm()`. `installGameLoop` wires `g_Step` and
 * the screen step/draw into `world.stepHook`.
 * Dropped: DEV timing/debug blocks, the `delta_multiplier` (fixed 60 Hz), commented-out data dumps.
 */
import { ROOM_SPEED_BASE, RUN_RANDOMIZATION_SEED } from '@z2/data'
import { DsMap } from '../../runtime/ds'
import { Instance } from '../../runtime/instance'
import { G, g, p, type World, world } from '../../runtime/world'
import { f_init } from '../file/f_init'
import { load_game_pref } from '../file/prefs'
import { init_save_files } from '../file/save'
import { g_Create } from '../Game/event/g_Create'
import { g_Draw } from '../Game/event/g_Draw'
import { g_Step } from '../Game/event/g_Step'
import { json_decode, json_encode } from '../Game/gm'
import { GameObjectData_Create } from '../game_object/game_object_data/GameObjectData_Create'
import { frameHooks } from '../hooks'
import { notPorted } from '../pending'
import { goto_title_rm } from '../rooms/goto'
import { drawScreens, persistentScreens, resetRooms, roomInstances, stepScreens } from '../rooms/roomChange'
import { FileSelect } from '../rooms/screens'
import { window_set_scale } from '../view/window'
import { drawInstances, wireCore } from '../wire'

/** Create scripts of singletons other ports own; no-op until registered. */
export const bootHooks = {
  Audio_Create: undefined as (() => void) | undefined,
  menus_Create: undefined as (() => void) | undefined,
  Surface_Create: undefined as (() => void) | undefined,
  Overworld_Create: undefined as (() => void) | undefined,
  RoomData_Create: undefined as (() => void) | undefined,
  GameObjectMgr_Create: undefined as (() => void) | undefined,
  BurnableMgr_Create: undefined as (() => void) | undefined,
  /** `instance_create(0,0,Dev_RmWarper/Dev_StabToCheat)` + `p_init.gml:1952`'s `PaletteEditor`. */
  createDevTools: undefined as (() => void) | undefined,
  PC_create: notPorted('PC_create') as (obj: string, x: number, y: number) => void,
  /** `GM_version` */
  appVersion: '1.7.12',
  /** `date_current_datetime()` */
  now: () => Date.now(),
}

export class ObjStart extends Instance {
  readonly objectName = 'obj_start'
  DURATION1 = 0x07
  counter = 0
  COLOR1 = 0x747474 // same as p.C_GRY3
}

/** `obj_start_Create()` */
export function obj_start_Create(self: ObjStart, opts: { createSingletons?: boolean } = {}): void {
  void ROOM_SPEED_BASE // room_speed = ROOM_SPEED_BASE (fixed 60 Hz step)
  G.DB0 = false // DB: DeBug.
  G.App_frame_count = -1
  G.App_frame_count_can_draw = false
  G.App_frame_count_unpaused = -1
  G.App_frame_count_unpaused_can_draw = false
  G.Room_frame_count = -1
  G.Room_frame_count_can_draw = false
  G.use_pal_swap = true
  G.randomized = false
  if (G.randomized)
    world.randomize() // Give game seed a random value. Turn off for debugging.
  else world.random_set_seed(RUN_RANDOMIZATION_SEED)
  self.DURATION1 = 0x07
  self.counter = 0
  self.COLOR1 = 0x747474
  // --------------------------------------------------------------------
  // AppData01.txt: last session's app version + date (used for palette cache invalidation in ZALiA)
  const _FILE_NAME0 = 'AppData01.txt'
  const _dk_APP_VERSION = 'app_version'
  const _dk_SESSION_DATE = 'session_date'
  let _version: string | number = -1
  let _date: string | number = -1
  let _dm: DsMap<string | number> | -1 = -1
  const text = world.storage.readText(_FILE_NAME0)
  if (text !== undefined) {
    _dm = json_decode(text) as DsMap<string | number> | -1
    if (_dm !== -1) {
      _version = _dm.get(_dk_APP_VERSION) ?? _version
      _date = _dm.get(_dk_SESSION_DATE) ?? _date
    }
  }
  G.LAST_APP_SESSION_APP_VER = _version
  G.LAST_APP_SESSION_DATE = _date
  if (_dm === -1) _dm = new DsMap<string | number>()
  _dm.set(_dk_APP_VERSION, bootHooks.appVersion)
  _dm.set(_dk_SESSION_DATE, bootHooks.now())
  world.storage.writeText(_FILE_NAME0, json_encode(_dm))
  // --------------------------------------------------------------------
  if (opts.createSingletons !== false) {
    // instance_create(Input) — exists on World;  g / p — exist, run their Create scripts
    g_Create()
    bootHooks.Audio_Create?.()
    bootHooks.menus_Create?.() // PauseMenu, LevelUpMenu, DialogueWindow, OptionsMenu, QuitAppMenu
    bootHooks.Surface_Create?.()
    f_init()
    bootHooks.Overworld_Create?.()
    bootHooks.RoomData_Create?.()
    GameObjectData_Create()
    bootHooks.GameObjectMgr_Create?.()
    bootHooks.BurnableMgr_Create?.()
    bootHooks.PC_create('Lonk', 0, 0)
    init_save_files()
    load_game_pref()
    window_set_scale(g.WindowScale_scale)
    persistentScreens.push(world.register(new FileSelect()))
    bootHooks.createDevTools?.() // Dev_RmWarper, Dev_StabToCheat (+ PaletteEditor, see dev/index.ts)
  }
  surfaceClear.color = self.COLOR1 // g.surf.draw_clear_color: p.C_GRY3
}

/** `g.surf.draw_clear_color` stand-in until the Surface object is ported: the adapter clears with this. */
export const surfaceClear = { color: 0x747474 }

/** `obj_start_Step()` */
export function obj_start_Step(self: ObjStart): void {
  if (self.counter >= self.DURATION1) {
    goto_title_rm()
  } else {
    if (self.counter < 3) surfaceClear.color = self.COLOR1
    else surfaceClear.color = p.C_BLK1
  }
  self.counter += 1
}

/** Boot a world like the GM runner does: `rmB_Start_Wide` with one `obj_start`. */
export function bootWorld(w: World, opts: { createSingletons?: boolean } = {}): ObjStart {
  wireCore()
  resetRooms()
  const start = w.register(new ObjStart())
  // obj_start is a non-persistent instance of the start room: the room change to the title destroys it.
  roomInstances.push(start as never)
  obj_start_Create(start, opts)
  return start
}

/** Wire the frame: `g_Step` (persistent `g` Step event), then screen Steps, then draws. */
export function installGameLoop(w: World, opts: { gStep?: boolean; splash?: ObjStart } = {}): void {
  const splash = opts.splash
  w.stepHook = () => {
    if (opts.gStep !== false) g_Step()
    if (splash?.exists) obj_start_Step(splash)
    stepScreens()
    if (opts.gStep !== false) {
      // `Surface_Step.gml:217` `color_tiles()`: the tile layers' palette indices for this frame. The Surface
      // object is not ported (its other half is the adapter's post-FX chain), so its one piece of game
      // logic runs here, between the last Step and the draws — where GM would have run it.
      frameHooks.color_tiles()
      g_Draw()
      frameHooks.p_Draw() // the `p` object's own Draw event, at its depth-0 position
      drawInstances()
    }
    drawScreens()
    // GM's Draw End runs after every instance's and screen's Draw event.
    if (opts.gStep !== false) frameHooks.Surface_Draw_End()
  }
}
