import {
  dk_RandomCustom,
  STR_Body,
  STR_Count,
  STR_Default,
  STR_Intro,
  STR_Music,
  STR_Qualified,
  STR_Rando,
  STR_Set,
  STR_Track,
  STR_Unique,
  STR_Value,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { world } from '../../runtime/world'
import { Audio, type SoundId } from './Audio'
import type { AudioGroup } from './playback'

const isRandomSet = (set: string) => set.toUpperCase().includes('RANDOM')

/** `get_audio_theme_track(audio theme)` — the track for the theme in the selected set, else the default set's. */
export function get_audio_theme_track(theme: string): SoundId {
  if (isRandomSet(Audio.audio_set)) return get_audio_theme_track_random(theme)
  const _DEFAULT = Audio.dm.val(theme + (Audio.dl_AUDIO_SETS.get(0) ?? STR_Default)) as SoundId
  return Audio.dm.val(theme + Audio.audio_set, _DEFAULT) as SoundId
}

/** `get_audio_theme_track_intro(track)` */
export function get_audio_theme_track_intro(track: SoundId): SoundId {
  return Audio.dm.val(Audio.audio_get_name(track) + STR_Intro, track) as SoundId
}

/** `sound_is_audio_group(sound id, audio group)` */
export function sound_is_audio_group(sound: SoundId | number, group: AudioGroup): boolean {
  return Audio.dm.val(`${Audio.audio_get_name(sound)}_AudioGroup`) === group
}

/** GML `ds_list_shuffle` with the world PRNG (Fisher–Yates). */
function shuffle<T>(items: T[]): void {
  for (let i = items.length - 1; i > 0; i--) {
    const j = world.irandom(i)
    const t = items[i] as T
    items[i] = items[j] as T
    items[j] = t
  }
}

/** `get_audio_theme_track_random(theme)` — pick a track among the theme's tracks (RANDOM / RANDOM-CUSTOM). */
export function get_audio_theme_track_random(theme: string): SoundId {
  const dm = Audio.dm
  let _track = dm.val(theme + STR_Default) as SoundId
  const _TRACK_COUNT = Number(dm.val(theme + STR_Track + STR_Count))
  if (_TRACK_COUNT > 1) {
    const _dl_SOUNDS: string[] = []
    if (Audio.audio_set === dk_RandomCustom) {
      const _DK1 = STR_Unique + STR_Track
      const _COUNT = Number(dm.val(theme + _DK1 + STR_Count + STR_Music))
      if (_COUNT) {
        for (let _i = 1; _i <= _COUNT; _i++) {
          const _sound = dm.val(theme + _DK1 + STR_Music + hexStr(_i) + STR_Body) as SoundId
          if (_sound && Audio.dm_random_custom.val(theme + hexStr(_i) + STR_Qualified)) {
            // if it's set in the AUDIO CUSTOM audio set
            if (!dm.val(`${STR_Rando + STR_Value}01${_sound}`) || !world.irandom(0x3)) _dl_SOUNDS.push(_sound)
          }
        }
      } else {
        for (let _i = 1; _i <= _TRACK_COUNT; _i++) {
          const _sound = dm.get(theme + _DK1 + hexStr(_i) + STR_Body) as string | undefined
          if (_sound !== undefined) {
            if (!dm.val(`${STR_Rando + STR_Value}01${_sound}`) || !world.irandom(0x3)) _dl_SOUNDS.push(_sound)
          }
        }
      }
    } else {
      for (let _i = 1; _i <= _TRACK_COUNT; _i++) {
        const _sound = dm.get(theme + STR_Track + hexStr(_i) + STR_Body) as string | undefined
        if (_sound !== undefined) {
          if (!dm.val(`${_sound}${STR_Rando + STR_Value}02`)) {
            if (!dm.val(`${_sound}${STR_Rando + STR_Value}01`) || !world.irandom(0x3)) _dl_SOUNDS.push(_sound)
          }
        }
      }
    }
    if (_dl_SOUNDS.length) {
      shuffle(_dl_SOUNDS)
      _track = _dl_SOUNDS[0] as string
    }
  }
  return _track
}

/** `get_audio_set_by_theme(theme)` — the right audio set in case `Audio.audio_set` is random. */
export function get_audio_set_by_theme(theme: string): string {
  const dm = Audio.dm
  let _return_set = Audio.dl_AUDIO_SETS.get(0) ?? STR_Default
  if (!isRandomSet(Audio.audio_set)) return Audio.audio_set
  const _TRACK_COUNT = Number(dm.val(theme + STR_Track + STR_Count))
  if (_TRACK_COUNT > 1) {
    if (Audio.audio_set === dk_RandomCustom) {
      const _DK1 = STR_Unique + STR_Track
      const _COUNT = Number(dm.val(theme + _DK1 + STR_Count + STR_Music))
      if (_COUNT) {
        const _dl_sets: string[] = []
        for (let _i = 1; _i <= _COUNT; _i++) {
          const _set = dm.get(theme + _DK1 + STR_Music + hexStr(_i) + STR_Set) as string | undefined
          if (_set !== undefined && Audio.dm_random_custom.val(theme + hexStr(_i) + STR_Qualified))
            _dl_sets.push(_set)
        }
        if (_dl_sets.length) {
          shuffle(_dl_sets)
          _return_set = _dl_sets[0] as string
        }
      } else {
        const _NUM = world.irandom(_TRACK_COUNT - 1) + 1
        _return_set = dm.val(theme + _DK1 + hexStr(_NUM) + STR_Set, _return_set) as string
      }
    } else {
      const _NUM = world.irandom(_TRACK_COUNT - 1) + 1
      _return_set = dm.val(theme + STR_Track + hexStr(_NUM) + STR_Set, _return_set) as string
    }
  }
  return _return_set
}
