/** Challenge base scripts: Challenge_init, init_vars_Challenge_1a/2a (Challenge_create is dead in ZALiA). */
import type { ChallengeBase } from './classes'

/** `init_vars_Challenge_1a()` */
export function init_vars_Challenge_1a(self: ChallengeBase): void {
  self.timer = 0
  self.challenge_id = `${self.objectName}00`
}
/** `init_vars_Challenge_2a()` */
export function init_vars_Challenge_2a(self: ChallengeBase): void {
  self.item_spawn_x = 0
  self.item_spawn_y = 0
}
/** `Challenge_init()` — `init_vars_go_A()` are the class fields; then the challenge vars. */
export function Challenge_init(self: ChallengeBase): void {
  init_vars_Challenge_1a(self)
}
