/** Guma (`GumaA`) — bolo thrower. Ported from `Guma_init2/update/udp/draw.gml`. */
import { CS_BD1, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { draw_sprite_, drawState } from '../../../../../rooms/draw'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { GO_draw_sprite } from '../../../../go/draw'
import { dir_to_pc } from '../../../../go/misc'
import { GO_vspd_update1, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { solid_clip_correction } from '../../../../goa/movement'
import type { ObjectName } from '../../../../objectNames'
import { gp } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_1, GOB_update_2 } from '../../../GameObjectB'

export class GumaA extends Enemy {
  readonly objectName = 'GumaA' as const
  VSPD_GRAV = 2
  arm: string | 0 = 0
  Arm_xoff = 4
  Arm_yoff = 0
}

/** `Guma_init2()` */
export function Guma_init2(self: GumaA): void {
  self.projectile_OBJ = 'Bolo'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  GO_init_palidx(self, G.PI_MOB_RED)
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.arm = 0
  self.Arm_xoff = 4
  self.Arm_yoff = 0
}

/** `Guma_update()` — BA57 */
export function Guma_update(self: GumaA): void {
  const g = gp()
  if (!g.counter1) self.vspd = 0xd0
  if (self.counter < 0xd8 && !(self.counter & 0x1f)) {
    // BA6A: JSR BC23
    self.behavior = (self.behavior + 1) & 0xff
    self.timer = 0xf // attack delay timer
  }
  // BA6D
  if (self.timer === 1 && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
    self.behavior = 1
    const p = GOC1_create(
      self.xl,
      self.yt,
      self.facing_dir,
      self.projectile as ObjectName,
      self.projectile_ver,
    ) // Bolo
    p.hspd = (p.hspd >> 1) | (p.hspd & 0x80)
    p.vspd = 0xd5
  }
  // BA90
  if (self.counter & 0x40) self.hspd = -0x8 & 0xff
  else self.hspd = 0x8 & 0xff
  updateY(self)
  self.counter = (self.counter + 1) & 0xff
  GO_update_cs(self)
  // BAA5
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  }
  // MOD. Prevent clip into ceiling
  GO_vspd_update1(self) // if (cs8() && vspd&$80) vspd=$0;
  // BAAE
  GOB_update_1(self, true) // update hspdPB
  GO_update_cs(self)
  if (!(self.cs & 0x3)) updateX(self)
  // BAB1
  GO_update_cs(self)
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  if (!(g.counter1 & 0xf)) self.facing_dir = dir_to_pc(self)
}

/** `Guma_udp()` */
export function Guma_udp(self: GumaA): void {
  const g = gp()
  self.can_draw_self = true
  if (self.cs & 0x4 && g.counter1 & 0x10) self.sprite = 'spr_Guma2'
  else self.sprite = 'spr_Guma1'
  self.arm = 0
  if (gmBool(self.timer)) {
    self.arm = 'spr_Guma_arm'
    self.Arm_xoff = 4 * -self.facing_dir
  }
}

/** `Guma_draw()` */
export function Guma_draw(self: GumaA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawState.depth = self.depth
  pal_swap_set(self.palidx)
  draw_sprite_(self.arm, 0, self.drawX + self.Arm_xoff, self.drawY + self.Arm_yoff, -1, self.xScale)
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

export function registerGuma(): void {
  registerObject('GumaA', GumaA)
  registerScripts({ Guma_init2, Guma_update, Guma_udp, Guma_draw })
}
registerGuma()
