/** `GO_draw_xy_point()` — dev-tools xy marker; no-op until the dev folder is ported. */
const GO_draw_xy_point = (_self: unknown): void => {}

/** `Cutscene_MoaiOpenMouth_init_1()` — shared by both Moai objects. */
export function Cutscene_MoaiOpenMouth_init_1(self: Cutscene_MoaiOpenMouth_1): void {
  Cutscene_init(self)
  switch (self.objectName) {
    case 'Cutscene_MoaiOpenMouth_1': // Kakusu Tomb
      GO_sprite_init(self, 'spr_Moai_mouth_1a_1')
      GO_depth_init(self, DEPTH_BG5 - 1)
      GO_init_palidx(self, G.PI_BGR4)
      break
    case 'Cutscene_MoaiOpenMouth2': // Mido Church
      GO_sprite_init(self, 'spr_Moai_mouth_3a_1') // wider, taller
      GO_depth_init(self, DEPTH_BG5 - 1)
      GO_init_palidx(self, G.PI_BGR4)
      break
  }
  self.sub_state = self.SUB_STATE_IDLE
  self.DUR1 = 0x30
  self.DUR2 = 0x10
  self.DUR3 = 0x30 // stun flash duration
  self.ROWS = self.hh >> 3
  self.rows_up = 0
}

/** `Cutscene_MoaiOpenMouth_1_init_2()` — Kakusu turn-in tomb. */
export function Cutscene_MoaiOpenMouth_1_init_2(self: Cutscene_MoaiOpenMouth_1): void {
  let _CLMS1: number
  let _CLMS2: number
  let _CLM1: number
  if (gmBool(self.x)) {
    // x>0 if using new tile data file, Kakusu positions have moved
    _CLMS1 = 0x0a
    _CLMS2 = 0x17
    _CLM1 = 0x32
  } else {
    _CLMS1 = 0x0a
    _CLMS2 = 0x1d
    _CLM1 = 0x2f
  }
  const _CLM2 = _CLM1 + _CLMS1
  const _CLM3 = _CLM2 + _CLMS2
  const _CLM4 = _CLM3 + _CLMS1
  const _ROW0 = g.rm_rows - PAGE_ROWS
  const _ROWS1 = 0x07
  self.scr_step = Cutscene_MoaiOpenMouth_1_update as never
  const _MAX_KAKUSU = val(g.dm_spawn.get(STR_Kakusu + STR_Count), 12) as number
  self.DEFEATED_GOAL = val(
    f.dm_save_file_settings.get(STR_Kakusu + STR_Required + STR_Count),
    _MAX_KAKUSU,
  ) as number
  self.DEFEATED_COUNT = 0
  self.TurnedIn_count = 0
  self.TurnedIn_DATAKEY = `_Turned_In${STR_Count}`
  // TODO(ZALiA): Determine which sprite each specific Kakusu uses
  const dg = new DsGrid<number>(_MAX_KAKUSU, 5, 0)
  self.dg_TurnedIn = dg
  let _row = _ROW0 + 0x18
  const clms = [_CLM1, _CLM2, _CLM3, _CLM4]
  for (let i = 0; i < 12; i++) {
    if (i && !(i & 3)) _row -= _ROWS1
    dg.set(i, 1, world.irandom(2)) // sprite type 0,1,2
    dg.set(i, 3, (clms[i & 3] as number) << 3)
    dg.set(i, 4, _row << 3)
  }
  const _count = dg.width
  for (let _i = 0; _i < _count; _i++)
    dg.set(_i, 1, val(f.dm_kakusu.get(hexStr(_i + 1) + STR_Sprite + STR_Type), dg.get(_i, 1)) as number)
  if (self.dk_spawn !== undefined)
    self.TurnedIn_count = val(f.dm_quests.get(self.dk_spawn + self.TurnedIn_DATAKEY)) as number
  self.DEFEATED_COUNT = get_kakusu_count()
  self.spawn_xl = (0x47 << 3) + 4 - self.ww_
  self.spawn_yt = (_ROW0 + 0x1b) << 3
  set_xlyt(self, self.spawn_xl, self.spawn_yt)
  if (self.TurnedIn_count >= self.DEFEATED_GOAL) {
    for (const ex of instancesNamed('Exit')) {
      if ((ex.exitNum & 0xff) === g.EXIT_DIR_MID) {
        ex.open = 1
        break
      }
    }
    self.rows_up = self.ROWS
    set_xlyt(self, self.xl, self.spawn_yt - self.hh)
    self.sub_state = self.SUB_STATE_DONE
  }
  for (let _i = 0; _i < self.TurnedIn_count; _i++) dg.set(_i, 0, 1)
  if (self.TurnedIn_count >= self.DEFEATED_COUNT) {
    self.timer = 0
    self.sub_state = self.SUB_STATE_DONE
  }
}

/** `Cutscene_MoaiOpenMouth_1_update()` */
export function Cutscene_MoaiOpenMouth_1_update(self: Cutscene_MoaiOpenMouth_1): void {
  if (gmBool(self.timer)) self.timer--
  const dg = self.dg_TurnedIn as DsGrid<number>
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE: {
      if (gmBool(self.timer)) break
      const _W = 8
      if (wINw(G.pc.x, 1, self.x - (_W >> 1), _W)) {
        g.pc_lock = PC_LOCK_ALL
        g.cutscene = 1
        self.timer = self.DUR1
        self.sub_state = self.SUB_STATE_ACTV1
      }
      break
    }
    case self.SUB_STATE_ACTV1: {
      if (gmBool(self.TurnedIn_count)) {
        for (let _i = dg.width - 1; _i >= 0; _i--) {
          if (gmBool(dg.get(_i, 2))) dg.set(_i, 2, (dg.get(_i, 2) as number) - 1) // stun flash timer
        }
      }
      if (gmBool(self.timer)) break
      if (self.TurnedIn_count < self.DEFEATED_COUNT) {
        const _count = dg.width
        for (let _i = 0; _i < _count; _i++) {
          if (!gmBool(dg.get(_i, 0))) {
            dg.set(_i, 0, 1)
            dg.set(_i, 2, self.DUR3) // $30. stun flash timer
            self.TurnedIn_count++
            f.dm_quests.set(self.dk_spawn + self.TurnedIn_DATAKEY, self.TurnedIn_count)
            aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
            self.timer = self.DUR1
            break
          }
        }
      } else {
        if (self.TurnedIn_count >= self.DEFEATED_GOAL) {
          for (let _i = dg.width - 1; _i >= 0; _i--) dg.set(_i, 2, 0) // timer.  just in case
          aud_play_sound(get_audio_theme_track(STR_Secret))
          self.timer = 0
          self.sub_state = self.SUB_STATE_OPEN1
        } else {
          self.timer = 0
          self.sub_state = self.SUB_STATE_DONE
        }
      }
      break
    }
    case self.SUB_STATE_OPEN1: {
      if (gmBool(self.timer)) break
      if (self.rows_up < self.ROWS) {
        self.rows_up++
        set_xlyt(self, self.xl, self.spawn_yt - (self.rows_up << 3))
        aud_play_sound(get_audio_theme_track(dk_ElevatorMove))
        aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
        self.timer = self.DUR2
      } else {
        self.timer = 0
        self.sub_state = self.SUB_STATE_OPEN2
      }
      break
    }
    case self.SUB_STATE_OPEN2: {
      if (gmBool(self.timer)) break
      for (const ex of instancesNamed('Exit')) {
        if ((ex.exitNum & 0xff) === g.EXIT_DIR_MID) {
          ex.open = 1
          break
        }
      }
      self.timer = 0
      self.sub_state = self.SUB_STATE_DONE
      break
    }
    case self.SUB_STATE_DONE: {
      if (gmBool(self.timer)) break
      g.pc_lock = 0
      g.cutscene = 0
      break
    }
  }
  Cutscene_MoaiOpenMouth_1_udp(self)
}

/** `Cutscene_MoaiOpenMouth_1_udp()` */
export function Cutscene_MoaiOpenMouth_1_udp(self: Cutscene_MoaiOpenMouth_1): void {
  self.can_draw_self = !!self.rows_up
  self.drawX = self.x
  self.drawY = self.y
}

/** `Cutscene_MoaiOpenMouth_1_draw()` — the turned-in Kakusu line-up plus the rising mouth. */
export function Cutscene_MoaiOpenMouth_1_draw(self: Cutscene_MoaiOpenMouth_1): void {
  if (gmBool(self.TurnedIn_count)) {
    const dg = self.dg_TurnedIn as DsGrid<number>
    const _COUNT = dg.width
    for (let _i = 0; _i < _COUNT; _i++) {
      if (!gmBool(dg.get(_i, 0))) continue
      // if turned in -----------------------------------
      const _x = dg.get(_i, 3) as number
      const _y = dg.get(_i, 4) as number
      let _pi: number
      // 2: stun timer
      if (gmBool(dg.get(_i, 2)))
        _pi = p.dg_PI_SEQ.get(0, ((dg.get(_i, 2) as number) >> 1) & 0x3) as number // stun flash
      else _pi = G.PI_GUI2 // PI_GUI2: grey-scale
      switch (dg.get(_i, 1)) {
        // kakusu graphic type
        case 0: // NORM
          pal_swap_set(_pi)
          draw_sprite_('spr_Bot2_Norm', 0, _x, _y, _pi)
          draw_sprite_('spr_Bot_Eyes_1a_1', 0, _x, _y, _pi)
          pal_swap_reset()
          draw_sprite_('spr_1x1_WHT', 0, _x - 1, _y + 3, -1, 2, 1, get_pal_color(p.pal_rm_new, _pi, 'B'))
          break
        case 1: // CYCLOPES EYE
          pal_swap_set(_pi)
          draw_sprite_('spr_Bot2_Norm', 0, _x, _y, _pi)
          draw_sprite_('spr_Eye_Open_1b_WRB', 0, _x, _y + 2, _pi) // eye half open
          pal_swap_reset()
          draw_sprite_('spr_1x1_WHT', 0, _x - 1, _y + 1, -1, 2, 1, get_pal_color(p.pal_rm_new, _pi, 'B'))
          break
        case 2: // TRANSPARENT
          pal_swap_set(_pi)
          draw_sprite_('spr_Slime_Small_1b_WRB', 0, _x, _y, _pi) // small slime
          draw_sprite_('spr_Slime_Transparent_1a_WRB', 0, _x, _y, _pi) // transparent body
          pal_swap_reset()
          break
      }
    }
  }
  if (!self.can_draw_self) return
  draw_sprite_(self.sprite as string, 0, self.drawX, self.drawY, self.palidx)
  GO_draw_xy_point(self)
}

/** `Cutscene_MoaiOpenMouth_1_end()` */
export function Cutscene_MoaiOpenMouth_1_end(self: Cutscene_MoaiOpenMouth_1): void {
  self.dg_TurnedIn = undefined
}

/** `Cutscene_MoaiOpenMouth2_init_2()` — Mido church door. */
export function Cutscene_MoaiOpenMouth2_init_2(self: Cutscene_MoaiOpenMouth2): void {
  const _ROW0 = g.rm_rows - PAGE_ROWS
  self.scr_step = Cutscene_MoaiOpenMouth2_update as never
  GO_sprite_init(self, 'spr_Moai_mouth_3a') // wider, taller
  self.TILE_DEPTH = DEPTH_BG5
  GO_depth_init(self, self.TILE_DEPTH - 1)
  self.sub_state = self.SUB_STATE_IDLE
  self.spawn_xl = 0x1d << 3
  self.spawn_yt = (_ROW0 + 0x1c) << 3 // _ROW0+$1C: ground row
  set_xlyt(self, self.spawn_xl, self.spawn_yt)
  self.PC_DEPTH = self.TILE_DEPTH + 1
  self.PC_DEPTH_DEF = G.pc.depth_def
  let _EXIT_NAME = `${g.rm_name}00`
  if (self.dk_spawn !== undefined)
    _EXIT_NAME = val(g.dm_spawn.get(`${self.dk_spawn + STR_Data}01`), _EXIT_NAME) as string
  self.Exit_inst = NOONE
  for (const ex of instancesNamed('Exit')) {
    if (ex.exitName === _EXIT_NAME) {
      self.Exit_inst = ex
      break
    }
  }
  self.opened = false
  if (self.dk_spawn !== undefined) self.opened = gmBool(val(f.dm_quests.get(self.dk_spawn + STR_Open)))
  if (self.opened) {
    if (self.Exit_inst) (self.Exit_inst as unknown as { open: number }).open = 1
    self.rows_up = self.ROWS
    set_xlyt(self, self.xl, self.spawn_yt - self.hh)
    for (let _i = 0; _i < self.ww >> 3; _i++) {
      const _x = self.xl + (_i << 3)
      for (let _j = 0; _j < self.ROWS; _j++) {
        // Remove tiles behind sprite
        tile_change_1a(self.TILE_DEPTH, _x, self.yt + (_j << 3), 0, 0)
      }
    }
  }
  if (self.opened || self.Exit_inst !== g.exit_enter) {
    self.timer = 0
    self.sub_state = self.SUB_STATE_DONE
  }
}

/** `Cutscene_MoaiOpenMouth2_update()` */
export function Cutscene_MoaiOpenMouth2_update(self: Cutscene_MoaiOpenMouth2): void {
  if (g.ChangeRoom_timer > 0) return
  if (gmBool(self.timer)) self.timer--
  const pc = G.pc
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE: {
      if (gmBool(self.timer)) break
      pc.depth_def = self.PC_DEPTH
      set_xy(pc, self.x, self.yt - pc.hh_)
      g.pc_lock = PC_LOCK_ALL
      g.cutscene = 1
      if (pc.state !== pc.state_NORMAL) break
      self.timer = 0x40
      self.sub_state = self.SUB_STATE_OPEN1
      break
    }
    case self.SUB_STATE_ACTV1: {
      if (gmBool(self.timer)) break
      break
    }
    case self.SUB_STATE_OPEN1: {
      if (gmBool(self.timer)) break
      pc.depth_def = self.PC_DEPTH
      if (self.rows_up < self.ROWS) {
        self.rows_up++
        set_xlyt(self, self.xl, self.spawn_yt - (self.rows_up << 3))
        for (let _i = 0; _i < self.ww >> 3; _i++)
          tile_change_1a(self.TILE_DEPTH, self.xl + (_i << 3), self.yt, 0, 0) // Remove tiles behind sprite
        aud_play_sound(get_audio_theme_track(dk_ElevatorMove))
        aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
        self.timer = self.DUR2
      } else {
        self.timer = 0
        self.sub_state = self.SUB_STATE_OPEN2
      }
      break
    }
    case self.SUB_STATE_OPEN2: {
      if (gmBool(self.timer)) break
      pc.depth_def = self.PC_DEPTH_DEF
      // FIDELITY: GML dereferenced Exit_inst unconditionally; guard `noone`.
      if (self.Exit_inst) (self.Exit_inst as unknown as { open: number }).open = 1
      self.opened = true
      if (self.dk_spawn !== undefined) f.dm_quests.set(self.dk_spawn + STR_Open, 1)
      self.timer = 0
      self.sub_state = self.SUB_STATE_WALK
      break
    }
    case self.SUB_STATE_WALK: {
      // Move PC from door center so player can't accidentally exit the door.
      if (gmBool(self.timer)) break
      pc.depth_def = self.PC_DEPTH_DEF
      const _X = self.x - self.ww_ - 0x10
      pc.WalkTo_active = true
      pc.WalkTo_x = _X
      pc.WalkTo_hspd_max = 0x10
      if (pc.x === _X) {
        pc.WalkTo_active = false
        pc.depth_def = self.PC_DEPTH_DEF
        g.pc_lock = 0
        g.cutscene = 0
        self.timer = 0
        self.sub_state = self.SUB_STATE_DONE
      }
      break
    }
    case self.SUB_STATE_DONE: {
      if (gmBool(self.timer)) break
      break
    }
  }
  Cutscene_MoaiOpenMouth_1_udp(self)
}

/** `Cutscene_MoaiOpenMouth2_draw()` */
export function Cutscene_MoaiOpenMouth2_draw(self: Cutscene_MoaiOpenMouth2): void {
  if (!self.can_draw_self) return
  draw_sprite_(self.sprite as string, 0, self.drawX, self.drawY, self.palidx)
  GO_draw_xy_point(self)
}
