/**
 * Hostile projectiles whose behaviour is a one-liner over the shared bases: Axe, Bolo, Bullet1/2, Mace1/2,
 * Rock1/2/3, Spear, SwordBeam, RisingBubble, SoundWave, BossExplosion.
 * ZALiA has byte-identical duplicates (`update_Axe`/`update_Rock1`, `usd_Bolo`/`usd_Boomerang`/`usd_Mace2`);
 * implemented once, exported under every GML name.
 */
import { DEPTH_ENEMY_EXPLOSION } from '@z2/data'
import { byteNegate, gmBool, isVal } from '../../../../nes/math8'
import { instanceExists } from '../../../../runtime/instance'
import { g } from '../../../../runtime/world'
import { rectInRect } from '../../../collision/geometry'
import { update_body_hb_1a } from '../../../collision/hitbox'
import { byte_dir } from '../../../math/index'
import type { GameObjectC } from '../../classes'
import { draw_sprite_ } from '../../go/draw'
import { GO_udp_1, update_draw_xy } from '../../go/movement'
import { GO_init_palidx, GO_update_pal_flash } from '../../go/palette'
import { GO_depth_init, GO_set_sprite, GO_sprite_init } from '../../go/sprite'
import { damage_gob } from '../../gob/GameObjectB'
import { isAncestorName } from '../../objectNames'
import { fp, GG, gp } from '../../pending'
import {
  collisionProjCS,
  isProjSprAdjFrame,
  Projectile_udd_1a,
  Projectile_update_1a,
  Projectile_update_3a,
} from '../Projectile'
import type { BossExplosion, Mace2, RisingBubble, SoundWave, Spear } from './classes'
import { projDeps } from './deps'

// ---- Axe -----------------------------------------------------------------------------------------
export function init_Axe(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Axe1')
  self.dl_sprites?.set(1, 'spr_Axe2')
  self.dl_sprites?.set(0, 'spr_Axe1')
  GO_init_palidx(self, GG().PI_MOB_RED)
}
/** `update_Axe()` — 9639, 96FF: JSR DED4. (byte-identical to `update_Rock1`) */
export function update_Axe(self: GameObjectC): void {
  Projectile_update_3a(self, self.despawn_offscreen_hor) // vspd_adj == 0;
}
export function usd_Axe(self: GameObjectC): void {
  self.can_draw_self = true
  // spr_Axe1, spr_Axe2
  const idx = gmBool(g.counter1 & 0x4) && self.dl_sprites?.get(1) !== undefined ? 1 : 0
  self.sprite = self.dl_sprites?.get(idx) ?? 0
  if (g.counter1 & 0x8) {
    self.xScale = 1
    self.yScale = 1
  } else {
    self.xScale = -1
    self.yScale = -1
  }
  self.xScale *= self.facing_dir // If facing left, xScale need to flip
}

// ---- Bolo ----------------------------------------------------------------------------------------
export function init_Bolo(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Bolo1')
  GO_init_palidx(self, GG().PI_MOB_RED)
  self.vspd_adj = 1
  self.despawn_offscreen_hor = false
}
/** `update_Bolo()` — 9940 */
export function update_Bolo(self: GameObjectC): void {
  Projectile_update_3a(self, self.despawn_offscreen_hor) // vspd_adj == 1;
}
/** `usd_Bolo()` (= `usd_Boomerang` = `usd_Mace2`) */
export function usd_Bolo(self: GameObjectC): void {
  Projectile_udd_1a(self)
}

// ---- Bullet1 / Bullet2 -----------------------------------------------------------------------------
/** `init_Bullet1()` — BulletSpawner, HelmetHeadHead, Mau, HelmetHead */
export function init_Bullet1(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Bullet1')
  GO_init_palidx(self, GG().PI_MOB_BLU)
}
/** `init_Bullet2()` — Tektite, Zora */
export function init_Bullet2(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Bullet1')
  self.pal_flash_time = 1
}
/** `update_Bullet1()` — 974E */
export function update_Bullet1(self: GameObjectC): void {
  // if (yt>=$C5) // OG
  // ver 2 from Mau
  if (collisionProjCS(self, 0, 0) && self.ver !== 2) {
    // 9754
    self.disintegrate_counter = 0xf4
    self.state = self.state_EXPLODE
  } else {
    // 9759
    Projectile_update_1a(self, self.despawn_offscreen_hor) // Projectile_update_1a(!isVal(pID, 6, 8));
  }
}
/** `update_Bullet2()` — 962F, 9634 */
export function update_Bullet2(self: GameObjectC): void {
  Projectile_update_3a(self, self.despawn_offscreen_hor) // vspd_adj == 0;
}
export function usd_Bullet1(self: GameObjectC): void {
  self.can_draw_self = true
  if (gmBool(self.pal_flash_time)) self.palidx = GO_update_pal_flash(g.counter1, self.pal_flash_time)
}

// ---- Mace1 / Mace2 ---------------------------------------------------------------------------------
/** `init_Mace1()` — Used by Geru v3 (Blue) */
export function init_Mace1(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Mace1')
  GO_init_palidx(self, GG().PI_MOB_BLU)
}
/** `init_Mace2()` — Used by Doomknocker */
export function init_Mace2(self: Mace2): void {
  GO_sprite_init(self, 'spr_Mace2')
  GO_init_palidx(self, GG().PI_MOB_BLU)
  self.reverse_ctr = 0
}
/** `update_Mace1()` — 962F, 9665 */
export function update_Mace1(self: GameObjectC): void {
  Projectile_update_3a(self, self.despawn_offscreen_hor) // vspd_adj == 0;
}
/** `update_Mace2()` — AD0D */
export function update_Mace2(self: Mace2): void {
  if (gmBool(self.counter)) self.counter--
  if (!gmBool(self.counter) || self.counter & 0x80) {
    // AD17
    self.facing_dir = -self.facing_dir
    self.hspd = byteNegate(self.hspd)
    self.counter = 0x80
    self.reverse_ctr++
    if (self.reverse_ctr >= 2 && self.source_object !== 0 && isAncestorName(self.source_object, 'DoomA')) {
      // OG would remove if off screen, so this compensates.
      self.state = 0
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
  }
  // ADB4, ADBF
  Projectile_update_3a(self, self.despawn_offscreen_hor) // Projectile_update_1a(pID != 8);
}
/** `usd_Mace1()` — same as Projectile_udd_1a() except xscale & yscale get opposite dirs */
export function usd_Mace1(self: GameObjectC): void {
  self.can_draw_self = true
  self.xScale = isVal(g.counter1 & 0xc, 4, 8) ? -1 : 1
  self.yScale = g.counter1 & 0x8 ? -1 : 1
  self.xScale *= self.facing_dir // If facing left, xScale need to flip
  self.xScale *= -1 // Because the sprites are backwards in my game
}

// ---- Rock1 / Rock2 / Rock3 ---------------------------------------------------------------------------
export function init_Rock1(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Rock1')
  GO_init_palidx(self, GG().PI_MOB_RED)
}
/** `init_Rock2()` — Used by Aneru, Bago, Octorok */
export function init_Rock2(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Rock1')
  GO_init_palidx(self, GG().PI_MOB_RED)
  self.vspd_adj = 2
}
export function init_Rock3(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Rock1')
  GO_init_palidx(self, GG().PI_MOB_RED)
  self.vspd_adj = 1
}
/** `update_Rock2()` — 965A */
export function update_Rock2(self: GameObjectC): void {
  // if havn't bounced off shield
  if (!self.collided_shield) self.vspd = -self.vspd_adj & 0xff
  Projectile_update_3a(self, self.despawn_offscreen_hor) // vspd_adj == 2;
}
/** `update_Rock3()` — 965B */
export function update_Rock3(self: GameObjectC): void {
  if (!collisionProjCS(self, 0, 0)) {
    // 9662, 9665
    Projectile_update_3a(self, self.despawn_offscreen_hor)
  } else {
    // 9670
    self.disintegrate_counter = 0xf3
    self.state = self.state_EXPLODE
  }
}
export function usd_Rock(self: GameObjectC): void {
  self.can_draw_self = true
  if (isAncestorName(self.objectName, 'Rock1') && self.state === self.state_NORMAL && g.counter1 & 0x10) {
    self.draw_yoff = g.counter1 & 0x20 ? -2 : 2
  } else self.draw_yoff = 0
  self.xScale = self.facing_dir
  self.yScale = g.counter1 & 0x4 && self.state === self.state_NORMAL ? -1 : 1
}

// ---- Spear -------------------------------------------------------------------------------------------
export function init_Spear(self: Spear): void {
  self.dl_sprites?.set(1, 'spr_Spear_piece2') // pole
  self.dl_sprites?.set(0, 'spr_Spear_piece1') // tip
  GO_set_sprite(self, 'spr_Spear_piece1')
  self.vspd_adj = 2
  self.spr_L = self.dl_sprites?.get(self.facing_dir === 1 ? 1 : 0) ?? 0
  self.spr_R = self.dl_sprites?.get(self.facing_dir !== 1 ? 1 : 0) ?? 0
  // palIndex_def set in Projectile_create() before init_Spear()
  self.palIdx_L = self.palidx_def
  self.palIdx_R = self.palidx_def
  self.xScale_L = self.facing_dir
  self.xScale_R = self.facing_dir
}
/** `update_Spear()` — 963E, 96FF: JSR DED4 */
export function update_Spear(self: GameObjectC): void {
  Projectile_update_3a(self, self.despawn_offscreen_hor) // vspd_adj == 2;
}
export function usd_Spear(self: Spear): void {
  self.can_draw_self = true
  self.xScale_L = self.facing_dir
  self.xScale_R = self.facing_dir
  self.palIdx_L = self.palidx_def
  self.palIdx_R = self.palidx_def
  if (isProjSprAdjFrame(self)) {
    self.xScale_L *= -1
    self.palIdx_L = GG().PI_PC1
  }
  // sprites[0]: tip, sprites[1]: pole
  self.spr_L = self.dl_sprites?.get(self.facing_dir === 1 ? 1 : 0) ?? 0
  self.spr_R = self.dl_sprites?.get(self.facing_dir !== 1 ? 1 : 0) ?? 0
}
export function draw_Spear(self: Spear): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (self.spr_L)
    draw_sprite_(self.spr_L, 0, self.drawX, self.drawY, self.palIdx_L, self.xScale_L, 1, self.depth)
  if (self.spr_R)
    draw_sprite_(self.spr_R, 0, self.drawX + 8, self.drawY, self.palIdx_R, self.xScale_R, 1, self.depth)
}

