// ---- RisingBubble ------------------------------------------------------------------------------------
export function init_RisingBubble(self: RisingBubble): void {
  GO_sprite_init(self, 'spr_Rising_Bubble_01')
  GO_init_palidx(self, GG().PI_MOB_RED)
  // Set in front of water & fg terrain
  GO_depth_init(self, (gp().dl_TILE_DEPTHS.get(gp().dl_TILE_DEPTHS.size - 1) as number) - 1)
  self.HSPD1 = 0x04
  self.hspd_base = self.HSPD1
  self.hspd = self.hspd_base // $04 or $FC during update
  self.vspd = 0xe4
  self.facing_dir = 1
  self.counter = 0 // 044C[pIndex]
  self.despawn_offscreen_hor = false
}
export function update_RisingBubble(self: RisingBubble): void {
  if (self.ver === 2 && collisionProjCS(self, 0, 0)) {
    // check at center
    self.disintegrate_counter = 0xf3
    self.state = self.state_EXPLODE
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // 9647
  self.counter = (self.counter + 1) & 0xff
  self.hspd = self.counter & 0x10 ? -self.hspd_base & 0xff : self.hspd_base & 0xff // -4 / 4
  Projectile_update_1a(self, self.despawn_offscreen_hor) // if off-screen hor: Stay spawned
}
export function usd_RisingBubble(self: GameObjectC): void {
  self.can_draw_self = true
  self.xScale = g.counter1 & 0x2 ? -self.facing_dir : self.facing_dir
}

// ---- SoundWave ---------------------------------------------------------------------------------------
export function init_SoundWave(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_SoundWave1')
  GO_init_palidx(self, GG().PI_MOB_RED)
  self.counter = 1 // 044C[p.Index]
  self.vspd = 0
  self.vspd_sub = 0
  self.vspd_grav = 0
  self.vspd_adj = 0
}
export function update_SoundWave(self: SoundWave): void {
  let _collided_src = false
  const src = self.source_inst
  // AD29
  if (
    self.reflected &&
    instanceExists(src) &&
    gmBool(src.hp) &&
    src.state === src.state_NORMAL &&
    gmBool(src.behavior)
  ) {
    // AD3E
    update_body_hb_1a(self)
    update_body_hb_1a(src)
    if (
      rectInRect(
        self.BodyHB_xl,
        self.BodyHB_yt,
        self.BodyHB_w,
        self.BodyHB_h,
        src.BodyHB_xl,
        src.BodyHB_yt,
        src.BodyHB_w,
        src.BodyHB_h,
      )
    ) {
      _collided_src = true
      self.disintegrate_counter = 0xf2
      self.state = self.state_EXPLODE
      const isCarock = isAncestorName(src.objectName, 'Carock01')
      const _DAMAGE =
        isCarock || isAncestorName(src.objectName, 'WizaA')
          ? 2
          : (gp().dg_enemy_damage.get(fp().level_lif - 1, self.attack_level) as number)
      damage_gob(src, _DAMAGE, true) // damage enemy
      if (isCarock) projDeps.Boss_update_5(src) // $22 Carock
    }
  }
  if (!_collided_src) {
    // ADB4, ADBF
    Projectile_update_3a(self, self.despawn_offscreen_hor) // Projectile_update_1a(pID != 8);
  }
}
/** `usd_SoundWave()` — AE11 */
export function usd_SoundWave(self: GameObjectC): void {
  self.can_draw_self = true
  self.xScale = byte_dir(self.hspd) // -1 if & $80, else 1
  self.palidx = GO_update_pal_flash(g.counter1, 1)
}

// ---- BossExplosion -----------------------------------------------------------------------------------
export function init_BossExplosion(self: BossExplosion): void {
  GO_depth_init(self, DEPTH_ENEMY_EXPLOSION)
  self.dl_sprites?.set(1, gp().BossExplosion_SPR2) // big
  self.dl_sprites?.set(0, gp().BossExplosion_SPR1) // small
  GO_sprite_init(self, self.dl_sprites?.get(0) ?? gp().BossExplosion_SPR1)
  GO_init_palidx(self, GG().PI_MOB_ORG)
  self.timer = gp().BossExplosion_Inst_DURATION // life duration timer
}
/** `update_BossExplosion()` — 9767 */
export function update_BossExplosion(self: GameObjectC): void {
  if (gmBool(self.timer)) {
    // 976E
    GO_udp_1(self) // drawX=x; drawY=y; xScale=facingDir;
    if (self.scr_udp) self.scr_udp(self)
    update_draw_xy(self) // drawX=x+DRAW_XOFF+drawXOff, drawY=y+DRAW_YOFF+drawYOff
  } else {
    // 995A
    self.state = 0
  }
}
/** `usd_BossExplosion()` — 976E */
export function usd_BossExplosion(self: GameObjectC): void {
  self.can_draw_self = true
  self.xScale = 1
  if (self.timer & 0x8) self.sprite = self.dl_sprites?.get(0) ?? 0
  else self.sprite = self.dl_sprites?.get(self.dl_sprites.get(1) !== undefined ? 1 : 0) ?? 0
}
export function draw_BossExplosion(self: GameObjectC): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!self.sprite) return
  draw_sprite_(self.sprite, 0, self.drawX, self.drawY, self.palidx, 1, 1, self.depth)
  draw_sprite_(self.sprite, 0, self.drawX, self.drawY, self.palidx, -1, 1, self.depth)
}
