/**
 * Fenser — Helmethead's flying head (ZALiA object `HelmetheadHead01`, parent `Enemy`; scripts in the enemy
 * `fenser` folder, data row in the boss section). `Fenser_init1/init2/update.gml` (`Fenser_update_OG` is dead).
 * Coordinator: the boss fork may also declare `HelmetheadHead01` — keep one.
 */
import { CS_BD1, dk_HitShield, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { abs8b, gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { viewYB } from '../../../../../collision/env'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { get_ground_y } from '../../../../../collision/solid'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { sign_ } from '../../../../../math/index'
import { str_hex } from '../../../../../other/index'
import { play_theme_sound } from '../../../../../sound/play'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { dir_to_pc } from '../../../../go/misc'
import { set_xy, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GameObjectB_init, gobCollision, update_EF11 } from '../../../GameObjectB'
import { goDist1, projOf } from '../ache/_shared'

export class HelmetheadHead01 extends Enemy {
  readonly objectName = 'HelmetheadHead01' as const
  is_from_HelmetHead = false
  control = 0 // 0401[eIndex]
  Rise_yt = 0
  Rise_YT = 0
  Rise_done = false // 0444[eIndex]
  Bounce_MAX = 3
  Bounce_VSPD = 0x20
  Bounce_vspd = 0
  GROUND_Y = 0
}

/** `Fenser_init1()` */
export function Fenser_init1(self: HelmetheadHead01): void {
  GameObjectB_init(self)
  self.is_from_HelmetHead = false
  self.control = 0 // 0401[eIndex]
  self.projectile_OBJ = 'Bullet1'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.Rise_yt = 0
  self.Rise_done = false // 0444[eIndex]
  self.Bounce_MAX = 3
  self.Bounce_VSPD = 0x20
  self.Bounce_vspd = 0
}

/** `Fenser_init2()` */
export function Fenser_init2(self: HelmetheadHead01): void {
  GO_init_palidx(self, G.PI_MOB_BLU)
  const _DIST = 0x60
  self.GROUND_Y = get_ground_y(self.x, self.spawn_yt, 1, self.spawn_yt)
  if (gmBool(self.GROUND_Y)) self.Rise_YT = self.GROUND_Y - _DIST
  else self.Rise_YT = ((viewYB() >> 3) << 3) - 0x18 - _DIST
  self.Rise_yt = self.Rise_YT
}

/** `Fenser_update()` — BCEF: knocked-off head bounces, rises, then undulates and shoots. */
export function Fenser_update(self: HelmetheadHead01): void {
  const P = pc()
  // BCEF: JSR EF11
  self.can_draw_self = true
  update_EF11(self)
  // BCF2
  gobCollision.GOB_body_collide_pc_body_1a(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // BCF8: JSR DEB8
  updateX(self)
  GO_update_cs(self)
  // BCFB. In OG the head performs its vertical wave near the ground after a second fall (Rise_done stays set).
  if (self.counter < self.Bounce_MAX) {
    // Bounce counter. Knocked off Helmethead, falling
    if (self.cs & 0x3) {
      self.hspd_dir = -sign_(self.cs & 0x1) // go opposite dir of collision side
      self.hspd = (abs8b(self.hspd) * self.hspd_dir) & 0xff
      let _AMT = 0
      if (self.cs & 0x1)
        _AMT = -(self.csRgt1X & 0x7) - 1 // colliding on the RIGHT
      else _AMT = -(self.csLft1X & 0x7) + 8 + 1 // colliding on the LEFT
      set_xy(self, self.x + _AMT, self.y)
      play_theme_sound(dk_HitShield)
    }
    // Head image is 8x16. 4th pixel from the btm is the btm of the head.
    const _Y_MAX = viewYB() + 8
    if (self.cs & 0x4 || self.y >= _Y_MAX) {
      self.timer = 0x30
      self.hspd = (self.hspd >> 1) | (self.hspd & 0x80)
      if (!self.counter) self.Bounce_vspd = self.Bounce_VSPD
      self.vspd = -self.Bounce_vspd & 0xff // $E0 -> $E8 -> $F0
      self.Bounce_vspd -= 8 // $20 -> $18 -> $10
      if (!(self.cs & 0x4)) self.vspd = 0
      self.counter = (self.counter + 1) & 0xff
      if (self.cs & 0x4) {
        play_theme_sound(dk_HitShield)
        set_xy(self, self.x, ((self.csBtm1Y >> 3) << 3) - (self.csBtm1Y - self.y))
      } else {
        // y>=_Y_MAX: for using obj in scenario other than Helmethead fight where it may fall into a pit.
        if (self.Rise_done) {
          // not 1st fall
          if (P.yt > self.Rise_YT)
            self.Rise_yt = P.yt // not 1st rise, wave height close to PC
          else self.Rise_yt = self.Rise_YT
        }
        if (!self.is_from_HelmetHead) self.Rise_yt = self.Rise_YT
        self.Rise_done = false
        set_xy(self, self.x, _Y_MAX)
      }
      if (!(self.cs & 0x4) || self.Bounce_vspd <= 8) {
        self.counter = self.Bounce_MAX + +!(self.Bounce_MAX & 0x1) // set counter odd, if even
      }
    }
    // BD21: JMP DEBE: JSR DEC8
    updateY(self)
    self.vspd = (self.vspd + 2) & 0xff
  } else {
    // BD24. All bounces complete
    if (!self.Rise_done && self.yt >= self.Rise_yt) {
      // Raising off ground. BD2D
      self.hspd = 0
      self.vspd = 0
      if (!gmBool(self.timer)) set_xy(self, self.x, self.y - 2)
    } else {
      // BD3E. undulating
      self.Rise_done = true
      updateY(self)
      let _DIR = 1 // making wave up to down /\    Downward force
      if (self.counter & 0x1) _DIR = -1 // making wave down to up   \/    Upward force
      self.vspd = (self.vspd + _DIR) & 0xff
      if (self.vspd === ((0x18 * _DIR) & 0xff)) {
        // reached end of wave
        self.counter = (self.counter + 1) & 0xff
        if (gmBool(g.mod_FenserFix1) || !self.is_from_HelmetHead) {
          // MOD. Will go back to correct height after falling again.
          if (!self.counter) self.Rise_done = false
        }
      }
      if (!g.counter1) {
        self.facing_dir = dir_to_pc(self)
        self.hspd = (0x06 * self.facing_dir) & 0xff
      }
      // BD66
      self.control = (self.control + 1) & 0xff
      if (
        !(self.control & 0x7f) &&
        self.facing_dir === dir_to_pc(self) &&
        avail_uidx_goc(MAX_GOC1) !== UIDX_NULL
      ) {
        // BD6F: JSR 9BE5: JSR DBCE
        let _idx = goDist1(self)
        if (_idx & 0x80) _idx ^= 0xff
        _idx = ((_idx - 0x14) & 0xff) >> 4
        if (_idx < 8) {
          // Create Bullet1, pID $10
          const proj = GOC1_create(
            self.xl,
            self.yt,
            self.facing_dir,
            projOf(self),
            self.projectile_ver,
            self,
            G.PI_MOB_BLU,
          )
          proj.vspd = str_hex('161413110F0E0D0B', _idx) // 9BD5-9BDC
          proj.hspd = str_hex('060A0D0F11121313', _idx) // 9BCD-9BD4
          // GML `if (!facing_dir)`: facing left (-1) is falsy → flip
          if (!gmBool(self.facing_dir)) proj.hspd ^= 0xff
          const _y1 = g.view_yt_og - 8 // OG 0y
          let _y = self.yt - _y1
          _y += 5
          let _x = self.xl + 4 + +(_y > 0xff)
          _x += proj.sprite_index_xoff
          _y &= 0xff
          _y = _y1 + _y
          _y += proj.sprite_index_yoff
          set_xy(proj, _x, _y)
        }
      }
    }
  }
  if (gmBool(self.hspd)) self.hspd_dir = sign_(self.hspd < 0x80)
  if (gmBool(self.vspd)) self.vspd_dir = sign_(self.vspd < 0x80)
}

registerObject('HelmetheadHead01', HelmetheadHead01)
registerScripts({ Fenser_init1, Fenser_init2, Fenser_update })
