/** Solid-tile grid queries (`global.dg_solid`) and solid instances (`g.dl_solid_inst`). */
import { TID_ONEWY1, TID_SOLID1 } from '@z2/data'
import { instanceExists, NOONE, type Ref } from '../../runtime/instance'
import { round8, sign_ } from '../math'
import type { GoBody, SolidInst } from './body'
import { cam_xl_min, cam_xr_max, cam_yb_max, cam_yt_min, env, viewYC } from './env'
import { is_in_grid, rectInRect } from './geometry'

/** `collide_solid_grid(x, y)` — solid bits of the 8×8 tile under a pixel, 0 outside the grid. */
export function collide_solid_grid(x: number, y: number): number {
  const s = env.solid()
  if (x >= 0 && y >= 0 && x >> 3 < s.w && y >> 3 < s.h) return s.grid.get(x >> 3, y >> 3) ?? 0
  return 0
}

/** `collide_solid_inst(x, y)` — the solid instance whose body hitbox contains the point, else noone. */
export function collide_solid_inst(x: number, y: number): Ref<SolidInst> {
  const list = env.solidInsts()
  for (let i = list.length - 1; i >= 0; i--) {
    const inst = list[i]
    if (
      instanceExists(inst as SolidInst | null | undefined) &&
      inst &&
      inst.state === inst.state_NORMAL &&
      inst.solid_type &&
      rectInRect(x, y, 1, 1, inst.BodyHB_xl, inst.BodyHB_yt, inst.BodyHB_w, inst.BodyHB_h)
    ) {
      return inst
    }
  }
  return NOONE
}

/** `inst_collide_solid_type(inst id, x, y)` — solid type at a point from instances (not self) or the grid. */
export function inst_collide_solid_type(self: { id: number } | null, x: number, y: number): number {
  const inst = collide_solid_inst(x, y)
  if (inst?.solid_type && inst !== self) return inst.solid_type
  return collide_solid_grid(x, y)
}

/**
 * `find_rc_solid(solid bits, clm start, row start, clm dir, row dir, *limit, *default)` —
 * walk the solid grid within the camera range; returns `row<<8 | clm` of the first tile matching
 * `bits` (or the first non-solid tile when bits = 0), else `dflt` (-1).
 */
export function find_rc_solid(
  bits0: number,
  clm0: number,
  row0: number,
  clmDir0: number,
  rowDir0: number,
  limit?: number,
  dflt?: number,
): number {
  const bits = bits0 & 0xf
  const clmDir = Math.sign(clmDir0)
  const rowDir = Math.sign(rowDir0)
  let count = 0xff
  if (limit !== undefined) count = Math.min(Math.abs(limit), count)
  if (!count) count = 0xff // Pass 0 for max limit.
  const DEFAULT = dflt === undefined ? -1 : dflt & 0xffff
  const s = env.solid()
  const minX = Math.max(0, cam_xl_min() >> 3)
  const minY = Math.max(0, cam_yt_min() >> 3)
  const gridW = Math.min(s.w, cam_xr_max() >> 3) - minX
  const gridH = Math.min(s.h, cam_yb_max() >> 3) - minY
  let clm = clm0
  let row = row0
  for (let i = 0; i < count; i++) {
    if (!is_in_grid(clm - minX, row - minY, gridW, gridH)) break
    const v = s.grid.get(clm, row) ?? 0
    if (v & bits) return (row << 8) | clm // found solid row & clm
    if (bits === 0 && !v) return (row << 8) | clm // found non-solid
    // If no dir was specified, this break allows at least 1 check.
    if (clmDir === 0 && rowDir === 0) break
    clm += clmDir
    row += rowDir
  }
  return DEFAULT
}

/** `find_clm_solid(solid bits, clm start, row, clm dir, *limit, *none found clm)` → clm byte ($FF if none). */
export function find_clm_solid(
  bits: number,
  clm: number,
  row: number,
  clmDir: number,
  limit?: number,
  noneClm?: number,
): number {
  let lim = 0xff
  if (limit !== undefined) lim = Math.min(Math.abs(limit), 0xff)
  if (!lim) lim = 0xff
  const dflt = noneClm === undefined ? -1 : (row << 8) | (noneClm & 0xff)
  return find_rc_solid(bits & 0xf, clm, row, Math.sign(clmDir), 0, lim, dflt) & 0xff
}

/** `find_row_solid(solid bits, clm, row start, row dir, *limit, *none found row)` → row byte ($FF if none). */
export function find_row_solid(
  bits: number,
  clm: number,
  row: number,
  rowDir: number,
  limit?: number,
  noneRow?: number,
): number {
  let lim = 0xff
  if (limit !== undefined) lim = Math.min(Math.abs(limit), lim)
  if (!lim) lim = 0xff
  const dflt = noneRow === undefined ? -1 : (noneRow << 8) | (clm & 0xff)
  const r = find_rc_solid(bits & 0xf, clm, row, 0, Math.sign(rowDir), lim, dflt)
  return (r >> 8) & 0xff
}

/** `find_solid_point(x, y, x dir, y dir, *limit, *default $7FF7FF)` → packed `y:$7FF000 | x:$0007FF`. */
export function find_solid_point(
  x: number,
  y: number,
  xDir: number,
  yDir: number,
  limit?: number,
  dflt?: number,
): number {
  let count = 0xff
  if (limit !== undefined) count = Math.min(Math.abs(limit), count)
  if (!count) count = 0xff
  const DEFAULT = dflt === undefined ? -1 : dflt & (0x7ff000 | 0x0007ff)
  const rc = find_rc_solid((TID_SOLID1 | TID_ONEWY1) & 0xf, x >> 3, y >> 3, xDir, yDir, count)
  if (rc >= 0) {
    let p = ((rc & 0xff00) << 7) | ((y & 7) << 0xc)
    p |= ((rc & 0x00ff) << 3) | ((x & 7) << 0)
    return p
  }
  return DEFAULT
}

/**
 * `get_ground_y(x, y start, y dir, *not found y, *solid bits)` — scan the solid column up or down for
 * the boundary of solid ground; returns the pixel y of that boundary (or the default).
 */
export function get_ground_y(
  x: number,
  yStart: number,
  yDir: number,
  notFoundY?: number,
  solidBits?: number,
): number {
  const s = env.solid()
  const ROWS = s.h
  const clm = Math.max(0, Math.min(x >> 3, Math.max(0, s.w - 1)))
  let row = Math.max(0, Math.min(yStart >> 3, Math.max(0, ROWS - 1)))
  const DIR = sign_(yDir)
  const DEFAULT =
    notFoundY === undefined
      ? (viewYC() >> 3) << 3
      : Math.max(0, Math.min(notFoundY >> 3, Math.max(0, ROWS - 1))) << 3
  if (!ROWS) return DEFAULT
  const BITS = solidBits ? Math.max(TID_SOLID1, solidBits) : TID_SOLID1
  let inSolid = ((s.grid.get(clm, row) ?? 0) & 0xff) !== 0
  for (let i = 0; i < ROWS; i++) {
    row += DIR
    if (row < 0 || row >= ROWS) return DEFAULT // out of solid grid
    let v = (s.grid.get(clm, row) ?? 0) & 0xff
    v &= BITS
    if ((v && !inSolid) || (!v && inSolid)) {
      if ((DIR > 0 && !inSolid) || (DIR < 0 && inSolid)) {
        return (row + (DIR < 0 ? 1 : 0)) << 3
      }
      // search for other type. this should only happen once.
      inSolid = v !== 0
      i = 0
    }
  }
  return DEFAULT
}

/** `update_trig_hb_1()` — extend trigger hitboxes to the nearest solids around the object. */
export function update_trig_hb_1(self: GoBody): void {
  const SOLID = (TID_SOLID1 | TID_ONEWY1) & 0xf
  const CLM = round8(self.xl) >> 3
  const ROW = round8(self.yt) >> 3
  const CLM_MIN = cam_xl_min() >> 3
  const CLM_MAX = cam_xr_max() >> 3
  const ROW_MIN = cam_yt_min() >> 3
  const ROW_MAX = cam_yb_max() >> 3
  if ((self.move_dirs ?? 0) & 0x3) {
    self.trig_hori_x =
      (Math.max(
        find_clm_solid(SOLID, CLM - 1, ROW, -1, 0, CLM_MIN),
        find_clm_solid(SOLID, CLM - 1, ROW + 1, -1, 0, CLM_MIN),
      ) +
        1) <<
      3
    self.trig_hori_w =
      Math.min(
        find_clm_solid(SOLID, CLM + 2, ROW, 1, 0, CLM_MAX),
        find_clm_solid(SOLID, CLM + 2, ROW + 1, 1, 0, CLM_MAX),
      ) << 3
    self.trig_hori_w -= self.trig_hori_x ?? 0
    self.trig_hori_h = self.trig_hori_H ?? 0
    self.trig_hori_y = self.y - ((self.trig_hori_h ?? 0) >> 1)
  }
  if ((self.move_dirs ?? 0) & 0xc) {
    self.trig_vert_y =
      (Math.max(
        find_row_solid(SOLID, CLM, ROW - 1, -1, 0, ROW_MIN),
        find_row_solid(SOLID, CLM + 1, ROW - 1, -1, 0, ROW_MIN),
      ) +
        1) <<
      3
    self.trig_vert_h =
      Math.min(
        find_row_solid(SOLID, CLM, ROW + 2, 1, 0, ROW_MAX),
        find_row_solid(SOLID, CLM + 1, ROW + 2, 1, 0, ROW_MAX),
      ) << 3
    self.trig_vert_h -= self.trig_vert_y ?? 0
    self.trig_vert_w = self.trig_vert_W ?? 0
    self.trig_vert_x = self.x - ((self.trig_vert_w ?? 0) >> 1)
  }
}
