/**
 * Player skins: the spritesheet registry (`PC_init_add_spritesheet.gml`, `PC_add_skin.gml` (dead duplicate,
 * dropped)) and the user-skin folder scan from `PC_init.gml:122-157`, modelled as an injectable provider
 * (core does no file I/O; the adapter lists `custom_playercharacter_graphics` and registers sprites).
 */
import {
  STR_Count,
  STR_Creator,
  STR_Datakey,
  STR_Idx,
  STR_Name,
  STR_Palette,
  STR_Set,
  STR_Sprite,
} from '@z2/data'
import { hex_str, val } from '../../other/index'
import type { Lonk } from './Lonk'

export interface CustomSkin {
  /** `<CharName>_<CreatorName>.png` split on the first underscore */
  name: string
  creator: string
  /** Sprite key the adapter registered via `addSprite` (full-sheet image, 1 frame). */
  key: string
}

/** ZALiA capped user skins at 4 (each `sprite_add` created a texture page); atlases remove that need. */
export let customSkinProvider: () => CustomSkin[] = () => []
export function setCustomSkinProvider(fn: () => CustomSkin[]): void {
  customSkinProvider = fn
}

/** `PC_init_add_spritesheet(sprite asset, character name, creator, *palette, *source is file)` */
export function PC_init_add_spritesheet(
  self: Lonk,
  _SPRITE: string,
  _CHAR_NAME: string,
  _CREATOR: string,
  palette?: string | number,
  sourceIsFile?: boolean | number,
): void {
  const dm = self.dm_skins
  const _IDX = Number(val(dm.get(STR_Set + STR_Count)))
  dm.set(STR_Set + STR_Count, _IDX + 1)
  let _DATAKEY = `${_CHAR_NAME}-${_CREATOR}`
  if (val(dm.get(_DATAKEY + STR_Sprite)) !== 0) _DATAKEY += '01'
  dm.set(hex_str(_IDX) + STR_Name, _CHAR_NAME)
  dm.set(hex_str(_IDX) + STR_Creator, _CREATOR)
  dm.set(hex_str(_IDX) + STR_Datakey, _DATAKEY)
  dm.set(_DATAKEY + STR_Idx, _IDX)
  dm.set(_DATAKEY + STR_Sprite, _SPRITE)
  if (typeof palette === 'string') dm.set(hex_str(_IDX) + STR_Palette, palette)
  if (sourceIsFile !== undefined) dm.set(`${hex_str(_IDX)}_source_is_file`, Math.sign(Number(sourceIsFile)))
}

