/** Boon (ZALiA object `Boon01`, parent `Enemy`; the rock-dropping fly). `Boon_init2/update/udp/draw.gml`. */
import { CS_BD1, DEPTH_FLYER, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { viewYB, viewYT } from '../../../../../collision/env'
import { ocsHV2 } from '../../../../../collision/ocs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { get_ground_y } from '../../../../../collision/solid'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { byte_dir, sign_ } from '../../../../../math/index'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { GO_draw_sprite } from '../../../../go/draw'
import { dir_to_pc } from '../../../../go/misc'
import { set_xy, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_depth_init } from '../../../../go/sprite'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_udp_1, GOB_update_2 } from '../../../GameObjectB'
import { projOf, rand } from '../ache/_shared'

export class Boon01 extends Enemy {
  readonly objectName = 'Boon01' as const
  GROUND_Y = 0
  HSPD = 0x20
  VSPD = 0x20
}

/** `Boon_init2()` */
export function Boon_init2(self: Boon01): void {
  self.DRAW_YOFF = 0
  GO_init_palidx(self, G.PI_MOB_BLU)
  GO_depth_init(self, DEPTH_FLYER)
  self.dl_sprites?.add('spr_Boon1', 'spr_Boon2')
  self.projectile_OBJ = 'Rock3'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.GROUND_Y = g.rm_h - (0x03 << 3)
  self.GROUND_Y = get_ground_y(self.x, self.GROUND_Y, -1, self.GROUND_Y)
  self.HSPD = 0x20
  self.VSPD = 0x20
}

/** `Boon_update()` — 9989 */
export function Boon_update(self: Boon01): void {
  // 9989
  if ((self.yt & 0xff) < 0x80 && !(g.counter1 & 0x1f) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
    const proj = GOC1_create(self.xl, self.yt, self.facing_dir, projOf(self), self.projectile_ver)
    proj.hspd = 0
    proj.vspd = 0
  }
  self.facing_dir = byte_dir(self.hspd)
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return
  }
  // 99A7
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  self.facing_dir = dir_to_pc(self)
  // 99AD
  const _RESET_Y = viewYT() - self.hh_
  if (!gmBool(self.counter)) {
    // Reset, pick new start position
    set_xy(self, g.view_xl_og + rand(self) + 8, _RESET_Y)
    self.behavior = 0
    self.counter = 1
    self.timer = 0x20
  } else {
    // 99D2.  HV2: At least 8 w & any h w/in ocs area
    if (!ocsHV2(self)) self.counter = 0
    // 99DA.  Start moving or pick a movement dir
    if (!gmBool(self.timer)) {
      const _RAND = rand(self)
      self.timer = (_RAND & 0xf) | 0x8 // 8-15
      self.behavior = _RAND & 0x3
    }
    // 99EF
    if (self.yt >= self.GROUND_Y - 0x20 || self.yt >= viewYB() - 0x30 || self.yt <= _RESET_Y + 0x50) {
      // MOD. Move down to reset or torwards pc.
      if (gmBool(self.hp)) self.timer = 0
      self.vspd = self.VSPD
      updateY(self)
    } else {
      if (self.behavior & 0x2) {
        // behavior 2,3.  Horizontal movement
        self.hspd = (self.HSPD * sign_(self.behavior & 0x1)) & 0xff
        updateX(self)
      } else {
        // behavior 0,1.  Vertical movement
        self.vspd = (self.VSPD * -sign_(self.behavior & 0x1)) & 0xff
        updateY(self)
      }
    }
  }
}

/** `Boon_udp()` */
export function Boon_udp(self: Boon01): void {
  self.can_draw_self = true
  GOB_udp_1(self, 1)
}

/** `Boon_draw()` */
export function Boon_draw(self: Boon01): void {
  if (!self.can_draw_self) return
  GO_draw_sprite(self, self.sprite, self.palidx)
}

registerObject('Boon01', Boon01)
registerScripts({ Boon_init2, Boon_update, Boon_udp, Boon_draw })
