/**
 * GameObjectD leaf objects: the moving platforms. Fields come from `Platform_init_1.gml` and the per-object
 * `*_init_1/_init_2` scripts. (ZALiA has a `Current_init` script but no `Current` object — dropped.)
 */
import { DsGrid } from '../../../runtime/ds'
import { Platform } from '../classes'

export abstract class PlatformBase extends Platform {
  // ---- Platform_init_1 ----------------------------------------------------------------------------
  /** pc.x diff from id.x */
  pc_xoff = 0
  path_dir = 1
  location_a = 0
  location_b = 0
  hspd1 = 0
  vspd1 = 0
  x_prev = 0
  y_prev = 0
}

export class PlatformA extends PlatformBase {
  readonly objectName = 'PlatformA' as const
  Body_mid_segments = 1
  Gear_SPRITE = 'spr_Elevator_gear_1a_WRB'
  Gear_yscale = 1
  Gear_TIMING1 = 0x8
  HSPD = 0x10
  VSPD = 0x10
  /** columns: locations; rows: 0 unused, 1 x, 2 y */
  dg_path = new DsGrid<number>(1, 3, 0)
  DELAY1_DUR = 0x40
  DELAY2_DUR = 0x10
  radius = 0
  angle = 0
  /** Duration (in seconds) it takes to make a full revolution */
  REV_DUR = 6
  rev_dur = 6
  /** degree change per frame */
  SPEED1 = 1
  speed1 = 1
}

/** PlatformB: A cloud that can be stood on & ridden (ver 2 = raft tiles). */
export class PlatformB extends PlatformBase {
  readonly objectName = 'PlatformB' as const
  Raft_TS = 'ts_Man_made_1a_WRB'
  Raft_TS_X = 0
  Raft_TS_Y = 0
  Tile_COUNT = 0
}

export class PlatformCloud extends PlatformBase {
  readonly objectName = 'PlatformCloud' as const
  CLMS_MIN = 6
  CLMS_MAX = 6
  CLMS = 6
  BODY_XOFF = 4
  BODY_W = 0
  /** Composite sprite key built from tileset parts (ZALiA: sprite_create_from_surface). */
  Cloud_SPR1: string | 0 = 0
}

export class PlatformRaft extends PlatformBase {
  readonly objectName = 'PlatformRaft' as const
  dock_state_DOCKED0 = 0 // Docked and waiting for player to get on
  dock_state_DOCKED1 = 1 // Docked and waiting for player to get off
  dock_state_FREE0 = 2 // Moving freely, not expecting to dock.
  dock_state_FREE1 = 3 // Moving freely, expecting to dock
  dock_state = 2
  dock_xc = 0
  Raft_TS = 'ts_Man_made_1a_WRB'
  Raft_TSRC1 = 0xa0
  Raft_TS_X = 0
  Raft_TS_Y = 0
  Tile_COUNT = 0
  WaterUndulate_DUR1 = 0x30
  WaterUndulate_DUR2 = 0x14
  WaterUndulate_DUR3 = 0x0c
  WaterUndulate_dur = 0x30
  WaterUndulate_timer = 0
  WaterUndulate_yoff_MAX = 2 // -2,-1,0,1,2
  WaterUndulate_yoff = 2
  WaterUndulate_dir = -1
  DistantWater_DEPTH = 0
  DistantWater_xoff = 0
  DistantWater_undulate = false
}
