/**
 * Cross-subsystem fields the audio scripts read. Typed views over the live singletons; every field listed
 * here is expected to exist on the owner's class (PENDING-FIELD: `g.room` — the GM room name string).
 */
import type { DsGrid, DsList, DsMap } from '../../runtime/ds'
import { f, G, g, world } from '../../runtime/world'
import { Boss } from '../game_object/classes'

export interface GameAudioDeps {
  room_type: string
  /** GM `room` as a room *name* (`rmB_Title`, `rmA_Action_Wide`, …). PENDING-FIELD on Game. */
  room: string
  rm_name: string | undefined
  town_name: string | undefined
  town_num: number
  dungeon_num: number
  dm_rm: DsMap<unknown>
  dm_town: DsMap<unknown>
  coming_from: number
  coming_from_FILE: number
  coming_from_CONT: number
  ChangeRoom_timer: number
  game_end_state: number | boolean
  mod_LOW_HP_SOUND: number | boolean | undefined
}
export interface FileAudioDeps {
  quest_num: number
  hp: number
  dm_rando: DsMap<unknown>
}
export interface OverworldAudioDeps {
  dg_AreaNames: DsGrid<string>
  pcrc: number
}
export interface GlobalsAudioDeps {
  Halloween1_enabled: boolean
  OVERWORLD: OverworldAudioDeps | undefined
  pc: { Disguise_enabled: boolean } | null
  dl_Halloween_TOWN_MUSIC: DsList<string>
}
export interface BossAudioDeps {
  MusicBattle_THEME: string
  MusicBattle_BODY: string | 0
  MusicBattle_INTRO: string | 0
}

export const gd = () => g as unknown as GameAudioDeps
export const fd = () => f as unknown as FileAudioDeps
export const Gd = () => G as unknown as GlobalsAudioDeps

/** GML `Boss.MusicBattle_*` — the first live Boss instance (`instance_exists(Boss)`). */
export function firstBoss(): (Boss & BossAudioDeps) | undefined {
  for (const b of world.instancesOf(Boss)) return b as Boss & BossAudioDeps
  return undefined
}

/** Whether a sound asset is in the build — ZALiA's `asset_get_index(name) != -1` probing. */
let soundSet: Set<string> | undefined
export function setSoundManifest(names: Iterable<string>): void {
  soundSet = new Set(names)
}
export function hasSound(name: string): boolean {
  return soundSet ? soundSet.has(name) : true
}
