import { is_undefined, script_execute, withInstance } from './gm'

/** GML: update_Platforms() */
export function update_Platforms() {
  withInstance('Platform', (self) => {
    if (!is_undefined(self.scr_step)) {
      // GML `with(Platform) script_execute(scr_step)` runs the script in the platform's scope — the
      // instance must be passed. FIXED: without it every moving platform threw on its first frame.
      script_execute(self.scr_step, self)
    }
  })
}
