/** Singletons not ported yet: any access throws so nothing silently no-ops. */
const pendingSingleton = (name: string): any =>
  new Proxy(
    {},
    {
      get: (_t, prop) => {
        throw new Error(`${name}.${String(prop)}: singleton ${name} is not ported yet`)
      },
    },
  )
export const Audio: any = pendingSingleton('Audio')
export const Surface: any = pendingSingleton('Surface')
