// ---- instances ------------------------------------------------------------------------------------
type Ctor = new () => Instance

/** One registry for every ported object class (`other/registry.ts`); `instancesNamed`/`instance_create` read it. */
export { registerObjectClass } from '../other/registry'
/**
 * Installed by `wire.ts` (avoids a gm ↔ rooms import cycle). `existing(name)` lets room scripts that
 * `instance_create` a screen object the room already created (`g_Room_Start` → TitleScreen) reuse it instead
 * of making a duplicate; `onScreenCreated` adds new screen objects to the room's instance list.
 */
export const instanceCreateHooks = {
  existing: (_objectName: string): Instance | undefined => undefined,
  onScreenCreated: (_inst: Instance): void => {},
}
export function instance_create(x: number, y: number, objectName: string): Instance {
  const reuse = instanceCreateHooks.existing(objectName)
  if (reuse) return reuse
  if (!hasObjectClass(objectName))
    throw new Error(`instance_create: object ${objectName} is not ported/registered`)
  const ctor = objectClass(objectName) as unknown as Ctor
  const inst = world.register(new ctor())
  inst.x = x
  inst.y = y
  // Screen-type objects (step/draw methods) created by room scripts join the current room's instance list so
  // they receive Step/Draw/Room End like the ones the room creates itself.
  if (typeof (inst as { step?: unknown }).step === 'function') instanceCreateHooks.onScreenCreated(inst)
  return inst
}
export const instance_exists = (i: unknown) => instanceExists(i as Instance | null | undefined)
export function instance_destroy(i: Instance): void {
  i.destroy()
}
