/**
 * GML `with (target) { … }`. `target` may be an instance/singleton (called once), an object name (every
 * live instance of that registered class, creation order), or an iterable of instances.
 *
 * A GML `return` inside a `with` body returns from the *script*, so the callback's value is propagated:
 * the first callback that returns anything other than `undefined` stops the loop and that value is
 * handed back. A callback that falls off its end (the common case, and the translation of `exit`)
 * returns `undefined` and the loop continues.
 */
export function withInstance(target: any, fn: (self: any) => any): any {
  if (target === undefined || target === NOONE) return undefined
  // ZALiA initialises singleton references to 0 until the object is created (`g.PAUSE_MENU = 0`);
  // `with(0)` on such a placeholder must do nothing.
  if (typeof target === 'number') return undefined
  if (typeof target === 'string') {
    const ctor = hasObjectClass(target) ? (objectClass(target) as unknown as Ctor) : undefined
    if (!ctor) throw new Error(`with(${target}): object class not registered`)
    for (const i of world.instancesOf(ctor as unknown as abstract new () => Instance)) {
      const r = fn(i)
      if (r !== undefined) return r
    }
    return undefined
  }
  if (typeof target[Symbol.iterator] === 'function' && typeof target !== 'string') {
    for (const i of target as Iterable<unknown>) {
      const r = fn(i)
      if (r !== undefined) return r
    }
    return undefined
  }
  return fn(target)
}
/** Every live instance registered under a ZALiA object name (for `with(Obj)` loops that `break`). */
export function* instancesNamed(objectName: string): Generator<any> {
  const ctor = hasObjectClass(objectName) ? (objectClass(objectName) as unknown as Ctor) : undefined
  if (!ctor) throw new Error(`instancesNamed(${objectName}): object class not registered`)
  yield* world.instancesOf(ctor as unknown as abstract new () => Instance)
}
