/** GML: Carock_init2() */
export function Carock_init2(self: Carock01) {
  let _i: any, _a: any, _CLMS: any

  //ver=1: Normal, ver=2: PENDANT Carock

  Boss_init_2(self)
  if (self.ver === 2) {
    _CLMS = 0x04
    self.spawn_xl = ((self.arena_w >> 1) >> 3) - _CLMS - (self.ww_ >> 3)
    self.spawn_xl = _CLMS + world.irandom(self.spawn_xl)
    self.spawn_xl = self.spawn_xl << 3
    self.spawn_xl *= sign_(G.pc.x < self.arena_x)
    self.spawn_xl = self.arena_x + self.spawn_xl
    self.spawn_xl -= self.ww_
    set_xy(self, self.spawn_xl + self.sprite_index_xoff, self.spawn_yt + self.sprite_index_yoff)
    NPC_catch_item(self as never)
  }
  GO_init_palidx(self, G.PI_MOB_RED)
  // placement sprite: spr_Carock_1a(32x48)
  self.SPRITE_IDLE = 'spr_Carock_1a'
  self.SPRITE_ATTACK = 'spr_Carock_1b'
  self.SPRITE_FORWARD = 'spr_Carock_2a_1_v2_WRB'
  //SPRITE_FORWARD = spr_Carock_2a_WRB;
  // GROUND_Y set in Boss_init_2().
  self.GROUND_Y = (((viewYC() >> 8) + 1) << 8) - (0x03 << 3)
  self.GROUND_Y = get_ground_y(self.arena_xl + 0x08, self.GROUND_Y, -1, self.GROUND_Y)
  self.spawn_yt = self.GROUND_Y - self.hh
  set_xy(self, self.x, self.spawn_yt + self.sprite_index_yoff)
  Boss_init_2b(self, -1) // Determine & set the side of the arena to start on.
  self.projectile_OBJ = 'SoundWave'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.Attack2_PROJECTILE = 'Flame1'
  self.Attack2_DURATION1 = 0xff // cooldown duration
  self.Attack2_SPACING = 0x04 << 3
  self.Attack2_xl = self.arena_xl
  self.Attack2_YT = (g.rm_rows - PAGE_ROWS + 0x08) << 3
  if (self.ver === 2) {
    self.Attack2_YT = ((viewYT() >> 3) + 0x03) << 3
  }
  self.Attack2_TIMING = 0x01 << 3
  self.Attack2_CUE0 = 0xd0
  self.Attack2_CUE1 = self.Attack2_CUE0 - 0x38 // $D0 - $38 = $98
  self.Attack2_CUE2 =
    self.Attack2_CUE1 - Math.trunc(self.arena_w / self.Attack2_SPACING) * self.Attack2_TIMING // $98 - (($1C0 div $20) * 8) = $98 - $70 = $28
  self.Attack2_CUE3 = self.Attack2_CUE2 - 0x18 // $28 - $18 = $10
  self.Attack2_CUE4 = 0x00
  self.Attack2_CUE5 = min(self.Attack2_CUE1 + 0x18, self.Attack2_CUE0) // Attack2_CUE1+$18 = $B0
  self.Attack2_dir = sign_(world.irandom(1)) // 1,-1.  Spawn from left-to-right or vice-versa
  Carock_set_Attack2x(self)
  self.FlameSmall_SPRITE = 'spr_Flame_Small_1a'
  self.FlameSmall_SPRITE_Y = self.GROUND_Y - (sprite_get_height(self.FlameSmall_SPRITE) >> 1)
  self.Attack3_PROJECTILE = 'Flame1'
  self.Attack3_Y = self.GROUND_Y - 8
  self.Attack3_DURATION0 = 0x0100
  self.Attack3_DURATION1 = 0xa0
  self.Attack3_DURATION2 = 0x18
  self.Attack3_CUE0 = 0x10
  self.Attack3_CUE1 = self.Attack3_DURATION0 - 0x20
  self.Attack3_CUE2 = self.Attack3_CUE0 + self.Attack3_DURATION2
  self.Attack3_CUE3 = self.Attack3_CUE1 - self.Attack3_DURATION2
  self.Attack3_CUE4 = self.Attack3_DURATION0 - 0x10
  self.dg_Attack3 = ds_grid_create(0, 3)
  _a = 0
  for (_i = 0; _i < 7; _i++) {
    ds_grid_resize(self.dg_Attack3, ds_grid_width(self.dg_Attack3) + 2, ds_grid_height(self.dg_Attack3))
    _a += 5
    self.dg_Attack3.set((_i << 1) + 0, 0, self.arena_xl + (_a++ << 3) + 4)
    self.dg_Attack3.set((_i << 1) + 1, 0, self.arena_xl + (_a++ << 3) + 4)
  }
  self.DURATION1 = 0x10
  self.DURATION2 = 0x20
  self.DURATION3 = 0xd0
  self.DURATION4 = 0x20
  self.DURATION5 = self.DURATION4 + self.DURATION4
  // DURATION6: Increases the time Carock is vulnerable
  // to compensate for the larger arena which makes it
  // less likely to collide with the projectile.
  self.DURATION6 = 0x05 // 2024/07/14
  //DURATION6 = $03;
  //DURATION6 = floor(DURATION1*($100/arena_w)); // Result is $0A
  //sdm("DURATION6 "+string(DURATION6)+", arena_w "+string(arena_w));
  // Minimum attack1 duration. For ver-2(PENDANT Carock).
  self.DURATION7 = 0x013f // 2025/03/22
  //DURATION7 = $FF;
  // Added to attack1 duration but as a random number from 0-DURATION8
  self.DURATION8 = 0xff
  self.attack_timer = self.DURATION7 + world.irandom(self.DURATION8) // For Attack2, Attack3
  _a = 1
  self.sub_state_ATTACK_1A = _a++ // Fade in
  self.sub_state_ATTACK_1B = _a++ // Shoot SoundWave
  self.sub_state_ATTACK_1C = _a++ // Fade out
  self.sub_state_ATTACK_1D = _a++ // Find/set new x
  //                              //
  self.sub_state_ATTACK_2A = _a++ // Atk 2
  self.sub_state_ATTACK_2B = _a++ // Delay next atk after atk 2
  //                              //
  self.sub_state_ATTACK_3A = _a++ // Atk 3
  self.sub_state_ATTACK_3B = _a++ // Delay next atk after atk 3
  self.sub_state = self.sub_state_ATTACK_1A
  self.sub_state_timer = self.DURATION1
  //                              //
  self.BodyHB_color = c_yellow
  if (f.quest_num > 1) {
    self.XP_IDX += 0x02
    self.xp = g.dl_XP.get(self.XP_IDX) as number
  }
  Boss_set_MusicBattle_props(self, `${STR_Boss}01`)
}

/** GML: Carock_update() */
export function Carock_update(self: Carock01) {
  let _i: any, _DIST: any, _XL: any, _YT: any, _dur: any, _count: any, _IDX: any, _dl_RAND: any

  // AE7B: JSR B20D
  // check battle start/end/qualify
  if (!gmBool(Boss_update_1(self))) {
    update_EF11(self)
    self.can_draw_self = self.pending_death
    if (self.ver === 2 && gmBool(self.pending_death)) {
      Carock_update_2(self)
    }
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // Update healthbar ------------------------------------------------------
  Boss_HPBar_udp(self)
  // Arena gate
  if (!gmBool(Boss_update_4(self))) {
    //update_EF11();
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // MOD. Delay 1st attack -----------------------------------------------
  if (gmBool(self.start_timer)) {
    self.start_timer--
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // AE7E: JSR B1E9 --------------------------------------------------------
  Boss_update_5(self) // check for and set pending death
  self.behavior = 0 // for SoundWave
  self.facing_dir = dir_to_pc(self)
  //if(!pending_death) Boss_Roar_update();
  if (self.ver === 2 && gmBool(g.mod_CAROCK_ATK_3)) {
    if (self.sub_state !== self.sub_state_ATTACK_3A || self.sub_state_timer <= self.Attack3_CUE4) {
      for (_i = ds_grid_width(self.dg_Attack3) - 1; _i >= 0; _i--) {
        if (!gmBool(self.dg_Attack3.get(_i, 1))) {
          continue
        }
        self.dg_Attack3.set(_i, 1, self.dg_Attack3.get(_i, 1) - 1) /* GML2TS-TODO: map-- used as a value */
        if (gmBool(self.dg_Attack3.get(_i, 1))) {
          continue
        }
        /* TODO with */ {
          const _w1: any = GOC1_create(
            self.dg_Attack3.get(_i, 0) - 4,
            self.Attack3_Y - 8,
            self.facing_dir,
            self.Attack3_PROJECTILE,
            -1,
            self,
          )
          if (_w1) {
            _w1.hspd = 0
            _w1.vspd = 0
          }
        }
      }
    }
  }
  if (gmBool(self.attack_timer)) {
    self.attack_timer--
  }
  // AE8D ------------------------------------------------------------------
  if (gmBool(self.sub_state_timer)) {
    self.sub_state_timer--
  }
  switch (self.sub_state) {
    // -----------------------------------------------------------------------
    // -----------------------------------------------------------------------
    case self.sub_state_ATTACK_1A: {
      // FADE IN
      if (gmBool(self.sub_state_timer)) {
        if (gmBool(self.sub_state_timer & 0x01)) {
          update_EF11(self)
        }
        break
      }
      // This will be Carock's vulnerability duration
      self.sub_state_timer = self.DURATION1 // DURATION1=$10
      if (gmBool(g.mod_Carock_VulnDur)) {
        self.sub_state_timer += self.DURATION6 // Extra vulnerability time to compensate wider arena
      }
      self.sub_state = self.sub_state_ATTACK_1B
      break
    }
    // -----------------------------------------------------------------------
    // -----------------------------------------------------------------------
    case self.sub_state_ATTACK_1B: {
      // ATK 1
      if (gmBool(self.sub_state_timer)) {
        // AE98
        if (self.sub_state_timer === 0x08 && !gmBool(self.ocs) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
          // AED9: JSR DBCE.  Carock spr is 32x48. SoundWave spr is 8x16
          if (false) {
            if (
              self.ver === 2 &&
              self.hp < Math.trunc(g.dl_HP.get(self.HP_IDX) / 3) &&
              !gmBool(world.irandom(0x17))
            ) {
              self.projectile = 'Fireball1'
              self.projectile_ver = 1
            } else {
              self.projectile = self.projectile_OBJ
              self.projectile_ver = self.projectile_VER
            }
          } else {
            self.projectile = self.projectile_OBJ
            self.projectile_ver = self.projectile_VER
          }
          _DIST = 0x0d + +gmBool(self.facing_dir)
          _XL = self.x + _DIST * self.facing_dir // SoundWave x
          _XL -= 0x04 // SoundWave xl
          //
          if (!gmBool(world.irandom(1)) && abs(self.x - G.pc.x) > 0x0a << 3) {
            _YT = self.yb - 0x20
          } else {
            _YT = self.yb - 0x10
          }
          /* TODO with */ {
            const _w2: any = GOC1_create(
              _XL,
              _YT,
              self.facing_dir,
              self.projectile as ObjectName,
              self.projectile_ver,
              self,
            )
            if (_w2) {
              if (_w2.objectName === 'SoundWave') {
                _w2.counter = 3 + +!gmBool(_w2.facing_dir)
              }
            }
          }
        }
        // AEB2
        self.behavior = 1 // for SoundWave
        GOB_body_collide_pc_body_1a(self)
        self.BodyHB_can_draw = true
        if (gmBool(self.cs & CS_BD1)) {
          enemy_collide_pc_body(self)
        }
        update_EF11(self)
        break
      }
      self.sub_state_timer = self.DURATION1 // DURATION1=$10
      self.sub_state = self.sub_state_ATTACK_1C
      break
    }
    // -----------------------------------------------------------------------
    // -----------------------------------------------------------------------
    case self.sub_state_ATTACK_1C: {
      // FADE OUT
      if (gmBool(self.sub_state_timer)) {
        if (gmBool(self.sub_state_timer & 0x01)) {
          update_EF11(self)
        }
        break
      }
      self.sub_state_timer = 0
      self.sub_state = self.sub_state_ATTACK_1D
      break
    }
    // -----------------------------------------------------------------------
    // -----------------------------------------------------------------------
    case self.sub_state_ATTACK_1D: {
      // FIND/SET NEW X
      if (gmBool(self.sub_state_timer)) {
        break
      }
      if (
        self.ver === 2 &&
        (gmBool(g.mod_CAROCK_ATK_2) || gmBool(g.mod_CAROCK_ATK_3)) &&
        !gmBool(self.attack_timer) &&
        self.hp < g.dl_HP.get(self.HP_IDX) >> 1
      ) {
        if (gmBool(g.mod_CAROCK_ATK_3) && gmBool(world.irandom(1))) {
          _count = ds_grid_width(self.dg_Attack3)
          _IDX = world.irandom((_count >> 1) - 1) << 1
          _dl_RAND = ds_list_create()
          for (_i = 0; _i < _count; _i++) {
            self.dg_Attack3.set(_i, 1, 0) // timer
            self.dg_Attack3.set(_i, 2, 0) // timer
            if (_i < _IDX || _i > _IDX + 1) {
              // clms that will NOT spawn flames
              ds_list_add(_dl_RAND, _i)
            }
          }
          ds_list_shuffle(_dl_RAND)
          _count = ds_list_size(_dl_RAND)
          _dur = 0
          for (_i = 0; _i < _count; _i++) {
            self.dg_Attack3.set(_dl_RAND.get(_i), 1, self.Attack3_DURATION1 + _dur) // Delay draw duration
            _dur += world.irandom(8) + 4
          }
          ds_list_destroy(_dl_RAND)
          _dl_RAND = undefined
          self.sub_state_timer = self.Attack3_DURATION0 //  Attack3_DURATION0: $100
          self.sub_state = self.sub_state_ATTACK_3A
          break
        } else {
          // ATK 2
          self.sub_state_timer = self.DURATION3 //  DURATION3: $D0
          self.sub_state = self.sub_state_ATTACK_2A
          break
        }
      }
      // AEBD
      Carock_update_1(self) // Find and set new x
      self.stun_timer = 0
      self.sub_state_timer = self.DURATION1 // DURATION1=$10
      self.sub_state = self.sub_state_ATTACK_1A
      break
    }
    // -----------------------------------------------------------------------
    // -----------------------------------------------------------------------
    case self.sub_state_ATTACK_2A: {
      // ATK 2
      if (gmBool(self.sub_state_timer)) {
        set_xy(self, self.arena_x, self.Attack2_YT + self.hh_)
        self.stun_timer = 0
        // Attack2_CUE3 $10, Attack2_CUE5 $B0
        if (inRange(self.sub_state_timer, self.Attack2_CUE3, self.Attack2_CUE5)) {
          // Attack2_CUE2 $28, Attack2_CUE1 $98
          // Fade in/out effect
          if (
            inRange(self.sub_state_timer, self.Attack2_CUE2, self.Attack2_CUE1) ||
            gmBool(self.sub_state_timer & 0x01)
          ) {
            update_EF11(self)
          }
        }
        // Attack2_CUE1 $98
        if (
          self.sub_state_timer <= self.Attack2_CUE1 &&
          !gmBool(self.sub_state_timer & (self.Attack2_TIMING - 1))
        ) {
          if (
            gmBool(wINwAll(self.Attack2_xl, 8, self.arena_xl, self.arena_w)) &&
            avail_uidx_goc(MAX_GOC1) !== UIDX_NULL
          ) {
            /* TODO with */ {
              const _w3: any = GOC1_create(
                self.Attack2_xl,
                self.Attack2_YT,
                self.facing_dir,
                self.Attack2_PROJECTILE,
                -1,
                self,
              )
              if (_w3) {
                _w3.hspd = 0
                _w3.vspd = 0
                _w3.float_tmr = 0x20
                _w3.timer -= _w3.float_tmr
              }
            }
          }
          self.Attack2_xl += self.Attack2_SPACING * -self.Attack2_dir
        }
        break
      }
      self.Attack2_dir = sign_(world.irandom(1)) // 1,-1
      Carock_set_Attack2x(self)
      set_xy(self, self.x, self.spawn_yt + self.sprite_index_yoff) // set to atk1 yt
      self.sub_state_timer = self.DURATION2
      self.sub_state = self.sub_state_ATTACK_2B
      break
    }
    // -----------------------------------------------------------------------
    // -----------------------------------------------------------------------
    case self.sub_state_ATTACK_2B: {
      // POST ATK2 DELAY ATK1
      if (gmBool(self.sub_state_timer)) {
        break
      }
      Carock_update_1(self) // Find and set new x
      self.attack_timer = self.DURATION7 + world.irandom(self.DURATION8) // For Attack2, Attack3
      self.sub_state_timer = self.DURATION1 // DURATION1=$10
      self.sub_state = self.sub_state_ATTACK_1A
      break
    }
    // -----------------------------------------------------------------------
    // -----------------------------------------------------------------------
    case self.sub_state_ATTACK_3A: {
      // ATK 3
      if (gmBool(self.sub_state_timer)) {
        set_xy(self, self.arena_x, self.Attack2_YT + self.hh_)
        self.stun_timer = 0
        // Attack3_CUE0 $10, Attack3_CUE1 $E0
        if (inRange(self.sub_state_timer, self.Attack3_CUE0, self.Attack3_CUE1)) {
          // Attack3_CUE2 $28, Attack3_CUE3 $C8
          // Fade in/out effect
          if (
            inRange(self.sub_state_timer, self.Attack3_CUE2, self.Attack3_CUE3) ||
            gmBool(self.sub_state_timer & 0x01)
          ) {
            update_EF11(self)
          }
        }
        break
      }
      set_xlyt(self, self.xl, self.spawn_yt) // set to atk1 yt
      self.sub_state_timer = self.Attack3_DURATION1
      self.sub_state = self.sub_state_ATTACK_3B
      break
    }
    // -----------------------------------------------------------------------
    // -----------------------------------------------------------------------
    case self.sub_state_ATTACK_3B: {
      // POST ATK3 DELAY NEXT ATK
      if (gmBool(self.sub_state_timer)) {
        break
      }
      Carock_update_1(self) // Find and set new x
      self.attack_timer = self.DURATION7 + world.irandom(self.DURATION8) // For Attack2, Attack3
      self.sub_state_timer = self.DURATION1 // DURATION1=$10
      self.sub_state = self.sub_state_ATTACK_1A
      break
    }
  }
}

/** GML: Carock_update_1() */
export function Carock_update_1(self: Carock01) {
  let _x: any, _DIST: any

  // Find and set new x for Attack1
  // AEBD
  _x = self.arena_xl + self.ww_ + world.irandom(self.arena_w - self.ww)
  _DIST = self.ww_ + G.pc.ww_
  _DIST += 0x14 // pad
  // if too close to PC
  if (_DIST >= abs(_x - G.pc.x)) {
    // if PC too close to arena edge
    if (abs(G.pc.x - self.arena_x) > (self.arena_w >> 1) - _DIST) {
      _x = G.pc.x + _DIST * sign_(G.pc.x < self.arena_x)
    } else {
      _x = G.pc.x + _DIST * sign_(world.irandom(1))
    }
  }
  set_xy(self, _x, self.y)
}

/** GML: Carock_update_2() */
export function Carock_update_2(self: Carock01) {
  let _LOW: any

  // $3F.  EXPLODE_DELAY1=$7F, DURATION5=DURATION4($20)+DURATION4($20)
  if (self.stun_timer < self.EXPLODE_DELAY1 - self.DURATION5) {
    set_xy(self, self.arena_x, self.Attack2_YT + self.hh_ + (0x03 << 3))
  }
  _LOW = self.EXPLODE_DELAY1 - self.DURATION4 - (self.DURATION4 << 1) // DURATION4=$20
  if (gmBool(self.stun_timer & 0x01)) {
    // DURATION4=$20
    if (self.stun_timer >= _LOW && self.stun_timer <= _LOW + (self.DURATION4 << 1)) {
      self.can_draw_self = false
    }
  }
}

/** GML: Carock_set_Attack2x() */
export function Carock_set_Attack2x(self: Carock01) {
  self.Attack2_xl = self.arena_xl + (self.arena_w - 8) * +gmBool(self.Attack2_dir)
  self.Attack2_xl += (world.irandom((self.Attack2_SPACING >> 3) - 1) << 3) * -self.Attack2_dir
}

/** GML: Carock_udp() */
export function Carock_udp(self: Carock01) {
  self.can_draw_self = true
  // sub_state_ATTACK_1A: Fade in
  if (self.sub_state === self.sub_state_ATTACK_1A) {
    GO_set_sprite(self, self.SPRITE_IDLE)
  } else {
    GO_set_sprite(self, self.SPRITE_ATTACK)
  }
  if (gmBool(g.mod_CAROCK_ATK_2) && self.sub_state === self.sub_state_ATTACK_2A) {
    // Attack2_CUE1($98) + $18 = $B0
    if (self.sub_state_timer < self.Attack2_CUE1 + 0x18) {
      // PRE FLAME SPAWNING
      self.xScale = self.Attack2_dir
      GO_set_sprite(self, self.SPRITE_IDLE)
    }
    // ------------------------------------------
    // Attack2_CUE1=$98
    if (self.sub_state_timer <= self.Attack2_CUE1) {
      // SPAWNING FLAMES
      self.xScale = self.Attack2_dir
      GO_set_sprite(self, self.SPRITE_ATTACK)
    }
    // $98 - ($70 div 3) = $98 - $25 = $73
    if (self.sub_state_timer < self.Attack2_CUE1 - Math.trunc((self.Attack2_CUE1 - self.Attack2_CUE2) / 3)) {
      // SPAWNING FLAMES
      self.xScale = 1
      GO_set_sprite(self, self.SPRITE_FORWARD)
    }
    // $28 + ($70 div 3) = $28 + $25 = $4D
    if (self.sub_state_timer < self.Attack2_CUE2 + Math.trunc((self.Attack2_CUE1 - self.Attack2_CUE2) / 3)) {
      // SPAWNING FLAMES
      self.xScale = -self.Attack2_dir
      GO_set_sprite(self, self.SPRITE_ATTACK)
    }
    // ------------------------------------------
    // Attack2_CUE2=$28
    if (self.sub_state_timer < self.Attack2_CUE2) {
      // POST FLAME SPAWNING
      self.xScale = -self.Attack2_dir
      GO_set_sprite(self, self.SPRITE_IDLE)
    }
  }
  if (gmBool(g.mod_CAROCK_ATK_3) && self.sub_state === self.sub_state_ATTACK_3A) {
    self.xScale = 1
    GO_set_sprite(self, self.SPRITE_FORWARD)
  }
  if (self.ver === 2) {
    if (
      self.state === self.state_EXPLODE ||
      (gmBool(self.pending_death) && self.stun_timer < self.EXPLODE_DELAY1 - self.DURATION5)
    ) {
      self.xScale = 1
      GO_set_sprite(self, self.SPRITE_FORWARD)
    }
  }
}

/** GML: Carock_draw() */
export function Carock_draw(self: Carock01) {
  let _i: any

  if (gmBool(self.can_draw_self)) {
    GO_draw_sprite(self, self.sprite, self.palidx)
  }
  if (self.ver === 2 && gmBool(g.mod_CAROCK_ATK_3)) {
    if (self.sub_state !== self.sub_state_ATTACK_3A || self.sub_state_timer <= self.Attack3_CUE4) {
      for (_i = ds_grid_width(self.dg_Attack3) - 1; _i >= 0; _i--) {
        if (!gmBool(self.dg_Attack3.get(_i, 1))) {
          continue
        }
        if (self.dg_Attack3.get(_i, 1) <= 0x20 || gmBool(self.dg_Attack3.get(_i, 1) & 0x01)) {
          draw_sprite_(
            self.FlameSmall_SPRITE,
            0,
            self.dg_Attack3.get(_i, 0),
            self.FlameSmall_SPRITE_Y,
            G.PI_MOB_ORG,
            sign_(self.dg_Attack3.get(_i, 1) & 0x04),
          )
        }
      }
    }
  }
}

