/** Types for the generated asset manifests in `packages/data/generated/*.json` (built by `pnpm tool assets`). */
export interface SpriteEntry {
  name: string
  /** Atlas page key, e.g. `enemy-0` → `assets/atlas/enemy-0.{json,png}`. */
  atlas: string
  frames: number
  width: number
  height: number
  originX: number
  originY: number
  bbox: { left: number; right: number; top: number; bottom: number }
  folder: string
}
export interface TilesetEntry {
  /** false for the two plain backgrounds (ts_Menu01, background_0) that still need size metadata. */
  isTileset: boolean
  name: string
  tileWidth: number
  tileHeight: number
  xoff: number
  yoff: number
  hsep: number
  vsep: number
  width: number
  height: number
  folder: string
}
export interface MapEntry {
  area: string
  file: string
  width: number
  height: number
  tileWidth: number
  tileHeight: number
  layerNames: string[]
  tilesets: { firstgid: number; name: string }[]
}
export interface SoundEntry {
  name: string
  file: string
  group: 'mus' | 'snd'
  volume: number
  /** Audio set = IDE sound folder ('' for the root set). */
  set: string
}

export interface Manifests {
  sprites: SpriteEntry[]
  tilesets: TilesetEntry[]
  maps: MapEntry[]
  sounds: SoundEntry[]
}

/** URL layout under the web app's public dir (`apps/web/public/assets`, gitignored; `assets/data` is served by Vite from the caches). */
export const ASSET_URL = {
  manifest: (name: keyof Manifests) => `assets/manifests/${name}.json`,
  atlasJson: (page: string) => `assets/atlas/${page}.json`,
  atlasPng: (page: string) => `assets/atlas/${page}.png`,
  tileset: (name: string) => `assets/tilesets/${name}.png`,
  map: (area: string, file: string) => `assets/maps/${area}/${file}`,
  audio: (file: string) => `assets/audio/${file}`,
  cache: (name: string) => `assets/data/${name}.json`,
} as const

/** Distinct atlas pages referenced by the sprite manifest, in first-seen order. */
export function atlasPages(sprites: readonly SpriteEntry[]): string[] {
  const seen = new Set<string>()
  for (const s of sprites) seen.add(s.atlas)
  return [...seen]
}

/** Atlas frame key convention used by the packer: `<sprite>/<frameIndex>`. */
export function frameKey(sprite: string, frame: number): string {
  return `${sprite}/${frame}`
}

export function spriteIndex(sprites: readonly SpriteEntry[]): Map<string, SpriteEntry> {
  return new Map(sprites.map((s) => [s.name, s]))
}

/** `PalcA_003.json` → `PalcA_003` (the key `world.maps` uses). */
export function mapStem(file: string): string {
  return file.replace(/\.json$/, '')
}
