/** Lowder (`LowdA`) — the crawler. Ported from `Lowder_init2/update/udp.gml` (ZALiA's modded edge logic). */
import { CS_BD1 } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { byte_negate } from '../../../../../math/index'
import { cam_xl_min, cam_xr_max } from '../../../../../view/camera'
import { Enemy } from '../../../../classes'
import { dir_to_pc, is_facing_pc } from '../../../../go/misc'
import { updateX, updateY2 } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { solid_clip_correction } from '../../../../goa/movement'
import { pc } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_udp_1, GOB_update_2 } from '../../../GameObjectB'

export class LowdA extends Enemy {
  readonly objectName = 'LowdA' as const
}

/** `Lowder_init2()` */
export function Lowder_init2(self: LowdA): void {
  self.dl_sprites?.add('spr_Lowder2')
  self.dl_sprites?.add('spr_Lowder1')
  GO_init_palidx(self, G.PI_MOB_BLU)
  self.uses_vspd_sub = false
  self.csBtm1_xoff = 4
  self.csBtm2_xoff = 12
}

/** `Lowder_update()` */
export function Lowder_update(self: LowdA): void {
  const P = pc()
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // 98C3, 98C6
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  const _cs_COPY = self.cs
  GO_update_cs(self)
  GOB_update_2(self)
  // 98CC
  const _HSPD = self.hspd
  self.hspd = (self.hspd << (is_facing_pc(self) ? 1 : 0)) & 0xff
  updateX(self)
  self.hspd = _HSPD
  // MODDED. See update_Lowder_OG for unmodded. 98E6
  const _C1a = P.yt + 0x10 >= self.yt // qualify aggro
  const _C1b = P.yt - 0x08 >= self.yt && self.ver === 2 // qualify walk off edge
  const _C2a = _cs_COPY & 0x4 && !(self.cs & 0x4) // is at edge of ground
  const _C2b = !(_cs_COPY & 0x4) && !(self.cs & 0x4) // is falling
  const _C3a = self.xl < cam_xl_min() || self.xr > cam_xr_max() // is past edge of room
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  } else if (_C2b || (_C2a && _C1b)) {
    // is falling OR (at ground edge && qual walk off edge)
    updateY2(self, 0x20, 3)
  }
  // Turn around
  if (self.cs & 0x3 || (_C2a && !_C1b) || _C3a) {
    // 9921
    self.facing_dir = -self.facing_dir
    self.hspd = byte_negate(self.hspd)
    // update x twice
    updateX(self)
    updateX(self)
  } else {
    // Aggro
    if (_C1a && !self.timer && self.cs & 0x4) {
      // 98F4
      self.facing_dir = dir_to_pc(self)
      self.hspd = (8 * self.facing_dir) & 0xff
      self.timer = 0xa0 // $A0 = 160 = 2.667s
    }
  }
}

/** `Lowder_udp()` */
export function Lowder_udp(self: LowdA): void {
  self.can_draw_self = true
  GOB_udp_1(self, 8)
}

export function registerLowder(): void {
  registerObject('LowdA', LowdA)
  registerScripts({ Lowder_init2, Lowder_update, Lowder_udp })
}
registerLowder()
