/** `StfnA` — ZALiA `enemy/stalfoon`: hovering Stalfoon (Rebonack-like hover / Ra wave), fires Bullet1 pairs. */
import { CS_BD1, DEPTH_FLYER, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { abs8b, byte, gmBool, sign8b } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { ocsH1, ocsH3 } from '../../../../../collision/ocs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { byte_dir } from '../../../../../math/index'
import { registerObjectClass } from '../../../../../other/registry'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { draw_sprite_ } from '../../../../../rooms/draw'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { GO_draw_sprite } from '../../../../go/draw'
import { dir_to_pc, is_facing_pc_ } from '../../../../go/misc'
import { set_xlyt, updateX, updateY } from '../../../../go/movement'
import { GO_depth_init } from '../../../../go/sprite'
import { pc } from '../../../../goa/pc'
import type { ObjectName } from '../../../../objectNames'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_1, GOB_update_2 } from '../../../GameObjectB'
import { sign } from '../../shared'

export class StfnA extends Enemy {
  readonly objectName = 'StfnA' as const
  BG_YOFF = 2
  sprBG: string = 'spr_Stalfoon_BG_1a'
  HSPD_TO_HOME = 6
  HSPD_MAX_TWRD = 0
  HSPD_MAX_AWAY = 0
  HSPD_PACE = 8
  DUR_PACE = 0x50
  hover_type = 1 // 0: none, 1: Rebonack hover, 2: Ra wave
  VSPD_MAX = 0x14
  vspd_add_dir = 1 // 1 or -1
  DIST_ATK = 0x60
  is_aggro: number | boolean = 0
  SPAWN_HP = 0
}
registerObject('StfnA', StfnA)
registerObjectClass('StfnA', StfnA)

/** `Stalfoon_init2()` */
export function Stalfoon_init2(self: StfnA): void {
  GO_depth_init(self, DEPTH_FLYER)
  self.BG_YOFF = 2
  self.sprBG = 'spr_Stalfoon_BG_1a'
  self.projectile_OBJ = 'Bullet1'
  self.projectile_VER = 2
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  // if hspd was inc or maintained for the frame
  self.hspd_impel = 0
  self.HSPD_TO_HOME = 6
  self.HSPD_MAX_TWRD = pc().hspd_max - 2
  self.HSPD_MAX_AWAY = self.HSPD_MAX_TWRD - 2
  self.HSPD_PACE = 8
  self.DUR_PACE = 0x50
  // 0: none, 1: Rebonack hover, 2: Ra wave
  self.hover_type = 1
  self.vspd = 0
  self.VSPD_MAX = 0x14 // vertical center of wave
  self.vspd_add_dir = 1
  if (self.hover_type === 2) set_xlyt(self, self.xl, self.yt - 8)
  // Dist from PC that enemy will return to
  self.DIST_ATK = 0x60
  self.is_aggro = 0
  self.SPAWN_HP = self.hp
}

/** `Stalfoon_udp()` */
export function Stalfoon_udp(self: StfnA): void {
  self.can_draw_self = true
}

/** `Stalfoon_draw()` */
export function Stalfoon_draw(self: StfnA): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  draw_sprite_(self.sprBG, 0, self.drawX, self.drawY + self.BG_YOFF, -1, self.xScale)
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

/** `Stalfoon_update()` */
export function Stalfoon_update(self: StfnA): void {
  const P = pc()
  self.hspd_impel = 0
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  GO_update_cs(self)
  GOB_update_2(self) // DE40
  self.facing_dir = dir_to_pc(self)
  if (gmBool(self.hspd_pushback)) self.hspd_impel = byte_dir(self.hspd_pushback)
  GOB_update_1(self, true) // update hspdPB
  GO_update_cs(self)
  updateX(self)
  switch (self.hover_type) {
    case 1: {
      // Rebonack-like hover
      let _TIMING = 7
      if (self.hp <= self.SPAWN_HP >> 1) _TIMING = 3
      if (!(g.counter1 & _TIMING)) {
        const _Y_OFF = 1
        if (g.counter1 & 0x20) set_xlyt(self, self.xl, self.yt - _Y_OFF)
        else set_xlyt(self, self.xl, self.yt + _Y_OFF)
      }
      break
    }
    case 2: {
      // Ra wave
      self.vspd = byte(self.vspd + self.vspd_add_dir)
      if (abs8b(self.vspd) === self.VSPD_MAX) self.vspd_add_dir *= -1
      updateY(self)
      break
    }
  }
  const _home_dir = sign(self.x - P.x)
  let _c1: boolean | number = ocsH3(self) // all w on screen
  let _c2: boolean | number = ocsH1(self) && gmBool(self.is_aggro) // any w on screen & aggro last frame
  // Much of this is similar to IronKnuckle behavior
  if ((_c1 || _c2) && Math.abs(self.spawn_yt - P.yt) <= 41) {
    self.is_aggro = true
    const _dist = Math.abs(self.x - P.x)
    _c1 = _dist < 0x50 && P.hspd_dir !== self.facing_dir // back away from pc
    _c2 = _dist >= 0x58 && P.hspd_dir === self.facing_dir // move toward pc
    if (is_facing_pc_(self)) {
      _c2 = _c2 && (gmBool(Math.abs(P.hspd_impel)) || _dist >= self.DIST_ATK)
      if ((_c1 || _c2) && gmBool(P.hspd)) {
        _c1 = _c1 && abs8b(self.hspd) < self.HSPD_MAX_AWAY
        _c2 = _c2 && abs8b(self.hspd) < self.HSPD_MAX_TWRD
        if ((_c1 || _c2) && abs8b(self.hspd) < abs8b(P.hspd)) {
          self.hspd = byte(self.hspd + P.hspd_dir)
          self.hspd_impel = P.hspd_dir
        }
      }
      if (
        _dist < self.DIST_ATK &&
        (!gmBool(self.hspd) || sign8b(self.hspd) === _home_dir) &&
        abs8b(self.hspd) <= self.HSPD_TO_HOME &&
        !gmBool(self.hspd_impel)
      ) {
        // Move back toward home
        if (self.hspd < byte(self.HSPD_TO_HOME * _home_dir)) {
          self.hspd = byte(self.hspd + _home_dir)
          self.hspd_impel = _home_dir
        }
      }
    }
    self.counter = byte(self.counter + 1)
    if (!(self.counter & 0x3f)) {
      // if facing pc & pc facing away (like Mario Boo behavior)
      if (
        _dist >= self.DIST_ATK - 8 &&
        is_facing_pc_(self) &&
        P.hspd_dir === self.facing_dir &&
        avail_uidx_goc(MAX_GOC1) !== UIDX_NULL
      ) {
        // Create Bullet1, pID $10. PI_MOB3: blue
        GOC1_create(
          self.xl,
          self.yt,
          self.facing_dir,
          self.projectile as ObjectName,
          self.projectile_ver,
          self,
          G.PI_MOB_BLU,
        )
        if (self.counter < 0x80)
          self.counter = 0x80 + 0x20 // 2nd Bullet fires on $C0
        else self.counter = 0 // After 2nd Bullet
      } else {
        self.counter &= 0x7f // lose token for 2nd bullet
      }
    }
  } else {
    // if was aggro last frame: start process for waiting to turn around
    if (gmBool(self.is_aggro)) {
      self.counter |= 1
      self.timer = self.DUR_PACE // $50(80): about 1.33 sec
    }
    self.is_aggro = false
    self.counter &= 0x7f // lose token for 2nd bullet
    // 0: moving, 1: still, waiting to turn around
    if (!(self.counter & 1)) {
      self.hspd = byte(self.HSPD_PACE * self.facing_dir)
      self.hspd_impel = self.facing_dir
    }
    if (!gmBool(self.timer)) {
      if (self.counter & 1) self.facing_dir *= -1 // turn around
      self.timer = self.DUR_PACE
      self.counter = byte(self.counter + 1)
    }
  }
  // Smooth stopping
  if (!gmBool(self.hspd_impel)) {
    self.hspd = byte(self.hspd + -sign8b(self.hspd))
    if (sign8b(self.hspd) !== _home_dir && abs8b(self.hspd) > abs8b(P.hspd)) {
      self.hspd = byte(self.hspd + -sign8b(self.hspd))
    }
  }
}

registerScripts({ Stalfoon_init2, Stalfoon_update, Stalfoon_udp, Stalfoon_draw })
