/**
 * Installs the player-side providers of the collision environment (`collision/env.ts`): the PC body and the
 * PC scripts the collision code calls back into. Everything else (view/cam/solid/game/file) is installed by
 * the bootstrap.
 */

import type { GoBody, PcBody } from '../../collision/body'
import { setCollisionEnv } from '../../collision/env'
import type { GameObject } from '../classes'
import { get_pc_attack_damage, PC_set_bounce, PC_take_damage } from './attack'
import { pc_is_cucco, pc_is_fairy } from './form'
import { pc } from './pc'

export function installPcCollisionEnv(): void {
  setCollisionEnv({
    pc: () => pc() as unknown as PcBody,
    fn: {
      PC_set_bounce: () => PC_set_bounce(),
      get_pc_attack_damage: () => get_pc_attack_damage(),
      PC_take_damage: (attacker: GoBody) => PC_take_damage(attacker as unknown as GameObject),
      pc_is_cucco: () => pc_is_cucco(),
      pc_is_fairy: () => pc_is_fairy(),
    },
  })
}
