/**
 * Adapter contract for audio.
 *
 * ZALiA calls GameMaker's audio API directly (`audio_play_sound`, `audio_is_playing`,
 * `audio_sound_get_track_position`, `audio_group_stop_all`, gains). In the port the core owns *what* plays
 * and *when*; the adapter owns the Web Audio side. The boundary is:
 *
 *   commands  (core → adapter): `Audio.commands` — drained by the adapter every frame after `world.step()`.
 *   state     (adapter → core): an `AudioPlayback` implementation installed with `setAudioPlayback()`;
 *             the core polls it (`isPlaying`, `trackPosition`) exactly where the GML polled GameMaker.
 *
 * Sounds are identified by asset name (`mus_Overworld_Body_1a`), instances by the number `play()` returned.
 * Groups are `'mus' | 'snd'` (GameMaker `audiogroup_mus/snd`). Gains are 0..1 (ZALiA volumes are 0..10 → /10).
 * `world.emit({kind:'sound'|'music'})` is also raised as a convenience mirror; `commands` is authoritative.
 */
export type AudioGroup = 'mus' | 'snd'

export type AudioCommand =
  | {
      kind: 'play'
      inst: number
      sound: string
      group: AudioGroup
      loop: boolean
      priority: number
      gain: number
    }
  | { kind: 'stop'; sound: string }
  | { kind: 'stopInst'; inst: number }
  | { kind: 'stopGroup'; group: AudioGroup }
  | { kind: 'gain'; inst: number; gain: number; ms: number }
  | { kind: 'groupGain'; group: AudioGroup; gain: number }
  | { kind: 'position'; inst: number; seconds: number }

export interface AudioPlayback {
  /** `audio_is_playing(x)`: any instance of the sound (string) / that instance (number) still playing. */
  isPlaying(x: string | number): boolean
  /** `audio_sound_get_track_position(inst)` in seconds. */
  trackPosition(inst: number): number
  /** `audio_sound_get_gain(inst)` / group gain query used by the mute toggles. */
  groupGain(group: AudioGroup): number
  /**
   * `audio_sound_length(x)` in seconds — GM takes either a sound asset or a live instance id. 0 when the
   * length is not known (the asset is not loaded); every caller has its own fallback for that.
   */
  length(x: string | number): number
}

/**
 * In-memory playback model used in tests and as the default: a sound plays from `play` until stopped or,
 * for non-looping sounds with a known length, until `advance()` runs past it.
 */
export class MemoryPlayback implements AudioPlayback {
  readonly playing = new Map<
    number,
    { sound: string; group: AudioGroup; loop: boolean; pos: number; gain: number }
  >()
  readonly lengths = new Map<string, number>()
  readonly groupGains: Record<AudioGroup, number> = { mus: 0.5, snd: 0.5 }
  readonly log: AudioCommand[] = []

  apply(cmd: AudioCommand): void {
    this.log.push(cmd)
    switch (cmd.kind) {
      case 'play':
        // snd_0 is ZALiA's "1 frame of dead air": it is over before the next step
        if (cmd.sound !== 'snd_0')
          this.playing.set(cmd.inst, {
            sound: cmd.sound,
            group: cmd.group,
            loop: cmd.loop,
            pos: 0,
            gain: cmd.gain,
          })
        break
      case 'stop':
        for (const [i, p] of this.playing) if (p.sound === cmd.sound) this.playing.delete(i)
        break
      case 'stopInst':
        this.playing.delete(cmd.inst)
        break
      case 'stopGroup':
        for (const [i, p] of this.playing) if (p.group === cmd.group) this.playing.delete(i)
        break
      case 'gain': {
        const p = this.playing.get(cmd.inst)
        if (p) p.gain = cmd.gain
        break
      }
      case 'groupGain':
        this.groupGains[cmd.group] = cmd.gain
        break
      case 'position': {
        const p = this.playing.get(cmd.inst)
        if (p) p.pos = cmd.seconds
        break
      }
    }
  }
  /** Simulate time passing (seconds). */
  advance(seconds: number): void {
    for (const [i, p] of this.playing) {
      p.pos += seconds
      const len = this.lengths.get(p.sound)
      if (len !== undefined) {
        if (p.loop) p.pos %= len
        else if (p.pos >= len) this.playing.delete(i)
      }
    }
  }
  isPlaying(x: string | number): boolean {
    if (typeof x === 'number') return this.playing.has(x)
    for (const p of this.playing.values()) if (p.sound === x) return true
    return false
  }
  trackPosition(inst: number): number {
    return this.playing.get(inst)?.pos ?? 0
  }
  groupGain(group: AudioGroup): number {
    return this.groupGains[group]
  }
  length(x: string | number): number {
    const name = typeof x === 'number' ? this.playing.get(x)?.sound : x
    return (name !== undefined ? this.lengths.get(name) : undefined) ?? 0
  }
}
