/** Goriya (`GoriA`; v1 orange, v2 red, v3 blue) — boomerang thrower. Ported from `Goriya_*.gml`. */
import { MAX_GOC1, UIDX_NULL } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { GO_update_cs } from '../../../../../collision/cs'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { inRange } from '../../../../../math/index'
import { drawState } from '../../../../../rooms/draw'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { GameObject_draw_1a } from '../../../../go/draw'
import { GO_set_sprite } from '../../../../go/sprite'
import type { ObjectName } from '../../../../objectNames'
import { gp, pc } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'
import { Enemy_update_1, rand } from '../iron_knuckle/common'

export class GoriA extends Enemy {
  readonly objectName = 'GoriA' as const
  attack_dist = 0x60
  BVR_IDLE = 0 // 0 attack NONE
  BVR_ATK1 = 1 // 1 attack low
  BVR_ATK2 = 3 // 3 attack high
  VSPD_GRAV = 2
  ATK_DIST = 0x60
  SPR_ATK2 = 'spr_Goriya_B2' // attack high
  SPR_ATK1 = 'spr_Goriya_B1' // attack low
  SPR_IDL2 = 'spr_Goriya_A2' // legs open
  SPR_IDL1 = 'spr_Goriya_A1' // legs closed
}

/** `Goriya_init2()` */
export function Goriya_init2(self: GoriA): void {
  self.BVR_IDLE = 0
  self.BVR_ATK1 = 1
  self.BVR_ATK2 = 3
  self.projectile_OBJ = 'Boomerang'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.ATK_DIST = 0x60
  self.attack_dist = self.ATK_DIST
  self.counter = 0
  self.SPR_ATK2 = 'spr_Goriya_B2'
  self.SPR_ATK1 = 'spr_Goriya_B1'
  self.SPR_IDL2 = 'spr_Goriya_A2'
  self.SPR_IDL1 = 'spr_Goriya_A1'
}

/** `Goriya_update()` */
export function Goriya_update(self: GoriA): void {
  const g = gp()
  const P = pc()
  self.attack_dist = self.ATK_DIST // $60
  // 9972
  if (gmBool(self.behavior) && !self.timer) {
    // 1,3. if attacking && Attack delay finished. 998B
    if (avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
      if (inRange(self.x, g.view_xl_og, g.view_xr_og) || Math.abs(self.x - P.x) < self.attack_dist) {
        const _YT = self.yt + 0x11 * (self.behavior === self.BVR_ATK1 ? 1 : 0) // 1 attack low
        const _P = GOC1_create(
          self.xl,
          _YT,
          self.facing_dir,
          self.projectile as ObjectName,
          self.projectile_ver,
          self,
        ) as unknown as {
          vspd: number
          facing_dir_spawn: number
          isHighAttack: boolean
        }
        if (self.behavior === self.BVR_ATK2)
          _P.vspd = 0xf0 // attack high
        else _P.vspd = rand(self) & 0x10
        _P.facing_dir_spawn = self.facing_dir
        _P.isHighAttack = self.behavior === self.BVR_ATK2
      }
    }
    self.behavior = self.BVR_IDLE // 0 attack NONE
  }
  // 99F2
  GO_update_cs(self)
  GOB_update_2(self)
  Enemy_update_1(self)
}

/** `Goriya_udp()` */
export function Goriya_udp(self: GoriA): void {
  const g = gp()
  self.can_draw_self = true
  if (!gmBool(self.behavior)) {
    if (gmBool(self.hspd) && g.counter1 & 0x8)
      GO_set_sprite(self, self.SPR_IDL2) // 1 legs open
    else GO_set_sprite(self, self.SPR_IDL1) // 0 legs closed
  } else {
    if (self.behavior === 3)
      GO_set_sprite(self, self.SPR_ATK2) // 3 attack high
    else GO_set_sprite(self, self.SPR_ATK1) // 2 attack low
  }
}

/** `Goriya_draw()` */
export function Goriya_draw(self: GoriA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawState.depth = self.depth
  if (self.sprite) GameObject_draw_1a(self, self.sprite, self.palidx) // draw self
}

export function registerGoriya(): void {
  registerObject('GoriA', GoriA)
  registerScripts({ Goriya_init2, Goriya_update, Goriya_udp, Goriya_draw })
}
registerGoriya()
