import type { Storage } from '@z2/core'

export interface KeyValueStore {
  getItem(key: string): string | null
  setItem(key: string, value: string): void
  removeItem(key: string): void
}

/** `Storage` over `localStorage` — the ZALiA save/preference files, one key each under `zalia/`. */
export class BrowserStorage implements Storage {
  constructor(
    private readonly store: KeyValueStore = globalThis.localStorage,
    private readonly prefix = 'zalia/',
  ) {}
  private k(name: string): string {
    return this.prefix + name
  }
  exists(name: string): boolean {
    return this.store.getItem(this.k(name)) !== null
  }
  readText(name: string): string | undefined {
    return this.store.getItem(this.k(name)) ?? undefined
  }
  writeText(name: string, text: string): void {
    this.store.setItem(this.k(name), text)
  }
  delete(name: string): void {
    this.store.removeItem(this.k(name))
  }
}
