/**
 * `dl_COLOR` — the 256-entry NES-style colour table indexed by the palette tiles in the Tiled `palette`
 * layer (low byte of the tile id). Row layout ($00-$0D, $10-$1D, $20-$2D, $30-$3D, $F0-$F7) as in p_init.
 */
export const DL_COLOR: readonly number[] = (() => {
  const t = new Array<number>(0x100).fill(C_ERR0)
  const rows: number[][] = [
    [
      C_GRY3,
      C_VLT4,
      C_BLU4,
      C_PUR4,
      C_MGN4,
      C_PNK4,
      C_RED4,
      C_ORG4,
      C_YLW4,
      C_YGR4,
      C_GRN4,
      C_GRB4,
      C_CYN4,
      C_BLK1,
    ],
    [
      C_GRY1,
      C_BLU3,
      C_VLT3,
      C_PUR3,
      C_MGN3,
      C_PNK3,
      C_RED3,
      C_ORG3,
      C_YLW3,
      C_YGR3,
      C_GRN3,
      C_GRB3,
      C_CYN3,
      C_BLK1,
    ],
    [
      C_WHT2,
      C_BLU2,
      C_VLT2,
      C_PUR2,
      C_MGN2,
      C_PNK2,
      C_RED2,
      C_ORG2,
      C_YLW2,
      C_YGR2,
      C_GRN2,
      C_GRB2,
      C_CYN2,
      C_GRY4,
    ],
    [
      C_WHT1,
      C_BLU1,
      C_VLT1,
      C_PUR1,
      C_MGN1,
      C_PNK1,
      C_RED1,
      C_ORG1,
      C_YLW1,
      C_YGR1,
      C_GRN1,
      C_GRB1,
      C_CYN1,
      C_GRY2,
    ],
  ]
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r] as number[]
    for (let i = 0; i < row.length; i++) t[(r << 4) + i] = row[i] as number
  }
  const full = [C_BLK0, C_WHT0, C_RED0, C_GRN0, C_BLU0, C_MGN0, C_CYN0, C_YLW0]
  for (let i = 0; i < full.length; i++) t[0xf0 + i] = full[i] as number
  t[0xff] = C_ERR0
  return t
})()

/** Colour index constants (`CI_*`) — position of a colour in `DL_COLOR`. */
export const CI_ERR0 = 0xff
export const CI_BLK1 = DL_COLOR.indexOf(C_BLK1) // $0D
export const CI_WHT1 = DL_COLOR.indexOf(C_WHT1) // $30
export const CI_GRY4 = DL_COLOR.indexOf(C_GRY4)

