/** `dl_COLORS_USED` — every distinct non-error colour of DL_COLOR in table order. */
export const DL_COLORS_USED: readonly number[] = DL_COLOR.filter(
  (c, i, a) => c !== C_ERR0 && a.indexOf(c) === i,
)

/** `color_str(color)` — 6 uppercase hex chars, GM byte order; strings are zero-padded to 6. */
export function color_str(color: number | string): string {
  if (typeof color === 'string') return '0'.repeat(Math.max(0, 6 - color.length)) + color
  let out = ''
  for (let i = 2; i >= 0; i--) out += hexStr((color >> (i << 3)) & 0xff)
  return out
}

