/** `get_color_brightness(color)` — perceived brightness 0..255 (floor). */
export function get_color_brightness(color: number): number {
  return Math.floor(
    ((color >> 0x00) & 0xff) * 0.2126 + ((color >> 0x08) & 0xff) * 0.7152 + ((color >> 0x10) & 0xff) * 0.0722,
  )
}

export const color_get_red = (c: number) => c & 0xff
export const color_get_green = (c: number) => (c >> 8) & 0xff
export const color_get_blue = (c: number) => (c >> 16) & 0xff

/** GM `colour_get_hue/saturation/value` (all 0..255). */
export function colour_get_hsv(c: number): { h: number; s: number; v: number } {
  const r = color_get_red(c) / 255
  const g = color_get_green(c) / 255
  const b = color_get_blue(c) / 255
  const max = Math.max(r, g, b)
  const min = Math.min(r, g, b)
  const d = max - min
  let h = 0
  if (d !== 0) {
    if (max === r) h = ((g - b) / d) % 6
    else if (max === g) h = (b - r) / d + 2
    else h = (r - g) / d + 4
    h /= 6
    if (h < 0) h += 1
  }
  return { h: Math.floor(h * 255), s: Math.floor((max === 0 ? 0 : d / max) * 255), v: Math.floor(max * 255) }
}
export const colour_get_hue = (c: number) => colour_get_hsv(c).h
export const colour_get_saturation = (c: number) => colour_get_hsv(c).s
export const colour_get_value = (c: number) => colour_get_hsv(c).v

/** GM `make_colour_hsv(h, s, v)` with 0..255 components → packed BGR. */
export function make_colour_hsv(h: number, s: number, v: number): number {
  const hh = (((h % 256) + 256) % 256) / 255
  const ss = Math.min(Math.max(s, 0), 255) / 255
  const vv = Math.min(Math.max(v, 0), 255) / 255
  const i = Math.floor(hh * 6)
  const f = hh * 6 - i
  const pp = vv * (1 - ss)
  const q = vv * (1 - f * ss)
  const t = vv * (1 - (1 - f) * ss)
  let r = 0
  let g = 0
  let b = 0
  switch (i % 6) {
    case 0:
      ;[r, g, b] = [vv, t, pp]
      break
    case 1:
      ;[r, g, b] = [q, vv, pp]
      break
    case 2:
      ;[r, g, b] = [pp, vv, t]
      break
    case 3:
      ;[r, g, b] = [pp, q, vv]
      break
    case 4:
      ;[r, g, b] = [t, pp, vv]
      break
    default:
      ;[r, g, b] = [vv, pp, q]
      break
  }
  return (Math.round(b * 255) << 16) | (Math.round(g * 255) << 8) | Math.round(r * 255)
}

/** GM `$BBGGRR` → standard `0xRRGGBB` for the renderer. */
export function bgrToRgb(c: number): number {
  return ((c & 0xff) << 16) | (c & 0xff00) | ((c >> 16) & 0xff)
}
