/** `PC_spawn()`, `set_pc_spawn_xy()`, `PC_reset_to_spawn()` — placing the player on room entry. */
import {
  dk_SceneRando,
  PC_W,
  PC_W_,
  RmName_LEN,
  STR_Randomized,
  STR_Scene,
  STR_Spawn_x,
  STR_Spawn_y,
} from '@z2/data'
import { gmBool } from '../../../nes/math8'
import { NOONE } from '../../../runtime/instance'
import { f, G, g, input, world } from '../../../runtime/world'
import { setCSOffsets, updateCSPoints } from '../../collision/cs'
import { PC_update_hitboxes_1a } from '../../collision/hitbox'
import { collide_pc_body } from '../../collision/pc'
import { collide_solid_grid, find_row_solid } from '../../collision/solid'
import { type Exit, is_exit_type } from '../../exit/Exit'
import { update_go_spawn_1b } from '../../game_object_mgr/spawn'
import { sign_ } from '../../math/index'
import { strR, val } from '../../other/index'
import { cam_xl_min, cam_xr_max, cam_yb_max, cam_yt_min, rm_set_cam_1a } from '../../view/camera'
import { Elevator } from '../classes'
import { GO_update_cam_vars } from '../go/misc'
import { set_xlyt, update_draw_xy } from '../go/movement'
import { PC_set_behavior } from './form'
import type { Lonk } from './Lonk'
import { pc, pcInput } from './pc'

/** Spawn frame. When state==state_SPAWN. */
export function PC_spawn(self: Lonk): void {
  const enter = g.exit_enter as Exit
  const _side = enter.side
  const _exit_type = enter.exit_type
  const _ON_ELEVATOR = is_exit_type(_exit_type, g.EXIT_TYPE_ELEVATOR)
  if (_ON_ELEVATOR) g.EnterRoom_control_timer = g.EnterRoom_DURATION_ELEV
  else if (_side & 0x3) g.EnterRoom_control_timer = g.EnterRoom_DURATION_SIDE
  else if (_side & 0xc) g.EnterRoom_control_timer = 0
  else g.EnterRoom_control_timer = g.EnterRoom_DURATION_DOOR
  set_pc_spawn_xy()
  // The default spawn_yt for entering from a Pit-Up Exit is too low for some rooms that have solid tiles high up.
  if (_side & 0x8 && !_ON_ELEVATOR) {
    // When coming from a Pit-up exit
    updateCSPoints(self)
    if (collide_solid_grid(self.csBtm1X, self.csBtm1Y) || collide_solid_grid(self.csBtm2X, self.csBtm2Y)) {
      const _ROW = Math.min(
        find_row_solid(0, self.csBtm1X >> 3, self.csBtm1Y >> 3, -1),
        find_row_solid(0, self.csBtm2X >> 3, self.csBtm2Y >> 3, -1),
      )
      self.spawn_yt = (_ROW + 1) << 3
      self.spawn_yt -= self.hh
    }
  }
  self.depth = self.depth_def
  set_xlyt(self, self.spawn_xl, self.spawn_yt) // current sprite_index is spr_Placement_32x32
  if ((_side & 0x3) === 0x1)
    self.xScale = -1 // right exit
  else if ((_side & 0x3) === 0x2)
    self.xScale = 1 // left exit
  else if (_ON_ELEVATOR)
    self.xScale = g.last_pc_xscale // MOD
  else self.xScale = sign_(self.x - (enter.xl + (enter.ww >> 1)))
  const _clm = Math.min(
    Math.max(self.x >> 3, ((cam_xl_min() + self.ww_) >> 3) + 1),
    ((cam_xr_max() - self.ww_) >> 3) - 1,
  )
  const _row = Math.min(Math.max(self.yb >> 3, ((cam_yt_min() + self.hh) >> 3) + 2), (cam_yb_max() >> 3) - 2)
  self.RescueDropOff_rc = (_row << 8) | _clm
  self.RescueDropOff_elevator = NOONE
  self.RescueDropOff_solid_inst = NOONE
  self.RmEnter_elevator = NOONE
  if (_ON_ELEVATOR) {
    for (const e of world.instancesOf(Elevator)) {
      if (collide_pc_body(e.BodyHB_xl, e.BodyHB_yt, e.BodyHB_w, e.BodyHB_h)) {
        self.RmEnter_elevator = e
        self.RescueDropOff_elevator = e
        break
      }
    }
  }
  pcInput.cPres = 0 // Attack or Jump button pressed
  pcInput.hHeld = 0
  pcInput.dHeld = false
  input.held_0 = input.held
  PC_set_behavior(self.behavior_IDLE)
  self.attack_phase = 0
  self.Cucco_crouching_state = 0
  self.hspd = 0
  self.hspd_dir = self.xScale // hspd_dir 005F
  self.hspd_dir_spawn = self.hspd_dir
  self.vspd = 0
  self.vspd_dir = 1
  self.vspd_dir_spawn = self.vspd_dir
  self.draw_xoff = 0
  self.draw_yoff = 0
  update_draw_xy(self)
  self.ocs = 0
  GO_update_cam_vars(self) // 00CC, 00C8
  setCSOffsets(self)
  PC_update_hitboxes_1a(pcInput.dHeld)
  self.state = self.state_NORMAL
}

/** `set_pc_spawn_xy()` — spawn position from the entry exit's data (scene rando aware). */
export function set_pc_spawn_xy(): void {
  const enter = g.exit_enter as Exit | null
  if (!enter) return
  const self = pc()
  let _scene_name: string = g.rm_name
  if (G.SceneRando_enabled)
    _scene_name = String(
      val(f.dm_rando.get(dk_SceneRando + STR_Scene + STR_Randomized + g.rm_name), g.rm_name),
    )
  const _EXIT_NAME = _scene_name + strR(f.reen, RmName_LEN + 1)
  self.spawn_xl = Number(val(g.dm_rm.get(_EXIT_NAME + STR_Spawn_x))) << 3
  self.spawn_yt = Number(val(g.dm_rm.get(_EXIT_NAME + STR_Spawn_y))) << 3
  if (gmBool(g.mod_PC_CUCCO_1) && g.CuccoSpell2_Active && g.CuccoSpell2_Option) self.spawn_yt += 0x10
  self.spawn_xl = Math.min(Math.max(self.spawn_xl, cam_xl_min() - 0x28), cam_xr_max() + 0x18)
  self.spawn_yt = Math.min(Math.max(self.spawn_yt, cam_yt_min() - 0x18), cam_yb_max() - 0x18)
  // set spawn_xl based off last x of prev room
  if (enter.exit_type & g.EXIT_BIT_VERT1) {
    self.spawn_xl = (g.leave_rm_x >> 4) << 4
    self.spawn_xl = Math.min(Math.max(self.spawn_xl, enter.xl), enter.xr - Math.min(self.ww, PC_W))
  }
  if (enter.side & 0xf && is_exit_type(enter.exit_type, g.EXIT_TYPE_ELEVATOR)) {
    for (const e of world.instancesOf(Elevator)) {
      const dl_exit = (e as Elevator & { dl_exit?: { findIndex(v: unknown): number } }).dl_exit
      if (dl_exit && dl_exit.findIndex(enter) !== -1) {
        // `set_pc_spawn_xy.gml:47` runs inside `with(Elevator)`, so the bare `spawn_xl/spawn_yt` are the
        // *elevator's* own (it qualifies the PC's with `other.` on the next two lines). Passing the PC's
        // teleported the elevator to the player's spawn point.
        set_xlyt(e, e.spawn_xl, e.spawn_yt) // in case of Out Of Bounds reset
        self.spawn_xl = e.x - PC_W_
        self.spawn_yt = e.yb - 8 - self.hh // in case of Out Of Bounds reset
        pcInput.vHeld = 0 // Don't know why or if this needs to be here..
        break
      }
    }
  }
}

/** `PC_reset_to_spawn(invulnerable value)` — place PC back at spawn. */
export function PC_reset_to_spawn(invulnerable: number): void {
  const self = pc()
  self.iframes_timer = invulnerable
  self.state = self.state_SPAWN
  set_pc_spawn_xy()
  rm_set_cam_1a(self.spawn_xl + self.ww_, self.spawn_yt + self.hh_)
  // Cam position may have changed so some GO may qualify for spawn.
  update_go_spawn_1b(true)
}
