/** `str_hex("1F")` — parse a hex string. */
const str_hex = (s: string) => Number.parseInt(s, 16)

/** GM `instance_create(x, y, obj)` for GameObjects: constructs the registered class, registers, positions. */
/**
 * Resolves an object name with no registered class. Default: none (throw). Tests crossing the entity
 * boundary install a fallback (e.g. nearest registered ancestor layer); production must not.
 */
export let instanceCreateFallback: (obj: ObjectName) => GameObjectClass | undefined = () => undefined
export function setInstanceCreateFallback(fn: typeof instanceCreateFallback): void {
  instanceCreateFallback = fn
}

export function instance_create(x: number, y: number, objIn: ObjectName | number): GameObject {
  // caches store GM object *indices* (`_obj_idx`, `_CutScene01_Object`); resolve them through the gm-index manifest
  const obj = gmObjectNameOf(objIn) as ObjectName
  const cls = objectClasses.get(obj) ?? instanceCreateFallback(obj)
  if (!cls) throw new Error(`object ${obj} has no registered class (not ported yet)`)
  const inst = new cls()
  inst.x = x
  inst.y = y
  installInstanceEnd(inst)
  world.register(inst)
  // init_vars_draw_1a defaults that need globals
  inst.palidx_def = GG().PI_MOB_ORG
  inst.palidx_base = inst.palidx_def
  inst.palidx = inst.palidx_def
  inst.BodyHB_color = gp().BodyHB_COLOR
  inst.is_hostile = inst instanceof Enemy || inst instanceof ProjectileHostile
  GO_sprite_init(inst, DEFAULT_PLACEMENT_SPRITE) // init_vars_draw_1a
  return inst
}

/**
 * `init_vars_go_1a()` — ver/state/timer defaults and the sprite-derived geometry. Every field except the
 * geometry is already a class default on a fresh instance; `xl/xc/xr/yt/yc/yb` are not, and GM derives them
 * here, *before* `scr_init1` runs (an `_init1` that reads `yb` or `xc` sees the created position, not 0).
 */
export function init_vars_go_1a(self: GameObject): void {
  self.state = 0
  self.ver = 1
  self.timer = 0
  self.update_idx = UIDX_NULL
  self.brightness = 0
  set_xy(self, self.x, self.y) // xl = x - sprite xoffset, xc, xr, yt, yc, yb
}

/** `GameObject_create_1a()` — bind data scripts, run scr_init1 */
export function GameObject_create_1a(self: GameObject): void {
  init_vars_go_1a(self)
  const slots = objectScripts.get(self.objectName) ?? {}
  // Object Specific Initializations -----------------------------------------
  if (slots.ini1) self.scr_init1 = resolveScript(slots.ini1)
  if (self.scr_init1) self.scr_init1(self)
  if (slots.ini2) self.scr_init2 = resolveScript(slots.ini2)
  if (slots.updt) self.scr_update = resolveScript(slots.updt)
  if (slots.udp) self.scr_udp = resolveScript(slots.udp)
  if (slots.draw) self.scr_draw = resolveScript(slots.draw)
  if (slots.iend) self.scr_inst_end = resolveScript(slots.iend)
  if (slots.dstr) self.scr_destroy = resolveScript(slots.dstr)
  if (slots.rmen) self.scr_room_end = resolveScript(slots.rmen)
}

/** `GameObject_create_2a(spawn datakey)` — set spawn_idx and dk_spawn from a datakey string or a PRXM index. */
export function GameObject_create_2a(self: GameObject, spawnDatakey: string | number): void {
  if (typeof spawnDatakey === 'string') {
    self.dk_spawn = spawnDatakey
    self.spawn_idx = str_hex(spawnDatakey.slice(-2))
  } else if (spawnDatakey > -1) {
    self.spawn_idx = spawnDatakey
    self.dk_spawn = get_spawn_datakey(gp().rm_name, STR_PRXM, self.spawn_idx)
  } else {
    self.dk_spawn = undefined
  }
}

/** `GameObject_create_3a(properties datakey)` — placement sprite and palette index from data. */
export function GameObject_create_3a(self: GameObject, propDk: string): void {
  const prop = goData.dm_go_prop
  const placement = prop.get(self.objectName + STR_Placement_spr)
  if (placement !== undefined) GO_sprite_init(self, placement as string)
  // Pallette.  note: palidx is defaulted as p.PI_MOB1. -----------------
  // pal_idx specific to the spawn data
  let _spawn_datakey = self.dk_spawn
  if (self.dk_spawn !== undefined) {
    const r = fp().dm_rando.get(
      STR_Randomize + STR_Enemy + STR_Spawn + self.dk_spawn + STR_Spawn + STR_Datakey + STR_Randomized,
    )
    _spawn_datakey = (r as string | undefined) ?? self.dk_spawn
  }
  if (_spawn_datakey !== undefined) {
    const pi = gp().dm_spawn.get(_spawn_datakey + STR_pal_idx)
    if (pi !== undefined) {
      GO_init_palidx(self, pi as number)
      return
    }
  }
  // sets palidx_def, palidx_base, palidx, palidx_permut
  const pi = prop.get(propDk + STR_pal_idx)
  if (pi !== undefined) GO_init_palidx(self, pi as number)
}

/**
 * `GameObject_create(XL, YT, object_index, version, *spawn datakey, *palette idx, *dlg datakey)`
 * Returns the instance or NOONE (unqualified quest / no free slot / fairy encounter).
 */
export function GameObject_create(
  _XL: number,
  _YT: number,
  _OBJECT: ObjectName | number,
  _VERSION: number,
  _SPAWN_DATAKEY: string | number = -1,
  _PALETTE_IDX = -1,
  _DIALOGUE_DATAKEY: string | -1 = -1,
): Ref<GameObject> {
  const g = gp()
  const self = instance_create(_XL, _YT, _OBJECT)
  // get scripts from data, run scr_vars, run scr_ini1
  GameObject_create_1a(self)
  self.ver = _VERSION
  const _OBJ_NAME = self.objectName
  const _OBJVER = _OBJ_NAME + hexStr(self.ver)
  self.state = self.state_NORMAL
  GameObject_create_2a(self, _SPAWN_DATAKEY) // set spawn_idx, set dk_spawn
  // --------------------------------------------------------------------------------------
  if (self.dk_spawn !== undefined) {
    // _val examples: "010204", "01", "02". This instance is qualified for ANY quest if there's no data
    const _val = g.dm_spawn.get(self.dk_spawn + STR_Qualified + STR_Quest + STR_Nums)
    if (typeof _val === 'string' && !_val.includes(hexStr(fp().quest_num))) {
      self.state = 0
      return NOONE
    }
  }
  // sets objver specific properties
  GO_set_prop_values(self)
  // sets placement sprite (so ogX/ogY are accurate) and palette index (spawn-specific or objver)
  GameObject_create_3a(self, _OBJVER)
  // Dialogue for this spawn_dk
  if (self.dk_spawn !== undefined) {
    const d = g.dm_spawn.get(self.dk_spawn + STR_Dialogue + STR_Datakey)
    if (d !== undefined) self.dialogue_datakey = d as string
  }
  self.spawn_xl = _XL
  self.spawn_yt = _YT
  set_xy(self, self.spawn_xl + self.sprite_index_xoff, self.spawn_yt + self.sprite_index_yoff)
  // --------------------------------------------------------------------------------------
  self.facing_dir = dir_to_pc_1(self)
  self.hspd = (0x08 * self.facing_dir) & 0xff // OG
  if (self instanceof Platform) {
    self.scr_step = self.scr_update
    self.facing_dir = 1
    self.xScale = self.facing_dir
    self.hspd = 0
    self.vspd = 0
  } else if (self instanceof Challenge) {
    self.scr_step = self.scr_update
    self.challenge_id = _OBJVER
    self.facing_dir = 1
    self.xScale = self.facing_dir
    self.hspd = 0
  } else if (self instanceof Item) {
    const _SPRITE = (g.dm_ITEM.get(_OBJVER + STR_Sprite) as string | undefined) ?? 'spr_Torch_1a'
    GO_sprite_init(self, _SPRITE)
    // object_index example: ItmK8, ItmC0
    self.ITEM_BIT = (g.dm_ITEM.get(_OBJ_NAME + STR_Bit) as number | undefined) ?? self.ITEM_BIT
    self.ITEM_TYPE = (g.dm_ITEM.get(_OBJ_NAME + STR_Item + STR_Type) as string | undefined) ?? 'undefined'
    self.IS_HOLD_ITEM = (g.dm_ITEM.get(_OBJ_NAME + STR_Hold + STR_Item) as number | undefined) ?? 0
    self.facing_dir = 1
    self.xScale = self.facing_dir
    self.hspd = 0
    if (!self.IS_HOLD_ITEM) pc().Disguise_enabled = false // So pc can stab item.
  } else if (self instanceof Boss) {
    self.facing_dir = dir_to_pc_(self)
  }
  if (self instanceof GOB1) {
    self.update_idx = add_to_update_list_b1(self)
    if (self.update_idx === UIDX_NULL || g.encounter_type & g.ENC_FARY) {
      // No hostile GO for fairy encounter
      self.state = 0
      return NOONE
    }
    if (g.mod_REFLECT_more_obj) {
      // dl_ProjVuln: Projectile Vulnerabilities
      const _DATAKEY = _OBJVER + STR_REFLECT + STR_Vulnerable
      self.dl_ProjVuln = new DsList<string>()
      let _i = 0
      for (;;) {
        const v = goData.dm_go_prop.get(_DATAKEY + hexStr(++_i))
        if (v === undefined) break
        self.dl_ProjVuln.add(v as string)
      }
    }
  } else if (self instanceof GOB2) {
    const _COUNT = goMgr.dl_gob2.size
    for (let _i = 0; _i < _COUNT; _i++) {
      const cur = goMgr.dl_gob2.get(_i)
      if (!instanceExists(cur as GameObject | null | undefined) || !(cur as GameObject).state) {
        goMgr.dl_gob2.set(_i, self)
        break
      }
    }
    if (goMgr.dl_gob2.findIndex(self) === -1) goMgr.dl_gob2.add(self)
    self.update_idx = goMgr.dl_gob2.findIndex(self)
    goMgr.uIdxSwap_gob = UIDX_NULL
    if (pc().Disguise_enabled) {
      // NPC_B: Minigame, NPC_D: Shop
      if (self instanceof NPC && (self.objectName === 'NPC_B' || self.objectName === 'NPC_D')) {
        pc().Disguise_enabled = false
      }
    }
  }
  // Secondary initializations -----------------------------------------
  if (self.scr_init2) self.scr_init2(self)
  // set a depth specific to this spawn
  if (self.dk_spawn !== undefined) {
    const d = g.dm_spawn.get(self.dk_spawn + STR_Depth)
    if (d !== undefined) GO_depth_init(self, d as number)
  }
  //  _PALETTE_IDX has been specified by the instance that spawned this instance
  if (_PALETTE_IDX !== -1) GO_init_palidx(self, _PALETTE_IDX)
  if (self.dk_spawn !== undefined) {
    const _val = g.dm_spawn.get(self.dk_spawn + STR_Palette)
    if (_val !== undefined) {
      const s = _val as string
      deps.change_pal(deps.strReplaceAt(pp_pal_rm_new(), deps.get_pal_pos(self.palidx), s.length, s))
    }
  }
  //  _DIALOGUE_DATAKEY has been specified by the instance that spawned this instance
  if (_DIALOGUE_DATAKEY !== -1) self.dialogue_datakey = _DIALOGUE_DATAKEY
  // --------------------------------------------------------------------------------------
  set_hspd_dir(self)
  self.hspd_dir_spawn = self.hspd_dir
  set_vspd_dir(self)
  self.vspd_dir_spawn = self.vspd_dir
  deps.setCSOffsets(self)
  update_draw_xy(self)
  deps.update_body_hb_1a(self)
  if (g.town_name === 'Bulblin' && pc().Disguise_enabled && self instanceof GOB1) {
    self.state = 0
  }
  // Final initializations -----------------------------------------
  if (self.scr_init3) self.scr_init3(self)
  return self
}

function pp_pal_rm_new(): string {
  return (world.p as unknown as { pal_rm_new: string }).pal_rm_new
}

/** Hooks filled by goc/Projectile.ts (addToProjectileList lives there). */
export const gocHooks = {
  addToProjectileList: (_inst: GameObject): number => UIDX_NULL,
}

/**
 * `GOC1_create(xx, yy, facing dir, object_index, *version, *src inst id, *palette idx)` — hostile projectile
 * factory. `-1` means "not given" (GML truthiness is `> 0.5`, so `if (_VER)` skips -1 and 0).
 */
export function GOC1_create(
  _XL: number,
  _YT: number,
  _FACING: number,
  _OBJ: ObjectName,
  _VER = -1,
  _SRC_INST: Ref<GameObject> | -1 = -1,
  _PAL_IDX = -1,
): GameObjectC {
  const self = instance_create(_XL, _YT, _OBJ) as GameObjectC
  // get scripts from data, run scr_vars, run scr_ini1
  GameObject_create_1a(self)
  if (_VER > 0.5) self.ver = _VER
  self.state = self.state_NORMAL
  if (_SRC_INST !== -1 && _SRC_INST !== NOONE) self.source_inst = _SRC_INST
  const src = self.source_inst
  if (instanceExists(src) && src.state === src.state_NORMAL) self.source_object = src.objectName
  // --------------------------------------------------------------------------------------
  const _PROP_DK = GO_set_prop_values(self)
  // set placement spr, set pi,
  GameObject_create_3a(self, _PROP_DK)
  self.spawn_xl = _XL
  self.spawn_yt = _YT
  set_xlyt(self, _XL, _YT)
  self.facing_dir = _FACING
  self.hspd = (0x20 * self.facing_dir) & 0xff
  self.vspd = 0
  // Secondary initializations -----------------------------------------
  if (self.scr_init2) self.scr_init2(self)
  // pal_idx has been specified by the instance that spawned this instance
  if (_PAL_IDX !== -1) GO_init_palidx(self, _PAL_IDX)
  // --------------------------------------------------------------------------------------
  set_hspd_dir(self)
  self.hspd_dir_spawn = self.hspd_dir
  set_vspd_dir(self)
  self.vspd_dir_spawn = self.vspd_dir
  deps.setCSOffsets(self)
  update_draw_xy(self)
  deps.update_body_hb_1a(self)
  // Final initializations -----------------------------------------
  if (self.scr_init3) self.scr_init3(self)
  return self
}
