/** Challenge_SwitchB: pressure-switch challenges (ver 1 door, 2 toggling blocks, 3 exit, 4 waterfall off). */
import {
  DEPTH_BG4,
  DEPTH_ENEMY,
  dk_BlockBreak,
  PAGE_ROWS,
  PC_LOCK_ALL,
  STR_Active,
  STR_Clms,
  STR_Complete,
  STR_Count,
  STR_Current,
  STR_Depth,
  STR_Height,
  STR_Layer,
  STR_LockedDoor,
  STR_Name,
  STR_Open,
  STR_Rows,
  STR_Surface,
  STR_Waterfall,
  STR_Width,
  TID_SOLID1,
} from '@z2/data'
import { hexStr } from '../../../nes/hexStr'
import { gmBool } from '../../../nes/math8'
import { g } from '../../../runtime/world'
import { pointInRect } from '../../collision/geometry'
import { draw_background_part_ext_ } from '../../draw/index'
import { str_hex } from '../../other/index'
import { pal_swap_reset, pal_swap_set } from '../../palette/scenePalette'
import { draw_background_part } from '../../rooms/draw'
import { aud_play_sound } from '../../sound/play'
import { get_audio_theme_track } from '../../sound/theme'
import { burnableTiles } from '../../tile/burnable'
import { tile_change_1a } from '../../tile/tileOps'
import { tile_layer_delete, tile_layer_find } from '../../tile/tileWorld'
import { GameObject_create } from '../create'
