import { type ExitLike, instancesNamed, type LockedDoorLike, type SwitchBLike } from './deps'

const completeKey = (self: Challenge_SwitchB) => self.challenge_id + STR_Complete
const wv = (self: Challenge_SwitchB, k: string): number => {
  const v = self.Water_dm.get(k)
  return v === undefined ? 0 : Number(v)
}

export function Challenge_SwitchB_init(self: Challenge_SwitchB): void {
  self.STATE_IDLE = 1
  self.STATE_CHANGING1 = 2
  self.STATE_CHANGING2 = 3
  self.STATE_CHANGING3 = 4
  self.STATE_INCOMPLETE = 5
  self.STATE_COMPLETE1 = 6
  self.STATE_COMPLETE2 = 7
  self.STATE_COMPLETE = 8
  self.sub_state = self.STATE_IDLE
  self.DUR_DELAY1 = 0x40 // Delay completion start
  self.DUR_DELAY2 = 0x20 // Delay completion reward
  self.DUR_DELAY3 = 0x10
  let _DEPTH = DEPTH_ENEMY
  for (const sw of instancesNamed('SwchB')) {
    _DEPTH = sw.depth
    break
  }
  for (const p of instancesNamed('PushA')) {
    _DEPTH = p.depth
    break
  }
  for (const sw of instancesNamed('SwchB')) GO_depth_init(sw, _DEPTH + 1)
  self.complete = false
  switch (self.ver) {
    case 1:
      self.locked_door = null
      if (gmBool(fp().dm_challenges.val(completeKey(self)))) {
        self.complete = true
        for (const sw of instancesNamed<SwitchBLike>('SwchB')) sw.complete = true
        self.sub_state = self.STATE_COMPLETE
      } else {
        self.complete = false
        self.locked_door = GameObject_create(self.x, self.y, 'LoDoA', 3)
      }
      break
    case 2:
      self.complete = false
      self.Blocks_COUNT_X = 2
      self.Blocks_COUNT_Y = 2
      self.Blocks_DEPTH = DEPTH_BG4
      self.Blocks_TSRC = 'EEEFFEFF'
      self.Blocks_SND_CHANGE = get_audio_theme_track(dk_BlockBreak)
      Challenge_SwitchB_update_1a(self, !self.complete)
      break
    case 3:
      break
    case 4: {
      // Press switch to turn off waterfall
      self.Water_TSRC1 = 0xf0
      self.Water_TSRC2 = 0xf8
      self.Water_dm = new Map()
      const names = gp().dl_TILE_DEPTH_NAMES
      for (let _i = names.size - 1; _i >= 0; _i--) {
        const _datakey0 = names.get(_i) as string
        const _depth = gp().dm_TILE_DEPTH.get(_datakey0) as number | undefined
        const _layer_name = gp().dm_tile_file?.get?.(_datakey0 + STR_Depth + STR_Layer + STR_Name) as
          | string
          | undefined
        if (_depth && _layer_name?.includes('LIQUID_03')) {
          GO_depth_init(self, _depth - 1)
          self.Water_dm.set(STR_Depth, _depth)
          break
        }
      }
      const _depth = self.Water_dm.get(STR_Depth) as number | undefined
      if (_depth !== undefined) {
        const _XL = 0
        const _CLMS0 = gp().rm_clms
        let _ROWS0: number
        let _YT: number
        if (gp().view_lock_rm & 0xc && gp().view_y_page_min === gp().view_y_page_max) {
          _ROWS0 = PAGE_ROWS
          _YT = (gp().view_y_page_max * PAGE_ROWS) << 3
        } else {
          _ROWS0 = gp().rm_rows
          _YT = 0
        }
        for (let _i = 0; _i < _CLMS0; _i++) {
          let _num = 0
          let _datakey0 = ''
          let _k = _i
          for (let _j = 0; _j < _ROWS0; _j++) {
            let _x = _XL + (_i << 3)
            const _y = _YT + (_j << 3)
            let _tile_id = tile_layer_find(_depth, _x, _y)
            if (_tile_id !== -1) {
              if (!_num) {
                _datakey0 = STR_Waterfall + STR_Count
                _num = wv(self, _datakey0) + 1
                self.Water_dm.set(_datakey0, _num)
                _datakey0 = STR_Waterfall + hexStr(_num)
                self.Water_dm.set(_datakey0 + STR_Surface, -1)
                self.Water_dm.set(`${_datakey0}_XL`, _x)
                self.Water_dm.set(`${_datakey0}_YT`, _y)
                self.Water_dm.set(_datakey0 + STR_Clms, 1)
                for (_k = _i + 1; _k < _CLMS0; _k++) {
                  _x = _XL + (_k << 3)
                  _tile_id = tile_layer_find(_depth, _x, _y)
                  if (_tile_id === -1) {
                    self.Water_dm.set(_datakey0 + STR_Clms, _k - _i)
                    break
                  }
                }
              }
              self.Water_dm.set(_datakey0 + STR_Rows, wv(self, _datakey0 + STR_Rows) + 1)
            }
          }
          if (_num) {
            self.Water_dm.set(_datakey0 + STR_Active, true)
            self.Water_dm.set(_datakey0 + STR_Width, wv(self, _datakey0 + STR_Clms) << 3)
            self.Water_dm.set(_datakey0 + STR_Height, wv(self, _datakey0 + STR_Rows) << 3)
            self.Water_dm.set(_datakey0 + STR_Current + STR_Width, wv(self, _datakey0 + STR_Width))
            self.Water_dm.set(_datakey0 + STR_Current + STR_Height, wv(self, _datakey0 + STR_Height))
            self.Water_dm.set(`${_datakey0 + STR_Current}_XL`, wv(self, `${_datakey0}_XL`))
            self.Water_dm.set(`${_datakey0 + STR_Current}_YT`, wv(self, `${_datakey0}_YT`))
            _i = _k // skip past all clms of this waterfall
          }
        }
        // `Challenge_SwitchB` will be drawing the waterfalls
        tile_layer_delete(_depth)
      }
      break
    }
  }
}

export function Challenge_SwitchB_update(self: Challenge_SwitchB): void {
  switch (self.sub_state) {
    case self.STATE_IDLE: {
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      if (self.ver === 1 && self.complete) {
        self.timer = 0
        self.sub_state = self.STATE_COMPLETE
      }
      let _change = false
      let _all_pressed = true
      for (const sw of instancesNamed<SwitchBLike>('SwchB')) {
        if (!gmBool(sw.pressed)) {
          _all_pressed = false
          break
        }
      }
      switch (self.ver) {
        case 1:
          _change = !self.complete && _all_pressed
          self.complete = self.complete || _all_pressed
          break
        case 2:
        case 3:
        case 4:
          if (self.complete !== _all_pressed) {
            _change = true
            self.complete = _all_pressed
          }
          break
      }
      if (_change) {
        self.timer = 0
        self.sub_state = self.STATE_CHANGING1
      }
      break
    }
    case self.STATE_CHANGING1: {
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      gp().pc_lock = PC_LOCK_ALL
      switch (self.ver) {
        case 1:
          if (self.complete) {
            fp().dm_challenges.set(completeKey(self), 1)
            for (const sw of instancesNamed<SwitchBLike>('SwchB')) sw.complete = self.complete
          }
          break
        case 2:
        case 3:
          fp().dm_challenges.set(completeKey(self), self.complete ? 1 : 0)
          break
        case 4:
          for (const sw of instancesNamed<SwitchBLike>('SwchB')) sw.complete = self.complete
          break
      }
      self.timer = self.DUR_DELAY2
      self.sub_state = self.STATE_CHANGING2
      break
    }
    case self.STATE_CHANGING2: {
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      switch (self.ver) {
        case 1:
          if (self.complete && self.locked_door) (self.locked_door as LockedDoorLike).counter = -1 // Starts opening process
          break
        case 2:
          Challenge_SwitchB_update_1a(self, !self.complete)
          break
        case 3:
          for (const ex of instancesNamed<ExitLike>('Exit')) {
            if (ex.exitNum === 0x00) {
              ex.open = self.complete
              ex.doorway_spr = ex.open ? gp().Doorway1_SPR : 'spr_Doorway01_Closed01'
              aud_play_sound(get_audio_theme_track(STR_Open + STR_LockedDoor))
              break
            }
          }
          break
      }
      self.timer = self.DUR_DELAY3
      self.sub_state = self.STATE_CHANGING3
      break
    }
    case self.STATE_CHANGING3: {
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      gp().pc_lock = 0
      self.timer = 0
      self.sub_state = self.STATE_COMPLETE1
      break
    }
    case self.STATE_COMPLETE1: {
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      self.timer = 0
      self.sub_state = self.STATE_COMPLETE2
      break
    }
    case self.STATE_COMPLETE2: {
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      self.timer = 0
      self.sub_state = self.STATE_COMPLETE
      break
    }
    case self.STATE_COMPLETE: {
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      gp().pc_lock = 0
      switch (self.ver) {
        case 1:
          self.timer = 0
          break
        case 2:
        case 3:
          self.timer = 0
          self.sub_state = self.STATE_IDLE
          break
      }
      break
    }
  }
  if (self.ver === 4) {
    const _Waterfall_COUNT = wv(self, STR_Waterfall + STR_Count)
    if (_Waterfall_COUNT) {
      // Waterfalls put out burning tiles under them
      const dg = burnableTiles.dg_Burnable
      for (let _i = 0; _i < dg.width; _i++) {
        if (!gmBool(dg.get(_i, 0x2))) continue
        const _x = dg.get(_i, 0x5) as number
        const _y = dg.get(_i, 0x6) as number
        for (let _j = 0; _j < _Waterfall_COUNT; _j++) {
          const _datakey0 = STR_Waterfall + hexStr(_j + 1)
          if (!gmBool(wv(self, _datakey0 + STR_Active))) continue
          const _w = wv(self, _datakey0 + STR_Current + STR_Width)
          if (_w > 8) {
            const _h = wv(self, _datakey0 + STR_Current + STR_Height)
            const _xl = wv(self, `${_datakey0 + STR_Current}_XL`)
            const _yt = wv(self, `${_datakey0 + STR_Current}_YT`)
            if (pointInRect(_x, _y, _xl, _yt, _w, _h)) {
              dg.set(_i, 0x2, 0) // main timer
              dg.set(_i, 0x3, 0) // spread timer
              dg.set(_i, 0x4, 0) // can draw
            }
          }
        }
      }
      if (self.sub_state !== self.STATE_IDLE) {
        for (let _i = 0; _i < _Waterfall_COUNT; _i++) {
          const _datakey0 = STR_Waterfall + hexStr(_i + 1)
          if (!gmBool(wv(self, _datakey0 + STR_Active))) continue
          if (wv(self, _datakey0 + STR_Current + STR_Width) > 2) {
            if (!(g.counter1 & 0x7)) {
              self.Water_dm.set(
                _datakey0 + STR_Current + STR_Width,
                wv(self, _datakey0 + STR_Current + STR_Width) - 2,
              )
              self.Water_dm.set(
                `${_datakey0 + STR_Current}_XL`,
                wv(self, `${_datakey0}_XL`) +
                  ((wv(self, _datakey0 + STR_Width) - wv(self, _datakey0 + STR_Current + STR_Width)) >> 1),
              )
            }
          } else {
            self.Water_dm.set(
              `${_datakey0 + STR_Current}_YT`,
              wv(self, `${_datakey0 + STR_Current}_YT`) + 1 + (g.counter1 & 0x1),
            )
            self.Water_dm.set(
              _datakey0 + STR_Current + STR_Height,
              wv(self, _datakey0 + STR_Height) -
                (wv(self, `${_datakey0 + STR_Current}_YT`) - wv(self, `${_datakey0}_YT`)),
            )
            // GM `!x` is `x <= 0.5`, so a height that has walked past 0 into negatives is *false* there
            // and the waterfall deactivates; a JS `!` keeps it alive and sliding down the room.
            if (!gmBool(wv(self, _datakey0 + STR_Current + STR_Height)))
              self.Water_dm.set(_datakey0 + STR_Active, false)
          }
        }
      }
    }
  }
}

/** `Challenge_SwitchB_update_1a(add or remove)` — place/remove the 2x2 block set (ver 2). */
export function Challenge_SwitchB_update_1a(self: Challenge_SwitchB, add: boolean | number): void {
  const _SOLID = gmBool(add) ? TID_SOLID1 : 0
  const _TILESET: string | 0 = gmBool(add) ? 'ts_DungeonA01' : 0
  for (let _i = 0; _i < self.Blocks_COUNT_Y; _i++) {
    for (let _j = 0; _j < self.Blocks_COUNT_X; _j++) {
      for (let _k = 0; _k < 4; _k++) {
        const _x = self.xl + (_j << 4) + ((_k & 1) << 3)
        const _y = self.yt + (_i << 4) + ((_k > 1 ? 1 : 0) << 3)
        const _tsrc = str_hex(self.Blocks_TSRC.substr(_k << 1, 2))
        tile_change_1a(self.Blocks_DEPTH, _x, _y, _TILESET, _tsrc, _SOLID)
      }
    }
  }
  aud_play_sound(self.Blocks_SND_CHANGE)
}

/**
 * `Challenge_SwitchB_draw()` — ver 4 draws the (shrinking) waterfalls. ZALiA pre-renders random-flipped
 * water tiles to surfaces; here the tiles are drawn directly with a deterministic flip per cell (the random
 * flips were re-rolled per surface creation and are purely cosmetic).
 */
export function Challenge_SwitchB_draw(self: Challenge_SwitchB): void {
  if (self.ver !== 4) return
  const _COUNT0 = wv(self, STR_Waterfall + STR_Count)
  if (!_COUNT0) return
  let _can_draw = false
  for (let _i = 0; _i < _COUNT0; _i++) {
    if (gmBool(wv(self, STR_Waterfall + hexStr(_i + 1) + STR_Active))) {
      _can_draw = true
      break
    }
  }
  if (!_can_draw) return
  const _XOFF0 = 0x3 * Math.sign(g.counter1 & 0x4)
  const _YOFF0 = 0x3
  const _YOFF1 = 0x8 - ((g.counter1 >> 0) & 0x7)
  const _YOFF2 = 0x2
  const tsx1 = ((self.Water_TSRC1 + 0x2) & 0xf) << 3
  const tsy1 = (((self.Water_TSRC1 + 0x2) >> 4) & 0xf) << 3
  const tsx2 = (self.Water_TSRC2 & 0xf) << 3
  const tsy2 = ((self.Water_TSRC2 >> 4) & 0xf) << 3
  pal_swap_set(self.palidx)
  for (let _i = 0; _i < _COUNT0; _i++) {
    const _datakey0 = STR_Waterfall + hexStr(_i + 1)
    if (!gmBool(wv(self, _datakey0 + STR_Active))) continue
    const _xl0 = wv(self, `${_datakey0}_XL`)
    let _yt1 = wv(self, `${_datakey0 + STR_Current}_YT`)
    const _xl1 = wv(self, `${_datakey0 + STR_Current}_XL`)
    const _w = wv(self, _datakey0 + STR_Current + STR_Width)
    const _h = wv(self, _datakey0 + STR_Current + STR_Height)
    const _surf_w = wv(self, _datakey0 + STR_Clms) << 3
    _yt1 += _YOFF0
    // top edge strip (Water_surf1: 2 tiles of TSRC1+2, scrolled by _xoff)
    const _xoff = _XOFF0 + ((_xl1 - _xl0) & 0x7)
    const _count = (_w >> 3) + Math.sign(_w & 0x7)
    for (let _j = 0; _j < _count; _j++) {
      const _x = _xl1 + (_j << 3)
      const w = Math.min(_xl1 + _w - _x, 8)
      draw_background_part('ts_Natural_1a_WRB', tsx1 + (_xoff & 0x7), tsy1, w, 8 - (_YOFF2 - 1), _x, _yt1)
    }
    // body: the falling water (Water_dm surface), cropped to the current width/height
    const sx0 = (_surf_w - _w) >> 1
    const rows = (_h + _YOFF1 + 7) >> 3
    const cols = (_w + (sx0 & 7) + 7) >> 3
    for (let r = 0; r <= rows; r++) {
      for (let c = 0; c <= cols; c++) {
        const cellX = ((sx0 >> 3) + c) << 3
        const cellY = r << 3
        const x_scale = (cellX ^ cellY) & 8 ? -1 : 1
        const y_scale = (cellX + cellY) & 16 ? -1 : 1
        const dx = _xl1 + (cellX - sx0) + (x_scale < 0 ? 8 : 0)
        const dy = _yt1 + _YOFF2 + (cellY - _YOFF1) + (y_scale < 0 ? 8 : 0)
        const clipL = Math.max(0, _xl1 - (dx - (x_scale < 0 ? 8 : 0)))
        if (cellX - sx0 >= _w || cellY - _YOFF1 >= _h || cellY - _YOFF1 + 8 <= 0 || cellX - sx0 + 8 <= 0)
          continue
        draw_background_part_ext_(
          self.palidx,
          'ts_Natural_1a_WRB',
          tsx2 + clipL,
          tsy2,
          8 - clipL,
          8,
          dx,
          dy,
          x_scale,
          y_scale,
        )
      }
    }
  }
  pal_swap_reset()
}

export function Challenge_SwitchB_end(self: Challenge_SwitchB): void {
  if (self.ver === 4) self.Water_dm.clear()
}
