/**
 * `BurnableMgr` — burnable tiles set on fire by friendly fire projectiles: BurnableMgr_Create, Room_Start,
 * Game_End, update, update_1a, Draw. State grids are the `burnableTiles` seam filled by `scene_enter_add_tiles`
 * (`game/tile/burnable.ts`), adopted here as ZALiA intended.
 */
import { DEPTH_NPC } from '@z2/data'
import { gmBool, isVal } from '../../nes/math8'
import { DsGrid } from '../../runtime/ds'
import { Instance, instanceExists } from '../../runtime/instance'
import { goMgr, world } from '../../runtime/world'
import { is_in_grid } from '../collision/geometry'
import type { GameObjectC } from '../game_object/classes'
import { GG, gp, pp } from '../game_object/pending'
import { sign_ } from '../game_object/util'
import { build_pal } from '../palette/palString'
import { pal_swap_reset, pal_swap_set } from '../palette/scenePalette'
import { draw_sprite_, drawState } from '../rooms/draw'
import { aud_play_fire } from '../sound/play'
import { burnableTiles } from '../tile/burnable'
import { tile_change_1a } from '../tile/tileOps'
import { graphicsDeps } from './deps'

/** dg_Burnable rows: 0 burn type, 1 tile depth, 2 main timer, 3 spread timer, 4 can draw, 5 x, 6 y, 7 sprite */
export class BurnableMgr extends Instance {
  readonly objectName = 'BurnableMgr'
  /** `<persistent>-1</persistent>` in ZALiA's object definition — survives a room change. */
  override readonly persistent = true
  depth = DEPTH_NPC
  // ---- init_vars_go_1a subset --------------------------------------------------------------------
  state = 0
  timer = 0
  Burnable_DUR1 = 0xb0
  Burnable_DUR2 = 0x10
  Burnable_DUR3 = 0
  FireSound_DUR = 0x14
  SMALL_SPR_CUE = 0x20
  FIRE_SPR1 = 'spr_Flame1'
  FIRE_SPR2 = 'spr_Flame2'
  FIRE_SPR3 = 'spr_Flame_Small_1a'
  FIRE_PI = 0
  FIRE_YOFF = 0
  can_draw = false
  Burnable_PI = 0
  Burnable_COLOR_W = 0x3cbcf0 // NES plain yellow
  Burnable_COLOR_R = 0x1f281f // Extra dark green
  Burnable_COLOR_B = 0x336667 // Light dull yellow-green
  Burnable_COLOR_G = 0
  Burnable_COLOR_Y = 0x3cbcf0
  Burnable_COLOR_M = 0x1f281f
  Burnable_COLOR_K = 0x336667
  Burnable_COLOR_C = 0
  Burnable_PAL = ''
  /** The tile grids live on the shared seam (`scene_enter_add_tiles` writes them). */
  get dg_RmTile_Burnable(): DsGrid<number> {
    return burnableTiles.dg_RmTile_Burnable
  }
  get dg_RmTile_Burnable_def(): DsGrid<number> {
    return burnableTiles.dg_RmTile_Burnable_def
  }
  get dg_Burnable(): DsGrid<number | string> {
    return burnableTiles.dg_Burnable as DsGrid<number | string>
  }
  set dg_Burnable(v: DsGrid<number | string>) {
    burnableTiles.dg_Burnable = v as DsGrid<number>
  }
  get scene_has_burnable(): boolean {
    return burnableTiles.scene_has_burnable
  }
  set scene_has_burnable(v: boolean) {
    burnableTiles.scene_has_burnable = v
  }
  get Burnable_pi(): number {
    return burnableTiles.Burnable_pi
  }
  set Burnable_pi(v: number) {
    burnableTiles.Burnable_pi = v
  }
}

let mgr: BurnableMgr | undefined
/** `g.burnable_mgr` */
export function burnableMgr(): BurnableMgr {
  if (!mgr?.exists) throw new Error('BurnableMgr not created (call BurnableMgr_Create)')
  return mgr
}

export function BurnableMgr_Create(): BurnableMgr {
  const self = world.register(new BurnableMgr())
  mgr = self
  ;(gp() as unknown as { burnable_mgr: BurnableMgr }).burnable_mgr = self
  burnableTiles.dg_RmTile_Burnable = new DsGrid<number>(0, 0, 0)
  burnableTiles.dg_RmTile_Burnable_def = new DsGrid<number>(0, 0, 0)
  burnableTiles.dg_Burnable = new DsGrid<number>(0, 9, 0)
  self.Burnable_DUR1 = 0xb0
  self.Burnable_DUR2 = 0x10
  self.Burnable_DUR3 =
    Math.min(0x20 + self.Burnable_DUR2, self.Burnable_DUR1 - self.Burnable_DUR2) - self.Burnable_DUR2
  self.FireSound_DUR = 0x14
  self.SMALL_SPR_CUE = 0x20
  self.FIRE_SPR1 = 'spr_Flame1'
  self.FIRE_SPR2 = 'spr_Flame2'
  self.FIRE_SPR3 = 'spr_Flame_Small_1a'
  self.FIRE_PI = GG().PI_MOB_ORG
  self.FIRE_YOFF = -((graphicsDeps.spriteHeight(self.FIRE_SPR1) - 8) >> 1)
  self.FIRE_YOFF--
  self.can_draw = false
  self.scene_has_burnable = false
  self.Burnable_PI = GG().PI_BGR4
  self.Burnable_pi = self.Burnable_PI
  self.Burnable_COLOR_G = pp().C_BLK1
  self.Burnable_COLOR_Y = self.Burnable_COLOR_W
  self.Burnable_COLOR_M = self.Burnable_COLOR_R
  self.Burnable_COLOR_K = self.Burnable_COLOR_B
  self.Burnable_COLOR_C = self.Burnable_COLOR_G
  self.Burnable_PAL = build_pal(
    self.Burnable_COLOR_W,
    self.Burnable_COLOR_R,
    self.Burnable_COLOR_B,
    self.Burnable_COLOR_G,
    self.Burnable_COLOR_Y,
    self.Burnable_COLOR_M,
    self.Burnable_COLOR_K,
    self.Burnable_COLOR_C,
  )
  self.depth = DEPTH_NPC
  return self
}

export function BurnableMgr_Game_End(): void {
  burnableTiles.dg_RmTile_Burnable = new DsGrid<number>(0, 0, 0)
  burnableTiles.dg_RmTile_Burnable_def = new DsGrid<number>(0, 0, 0)
  burnableTiles.dg_Burnable = new DsGrid<number>(0, 9, 0)
}

export function BurnableMgr_Room_Start(): void {
  const self = burnableMgr()
  self.dg_Burnable = new DsGrid<number | string>(0, 9, 0)
  self.can_draw = false
  self.scene_has_burnable = false
  self.Burnable_pi = self.Burnable_PI
}

function grow(grid: DsGrid<number | string>, newWidth: number): DsGrid<number | string> {
  const out = new DsGrid<number | string>(newWidth, grid.height, 0)
  for (let y = 0; y < grid.height; y++)
    for (let x = 0; x < Math.min(newWidth, grid.width); x++) out.set(x, y, grid.get(x, y) as number)
  return out
}

export function BurnableMgr_update(): void {
  const self = burnableMgr()
  const { BURNABLE_A, BURNABLE_B, BURNABLE_C } = burnableTiles
  self.can_draw = false
  const rm = self.dg_RmTile_Burnable
  for (let _i = goMgr.dl_goc2.size - 1; _i >= 0; _i--) {
    const proj = goMgr.dl_goc2.get(_i) as GameObjectC | null | undefined
    if (!instanceExists(proj)) continue
    const _clm = proj.x >> 3
    const _row = proj.y >> 3
    if (
      proj.state === proj.state_NORMAL &&
      proj.type_bits & proj.BIT_FIR1 &&
      is_in_grid(_clm, _row, rm.width, rm.height) &&
      isVal((rm.get(_clm, _row) as number) & 0xff, BURNABLE_A, BURNABLE_B)
    ) {
      // light tile on fire
      if (BurnableMgr_update_1a(_clm, _row, true)) proj.state = 0 // if it got lit
    }
  }
  let dg = self.dg_Burnable
  let _COUNT = dg.width
  if (!_COUNT) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // cleanup
  if (!gmBool(dg.get(_COUNT - 1, 2))) {
    // CLEANUP. Truncate any finished.
    let keep = 0
    for (let _i = _COUNT - 1; _i >= 0; _i--) {
      if (gmBool(dg.get(_i, 2))) {
        keep = _i + 1
        break
      }
    }
    dg = grow(dg, keep)
    self.dg_Burnable = dg
    _COUNT = dg.width
  }
  let _can_play_sound = false
  // update main timer & spread
  for (let _i = _COUNT - 1; _i >= 0; _i--) {
    const timer = dg.get(_i, 2) as number
    if (!gmBool(timer)) {
      dg.set(_i, 3, 0) // spread timer
      dg.set(_i, 4, 0) // can draw
      continue
    }
    dg.set(_i, 2, timer - 1) // main timer
    dg.set(_i, 4, 1) // can draw
    self.can_draw = true
    _can_play_sound = _can_play_sound || (dg.get(_i, 2) as number) >= self.SMALL_SPR_CUE
    if (!gmBool(dg.get(_i, 2))) {
      // done burning, remove tile
      let _clm = (dg.get(_i, 5) as number) >> 3
      let _row = (dg.get(_i, 6) as number) >> 3
      const _val = dg.get(_i, 0) === BURNABLE_A ? 0 : -1 // remove solid / dont change solid
      tile_change_1a(dg.get(_i, 1) as number, _clm << 3, _row << 3, 0, 0, _val)
      _clm--
      _row--
      // check surrounding tiles for extra parts of the graphic that need to be removed
      for (let _j = 0; _j < 9; _j++) {
        // 3x3 grid of tiles
        if (_j === 4) continue // This is _i tile(the center tile of the 9)
        const _clm1 = _clm + (_j % 3)
        const _row1 = _row + Math.trunc(_j / 3)
        if (
          is_in_grid(_clm1, _row1, rm.width, rm.height) &&
          ((rm.get(_clm1, _row1) as number) & 0xff) === BURNABLE_C
        ) {
          tile_change_1a(dg.get(_i, 1) as number, _clm1 << 3, _row1 << 3, 0, 0)
          rm.set(_clm1, _row1, 0)
        }
      }
    }
    if (gmBool(dg.get(_i, 3))) dg.set(_i, 3, (dg.get(_i, 3) as number) - 1) // spread timer
    if (!gmBool(dg.get(_i, 3))) {
      // spread fire
      const _clm = ((dg.get(_i, 5) as number) >> 3) - 1 // x
      const _row = ((dg.get(_i, 6) as number) >> 3) - 1 // y
      for (let _j = 0; _j < 9; _j++) {
        // check surrounding tiles for burnables
        if (_j === 4) continue // This is _i tile(the center tile of the 9)
        const _clm1 = _clm + (_j % 3)
        const _row1 = _row + Math.trunc(_j / 3)
        if (
          is_in_grid(_clm1, _row1, rm.width, rm.height) &&
          isVal((rm.get(_clm1, _row1) as number) & 0xff, BURNABLE_A, BURNABLE_B)
        ) {
          // main timer running out: guarantee it gets lit
          if ((dg.get(_i, 2) as number) <= 0x10 || !world.irandom(1)) BurnableMgr_update_1a(_clm1, _row1) // light tile on fire
        }
      }
    }
  }
  void _can_play_sound // aud_play_fire(_can_play_sound) is commented out in ZALiA
}

/** `BurnableMgr_update_1a(clm, row, *use big sprite)` — light a burnable tile through spread or from a fireball. */
export function BurnableMgr_update_1a(_CLM: number, _ROW: number, _USE_BIG_SPRITE = false): boolean {
  const self = burnableMgr()
  const rm = self.dg_RmTile_Burnable
  const _DATA = rm.get(_CLM, _ROW) as number
  if (!gmBool(_DATA)) return false
  rm.set(_CLM, _ROW, 0)
  const _IDX = self.dg_Burnable.width
  const dg = grow(self.dg_Burnable, _IDX + 1)
  self.dg_Burnable = dg
  const r = (n: number) => world.irandom(n)
  dg.set(_IDX, 0, _DATA & 0xff) // burn type
  dg.set(_IDX, 1, gp().dl_TILE_DEPTHS.get((_DATA >> 8) & 0xff) as number) // tile depth
  dg.set(_IDX, 2, self.Burnable_DUR1 + r(self.Burnable_DUR2) * sign_(r(1))) // main timer
  dg.set(_IDX, 3, r(self.Burnable_DUR3) + self.Burnable_DUR2) // spread timer
  dg.set(_IDX, 4, 0) // can draw
  dg.set(_IDX, 5, (_CLM << 3) + 4 + r(1) * sign_(r(1))) // x  +/- 0,1
  dg.set(_IDX, 6, (_ROW << 3) + 4 + r(1) * sign_(r(1))) // y  +/- 0,1
  dg.set(_IDX, 7, !r(3) || _USE_BIG_SPRITE ? self.FIRE_SPR1 : self.FIRE_SPR2) // 8x16 / 8x8
  aud_play_fire(true)
  return true
}

export function BurnableMgr_Draw(): void {
  const self = burnableMgr()
  if (!self.can_draw) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  self.can_draw = false
  const dg = self.dg_Burnable
  const _depth_prev = drawState.depth
  pal_swap_set(self.FIRE_PI)
  for (let _i = dg.width - 1; _i >= 0; _i--) {
    if (!gmBool(dg.get(_i, 4))) continue
    dg.set(_i, 4, 0) // can draw
    // GML assigns the *instance* `depth` per tile, one tile in front of the tile layer it burns on. GM
    // applies a depth change to the next frame's sort, so all flames really drew at one depth; here every
    // command carries its own depth, which is what the per-tile assignment asks for (FIDELITY_NOTES).
    self.depth = (dg.get(_i, 1) as number) - 1
    drawState.depth = self.depth
    const _spr = (dg.get(_i, 2) as number) >= self.SMALL_SPR_CUE ? (dg.get(_i, 7) as string) : self.FIRE_SPR3
    const _x = dg.get(_i, 5) as number
    const _y = (dg.get(_i, 6) as number) - ((graphicsDeps.spriteHeight(_spr) - 8) >> 1)
    draw_sprite_(_spr, 0, _x, _y, self.FIRE_PI, sign_((dg.get(_i, 2) as number) & 4))
  }
  pal_swap_reset()
  drawState.depth = _depth_prev
}
