/** GM builtins the screens use that `Game/gm.ts` does not provide. */
import type { DsList } from '../../runtime/ds'
import { world } from '../../runtime/world'

/** `string_count(substr, str)` */
export function string_count(sub: string, str: string): number {
  if (!sub) return 0
  return str.split(sub).length - 1
}
/** `string_delete(str, index, count)` — 1-based */
export const string_delete = (str: string, index: number, count: number): string =>
  str.slice(0, index - 1) + str.slice(index - 1 + count)
/** `string_insert(substr, str, index)` — 1-based */
export const string_insert = (sub: string, str: string, index: number): string =>
  str.slice(0, index - 1) + sub + str.slice(index - 1)
/** `ds_list_shuffle(list)` — Fisher–Yates with the world PRNG (GM uses its own RNG state too). */
export function ds_list_shuffle<T>(l: DsList<T>): void {
  const a = l.items
  for (let i = a.length - 1; i > 0; i--) {
    const j = world.irandom(i)
    const t = a[i] as T
    a[i] = a[j] as T
    a[j] = t
  }
}
/** `random_get_seed()` */
export const random_get_seed = (): number => world.randomize(world.irandom(0x7fffffff))
/** `file_text_open_write` / `file_text_write_string` / `file_text_close` on `world.storage`. */
export interface TextWriter {
  name: string
  text: string
}
export const file_text_open_write = (name: string): TextWriter => ({ name, text: '' })
export const file_text_write_string = (f: TextWriter, s: string): void => {
  f.text += s
}
export const file_text_close = (f: TextWriter): void => world.storage.writeText(f.name, f.text)

import { get_saved_value, set_saved_value } from '../file/save'
// biome-ignore lint/suspicious/noExplicitAny: GML-typed wrappers
export const getSaved = (...a: any[]): any => (get_saved_value as any)(...a)
// biome-ignore lint/suspicious/noExplicitAny: GML-typed wrappers
export const setSaved = (...a: any[]): any => (set_saved_value as any)(...a)

import { gmBool } from '../../nes/math8'
/** `gmBool` over GML-typed (any) values. */
// biome-ignore lint/suspicious/noExplicitAny: GML-typed wrapper
export const gmb = (v: any): boolean => (typeof v === 'string' ? v.length > 0 : gmBool(v))
