/**
 * `PaletteEditor` (IDE folder `dev/Dev_Palette`) — the in-game palette editor: pick one of the scene's
 * editable palette colours, then pick a replacement from the colour grid; plus a background-colour
 * picker and a "show every palette" overlay. Opened from Options → Other / Dev Tools (through
 * `guiSeams.PaletteEditor_initiate_pal_edit_mode` / `_bgr_edit_mode`) or with the gamepad combos.
 *
 * Deviations
 * - GM surfaces (`ColorGrid_surf`, `PalEdit_Outline_surf`, `Cursor_surf`, `ColorOutline1_surf`,
 *   `ObjPal_surf`) were pixel caches; every one is redrawn from primitives each frame here.
 * - `PaletteEditor_draw_PalView` sampled `global.palette_image` (a sprite in ZALiA, a data texture in
 *   this port), so the overlay is drawn from `p.pal_rm_curr` with `get_pal_color` instead — same picture.
 * - `PaletteEditor_Draw_GUI_Begin` is entirely `/* *\/`-commented in ZALiA → dropped.
 * - The keyboard shortcuts ('P' = show all palettes, Ctrl+'P' = open, 'C' = colour info) need 'P'/'C'
 *   in `RawInput`'s `Key` union; until they are added those reads are false and the gamepad combos and
 *   the Options menu entries are the way in.
 * - `dev_output_colors_1a` / `dev_automate_palette_data2` are code-generation scripts (print GML to
 *   paste back into the source) → dropped with the rest of the `debug` folder.
 */
import { STR_Color, STR_Count, STR_Index, STR_Name, STR_Palette, STR_Width } from '@z2/data'
import { DsList, DsMap } from '../../runtime/ds'
import { Instance } from '../../runtime/instance'
import { G, g, input, p } from '../../runtime/world'
import { keyboard_check, keyboard_check_pressed } from '../Game/gm'
import { c_black, c_white } from '../Game/gmConsts'
import { set_background_color } from '../graphics/index'
import { bit_dir } from '../math/index'
import { hex_str, strReplaceAt, val } from '../other/index'
import {
  color_str,
  colour_get_hue,
  colour_get_saturation,
  colour_get_value,
  get_color_brightness,
  PAL_BASE_COLOR_ORDER,
  PAL_CHAR_PER_COLOR,
  PAL_CHAR_PER_PAL,
} from '../palette/colors'
import { get_pal_col_pos, get_pal_color, get_pal_pos } from '../palette/palString'
import { PI_BGR1, PI_BGR2, PI_BGR3, PI_BGR4, PI_BGR5 } from '../palette/pi'
import { get_random_color, get_random_palette2 } from '../palette/randomColors'
import { change_pal } from '../palette/scenePalette'
import { draw_rect_, draw_sprite_, draw_text_, drawState } from '../rooms/draw'
import { viewXL, viewYT } from '../view/camera'

const state_IDLE = 0
const state_EDIT1A = 1 // pick a color in a palette to change
const state_EDIT1B = 2 // picking a new color from a color grid
const state_BGR_COLOR = 3 // pick background color

const SPR_1x1 = 'spr_1x1_WHT'

/** One row of the on-screen instruction block (`Info1_dg` in the GML). */
interface Info1Row {
  text: string
  states: number[]
}

export class PaletteEditor extends Instance {
  readonly objectName = 'PaletteEditor'
  /** `<persistent>-1</persistent>` in ZALiA's object definition — survives a room change. */
  override readonly persistent = true
  depth = 0 // DEPTH_HUD (set in Create)
  readonly state_IDLE = state_IDLE
  readonly state_EDIT1A = state_EDIT1A
  readonly state_EDIT1B = state_EDIT1B
  readonly state_BGR_COLOR = state_BGR_COLOR
  state = state_IDLE
  gui_state_at_sess_start = 0
  readonly gui_PAD2 = 0x8 // editor elements x separator
  readonly gui_PAD3 = 0x2
  readonly gui_Background_ALPHA = 0.7
  gui_xl = 0
  gui_yt = 0
  readonly gui_XLOFF = 0x2
  readonly gui_YTOFF = 0x2
  Font1_sprite = 'spr_Font3_1'
  readonly Font1_W = 8
  readonly Font1_H = 8
  color_old = 0
  color_new = 0
  // PalView --------------------------------------------------------------
  PalView_enabled = false
  readonly PalView_SCALE1 = 2
  PalView_xl = 0
  PalView_yt = 0
  readonly PalView_XL = 0x01 << 3
  readonly PalView_YT = 0x05 << 3
  // Cursor ---------------------------------------------------------------
  Cursor_can_draw = false
  readonly Cursor_COLOR = 0x40a0ff // c_orange
  readonly Cursor_W = 6 + 4
  readonly Cursor_H = 6 + 4
  Cursor_xl = 0
  Cursor_yt = 0
  // Palette edit ---------------------------------------------------------
  readonly PalEdit_SCALE = 6
  readonly PalEdit_Outline_W = 2
  PalEdit_X_BASE = 0
  PalEdit_xl = 0
  PalEdit_yt = 0
  PalEdit_dm = new DsMap<number | string | boolean>()
  PalEdit_group_count = 0
  PalEdit_PALS_W = 0
  PalEdit_PALS_H = 0
  PalEdit_PAL_COUNT = 0
  PalEdit_Cursor_clm = 0
  PalEdit_Cursor_row = 0
  readonly PalEdit_ViewColorInfo_KEY = 'C'
  PalEdit_ViewColorInfo_enabled = false
  // Colour grid ----------------------------------------------------------
  readonly ColorGrid_SCALE = 6
  readonly ColorGrid_Outline_W = 2
  ColorGrid_dl_colors = new DsList<number>()
  ColorGrid_CLMS = 0
  ColorGrid_ROWS = 0
  ColorGrid_Cursor_clm = 0
  ColorGrid_Cursor_row = 0
  ColorGrid_W = 0
  ColorGrid_H = 0
  ColorGrid_xl = 0
  ColorGrid_yt = 0
  ColorGrid_X_BASE = 0
  // Info block -----------------------------------------------------------
  Info1_can_draw = false
  Info1_rows: Info1Row[] = []
  Info1Area_W = 0
  Info1Area_h = 0
  Info1Area_xl = 0
  Info1Area_yt = 0
  Info1Area_X_BASE = 0
  readonly Info1Area_Y_BASE = 0x2
  readonly Info1_PAD2 = 0x2
  readonly Info1_DIST1 = 8 + 0x2 + 0x2
  // timers / keys --------------------------------------------------------
  readonly DELAY1_DUR = 0x10
  readonly DELAY2_DUR = 0x20
  readonly DELAY4_DUR = 0x40
  timer = 0x40
  PP = false // 'P' key pressed
  PP0 = false // 'P' is the ONLY key pressed
  CTL = false
  SHF = false
  ALT = false
  // history / backups ----------------------------------------------------
  dl_hist_sess = new DsList<string>()
  dl_hist_room = new DsList<string>()
  pal_before_edit_sess = ''
  pal_before_edit_color = ''
  pal_during_edit = ''
  BgrColor_before_edit = 0

  constructor() {
    super()
    PaletteEditor_Create(this)
  }
  step(): void {
    PaletteEditor_Step(this)
  }
  draw(): void {
    PaletteEditor_Draw(this)
  }
  roomStart(): void {
    PaletteEditor_Room_Start(this)
  }
}

/** `PaletteEditor_Create()` */
export function PaletteEditor_Create(self: PaletteEditor): void {
  self.depth = 0 // DEPTH_HUD; the port draws screens by `drawState.depth`
  self.state = state_IDLE

  // --- editable palettes. ZALiA ships with only the BGR group live (`if (true)`); the PC / CUCCO /
  //     MOB groups are behind `if (false)` and are dropped here (dead code, kept as this comment).
  const dm = self.PalEdit_dm
  dm.clear()
  let _xl = 0
  let _count1 = 0
  self.PalEdit_group_count = 0
  dm.set(STR_Palette + dk_XL, _xl)
  dm.set(STR_Group1 + hex_str(++self.PalEdit_group_count) + dk_XL, _xl)
  const BGR_COUNT = Number(val(p.dm_pi.get(`BGR${STR_Count}`)))
  const BGR_PIS = [PI_BGR1, PI_BGR2, PI_BGR3, PI_BGR4, PI_BGR5]
  for (let _i = 0; _i < BGR_PIS.length; _i++) {
    if (BGR_COUNT <= _i) continue
    const _dk1 = STR_Palette + hex_str(++_count1)
    dm.set(_dk1 + STR_Name, `BGR ${_i + 1}`)
    dm.set(_dk1 + STR_Palette + STR_Index, BGR_PIS[_i] as number)
    dm.set(_dk1 + dk_XL, _xl)
    _xl += self.PalEdit_SCALE
  }
  dm.set(
    STR_Group1 + hex_str(self.PalEdit_group_count) + STR_Width,
    _xl - Number(val(dm.get(STR_Group1 + hex_str(self.PalEdit_group_count) + dk_XL))),
  )
  self.PalEdit_PALS_W = _xl - Number(val(dm.get(STR_Palette + dk_XL)))
  self.PalEdit_PALS_H = PAL_BASE_COLOR_ORDER.length * self.PalEdit_SCALE
  self.PalEdit_PAL_COUNT = _count1
  self.PalEdit_Cursor_clm = 0
  self.PalEdit_Cursor_row = 0
  self.PalEdit_X_BASE = Math.max(0, self.gui_XLOFF - self.PalEdit_Outline_W)

  // --- colour grid (ColorGrid_VER 2: `global.dl_COLOR01`, rotated to landscape) -------------------
  self.ColorGrid_dl_colors.clear()
  let CLMS = p.ColorGrid_CLMS
  let ROWS = p.ColorGrid_ROWS
  const src = p.dl_COLOR01 as readonly number[]
  if (ROWS > CLMS) {
    // grid is portrait; rotate to landscape so it covers less of the scene
    for (let _j = 0; _j < CLMS; _j++)
      for (let _i = ROWS - 1; _i >= 0; _i--) self.ColorGrid_dl_colors.add(src[CLMS * _i + _j] as number)
    const t = CLMS
    CLMS = ROWS
    ROWS = t
  } else {
    for (const c of src) self.ColorGrid_dl_colors.add(c)
  }
  self.ColorGrid_CLMS = CLMS
  self.ColorGrid_ROWS = ROWS
  self.ColorGrid_Cursor_clm = 0
  self.ColorGrid_Cursor_row = 0
  self.ColorGrid_W = CLMS * self.ColorGrid_SCALE + (self.ColorGrid_Outline_W << 1)
  self.ColorGrid_H = ROWS * self.ColorGrid_SCALE + (self.ColorGrid_Outline_W << 1)
  self.ColorGrid_X_BASE = self.gui_XLOFF + self.PalEdit_PALS_W + self.gui_PAD2 - self.ColorGrid_Outline_W

  // --- instruction block ---------------------------------------------------------------------
  const EDITS = [state_EDIT1A, state_EDIT1B, state_BGR_COLOR]
  self.Info1_rows = [
    { text: 'B: CANCEL CHANGES AND EXIT', states: EDITS },
    { text: 'START: CONFIRM CHANGES AND EXIT', states: EDITS },
    { text: 'A: PICK NEW COLOR', states: [state_EDIT1A, state_EDIT1B] },
    { text: 'X,X+LT,X+RT: RANDOMIZE COLOR(S)', states: [state_EDIT1A] },
    { text: 'Y,Y+LT,Y+RT: VIEW PREVIOUS COLOR(S)', states: EDITS },
    { text: `PRESS '${self.PalEdit_ViewColorInfo_KEY}': TOGGLE COLOR INFO`, states: EDITS },
  ]
  const _len1 = self.Info1_rows.reduce((m, r) => Math.max(m, r.text.length), 0)
  self.Info1Area_W = self.Font1_W * _len1 + (self.Info1_PAD2 << 1)
  self.Info1Area_X_BASE = self.ColorGrid_X_BASE + self.ColorGrid_W + 0x6

  self.timer = self.DELAY4_DUR
  self.BgrColor_before_edit = Number(val(p.BackgroundColor_scene, p.C_BLK1))
}

const dk_XL = '_XL'
const STR_Group1 = '_Group'

/** `PaletteEditor_Room_Start()` */
export function PaletteEditor_Room_Start(self: PaletteEditor): void {
  self.dl_hist_sess.clear()
  self.dl_hist_room.clear()
  self.dl_hist_room.add(p.pal_rm_curr)
  self.pal_before_edit_sess = ''
  self.timer = self.DELAY4_DUR
  self.state = state_IDLE
}

/** `PaletteEditor_initiate_pal_edit_mode()` */
export function PaletteEditor_initiate_pal_edit_mode(self: PaletteEditor): void {
  self.gui_state_at_sess_start = g.gui_state
  g.gui_state = g.gui_state_EDIT_PAL
  self.pal_before_edit_sess = p.pal_rm_curr
  self.pal_during_edit = self.pal_before_edit_sess
  self.PalEdit_ViewColorInfo_enabled = false
  self.timer = self.DELAY1_DUR // Delay any input reaction in next state.
  self.state = state_EDIT1A
}

/** `PaletteEditor_initiate_bgr_edit_mode()` */
export function PaletteEditor_initiate_bgr_edit_mode(self: PaletteEditor): void {
  self.BgrColor_before_edit = Number(val(p.BackgroundColor_scene, p.C_BLK1))
  const _IDX = self.ColorGrid_dl_colors.findIndex(self.BgrColor_before_edit)
  if (_IDX !== -1) {
    self.ColorGrid_Cursor_clm = _IDX % self.ColorGrid_CLMS
    self.ColorGrid_Cursor_row = Math.trunc(_IDX / self.ColorGrid_CLMS)
  }
  self.gui_state_at_sess_start = g.gui_state
  g.gui_state = g.gui_state_EDIT_PAL
  self.timer = self.DELAY1_DUR // Delay any input reaction in next state.
  self.state = state_BGR_COLOR
}

/** `PaletteEditor_get_cursor_color(for palette grid)` */
export function PaletteEditor_get_cursor_color(self: PaletteEditor, forPaletteGrid: boolean): number {
  if (forPaletteGrid) {
    const _PI = Number(
      val(self.PalEdit_dm.get(STR_Palette + hex_str(self.PalEdit_Cursor_clm + 1) + STR_Palette + STR_Index)),
    )
    const _COLOR_CHAR = PAL_BASE_COLOR_ORDER.charAt(self.PalEdit_Cursor_row)
    return get_pal_color(self.pal_during_edit, _PI, _COLOR_CHAR)
  }
  const _IDX = self.ColorGrid_Cursor_row * self.ColorGrid_CLMS + self.ColorGrid_Cursor_clm
  return (self.ColorGrid_dl_colors.get(_IDX) as number) ?? 0
}

/** `PaletteEditor_update_cursor()` */
export function PaletteEditor_update_cursor(self: PaletteEditor): void {
  if (!input.pressedHV) return
  if (self.state === state_EDIT1A) {
    if (input.pressedH)
      self.PalEdit_Cursor_clm =
        (self.PalEdit_Cursor_clm + bit_dir(input.pressedH) + self.PalEdit_PAL_COUNT) % self.PalEdit_PAL_COUNT
    if (input.pressedV)
      self.PalEdit_Cursor_row =
        (self.PalEdit_Cursor_row + bit_dir(input.pressedV) + PAL_BASE_COLOR_ORDER.length) %
        PAL_BASE_COLOR_ORDER.length
  } else {
    // state_EDIT1B, state_BGR_COLOR
    if (input.pressedH)
      self.ColorGrid_Cursor_clm =
        (self.ColorGrid_Cursor_clm + bit_dir(input.pressedH) + self.ColorGrid_CLMS) % self.ColorGrid_CLMS
    if (input.pressedV)
      self.ColorGrid_Cursor_row =
        (self.ColorGrid_Cursor_row + bit_dir(input.pressedV) + self.ColorGrid_ROWS) % self.ColorGrid_ROWS
  }
}

/** `PaletteEditor_Step_1()` — the 'P' overlay toggle and the "randomize now" combo. */
export function PaletteEditor_Step_1(self: PaletteEditor): void {
  if (self.state === state_EDIT1A || self.state === state_EDIT1B || self.state === state_BGR_COLOR) {
    self.PalView_enabled = false
  } else if (self.PP0) {
    self.PalView_enabled = !self.PalView_enabled // Toggle show all palettes
  } else if (self.state === state_IDLE) {
    // Randomize palette right now: Ctrl+Shift+P, or hold(TrigR + XBox-B) and press XBox-Y
    if (
      (self.PP && self.CTL && self.SHF) ||
      (input.GP_Other6_held && input.GP_Other1_held && input.Other2_pressed)
    ) {
      let _palette = p.pal_rm_curr
      for (let _i = 0; _i < self.PalEdit_PAL_COUNT; _i++) {
        const _pi = Number(val(self.PalEdit_dm.get(STR_Palette + hex_str(_i + 1) + STR_Palette + STR_Index)))
        _palette = strReplaceAt(_palette, get_pal_pos(_pi), PAL_CHAR_PER_PAL, get_random_palette2(-1))
      }
      change_pal(_palette)
    }
  }
}

/** `PaletteEditor_Step()` */
export function PaletteEditor_Step(self: PaletteEditor): void {
  self.CTL = keyboard_check('vk_control')
  self.SHF = keyboard_check('vk_shift')
  self.ALT = keyboard_check('vk_alt')
  self.PP = keyboard_check_pressed('P')
  self.PP0 = !self.CTL && !self.SHF && !self.ALT && self.PP
  const CTL0 = self.CTL && !self.SHF && !self.ALT

  const _EDIT_REQUESTED_PAL =
    (CTL0 && self.PP) || (input.GP_Other6_held && input.GP_Other4_held && input.Other2_pressed)
  const _EDIT_REQUESTED_BGR = input.GP_Other5_held && input.GP_Other3_held && input.Other2_pressed
  const _Input_COLOR_SELECTED = !!input.Jump_pressed || !!input.Pause_pressed
  const _Input_ViewOld_HELD = input.GP_Other2_held // xbox 'Y'. Toggle old/new
  const _Input_ViewOld_RELS = input.Other2_released
  const _Input_Randomize_PRES = !!input.Attack_pressed // xbox 'X'
  const _Input_CANCEL =
    keyboard_check_pressed('vk_backspace') || keyboard_check_pressed('vk_escape') || input.Other1_pressed

  if (self.timer) self.timer--
  if (!self.timer) PaletteEditor_Step_1(self)

  const editing = self.state === state_EDIT1A || self.state === state_EDIT1B || self.state === state_BGR_COLOR
  if (editing) {
    self.PalView_enabled = false
    if (self.state === state_EDIT1A) self.color_old = PaletteEditor_get_cursor_color(self, true)
    else if (self.state === state_BGR_COLOR) self.color_old = self.BgrColor_before_edit
    self.color_new = PaletteEditor_get_cursor_color(self, false)
  }

  switch (self.state) {
    case state_IDLE: {
      if (self.timer) break
      if (g.gui_state === g.gui_state_NONE) {
        if (_EDIT_REQUESTED_PAL) {
          PaletteEditor_initiate_pal_edit_mode(self)
          break
        }
        if (_EDIT_REQUESTED_BGR) {
          PaletteEditor_initiate_bgr_edit_mode(self)
          break
        }
      }
      break
    }

    case state_EDIT1A: {
      // Choose a palette's color to change
      if (self.timer) break
      if (input.Pause_pressed) {
        // Complete changes
        self.dl_hist_sess.clear()
        g.gui_state = g.gui_state_NONE
        self.timer = self.DELAY1_DUR
        self.state = state_IDLE
        break
      }
      if (_Input_CANCEL || _EDIT_REQUESTED_PAL) {
        // CLOSE PaletteEditor
        change_pal(self.pal_before_edit_sess)
        self.dl_hist_sess.clear()
        g.gui_state = g.gui_state_NONE
        self.timer = self.DELAY1_DUR
        self.state = state_IDLE
        break
      }
      if (_Input_COLOR_SELECTED) {
        if (self.pal_before_edit_sess !== p.pal_rm_curr) self.dl_hist_room.add(p.pal_rm_curr)
        self.pal_before_edit_color = p.pal_rm_curr
        self.pal_during_edit = p.pal_rm_curr
        const _idx = self.ColorGrid_dl_colors.findIndex(self.color_old)
        if (_idx !== -1) {
          self.ColorGrid_Cursor_clm = _idx % self.ColorGrid_CLMS
          self.ColorGrid_Cursor_row = Math.trunc(_idx / self.ColorGrid_CLMS)
        }
        self.timer = self.DELAY2_DUR
        self.state = state_EDIT1B
        break
      }

      const _Input1_HELD = input.GP_Other5_held // trig L: all colors of the cursor's PI
      const _Input2_HELD = input.GP_Other6_held // trig R: the whole palette

      if (_Input_ViewOld_HELD) {
        // TOGGLE OLD/NEW
        if (_Input1_HELD && _Input2_HELD) break
        if (!_Input1_HELD && !_Input2_HELD) {
          // SINGLE COLOR
          const _PI = cursorPi(self)
          const _POS = get_pal_col_pos(_PI, PAL_BASE_COLOR_ORDER.charAt(self.PalEdit_Cursor_row))
          const _COL1 = self.pal_before_edit_sess.substr(_POS - 1, PAL_CHAR_PER_COLOR)
          const _COL2 = self.pal_during_edit.substr(_POS - 1, PAL_CHAR_PER_COLOR)
          if (_COL1 !== _COL2) {
            change_pal(strReplaceAt(p.pal_rm_new, _POS, _COL1.length, _COL1))
            break
          }
        }
        if (_Input1_HELD && !_Input2_HELD) {
          // ALL COLORS OF THE CURSOR'S PI
          const _POS = get_pal_pos(cursorPi(self))
          const _PAL1 = self.pal_before_edit_sess.substr(_POS - 1, PAL_CHAR_PER_PAL)
          const _PAL2 = self.pal_during_edit.substr(_POS - 1, PAL_CHAR_PER_PAL)
          if (_PAL1 !== _PAL2) {
            change_pal(strReplaceAt(p.pal_rm_new, _POS, _PAL1.length, _PAL1))
            break
          }
        }
        if (_Input2_HELD && !_Input1_HELD) {
          // WHOLE PALETTE
          if (self.pal_during_edit !== self.pal_before_edit_sess) {
            change_pal(self.pal_before_edit_sess)
            break
          }
        }
        break
      }
      if (_Input_ViewOld_RELS && self.pal_during_edit !== self.pal_before_edit_sess) {
        change_pal(self.pal_during_edit)
        break
      }

      if (_Input_Randomize_PRES) {
        if (_Input1_HELD && _Input2_HELD) break
        if (!_Input1_HELD && !_Input2_HELD) {
          // Randomize the color the cursor is on
          const _color_char = PAL_BASE_COLOR_ORDER.charAt(self.PalEdit_Cursor_row)
          const _pos = get_pal_col_pos(cursorPi(self), _color_char)
          const _color = get_random_color(true, _color_char)
          self.pal_during_edit = change_pal(
            strReplaceAt(self.pal_during_edit, _pos, PAL_CHAR_PER_COLOR, color_str(_color)),
          )
          break
        }
        if (_Input1_HELD && !_Input2_HELD) {
          // Randomize the palette the cursor is on
          const _pos = get_pal_pos(cursorPi(self))
          self.pal_during_edit = change_pal(
            strReplaceAt(self.pal_during_edit, _pos, PAL_CHAR_PER_PAL, get_random_palette2(-1)),
          )
          break
        }
        if (!_Input1_HELD && _Input2_HELD) {
          // Randomize all editable colors
          for (let _i = 0; _i < self.PalEdit_PAL_COUNT; _i++) {
            const _pi = Number(
              val(self.PalEdit_dm.get(STR_Palette + hex_str(_i + 1) + STR_Palette + STR_Index)),
            )
            self.pal_during_edit = strReplaceAt(
              self.pal_during_edit,
              get_pal_pos(_pi),
              PAL_CHAR_PER_PAL,
              get_random_palette2(-1),
            )
          }
          self.pal_during_edit = change_pal(self.pal_during_edit)
          break
        }
        break
      }

      if (keyboard_check_pressed(self.PalEdit_ViewColorInfo_KEY))
        self.PalEdit_ViewColorInfo_enabled = !self.PalEdit_ViewColorInfo_enabled

      PaletteEditor_update_cursor(self)
      break
    }

    case state_EDIT1B: {
      // Choose a new color for the palette color
      if (self.timer) break
      if (_Input_ViewOld_HELD) {
        if (p.pal_rm_curr !== self.pal_before_edit_color) change_pal(self.pal_before_edit_color)
        break
      }
      if (p.pal_rm_curr !== self.pal_during_edit) change_pal(self.pal_during_edit)

      if (_Input_CANCEL) {
        self.pal_during_edit = change_pal(self.pal_before_edit_color)
        self.timer = self.DELAY1_DUR
        self.state = state_EDIT1A
        break
      }
      if (_Input_COLOR_SELECTED) {
        if (self.pal_before_edit_color !== p.pal_rm_new) self.dl_hist_sess.add(p.pal_rm_new)
        self.timer = self.DELAY2_DUR
        self.state = state_EDIT1A
        break // **Selecting a palette color to edit gets priority.
      }

      PaletteEditor_update_cursor(self)
      const _color = PaletteEditor_get_cursor_color(self, false) // color grid cursor color
      if (_color !== PaletteEditor_get_cursor_color(self, true)) {
        const _POS = get_pal_col_pos(cursorPi(self), PAL_BASE_COLOR_ORDER.charAt(self.PalEdit_Cursor_row))
        self.pal_during_edit = change_pal(
          strReplaceAt(self.pal_during_edit, _POS, PAL_CHAR_PER_COLOR, color_str(_color)),
        )
      }
      break
    }

    case state_BGR_COLOR: {
      // Choose a new color for the background
      if (self.timer) break
      if (input.Pause_pressed) {
        // CONFIRM
        setBgr(PaletteEditor_get_cursor_color(self, false))
        g.gui_state = g.gui_state_NONE
        self.timer = self.DELAY1_DUR
        self.state = state_IDLE
      }
      if (_Input_CANCEL || _EDIT_REQUESTED_BGR) {
        // CANCEL
        setBgr(self.BgrColor_before_edit)
        g.gui_state = g.gui_state_NONE
        self.timer = self.DELAY1_DUR
        self.state = state_IDLE
        break
      }
      if (_Input_ViewOld_HELD) {
        setBgr(self.BgrColor_before_edit)
        break
      }
      if (_Input_Randomize_PRES) {
        const _RAND = Math.floor(Math.random() * 100)
        if (_RAND < 10) setBgr(get_random_color(true, 0))
        else if (_RAND < 40) setBgr(get_random_color(true, 1))
        else setBgr(get_random_color(true, 2))
      } else if (_Input_COLOR_SELECTED) {
        setBgr(PaletteEditor_get_cursor_color(self, false))
        break
      } else {
        PaletteEditor_update_cursor(self)
        setBgr(PaletteEditor_get_cursor_color(self, false))
      }
      break
    }
  }

  PaletteEditor_udp(self)
}

function setBgr(color: number): void {
  p.BackgroundColor_scene = color // `global.BackgroundColor_scene`
  set_background_color(color)
}

function cursorPi(self: PaletteEditor): number {
  return Number(
    val(self.PalEdit_dm.get(STR_Palette + hex_str(self.PalEdit_Cursor_clm + 1) + STR_Palette + STR_Index)),
  )
}

/** `PaletteEditor_udp()` — per-frame layout (cursor position, palette colour cache, info block). */
export function PaletteEditor_udp(self: PaletteEditor): void {
  const _XL0 = viewXL()
  const _YT0 = viewYT()
  self.gui_xl = _XL0 + self.gui_XLOFF
  self.gui_yt = _YT0 + self.gui_YTOFF

  if (!p.palette_image.width) self.PalView_enabled = false
  if (self.PalView_enabled) {
    self.PalView_xl = self.gui_xl
    self.PalView_yt = self.gui_yt
  }

  self.PalEdit_xl = _XL0 + self.PalEdit_X_BASE
  self.PalEdit_yt = self.gui_yt - self.PalEdit_Outline_W
  self.ColorGrid_xl = _XL0 + self.ColorGrid_X_BASE
  self.ColorGrid_yt = self.gui_yt - self.ColorGrid_Outline_W

  const editing = self.state === state_EDIT1A || self.state === state_EDIT1B || self.state === state_BGR_COLOR
  if (editing) {
    if (self.state === state_EDIT1B || self.state === state_BGR_COLOR) {
      // the cursor is only on the color grid in these states
      self.Cursor_xl =
        self.ColorGrid_xl +
        self.ColorGrid_Outline_W +
        self.ColorGrid_Cursor_clm * self.ColorGrid_SCALE +
        (self.ColorGrid_SCALE >> 1) -
        (self.Cursor_W >> 1)
      self.Cursor_yt =
        self.ColorGrid_yt +
        self.ColorGrid_Outline_W +
        self.ColorGrid_Cursor_row * self.ColorGrid_SCALE +
        (self.ColorGrid_SCALE >> 1) -
        (self.Cursor_H >> 1)
    } else {
      self.Cursor_xl =
        self.gui_xl +
        Number(val(self.PalEdit_dm.get(STR_Palette + hex_str(self.PalEdit_Cursor_clm + 1) + dk_XL))) +
        (self.PalEdit_SCALE >> 1) -
        (self.Cursor_W >> 1)
      self.Cursor_yt =
        self.gui_yt +
        self.PalEdit_Cursor_row * self.PalEdit_SCALE +
        (self.PalEdit_SCALE >> 1) -
        (self.Cursor_H >> 1)
    }
    self.Cursor_can_draw = !!(g.counter0 & 0x8)

    if (self.state === state_EDIT1A || self.state === state_EDIT1B) {
      for (let _i = 0; _i < self.PalEdit_PAL_COUNT; _i++) {
        const _pi = Number(val(self.PalEdit_dm.get(STR_Palette + hex_str(_i + 1) + STR_Palette + STR_Index)))
        for (let _j = 0; _j < PAL_BASE_COLOR_ORDER.length; _j++) {
          const _dk = STR_Palette + hex_str(_i + 1) + STR_Color + hex_str(_j + 1)
          const _color = get_pal_color(p.pal_rm_new, _pi, PAL_BASE_COLOR_ORDER.charAt(_j))
          self.PalEdit_dm.set(_dk, _color)
          self.PalEdit_dm.set(`${_dk}_Tinted`, merge_colour(_color, c_black, 0.7))
          self.PalEdit_dm.set(
            `${_dk}_UseTinted`,
            self.state === state_EDIT1B && (self.PalEdit_Cursor_clm !== _i || self.PalEdit_Cursor_row !== _j),
          )
          self.PalEdit_dm.set(
            `${_dk}_Editing`,
            self.state === state_EDIT1B && self.PalEdit_Cursor_clm === _i && self.PalEdit_Cursor_row === _j,
          )
        }
      }
    }
  }

  self.Info1_can_draw = false
  if (editing) {
    self.Info1Area_xl = _XL0 + self.Info1Area_X_BASE
    self.Info1Area_yt = _YT0 + self.Info1Area_Y_BASE
    let _yt = self.Info1Area_yt + self.Info1_PAD2
    for (const r of self.Info1_rows) {
      if (!r.states.includes(self.state)) continue
      self.Info1_can_draw = true
      _yt += self.Info1_DIST1
    }
    if (self.Info1_can_draw) self.Info1Area_h = _yt - self.Info1Area_yt
  }
}

/** GM `merge_colour(c1, c2, amount)` — the GML only ever darkens toward black here. */
function merge_colour(c1: number, c2: number, amount: number): number {
  const mix = (s: number) => {
    const a = (c1 >> s) & 0xff
    const b = (c2 >> s) & 0xff
    return Math.round(a + (b - a) * amount) & 0xff
  }
  return (mix(16) << 16) | (mix(8) << 8) | mix(0)
}

/** `PaletteEditor_Draw()` */
export function PaletteEditor_Draw(self: PaletteEditor): void {
  const depthCopy = drawState.depth
  drawState.depth = self.depth
  try {
    if (self.PalView_enabled) {
      PaletteEditor_draw_PalView(self)
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
    if (self.state !== state_EDIT1A && self.state !== state_EDIT1B && self.state !== state_BGR_COLOR) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!

    // Editor palette column ------------------------------------------------
    let _outline_xl = 0
    let _outline_yt = 0
    if (self.state === state_EDIT1A || self.state === state_EDIT1B) {
      // group outline (was PalEdit_Outline_surf)
      const _w1 = self.PalEdit_Outline_W
      const _h = self.PalEdit_PALS_H + (_w1 << 1)
      for (let _i = 0; _i < self.PalEdit_group_count; _i++) {
        const _gx = Number(val(self.PalEdit_dm.get(STR_Group1 + hex_str(_i + 1) + dk_XL)))
        const _gw = Number(val(self.PalEdit_dm.get(STR_Group1 + hex_str(_i + 1) + STR_Width))) + (_w1 << 1)
        box(self.PalEdit_xl + _gx, self.PalEdit_yt, _gw, _h, c_white)
        box(self.PalEdit_xl + _gx + (_w1 >> 1), self.PalEdit_yt + (_w1 >> 1), _gw - _w1, _h - _w1, c_black)
      }
      for (let _i = 0; _i < self.PalEdit_PAL_COUNT; _i++) {
        const _dk1 = STR_Palette + hex_str(_i + 1)
        const _xl = self.PalEdit_xl + self.PalEdit_Outline_W + Number(val(self.PalEdit_dm.get(_dk1 + dk_XL)))
        for (let _j = 0; _j < PAL_BASE_COLOR_ORDER.length; _j++) {
          const _dk2 = _dk1 + STR_Color + hex_str(_j + 1)
          const _yt = self.PalEdit_yt + self.PalEdit_Outline_W + self.PalEdit_SCALE * _j
          if (self.PalEdit_dm.get(`${_dk2}_Editing`) === true) {
            _outline_xl = _xl - 2
            _outline_yt = _yt - 2
          }
          const tinted = self.PalEdit_dm.get(`${_dk2}_UseTinted`) === true
          const _color = Number(
            val(self.PalEdit_dm.get(tinted ? `${_dk2}_Tinted` : _dk2), p.C_GRN0 as number),
          )
          box(_xl, _yt, self.PalEdit_SCALE, self.PalEdit_SCALE, _color)
        }
      }
      // drawn last so the colour squares do not cover it
      if (_outline_xl) colorOutline(_outline_xl, _outline_yt, self.PalEdit_SCALE)
    }

    // Colour grid ------------------------------------------------------------
    if (self.state === state_EDIT1B || self.state === state_BGR_COLOR) {
      const _w1 = self.ColorGrid_Outline_W
      box(self.ColorGrid_xl, self.ColorGrid_yt, self.ColorGrid_W, self.ColorGrid_H, c_white)
      box(
        self.ColorGrid_xl + (_w1 >> 1),
        self.ColorGrid_yt + (_w1 >> 1),
        self.ColorGrid_W - _w1,
        self.ColorGrid_H - _w1,
        c_black,
      )
      const _w = self.ColorGrid_SCALE
      for (let _i = 0; _i < self.ColorGrid_ROWS; _i++) {
        for (let _j = 0; _j < self.ColorGrid_CLMS; _j++) {
          const _idx = self.ColorGrid_CLMS * _i + _j
          box(
            self.ColorGrid_xl + _w * _j + _w1,
            self.ColorGrid_yt + _w * _i + _w1,
            _w,
            _w,
            self.ColorGrid_dl_colors.get(_idx) as number,
          )
        }
      }
    }

    // Cursor -----------------------------------------------------------------
    if (self.Cursor_can_draw) {
      self.Cursor_can_draw = false
      PaletteEditor_draw_cursor(self, self.Cursor_xl, self.Cursor_yt)
    }

    // INFO: OLD COLOR / NEW COLOR --------------------------------------------
    const _PAD1 = 3
    const _H1 = self.Font1_H + (_PAD1 << 1)
    const _W2 = self.PalEdit_SCALE
    const _DIST1 = self.Font1_H * 2
    const _XL0 = self.PalEdit_xl + _PAD1
    let _yt1 = Math.max(self.PalEdit_yt + self.PalEdit_PALS_H, self.ColorGrid_yt + self.ColorGrid_H) + 0x4

    const infoLine = (text: string) => {
      draw_rect_(
        c_black,
        _XL0 - _PAD1,
        _yt1 - _PAD1,
        text.length * self.Font1_W + (_PAD1 << 1),
        _H1,
        self.gui_Background_ALPHA,
      )
      draw_text_(_XL0, _yt1, text, self.Font1_sprite)
    }
    if (self.state === state_EDIT1A || self.state === state_EDIT1B) {
      infoLine(
        String(val(self.PalEdit_dm.get(STR_Palette + hex_str(self.PalEdit_Cursor_clm + 1) + STR_Name), '?')),
      )
    }
    const swatch = (label: string, color: number) => {
      _yt1 += _DIST1
      const _text = `${label}  ${color_str(color)}`
      const _xl = _XL0 + label.length * self.Font1_W
      const _yt = _yt1 + (self.Font1_H >> 1) - (_W2 >> 1)
      infoLine(_text)
      colorOutline(_xl - self.PalEdit_Outline_W, _yt - self.PalEdit_Outline_W, _W2)
      box(_xl, _yt, _W2, _W2, color)
    }
    swatch('OLD COLOR ', self.color_old)
    if (self.state === state_EDIT1B || self.state === state_BGR_COLOR) swatch('NEW COLOR ', self.color_new)

    // INSTRUCTIONS -----------------------------------------------------------
    if (self.Info1_can_draw) {
      draw_rect_(
        c_black,
        self.Info1Area_xl,
        self.Info1Area_yt,
        self.Info1Area_W,
        self.Info1Area_h,
        self.gui_Background_ALPHA,
      )
      let _y = self.Info1Area_yt + self.Info1_PAD2 + 1
      for (const r of self.Info1_rows) {
        if (!r.states.includes(self.state)) continue
        draw_text_(self.Info1Area_xl + self.Info1_PAD2 + 2, _y, r.text, self.Font1_sprite)
        _y += self.Info1_DIST1
      }
    }

    // COLOR INFO (hold/toggle 'C') -------------------------------------------
    if (self.state === state_EDIT1A && self.PalEdit_ViewColorInfo_enabled) {
      const _AREA_XL0 = self.PalEdit_xl
      const _AREA_YT0 =
        Math.max(self.PalEdit_yt + self.PalEdit_PALS_H, self.ColorGrid_yt + self.ColorGrid_H) +
        4 +
        (_DIST1 << 2)
      const _TEXT_XL0 = _AREA_XL0 + (_W2 + (self.PalEdit_Outline_W << 1)) + self.Font1_W
      const _PI = cursorPi(self)
      for (let _i = 0; _i < PAL_BASE_COLOR_ORDER.length; _i++) {
        const _CH = PAL_BASE_COLOR_ORDER.charAt(_i)
        const _color = get_pal_color(self.pal_during_edit, _PI, _CH)
        const _yt = _AREA_YT0 + self.Info1_DIST1 * _i
        colorOutline(_AREA_XL0, _yt, _W2)
        box(_AREA_XL0 + self.PalEdit_Outline_W, _yt + self.PalEdit_Outline_W, _W2, _W2, _color)
        const _text =
          `${_CH}: ${color_str(_color)}.` +
          ` H-${hex_str(colour_get_hue(_color))}` +
          ` S-${hex_str(colour_get_saturation(_color))}` +
          ` L-${hex_str(colour_get_value(_color))}` +
          ` B-${hex_str(get_color_brightness(_color))}`
        draw_text_(
          _TEXT_XL0,
          _yt + self.PalEdit_Outline_W + (_W2 >> 1) - (self.Font1_H >> 1),
          _text,
          self.Font1_sprite,
        )
      }
    }
  } finally {
    drawState.depth = depthCopy
  }
}

/** `PaletteEditor_draw_cursor(XL, YT)` — the 2px orange ring (was `Cursor_surf`). */
export function PaletteEditor_draw_cursor(self: PaletteEditor, XL: number, YT: number): void {
  draw_rect_(c_black, XL, YT, self.Cursor_W, self.Cursor_H, 1, true)
  draw_rect_(self.Cursor_COLOR, XL + 1, YT + 1, self.Cursor_W - 2, self.Cursor_H - 2, 1, true)
}

/**
 * `PaletteEditor_draw_PalView()` — the "show every palette" overlay ('P'). ZALiA blitted slices of the
 * palette sprite; here the same grid is drawn from the current palette string.
 */
export function PaletteEditor_draw_PalView(self: PaletteEditor): void {
  const S = self.PalView_SCALE1
  const _COUNT = p.palette_image.width
  const rows = p.palette_image.palettes
  for (let _pi = 0; _pi < _COUNT; _pi++) {
    const col = rows[_pi]
    if (!col) continue
    for (let _c = 0; _c < col.length; _c++) {
      // palette_image stores RGB; draw commands carry GM BGR, so swap back
      const rgb = col[_c] as number
      const bgr = ((rgb & 0xff) << 16) | (rgb & 0xff00) | ((rgb >> 16) & 0xff)
      box(self.PalView_xl + _pi * S, self.PalView_yt + _c * S, S, S, bgr)
    }
  }
}

function box(x: number, y: number, w: number, h: number, color: number): void {
  draw_sprite_(SPR_1x1, 0, x, y, -1, w, h, color)
}

/** The 2px black-on-white ring ZALiA cached in `ColorOutline1_surf`. */
function colorOutline(x: number, y: number, size: number): void {
  const OUT = 2
  draw_rect_(c_white, x, y, size + (OUT << 1), size + (OUT << 1), 1, true)
  draw_rect_(c_black, x + 1, y + 1, size + OUT, size + OUT, 1, true)
}
