// Ported from ZALiA scripts: NextLifeScreen_Create, NextLifeScreen_Step, NextLifeScreen_Draw (generated by rooms/_port/convert.py, then hand-finished).
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML state, typed progressively

import { SAVE_NAME_CHAR_LIMIT } from '@z2/data'
import { Instance } from '../../runtime/instance'
import { f, G, g, p } from '../../runtime/world'
import { string, string_length, string_repeat, withInstance } from '../Game/gm'
import { update_change_room_1a } from '../Game/update_change_room_1a'
import { set_background_color } from '../graphics/index'
import { notPorted } from '../pending'
import { viewXC, viewYC } from '../view/camera'
import { draw_pc_skin } from './deps'
import { draw_text_ } from './draw'
import { gmb } from './gmExtra'
import { roomName } from './roomChange'

export class NextLifeScreen extends Instance {
  readonly objectName = 'NextLifeScreen'
  ChangeRoom_timer: any = undefined
  INFO_X: any = undefined
  INFO_Y: any = undefined
  LINK_X: any = undefined
  LINK_Y: any = undefined
  LIVES_X: any = undefined
  ROOM_CHANGE_CUE: any = undefined
  SHOW_INFO_CUE: any = undefined
  SHOW_LINK_CUE: any = undefined
  TIMES_SYMBOL_X: any = undefined
  save_name: any = undefined
  constructor() {
    super()
    NextLifeScreen_Create(this)
  }
  step(): void {
    NextLifeScreen_Step(this)
  }
  draw(): void {
    NextLifeScreen_Draw(this)
  }
}

/** GML: NextLifeScreen_Create(self) */
export function NextLifeScreen_Create(self: NextLifeScreen) {
  self.x = viewXC() // centered
  self.y = viewYC() // centered
  // x  = viewXC() - VIEW_W_OG_;  // centered
  // y  = viewYC() - VIEW_H_OG_; // centered
  // x  = viewXC() - (256>>1); // centered
  // y  = viewYC() - (224>>1); // centered
  // y  = viewYB() -  224; // aligned to bottom
  g.counter1 = 2
  self.SHOW_INFO_CUE = 5
  self.SHOW_LINK_CUE = 6
  self.ROOM_CHANGE_CUE = 0x79 // $79 == 121
  self.save_name = f.dl_save_names.get(f.file_num - 1)
  self.save_name += string_repeat('.', SAVE_NAME_CHAR_LIMIT - string_length(self.save_name))
  // save_name = f.save_name;
  // var _dotsCount = f.SAVE_NAME_CHAR_LIMIT - string_length(f.save_name);
  // for (var i = 0; i < _dotsCount; i++) save_name += ".";
  // // save_name += "    ";
  // // save_name += string(lives);
  self.INFO_X = self.x - (0x0b << 3)
  self.INFO_Y = self.y - (0x03 << 3)
  // INFO_X = x + ($05<<3);
  // INFO_Y = y + ($0B<<3);
  self.TIMES_SYMBOL_X = self.x + (0x03 << 3) // $98 = 152
  self.LIVES_X = self.TIMES_SYMBOL_X + (0x01 << 3)
  self.LINK_X = self.x + (0x00 << 3)
  self.LINK_Y = self.y - (0x05 << 3) + 1
  //TIMES_SYMBOL_SPR = spr_Times_symbol;
}

/** GML: NextLifeScreen_Step(self) */
export function NextLifeScreen_Step(self: NextLifeScreen) {
  // Triggers update_change_room() to change the room
  // with(g)
  if (g.counter1 !== self.ROOM_CHANGE_CUE) return
  g.ChangeRoom_timer = g.ChangeRoom_ENTER_DURATION1
  g.ChangeRoom_timer++ // because this frame will decrement 1
  update_change_room_1a()
}

/** GML: NextLifeScreen_Draw(self) */
export function NextLifeScreen_Draw(self: NextLifeScreen) {
  set_background_color(p.C_BLK1)
  if (g.counter1 >= self.SHOW_INFO_CUE) {
    draw_text_(self.INFO_X, self.INFO_Y, self.save_name)
    draw_text_(self.LIVES_X, self.INFO_Y, string(f.lives))
    draw_text_(self.TIMES_SYMBOL_X, self.INFO_Y, '*', -1, G.PI_GUI1)
    //draw_sprite_(TIMES_SYMBOL_SPR,0, TIMES_SYMBOL_X, INFO_Y, get_pi(PI_GUI_1));
  }
  if (g.counter1 >= self.SHOW_LINK_CUE) {
    draw_pc_skin(self.LINK_X + 0x08, self.LINK_Y + 0x10, 1, 1, G.pc.behavior_IDLE, false, -1, -1, G.PI_PC1)
  }
}
