/**
 * ZALiA `math` IDE folder. The 6502 helpers (`adc`, `sbc`, `rol`, `ror`, `byte`, `byte_to_int`,
 * `byte_negate`, `abs8b`, `sign8b`, `dir8b`, `bitCount`, `bit1st`, `isVal`) live in `nes/math8.ts` and
 * are re-exported here under both their GML and camelCase names.
 */
import {
  abs8b,
  adc,
  bit1st,
  bitCount,
  byte,
  byteNegate,
  byteToInt,
  dir8b,
  isVal,
  rol,
  ror,
  sbc,
  sign8b,
} from '../../nes/math8'

export { abs8b, adc, bit1st, bitCount, byte, dir8b, isVal, rol, ror, sbc, sign8b }
export const byte_to_int = byteToInt
export const byte_negate = byteNegate

/** `round_(real)` — round half away from zero (GML `round` is banker's-ish; ZALiA wanted this). */
export function round_(v: number): number {
  if (Math.abs(v % 1) === 0.5) return v > 0 ? Math.ceil(v) : Math.floor(v)
  return Math.round(v)
}

/** `round8(int)` — round an int to the nearest 8th. */
export function round8(v: number): number {
  return ((v >> 3) << 3) + ((v & 0x4) << 1)
}

/** `inRange(num, low, high)` — inclusive. */
export function inRange(num: number, low: number, high: number): boolean {
  return num >= low && num <= high
}

/** `bitNum(uint)` — 1-based bit number of the lowest set bit, 0 if none. */
export function bitNum(v: number): number {
  let x = v >>> 0
  if (x === 0) return 0
  let n = 1
  while (x > 0) {
    if (x & 1) return n
    x >>>= 1
    n++
  }
  return 0
}

/** `byte_dir(byte)` — -1 for a negative byte (bit 7 set), else 1. */
export function byte_dir(v: number): -1 | 1 {
  return v & 0x80 ? -1 : 1
}

/**
 * `byte_bit_dir(hspd, vspd)` — direction nybble from byte speeds:
 * hspd $00→0, $01-$7F→$1 (right), $80-$FF→$2 (left); vspd $00→0, $01-$7F→$4 (down), $80-$FF→$8 (up).
 */
export function byte_bit_dir(hspd: number, vspd: number): number {
  return ((1 << +(hspd >= 0x80)) * +!!hspd) | ((4 << +(vspd >= 0x80)) * +!!vspd)
}

/** `bit_dir(nybble)` — $01(right)|$04(down) → +1, $02(left)|$08(up) → -1, else 0. */
export function bit_dir(nybble: number): -1 | 0 | 1 {
  if (nybble & 0x5) return 1
  if (nybble & 0xa) return -1
  return 0
}

/** `sign_(number)` — like sign() but returns -1 instead of 0. Booleans map true→1, false→-1. */
export function sign_(v: number | boolean): -1 | 1 {
  if (typeof v === 'boolean') return v ? 1 : -1
  return v > 0 ? 1 : -1
}

/**
 * GML 1.4 truthiness: a real is true only when > 0.5. Matters for ±1 direction values
 * (`if (facing_dir)` means "facing right"; `!facing_dir` means "facing left").
 */
export function gmBool(v: number | boolean | undefined | null): boolean {
  if (typeof v === 'boolean') return v
  return v !== undefined && v !== null && v > 0.5
}

/** `dir8b(direction)` with GML truthiness: +1 (right) → 1, 0 or -1 (left) → 2. Shadows nes/math8's. */
export function dir8b_(direction: number): 1 | 2 {
  return gmBool(direction) ? 1 : 2
}
