/** Daira (ZALiA object `DairA`, parent `Enemy`; the axe-throwing lizard-man, v1 orange, v2 red). `Daira_init2/update/udp/draw.gml`. */
import { ITM_SHLD, MAX_GOC1, SPL_RFLC, UIDX_NULL } from '@z2/data'
import { byte, gmBool } from '../../../../../../nes/math8'
import { f, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { GOB_sword_collision_1a, GOB_sword_collision_2a } from '../../../../../collision/gob'
import { ocsH3 } from '../../../../../collision/ocs'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { inRange } from '../../../../../math/index'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { draw_sprite_ } from '../../../../go/draw'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2, update_EF11 } from '../../../GameObjectB'
import { Enemy_update_1, projOf } from '../ache/_shared'

export class DairA extends Enemy {
  readonly objectName = 'DairA' as const
  VSPD_GRAV = 2
  armXScale = -1
  armYScale = -1
  Arm_xoff = 16
  Arm_yoff = -8
  Arm_sprite: string | 0 = 0
  SwordHB_XOFF = 16
  SwordHB_YOFF = 11
  SwordHB_W = 14
  SwordHB_H = 1
  attack_dist = 0x1e
  frwd_bkwd = 1
}

/** `Daira_init2()` */
export function Daira_init2(self: DairA): void {
  self.projectile_OBJ = 'Axe'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.dl_sprites?.set(1, 'spr_Daira2') // legs open
  self.dl_sprites?.set(0, 'spr_Daira1') // legs closed
  self.armXScale = -1
  self.armYScale = -1
  self.Arm_xoff = 16
  self.Arm_yoff = -8
  self.Arm_sprite = 0
  // sword hb
  self.SwordHB_XOFF = 16 + g.HB_ADJ_X
  self.SwordHB_YOFF = 11 + g.HB_ADJ_Y
  self.SwordHB_W = 14 + g.HB_ADJ_W
  self.SwordHB_H = 1 + g.HB_ADJ_H
  self.SwordHB_xoff = self.SwordHB_XOFF * self.facing_dir
  self.SwordHB_yoff = self.SwordHB_YOFF
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
}

/** `Daira_update()` — 9A15 */
export function Daira_update(self: DairA): void {
  if (self.ver === 2)
    self.attack_dist = 0x37 // Daira red
  else self.attack_dist = 0x1e // Daira orange
  // 9A15
  if (gmBool(self.behavior) && !gmBool(self.timer)) {
    self.behavior++
    // 9AE5
    if (self.behavior === 2) {
      update_EF11(self)
      // 9AEC: JSR E558,   E563: JSR E5F3
      const _C1 = !(g.spells_active & SPL_RFLC) && !(f.items & ITM_SHLD)
      if (_C1 || !GOB_sword_collision_2a(self)) {
        // handles PC SHIELD collision check & reaction. E579: JSR E5F3
        GOB_sword_collision_1a(self) // handles PC BODY collision check & reaction
      }
      // 9AEF, DBCE
      if (self.ver === 2 && ocsH3(self) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
        // Daira red; all width must be in ocs area
        if (inRange(self.x, g.view_xl_og, g.view_xr_og) || Math.abs(self.x - pc().x) < self.attack_dist) {
          GOC1_create(self.xl, self.yt, self.facing_dir, projOf(self), self.projectile_ver)
        }
      }
    }
    if (self.behavior >= 3 + +(self.ver === 1)) {
      // 3: Daira red, 4: Daira orange
      self.behavior = 0
    } else {
      // 9AFF
      self.timer = 5
    }
  }
  // 9A18
  GO_update_cs(self)
  GOB_update_2(self)
  // 9A2C
  Enemy_update_1(self)
}

/** `Daira_udp()` — 9D69 */
export function Daira_udp(self: DairA): void {
  self.can_draw_self = true
  if (self.cs & 0x4 && gmBool(self.hspd)) {
    let _val = 4
    if (byte(self.hspd + 8) < 0xb) _val = 8
    self.sprite = (g.counter1 & _val ? self.dl_sprites?.get(1) : self.dl_sprites?.get(0)) as string
  } else self.sprite = self.dl_sprites?.get(0) as string // legs closed
  // 9DA6
  self.Arm_sprite = 0
  if (gmBool(self.behavior)) {
    if (self.behavior === 3) {
      // ver1 (Orange). Only draws axe
      self.armXScale = 1
      self.armYScale = 1
      self.Arm_xoff = 9
      self.Arm_yoff = 9
    } else {
      const _flip = self.behavior === 2 ? -1 : 1
      const _xOff = self.behavior === 2 ? 0 : 3 * _flip
      self.armXScale = -1 * _flip
      self.armYScale = -1 * _flip
      self.Arm_xoff = -16 * _flip
      self.Arm_xoff += _xOff
      self.Arm_yoff = -8 + +(self.behavior === 2)
    }
    self.armXScale *= self.facing_dir
    self.Arm_xoff *= self.facing_dir
    self.Arm_sprite = self.behavior < 3 ? 'spr_Daira_Arm' : 'spr_Axe2'
  }
}

/** `Daira_draw()` */
export function Daira_draw(self: DairA): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  if (self.Arm_sprite)
    draw_sprite_(
      self.Arm_sprite,
      0,
      self.drawX + self.Arm_xoff,
      self.drawY + self.Arm_yoff,
      -1,
      self.armXScale,
      self.armYScale,
      self.depth,
    )
  if (self.sprite)
    draw_sprite_(self.sprite, 0, self.drawX, self.drawY, -1, self.xScale, self.yScale, self.depth)
  pal_swap_reset()
}

registerObject('DairA', DairA)
registerScripts({ Daira_init2, Daira_update, Daira_udp, Daira_draw })
