/**
 * `PC_update_1()` and its helpers `PC_update_1a..1e` — the player's main per-frame update (D4F3: JSR 903A).
 * `PC_update_hitboxes` wraps `collision/hitbox.ts PC_update_hitboxes_1a(downHeld)` with the PC's down flag.
 */
import {
  BIT_ATK3,
  BIT_ATK4,
  CUCCO_PLACEMENT_SPR,
  ITM_FRY1,
  ITM_SWRD,
  PC_LOCK_ALL,
  PC_PLACEMENT_SPR,
  SPL_FARY,
  TID_BREAK1,
  TID_BREAK2,
  TID_BREAK3,
  TID_BREAK4,
  TILE_DEPTHS_PAD,
} from '@z2/data'
import { gmBool, isVal } from '../../../nes/math8'
import { NOONE } from '../../../runtime/instance'
import { f, G, g, input, world } from '../../../runtime/world'
import { updateCSPoints } from '../../collision/cs'
import { viewXL, viewXR, viewYB, viewYT } from '../../collision/env'
import { PC_update_body_offsets, PC_update_hitboxes_1a, update_body_hb } from '../../collision/hitbox'
import { ocsH3 } from '../../collision/ocs'
import { collide_solid_grid } from '../../collision/solid'
import { cast_spell } from '../../Game/cast_spell'
import { bit_dir, byte_dir, sign_ } from '../../math/index'
import { ease_in_out } from '../../other/index'
import { aud_play_fairy1 } from '../../sound/play'
import { cam_xl_min, cam_xr_max, cam_yb_max, cam_yt_min } from '../../view/camera'
import { Boss } from '../classes'
import { set_xy, updateY } from '../go/movement'
import { GO_set_sprite_index } from '../go/sprite'
import {
  PC_update_attack_1,
  PC_update_attack_2,
  PC_update_hold_item,
  PC_update_stab_frenzy_1,
  walk_pc_to_x,
} from './attack'
import { PC_cucco_fury_update } from './cucco'
import { PC_set_behavior, pc_is_cucco, pc_is_fairy } from './form'
import type { Lonk } from './Lonk'
import { PC_update_horizontal, PC_update_vertical, PC_update_walk } from './movement'
import { instanceNamed, pcInput } from './pc'
import { PC_spawn } from './spawn'
import { PC_update_1b_ } from './update1b'
import { PC_update_1c_impl } from './update1c'
import { PC_update_2a } from './update2'

/** `PC_update_hitboxes_1a()` as the PC calls it (body, shield, sword). */
export function PC_update_hitboxes(_self: Lonk): void {
  PC_update_hitboxes_1a(pcInput.dHeld)
}

export function PC_update_1(self: Lonk): void {
  self.x_prev = self.x
  self.y_prev = self.y
  self.x_scale_prev = self.xScale
  self.SwordHB2_colliding = NOONE
  self.SwordHB2_collidable = false
  self.SwordHB2_can_draw = false
  self.is_fairy = pc_is_fairy()
  self.is_cucco = pc_is_cucco()
  // this is set when transforming back to human in a space not tall enough to fit
  if (self.TransformHumanClipCorrect_timer) {
    self.TransformHumanClipCorrect_timer--
    if (!self.TransformHumanClipCorrect_timer && !self.is_cucco) cast_spell(SPL_FARY)
  }
  PC_update_1a(self) // set properties specific to PC form(cucco, fairy, Lonk)
  self.hspd_impel = 0
  if (self.RescueFairy_sprite) aud_play_fairy1()
  // =========================  SPAWN  =============================== 903A
  if (self.state === self.state_SPAWN) {
    PC_spawn(self)
    return
  }
  // =========================  DROWN  =============================== OG state 2
  if (self.state === self.state_DROWN) {
    let _x = self.x
    let _y = self.y + 1
    // 93AC
    PC_set_behavior(self.behavior_DAMAGE)
    // 918E
    if (self.yt >= self.DrownLiquid_y + (0x2 << 3) || self.yt >= viewYB() - (0x3 << 3)) {
      if (f.items & ITM_FRY1 && f.hp) {
        const _X_PREV = self.x
        const _Y_PREV = self.y
        const _INV_DUR = 2
        const startRescue = (ex: number, ey: number) => {
          self.hspd = 0
          self.vspd = 0
          self.iframes_timer = _INV_DUR
          self.Rescue_x_start = _X_PREV
          self.Rescue_y_start = _Y_PREV
          self.Rescue_x_end = ex
          self.Rescue_y_end = ey
          self.Rescue_x_time = 0
          self.Rescue_y_time = 0
          set_xy(self, self.Rescue_x_start, self.Rescue_y_start)
          self.state = self.state_RESCUE
        }
        const solidInst = self.RescueDropOff_solid_inst
        if (solidInst !== NOONE) {
          if (solidInst.exists) {
            _x = solidInst.xl + ((self.RescueDropOff_rc & 0xff) << 3)
            _x = Math.min(Math.max(_x, solidInst.xl + 8), solidInst.xr - 8)
            _y = solidInst.yt - self.hh_
            startRescue(_x, _y)
            return
          }
        } else if (self.RescueDropOff_rc + 1) {
          _x = (self.RescueDropOff_rc & 0xff) << 3
          _x = (_x >> 3) << 3
          _y = (((self.RescueDropOff_rc >> 8) & 0xff) << 3) - self.hh_
          _y = (_y >> 3) << 3
          set_xy(self, _x, _y)
          const elev = self.RescueDropOff_elevator
          if (elev?.exists) {
            set_xy(elev, elev.x, self.y)
            set_xy(self, elev.x, self.y)
          } else {
            if (!collide_solid_grid(self.x - 7, self.yb)) set_xy(self, self.x + 8, self.y)
            if (!collide_solid_grid(self.x + 7, self.yb)) set_xy(self, self.x - 8, self.y)
            if (collide_solid_grid(self.x - 7, self.yt + self.csLft2_yoff)) set_xy(self, self.x + 8, self.y)
            if (collide_solid_grid(self.x + 7, self.yt + self.csRgt2_yoff)) set_xy(self, self.x - 8, self.y)
          }
          self.RescueDropOff_rc = ((self.yb >> 3) << 8) | (self.x >> 3)
          startRescue(self.x, self.y)
          return
        } else {
          // go to spawn
          if (g.view_lock & 0x3) _x = Math.min(Math.max(self.spawn_xl, viewXL()), viewXR() - self.ww)
          else _x = self.spawn_xl
          _x = (_x >> 3) << 3
          _x += self.sprite_index_xoff
          if (g.view_lock & 0xc)
            _y = Math.min(Math.max(self.spawn_yt, viewYT()), viewYB() - self.hh - (0x01 << 3))
          else _y = self.spawn_yt
          _y = (_y >> 3) << 3
          _y += self.sprite_index_yoff
          startRescue(_x, _y)
          return
        }
      } else {
        self.is_dead = true
      }
    }
    // 91A1: JMP EBF0
    PC_update_2a(self) // GO_update_cam_vars(), usd_pc_1a(), update_swrdXY()
    PC_update_1e(self) // update g.lastX, g.lastY, g.lastXScale
    set_xy(self, _x, _y)
    return
  }
  // =========================  RESCUE  ===============================
  if (self.state === self.state_RESCUE) {
    const _X_PREV = self.x
    const _Y_PREV = self.y
    self.iframes_timer = 2
    const solidInst = self.RescueDropOff_solid_inst
    if (solidInst !== NOONE && solidInst.exists) {
      // coords are followed here because this could be a moving object/platform
      self.Rescue_x_end = solidInst.xl + ((self.RescueDropOff_rc & 0xff) << 3)
      self.Rescue_x_end = Math.min(Math.max(self.Rescue_x_end, solidInst.xl + 8), solidInst.xr - 8)
      self.Rescue_y_end = solidInst.yt - self.hh_
    }
    self.Rescue_x_dist = self.Rescue_x_end - self.Rescue_x_start
    self.Rescue_y_dist = self.Rescue_y_end - self.Rescue_y_start
    const clampDur = (d: number) =>
      Math.min(
        Math.max(Math.floor(Math.abs(d) / self.Rescue_DIST2), self.Rescue_duration_MIN),
        self.Rescue_duration_MAX,
      )
    self.Rescue_x_duration = clampDur(self.Rescue_x_dist)
    self.Rescue_y_duration = clampDur(self.Rescue_y_dist)
    self.Rescue_x_duration = Math.max(self.Rescue_x_duration, self.Rescue_y_duration)
    self.Rescue_y_duration = Math.floor(self.Rescue_x_duration * 0.9)
    if (self.Rescue_x_time < self.Rescue_x_duration || self.Rescue_y_time < self.Rescue_y_duration) {
      if (self.Rescue_x_time < self.Rescue_x_duration) {
        const _X = Math.floor(
          ease_in_out(self.Rescue_x_start, self.Rescue_x_dist, self.Rescue_x_time, self.Rescue_x_duration),
        )
        set_xy(self, _X, self.y)
        self.x_change += self.x - _X_PREV
        self.Rescue_x_time++
      }
      if (self.Rescue_y_time < self.Rescue_y_duration) {
        const _Y = Math.floor(
          ease_in_out(self.Rescue_y_start, self.Rescue_y_dist, self.Rescue_y_time, self.Rescue_y_duration),
        )
        set_xy(self, self.x, _Y)
        self.y_change += self.y - _Y_PREV
        self.Rescue_y_time++
      }
    } else {
      set_xy(self, self.Rescue_x_end, self.Rescue_y_end)
      self.x_change += self.x - _X_PREV
      self.y_change += self.y - _Y_PREV
      self.Rescue_x_start = 0
      self.Rescue_y_start = 0
      self.Rescue_x_end = 0
      self.Rescue_y_end = 0
      self.Rescue_x_dist = 0
      self.Rescue_y_dist = 0
      self.Rescue_x_duration = 0
      self.Rescue_y_duration = 0
      self.Rescue_x_time = 0
      self.Rescue_y_time = 0
      PC_set_behavior(self.behavior_IDLE)
      self.state = self.state_NORMAL
    }
    return
  }
  // -----------------------------------------------------------------------------------------
  if (self.state !== self.state_NORMAL) return
  // --------------------------  state_NORMAL  -----------------------------------
  // =========================  PIPE SINK  ===========================
  if (self.pipe_sink_timer) {
    self.pipe_sink_timer--
    if (self.pipe_sink_timer) {
      set_xy(self, self.x, self.y + 1)
      PC_set_behavior(self.behavior_CROUCH)
      self.depth = Number(g.TILE_DEPTH_MAX_BACK) + (TILE_DEPTHS_PAD >> 1)
      // 92DE: JMP EBF0
      PC_update_2a(self) // GO_update_cam_vars(), usd_pc_1a()
    }
    PC_update_hitboxes(self) // body, shield, sword
    PC_update_1e(self) // update g.lastX, g.lastY, g.lastXScale
    return
  }
  // =========================  LOCKED  ===========================
  if (g.pc_lock === PC_LOCK_ALL) {
    if (self.WalkTo_active) walk_pc_to_x(self.WalkTo_x, self.WalkTo_hspd_max)
    // update hspd_dir, PC_update_cs(), if (cs3()) hspd=0, update cs, swamp walk, crumble bridge, drown, pushable, exiting
    PC_update_1d(self)
    PC_update_hitboxes(self) // body, shield, sword
    PC_update_1e(self) // g.lastX, g.lastY, g.lastXScale
    return
  }
  self.WalkTo_active = false
  // ------------------------  RESCUE DROP-OFF TRACKING  -----------------------------------------
  if (f.items & ITM_FRY1) {
    let _clm: number
    let _row: number
    const elev = self.colliding_elevator
    if (elev?.exists) {
      if (
        self.RescueDropOff_elevator !== elev ||
        !(self.RescueDropOff_rc + 1) ||
        (self.RescueDropOff_rc & 0xff) !== elev.x >> 3
      ) {
        _clm = Math.min(
          Math.max(elev.x >> 3, ((cam_xl_min() + self.ww_) >> 3) + 1),
          ((cam_xr_max() - self.ww_) >> 3) - 1,
        )
        _row = Math.min(Math.max(self.yb >> 3, ((cam_yt_min() + self.hh) >> 3) + 2), (cam_yb_max() >> 3) - 2)
        self.RescueDropOff_rc = (_row << 8) | _clm
      }
      self.RescueDropOff_elevator = elev
    } else {
      self.RescueDropOff_elevator = NOONE
      if (!self.ogr) {
        const _C1 = collide_solid_grid(self.csBtm1X, self.csBtm1Y)
        const _C2 = collide_solid_grid(self.csBtm2X, self.csBtm2Y)
        if (_C1 || _C2) {
          const B = g.dg_RmTile_Break_def
          const T = g.dg_RmTile_TempSolid
          const _CLMS1 = B.width
          const _ROWS1 = B.height
          const _CLMS2 = T.width
          const _ROWS2 = T.height
          _clm = self.csBtm1X >> 3
          _row = self.csBtm1Y >> 3
          const _clm2 = self.csBtm2X >> 3
          const _row2 = self.csBtm2Y >> 3
          const cl = (v: number, m: number) => Math.min(Math.max(v, 0), m)
          const isBreak = (v: unknown) =>
            isVal(Number(v ?? 0) & 0xff, TID_BREAK1, TID_BREAK2, TID_BREAK3, TID_BREAK4)
          if (
            !isBreak(B.get(cl(_clm, _CLMS1), cl(_row, _ROWS1))) &&
            !isBreak(B.get(cl(_clm2, _CLMS1), cl(_row2, _ROWS1))) &&
            !(Number(T.get(cl(_clm, _CLMS2), cl(_row, _ROWS2)) ?? 0) & 0xff) &&
            !(Number(T.get(cl(_clm2, _CLMS2), cl(_row2, _ROWS2)) ?? 0) & 0xff)
          ) {
            if (_C1 && _C2) _clm = self.x >> 3
            else if (_C1) _clm = self.csBtm1X >> 3
            else _clm = self.csBtm2X >> 3
            _clm = Math.min(
              Math.max(_clm, ((cam_xl_min() + self.ww_) >> 3) + 1),
              ((cam_xr_max() - self.ww_) >> 3) - 1,
            )
            _row = Math.min(
              Math.max(self.yb >> 3, ((cam_yt_min() + self.hh) >> 3) + 0),
              (cam_yb_max() >> 3) - 1,
            )
            self.RescueDropOff_rc = (_row << 8) | _clm
          }
          self.RescueDropOff_solid_inst = NOONE
        } else {
          const inst = self.cs_btm_inst
          if (inst?.exists && inst.solid_type) {
            self.RescueDropOff_solid_inst = inst
            _clm = Math.min(Math.max(self.x >> 3, (inst.xl >> 3) + 1), (inst.xr >> 3) - 1)
            _clm -= inst.xl >> 3
            _row = self.csBtm1Y >> 3
            self.RescueDropOff_rc = (_row << 8) | _clm
          }
        }
      }
    }
    if (g.view_lock_boss) {
      // if in boss battle
      const boss = [...world.instancesOf(Boss)][0] as
        | (Boss & { arena_x?: number; arena_xl?: number; arena_xr?: number })
        | undefined
      if (self.RescueDropOff_rc < 0) {
        _clm = g.rm_w_ >> 3
        _row = viewYT() + 0 // viewYC()>>3 below
        _row = (viewYT() + (viewYB() - viewYT()) / 2) >> 3
        if (boss?.arena_x !== undefined) _clm = boss.arena_x >> 3
      } else {
        _clm = self.RescueDropOff_rc & 0xff
        _row = (self.RescueDropOff_rc >> 8) & 0xff
      }
      if (boss?.arena_xl !== undefined && boss.arena_xr !== undefined)
        _clm = Math.min(
          Math.max(_clm, ((boss.arena_xl + self.ww_) >> 3) + 1),
          ((boss.arena_xr - self.ww_) >> 3) - 1,
        )
      _clm = Math.min(
        Math.max(_clm, ((cam_xl_min() + self.ww_) >> 3) + 1),
        ((cam_xr_max() - self.ww_) >> 3) - 1,
      )
      _row = Math.min(Math.max(_row, ((cam_yt_min() + self.hh) >> 3) + 0), (cam_yb_max() >> 3) - 1)
      self.RescueDropOff_rc = (_row << 8) | _clm
    }
  } else {
    self.RescueDropOff_rc = -1
    self.RescueDropOff_elevator = NOONE
    self.RescueDropOff_solid_inst = NOONE
  }
  // =========================  HOLD ITEM  =========================== MOD: moved from between FAIRY & STUNNED
  if (self.HoldItem_timer && !self.is_fairy) {
    if (gmBool(g.mod_SKIP_HOLD_ITEM)) self.HoldItem_timer = 0
    else {
      PC_update_hold_item(self)
      return
    }
  }
  // ===========================  CUCCO  =============================
  if (self.is_cucco && !g.EnterRoom_control_timer) {
    // 9379, 95B5
    readPcInput(self)
    PC_update_stab_frenzy_1(self)
    self.Cucco_crouching_state = 0
    const _C1 =
      pcInput.dHeld && // down is held
      !self.ogr && // is on ground
      !!(self.cs & 0x4) && // CS_BTM colliding w/ solid
      (!self.Disguise_enabled || G.Halloween1_enabled)
    const _C2 =
      !!(self.cs & 0x4) &&
      !!(self.cs & 0x8) && // Both CS_BTM && CS_TOP colliding w/ solid (Cucco is in 1 tile high space)
      (!self.Disguise_enabled || G.Halloween1_enabled)
    if (_C1 || _C2) self.hspd_max = g.DevDash_state === 2 ? self.Cucco_HSPD_MAX2_DASH : self.Cucco_HSPD_MAX2
    else self.hspd_max = g.DevDash_state === 2 ? self.Cucco_HSPD_MAX1_DASH : self.Cucco_HSPD_MAX1
    if (_C1 || _C2) self.cs_off_idx = self.Cucco_CS_OFF_IDX2
    self.Cucco_crouching_state = _C1 || _C2 ? 1 + ((_C1 && self.hspd) || _C2 ? 1 : 0) : 0 // 1,2
    if (self.stun_timer) {
      // 9370
      PC_update_vertical(self)
      // 9373: JSR 93A3
      if (!(self.cs & 0x3)) {
        PC_update_1b(self) // updateX()
        PC_update_walk(self)
      }
      PC_set_behavior(self.behavior_DAMAGE) // 93AC
      PC_update_1d(self) // 938A
      PC_update_hitboxes(self)
      PC_update_1e(self)
      self.StabFrenzy_charge_counter = 0
    } else {
      PC_update_attack_1(self) // 95DC. Start attack.
      PC_update_horizontal(self) // 93CD
      if (_C1 || _C2) PC_set_behavior(self.behavior_CROUCH)
      PC_update_vertical(self) // 9384 JSR: 94C5
      PC_update_attack_2(self) // 9387 JSR: 9483
      if (self.attack_phase > 2) self.attack_phase = 0
      PC_update_1d(self) // 938A
      PC_update_hitboxes(self)
      PC_cucco_fury_update(self)
      PC_update_1e(self)
    }
    return
  }
  // ===========================  FAIRY  ============================= 92F6
  if (self.is_fairy) {
    // 92FB
    aud_play_fairy1()
    pcInput.vHeld = input.heldV
    self.hspd = 0
    self.xScale = 1
    self.SwordHB_collidable = false
    self.HoldItem_timer = 0
    // 930A
    if (input.heldHV && !(input.heldHV & self.colliding_locked_door)) {
      // Stops fairy from moving through lock. 931E
      self.hspd_impel = bit_dir(input.heldH)
      self.vspd_impel = bit_dir(input.heldV)
      if (input.heldH) self.hspd_dir = self.hspd_impel
      if (input.heldV) self.vspd_dir = self.vspd_impel
      self.hspd = (self.HSPD_FAIRY * self.hspd_impel) & 0xff
      self.vspd = (self.VSPD_FAIRY * self.vspd_impel) & 0xff
      PC_update_1c(self) // update cs, swamp walk, crumble bridge, drown, pushable, exiting
      // 932C
      let _cs = self.cs
      if (self.y - 8 <= viewYT() && self.colliding_elevator?.exists) _cs |= 0x08 // CS_TOP
      if (!(_cs & input.held)) {
        // 933A: JSR 9610
        PC_update_1b(self) // updateX()
        if (!self.colliding_elevator?.exists) updateY(self)
      }
    }
    updateCSPoints(self) // MOD. So cs will be acurate and draw even when not moving
    self.BodyHB_can_draw = true
    PC_update_body_offsets(pcInput.dHeld)
    update_body_hb(self)
    PC_update_1e(self)
    return
  }
  // ===========================  STUNNED  ============================= 936B
  if (self.stun_timer) {
    PC_update_vertical(self) // 9370
    // 9373: JSR 93A3
    if (!(self.cs & 0x3)) {
      PC_update_1b(self) // 93A9: JSR 943A, 943A: JSR 9610
      PC_update_walk(self)
    }
    PC_set_behavior(self.behavior_DAMAGE) // 93AC
    PC_update_1d(self) // 938A
    PC_update_hitboxes(self)
    PC_update_1e(self)
    self.StabFrenzy_charge_counter = 0
    return
  }
  // ========================  ENTER ROOM WALK  ======================== 9381: JSR 93BC
  if (g.EnterRoom_control_timer) {
    if (!self.colliding_elevator?.exists) {
      // 93C1
      self.hspd = (0x10 * -sign_(self.x > g.rm_w_)) & 0xff
      self.hspd_impel = byte_dir(self.hspd)
      // 93CA: JMP 943A, 943A: JSR 9610
      if (!(self.cs & 0x3) || !ocsH3(self)) PC_update_1b(self) // updateX(). MOD
      PC_update_walk(self) // 943D
    }
    PC_update_vertical(self) // 9384 JSR: 94C5
    PC_update_1d(self) // 938A
    PC_update_hitboxes(self)
    PC_update_1e(self)
    return
  }
  // ========================  NORMAL  ================================ 9379, 95B5
  readPcInput(self)
  // 937E: JSR 959C
  if (self.attack_phase === 4) {
    // 4: drawback after stab
    let _INPUTS: number
    if (gmBool(g.mod_StabFrenzy) && self.StabFrenzy_charge_counter > 0x80 && input.Attack_held)
      _INPUTS = input.A | input.D
    else _INPUTS = input.A | input.R | input.L | input.D
    if (input.held & _INPUTS) {
      // 95A9
      self.attack_phase = 0
      if (!self.ogr) self.hspd = 0
    }
  }
  PC_update_stab_frenzy_1(self)
  PC_update_attack_1(self) // 95DC. Start attack.
  PC_update_horizontal(self) // 93CD
  PC_update_vertical(self) // 9384 JSR: 94C5
  PC_update_attack_2(self) // 9387 JSR: 9483
  PC_update_1d(self) // 938A
  PC_update_hitboxes(self) // body, shield, sword
  PC_update_1e(self) // update g.lastX, g.lastY, g.lastXScale
}

/** 9379, 95B5 — latch the frame's directional input the way the OG stored it. */
function readPcInput(self: Lonk): void {
  pcInput.hHeld = input.heldH // held right $1 or left $2
  pcInput.vHeld = input.heldV // held down  $4 or up   $8
  pcInput.cPres = input.pressedC // pressed b $40 and/or a $80
  pcInput.dHeld = input.Down_held !== 0 // 0: down NOT held, 1: down held
  if (pcInput.hHeld === input.R) self.xScale = 1
  else if (pcInput.hHeld === input.L) self.xScale = -1
}

/** `PC_update_1a()` — set properties specific to PC form (cucco, fairy, Lonk). */
export function PC_update_1a(self: Lonk): void {
  if (!self.is_cucco) self.Cucco_is_slowfalling_prev = 0
  else self.Cucco_is_slowfalling_prev = self.Cucco_is_slowfalling
  self.Cucco_is_slowfalling = 0
  const sword2 = (base: number) => {
    if (gmBool(g.mod_PCSword2) && f.items & ITM_SWRD) {
      switch (g.mod_PCSword2) {
        case 1:
          return base + 2
        case 2:
          return base + 3
        case 3:
          return base + 3 - (instanceNamed('ShadowLonk01') ? 1 : 0)
      }
    }
    return base
  }
  if (self.is_cucco) {
    self.DRAW_YOFF = 0
    if (self.sprite_index !== CUCCO_PLACEMENT_SPR) {
      GO_set_sprite_index(self, CUCCO_PLACEMENT_SPR)
      set_xy(self, self.x, self.y)
    }
    self.hspd_max = g.DevDash_state === 2 ? self.Cucco_HSPD_MAX1_DASH : self.Cucco_HSPD_MAX1
    self.cs_off_idx = self.Cucco_CS_OFF_IDX1
    self.BodyHB_idx = self.Cucco_BodyHB_IDX1 // 16x16 GO
    const _THRUST_D = (f.Cucco_skills & f.CuccoSkill_THRUST_D) * Math.sign(Number(g.CUCCO_CAN_THRUST_D))
    const _THRUST_U = (f.Cucco_skills & f.CuccoSkill_THRUST_U) * Math.sign(Number(g.CUCCO_CAN_THRUST_U))
    if ((_THRUST_D && self.attack_bits & BIT_ATK3) || (_THRUST_U && self.attack_bits & BIT_ATK4)) {
      if (gmBool(g.mod_CuccoUpDownThrustHB) && _THRUST_U && self.attack_bits & BIT_ATK4) {
        self.SwordHB_w = self.SwordHB_W - 4
        self.SwordHB_h = self.SwordHB_H
      } else {
        self.SwordHB_w = self.SwordHB_W
        self.SwordHB_h = self.SwordHB_H
      }
    } else {
      self.SwordHB_w = self.Cucco_SwordHB_W
      self.SwordHB_h = self.Cucco_SwordHB_H
      if (g.CuccoSpell2_Active) self.SwordHB_w = sword2(self.SwordHB_w)
    }
    self.SwordHB_w_ = self.SwordHB_w >> 1
    self.SwordHB_h_ = self.SwordHB_h >> 1
    self.SwordHB2_w = self.Cucco_SwordHB_W
    self.SwordHB2_h = self.Cucco_SwordHB_H
  } else if (pc_is_fairy()) {
    self.DRAW_YOFF = 1 // +1 for 1 pixel in ground
    if (self.sprite_index !== PC_PLACEMENT_SPR) {
      GO_set_sprite_index(self, PC_PLACEMENT_SPR)
      set_xy(self, self.x, self.y)
    }
    self.hspd_max = g.DevDash_state === 2 ? self.HSPD_MAX1_DASH : self.HSPD_MAX1
    self.cs_off_idx = self.Fairy_CS_OFF_IDX
    self.BodyHB_idx = self.Fairy_BodyHB_IDX1
    self.SwordHB_w = self.SwordHB_W
    self.SwordHB_h = self.SwordHB_H
    self.SwordHB_w_ = self.SwordHB_w >> 1
    self.SwordHB_h_ = self.SwordHB_h >> 1
    self.SwordHB2_w = self.SwordHB2_W
    self.SwordHB2_h = self.SwordHB2_H
  } else {
    self.DRAW_YOFF = 1 // +1 for 1 pixel in ground
    if (self.sprite_index !== PC_PLACEMENT_SPR) {
      GO_set_sprite_index(self, PC_PLACEMENT_SPR)
      set_xy(self, self.x, self.y)
    }
    self.hspd_max = g.DevDash_state === 2 ? self.HSPD_MAX1_DASH : self.HSPD_MAX1
    self.cs_off_idx = self.CS_OFF_IDX
    self.BodyHB_idx = self.BodyHB_IDX1
    self.SwordHB_w = sword2(self.SwordHB_W)
    self.SwordHB_h = self.SwordHB_H
    self.SwordHB_w_ = self.SwordHB_w >> 1
    self.SwordHB_h_ = self.SwordHB_h >> 1
    self.SwordHB2_w = self.SwordHB2_W
    self.SwordHB2_h = self.SwordHB2_H
  }
}

/** `PC_update_1b()` — 9610: water-walk sound + `updateX()` on the qualified frame. */
export function PC_update_1b(self: Lonk): void {
  PC_update_1b_(self)
}

/**
 * `PC_update_1c()` — GO_update_cs, then the tile interactions under the feet: insta-kill liquid (E098),
 * spikes, crumble ground (E0FC), viscous liquid (E0B0), and the exit checks. Body in `update1c.ts`.
 */
export function PC_update_1c(self: Lonk): void {
  PC_update_1c_impl(self)
}

/** `PC_update_1d()` — 938A: hspd/vspd dirs, `PC_update_1c`, stop hspd when a side is colliding. */
export function PC_update_1d(self: Lonk): void {
  if (self.hspd & 0x80) self.hspd_dir = -1
  else if (self.hspd) self.hspd_dir = 1
  if (self.vspd & 0x80) self.vspd_dir = -1
  else if (self.vspd) self.vspd_dir = 1
  PC_update_1c(self) // 9395: JSR E070
  if (self.cs & 0x3) self.hspd = 0 // 9398
}

/** `PC_update_1e()` — remember last position for the death flash screen. */
export function PC_update_1e(self: Lonk): void {
  g.last_pc_x = self.x // For Death flash screen
  g.last_pc_y = self.y
  g.last_dist_from_view_x = g.last_pc_x - viewXL()
  g.last_dist_from_view_y = g.last_pc_y - viewYT()
  g.last_pc_xscale = self.xScale // For rm_Death
  if (!input.Attack_held && self.StabFrenzy_charge_counter < 0x80) self.StabFrenzy_charge_counter = 0
}
