/** `Octorok01` — ZALiA `enemy/octorok`: Octorok_init2, Octorok_update, Octorok_udp. v1 still, v2 walking, v3 purple. */
import { ABL_JUMP, ABL_SHOT, ABL_WALK, Area_EastA, CS_BD1, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { byteNegate, gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { registerObjectClass } from '../../../../../other/registry'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { dir_to_pc, is_facing_pc } from '../../../../go/misc'
import { GO_vspd_update1, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { solid_clip_correction } from '../../../../goa/movement'
import type { ObjectName } from '../../../../objectNames'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_udp_1, GOB_update_2 } from '../../../GameObjectB'
import { dl, rand } from '../../shared'

export class Octorok01 extends Enemy {
  readonly objectName = 'Octorok01' as const
  VSPD_GRAV = 2
}
registerObject('Octorok01', Octorok01)
registerObjectClass('Octorok01', Octorok01)

/** `Octorok_init2()` */
export function Octorok_init2(self: Octorok01): void {
  const s = dl(self)
  switch (self.ver) {
    case 1:
    case 2:
      s.add('spr_Octorok_Idle', 'spr_Octorok_Mouth')
      break
    case 3:
      s.add('spr_Octorok2_Idle', 'spr_Octorok2_Mouth')
      break
  }
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.abilities |= ABL_JUMP
  self.abilities |= ABL_SHOT
  if (self.ver === 2) self.abilities |= ABL_WALK
  self.projectile_OBJ = 'Rock2'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  if (self.ver === 3) {
    GO_init_palidx(self, G.PI_MOB_PUR)
  } else if (g.area_name === Area_EastA) {
    GO_init_palidx(self, G.PI_MOB_BLU)
    self.HP_IDX = 0x08
    self.hp = g.dl_HP.get(self.HP_IDX)
    self.XP_IDX = 0x0c
    self.xp = g.dl_XP.get(self.XP_IDX)
  }
}

/** `Octorok_update()` — D888(moving), D842(still) */
export function Octorok_update(self: Octorok01): void {
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return
  }
  // D845: JSR DC91 (still)
  if (!(self.abilities & ABL_WALK)) self.facing_dir = dir_to_pc(self)
  // D88B: JSR D848 (moving)
  // counter.  Jump is on $00,80.  Face PC on $40,C0
  self.counter = (self.counter + 1) & 0xff
  // Jump on $00,80
  if (self.abilities & ABL_JUMP && !(self.counter & 0x7f)) self.vspd = 0xe0 // Jump!!
  updateY(self)
  // D858
  GO_update_cs(self)
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self) // CS_BD1
  // D85E
  if (self.cs & 0x04) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  } else {
    // MOD. Prevent clip into ceiling
    GO_vspd_update1(self) // if (cs8() && vspd&$80) vspd=$0;
    // at peak of jump
    if (!gmBool(self.vspd) || self.vspd < self.vspd_grav) {
      if (self.abilities & ABL_SHOT && is_facing_pc(self) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
        GOC1_create(self.xl, self.yt, self.facing_dir, self.projectile as ObjectName, self.projectile_ver)
      }
    }
  }
  // moving Octorok (v2)
  if (self.abilities & ABL_WALK) {
    // D88E
    if (self.cs & 0x03) {
      self.facing_dir = -self.facing_dir
      self.hspd = byteNegate(self.hspd)
    }
    updateX(self)
    // D89A:  Face and move towards PC on $40,C0
    if (((self.counter << 1) & 0xff) === 0x80) {
      self.facing_dir = dir_to_pc(self)
      self.hspd = (0x08 * self.facing_dir) & 0xff
    }
  }
  // D8A9
  if (self.abilities & ABL_SHOT && self.ver === 2 && !gmBool(self.timer)) {
    self.timer = rand(self) | 0x80
    if (self.cs & 0x04 && is_facing_pc(self) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
      GOC1_create(self.xl, self.yt, self.facing_dir, self.projectile as ObjectName, self.projectile_ver)
    }
  }
}

/** `Octorok_udp()` */
export function Octorok_udp(self: Octorok01): void {
  self.can_draw_self = true
  GOB_udp_1(self, 8)
}

registerScripts({ Octorok_init2, Octorok_update, Octorok_udp })
