/** `WizaA` — ZALiA `enemy/wizard`: teleporting Wizzrobe that fires a SoundWave. AE4F */
import { CS_BD1, MAX_GOC1, PAGE_W, UIDX_NULL } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { GOB_body_collide_pc_body_1a } from '../../../../../collision/gob'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { registerObjectClass } from '../../../../../other/registry'
import { cam_xl_min, cam_xr_max } from '../../../../../view/camera'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { dir_to_pc, prevent_spawn_in_pc } from '../../../../go/misc'
import { set_xy } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import type { ObjectName } from '../../../../objectNames'
import { registerObject, registerScripts } from '../../../../registry'
import { update_EF11 } from '../../../GameObjectB'
import { rand } from '../../shared'

export class WizaA extends Enemy {
  readonly objectName = 'WizaA' as const
}
registerObject('WizaA', WizaA)
registerObjectClass('WizaA', WizaA)

/** `Wizard_init2()` */
export function Wizard_init2(self: WizaA): void {
  GO_init_palidx(self, G.PI_MOB_RED)
  self.projectile_OBJ = 'SoundWave'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
}

/** `Wizard_udp()` */
export function Wizard_udp(self: WizaA): void {
  self.can_draw_self = true
  if (self.counter < 0xc0) GO_set_sprite(self, 'spr_Wizard1')
  else GO_set_sprite(self, 'spr_Wizard2')
}

/** `Wizard_update()` — AE4F */
export function Wizard_update(self: WizaA): void {
  self.behavior = 0 // SoundWave checks this
  self.facing_dir = dir_to_pc(self)
  self.counter = (self.counter - 1) & 0xff
  // $FF-C0
  if (self.counter >= 0xc0) {
    if (self.counter & 1) update_EF11(self)
    return
  }
  // AE64
  if (self.counter === 0xb0 && !gmBool(self.ocs) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
    let _XX = self.xl + 0x0d
    if (!gmBool(self.facing_dir)) _XX = self.xl + -0x06
    const _YY = self.yt + 0x10
    const wave = GOC1_create(
      _XX,
      _YY,
      self.facing_dir,
      self.projectile as ObjectName,
      self.projectile_ver,
      self,
    )
    wave.counter = 1 + (gmBool(self.facing_dir) ? 0 : 1) // 1,2
  }
  // AE6D
  if (self.counter & 0x80) {
    // $BF-80
    self.behavior = 1 // SoundWave checks this
    GOB_body_collide_pc_body_1a(self)
    if (self.cs & CS_BD1) enemy_collide_pc_body(self)
    update_EF11(self)
  } else if (self.counter >= 0x40) {
    // AEBA. $7F-40
    if (!(self.counter & 0x01)) update_EF11(self)
  } else {
    // AEBD. $3F
    self.stun_timer = 0
    self.counter = 0
    switch (g.mod_Wizard_TELEPORT_AREA) {
      case 0: {
        // OG: Wizards only teleport inside map page 1...
        let _xl = rand(self)
        if (_xl >= 0xe0) _xl = _xl >> 1
        _xl += 0x0100
        set_xy(self, _xl + self.sprite_index_xoff, self.yt)
        break
      }
      case 1: {
        let _x = g.view_xl_og + g_irandom(0x0100) // MOD.  Using rand() can make Wizards group together
        _x = clamp(_x, cam_xl_min() + self.sprite_index_xoff, cam_xr_max() - self.sprite_index_xoff)
        set_xy(self, _x, self.y)
        prevent_spawn_in_pc(self)
        _x = clamp(_x, cam_xl_min() + self.sprite_index_xoff, cam_xr_max() - self.sprite_index_xoff)
        set_xy(self, _x, self.y)
        break
      }
      case 2: {
        const _PAD = PAGE_W >> 2
        let _x = Math.max(cam_xl_min() + _PAD, g.view_xl_og)
        const _W = Math.min(_x + PAGE_W, cam_xr_max() - _PAD) - _x
        _x += g_irandom(_W)
        set_xy(self, _x, self.y)
        prevent_spawn_in_pc(self)
        break
      }
    }
  }
}

import { world } from '../../../../../../runtime/world'

const g_irandom = (n: number) => world.irandom(n)
const clamp = (v: number, lo: number, hi: number) => Math.min(Math.max(v, lo), hi)

registerScripts({ Wizard_init2, Wizard_update, Wizard_udp })
