/**
 * Palette rando — ported from `Rando_randomize_palettes.gml` (798 lines).
 *
 * Three passes, all writing scene palette strings that `p_Room_Start_palette_rando` reads back:
 * 1. Dungeons: each palace gets one main colour scheme (BGR1) and one secondary scheme (BGR2) built from
 *    two neighbouring entries of the shuffled base-hue list, plus a darkened BGR4 "B" colour for the
 *    BGWALL layers. Every scene of the palace gets the same three replacements.
 * 2. Non-dungeon scenes: the scene's Tiled layer names say which BGR palette indices it actually uses;
 *    indices used by a LIQUID/BURNABLE layer are protected (their colours are swap sources) and the rest
 *    are shuffled — one of them (1/16 of the time two) gets a fresh random palette.
 * 3. PC and Cucco: a shuffled tunic-colour list feeds `build_pal` for the three PC and three Cucco
 *    palettes; skin/outline and the cucco legs/body colours are kept.
 *
 * `Rando_generate` reads `STR_Palette+STR_Rando+<scene>` back for boss rando, so those datakeys are exact.
 *
 * Dropped:
 * - `:384-794` — one `/* *\/` block holding an older whole-script draft (verified: the file's only `/*`
 *   is at 384 and its only `*\/` at 794; `:795-798` are blank). Live code is `:1-383`.
 * - the commented-out `if (DEBUG){…}` at `:9`. This script writes no `dm_debug_data` line at all.
 *
 * GML quirks kept: `_area` (`:175`) and `_datakey1` (`:213`) are never `var`-declared, so ZALiA leaks them
 * onto the `Rando` instance; they are plain locals here. `global.PI_BGR5` is -1 (never registered), so the
 * `case $05` arms below add/select an invalid palette index — unreachable with the shipped layer data,
 * whose palette suffixes are only 01-04 (plus one `BG0306` and one `BG0709`, both handled by `default`).
 */
import {
  Area_PalcA,
  Area_PalcB,
  Area_PalcC,
  Area_PalcD,
  Area_PalcE,
  Area_PalcF,
  Area_PalcG,
  Area_PalcH,
  dk_BGR,
  dk_FileName,
  STR_Count,
  STR_Cucco,
  STR_Game,
  STR_Layer,
  STR_Name,
  STR_Num,
  STR_Palette,
  STR_Quest,
  STR_Rando,
  STR_Rm,
} from '@z2/data'
import { DsList } from '../../runtime/ds'
import { G, g, p, world } from '../../runtime/world'
import { save_game_pref } from '../file/prefs'
import { gmBool } from '../math/index'
import { hex_str, str_hex, strReplaceAt } from '../other/index'
import {
  color_str,
  colour_get_hue,
  colour_get_saturation,
  colour_get_value,
  make_colour_hsv,
} from '../palette/colors'
import { build_pal } from '../palette/palString'
import { get_random_palette2 } from '../palette/randomColors'
import { paletteFromSceneFile } from '../palette/roomStart'
import { choose, clamp, ds_list_shuffle, string_copy, string_pos } from './helpers'
import type { Rando } from './Rando'

/**
 * The scene's BGR palette string, keyed by Tiled file name as `p_init_palette_data` keys it.
 *
 * SEAM(palette): ZALiA's `p_init_palette_data` decoded every scene's Tiled file at boot and filled
 * `dm_scene_palette[?<file>_BGR]` for all of them (it also wrote the `PaletteData01.txt` cache the port
 * dropped — see FIDELITY_NOTES). This port decodes a scene's palette lazily at room start, so at file
 * registration — when the randomizer runs — the map holds only the shipped `_MOB` overrides and every
 * lookup missed, making the whole palette pass a no-op. Decode on the miss and memoise under the same
 * datakey: the randomizer sees what `p_init` would have left it, boot stays lazy, and `p_Room_Start`
 * reads the memoised value instead of decoding the file twice.
 */
export function scene_bgr_palette(
  _scene_name: string,
  _file_name: string,
  _QUEST_NUM: number,
): string | undefined {
  const _dk = _file_name + dk_BGR
  let _palette = p.dm_scene_palette.get(_dk) as string | undefined
  if (_palette !== undefined) return _palette
  _palette = paletteFromSceneFile(_scene_name, _QUEST_NUM)
  if (_palette !== undefined) p.dm_scene_palette.set(_dk, _palette)
  return _palette
}

export function Rando_randomize_palettes(self: Rando): void {
  if (gmBool(self.Palette_WILL_RANDOMIZE))
    g.RandoPalette_state = 2 // 2: Full palette rando
  else g.RandoPalette_state = 0 // 0: Palette rando off
  save_game_pref()

  // --------------------------------------------
  world.random_set_seed(self.Rando_SEED)
  // --------------------------------------------

  const _dl_pi = new DsList<number>()

  const _dl_base_hues = new DsList<number>()
  _dl_base_hues.add(0x0000ff) // hue: 00  RED
  _dl_base_hues.add(0x0048ff) // hue: 0C  RED-ORANGE
  _dl_base_hues.add(0x007fff) // hue: 15  ORANGE
  _dl_base_hues.add(0x00c0ff) // hue: 20  ORANGE-YELLOW
  _dl_base_hues.add(0x00ffff) // hue: 2B  YELLOW
  _dl_base_hues.add(0x00ffaa) // hue: 39  YELLOW-GREEN
  _dl_base_hues.add(0x00ff00) // hue: 55  GREEN
  _dl_base_hues.add(0xaaff00) // hue: 71  GREEN-CYAN
  _dl_base_hues.add(0xffff00) // hue: 80  CYAN
  _dl_base_hues.add(0xff8000) // hue: 95  CYAN-BLUE
  _dl_base_hues.add(0xff0000) // hue: AA  BLUE
  _dl_base_hues.add(0xff0066) // hue: BB  BLUE-PURPLE
  _dl_base_hues.add(0xff00aa) // hue: C6  PURPLE
  _dl_base_hues.add(0xff00ff) // hue: D5  MAGENTA
  _dl_base_hues.add(0x7f00ff) // hue: EA  MAGENTA-RED
  for (let _i = _dl_base_hues.size - 1; _i >= 0; _i--) {
    const _color = _dl_base_hues.get(_i) as number
    const _val1 = colour_get_hue(_color)

    // add a little variation to the base hues
    let _val = _val1 + 0x100
    _val += world.irandom(5) * choose(1, -1)
    _val = _val % 0x100

    _dl_base_hues.set(_i, _val)
  }
  _dl_base_hues.add(-2) // -2: Tells `get_random_palette1` to use $00 saturation
  ds_list_shuffle(_dl_base_hues)

  const _dl_DUNGEON_AREAS = new DsList<string>()
  _dl_DUNGEON_AREAS.add(Area_PalcA) // Parapa Palace
  _dl_DUNGEON_AREAS.add(Area_PalcB) // Midoro Palace
  _dl_DUNGEON_AREAS.add(Area_PalcC) // Island Palace
  _dl_DUNGEON_AREAS.add(Area_PalcD) // Maze Isl Palace
  _dl_DUNGEON_AREAS.add(Area_PalcE) // Palace on the Sea
  _dl_DUNGEON_AREAS.add(Area_PalcF) // Hidden Palace
  _dl_DUNGEON_AREAS.add(Area_PalcG) // Great Palace
  _dl_DUNGEON_AREAS.add(Area_PalcH) // Dragmire Tower

  // Dungeons ---------------------------------------------------
  const _dl_DUNGEON_AREAS_COUNT = _dl_DUNGEON_AREAS.size
  for (let _i = 1; _i <= _dl_DUNGEON_AREAS_COUNT; _i++) {
    // each dungeon
    // The main color scheme palette of the dungeon
    let _pos1 = p.PI_BGR1
    _pos1 -= p.PI_BGR1
    _pos1 *= p.PAL_CHAR_PER_PAL
    _pos1++
    const _palette1 = get_random_palette2(_dl_base_hues.get(_i) as number)

    // Dungeon secondary palette (the palette curtains,crystal-holder,etc.. use)
    let _pos2 = p.PI_BGR2
    _pos2 -= p.PI_BGR1
    _pos2 *= p.PAL_CHAR_PER_PAL
    _pos2++
    const _palette2 = get_random_palette2(_dl_base_hues.get((_i + 1) % _dl_base_hues.size) as number)

    // BGR4 shade color for BGWALL layers
    let _pos = Math.max(0, string_pos('B', p.PAL_BASE_COLOR_ORDER) - 1)
    _pos *= p.PAL_CHAR_PER_COLOR
    _pos++
    const _color = str_hex(string_copy(_palette1, _pos, p.PAL_CHAR_PER_COLOR))
    const _hue = colour_get_hue(_color)
    const _sat = colour_get_saturation(_color)
    const _lum = clamp(colour_get_value(_color), 0x04, 0x40)
    const _color1 = make_colour_hsv(_hue, _sat, _lum)
    let _pos3 = p.PI_BGR4
    _pos3 -= p.PI_BGR1
    _pos3 *= p.PAL_CHAR_PER_PAL
    _pos3 += _pos - 1
    _pos3++

    for (let _j = 0; _j < 0x100; _j++) {
      // Each dungeon scene
      const _scene_name = (_dl_DUNGEON_AREAS.get(_i - 1) as string) + hex_str(_j)

      if (g.dm_rm.get(_scene_name + STR_Rm + STR_Num + STR_Game) === undefined) {
        continue //_j
      }

      // file name data example: "PalcA_003"
      const _file_name1 = g.dm_rm.get(`${_scene_name + dk_FileName + STR_Quest}01`) as string | undefined
      const _file_name2 = g.dm_rm.get(`${_scene_name + dk_FileName + STR_Quest}02`) as string | undefined
      if (_file_name1 === undefined) {
        continue //_j
      }

      const _file_name = self.QUEST_NUM === 2 && _file_name2 !== undefined ? _file_name2 : _file_name1
      // Decode the file the name above actually resolved to. `scene_data.json` has 7 `_FileName_Quest02`
      // keys against 794 quest-1 ones, so asking for quest 2 by scene name missed for 787 of 794 scenes and
      // a quest-2 generation randomized no scene palette at all.
      const _file_quest = _file_name === _file_name2 ? 2 : 1

      // `p.dm_scene_palette[?_file_name+dk_BGR]` is only PI_BGR1-PI_BGR4
      let _palette = scene_bgr_palette(_scene_name, _file_name, _file_quest)
      if (_palette === undefined) {
        continue //_j
      }

      // BGR1
      _palette = strReplaceAt(_palette, _pos1, _palette1.length, _palette1)

      // BGR2
      _palette = strReplaceAt(_palette, _pos2, _palette2.length, _palette2)

      // BGR4 shade color for BGWALL layers
      _palette = strReplaceAt(_palette, _pos3, p.PAL_CHAR_PER_COLOR, color_str(_color1))

      self.dm_save_data.set(STR_Palette + STR_Rando + _scene_name, _palette)
    }
  }

  // Non-Dungeon Scenes ------------------------------------------------
  const _dl_protected_pi = new DsList<number>()
  const _AREA_COUNT = g.dl_AREA_NAME.size
  for (let _i = 0; _i < _AREA_COUNT; _i++) {
    // Each area
    const _area = g.dl_AREA_NAME.get(_i) as string
    if (_dl_DUNGEON_AREAS.findIndex(_area) !== -1) {
      continue //_i
    }

    for (let _j = 0; _j < 0x100; _j++) {
      // Each possible scene of the area
      const _scene_name = _area + hex_str(_j)

      // file name data example: "PalcA_003"
      const _file_name1 = g.dm_rm.get(`${_scene_name + dk_FileName + STR_Quest}01`) as string | undefined
      const _file_name2 = g.dm_rm.get(`${_scene_name + dk_FileName + STR_Quest}02`) as string | undefined
      if (_file_name1 === undefined) {
        continue //_j
      }

      const _file_name = self.QUEST_NUM === 2 && _file_name2 !== undefined ? _file_name2 : _file_name1
      // Decode the file the name above actually resolved to. `scene_data.json` has 7 `_FileName_Quest02`
      // keys against 794 quest-1 ones, so asking for quest 2 by scene name missed for 787 of 794 scenes and
      // a quest-2 generation randomized no scene palette at all.
      const _file_quest = _file_name === _file_name2 ? 2 : 1

      // `p.dm_scene_palette[?_file_name+dk_BGR]` is only PI_BGR1-PI_BGR4
      let _palette = scene_bgr_palette(_scene_name, _file_name, _file_quest)
      if (_palette === undefined) {
        continue //_j
      }

      //_dm[?'WestA_024'+STR_Layer+'02'+STR_Name] = 'FG0203, LIQUID_02 DIR_02 SPEED_08';
      const _datakey1 = _file_name + STR_Layer

      let _layer_data_num = 0x01
      _dl_protected_pi.clear()
      while (true) {
        const _layer_name = G.dm_tile_layer_data.get(_datakey1 + hex_str(_layer_data_num++) + STR_Name) as
          | string
          | undefined
        if (_layer_name === undefined) {
          break //while (true)
        }

        if (string_pos('LIQUID', _layer_name) !== 0 || string_pos('BURNABLE', _layer_name) !== 0) {
          if (string_pos('BG0', _layer_name) !== 0 || string_pos('FG0', _layer_name) !== 0) {
            let _pos: number
            if (string_pos('BG0', _layer_name) !== 0) _pos = string_pos('BG0', _layer_name)
            else _pos = string_pos('FG0', _layer_name)

            // `_pos+4` skips "BG0N"/"FG0N" (the depth) — these two chars are the palette number.
            const _val = str_hex(string_copy(_layer_name, _pos + 4, 2))
            switch (_val) {
              case 0x01:
                _dl_protected_pi.add(p.PI_BGR1)
                break
              case 0x02:
                _dl_protected_pi.add(p.PI_BGR2)
                break
              case 0x03:
                _dl_protected_pi.add(p.PI_BGR3)
                break
              case 0x04:
                _dl_protected_pi.add(p.PI_BGR4)
                break
              case 0x05:
                _dl_protected_pi.add(p.PI_BGR5)
                break
            }
          }
        }
      }

      _layer_data_num = 0x01
      _dl_pi.clear()
      while (true) {
        const _layer_name = G.dm_tile_layer_data.get(_datakey1 + hex_str(_layer_data_num++) + STR_Name) as
          | string
          | undefined
        if (_layer_name === undefined) {
          break //while (true)
        }

        if (string_pos('BG0', _layer_name) !== 0 || string_pos('FG0', _layer_name) !== 0) {
          let _pos: number
          if (string_pos('BG0', _layer_name) !== 0) _pos = string_pos('BG0', _layer_name)
          else _pos = string_pos('FG0', _layer_name)

          const _val = str_hex(string_copy(_layer_name, _pos + 4, 2))
          let _pi: number
          switch (_val) {
            case 0x02:
              _pi = p.PI_BGR2
              break
            case 0x03:
              _pi = p.PI_BGR3
              break
            case 0x04:
              _pi = p.PI_BGR4
              break
            case 0x05:
              _pi = p.PI_BGR5
              break
            default:
              _pi = p.PI_BGR1
              break
          }

          if (_dl_pi.findIndex(_pi) === -1 && _dl_protected_pi.findIndex(_pi) === -1) {
            _dl_pi.add(_pi)
            if (_dl_pi.size >= (p.dm_pi.val(`BGR${STR_Count}`) as number)) {
              break //while (true)
            }
          }
        }
      }

      if (_dl_pi.size !== 0) {
        ds_list_shuffle(_dl_pi)

        let _count = 1
        _count += world.irandom(0xf) === 0 ? 1 : 0 // GML `!irandom($F)`
        _count = Math.min(_count, _dl_pi.size)
        for (let _k = 0; _k < _count; _k++) {
          let _pos = _dl_pi.get(_k) as number
          _pos -= p.PI_BGR1
          _pos *= p.PAL_CHAR_PER_PAL
          _pos++
          const _palette1 = get_random_palette2(-1)
          // FIDELITY: ZALiA replaced into the *untouched* `_palette` on every `_k`, so when `_count` was 2
          // the second write threw the first randomized palette index away. Accumulate instead — the RNG
          // stream is unchanged (`get_random_palette2` is still called `_count` times).
          _palette = strReplaceAt(_palette, _pos, _palette1.length, _palette1)
          self.dm_save_data.set(STR_Palette + STR_Rando + _scene_name, _palette)
        }
      }
    }
  }

  // PC and Cucco -----------------------------------------------------------------------------
  // ----------------------------------------------------------------------------
  const _COLOR_pc_skin = string_copy(p.PAL_PC_1, p.PAL_CHAR_PER_COLOR * 0 + 1, p.PAL_CHAR_PER_COLOR) // pc skin
  const _COLOR_pc_outline = string_copy(p.PAL_PC_1, p.PAL_CHAR_PER_COLOR * 2 + 1, p.PAL_CHAR_PER_COLOR) // pc outline
  const _COLOR_cucco_legs = string_copy(p.PAL_CUC1, p.PAL_CHAR_PER_COLOR * 0 + 1, p.PAL_CHAR_PER_COLOR) // cucco legs/beak
  const _COLOR_cucco_body = string_copy(p.PAL_CUC1, p.PAL_CHAR_PER_COLOR * 1 + 1, p.PAL_CHAR_PER_COLOR) // cucco body

  const _dl_tunic_colors = new DsList<number>() // acceptable tunic colors
  _dl_tunic_colors.add(p.C_WHT2, p.C_GRY4, p.C_BLK1)
  _dl_tunic_colors.add(p.C_BLU2, p.C_BLU3, p.C_BLU4)
  _dl_tunic_colors.add(p.C_VLT2, p.C_VLT3, p.C_VLT4)
  _dl_tunic_colors.add(p.C_PUR2, p.C_PUR3, p.C_PUR4)
  _dl_tunic_colors.add(p.C_MGN2, p.C_MGN3, p.C_MGN4)
  _dl_tunic_colors.add(p.C_PNK2, p.C_PNK3, p.C_PNK4)
  _dl_tunic_colors.add(p.C_RED2, p.C_RED3, p.C_RED4)
  _dl_tunic_colors.add(p.C_ORG2, p.C_ORG3, p.C_ORG4)
  _dl_tunic_colors.add(p.C_YLW2, p.C_YLW3, p.C_YLW4)
  _dl_tunic_colors.add(
    choose(p.C_YGR2, p.C_GRN2, p.C_GRB2),
    choose(p.C_YGR3, p.C_GRN3, p.C_GRB3),
    choose(p.C_YGR4, p.C_GRN4, p.C_GRB4),
  )
  _dl_tunic_colors.add(p.C_CYN2, p.C_CYN3, p.C_CYN4)

  // Limiting the number of brights because their colors aren't very distinct
  const _dl_bright_colors = new DsList<number>() // bright acceptable tunic colors
  _dl_bright_colors.add(
    p.C_BLU1,
    p.C_VLT1,
    p.C_PUR1,
    p.C_MGN1,
    p.C_PNK1,
    p.C_RED1,
    p.C_ORG1,
    p.C_YLW1,
    p.C_YGR1,
    p.C_GRN1,
    p.C_GRB1,
    p.C_CYN1,
  )
  ds_list_shuffle(_dl_bright_colors)
  _dl_tunic_colors.add(
    _dl_bright_colors.get(0) as number,
    _dl_bright_colors.get(1) as number,
    _dl_bright_colors.get(2) as number,
    _dl_bright_colors.get(3) as number,
  )

  ds_list_shuffle(_dl_tunic_colors)

  let _i = 0

  // PC -------------
  let _val = build_pal(
    _COLOR_pc_skin,
    _dl_tunic_colors.get(_i++) as number,
    _COLOR_pc_outline,
    p.C_BLK1,
    -2,
    -2,
    -2,
    -2,
  )
  _val += build_pal(
    _COLOR_pc_skin,
    _dl_tunic_colors.get(_i++) as number,
    _COLOR_pc_outline,
    p.C_BLK1,
    -2,
    -2,
    -2,
    -2,
  )
  _val += build_pal(
    _COLOR_pc_skin,
    _dl_tunic_colors.get(_i++) as number,
    _COLOR_pc_outline,
    p.C_BLK1,
    -2,
    -2,
    -2,
    -2,
  )
  self.dm_save_data.set(`${STR_Palette}_PC01`, _val)

  // CUCCO -------------
  _val = build_pal(
    _COLOR_cucco_legs,
    _COLOR_cucco_body,
    _dl_tunic_colors.get(_i++) as number,
    p.C_BLK1,
    -2,
    -2,
    -2,
    -2,
  )
  _val += build_pal(
    _COLOR_cucco_legs,
    _COLOR_cucco_body,
    _dl_tunic_colors.get(_i++) as number,
    p.C_BLK1,
    -2,
    -2,
    -2,
    -2,
  )
  _val += build_pal(
    _COLOR_cucco_legs,
    _COLOR_cucco_body,
    _dl_tunic_colors.get(_i++) as number,
    p.C_BLK1,
    -2,
    -2,
    -2,
    -2,
  )
  self.dm_save_data.set(`${STR_Palette + STR_Cucco}01`, _val)
}
