/** Spawn-by-stab — ZALiA `gob2/spawn_by_stab` (`SpStA`). */
import { Area_PalcG, CS_SW1, dk_StrikeEnemy, ITM_GLOV, TID_BREAK1, TID_BREAK3 } from '@z2/data'
import { gmBool, isVal } from '../../../../nes/math8'
import { NOONE } from '../../../../runtime/instance'
import { f, g, world } from '../../../../runtime/world'
import { is_in_grid, pointInRect } from '../../../collision/geometry'
import { GOB_body_collide_pc_sword } from '../../../collision/gob'
import { aud_play_sound } from '../../../sound/play'
import { get_audio_theme_track } from '../../../sound/theme'
import { Enemy, Item } from '../../classes'
import { GameObject_create } from '../../create'
import { pc } from '../../goa/pc'
import type { ObjectName } from '../../objectNames'
import type { SpStA } from './classes'
import { OgRandomRead } from './rand'

/** `SpawnByStab_init2()` */
export function SpawnByStab_init2(self: SpStA): void {
  // 0: Waiting for stab. 1: Waiting for spawned (GO.state == 0) so can set proper respawn value.
  self.BVR_STBD = 1 // STABBED
  self.BVR_AFTR = 2 // AFTER. Waiting for spawned inst state to be 0.
  self.BVR_CFRM = 3 // CONFIRM. Confirm spawned inst is defeated.
  self.behavior = 0
  self.spawned_inst = NOONE
  const _CLM = self.xl >> 3
  const _ROW = self.yt >> 3
  self.IS_BREAK_BLOCK =
    is_in_grid(_CLM, _ROW, g.dg_RmTile_Break.width, g.dg_RmTile_Break.height) &&
    isVal((g.dg_RmTile_Break.get(_CLM, _ROW) as number) & 0xff, TID_BREAK1, TID_BREAK3)
}

/** `SpawnByStab_update()` */
export function SpawnByStab_update(self: SpStA): void {
  const P = pc()
  let _can_spawn_jar = false
  switch (self.behavior) {
    case 0: {
      // AF61
      if (self.ocs) break // if any width is outside the view. ###########################
      if (gmBool(g.mod_SpawnByStab_Block)) {
        // MOD: It makes more sense that only breaking the block would activate the spawn.
        self.BodyHB_can_draw = true
        if (self.IS_BREAK_BLOCK) {
          // Breakable block
          if (
            !P.SwordHB_collidable ||
            !(f.items & ITM_GLOV) ||
            !pointInRect(P.SCS_x, P.SCS_y, (self.xl >> 3) << 3, (self.yt >> 3) << 3, 0x10, 0x10)
          ) {
            break // #################################################
          }
        } else {
          GOB_body_collide_pc_sword(self)
          if (!(self.cs & CS_SW1)) break // #################################################
        }
      } else {
        // AF65: JSR E677
        GOB_body_collide_pc_sword(self)
        self.BodyHB_can_draw = true
        // MOD. It's possible to break the block w/out activating SpawnByStab bc scs is not inside swrd hb.
        let _colliding: boolean | number = self.cs & CS_SW1
        if (!_colliding && self.ver === 1 && P.SwordHB_collidable) {
          _colliding = pointInRect(P.SCS_x, P.SCS_y, (self.xl >> 3) << 3, (self.yt >> 3) << 3, 0x10, 0x10)
        }
        if (!_colliding) break // #################################################
      }
      self.stun_timer = 0
      self.behavior = self.BVR_STBD
      aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
      break
    }
    case self.BVR_STBD: {
      // STBD: STaBbed
      switch (self.ver) {
        case 0x01: // Guarantee Jar
          _can_spawn_jar = true
          break
        case 0x02: {
          // Jar or Knight
          const _MOD = gmBool(g.mod_SpawnByStab_DungeonEntrance)
          if ((_MOD && world.irandom(99) > 14) || (!_MOD && OgRandomRead(self) < 0x80)) {
            // JAR: MAGIC FULL
            _can_spawn_jar = true
          } else {
            // IRONKNUCKLE OR FOKKA
            let _obj: ObjectName = 'IrKnA'
            let _ver = 2 // IronKnuckle red
            if (g.area_name === Area_PalcG) {
              _obj = 'FokkA'
              _ver = 1 // Fokka Red
            }
            const sp = GameObject_create(self.xl + 3, self.yt, _obj, _ver)
            self.spawned_inst = sp
            if (sp) {
              sp.HP_IDX = 0x0d // g.dl_HP_DEFAULT[|$0D] = $18
              sp.hp = g.dl_HP.get(sp.HP_IDX) as number
              sp.counter = 0x11
              sp.facing_dir = self.facing_dir
              sp.hspd = self.hspd
              sp.stun_timer = 8
              sp.cs = self.cs
              // respawn_type: 0: never, 1: off screen, 2: refresh area, 3: refresh rm, 4: 30 seconds
              sp.RESPAWN_TYPE = 0
              sp.respawn_type = sp.RESPAWN_TYPE
              sp.SpawnByStab_inst = self
            }
          }
          break
        }
      }
      self.behavior = self.BVR_AFTR
      break
    }
    case self.BVR_AFTR: {
      if (!g.mod_destroy_go_on_death) {
        const sp = self.spawned_inst
        if (!sp) {
          // If nothing was spawned
          self.state = 0
          return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
        }
        // Because the spawned_inst is, in a sense, still the SpawnByStab obj, specific checks need to be done to
        // make sure the spawned_inst has been used/taken/completed/defeated.
        if (sp instanceof Item && sp.cs & CS_SW1 && !sp.state) {
          self.behavior = self.BVR_CFRM
          break
        }
        if (sp instanceof Enemy && sp.state === sp.state_EXPLODE) {
          self.behavior = self.BVR_CFRM
          break
        }
      }
      break
    }
    case self.BVR_CFRM: {
      if (!g.mod_destroy_go_on_death) {
        const sp = self.spawned_inst
        if (!sp || !sp.exists || !sp.state) {
          self.state = 0
          return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
        }
      }
      break
    }
  }
  if (_can_spawn_jar) {
    // JAR: MAGIC FULL
    const sp = GameObject_create(self.xl + 3, self.yt, 'ItmE0', 1) // Full Magic Jar
    self.spawned_inst = sp
    if (sp) {
      sp.hp = 0
      sp.facing_dir = 1
      sp.hspd = self.hspd
      sp.stun_timer = 0x18 // OG: 8
      sp.cs = self.cs
      sp.RESPAWN_TYPE = 0
      sp.respawn_type = sp.RESPAWN_TYPE
      sp.SpawnByStab_inst = self
    }
  }
}
