/** Small GML helpers the boss scripts use that have no home yet (`goDist1.gml`, `rand.gml`). */
import { byte } from '../../../../../nes/math8'
import { DsList } from '../../../../../runtime/ds'
import { world } from '../../../../../runtime/world'
import { instancesNamed as gmInstancesNamed } from '../../../../Game/gm'
import { Audio } from '../../../../sound/Audio'
import type { GameObject } from '../../../classes'
import { pc } from '../../../pending'

/**
 * `goDist1()` — distance between `global.pc.xl` and this `xl` mimicking the value stored in 000F at DCA1.
 * !!! This is meant to be used as the value in 000F that DC91 produces.
 */
export function goDist1(self: GameObject): number {
  // DCA1.  return value of 000F
  let _return = pc().xl & 0xff
  _return += byte(~(self.xl & 0xff))
  _return += +(pc().xl >= 0 && pc().xl <= 7) // carry
  _return &= 0xff
  return _return
}

/** `rand()` — this object's byte of the OG random register (by update slot), `irandom($FF)` outside it. */
export function rand(self: GameObject): number {
  return world.ogRandom.rand(self.update_idx, () => world.irandom(0xff))
}

/** `dl_sprites` is optional on GameObject; the boss init scripts always fill it. */
export function dlSprites(self: GameObject): DsList<string> {
  if (!self.dl_sprites) self.dl_sprites = new DsList<string>()
  return self.dl_sprites
}

/** GM `ds_list_shuffle` with the world's seeded PRNG (Fisher–Yates). */
export function ds_list_shuffle<T>(list: DsList<T>): void {
  const a = list.items
  for (let i = a.length - 1; i > 0; i--) {
    const j = world.irandom(i)
    const t = a[i] as T
    a[i] = a[j] as T
    a[j] = t
  }
}

/**
 * GM `with (Obj)` over every live instance of an object name (creation order).
 * FIXED: this used to match `objectName` exactly, so a GM *parent* name yielded nothing — `with(ArenaGate)`
 * never saw the live `ArenaGateA`. Delegates to the class-aware resolver, which honours the parent chain.
 */
export function* instancesNamed(objectName: string): Generator<GameObject> {
  yield* gmInstancesNamed(objectName) as Generator<GameObject>
}

/** Dev overlays (`GOB_draw_hp`, `GO_debug_draw_1a`, `GameObjectB_debug_draw_1a`) — no-ops until the dev-tools port. */
export function GOB_draw_hp(_self: GameObject): void {}
export function GO_debug_draw_1a(_self: GameObject): void {}
export function GameObjectB_debug_draw_1a(_self: GameObject): void {}

/** GM `audio_sound_length(sound)` in seconds — the adapter's playback answers it (0 when not loaded). */
export function audio_sound_length(sound: string | number | 0): number {
  if (!sound) return 0
  return Audio.playback?.length(sound) ?? 0
}
