/**
 * `Dev_RmWarper` — the area / room-id / exit-id warp picker that opens from the pause menu.
 * ZALiA deliberately un-gated it for everyone on 2024-09-12 ("This is useful if the player is making
 * custom content and needs to get somewhere fast", `Dev_RmWarper_Step.gml:4`); that stays.
 *
 * Dropped: the commented-out `dm_DATA` pre-scan in `_Create`, the `show_debug_message` dump in `_Step`,
 * the `vk_space` datakey report and the `switch(_CASE)` exit-index experiments in `_Draw`, and
 * `Dev_RmWarper_Game_End` (ds_* frees only — garbage collected here).
 */
import {
  Area_Title,
  AreaID_LEN,
  DEPTH_SURFACE,
  dk_CursorFileSelect,
  dk_CursorSpellMenu,
  dk_ItemDrop,
  dk_OpenGUI,
  dk_StrikeEnemy,
  EXIT_NAME_GAME_START,
  REEN_DEFAULT,
  RmName_LEN,
  STR_Area,
  STR_Beam,
  STR_Count,
  STR_Damage,
  STR_Game,
  STR_ID,
  STR_Name,
  STR_Num,
  STR_PC,
  STR_Rm,
  STR_Scene,
  STR_Sword,
} from '@z2/data'
import { DsList } from '../../runtime/ds'
import { Instance, instanceExists } from '../../runtime/instance'
import { f, g, input } from '../../runtime/world'
import { hINh } from '../collision/geometry'
import { type Exit, Exit_construct } from '../exit/Exit'
import { can_update_frame } from '../Game/can_update_frame'
import { instancesNamed, keyboard_check_pressed } from '../Game/gm'
import { c_black } from '../Game/gmConsts'
import { gui_tmr_cursor_h, gui_tmr_cursor_v } from '../gui/index'
import { bit_dir, bitNum, isVal, sign_ } from '../math/index'
import { hex_str, str_hex, val } from '../other/index'
import { area_is_ow } from '../overworld/helpers'
import { PI_GUI1 } from '../palette/pi'
import { add_pi_permut } from '../palette/scenePalette'
import { draw_rect_, draw_text_, drawState } from '../rooms/draw'
import { goto_title_rm } from '../rooms/goto'
import { aud_play_sound } from '../sound/play'
import { get_audio_theme_track } from '../sound/theme'
import { viewH, viewW, viewXL, viewYC, viewYT } from '../view/camera'

const STATE_IDLE = 0
const STATE_AREA = 1
const STATE_RM1 = 2
const STATE_EXIT = 3
const STATE_GOTO = 4

export class Dev_RmWarper extends Instance {
  readonly objectName = 'Dev_RmWarper'
  /** `<persistent>-1</persistent>` in ZALiA's object definition — survives a room change. */
  override readonly persistent = true
  depth = DEPTH_SURFACE - 1
  readonly STATE_IDLE = STATE_IDLE
  readonly STATE_AREA = STATE_AREA
  readonly STATE_RM1 = STATE_RM1
  readonly STATE_EXIT = STATE_EXIT
  readonly STATE_GOTO = STATE_GOTO
  state = STATE_IDLE
  timer = 0
  readonly DUR1 = 0x20
  readonly DUR2 = 0x08
  SND_OPEN_APP: string | 0 = 0
  SND_OPTION_CHANGE1: string | 0 = 0
  SND_OPTION_CHANGE2: string | 0 = 0
  SND_OPTION_CHANGE_UP: string | 0 = 0
  SND_OPTION_CHANGE_DWN: string | 0 = 0
  SND_OPTION_SELECT1: string | 0 = 0
  SND_OPTION_CONFIRM: string | 0 = 0
  SND_OPTION_CANCEL: string | 0 = 0
  // text layout
  readonly Text_CHAR_W = 8
  readonly TEXT_PAD_X = 0x01 * 8
  readonly TEXT_PAD_Y = 0x01 * 8
  readonly TEXT_DIST_Y = 0x01 * 8 + 0x01 * 8 // vertical dist between 2 options
  readonly TEXT_DRAWAREA_PAD_X = 0x10 << 3
  readonly TEXT_DRAWAREA_PAD_Y = 0x04 << 3
  // selection
  area_idx = 0
  AREA_COUNT = 0
  dl_area = new DsList<string>()
  rm_id = 0x00
  readonly RmID_COUNT = 0x100
  readonly ExitType_COUNT = 0x05
  readonly ExitID_COUNT = 0x05 << 4
  ExitID = 0
  exit_idx = 0
  dl_ExitID = new DsList<number>()
  dl_Rm_ExitIDs = new DsList<number>()
  // draw areas (filled in Create)
  Text_DrawArea_X = 0
  AreaID_DrawArea_W = 0
  AreaID_DrawArea_H = 0
  AreaID_DrawArea_H_ = 0
  AreaID_DrawArea_X = 0
  RmID_DrawArea_W = 0
  RmID_DrawArea_H_ = 0
  RmID_DrawArea_X = 0
  ExitID_DrawArea_W = 0
  ExitID_DrawArea_H_ = 0
  ExitID_DrawArea_X = 0
  ExitName_goto: string = REEN_DEFAULT
  readonly ExitName_CLM = 0x02
  readonly ExitName_ROW = 0x03

  constructor() {
    super()
    Dev_RmWarper_Create(this)
  }
  step(): void {
    Dev_RmWarper_Step(this)
  }
  draw(): void {
    Dev_RmWarper_Draw(this)
  }
  roomStart(): void {
    Dev_RmWarper_Room_Start(this)
  }
}

/** `Dev_RmWarper_Create()` */
export function Dev_RmWarper_Create(self: Dev_RmWarper): void {
  self.SND_OPEN_APP = get_audio_theme_track(dk_OpenGUI)
  self.SND_OPTION_CHANGE1 = get_audio_theme_track(dk_CursorSpellMenu)
  self.SND_OPTION_CHANGE2 = get_audio_theme_track(dk_CursorFileSelect)
  self.SND_OPTION_CHANGE_UP = self.SND_OPTION_CHANGE1
  self.SND_OPTION_CHANGE_DWN = self.SND_OPTION_CHANGE1
  self.SND_OPTION_SELECT1 = get_audio_theme_track(dk_ItemDrop)
  self.SND_OPTION_CONFIRM = get_audio_theme_track(STR_Sword + STR_Beam)
  self.SND_OPTION_CANCEL = get_audio_theme_track(dk_StrikeEnemy)
  self.state = STATE_IDLE
  self.timer = 0
  self.area_idx = 0

  self.dl_area.clear()
  for (let _i = 0; _i < g.dl_AREA_NAME.size; _i++) self.dl_area.add(String(g.dl_AREA_NAME.get(_i)))
  self.dl_area.add(Area_Title)
  self.AREA_COUNT = self.dl_area.size

  self.rm_id = 0x00
  self.ExitID = 0
  self.exit_idx = 0

  self.dl_ExitID.clear()
  for (let _i = 0; _i < self.ExitID_COUNT; _i++) {
    let _val = (_i >> 4) & 0xf //   0,  1,  2,  3,  4
    _val = 0x08 << _val // $08,$10,$20,$40,$80
    _val &= 0xf0 // $00,$10,$20,$40,$80
    _val |= _i & 0xf
    self.dl_ExitID.set(_i, _val)
  }
  self.dl_Rm_ExitIDs.clear()

  self.Text_DrawArea_X = ((viewW() >> 2) >> 3) << 3 // round down to 8
  self.AreaID_DrawArea_W = AreaID_LEN * self.Text_CHAR_W
  self.AreaID_DrawArea_H = self.TEXT_DIST_Y * self.AREA_COUNT - self.TEXT_PAD_Y
  self.AreaID_DrawArea_H_ = self.AreaID_DrawArea_H >> 1
  self.AreaID_DrawArea_X = self.Text_DrawArea_X

  self.RmID_DrawArea_W = 0x02 * self.Text_CHAR_W
  self.RmID_DrawArea_H_ = (self.TEXT_DIST_Y * self.RmID_COUNT - self.TEXT_PAD_Y) >> 1
  self.RmID_DrawArea_X = self.AreaID_DrawArea_X + self.AreaID_DrawArea_W + self.TEXT_PAD_X

  self.ExitID_DrawArea_W = 0x02 * self.Text_CHAR_W
  self.ExitID_DrawArea_H_ = (self.TEXT_DIST_Y * self.ExitID_COUNT - self.TEXT_PAD_Y) >> 1
  self.ExitID_DrawArea_X = self.RmID_DrawArea_X + self.RmID_DrawArea_W + self.TEXT_PAD_X

  self.ExitName_goto = REEN_DEFAULT
}

/** `Dev_RmWarper_Room_Start()` — seed the picker from the room the PC just entered. */
export function Dev_RmWarper_Room_Start(self: Dev_RmWarper): void {
  self.state = STATE_IDLE
  self.timer = 0
  self.area_idx = 0
  self.rm_id = 0
  self.ExitID = 0
  self.exit_idx = 0
  if (g.room_type !== 'A') return
  const _SCENE_NAME = String(val(f.dm_rando.get(g.rm_name + STR_Scene + STR_Name), g.rm_name))
  const _AREA_NAME = _SCENE_NAME.substring(0, AreaID_LEN)
  const _RM_NUM = str_hex(_SCENE_NAME.substring(AreaID_LEN, AreaID_LEN + 2))
  self.area_idx = g.dl_AREA_NAME.findIndex(_AREA_NAME)
  self.rm_id = _RM_NUM // $00-FF
  if (instanceExists(g.exit_enter)) {
    self.ExitID = (g.exit_enter as Exit).exitNum // $00-0F, $10-1F, $20-2F, $40-4F, $80-8F
  } else {
    for (const e of instancesNamed('Exit') as Generator<Exit>) {
      self.ExitID = e.exitNum
      break
    }
  }
  self.exit_idx = bitNum((self.ExitID & 0xff) >> 4) // 0,1,2,3,4
  self.exit_idx = (self.exit_idx << 4) | (self.ExitID & 0xf) // $00-4F
}

/** `Dev_RmWarper_update_1a(rm name)` — populates `dl_Rm_ExitIDs` with the exits this room has. */
export function Dev_RmWarper_update_1a(self: Dev_RmWarper, _RM_NAME: string): void {
  self.dl_Rm_ExitIDs.clear()
  for (let _i = 0; _i < 5; _i++) {
    // each exit type
    for (let _j = 0; _j < 0x10; _j++) {
      // each exit id
      let _exit_id = 0x08 << _i
      _exit_id &= 0xf0 // $00,$10,$20,$40,$80
      _exit_id |= _j & 0xf
      const _exit_name = _RM_NAME + hex_str(_exit_id)
      if (g.dm_rm.get(_exit_name + STR_Num) === undefined) break // No more exits for _i's exit type
      self.dl_Rm_ExitIDs.add(_exit_id)
    }
  }
}

/** `Dev_RmWarper_update_2a(difference)` — the next/previous existing exit id. */
export function Dev_RmWarper_update_2a(self: Dev_RmWarper, _DIFF: number): number {
  const _COUNT = self.dl_Rm_ExitIDs.size
  if (!_COUNT) return self.ExitID
  let _idx = Math.min(Math.max(self.dl_Rm_ExitIDs.findIndex(self.ExitID), 0), _COUNT - 1)
  _idx = _idx + _COUNT + _DIFF
  _idx = _idx % _COUNT
  return self.dl_Rm_ExitIDs.get(_idx) as number
}

/** `Dev_RmWarper_update_3a()` — rebuilds the `<Area><rm><exit>` name shown in the corner. */
export function Dev_RmWarper_update_3a(self: Dev_RmWarper): void {
  self.ExitName_goto = String(self.dl_area.get(self.area_idx)) + hex_str(self.rm_id) + hex_str(self.ExitID)
}

/** `Dev_RmWarper_Step()` */
export function Dev_RmWarper_Step(self: Dev_RmWarper): void {
  // 2024/09/12. Anyone can use. Useful if the player is making custom content and needs to get somewhere fast.
  if (g.room_type !== 'A' || g.gui_state !== g.gui_state_PAUSE) {
    self.state = STATE_IDLE
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (self.timer) self.timer--

  // ---- UPDATE INPUT -------------------------------------------------------------------------
  const _QUAL_STATE = isVal(self.state, STATE_AREA, STATE_RM1, STATE_EXIT)
  const _xbox_ap = input.Jump_pressed
  const _xbox_bp = input.Other1_pressed // GP_Other1_pressed (xbox B)
  const _xbox_ah = input.Jump_held

  let _HORZ_QUAL = 0
  let _VERT_QUAL = 0
  if (_QUAL_STATE && !self.timer && input.heldHV) {
    _HORZ_QUAL = gui_tmr_cursor_h()
    _VERT_QUAL = gui_tmr_cursor_v()
  }

  // Hold SELECT && press xbox-Y. ZALiA's condition is gamepad-only, which contradicts the 2024-09-12
  // "Anyone can use" comment on a keyboard-and-gamepad game, so `F2` opens it too (the guards above
  // already restrict this to the pause menu of a type-A room). `Input.Magic_*` is the NES SELECT action,
  // so the SELECT half also accepts the keyboard — ZALiA's own commented-out alternative on line 66.
  const _SELECT_HELD = input.gamepad_button_check('gp_select') || !!input.Magic_held
  const _RQST_OPEN_APP =
    (_SELECT_HELD && input.gamepad_button_check_pressed('gp_face4')) || keyboard_check_pressed('F2')

  // FWRD: FORWARD (RIGHT. state += 1) / BWRD: BACKWARD (LEFT. state -= 1)
  const _RQST_STATE_FWRD = !!_HORZ_QUAL && (!!input.Right_pressed || !!_xbox_ap)
  let _RQST_STATE_BWRD = !!_HORZ_QUAL && (!!input.Left_pressed || keyboard_check_pressed('vk_backspace'))
  _RQST_STATE_BWRD ||= !!_HORZ_QUAL && _xbox_bp && isVal(self.state, STATE_RM1, STATE_EXIT)

  let _CANCEL = keyboard_check_pressed('vk_escape') || _RQST_OPEN_APP
  _CANCEL ||= _xbox_bp && self.state === STATE_IDLE
  const _CONFIRM = !!input.Pause_held || keyboard_check_pressed('vk_enter')

  // -------------------------------------------------------------------------------------------
  if (_QUAL_STATE && !self.timer) {
    if (_CONFIRM) {
      if (self.dl_area.get(self.area_idx) === Area_Title) {
        self.state = STATE_IDLE
        goto_title_rm()
        return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
      }
      Dev_RmWarper_update_3a(self)
      if (g.dm_rm.get(self.ExitName_goto + STR_Num) !== undefined) {
        g.exit_leave = Exit_construct(EXIT_NAME_GAME_START) // triggers rm change
        const e = g.exit_leave as Exit
        e.goToExitName = self.ExitName_goto
        // GML sliced `RmName_LEN-1, 2` — the *room* digits, not the exit's (the field is write-only
        // in ZALiA so it never showed). Uses the exit digits, matching `Exit_construct`.
        e.goToExitNum = str_hex(self.ExitName_goto.slice(-2))
        e.goToRoom = self.ExitName_goto.substring(0, RmName_LEN)
        aud_play_sound(self.SND_OPTION_CONFIRM)
        aud_play_sound(self.SND_OPTION_SELECT1)
        self.state = STATE_IDLE
        return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
      }
    }

    if (_CANCEL || (_xbox_bp && self.state === STATE_IDLE)) {
      aud_play_sound(self.SND_OPTION_CANCEL)
      aud_play_sound(get_audio_theme_track(STR_PC + STR_Damage))
      self.state = STATE_IDLE
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }

    if (_RQST_STATE_FWRD || _RQST_STATE_BWRD) {
      aud_play_sound(self.SND_OPTION_CHANGE2)
      self.timer = self.DUR2 // Delay any input reaction in next state.
      const _DIR = sign_(+_RQST_STATE_FWRD)
      self.state += _DIR
      if (!isVal(self.state, STATE_AREA, STATE_RM1, STATE_EXIT)) {
        if (_DIR > 0) self.state = STATE_AREA
        else self.state = STATE_EXIT
      }
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }

    if (_VERT_QUAL) {
      const _DIR = sign_(bit_dir(_VERT_QUAL & 0xc)) //  1: DWN pressed,  -1: UP pressed
      switch (self.state) {
        case STATE_AREA: {
          self.area_idx = (self.area_idx + self.AREA_COUNT + _DIR) % self.AREA_COUNT
          for (let _i = 0; _i < self.RmID_COUNT; _i++) {
            self.rm_id = _i
            const _rm_name = String(self.dl_area.get(self.area_idx)) + hex_str(self.rm_id)
            if (g.dm_rm.get(_rm_name + STR_Rm + STR_Num + STR_Game) !== undefined) {
              Dev_RmWarper_update_1a(self, _rm_name) // populates dl_Rm_ExitIDs
              if (self.dl_Rm_ExitIDs.size) self.ExitID = self.dl_Rm_ExitIDs.get(0) as number
              break // _i
            }
          }
          break
        }
        case STATE_RM1: {
          const _diff = _xbox_ah ? 0x08 * _DIR : _DIR
          const _area = String(self.dl_area.get(self.area_idx))
          let _rm_name = _area + hex_str(self.rm_id)
          const _count = Number(val(g.dm_rm.get(_area + STR_Rm + STR_Count))) // area rm count
          let _num = Number(val(g.dm_rm.get(_rm_name + STR_Rm + STR_Num + STR_Area)))
          _num = _num + _count - 1
          _num = (_num + _diff) % _count
          _num++
          self.rm_id = Number(val(g.dm_rm.get(_area + STR_Rm + hex_str(_num) + STR_ID), self.rm_id))
          _rm_name = _area + hex_str(self.rm_id)
          Dev_RmWarper_update_1a(self, _rm_name) // populates dl_Rm_ExitIDs
          if (self.dl_Rm_ExitIDs.size) self.ExitID = self.dl_Rm_ExitIDs.get(0) as number
          break
        }
        case STATE_EXIT: {
          const _diff = _xbox_ah ? 0x08 * _DIR : _DIR
          self.ExitID = Dev_RmWarper_update_2a(self, _diff)
          break
        }
      }
      if (_DIR > 0)
        aud_play_sound(self.SND_OPTION_CHANGE_DWN) // down pressed
      else aud_play_sound(self.SND_OPTION_CHANGE_UP) // up pressed
    }
  }

  // -------------------------------------------------------------------------------------------
  if (self.state === STATE_IDLE && !self.timer) {
    if (_RQST_OPEN_APP && g.room_type === 'A' && g.gui_state === g.gui_state_PAUSE && can_update_frame()) {
      const _SCENE_NAME = String(val(f.dm_rando.get(g.rm_name + STR_Scene + STR_Name), g.rm_name))
      const _AREA_NAME = _SCENE_NAME.substring(0, AreaID_LEN)
      const _RM_NUM = str_hex(_SCENE_NAME.substring(AreaID_LEN, AreaID_LEN + 2))
      self.area_idx = Math.max(0, g.dl_AREA_NAME.findIndex(_AREA_NAME))
      self.rm_id = _RM_NUM
      const _rm_name = String(self.dl_area.get(self.area_idx)) + hex_str(self.rm_id)
      if (f.reen === undefined || area_is_ow(f.reen)) {
        for (const e of instancesNamed('Exit') as Generator<Exit>) {
          self.ExitID = e.exitNum
          break
        }
      } else {
        self.ExitID = str_hex(String(f.reen).slice(-2))
      }
      self.exit_idx = bitNum((self.ExitID >> 4) & 0xf) // 0,1,2,3,4
      self.exit_idx = (self.exit_idx << 4) | (self.ExitID & 0xf) // $00-4F
      Dev_RmWarper_update_1a(self, _rm_name) // populates dl_Rm_ExitIDs
      self.ExitID = Dev_RmWarper_update_2a(self, 0)
      aud_play_sound(self.SND_OPEN_APP)
      self.timer = self.DUR1
      self.state = STATE_AREA
    }
  }
}

/** `Dev_RmWarper_Draw()` — three scrolling columns (area, room id, exit id) over a dimmed screen. */
export function Dev_RmWarper_Draw(self: Dev_RmWarper): void {
  if (isVal(self.state, STATE_IDLE, STATE_GOTO)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const depthCopy = drawState.depth
  drawState.depth = self.depth
  const _VIEW_XL = viewXL()
  const _VIEW_YT = viewYT()
  const _DRAWAREA_H = viewH() - (self.TEXT_DRAWAREA_PAD_Y << 1)
  const _DRAWAREA_Y = _VIEW_YT + self.TEXT_DRAWAREA_PAD_Y

  const _PI1 = PI_GUI1 // HMS.     Current option
  const _PI2 = add_pi_permut(_PI1, 'BWRGKYMC', 'Dev_RmWarper_Draw() pi-2') // SHM. NOT current option
  const _PI3 = add_pi_permut(_PI1, 'RBWGMKYC', 'Dev_RmWarper_Draw() pi-3') // MSH. Rm/Exit doesn't exist.

  // Shade the screen for the text.
  draw_rect_(c_black, viewXL(), viewYT(), viewW(), viewH(), 0.75)

  // Current exit pick in the upper left of the view.
  draw_text_(_VIEW_XL + (self.ExitName_CLM << 3), viewYT() + (self.ExitName_ROW << 3), self.ExitName_goto)

  //  AREA ------------------------------------------------------------
  let _x = viewXL() + self.AreaID_DrawArea_X
  let _DrawArea_yt = viewYC() - self.AreaID_DrawArea_H_
  for (let _i = 0; _i < self.AREA_COUNT; _i++) {
    const _y = _DrawArea_yt + _i * self.TEXT_DIST_Y
    if (!hINh(_y, 8, _DRAWAREA_Y, _DRAWAREA_H)) continue
    let _idx = self.area_idx + self.AREA_COUNT - (self.AREA_COUNT >> 1)
    _idx = (_idx + _i) % self.AREA_COUNT
    draw_text_(_x, _y, String(self.dl_area.get(_idx)), -1, _idx === self.area_idx ? _PI1 : _PI2)
  }

  //  RM ID ------------------------------------------------------------
  _x = viewXL() + self.RmID_DrawArea_X
  _DrawArea_yt = viewYC() - self.RmID_DrawArea_H_
  for (let _i = 0; _i < self.RmID_COUNT; _i++) {
    const _y = _DrawArea_yt + _i * self.TEXT_DIST_Y
    if (!hINh(_y, 8, _DRAWAREA_Y, _DRAWAREA_H)) continue
    let _idx = self.rm_id + self.RmID_COUNT - (self.RmID_COUNT >> 1)
    _idx = (_idx + _i) % self.RmID_COUNT
    let _pi = _idx === self.rm_id ? _PI1 : _PI2
    const _mapkey = String(self.dl_area.get(self.area_idx)) + hex_str(_idx)
    if (g.dm_rm.get(_mapkey + STR_Rm + STR_Num + STR_Game) === undefined) _pi = _PI3 // rm does NOT exist
    draw_text_(_x, _y, hex_str(_idx), -1, _pi)
  }

  //  EXIT ID ------------------------------------------------------------
  _x = viewXL() + self.ExitID_DrawArea_X
  _DrawArea_yt = viewYC() - self.ExitID_DrawArea_H_
  for (let _i = 0; _i < self.ExitID_COUNT; _i++) {
    const _y = _DrawArea_yt + _i * self.TEXT_DIST_Y
    if (!hINh(_y, 8, _DRAWAREA_Y, _DRAWAREA_H)) continue
    let _idx = self.dl_ExitID.findIndex(self.ExitID)
    _idx = _idx + self.ExitID_COUNT - (self.ExitID_COUNT >> 1)
    _idx = (_idx + _i) % self.ExitID_COUNT
    _idx = self.dl_ExitID.get(_idx) as number
    let _pi = _idx === self.ExitID ? _PI1 : _PI2
    const _mapkey = String(self.dl_area.get(self.area_idx)) + hex_str(self.rm_id) + hex_str(_idx)
    if (g.dm_rm.get(_mapkey + STR_Num) === undefined) _pi = _PI3 // exit does NOT exist
    draw_text_(_x, _y, hex_str(_idx), -1, _pi)
  }

  // Dim the two columns that are not being edited.
  const _PAD = 2
  const _COLUMNS: [state: number, w: number, x: number][] = [
    [STATE_AREA, self.AreaID_DrawArea_W, self.AreaID_DrawArea_X],
    [STATE_RM1, self.RmID_DrawArea_W, self.RmID_DrawArea_X],
    [STATE_EXIT, self.ExitID_DrawArea_W, self.ExitID_DrawArea_X],
  ]
  for (let _i = _COLUMNS.length - 1; _i >= 0; _i--) {
    const [_state, _w0, _x0] = _COLUMNS[_i] as [number, number, number]
    if (self.state === _state) continue
    draw_rect_(c_black, viewXL() + _x0 - _PAD, viewYT(), _w0 + (_PAD << 1), viewH(), 0.7, false)
  }
  drawState.depth = depthCopy
}
