import { PAGE_H } from '@z2/data'
import { gmBool } from '../../nes/math8'
import { G, g } from '../../runtime/world'
import { wINw } from '../collision/geometry'
import { notPorted } from '../pending'
import { rm_restart } from '../room/index'

/** GML: update_out_of_bounds_fail_safe() */
export function update_out_of_bounds_fail_safe() {
  // GML `var` is function-scoped; locals hoisted here:
  let _DIST: any
  if (G.pc.state !== G.pc.state_NORMAL) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  _DIST = 0x10 << 3
  //var _DIST=$8<<3;
  if (!gmBool(wINw(G.pc.xl, G.pc.ww, -_DIST, g.rm_w + (_DIST << 1))) || G.pc.yt > g.rm_h + PAGE_H) {
    rm_restart()
  }
}
