/** GameObjectD leaf objects: platforms (class + script registration). */
import { registerObject, registerScripts } from '../registry'
import { PlatformA, PlatformB, PlatformCloud, PlatformRaft } from './classes'
import * as P from './platform'

export * from './classes'
export * from './deps'
export * from './platform'

export const platformScripts = {
  Platform_init_1: P.Platform_init_1,
  Platform_update_1a: P.Platform_update_1a,
  PlatformA_init_1: P.PlatformA_init_1,
  PlatformA_init_2: P.PlatformA_init_2,
  PlatformA_init3: P.PlatformA_init3,
  PlatformA_update: P.PlatformA_update,
  PlatformA_udp: P.PlatformA_udp,
  PlatformA_draw: P.PlatformA_draw,
  PlatformA_end: P.PlatformA_end,
  PlatformB_init_1: P.PlatformB_init_1,
  PlatformB_init_2: P.PlatformB_init_2,
  PlatformB_update: P.PlatformB_update,
  PlatformB_udp: P.PlatformB_udp,
  PlatformB_draw: P.PlatformB_draw,
  PlatformCloud_init1: P.PlatformCloud_init1,
  PlatformCloud_init2: P.PlatformCloud_init2,
  PlatformCloud_update: P.PlatformCloud_update,
  PlatformCloud_udp: P.PlatformCloud_udp,
  PlatformCloud_draw: P.PlatformCloud_draw,
  PlatformCloud_draw_1a: P.PlatformCloud_draw_1a,
  PlatformCloud_end: P.PlatformCloud_end,
  PlatformRaft_init_1: P.PlatformRaft_init_1,
  PlatformRaft_init_2: P.PlatformRaft_init_2,
  PlatformRaft_update: P.PlatformRaft_update,
  PlatformRaft_udp: P.PlatformRaft_udp,
  PlatformRaft_draw: P.PlatformRaft_draw,
}

export function registerPlatforms(): void {
  registerObject('PlatformA', PlatformA)
  registerObject('PlatformB', PlatformB)
  registerObject('PlatformCloud', PlatformCloud)
  registerObject('PlatformRaft', PlatformRaft)
  registerScripts(platformScripts as Record<string, (self: never) => unknown>)
}
registerPlatforms()
