  GRAV_ADD: any = undefined
  ShieldHB_IDX_HGH: any = undefined
  ShieldHB_IDX_LOW: any = undefined
  SwordHB_H: any = undefined
  SwordHB_W: any = undefined
  SwordHB_x_base: any = undefined
  SwordHB_y_base: any = undefined
  TERMINAL_VELOCITY: any = undefined
  attack_phase: any = undefined
