/** GML: ShadowBoss_udp() */
export function ShadowBoss_udp(self: ShadowLonk01) {
  if (gmBool(g.mod_ShadowBoss_DrawWithFairy) || !gmBool(pc_is_fairy())) {
    self.can_draw_self = true
    /// 9A77
    // ShadowBoss uses same code as PC, but I modded it because of
    // various unneccessary stuff and ShadowBoss won't draw if PC
    // is fairy.
    // 9A7F: JSR EC02
    self.draw_xoff = 0
    self.draw_yoff = 0
    // EC1E, EC40
    update_draw_xy(self)
    GO_set_sprite(self, PC_PLACEMENT_SPR)
    //GO_set_sprite(id,g.pc.dl_ShadowBoss_SPRITES.get(|behavior));
    self.behavior_at_udp = self.behavior
    if (gmBool((g.boss_stun_timer >> 1) & 0x01)) {
      self.palidx = G.PI_MOB_BLU // stun flash
    } else {
      self.palidx = self.palidx_def
    }
    GO_update_cam_vars(self) // MOD
    // EC7F
    PC_update_SwordHB_xy(self as never)
  }
}

/** GML: ShadowBoss_draw() */
export function ShadowBoss_draw(self: ShadowLonk01) {
  if (!gmBool(self.can_draw_self)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  draw_pc_skin(
    self.drawX,
    self.drawY,
    self.xScale,
    self.yScale,
    self.behavior_at_udp,
    false,
    1,
    1,
    self.palidx,
  )
}
