/** `FallingBlock_init2()` */
export function FallingBlock_init2(self: FaBlA): void {
  self.can_draw_self_exception = true
  GO_init_palidx(self, G.PI_BGR1)
  self.LAND_DEPTH = DEPTH_BG1
  self.facing_dir = 1
  self.vspd_grav = 2
  self.vspd = 0
  if (g.area_name === Area_PalcG) {
    self.ATTACK_LEVEL = 0x03
    self.attack_level = self.ATTACK_LEVEL
  }
}

/** `FallingBlock_update()` — ABE9 */
export function FallingBlock_update(self: FaBlA): void {
  self.stun_timer = 0
  if (self.counter) {
    // breaking apart. ABF2
    set_xlyt(self, self.xl, self.yt + 1)
    self.counter++
    if (self.counter < 0x11)
      update_EF11(self) // ABFD: JMP EF11
    else self.state = 0 // ABFA: JMP DD47
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // AC00: JSR DEBE: JSR DEC8
  updateY(self)
  // AC03: JSR EA32
  GO_update_cs(self)
  // MOD
  if (self.yt >= cam_yb_max() + 0x18) {
    GOB_despawn(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // AC06: JSR E677
  GOB_body_collide_pc_sword(self)
  if (self.pc_sword_collided_solid_body) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // AC09: JSR E4D9
  GOB_body_collide_pc_body_1a(self)
  // AC0C
  if (self.cs & (CS_BD1 | CS_SW1)) {
    if (self.cs & CS_BD1) enemy_collide_pc_body(self) // AC16: JSR E2EF
    // AC19
    aud_play_sound(get_audio_theme_track(dk_BlockBreak))
    self.counter = 1 // Start breaking process
  }
  // AC1F
  if (!(self.cs & 0x4)) {
    update_EF11(self) // ABFD: JMP EF11
  } else {
    // AC2C
    const _DEPTH_IDX = g.dl_TILE_DEPTHS.findIndex(self.LAND_DEPTH)
    const _CLM = self.xl >> 3
    const _ROW = self.yt >> 3
    const _TS = 'ts_Man_made_1a_WRB'
    const _TS_DATA = TSRC_BREAK1_A
    for (let _i = 0; _i < 4; _i++) {
      // each 8x8 tile of the block graphic
      const _x = (_CLM + (_i & 0x1)) << 3
      const _y = (_ROW + (_i > 0x1 ? 1 : 0)) << 3
      const _tsrc = str_hex(_TS_DATA, _i)
      tile_change_1a(
        self.LAND_DEPTH,
        _x,
        _y,
        _TS,
        _tsrc,
        TID_SOLID1,
        TID_BREAK1 + (_DEPTH_IDX << 8),
        TID_HIDE_1 & 0xf,
      )
    }
    // AC29: JSR DD47
    aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
    self.state = 0
  }
}

/** `FallingBlock_udp()` — EFD2 */
export function FallingBlock_udp(self: FaBlA): void {
  self.can_draw_self = true
  if (!self.counter) self.sprite = 'spr_Block_01a'
  else if (self.counter < 8) self.sprite = 'spr_Block_01b'
  else self.sprite = 'spr_Block_01c'
  self.palidx = self.palidx_def
  self.xScale = 1
}

/** `BlockB_end()` */
export function BlockB_end(self: BlckB): void {
  if (surface_exists(self.ChainLink_surf)) surface_free(self.ChainLink_surf)
}

/** `BlockB_init2()` — hanging/falling metal block */
export function BlockB_init2(self: BlckB): void {
  set_xlyt(self, round8(self.xl), round8(self.yt))
  GO_sprite_init(self, 'spr_Block_02a')
  self.can_draw_self_exception = true
  self.Chain_hang = false
  self.Chain_connected = true
  self.Chain_connected_prev = self.Chain_connected
  self.Chain_can_draw = false
  self.Chain_PI = G.PI_BGR4
  self.ChainLink_W = 8
  self.ChainLink_H = 8
  self.Chain_XL = self.x - (self.ChainLink_W >> 1)
  let _val = Math.trunc(cam_yt_min() / 8) - 1
  _val = find_row_solid(TID_SOLID1 | TID_ONEWY1, self.x >> 3, self.yt >> 3, -1, 0, _val)
  self.Chain_YT = _val * 8
  self.ChainLink_COUNT = Math.max(0, Math.trunc((self.yt - self.Chain_YT) / self.ChainLink_H))
  self.ChainLink_surf = -1
  GO_init_palidx(self, G.PI_BGR4)
  if (self.dk_spawn !== undefined) {
    GO_init_palidx(self, val(g.dm_spawn.get(self.dk_spawn + STR_pal_idx), self.palidx) as number)
    for (let _i = 1; _i <= 0x10; _i++) {
      const _data = g.dm_spawn.get(self.dk_spawn + STR_Data + hexStr(_i))
      if (_data === undefined) break
      if (String(_data).includes('_ChainHang')) self.Chain_hang = self.ChainLink_COUNT > 0
    }
  }
  GO_depth_init(self, DEPTH_BG1 - 1) // -1 so tile pal swap can work
  self.facing_dir = 1
  self.hspd = 0
  self.VSPD_MAX = 0x50
  self.vspd_grav = 2
  self.vspd = 0
  self.BODY_HB_IDX1 = 0x01 // $01: about +2,3 xy offsets, about 12x12
  self.BODY_HB_IDX2 = 0x66 // $66: 0 offsets, 16x16
  self.BodyHB_idx = self.BODY_HB_IDX2
  self.Fall_delay_DURATION = 3 // Give time for breaking block anim below.
  self.Fall_delay_timer = 0
  self.solid_type = TID_SOLID1
  add_to_solid_inst_list(self)
  // TID_HIDE_1: Hidden when rm is NOT lit.
  self.TID_HIDDEN = TID_HIDE_1 & 0xf
  // Change tiles to solid.
  setBlockSolid(self, TID_SOLID1)
}

function setBlockSolid(self: BlckB, tid: number): void {
  for (let _i = 0; _i < 4; _i++) {
    const _x = self.xl + ((_i & 0x1) << 3)
    const _y = self.yt + ((_i > 0x1 ? 1 : 0) << 3)
    tile_change_1a(0, _x, _y, -1, 0, tid)
  }
}

/** `BlockB_update()` */
export function BlockB_update(self: BlckB): void {
  const P = pc()
  const _CS4 = self.cs & 0x4
  GO_update_cs(self)
  if (self.Chain_hang) {
    if (self.Chain_connected_prev && !self.Chain_connected) self.Fall_delay_timer = self.Fall_delay_DURATION
  } else {
    if (_CS4 && !(self.cs & 0x4)) self.Fall_delay_timer = self.Fall_delay_DURATION
  }
  if (self.Fall_delay_timer) {
    self.Fall_delay_timer--
    if (!self.Fall_delay_timer && !self.Chain_hang) setBlockSolid(self, 0) // Starting to fall. Change tiles to non-solid.
  }
  self.BodyHB_idx = self.BODY_HB_IDX2
  if (!self.Fall_delay_timer && !(self.cs & 0x4)) {
    if (!self.Chain_hang || !self.Chain_connected) {
      updateY(self)
      if (self.vspd < 0x80 && self.vspd > self.VSPD_MAX) self.vspd = self.VSPD_MAX
      GO_update_cs(self)
      self.BodyHB_idx = self.BODY_HB_IDX1
      if (self.cs & 0x4) {
        // Landed!
        self.Chain_hang = false
        self.BodyHB_idx = self.BODY_HB_IDX2
        solid_clip_correction(self, false)
        self.vspd = 0
        setBlockSolid(self, TID_SOLID1) // Change tiles to solid.
        aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
      } else if (self.vspd >= 0x10) {
        GOB_body_collide_pc_body_1a(self)
        if (self.cs & CS_BD1 && P.yt + P.hh >= self.yt + 8) enemy_collide_pc_body(self)
      }
    }
  }
  if (self.yt >= cam_yb_max() + 0x18) {
    GOB_despawn(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  update_EF11(self)
  update_body_hb_1a(self) // body hb is the "solid" area of the object
  self.Chain_connected_prev = self.Chain_connected
}

/** `BlockB_udp()` */
export function BlockB_udp(self: BlckB): void {
  self.can_draw_self = tile_visibility(self.TID_HIDDEN)
  self.Chain_can_draw = self.can_draw_self && self.Chain_hang && self.Chain_connected
  self.xScale = 1
}

/** `BlockB_draw()` — the chain is a small surface of two tileset parts, drawn per link. */
export function BlockB_draw(self: BlckB): void {
  if (self.Chain_hang && self.Chain_connected) {
    if (!surface_exists(self.ChainLink_surf)) {
      // Create surface: two 8x8 tileset parts side by side, offset -4 (ZALiA `draw_background_part`)
      const s = surface_create(self.ChainLink_W, self.ChainLink_H)
      self.ChainLink_surf = s
      surface_set_target(s)
      const _XL = -4
      draw_background_part('ts_Man_made_1a_WRB', 0x5 << 3, 0x1 << 3, 8, 8, _XL, 0)
      draw_background_part('ts_Man_made_1a_WRB', 0x6 << 3, 0x1 << 3, 8, 8, _XL + 8, 0)
      surface_reset_target()
    }
    if (self.Chain_can_draw) {
      pal_swap_set(self.Chain_PI)
      const prev = drawState.depth
      drawState.depth = self.depth
      for (let _i = 0; _i < self.ChainLink_COUNT; _i++)
        draw_surface(self.ChainLink_surf, self.Chain_XL, self.Chain_YT + self.ChainLink_H * _i)
      drawState.depth = prev
      pal_swap_reset()
    }
  }
  GameObjectB_draw_2(self)
}

/** `Spawner_FallingBlock_init2()` */
export function Spawner_FallingBlock_init2(self: Spawner_FallingBlock): void {
  self.is_active = true
  for (let _i = g.dg_spawn_prio.width - 1; _i >= 0; _i--) {
    if (g.dg_spawn_prio.get(_i, 1) === 'Kakusu014') {
      self.is_active = false // Kakusu014 controls when active
      break
    }
  }
  self.SPAWN_OBJ = 'FaBlA'
  self.SPAWNED_MAX = 6 // 6: OG
  switch (self.ver) {
    case 1: {
      self.CLMS = 0xa // OG: $A
      // OG spawn_x = $1B0. This should allow any spawn_x while keeping OG logic
      self.GRID_XL = ((self.xl >> 4) << 4) - 0xb0 + (0x100 - (self.CLMS << 4))
      break
    }
    case 2: {
      self.CLMS = 0xa // Number of block clms
      if (self.dk_spawn !== undefined) {
        for (let _i = 0x1; _i <= 0xf; _i++) {
          const _val = val(g.dm_spawn.get(self.dk_spawn + STR_Data + hexStr(_i)))
          if (typeof _val === 'string') {
            const _pos = _val.indexOf(STR_Clms)
            if (_pos >= 0) {
              self.CLMS = str_hex(_val.substring(_pos + STR_Clms.length))
              break
            }
          }
        }
      }
      self.CLMS = Math.min((g.rm_w >> 4) - 1, Math.max(0x1, self.CLMS))
      let _XL = self.xl >> 4
      _XL = Math.min((g.rm_w >> 4) - self.CLMS, Math.max(0, _XL))
      _XL = _XL << 4
      self.GRID_XL = _XL // Left edge of left most block clm
      set_xlyt(self, self.GRID_XL, self.yt)
      // So that sprite_index is less than CLMS width & centered w/in the CLMS
      GO_set_sprite_index(self, 'spr_Placement_01x01')
      self.xScale = self.CLMS << 4
      self.yScale = 0x10
      const _PAD = 0x2
      if (self.CLMS > _PAD << 1) {
        set_xlyt(self, self.GRID_XL + (_PAD << 4), self.yt)
        self.xScale -= (_PAD << 1) << 4
      } else if (self.CLMS > _PAD) {
        set_xlyt(self, self.GRID_XL + (0x1 << 4), self.yt)
        self.xScale = (self.CLMS >> 1) << 4
      }
      self.image_xscale = self.xScale
      self.image_yscale = self.yScale
      // So ocs will be accurate.
      self.ww = self.xScale
      self.hh = self.yScale
      self.ww_ = self.ww >> 1
      self.hh_ = self.hh >> 1
      break
    }
  }
}

/** `Spawner_FallingBlock_update()` — AB98 */
export function Spawner_FallingBlock_update(self: Spawner_FallingBlock): void {
  // ver 1(OG) w is $10 at 6th(out of 10) clm of block grid
  if (!self.is_active || !ocsH1(self) || g.counter1 & 0xf) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  let _SPAWNED_MAX = self.SPAWNED_MAX
  if (self.ver === 1) {
    // MOD. Simulate OG spawn rate
    _SPAWNED_MAX = self.SPAWNED_MAX - instance_number(GameObjectB)
    _SPAWNED_MAX = Math.max(4, _SPAWNED_MAX)
  } else {
    _SPAWNED_MAX = self.SPAWNED_MAX - 1 // 12/10/06: Trying to lessen falling rate
  }
  let _count = 0
  const blocks: GameObject[] = []
  for (const o of world.instances) {
    if (!o.exists) continue // GM's `with(Obj)` skips instances destroyed earlier this frame
    const b = o as GameObject
    if (b.objectName === self.SPAWN_OBJ) {
      blocks.push(b)
      _count += b.state !== 0 ? 1 : 0
    }
  }
  if (_count >= _SPAWNED_MAX) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const _Y1 = ((viewYT() + 0x18) >> 4) << 4
  const _Y2 = viewYT() - 0x10 // MOD
  for (let _i = 0; _i < _SPAWNED_MAX; _i++) {
    // Number of chances to spawn a block this frame.
    if (self.ver === 2 && world.irandom(0xf) < 0x6) continue // Simulate OG.
    let _x: number
    if (self.ver === 1) {
      // $F0-$60 = $90. Means 10 clms(0-9) of falling blocks starting at $100 + rand val
      _x = (g.dl_RandomOG.get(1 + _i) as number) & 0xf0 // must be >= ($100-(CLMS<<4)). (OG: $60). $60-F0
      _x -= 0x100 - (self.CLMS << 4) // OG: x -= ($100-$A0). (OG: $60)
      if (_x < 0) continue // if rand was out of range, do NOT spawn
    } else {
      _x = world.irandom(self.CLMS - 1) << 4
    }
    if (_x >> 3 < 0 || _x >> 3 > G.dg_solid_w - 1) continue
    _x += self.GRID_XL
    let _c1: unknown = G.dg_solid.get(_x >> 3, _Y1 >> 3)
    if (!_c1) _c1 = G.dg_solid.get(_x >> 3, (_Y1 >> 3) + 2) && collideRect(_x, _Y2, 0x10, 0x30, blocks)
    if (_c1) continue // MOD: bc OG would've spawned one just to immediatley de-spawn it.
    const _y = _Y2 // MOD
    const b = GameObject_create(_x, _y - 1, self.SPAWN_OBJ, 1)
    if (b) {
      b.is_from_spawner = true
      b.vspd = 0x10
      b.counter = 0
    }
    break // Spawn only 1 every x frames
  }
}
