/** Girubokku (`GiruA`) — the flying eye that opens. Ported from `Girubokku_init2/update/udp.gml`. */
import { CS_BD1, DEPTH_FLYER, ITM_SWRD } from '@z2/data'
import { G } from '../../../../../../runtime/world'
import { GOB_shield_collision_1a } from '../../../../../collision/gob'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { Enemy } from '../../../../classes'
import { dir_to_pc } from '../../../../go/misc'
import { updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_depth_init } from '../../../../go/sprite'
import { fp } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2, update_EF11 } from '../../../GameObjectB'
import { rand } from '../iron_knuckle/common'

export class GiruA extends Enemy {
  readonly objectName = 'GiruA' as const
}

/** `Girubokku_init2()` */
export function Girubokku_init2(self: GiruA): void {
  self.dl_sprites?.set(1, 'spr_Girubokku2')
  self.dl_sprites?.set(0, 'spr_Girubokku1') // 1: eye open
  GO_init_palidx(self, G.PI_MOB_RED)
  GO_depth_init(self, DEPTH_FLYER)
  self.ShieldHB_IDX = 6
  self.ShieldHB_idx = self.ShieldHB_IDX // 0444,X
}

/** `Girubokku_update()` */
export function Girubokku_update(self: GiruA): void {
  // 98BC: JSR D6C1
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // 98BF
  if (!self.timer) {
    // 98C7
    if (self.counter & 0x20) {
      if (self.counter & 0x40) self.vspd = -8 & 0xff
      else self.vspd = 8 & 0xff
      updateY(self)
    }
    // 98DE
    self.counter = (self.counter + 1) & 0xff
    if (!(self.counter & 0x3f)) self.facing_dir = dir_to_pc(self)
    self.hspd = (8 * self.facing_dir) & 0xff
    updateX(self)
    update_EF11(self)
    // 98FB: JSR E617
    if (!GOB_shield_collision_1a(self) || fp().items & ITM_SWRD) {
      // if pc sword did NOT collide w/ GOB body, or lvl2 sword can pierce
      GOB_update_2(self)
      // 9901.  !(rand()&$1F): 1/32 chance
      if (!(rand(self) & 0x1f)) self.timer = 0x3f // eye open timer
    }
  } else {
    // 98C4: JMP DE40.  eye open
    GOB_update_2(self)
  }
}

/** `Girubokku_udp()` */
export function Girubokku_udp(self: GiruA): void {
  self.can_draw_self = true
  if (self.timer & 0x7f)
    self.sprite = self.dl_sprites?.get(0) ?? 0 // eye open
  else self.sprite = self.dl_sprites?.get(1) ?? 0
}

export function registerGirubokku(): void {
  registerObject('GiruA', GiruA)
  registerScripts({ Girubokku_init2, Girubokku_update, Girubokku_udp })
}
registerGirubokku()
