export class GeldA extends Enemy {
  readonly objectName: 'GeldA' | 'GlzmA' = 'GeldA'
  SEGMENT_SPR = 'spr_Geldarm2'
  HEAD_SPR = 'spr_Geldarm1'
  SEGMENTS = 5 // 5: OG
  HEAD_DRAW_YOFF = 0
  SEGMENT_OVERLAP = 3 // Amt each segment overlaps eachother (fully unscrunched).
  GROUND_Y = 0
  isIdle = true // 00AF,X. 1: fully unscrunched, 0: all else
  MIN_Y = 0
  MAX_Y = 0 // 0081,X
  DIFF_DW = 1
  DIFF_UP = -2
  scrunch_dir = 0 // 0060,X schrunch state. idle 0,  down +1,  up -2,
  sway_dir = -1
  addOneY_cnt = 0
  segmentYOff = 0
  canDraw_segments = 1
  canDrawScrunchHB = true
  SCRUNCH_W = 8 // hb w
  scrunch_h = 0 // hb h
  scrunchX1 = 0 // hb x
  scrunchY1 = 0 // hb y
}

/** `Geldarm_init2()` */
export function Geldarm_init2(self: GeldA): void {
  const g = gp()
  const p = pp()
  if (
    self.dk_spawn !== undefined &&
    fp().dm_rando.get(
      STR_Randomize + STR_Enemy + STR_Spawn + self.dk_spawn + STR_Spawn + STR_Datakey + STR_Randomized,
    ) !== undefined
  ) {
    GO_depth_init(self, DEPTH_BG4 + 1) // attempting to stop from hiding behind tile graphics in enemy rando
  } else GO_depth_init(self, DEPTH_BG6 + 1)
  if (gmBool(g.dungeon_num)) {
    for (let _i = g.dl_TILE_DEPTH_NAMES.size - 1; _i >= 0; _i--) {
      const _dk = g.dl_TILE_DEPTH_NAMES.get(_i) as string // "BG01, BG02, ..."
      const _depth = g.dm_TILE_DEPTH.get(_dk) as number | undefined
      const _layer_name = g.dm_tile_file?.get?.(_dk + STR_Depth + STR_Layer + STR_Name) as string | undefined
      if (_depth !== undefined && _layer_name !== undefined && String(_layer_name).includes('PILLAR')) {
        GO_depth_init(self, _depth - 1)
        break
      }
    }
  }
  self.SEGMENT_SPR = 'spr_Geldarm2'
  self.HEAD_SPR = 'spr_Geldarm1'
  self.dl_sprites?.set(0, 'spr_Placement_08x16')
  // So the shadow color is black
  const _val = color_str(p.C_BLK1)
  let _pos = PAL_BASE_COLOR_ORDER.indexOf('B')
  _pos *= PAL_CHAR_PER_COLOR
  _pos += get_pal_pos(self.palidx_def)
  change_pal(strReplaceAt(p.pal_rm_new, _pos, _val.length, _val))
  self.SEGMENTS = 5 // 5: OG
  self.SEGMENTS = 4 + (rand(self) & 0x3) + (self.update_idx & 0x1) // 4-7
  self.HEAD_DRAW_YOFF = 0
  self.SEGMENT_OVERLAP = 3
  // FIXED: was hard-coded 8; `spr_Geldarm2` is 8x16 (`sprites/spr_Geldarm2.sprite.gmx`), and GML reads
  // `sprite_get_height(SEGMENT_SPR)`. At 8 the worm was built a third of its height, spawning at the
  // wrong Y with far too little scrunch travel (and Gellzem inherits both).
  const _SEGMENT_H = sprite_get_height('spr_Geldarm2')
  let _HEIGHT_MAX = self.SEGMENTS * _SEGMENT_H + _SEGMENT_H // +1 for head
  _HEIGHT_MAX -= self.SEGMENTS * self.SEGMENT_OVERLAP
  _HEIGHT_MAX-- // In OG the bottom 2 segments are overlapping by 1 extra pixel
  self.GROUND_Y = self.spawn_yt + self.hh
  self.GROUND_Y = get_ground_y(self.x, self.GROUND_Y - 8, 1, self.GROUND_Y, TID_SOLID1 | TID_ONEWY1)
  set_xlyt(self, self.xl, self.GROUND_Y - _HEIGHT_MAX)
  self.facing_dir = dir_to_pc_1(self)
  self.isIdle = true
  self.MIN_Y = self.yt
  self.MAX_Y = self.MIN_Y + (_HEIGHT_MAX - _SEGMENT_H) // 0081,X
  self.DIFF_DW = 1
  self.DIFF_UP = -2
  self.scrunch_dir = 0
  self.sway_dir = -1
  self.xScale = -1
  self.addOneY_cnt = 0
  self.segmentYOff = 0
  self.canDraw_segments = 1
  self.canDrawScrunchHB = true
  self.SCRUNCH_W = 8
  self.scrunch_h = 0
  self.scrunchX1 = 0
  self.scrunchY1 = 0
  Geldarm_update_scrunchHB(self)
}

/** `Geldarm_update_scrunchHB()` */
export function Geldarm_update_scrunchHB(self: GeldA): void {
  self.scrunch_h = self.MAX_Y - self.yt
  self.scrunchX1 = self.xl
  self.scrunchY1 = self.yt + 8
}

/** `Geldarm_update()` */
export function Geldarm_update(self: GeldA): void {
  const g = gp()
  self.canDrawScrunchHB = false
  // 9BB5
  if (self.scrunch_dir !== 0) {
    // if NOT fully unscrunched. scrunch_dir: 1 DOWN (true), -2 UP (false in GML truthiness)
    if (gmBool(self.scrunch_dir) || !self.timer) {
      // 9BCA
      if (self.SEGMENTS > 5 && g.counter1 & 0x1) set_xy(self, self.x, self.y + Math.sign(self.scrunch_dir)) // Faster bc longer dist to scrunch
      set_xy(self, self.x, self.y + self.scrunch_dir)
      if (self.yt >= self.MAX_Y) {
        // if fully scrunched DOWN
        set_xlyt(self, self.xl, self.MAX_Y)
        // 9C2C
        self.scrunch_dir = self.DIFF_UP // -2 (move UP)
        self.timer = 0x80 // delay unscrunching UP
      } else {
        if (self.yt <= self.MIN_Y) {
          set_xlyt(self, self.xl, self.MIN_Y)
          self.scrunch_dir = 0 // 0: idle (fully stretched)
        }
        self.timer = 5
      }
    }
    // DE51: JSR EF11
    update_EF11(self)
    // DE54 & DE6C, DD3D. Despawn check
    GOB_update_2a(self) // GOB body to proj/sword/body collision checks
    if (self.cs & CS_BD1) enemy_collide_pc_body(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (ocsH1(self)) {
    // fully unscrunched && any width is w/in ocs area width
    self.canDrawScrunchHB = true
    // 9BF2
    Geldarm_update_scrunchHB(self)
    if (collide_pc_sword(self.scrunchX1, self.scrunchY1, self.SCRUNCH_W, self.scrunch_h)) {
      // 9C0F
      self.scrunch_dir = self.DIFF_DW // +1 (move down)
      self.timer = 1
      aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
    } else if (collide_pc_body(self.scrunchX1, self.scrunchY1, self.SCRUNCH_W, self.scrunch_h)) {
      enemy_collide_pc_body(self)
    }
    update_EF11(self)
    GOB_update_2a(self)
    if (self.cs & CS_BD1) enemy_collide_pc_body(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
}

/** `Geldarm_udp()` */
export function Geldarm_udp(self: GeldA): void {
  const g = gp()
  self.can_draw_self = true
  self.canDraw_segments = self.MAX_Y - self.yt
  const _DIFF = self.MAX_Y - self.yt
  self.segmentYOff = Math.trunc(_DIFF / self.SEGMENTS)
  self.addOneY_cnt = _DIFF % self.SEGMENTS
  if (g.counter1 & 0x10) self.xScale = 1
  else self.xScale = -1
  if (self.scrunch_dir !== 0) self.sway_dir = 0
  else if (g.counter1 & 0x20) self.sway_dir = 1
  else self.sway_dir = -1
  if (self.state === self.state_EXPLODE) {
    self.explosion_count = 2
    self.explosion_count = 1 + ((self.GROUND_Y - self.yt) >> 4 >= 2 ? 1 : 0)
    self.explosion_y = self.GROUND_Y - (self.explosion_count << 4)
    self.explosion_y += 8 // centered like drawY
    if (self.timer === 1) {
      // So rising xp not so high
      set_xlyt(self, self.xl, self.explosion_y - 8)
    }
  }
}

/** `Geldarm_draw()` */
export function Geldarm_draw(self: GeldA): void {
  const g = gp()
  drawState.depth = self.depth
  if (self.can_draw_self) {
    pal_swap_set(self.palidx)
    let _xoff = 0
    // 0: draw head first, 1: draw head last (OG). Head must be drawn last so it's in front for scrunching.
    const _ORDER = gmBool(Math.abs(self.scrunch_dir)) || true
    if (!_ORDER) {
      _xoff = self.sway_dir + Math.sign(self.sway_dir) // 0, +1, -1
      draw_sprite_(self.HEAD_SPR, 0, self.drawX + _xoff, self.drawY + self.HEAD_DRAW_YOFF, -1, self.xScale)
    }
    if (gmBool(self.canDraw_segments)) {
      const _ds_SEGMENT_Y: number[] = []
      let _y = self.drawY + self.segmentYOff // segmentYOff: dist between TOP of each segment
      for (let _i = 0; _i < self.SEGMENTS; _i++) {
        if (_i < self.addOneY_cnt) _y++
        _ds_SEGMENT_Y.push(_y)
        _y += self.segmentYOff
      }
      for (let _i = self.SEGMENTS; _i > 0; _i--) {
        if (_i === 1)
          _xoff = self.sway_dir // 1st segment below head
        else _xoff = 0
        _y = _ds_SEGMENT_Y.pop() as number
        draw_sprite_(self.SEGMENT_SPR, 0, self.drawX + _xoff, _y, -1, self.xScale)
      }
    }
    if (_ORDER) {
      _xoff = self.sway_dir + Math.sign(self.sway_dir) // 0, +1, -1
      draw_sprite_(self.HEAD_SPR, 0, self.drawX + _xoff, self.drawY + self.HEAD_DRAW_YOFF, -1, self.xScale)
    }
    pal_swap_reset()
  }
  // scrunch hb
  if (
    gmBool(g.DevTools_state) &&
    gmBool(self.state) &&
    g.can_draw_hb &&
    isAncestorName(self.objectName, 'GeldA') &&
    self.canDrawScrunchHB
  ) {
    draw_rect_(pp().C_GRN2, self.scrunchX1, self.scrunchY1, self.SCRUNCH_W, self.scrunch_h, 1, true)
  }
}

export function registerGeldarm(): void {
  registerObject('GeldA', GeldA)
  registerScripts({ Geldarm_init2, Geldarm_update, Geldarm_update_scrunchHB, Geldarm_udp, Geldarm_draw })
}
registerGeldarm()
