/** Ported from `Cutscene_init_vars.gml`, `Cutscene_init.gml`, `cutscene_update.gml`. */
import { gmBool } from '../../../nes/math8'
import { g, world } from '../../../runtime/world'
import { Cutscene } from '../classes'
import type { CutsceneObject } from './classes'
import { FallScene_update } from './fallScene'

/** `Cutscene_init_vars()` */
export function Cutscene_init_vars(self: CutsceneObject): void {
  self.DUR1 = 0x5f // _DUR1: $5F 1.583s
}

/** `Cutscene_init()` — `init_vars_go_B()` are the class field defaults. */
export function Cutscene_init(self: CutsceneObject): void {
  Cutscene_init_vars(self)
}

/** `cutscene_update()` — called at the end of `g_Step`. */
export function cutscene_update(): void {
  if (!gmBool(g.cutscene)) g.cutscene_part = 0
  if (!gmBool(g.cutscene)) g.cutscene_ctr = 0
  if (gmBool(g.cutscene_timer)) g.cutscene_timer--
  FallScene_update()
  for (const self of world.instancesOf(Cutscene)) self.scr_step?.(self)
}
