/**
 * Seams for scripts outside the overworld port: items/quests (`file`/`gob` folders), player skin sheet
 * (`goa`), audio sound length (adapter playback), `draw_sprite_part_` (draw folder). Defaults are the
 * smallest faithful behaviour; the owning ports replace them via the `set*` functions.
 */
// biome-ignore-all lint/suspicious/noExplicitAny: seams over un-ported ZALiA state
import { G, world } from '../../runtime/world'
import { notPorted } from '../pending'
import type { SoundInst } from '../sound/Audio'

/** `item_acquired(item id)` (file/gob folders). */
export let item_acquired: (itemId: string) => boolean | number = notPorted('item_acquired')
/** `crystal_is_placed(dungeon num)` (goe/cutscene folder). */
export let crystal_is_placed: (dungeonNum: number) => boolean | number = notPorted('crystal_is_placed')
/** `get_bottle_bubbling_frame()` — 0..2 animation frame of the magic-container bottle (gui folder). */
export let get_bottle_bubbling_frame: () => number = () => 0
export function setOverworldDeps(
  d: Partial<{
    item_acquired: typeof item_acquired
    crystal_is_placed: typeof crystal_is_placed
    get_bottle_bubbling_frame: typeof get_bottle_bubbling_frame
    audio_sound_length_frames: typeof audio_sound_length_frames
  }>,
): void {
  if (d.item_acquired) item_acquired = d.item_acquired
  if (d.crystal_is_placed) crystal_is_placed = d.crystal_is_placed
  if (d.get_bottle_bubbling_frame) get_bottle_bubbling_frame = d.get_bottle_bubbling_frame
  if (d.audio_sound_length_frames) audio_sound_length_frames = d.audio_sound_length_frames
}

/**
 * `round(audio_sound_length(inst) * room_speed)` — the flute jingle length in frames. GameMaker knew the
 * asset length; the adapter installs a provider from its loaded audio. Until then ZALiA's own
 * approximation `FLUTE_DURATION1` ($88+$08, "at worst, an approximation") is used.
 */
export let audio_sound_length_frames: (inst: SoundInst, fallbackFrames: number) => number = (
  _inst,
  fallbackFrames,
) => fallbackFrames

/** The player (`global.pc`) fields the overworld reads for drawing the map sprite. */
export interface PcOverworldView {
  dm_skins: { get(k: string): any }
  Spritesheet_W: number
  Spritesheet_H: number
  Skin_image: string
}
const PC_DEFAULT: PcOverworldView = {
  dm_skins: { get: () => undefined },
  Spritesheet_W: 0x40,
  Spritesheet_H: 0x40,
  Skin_image: 'spr_0',
}
export function pcView(): PcOverworldView {
  const pc = G.pc as PcOverworldView | null | undefined
  return pc && (pc as any).dm_skins ? pc : PC_DEFAULT
}

/**
 * `draw_sprite_part_(sprite, sub image, left, top, width, height, x, y, *pal index, *xscale, *yscale)` —
 * emitted as a `spritePart` draw command (DrawCmd extension: `{ kind: 'spritePart', sprite, frame, left,
 * top, width, height, x, y, xscale, yscale, palIdx, depth }`); the draw-folder port owns the real one.
 */
/** `draw_sprite_part_` — the draw folder owns it; re-exported here for the overworld scripts. */
export { draw_sprite_part_ } from '../draw'

/** GM `frac(x)` */
export const frac = (v: number): number => v - Math.trunc(v)
/** GM `string_count(sub, str)` */
export const string_count = (sub: string, str: string): number => (sub ? str.split(sub).length - 1 : 0)
/** GM `string_lettersdigits(str)` */
export const string_lettersdigits = (s: string): string => s.replace(/[^A-Za-z0-9]/g, '')
/** GM `ds_list_shuffle` on a plain array, using the world PRNG (deterministic under a seed). */
export function shuffleInPlace<T>(a: T[]): T[] {
  for (let i = a.length - 1; i > 0; i--) {
    const j = world.irandom(i)
    const t = a[i] as T
    a[i] = a[j] as T
    a[j] = t
  }
  return a
}
