/** Fields of the Iron Knuckle family (also used by the Fokka udp). */
export class IrKnA extends Enemy {
  readonly objectName: 'IrKnA' | 'Rebonack01B' = 'IrKnA'
  BVR_IDLE = 0
  BVR_DRWH = 1 // draw high
  BVR_ATKH = 2 // stab/strike high
  BVR_DRWL = 3 // draw low
  BVR_ATKL = 4 // stab/strike low
  BVR_THRW = 5 // throw. This only happens for Fokka & Moblin
  SPR_WALK1 = 'spr_Iron_Knuckle_Walk1'
  SPR_IDLE1 = 'spr_Iron_Knuckle_Idle1'
  SPR_WALK2 = 'spr_Iron_Knuckle_Walk2'
  SPR_IDLE2 = 'spr_Iron_Knuckle_Idle2'
  SPR_JUMP1 = 'spr_Iron_Knuckle_Walk2'
  HSPD_PACE = 8
  HSPD_CHASE = 0x10
  JUMP_VEL = 0
  INIT_VEL = 0
  VSPD_GRAV = 2
  DUR_PACE = 0x50 // 80 - $0504,X
  DUR_ATK_DRAW = 0x18 // $0504,X
  DUR_ATK_STAB = 0x10 // $0504,X
  CUE_ATK_PHASE2 = 0x0c // for udd
  CUE_ATK_PHASE3 = 0x02 // for udd
  is_aggro = false
  is_cucco_aware = false
  attack_tokens = 0 // $0401[uIdx].  Num of remaining quick succession attacks
  DUR_DELAY_SHIELD1 = 0x20 // 32  frames = 0.533s
  DUR_DELAY_SHIELD2 = 0x04
  tmr_delay_shield = 0 // Delay set shield to match PC position
  delay_shield_chance = 0 // 0: 12.5%, 1: 25%, 2: 50%, 3: 93.75%
  CHANCES = '204080F0'
  DUR_ATK_COOLDOWN1 = 0x60 // 96  frames = 1.600s
  DUR_ATK_COOLDOWN2 = 0x30
  AttackCooldown_timer = 0x60
  ShieldHB_IDX_LOW = 1
  ShieldHB_IDX_HGH = 2
  SwordHB_XOFF = 8
  SwordHB_YOFF = 16
  SwordHB_W = 14
  SwordHB_H = 1
  dl_Arm_SPRITES = new DsList<string | 0>()
  Arm_sprite: string | 0 = 0
  dg_Arm_XOFF = new DsGrid<number>(4, 6, 0)
  Arm_xoff = 0
}

/** `IronKnuckle_init2()` */
export function IronKnuckle_init2(self: IrKnA): void {
  const g = gp()
  self.BVR_IDLE = 0
  self.BVR_DRWH = 1
  self.BVR_ATKH = 2
  self.BVR_DRWL = 3
  self.BVR_ATKL = 4
  self.BVR_THRW = 5
  self.behavior = self.BVR_IDLE
  self.SPR_WALK1 = 'spr_Iron_Knuckle_Walk1'
  self.SPR_IDLE1 = 'spr_Iron_Knuckle_Idle1'
  self.SPR_WALK2 = 'spr_Iron_Knuckle_Walk2'
  self.SPR_IDLE2 = 'spr_Iron_Knuckle_Idle2'
  self.SPR_JUMP1 = self.SPR_WALK2
  self.HSPD_PACE = 8
  self.HSPD_CHASE = 0x10
  self.hspd = self.HSPD_PACE // $0071,X
  self.JUMP_VEL = 0
  self.INIT_VEL = 0
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.vspd = 0 // $057D,X - $057E-0583
  self.timer = 1 // 1st frame after spawn is 0
  self.DUR_PACE = 0x50
  self.DUR_ATK_DRAW = 0x18
  self.DUR_ATK_STAB = 0x10
  self.CUE_ATK_PHASE2 = 0x0c
  self.CUE_ATK_PHASE3 = 0x02
  self.is_aggro = isAncestorName(self.objectName, 'Rebonack01B')
  self.is_cucco_aware = false
  self.attack_tokens = 0
  self.projectile_OBJ = 'SwordBeam'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.DUR_DELAY_SHIELD1 = 0x20
  self.DUR_DELAY_SHIELD2 = 0x04
  self.tmr_delay_shield = 0
  self.delay_shield_chance = 0
  self.CHANCES = '20' + '40' + '80' + 'F0' // 12.5%, 25%, 50%, 93.75%
  self.DUR_ATK_COOLDOWN1 = 0x60
  self.DUR_ATK_COOLDOWN2 = self.DUR_ATK_COOLDOWN1 >> 1
  self.AttackCooldown_timer = self.DUR_ATK_COOLDOWN1
  // shield hb
  self.ShieldHB_IDX_LOW = 1
  self.ShieldHB_IDX_HGH = 2
  self.ShieldHB_IDX = self.ShieldHB_IDX_LOW
  self.ShieldHB_idx = self.ShieldHB_IDX // 0444,X
  GOB_update_shield_offsets(self)
  update_shield_hb(self)
  // sword hb
  self.SwordHB_XOFF = 8 + g.HB_ADJ_X
  self.SwordHB_YOFF = 16 + g.HB_ADJ_Y
  self.SwordHB_xoff = self.SwordHB_XOFF * self.facing_dir
  self.SwordHB_yoff = self.SwordHB_YOFF
  self.SwordHB_W = 14 + g.HB_ADJ_W
  self.SwordHB_H = 1 + g.HB_ADJ_H
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
  // Arm -------------------------------
  self.dl_Arm_SPRITES = new DsList<string | 0>()
  self.dl_Arm_SPRITES.set(self.BVR_IDLE, 0)
  self.dl_Arm_SPRITES.set(self.BVR_DRWH, 'spr_Iron_Knuckle_Attack_high_Draw')
  self.dl_Arm_SPRITES.set(self.BVR_ATKH, 'spr_Iron_Knuckle_Attack_high_Stab')
  self.dl_Arm_SPRITES.set(self.BVR_DRWL, 'spr_Iron_Knuckle_Attack_low_Draw')
  self.dl_Arm_SPRITES.set(self.BVR_ATKL, 'spr_Iron_Knuckle_Attack_low_Stab')
  self.Arm_sprite = self.dl_Arm_SPRITES.get(self.BVR_IDLE) ?? 0
  // rows: facing right atk high / atk low, facing left atk high / atk low; cols: DRW×3, ATK×3
  const T = [
    [-4, -9, -5, 9, 16, 8],
    [-3, -7, -4, 9, 16, 8],
    [6, 10, 5, -7, -15, -8],
    [5, 8, 4, -7, -15, -8],
  ]
  self.dg_Arm_XOFF = new DsGrid<number>(4, 6, 0)
  for (let r = 0; r < 4; r++)
    for (let c = 0; c < 6; c++) self.dg_Arm_XOFF.set(r, c, (T[r] as number[])[c] as number)
  self.Arm_xoff = self.dg_Arm_XOFF.get(0, 0) as number
  // -------------------------------------------------
  self.abilities |= ABL_WALK
  if (
    isAncestorName(self.objectName, 'Rebonack01B') ||
    (isAncestorName(self.objectName, 'IrKnA') && self.ver === 3)
  )
    self.abilities |= ABL_SHOT
}

/** `IronKnuckle_end()` — list/grid cleanup; garbage collected here. */
export function IronKnuckle_end(_self: IrKnA): void {}

/** `IronKnuckle_update()` */
export function IronKnuckle_update(self: IrKnA): void {
  const g = gp()
  const P = pc()
  const _RAND = rand(self)
  const _REBO = isAncestorName(self.objectName, 'Rebonack01B')
  // 9C8C
  update_EF11(self)
  // 9C99
  if (gmBool(self.behavior)) {
    // if attacking. 9C9D
    if (self.behavior === self.BVR_ATKH || self.behavior === self.BVR_ATKL) {
      if (self.abilities & ABL_SHOT && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
        // IronKnuckle Blue, RebonackB --------------------
        const _XL = self.xl
        const _YT = self.yt + 0xa * (self.behavior === self.BVR_ATKL ? 1 : 0)
        GOC1_create(_XL, _YT, self.facing_dir, self.projectile as ObjectName, self.projectile_ver)
        self.behavior = 0
      } else {
        // IronKnuckle Orange, Red, Blue if Proj slot unavail. 9CC3: JSR E563: JSR E5F3
        if (!GOB_sword_collision_2a(self)) GOB_sword_collision_1a(self) // E579: JSR E5F3
      }
    }
    // 9CC6
    if (!self.timer) {
      if (self.behavior === self.BVR_DRWH) self.behavior = self.BVR_ATKH
      else if (self.behavior === self.BVR_DRWL) self.behavior = self.BVR_ATKL
      else self.behavior = 0
      if (gmBool(self.behavior)) self.timer = self.DUR_ATK_STAB // $10: 0.267s
    }
  }
  // PC projectile/sword to GOB shield. 9CE3: JSR E617
  if (GOB_shield_collision_1a(self)) return // if Link sword collided enemy shield !!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // PC sword did NOT collide GOB shield. 9CE6, 9CE9
  GO_update_cs(self)
  GO_update_cam_vars(self)
  if (self.yt >= cam_yb_max() + 0x18) {
    GOB_despawn(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // 9CFA, 9D0C: JSR E48B (body collision)
  if (ocsH3(self) || _REBO) GOB_update_2a(self) // PC proj+swrd+body collision, despawn check
  if (gmBool(self.pc_sword_collided_solid_body)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!self.is_cucco_aware && self.cs & CS_SW1 && pc_is_cucco()) {
    self.is_cucco_aware = true // Is aware cucco is a threat. Will now treat cucco as human Link
  }
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // 9D18
  updateY(self)
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  }
  // 9D24
  GOB_update_1(self, true) // update hspdPB
  GO_update_cs(self)
  if (!(self.cs & 0x3)) updateX(self)
  // 9D27
  if (self.stun_timer === 2) self.attack_tokens = 0x4 | (_RAND & 0x3) // result 4,5,6,7
  // 9D38
  let _MAX = 41 // OG
  if (gmBool(g.mod_IronKnuckle_AggroAI2)) _MAX = 47
  let _MIN = 0 // OG
  if (gmBool(g.mod_IronKnuckle_AggroAI3)) _MIN = -7
  let _ATTACK_DIST = 0x1c
  if (self.abilities & ABL_SHOT) _ATTACK_DIST = 0x60 // IronKnuckleBlue, RebonackB
  const _IN_DIST_Y = inRange(self.yt - P.yt, _MIN, _MAX)
  let _IN_DIST_ATTACK = false
  let _QUAL_ATTACK = false
  let _QUAL_AGGRO = false
  switch (Number(g.mod_IronKnuckle_AggroAI ?? 0)) {
    case 0: {
      // OG.
      _IN_DIST_ATTACK =
        byte(goDist1(self) + _ATTACK_DIST + (gmBool(self.facing_dir) ? 0 : 1)) < byte(_ATTACK_DIST << 1)
      _QUAL_ATTACK = _IN_DIST_Y && _IN_DIST_ATTACK
      _QUAL_AGGRO = _IN_DIST_Y
      break
    }
    case 1: {
      // MOD. Must face PC to aggro
      _IN_DIST_ATTACK = Math.abs(self.x - P.x) <= _ATTACK_DIST
      _QUAL_ATTACK = _IN_DIST_Y && _IN_DIST_ATTACK
      _QUAL_AGGRO = ocsH2(self) && (self.is_aggro || (_IN_DIST_Y && is_facing_pc_(self)))
      break
    }
    case 2: {
      // MOD. Must face PC to aggro if outside of og view area. Does not attack nor aggro cucco until provoked
      const _C1 = !pc_is_cucco() || self.is_cucco_aware
      const _IN_DIST_X1 = wINw(self.x, 1, g.view_xl_og, VIEW_W_OG)
      _IN_DIST_ATTACK = Math.abs(self.x - P.x) <= _ATTACK_DIST
      _QUAL_ATTACK = _IN_DIST_Y && _IN_DIST_ATTACK && (_C1 || _REBO)
      if (_REBO) _QUAL_AGGRO = true
      else {
        _QUAL_AGGRO = _C1 && _IN_DIST_Y && ocsH2(self)
        if (_QUAL_AGGRO) _QUAL_AGGRO = _QUAL_AGGRO && (is_facing_pc_(self) || _IN_DIST_X1)
      }
      break
    }
    default: {
      // 3: MOD. Must face PC to aggro if outside of og view area, No special behavior towards cucco
      const _IN_DIST_X1 = wINw(self.x, 1, g.view_xl_og, VIEW_W_OG)
      _IN_DIST_ATTACK = Math.abs(self.x - P.x) <= _ATTACK_DIST
      _QUAL_ATTACK = _IN_DIST_Y && _IN_DIST_ATTACK
      if (_REBO) _QUAL_AGGRO = true
      else {
        _QUAL_AGGRO = _IN_DIST_Y && ocsH2(self)
        if (_QUAL_AGGRO) _QUAL_AGGRO = _QUAL_AGGRO && (is_facing_pc_(self) || _IN_DIST_X1)
      }
      break
    }
  }
  if (!_QUAL_ATTACK) {
    self.delay_shield_chance = -1 // -1: 100% chance will match shield w/ PC level
    self.tmr_delay_shield = 0
  }
  self.is_aggro = _REBO
  if (_QUAL_AGGRO || _QUAL_ATTACK) {
    // 9D52, 9D67. ----------- SET shld_hb_idx --------------------
    IronKnuckle_update_ShieldHB_idx(self, _IN_DIST_ATTACK, _QUAL_ATTACK)
    // 9D7B
    self.facing_dir = dir_to_pc(self)
    self.hspd = (self.HSPD_CHASE * self.facing_dir) & 0xff
    self.is_aggro = self.is_aggro || _QUAL_AGGRO
    // 9D84
    if (_IN_DIST_ATTACK) {
      // 9D91. ---------- SET hspd ------------------
      if (gmBool(P.hspd)) self.hspd = P.hspd
      else if (g.counter1 & 0x40) self.hspd = self.HSPD_PACE & 0xff
      else self.hspd = -self.HSPD_PACE & 0xff
      if (self.abilities & ABL_SHOT || !gmBool(P.ogr)) {
        // IronKnuckle-Blue, RebonackB
        self.hspd = (self.hspd >> 1) | (self.hspd & 0x80)
      }
      // 9DB0. ----------- Check for and start attack -----------------
      if (self.behavior === self.BVR_IDLE && !(self.ocs & 0x4)) {
        // Rebonack01B can be w/in atk dist but off screen
        let _can_attack = false
        switch (Number(g.mod_IronKnuckle_AttackAI ?? 0)) {
          case 0: {
            // OG
            if (!gmBool(self.attack_tokens)) self.counter = (self.counter + 1) & 0xff
            if (gmBool(self.attack_tokens) || !(self.counter & 0x3f)) {
              // atk every 64 frames. 1.067 sec
              if (gmBool(self.attack_tokens)) self.attack_tokens--
              else if (!(_RAND & 0xf)) self.counter = 0x20 // 1 in 16 chance (6.25%). Only $20 (instead of $40) until next atk
              _can_attack = true
            }
            break
          }
          default: {
            // 1: MOD. Reduced attack frequency
            if (!gmBool(self.attack_tokens) && gmBool(self.AttackCooldown_timer)) self.AttackCooldown_timer--
            if (gmBool(self.attack_tokens) || !self.AttackCooldown_timer) {
              if (gmBool(self.attack_tokens)) self.attack_tokens--
              else if (!(_RAND & 0xf))
                self.AttackCooldown_timer = self.DUR_ATK_COOLDOWN2 // 1 in 16 chance (6.25%)
              else self.AttackCooldown_timer = self.DUR_ATK_COOLDOWN1
              _can_attack = true
            }
            break
          }
        }
        if (_can_attack) {
          // 9DD2. ------------ START ATTACK ---------------
          if (!(_RAND & 0x1)) {
            if (_RAND & 0x4)
              self.behavior = self.BVR_DRWL // 3: BVR_DRWL
            else self.behavior = self.BVR_DRWH // 1: BVR_DRWH
          } else {
            if (dHeld())
              self.behavior = self.BVR_DRWL // 3: BVR_DRWL
            else self.behavior = self.BVR_DRWH // 1: BVR_DRWH
          }
          self.timer = self.DUR_ATK_DRAW // $18
        }
      }
    }
  } else {
    // 9DEE
    if (self.counter & 0x1) self.hspd = 0
    else self.hspd = (self.HSPD_PACE * self.facing_dir) & 0xff
    if (!self.timer) {
      // 9E0F
      self.timer = self.DUR_PACE // $50
      if (self.counter & 0x1) self.facing_dir = -self.facing_dir
      self.counter = (self.counter + 1) & 0xff
    }
  }
}

/**
 * `IronKnuckle_update_ShieldHB_idx()` — 9D52, 9D67. FIDELITY: ZALiA's MOD1 branch read the caller's
 * locals `_IN_DIST_ATK`/`_QUAL_ATCK` (never set in that scope → GML "variable not set" error if the mod
 * were ever enabled); they are explicit parameters here.
 */
export function IronKnuckle_update_ShieldHB_idx(
  self: IrKnA,
  inDistAttack: boolean,
  qualAttack: boolean,
): void {
  const g = gp()
  const P = pc()
  switch (Number(g.mod_IronKnuckle_ShieldAI ?? 0)) {
    case 0: {
      // OG
      if (self.yt !== P.yt) {
        if (P.yt + 0xa >= self.yt)
          self.ShieldHB_idx = self.ShieldHB_IDX_LOW // 1
        else self.ShieldHB_idx = self.ShieldHB_IDX_HGH // 2
      } else {
        if (input.Attack_pressed && rand(self) & (0x3 >> (is_ver(self, 'IrKnA', 1) ? 1 : 0))) {
          // Chance to block PC's attack. (rand()&$3): 75%, (rand()&$1): 50%
          if (dHeld())
            self.ShieldHB_idx = self.ShieldHB_IDX_LOW // 1
          else self.ShieldHB_idx = self.ShieldHB_IDX_HGH // 2
        }
      }
      break
    }
    default: {
      // MOD1
      if (gmBool(self.stun_timer)) self.delay_shield_chance = -1 // -1: 100% chance
      if (gmBool(self.tmr_delay_shield)) {
        self.tmr_delay_shield--
        if (!self.tmr_delay_shield && inDistAttack) self.delay_shield_chance = -1 // -1: 100% chance
      }
      if (inDistAttack) {
        if (gmBool(P.ogr)) {
          // OGR_OTHR, OGR_JUMP
          if (P.yt + 0xa >= self.yt) self.ShieldHB_idx = self.ShieldHB_IDX_LOW
          else self.ShieldHB_idx = self.ShieldHB_IDX_HGH
          self.delay_shield_chance = -1
          self.tmr_delay_shield = 0
        } else {
          const down = dHeld() !== 0
          if (
            (down && self.ShieldHB_idx === self.ShieldHB_IDX_HGH) ||
            (!down && self.ShieldHB_idx === self.ShieldHB_IDX_LOW)
          ) {
            if (!self.tmr_delay_shield && qualAttack) {
              const _dl_chances = [0x20, 0x40, 0x80, 0xf0] // 12.5%, 25%, 50%, 93.75%
              let _chance = 0 // 100% chance
              if (self.delay_shield_chance < 0) self.delay_shield_chance = 0
              else _chance = _dl_chances[self.delay_shield_chance] ?? 0
              if (gmBool(self.behavior)) _chance = 0x80 // During attack
              if (rand(self) < _chance) {
                self.delay_shield_chance = -1
                self.tmr_delay_shield = self.DUR_DELAY_SHIELD1
              } else {
                if (down) self.ShieldHB_idx = self.ShieldHB_IDX_LOW
                else self.ShieldHB_idx = self.ShieldHB_IDX_HGH
                self.delay_shield_chance += self.delay_shield_chance < _dl_chances.length - 1 ? 1 : 0
                self.tmr_delay_shield = 0
              }
            }
          } else if (gmBool(self.tmr_delay_shield)) {
            // Reseting here penalizes the player for not patiently waiting to see if they had an open for the attack.
            self.delay_shield_chance = 1
            self.tmr_delay_shield = 0
          }
        }
      }
      break
    }
  }
}

/** `Fokka_udp()` — sprite + arm selection shared by Iron Knuckle and Fokka. */
export function Fokka_udp(self: IrKnA): void {
  const g = gp()
  self.can_draw_self = true
  if (self.cs & 0x4) {
    // ON  GROUND
    if (gmBool(self.hspd) && g.counter1 & (0x4 << (abs8b(self.hspd) < self.HSPD_CHASE ? 1 : 0))) {
      // 4, 8
      if (self.ShieldHB_idx === self.ShieldHB_IDX_HGH) GO_set_sprite(self, self.SPR_WALK2)
      else GO_set_sprite(self, self.SPR_WALK1)
    } else {
      if (self.ShieldHB_idx === self.ShieldHB_IDX_HGH) GO_set_sprite(self, self.SPR_IDLE2)
      else GO_set_sprite(self, self.SPR_IDLE1)
    }
  } else {
    // OFF GROUND
    if (self.vspd & 0x80) GO_set_sprite(self, self.SPR_JUMP1)
    else if (self.ShieldHB_idx === self.ShieldHB_IDX_HGH) GO_set_sprite(self, self.SPR_IDLE2)
    else GO_set_sprite(self, self.SPR_IDLE1)
  }
  self.Arm_sprite = self.dl_Arm_SPRITES.get(self.behavior) ?? 0 // dl_Arm_SPRITES[|0] = 0;
  if (gmBool(self.behavior)) {
    let _idx1 = 0
    if (self.behavior > self.BVR_ATKH) _idx1 = 1
    if (self.facing_dir === -1) _idx1 += 2
    let _idx2 = 0
    if (!(self.behavior & 0x1)) _idx2 += 3
    if (self.timer <= self.CUE_ATK_PHASE2) _idx2++
    if (self.timer <= self.CUE_ATK_PHASE3) _idx2++
    self.Arm_xoff = self.dg_Arm_XOFF.get(_idx1, _idx2) ?? 0
  }
}

/** `IronKnuckle_udp()` */
export function IronKnuckle_udp(self: IrKnA): void {
  self.can_draw_self = true
  Fokka_udp(self)
}

/** `IronKnuckle_draw()` */
export function IronKnuckle_draw(self: IrKnA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawState.depth = self.depth
  pal_swap_set(self.palidx)
  draw_sprite_(self.Arm_sprite, 0, self.drawX + self.Arm_xoff, self.drawY, -1, self.xScale)
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

export function registerIronKnuckle(): void {
  registerObject('IrKnA', IrKnA)
  registerScripts({
    IronKnuckle_init2,
    IronKnuckle_update,

    IronKnuckle_udp,
    IronKnuckle_draw,
    IronKnuckle_end,
    Fokka_udp,
  })
}
registerIronKnuckle()
