/**
 * Bot / Bit / Nyb (ZALiA objects `Bot_A`, `Bot_B`, parent `Bot` (an `Enemy` with `init_vars_Bot`)); OG eID
 * $04/$05. `Bot_init2/update/udp/draw/draw_cover/end.gml`. The ver-3 "hiding under a bush" cover system is
 * dead in ZALiA (its init is commented out, so `Cover_state` stays 0) — ported as-is.
 */
import {
  ABL_JUMP,
  ABL_RUN_,
  ABL_WALK,
  Area_EastA,
  Area_PalcG,
  Area_TownA,
  Area_WestA,
  CS_BD1,
  DEPTH_BG4,
  OGR_JUMP,
  OGR_OTHR,
  STR_Data,
  TID_ONEWY1,
  TID_SOLID1,
} from '@z2/data'
import { hexStr } from '../../../../../../nes/hexStr'
import { gmBool } from '../../../../../../nes/math8'
import { G, g, world } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { viewYT } from '../../../../../collision/env'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { get_ground_y } from '../../../../../collision/solid'
import { sprite_create_with_tiles } from '../../../../../graphics/index'
import { inRange, sign_ } from '../../../../../math/index'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { Bot, type Enemy } from '../../../../classes'
import { draw_sprite_, GO_draw_sprite } from '../../../../go/draw'
