/** Fields set by `Bot_init2` (shared by Bot_A, Bot_B and Capper). */
export abstract class BotObject extends Bot {
  SPR_NORM = 'spr_Bot_Norm'
  SPR_SQSH = 'spr_Bot_Squish'
  SPR_BALL = 'spr_Bot_Ball'
  SPR_EYE1 = 'spr_Bot_Eyes_1a'
  SPR_EYE2 = 'spr_Bot_Eyes_1b'
  spr_eyes: string | 0 = 0
  eyes_yoff = 0
  mouth_state = 0 // 0: no mouth, 1: norm mouth, 2: open mouth
  mouth_yoff = 0
  mouth_color = 0
  GROUND_Y = 0
  /** What number inst of spawned ver2 is this (Bot_A v2 only) */
  ver2_inst = 0
  // ver 3 cover (dead in ZALiA — init commented out)
  Cover_state = 0
  Cover_SPR: string | 0 = 0
  Cover_PI = 0
  Cover_H = 0
  Cover_X = 0
  Cover_YB = 0
  Cover_xoff = 0
  Cover_yoff = 0
  Cover_DUR1 = 0x40
  Cover_DUR2 = 0x100 - 0x40
  Cover_tmr = 0
  Cover_NUM = 1
  Hide_DEPTH = DEPTH_BG4 + 1
}
export class Bot_A extends BotObject {
  readonly objectName = 'Bot_A' as const
}
export class Bot_B extends BotObject {
  readonly objectName = 'Bot_B' as const
}

/** `Bot_init2()` — eID = $04, $05 */
export function Bot_init2(self: BotObject): void {
  // init_vars_Bot() are class fields (Bot) — except the gravity it also sets (base class gap, see report)
  self.vspd_grav = self.VSPD_INC_DEF
  self.hspd_jump = self.HSPD_JUMP_DEF
  self.term_vel = self.TERM_VEL_DEF
  self.SPR_NORM = 'spr_Bot_Norm'
  self.SPR_SQSH = 'spr_Bot_Squish'
  self.SPR_BALL = 'spr_Bot_Ball'
  self.SPR_EYE1 = 'spr_Bot_Eyes_1a'
  self.SPR_EYE2 = 'spr_Bot_Eyes_1b'
  self.spr_eyes = 0
  self.eyes_yoff = 0
  self.mouth_state = 0
  self.mouth_yoff = 0
  self.mouth_color = 0
  self.GROUND_Y = ((self.spawn_yt + self.hh) >> 3) << 3
  self.GROUND_Y = get_ground_y(self.x, self.spawn_yt, 1, self.GROUND_Y, TID_SOLID1 | TID_ONEWY1)
  switch (self.ver) {
    case 1: // Bot
      GO_init_palidx(self, G.PI_MOB_BLU)
      self.abilities |= ABL_WALK
      self.abilities |= ABL_JUMP
      break
    case 2: // Bit
      GO_init_palidx(self, G.PI_MOB_RED)
      self.abilities |= ABL_WALK
      self.abilities |= ABL_RUN_
      break
    case 3: // ver 3 behavior is to only jump when PC is close enough (cover init is commented out in ZALiA)
      break
    case 4: // v4: Nyb (same as Bit but all hspd is fast hspd)
      GO_init_palidx(self, G.PI_MOB_PUR)
      self.abilities |= ABL_WALK
      self.abilities |= ABL_RUN_
      break
  }
  if (self.objectName === 'Bot_A' && self.ver === 2) {
    // red Bot(Bit) Bot_A v2. OG eID: $05. What number inst of spawned ver2 is this
    self.ver2_inst = 0
    const _dl_uIdx: number[] = []
    for (const b of instancesNamed('Bot_A')) if (b.ver === 2 && gmBool(b.state)) _dl_uIdx.push(b.update_idx)
    _dl_uIdx.sort((a, b) => a - b)
    self.ver2_inst = _dl_uIdx.indexOf(self.update_idx)
  }
  switch (self.ver) {
    case 1:
      switch (g.area_name) {
        case Area_WestA:
          self.ATTACK_LEVEL = 0x01
          self.attack_level = self.ATTACK_LEVEL
          break
        case Area_PalcG:
          self.ATTACK_LEVEL = 0x04
          self.attack_level = self.ATTACK_LEVEL
          break
        case Area_TownA:
          self.ATTACK_LEVEL = 0x01
          self.attack_level = self.ATTACK_LEVEL
          break
      }
      switch (g.area_name) {
        case Area_WestA:
          self.HP_IDX = 0x03
          self.hp = g.dl_HP.get(self.HP_IDX) as number
          break
        case Area_PalcG:
          self.HP_IDX = 0x11
          self.hp = g.dl_HP.get(self.HP_IDX) as number
          break
        case Area_TownA:
          self.HP_IDX = 0x03
          self.hp = g.dl_HP.get(self.HP_IDX) as number
          break
      }
      if (g.area_name === Area_PalcG) {
        self.XP_IDX = 0x0a
        self.xp = g.dl_XP.get(self.XP_IDX) as number
      }
      if (g.area_name === Area_TownA) {
        self.DROP_BITS = 0x00
        self.drop_bits = self.DROP_BITS
      }
      break
    case 2:
      if (g.area_name === Area_EastA) {
        self.HP_IDX = 0x04
        self.hp = g.dl_HP.get(self.HP_IDX) as number
      }
      break
  }
}

/**
 * The `init_vars_Bot` fields `Bot_update` reads. `Myu_A`'s GML object parent is `Enemy`, not `Bot`, but its
 * `Myu_update` calls `Bot_update()` — so the walker update is typed structurally rather than on `BotObject`.
 */
export interface BotWalker extends Enemy {
  is_idle: number
  walk_dir: number
  hspd_jump: number
  INIT_VEL_DEF: number
  term_vel: number
  HSPD_WALK1: number
  HSPD_WALK2: number
  /** Bot_A ver 2 only (`BotObject`); absent on `Myu_A`, whose ver-2 branch is unreachable. */
  ver2_inst?: number
}

/** `Bot_update()` — update for Bot_A, Myu_A. DA54 */
export function Bot_update(self: BotWalker): void {
  const P = pc()
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return
  }
  const _RAND = rand(self)
  const _VER3 = self.objectName === 'Bot_A' && self.ver === 3
  // ---------------- JUMPING --------------------------
  if (self.abilities & ABL_JUMP && self.cs & 0x4) {
    let _C1 = !(_RAND & 0x7f)
    if (_VER3) {
      _C1 =
        !!(_RAND & 0x8) &&
        Math.abs(self.x - P.x) <= 0x18 + world.irandom(0xc) &&
        inRange(self.y, viewYT(), P.yb + (0x3 << 3))
    }
    if (_C1) {
      if (self.is_hostile || g.counter1 & 0x40) {
        self.facing_dir = dir_to_pc(self)
        self.hspd = (self.hspd_jump * self.facing_dir) & 0xff
        self.vspd = self.INIT_VEL_DEF // Jump!
        self.ogr = OGR_JUMP
        if (_VER3) self.abilities |= ABL_WALK
      }
    }
  }
  // DA54 ------------------------------------------------------------
  const _VSPD = self.vspd
  updateY(self)
  if (_VSPD < 0x80) self.vspd = Math.min(self.vspd, self.term_vel)
  GO_update_cs(self)
  GOB_update_2(self)
  if (self.cs & CS_BD1 && self.is_hostile) enemy_collide_pc_body(self)
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  }
  GO_vspd_update1(self) // if (cs8() && vspd&$80) vspd=$0;
  if (self.cs & 0x8 && self.cs & 0x4 && self.cs & 0x3) {
    // Stuck in wall?
    if (self.hspd < 0x80) set_xy(self, (self.x >> 3) << 3, self.y)
    else set_xy(self, ((self.x >> 3) + 1) << 3, self.y)
  }
  if (self.cs & 0x4) self.ogr = 0
  else if (!gmBool(self.ogr)) self.ogr = OGR_OTHR
  if (_VER3 && self.ogr === OGR_JUMP && self.depth !== self.depth_def) {
    if (self.vspd === 0 || (self.vspd < 0x80 && _VSPD & 0x80)) self.depth = self.depth_def
  }
  // ------------------------------------------------------------
  if (self.cs & 0x4) {
    if (self.abilities & ABL_WALK) {
      // DA75
      if (!gmBool(self.is_idle)) {
        // DA7D, DA89
        if ((self.counter & 0xf) === 0xf || (self.counter & 0xf) === 0x3) {
          let _C1: boolean | number = self.objectName === 'Bot_A' && self.ver === 4 // v4: Nyb
          if (!_C1 && self.abilities & ABL_RUN_) {
            if (self.objectName === 'Bot_A' && self.ver === 2)
              _C1 = (g.counter1 - (((self.ver2_inst ?? 0) << 5) & 0xc0)) & 0xff
            else _C1 = g.counter1
            _C1 = _C1 < 0x80
          }
          if (_C1) self.hspd = (self.HSPD_WALK2 * self.walk_dir) & 0xff
          else self.hspd = (self.HSPD_WALK1 * self.walk_dir) & 0xff
          if (!(self.cs & 0x3)) updateX(self)
        }
        self.counter = (self.counter + 1) & 0xff
      }
      if (!gmBool(self.timer)) {
        // DAA4
        self.is_idle = +!gmBool(self.is_idle)
        if (self.is_idle)
          self.timer = 0xc0 | (_RAND & 0x3f) // $C0-FF. Idle period
        else self.timer = 0x40 | (_RAND & 0x3f) // $40-7F. walk period
        self.walk_dir = sign_(~_RAND & 0x1) // 1,0 = 1,-1
      }
    }
  } else {
    // DA69. Off ground
    if (!(self.cs & 0x3)) updateX(self)
  }
}

/** `Bot_udp()` — EFA2 / EF91 */
export function Bot_udp(self: BotObject): void {
  self.can_draw_self = true
  self.xScale = 1
  if (gmBool(self.is_idle)) {
    // 00AF
    GO_set_sprite(self, g.counter1 & 0x4 ? self.SPR_NORM : self.SPR_SQSH)
  } else {
    // EF91: $C bits set ($4-F) 75% of the time → NORM, clear ($0-3) 25% → BALL
    GO_set_sprite(self, self.counter & 0xc ? self.SPR_NORM : self.SPR_BALL)
  }
  self.spr_eyes = self.sprite === self.SPR_SQSH ? self.SPR_EYE2 : self.SPR_EYE1
  self.eyes_yoff = self.sprite === self.SPR_BALL ? -2 : 0
}

/** `Bot_draw()` */
export function Bot_draw(self: BotObject): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  GO_draw_sprite(self, self.sprite)
  if (self.spr_eyes)
    draw_sprite_(
      self.spr_eyes,
      0,
      self.drawX,
      self.drawY + self.eyes_yoff,
      -1,
      self.xScale,
      self.yScale,
      self.depth,
    )
  pal_swap_reset()
  Bot_draw_cover(self)
}

/** `Bot_draw_cover()` — ver 3 only; inert while `Cover_state` is 0 (as in ZALiA). */
export function Bot_draw_cover(self: BotObject): void {
  if (self.ver !== 3) return
  if (!gmBool(self.Cover_state)) return
  if (self.Cover_SPR === 0) {
    switch (self.Cover_NUM) {
      case 1: {
        const _TSIDX = hexStr(Math.max(0, g.dl_tileset.findIndex(g.ts_Natural1_HMS)))
        const _TSRC_BASE = 0x70 // $70,71,72, $80,81,82:  Bush 1
        let _TSIDX_DATA = _TSIDX
        let _TSRC_DATA = hexStr(_TSRC_BASE)
        let _RCOFF_DATA = '00'
        for (const [off, rc] of [
          [1, '01'],
          [2, '02'],
          [0x10, '10'],
          [0x11, '11'],
          [0x12, '12'],
        ] as const) {
          _TSIDX_DATA += _TSIDX
          _TSRC_DATA += hexStr(_TSRC_BASE + off)
          _RCOFF_DATA += rc
        }
        self.Cover_SPR = sprite_create_with_tiles(
          (idx) => (g.dl_tileset.get(idx) as string | undefined) ?? '',
          _TSIDX_DATA,
          _TSRC_DATA,
          _RCOFF_DATA,
        )
        self.Cover_H = spriteMeta(self.Cover_SPR).height
        break
      }
    }
  }
  if (self.depth === self.Hide_DEPTH && !gmBool(self.ogr)) {
    if (gmBool(self.Cover_tmr)) {
      self.Cover_tmr--
    } else {
      // 0: NO cover, 1: NO shake, 2: shake
      switch (self.Cover_state) {
        case 1:
          self.Cover_state = 2
          self.Cover_tmr = 0x10 + world.irandom(self.Cover_DUR1)
          self.Cover_xoff = 1
          break
        case 2:
          self.Cover_state = 1
          self.Cover_tmr = self.Cover_DUR1 + world.irandom(self.Cover_DUR2)
          self.Cover_xoff = 0
          break
      }
    }
  } else {
    self.Cover_tmr = 0
    self.Cover_state = +!!self.Cover_state // 0,1
  }
  if (self.Cover_state === 2 && !(g.counter1 & 0x3)) self.Cover_xoff = +!self.Cover_xoff
  const _x = self.Cover_X + self.Cover_xoff
  const _y = self.Cover_YB - (self.Cover_H >> 1) + self.Cover_yoff
  if (self.Cover_SPR) draw_sprite_(self.Cover_SPR, 0, _x, _y, self.Cover_PI, 1, 1, self.depth)
}

/** `Bot_end()` — deleted the generated cover sprite; the adapter owns sprite lifetimes now. */
export function Bot_end(self: BotObject): void {
  if (self.objectName === 'Bot_A' && self.ver === 3) self.Cover_SPR = 0
}

registerObject('Bot_A', Bot_A)
registerObject('Bot_B', Bot_B)
registerScripts({ Bot_init2, Bot_update, Bot_udp, Bot_draw, Bot_draw_cover, Bot_end })
