export class Moa_A extends Enemy {
  readonly objectName: 'Moa_A' | 'Moa_B' = 'Moa_A'
  sprL = 'spr_Moa2'
  sprR = 'spr_Moa1'
  sprRXOff = 0
  hspd_impel_dir = 1
  hDir = 0 // 0401,X. horizontal Direction. 1 or -1
  NEED_CROSS = false
  DEPTH1 = 0
  DEPTH2 = 0
  HSPD1 = 0x14
}

/** `Moa_init2()` */
export function Moa_init2(self: Moa_A): void {
  const g = gp()
  const p = pp()
  switch (self.ver) {
    case 1:
      GO_init_palidx(self, G.PI_MOB_RED)
      break
    case 2:
      GO_init_palidx(self, G.PI_MOB_PUR)
      break
    default:
      break
  }
  GO_depth_init(self, DEPTH_FLYER)
  self.sprL = 'spr_Moa2'
  self.sprR = 'spr_Moa1'
  self.sprRXOff = 0
  self.hspd_dir = byte_dir(self.hspd)
  self.hspd_impel_dir = self.hspd_dir
  self.hDir = 0
  self.timer = 0
  self.NEED_CROSS = self.ver === 2
  if (self.ver === 2 && g.area_name === Area_TownA) {
    GO_init_palidx(self, G.PI_MOB_PUR)
    self.XP_IDX = 0x0e
    self.xp = (g.dl_XP.get(self.XP_IDX) as number) ?? 0
    self.DROP_BITS = 0x00
    self.drop_bits = self.DROP_BITS
  }
  if (self.ver === 3) {
    // ver 3 for halloween scene
    self.DEPTH1 = DEPTH_BG8 + 3
    self.DEPTH2 = DEPTH_FG8 - 3
    GO_depth_init(self, self.DEPTH1)
    const _PI = G.PI_MOB_BLU
    GO_init_palidx(self, _PI)
    const _PAL = build_pal(p.C_WHT1, p.C_WHT1, p.C_BLU2)
    change_pal(strReplaceAt(p.pal_rm_curr, get_pal_pos(_PI), _PAL.length, _PAL))
    self.HSPD1 = 0x14
    self.hspd_dir = -sign_(self.x > g.rm_w_)
    self.hspd = (self.HSPD1 * self.hspd_dir) & 0xff
    self.hspd_impel_dir = self.hspd_dir
    self.counter = 0
  }
}

/** `Moa_update()` — DACF */
export function Moa_update(self: Moa_A): void {
  const g = gp()
  const P = pc()
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // DAD2: JSR DE54
  GOB_update_2a(self)
  // DAD5
  if (self.ver === 1 || !self.NEED_CROSS || fp().items & ITM_CROS) update_EF11(self)
  // DAE4
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  switch (self.ver) {
    case 3: {
      if (!gmBool(self.counter)) {
        if (
          sign_(self.x > g.rm_w_) === byte_dir(self.hspd) &&
          Math.abs(self.x - g.rm_w_) >= (g.rm_w_ >> 3) * 5
        ) {
          self.counter = 1
          self.hspd_impel_dir = -byte_dir(self.hspd)
        }
      } else {
        // Turning around. DB2D
        updateY(self)
        if (g.counter0 & 0x1) self.hspd = (self.hspd + self.hspd_impel_dir) & 0xff
        if (self.hspd === ((self.HSPD1 * self.hspd_impel_dir) & 0xff)) {
          // DB47
          self.counter = 0
          if (self.depth === self.DEPTH1) GO_depth_init(self, self.DEPTH2)
          else GO_depth_init(self, self.DEPTH1)
        }
        self.hspd_dir = byte_dir(self.hspd)
      }
      updateX(self)
      self.facing_dir = self.hspd_dir
      break
    }
    default: {
      const _HSPD = self.hspd
      self.facing_dir = dir_to_pc(self)
      self.hspd += P.hspd + (DC91_carry(self) ? 1 : 0)
      self.hspd = self.hspd + ((8 * self.facing_dir) & 0xff) + (self.hspd > 0xff ? 1 : 0)
      self.hspd &= 0xff
      updateX(self)
      self.hspd = _HSPD
      self.facing_dir = self.hspd_dir
      // DB02
      if (!gmBool(self.counter)) {
        if (!self.timer) {
          self.counter = 1
          self.hspd_impel_dir = self.facing_dir
          const _DIST = self.yt - g.view_yt_og
          if (_DIST < 0x48 || _DIST >= 0xc8) {
            // OG: $28 below HUD / $20 above view btm
            if (_DIST >= 0xc8) self.vspd = byte(-0x08)
            else self.vspd = byte(0x08)
          } else {
            if (rand(self) & 0x1) self.vspd = byte(-0x08)
            else self.vspd = byte(0x08)
          }
        }
      } else {
        // Turning around. DB2D
        updateY(self)
        self.hspd = (self.hspd + -self.hspd_impel_dir) & 0xff
        if (self.hspd === ((0x20 * -self.hspd_impel_dir) & 0xff)) {
          // DB47
          self.counter = 0
          self.timer = 0x20 // 0.533s
        }
        self.hspd_dir = byte_dir(self.hspd)
      }
      break
    }
  }
}

/** `Moa_udp()` — EFF2 */
export function Moa_udp(self: Moa_A): void {
  const g = gp()
  self.can_draw_self = true
  if (g.counter1 & 0x10) self.yScale = 1
  else self.yScale = -1
  if (self.hspd < 0x80) {
    self.xScale = 1
    self.sprL = 'spr_Moa2'
    self.sprR = 'spr_Moa1'
  } else {
    self.xScale = -1
    self.sprL = 'spr_Moa1'
    self.sprR = 'spr_Moa2'
  }
  // F00D
  let _val = self.hspd
  if (self.hspd & 0x80) _val ^= 0xff
  _val = _val >> 2
  if (_val < 6) {
    self.sprRXOff = -1
    if (_val < 4) self.sprRXOff = -2
    if (_val < 2) self.sprRXOff = -3
  } else self.sprRXOff = 0
  // F1D7
  if (self.ver === 3) self.can_draw_self = (g.counter0 & 0x1) !== 0
}

/** `Moa_draw()` */
export function Moa_draw(self: Moa_A): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawState.depth = self.depth
  pal_swap_set(self.palidx)
  draw_sprite_(self.sprR, 0, self.drawX + 4 + self.sprRXOff, self.drawY, -1, self.xScale, self.yScale)
  draw_sprite_(self.sprL, 0, self.drawX - 4, self.drawY, -1, self.xScale, self.yScale)
  pal_swap_reset()
}

// ------------------------------------------------------------------------------------------------ FieryMoa
export class Moa_B extends Moa_A {
  override readonly objectName = 'Moa_B' as const
  hspd_dir_reset = 1 // 0081[eIndex]
  RESET_Y = 0
}

/** `FieryMoa_init2()` */
export function FieryMoa_init2(self: Moa_B): void {
  const g = gp()
  GO_init_palidx(self, G.PI_MOB_ORG)
  GO_depth_init(self, DEPTH_FLYER)
  self.sprL = 'spr_Moa2'
  self.sprR = 'spr_Moa1'
  self.sprRXOff = 0
  self.projectile_OBJ = 'Flame1'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.hspd_dir = byte_dir(self.hspd)
  self.hspd_dir_reset = self.hspd_dir
  self.timer = 0
  self.RESET_Y = g.rm_h - 0x6b // room_height
  let _spawn_datakey = self.dk_spawn
  if (self.dk_spawn !== undefined) {
    const r = fp().dm_rando.get(
      STR_Randomize + STR_Enemy + STR_Spawn + self.dk_spawn + STR_Spawn + STR_Datakey + STR_Randomized,
    )
    _spawn_datakey = r !== undefined ? String(r) : self.dk_spawn
  }
  const _DATAKEY = `${STR_Reset}_y`
  if (_spawn_datakey !== undefined) {
    for (let _i = 0x1; _i <= 0xf; _i++) {
      let _val = g.dm_spawn.get(_spawn_datakey + STR_Data + hexStr(_i)) ?? 0
      if (typeof _val === 'string') {
        let _pos = _val.indexOf(_DATAKEY) + 1
        if (_pos) {
          _pos += _DATAKEY.length
          _val = _val.substr(_pos - 1, _val.length - (_pos - 1))
          self.RESET_Y = str_hex(_val)
          break
        }
      }
    }
  }
}

/** `FieryMoa_update()` — B909 */
export function FieryMoa_update(self: Moa_B): void {
  const g = gp()
  const P = pc()
  if (self.counter & 0x3) {
    // Vertical sway
    if (g.counter1 & 0x10)
      self.vspd = 0x04 & 0xff // $10: dur 0.267s
    else self.vspd = -0x04 & 0xff
    updateY(self)
    updateX(self)
    GOB_update_cs_2a(self) // checks both left & right to prevent Flame spawning in solid wall
    GOB_update_2(self)
    if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  }
  // B929
  switch (self.counter & 0x3) {
    case 0: {
      // B93C
      if (gmBool(self.timer)) break
      // Appear at the view edge PC is moving towards, move towards PC, turn around at PC and move back,
      // leaving flames in the PC's path.
      self.hspd = (0x20 * -sign_(P.hspd_dir)) & 0xff
      set_hspd_dir(self)
      self.hspd_dir_reset = self.hspd_dir
      self.facing_dir = self.hspd_dir
      let _X = viewXR() - self.ww_
      if (gmBool(self.hspd_dir)) _X = viewXL() + self.ww_
      let _Y = self.RESET_Y
      if (gmBool(cam_yt_range())) _Y = P.yt - 0x2b
      set_xy(self, _X, _Y)
      // Duration until turn around.
      if (gmBool(P.hspd))
        self.timer = 0x10 // $10: 0.267s
      else self.timer = 0x50 // $50: 1.333s
      // With wideview it takes longer to make it to the PC: add the view-width difference as a percentage.
      let _extra = Math.abs(1 - VIEW_W_OG / VIEW_W_WD)
      _extra = round(self.timer * _extra)
      // MOD.  Start outside of view instead of inside.
      if (gmBool(self.hspd_dir)) set_xy(self, viewXL() - self.ww_, self.y)
      else set_xy(self, viewXR() + self.ww_, self.y)
      _extra += Math.trunc(Math.abs(self.x - _X) / Math.max(1, abs8b(self.hspd) >> 4))
      self.timer += _extra
      self.counter = (self.counter + 1) & 0xff
      break
    }
    case 1: {
      // B96D.  Moving towards PC
      if (gmBool(self.timer)) break
      self.timer = 0x40 // $40: 1.067s
      self.counter = (self.counter + 1) & 0xff
      break
    }
    case 2: {
      // B97C.  Turning around
      if (gmBool(self.timer)) {
        set_xy(self, self.x, self.y - 1)
        self.hspd = (self.hspd + -self.hspd_dir_reset) & 0xff
        self.hspd_dir = byte_dir(self.hspd)
      } else self.counter = (self.counter + 1) & 0xff // B98E
      break
    }
    default: {
      // 3: B991.  Moving towards view edge. $00,10, $40,50, $80,90, $C0,D0
      if (!(g.counter1 & 0x2f) && !(self.cs & 0x4) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
        // Prevent spawn proj in solid.
        const p = GOC1_create(
          self.xl,
          self.yt,
          self.facing_dir,
          self.projectile as ObjectName,
          self.projectile_ver,
        )
        p.hspd = 0
      }
      if (!wINw(self.xl, self.ww, viewXL(), viewXR())) {
        self.timer = 0xbf // $BF(191): 3.183s
        self.counter = (self.counter + 1) & 0xff
      }
      break
    }
  }
}

export function registerMoa(): void {
  registerObject('Moa_A', Moa_A)
  registerObject('Moa_B', Moa_B)
  registerScripts({ Moa_init2, Moa_update, Moa_udp, Moa_draw, FieryMoa_init2, FieryMoa_update })
}
registerMoa()
