import { MAX_GOB1 } from '@z2/data'

/**
 * The original game's random number system, NES RAM `$051A-$0522` — ported from ZALiA
 * `update_og_rand.gml` / `rand.gml` / `g_Create.gml:823-831`.
 *
 * A shift register of `size` bytes advanced once per frame: the new top bit is bit 1 of byte 0 XOR
 * bit 1 of byte 1, and each byte shifts right, carrying its low bit into the next byte's high bit.
 * Game objects read "their" byte by update slot (`rand()` → `bytes[1 + updateIdx]`).
 */
export class OgRandom {
  /** OG NES has 9 bytes; ZALiA widens it to MAX_GOB1 + 3 so every enemy slot has a byte. */
  static readonly SIZE = MAX_GOB1 + 3
  static readonly START_VAL = 0xa5

  readonly bytes: number[]
  /** RandomOG_started: the register only starts once the player's state leaves 0 (first action room). */
  started = false

  constructor(readonly size = OgRandom.SIZE) {
    this.bytes = new Array<number>(size).fill(0)
  }

  /** `update_og_rand()`: call once per frame with whether the PC state is non-zero. */
  update(pcActive: boolean): void {
    if (!this.started) {
      if (pcActive) {
        this.started = true
        this.bytes[0] = OgRandom.START_VAL
      }
      return
    }
    const b = this.bytes
    let carry = (((b[0] as number) & 0x2) ^ ((b[1] as number) & 0x2)) << 6 // $00 or $80
    for (let i = 0; i < this.size; i++) {
      const cur = b[i] as number
      b[i] = (cur >> 1) | carry
      carry = (cur & 0x1) << 7
    }
  }

  /**
   * `rand()` for an object in update slot `updateIdx`; falls back to `fallback()` (GML `irandom($FF)`)
   * when the slot is outside the register.
   */
  rand(updateIdx: number, fallback: () => number): number {
    if (updateIdx >= 0 && updateIdx < this.size - 1) return this.bytes[1 + updateIdx] as number
    return fallback()
  }

  reset(): void {
    this.bytes.fill(0)
    this.started = false
  }
}
