/**
 * `Audio_Create()` — builds the `Audio` singleton's data from `audioTable.json` (extracted from
 * `Audio_Create.gml` by `pnpm tool audio-table` into `audioTable.ts`) with ZALiA's registration order and guards preserved:
 * a set/track is registered only if its probe sound is in the build (`hasSound`, ZALiA's
 * `asset_get_index(...) != -1`), so missing audio sets degrade instead of failing.
 * Dropped: `DEV` timing prints, `audio_group_load`, the commented Isabelle-Chiming length table.
 */
import {
  dk_RandomCustom,
  dk_SceneMusicThemeException,
  STR_Audio,
  STR_AudioGroup,
  STR_Body,
  STR_Count,
  STR_Creator,
  STR_Description,
  STR_Intro,
  STR_Length,
  STR_Loop,
  STR_Music,
  STR_Name,
  STR_Num,
  STR_Qualified,
  STR_Rando,
  STR_Random,
  STR_Set,
  STR_Theme,
  STR_Town,
  STR_Track,
  STR_Value,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { DsList, DsMap } from '../../runtime/ds'
import { Audio } from './Audio'
import { add_sound_data } from './addSoundData'
import { audioTable } from './audioTable'
import { Gd, gd, hasSound } from './deps'

export interface AudioTableJson {
  sets: {
    dk: string
    name: string
    guard?: string
    hidden?: boolean
    exception01?: boolean
    exception02?: boolean
  }[]
  entries: {
    sound: string
    volume: number
    theme?: string
    set?: string
    intro?: string
    loop?: boolean
    guard?: string
    named?: string
  }[]
  descriptions: Record<string, string>
  exceptions01: string[]
  exceptions02: string[]
  dl1: { sound: string; intro?: string; guard?: string }[]
  dl2: { sound: string; intro?: string; guard?: string }[]
  halloweenTownMusic: { sound: string; guard?: string }[]
  noLoop: { sound: string; guard?: string }[]
  aliases: Record<string, string>
  lengths: Record<string, { intro?: number; body?: number; guard?: string }>
  randoValue01: { sound: string; guard?: string }[]
  randoValue02: { sound: string; guard?: string }[]
  /** extractor diagnostics — always empty for a clean extraction */
  unhandled: string[]
}

const RANDOM_SETS = new Set([`${STR_Random}1`, dk_RandomCustom])

export function Audio_Create(): void {
  const A = Audio
  A.testing_num = 0
  A.dm = new DsMap()
  A.dm.set(`${STR_AudioGroup}_snd`, 'snd')
  A.dm.set(`${STR_AudioGroup}_mus`, 'mus')
  A.named.clear()
  A.dm_music_inst = new DsMap()
  A.instNames.clear()

  // ---- audio sets ---------------------------------------------------------
  const _dk1 = STR_Audio + STR_Set + STR_Creator + STR_Name
  A.dl_AUDIO_SETS = new DsList<string>()
  let countTaken = false
  for (const s of audioTable.sets) {
    if (s.guard && !hasSound(s.guard)) continue
    if (RANDOM_SETS.has(s.dk) && !countTaken) {
      A.AudioSets_COUNT = A.dl_AUDIO_SETS.size
      A.dl_random_custom = new DsList<string>()
      for (const x of A.dl_AUDIO_SETS) A.dl_random_custom.add(x)
      countTaken = true
    }
    if (!s.hidden) A.dl_AUDIO_SETS.add(s.dk)
    A.dm.set(_dk1 + s.dk, s.name)
    if (s.exception01) A.dm.set(`${dk_SceneMusicThemeException}01${s.dk}`, true)
    if (s.exception02) A.dm.set(`${dk_SceneMusicThemeException}02${s.dk}`, true)
  }
  if (!countTaken) A.AudioSets_COUNT = A.dl_AUDIO_SETS.size

  A.audio_set = A.dl_AUDIO_SETS.get(0) ?? '_Default'
  A.snd_vol = A.Volume_DEFAULT
  A.audio_group_set_gain('snd', A.snd_vol / 10)
  A.mus_vol = A.Volume_DEFAULT
  A.audio_group_set_gain('mus', A.mus_vol / 10)

  // ---- themes / tracks ------------------------------------------------------
  for (const [theme, text] of Object.entries(audioTable.descriptions)) {
    A.dm.set(theme + STR_Description, resolveDescription(text))
  }
  for (const e of audioTable.entries) {
    if (e.guard && !hasSound(e.guard)) continue
    const intro = e.intro && hasSound(e.intro) ? e.intro : 0 // max(0, asset_get_index(intro))
    const sound = add_sound_data(
      e.sound,
      e.volume,
      e.theme ?? 0,
      e.set ?? '_Default',
      intro,
      e.loop === undefined ? -1 : e.loop,
    )
    if (e.named) A.named.set(e.named, sound)
  }
  for (const [alias, target] of Object.entries(audioTable.aliases)) {
    const v = A.named.get(target)
    if (v) A.named.set(alias, v)
  }
  for (const t of audioTable.exceptions01) A.dm.set(`${dk_SceneMusicThemeException}01${t}`, true)
  for (const t of audioTable.exceptions02) A.dm.set(`${dk_SceneMusicThemeException}02${t}`, true)
  // These tracks should persist into certain rooms like encounters
  for (const r of audioTable.dl1)
    if (!r.guard || hasSound(r.guard)) A.dm.set(`${dk_SceneMusicThemeException}01${r.sound}`, true)
  // These tracks should resume at interruption pos if interrupted
  for (const r of audioTable.dl2)
    if (!r.guard || hasSound(r.guard)) A.dm.set(`${dk_SceneMusicThemeException}02${r.sound}`, true)
  for (const [name, l] of Object.entries(audioTable.lengths)) {
    if (l.guard && !hasSound(l.guard)) continue
    if (l.intro !== undefined) A.dm.set(name + STR_Intro + STR_Length, l.intro)
    if (l.body !== undefined) A.dm.set(name + STR_Body + STR_Length, l.body)
  }
  const _dk1r = `${STR_Rando + STR_Value}01` // Limit chance of rando selecting sound
  const _dk2r = `${STR_Rando + STR_Value}02` // Exclude track from rando audio set (can be turned on in rando custom)
  for (const r of audioTable.randoValue01) if (!r.guard || hasSound(r.guard)) A.dm.set(r.sound + _dk1r, true)
  for (const r of audioTable.randoValue02) if (!r.guard || hasSound(r.guard)) A.dm.set(r.sound + _dk2r, true)
  for (const r of audioTable.noLoop) if (!r.guard || hasSound(r.guard)) A.dm.set(r.sound + STR_Loop, false) // Wyng says the credits track should NOT loop

  // fire sound rotation (SND_FIRE_VER 1)
  A.SND_FIRE_VER = 1
  A.dl_snd_fire = new DsList()
  A.dl_snd_fire.add(A.sound('SND_FIRE_1A')) // 0: First idx is most recent one
  A.dl_snd_fire.add(0) // 1: can play
  A.dl_snd_fire.add(-1) // 2: volume.  -1: use default
  A.dl_snd_fire.add(0) // 3: timer
  A.dl_snd_fire.add(0x07) // 4: timer reset
  A.dl_snd_fire.add(A.sound('SND_FIRE_1A')) // 5:
  A.dl_snd_fire.add(A.sound('SND_FIRE_1B')) // 6:
  A.dl_snd_fire.add(A.sound('SND_FIRE_1C')) // 7:
  A.dl_snd_fire.add(A.sound('SND_FIRE_1D')) // 8:

  // Halloween town music pool (`global.dl_Halloween_TOWN_MUSIC`)
  const hallow = new DsList<string>()
  for (const r of audioTable.halloweenTownMusic) if (!r.guard || hasSound(r.guard)) hallow.add(r.sound)
  Gd().dl_Halloween_TOWN_MUSIC = hallow

  A.PRIORITY_TOP = 0xff
  A.PRIORITY_LOW = 0
  // FIXED: ZALiA seeds `rm_music_theme = STR_Title` here (`Audio_Create.gml:1476-1477`) — the theme the
  // *first* room will resolve to — and `Audio_Room_Start` opens by copying it into `rm_music_theme_prev`
  // (`:40`). `Audio` is created inside the boot room, after that room's Room Start has already fired, so
  // the title screen's is the first `Audio_Room_Start` there is, and its
  // `_IS_DIFF_THEME = rm_music_theme != rm_music_theme_prev` came out **false**. The `else` branch then
  // zeroes `mus_rm_intr`, so the title prelude (`mus_Title_Intro_1a`, the downward arpeggio) never played
  // on a first boot — only on a later entry from the file select or the game end, where the previous theme
  // really was something else. It also left `mus_rm_body` at 0 on the first title screen for any RANDOM
  // audio set, whose body is only drawn `if (_IS_DIFF_THEME)`.
  //
  // No room has started yet at Create time, so there is no room music theme yet: leave it empty and let
  // the first Room Start be a change like any other. The one thing that reads it earlier is
  // `Audio_update`'s `rm_music_theme == STR_Title` timing-sound gate, which used to start
  // `snd_Default_Title_Intro_no_volume` during the splash only for the title's own Room Start to stop it
  // again a few frames later.
  A.rm_music_theme = ''
  A.rm_music_theme_prev = A.rm_music_theme
  A.current_theme_random_track = 0

  A.mus_rm_intr = 0
  A.mus_rm_body = 0
  A.mus_rm_curr = 0
  A.mus_rm_inst = 0
  A.mus_rm_body_prev = 0
  A.encounter_sound_inst = 0
  A.can_play_mus_rm_body = true
  A.mus_rm_started = false
  A.can_play_boss_music = false
  A.mus_rm_pos_prev = 0
  A.mus_rm_pos_curr = 0
  A.timing_sound_position_prev = 0
  A.timing_sound_position_curr = 0
  A.timing_sound_inst = 0
  A.mus_rm_body_last_pos = 0
  A.mus_asset_name_interrupted = 0
  A.walk_water_played_count = 0
  A.LowHPSound_counter1 = 0
  A.LowHPSound_counter2 = 0

  // RANDOM-CUSTOM: every music track of every theme starts qualified
  A.dm_random_custom = new DsMap()
  const _count = Number(A.dm.val(STR_Theme + STR_Count + STR_Music))
  for (let _i = 1; _i <= _count; _i++) {
    const _theme = String(A.dm.get(STR_Theme + STR_Music + hexStr(_i)))
    const _count1 = Number(A.dm.val(_theme + STR_Track + STR_Count + STR_Music))
    for (let _j = 1; _j <= _count1; _j++) A.dm_random_custom.set(_theme + hexStr(_j) + STR_Qualified, true)
  }
}

/** `{TOWN_NUM:<town>}` placeholders come from `string(val(g.dm_town[?STR_Town+STR_Num+_town_name]))`. */
function resolveDescription(text: string): string {
  return text.replace(/\{TOWN_NUM:([^}]+)\}/g, (_m, town: string) =>
    String(gd().dm_town?.get(STR_Town + STR_Num + town) ?? 0),
  )
}
