/** `NPC_D_init2()` — Shop NPC */
export function NPC_D_init2(self: NPC_D): void {
  self.sprite_datakey = STR_Jack // STR_Jack: Fat man,   STR_Bill: Skinny man
  self.Product1_OBJ = 0
  self.Product2_OBJ = 0
  self.Product3_OBJ = 0
  self.Product1_COST = 10
  self.Product1_COST2 = self.Product1_COST >> 1
  self.Product1_COST3 = self.Product1_COST2 >> 1
  self.Product1_cost = self.Product1_COST
  self.Product2_COST = 10
  self.Product3_COST = 10
  const randoItems = gmBool(
    val(G.dm_save_file_settings.get(STR_Randomize + STR_Item + STR_Locations)) as number,
  )
  switch (self.ver) {
    case 1:
      self.Product1_OBJ = val(g.dm_ITEM.get(hexStr(ITM_MAP2) + STR_Object), 'ItmK9') as ObjectName // MAP2
      self.Product1_COST = MAP2_PRICE
      if (randoItems)
        self.Product1_COST = val(f.dm_rando.get(`${STR_Map}2${STR_Cost}`), self.Product1_COST) as number
      break
    case 2:
      self.Product1_OBJ = val(g.dm_ITEM.get(hexStr(ITM_MAP1) + STR_Object), 'ItmK8') as ObjectName // MAP1
      self.Product1_COST = MAP1_PRICE
      if (randoItems)
        self.Product1_COST = val(f.dm_rando.get(`${STR_Map}1${STR_Cost}`), self.Product1_COST) as number
      break
  }
  // Bargaining costs
  const _val = 20
  self.Product1_COST2 = Math.max(_val, self.Product1_COST >> 1)
  self.Product1_COST3 = Math.max(_val >> 1, self.Product1_COST2 >> 1)
  self.Product1_cost = self.Product1_COST
  self.Bargaining_ENABLED = true
  GO_sprite_init(self, NPC_get_init_sprite(self))
  update_body_hb_1a(self)
  self.sub_state = self.SUB_STATE_IDLE1
  self.hspd = 0
  self.ITEM_BIT = val(g.dm_ITEM.get(String(self.Product1_OBJ) + STR_Bit)) as number
  self.Merchant_NUM = val(g.dm_spawn.get(self.dk_spawn + STR_Merchant + STR_Num)) as number
  // Because dk_spawn can change while in dev, why not check by g.rm_name..
  for (let _i = val(g.dm_spawn.get(STR_Merchant + STR_Count)) as number; _i >= 1; _i--) {
    const rm = g.dm_spawn.get(STR_Merchant + hexStr(_i) + STR_Rm + STR_Name)
    if (rm !== undefined && g.rm_name === rm) {
      self.Merchant_NUM = _i
      break
    }
  }
  const _datakey = STR_Merchant + hexStr(self.Merchant_NUM)
  self.OfferDeclined_DATAKEY = `${_datakey}_OfferDeclined`
  self.Paid_DATAKEY = `${_datakey}01${STR_Paid}`
  if (gmBool(val(f.dm_quests.get(self.Paid_DATAKEY)) as number)) {
    // if already paid
    self.timer = 0
    self.sub_state = self.SUB_STATE_IDLE2
  } else {
    const _CLM = 0x25
    const _ROW = g.rm_row0 + 0x16
    GameObject_create((_CLM << 3) + 4, _ROW << 3, 'LoDoA', 3)
  }
  self.scr_inst_end = NPC_D_end as (s: unknown) => void
}

/**
 * FIXED (no counterpart in ZALiA): paying the merchant takes `g.pc_lock = PC_LOCK_ALL` in `SUB_STATE_OFFER`
 * and gives it back from `SUB_STATE_UNLOCK`, once every `LoDoA` the payment opened has finished opening —
 * so only this instance can end the lock it took. Nothing in the shipped game destroys the merchant in that
 * window, but the failure mode if anything did is the restore fairy's: `PC_LOCK_ALL` with no one left to
 * clear it, and a locked player cannot walk to an exit to reach `PC_Room_Start`. Hand it back on teardown.
 */
export function NPC_D_end(self: NPC_D): void {
  if (self.sub_state === self.SUB_STATE_UNLOCK) g.pc_lock = 0
}

const STR_Num = '_Num'

/** `NPC_D_update()` */
export function NPC_D_update(self: NPC_D): void {
  self.hspd = 0
  NPC_update_1(self)
  if (!self.is_talking) {
    Merchant_update_1(self) // update_EF11(), set facingDir, counter = 0;
    if (self.sub_state === self.SUB_STATE_IDLE1 || self.sub_state === self.SUB_STATE_IDLE2) NPC_update_2(self)
  }
  const DW = g.DIALOGUE_WINDOW
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE1: {
      if (self.timer) break
      if (self.is_talking && g.dialogue_source === self) {
        const _DECLINED_COUNT = val(f.dm_quests.get(self.OfferDeclined_DATAKEY + STR_Count)) as number
        if (self.Bargaining_ENABLED && _DECLINED_COUNT >= 0x08) {
          self.dialogue_ver = 'E'
          self.Product1_cost = self.Product1_COST2
        } else if (self.Bargaining_ENABLED && _DECLINED_COUNT >= 0x10) {
          // FIDELITY: unreachable in ZALiA (>=8 catches >=16 first) — kept as written
          self.dialogue_ver = 'F'
          self.Product1_cost = self.Product1_COST3
        } else if (
          gmBool(val(G.dm_save_file_settings.get(STR_Randomize + STR_Item + STR_Locations)) as number)
        ) {
          self.dialogue_ver = 'D'
          self.Product1_cost = self.Product1_COST
        } else {
          self.dialogue_ver = 'A'
          self.Product1_cost = self.Product1_COST
        }
        if (!gmBool(val(f.dm_quests.get(self.Paid_DATAKEY)) as number)) {
          // if have NOT paid
          const _dk = self.dialogue_datakey + self.dialogue_ver
          // This removes the product cost in front of "-P" (resets to default text)
          let _dialogue = DW.dm_dialogue.get(_dk + self.dialogue_ver) // default
          if (_dialogue !== undefined) DW.dm_dialogue.set(_dk, _dialogue)
          // Add the product cost in front of "-P"
          _dialogue = DW.dm_dialogue.get(_dk)
          if (_dialogue !== undefined) {
            // Add in the cost to the dialogue
            const _POS = String(_dialogue).indexOf('-P') + 1
            if (_POS)
              DW.dm_dialogue.set(_dk, string_insert(String(self.Product1_cost), String(_dialogue), _POS))
          }
          g.gui_state = g.gui_state_DIALOGUE3
          self.timer = 0
          self.sub_state = self.SUB_STATE_OFFER
        } else {
          self.timer = 0
          self.sub_state = self.SUB_STATE_IDLE2
        }
      }
      break
    }
    case self.SUB_STATE_OFFER: {
      // Player is offered product with "YES" or "NO" options.
      if (self.timer) break
      if (g.gui_state !== g.gui_state_NONE) break
      // A choice has been made.
      if (DW.cursor_option === input.L) {
        // "YES". Player accepted offer
        if (f.xp >= self.Product1_cost) {
          f.xpDrain += self.Product1_cost
          g.pc_lock = PC_LOCK_ALL
          f.dm_quests.set(self.Paid_DATAKEY, 1)
          // GM's `with(Obj)` skips instances destroyed earlier this frame
          for (const d of world.instances)
            if (d.exists && (d as GameObject).objectName === 'LoDoA') (d as GameObject).counter = -1 // -1: Starts opening process
          self.timer = 0
          self.sub_state = self.SUB_STATE_UNLOCK
        } else {
          // Not enough money.
          NPC_activate_dialogue(self)
          self.dialogue_ver = 'B'
          self.timer = 0
          self.sub_state = self.SUB_STATE_LOWP
        }
      } else {
        // "NO". Player declined offer.
        f.dm_quests.set(
          self.OfferDeclined_DATAKEY + STR_Count,
          (val(f.dm_quests.get(self.OfferDeclined_DATAKEY + STR_Count)) as number) + 1,
        )
        g.pc_lock = 0
        self.timer = 0
        self.sub_state = self.SUB_STATE_IDLE1
      }
      break
    }
    case self.SUB_STATE_LOWP: {
      if (self.timer) break
      self.dialogue_ver = 'B'
      if (g.gui_state !== g.gui_state_NONE) break
      g.pc_lock = 0
      self.timer = 0
      self.sub_state = self.SUB_STATE_IDLE1
      break
    }
    case self.SUB_STATE_UNLOCK: {
      if (self.timer) break
      let doorExists = false
      for (const d of world.instances)
        if ((d as GameObject).objectName === 'LoDoA' && d.exists) doorExists = true
      if (doorExists) break
      g.pc_lock = 0
      self.timer = 0
      self.sub_state = self.SUB_STATE_IDLE2
      break
    }
    case self.SUB_STATE_IDLE2: {
      if (self.timer) break
      self.dialogue_ver = 'C' // C: "I HAVE NOTHING ELSE TO OFFER YOU."
      break
    }
  }
}

/** `NPC_D_udp()` */
export function NPC_D_udp(self: NPC_D): void {
  self.can_draw_self = true
  // NPC_udp_2 — update `RandoHint_hint_num`
  if (
    self.RandoHint_hint_num &&
    g.dm_RandoHintsRecorder.get(`_Hint${hexStr(self.RandoHint_hint_num)}_Dialogue`) !== undefined
  )
    self.RandoHint_hint_num = 0
}
