/**
 * GML builtins and idioms the `rando` folder leans on. Nothing here is a ZALiA script of its own except
 * `isVal` (`isVal.gml`, shared helper) — the rest are GameMaker builtins reproduced with the world PRNG so
 * generation stays deterministic for a given `random_set_seed(Rando_SEED)`.
 */
import { STR_Data } from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import type { DsGrid, DsList } from '../../runtime/ds'
import { world } from '../../runtime/world'
import { sdm } from '../other/index'
import type { Rando } from './Rando'

/** `isVal(base value, compare values...)` — true when at least one compare value equals the base. */
export function isVal<T>(base: T, ...values: T[]): boolean {
  for (const v of values) if (base === v) return true
  return false
}

/** GM `choose(a, b, …)` */
export function choose<T>(...values: T[]): T {
  return values[world.irandom(values.length - 1)] as T
}

/** GM `irandom_range(from, to)` — inclusive both ends. */
export function irandom_range(from: number, to: number): number {
  return from + world.irandom(to - from)
}

/** GM `ds_list_shuffle` — Fisher-Yates over the world PRNG. */
export function ds_list_shuffle<T>(list: DsList<T>): void {
  const a = list.items
  for (let i = a.length - 1; i > 0; i--) {
    const j = world.irandom(i)
    const t = a[i] as T
    a[i] = a[j] as T
    a[j] = t
  }
}

/** GM `ds_list_copy(dst, src)` */
export function ds_list_copy<T>(dst: DsList<T>, src: DsList<T>): void {
  dst.items.length = 0
  dst.items.push(...src.items)
}

/**
 * GM `ds_grid_copy(dst, src)`. GM resizes `dst` to `src`; the port's `DsGrid` has a fixed size, so the
 * cells are copied in place over the overlapping region. Every ZALiA use here copies a `*_DEFAULT` grid
 * onto its same-sized live twin (`f.dg_xp_next`, `g.dg_spell_cost`, `g.dg_enemy_damage`), so the sizes
 * always match; a mismatch would be a data bug, not a resize.
 */
export function ds_grid_copy<T>(dst: DsGrid<T>, src: DsGrid<T>): void {
  const w = Math.min(dst.width, src.width)
  const h = Math.min(dst.height, src.height)
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) dst.set(x, y, src.get(x, y) as T)
}

/** GM `ds_list_insert(list, index, value)` */
export function ds_list_insert<T>(list: DsList<T>, index: number, value: T): void {
  list.items.splice(index, 0, value)
}

/** GM `ds_list_delete(list, index)` — deletes by index; a `-1` index is a no-op here (GML ignores it). */
export function ds_list_delete<T>(list: DsList<T>, index: number): void {
  if (index >= 0 && index < list.items.length) list.items.splice(index, 1)
}

/** Remove `value` from `list` if present — the `_idx = find_index(); if (_idx!=-1) delete()` idiom. */
export function ds_list_remove<T>(list: DsList<T>, value: T): boolean {
  const idx = list.items.indexOf(value)
  if (idx === -1) return false
  list.items.splice(idx, 1)
  return true
}

/** `ds_list_find_index(list, v) != -1` */
export function inList<T>(list: DsList<T>, value: T): boolean {
  return list.items.indexOf(value) !== -1
}

/** GM `string_pos(substr, str)` — 1-based position, 0 when absent. */
export function string_pos(substr: string, str: string): number {
  return str.indexOf(substr) + 1
}

/** GM `string_repeat(str, count)` — negative counts give "". */
export function string_repeat(str: string, count: number): string {
  return count > 0 ? str.repeat(count) : ''
}

/** GM `string_copy(str, index, count)` — 1-based index. */
export function string_copy(str: string, index: number, count: number): string {
  return str.substr(index - 1, count)
}

/** GM `string_delete(str, index, count)` — 1-based index. */
export function string_delete(str: string, index: number, count: number): string {
  return str.slice(0, index - 1) + str.slice(index - 1 + count)
}

/** GM `string_insert(substr, str, index)` — 1-based index. */
export function string_insert(substr: string, str: string, index: number): string {
  return str.slice(0, index - 1) + substr + str.slice(index - 1)
}

/** GM `string_letters` — a-z/A-Z only. */
export function string_letters(str: string): string {
  return str.replace(/[^A-Za-z]/g, '')
}

/**
 * The folder's ubiquitous debug idiom:
 * `sdm(s); dm_debug_data[?STR_Data+'01'+hex_str(++debug_data_count)] = s;`
 * The `dm_debug_data` lines become the spoiler log (`SaveFile_N_Rando_Spoiler.txt`).
 */
export function debugLine(self: Rando, line: string): void {
  self.debug_str = line
  sdm(line)
  self.debug_data_count++
  self.dm_debug_data.set(STR_Data + '01' + hexStr(self.debug_data_count), line)
}

/** `repeat(n){ sdm(""); dm_debug_data[?…]=""; }` */
export function debugBlank(self: Rando, times = 1): void {
  for (let i = 0; i < times; i++) debugLine(self, '')
}

/**
 * `dm_debug_data` entry without the `show_debug_message` — used by the blocks ZALiA guards with
 * `if (_CAN_PRINT_DEBUG)`: the line always goes to the spoiler file, only the console print is gated.
 */
export function debugData(self: Rando, line: string): void {
  self.debug_str = line
  self.debug_data_count++
  self.dm_debug_data.set(STR_Data + '01' + hexStr(self.debug_data_count), line)
}

export const clamp = (v: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, v))

/**
 * `enum ZELDA_HINT_OPTIONS` from `FileSelect_Create_Rando.gml:200` — what Zelda's hint gives away.
 * Declared here (not imported from `game/rooms/FileSelect.ts`) so the rando folder does not depend on the
 * rooms folder for four numbers.
 */
export const ZELDA_HINT_OPTIONS = { NONE: 0, FLUTE: 1, ALLKEY: 2, JUMP: 3, COUNT: 4 } as const
