/** GameObject_draw, GameObject_draw_1a, GO_draw_sprite, draw_sprite_ adapter (scripts/game_object/go, draw) */

import { draw_sprite_ as draw_sprite_cmd, drawState } from '../../rooms/draw'
import type { GameObject } from '../classes'

/**
 * `draw_sprite_(sprite, subimg, x, y, palette index, xscale, yscale)` for the entity ports.
 *
 * Same ZALiA script as `rooms/draw.ts`'s wrapper, with one difference the entity call sites rely on: GM
 * draws an instance's sprite at the *instance's* depth, so these take the depth where the `rooms/draw`
 * signature takes a colour, and set it for the duration of the command. Omitting it means "the depth this
 * draw script is drawing at" — a GM Draw event runs at its instance's depth, which `<Object>_draw` sets on
 * `drawState` — not 0, which is a tile layer. Everything else is delegated —
 * this used to push straight onto `world.draw`, which meant an entity draw skipped the surface target and,
 * worse, skipped the ambient `pal_swap_set`: the `pal_swap_set(palidx); GO_draw_sprite(spr)` idiom of 16
 * enemy draw scripts recorded no palette at all.
 */
export function draw_sprite_(
  sprite: string,
  subimg: number,
  x: number,
  y: number,
  palIdx = -1,
  xscale = 1,
  yscale = 1,
  depth = drawState.depth,
  alpha = 1,
): void {
  const prev = drawState.depth
  drawState.depth = depth
  draw_sprite_cmd(sprite, subimg, x, y, palIdx, xscale, yscale, -1, alpha)
  drawState.depth = prev
}

/** `GameObject_draw(can draw debug)` — scr_draw OR draw self. Debug overlays are the dev-tools port's. */
export function GameObject_draw(self: GameObject, _canDrawDebug: number | boolean): void {
  if (self.scr_draw) self.scr_draw(self)
  else if (self.can_draw_self && self.sprite) GameObject_draw_1a(self, self.sprite, self.palidx) // draw self
}

/** `GameObject_draw_1a(sprite, palette index)` */
export function GameObject_draw_1a(self: GameObject, sprite: string, palIdx: number): void {
  draw_sprite_(sprite, 0, self.drawX, self.drawY, palIdx, self.xScale, self.yScale, self.depth)
}

/** `GO_draw_sprite(sprite, *palette index)` */
export function GO_draw_sprite(self: GameObject, sprite: string | 0, palIdx?: number): void {
  if (!sprite) return
  draw_sprite_(sprite, 0, self.drawX, self.drawY, palIdx ?? -1, self.xScale, self.yScale, self.depth)
}
