/** `is_ancestor(child, parent)` on names, walking OBJECT_PARENTS. */
/** `is_ancestor(obj, parent)` by name; `child` may be a numeric GM object index (as stored in the caches). */
export function isAncestorName(child: ObjectName | number, parent: ObjectName): boolean {
  let c: string | undefined = typeof child === 'number' ? GM_OBJECT_NAMES[child] : child
  while (c !== undefined && c !== '') {
    if (c === parent) return true
    c = OBJECT_PARENTS[c as ObjectName]
  }
  return false
}
