/**
 * Small NIAO kinds — ported from `Fire1_*.gml`, `Fountain_1_*.gml`, `Jackolantern1_*.gml`, `Moon1_*.gml`,
 * `Torch_1_*.gml`, `Skull1_*.gml`, `StarSky_1_*.gml`.
 */
import {
  DEPTH_BG3,
  DEPTH_BG4,
  QuestID_Nabooru_Spell,
  STR_Data,
  STR_Nabooru,
  STR_New_Kasuto,
  STR_pal_idx,
} from '@z2/data'
import { gmBool } from '../../nes/math8'
import { G, g } from '../../runtime/world'
import { rectInView } from '../collision/geometry'
import { quest_is_complete } from '../file/stats'
import { roomSize } from '../Game/gm'
import { GO_draw_sprite } from '../game_object/go/draw'
import { set_xy, update_draw_xy } from '../game_object/go/movement'
import { GO_init_palidx } from '../game_object/go/palette'
import { GO_depth_init, GO_set_sprite, GO_set_sprite_index, GO_sprite_init } from '../game_object/go/sprite'
import { sign_ } from '../math'
import { val } from '../other'
import { add_pi_permut } from '../palette/scenePalette'
import { draw_sprite_, pushCmd } from '../rooms/draw'
import { tile_find_depth_by_tsrc } from '../tile/tileOps'
import { viewH, viewH_, viewW, viewW_, viewXL, viewXR, viewYB, viewYT } from '../view/camera'
import type { NiaoObject } from './NiaoObject'

/** Remove this instance from `g.dl_niao` (shared by the Halloween-only kinds). */
function dropFromNiaoList(self: NiaoObject): void {
  const dl = g.dl_niao
  for (let _i = dl.size - 1; _i >= 0; _i--) {
    const cur = dl.get(_i)
    if (cur !== undefined && cur === self) {
      dl.set(_i, null)
      break
    }
  }
}

// ------------------------------------------------------------------ Fire1
/** `Fire1_init()` */
export function Fire1_init(self: NiaoObject): void {
  self.scr_draw = Fire1_draw as never
  switch (self.ver) {
    case 1:
      GO_sprite_init(self, 'spr_Fire_1a_2')
      break
    case 2:
      GO_sprite_init(self, 'spr_Flame1')
      break
    case 3:
      GO_sprite_init(self, 'spr_Flame_Small_1b')
      break
  }
  self.ANIM_SPEED = 0x08
  GO_depth_init(self, DEPTH_BG4 + 1)
  GO_init_palidx(self, G.PI_MOB_ORG)
  self.can_draw_self = true
}
/** `Fire1_draw()` — flips every ANIM_SPEED frames. */
export function Fire1_draw(self: NiaoObject): void {
  if (!self.can_draw_self) return
  draw_sprite_(self.sprite as string, 0, self.x, self.y, self.palidx, sign_(g.counter1 & self.ANIM_SPEED))
}

// ------------------------------------------------------------------ Fountain_1
/** `Fountain_1_init()` */
export function Fountain_1_init(self: NiaoObject): void {
  self.scr_draw = Fountain_1_draw as never
  self.Water_SPR1 = 'spr_Fountain_Water_1a_1' // anim frame 1
  self.Water_SPR2 = 'spr_Fountain_Water_1b_1' // anim frame 2
  GO_sprite_init(self, self.Water_SPR1)
  self.ANIM_SPEED = 1 << 3
  const _TSRC1 = 0xf3 // Fountain statue head
  const _DEPTH_ADD = 3
  let _DEPTH = tile_find_depth_by_tsrc((self.xl >> 3) + 1, self.yt >> 3, 'ts_Man_made_1a_WRB', _TSRC1)
  if (_DEPTH === -1) _DEPTH = DEPTH_BG4
  GO_depth_init(self, _DEPTH + _DEPTH_ADD)
  let _pi_base: number = G.PI_BGR3
  let _pi_permut = 0
  if (self.dk_spawn !== undefined) {
    if (gmBool(val(g.dm_rm.get(self.dk_spawn + STR_pal_idx))))
      _pi_base = g.dm_rm.get(self.dk_spawn + STR_pal_idx) as number
    const d1 = g.dm_rm.get(`${self.dk_spawn + STR_Data}01`)
    if (d1 !== undefined) _pi_permut = d1 as number
    const d2 = g.dm_rm.get(`${self.dk_spawn + STR_Data}02`)
    if (d2 !== undefined) {
      self.depth = d2 as number
      GO_depth_init(self, self.depth + _DEPTH_ADD)
    }
  }
  switch (_pi_permut) {
    default:
      self.PALIDX = _pi_base
      break
    case 1:
      self.PALIDX = add_pi_permut(_pi_base, 'WBRGYKMC', 'Fountain')
      break
    case 2:
      self.PALIDX = add_pi_permut(_pi_base, 'RWBGMYKC', 'Fountain')
      break
    case 3:
      self.PALIDX = add_pi_permut(_pi_base, 'RBWGMKYC', 'Fountain')
      break
    case 4:
      self.PALIDX = add_pi_permut(_pi_base, 'BWRGKYMC', 'Fountain')
      break
    case 5:
      self.PALIDX = add_pi_permut(_pi_base, 'BRWGKMYC', 'Fountain')
      break
  }
  GO_init_palidx(self, _pi_base)
  self.palidx_permut = _pi_permut
  self.can_draw_self = true
  if (g.town_name === STR_Nabooru && !quest_is_complete(QuestID_Nabooru_Spell)) self.can_draw_self = false
}
/** `Fountain_1_draw()` */
export function Fountain_1_draw(self: NiaoObject): void {
  if (!self.can_draw_self) return
  let _SPR = self.Water_SPR1
  if (g.counter1 & self.ANIM_SPEED) _SPR = self.Water_SPR2
  draw_sprite_(_SPR, 0, self.x, self.y, self.PALIDX)
}

// ------------------------------------------------------------------ Jackolantern1
/** `Jackolantern1_init()` */
export function Jackolantern1_init(self: NiaoObject): void {
  let _depth = DEPTH_BG3 - 1
  self.can_draw_self = true
  self.state = 1
  if (self.ver === 1 && !G.Halloween1_enabled) {
    self.can_draw_self = false
    self.state = 0
    dropFromNiaoList(self)
    self.destroy()
    return
  }
  self.scr_draw = Jackolantern1_draw as never
  if (self.dk_spawn !== undefined) {
    const d1 = g.dm_rm.get(`${self.dk_spawn + STR_Data}01`)
    if (d1 !== undefined) self.x = val(d1) as number
    const d2 = g.dm_rm.get(`${self.dk_spawn + STR_Data}02`)
    if (d2 !== undefined) self.y = val(d2) as number
    set_xy(self, self.x, self.y)
    const d3 = g.dm_rm.get(`${self.dk_spawn + STR_Data}03`)
    if (d3 !== undefined) _depth = val(d3) as number
  }
  const _SPR = 'spr_Jackolantern01_1'
  switch (self.ver) {
    case 1:
      GO_sprite_init(self, _SPR)
      break
  }
  GO_depth_init(self, _depth)
  GO_init_palidx(self, G.PI_MOB_ORG)
}
/** `Jackolantern1_draw()` — 3-frame flicker on a $80-frame cycle. */
export function Jackolantern1_draw(self: NiaoObject): void {
  if (!self.can_draw_self) return
  if (!gmBool(self.state)) return
  const _TIME = g.counter1 & 0x7f
  let _sprite = 'spr_Jackolantern01_1'
  if (_TIME >= 0x40) {
    if (Math.trunc((_TIME - 0x3f) / (0x40 / 3)) === 1) _sprite = 'spr_Jackolantern01_3'
    else _sprite = 'spr_Jackolantern01_2'
  }
  draw_sprite_(_sprite, 0, self.x, self.y)
}

// ------------------------------------------------------------------ Moon1
/** `Moon1_init()` */
export function Moon1_init(self: NiaoObject): void {
  if (!G.Halloween1_enabled) {
    self.destroy()
    return
  }
  self.scr_update = Moon1_update as never
  self.scr_draw = Moon1_draw as never
  GO_sprite_init(self, 'spr_Moon01')
  GO_depth_init(self, g.DEPTH_STARS - 1)
  GO_init_palidx(self, G.PI_MOB_ORG)
  self.CAM_LOCKED = true
  if (self.CAM_LOCKED) {
    let _x = viewW()
    _x -= self.ww_
    _x -= 0x0c << 3
    self.X_OFF = _x
    let _y = 0
    _y += self.hh_
    _y += 0x04 << 3
    if (g.town_name === STR_New_Kasuto) _y += 0x06 << 3
    self.Y_OFF = _y
    self.ADJUST_DIST = 0x400
    _x = viewXL() + self.X_OFF
    _x += Math.trunc((roomSize.width - viewXR()) / self.ADJUST_DIST)
    _y = viewYT() + self.Y_OFF
    _y += Math.trunc((roomSize.height - viewYB()) / self.ADJUST_DIST)
    set_xy(self, _x, _y)
  } else {
    let _x = roomSize.width
    _x -= self.ww_
    _x -= 0x10 << 3
    self.X1 = _x
    let _y = 0x00
    _y += self.hh_
    _y += 0x02 << 3
    self.Y1 = _y
    set_xy(self, self.X1, self.Y1)
  }
  self.can_draw_self = true
}
/** `Moon1_update()` */
export function Moon1_update(self: NiaoObject): void {
  if (self.CAM_LOCKED) {
    let _x = viewXL() + self.X_OFF
    _x += Math.trunc((roomSize.width - viewXR()) / self.ADJUST_DIST)
    let _y = viewYT() + self.Y_OFF
    _y += Math.trunc((roomSize.height - viewYB()) / self.ADJUST_DIST)
    set_xy(self, _x, _y)
  } else {
    set_xy(self, self.X1, self.Y1)
  }
  self.can_draw_self = true
}
/** `Moon1_draw()` */
export function Moon1_draw(self: NiaoObject): void {
  if (!self.can_draw_self) return
  draw_sprite_(self.sprite as string, 0, self.x, self.y)
}

// ------------------------------------------------------------------ Torch_1
/** `Torch_1_init()` */
export function Torch_1_init(self: NiaoObject): void {
  self.scr_udp = Torch_1_udd as never
  self.scr_draw = Torch_1_draw as never
  GO_set_sprite_index(self, 'spr_Placement_08x16')
  GO_set_sprite(self, 'spr_Torch_1a')
  GO_init_palidx(self, G.PI_MOB_BLU)
}
/** `Torch_1_udd()` — xScale flicker for the flame. */
export function Torch_1_udd(self: NiaoObject): void {
  if (g.counter1 & 0x4) self.xScale = -1
  else self.xScale = 1
  self.can_draw_self = gmBool(self.state) && rectInView(self.xl, self.yt - 0x10, 8, 0x20)
  update_draw_xy(self)
}
/** `Torch_1_draw()` */
export function Torch_1_draw(self: NiaoObject): void {
  if (!self.can_draw_self) return
  self.can_draw_self = false
  const _YOFF = -0x11
  self.drawY += _YOFF
  GO_draw_sprite(self, 'spr_Flame1', G.PI_MOB_ORG)
  self.drawY += -_YOFF
  self.xScale = 1
  GO_draw_sprite(self, self.sprite, self.palidx)
}

// ------------------------------------------------------------------ Skull1
/** `Skull1_init()` — ver 2 only exists on Halloween. */
export function Skull1_init(self: NiaoObject): void {
  self.can_draw_self = true
  if (self.ver === 2 && !G.Halloween1_enabled) {
    self.can_draw_self = false
    self.state = 0
    dropFromNiaoList(self)
    self.destroy()
    return
  }
  self.scr_draw = Skull1_draw as never
  GO_sprite_init(self, 'spr_Skull04')
  GO_init_palidx(self, G.PI_MOB_ORG)
  GO_depth_init(self, DEPTH_BG3 - 1)
  if (self.dk_spawn !== undefined) {
    const d1 = g.dm_rm.get(`${self.dk_spawn + STR_Data}01`)
    if (d1 !== undefined) self.x = val(d1) as number
    const d2 = g.dm_rm.get(`${self.dk_spawn + STR_Data}02`)
    if (d2 !== undefined) self.y = val(d2) as number
    set_xy(self, self.x, self.y)
    const d3 = g.dm_rm.get(`${self.dk_spawn + STR_Data}03`)
    if (d3 !== undefined) self.depth = val(d3) as number
    GO_depth_init(self, self.depth)
  }
}
/** `Skull1_draw()` */
export function Skull1_draw(self: NiaoObject): void {
  if (!self.can_draw_self) return
  draw_sprite_(self.sprite as string, 0, self.x, self.y, self.palidx)
}

// ------------------------------------------------------------------ StarSky_1
/**
 * `StarSky_1_init()`. The star field itself is 4 pre-rendered 256×256 surfaces built by `g_Draw`
 * (`g.StarSky_dl_surfaces`); here they are referenced by index through a `surface` draw command the
 * adapter resolves (`{ kind: 'surface', surface: 'StarSky', index }`). The GML's dead star table after
 * `exit` was dropped.
 */
export function StarSky_1_init(self: NiaoObject): void {
  GO_depth_init(self, g.DEPTH_STARS)
  self.scr_draw = StarSky_1_Draw as never
  self.scr_update = undefined // StarSky_1_update is empty
  self.scr_inst_end = StarSky_1_end as never
  // star sky sprites are 256x256
  self.SPR_W = 0x100
  self.SPR_H = 0x100
  self.SPR_XOFF = self.SPR_W >> 1
  self.SPR_YOFF = self.SPR_H >> 1
  self.CAM_LOCKED = G.Halloween1_enabled && gmBool(g.town_num)
  if (self.CAM_LOCKED) {
    self.CLMS = Math.trunc(viewW() / self.SPR_W) + Math.sign(viewW() % self.SPR_W)
    let _x = viewW_()
    _x -= (self.SPR_W * self.CLMS) >> 1
    _x += self.SPR_W >> 1
    self.X_OFF = _x
    if (g.view_lock_rm & 0xc || g.rm_rows === 1) {
      self.ROWS = 1
      self.Y_OFF = self.SPR_H >> 1
    } else {
      self.ROWS = Math.trunc(viewH() / self.SPR_H) + Math.sign(viewH() % self.SPR_H)
      let _y = viewH_()
      _y -= (self.SPR_H * self.ROWS) >> 1
      _y += self.SPR_H >> 1
      self.Y_OFF = _y
    }
  }
}
/** `StarSky_1_Draw()` — tiles the 4 animated star surfaces over the view or the room. */
export function StarSky_1_Draw(self: NiaoObject): void {
  const _TIME = g.counter1 >> 4
  const draw = (idx: number, x: number, y: number) =>
    pushCmd({ kind: 'surface', surface: 'StarSky', index: idx, x, y, depth: self.depth })
  if (self.CAM_LOCKED) {
    for (let _i = 0; _i < self.ROWS; _i++)
      for (let _j = 0; _j < self.CLMS; _j++) {
        const _idx = (_TIME + _i + _j) & 0x3
        draw(_idx, viewXL() + self.SPR_W * _j, viewYT() + self.SPR_H * _i)
      }
  } else {
    for (let _i = (roomSize.height >> 8) - 1; _i >= 0; _i--)
      // each row of pages
      for (let _j = (roomSize.width >> 8) - 1; _j >= 0; _j--) {
        // each clm of pages
        const _idx = (_TIME + _i + _j) & 0x3
        const _x = _j << 8
        let _y = _i << 8
        if (g.view_lock_rm & 0xc || g.rm_rows === 1) _y = viewYT()
        if (!rectInView(_x, _y, self.SPR_W, self.SPR_H)) continue
        draw(_idx, _x, _y)
      }
  }
}
/** `StarSky_1_end()` */
export function StarSky_1_end(_self: NiaoObject): void {}
