/**
 * Camera accessors — ported from ZALiA `scripts/view/*` (viewXL/XR/XC/YT/YB/YC, viewW/H, cam_*).
 * The GM view (`view_xview[0]`…) lives in `Game/gm.ts` `view` so the g port's shims and this module agree.
 * `set_camera_xy` writes it; `room_set_view_` sizes it for the next room.
 */
import { VIEW_H_OG, VIEW_H_OG_, VIEW_W_OG, VIEW_W_OG_ } from '@z2/data'
import { gmBool } from '../../nes/math8'
import { G, g } from '../../runtime/world'
import { view } from '../Game/gm'

export function viewXL(): number {
  return view.x
}
export function viewXR(): number {
  return viewXL() + viewW()
}
export function viewXC(): number {
  return viewXL() + viewW_()
}
export function viewYT(): number {
  return view.y
}
export function viewYB(): number {
  return viewYT() + viewH()
}
export function viewYC(): number {
  return viewYT() + viewH_()
}
export function viewW(): number {
  return view.w
}
export function viewH(): number {
  return view.h
}
export function viewW_(): number {
  return viewW() >> 1
}
export function viewH_(): number {
  return viewH() >> 1
}

/** `set_camera_xy(new x, new y)` */
export function set_camera_xy(x: number, y: number): void {
  view.x = x
  view.y = y
}

/** Size requested for the next room by `room_set_view_`; applied by the room change. */
export const pendingView = { w: 0, h: 0 }
/** `room_set_view_(room_index, view w, view h)` — set camera size for next room. */
export function room_set_view_(_room: string, viewW: number, viewH: number): void {
  pendingView.w = viewW
  pendingView.h = viewH
}

// ---- camera bounds (scripts/view/cam_*) -------------------------------------------------------
/** `cam_xl_min()` — x coord of furthest left view_x can be */
export function cam_xl_min(): number {
  if (g.rm_w < viewW() || g.view_lock_rm & 0x3) return g.rm_w_ - viewW_()
  return 0
}
/** `cam_xl_max()` */
export function cam_xl_max(): number {
  if (g.view_lock_rm & 0x3 || g.rm_w < viewW()) return g.rm_w_ - viewW_()
  return g.rm_w - viewW()
}
/** `cam_xr_max()` — x coord of furthest right cam x + $100 can be */
export function cam_xr_max(): number {
  return cam_xl_max() + viewW()
}
/** `cam_xl_range()` */
export function cam_xl_range(): number {
  return cam_xl_max() - cam_xl_min()
}
/** `cam_x_range()` — the distance between the max x of camXR and min x of camXL */
export function cam_x_range(): number {
  return cam_xr_max() - cam_xl_min()
}
/** `cam_yt_min()` */
export function cam_yt_min(): number {
  let yt: number
  if (g.view_y_page_max - g.view_y_page_min) {
    if (!g.view_y_page_min) {
      yt = g.VIEW_PAD_YT
    } else {
      yt = ((g.view_y_page_min + 1) << 8) - viewH()
      if (g.view_y_page_min + 1 === g.view_y_page_max) yt -= g.VIEW_PAD_YB
    }
  } else {
    yt = ((g.view_y_page_min + 1) << 8) - viewH()
    if (g.view_y_page_max + 1 === g.rm_pages_y) yt -= g.VIEW_PAD_YB
  }
  return yt
}
/** `cam_yt_max()` */
export function cam_yt_max(): number {
  let yb = (g.view_y_page_max + 1) << 8
  yb = Math.min(yb, g.rm_h - g.VIEW_PAD_YB)
  return yb - viewH()
}
/** `cam_yb_min()` */
export function cam_yb_min(): number {
  return cam_yt_min() + viewH()
}
/** `cam_yb_max()` */
export function cam_yb_max(): number {
  return cam_yt_max() + viewH()
}
/** `cam_yt_range()` */
export function cam_yt_range(): number {
  return cam_yt_max() - cam_yt_min()
}
/** `cam_y_range()` */
export function cam_y_range(): number {
  return cam_yb_max() - cam_yt_min()
}

/** `rm_set_cam_1a(cam center x target, cam center y target)` */
export function rm_set_cam_1a(cx: number, cy: number): void {
  g.view_dir_x = 1 // 071F
  g.view_dir_y = 1
  view.w = g.VIEW_W
  view.h = g.VIEW_H
  set_camera_xy(
    clamp(cx - viewW_(), cam_xl_min(), cam_xl_max()),
    clamp(cy - viewH_(), cam_yt_min(), cam_yt_max()),
  )
}

/** The PC fields the camera reads (`global.pc`). */
export interface PcCamView {
  x: number
  y: number
  x_change: number
  y_change: number
  x_change_dir: number
  y_change_dir: number
  view_xl_dist: number
  view_yt_dist: number
}
export const pcView = (): PcCamView => G.pc as PcCamView

/** `set_view_xy_on_pc()` */
export function set_view_xy_on_pc(): void {
  const pc = pcView()
  let x: number
  let y: number
  if (g.view_lock & 0x3) x = viewXL()
  else x = pc.x - viewW_()
  x = clamp(x, cam_xl_min(), cam_xl_max())
  if (g.view_lock & 0xc) y = viewYT()
  else y = pc.y - viewH_()
  y = clamp(y, cam_yt_min(), cam_yt_max())
  set_camera_xy(x, y)
}

/** `update_view_og()` — the original 256×240 view tracking the PC (072C…). */
export function update_view_og(): void {
  const pc = pcView()
  g.view_xl_og = clamp(pc.x - VIEW_W_OG_, cam_xl_min(), cam_xr_max() - VIEW_W_OG)
  g.view_xr_og = g.view_xl_og + (VIEW_W_OG - 1)
  g.view_xc_og = g.view_xl_og + VIEW_W_OG_
  g.view_yt_og = clamp(pc.y - VIEW_H_OG_, cam_yb_min() - VIEW_H_OG, cam_yb_max() - VIEW_H_OG)
  g.view_yb_og = g.view_yt_og + (VIEW_H_OG - 1)
  g.view_yc_og = g.view_yt_og + VIEW_H_OG_
}

export const clamp = (v: number, lo: number, hi: number) => Math.min(Math.max(v, lo), hi)

/**
 * The NES-original 256×240 window inside the room, or `null` while the screen is presenting ZALiA's wide
 * view. ZALiA renders 480×270 and paints black side masks (`MaskWideView`) to letterbox the OG view inside
 * it; an adapter that owns the whole display can instead present that window directly, at the 4:3 a NES
 * was actually shown on. Bottom-aligned to the room, which is where the NES framing sits: on the title
 * screen this is room x 128..384, y 16..256 — measured against a 256×240 NES capture, it puts the sword
 * dead centre and the landscape's top edge on scanline 144, both exactly as the original.
 */
export function ogViewWindow(): { x: number; y: number; w: number; h: number } | null {
  if (!gmBool(g.MaskWideView)) return null
  return {
    x: g.rm_w_ - (VIEW_W_OG >> 1),
    y: Math.max(0, g.rm_h - VIEW_H_OG),
    w: VIEW_W_OG,
    h: VIEW_H_OG,
  }
}
