/** `room_goto_`, `goto_title_rm`, `goto_room` — ZALiA IDE folder `rooms` (root scripts). */
import { EXIT_NAME_GAME_START } from '@z2/data'
import { f, g } from '../../runtime/world'
import { audio_group_stop_all } from '../Game/gm'
import { set_go_can_draw_self } from '../game_object/go/misc'
import { sdm } from '../other/index'
import { room_set_view_ } from '../view/camera'
import { gotoRoom } from './roomChange'

export const RM = {
  START: 'rmB_Start',
  START_WIDE: 'rmB_Start_Wide',
  TITLE: 'rmB_Title',
  FILE_SELECT: 'rmB_FileSelect',
  CONTINUE_SAVE: 'rmB_ContinueSave',
  DEATH: 'rmB_Death',
  NEXT_LIFE: 'rmB_NextLife',
  GAME_OVER: 'rmB_GameOver',
  OVERWORLD: 'rmC_Overworld_A',
  ACTION: 'rmA_Action',
  ACTION_WIDE: 'rmA_Action_Wide',
} as const

/** `room_goto_(room, *width, *height)` */
export function room_goto_(room: string, width = 0, height = 0): void {
  let _view_w = g.VIEW_W
  if (width) _view_w = Math.min(Math.max(width, 1 << 8), 4 << 8)
  let _view_h = g.VIEW_H
  if (height) _view_h = Math.min(Math.max(height, 1 << 8), 4 << 8)
  sdm(`room_goto_(). ${room}`)
  room_set_view_(room, _view_w, _view_h)
  gotoRoom(room)
}

/** `goto_room()` — empty in ZALiA. */
export function goto_room(): void {}

/** `goto_title_rm()` */
export function goto_title_rm(): void {
  // There's also a bunch of TitleScreen property resets in g_Room_Start(). Not sure if they should go here.
  if (g.MaskWideView_RESPAWN) {
    g.MaskWideView = 1
    g.MaskWideView_w = g.MaskWideView_W
  }
  set_go_can_draw_self(false)
  g.counter1 = 0
  g.pc_lock = 0
  g.cutscene = 0
  g.game_end_state = 0
  f.reen = EXIT_NAME_GAME_START
  g.dm_room_history.clear()
  audio_group_stop_all('audiogroup_mus')
  room_goto_(RM.TITLE)
}
