/** Collision tests against the player's hitboxes and PC projectiles. */
import { NOONE, type Ref } from '../../runtime/instance'
import type { GoBody, ProjBody } from './body'
import { env } from './env'
import { rectInCirc, rectInRect } from './geometry'
import { PC_update_sword_hb } from './hitbox'

/** `collideRect(x, y, w, h, obj, *obj..)` — first body (in list order) whose body hitbox overlaps. */
export function collideRect(
  x: number,
  y: number,
  w: number,
  h: number,
  ...bodies: Iterable<GoBody>[]
): Ref<GoBody> {
  for (const list of bodies) {
    for (const b of list) {
      if (rectInRect(x, y, w, h, b.BodyHB_xl, b.BodyHB_yt, b.BodyHB_w, b.BodyHB_h)) return b
    }
  }
  return NOONE
}

/** `collide_pc_shield(x, y, w, h, *radius)` */
export function collide_pc_shield(x: number, y: number, w: number, h: number, radius = 0): boolean {
  const pc = env.pc()
  if (radius) return rectInCirc(x, y, radius, pc.ShieldHB_x, pc.ShieldHB_y, pc.ShieldHB_w, pc.ShieldHB_h)
  return rectInRect(x, y, w, h, pc.ShieldHB_x, pc.ShieldHB_y, pc.ShieldHB_w, pc.ShieldHB_h)
}

/** `collide_pc_body(x, y, w, h, *radius)` */
export function collide_pc_body(x: number, y: number, w: number, h: number, radius = 0): boolean {
  const pc = env.pc()
  if (radius) return rectInCirc(x, y, radius, pc.BodyHB_xl, pc.BodyHB_yt, pc.BodyHB_w, pc.BodyHB_h)
  return rectInRect(x, y, w, h, pc.BodyHB_xl, pc.BodyHB_yt, pc.BodyHB_w, pc.BodyHB_h)
}

/** `collide_pc_sword(x, y, w, h, *radius)` — refreshes the sword hitbox first. */
export function collide_pc_sword(x: number, y: number, w: number, h: number, radius = 0): boolean {
  const pc = env.pc()
  // SwordHB_collidable is set and determined at end of master update in update_swrdXY()
  if (!pc.SwordHB_collidable) return false
  PC_update_sword_hb()
  if (radius) return rectInCirc(x, y, radius, pc.SwordHB_x, pc.SwordHB_y, pc.SwordHB_w, pc.SwordHB_h)
  return rectInRect(x, y, w, h, pc.SwordHB_x, pc.SwordHB_y, pc.SwordHB_w, pc.SwordHB_h)
}

/** `collide_pc_proj(x, y, w, h, *radius)` — the PC projectile (`dl_goc2`, highest slot first) hitting the box, or null. */
export function collide_pc_proj(x: number, y: number, w: number, h: number, radius = 0): Ref<ProjBody> {
  const list = env.goc2()
  for (let i = list.length - 1; i >= 0; i--) {
    const p = list[i]
    if (!p?.exists) continue
    if (p.state !== p.state_NORMAL) continue
    if (radius) {
      if (rectInCirc(x, y, radius, p.BodyHB_xl, p.BodyHB_yt, p.BodyHB_w, p.BodyHB_h)) return p
    } else if (rectInRect(x, y, w, h, p.BodyHB_xl, p.BodyHB_yt, p.BodyHB_w, p.BodyHB_h)) return p
  }
  return NOONE
}

/** `body_collide_body(inst, obj or inst)` — body hitboxes overlap for any of the given bodies. */
export function body_collide_body(a: GoBody, others: Iterable<GoBody>): boolean {
  for (const b of others) {
    if (
      rectInRect(
        a.BodyHB_xl,
        a.BodyHB_yt,
        a.BodyHB_w,
        a.BodyHB_h,
        b.BodyHB_xl,
        b.BodyHB_yt,
        b.BodyHB_w,
        b.BodyHB_h,
      )
    )
      return true
  }
  return false
}

/** `enemy_collide_pc_body()` — E2EF: damage the player unless invulnerable. */
export function enemy_collide_pc_body(self: GoBody): void {
  if (!env.pc().iframes_timer) env.fn.PC_take_damage(self)
}
