/** Seams of the challenge scripts: other objects' fields read structurally + instance lookups by GML name. */
import { world } from '../../../runtime/world'
import { notPorted } from '../../pending'
import { GameObject } from '../classes'
import { isAncestorName, type ObjectName } from '../objectNames'

/** `with (Obj)` over every live instance whose object is `name` or a descendant of it. */
export function* instancesNamed<T extends GameObject = GameObject>(name: ObjectName): Generator<T> {
  for (const i of world.instancesOf(GameObject)) if (isAncestorName(i.objectName, name)) yield i as T
}

/** SwchA (switch A) fields the Switch challenges read. */
export interface SwitchALike extends GameObject {
  sub_state: number
  SUB_ST_GOAL: number
  SUB_ST_COMP: number
  DIR_IN: number
  orientation: number
  GOAL_XX: number
  GOAL_YY: number
}
/** SwchB (pressure switch) fields. */
export interface SwitchBLike extends GameObject {
  pressed: boolean | number
  complete: boolean | number
}
/** PushA (pushable block) fields. */
export interface PushableLike extends GameObject {
  moving_dir: number
}
/** BlckB (hanging prize block) fields. */
export interface BlockBLike extends GameObject {
  Chain_hang: boolean | number
  Chain_connected: boolean | number
}
/** LoDoA (locked door): `counter = -1` starts the opening process. */
export interface LockedDoorLike extends GameObject {
  counter: number
}
/** Torch objects: `is_lit`. */
export interface TorchLike extends GameObject {
  is_lit: boolean | number
}
/** Exit fields used by SwitchB ver 3. */
export interface ExitLike extends GameObject {
  exitNum: number
  open: boolean | number
  doorway_spr: string | number
}
/** Target (mini game) fields. */
export interface TargetLike extends GameObject {
  target_hit: boolean | number
  BVR_STRT: number
  BVR_VULN: number
  TARGET_NUM: number
}
/** ItmD0 key: `dk_item`. */
export interface KeyItemLike extends GameObject {
  dk_item: string
}

export const goeHooks = {
  /**
   * `audio_sound_length(sound) * room_speed` — frames of a sound. Bound by `wireCore()`; a plausible-looking
   * `() => 0` default was invisible to `seams.test.ts` while both mini-game jingle waits collapsed.
   */
  audioLengthFrames: notPorted('audio_sound_length') as (sound: string | number) => number,
  /** `audio_group_stop_all(audiogroup_mus)` — bound by `wireCore()`. */
  audio_group_stop_all_mus: notPorted('audio_group_stop_all(audiogroup_mus)') as () => void,
  /** `GO_draw_body_hb()` (dev) — deliberately a no-op, like the other dev-overlay draws. */
  GO_draw_body_hb: (_self: GameObject): void => {},
}
