/**
 * Menu / HUD instances and their wiring into the boot and frame sequence.
 * `obj_start_Create.gml:110-114` creates PauseMenu, LevelUpMenu, DialogueWindow, OptionsMenu, QuitAppMenu
 * (persistent; Create + Game End + Draw events only — their updates run from `update_menus`/`g_Step`).
 * HUD is created per action room by `g_Room_Start` (`instance_create(..., HUD)`) and has Step + Draw.
 */
import { Instance } from '../../runtime/instance'
import { G, g, type World, world } from '../../runtime/world'
import { set_go_can_draw_self } from '../game_object/go/misc'
import { bootHooks } from '../obj_start/boot'
import { registerObjectClass } from '../other/registry'
import { setGuiDeps } from '../rooms/deps'
import { persistentScreens, roomHooks, type ScreenObject } from '../rooms/roomChange'
import { DialogueWindow, update_Dialogue } from './DialogueWindow'
import { HUD } from './HUD'
import { gui_tmr_cursor_h, gui_tmr_cursor_v, guiDeps, keyboard_bindings_load, menuHandles } from './index'
import { LevelUpMenu, update_LevelUp } from './LevelUpMenu'
import { OptionsMenu } from './OptionsMenu'
import { PauseMenu, PauseMenu_update } from './PauseMenu'
import { QuitAppMenu } from './QuitAppMenu'

export interface Menus {
  pause: PauseMenu
  levelUp: LevelUpMenu
  dialogue: DialogueWindow
  options: OptionsMenu
  quitApp: QuitAppMenu
}
let menus: Menus | undefined
export const currentMenus = (): Menus | undefined => menus

/** Steps and draws every live HUD instance (HUD has Step + Draw events in ZALiA). */
class HudDriver extends Instance implements ScreenObject {
  readonly objectName = '__HudDriver'
  step(): void {
    for (const h of world.instancesOf(HUD)) h.step()
  }
  draw(): void {
    for (const h of world.instancesOf(HUD)) h.draw()
  }
}

/** `instance_create(0,0,PauseMenu)` … in `obj_start_Create` order; registers everything the loop needs. */
export function createMenus(w: World = world): Menus {
  registerObjectClass('HUD', HUD)
  registerObjectClass('PauseMenu', PauseMenu)
  registerObjectClass('LevelUpMenu', LevelUpMenu)
  registerObjectClass('DialogueWindow', DialogueWindow)
  registerObjectClass('OptionsMenu', OptionsMenu)
  registerObjectClass('QuitAppMenu', QuitAppMenu)
  const m: Menus = {
    pause: w.register(new PauseMenu()),
    levelUp: w.register(new LevelUpMenu()),
    dialogue: w.register(new DialogueWindow()),
    options: w.register(new OptionsMenu()),
    quitApp: w.register(new QuitAppMenu()),
  }
  // the Create scripts store `id` on g / global — mirror that explicitly (the ported Create does it too)
  g.PAUSE_MENU = m.pause
  g.LEVEL_MENU = m.levelUp
  g.DIALOGUE_WINDOW = m.dialogue
  g.QUIT_APP_MENU = m.quitApp
  G.OPTIONS_MENU = m.options
  menuHandles.pause = {
    update: () => PauseMenu_update(m.pause),
    get state() {
      return m.pause.state
    },
    set state(v) {
      m.pause.state = v
    },
    get state_SPELL() {
      return m.pause.state_SPELL
    },
  }
  menuHandles.levelUp = { update: () => update_LevelUp(m.levelUp) }
  menuHandles.dialogue = { update: () => update_Dialogue(m.dialogue) }
  guiDeps.set_go_can_draw_self = set_go_can_draw_self
  setGuiDeps({ gui_tmr_cursor_v, gui_tmr_cursor_h })
  keyboard_bindings_load()
  // draw order: menus (Draw event, depth DEPTH_MENU_WINDOW) and the HUD driver, every frame
  persistentScreens.push(w.register(new HudDriver()), m.pause, m.levelUp, m.dialogue, m.options, m.quitApp)
  menus = m
  return m
}

/** Game End events of the menus (`*_Game_End`), in creation order. */
export function menus_Game_End(): void {
  if (!menus) return
  menus.pause.gameEnd()
  menus.levelUp.gameEnd()
  menus.dialogue.gameEnd()
  menus.options.gameEnd()
}

/** Install into the boot sequence (`bootHooks.menus_Create`). Menus have no Room Start/End events. */
export function installMenus(): void {
  bootHooks.menus_Create = () => {
    createMenus()
  }
  roomHooks.roomStart.menus = undefined
  roomHooks.roomEnd.menus = undefined
}
