/** GML: PauseMenu_Draw() */
export function PauseMenu_Draw(self: PauseMenu) {
  if (+!gmb(self.canDrawSections)) {
    self.canDrawSections = 0
    self.canDrawItems = 0
    self.canDrawSpells = 0
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // ----------------------------------------------------------------------------------
  // Draw bg color of menu
  if (gmb(self.WindowBackground_can_draw)) {
    draw_sprite_(
      'spr_1x1_WHT',
      0,
      self.WindowBackground_xl,
      self.WindowBackground_yt,
      -1,
      self.WindowBackground_w,
      self.WindowBackground_h,
      self.WindowBackground_color,
      self.WindowBackground_alpha,
    )
  }
  // ----------------------------------------------------------------------------------
  // Draw GUI Window Frame
  PauseMenu_Draw_1(self) // create surfaces
  pal_swap_set(self.PI_MENU1)
  switch (self.Window_draw_data_state) {
    case self.state_SPELL: {
      draw_surface_part(
        self.MenuFrame_srf_SPELL,
        self.MenuFrameMain_srf_xl,
        0,
        self.MenuFrameMain_w,
        self.Window_h,
        self.MenuFrameMain_xl,
        self.MenuFrameMain_yt,
      )
      break
    }
    case self.state_ITEM: {
      draw_surface_part(
        self.MenuFrame_srf_ITEM,
        self.MenuFrameMain_srf_xl,
        0,
        self.MenuFrameMain_w,
        self.Window_h,
        self.MenuFrameMain_xl,
        self.MenuFrameMain_yt,
      )
      break
    }
    case self.state_MAP: {
      draw_surface_part(
        self.MenuFrame_srf_MAP,
        self.MenuFrameMain_srf_xl,
        0,
        self.MenuFrameMain_w,
        self.Window_h,
        self.MenuFrameMain_xl,
        self.MenuFrameMain_yt,
      )
      break
    }
  }
  // For clms extending left beyond spell/item window
  if (gmb(self.Window_extra_draw_clms)) {
    draw_surface_part(
      self.MenuFrame_srf_MAP,
      0,
      0,
      self.Window_extra_draw_clms_w,
      self.Window_h,
      self.drawX,
      self.MenuFrameMain_yt,
    )
  }
  // draw map area-name/menu-nav separator
  if (gmb(self.MenuFrameSeparator1_can_draw)) {
    draw_surface_part(
      self.MenuFrame_srf_MAP,
      self.MenuFrameSeparator1_SURF_XL,
      0,
      self.MenuFrameSeparator1_W,
      self.Window_h,
      self.Window_xl0,
      self.MenuFrameMain_yt,
    )
  }
  pal_swap_reset()
  // SPELL MENU  ----------------------------------------------------------------------
  if (gmb(self.canDrawSpells)) {
    PauseMenu_draw_spell_menu(self)
  }
  // INVENTORY  -----------------------------------------------------------------------
  if (gmb(self.canDrawItems)) {
    PauseMenu_draw_inventory(self)
  }
  // MAP  -----------------------------------------------------------------------------
  PauseMenu_draw_map(self)
  // ----------------------------------------------------------------------------------
  //  MENU NAVIGATION  -------------------------------------------------------------
  pal_swap_set(self.PI_MENU1)
  if (gmb(self.MenuNav_can_draw)) {
    if (gmb(self.MenuNavL_text_can_draw)) {
      draw_text_(self.MenuNavL_text_xl, self.MenuNavL_text_yt, self.MenuNavL_text) // left   $20
    }
    if (gmb(self.MenuNavR_text_can_draw)) {
      draw_text_(self.MenuNavR_text_xl, self.MenuNavR_text_yt, self.MenuNavR_text) // right  $50
    }
    draw_sprite_(self.MenuNavL_sprite, 0, self.MenuNavL_sprite_x, self.MenuNavL_sprite_y)
    draw_sprite_(self.MenuNavR_sprite, 0, self.MenuNavR_sprite_x, self.MenuNavR_sprite_y)
  }
  // ----------------------------------------------------------------------------------
  //  AREA NAME  -------------------------------------------------------------------
  if (gmb(self.AreaName_can_draw)) {
    draw_text_(self.AreaName_xl, self.AreaName_yt, self.AreaName_text)
  }
  pal_swap_reset()
  // ----------------------------------------------------------------------------------
  // ----------------------------------------------------------------------------------
  self.canDrawSections = 0
  self.canDrawItems = 0
  self.canDrawSpells = 0
}

/** GML: PauseMenu_update() */
export function PauseMenu_update(self: PauseMenu) {
  let _text: any, _DUNGEON_NUM: any, _count: any, _C1: any

  //if (timer)  timer--;
  if (gmb(self.timer0)) {
    self.timer0--
  }
  // 9DD0, 9DDB: JSR 9B19
  self.state_dir += -sign(self.state_dir)
  self.state &= 0x33
  // 9DDE, 9DE1: JSR D385
  switch (g.menu_state) {
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    case 1: {
      // ---------------------------------------------------------------------------------------------
      if (gmb(self.timer0)) {
        break
      }
      // A31C
      g._074F = 0xc0
      self.LifeDolls_count = get_life_doll_count()
      self.ContainerPiece_count_hp = cont_piece_cnt_hp()
      self.ContainerPiece_count_mp = cont_piece_cnt_mp()
      //if (keyboard_check_pressed(vk_f7)) show_debug_message("PauseMenu_update(). "+"LifeDolls_count="+string(LifeDolls_count));
      if (f.quest_num === 1) {
        self.dg_items.set(self.ITM_NOTE_IDX, 0x01, 0x14)
        self.dg_items.set(self.ITM_MIRR_IDX, 0x01, 0x24)
        self.dg_items.set(self.ITM_TRPH_IDX, 0x01, 0x38)
        self.dg_items.set(self.ITM_MEDI_IDX, 0x01, 0x4c)
        self.dg_items.set(self.ITM_CHLD_IDX, 0x01, 0x5d)
      } else {
        self.dg_items.set(self.ITM_NOTE_IDX, 0x01, 0x11)
        self.dg_items.set(self.ITM_MIRR_IDX, 0x01, 0x1f)
        self.dg_items.set(self.ITM_TRPH_IDX, 0x01, 0x30)
        self.dg_items.set(self.ITM_MEDI_IDX, 0x01, 0x41)
        self.dg_items.set(self.ITM_CHLD_IDX, 0x01, 0x51)
        if (self.POSITIONING_VER !== 3) {
          self.dg_items.set(self.ITM_BTL1_IDX, 0x01, 0x60)
        }
        if (gmb(val(f.dm_quests.get(`${STR_Bottle}01${STR_State}`)))) {
          self.dg_items.set(self.ITM_BTL1_IDX, 0x03, self.ITM_BTL1_SPR2)
        } /* Bottle full */ else {
          self.dg_items.set(self.ITM_BTL1_IDX, 0x03, self.ITM_BTL1_SPR1) //  Bottle empty
        }
      }
      self.dg_icons1.set(0, 1, g.CHAR_TIMES + string(f.lives))
      self.dg_icons1.set(2, 1, g.CHAR_TIMES + string(f.kakusu_count))
      _text = g.CHAR_TIMES
      if (gmb(f.items & ITM_SKEY)) {
        _text += 'A'
      } else {
        _DUNGEON_NUM = val(f.dm_rando.get(g.rm_name + STR_Dungeon + STR_Num), g.dungeon_num)
        _text += string(get_key_count(_DUNGEON_NUM))
        //_text = string(f.key_count);
      }
      self.dg_icons1.set(1, 1, _text)
      //if (g.area_name==Area_TownB
      //&& !(f.items&ITM_MASK) )
      if (g.town_name === STR_Bulblin && +!gmb(G.pc.Disguise_enabled)) {
        self.MapAreaName = MapAreaName_DEF
      } else if (gmb(g.encounter_type)) {
        self.MapAreaName = G.OVERWORLD.dg_AreaNames.get(
          (G.OVERWORLD.pcrc >> 0) & 0xff,
          (G.OVERWORLD.pcrc >> 8) & 0xff,
        )
      } else {
        self.MapAreaName = val(g.dm_rm.get(g.rm_name + MapAreaName_DATAKEY), MapAreaName_DEF)
        self.MapAreaName = val(f.dm_rando.get(g.rm_name + MapAreaName_DATAKEY), self.MapAreaName)
      }
      PauseMenu_udp(self)
      aud_play_sound(get_audio_theme_track(dk_OpenGUI))
      self.timer0 = 0
      g.menu_state++
      break
    }
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    case 2: {
      // ---------------------------------------------------------------------------------------------
      if (gmb(self.timer0)) {
        break
      }
      // A148, A267
      // g.spell_ready = SPL_NONE;
      // g.spell_cast = SPL_NONE;
      PauseMenu_udp(self)
      self.timer0 = 0
      g.menu_state++
      break
    }
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    case 3: {
      // ---------------------------------------------------------------------------------------------
      if (gmb(self.timer0)) {
        break
      }
      self.state &= 0x03
      if (+!gmb(self.state)) {
        self.state = self.state_SPELL
      }
      self.rm_pal_on_open = p.pal_rm_curr
      change_pal(
        strReplaceAt(self.rm_pal_on_open, p.PAL_POS_MOB1, string_length(self.PAL_MOBS), self.PAL_MOBS),
      )
      PauseMenu_udp(self)
      self.timer0 = 0
      g.menu_state++
      break
    }
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    case 4: {
      // ---------------------------------------------------------------------------------------------
      if (gmb(self.timer0)) {
        break
      }
      PauseMenu_update_1a(self) // sets: g.spell_selected, map_clm_off,map_row_off
      _count = self.ANIM_FRAMES_DEF // Going to spell or item
      if ((self.state & 0x03) === self.state_MAP) {
        _count = self.ANIM_FRAMES_MAP // Going to Map
      }
      _C1 = true
      //_C1 = Input.GP_Other6_pressed; // for testing. animation advances only 1 frame with button press
      if (gmb(_C1)) {
        g.menu_built_count += +(g.menu_built_count < _count)
        g.menu_built_count -= +(g.menu_built_count > _count)
      }
      PauseMenu_udp(self)
      //timer0 = $10; // testing. slow down animation
      if (gmb(_C1) && g.menu_built_count === _count) {
        self.timer0 = 0
        g.menu_state++
      }
      break
    }
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    case 5: {
      // PAUSEMENU INTERACTIVITY -------------------------------------------
      if (gmb(self.timer0)) {
        break
      }
      PauseMenu_update_2a(self)
      break
    }
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    case 6: {
      // ---------------------------------------------------------------------------------------------
      if (gmb(self.timer0)) {
        break
      }
      // Start was pressed. Closing menu.
      if (g.menu_built_count > self.ANIM_FRAMES_DEF || (self.state & 0x03) === self.state_MAP) {
        self.state = (self.state << 4) | (self.state >> 4) // draws SPL or ITM as MAP closes
        g.menu_built_count--
      }
      // A26B
      PauseMenu_udp(self)
      // A267
      self.timer0 = 0
      g.menu_state++
      break
    }
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    case 7: {
      // ---------------------------------------------------------------------------------------------
      if (gmb(self.timer0)) {
        break
      }
      // A3D7
      g.menu_built_count--
      if (g.menu_built_count < 0) {
        change_pal(self.rm_pal_on_open)
        self.timer0 = 0
        g.menu_state++ // menu_built_count below 0
      } else {
        PauseMenu_udp(self)
      }
      break
    }
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    // ---------------------------------------------------------------------------------------------
    case 8: {
      // ---------------------------------------------------------------------------------------------
      if (gmb(self.timer0)) {
        break
      }
      //change_pal(rm_pal_on_open);
      // A338
      self.timer0 = 0
      g.gui_state = g.gui_state_NONE
      g.menu_state = 0
      g.menu_built_count = 0
      break
    }
  }
  self.state &= 0x33
}

