/** GML: PauseMenu_draw_spell_menu() */
export function PauseMenu_draw_spell_menu(self: PauseMenu) {
  let _i: any, _x: any, _y: any, _text: any, _spell_bit: any, _amount: any, _pi: any

  if (gmb(g.mod_SHOW_MAGIC_REMAINING_NUM) && gmb(self.Window_vertical_draw_section_count)) {
    _spell_bit = -1
    _text = self.Head_TEXT
    _amount = f.mp >> 1
    _x = self.Window_xl0
    _y = self.drawY
    _y -= 1 // micro adj
    PauseMenu_draw_spell(self, _spell_bit, _text, _amount, _x, _y, self.PI_MENU1)
  }
  // Each section
  for (_i = 0; _i < self.Window_vertical_draw_section_count - 1; _i++) {
    if (_i >= g.SPELL_COUNT) {
      break //_i
    }
    _spell_bit = 0x01 << _i
    if (+!gmb(f.spells & _spell_bit)) {
      continue //_i
    }
    if (_spell_bit === SPL_FARY && gmb(g.CuccoSpell2_Acquired) && gmb(g.CuccoSpell2_Option)) {
      _text = self.SPELL_TEXT_CUCCO
    } else {
      _text = self.dl_spell_str.get(_i)
    }
    _amount = get_spell_cost(_spell_bit)
    _x = self.Window_xl0
    _y = self.drawY + (_i << 4)
    _y -= 1 // gives 1 extra pixel pad for 9th spell
    if (gmb(g.mod_IndicateSpellUnaffordable) && f.mp - _amount < 0) {
      _pi = G.spell_unaffordable_pi
    } else if (gmb(g.mod_IndicateSpellActive) && gmb(g.spells_active & _spell_bit)) {
      _pi = G.spell_futile_pi
    } else {
      _pi = self.PI_MENU1
    }
    _amount = _amount >> 1
    PauseMenu_draw_spell(self, _spell_bit, _text, _amount, _x, _y, _pi)
  }
}

/** GML: PauseMenu_draw_spell() */
export function PauseMenu_draw_spell(self: PauseMenu, ...argument: any[]) {
  let _x: any, _y: any

  argument[3] += g.mod_MENU_SPELLS_XOFF
  argument[4] += g.mod_MENU_SPELLS_YOFF
  // if not "MAGIC" text amt at menu top
  if (gmb(g.mod_SHOW_MAGIC_REMAINING_NUM) && gmb(argument[0])) {
    argument[4] += 0x02 << 3
  }
  if (g.spell_selected === argument[0]) {
    _x = argument[3] + (0x01 << 3)
    _y = argument[4] + (0x01 << 3)
    draw_spr_aligned(self.SPR_ICON_SPL, _x, _y, -1, -1, self.PI_MENU1)
  }
  // text --------------------------------
  if (argument[2] < 10) {
    argument[1] += '00'
  } else if (argument[2] < 100) {
    argument[1] += '0'
  }
  argument[1] += string(argument[2])
  //
  _x = argument[3] + (0x02 << 3)
  _y = argument[4] + (0x01 << 3)
  draw_text_(_x, _y, argument[1], -1, argument[5])
}

