/** GML: PauseMenu_draw_map_dungeon() */
export function PauseMenu_draw_map_dungeon(self: PauseMenu) {
  let _i: any,
    _j: any,
    _x: any,
    _y: any,
    _xl: any,
    _yt: any,
    _x_base: any,
    _y_base: any,
    _x_scale: any,
    _y_scale: any,
    _tsrc: any,
    _ts_xl: any,
    _ts_yt: any,
    _clm: any,
    _row: any,
    _rm_name: any,
    _page: any,
    _AREA_NAME: any,
    _DUNGEON_NUM: any,
    _Entrance_COUNT: any,
    _Entrance_ExitName: any,
    _Entrance_ExitID: any,
    _Entrance_RmName: any,
    _Entrance_Page: any,
    _Entrance_Open: any,
    _dg_Entrance: any,
    _DRAW_CLM_LFT: any,
    _DNGN_CLM_LFT: any,
    _DRAW_ROW_TOP: any,
    _DNGN_ROW_TOP: any,
    _Entrance_ExitDir: any,
    _EntranceArrow_SPR: any

  _rm_name = RM_NAME_NPALACE

  _AREA_NAME = val(f.dm_rando.get(g.rm_name + STR_Dungeon + STR_Area), g.area_name)
  _DUNGEON_NUM = val(f.dm_rando.get(g.rm_name + STR_Dungeon + STR_Num), g.dungeon_num)
  _Entrance_COUNT = val(g.dm_rm.get(_AREA_NAME + STR_Entrance + STR_Count))
  _Entrance_ExitName = val(g.dm_rm.get(get_dk_dungeon_entrance(_DUNGEON_NUM)), REEN_DEFAULT)
  _Entrance_ExitID = str_hex(string_copy(_Entrance_ExitName, RmName_LEN + 1, 2))
  _Entrance_RmName = string_copy(_Entrance_ExitName, 1, RmName_LEN)
  _Entrance_Page = val(g.dm_rm.get(_Entrance_ExitName + STR_Page))
  _Entrance_Open = 0
  //var _Entrance_Open     = val(g.dm_rm[?_Entrance_ExitName+STR_Open]);
  if (gmb(_Entrance_COUNT)) {
    _dg_Entrance = ds_grid_create(_Entrance_COUNT, 5)
    for (_i = 0; _i < _Entrance_COUNT; _i++) {
      _Entrance_ExitName = val(g.dm_rm.get(_AREA_NAME + STR_Entrance + hex_str(_i + 1)), REEN_DEFAULT)
      _Entrance_ExitID = str_hex(string_copy(_Entrance_ExitName, RmName_LEN + 1, 2))
      _Entrance_RmName = string_copy(_Entrance_ExitName, 1, RmName_LEN)
      _Entrance_Page = val(g.dm_rm.get(_Entrance_ExitName + STR_Page))
      _Entrance_Open = val(g.dm_rm.get(_Entrance_ExitName + STR_Open))
      _dg_Entrance.set(_i, 0, _Entrance_ExitName)
      _dg_Entrance.set(_i, 1, _Entrance_ExitID)
      _dg_Entrance.set(_i, 2, _Entrance_RmName)
      _dg_Entrance.set(_i, 3, _Entrance_Page)
      _dg_Entrance.set(_i, 4, _Entrance_Open)
    }
  }
  _x_base = 0
  _y_base = 0
  /*
if (MapPaper_USE_SURFACE)
{
    _x_base = 0;
    _y_base = 0;
}
else
{
    _x_base = MapArea_xl;
    _y_base = MapArea_yt;
}
*/
  _x_base += 0x01 << 3
  _y_base += 0x01 << 3
  _DRAW_CLM_LFT = _x_base >> 3 // 1st rm draw clm
  _DNGN_CLM_LFT = _DRAW_CLM_LFT - 1 // 1st clm of drawn paper
  _DNGN_CLM_LFT += self.paper_drawn_clms // 1st clm after rgt of paper
  _DNGN_CLM_LFT -= self.MapPaper_CLMS // 1st clm of paper (drawn or not)
  _DNGN_CLM_LFT += 1 // 1st clm of rm draw area (drawn or not)
  _DNGN_CLM_LFT += self.map_clm_off // lft most clm of dungeon (drawn or not)
  //
  _DRAW_ROW_TOP = _y_base >> 3 // 1st rm draw row
  _DNGN_ROW_TOP = _DRAW_ROW_TOP - 1 // 1st row of drawn paper
  _DNGN_ROW_TOP += self.paper_drawn_rows // 1st row after btm of paper
  _DNGN_ROW_TOP -= self.MapPaper_ROWS // 1st row of paper (drawn or not)
  _DNGN_ROW_TOP += 1 // 1st row of rm draw area (drawn or not)
  _DNGN_ROW_TOP += self.map_row_off // top most row of dungeon (drawn or not)
  //
  pal_swap_set(G.PI_GUI1)
  for (_i = ds_grid_width(self.dg_dngn_map) - 1; _i >= 0; _i--) {
    // index: 5 rm_name, 6 rm page, 7 explored
    // if not yet explored rm page
    // if true, all rms/pages will draw regardless of explored amount
    if (+!gmb(self.dg_dngn_map.get(_i, 7)) && +!gmb(g.dev_DungeonMapShowAll)) {
      continue //_i
    }
    _clm = _DNGN_CLM_LFT + self.dg_dngn_map.get(_i, 0) // idx 0: clm
    _row = _DNGN_ROW_TOP + self.dg_dngn_map.get(_i, 1) // idx 1: row
    //if(g.dungeon_num==2 && !(g.counter0&$7F)) sdm("dg_dngn_map[#_i,0] $"+hex_str(dg_dngn_map[#_i,0])+", dg_dngn_map[#_i,1] $"+hex_str(dg_dngn_map[#_i,1])+", _DNGN_CLM_LFT $"+hex_str(_DNGN_CLM_LFT)+", _DNGN_ROW_TOP $"+hex_str(_DNGN_ROW_TOP)+", _clm $"+hex_str(_clm)+", _row $"+hex_str(_row));
    if (
      _clm < _DRAW_CLM_LFT ||
      _clm >= _DRAW_CLM_LFT + (self.paper_drawn_clms - 2) ||
      _row < _DRAW_ROW_TOP ||
      _row >= _DRAW_ROW_TOP + (self.paper_drawn_rows - 2)
    ) {
      continue //_i
    }
    _x_scale = self.dg_dngn_map.get(_i, 3)
    _y_scale = self.dg_dngn_map.get(_i, 4)
    _x = _clm << 3
    _x += +!gmb(_x_scale) << 3
    _y = _row << 3
    _y += +!gmb(_y_scale) << 3
    _tsrc = self.dg_dngn_map.get(_i, 2)
    _ts_xl = ((_tsrc >> 0) & 0x0f) << 3
    _ts_yt = ((_tsrc >> 4) & 0x0f) << 3
    draw_background_part_ext(g.TS_MENU, _ts_xl, _ts_yt, 8, 8, _x, _y, _x_scale, _y_scale, c_white, 1)
    if (gmb(_Entrance_COUNT) && gmb(g.counter0 & 0x20)) {
      _x_base = (_clm << 3) + 4
      _y_base = (_row << 3) + 4
      _rm_name = self.dg_dngn_map.get(_i, 5)
      _page = self.dg_dngn_map.get(_i, 6)
      for (_j = 0; _j < _Entrance_COUNT; _j++) {
        _Entrance_ExitName = _dg_Entrance.get(_j, 0)
        _Entrance_ExitID = _dg_Entrance.get(_j, 1)
        _Entrance_RmName = _dg_Entrance.get(_j, 2)
        _Entrance_Page = _dg_Entrance.get(_j, 3)
        _Entrance_Open = _dg_Entrance.get(_j, 4)
        if (_Entrance_RmName !== _rm_name || _Entrance_Page !== _page || +!gmb(_Entrance_Open)) {
          continue //_j
        }
        // $00-0F:  Middle/Doorway exits
        // $10-1F, $20-2F, $40-4F, $80-8F: Side exits
        _Entrance_ExitDir = (_Entrance_ExitID & 0xf0) >> 4
        // $0:  Middle/Doorway exits
        if (+!gmb(_Entrance_ExitDir)) {
          // Arrow will face downward pointing a bit above the
          // y center of the entrance exit's page.
          _EntranceArrow_SPR = self.dl_DngnEntranceArrow_SPR.get(bitNum(0x04))
        } /* $1(RGT), $2(LFT), $4(DWN), $8(UP) */ else {
          // Arrow will point AWAY from the entrance exit
          // and be close to that exit, but outside the rm.
          _EntranceArrow_SPR = self.dl_DngnEntranceArrow_SPR.get(bitNum(_Entrance_ExitDir))
        }
        _x = _x_base
        _y = _y_base
        if (+!gmb(_Entrance_ExitDir)) {
          _y -= 3
        } else {
          _x += self.DngnEntranceArrow_XYOff * bit_dir(_Entrance_ExitDir & 0x03)
          _y += self.DngnEntranceArrow_XYOff * bit_dir(_Entrance_ExitDir & 0x0c)
        }
        draw_sprite_(_EntranceArrow_SPR, 0, _x, _y)
      }
    }
  }
  pal_swap_reset()
  if (gmb(_Entrance_COUNT)) {
    ds_grid_destroy(_dg_Entrance)
    _dg_Entrance = undefined
  }
  /* // debug.  1 Line indicates the left edge of rm draw area.
var _color = c_lime;
// indicates the LEFT edge of rm draw area.
draw_line_colour( _x_base,      0, _x_base,viewYB(), _color,_color);
// indicates the TOP  edge of rm draw area.
draw_line_colour(viewXL(),_y_base,viewXR(), _y_base, _color,_color);

_color = c_aqua;
_x  = _DNGN_CLM_LFT<<3;
// indicates the LEFT edge of the dungeon
draw_line_colour( _x,           0, _x,     viewYB(), _color,_color);
// indicates the TOP  edge of the dungeon
_y  = _DNGN_ROW_TOP<<3;
draw_line_colour(viewXL(),     _y,viewXR(),       _y, _color,_color);
*/
}

/** GML: update_explored_data() */
export function update_explored_data(self: PauseMenu) {
  let _PAGE_X: any,
    _PAGE_Y: any,
    _SCENE_NAME: any,
    _DUNGEON_NUM: any,
    _MAP_ALL_PAGES: any,
    _PAGE: any,
    _i: any,
    _j: any,
    _k: any,
    _m: any,
    _val: any,
    _val1: any,
    _val2: any,
    _count: any,
    _page: any,
    _clm: any,
    _row: any,
    _len: any,
    _rm_name: any,
    _exit_name: any,
    _qualifies: any,
    _IDX1: any,
    _COUNT2: any,
    _COUNT1: any,
    _datakey: any

  // Crossed into a map page
  // Crossed into a map page
  if (G.pc.x >> 8 !== G.pc.x_prev >> 8 || G.pc.y >> 8 !== G.pc.y_prev >> 8) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  _PAGE_X = G.pc.x >> 8
  _PAGE_Y = G.pc.y >> 8
  if (+!gmb(_PAGE_X + 1) || +!gmb(_PAGE_Y + 1)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  _SCENE_NAME = g.rm_name
  _SCENE_NAME = val(f.dm_rando.get(g.rm_name + STR_Scene + STR_Name), _SCENE_NAME)
  //
  _DUNGEON_NUM = g.dungeon_num
  _DUNGEON_NUM = val(f.dm_rando.get(g.rm_name + STR_Dungeon + STR_Num), _DUNGEON_NUM)
  //var _AREA_NAME   = val(f.dm_rando[?g.rm_name+STR_Dungeon+STR_Area], g.area_name);
  _MAP_ALL_PAGES = false
  if (
    gmb(_DUNGEON_NUM) &&
    gmb(val(g.dm_rm.get(`${STR_Map + STR_Explored + STR_Exception}01${_SCENE_NAME}`))) &&
    +!gmb(val(f.dm_explored.get(_SCENE_NAME + STR_Explored)))
  ) {
    _MAP_ALL_PAGES = true
  }
  _PAGE = hex_str(_PAGE_Y * g.rm_pages_x + _PAGE_X)
  //if(!val(f.dm_explored[?_SCENE_NAME+STR_Explored])) sdm(_SCENE_NAME+". "+"_MAP_ALL_PAGES "+string(_MAP_ALL_PAGES)+", g.rm_pages_x "+string(g.rm_pages_x)+", g.rm_pages_y "+string(g.rm_pages_y)+", _PAGE_X "+string(_PAGE_X)+", _PAGE_Y "+string(_PAGE_Y)+", _PAGE "+string(_PAGE));
  f.dm_explored.set(_SCENE_NAME + STR_Explored + STR_Page + _PAGE, 1)
  f.dm_explored.set(_SCENE_NAME + STR_Explored, 1)
  // ---------------------------------------------------------------------------------------------------
  // ---------------------------------------------------------------------------------------------------
  if (gmb(_DUNGEON_NUM)) {
    withOther(g.PAUSE_MENU, self, (self: any, _other) => {
      _qualifies = false
      _IDX1 = 7 // dg_dngn_map index 7: Has visited map page
      _COUNT2 = ds_grid_width(self.dg_dngn_map)
      if (gmb(_MAP_ALL_PAGES)) {
        _COUNT1 = g.rm_pages_x * g.rm_pages_y
      } else {
        _COUNT1 = 1
      }
      for (_i = 0; _i < _COUNT1; _i++) {
        if (gmb(_MAP_ALL_PAGES)) {
          _page = hex_str(_i)
        } else {
          _page = _PAGE
        }
        f.dm_explored.set(_SCENE_NAME + STR_Explored + STR_Page + _page, 1)
        _datakey = _SCENE_NAME + STR_Page + _page + STR_Map
        // dg_dngn_map: 0:clm, 1:row, 2:tsrc, 3: xscale, 4: yscale, 5: rm_name, 6: rm page, 7: explored, 8: if tsrc is elevator shaft, this is a string of each exit name
        _clm = g.dm_rm.get(_datakey + STR_Idx)
        if (+!gmb(_MAP_ALL_PAGES)) {
          if (!is_undefined(_clm)) {
            self.dngn_map_pc_rc = (self.dg_dngn_map.get(_clm, 1) << 8) | self.dg_dngn_map.get(_clm, 0)
          }
        }
        if (!is_undefined(_clm)) {
          update_dngn_vis_rc(self, self.dg_dngn_map.get(_clm, 0), self.dg_dngn_map.get(_clm, 1))
        }
        //
        if (!is_undefined(_clm) && +!gmb(self.dg_dngn_map.get(_clm, _IDX1))) {
          self.dg_dngn_map.set(_clm, _IDX1, 1)
          switch (_DUNGEON_NUM) {
            case 1: {
              self.dg_dngn_map_1.set(_clm, _IDX1, 1)
              break
            }
            case 2: {
              self.dg_dngn_map_2.set(_clm, _IDX1, 1)
              break
            }
            case 3: {
              self.dg_dngn_map_3.set(_clm, _IDX1, 1)
              break
            }
            case 4: {
              self.dg_dngn_map_4.set(_clm, _IDX1, 1)
              break
            }
            case 5: {
              self.dg_dngn_map_5.set(_clm, _IDX1, 1)
              break
            }
            case 6: {
              self.dg_dngn_map_6.set(_clm, _IDX1, 1)
              break
            }
            case 7: {
              self.dg_dngn_map_7.set(_clm, _IDX1, 1)
              break
            }
            case 8: {
              self.dg_dngn_map_8.set(_clm, _IDX1, 1)
              break
            }
          }
          //ds_map_add(dg_dngn_map, _datakey+STR_Clm, _clm);
          //ds_map_add(dg_dngn_map, _datakey+STR_Row, _IDX1);
          // ELEVATOR SHAFTS  -------------------------------------------
          _len = string_length(_SCENE_NAME) + 2
          // _COUNT2: dg_dngn_map width
          for (_j = 0; _j < _COUNT2; _j++) {
            // TSRC_ELEVATOR_SHAFT=$60
            if (self.dg_dngn_map.get(_j, 2) === TSRC_ELEVATOR_SHAFT) {
              _val = self.dg_dngn_map.get(_j, 8)
              if (is_string(_val)) {
                _count = Math.trunc(string_length(_val) / ExitName_LEN)
                for (_k = 0; _k < _count; _k++) {
                  _exit_name = string_copy(_val, ExitName_LEN * _k + 1, ExitName_LEN)
                  _val1 = val(g.dm_rm.get(_exit_name + STR_Page), -1)
                  _rm_name = string_copy(_exit_name, 1, RmName_LEN)
                  //sdm("_count "+string(_count)+", "+_val+", _exit_name "+_exit_name+", _rm_name "+_rm_name+", _val1 "+string(_val1)+", _page "+string(_page));
                  if (_rm_name === _SCENE_NAME && _val1 === str_hex(_page)) {
                    self.dg_dngn_map.set(_j, _IDX1, 1)
                    switch (_DUNGEON_NUM) {
                      case 1: {
                        self.dg_dngn_map_1.set(_j, _IDX1, 1)
                        break
                      }
                      case 2: {
                        self.dg_dngn_map_2.set(_j, _IDX1, 1)
                        break
                      }
                      case 3: {
                        self.dg_dngn_map_3.set(_j, _IDX1, 1)
                        break
                      }
                      case 4: {
                        self.dg_dngn_map_4.set(_j, _IDX1, 1)
                        break
                      }
                      case 5: {
                        self.dg_dngn_map_5.set(_j, _IDX1, 1)
                        break
                      }
                      case 6: {
                        self.dg_dngn_map_6.set(_j, _IDX1, 1)
                        break
                      }
                      case 7: {
                        self.dg_dngn_map_7.set(_j, _IDX1, 1)
                        break
                      }
                    }
                    break //_k
                  }
                }
              }
            }
          }
        }
      }
    })
  }
}

/** GML: update_dngn_vis_rc() */
export function update_dngn_vis_rc(self: PauseMenu, ...argument: any[]) {
  withOther(g.PAUSE_MENU, self, (self: any, _other) => {
    if (self.dungeon_vis_rgt < argument[0]) {
      self.dungeon_vis_rgt = argument[0]
    }
    if (self.dungeon_vis_lft > argument[0]) {
      self.dungeon_vis_lft = argument[0]
    }
    if (self.dungeon_vis_btm < argument[1]) {
      self.dungeon_vis_btm = argument[1]
    }
    if (self.dungeon_vis_top > argument[1]) {
      self.dungeon_vis_top = argument[1]
    }
    //dungeon_clms = max((dungeon_vis_rgt - dungeon_vis_lft) + 1);
    //dungeon_rows = max((dungeon_vis_btm - dungeon_vis_top) + 1);
  })
}

