/** Leever (`LeevA`) — burrows, surfaces, moves, submerges. Ported from `Leever_init2/update/udp/in_ground_y.gml`. */
import { CS_BD1, DEPTH_BG7, STR_Ground, STR_Row, TID_SOLID1 } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G } from '../../../../../../runtime/world'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { find_rc_solid, find_solid_point } from '../../../../../collision/solid'
import { cam_yt_max, cam_yt_min } from '../../../../../view/camera'
import { Enemy } from '../../../../classes'
import { dir_to_pc } from '../../../../go/misc'
import { set_xlyt, set_xy, updateX } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_depth_init } from '../../../../go/sprite'
import { gp } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_udp_1, GOB_update_2 } from '../../../GameObjectB'
import { rand } from '../iron_knuckle/common'

export class LeevA extends Enemy {
  readonly objectName = 'LeevA' as const
  SUB_STATE_NEWXY = 1
  SUB_STATE_SURFC = 2 // Surface. In ground, moving up to surface.
  SUB_STATE_MOVEX = 3
  SUB_STATE_SBMRG = 4 // Submerge. Moving down to under ground.
  sub_state = 1
  IN_GROUND_YOFF = -4
  IN_GROUND_Y_DEF = 0
  IN_GROUND_ROW_MIN = 0
}

/** `Leever_init2()` */
export function Leever_init2(self: LeevA): void {
  const g = gp()
  self.dl_sprites?.add('spr_Leever1')
  self.dl_sprites?.add('spr_Leever2')
  GO_init_palidx(self, G.PI_MOB_BLU)
  GO_depth_init(self, DEPTH_BG7 + 3)
  let _a = 1
  self.SUB_STATE_NEWXY = _a++
  self.SUB_STATE_SURFC = _a++
  self.SUB_STATE_MOVEX = _a++
  self.SUB_STATE_SBMRG = _a++
  self.sub_state = self.SUB_STATE_NEWXY
  self.IN_GROUND_YOFF = -4
  self.IN_GROUND_Y_DEF = cam_yt_max() - 8 + (0x18 << 3) + self.IN_GROUND_YOFF // OG: $BC
  self.IN_GROUND_ROW_MIN = Math.max(cam_yt_min(), 0x03 << 3) >> 3
  let _YT = find_solid_point(
    self.xl,
    self.IN_GROUND_ROW_MIN << 3,
    0,
    1,
    0,
    (self.IN_GROUND_Y_DEF - self.IN_GROUND_YOFF) << 0xc,
  )
  _YT = ((_YT >> 0xc) & 0xff8) + self.IN_GROUND_YOFF
  set_xlyt(self, self.xl, _YT)
  const _val = g.dm_rm.get(g.rm_name + STR_Ground + STR_Row)
  if (_val !== undefined) {
    self.IN_GROUND_ROW_MIN = Number(_val)
    set_xlyt(self, self.xl, (self.IN_GROUND_ROW_MIN << 3) + self.IN_GROUND_YOFF)
  }
}

/** `Leever_in_ground_y(clm, row)` */
export function Leever_in_ground_y(self: LeevA, clm: number, row: number): number {
  let _Y = find_rc_solid(TID_SOLID1 & 0xf, clm, row, 0, 1)
  _Y = (_Y >> 8) & 0xff
  _Y = _Y << 3
  return _Y + self.IN_GROUND_YOFF
}

/** `Leever_update()` */
export function Leever_update(self: LeevA): void {
  const g = gp()
  const _RAND = rand(self)
  // 9910: JSR DA02
  GOB_update_2(self)
  if (gmBool(self.stun_timer)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // 9916
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  switch (self.sub_state) {
    case self.SUB_STATE_NEWXY: {
      // 9928
      if (gmBool(self.timer)) break
      let _X = g.view_xl_og + _RAND
      _X += self.ww_
      let _Y = Leever_in_ground_y(self, _X >> 3, self.IN_GROUND_ROW_MIN)
      _Y += self.hh_
      // MOD.  Prevent spawning out of solids.
      if (!gmBool(G.dg_solid.get((_X - self.ww_) >> 3, _Y >> 3))) _X += 8
      if (!gmBool(G.dg_solid.get((_X + self.ww_) >> 3, _Y >> 3))) _X -= 8
      _X = (_X >> 3) << 3
      set_xy(self, _X, _Y)
      self.facing_dir = dir_to_pc(self)
      self.hspd_dir = self.facing_dir
      self.hspd = (0x10 * self.hspd_dir) & 0xff
      self.timer = 0x50 // 1.333s
      self.sub_state = self.SUB_STATE_SURFC
      break
    }
    case self.SUB_STATE_SURFC: {
      // 9950
      if (gmBool(self.timer)) {
        if (self.timer < 0x1a && !(self.timer & 1)) set_xy(self, self.x, self.y - 1)
        break
      }
      // $30-3F: 0.800s-1.050s, $70-7F: 1.867s-2.117s. 50% chance to include bit $40
      self.timer = 0x30 | (_RAND >> 1)
      self.sub_state = self.SUB_STATE_MOVEX
      break
    }
    case self.SUB_STATE_MOVEX: {
      // 996C. MOD.  Prevent moving out of solids.
      const _X = self.x + self.ww_ * self.hspd_dir + self.hspd_dir
      const _Y = self.y + self.hh_ + 1
      if (!gmBool(G.dg_solid.get(_X >> 3, _Y >> 3)))
        self.timer = 0 // Force SUB_STATE_SBMRG
      else updateX(self)
      if (gmBool(self.timer)) break
      self.timer = 0x20 // 0.533s
      self.sub_state = self.SUB_STATE_SBMRG
      break
    }
    case self.SUB_STATE_SBMRG: {
      // 997C
      if (gmBool(self.timer)) {
        if (self.timer & 1) set_xy(self, self.x, self.y + 1)
        break
      }
      self.timer = 0x30 | (_RAND >> 1)
      self.sub_state = self.SUB_STATE_NEWXY
      break
    }
    default:
      break
  }
}

/** `Leever_udp()` */
export function Leever_udp(self: LeevA): void {
  self.can_draw_self = true
  GOB_udp_1(self, 8)
}

export function registerLeever(): void {
  registerObject('LeevA', LeevA)
  registerScripts({ Leever_init2, Leever_update, Leever_udp })
}
registerLeever()
