import {
  dk_Intro_CanPlay,
  dk_LowHPBeep,
  dk_SceneMusicThemeException,
  STR_Asset,
  STR_Audio,
  STR_Body,
  STR_Boss,
  STR_Intro,
  STR_Length,
  STR_Name,
  STR_Volume,
} from '@z2/data'
import { gmBool } from '../../nes/math8'
import { input, world } from '../../runtime/world'
import { Audio, type SoundId } from './Audio'
import { fd, firstBoss, gd } from './deps'
import { aud_play_sound, aud_toggle_mus, aud_toggle_snd, audio_stop_sound } from './play'
import { get_audio_theme_track } from './theme'

const val = <T>(v: T | undefined, dflt?: T): T | 0 => (v === undefined ? (dflt === undefined ? 0 : dflt) : v)

/** `Audio_update()` — per-frame audio: mute keys, fire sfx, boss/scene music, track-position bookkeeping. */
export function Audio_update(): void {
  const A = Audio
  // MUTE/UN-MUTE - music("M") / sound("S"); update fire sound
  Audio_update_1()
  // update boss music and scene music
  Audio_update_2()

  // ------------------------------------------------------------------------
  // Title screen timing sound: a silent copy of the title track whose position drives the scrolling.
  if (A.rm_music_theme === '_Title' && gd().ChangeRoom_timer <= 0) {
    const n = A.audio_get_name(A.timing_sound_inst)
    if (n !== 'snd_Default_Title_Intro_no_volume' && n !== 'snd_Default_Title_no_volume') {
      A.timing_sound_inst = aud_play_sound('snd_Default_Title_Intro_no_volume', 1, false)
    } else if (n === 'snd_Default_Title_Intro_no_volume' && !A.audio_is_playing(A.timing_sound_inst)) {
      A.timing_sound_inst = aud_play_sound('snd_Default_Title_no_volume', 1, true)
    }
  }
  // ------------------------------------------------------------------------
  if (A.mus_rm_inst && A.audio_is_playing(A.mus_rm_inst)) {
    A.mus_rm_pos_prev = A.mus_rm_pos_curr
    A.mus_rm_pos_curr = A.playback.trackPosition(A.mus_rm_inst)
  } else {
    A.mus_rm_pos_prev = 0
    A.mus_rm_pos_curr = 0
  }
  // The track position of a sound instance on any given frame is a very precise fraction and does NOT
  // start at 0 on the frame it loops.
  if (A.timing_sound_inst && A.audio_is_playing(A.timing_sound_inst)) {
    A.timing_sound_position_prev = A.timing_sound_position_curr
    A.timing_sound_position_curr = A.playback.trackPosition(A.timing_sound_inst)
  } else {
    A.timing_sound_position_prev = 0
    A.timing_sound_position_curr = 0
  }
  if (
    A.mus_rm_inst &&
    A.audio_is_playing(A.mus_rm_inst) &&
    A.mus_rm_body &&
    A.audio_get_name(A.mus_rm_inst) === A.audio_get_name(A.mus_rm_body)
  ) {
    A.mus_rm_body_last_pos = A.playback.trackPosition(A.mus_rm_inst)
  }
}

/** `Audio_update_1()` — mute toggles and the fire-crackle sound (C1C6). */
export function Audio_update_1(): void {
  const A = Audio
  if (input.keyboard_check_pressed(A.TOGGLE_SOUND_KEY)) aud_toggle_snd()
  if (input.keyboard_check_pressed(A.TOGGLE_MUSIC_KEY)) aud_toggle_mus()

  // C1C6
  const fire = A.dl_snd_fire
  const cur = fire.get(0) as SoundId
  if (gmBool(fire.get(1) as number)) {
    // 1: can_play. Must be set every frame
    if (!A.audio_is_playing(cur) || !gmBool(fire.get(3) as number)) {
      // 3: timer
      fire.set(3, fire.get(4) as number) // 4: timer reset
      if (A.SND_FIRE_VER === 1) fire.set(0, fire.get(world.irandom(3) + 5) as SoundId)
      const vol = fire.get(2) as number
      if (vol === -1)
        aud_play_sound(fire.get(0) as SoundId) // -1: use default volume
      else aud_play_sound(fire.get(0) as SoundId, -1, -1, vol)
    }
    if (gmBool(fire.get(3) as number)) fire.set(3, (fire.get(3) as number) - 1) // 3: timer
  } else {
    audio_stop_sound(cur) // 0: current snd playing
  }
  fire.set(1, 0) //  1: can_play. Must be set every frame
  fire.set(2, -1) // -1: use default volume
}

/** `Audio_update_2()` — boss music, then play the room intro or body when nothing is playing. */
export function Audio_update_2(): void {
  const A = Audio
  const dm = A.dm
  if (A.audio_is_playing(A.mus_rm_inst)) {
    // TODO (ZALiA 2024/10/11): Finish converting all tracks to this new system — tracks with a
    // `_Intro_Length`/`_Body_Length` (the Wyng set) loop by track position inside one asset.
    const _NAME = A.dm_music_inst.get(String(A.mus_rm_inst) + STR_Audio + STR_Asset + STR_Name) as
      | string
      | undefined
    if (_NAME !== undefined) {
      const _INTRO_LEN = Number(val(dm.get(_NAME + STR_Intro + STR_Length)))
      if (_INTRO_LEN > 0) {
        const _BODY_LEN = Number(val(dm.get(_NAME + STR_Body + STR_Length)))
        const _POS = A.playback.trackPosition(A.mus_rm_inst)
        if (_POS >= _INTRO_LEN + _BODY_LEN)
          A.push({ kind: 'position', inst: A.mus_rm_inst, seconds: _POS - _BODY_LEN })
        return
      }
    }
  }

  // ------------------------------------------------------------------------
  const boss = firstBoss()
  if (A.can_play_boss_music && !A.audio_is_playing(A.mus_rm_inst) && boss) {
    if (
      boss.MusicBattle_BODY &&
      (!boss.MusicBattle_INTRO ||
        val(A.dm_music_inst.get(String(A.mus_rm_inst) + STR_Audio + STR_Asset + STR_Name)) ===
          A.audio_get_name(boss.MusicBattle_INTRO))
    ) {
      aud_play_sound(boss.MusicBattle_BODY, A.PRIORITY_TOP, true, -1, boss.MusicBattle_THEME)
    } else {
      aud_play_sound(get_audio_theme_track(`${STR_Boss}01`), A.PRIORITY_TOP, true, -1, `${STR_Boss}01`)
    }
  }

  // ------------------------------------------------------------------------
  // Play mus_rm_intr OR mus_rm_body. NOTE: when changing rooms there is a short period where music is
  // stopped until g.ChangeRoom_timer reaches 0; `can_play_mus_rm_body` (set in Audio_Room_Start and
  // update_change_room) gates this instead of the timer so intro→body has no gap.
  if (A.can_play_mus_rm_body && A.mus_rm_body !== 0 && !A.audio_is_playing(A.mus_rm_inst)) {
    let _audio_asset: SoundId = 0
    let _play_pos = 0
    const _NAME = A.audio_get_name(A.mus_rm_body)
    const _INTRO_LEN = Number(val(dm.get(_NAME + STR_Intro + STR_Length)))
    if (_INTRO_LEN > 0) {
      if (!val(dm.get(A.rm_music_theme + dk_Intro_CanPlay))) _play_pos = _INTRO_LEN + 0.001
      dm.set(A.rm_music_theme + dk_Intro_CanPlay, false)
      _audio_asset = A.mus_rm_body
    } else if (A.mus_rm_intr !== 0 && val(dm.get(A.rm_music_theme + dk_Intro_CanPlay))) {
      dm.set(A.rm_music_theme + dk_Intro_CanPlay, false)
      _audio_asset = A.mus_rm_intr
    } else {
      _audio_asset = A.mus_rm_body
    }
    if (_audio_asset) {
      // ==============================================================================
      aud_play_sound(_audio_asset, A.PRIORITY_TOP, _audio_asset === A.mus_rm_body, -1, A.rm_music_theme)
      // ==============================================================================
      if (_play_pos > 0) A.push({ kind: 'position', inst: A.mus_rm_inst, seconds: _play_pos })

      // This is to prevent long tracks from starting over if interrupted by something like a level-up
      if (
        A.mus_rm_body_last_pos > 0 &&
        A.mus_asset_name_interrupted !== 0 &&
        val(dm.get(`${dk_SceneMusicThemeException}02${A.mus_asset_name_interrupted}`))
      ) {
        const _N = A.audio_get_name(A.mus_rm_inst)
        if (val(dm.get(`${dk_SceneMusicThemeException}02${_N}`))) {
          // if it was a track that should continue after an interruption
          if (
            (A.mus_rm_intr &&
              _N === A.audio_get_name(A.mus_rm_intr) &&
              _N === A.mus_asset_name_interrupted) ||
            (A.mus_rm_body && _N === A.audio_get_name(A.mus_rm_body) && _N === A.mus_asset_name_interrupted)
          ) {
            A.mus_asset_name_interrupted = 0
            A.push({ kind: 'position', inst: A.mus_rm_inst, seconds: A.mus_rm_body_last_pos })
            A.push({ kind: 'gain', inst: A.mus_rm_inst, gain: 0, ms: 0 })
            A.push({
              kind: 'gain',
              inst: A.mus_rm_inst,
              gain: Number(val(dm.get(_N + STR_Volume), 0.5)),
              ms: 500,
            })
          }
        }
      }
    }
  }
  if (A.mus_rm_body !== 0 && A.audio_is_playing(A.mus_rm_body)) A.mus_asset_name_interrupted = 0

  // ------------------------------------------------------------------------
  if (A.encounter_sound_inst && !A.audio_is_playing(A.encounter_sound_inst)) A.encounter_sound_inst = 0
}

/** `update_low_hp_sound()` — D4D1, D4ED: the low-HP beep, rate-limited by `mod_LOW_HP_SOUND`. */
export function update_low_hp_sound(): void {
  const g = gd()
  if (g.room_type !== 'A') return
  const A = Audio
  if (A.LowHPSound_HP_AMT <= fd().hp) {
    A.LowHPSound_counter1 = 0
    A.LowHPSound_counter2 = 0
    return
  }
  if (A.LowHPSound_counter1 >= A.LowHPSound_PLAY_LIMIT1) A.LowHPSound_counter2++
  if (!gmBool(g.game_end_state as number)) {
    if (
      !gmBool(g.mod_LOW_HP_SOUND as number) ||
      A.LowHPSound_counter1 < A.LowHPSound_PLAY_LIMIT1 ||
      !(A.LowHPSound_counter2 & 0x7f)
    ) {
      const t = get_audio_theme_track(dk_LowHPBeep)
      if (!A.audio_is_playing(t)) {
        aud_play_sound(t)
        A.LowHPSound_counter1++
      }
    }
  }
}

/** Hooks other ports call instead of touching Audio fields directly. */
export const audioHooks = {
  setCanPlayMusRmBody(v: boolean): void {
    Audio.can_play_mus_rm_body = v
  },
  setCanPlayBossMusic(v: boolean): void {
    Audio.can_play_boss_music = v
  },
}
