/** Ported from `AdditionalBGGraphics_init.gml`, `_draw.gml`, `_end.gml` — extra background sprites at listed positions. */
import {
  DEPTH_BG1,
  DEPTH_BG2,
  DEPTH_BG3,
  DEPTH_BG4,
  DEPTH_BG5,
  DEPTH_BG6,
  DEPTH_BG7,
  DEPTH_BG8,
  PI_PERMUTATIONS,
  STR_Complete,
  STR_Dark,
  STR_Data,
  STR_Quest,
  STR_Ruto,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { gmBool } from '../../nes/math8'
import { DsGrid } from '../../runtime/ds'
import { f, G, g, p } from '../../runtime/world'
import { GO_depth_init } from '../game_object/go/sprite'
import { str_hex, val } from '../other'
import { rm_pal_qual_lit } from '../palette/roomStart'
import { add_pi_permut, pal_swap_reset, pal_swap_set } from '../palette/scenePalette'
import { draw_sprite_ } from '../rooms/draw'
import { Jackolantern1_init } from './ambient'
import { gmSpriteName } from './gmIndex.generated'
import type { NiaoObject } from './NiaoObject'
import { NIAO_create2 } from './niao'

/** Cache values for sprites are GM sprite indices; accept names too. */
function spriteRef(v: unknown): string {
  if (typeof v === 'number') return gmSpriteName(v) ?? 'spr_0'
  return String(v)
}

/** `AdditionalBGGraphics_init()` */
export function AdditionalBGGraphics_init(self: NiaoObject): void {
  self.scr_draw = AdditionalBGGraphics_draw as never
  self.scr_inst_end = AdditionalBGGraphics_end as never
  self.can_draw_self = true
  self.sprite = 'spr_0'
  self.depth = DEPTH_BG1 + 1
  let _xy_data: string | undefined
  // sprite, palidx, depth, locations
  if (self.dk_spawn !== undefined) {
    const d = (n: string) => g.dm_rm.get(self.dk_spawn + STR_Data + n)
    if (d('01') !== undefined) self.sprite = spriteRef(d('01'))
    if (d('02') !== undefined) self.palidx_permut = d('02') as number
    if (d('03') !== undefined) self.depth = d('03') as number
    if (d('04') !== undefined) _xy_data = String(d('04'))
  }
  if (
    [DEPTH_BG1, DEPTH_BG2, DEPTH_BG3, DEPTH_BG4, DEPTH_BG5, DEPTH_BG6, DEPTH_BG7, DEPTH_BG8].includes(
      self.depth,
    )
  )
    self.depth += 1
  GO_depth_init(self, self.depth)
  self.palidx_permut = Math.min(Math.max(self.palidx_permut, 0), PI_PERMUTATIONS - 1)
  self.palidx_LIT = self.palidx_def + p.PI_LIT1
  self.palidx_DARK = self.palidx_def + p.PI_DRK1
  if (gmBool(self.palidx_permut)) {
    let _order: string = p.PAL_BASE_COLOR_ORDER
    switch (self.palidx_permut) {
      case 1:
        _order = 'WBRGYKMC'
        break
      case 2:
        _order = 'RWBGMYKC'
        break
      case 3:
        _order = 'RBWGMKYC'
        break
      case 4:
        _order = 'BWRGKYMC'
        break
      case 5:
        _order = 'BRWGKMYC'
        break
    }
    self.palidx_LIT = add_pi_permut(self.palidx_LIT, _order, 'AdditionalBGGraphics')
    self.palidx_DARK = val(G.dm_pi.get(`${hexStr(self.palidx_LIT) + STR_Dark}1`), self.palidx_LIT) as number
  }
  //                                       x      y
  if (_xy_data === undefined) _xy_data = '00000000'
  let _len = _xy_data.length
  if (_len & 0x7) _xy_data = _xy_data.substr(0, _len - (_len & 0x7))
  _len = _xy_data.length
  const _count = _len >> 3
  const dg = new DsGrid<number>(_count, 2, 0)
  for (let _i = 0; _i < _count; _i++) {
    const _data = _xy_data.substr(_i << 3, 8)
    dg.set(_i, 0, str_hex(_data.substr(0, 4)))
    dg.set(_i, 1, str_hex(_data.substr(4, 4)))
  }
  self.dg_xy = dg
  self.Sprite_COUNT = dg.width
  if (G.Halloween1_enabled && self.sprite === g.SPR_ITEM_TROPHY) {
    self.can_draw_self = false
    self.state = 0
    const dl = g.dl_niao
    for (let _i = dl.size - 1; _i >= 0; _i--) {
      const cur = dl.get(_i)
      if (cur !== undefined && cur === self) {
        dl.set(_i, null)
        break
      }
    }
    NIAO_create2((dg.get(0, 0) as number) - 8, (dg.get(0, 1) as number) - 8, 1, Jackolantern1_init)
    self.destroy()
  }
}

/** `AdditionalBGGraphics_draw()` */
export function AdditionalBGGraphics_draw(self: NiaoObject): void {
  if (!self.can_draw_self) return
  if (!gmBool(self.state)) return
  if (self.sprite === g.SPR_ITEM_TROPHY && !gmBool(val(f.dm_quests.get(STR_Ruto + STR_Quest + STR_Complete))))
    return
  if (rm_pal_qual_lit()) self.palidx_base = self.palidx_LIT
  else self.palidx_base = self.palidx_DARK
  self.palidx = self.palidx_base
  pal_swap_set(self.palidx)
  const dg = self.dg_xy as DsGrid<number>
  for (let _i = 0; _i < self.Sprite_COUNT; _i++)
    draw_sprite_(self.sprite as string, 0, dg.get(_i, 0) as number, dg.get(_i, 1) as number)
  pal_swap_reset()
}

/** `AdditionalBGGraphics_end()` */
export function AdditionalBGGraphics_end(self: NiaoObject): void {
  self.dg_xy = undefined
}
