/**
 * Palette-string helpers: `build_pal`, `get_pal_pos`, `get_pal_col_pos`, `get_pal_color`.
 * A "palette" is `PAL_CHAR_PER_PAL` (48) hex chars: one `color_str` per letter of `WRBGYMKC`; a scene
 * palette string is many palettes concatenated and addressed by palette index (pi). Positions are
 * 1-based like GML `string_copy`.
 */
import {
  C_BLK1,
  C_BLU0,
  C_GRN0,
  C_RED0,
  C_WHT0,
  COLORS_PER_PALETTE,
  color_str,
  PAL_BASE_COLOR_ORDER,
  PAL_CHAR_PER_COLOR,
  PAL_CHAR_PER_PAL,
  str_hex,
} from './colors'

/**
 * `build_pal(WHT, *RED, *BLU, *GRN, *YLW, *MGN, *BLK, *CYN)` — colours may be packed numbers or 6-char
 * strings; `-1` = use the base colour, `-2` = "YMKC" mirror "WRBG" (Y←W, M←R, K←B, C←G), as in the GML.
 */
export function build_pal(...args: (number | string)[]): string {
  const defaults = [C_WHT0, C_RED0, C_BLU0, C_GRN0, 0x00ffff, 0xff00ff, 0x000000, 0xffff00] as const
  const c: (number | string)[] = [...defaults]
  for (let i = 0; i < 8 && i < args.length; i++) {
    const a = args[i]
    if (a !== undefined && a !== -1) c[i] = a
  }
  let out = ''
  for (let i = 0; i < COLORS_PER_PALETTE; i++) {
    let color = c[i] as number | string
    if (color === -2) {
      switch (PAL_BASE_COLOR_ORDER[i]) {
        case 'W':
          color = C_WHT0
          break
        case 'R':
          color = C_RED0
          break
        case 'B':
          color = C_BLU0
          break
        case 'G':
          color = C_GRN0
          break
        case 'Y':
          color = c[0] as number | string
          break
        case 'M':
          color = c[1] as number | string
          break
        case 'K':
          color = c[2] as number | string
          break
        default:
          color = c[3] as number | string
          break
      }
      if (color === -2) color = C_BLK1
    }
    out += color_str(color)
  }
  return out
}

/** `get_pal_pos(pi)` — 1-based char position where palette `pi` starts. */
export function get_pal_pos(pi: number): number {
  return pi * PAL_CHAR_PER_PAL + 1
}

/** `get_pal_col_pos(pi, colorChar)` — 1-based char position of colour `colorChar` in palette `pi`. */
export function get_pal_col_pos(pi: number, colorChar: string): number {
  const pos = (PAL_BASE_COLOR_ORDER.indexOf(colorChar[0] ?? '') - 1 + 1) * PAL_CHAR_PER_COLOR
  return get_pal_pos(pi) + pos
}

/** `get_pal_color(paletteData, pi, colorChar)` → packed colour number. */
export function get_pal_color(palette: string, pi: number, colorChar: string): number {
  const idx = Math.max(0, PAL_BASE_COLOR_ORDER.indexOf(colorChar[0] ?? ''))
  const pos = get_pal_pos(pi) + idx * PAL_CHAR_PER_COLOR
  return str_hex(palette.substr(pos - 1, PAL_CHAR_PER_COLOR))
}

/** GML `string_copy(str, pos(1-based), count)` */
export function string_copy(str: string, pos: number, count: number): string {
  return str.substr(Math.max(0, pos - 1), Math.max(0, count))
}

/** Split a palette string into palettes × 8 packed colours. */
export function palettesOf(str: string): number[][] {
  const out: number[][] = []
  const count = Math.floor(str.length / PAL_CHAR_PER_PAL)
  for (let i = 0; i < count; i++) {
    const row: number[] = []
    for (let j = 0; j < COLORS_PER_PALETTE; j++) {
      row.push(str_hex(str.substr((i * COLORS_PER_PALETTE + j) * PAL_CHAR_PER_COLOR, PAL_CHAR_PER_COLOR)))
    }
    out.push(row)
  }
  return out
}
