import { gmBool } from '../../../../../../nes/math8'
import { G, world } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { ocsHV2 } from '../../../../../collision/ocs'
import { collide_pc_body, enemy_collide_pc_body } from '../../../../../collision/pc'
import { update_trig_hb_1 } from '../../../../../collision/solid'
import { point_distance } from '../../../../../Game/gm'
import { round8, sign_ } from '../../../../../math/index'
import { get_pal_color } from '../../../../../palette/palString'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { draw_rect_, draw_sprite_, drawState } from '../../../../../rooms/draw'
import { cam_xl_min, cam_xr_max, cam_yb_max, cam_yt_min } from '../../../../../view/camera'
import { Enemy, type GameObject } from '../../../../classes'
import { GO_draw_sprite } from '../../../../go/draw'
import { set_xlyt, updateX, updateY } from '../../../../go/movement'
