/** Pure rectangle / circle tests. GML semantics kept exactly (note the asymmetric `hINh`). */
import { viewH, viewW, viewXL, viewYT } from './env'

/** `hINh(ay, ah, by, bh)` — heights overlap. NB: `ay+ah >= by` (inclusive), unlike `wINw`. */
export function hINh(ay: number, ah: number, by: number, bh: number): boolean {
  return ay < by + bh && ay + ah >= by
}

/** `hINhAll(ay, ah, by, bh)` — all of a inside b. */
export function hINhAll(ay: number, ah: number, by: number, bh: number): boolean {
  if (ay < by) return false
  if (ay + ah > by + bh) return false
  return true
}

/** `wINw(ax, aw, bx, bw)` — widths overlap (strict). */
export function wINw(ax: number, aw: number, bx: number, bw: number): boolean {
  return ax < bx + bw && ax + aw > bx
}

/** `wINwAll(ax, aw, bx, bw)` */
export function wINwAll(ax: number, aw: number, bx: number, bw: number): boolean {
  return ax >= bx && ax + aw <= bx + bw
}

/** `rectInRect(ax, ay, aw, ah, bx, by, bw, bh)` — strict overlap on both axes. */
export function rectInRect(
  ax: number,
  ay: number,
  aw: number,
  ah: number,
  bx: number,
  by: number,
  bw: number,
  bh: number,
): boolean {
  return ax < bx + bw && ay < by + bh && ax + aw > bx && ay + ah > by
}

/** `rectInRectAll(...)` — all of rect a inside rect b. */
export function rectInRectAll(
  ax: number,
  ay: number,
  aw: number,
  ah: number,
  bx: number,
  by: number,
  bw: number,
  bh: number,
): boolean {
  return ax >= bx && ay >= by && ax + aw <= bx + bw && ay + ah <= by + bh
}

/** `rectInCirc(cX, cY, radius, rX, rY, rW, rH)` — circle vs rectangle. */
export function rectInCirc(
  cx: number,
  cy: number,
  rad: number,
  rxl: number,
  ryt: number,
  rw: number,
  rh: number,
): boolean {
  // rc: Row Clm of the 3x3 zone the circle centre is in; $11 is the rectangle
  let rc = 0x00
  if (cx >= rxl) rc += 0x01
  if (cx >= rxl + rw) rc += 0x01
  if (cy >= ryt) rc += 0x10
  if (cy >= ryt + rh) rc += 0x10
  if (rc === 0x11) return true
  if (rc & 0x11) {
    // Circle becomes a square of its diameter; check both rectangles overlap.
    return rectInRect(cx - rad, cy - rad, rad << 1, rad << 1, rxl, ryt, rw, rh)
  }
  // Point will be one of the rectangle's 4 corners
  let x = rxl
  let y = ryt
  if (rc & 0x02) x += rw
  if (rc & 0x20) y += rh
  return Math.hypot(cx - x, cy - y) < rad
}

/** `circInCirc(c1x, c1y, r1, c2x, c2y, r2)` */
export function circInCirc(x1: number, y1: number, r1: number, x2: number, y2: number, r2: number): boolean {
  return Math.hypot(x1 - x2, y1 - y2) < r1 + r2
}

/** `rectInView(x, y, w, h)` */
export function rectInView(x: number, y: number, w: number, h: number): boolean {
  return rectInRect(x, y, w, h, viewXL(), viewYT(), viewW(), viewH())
}

/** `rectInViewAll(x, y, w, h)` */
export function rectInViewAll(x: number, y: number, w: number, h: number): boolean {
  return rectInRectAll(x, y, w, h, viewXL(), viewYT(), viewW(), viewH())
}

/** `borderInRect(thickness, ax, ay, aw, ah, bx, by, bw, bh)` — any edge band of a fully inside b. */
export function borderInRect(
  t0: number,
  ax: number,
  ay: number,
  aw: number,
  ah: number,
  bx: number,
  by: number,
  bw: number,
  bh: number,
): boolean {
  const t = Math.max(1, Math.min(t0, Math.min(aw, ah, bw, bh)))
  return (
    wINwAll(ax, t, bx, bw) ||
    hINhAll(ay, t, by, bh) ||
    wINwAll(ax + aw - t, t, bx, bw) ||
    hINhAll(ay + ah - t, t, by, bh)
  )
}

/** `pointInRect(px, py, rx, ry, rw, rh)` — the point as a 1×1 rect (edge-exclusive on right/bottom). */
export function pointInRect(px: number, py: number, rx: number, ry: number, rw: number, rh: number): boolean {
  return rectInRect(px, py, 1, 1, rx, ry, rw, rh)
}

/** `point_in_rect(px, py, rx, ry, rw, rh)` — inclusive on all edges. */
export function point_in_rect(
  px: number,
  py: number,
  rx: number,
  ry: number,
  rw: number,
  rh: number,
): boolean {
  return px >= rx && px <= rx + rw && py >= ry && py <= ry + rh
}

/** `is_in_grid(CLM, ROW, CLMS, ROWS)` */
export function is_in_grid(clm: number, row: number, clms: number, rows: number): boolean {
  return clm >= 0 && row >= 0 && clm < clms && row < rows
}
