/**
 * Registers the boss classes (`objectClasses`) and every boss script (`scriptRegistry`) under their ZALiA
 * names so `GameObjectData_Create`'s `data_go_scr(...)` rows resolve. `HelmetheadHead01` (the popped helmet)
 * is an `Enemy` driven by the Fenser scripts (enemy port) — only its class is declared here.
 */
import { Enemy, type GameObject, ProjectileHostile } from '../../../classes'
import { registerObject, registerScripts } from '../../../registry'
import { gobDrawHooks } from '../../GameObjectB'
import * as bossBase from './BossObject'
import * as barba from './barba'
import * as carock from './carock'
import * as ganon from './ganon'
import * as ganon1 from './ganon1'
import * as ganon2 from './ganon2'
import * as ganon3 from './ganon3'
import * as gooma from './gooma'
import * as helmethead from './helmethead'
import * as horsehead from './horsehead'
import * as rebonackA from './rebonackA'
import * as rebonackB from './rebonackB'
import * as shadowBoss from './shadowBoss'
import * as thunderbird from './thunderbird'

/** `HelmetheadHead01` (objects/HelmetheadHead01.object.gmx, parent Enemy; scripts `Fenser_*`). */
export class HelmetheadHead01 extends Enemy {
  override readonly objectName = 'HelmetheadHead01' as const
}

/** `BossExplosion` (parent ProjectileHostile; behaviour lives with the hostile-projectile port). */
export class BossExplosion extends ProjectileHostile {
  override readonly objectName = 'BossExplosion' as const
}

function scriptsOf(mod: Record<string, unknown>): Record<string, never> {
  const out: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(mod))
    if (typeof v === 'function' && /^[A-Z][A-Za-z0-9]*_/.test(k)) out[k] = v
  return out as Record<string, never>
}

export function registerBosses(): void {
  // `Boss_Draw()`: `Boss_HPBar_draw(); event_inherited();`
  gobDrawHooks.Boss_HPBar_draw = bossBase.Boss_HPBar_draw as unknown as (self: GameObject) => void
  registerObject('Horsehead01', horsehead.Horsehead01)
  registerObject('Helmethead01', helmethead.Helmethead01)
  registerObject('HelmetheadHead01', HelmetheadHead01)
  registerObject('Rebonack01A', rebonackA.Rebonack01A)
  registerObject('Rebonack01B', rebonackB.Rebonack01B)
  registerObject('Carock01', carock.Carock01)
  registerObject('Gooma01', gooma.Gooma01)
  registerObject('Barba01', barba.Barba01)
  registerObject('Thunderbird01', thunderbird.Thunderbird01)
  registerObject('ShadowLonk01', shadowBoss.ShadowLonk01)
  registerObject('Ganon1', ganon1.Ganon1)
  registerObject('Ganon2', ganon2.Ganon2)
  registerObject('Ganon3', ganon3.Ganon3)
  registerObject('BossExplosion', BossExplosion)
  for (const mod of [
    bossBase,
    horsehead,
    helmethead,
    rebonackA,
    rebonackB,
    carock,
    gooma,
    barba,
    thunderbird,
    shadowBoss,
    ganon,
    ganon1,
    ganon2,
    ganon3,
  ]) {
    registerScripts(scriptsOf(mod as Record<string, unknown>))
  }
}

registerBosses()
