/** Blooby (Darunia pogo minigame bouncer) — ZALiA `gob2/blooby`. */
import { CS_SW1, dk_ElevatorMove, STR_Data, STR_Stab } from '@z2/data'
import { hexStr } from '../../../../nes/hexStr'
import { abs8b, gmBool, isVal, gmRound as round } from '../../../../nes/math8'
import { G, g, p } from '../../../../runtime/world'
import { GO_update_cs } from '../../../collision/cs'
import { PC_update_sword_hb, update_body_hb_1a } from '../../../collision/hitbox'
import { collide_pc_sword, collideRect } from '../../../collision/pc'
import { sign_ } from '../../../math/index'
import { val } from '../../../other/index'
import { color_str, strReplaceAt } from '../../../palette/colors'
import { get_pal_col_pos } from '../../../palette/palString'
import { change_pal } from '../../../palette/scenePalette'
import { Audio } from '../../../sound/Audio'
import { aud_play_sound } from '../../../sound/play'
import { get_audio_theme_track } from '../../../sound/theme'
import { cam_xl_min, cam_xr_max, cam_yb_max, cam_yt_min } from '../../../view/camera'
import { dir_to_pc_, GO_update_cam_vars } from '../../go/misc'
import { set_xy, updateX, updateY } from '../../go/movement'
import { GO_init_palidx } from '../../go/palette'
import { pushback_pc } from '../../go/pushback'
import { GO_set_sprite, GO_sprite_init } from '../../go/sprite'
import { pc_is_cucco } from '../../goa/form'
import { pc } from '../../goa/pc'
import { GameObjectB_init, update_EF11 } from '../GameObjectB'
import type { Blooby } from './classes'

/** `Blooby_init1()` — ver 2: Has a collision cooldown */
export function Blooby_init1(self: Blooby): void {
  GameObjectB_init(self)
  self.Blooby_SPR_A1 = 'spr_Blooby_1a_1'
  self.Blooby_SPR_A2 = 'spr_Blooby_1b_1'
  self.Blooby_SPR_B1 = 'spr_Blooby_2a_2'
  GO_sprite_init(self, self.Blooby_SPR_A1)
  self.sub_state = self.sub_state_IDLE
  self.XC_MIN = cam_xl_min() + self.ww_
  self.XC_MAX = cam_xr_max() - self.ww_
  self.YC_MIN = cam_yt_min() + self.hh_
  self.YC_MAX = cam_yb_max() - self.hh_
  self.hspd_PACE = 0x0c
  self.hspd_pace_dist = 0x04 << 3
  self.hspd_PUSHBACK = 0x30
  self.hspd = 0
  self.BounceVelocity_BASE = 1.4 // per vspd of pc
  self.BounceVelocity_MIN = Math.min(1.3, self.BounceVelocity_BASE)
  self.BounceVelocity = -self.BounceVelocity_BASE & 0xff
  self.ReactionAnim_TIMING = 0x08
  self.ReactionAnim_DUR1 = ((self.ReactionAnim_TIMING * 3) << 1) - 1
  self.ReactionAnim_timer = 0
}

/** `Blooby_init2()` */
export function Blooby_init2(self: Blooby): void {
  self.DRAW_YOFF = 0
  self.hspd = 0x00
  self.hspd_dir = 1
  const dk = self.dk_spawn
  if (dk !== undefined) {
    self.hspd_dir = sign_(val(g.dm_spawn.get(dk + STR_Data + hexStr(1)), self.hspd_dir) as number)
    self.hspd = val(g.dm_spawn.get(dk + STR_Data + hexStr(2)), self.hspd) as number
  }
  self.hspd = Math.min(0x20, Math.max(0, self.hspd))
  self.hspd = (self.hspd * self.hspd_dir) & 0xff
  self.vspd = 0x00
  self.vspd_dir = -1
  if (dk !== undefined) {
    self.vspd_dir = sign_(val(g.dm_spawn.get(dk + STR_Data + hexStr(3)), self.vspd_dir) as number)
    self.vspd = val(g.dm_spawn.get(dk + STR_Data + hexStr(4)), self.vspd) as number
  }
  self.vspd = Math.min(0x20, Math.max(0, self.vspd))
  self.vspd = (self.vspd * self.vspd_dir) & 0xff
  if (dk !== undefined) {
    const d5 = g.dm_spawn.get(dk + STR_Data + hexStr(5))
    if (d5 !== undefined) self.XC_MIN = d5 as number
    const d6 = g.dm_spawn.get(dk + STR_Data + hexStr(6))
    if (d6 !== undefined) self.XC_MAX = d6 as number
    const d7 = g.dm_spawn.get(dk + STR_Data + hexStr(7))
    if (d7 !== undefined) self.YC_MIN = d7 as number
    const d8 = g.dm_spawn.get(dk + STR_Data + hexStr(8))
    if (d8 !== undefined) self.YC_MAX = d8 as number
  }
  self.facing_dir = self.hspd_dir
  set_xy(
    self,
    Math.min(self.XC_MAX, Math.max(self.XC_MIN, self.x)),
    Math.min(self.YC_MAX, Math.max(self.YC_MIN, self.y)),
  )
  switch (self.ver) {
    case 1:
      GO_init_palidx(self, G.PI_MOB_PUR)
      break
    case 2:
      GO_init_palidx(self, G.PI_MOB_RED)
      break
  }
  for (const [col, color] of [
    ['W', p.C_WHT1],
    ['Y', p.C_WHT1],
    ['B', p.C_BLK1],
    ['K', p.C_BLK1],
  ] as const) {
    change_pal(
      strReplaceAt(p.pal_rm_new, get_pal_col_pos(self.palidx, col), p.PAL_CHAR_PER_COLOR, color_str(color)),
    )
  }
}

/** `Blooby_update()` */
export function Blooby_update(self: Blooby): void {
  const P = pc()
  if (self.ReactionAnim_timer) self.ReactionAnim_timer--
  updateX(self)
  updateY(self)
  GO_update_cs(self)
  if (self.hspd) {
    if (self.csRgt1X >= self.XC_MAX + self.ww_) self.cs |= 0x1
    if (self.csLft1X < self.XC_MIN - self.ww_) self.cs |= 0x2
  }
  if (self.vspd) {
    if (self.csBtm1Y >= self.YC_MAX + self.ww_) self.cs |= 0x4
    if (self.csTop1Y < self.YC_MIN - self.ww_) self.cs |= 0x8
  }
  if (self.cs & 0x3 && self.hspd && self.hspd_dir === sign_(self.cs & 0x1)) {
    self.hspd_dir = -self.hspd_dir
    self.hspd = (abs8b(self.hspd) * self.hspd_dir) & 0xff
    self.facing_dir = self.hspd_dir
  }
  if (self.cs & 0xc && self.vspd && self.vspd_dir === sign_(self.cs & 0x4)) {
    self.vspd_dir = -self.vspd_dir
    self.vspd = (abs8b(self.vspd) * self.vspd_dir) & 0xff
  }
  const _PC_VSPD = P.vspd
  if (!self.hspd && !(g.counter1 & 0x3f)) self.facing_dir = dir_to_pc_(self)
  GO_update_cam_vars(self)
  update_EF11(self)
  update_body_hb_1a(self)
  PC_update_sword_hb()
  if (
    P.SwordHB_collidable &&
    collide_pc_sword(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h, self.BodyHB_r)
  ) {
    self.cs |= CS_SW1
  }
  switch (self.sub_state) {
    case self.sub_state_IDLE: {
      if (self.timer) break
      if (self.cs & CS_SW1) {
        let _reacted = false
        if (P.behavior === P.behavior_STAB_DOWN) {
          if (_PC_VSPD && _PC_VSPD < 0x80) {
            const _HB_W = 8
            if (
              self.ver !== 2 ||
              P.SwordHB_w < _HB_W ||
              collideRect(P.SwordHB_x + P.SwordHB_w_ - (_HB_W >> 1), P.SwordHB_y, _HB_W, P.SwordHB_h, [self])
            ) {
              // more specific/narrower sword hb
              if (self.ver === 2) {
                P.vspd = 0xfa
              } else {
                self.BounceVelocity = round(abs8b(_PC_VSPD) * self.BounceVelocity_BASE)
                if (pc_is_cucco()) self.BounceVelocity += 0x3
                self.BounceVelocity = -Math.max(self.BounceVelocity_MIN, self.BounceVelocity)
                self.BounceVelocity &= 0xff
                P.vspd = self.BounceVelocity
              }
              _reacted = true
            }
          }
        } else if (P.behavior === P.behavior_STAB_UP) {
          // (no reaction in ZALiA)
        } else if (isVal(P.behavior, P.behavior_STAB_STAND, P.behavior_STAB_CROUCH)) {
          g.control1_timer = P.Pushback_DURATION // PC atk will NOT affect PC.hspd
          pushback_pc(self.x, self.hspd_PUSHBACK)
          _reacted = true
        }
        if (_reacted) {
          self.ReactionAnim_timer = self.ReactionAnim_DUR1
          aud_play_sound(get_audio_theme_track(dk_ElevatorMove))
          aud_play_sound(get_audio_theme_track(STR_Stab))
          aud_play_sound(Audio.sound('SND_STEP_1A'))
          if (self.ver === 2) {
            self.timer = 0xc
            self.sub_state = self.sub_state_COOLDOWN0
          }
        }
      }
      break
    }
    case self.sub_state_COOLDOWN0: // Transition to cooldown
      if (self.timer) break
      self.timer = 0x80
      self.sub_state = self.sub_state_COOLDOWN1
      break
    case self.sub_state_COOLDOWN1: // Cooldown period
      if (self.timer) break
      self.timer = 0x10
      self.sub_state = self.sub_state_COOLDOWN2
      break
    case self.sub_state_COOLDOWN2: // Transition to collidable
      if (self.timer) break
      self.timer = 0x0
      self.sub_state = self.sub_state_IDLE
      break
  }
  self.cs &= ~CS_SW1
  self.BounceVelocity = 0
}

/** `Blooby_udp()` */
export function Blooby_udp(self: Blooby): void {
  self.can_draw_self = true
  let _spr: string
  if (self.ReactionAnim_timer & self.ReactionAnim_TIMING)
    _spr = self.Blooby_SPR_B1 // puffed up
  else if (g.counter1 & 0x8) _spr = self.Blooby_SPR_A1
  else _spr = self.Blooby_SPR_A2
  GO_set_sprite(self, _spr)
  switch (self.sub_state) {
    case self.sub_state_IDLE:
      self.palidx_base = self.palidx_def
      break
    case self.sub_state_COOLDOWN0: // Deflating
    case self.sub_state_COOLDOWN2: // Inflating
      self.can_draw_self = gmBool(g.counter1 & 0x1)
      self.palidx_base = g.counter1 & 0x2 ? self.palidx_def : G.PI_GUI2
      break
    case self.sub_state_COOLDOWN1: // Deflated. Not collidable
      self.can_draw_self = gmBool(g.counter1 & 0x1)
      self.palidx_base = G.PI_GUI2
      break
  }
}
