export class LevelUpMenu extends Menu {
  override readonly objectName = 'LevelUpMenu'
  /** `<persistent>-1</persistent>` in ZALiA's object definition — survives a room change. */
  override readonly persistent = true
  ANIM_FRAMES_DEF: any = undefined
  ARROW_SPR: any = undefined
  CLMS: any = undefined
  CLM_LVL_ICON: any = undefined
  CLM_LVL_TEXT: any = undefined
  CLM_XP: any = undefined
  IDX_CAN_LVL: any = undefined
  IDX_ICON_SPR: any = undefined
  IDX_LVLS_ROW: any = undefined
  IDX_TEXT: any = undefined
  IDX_TEXT_CLM: any = undefined
  IDX_TEXT_ROW: any = undefined
  LVL_SECTIONS_ROW: any = undefined
  LVL_SECTION_ROWS: any = undefined
  OPTION_CANCEL: any = undefined
  PI_DEF: any = undefined
  ROWS: any = undefined
  WILL_GO_UP_IDX: any = undefined
  anim_frame: any = undefined
  canDrawStatIcon: any = undefined
  cnt_draw_rows: any = undefined
  dg_DATA: any = undefined
  dl_tsrc_data: any = undefined
  dl_xp_next_stat: any = undefined
  srf_FRAME: any = undefined
  constructor() {
    super()
    LevelUpMenu_Create(this)
  }
  gameEnd(): void {
    LevelUpMenu_Game_End(this)
  }
  draw(): void {
    LevelUpMenu_Draw(this)
  }
}

/** GML: LevelUpMenu_Create() */
export function LevelUpMenu_Create(self: LevelUpMenu) {
  let _START_TIME: any,
    _i: any,
    _idx: any,
    _MIN: any,
    _MAX: any,
    _TEXT_LVL_ATK: any,
    _TEXT_LVL_MAG: any,
    _TEXT_LVL_LIF: any,
    _TEXT_NEXT: any,
    _TEXT_CANCEL: any,
    _TEXT_WILL: any,
    _TEXT_GO_UP: any,
    _count: any,
    _dm_text: any,
    _ROW_TEXT_NEXT: any,
    _E: any,
    _H: any,
    _V: any,
    _C: any,
    _POS: any,
    _TSRC_DATA1: any,
    _TSRC_DATA2: any,
    _TSRC_DATA3: any,
    _TSRC_DATA4: any

  if (gmb(DEV)) {
    _START_TIME = current_time
  }

  _MIN = min(STAT_ATK, STAT_MAG, STAT_LIF) // 0,1,2
  _MAX = max(STAT_ATK, STAT_MAG, STAT_LIF) // 0,1,2
  // ------------------------------------------------------------------------
  // ------------------------------------------------------------------------
  _TEXT_LVL_ATK = 'ATTACK'
  _TEXT_LVL_MAG = 'MAGIC'
  _TEXT_LVL_LIF = 'LIFE'
  _TEXT_NEXT = 'NEXT'
  _TEXT_CANCEL = 'CANCEL'
  _TEXT_WILL = 'WILL'
  _TEXT_GO_UP = 'GO UP'
  g.LEVEL_MENU = self
  _idx = 0
  self.IDX_TEXT_CLM = _idx++
  self.IDX_TEXT_ROW = _idx++
  self.IDX_TEXT = _idx++
  self.IDX_LVLS_ROW = _idx++
  self.IDX_ICON_SPR = _idx++
  self.IDX_CAN_LVL = _idx++
  _count = _MAX + 1 // 3  levels: atk, mag, lif
  _count += 5 // 4  text: NEXT, UP, CANCEL, WILL, GO UP
  self.dg_DATA = ds_grid_create(_count, _idx + 1)
  // ------------------------------------------------------------------------
  // ------------------------------------------------------------------------
  self.LVL_SECTIONS_ROW = 4
  self.LVL_SECTION_ROWS = 5
  // 8x8 tiles
  self.CLMS = g.GUI_WIN_CLMS1 // 8x8
  self.ROWS = 2 // Border rows
  self.ROWS += 3 // NEXT UP & CANCEL section
  self.ROWS += self.LVL_SECTION_ROWS * 3 // LEVEL UP SECTIONS
  // ROWS = $14; // 8x8. $14 == 20
  self.CLM_LVL_TEXT =
    self.CLMS -
    1 -
    max(string_length(_TEXT_LVL_ATK), string_length(_TEXT_LVL_MAG), string_length(_TEXT_LVL_LIF))
  self.CLM_LVL_ICON = self.CLMS - 1 - STAT_LEVEL_MAX
  self.CLM_XP = 1 // align left in case xp goes to a 5th digit
  //CLM_XP = 4; // OG aligns it right starting at this clm
  // ------------------------------------------------------------------------
  // ------------------------------------------------------------------------
  _dm_text = ds_map_create()
  _dm_text.set(hex_str(STAT_ATK), _TEXT_LVL_ATK)
  _dm_text.set(hex_str(STAT_MAG), _TEXT_LVL_MAG)
  _dm_text.set(hex_str(STAT_LIF), _TEXT_LVL_LIF)
  for (_i = _MIN; _i <= _MAX; _i++) {
    self.dg_DATA.set(_i, self.IDX_TEXT, _dm_text.get(hex_str(_i)))
    self.dg_DATA.set(_i, self.IDX_LVLS_ROW, self.LVL_SECTIONS_ROW + self.LVL_SECTION_ROWS * (_i - _MIN))
    self.dg_DATA.set(_i, self.IDX_TEXT_CLM, self.CLM_LVL_TEXT)
    self.dg_DATA.set(_i, self.IDX_TEXT_ROW, self.dg_DATA.get(_i, self.IDX_LVLS_ROW) + 1)
  }
  ds_map_destroy(_dm_text)
  _dm_text = undefined
  self.dg_DATA.set(STAT_ATK, self.IDX_ICON_SPR, G.SPR_ICON_ATK)
  self.dg_DATA.set(STAT_MAG, self.IDX_ICON_SPR, G.SPR_ICON_MAG)
  self.dg_DATA.set(STAT_LIF, self.IDX_ICON_SPR, G.SPR_ICON_LIF)
  // ------------------------------------------------------------------------
  _ROW_TEXT_NEXT = 0x01
  _idx = _MAX + 1
  // "CANCEL"
  self.dg_DATA.set(_idx, self.IDX_TEXT, _TEXT_CANCEL)
  self.dg_DATA.set(
    _idx,
    self.IDX_TEXT_CLM,
    self.CLMS - 1 - string_length(self.dg_DATA.get(_idx, self.IDX_TEXT)),
  )
  self.dg_DATA.set(_idx, self.IDX_TEXT_ROW, _ROW_TEXT_NEXT + 1)
  _idx++
  //
  // "NEXT"
  self.dg_DATA.set(_idx, self.IDX_TEXT, _TEXT_NEXT)
  self.dg_DATA.set(_idx, self.IDX_TEXT_CLM, 0x01)
  self.dg_DATA.set(_idx, self.IDX_TEXT_ROW, _ROW_TEXT_NEXT)
  _idx++
  //
  // "UP"
  self.dg_DATA.set(_idx, self.IDX_TEXT, 'UP')
  self.dg_DATA.set(_idx, self.IDX_TEXT_CLM, self.dg_DATA.get(_idx - 1, self.IDX_TEXT_CLM))
  self.dg_DATA.set(_idx, self.IDX_TEXT_ROW, _ROW_TEXT_NEXT + 1)
  _idx++
  //
  self.WILL_GO_UP_IDX = _idx
  // "WILL"
  self.dg_DATA.set(_idx, self.IDX_TEXT, _TEXT_WILL)
  self.dg_DATA.set(_idx, self.IDX_TEXT_CLM, self.CLM_LVL_TEXT)
  self.dg_DATA.set(_idx, self.IDX_TEXT_ROW, self.dg_DATA.get(STAT_ATK, self.IDX_TEXT_ROW) + 1)
  _idx++
  //
  // "GO UP"
  self.dg_DATA.set(_idx, self.IDX_TEXT, _TEXT_GO_UP)
  self.dg_DATA.set(_idx, self.IDX_TEXT_CLM, self.dg_DATA.get(_idx - 1, self.IDX_TEXT_CLM))
  self.dg_DATA.set(_idx, self.IDX_TEXT_ROW, self.dg_DATA.get(_idx - 1, self.IDX_TEXT_ROW) + 1)
  _idx++
  //
  self.ARROW_SPR = 'spr_Menu_Selector_arrow_1a'
  self.PI_DEF = G.PI_GUI1
  self.ANIM_FRAMES_DEF = self.ROWS >> 1
  self.anim_frame = 0
  self.cnt_draw_rows = 0
  self.OPTION_CANCEL = 3
  _E = '&' // Empty
  _H = '0' // Bar horizontal
  _V = '1' // Bar vertical
  _C = '2' // Corner square
  _POS = string_length(_TEXT_NEXT) + 2 // ("NEXT" length) + (2 frame pieces)
  //  _TSRC_DATA1 = "2" +   "0000" + "0000" + "0000"   +  "2";    // Hor bar 1
  _TSRC_DATA1 = _C + string_repeat(_H, self.CLMS - 2) + _C // Hor bar 1
  //  _TSRC_DATA2 = "2" +   "0000" + "2000" + "0000"   +  "2";    // Hor bar 2 (Next/Cancel)
  _TSRC_DATA2 = _C + string_repeat(_H, self.CLMS - 2) + _C // Hor bar 2 (Next/Cancel)
  _TSRC_DATA2 = strReplaceAt(_TSRC_DATA2, _POS, 1, _C)
  //
  //  _TSRC_DATA3 = "1" +   "&&&&" + "&&&&" + "&&&&"   +  "1";    // Side 1
  _TSRC_DATA3 = _V + string_repeat(_E, self.CLMS - 2) + _V // Side 1
  //  _TSRC_DATA4 = "1" +   "&&&&" + "1&&&" + "&&&&"   +  "1";    // Side 2 (Next/Cancel)
  _TSRC_DATA4 = _V + string_repeat(_E, self.CLMS - 2) + _V // Side 2 (Next/Cancel)
  _TSRC_DATA4 = strReplaceAt(_TSRC_DATA4, _POS, 1, _V)
  //
  self.dl_tsrc_data = ds_list_create()
  // Side 1                       "1" +   "&&&&" + "&&&&" + "&&&&"   +  "1"
  for (_i = 0; _i < self.ROWS; _i++) {
    ds_list_add(self.dl_tsrc_data, _TSRC_DATA3)
  }
  // Hor bar 2 (Next/Cancel)      "2" +   "0000" + "2000" + "0000"   +  "2"
  self.dl_tsrc_data.set(0, _TSRC_DATA2)
  self.dl_tsrc_data.set(self.LVL_SECTIONS_ROW - 1, _TSRC_DATA2)
  // Side 2 (Next/Cancel)         "1" +   "&&&&" + "1&&&" + "&&&&"   +  "1"
  for (_i = 1; _i < 1 + (self.LVL_SECTIONS_ROW - 2); _i++) {
    self.dl_tsrc_data.set(_i, _TSRC_DATA4)
  }
  // Hor bar 1                    "2" +   "0000" + "0000" + "0000"   +  "2";
  for (_i = 0; _i < 4; _i++) {
    self.dl_tsrc_data.set(self.LVL_SECTIONS_ROW + self.LVL_SECTION_ROWS * _i, _TSRC_DATA1)
  }
  /*
ar_TSRC_DATA[ 0] = _TSRC_DATA2; // Hor bar 2 (Next/Cancel)
ar_TSRC_DATA[ 1] = _TSRC_DATA4; // Side 2 (Next/Cancel)
ar_TSRC_DATA[ 2] = _TSRC_DATA4; // Side 2 (Next/Cancel)
ar_TSRC_DATA[ 3] = _TSRC_DATA2; // Hor bar 2 (Next/Cancel)
                                // 
ar_TSRC_DATA[ 4] = _TSRC_DATA1; // Hor bar 1
ar_TSRC_DATA[ 5] = _TSRC_DATA3; // Side 1
ar_TSRC_DATA[ 6] = _TSRC_DATA3; // Side 1
ar_TSRC_DATA[ 7] = _TSRC_DATA3; // Side 1
                                // 
ar_TSRC_DATA[ 8] = _TSRC_DATA3; // Side 1
ar_TSRC_DATA[ 9] = _TSRC_DATA1; // Hor bar 1
ar_TSRC_DATA[10] = _TSRC_DATA3; // Side 1
ar_TSRC_DATA[11] = _TSRC_DATA3; // Side 1
                                // 
ar_TSRC_DATA[12] = _TSRC_DATA3; // Side 1
ar_TSRC_DATA[13] = _TSRC_DATA3; // Side 1
ar_TSRC_DATA[14] = _TSRC_DATA1; // Hor bar 1
ar_TSRC_DATA[15] = _TSRC_DATA3; // Side 1
                                // 
ar_TSRC_DATA[16] = _TSRC_DATA3; // Side 1
ar_TSRC_DATA[17] = _TSRC_DATA3; // Side 1
ar_TSRC_DATA[18] = _TSRC_DATA3; // Side 1
ar_TSRC_DATA[19] = _TSRC_DATA1; // Hor bar 1
*/
  self.canDrawStatIcon = 1
  self.dl_xp_next_stat = ds_list_create()
  ds_list_add(self.dl_xp_next_stat, 0, 0, 0)
  self.srf_FRAME = 0
  //srf_FRAME = surface_create(CLMS<<3, ROWS<<3);
  if (gmb(DEV)) {
  }
}

