/** GML: LevelUpMenu_Draw() */
export function LevelUpMenu_Draw(self: LevelUpMenu) {
  let _i: any,
    _j: any,
    _x: any,
    _y: any,
    _tsrc: any,
    _ts_x: any,
    _ts_y: any,
    _idx: any,
    _count: any,
    _row: any

  //if(!global.App_frame_count
  //|| +!surface_exists(srf_FRAME) )
  if (+!surface_exists(self.srf_FRAME)) {
    if (+!surface_exists(self.srf_FRAME)) {
      self.srf_FRAME = surface_create(self.CLMS << 3, self.ROWS << 3)
    }
    surface_set_target(self.srf_FRAME)
    draw_clear_alpha(c_black, 0)
    // each row
    for (_i = 0; _i < self.ROWS; _i++) {
      // each clm
      for (_j = 0; _j < self.CLMS; _j++) {
        _tsrc = string_char_at(self.dl_tsrc_data.get(_i), _j + 1)
        if (_tsrc === '0' || _tsrc === '1' || _tsrc === '2') {
          _tsrc = g.dl_MenuFrame_TSRC.get(real(_tsrc))
          _ts_x = ((_tsrc >> 0) & 0x0f) << 3
          _ts_y = ((_tsrc >> 4) & 0x0f) << 3
          _x = _j << 3
          _y = _i << 3
          draw_background_part(g.TS_MENU, _ts_x, _ts_y, 8, 8, _x, _y)
        }
      }
    }
    surface_reset_target()
  }
  if (+!gmb(self.canDrawSections)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (+!gmb(self.cnt_draw_rows)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // -------------------------------------------------------------------------
  // -------------------------------------------------------------------------

  draw_sprite_(
    'spr_1x1_WHT',
    0,
    self.drawX,
    self.drawY,
    -1,
    self.CLMS << 3,
    self.cnt_draw_rows << 3,
    background_colour(),
  )
  // -------------------------------------------------------------------------
  pal_swap_set(self.PI_DEF)
  // -------------------------------------------------------------------------
  // -------------------------------------------------------------------------
  if (surface_exists(self.srf_FRAME)) {
    if (self.cnt_draw_rows < self.ROWS) {
      draw_surface_part(self.srf_FRAME, 0, 0, self.CLMS << 3, self.cnt_draw_rows << 3, self.drawX, self.drawY)
    } else {
      draw_surface(self.srf_FRAME, self.drawX, self.drawY)
    }
  }
  // -------------------------------------------------------------------------
  // ARROW SPRITE
  if (self.cnt_draw_rows > self.dg_DATA.get(g.level_up_idx, self.IDX_TEXT_ROW)) {
    _x = self.drawX + ((self.dg_DATA.get(g.level_up_idx, self.IDX_TEXT_CLM) - 1) << 3)
    _y = self.drawY + (self.dg_DATA.get(g.level_up_idx, self.IDX_TEXT_ROW) << 3)
    draw_sprite_(self.ARROW_SPR, 0, _x, _y)
  }
  // ----------------------------------------------------------------------------
  // ICON SPRITES
  for (_i = 0; _i < 3; _i++) {
    _row = self.dg_DATA.get(_i, self.IDX_LVLS_ROW) + self.LVL_SECTION_ROWS - 1
    if (self.cnt_draw_rows <= _row || (g.level_up_idx === _i && +!gmb(self.canDrawStatIcon))) {
      continue //_i
    }
    switch (_i) {
      case STAT_ATK: {
        _count = f.level_atk
        break
      }
      case STAT_MAG: {
        _count = f.level_mag
        break
      }
      case STAT_LIF: {
        _count = f.level_lif
        break
      }
    }
    _x = self.drawX + (self.CLM_LVL_ICON << 3)
    _y = self.drawY + (_row << 3)
    _y += 1 // mod 2022/05/27. Padding against bottom of "WILL GO UP" text
    for (_j = 0; _j < _count; _j++) {
      draw_spr_aligned(self.dg_DATA.get(_i, self.IDX_ICON_SPR), _x + (_j << 3), _y, -1, -1)
    }
    /*
    if (g.level_up_idx==_i 
    &&  _count>=STAT_LEVEL_MAX )
    {// Draw 1up +1 instead of "WILL GO UP"
        _x  = drawX + (CLM_LVL_TEXT<<3);
        _y -= 9;
        _x += 4;
        _y += 8;
        //spr_Lives_icon
        draw_sprite_(spr_Lives_icon,0,  _x,_y, PI_PC_1);
        _x += 8;
        draw_sprite_(spr_plus_symbol,0, _x,_y, PI_DEF);
        _x += 8;
        draw_text_(_x,_y, "1");
    }
    */
  }
  // ----------------------------------------------------------------------------
  // TEXT
  for (_i = ds_grid_width(self.dg_DATA) - 1; _i >= 0; _i--) {
    if (
      _i === self.WILL_GO_UP_IDX ||
      _i === self.WILL_GO_UP_IDX + 1 ||
      self.cnt_draw_rows <= self.dg_DATA.get(_i, self.IDX_TEXT_ROW)
    ) {
      continue //_i
    }
    _x = self.drawX + (self.dg_DATA.get(_i, self.IDX_TEXT_CLM) << 3)
    _y = self.drawY + (self.dg_DATA.get(_i, self.IDX_TEXT_ROW) << 3)
    draw_text_(_x, _y, self.dg_DATA.get(_i, self.IDX_TEXT))
  }
  // ----------------------------------------------------------------------------
  // TEXT: "WILL", "GO UP"
  if (g.level_up_idx === STAT_ATK || g.level_up_idx === STAT_MAG || g.level_up_idx === STAT_LIF) {
    // This only draws "WILL GO UP" for the cursor's stat.
    // I beleive OG draws "WILL GO UP" for any stat that qualifies to level up.
    if (gmb(self.dg_DATA.get(g.level_up_idx, self.IDX_CAN_LVL))) {
      _idx = self.WILL_GO_UP_IDX
      _row = self.dg_DATA.get(_idx, self.IDX_TEXT_ROW) + self.LVL_SECTION_ROWS * g.level_up_idx
      for (_i = 0; _i < 2; _i++) {
        _row += _i
        if (self.cnt_draw_rows > _row) {
          _idx += _i
          _x = self.drawX + (self.dg_DATA.get(_idx, self.IDX_TEXT_CLM) << 3)
          _y = self.drawY + (_row << 3)
          draw_text_(_x, _y, self.dg_DATA.get(_idx, self.IDX_TEXT))
        }
      }
    }
  }
  // ----------------------------------------------------------------------------
  // TEXT: LEVEL UP COST
  for (_i = 0; _i < 3; _i++) {
    if (self.cnt_draw_rows > self.dg_DATA.get(_i, self.IDX_TEXT_ROW) + 1) {
      _x = self.drawX + (self.CLM_XP << 3)
      _y = self.drawY + ((self.dg_DATA.get(_i, self.IDX_TEXT_ROW) + 1) << 3)
      draw_text_(_x, _y, string(self.dl_xp_next_stat.get(_i)))
    }
  }
  // ----------------------------------------------------------------------------
  pal_swap_reset()
  // ----------------------------------------------------------------------------
  // ----------------------------------------------------------------------------
  // ----------------------------------------------------------------------------
  self.canDrawSections = 0
  self.cnt_draw_rows = 0
}

/** GML: update_LevelUp() */
export function update_LevelUp(self: LevelUpMenu) {
  let _i: any, _j: any, _DIFF: any

  // 9D75
  switch (g.menu_state) {
    // ---------------------------------------------------------------------
    case 0: {
      // ---------------------------------------------------------------------
      // g.menu_built_count = 0;
      // A199: JMP A267
      g.menu_state++
      break
    }
    // ---------------------------------------------------------------------
    case 1: {
      // ---------------------------------------------------------------------
      // A347, A31C
      g._074F = 0xc0
      aud_play_sound(get_audio_theme_track(dk_OpenGUI))
      g.menu_state++
      break
    }
    // ---------------------------------------------------------------------
    case 2: {
      // ---------------------------------------------------------------------
      g.level_up_idx = self.OPTION_CANCEL // mod
      // 9FCE
      if (false) {
        // OG
        if (get_xp_next(STAT_ATK) < f.xp) {
          g.level_up_idx = STAT_ATK
        } else if (get_xp_next(STAT_MAG) < f.xp) {
          g.level_up_idx = STAT_MAG
        } else if (get_xp_next(STAT_LIF) < f.xp) {
          g.level_up_idx = STAT_LIF
        }
      } else {
        // MOD
        if (get_xp_next(STAT_ATK) === f.xpNext) {
          g.level_up_idx = STAT_ATK
        } else if (get_xp_next(STAT_MAG) === f.xpNext) {
          g.level_up_idx = STAT_MAG
        } else if (get_xp_next(STAT_LIF) === f.xpNext) {
          g.level_up_idx = STAT_LIF
        }
      }
      for (_i = min(STAT_ATK, STAT_MAG, STAT_LIF); _i <= max(STAT_ATK, STAT_MAG, STAT_LIF); _i++) {
        self.dg_DATA.set(_i, self.IDX_CAN_LVL, get_xp_next(_i) <= f.xp)
      }
      // dg_DATA[#STAT_ATK,IDX_CAN_LVL] = get_xp_next(STAT_ATK) <= f.xp;
      // dg_DATA[#STAT_MAG,IDX_CAN_LVL] = get_xp_next(STAT_MAG) <= f.xp;
      // dg_DATA[#STAT_LIF,IDX_CAN_LVL] = get_xp_next(STAT_LIF) <= f.xp;
      // dg_DATA[#STAT_ATK,IDX_CAN_LVL] = get_xp_next(STAT_ATK) < f.xp;
      // dg_DATA[#STAT_MAG,IDX_CAN_LVL] = get_xp_next(STAT_MAG) < f.xp;
      // dg_DATA[#STAT_LIF,IDX_CAN_LVL] = get_xp_next(STAT_LIF) < f.xp;
      // A053
      g.menu_state++
      break
    }
    // ---------------------------------------------------------------------
    case 3: {
      // ---------------------------------------------------------------------
      // A26B, A267
      g.menu_state++
      break
    }
    // ---------------------------------------------------------------------
    case 4: {
      // ---------------------------------------------------------------------
      // A2F8: JSR A647, A304
      g.menu_built_count = (g.menu_built_count + 1) & 0xff
      usd_LevelUpMenu(self)
      if (g.menu_built_count >= self.ROWS >> 1) {
        g.menu_state++
      }
      break
    }
    // ---------------------------------------------------------------------
    case 5: {
      // ---------------------------------------------------------------------

      // 9E7A: JSR 9DF6
      // 9DF6
      if (gmb(gui_tmr_cursor_v())) {
        // 9E82
        // each menu option
        for (_i = 0; _i < 4; _i++) {
          g.level_up_idx = (g.level_up_idx + sign_(input.Down_held)) & 3
          // 3: CANCEL
          if (g.level_up_idx === self.OPTION_CANCEL) {
            // each stat
            for (_j = 0; _j < 3; _j++) {
              // As long as xp has not been reached for 1 stat
              if (get_xp_next(_j) > f.xpNext) {
                _i = 4
                break
              }
            }
          } else if (f.xp >= get_xp_next(g.level_up_idx)) {
            break
          }
        }
        // 9ECA
        aud_play_sound(get_audio_theme_track(dk_CursorSpellMenu))
      }
      // 9F3D
      usd_LevelUpMenu(self)
      //if ( Input.Pause_held          // Start held
      //&& !(Input.heldPrev&Input.S) ) // Start NOT held prev frame
      if (gmb(input.Pause_pressed)) {
        update_LevelUp_1a(self) // option selected by pressing start
        // 9FC0: JMP 9FB9, 9F92, 9FB9
        g.menu_state++
      }
      break
    }
    // ---------------------------------------------------------------------
    case 6: {
      // ---------------------------------------------------------------------
      usd_LevelUpMenu(self)
      /*
        // A68B
        if (g.level_up_idx == 3) // 3: CANCEL
        {
            var _buildCountCopy = g.menu_built_count;
            
                 if (g.level_up_idx == 0) g.menu_built_count = 4;
            else if (g.level_up_idx == 1) g.menu_built_count = 6;
            else if (g.level_up_idx == 2) g.menu_built_count = 9;
            
            // A69C: JSR A647
            // A69F: JSR A35F
            
            g.menu_built_count = _buildCountCopy;
        }
        */
      if (g.level_up_idx === self.OPTION_CANCEL) {
        g.gui_timer1 = 0x60
      } else {
        g.gui_timer1 = 0x20
      }
      g._074F |= 0xc0
      g.menu_state++
      break
    }
    // ---------------------------------------------------------------------
    case 7: {
      // ---------------------------------------------------------------------
      if (+!gmb(g.level_up_timer)) {
        g.level_up_timer = 0x9a // For pre-sound only
      }
      if (gmb(g.level_up_timer)) {
        g.level_up_timer-- // For pre-sound only
      }
      // MOD  --------------------------------------------
      // Uptick xpnext value for stat chosen to level up
      if (g.level_up_idx !== self.OPTION_CANCEL) {
        _DIFF = get_xp_next(g.level_up_idx) - self.dl_xp_next_stat.get(g.level_up_idx)
        if (gmb(_DIFF)) {
          if (_DIFF >= 10) {
            self.dl_xp_next_stat.set(g.level_up_idx, self.dl_xp_next_stat.get(g.level_up_idx) + 10)
          } else {
            self.dl_xp_next_stat.set(g.level_up_idx, self.dl_xp_next_stat.get(g.level_up_idx) + 1)
          }
          if (+!gmb(g.level_up_timer)) {
            g.level_up_timer = 1 // Keep menu open until uptick done
          }
        }
      }
      // ------------------------------------------------
      if (g.level_up_idx === self.OPTION_CANCEL) {
        g.level_up_timer = 0 // CANCEL
      }
      // A0F1
      g.gui_timer1 = (g.gui_timer1 - 1) & 0xff
      if (+!gmb(g.level_up_timer)) {
        // A325
        g.menu_state++
      }
      usd_LevelUpMenu(self)
      /*
        if(!g.luTimer 
        || (g.menu_built_count == 3 && !g.gui_tmr_1) )
        {
            // A325
            g.menu_state++;
        }
        
        if (g.luTimer 
        &&  g.menu_built_count != 3 )
        {
            // A0FE
            // A114: JSR A647
            
            // A117
            // usd_LevelUpMenu();
        }
        
        usd_LevelUpMenu();
        */
      // LOGIC WITH SOUND -------------------------------------------------
      /*
        if (Sound._07FB != $10 
        ||  (g.menu_built_count == 3 && !g._0487) )
        {
            // A325
            g.menu_state = byte(g.menu_state + 1);
        }
        
        if (Sound._07FB == $10 && g.menu_built_count != 3)
        {
            // A0FE
            // A114: JSR A647
            
            // A117
            usd_LevelUpMenu();
        }
        */
      break
    }
    // ---------------------------------------------------------------------
    case 8: {
      // ---------------------------------------------------------------------
      usd_LevelUpMenu(self)
      // A26B, A267
      g.menu_state++
      break
    }
    // ---------------------------------------------------------------------
    case 9: {
      // ---------------------------------------------------------------------
      // A3D7, A267, A3DF
      g.menu_built_count--
      if (g.menu_built_count < 0) {
        g.menu_state++
      } else {
        usd_LevelUpMenu(self)
      }
      break
    }
    // ---------------------------------------------------------------------
    case 10: {
      // ---------------------------------------------------------------------
      // A338
      g.gui_state = g.gui_state_NONE
      g.menu_built_count = 0
      g.menu_state = 0
      break
    }
  }
  // MOD. Start stat restore in level up menu instead of after.
  if (g.gui_state !== g.gui_state_NONE && g.menu_state > 5) {
    update_stat_restore()
  }
}

