// Ported from ZALiA scripts/g_Room_Start_1c.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively
import {
  STR_Enemy,
  STR_Height,
  STR_Idx,
  STR_Method,
  STR_OBJVER,
  STR_Object,
  STR_obj_idx,
  STR_Randomize,
  STR_Randomized,
  STR_Respawn,
  STR_Spawn,
  STR_Spawn_Permission,
  STR_Type,
  STR_Version,
  STR_Width,
} from '@z2/data'
import { hexStr as hex_str } from '../../../nes/hexStr'
import { gmBool } from '../../../nes/math8'
import { f, G, g } from '../../../runtime/world'
import { get_defeated_dk, get_spawn_datakey } from '../../game_object_mgr/spawn'
import { str_hex } from '../../other/index'
import {
  ds_grid_create,
  ds_grid_destroy,
  ds_grid_height,
  ds_grid_read,
  ds_grid_resize,
  ds_grid_width,
  ds_grid_write,
  ds_list_add,
  ds_list_create,
  ds_list_destroy,
  ds_list_size,
  is_undefined,
  min,
  object_get_name,
  string_copy,
  string_length,
  val,
} from '../gm'
import { g_Room_Start_1a } from './g_Room_Start_1a'
import { g_Room_Start_1b } from './g_Room_Start_1b'
import { g_Room_Start_1d } from './g_Room_Start_1d'

/** GML: g_Room_Start_1c(encoded grid, spawn type, original scene name, rando scene name) */
export function g_Room_Start_1c(...argument: any[]) {
  // GML `var` is function-scoped; locals hoisted here:
  let _ENEMY_RANDO_METHOD: any,
    _SCENE_NAME_A: any,
    _SCENE_NAME_B: any,
    _SPAWN_TYPE: any,
    _arg: any,
    _count0: any,
    _dg: any,
    _dg_encoded: any,
    _dl_avail_spawn_dk: any,
    _h: any,
    _i: any,
    _idx: any,
    _idx1: any,
    _len: any,
    _obj: any,
    _obj_name: any,
    _objver1: any,
    _objver2: any,
    _respawn_type: any,
    _spawn_datakey: any,
    _spawn_datakey1: any,
    _spawn_datakey2: any,
    _spawn_permission: any,
    _spawn_permission1: any,
    _spawn_xc: any,
    _spawn_xl: any,
    _spawn_yc: any,
    _spawn_yt: any,
    _val: any,
    _val1: any,
    _val2: any,
    _ver: any,
    _w: any
  _arg = 0
  _dg_encoded = argument[_arg++] // dg_spawn_prio or dg_spawn_prxm encoded
  _SPAWN_TYPE = argument[_arg++] // STR_PRIO or STR_PRXM
  _SCENE_NAME_A = argument[_arg++]
  _SCENE_NAME_B = argument[_arg++]
  // let _i: any, _idx, _idx1, _val, _val1, _val2, _count0, _len: any;
  // let _w: any, _h: any;
  // let _obj: any, _ver, _obj_name: any;
  // let _spawn_datakey: any, _spawn_datakey1, _spawn_datakey2: any;
  // let _spawn_xl: any, _spawn_xc, _spawn_yt, _spawn_yc: any;
  // let _respawn_type: any;
  _spawn_permission = 0
  _spawn_permission1 = 0
  _objver1 = undefined as any
  _objver2 = undefined as any
  _dl_avail_spawn_dk = ds_list_create()
  _ENEMY_RANDO_METHOD = val(G.dm_save_file_settings.get(STR_Randomize + STR_Enemy + STR_Method))
  _count0 = val(g.dm_spawn.get(get_spawn_datakey(_SCENE_NAME_B, _SPAWN_TYPE, -1)))
  for (_i = 0; _i < _count0; _i++) {
    _spawn_datakey = get_spawn_datakey(_SCENE_NAME_B, _SPAWN_TYPE, _i)
    _obj = val(g.dm_spawn.get(_spawn_datakey + STR_obj_idx))
    if (gmBool(g_Room_Start_1b(_obj))) {
      _dg_encoded = g_Room_Start_1a(_dg_encoded, _spawn_datakey, true)
    } else if (gmBool(g_Room_Start_1d(_obj))) {
      ds_list_add(_dl_avail_spawn_dk, _spawn_datakey)
    }
  }
  _dg = ds_grid_create(0, 0)
  ds_grid_read(_dg, _dg_encoded)
  // Add enemy spawns from the vanilla scene to the spawn list
  _count0 = val(g.dm_spawn.get(get_spawn_datakey(_SCENE_NAME_A, _SPAWN_TYPE, -1)))
  _count0 = min(_count0, ds_list_size(_dl_avail_spawn_dk))
  for (_i = 0; _i < _count0; _i++) {
    _spawn_datakey1 = get_spawn_datakey(_SCENE_NAME_A, _SPAWN_TYPE, _i)
    _spawn_datakey2 = _dl_avail_spawn_dk.get(_i)
    _obj = val(g.dm_spawn.get(_spawn_datakey1 + STR_obj_idx))
    if (gmBool(_obj) && gmBool(g_Room_Start_1d(_obj))) {
      _obj_name = object_get_name(_obj)
      _ver = val(g.dm_spawn.get(_spawn_datakey1 + STR_Version))
      _objver1 = _obj_name + hex_str(_ver) // _objver example: "Snaraa"+"01" = obj name + ver
      if (gmBool(G.EnemyRando_enabled) && gmBool(_ENEMY_RANDO_METHOD)) {
        switch (_ENEMY_RANDO_METHOD) {
          default: {
            _objver2 = f.dm_rando.get(
              STR_Randomize + STR_Enemy + STR_Spawn + _spawn_datakey1 + STR_OBJVER + STR_Randomized,
            )
            break
          }
          case 2: {
            _objver2 = f.dm_rando.get(
              STR_Randomize + STR_Enemy + STR_Type + _objver1 + STR_OBJVER + STR_Randomized,
            )
            break
          }
        }
        if (!is_undefined(_objver2)) {
          _len = string_length(_objver2)
          _val1 = string_copy(_objver2, 1, _len - 2) // obj name
          _val2 = g.dm_go_prop.get(_val1 + STR_Object + STR_Idx) // obj
          if (!is_undefined(_val2)) {
            _obj = _val2
            _ver = str_hex(string_copy(_objver2, _len - 1, 2))
            _obj_name = object_get_name(_obj)
            _objver1 = _obj_name + hex_str(_ver)
          }
        }
      }
      _w = val(g.dm_go_prop.get(_obj_name + STR_Width), 0x10)
      _h = val(g.dm_go_prop.get(_obj_name + STR_Height), 0x10)
      _spawn_xl = val(g.dm_spawn.get(`${_spawn_datakey2}_x`)) // spawn x
      _spawn_yt = val(g.dm_spawn.get(`${_spawn_datakey2}_y`)) // spawn y
      // respawn_type: Value representing if and when GO can respawn.
      // 0: never, 1: off screen, 2: refresh area, 3: refresh rm, 4: 30 seconds (on or off screen)
      _respawn_type = val(g.dm_go_prop.get(_objver1 + STR_Respawn))
      _spawn_permission1 = val(g.dm_spawn.get(_spawn_datakey1 + STR_Spawn_Permission))
      // -1 never spawn again
      if (_respawn_type === 3 && _spawn_permission1 !== -1) {
        g.dm_spawn.set(_spawn_datakey1 + STR_Spawn_Permission, 1)
      }
      _spawn_permission = val(g.dm_spawn.get(_spawn_datakey1 + STR_Spawn_Permission))
      _idx1 = ds_grid_width(_dg)
      ds_grid_resize(_dg, _idx1 + 1, ds_grid_height(_dg))
      _idx = 0
      _dg.set(_idx1, _idx++, _spawn_datakey1) //
      _dg.set(_idx1, _idx++, _obj) //
      _dg.set(_idx1, _idx++, _obj_name) //
      _dg.set(_idx1, _idx++, _ver) //
      //                                          //
      _dg.set(_idx1, _idx++, _spawn_xl) //
      _dg.set(_idx1, _idx++, _spawn_xl + (_w >> 1)) //
      _dg.set(_idx1, _idx++, _spawn_yt) //
      _dg.set(_idx1, _idx++, _spawn_yt + (_h >> 1)) //
      //                                          //
      _dg.set(_idx1, _idx++, _w) //
      _dg.set(_idx1, _idx++, _w >> 1) //
      _dg.set(_idx1, _idx++, _h) //
      _dg.set(_idx1, _idx++, _h >> 1) //
      //                                          //
      _dg.set(_idx1, _idx++, _respawn_type) //
      _dg.set(_idx1, _idx++, val(f.dm_quests.get(get_defeated_dk() + _spawn_datakey1))) //
      _dg.set(_idx1, _idx++, _spawn_permission) //
    }
  }
  ds_list_destroy(_dl_avail_spawn_dk)
  _dl_avail_spawn_dk = undefined as any
  _dg_encoded = ds_grid_write(_dg)
  ds_grid_destroy(_dg)
  _dg = undefined as any
  return _dg_encoded
}
