/** Ported from `cutscene_build_house_1.gml`, `Cutscene_MagicalKeyHouse_init.gml`, `Cutscene_MagicalKeyHouse_update.gml`. */
import {
  DEPTH_BG3,
  DEPTH_BG4,
  dk_BridgeCrumble,
  dk_ExitName,
  dk_MagicalKeyHouse,
  PC_LOCK_ALL,
  SPL_SPEL,
  STR_Data,
} from '@z2/data'
import { bit1st, gmBool } from '../../../nes/math8'
import { g } from '../../../runtime/world'
import { instancesNamed } from '../../Game/gm'
import { spell_last_used } from '../../Game/spell_last_used'
import { sign_ } from '../../math'
import { str_hex, val } from '../../other'
import { aud_play_sound } from '../../sound/play'
import { get_audio_theme_track } from '../../sound/theme'
import { tile_change_1a } from '../../tile/tileOps'
import type { Cutscene_MagicalKeyHouse } from './classes'
import { Cutscene_init } from './cutscene'

/** `cutscene_build_house_1(build dir, speed, clm, row, *depth, *tsrc data)` — builds the Magical Key house row by row. */
export function cutscene_build_house_1(
  dir: number,
  speed: number,
  rmClm: number,
  rmRow: number,
  depth = -1,
  tsrcData: string | -1 = -1,
): void {
  if (gmBool(g.cutscene_house_built) || g.ChangeRoom_timer > 0 || gmBool(g.EnterRoom_SpawnGO_timer)) return
  // -------------------------------------------------------------------------------------
  const _DIR = sign_(dir)
  const _SPEED = Math.min(Math.max(bit1st(speed), 0x01), 0x08) // build 1 row every 2,4,8,16,32,64,128,256 frames
  const _TIMING = (1 << _SPEED) - 1
  if (!gmBool(g.cutscene))
    g.cutscene_ctr = (g.counter1 & _TIMING) + 1 // First frame of cutscene.
  else g.cutscene_ctr++ // Might need this to be able to go beyond 256.
  g.cutscene = g.CUTSCENE_BUILD_HOUSE1
  // -------------------------------------------------------------------------------------
  if (g.cutscene_ctr & _TIMING) return
  // 8F02. mkh update draw data
  // Nothing gets built until the 2nd time it makes it here.
  const _BUILD_ROWS = (g.cutscene_ctr >> _SPEED) - 1
  if (!_BUILD_ROWS) return
  // -------------------------------------------------------------------------------------
  let _DEPTH = DEPTH_BG3
  if (depth !== -1) _DEPTH = depth
  let _TSRC_DATA: string = g.MKH_TSRC_DATA
  if (tsrcData !== -1) _TSRC_DATA = tsrcData
  const _CHAR_PER_TILE = 4
  for (let _i = 0; _i < _BUILD_ROWS; _i++) {
    // each row of house built
    for (let _j = 0; _j < g.MKH_CLMS; _j++) {
      // each clm of house
      const _x = (rmClm + _j) << 3
      const _y = (rmRow + _BUILD_ROWS * _DIR + _i * -_DIR) << 3
      let _idx = g.MKH_CLMS * _CHAR_PER_TILE * _i
      _idx += _j * _CHAR_PER_TILE
      const _tile_data = _TSRC_DATA.substr(_idx, _CHAR_PER_TILE)
      const _tsrc = str_hex(_tile_data.substr(2, 2))
      _idx = str_hex(_tile_data.substr(0, 2))
      let _ts: string | 0
      if (!_idx)
        _ts = 0 // deletes tile
      else _ts = g.dl_tileset.get(_idx) as string
      tile_change_1a(_DEPTH, _x, _y, _ts, _tsrc)
    }
  }
  aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
  if (_BUILD_ROWS === g.MKH_ROWS) {
    g.cutscene_house_built = 1 // Only sets 0 at g_Room_Start()
    g.cutscene = 0
    g.cutscene_ctr = 0
    g.pc_lock = 0
  }
}

/** `Cutscene_MagicalKeyHouse_init()` */
export function Cutscene_MagicalKeyHouse_init(self: Cutscene_MagicalKeyHouse): void {
  Cutscene_init(self)
  self.scr_step = Cutscene_MagicalKeyHouse_update as never
  self.CLM = self.xl >> 3 // left most clm
  self.ROW = self.yt >> 3 // grow source row
  const d1 = self.dk_spawn !== undefined ? g.dm_spawn.get(`${self.dk_spawn + STR_Data}01`) : undefined
  if (d1 !== undefined) self.depth = d1 as number
  else self.depth = DEPTH_BG4
}

/** `Cutscene_MagicalKeyHouse_update()` — SPELL cast next to the house builds it. */
export function Cutscene_MagicalKeyHouse_update(self: Cutscene_MagicalKeyHouse): void {
  if (spell_last_used() !== SPL_SPEL && g.cutscene !== g.CUTSCENE_BUILD_HOUSE1) return
  const _cutscene_COPY = g.cutscene
  cutscene_build_house_1(-1, 0x04, self.CLM, self.ROW, self.depth)
  if (!gmBool(_cutscene_COPY) && gmBool(g.cutscene)) {
    // The frame the cutscene started.
    aud_play_sound(get_audio_theme_track(dk_MagicalKeyHouse))
  }
  if (gmBool(_cutscene_COPY) && !gmBool(g.cutscene)) {
    // The frame the cutscene fininshed
    for (const ex of instancesNamed('Exit')) {
      if (ex.exitName === val(g.dm_rm.get(dk_MagicalKeyHouse + dk_ExitName))) {
        ex.open = 1
        break
      }
    }
  }
  if (gmBool(g.cutscene)) g.pc_lock = PC_LOCK_ALL
}
