/**
 * Sprite metadata runtime — GM's `sprite_get_*` over the generated manifest
 * (`packages/data/generated/sprites.json`, produced by `pnpm tool assets sprites`).
 * Sprites are referenced by name string everywhere in the port.
 */
export interface SpriteBBox {
  left: number
  right: number
  top: number
  bottom: number
}

export interface SpriteInfo {
  name: string
  atlas: string
  frames: number
  width: number
  height: number
  originX: number
  originY: number
  bbox: SpriteBBox
  folder: string
  /** Set for sprites composed at runtime (`sprite_create_with_tiles`). */
  composite?: CompositeSprite
}

/** A runtime-composed sprite: 8×8 tileset cells drawn onto a canvas (adapter builds the texture). */
export interface CompositeSprite {
  width: number
  height: number
  tiles: { tileset: string; tsx: number; tsy: number; x: number; y: number; xscale: 1 | -1; yscale: 1 | -1 }[]
}

const manifest = new Map<string, SpriteInfo>()

/** Inject the manifest (adapter: fetched JSON; tests: read from disk). Replaces any previous one. */
export function setSpriteManifest(entries: readonly SpriteInfo[]): void {
  manifest.clear()
  for (const e of entries) manifest.set(e.name, e)
}

export function spriteExists(name: string): boolean {
  return manifest.has(name)
}

/** Whether the manifest knows this sprite (GM `sprite_exists`). */
export function hasSpriteInfo(name: string): boolean {
  return manifest.has(name)
}

export function spriteInfo(name: string): SpriteInfo {
  const s = manifest.get(name)
  if (!s) throw new Error(`unknown sprite ${name} (manifest not loaded, or asset missing)`)
  return s
}

/** Register a runtime-created sprite (composites); returns its name. */
export function addSprite(info: SpriteInfo): string {
  manifest.set(info.name, info)
  return info.name
}

export const sprite_get_width = (s: string): number => spriteInfo(s).width
export const sprite_get_height = (s: string): number => spriteInfo(s).height
export const sprite_get_xoffset = (s: string): number => spriteInfo(s).originX
export const sprite_get_yoffset = (s: string): number => spriteInfo(s).originY
export const sprite_get_number = (s: string): number => spriteInfo(s).frames
export const sprite_get_bbox_left = (s: string): number => spriteInfo(s).bbox.left
export const sprite_get_bbox_right = (s: string): number => spriteInfo(s).bbox.right
export const sprite_get_bbox_top = (s: string): number => spriteInfo(s).bbox.top
export const sprite_get_bbox_bottom = (s: string): number => spriteInfo(s).bbox.bottom
