/** Doomknocker (ZALiA object `DoomA`, parent `Enemy`; the mace-throwing hopper). `Doomknocker_init2/update/udp/draw.gml`. */
import { CS_BD1, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { draw_sprite_, GO_draw_sprite } from '../../../../go/draw'
import { dir_to_pc } from '../../../../go/misc'
import { GO_vspd_update1, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { solid_clip_correction } from '../../../../goa/movement'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_1, GOB_update_2 } from '../../../GameObjectB'
import { projOf } from '../ache/_shared'

export class DoomA extends Enemy {
  readonly objectName = 'DoomA' as const
  VSPD_GRAV = 2
  Arm_sprite: string | 0 = 0
  Arm_xoff = 4
  Arm_yoff = 0
  Legs_sprite = 'spr_Doomknocker_legs1'
}

/** `Doomknocker_init2()` */
export function Doomknocker_init2(self: DoomA): void {
  self.projectile_OBJ = 'Mace2'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.dl_sprites?.set(0, 'spr_Doomknocker_body1')
  GO_init_palidx(self, G.PI_MOB_BLU)
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.Arm_sprite = 0
  self.Arm_xoff = 4
  self.Arm_yoff = 0
  self.Legs_sprite = 'spr_Doomknocker_legs1'
}

/** `Doomknocker_update()` — B0AD */
export function Doomknocker_update(self: DoomA): void {
  // B0AD. Set attack timer
  if (!(self.counter & 0x7f)) self.timer = 0x10
  if (self.timer === 1 && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
    const proj = GOC1_create(self.xl, self.yt, self.facing_dir, projOf(self), self.projectile_ver, self)
    proj.counter = 0x40
  }
  // B0D7
  if (self.counter & 0x40) self.hspd = -0x8 & 0xff
  else self.hspd = 0x8 & 0xff
  // JUMP!!!
  if (!g.counter1) self.vspd = 0xd0
  updateY(self)
  GOB_update_1(self, true) // hspdPB
  GO_update_cs(self)
  if (!(self.cs & 0x3)) updateX(self)
  // B0EA: JSR DE3D
  GO_update_cs(self)
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // B0F0
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
    self.counter = (self.counter + 1) & 0xff
  }
  // MOD. Prevent clip into ceiling
  GO_vspd_update1(self)
  // B0FB
  self.facing_dir = dir_to_pc(self)
}

/** `Doomknocker_udp()` */
export function Doomknocker_udp(self: DoomA): void {
  self.can_draw_self = true
  if (self.cs & 0x4 && g.counter1 & 0x10) self.Legs_sprite = 'spr_Doomknocker_legs2'
  else self.Legs_sprite = 'spr_Doomknocker_legs1'
  self.Arm_sprite = gmBool(self.timer) ? 'spr_Doomknocker_arm1' : 0
  self.Arm_xoff = 4 * -self.facing_dir
}

/** `Doomknocker_draw()` */
export function Doomknocker_draw(self: DoomA): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  if (self.Arm_sprite)
    draw_sprite_(
      self.Arm_sprite,
      0,
      self.drawX + self.Arm_xoff,
      self.drawY + self.Arm_yoff,
      -1,
      self.xScale,
      1,
      self.depth,
    )
  GO_draw_sprite(self, self.Legs_sprite)
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

registerObject('DoomA', DoomA)
registerScripts({ Doomknocker_init2, Doomknocker_update, Doomknocker_udp, Doomknocker_draw })
