/** `update_GameObjectMgr()` — D504: JSR D5A7. The per-frame entity update with the OG take-turn ordering. */
import { MAX_GOB1, MAX_GOC1 } from '@z2/data'
import { instanceExists } from '../../runtime/instance'
import { goMgr, world } from '../../runtime/world'
import { Challenge, type GameObject, GOB1, GOB2, ProjectileHostile } from '../game_object/classes'
import { gp } from '../game_object/pending'
import { update_go_spawn_1b } from './spawn'

const alive = (v: unknown): v is GameObject => instanceExists(v as GameObject | null | undefined)

export function update_GameObjectMgr(): void {
  const m = goMgr
  // ---------------------------------------------------------------------------
  if (m.counter + 1 === MAX_GOC1) m.counter = 0
  else m.counter++
  // ---------------------------------------------------------------------------
  // GOB2. NPC, Item, RestoreFairy, LockedDoor, Elevator, CrystalHolder, Barrier, Pushable, ...
  for (let _i = m.dl_gob2.size - 1; _i >= 0; _i--) {
    const inst = m.dl_gob2.get(_i)
    if (!alive(inst)) continue
    inst.update_idx = _i
    if (inst.timer) inst.timer--
    if (inst.scr_step) inst.scr_step(inst)
  }
  // ---------------------- MAIN GAME OBJECT UPDATE -----------------------------------
  // OG executes a 'take-turn' method of updating GOB and GOC. 1 GOB, then 1 GOC, then to the next index and repeat.
  for (m.update_idx = 0; m.update_idx < m.UPDATE_COUNT; m.update_idx++) {
    // GOB1 (Enemy, Boss) ---------------------------------
    if (m.update_idx >= 0 && m.update_idx < MAX_GOB1) {
      // D5A7, D5D4, D5E0, D603
      const inst = m.dl_gob1.get(m.update_idx)
      if (alive(inst) && inst.state) {
        inst.update_idx = m.update_idx
        if (inst.timer) inst.timer--
        if (inst.scr_step) inst.scr_step(inst) // scr_step: GameObjectB_step()
      }
    }
    // GOC1 (Hostile Projectiles) ----------------------------
    if (m.update_idx >= 0 && m.update_idx < MAX_GOC1) {
      const inst = m.dl_goc1.get(m.update_idx)
      if (alive(inst) && inst.state) {
        // D577
        inst.update_idx = m.update_idx
        if (inst.timer) inst.timer--
        if (inst.scr_step) inst.scr_step(inst)
      }
    }
  }
  update_go_spawn_1b(false)
  // ---------------------------------------------------------------------------
  for (const c of world.instancesOf(Challenge)) {
    if (c.scr_step) c.scr_step(c)
  }
  // ---------------------  CLEAN UP  ----------------------------------
  if (!(gp().counter1 & 0x3)) {
    // limit frequency of this for better performance?
    for (const e of world.instancesOf(GOB1)) {
      if (!e.state || m.dl_gob1.findIndex(e) === -1) e.destroy()
    }
    for (const p of world.instancesOf(ProjectileHostile)) {
      // Hostile Projectiles (GOC1)
      if (!p.state || m.dl_goc1.findIndex(p) === -1) p.destroy()
    }
    // GOB2 cleanup: truncate all dead beyond the furthest alive one so alive ones keep their update index.
    for (let _i = m.dl_gob2.size - 1; _i >= 0; _i--) {
      const inst = m.dl_gob2.get(_i)
      if (alive(inst) && inst.state) break // Only remove ones beyond the furthest alive one.
      m.dl_gob2.delete(_i)
    }
    for (const b of world.instancesOf(GOB2)) {
      if (m.dl_gob2.findIndex(b) === -1) b.destroy()
    }
  }
}
