/** Aneru (ZALiA object `Aneru01`, parent `Enemy`; the jumping/shooting Octorok variant). `Aneru_init2/update/udp.gml`. */
import { ABL_JUMP, ABL_SHOT, ABL_WALK } from '@z2/data'
import { Enemy } from '../../../../classes'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_udp_1 } from '../../../GameObjectB'
import { Octorok_update } from '../ache/_shared'

export class Aneru01 extends Enemy {
  readonly objectName = 'Aneru01' as const
  VSPD_GRAV = 2
}

/** `Aneru_init2()` */
export function Aneru_init2(self: Aneru01): void {
  self.dl_sprites?.add('spr_Aneru1', 'spr_Aneru2')
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  switch (self.ver) {
    case 1:
      self.abilities |= ABL_JUMP
      self.abilities |= ABL_SHOT
      self.projectile_OBJ = 'Rock2'
      self.projectile_VER = 1
      break
    case 2:
      self.abilities |= ABL_JUMP
      self.abilities |= ABL_SHOT
      self.abilities |= ABL_WALK
      self.projectile_OBJ = 'Rock2'
      self.projectile_VER = 1
      break
    case 3:
      self.abilities |= ABL_JUMP
      self.abilities |= ABL_SHOT
      self.projectile_OBJ = 'Fireball1'
      self.projectile_VER = 1
      break
  }
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
}

/** `Aneru_update()` */
export function Aneru_update(self: Aneru01): void {
  Octorok_update(self)
}

/** `Aneru_udp()` */
export function Aneru_udp(self: Aneru01): void {
  self.can_draw_self = true
  GOB_udp_1(self, 8)
}

registerObject('Aneru01', Aneru01)
registerScripts({ Aneru_init2, Aneru_update, Aneru_udp })
