export const kakusuClasses: Record<string, new () => KakusuBase> = {}
for (const name of NAMES) {
  const cls = class extends KakusuBase {
    override readonly objectName: ObjectName = name
  }
  Object.defineProperty(cls, 'name', { value: name })
  kakusuClasses[name] = cls
  registerObject(name, cls)
  registerObjectClass(name, cls)
}

