/** `Kakusu001_init2()` — DthMt_0F: 5 short pillars; jump on each from the left end without touching ground. */
export function Kakusu001_init2(self: KakusuBase): void {
  let _a = 1
  self.SUB_STATE_CHLG_1A = _a++
  self.SUB_STATE_CHLG_1B = _a++
  self.SUB_STATE_ACTV = _a++
  self.sub_state = self.SUB_STATE_CHLG_1A
  self.abilities |= ABL_WALK
  self.abilities |= ABL_JUMP
  self.abilities |= ABL_RUN_
  self.VSPD_REVEAL = self.vspd_jump
  const _CLM = G.dg_solid_w
  const _ROW = G.dg_solid_h
  self.Platform_COUNT = 5
  self.PLATFORM_DEPTH = DEPTH_BG2
  self.PLATFORM_PI = G.PI_BGR2
  self.PLATFORM_PI = val(
    p.dm_depth_pi.get(hex_str(Math.abs(self.PLATFORM_DEPTH))),
    self.PLATFORM_PI,
  ) as number
  self.PLATFORM_DEPTH--
  self.PLATFORM_TS = 'ts_DungeonA01'
  self.PlatformNext_idx = 0
  self.TSRC_IDX = self.Platform_COUNT - 1
  // dg_platform[i, 0] = done flag, [i,1] = clm, [i,2] = row, [i, TSRC_IDX] = packed tsrc (surfaces/sprites are adapter-side)
  self.dg_platform = new DsGrid<number>(self.Platform_COUNT, 5, 0)
  // Each nybble's value is a diff pillar head and the row in the tileset.
  const _dl_TSRC = [0x1011, 0x1311, 0x11, 0x0101, 0x3010, 0x2111, 0x1110, 0x1001, 0x3100, 0x1010]
  for (let _i = _dl_TSRC.length - 1; _i >= 0; _i--) {
    const _data = _dl_TSRC[_i] as number
    let v = 0
    v = (((_data >> 0x0c) & 0x0f) << 4) | 0x00 // ts clm $0: TOP-LFT
    v |= ((((_data >> 0x08) & 0x0f) << 4) | 0x01) << 0x08 // ts clm $1: TOP-RGT
    v |= ((((_data >> 0x04) & 0x0f) << 4) | 0x04) << 0x10 // ts clm $4: BTM-LFT
    v |= ((((_data >> 0x00) & 0x0f) << 4) | 0x05) << 0x18 // ts clm $5: BTM-RGT
    _dl_TSRC[_i] = v >>> 0
  }
  self.dg_platform.set(0, self.TSRC_IDX, _dl_TSRC[5] as number)
  self.dg_platform.set(1, self.TSRC_IDX, _dl_TSRC[9] as number)
  self.dg_platform.set(2, self.TSRC_IDX, _dl_TSRC[1] as number)
  self.dg_platform.set(3, self.TSRC_IDX, _dl_TSRC[7] as number)
  self.dg_platform.set(4, self.TSRC_IDX, _dl_TSRC[8] as number)
  for (let _i = 0; _i < self.Platform_COUNT; _i++) {
    const _idx = Math.max(0, _i - 1)
    const _clm = (self.dg_platform.get(_idx, 1) as number) + 3
    // lft to rgt, btm to top: first one-way tile
    outer: for (let _j = _clm; _j < _CLM; _j++) {
      for (let _k = _ROW - 1; _k >= 0; _k--) {
        if ((G.dg_solid.get(_j, _k) as number) & TID_ONEWY1) {
          self.dg_platform.set(_i, 1, _j)
          self.dg_platform.set(_i, 2, _k)
          break outer
        }
      }
    }
  }
  const _idx = self.Platform_COUNT - 3 // Which platform will Kakusu spawn from when revealed.
  const _x = ((self.dg_platform.get(_idx, 1) as number) << 3) + self.ww_
  const _y = ((self.dg_platform.get(_idx, 2) as number) << 3) - self.hh_
  set_xy(self, _x, _y)
  Kakusu_init2(self)
}

/** `Kakusu001_update()` */
export function Kakusu001_update(self: KakusuBase): void {
  const P = pc()
  const D = self.dg_platform
  switch (self.sub_state) {
    case self.SUB_STATE_CHLG_1A: {
      if (gmBool(P.ogr)) break
      const _ROW = P.csBtm1Y >> 3
      if (
        wINw(P.csBtm1X, P.csBtm2X - P.csBtm1X, (D.get(0, 1) as number) << 3, 0x02 << 3) &&
        _ROW === D.get(0, 2)
      ) {
        for (let _i = 0; _i < self.Platform_COUNT; _i++) D.set(_i, 0, 0)
        self.PlatformNext_idx = 0
        D.set(self.PlatformNext_idx, 0, 1)
        aud_play_combo1(3)
        self.sub_state = self.SUB_STATE_CHLG_1B
      }
      break
    }
    case self.SUB_STATE_CHLG_1B: {
      if (gmBool(P.ogr) || !(P.cs & CS_BTM)) break
      const _ROW = P.csBtm1Y >> 3
      const _CLM1 = P.csBtm1X >> 3
      const _CLM2 = P.csBtm2X >> 3
      let _c1: boolean = is_in_grid(_CLM1, _ROW, g.rm_clms, g.rm_rows)
      let _c2: boolean = is_in_grid(_CLM2, _ROW, g.rm_clms, g.rm_rows)
      const _SOLID1 = _c1 ? (G.dg_solid.get(_CLM1, _ROW) as number) : 0
      const _SOLID2 = _c2 ? (G.dg_solid.get(_CLM2, _ROW) as number) : 0
      if ((!_c1 || !gmBool(_SOLID1)) && (!_c2 || !gmBool(_SOLID2))) break // NOT in solids grid or NOT on a solid
      // PC confirmed on top of solid tile
      if (_SOLID1 & TID_ONEWY1 || _SOLID2 & TID_ONEWY1) {
        const _W = 2 << 3
        const _x = P.x - (_W >> 1)
        const _y = _ROW << 3
        for (let _i = 1; _i < self.Platform_COUNT; _i++) {
          if (gmBool(D.get(_i, 0))) continue
          _c1 = rectInRect(
            _x,
            _y,
            _W,
            0x01 << 3,
            (D.get(_i, 1) as number) << 3,
            (D.get(_i, 2) as number) << 3,
            2 << 3,
            1 << 3,
          )
          _c2 = rectInRect(
            _x,
            _y,
            _W,
            0x01 << 3,
            (D.get(_i - 1, 1) as number) << 3,
            (D.get(_i - 1, 2) as number) << 3,
            2 << 3,
            1 << 3,
          )
          // PC is on next / curr platform in the sequence
          if (_c1 || _c2) {
            if (_c1) {
              D.set(_i, 0, 1)
              if (_i + 1 === self.Platform_COUNT) {
                self.facing_dir = -1
                self.hspd = (self.hspd_jump * self.facing_dir) & 0xff
                self.vspd = self.VSPD_REVEAL // Jump!
                self.ogr = OGR_JUMP
                self.stun_timer = self.STUN_DURATION1
                aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
                aud_play_sound(self.SND_REVEAL as string)
                self.sub_state = self.SUB_STATE_ACTV
              } else {
                self.PlatformNext_idx = _i + 1
                aud_play_combo1(3)
              }
            }
            return // PC is on qualified platform, skip the reset.
          }
          break // PC on wrong platform. Reset challenge.
        }
      }
      // PC NOT on qualified platform. Reset challenge.
      for (let _i = 0; _i < self.Platform_COUNT; _i++) D.set(_i, 0, 0)
      aud_play_combo1(3)
      self.sub_state = self.SUB_STATE_CHLG_1A
      break
    }
    case self.SUB_STATE_ACTV:
      Kakusu_update(self)
      break
  }
}

/** `Kakusu001_draw()` — the pillar-head graphic is 4 tiles of the dungeon tileset (drawn from tsrc, no surface). */
export function Kakusu001_draw(self: KakusuBase): void {
  if (self.sub_state === self.SUB_STATE_CHLG_1A || self.sub_state === self.SUB_STATE_CHLG_1B) {
    const D = self.dg_platform
    let _idx = 0
    const _FIRST = D.width - self.Platform_COUNT
    for (let _i = _FIRST; _i < self.Platform_COUNT + _FIRST; _i++) {
      _idx = _i
      if (!gmBool(D.get(_i, 0))) break
    }
    const _x = (D.get(_idx, 1) as number) << 3
    const _y = (D.get(_idx, 2) as number) << 3
    if (!rectInView(_x, _y, 0x10, 0x10)) return
    self.depth = self.PLATFORM_DEPTH
    // Cover any bg graphic behind pillar head so you can't see any bg graphic behind it.
    draw_sprite_('spr_1x1_WHT', 0, _x, _y, -1, 0x10, 0x10, background_colour())
    let _pi = self.PLATFORM_PI
    if (rm_pal_qual_lit()) _pi += p.PI_LIT1
    else _pi += p.PI_DRK1
    pal_swap_set(_pi)
    const packed = D.get(_idx, self.TSRC_IDX) as number
    for (let _j = 0; _j < 4; _j++) {
      const _tsrc = (packed >>> (_j << 3)) & 0xff
      let _ts: string
      switch ((_tsrc >> 4) & 0x0f) {
        case 0:
          _ts = 'ts_DungeonG01'
          break
        case 2:
          _ts = 'ts_DungeonB01'
          break
        case 3:
          _ts = 'ts_DungeonC01'
          break
        default:
          _ts = 'ts_DungeonA01'
      }
      const t = [0xe0, 0xe1, 0xf0, 0xf1][_j] as number
      draw_background_part(
        _ts,
        ((t >> 0) & 0x0f) << 3,
        ((t >> 4) & 0x0f) << 3,
        8,
        8,
        _x + ((_j & 1) << 3),
        _y + ((_j > 1 ? 1 : 0) << 3),
      )
    }
    pal_swap_reset()
    return
  }
  self.depth = self.depth_def
  Kakusu_draw(self)
}

