/** `Kakusu005_update()` */
export function Kakusu005_update(self: KakusuBase): void {
  switch (self.sub_state) {
    case self.SUB_STATE_CHLG_1A: {
      if (gmBool(self.sub_state_timer)) {
        self.sub_state_timer--
        break
      }
      let _complete = true
      for (const t of instancesOfName<Torch & { is_lit: boolean | number }>('Torch')) {
        if (!gmBool(t.is_lit)) {
          _complete = false
          break
        }
      }
      if (_complete) self.sub_state = self.SUB_STATE_CHLG_1B
      break
    }
    case self.SUB_STATE_CHLG_1B: {
      if (gmBool(self.sub_state_timer)) {
        self.sub_state_timer--
        break
      }
      // Stop any animating crumble blocks
      for (let _i = g.dg_tile_anim.width - 1; _i >= 0; _i--) {
        if (g.dg_tile_anim.get(_i, 0) === TID_BREAK2 || g.dg_tile_anim.get(_i, 0) === TID_BREAK4) {
          g.dg_tile_anim.set(_i, 1, 0) // set counter
          g.dg_tile_anim.set(_i, 3, 0) // set Anim frame num
          g.dg_tile_anim.set(_i, 7, 1)
        }
      }
      // Remove all crumble tiles
      const _ar_tid = tile_get_ids_at_depth(self.BreakTile_DEPTH)
      for (let _i = _ar_tid.length - 1; _i >= 0; _i--) {
        const id = _ar_tid[_i] as number
        if (!tile_exists(id)) continue
        const _clm = tile_get_x(id) >> 3
        const _row = tile_get_y(id) >> 3
        g.dg_RmTile_Break.set(_clm, _row, 0)
        tile_change_1a(self.BreakTile_DEPTH, _clm << 3, _row << 3, 0, -1, 0, 0, 0)
      }
      tile_layer_delete(self.BreakTile_DEPTH)
      // Add new ground
      const _y = self.GROUND_ROW << 3
      for (let _i = self.GROUND_CLM; _i < g.rm_clms; _i++) {
        if (gmBool(G.dg_solid.get(_i, self.GROUND_ROW))) break
        tile_change_1a(DEPTH_BG1, _i << 3, _y, 'ts_Man_made_1a_WRB', 0xa0, TID_ONEWY1)
      }
      aud_play_sound(get_audio_theme_track(dk_BlockBreak))
      aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
      self.facing_dir = sign_(self.x < g.rm_w_)
      aud_play_sound(self.SND_REVEAL as string)
      self.sub_state = self.SUB_STATE_ACTV
      break
    }
    case self.SUB_STATE_ACTV: {
      if (gmBool(self.sub_state_timer)) {
        self.sub_state_timer--
        break
      }
      Kakusu_update(self)
      break
    }
  }
}

