/**
 * GPU palette swap as a Phaser 4 Filter — port of ZALiA `shaders/shd_pal_swapper.shader`.
 * NOT verified in a browser (no GPU on the dev box); the CPU path in `paletteSwap.ts` is the default.
 * Usage: `registerPaletteSwapNode(game.renderer)` once, then on a Game Object
 * `obj.enableFilters(); obj.filters.internal.add(new PaletteSwapController(obj.filterCamera, palIdx))`.
 * Uniforms: `uPalette` (texture: N palettes wide × 8 high, see `paletteTextureBytes`), `uPaletteIndex`,
 * `uPaletteCount`, `uAlpha0` (ZALiA `ALPHA0_COLOR`).
 * APIs used (Phaser 4.2 types): `Phaser.Filters.Controller`, `Renderer.WebGL.RenderNodes.BaseFilterShader`
 * (`setupUniforms`/`setupTextures` overrides, `programManager.setUniform`), `renderNodes.addNode`.
 */
import Phaser from 'phaser'
import { PALETTE_SIZE, PALETTE_TEXTURE_KEY } from './paletteSwap'

export const PALETTE_SWAP_NODE = 'FilterPaletteSwap'

export const PALETTE_SWAP_FRAG = /* glsl */ `
precision mediump float;
uniform sampler2D uMainSampler;
uniform sampler2D uPalette;
uniform float uPaletteIndex;
uniform float uPaletteCount;
uniform vec3 uAlpha0;
varying vec2 outTexCoord;

void main () {
  vec4 src = texture2D(uMainSampler, outTexCoord);
  if (src.a > 0.0 && distance(src.rgb, uAlpha0) < 0.004) {
    src.a = 0.0; // ZALiA: cut out ALPHA0_COLOR pixels
  } else if (src.a > 0.0) {
    float srcX = 0.5 / uPaletteCount;
    float dstX = (uPaletteIndex + 0.5) / uPaletteCount;
    for (int i = 0; i < ${PALETTE_SIZE}; i++) {
      float y = (float(i) + 0.5) / ${PALETTE_SIZE}.0;
      // ZALiA compares for exact equality; a small tolerance survives texture filtering/precision.
      if (distance(src.rgb, texture2D(uPalette, vec2(srcX, y)).rgb) <= 0.004) {
        src.rgb = texture2D(uPalette, vec2(dstX, y)).rgb;
        break;
      }
    }
  }
  gl_FragColor = src;
}
`

export class PaletteSwapController extends Phaser.Filters.Controller {
  constructor(
    camera: Phaser.Cameras.Scene2D.Camera,
    public paletteIndex = 0,
    public paletteCount = 1,
  ) {
    super(camera, PALETTE_SWAP_NODE)
  }
}

class PaletteSwapNode extends Phaser.Renderer.WebGL.RenderNodes.BaseFilterShader {
  constructor(manager: Phaser.Renderer.WebGL.RenderNodes.RenderNodeManager) {
    super(PALETTE_SWAP_NODE, manager, undefined, PALETTE_SWAP_FRAG)
  }

  override setupTextures(
    _controller: Phaser.Filters.Controller,
    textures: Phaser.Renderer.WebGL.Wrappers.WebGLTextureWrapper[],
    drawingContext: Phaser.Renderer.WebGL.DrawingContext,
  ): void {
    const tex = drawingContext.renderer.game.textures.get(PALETTE_TEXTURE_KEY)
    const gl = tex?.source[0]?.glTexture
    if (gl) textures[1] = gl
  }

  override setupUniforms(
    controller: Phaser.Filters.Controller,
    _drawingContext: Phaser.Renderer.WebGL.DrawingContext,
  ): void {
    const c = controller as PaletteSwapController
    const pm = this.programManager
    pm.setUniform('uPalette', 1)
    pm.setUniform('uPaletteIndex', c.paletteIndex)
    pm.setUniform('uPaletteCount', c.paletteCount)
    pm.setUniform('uAlpha0', [0x7f / 255, 0x7f / 255, 0x7f / 255])
  }
}

export function registerPaletteSwapNode(
  renderer: Phaser.Renderer.WebGL.WebGLRenderer | Phaser.Renderer.Canvas.CanvasRenderer,
): void {
  if (!('renderNodes' in renderer)) return
  const manager = renderer.renderNodes
  if (!manager.hasNode(PALETTE_SWAP_NODE)) manager.addNode(PALETTE_SWAP_NODE, new PaletteSwapNode(manager))
}
