/**
 * `FrameIndicator` and `ValDisplay2` — two dev objects whose whole implementation lives in their
 * `.object.gmx` event code (no scripts). Neither is created by any ZALiA script or placed in any room:
 * they are spawned by hand from the IDE while debugging. They are registered for `instance_create` so
 * the same is possible here (`instance_create(0, 0, 'FrameIndicator')`).
 *
 * Dropped: `FrameIndicator`'s commented-out `frameCounter`/`MOD*` variant (the live block blinks off
 * `g.counter0` instead).
 */
import { DEPTH_SURFACE, ROOM_SPEED_BASE } from '@z2/data'
import { Instance } from '../../runtime/instance'
import { g } from '../../runtime/world'
import { draw_circ_ } from '../draw/index'
import { c_black, c_blue, c_lime, c_red } from '../Game/gmConsts'
import { draw_rect_, draw_text_, drawState } from '../rooms/draw'
import { viewXL, viewXR, viewYT } from '../view/camera'

/** Blinking circles at the bottom of the view: 1 = every 2nd frame, 2 = 4th, 3 = 8th. */
export class FrameIndicator extends Instance {
  readonly objectName = 'FrameIndicator'
  /** `<persistent>-1</persistent>` in ZALiA's object definition — survives a room change. */
  override readonly persistent = true
  depth = -1000
  useC1 = true
  useC2 = false
  useC3 = false
  readonly COL1 = c_red
  readonly COL2 = c_lime
  readonly COL3 = c_blue
  readonly C_RAD3 = 8
  readonly PADY = 4
  readonly PADX = 8
  readonly SPACING = this.C_RAD3 * 2 + this.PADX
  YOFF = g.VIEW_H - this.C_RAD3 - this.PADY
  XOFF_C1 = (g.VIEW_W >> 1) - this.SPACING
  XOFF_C2 = g.VIEW_W >> 1
  XOFF_C3 = (g.VIEW_W >> 1) + this.SPACING

  draw(): void {
    if (!g.can_use_FrameIndicator) return
    const depthCopy = drawState.depth
    drawState.depth = this.depth
    const _x = viewXL()
    if (this.useC1 && !(g.counter0 & 1))
      // blink every 2nd frame
      draw_circ_(this.COL1, _x + this.XOFF_C1, this.YOFF, this.C_RAD3, 1, false)
    if (this.useC2 && !(g.counter0 & 3))
      // blink every 4th frame
      draw_circ_(this.COL2, _x + this.XOFF_C2, this.YOFF, this.C_RAD3, 1, false)
    if (this.useC3 && !(g.counter0 & 7))
      // blink every 8th frame
      draw_circ_(this.COL3, _x + this.XOFF_C3, this.YOFF, this.C_RAD3, 1, false)
    drawState.depth = depthCopy
  }
}

/** A single value printed in the top-right corner for `DISPLAY_DUR` frames, then self-destructs. */
export class ValDisplay2 extends Instance {
  readonly objectName = 'ValDisplay2'
  depth = DEPTH_SURFACE + 1
  /** The value that will display */
  displayVal: number | string = 0
  readonly DISPLAY_DUR = ROOM_SPEED_BASE * 4
  timer = this.DISPLAY_DUR
  readonly X_OFF = 0
  readonly Y_OFF = 24
  readonly TEXT_X_OFF = 4
  readonly TEXT_Y_OFF = 2

  step(): void {
    if (this.timer) this.timer--
    else this.destroy()
  }

  draw(): void {
    const depthCopy = drawState.depth
    drawState.depth = this.depth
    const _str = String(this.displayVal)
    const _gmFix = 1
    const _width = 8 * _str.length + this.TEXT_X_OFF * 2 - _gmFix
    const _height = 8 + this.TEXT_Y_OFF * 2 - _gmFix
    const _x = viewXR() - _width - this.X_OFF
    const _y = viewYT() + this.Y_OFF
    draw_rect_(c_black, _x, _y, _width + 1, _height + 1, 1, false)
    draw_text_(_x + this.TEXT_X_OFF, _y + this.TEXT_Y_OFF, _str)
    drawState.depth = depthCopy
  }
}
