/** `Ra__A` — ZALiA `enemy/ra`: Ra_init2, Ra_update, Ra_update_1a. Wave-flying Ra (v1/v2/v3 speeds). */
import { CS_BD1, DEPTH_FLYER } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { g } from '../../../../../../runtime/world'
import { viewW, viewW_, viewXC, viewXL, viewXR } from '../../../../../collision/env'
import { wINw } from '../../../../../collision/geometry'
import { ocsH1, ocsV1 } from '../../../../../collision/ocs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { sign_ } from '../../../../../math/index'
import { registerObjectClass } from '../../../../../other/registry'
import { Enemy } from '../../../../classes'
import { dir_to_pc, GO_update_cam_vars } from '../../../../go/misc'
import { set_xlyt, set_xy, updateX, updateY } from '../../../../go/movement'
import { GO_depth_init, GO_set_sprite } from '../../../../go/sprite'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'
import { sign } from '../../shared'

export class Ra__A extends Enemy {
  readonly objectName = 'Ra__A' as const
  VSPD_CHANGE = 2
  vspd_change = 2
  HSPD = 0x10
  VSPD_MAX = 0x30
  SPAWN_YOFF = 0x20
}
registerObject('Ra__A', Ra__A)
registerObjectClass('Ra__A', Ra__A)

/** `Ra_init2()` */
export function Ra_init2(self: Ra__A): void {
  // Put far in front so doesn't draw behind walls
  GO_depth_init(self, DEPTH_FLYER)
  GO_set_sprite(self, 'spr_Ra2')
  self.DRAW_YOFF = 0
  self.VSPD_CHANGE = 2
  self.vspd_change = self.VSPD_CHANGE
  self.HSPD = 0x10
  self.VSPD_MAX = 0x30
  self.SPAWN_YOFF = 0x20
  switch (self.ver) {
    case 1:
      self.HSPD = 0x10
      self.VSPD_MAX = 0x30
      self.SPAWN_YOFF = 0x20
      break
    case 2:
      self.HSPD = 0x18
      self.VSPD_MAX = 0x2e
      self.SPAWN_YOFF = 0x24
      break
    case 3:
      self.HSPD = 0x18
      self.VSPD_MAX = 0x38
      self.SPAWN_YOFF = 0x30
      break
  }
  const P = pc()
  const exitEnter = g.exit_enter as { side: number } | null
  if (
    wINw(self.xl, self.ww, viewXL(), viewW()) &&
    P.state === P.state_SPAWN &&
    exitEnter &&
    exitEnter.side & 0x03
  ) {
    self.hspd = 0
    self.vspd = 0
    if (exitEnter.side & 0x01) set_xy(self, viewXL() - self.ww, self.y)
    else set_xy(self, viewXR() + self.ww, self.y)
    // To stop Ra_update() from activating Ra
    GO_update_cam_vars(self)
    g.view_at_rm_edge = exitEnter.side & 0x03
  }
}

/** `Ra_update_1a(cam is at room edge)` — BA2B: JSR B9F4, ACE5: JSR ACAD, 966D: JSR 963B */
export function Ra_update_1a(self: Ra__A, camAtEdge: number): void {
  const P = pc()
  let _DIR: number = P.hspd_dir
  if (gmBool(camAtEdge)) _DIR = sign_(camAtEdge & 0x02)
  let _X = viewXL() + self.ww_
  if (gmBool(_DIR)) _X = viewXR() - self.ww_ - 1
  _X += self.SPAWN_YOFF <= (P.yt & 0xff) ? 1 : 0 // carry
  if (gmBool(camAtEdge)) _X = viewXC() + (viewW_() + 0x10) * _DIR
  const _Y = P.yt + self.hh_ - self.SPAWN_YOFF
  set_xy(self, _X, _Y)
  self.facing_dir = dir_to_pc(self)
  self.hspd = (self.HSPD * self.facing_dir) & 0xff
  self.vspd = 0
  self.vspd_change = self.VSPD_CHANGE // 2
}
// OG variant (kept for reference): set_xlyt(self, viewXL()/viewXR()-$11 (+carry), (pc.yt&$FF)-SPAWN_YOFF)
export { set_xlyt as _Ra_set_xlyt }

/** `Ra_update()` */
export function Ra_update(self: Ra__A): void {
  const _IN_VIEW = ocsH1(self) // if any width is on camera
  const _CAM_AT_EDGE = g.view_at_rm_edge & 0x03
  // BA20, ACDA, 9667
  if (!_IN_VIEW) Ra_update_1a(self, _CAM_AT_EDGE) // BA2B
  if (_IN_VIEW || !_CAM_AT_EDGE) {
    // BA2E, ACE8, 9670
    if (!gmBool(self.stun_timer)) {
      // BA31, ACEB, 9673
      self.vspd = (self.vspd + self.vspd_change) & 0xff
      if (self.vspd === ((self.VSPD_MAX * sign(self.vspd_change)) & 0xff))
        self.vspd_change = -self.vspd_change
      // BA47
      updateY(self)
      updateX(self)
    }
    // BA4D: JSR DE40
    self.can_draw_self = ocsH1(self) && ocsV1(self) // if ANY w AND h in ocs area
    const _stun_timer_PREV = self.stun_timer
    GOB_update_2(self)
    if (!gmBool(_stun_timer_PREV) && self.cs & CS_BD1) enemy_collide_pc_body(self) // BA50: JMP D6C1
  }
}

registerScripts({ Ra_init2, Ra_update })
