/**
 * Ache / Acheman (ZALiA object `Ache01`, parent `Enemy`; ver 1 = Ache (blue bat), ver 2 = Acheman, OG eID $0A).
 * Ported from `Ache_init2.gml`, `Ache_update.gml`, `Ache_udp.gml`.
 */
import { Area_EastA, Area_TownA, CS_BD1, DEPTH_FLYER, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { byte, dir8b, gmBool, isVal } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { cam_x_range, cam_xl_min, cam_xr_max } from '../../../../../collision/env'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { bit_dir } from '../../../../../math/index'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { dir_to_pc } from '../../../../go/misc'
import { set_xlyt, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_depth_init, GO_set_sprite } from '../../../../go/sprite'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'
import { goDist1, projOf, rand } from './_shared'

export class Ache01 extends Enemy {
  readonly objectName = 'Ache01' as const
  SPR_IDLE = 'spr_Ache1'
  SPR_FLAP = 'spr_Ache2'
  ACHEMAN_DUR = 0x30
  acheManTimer = 0 // $00AF,X
  IDLE_Y = 0
  attack_dist = 0x20
}

/** `Ache_init2()` */
export function Ache_init2(self: Ache01): void {
  self.SPR_IDLE = 'spr_Ache1'
  self.SPR_FLAP = 'spr_Ache2'
  if (self.ver === 2) GO_init_palidx(self, G.PI_MOB_RED)
  else GO_init_palidx(self, G.PI_MOB_BLU)
  GO_depth_init(self, DEPTH_FLYER)
  self.projectile_OBJ = 'Fireball1'
  self.projectile_VER = 2
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.DRAW_YOFF = 0 // No in-ground +1
  self.yScale = -1
  self.ACHEMAN_DUR = 0x30
  self.acheManTimer = 0 // $00AF,X
  self.IDLE_Y = (self.yt >> 3) << 3
  self.attack_dist = 0x20
  if (self.ver === 1) {
    switch (g.area_name) {
      case Area_EastA:
        self.ATTACK_LEVEL = 0x02
        self.attack_level = self.ATTACK_LEVEL
        break
      case Area_TownA:
        self.ATTACK_LEVEL = 0x03
        self.attack_level = self.ATTACK_LEVEL
        break
    }
    if (g.area_name === Area_TownA) {
      self.HP_IDX = 0x00
      self.hp = g.dl_HP.get(self.HP_IDX) as number
    }
    switch (g.area_name) {
      case Area_EastA:
        self.XP_IDX = 0x05
        self.xp = g.dl_XP.get(self.XP_IDX) as number
        break
      case Area_TownA:
        self.XP_IDX = 0x00
        self.xp = g.dl_XP.get(self.XP_IDX) as number
        break
    }
    if (g.area_name === Area_TownA) {
      self.RESPAWN_TYPE = 0x00
      self.respawn_type = self.RESPAWN_TYPE
      self.DROP_BITS = 0x00
      self.drop_bits = self.DROP_BITS
    }
  }
}

/** `Ache_update()` */
export function Ache_update(self: Ache01): void {
  if (gmBool(self.stun_timer)) {
    // DBC8, DE40
    GOB_update_2(self)
    return
  }
  // DB53. ver 2: Acheman (OG eID $0A)
  if (self.ver === 2 && gmBool(self.acheManTimer)) {
    self.acheManTimer--
    if (self.acheManTimer === self.ACHEMAN_DUR >> 1 && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
      // if (acheManTimer == $18)
      GOC1_create(self.xl, self.yt + 2, self.facing_dir, projOf(self), self.projectile_ver)
    }
    // DB73
    self.facing_dir = dir_to_pc(self)
  } else {
    // if idle.    DB8B
    if (!gmBool(self.behavior)) {
      self.facing_dir = dir_to_pc(self)
      // Map Page (rm section)
      const _page_COUNT = cam_x_range() >> 8
      const _page_IDX = (self.xl >> 8) - (cam_xl_min() >> 8)
      const _IN_DIST = byte(goDist1(self) + self.attack_dist) < byte(self.attack_dist << 1)
      // if more than 2 sections, use OG rules
      const _C1 = _page_COUNT > 2
      // Must be in atk dist
      const _C2 = !_C1 || !isVal(_page_IDX, 0, _page_COUNT - 1)
      // For less than 3 rm sections and less than $80 from rm edge
      let _C3 = 0
      if (Math.abs(self.x - cam_xl_min()) < 0x80) _C3 = 1 // move right
      if (Math.abs(self.x - cam_xr_max()) < 0x80) _C3 = 2 // move left
      // Dir torwards pc, 1(right) or 2(left)
      const _C4 = dir8b(pc().x - self.x)
      // Each scenario. Only one can be positive.
      // Atk regardless of dist && rm has more than 2 sections
      let _A1 = +(!_C2 && _C1)
      // Atk if in dist && (rm has more than 2 sections || is more than $80 away from rm edge)
      let _A2 = +(_C2 && _IN_DIST && (_C1 || !_C3))
      // Atk if in dist && rm has less than 3 sections && less than $80 from rm edge && pc is on side of GOB w/ more rm space
      let _A3 = +(_C2 && _IN_DIST && !_C1 && _C3 === _C4)
      // Set atk dir. Only one will NOT be 0
      _A1 *= 1 + +(_page_IDX !== 0)
      _A2 *= 1 + +!(rand(self) & 0x1)
      _A3 *= _C3
      // 1 or 2. atk dir
      const _ATK_DIR = _A1 | _A2 | _A3 // *** this needs to use |, not ||
      if (_ATK_DIR) {
        // if idle && qualify to atk
        if (self.is_hostile || !(g.counter0 & 0x7f)) {
          self.hspd = (8 * bit_dir(_ATK_DIR)) & 0xff
          if (self.is_hostile) self.vspd = 0x40
          else self.vspd = 0x20
          self.behavior = 1 // ATTACK!!!
        }
      }
    }
    if (gmBool(self.behavior)) {
      // if attacking. DBA8
      updateX(self)
      self.vspd = (self.vspd - 1) & 0xff
      if (!self.vspd) self.acheManTimer = self.ACHEMAN_DUR
      updateY(self)
      if (self.yt < self.IDLE_Y) {
        set_xlyt(self, self.xl, self.IDLE_Y)
        self.vspd = 0
        self.behavior = 0 // set to idle
      }
    }
  }
  // DBC8
  GOB_update_2(self)
  if (self.cs & CS_BD1 && self.is_hostile) enemy_collide_pc_body(self)
}

/** `Ache_udp()` — F17E */
export function Ache_udp(self: Ache01): void {
  self.can_draw_self = true
  self.yScale = 1
  self.draw_yoff = 0
  if (self.ver === 2 && gmBool(self.acheManTimer)) {
    // Acheman
    GO_set_sprite(self, 'spr_Acheman1')
    self.draw_yoff = 8 + 2
  } else {
    // Ache
    if (gmBool(self.behavior) && g.counter1 & 0x8) GO_set_sprite(self, self.SPR_FLAP)
    else GO_set_sprite(self, self.SPR_IDLE)
    if (!gmBool(self.behavior)) self.yScale = -1
  }
}

registerObject('Ache01', Ache01)
registerScripts({ Ache_init2, Ache_update, Ache_udp })
