export class GeruA extends Enemy {
  readonly objectName = 'GeruA' as const
  attack_dist = 0x18
  VSPD_GRAV = 2
  armXOff1 = 8
  armXOff2 = 6
  armXOff3 = 2
  armXScale = -1
  armYScale = 1
  Arm_xoff = 8
  Arm_yoff = -8
  arm: string | 0 = 0
  lance1: string | 0 = 0
  lance2: string | 0 = 0
  ShieldHB_IDX_LOW = 1
  ShieldHB_IDX_HGH = 2
  SwordHB_XOFF = 6
  SwordHB_YOFF = 9
  SwordHB_W = 14
  SwordHB_H = 1
}

/** `Geru_init2()` — ver 1 orange/Lance, 2 red/Club, 3 blue/Mace1 (projectile) */
export function Geru_init2(self: GeruA): void {
  const g = gp()
  self.projectile_OBJ = 'Mace1'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.dl_sprites?.set(3, 'spr_Geru_2B') // shield up,   legs closed
  self.dl_sprites?.set(2, 'spr_Geru_2A') // shield up,   legs open
  self.dl_sprites?.set(1, 'spr_Geru_1B') // shield down, legs closed
  self.dl_sprites?.set(0, 'spr_Geru_1A') // shield down, legs open
  // 9F35. X = 2, 3, 5, 6; 9ED4,X: -6,-2, 6, 2
  self.armXOff1 = 8 + g.HB_ADJ_X // behavior 1, 4
  self.armXOff2 = 6 // behavior 2, 5
  self.armXOff3 = 2 // behavior 3, 6
  self.armXScale = -1
  self.armYScale = 1
  self.Arm_xoff = self.armXOff1
  self.Arm_yoff = -8
  self.arm = 0
  self.lance1 = 0
  self.lance2 = 0
  // shield hb
  self.ShieldHB_IDX_LOW = 1
  self.ShieldHB_IDX_HGH = 2
  self.ShieldHB_IDX = self.ShieldHB_IDX_LOW
  self.ShieldHB_idx = self.ShieldHB_IDX // 0444,X
  // sword hb
  self.SwordHB_XOFF = 6 + g.HB_ADJ_X
  self.SwordHB_YOFF = 9 + g.HB_ADJ_Y
  self.SwordHB_W = 14 + g.HB_ADJ_W
  self.SwordHB_H = 1 + g.HB_ADJ_H
  self.SwordHB_xoff = self.SwordHB_XOFF * self.facing_dir
  self.SwordHB_yoff = self.SwordHB_YOFF
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
}

/** `Geru_update()` */
export function Geru_update(self: GeruA): void {
  const g = gp()
  const P = pc()
  if (self.ver === 3)
    self.attack_dist = 0x40 // $1C Geru blue
  else self.attack_dist = 0x18 // Geru red & orange
  const _RAND = rand(self)
  // 9B56, 9B90
  update_EF11(self)
  if (gmBool(self.behavior)) {
    // 9B59. ---------------------   ATTACKING   -----------------------------------
    if (self.ver === 1) {
      // ------------------------ Geru (orange) ---------------------------
      if (self.behavior === 2 || self.behavior === 5) {
        // 9B65: JSR E563, E563: JSR E5F3
        if (!GOB_sword_collision_2a(self)) GOB_sword_collision_1a(self) // E579: JSR E5F3
      }
      // 9B68
      if (!self.timer) {
        self.behavior++
        if (self.behavior === 4 || self.behavior >= 7) self.behavior = 0
        else self.timer = 0xc
      }
    } else if (!self.timer) {
      // 9B93 ------------------------- Geru (red & blue) -----------------------------
      self.behavior++
      if (self.behavior === 4) {
        // 9D08
        self.behavior = 0
      } else if (self.behavior === 2) {
        // 9CD3
        update_EF11(self)
        // 9CD6: JSR E558
        if ((!(g.spells_active & SPL_RFLC) && !(fp().items & ITM_SHLD)) || !GOB_sword_collision_2a(self)) {
          GOB_sword_collision_1a(self) // E579: JSR E5F3
        }
        // 9CD9
        if (self.ver === 3 && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
          // Geru blue
          if (inRange(self.x, g.view_xl_og, g.view_xr_og) || Math.abs(self.x - P.x) < self.attack_dist) {
            let _XL = self.xl
            if (gmBool(self.facing_dir)) _XL += 0x10
            else _XL += -8
            GOC1_create(
              _XL,
              self.yt,
              self.facing_dir,
              self.projectile as ObjectName,
              self.projectile_ver,
              self,
              self.palidx_def,
            )
          }
          self.behavior = 0
        }
      }
      // 9D02
      if (gmBool(self.behavior)) self.timer = 5
    }
  }
  // 9BA2.  shld_hb_idx: 1 LOW, 2 HIGH
  if (input.Attack_pressed && _RAND & 0x3) {
    self.ShieldHB_idx = self.ShieldHB_IDX_LOW + (dHeld() ? 0 : 1) // Input.dHeld = 1 if down held, 0 if not
  }
  if (GOB_shield_collision_1a(self)) return // if PC sword collided enemy shield !!!!!!!!!!!!!!!!!!!!!!!!
  // 9BB7.   PC sword did NOT collide GOB shield -----------------
  GO_update_cs(self)
  GO_update_cam_vars(self)
  // 9D83
  if (self.yt >= cam_yb_max() + 0x18) {
    // Same as OG
    GOB_despawn(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  GOB_update_2a(self) // DE54 & DE63 collision
  if (gmBool(self.pc_sword_collided_solid_body)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // 9BE9.  update vertical -----------
  updateY(self)
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  }
  // 9BF5.  update horizontal --------
  const _hspdPB_COPY = self.hspd_pushback
  GOB_update_1(self, true) // update hspd_pushback
  if (!(self.cs & 0x3)) updateX(self)
  if (gmBool(_hspdPB_COPY)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // 9BF8
  self.facing_dir = dir_to_pc(self)
  // 9B96
  const _IN_DIST_ATCK = Math.abs(self.x - P.x) < self.attack_dist
  const _IN_DIST_AGRO = Math.abs(self.x - P.x) < 0x50
  if (_IN_DIST_ATCK || _IN_DIST_AGRO) {
    // 9C1C
    if (!gmBool(self.behavior) && gmBool(P.ogr)) {
      // PC off ground
      self.ShieldHB_idx = self.ShieldHB_IDX_LOW + (P.yt + 0xa < self.yt ? 1 : 0)
    }
    // ------------- Check to start attack -------------------
    if (!gmBool(self.behavior)) {
      // 9C34
      self.counter = (self.counter + 1) & 0xff
      const _val = self.ver === 1 ? 0x1f : 0x3f // Geru orange : red & blue
      if (!(self.counter & _val)) {
        // ------------------- START ATTACK ---------------------- 9C4A
        self.behavior = 1
        if (self.ver === 1) {
          // Geru orange
          if (_RAND & 0x1 || dHeld()) self.behavior = 4
        }
        self.timer = 0x18
      }
      if (!(self.counter & _val) && !(_RAND & 0x3)) self.counter = 0xc0
    }
    // ------------------ SET hspd ----------------------- 9C66
    if (P.cs & 0x3)
      self.hspd = 0 // CS_RGT|CS_LFT
    else if (gmBool(P.hspd) && hHeld()) self.hspd = P.hspd
    else self.hspd = (4 * sign_(g.counter1 & 0x40)) & 0xff
    self.hspd = (self.hspd >> 1) | (self.hspd & 0x80)
  }
  if (!_IN_DIST_ATCK) {
    // 9C0F
    if (_IN_DIST_AGRO) self.facing_dir = dir_to_pc(self)
    self.hspd = (0x10 * self.facing_dir) & 0xff
  }
}

/** `Geru_udp()` */
export function Geru_udp(self: GeruA): void {
  const g = gp()
  self.can_draw_self = true
  let _idx = 0
  if (self.ShieldHB_idx === self.ShieldHB_IDX_HGH) _idx += 2
  if (gmBool(self.hspd) && self.cs & 0x4 && !(g.counter1 & 0x8)) _idx += 1
  self.sprite = self.dl_sprites?.get(_idx) ?? 0 // 0,1,2,3
  self.arm = 0
  self.lance1 = 0
  self.lance2 = 0
  if (gmBool(self.behavior)) {
    if (self.ver === 2 && self.behavior === 3) {
      // Geru red, weapon: Club — arm & weapon behind, at side, no xoff
      self.armXScale = 1
      self.armYScale = 1
      self.Arm_xoff = 0
      self.Arm_yoff = 6
    } else {
      let _bvrXOff = 1
      if (self.behavior === 1 || self.behavior === 4) _bvrXOff = -1
      self.Arm_xoff = self.armXOff1 // 8
      if (self.behavior === 2 || self.behavior === 5) self.Arm_xoff = self.armXOff2 // 6
      if (self.behavior === 3 || self.behavior === 6) self.Arm_xoff = self.armXOff3 // 2
      if (self.ver === 2 || inRange(self.timer, 3, 8)) self.Arm_xoff = self.Arm_xoff << 1
      self.Arm_xoff *= _bvrXOff
      self.Arm_yoff = -8
      self.armXScale = -_bvrXOff
      self.armYScale = -_bvrXOff
    }
    self.Arm_xoff *= self.facing_dir
    self.armXScale *= self.facing_dir
    if (self.ver === 1) {
      if (self.behavior >= 4) self.Arm_yoff += 8
      self.armXScale *= -1
      self.armYScale = 1
      self.lance1 = 'spr_Lance_1B' // pole
      if (!(self.behavior === 1 || self.behavior === 4)) self.lance2 = 'spr_Lance_1A' // head
    } else {
      if (self.ver === 2 && self.behavior === 3) self.arm = 'spr_Mace1'
      else self.arm = 'spr_Geru_Arm1'
    }
  }
}

/** `Geru_draw()` */
export function Geru_draw(self: GeruA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawState.depth = self.depth
  pal_swap_set(self.palidx)
  draw_sprite_(
    self.arm,
    0,
    self.drawX + self.Arm_xoff,
    self.drawY + self.Arm_yoff,
    -1,
    self.armXScale,
    self.armYScale,
  )
  draw_sprite_(
    self.lance1,
    0,
    self.drawX + self.Arm_xoff,
    self.drawY + self.Arm_yoff,
    -1,
    self.armXScale,
    self.armYScale,
  )
  draw_sprite_(
    self.lance2,
    0,
    self.drawX + self.Arm_xoff,
    self.drawY + self.Arm_yoff,
    -1,
    self.armXScale,
    self.armYScale,
  )
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

// ------------------------------------------------------------------------------------------------ RockGeru
export class GeruB extends Enemy {
  readonly objectName = 'GeruB' as const
  control = 0 // 0444[eIndex]
  arm: string | 0 = 0
  Arm_xoff = 0
  Arm_yoff = 0
  armXScale = -1
  armYScale = 1
  rock: string | 0 = 0
  rockXOff = 0
  rockYOff = 0
  Wall_Y = 0
  Wall_XL = 0
  Wall_W = 0
  Wall_XR = 0
}

/** `RockGeru_init2()` */
export function RockGeru_init2(self: GeruB): void {
  const g = gp()
  self.projectile_OBJ = 'Rock3'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  GO_init_palidx(self, G.PI_MOB_RED)
  self.control = 0
  self.arm = 0
  self.Arm_xoff = 0
  self.Arm_yoff = 0
  self.armXScale = -1
  self.armYScale = 1
  self.rock = 0
  self.rockXOff = 0
  self.rockYOff = 0
  self.Wall_Y = self.spawn_yt
  self.Wall_XL = self.spawn_xl
  self.Wall_W = g.rm_w
  self.Wall_XR = self.Wall_XL + self.Wall_W
  switch (self.ver) {
    case 1: {
      GO_depth_init(self, DEPTH_BG5 + 3)
      self.Wall_XL = 0
      self.Wall_W = g.rm_w
      break
    }
    case 2: {
      // For Bulblin
      GO_depth_init(self, DEPTH_BG7 + 3)
      let _spawn_datakey = self.dk_spawn
      if (self.dk_spawn !== undefined) {
        const r = fp().dm_rando.get(
          STR_Randomize + STR_Enemy + STR_Spawn + self.dk_spawn + STR_Spawn + STR_Datakey + STR_Randomized,
        )
        _spawn_datakey = r !== undefined ? String(r) : self.dk_spawn
      }
      if (_spawn_datakey !== undefined) {
        for (let _i = 0x1; _i <= 0xf; _i++) {
          let _val = g.dm_spawn.get(_spawn_datakey + STR_Data + hexStr(_i)) ?? 0
          if (typeof _val === 'string') {
            let _pos = _val.indexOf(STR_Clms) + 1
            if (_pos) {
              _pos += STR_Clms.length
              _val = _val.substr(_pos - 1, _val.length - (_pos - 1))
              self.Wall_W = str_hex(_val) << 3
              break
            }
          }
        }
      }
      self.Wall_XR = self.Wall_XL + self.Wall_W
      break
    }
    default:
      break
  }
  self.Wall_XR = Math.max(self.Wall_XL, Math.min(self.Wall_XR, g.rm_w))
}

/** `RockGeru_update()` */
export function RockGeru_update(self: GeruB): void {
  const g = gp()
  const P = pc()
  const _RAND = rand(self)
  // 9730: JSR DC91
  self.facing_dir = dir_to_pc(self)
  // 9733
  if (gmBool(self.behavior)) {
    const _behaviorCopy = self.behavior
    if (!gmBool(self.control)) self.behavior = (self.behavior + 1) & 0xff
    if (!gmBool(self.control) && _behaviorCopy !== 2) {
      self.control = 0x10
      // 9748: JSR 9A11: JSR DBCE
      if (avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
        const _p = GOC1_create(
          self.xl,
          self.yt,
          self.facing_dir,
          self.projectile as ObjectName,
          self.projectile_ver,
        )
        // 974D
        let _diff = goDist1(self)
        if (_diff & 0x80) _diff ^= 0xff
        const _carry = _diff & 3 ? 1 : 0
        _diff = _diff >> 2
        if (!gmBool(self.facing_dir)) _diff ^= 0xff
        _p.hspd = byte(_diff + P.hspd + _carry)
        const _data = 'DCE4ECF4F8000000'
        const _idx = (P.yt >> 5) & 7
        _p.vspd = str_hex(_data, _idx)
      }
    } else {
      if (gmBool(self.control))
        self.control-- // 9773
      else self.behavior = 0 // 9778
    }
  }
  // 977C: JSR EF11
  update_EF11(self)
  // 977F
  switch (self.counter & 3) {
    case 0: {
      // 978E
      if (!self.timer) {
        let _x: number
        switch (self.ver) {
          case 1: {
            _x = _RAND >> 1
            let _carry: number = _RAND & 1
            _x += 0x40 + _carry
            _carry = _x > 0xff ? 1 : 0
            _x &= 0xff
            _x += P.hspd + _carry
            _carry = _x > 0xff ? 1 : 0
            _x &= 0xff
            _x += P.hspd + _carry
            _carry = _x > 0xff ? 1 : 0
            _x &= 0xff
            _x += P.hspd + _carry
            _carry = _x > 0xff ? 1 : 0
            _x &= 0xff
            _x += g.view_xl_og + _carry
            set_xlyt(self, _x, self.yt)
            self.timer = (_x & 0x1f) + 0x24
            break
          }
          case 2: {
            // wall is house
            if (!wINw(self.Wall_XL + 8, self.Wall_W - 0x10, viewXL(), viewW())) break
            const _W = Math.min(viewXR(), self.Wall_XR) - Math.max(viewXL(), self.Wall_XL)
            _x = Math.max(viewXL(), self.Wall_XL) + world.irandom(_W)
            if (gmBool(P.hspd)) _x += 8 * sign_(P.hspd < 0x80)
            _x = Math.max(self.Wall_XL, Math.min(_x, self.Wall_XR))
            set_xy(self, _x, self.y)
            self.timer = (world.irandom(0xff) & 0x1f) + 0x24
            break
          }
          default:
            break
        }
        self.counter = (self.counter + 1) & 0xff
      }
      break
    }
    case 1: {
      // 97B7
      if (gmBool(self.timer)) {
        if (self.yt >= self.Wall_Y - 4) set_xy(self, self.x, self.y - 1)
      } else self.counter = (self.counter + 1) & 0xff
      break
    }
    case 2: {
      // 97C8
      if (self.yt >= self.Wall_Y - 0xb) set_xy(self, self.x, self.y - 1)
      else {
        self.timer = (_RAND >> 1) | 0x40
        self.counter = (self.counter + 1) & 0xff
      }
      break
    }
    case 3: {
      // 97DA
      if (gmBool(self.timer)) {
        if (self.timer >= 0x11) {
          if (!gmBool(self.behavior)) {
            self.behavior = 1
            self.control = 0x10
          }
        } else set_xy(self, self.x, self.y + 1)
      } else {
        self.timer |= 0x40
        self.counter = (self.counter + 1) & 0xff
      }
      break
    }
    default:
      break
  }
}

/** `RockGeru_udp()` — 9D32 */
export function RockGeru_udp(self: GeruB): void {
  self.arm = 0
  self.rock = 0
  // 9D3D
  self.can_draw_self = true
  if (gmBool(self.behavior)) {
    self.arm = 'spr_Geru_Arm2'
    self.armXScale = self.xScale
    if (self.behavior === 2) self.armXScale = -self.xScale
    self.armYScale = 1
    if (self.behavior === 2) self.armYScale = -1
    self.Arm_xoff = 0 // -4
    if (self.control < 7) self.Arm_xoff = -8
    if (self.behavior === 2) self.Arm_xoff = 8
    self.Arm_xoff *= self.xScale
    self.Arm_yoff = 0
    if (self.behavior === 2) self.Arm_yoff = 3
    self.Arm_yoff += -8 // b/c arm spr is 16x16
    if (self.behavior === 1) {
      self.rock = 'spr_Rock1'
      self.rockXOff = self.Arm_xoff + 11 * -self.armXScale
      self.rockYOff = self.Arm_yoff - 4 - 0
    }
  }
}

/** `RockGeru_draw()` */
export function RockGeru_draw(self: GeruB): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawState.depth = self.depth
  pal_swap_set(self.palidx)
  draw_sprite_(
    self.arm,
    0,
    self.drawX + self.Arm_xoff,
    self.drawY + self.Arm_yoff,
    -1,
    self.armXScale,
    self.armYScale,
  )
  draw_sprite_(self.rock, 0, self.drawX + self.rockXOff, self.drawY + self.rockYOff, -1, self.xScale)
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

export function registerGeru(): void {
  registerObject('GeruA', GeruA)
  registerObject('GeruB', GeruB)
  registerScripts({
    Geru_init2,
    Geru_update,
    Geru_udp,
    Geru_draw,
    RockGeru_init2,
    RockGeru_update,
    RockGeru_udp,
    RockGeru_draw,
  })
}
registerGeru()
