/** `PC_update_2()`, `PC_update_2a()`, `PC_update_2b()` — the tail of the frame (D513…D530). */
import {
  BIT_ATK1,
  BIT_ATK2,
  BIT_ATK3,
  dk_StrikeSolid,
  ITM_GLOV,
  TID_BREAK1,
  TID_BREAK3,
  TID_SOLID1,
} from '@z2/data'
import { gmBool, isVal } from '../../../nes/math8'
import { f, g } from '../../../runtime/world'
import { is_in_grid, point_in_rect } from '../../collision/geometry'
import { collide_solid_grid, collide_solid_inst } from '../../collision/solid'
import { inRange } from '../../math/index'
import { aud_play_sound } from '../../sound/play'
import { get_audio_theme_track } from '../../sound/theme'
import { break_block } from '../../tile/tileOps'
import { GO_update_cam_vars } from '../go/misc'
import { PC_update_SwordHB_xy } from './attack'
import { pcHooks } from './deps'
import { PC_set_behavior } from './form'
import type { Lonk } from './Lonk'
import { instanceNamed } from './pc'
import { PC_udp } from './udp'

/** D513: landing crouch, then camera/draw/sword (2a) and the sword-vs-solid check (2b). */
export function PC_update_2(self: Lonk): void {
  if (self.landing_timer) {
    self.landing_timer--
    // MOD. Don't crouch if holding item
    if (!self.HoldItem_timer) PC_set_behavior(self.behavior_CROUCH)
  }
  // D51F
  if (gmBool(g.mod_PCUpdate1)) {
    // MOD: D52D: JSR EBF0 - camX, ocs, udp, update_swrdXY; D530 - scs (sword collide solid)
    PC_update_2a(self)
    PC_update_2b(self)
  } else {
    // OG. This will skip things like GO_update_cam_vars() and scs update every other frame when invulnerable_timer==1,2
    if (!inRange(self.iframes_timer, 1, 2) || !(g.counter1 & 0x1)) {
      PC_update_2a(self)
      PC_update_2b(self)
    }
  }
  pcHooks.update_explored_data()
}

/** EBF0 */
export function PC_update_2a(self: Lonk): void {
  if (self.in_restore_house) return
  GO_update_cam_vars(self) // EBFF: JSR F27D
  // EC02
  if (gmBool(g.mod_PCUpdate1)) {
    // MOD: transparent effect — skip the draw update on alternating frames while iframes_timer is 1,2
    if (!inRange(self.iframes_timer, 1, 2) || !(g.counter1 & 0x1)) PC_udp(self)
  } else {
    PC_udp(self) // OG
  }
  PC_update_SwordHB_xy(self) // EC7F
}

/** Last script of the game update. D530, D535: JSR E1DD, E1DD: JSR FFC9, E1E0: JSR E1E6 */
export function PC_update_2b(self: Lonk): void {
  if (!self.SwordHB_collidable || g.EnterRoom_control_timer) return
  const _YOFF_ATKH = 3 // BVR_ATK1. HGH
  const _YOFF_ATKL = 19 // BVR_ATK2. LOW
  const _YOFF_THDW = 36 // BVR_DWTH
  const _YOFF_THUP = -4 // BVR_UPTH
  // scs: Sword Collide Solid point
  const _DIST = 20
  switch (self.behavior) {
    case self.behavior_STAB_STAND:
      self.SCS_x = self.x + _DIST * self.xScale
      self.SCS_y = self.yt + _YOFF_ATKH
      break
    case self.behavior_STAB_CROUCH:
      self.SCS_x = self.x + _DIST * self.xScale
      self.SCS_y = self.yt + _YOFF_ATKL
      break
    case self.behavior_STAB_DOWN:
      self.SCS_x = self.x + 4
      self.SCS_y = self.yt + _YOFF_THDW
      break
    case self.behavior_STAB_UP:
      self.SCS_x = self.x + -2 + 4 * self.hspd_dir
      self.SCS_y = self.yt + _YOFF_THUP
      break
  }
  if (self.is_cucco) {
    if (self.attack_bits & (BIT_ATK1 | BIT_ATK2))
      self.SCS_x += (self.SwordHB_W - self.SwordHB_w) * -self.xScale
    if (self.attack_bits & BIT_ATK2) self.SCS_y = self.yt + _YOFF_ATKL - 8 // stab low
    if (self.attack_bits & BIT_ATK3) self.SCS_y = self.yt + _YOFF_THDW - 16 // downthrust
  }
  self.SCS_can_draw = true
  self.SCS_draw_x = self.SCS_x
  self.SCS_draw_y = self.SCS_y
  // --------------------------------------------------------------------
  let _scsX = self.SCS_x
  let _COUNT = 1 // OG
  _COUNT += Math.sign(self.attack_bits & (BIT_ATK1 | BIT_ATK2)) // MOD. thin solids: SCS_x may be beyond
  let hit = false
  for (let _i = 0; _i < _COUNT; _i++) {
    _scsX = self.SCS_x
    _scsX += (_i << 3) * -self.xScale
    if (collide_solid_grid(_scsX, self.SCS_y) === TID_SOLID1) {
      hit = true
      break
    }
    if (self.attack_bits & (BIT_ATK1 | BIT_ATK2)) {
      let _c1 = false
      if (collide_solid_inst(_scsX, self.SCS_y)) _c1 = true
      else {
        const ganon = instanceNamed('Ganon1')
        if (ganon && point_in_rect(_scsX, self.SCS_y, ganon.xl, ganon.yt, ganon.ww, ganon.hh)) _c1 = true
      }
      if (_c1) {
        aud_play_sound(get_audio_theme_track(dk_StrikeSolid))
        g.control1_timer = self.Pushback_DURATION
        self.hspd = (0xc * -self.xScale) & 0xff
        return
      }
    }
    if (_i + 1 === _COUNT) return
  }
  if (!hit) return
  // --------------------------------------------------------------------
  // E22A
  const _C1 = isVal(self.behavior, self.behavior_STAB_UP, self.behavior_STAB_DOWN)
  let _clm = _scsX >> 3
  let _row = self.SCS_y >> 3
  const B = g.dg_RmTile_Break
  const isBreak = (c: number, r: number) => isVal(Number(B.get(c, r) ?? 0) & 0xff, TID_BREAK1, TID_BREAK3)
  // $FFFF. 2 bytes contain tile id & g.dl_t_depth index
  if (
    is_in_grid(_clm, _row, g.rm_clms, g.rm_rows) &&
    isBreak(_clm, _row) &&
    f.items & ITM_GLOV &&
    (!self.is_cucco || (gmBool(g.CUCCO_CAN_BREAK1) && f.Cucco_skills & f.CuccoSkill_BREAK1))
  ) {
    if (_clm) {
      let _clm2 = _clm - 1
      while (isBreak(_clm2, _row)) {
        _clm2--
        if (!(_clm2 + 1)) break
      }
      _clm2++
      _clm -= (_clm & 1) !== (_clm2 & 1) ? 1 : 0
    }
    if (_row) {
      let _row2 = _row - 1
      while (isBreak(_clm, _row2)) {
        _row2--
        if (!(_row2 + 1)) break
      }
      _row2++
      _row -= (_row & 1) !== (_row2 & 1) ? 1 : 0
    }
    // E23A. break block
    break_block(_clm, _row)
    if (_C1) self.vspd = 0
  } else if (!_C1) {
    // E26A
    aud_play_sound(get_audio_theme_track(dk_StrikeSolid))
  }
  if (!_C1) {
    // E277. PC pushback. This timer prevents hspd being set to 0 when attacking and
    // allows hspd to be updated normally while attacking.
    g.control1_timer = self.Pushback_DURATION
    self.hspd = (0xc * -self.xScale) & 0xff
  }
}
