// Ported from ZALiA scripts/init_data_spells_1a.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively
import {
  Container_AMT,
  SPELL_COST_MAX,
  SPL_FARY,
  SPL_FIRE,
  SPL_JUMP,
  SPL_LIFE,
  SPL_PRTC,
  SPL_RFLC,
  SPL_SPEL,
  SPL_SUMM,
  SPL_THUN,
  STR_Cost,
  STR_Max,
  STR_Rando,
} from '@z2/data'
import { hexStr as hex_str } from '../../../nes/hexStr'
import { g } from '../../../runtime/world'
import { bitNum } from '../../math/index'
import { notPorted } from '../../pending'
import { ds_grid_copy, min } from '../gm'

export function init_data_spells_1a() {
  // GML `var` is function-scoped; locals hoisted here:
  let _DK: any, _MAX: any, _idx: any, _val: any
  // ***** Keep mp even because spell costs are drawn as half of what the
  // actual values are. Pause menu could show that the player has the
  // exact mp to cast a spell but the spell is actually costs +1 more
  // 0E48DA80AE0F0AE2003071200F08E300D20E1D600E08D2089473F4158237F41F8638FA1B7237630F089774E300DE0E24600E08D40860016B02D10E84919091D6
  /*
8D7B-8DBA:  $40 bytes
403030202020202060504040282018108C8C787864646464A0A0787850505050F0A0783C20202020F0F0A06050403020F0E0C0A060403020F0F0F0F0F0F0C880
40 30 30 20 20 20 20 20     
60 50 40 40 28 20 18 10     
8C 8C 78 78 64 64 64 64     
A0 A0 78 78 50 50 50 50     
F0 A0 78 3C 20 20 20 20     
F0 F0 A0 60 50 40 30 20     
F0 E0 C0 A0 60 40 30 20     
F0 F0 F0 F0 F0 F0 C8 80     
*/
  // let _idx: any, _val: any;
  _MAX = SPELL_COST_MAX
  // dg_spell_cost: width = spell num(1-8), height = magic_lvl_idx(0-7)
  // column 0 of dg_spell_cost is intentionally skipped. 1st spell is column 1.
  _idx = 0
  g.dg_spell_cost.set(_idx, 0, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 1, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 2, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 3, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 4, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 5, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 6, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 7, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 8, _MAX) // $F0(240) >>1 = 120
  // PROTECT/SHIELD - $40, $30, $30, $20, $20, $20, $20, $20
  _idx = bitNum(SPL_PRTC)
  g.dg_spell_cost.set(_idx, 0, 0x40) // $40( 64) >>1 =  32
  g.dg_spell_cost.set(_idx, 1, 0x30) // $30( 48) >>1 =  24
  g.dg_spell_cost.set(_idx, 2, 0x30) // $30( 48) >>1 =  24
  g.dg_spell_cost.set(_idx, 3, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 4, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 5, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 6, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 7, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 8, 0x18) // $18( 24) >>1 =  12
  // JUMP - $60, $50, $40, $40, $28, $20, $18, $10
  _idx = bitNum(SPL_JUMP)
  g.dg_spell_cost.set(_idx, 0, 0x60) // $60( 96) >>1 =  48
  g.dg_spell_cost.set(_idx, 1, 0x50) // $50( 80) >>1 =  40
  g.dg_spell_cost.set(_idx, 2, 0x40) // $40( 64) >>1 =  32
  g.dg_spell_cost.set(_idx, 3, 0x40) // $40( 64) >>1 =  32
  g.dg_spell_cost.set(_idx, 4, 0x28) // $28( 40) >>1 =  20
  g.dg_spell_cost.set(_idx, 5, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 6, 0x18) // $18( 24) >>1 =  12
  g.dg_spell_cost.set(_idx, 7, 0x10) // $10( 16) >>1 =  08
  g.dg_spell_cost.set(_idx, 8, 0x0c) // $0C( 12) >>1 =  06
  // HEAL/LIFE - $8C, $8C, $78, $78, $64, $64, $64, $64
  _idx = bitNum(SPL_LIFE)
  g.dg_spell_cost.set(_idx, 0, 0x8c) // $8C(140) >>1 =  70
  g.dg_spell_cost.set(_idx, 1, 0x8c) // $8C(140) >>1 =  70
  g.dg_spell_cost.set(_idx, 2, 0x78) // $78(120) >>1 =  60
  g.dg_spell_cost.set(_idx, 3, 0x78) // $78(120) >>1 =  60
  g.dg_spell_cost.set(_idx, 4, 0x64) // $64(100) >>1 =  50
  g.dg_spell_cost.set(_idx, 5, 0x64) // $64(100) >>1 =  50
  g.dg_spell_cost.set(_idx, 6, 0x64) // $64(100) >>1 =  50
  g.dg_spell_cost.set(_idx, 7, 0x64) // $64(100) >>1 =  50
  g.dg_spell_cost.set(_idx, 8, 0x50) // $50( 80) >>1 =  40
  // FAIRY - $A0, $A0, $78, $78, $50, $50, $50, $50
  _idx = bitNum(SPL_FARY)
  g.dg_spell_cost.set(_idx, 0, 0xa0) // $A0(160) >>1 =  80
  g.dg_spell_cost.set(_idx, 1, 0xa0) // $A0(160) >>1 =  80
  g.dg_spell_cost.set(_idx, 2, 0x78) // $78(120) >>1 =  60
  g.dg_spell_cost.set(_idx, 3, 0x78) // $78(120) >>1 =  60
  g.dg_spell_cost.set(_idx, 4, 0x50) // $50( 80) >>1 =  40
  g.dg_spell_cost.set(_idx, 5, 0x50) // $50( 80) >>1 =  40
  g.dg_spell_cost.set(_idx, 6, 0x50) // $50( 80) >>1 =  40
  g.dg_spell_cost.set(_idx, 7, 0x50) // $50( 80) >>1 =  40
  g.dg_spell_cost.set(_idx, 8, 0x3c) // $3C( 60) >>1 =  30
  // FIRE - $F0, $A0, $78, $3C, $20, $20, $20, $20
  _idx = bitNum(SPL_FIRE)
  g.dg_spell_cost.set(_idx, 0, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 1, 0xa0) // $A0(160) >>1 =  80
  g.dg_spell_cost.set(_idx, 2, 0x78) // $78(120) >>1 =  60
  g.dg_spell_cost.set(_idx, 3, 0x3c) // $3C( 60) >>1 =  30
  g.dg_spell_cost.set(_idx, 4, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 5, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 6, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 7, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 8, 0x18) // $18( 24) >>1 =  12
  // REFLECT - $F0, $F0, $A0, $60, $50, $40, $30, $20
  _idx = bitNum(SPL_RFLC)
  g.dg_spell_cost.set(_idx, 0, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 1, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 2, 0xa0) // $A0(160) >>1 =  80
  g.dg_spell_cost.set(_idx, 3, 0x60) // $60( 96) >>1 =  48
  g.dg_spell_cost.set(_idx, 4, 0x50) // $50( 80) >>1 =  40
  g.dg_spell_cost.set(_idx, 5, 0x40) // $40( 64) >>1 =  32
  g.dg_spell_cost.set(_idx, 6, 0x30) // $30( 48) >>1 =  24
  g.dg_spell_cost.set(_idx, 7, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 8, 0x18) // $18( 24) >>1 =  12
  // ENIGMA/SPELL - $F0, $E0, $C0, $A0, $60, $40, $30, $20
  _idx = bitNum(SPL_SPEL)
  g.dg_spell_cost.set(_idx, 0, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 1, 0xe0) // $E0(224) >>1 = 112
  g.dg_spell_cost.set(_idx, 2, 0xc0) // $C0(192) >>1 =  96
  g.dg_spell_cost.set(_idx, 3, 0xa0) // $A0(160) >>1 =  80
  g.dg_spell_cost.set(_idx, 4, 0x60) // $60( 96) >>1 =  48
  g.dg_spell_cost.set(_idx, 5, 0x40) // $40( 64) >>1 =  32
  g.dg_spell_cost.set(_idx, 6, 0x30) // $30( 48) >>1 =  24
  g.dg_spell_cost.set(_idx, 7, 0x20) // $20( 32) >>1 =  16
  g.dg_spell_cost.set(_idx, 8, 0x18) // $18( 24) >>1 =  12
  // THUNDER - $F0, $F0, $F0, $F0, $F0, $F0, $C8, $80
  _idx = bitNum(SPL_THUN)
  g.dg_spell_cost.set(_idx, 0, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 1, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 2, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 3, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 4, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 5, _MAX) // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 6, 0xc8) // $C8(200) >>1 = 100
  g.dg_spell_cost.set(_idx, 7, 0x80) // $80(128) >>1 =  64
  g.dg_spell_cost.set(_idx, 8, 0x60) // $60( 96) >>1 =  48
  // SUMMON
  _val = 0x60
  _idx = bitNum(SPL_SUMM) // $60( 96) >>1 =  48
  //_val=$80;      _idx=bitNum(SPL_SUMM); // $80(128) >>1 =  64
  //_val=$F0;      _idx=bitNum(SPL_SUMM); // $F0(240) >>1 = 120
  g.dg_spell_cost.set(_idx, 0, _val)
  g.dg_spell_cost.set(_idx, 1, _val)
  g.dg_spell_cost.set(_idx, 2, _val)
  g.dg_spell_cost.set(_idx, 3, _val)
  g.dg_spell_cost.set(_idx, 4, _val)
  g.dg_spell_cost.set(_idx, 5, _val)
  g.dg_spell_cost.set(_idx, 6, _val)
  g.dg_spell_cost.set(_idx, 7, _val)
  g.dg_spell_cost.set(_idx, 8, _val)
  ds_grid_copy(g.dg_spell_cost_DEFAULT, g.dg_spell_cost)
  _DK = STR_Rando + STR_Cost + STR_Max
  g.dm_Spell.set(hex_str(0x00) + _DK, min(Container_AMT * 3, g.dg_spell_cost.get(0, 0)))
  g.dm_Spell.set(hex_str(SPL_PRTC) + _DK, min(Container_AMT * 3, g.dg_spell_cost.get(bitNum(SPL_PRTC), 0)))
  g.dm_Spell.set(hex_str(SPL_JUMP) + _DK, min(Container_AMT * 3, g.dg_spell_cost.get(bitNum(SPL_JUMP), 0)))
  g.dm_Spell.set(hex_str(SPL_LIFE) + _DK, min(Container_AMT * 3, g.dg_spell_cost.get(bitNum(SPL_LIFE), 0)))
  g.dm_Spell.set(hex_str(SPL_FARY) + _DK, min(Container_AMT * 4, g.dg_spell_cost.get(bitNum(SPL_FARY), 0)))
  g.dm_Spell.set(hex_str(SPL_FIRE) + _DK, min(Container_AMT * 2, g.dg_spell_cost.get(bitNum(SPL_FIRE), 0)))
  g.dm_Spell.set(hex_str(SPL_RFLC) + _DK, min(Container_AMT * 3, g.dg_spell_cost.get(bitNum(SPL_RFLC), 0)))
  g.dm_Spell.set(hex_str(SPL_SPEL) + _DK, min(Container_AMT * 3, g.dg_spell_cost.get(bitNum(SPL_SPEL), 0)))
  g.dm_Spell.set(hex_str(SPL_THUN) + _DK, min(Container_AMT * 5, g.dg_spell_cost.get(bitNum(SPL_THUN), 0)))
  g.dm_Spell.set(hex_str(SPL_SUMM) + _DK, min(Container_AMT * 3, g.dg_spell_cost.get(bitNum(SPL_SUMM), 0)))
}
