/** Mau (`Mau_A`) — the flying bullet-shooter (v2 flips behind Link). Ported from `Mau_init2/update/udp.gml`. */
import { CS_BD1, DEPTH_FLYER, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { abs8b } from '../../../../../../nes/math8'
import { G } from '../../../../../../runtime/world'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { dir_to_pc_, is_facing_pc } from '../../../../go/misc'
import { set_xy, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_depth_init } from '../../../../go/sprite'
import type { ObjectName } from '../../../../objectNames'
import { pc } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'

export class Mau_A extends Enemy {
  readonly objectName = 'Mau_A' as const
  HSPD1 = 0x08
  VSPD1 = 0x08
  MIN_DIST = 0x18
}

/** `Mau_init2()` */
export function Mau_init2(self: Mau_A): void {
  self.dl_sprites?.set(0, 'spr_Mau1')
  GO_init_palidx(self, G.PI_MOB_RED)
  GO_depth_init(self, DEPTH_FLYER)
  self.facing_dir = dir_to_pc_(self)
  self.counter = 0xff
  self.projectile_OBJ = 'Bullet1'
  self.projectile_VER = 2
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  const _SPEED = 0x08
  self.HSPD1 = _SPEED
  self.VSPD1 = _SPEED
  if (self.ver === 2) {
    self.hspd = (self.HSPD1 * self.facing_dir) & 0xff
    self.MIN_DIST = 0x18
  }
}

/** `Mau_update()` — B8BB: JSR DE40 */
export function Mau_update(self: Mau_A): void {
  const P = pc()
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  self.counter = (self.counter + 1) & 0xff
  // B8CD
  if (!(self.counter & 0x3f) && is_facing_pc(self) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
    // every 64 frames. 1.067s. Bullet1
    GOC1_create(
      self.xl,
      self.yt,
      self.facing_dir,
      self.projectile as ObjectName,
      self.projectile_ver,
      self,
      G.PI_MOB_BLU,
    )
  }
  if (self.counter & 0x20) {
    // For 0.533s.   $20-3F, $60-7F, $A0-BF, $E0-FF. B8F0
    if (self.counter & 0x40)
      self.vspd = -self.VSPD1 & 0xff // counter: $60-7F, $E0-FF
    else self.vspd = self.VSPD1 & 0xff // counter: $20-3F, $A0-BF
    updateY(self)
  } else {
    // For 0.533s.   $00-1F, $40-5F, $80-9F, $C0-DF. B8ED
    updateX(self)
  }
  if (self.ver === 2 && self.facing_dir === P.facing_dir) {
    const _DIST = Math.abs(P.x - self.x)
    if (_DIST >= self.MIN_DIST) {
      // FLIP_DIST = $18;
      self.facing_dir = -P.facing_dir
      self.hspd = (abs8b(self.hspd) * self.facing_dir) & 0xff
      const _X = P.x + _DIST * P.facing_dir
      set_xy(self, _X, self.y)
    }
  }
}

/** `Mau_udp()` */
export function Mau_udp(self: Mau_A): void {
  self.can_draw_self = true
}

export function registerMau(): void {
  registerObject('Mau_A', Mau_A)
  registerScripts({ Mau_init2, Mau_update, Mau_udp })
}
registerMau()
