import { g } from '../../runtime/world'

/** `can_update_frame()` — false while the dev frame-step pause is active (`g.app_paused`) unless advancing one frame. */
export function can_update_frame(): boolean {
  const gg = g as unknown as { app_paused?: boolean; app_adv_frame?: boolean }
  return !gg.app_paused || !!gg.app_adv_frame
}
