/**
 * `hex_str(number, *charCount)` — ZALiA's universal number→datakey formatter.
 * Uppercase hex, 32-bit, padded to an even length by default, or to exactly `chars` (1–8)
 * digits — truncating from the left when too long, exactly like the GML.
 */
export function hexStr(value: number | string, chars?: number): string {
  if (typeof value === 'string') return value
  let n = value >>> 0 // limit to 32 bits (GML: `&= $FFFFFFFF`)
  const width = chars === undefined ? undefined : Math.min(8, Math.max(1, chars))
  if (n === 0) return width === undefined ? '00' : '0'.repeat(width)
  let s = ''
  while (n !== 0) {
    s = '0123456789ABCDEF'[n & 0xf] + s
    n >>>= 4
  }
  if (width !== undefined) {
    if (s.length < width) s = '0'.repeat(width - s.length) + s
    else if (s.length > width) s = s.slice(s.length - width)
  } else if (s.length & 1) {
    s = `0${s}`
  }
  return s
}
