/**
 * Blaze / Flame (ZALiA object `Blaze01`, parent `Enemy`): v1 stationary flame, v2 jumping flame that leaves
 * little flames behind, v3-5 fading fires, v6 the Old Kasuto fires. `Blaze_init1/init2/update/udp/draw/end.gml`.
 * `Blaze_end` only destroyed `dg_kids` (GC here).
 */
import {
  ABL_JUMP,
  CS_BD1,
  CS_PR1,
  CS_SW1,
  DEPTH_BG4,
  dk_StrikeEnemy,
  OGR_JUMP,
  OGR_OTHR,
  STR_Size,
} from '@z2/data'
import { abs8b, byte, gmBool, isVal } from '../../../../../../nes/math8'
import { DsGrid } from '../../../../../../runtime/ds'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { rectInRect } from '../../../../../collision/geometry'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { sign_ } from '../../../../../math/index'
import { play_theme_sound } from '../../../../../sound/play'
import { Enemy } from '../../../../classes'
import { draw_sprite_, GO_draw_sprite } from '../../../../go/draw'
import { dir_to_pc_ } from '../../../../go/misc'
import { GO_vspd_update1, set_xlyt, set_xy, updateX, updateY } from '../../../../go/movement'
import { GO_depth_init, GO_sprite_init } from '../../../../go/sprite'
import { solid_clip_correction } from '../../../../goa/movement'
import { pc } from '../../../../goa/pc'
import { HostileFire_init_1, HostileFire_udp_1 } from '../../../../goc/Projectile'
import { registerObject, registerScripts } from '../../../../registry'
import { GameObjectB_init, GOB_update_2, update_EF11 } from '../../../GameObjectB'
import { rand, randoSpawnDatakey, spawnDataHex } from '../ache/_shared'

export class Blaze01 extends Enemy {
  readonly objectName = 'Blaze01' as const
  HSPD_JUMP_DEF = 0x10
  HSPD_JUMP_1 = 0x20
  HSPD_JUMP_2 = 0x30
  hspd_jump = 0x10
  VSPD_JUMP_1 = 0xe5
  VSPD_JUMP_2 = 0xd0
  vspd_jump = 0xe5
  vspd_MAX = 0x7 << 4
  DUR_DELAY_JUMP = 0x80
  ANIM_SPEED = 0x04
  DUR_FADE1 = 0x30
  DRAW_CUE1 = (0x30 >> 3) * 3
  can_leave_kid = false
  size = 2
  SPR_KID = 'spr_Flame_Small_1a'
  DUR_KID = 0x40
  KID_CUE1 = (0x40 >> 3) * 3
  /** [i, 0] = timer, [i, 1] = x, [i, 2] = y for each little flame left behind (ver 2). */
  dg_kids: DsGrid<number> | undefined = undefined
  // HostileFire palette permutations (HostileFire_init_1)
  PI1 = 0
  PI2 = 0
  PI3 = 0
}

/** `Blaze_init1()` */
export function Blaze_init1(self: Blaze01): void {
  GameObjectB_init(self)
  self.HSPD_JUMP_DEF = 0x10
  self.HSPD_JUMP_1 = 0x20
  self.HSPD_JUMP_2 = 0x30
  self.hspd_jump = self.HSPD_JUMP_DEF
  self.VSPD_JUMP_1 = 0xe5
  self.VSPD_JUMP_2 = 0xd0
  self.vspd_jump = self.VSPD_JUMP_1
  self.vspd_MAX = 0x7 << 4
  self.DUR_DELAY_JUMP = 0x80
  self.ANIM_SPEED = 0x04
  self.DUR_FADE1 = 0x30
  self.DRAW_CUE1 = (self.DUR_FADE1 >> 3) * 3
  self.can_leave_kid = false
  self.size = 2
}

/** `Blaze_init2()` */
export function Blaze_init2(self: Blaze01): void {
  switch (self.ver) {
    case 1: {
      // OG. Stationary Flame
      GO_sprite_init(self, 'spr_Flame1')
      HostileFire_init_1(self as never, G.PI_MOB_RED)
      self.hspd = 0
      break
    }
    case 2: {
      // Jumping Flame
      GO_sprite_init(self, 'spr_Flame1')
      HostileFire_init_1(self as never, G.PI_MOB_ORG)
      self.abilities |= ABL_JUMP
      self.SPR_KID = 'spr_Flame_Small_1a'
      self.DUR_KID = 0x40
      self.KID_CUE1 = (self.DUR_KID >> 3) * 3
      self.dg_kids = new DsGrid<number>(3, 3, 0)
      break
    }
    case 3:
      GO_sprite_init(self, 'spr_Fire_1a_2')
      break
    case 4:
      GO_sprite_init(self, 'spr_Flame1')
      break
    case 5:
      GO_sprite_init(self, 'spr_Flame_Small_1b')
      break
    case 6: {
      // Fires in Old Kasuto
      self.size = 2
      const _spawn_datakey = randoSpawnDatakey(self.dk_spawn)
      self.size = spawnDataHex(_spawn_datakey, STR_Size, self.size)
      self.size = Math.max(1, Math.min(3, self.size))
      switch (self.size) {
        case 1:
          GO_sprite_init(self, 'spr_Flame_Small_1b')
          self.BodyHB_IDX = 0x56
          break
        case 2:
          GO_sprite_init(self, 'spr_Flame1')
          self.BodyHB_IDX = 0x30
          break
        case 3:
          GO_sprite_init(self, 'spr_Fire_1a_2')
          self.BodyHB_IDX = 0x01
          break
      }
      set_xlyt(self, self.spawn_xl, self.spawn_yt)
      GO_depth_init(self, DEPTH_BG4 + 1)
      self.BodyHB_idx = self.BodyHB_IDX
      self.hspd = 0
      self.ATTACK_LEVEL = 0
      self.attack_level = self.ATTACK_LEVEL
      break
    }
  }
  if (self.ver === 3 || self.ver === 4 || self.ver === 5) {
    self.ANIM_SPEED = 0x08
    self.hspd = 0
    self.vspd = 0
    set_xlyt(self, self.spawn_xl, self.spawn_yt)
  }
  self.DRAW_YOFF = 0 // MOD. No +1 in ground
  self.DRAW_CUE1 = (self.DUR_FADE1 >> 3) * 3
  self.can_leave_kid = self.dg_kids !== undefined
}

/** `Blaze_update()` — B485: JSR D959: JSR DE3D */
export function Blaze_update(self: Blaze01): void {
  const P = pc()
  GO_update_cs(self)
  if (self.can_leave_kid && self.dg_kids) {
    const kids = self.dg_kids
    for (let _i = kids.width - 1; _i >= 0; _i--) {
      if (kids.get(_i, 0)) kids.set(_i, 0, (kids.get(_i, 0) as number) - 1)
      if (!kids.get(_i, 0)) continue
      if (
        !gmBool(P.ogr) &&
        rectInRect(
          (kids.get(_i, 1) as number) - 2,
          (kids.get(_i, 2) as number) - 2,
          4,
          4,
          P.x - 6,
          P.yt,
          12,
          P.hh,
        )
      ) {
        // PC can put out flame.
        kids.set(_i, 0, 0)
      }
    }
  }
  // ===================================================================
  if (self.ver === 1 || self.ver === 2) {
    GOB_update_2(self)
    // D95C
    if (self.cs & 0x4) {
      solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
      if (self.vspd > 0x0e) {
        if (abs8b(self.hspd) === self.hspd_jump) self.hspd = (self.hspd >> 1) | (self.hspd & 0x80)
        // BOUNCE -------
        set_xy(self, self.x, self.y - 1)
        if (self.vspd > 0x30) self.vspd = 0xf1
        else self.vspd = 0xf8
      } else {
        self.hspd = 0
        self.vspd = 0
        if (self.abilities & ABL_JUMP && !gmBool(self.timer) && !gmBool(self.ogr)) {
          self.hspd = (self.hspd_jump * dir_to_pc_(self)) & 0xff
          self.vspd = self.vspd_jump
          if (self.can_leave_kid && self.dg_kids) {
            const kids = self.dg_kids
            for (let _i = kids.width - 1; _i >= 0; _i--) {
              if (kids.get(_i, 0)) continue
              // Leave a little flame behind each jump.
              kids.set(_i, 0, self.DUR_KID)
              kids.set(_i, 1, self.x)
              kids.set(_i, 2, self.yt + self.hh - 2)
              break
            }
          }
          self.ogr = OGR_JUMP
        } else {
          if (self.abilities & ABL_JUMP && gmBool(self.ogr)) {
            self.timer = self.DUR_DELAY_JUMP
            if (self.ogr === OGR_OTHR) self.timer -= 0x20
            else if (!(rand(self) & 0x3)) self.timer += 0x20 * sign_(g.counter1 & 0x1) // 25% chance
          }
          self.ogr = 0
        }
      }
    } else {
      if (!gmBool(self.ogr)) self.ogr = OGR_OTHR
      self.vspd = (self.vspd + 1) & 0xff
      // Prevent from doing endless wave
      if ((abs8b(self.vspd) & 0x7f) >= self.vspd_MAX)
        self.vspd = byte(self.vspd_MAX * sign_(self.vspd < 0x80))
    }
    if (self.cs & 0x3 && self.vspd < 0x80) self.hspd = 0x0
    if (!(self.cs & 0x3)) updateX(self)
    updateY(self)
    // B488: JMP D6C1
    if (self.cs & CS_BD1) enemy_collide_pc_body(self)
    GO_vspd_update1(self) // if (cs8() && vspd&$80) vspd=$0;
  }
  // ===================================================================
  if (self.ver === 3 || self.ver === 4 || self.ver === 5) {
    if (gmBool(self.timer)) {
      update_EF11(self)
      if (self.timer === 1) {
        self.hp = 0
        self.state = 0
      }
    } else {
      const _PC_REACT = 2
      const _PC_VSPD = P.vspd
      GOB_update_2(self)
      self.stun_timer = 0
      if (self.cs & (CS_BD1 | CS_SW1 | CS_PR1)) self.timer = self.DUR_FADE1
      if (isVal(self.ver, 3, 4) && self.cs & (CS_SW1 | CS_PR1)) play_theme_sound(dk_StrikeEnemy)
      if (isVal(self.ver, 3, 4) && self.cs & CS_BD1) enemy_collide_pc_body(self)
      if (_PC_REACT === 2 || (_PC_REACT === 1 && self.ver === 5)) {
        if (self.cs & CS_SW1 && isVal(P.behavior, P.behavior_STAB_UP, P.behavior_STAB_DOWN)) P.vspd = _PC_VSPD
      }
    }
    self.hp = 0xff
  }
  if (self.ver === 6) {
    if (self.size !== 1) GOB_update_2(self)
    else update_EF11(self)
    self.hspd = 0
    if (self.cs & CS_BD1) {
      if (self.size === 1) self.state = 0
      else enemy_collide_pc_body(self)
    }
  }
}

/** `Blaze_udp()` */
export function Blaze_udp(self: Blaze01): void {
  self.can_draw_self = true
  self.xScale = g.counter1 & self.ANIM_SPEED ? 1 : -1
  if (self.ver === 3 || self.ver === 4 || self.ver === 5) {
    if (gmBool(self.timer) && self.timer & (self.ANIM_SPEED >> 2)) self.can_draw_self = false
  }
  HostileFire_udp_1(self as never)
}

/** `Blaze_draw()` */
export function Blaze_draw(self: Blaze01): void {
  if (self.can_leave_kid && self.dg_kids) {
    const kids = self.dg_kids
    for (let _i = kids.width - 1; _i >= 0; _i--) {
      const t = kids.get(_i, 0) as number
      if (!t || (t < self.KID_CUE1 && g.counter1 & (self.ANIM_SPEED >> 1))) continue
      draw_sprite_(
        self.SPR_KID,
        0,
        kids.get(_i, 1) as number,
        kids.get(_i, 2) as number,
        self.palidx,
        sign_(!(g.counter1 & self.ANIM_SPEED)),
        1,
        self.depth,
      )
    }
  }
  if (!self.can_draw_self) return
  GO_draw_sprite(self, self.sprite, self.palidx)
}

/** `Blaze_end()` — freed `dg_kids` in ZALiA; nothing to do here. */
export function Blaze_end(self: Blaze01): void {
  self.dg_kids = undefined
}

registerObject('Blaze01', Blaze01)
registerScripts({ Blaze_init1, Blaze_init2, Blaze_update, Blaze_udp, Blaze_draw, Blaze_end })
