  STR_Active,
  STR_Audio,
  STR_Background,
  STR_Bloom,
  STR_Blur,
  STR_Brightness,
  STR_Count,
  STR_Cucco,
  STR_Current,
  STR_Custom,
  STR_Dialogue,
  STR_Dungeon,
  STR_Enemy,
  STR_Exit,
  STR_Flashing,
  STR_Font,
  STR_Frame,
  STR_Frenzy,
  STR_Fullscreen,
  STR_Game,
  STR_Halloween,
  STR_Hidden,
  STR_Hint,
  STR_HUD,
  STR_Idx,
  STR_Indicate,
  STR_Input,
  STR_Key,
  STR_Lighting,
  STR_Map,
  STR_Mark,
  STR_Music,
  STR_Overworld,
  STR_Palette,
  STR_PC,
  STR_Preference,
  STR_Preferences,
  STR_Quest,
  STR_Rando,
  STR_Random,
  STR_Saturation,
  STR_Scale,
  STR_Scanlines,
  STR_Scene,
  STR_Screen,
  STR_Set,
  STR_Shake,
  STR_Show,
  STR_Speed,
  STR_Spell,
  STR_Sprite,
  STR_Stab,
  STR_State,
  STR_Tileset,
  STR_Timer,
  STR_Torch,
  STR_TSRC,
  STR_Type,
  STR_Window,
