/** GML: RebonackA_init2() */
export function RebonackA_init2(self: Rebonack01A) {
  let _i: any, _a: any, _idx: any, _val: any, _pi: any, _pi_permut: any, _PAL: any, _DIST: any

  // ver 1: Normal
  // ver 2: Dark Knight

  Boss_init_2(self)
  GO_init_palidx(self, G.PI_MOB_BLU)
  // dark knight
  if (self.ver === 2) {
    GO_init_palidx(self, G.PI_MOB_PUR)
    _PAL = build_pal(p.C_WHT1, p.C_BLK1, p.C_VLT4, p.C_BLK1, -2, -2, -2, -2)
    /*
    //var _PAL = p.CI_BLK1_ + p.CI_WHT2_ + p.CI_BLK1_ + p.CI_VLT4_;
    //var _PAL = p.CI_BLK1_ + p.CI_WHT2_ + p.CI_VLT4_ + p.CI_BLK1_;
    //var _PAL = p.CI_BLK1_ + p.CI_WHT2_ + p.CI_BLK1_ + p.CI_RED4_;
    //var _PAL = p.CI_BLK1_ + p.CI_WHT2_ + p.CI_RED4_ + p.CI_BLK1_;
    //var _PAL = p.CI_BLK1_ + p.CI_WHT1_ + p.CI_BLK1_ + p.CI_PUR4_;
    var _PAL = p.CI_BLK1_ + p.CI_WHT1_ + p.CI_BLK1_ + p.CI_VLT4_;
    //var _PAL = p.CI_BLK1_ + p.CI_WHT1_ + p.CI_BLK1_ + p.CI_GRY4_;
    */
    change_pal(strReplaceAt(p.pal_rm_new, get_pal_pos(self.palidx_def), string_length(_PAL), _PAL))
  }
  // phase(0081(X)). 1: on horse(00A1(X)=$20). 2: horse moving off screen.
  // 3: waiting for RebonackB defeat, 4: Building bridge,
  self.phase = 1
  self.reboB = 0 // RebonackB(IronKnuckle) instance
  self.Turn_DURATION = 0x20
  self.Turn_timer = 0
  self.Explode_DURATION = 0x20
  self.Explode_counter = 0
  if (f.quest_num > 1) {
    self.HP_IDX += 0x04
  }
  self.HP_IDX = clamp(self.HP_IDX, 0, ds_list_size(g.dl_HP) - 1)
  self.hp = g.dl_HP.get(self.HP_IDX) as number
  self.HP_CUE = g.dl_HP.get(self.HP_IDX) >> 1
  if (f.quest_num > 1 && self.ver === 1) {
    self.XP_IDX += 0x02
    self.xp = g.dl_XP.get(self.XP_IDX) as number
  }
  self.hspd_SWAY = 0x04
  self.hspd_MAX = 0x30 + (+(self.ver === 2) << 3) // $30,38
  self.Front_SPRITE = 'spr_Rebonack_1a' // vehicle front graphic
  self.Front_xoff = 0 // Horse head & body front (spr_Rebonack_1a)
  self.Back_SPRITE1 = 'spr_Rebonack_2a' // vehicle rear  graphic (with rider)
  self.Back_SPRITE2 = 'spr_Rebonack_2b' // vehicle rear  graphic (NO   rider)
  self.Back_sprite = self.Back_SPRITE1
  self.Back_xoff = 0 // body back & Rider
  self.XOFF_DATA = '00FEFCFAF8FAFCFE' + '0002040608060402' // B398-B3A7
  // "00"+"FE"+"FC"+"FA" + "F8" + "FA"+"FC"+"FE"
  // "00"+"02"+"04"+"06" + "08" + "06"+"04"+"02"; // B398-B3A7
  self.Rider_SPRITE = 'spr_Rebonack_Rider'
  self.Rider_sprite = 0
  self.Rider_yoff = 0
  // AF9F
  _DIST = (0x05 << 3) * sign_(self.arena_w === PAGE_W)
  _DIST = (self.arena_w >> 1) + _DIST
  Boss_init_2b(self, _DIST) // Determine & set the side of the arena to start on.
  self.facing_dir = -sign_(self.x - self.arena_x)
  set_xy(self, self.x, self.y - 2) // MOD: Rebonack seems a little low and is drawing behind fg floor.
  // target_side: for ver 2
  self.target_side = self.facing_dir
  /* Body HB data --------------------------------------
id   = ed3&$1F = $00;
data = string_copy(g.BODY_HB_DATA, (id<<3)+1, 8)

dg_BODY_HB[#$02:
data         xOff    width   yOff    height
020C0317  -  $02     $0C     $03     $17

sprite_index = spr_Rebonack_1a(32x32)
*/
  self.BodyHB_color = c_blue
  self.BodyHB_IDX_LFT = 0x0d // xoff 18, yoff 3, wdth 12, hght 23
  self.BodyHB_IDX_RGT = 0x02 // xoff  2, yoff 3, wdth 12, hght 23
  self.BodyHB_idx = self.BodyHB_IDX_LFT
  self.ShieldHB_color = c_white
  self.ShieldHB_IDX = 5 // 5: xoffR=17,xoffL=1, yoff=5, w=16, h=33
  self.ShieldHB_idx = self.ShieldHB_IDX //
  self.SwordHB_W = 14 + g.HB_ADJ_W //
  self.SwordHB_H = 1 + g.HB_ADJ_H //
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
  // ======================================================
  // -----------------------------------------------
  // Statue head will shoot fire each time Rebonack charges
  self.Proj_USE = +(f.quest_num > 1)
  if (gmBool(self.Proj_USE)) {
    self.Proj_OBJ = 'Flame2'
    self.Proj_DEPTH = DEPTH_BG2 + 1
    self.Proj_tokens = 1
    self.Proj_DIST1 = self.arena_x - (self.arena_xl + 0x08) // dist from arena center to center of stone head
    self.Proj_YT = (g.rm_row0 + 0x0d) << 3
    /* TODO with */ for (const _w1 of [...instancesNamed('ArenaGate')] as any[]) {
      self.Proj_YT = _w1.DOOR_Y - (0x04 << 3)
      break
    }
  }
}

/** GML: RebonackA_update() */
export function RebonackA_update(self: Rebonack01A) {
  let _PAD: any, _TARGET_X: any, _DIR: any, _XC: any, _DIST: any, _XL: any, _YT: any, _VER: any

  // --------------------------------------------------------
  // AFBC - HEALTH BAR ----------------------------------
  if (self.phase === 1 && gmBool(g.view_lock_boss)) {
    Boss_HPBar_udp(self)
  }
  // --------------------------------------------------------
  self.hspd_impel = 0
  if (self.phase === 1 || self.phase === 2) {
    if (!gmBool(g.view_lock_boss) || gmBool(self.start_timer)) {
      update_EF11(self) // MOD. Draw pre battle
      RebonackA_update_hover(self) // HOVER EFFECT -----------------------
      RebonackA_update_sway(self) // SWAY BACK AND FORTH --------------------
      updateX(self)
    }
  }
  // --------------------------------------------------------
  // AFEC: JSR B20D, B212.  START BATTLE -------------
  if (self.phase === 1 && !gmBool(g.view_lock_boss)) {
    Boss_update_start(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (self.phase === 1) {
    // Arena gate
    if (!gmBool(Boss_update_4(self))) {
      g.pc_lock = PC_LOCK_ALL
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
    g.pc_lock = 0
  }
  // --------------------------------------------------------
  // AFC6 - DELAY UPDATE AFTER START BATTLE -----------
  if (self.phase === 1 || self.phase === 2) {
    if (gmBool(self.start_timer)) {
      self.start_timer--
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
  }
  // --------------------------------------------------------
  // --------------------------------------------------------
  // --------------------------------------------------------
  // --------------------------------------------------------
  // --------------------------------------------------------
  // --------------------------------------------------------
  if (self.phase === 1 || self.phase === 2) {
    // AFCB
    update_EF11(self)
    // SHIELD COLLISION
    if (gmBool(GOB_shield_collision_1a(self))) {
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
    // AFD6
    RebonackA_update_hover(self) // HOVER EFFECT -----------------------
  }
  // if not exploding
  if (
    self.phase === 1 ||
    (self.phase === 2 &&
      gmBool(self.reboB) &&
      instance_exists(self.reboB) &&
      self.reboB.state === self.state_NORMAL)
  ) {
    updateX(self)
  }
  // --------------------------------------------------------
  // B003: JSR B1E3
  if (self.phase === 1) {
    update_EF11(self)
    // B1E6: JSR D6C1 -----------------------------------------
    if (gmBool(self.cs & CS_BD1)) {
      enemy_collide_pc_body(self)
    }
    if (gmBool(g.mod_RebonackA_HBBalance)) {
      // MOD: hb xoff balance.  $D Left, $2 Right ----------
      if (gmBool(self.facing_dir)) {
        self.BodyHB_idx = self.BodyHB_IDX_RGT // xoff  2, yoff 3, wdth 12, hght 23
      } else {
        self.BodyHB_idx = self.BodyHB_IDX_LFT // xoff 18, yoff 3, wdth 12, hght 23
      }
    } else {
      self.BodyHB_idx = self.BodyHB_IDX_RGT // OG
    }
    if (!gmBool(self.ocs)) {
      GOB_update_2(self)
    }
    // B006: JSR E579 -----------------------------------------
    GOB_sword_collision_1a(self) // handles PC BODY collision check & reaction
    // --------------------------------------------------------
    // B04D -------------------------------------------
    // HP_CUE=$24
    if (self.hp >= self.HP_CUE) {
      // Change facing_dir once half-way turned around
      if (self.Turn_timer === self.Turn_DURATION >> 1) {
        self.target_side = -self.target_side
        self.facing_dir = self.target_side
      }
      if (gmBool(self.Turn_timer)) {
        self.Turn_timer--
      }
      // B05A
      // If NOT in process of turning around
      // If slowed down enough
      if (
        !gmBool(self.Turn_timer) &&
        self.facing_dir !== dir_to_pc(self) &&
        ((self.hspd + 8) & 0xff) < 0x11
      ) {
        // Start turning around once slowed down enough after passing PC.
        // Timer for turning around and determining sprite.
        self.Turn_timer = self.Turn_DURATION - 1 // TURN_AROUND_DUR: $20
      }
      // B07A
      if (gmBool(self.timer)) {
        RebonackA_update_sway(self) // SWAY BACK AND FORTH --------------------
        if (gmBool(self.Proj_USE) && !gmBool(self.Proj_tokens)) {
          self.Proj_tokens = 1
        }
      } else if (!gmBool(g.counter1 & 0x01)) {
        _PAD = 0x0c << 3
        if (self.arena_w > PAGE_W) {
          _PAD += 0x0a << 3
        }
        if (gmBool(self.target_side)) {
          _TARGET_X = self.arena_xr - _PAD
        } else {
          _TARGET_X = self.arena_xl + _PAD
        }
        _DIR = sign_(self.x < _TARGET_X)
        // if not max hspd toward pc
        if (self.hspd !== ((self.hspd_MAX * _DIR) & 0xff)) {
          // B09A
          self.hspd = (self.hspd + _DIR) & 0xff // inc/dec hspd toward pc
          self.hspd_impel = _DIR
          // idle timer. for swaying back & forth while waiting to charge pc
          // When timer reaches 0, if hspd dir is charge dir, Rebo will charge,
          // otherwise hspd will increment towards 0 and a new sway period will
          // begin. A charge wont happen unless hspd dir is charge dir when
          // sway period ends.
          if (!gmBool(self.hspd)) {
            self.timer = 0x53
          }
        }
        if (
          gmBool(self.Proj_USE) &&
          gmBool(self.Proj_tokens) &&
          gmBool(self.hspd) &&
          byte_dir(self.hspd) === _DIR &&
          abs8b(self.hspd) > self.hspd_SWAY
        ) {
          self.Proj_tokens = 0
          _XC = self.arena_x + self.Proj_DIST1 * -_DIR
          _DIST = abs(G.pc.x - _XC) >> 3
          _DIST = clamp(_DIST, 3, (self.arena_w >> 3) - 5)
          /* TODO with */ {
            const _w2: any = GOC1_create(_XC, self.Proj_YT, _DIR, self.Proj_OBJ)
            if (_w2) {
              //GO_depth_init(self.Proj_DEPTH); // 2024/10/15. Removing this because fire is behind pillars. Another solution would be to put the pillars on a different layer.
              set_xy(_w2, _w2.x - _w2.ww_, _w2.y)
              _w2.vspd = 0xfc
              _w2.hspd = round(2.6 * _DIST) // This aims really well!
              _w2.hspd = (_w2.hspd * _w2.facing_dir) & 0xff
            }
          }
        }
      }
    } // HP_CUE=$24
    else if (self.hp < self.HP_CUE) {
      // B009 - CHANGE TO KNIGHT BATTLE -------------------------
      _XL = self.xl + 0x18
      _YT = self.yt
      _VER = 1 + +(self.ver === 2)
      /* TODO with */ {
        const _w3: any = GameObject_create(_XL, _YT, 'Rebonack01B', _VER, self.dk_spawn, self.palidx_def)
        if (_w3) {
          _w3.state = _w3.state_NORMAL
          self.reboB = _w3
          _w3.reboA = self
          //
          _w3.vspd = 0xea
          _w3.hspd = (0x10 * self.facing_dir) & 0xff
          _w3.hspd ^= 0xff
          _w3.hspd = (_w3.hspd << 1) & 0xff
          _w3.arena_xl = self.arena_xl
          _w3.arena_x = self.arena_x
          _w3.arena_w = self.arena_w
          _w3.HPBar_XOFF = self.HPBar_XOFF
          _w3.HPBar_YOFF = self.HPBar_YOFF
          _w3.ShieldHB_idx = _w3.ShieldHB_IDX_HGH
          _w3.MusicBattle_THEME = self.MusicBattle_THEME
          _w3.MusicBattle_BODY = self.MusicBattle_BODY
          _w3.MusicBattle_INTRO = self.MusicBattle_INTRO
        }
      }
      /* TODO with */ {
        const _w4: any = G.pc
        if (_w4) {
          if (_w4.behavior === pc().behavior_STAB_DOWN && gmBool(_w4.vspd & 0x80)) {
            _w4.vspd = (_w4.vspd << 1) & 0xff
          }
        }
      }
      self.hspd = (0x10 * self.facing_dir) & 0xff
      self.behavior = 1
      self.phase = 2 // 2: Horse leaving battle & waiting for battle end
      self.hp = 1 //
      self.state = self.state_NORMAL
    }
  } else {
    // AFF2 - HORSE LEAVING BATTLE ----------------------------
    // true if any width is w/in ocs area width
    // Rider knocked off horse
    if (!gmBool(ocsH1(self)) && self.phase === 2) {
      self.phase = 3 // if all ocs outside of ocs area
    }
  }
  // --------------------------------------------------------
  // --------------------------------------------------------
  // Waiting for reboB to die --------------------------
  if (self.phase === 2 || self.phase === 3) {
    // In case was in the middle of turning around when knocked off horse,
    // this will finish the horse turning around.
    if (gmBool(self.Turn_timer)) {
      self.Turn_timer--
    }
    // Last frame of rising xp
    if (
      gmBool(self.reboB) &&
      instance_exists(self.reboB) &&
      self.reboB.state === self.state_DROP &&
      self.reboB.timer === 1 &&
      G.pc.state === G.pc.state_NORMAL &&
      !gmBool(G.pc.is_dead)
    ) {
      self.phase = 4
      // FIXED: `instance_exists(<name string>)` is always false here — the shim tests `.exists` on its
      // argument, so this safety net fired the instant the rider dismounted and ended the fight early.
    } else if (![...instancesNamed('ArenaGate')].some((i) => i.exists)) {
      self.phase = 4
    }
  }
  if (self.phase === 4) {
    g.pc_lock = 0
    // This is how game spawner knows not to spawn again
    GOB_update_data_defeated(self)
    self.state = 0
  }
}

/** GML: RebonackA_update_hover() */
export function RebonackA_update_hover(self: Rebonack01A) {
  set_xy(self, self.x, self.y + get_hover_y_adj(g.counter1, 2))
}

/** GML: RebonackA_update_sway() */
export function RebonackA_update_sway(self: Rebonack01A) {
  // SWAY BACK AND FORTH --------------------
  if (gmBool(g.counter1 & 0x40)) {
    self.hspd = -self.hspd_SWAY & 0xff
  } else {
    self.hspd = self.hspd_SWAY & 0xff
  }
  self.hspd_impel = byte_dir(self.hspd)
}

