/** GML: RebonackA_draw() */
export function RebonackA_draw(self: Rebonack01A) {
  let _can_draw_self: any, _x: any, _y: any, _is_exploding: any

  if (!gmBool(self.can_draw_self)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  _can_draw_self = false
  switch (self.phase) {
    case 1: {
      _can_draw_self = true
      break
    }
    case 2: {
      // true if any width is w/in ocs area width
      if (gmBool(ocsH1(self)) && gmBool(self.reboB) && instance_exists(self.reboB)) {
        if (self.reboB.state === self.state_NORMAL) {
          _can_draw_self = true
          break
        }
        if (self.reboB.state === self.state_EXPLODE && self.reboB.timer >= g.BOSS_DEATH_FLASH_CUE) {
          _can_draw_self = true
          break
        }
      }
      break
    }
  }
  if (gmBool(_can_draw_self) && self.Explode_counter < self.Explode_DURATION >> 1) {
    pal_swap_set(self.palidx)
    draw_sprite_(
      self.Rider_sprite,
      0,
      self.drawX + self.Back_xoff,
      self.drawY + self.Rider_yoff,
      -1,
      self.xScale,
    )
    draw_sprite_(self.Back_sprite, 0, self.drawX + self.Back_xoff, self.drawY, -1, self.xScale)
    draw_sprite_(self.Front_SPRITE, 0, self.drawX + self.Front_xoff, self.drawY, -1, self.xScale)
    pal_swap_reset()
  }
  // --------------------------------------
  if (
    self.phase === 2 &&
    self.Explode_counter < self.Explode_DURATION &&
    gmBool(self.reboB) &&
    instance_exists(self.reboB) &&
    self.reboB.state === self.state_EXPLODE
  ) {
    _is_exploding = false
    /* TODO with */ for (const _w6 of [...instancesNamed('BossExplosion')] as any[]) {
      if (gmBool(_w6.state) && gmBool(_w6.source_inst) && instance_exists(_w6.source_inst)) {
        _is_exploding = true
        _x = self.x - (_w6.x - _w6.source_inst.x)
        _y = self.y - (_w6.y - _w6.source_inst.y)
        /* TODO with */ {
          const _w5: any = self
          if (_w5) {
            draw_sprite_(_w6.sprite, 0, _x, _y, _w6.palidx, 1)
            draw_sprite_(_w6.sprite, 0, _x, _y, _w6.palidx, -1)
          }
        }
      }
    }
    self.Explode_counter += _is_exploding
  }
}
