/** New-quest puzzle randomisation — ported from `new_quest_init_puzzles.gml`, `generate_spell_sequences.gml`. */
import {
  SPL_FARY,
  SPL_FIRE,
  SPL_JUMP,
  SPL_LIFE,
  SPL_PRTC,
  SPL_RFLC,
  SPL_SPEL,
  STR_Boulder,
  STR_Circle,
  STR_Count,
  STR_Datakey,
  STR_Dialogue,
  STR_Hylian,
  STR_Name,
  STR_Order,
  STR_Sequence,
  STR_Spell,
  STR_THUNDER,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { DsMap } from '../../runtime/ds'
import { f, world } from '../../runtime/world'
import { gd, hooks } from './deps'
import { type GmJsonValue, json_encode } from './json'

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v))

/** `ds_list_shuffle` with the world PRNG (Fisher–Yates). */
export function shuffle<T>(list: T[]): void {
  for (let i = list.length - 1; i > 0; i--) {
    const j = world.irandom(i)
    const t = list[i] as T
    list[i] = list[j] as T
    list[j] = t
  }
}

/** GML `string_letters` — keep only a-z/A-Z. */
const string_letters = (s: string) => s.replace(/[^A-Za-z]/g, '')

/** `new_quest_init_puzzles(spell sequences spell count)` */
export function new_quest_init_puzzles(spellSequenceSpellCount: number): void {
  const SPELL_SEQUENCE_SPELL_COUNT = clamp(spellSequenceSpellCount, 1, 4)
  // Boulder Circle
  const order = ['NORTH', 'NORTH EAST', 'EAST', 'SOUTH EAST', 'SOUTH', 'SOUTH WEST', 'WEST', 'NORTH WEST']
  const rand = [...order]
  shuffle(rand)
  const datakey = STR_Boulder + STR_Circle + STR_Order
  f.dm_quests.set(datakey + STR_Count, rand.length)
  for (let i = rand.length - 1; i >= 0; i--) {
    const dk = datakey + hexStr(i + 1)
    const v = rand[i] as string
    f.dm_quests.set(dk + STR_Dialogue, v)
    f.dm_quests.set(dk, order.indexOf(v) + 1)
  }
  // Spell Sequences
  generate_spell_sequences(SPELL_SEQUENCE_SPELL_COUNT)
}

/**
 * `generate_spell_sequences(spell count)` — Kings Tomb, Carock 2, Kasuto Cemetery Kakusu.
 * @returns the generated dialogue map JSON, or undefined when there are no sequence dialogues.
 */
export function generate_spell_sequences(spellCount: number): string | undefined {
  const g = gd()
  const CAST_SPELL_COUNT = clamp(spellCount, 1, 4)
  // Each group is a tier of spells (2024/08/31, rated roughly by cast cost / when acquired).
  const group1 = [SPL_PRTC, SPL_JUMP, SPL_FIRE]
  const group2 = [SPL_LIFE, SPL_FARY]
  const group3 = [SPL_RFLC, SPL_SPEL]
  const dm1 = new DsMap<GmJsonValue>()
  const dk2 = STR_Spell + STR_Sequence
  const dlg = g.DIALOGUE_WINDOW.dm_dialogue
  let n = 0
  while (dlg.get(dk2 + STR_Dialogue + STR_Datakey + hexStr(n + 1)) !== undefined) n++
  const SPELL_SEQUENCE_COUNT = n
  for (let i = 0; i < SPELL_SEQUENCE_COUNT; i++) {
    const dkDialogue = dlg.get(dk2 + STR_Dialogue + STR_Datakey + hexStr(i + 1))
    if (dkDialogue === undefined) continue
    const dk3 = dk2 + hexStr(i + 1)
    shuffle(group1)
    shuffle(group2)
    shuffle(group3)
    const seq: number[] = []
    switch (i) {
      case 0:
        seq.push(SPL_RFLC) // Kings Tomb
        break
      case 1:
        seq.push(SPL_SPEL) // Carock 2
        break
      case 2:
        seq.push(SPL_SPEL) // Kasuto Cemetery Kakusu
        break
    }
    if (CAST_SPELL_COUNT > 1) seq.push(group1[0] as number)
    if (CAST_SPELL_COUNT > 2) seq.push(group2[0] as number)
    if (CAST_SPELL_COUNT > 3) {
      switch (i) {
        case 0:
          seq.push(group1[1] as number)
          break
        case 1:
          seq.push(group1[1] as number)
          break
        case 2:
          seq.push(group3[0] as number)
          break
      }
    }
    shuffle(seq)
    let str = ''
    let str2 = ''
    for (let j = 0; j < seq.length; j++) {
      const str1 = hexStr(seq[j] as number) // spell bit as string
      str2 += str1 // string of spell bits
      str += string_letters(String(g.dm_Spell.val(str1 + STR_Name, STR_THUNDER)))
      if (j === seq.length - 1) break
      str += g.CHAR_END_LINE1
    }
    const hylian = hooks.get_random_lorem_dlg(seq.length, true)
    const dk4 = dk2 + STR_Dialogue + STR_Count
    dm1.set(dk4, Number(dm1.val(dk4)) + 1)
    dm1.set(dk3 + STR_Dialogue + STR_Datakey, dkDialogue)
    dm1.set(`${dkDialogue}A`, hylian) // Hylian
    dm1.set(`${dkDialogue}B`, str) // Hylian Translated
    dm1.set(String(dkDialogue) + dk2, str2) // spell bits, e.g. "01"+"08"+"04"+"40"
    f.dm_quests.set(dk4, Number(f.dm_quests.val(dk4)) + 1)
    f.dm_quests.set(dk3 + STR_Dialogue + STR_Hylian, hylian)
    f.dm_quests.set(dk3 + STR_Dialogue, str)
    f.dm_quests.set(dk3, str2)
    dlg.set(`${dkDialogue}A`, hylian)
    dlg.set(`${dkDialogue}B`, str)
    dlg.set(String(dkDialogue) + dk2, str2)
  }
  return dm1.size ? json_encode(dm1) : undefined
}
