/**
 * Bagin (ZALiA object `Bagin01`, parent `Enemy`; the fish that jumps out of water; ver 2 spawns RisingBubbles).
 * `Bagin_init2/update/update_1/udp.gml`.
 */
import { CS_BD1, DEPTH_BG1, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { Enemy } from '../../../../classes'
import { GameObject_create, GOC1_create } from '../../../../create'
import { dir_to_pc } from '../../../../go/misc'
import { set_xlyt, set_xy, updateY } from '../../../../go/movement'
import { GO_depth_init, GO_sprite_init } from '../../../../go/sprite'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_udp_1, GOB_update_2 } from '../../../GameObjectB'
import { projOf, randoSpawnDatakey } from '../ache/_shared'

export class Bagin01 extends Enemy {
  readonly objectName = 'Bagin01' as const
  VSPD1 = 0xc0 // Jump speed (initial velocity)
  TERMINAL_VELOCITY = 5
  readonly ST_SUB1_IDLE = 0
  readonly ST_SUB1_JUMP = 1
  readonly ST_SUB1_RESF = 2 // Resurfacing. Period below water line, moving to water line
  sub_state = 0
  DIST_ATK = 0x28 // $30 more challenging
  y_idle = 0
  y_dive = 0
  y_off_float = 0
  DUR_COOLDOWN_ATK = 0x40
  atk_cooldown_timer = 0
}

/** `Bagin_init2()` */
export function Bagin_init2(self: Bagin01): void {
  randoSpawnDatakey(self.dk_spawn) // computed in ZALiA but unused afterwards
  GO_depth_init(self, DEPTH_BG1 + 1)
  self.dl_sprites?.add('spr_Bagin_1a', 'spr_Bagin_1b')
  GO_sprite_init(self, self.dl_sprites?.get(0) as string)
  self.VSPD1 = 0xc0 // Jump speed (initial velocity)
  self.TERMINAL_VELOCITY = 5
  if (self.ver === 2) {
    self.projectile_OBJ = 'RisingBubble'
    self.projectile_VER = 1
    self.projectile = self.projectile_OBJ
    self.projectile_ver = self.projectile_VER
  }
  self.sub_state = self.ST_SUB1_IDLE
  self.DIST_ATK = 0x28 // $30 more challenging
  self.y_idle = self.spawn_yt - 2
  self.y_dive = self.y_idle + 0x10
  self.y_off_float = 0
  self.counter = 0x60
  self.DUR_COOLDOWN_ATK = 0x40
  self.atk_cooldown_timer = 0
}

/** `Bagin_update()` */
export function Bagin_update(self: Bagin01): void {
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    Bagin_update_1(self) // replacement update
    return
  }
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  switch (self.sub_state) {
    case self.ST_SUB1_IDLE: {
      self.counter = (self.counter + 1) & 0x7f
      let _DIR = -1
      if (self.counter & 0x40) _DIR = 1
      self.y_off_float = _DIR // 1, -1
      if ((self.counter & 0x3f) >= 0x20) self.y_off_float += -_DIR // 0
      if ((self.counter & 0x3f) >= 0x30) self.y_off_float += -_DIR // 1, -1
      set_xlyt(self, self.xl, self.y_idle + self.y_off_float)
      if (gmBool(self.atk_cooldown_timer)) self.atk_cooldown_timer--
      if (!gmBool(self.atk_cooldown_timer)) self.facing_dir = dir_to_pc(self)
      if (!gmBool(self.atk_cooldown_timer) && Math.abs(pc().x - self.x) <= self.DIST_ATK) {
        self.y_off_float = 0
        set_xy(self, self.x, self.y - 1)
        self.vspd = self.VSPD1
        self.sub_state = self.ST_SUB1_JUMP
      }
      break
    }
    case self.ST_SUB1_JUMP: {
      if (self.yt < self.y_dive) {
        updateY(self)
        self.vspd = (self.vspd + 1) & 0xff
        // ver2 only
        if (gmBool(self.projectile) && self.vspd === 0 && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
          // jump peak
          GOC1_create(self.x - 4, self.yt, self.facing_dir, projOf(self), self.projectile_ver)
        }
      } else {
        set_xlyt(self, self.xl, self.y_dive)
        self.vspd = 0
        self.sub_state = self.ST_SUB1_RESF
      }
      break
    }
    case self.ST_SUB1_RESF: {
      if (gmBool(self.timer)) break // replacement delay
      if (!(g.counter1 & 0x1)) set_xy(self, self.x, self.y - 1)
      if (self.yt <= self.y_idle) {
        set_xlyt(self, self.xl, self.y_idle)
        self.atk_cooldown_timer = self.DUR_COOLDOWN_ATK
        self.counter = 0x60
        self.sub_state = self.ST_SUB1_IDLE
      }
      break
    }
  }
  GO_update_cs(self)
  GOB_update_2(self)
  Bagin_update_1(self) // replacement update
}

/** `Bagin_update_1()` — when killed, a replacement resurfaces from the same spawn after a delay. */
export function Bagin_update_1(self: Bagin01): void {
  if (self.state !== self.state_NORMAL && !gmBool(self.hp)) {
    const r = GameObject_create(
      self.spawn_xl,
      self.spawn_yt,
      self.objectName,
      self.ver,
      self.dk_spawn ?? -1,
    ) as Bagin01 | null
    if (r) {
      set_xlyt(r, r.xl, self.y_dive)
      GO_depth_init(r, self.depth_def) // just in case this spawn has a unique depth
      r.sub_state = r.ST_SUB1_RESF
      r.timer = self.timer + 0xff // resurface delay
    }
  }
}

/** `Bagin_udp()` */
export function Bagin_udp(self: Bagin01): void {
  self.can_draw_self = true
  switch (self.sub_state) {
    case self.ST_SUB1_IDLE:
      GOB_udp_1(self, 0x10)
      self.yScale = 1
      break
    case self.ST_SUB1_JUMP:
      GOB_udp_1(self, 0x08)
      self.yScale = self.vspd & 0x80 ? 1 : -1
      break
    case self.ST_SUB1_RESF:
      GOB_udp_1(self, 0x08)
      self.yScale = -1
      break
  }
}

registerObject('Bagin01', Bagin01)
registerScripts({ Bagin_init2, Bagin_update, Bagin_update_1, Bagin_udp })
