/**
 * gui folder root scripts: `get_menu_x`, `get_xp_str`, `gui_tmr_cursor_v/h`, `update_menus`, plus the
 * keyboard-binding table (ZALiA's open TODO, implemented here — see FIDELITY_NOTES).
 */
import { PC_LOCK_MENU } from '@z2/data'
import { gmBool } from '../../nes/math8'
import { f, g, input } from '../../runtime/world'
import { viewXC } from '../view/camera'

/** `get_menu_x()` — menu x aligned to 16 px, shifted right on wide rooms. */
export function get_menu_x(): number {
  let _return = viewXC() - 8
  _return = (_return >> 4) << 4
  if (g.rm_pages_x >= 2) _return += 0x7 << 3
  return _return
}

/** `get_xp_str(xp)` — 4-digit zero padded. */
export function get_xp_str(xp: number | string): string {
  let _str = String(xp)
  for (let i = 4 - _str.length; i > 0; i--) _str = `0${_str}`
  return _str
}

/**
 * `gui_tmr_cursor_v()` — d-pad up/down with auto-repeat: first press returns immediately and arms a $10
 * frame delay, then repeats every $07 frames while held. Returns the held V bits or 0. (Uses g.gui_timer1.)
 */
export function gui_tmr_cursor_v(): number {
  if (!input.heldV) return 0
  const _C1 = input.heldV !== (input.heldPrev & (input.D | input.U))
  if (!_C1) g.gui_timer1-- // menu timer
  if (_C1 || !g.gui_timer1) {
    if (_C1)
      g.gui_timer1 = 0x10 // delay auto-scroll
    else g.gui_timer1 = 0x07 // auto-scroll
    return input.heldV
  }
  return 0
}

/** `gui_tmr_cursor_h()` — same as `gui_tmr_cursor_v` for left/right (g.gui_timer2). */
export function gui_tmr_cursor_h(): number {
  if (!input.heldH) return 0
  const _C1 = input.heldH !== (input.heldPrev & (input.R | input.L))
  if (!_C1) g.gui_timer2-- // menu timer
  if (_C1 || !g.gui_timer2) {
    if (_C1)
      g.gui_timer2 = 0x10 // delay auto-scroll
    else g.gui_timer2 = 0x07 // auto-scroll
    return input.heldH
  }
  return 0
}

/** Menu instances the g singleton addresses (`g.PAUSE_MENU`, `g.LEVEL_MENU`, `g.DIALOGUE_WINDOW`, …). */
export interface MenuHandles {
  pause: { update(): void; state: number; state_SPELL: number }
  levelUp: { update(): void }
  dialogue: { update(): void }
}
export const menuHandles: Partial<MenuHandles> = {}

/** `set_go_can_draw_self(false)` — Game folder; injected to avoid the import cycle. */
export const guiDeps = {
  set_go_can_draw_self: (_v: boolean): void => {},
}

/**
 * `update_menus()` — C206. Runs in `g` scope: opens the level-up menu when XP allows, the pause menu on
 * Start, and dispatches to the active menu's update.
 */
export function update_menus(): void {
  g.gui_window_can_draw = 1
  // C218
  if (
    g.gui_state === g.gui_state_DIALOGUE1 ||
    g.gui_state === g.gui_state_DIALOGUE2 ||
    g.gui_state === g.gui_state_DIALOGUE3
  ) {
    // C245 - Dialogue Window
    menuHandles.dialogue?.update()
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  switch (g.gui_state) {
    case g.gui_state_NONE: {
      if (f.xp >= f.xpNext) {
        // Open LevelUp Menu
        g.gui_state = g.gui_state_LEVEL_UP
      } else if (gmBool(input.Pause_pressed)) {
        // Open Pause Menu
        g.gui_state = g.gui_state_PAUSE
        g.menu_state = 1
        const pm = menuHandles.pause
        if (pm) pm.state = pm.state_SPELL
      }
      break
    }
    case g.gui_state_PAUSE: {
      // SPELL/ITEM/MAP
      if (!(g.pc_lock & PC_LOCK_MENU)) {
        // C212: JSR D250       - set all GO.can_draw_self = false
        if (gmBool(g.menu_state)) guiDeps.set_go_can_draw_self(false)
        // 9D91 - Pause Menu
        menuHandles.pause?.update()
      } else {
        g.gui_state = g.gui_state_NONE
        g.menu_state = 0
      }
      break
    }
    case g.gui_state_LEVEL_UP: {
      // C212: JSR D250       - set all GO.canDrawSelf = false
      if (gmBool(g.menu_state)) guiDeps.set_go_can_draw_self(false)
      // 9D54 - Level-up Menu
      menuHandles.levelUp?.update()
      break
    }
    default:
      break
  }
}

// ---- keyboard rebinding (ZALiA TODO `OptionsMenu_InputConfig_update.gml:4`, implemented) -----------------
// The table lives in `objects/keyboardBindings.ts` (leaf) so `Input_update2a` can read it.
import {
  KEY_ACTIONS,
  KEYBOARD_DEFAULTS,
  type KeyAction,
  keyboardBindings,
  keyboard_bindings_load as loadBindings,
  keyboard_bindings_reset as resetBindings,
  keyboard_bindings_save as saveBindings,
} from '../../objects/keyboardBindings'

export { KEY_ACTIONS, KEYBOARD_DEFAULTS, type KeyAction, keyboardBindings }

export function keyboard_bindings_load(): void {
  loadBindings(input.dm_UserInputConfig)
}
export function keyboard_bindings_save(): void {
  saveBindings(input.dm_UserInputConfig)
}
export function keyboard_bind(action: KeyAction, key: string): void {
  keyboardBindings[action] = [key]
  keyboard_bindings_save()
}
export function keyboard_bindings_reset(): void {
  resetBindings()
  keyboard_bindings_save()
}
