import { type DrawCmd, hasSpriteInfo, spriteInfo } from '@z2/core'
import Phaser from 'phaser'
import { frameKey, type SpriteEntry } from '../assets/manifest'
import { PaletteSwapCache } from './paletteSwap'
import { glyphFrames, phaserDepth } from './text'

/**
 * Renders the core's per-frame `DrawCmd` list with pooled Phaser objects.
 * `DrawCmd.sprite` x/y are GameMaker draw coordinates (origin-relative), so each Image gets the sprite's
 * origin from the manifest. `palIdx >= 0` routes through the palette-swap cache.
 */
export class DrawListRenderer {
  private images: Phaser.GameObjects.Image[] = []
  private rects: Phaser.GameObjects.Rectangle[] = []
  private arcs: Phaser.GameObjects.Arc[] = []
  private lines: Phaser.GameObjects.Line[] = []
  /**
   * Within-frame sequence, reset each `render()`. `world.draw.sorted()` already hands commands over in
   * painting order, but every object here got a depth of exactly `phaserDepth(c.depth)` — so at equal GM
   * depth Phaser fell back to display-list insertion order, and the image/rect/arc/line pools are separate
   * arrays built at different times, so that order was not the command order. On the title screen the star
   * field (points → the rect pool) drew *in front of* the terrain (tiles → the image pool), which the GML
   * draws after it. Adding a sub-1 fraction keeps the GM depth ordering and breaks ties in command order.
   * It also lands draw-list commands just in front of a `TileRenderer` layer at the same GM depth, which is
   * what GM does with instances versus tiles.
   */
  private seq = 0
  private z(gmDepth: number): number {
    return phaserDepth(gmDepth) + Math.min(this.seq++, 99_999) * 1e-5
  }
  private usedImages = 0
  private usedRects = 0
  private usedArcs = 0
  private usedLines = 0
  readonly palette: PaletteSwapCache

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly sprites: Map<string, SpriteEntry>,
  ) {
    this.palette = new PaletteSwapCache(scene)
  }

  private image(): Phaser.GameObjects.Image {
    let img = this.images[this.usedImages]
    if (!img) {
      img = this.scene.add.image(0, 0, '__DEFAULT')
      this.images.push(img)
    }
    this.usedImages++
    img.setVisible(true)
    return img
  }

  private rect(): Phaser.GameObjects.Rectangle {
    let r = this.rects[this.usedRects]
    if (!r) {
      r = this.scene.add.rectangle(0, 0, 1, 1)
      r.setOrigin(0)
      this.rects.push(r)
    }
    this.usedRects++
    r.setVisible(true)
    return r
  }

  private arc(): Phaser.GameObjects.Arc {
    let a = this.arcs[this.usedArcs]
    if (!a) {
      a = this.scene.add.circle(0, 0, 1)
      this.arcs.push(a)
    }
    this.usedArcs++
    a.setVisible(true)
    return a
  }

  private line(): Phaser.GameObjects.Line {
    let l = this.lines[this.usedLines]
    if (!l) {
      l = this.scene.add.line(0, 0, 0, 0, 0, 0)
      l.setOrigin(0, 0)
      this.lines.push(l)
    }
    this.usedLines++
    l.setVisible(true)
    return l
  }

  private drawSprite(
    sprite: string,
    frame: number,
    x: number,
    y: number,
    xscale: number,
    yscale: number,
    palIdx: number,
    depth: number,
    alpha: number,
    tint?: number,
    rotation = 0,
  ) {
    const meta = this.sprites.get(sprite)
    if (!meta) {
      // Composites (`sprite_create_with_tiles`) are built at runtime and live only in the core's manifest,
      // so they are absent from the boot atlas index. Without this branch `g.TownDoor1_SPR` (every town
      // doorway), `g.Block1_SPR1`, `g.CloudLarge1_SPR1` and `HeadMount1-5_SPR` drew nothing at all.
      this.drawComposite(sprite, x, y, xscale, yscale, palIdx, depth, alpha)
      return
    }
    const atlas = `atlas:${meta.atlas}`
    const fkey = frameKey(sprite, ((frame % meta.frames) + meta.frames) % meta.frames)
    const img = this.image()
    if (palIdx >= 0) img.setTexture(this.palette.get(atlas, fkey, palIdx))
    else img.setTexture(atlas, fkey)
    img.setOrigin(meta.width ? meta.originX / meta.width : 0, meta.height ? meta.originY / meta.height : 0)
    img.setPosition(x, y)
    img.setScale(xscale, yscale)
    img.setAlpha(alpha)
    img.setAngle(-rotation) // GM rotates counter-clockwise, Phaser clockwise
    img.setDepth(this.z(depth))
    // GM's `draw_sprite_ext` colour argument *multiplies* the sprite, so `c_white` ($FFFFFF) is its
    // identity and black is the silhouette FILL was chosen for. Phaser's MULTIPLY reproduces both; FILL
    // turned every `c_white` call site (Bubble's skull, the fire-rope segments, the toggling-path arrows,
    // the dialogue advance arrow) into a solid white block.
    if (tint !== undefined) img.setTint(tint).setTintMode(Phaser.TintModes.MULTIPLY)
    else img.clearTint()
  }

  /** `draw_sprite_part(_ext)` / user skin sheets: a sub-rectangle of a sprite frame (or a runtime sheet). */
  private drawSpritePart(
    sprite: string,
    frame: number,
    left: number,
    top: number,
    w: number,
    h: number,
    x: number,
    y: number,
    xscale: number,
    yscale: number,
    palIdx: number,
    depth: number,
    alpha: number,
    tint?: number,
  ): void {
    let key: string
    let base: string
    if (this.scene.textures.exists(`sheet:${sprite}`)) {
      key = `sheet:${sprite}` // runtime-added user skin sheet (see GameScene.registerSkinSheet)
      base = '__BASE'
    } else {
      const meta = this.sprites.get(sprite)
      if (!meta) return
      key = `atlas:${meta.atlas}`
      base = frameKey(sprite, ((frame % meta.frames) + meta.frames) % meta.frames)
    }
    const tex = this.scene.textures.get(key)
    if (!tex.has(base)) return
    const src = tex.get(base)
    const fkey = `${base}@${left},${top},${w},${h}`
    if (!tex.has(fkey)) tex.add(fkey, src.sourceIndex, src.cutX + left, src.cutY + top, w, h)
    const img = this.image()
    if (palIdx >= 0) img.setTexture(this.palette.get(key, fkey, palIdx))
    else img.setTexture(key, fkey)
    img.setOrigin(0, 0)
    img.setPosition(x, y)
    img.setScale(xscale, yscale)
    img.setAlpha(alpha)
    img.setAngle(0)
    img.setDepth(this.z(depth))
    // GM's `draw_sprite_ext` colour argument *multiplies* the sprite, so `c_white` ($FFFFFF) is its
    // identity and black is the silhouette FILL was chosen for. Phaser's MULTIPLY reproduces both; FILL
    // turned every `c_white` call site (Bubble's skull, the fire-rope segments, the toggling-path arrows,
    // the dialogue advance arrow) into a solid white block.
    if (tint !== undefined) img.setTint(tint).setTintMode(Phaser.TintModes.MULTIPLY)
    else img.clearTint()
  }

  /** A tileset rectangle by source rect — the shared half of `drawTile` and `drawComposite`. */
  private tileFrame(key: string, left: number, top: number, w: number, h: number): string | undefined {
    if (!this.scene.textures.exists(key)) return undefined
    const tex = this.scene.textures.get(key)
    const fkey = `${left},${top},${w},${h}`
    if (!tex.has(fkey)) tex.add(fkey, 0, left, top, w, h)
    return fkey
  }

  /**
   * A sprite GM built from tiles at runtime (`sprite_create_with_tiles`): the core keeps the recipe (which
   * 8×8 tileset cell goes where, and its flips) instead of a texture. Its origin is the centre, as
   * `sprite_create_from_surface(..., _SPR_W>>1, _SPR_H>>1)` sets.
   */
  private drawComposite(
    sprite: string,
    x: number,
    y: number,
    xscale: number,
    yscale: number,
    palIdx: number,
    depth: number,
    alpha: number,
  ): void {
    if (!hasSpriteInfo(sprite)) return
    const info = spriteInfo(sprite)
    const c = info.composite
    if (!c) return
    for (const t of c.tiles) {
      const key = `ts:${t.tileset}`
      const frame = this.tileFrame(key, t.tsx, t.tsy, 8, 8)
      if (frame === undefined) continue
      const img = this.image()
      if (palIdx >= 0) img.setTexture(this.palette.get(key, frame, palIdx))
      else img.setTexture(key, frame)
      img.clearTint()
      img.setOrigin(0, 0)
      img.setPosition(x + (t.x - info.originX) * xscale, y + (t.y - info.originY) * yscale)
      img.setScale(t.xscale * xscale, t.yscale * yscale)
      img.setAlpha(alpha)
      img.setAngle(0)
      img.setDepth(this.z(depth))
    }
  }

  /** `draw_background_part(_ext)`: a rectangle cut from a tileset image (`ts:<name>` textures). */
  private drawTile(c: Extract<DrawCmd, { kind: 'tile' }>): void {
    const key = `ts:${c.tileset}`
    const fkey = this.tileFrame(key, c.left, c.top, c.w, c.h)
    if (fkey === undefined) return
    const img = this.image()
    // A tile part carries the palette swap that was active when it was recorded, exactly as a sprite does
    // (`draw_background_part_ext_` sets one explicitly; the object draw scripts inherit the global one).
    if (c.palIdx >= 0) img.setTexture(this.palette.get(key, fkey, c.palIdx))
    else img.setTexture(key, fkey)
    img.clearTint()
    img.setOrigin(0, 0)
    img.setPosition(c.x, c.y)
    img.setScale(c.xscale, c.yscale)
    img.setAlpha(c.alpha)
    img.setAngle(0)
    img.setDepth(this.z(c.depth))
  }

  render(cmds: readonly DrawCmd[]): void {
    this.seq = 0
    this.usedImages = 0
    this.usedRects = 0
    this.usedArcs = 0
    this.usedLines = 0
    for (const c of cmds) {
      switch (c.kind) {
        case 'sprite':
          this.drawSprite(
            c.sprite,
            c.frame,
            c.x,
            c.y,
            c.xscale,
            c.yscale,
            c.palIdx,
            c.depth,
            c.alpha,
            c.tint,
            c.rotation,
          )
          break
        case 'spritePart':
          this.drawSpritePart(
            c.sprite,
            c.frame,
            c.left,
            c.top,
            c.width,
            c.height,
            c.x,
            c.y,
            c.xscale,
            c.yscale,
            c.palIdx,
            c.depth,
            c.alpha ?? 1,
            c.tint,
          )
          break
        case 'sheet':
          this.drawSpritePart(
            c.sprite,
            0,
            c.sx,
            c.sy,
            c.w,
            c.h,
            c.x,
            c.y,
            c.xscale,
            c.yscale,
            c.palIdx,
            c.depth,
            1,
            c.tint,
          )
          break
        case 'circle': {
          const a = this.arc()
          a.setPosition(c.x, c.y)
          a.setRadius(c.radius)
          if (c.outline) {
            a.setFillStyle(undefined, 0)
            a.setStrokeStyle(1, c.color, c.alpha)
          } else {
            a.setStrokeStyle(undefined, 0)
            a.setFillStyle(c.color, c.alpha)
          }
          a.setDepth(this.z(c.depth))
          break
        }
        case 'line': {
          const l = this.line()
          l.setTo(c.x1, c.y1, c.x2, c.y2)
          l.setStrokeStyle(1, c.color, 1)
          l.setDepth(this.z(c.depth))
          break
        }
        case 'surface': {
          const key = `surface:${c.surface}:${c.index}`
          if (!this.scene.textures.exists(key)) break // the surface provider (StarSky pages) registers textures under this key
          const img = this.image()
          img.setTexture(key)
          img.clearTint()
          img.setOrigin(0, 0)
          img.setPosition(c.x, c.y)
          img.setScale(1, 1)
          img.setAlpha(1)
          img.setAngle(0)
          img.setDepth(this.z(c.depth))
          break
        }
        case 'tile':
          this.drawTile(c)
          break
        case 'point': {
          const r = this.rect()
          r.setPosition(c.x, c.y)
          r.setSize(1, 1)
          r.setStrokeStyle(undefined, 0)
          r.setFillStyle(c.color, 1)
          r.setDepth(this.z(c.depth))
          break
        }
        case 'rect': {
          const r = this.rect()
          r.setPosition(Math.min(c.x1, c.x2), Math.min(c.y1, c.y2))
          r.setSize(Math.abs(c.x2 - c.x1) + 1, Math.abs(c.y2 - c.y1) + 1)
          if (c.outline) {
            r.setFillStyle(undefined, 0)
            r.setStrokeStyle(1, c.color, c.alpha)
          } else {
            r.setStrokeStyle(undefined, 0)
            r.setFillStyle(c.color, c.alpha)
          }
          r.setDepth(this.z(c.depth))
          break
        }
        case 'text': {
          const meta = this.sprites.get(c.font)
          if (!meta) break
          let x = c.x
          for (const f of glyphFrames(c.text)) {
            if (f >= 0) this.drawSprite(c.font, f, x, c.y, 1, 1, c.palIdx, c.depth, 1)
            x += meta.width
          }
          break
        }
      }
    }
    for (let i = this.usedImages; i < this.images.length; i++)
      (this.images[i] as Phaser.GameObjects.Image).setVisible(false)
    for (let i = this.usedRects; i < this.rects.length; i++)
      (this.rects[i] as Phaser.GameObjects.Rectangle).setVisible(false)
    for (let i = this.usedArcs; i < this.arcs.length; i++)
      (this.arcs[i] as Phaser.GameObjects.Arc).setVisible(false)
    for (let i = this.usedLines; i < this.lines.length; i++)
      (this.lines[i] as Phaser.GameObjects.Line).setVisible(false)
  }
}
