// Ported from ZALiA scripts/update_change_room.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively
import {
  dk_FallScene,
  dk_PI,
  STR_Base,
  STR_Counter,
  STR_Current,
  STR_Direction,
  STR_Encounter,
  STR_Enter,
  STR_Fall,
  STR_Height,
  STR_Image,
  STR_Index,
  STR_Leave,
  STR_Palette,
  STR_Sequence,
  STR_Sound,
  STR_Special,
  STR_Speed,
  STR_Type,
  STR_Width,
} from '@z2/data'
import { hexStr as hex_str } from '../../nes/hexStr'
import { gmBool } from '../../nes/math8'
import { G, g, p } from '../../runtime/world'
import { viewXL, viewXR, viewYB, viewYC, viewYT } from '../collision/env'
import { set_go_can_draw_self } from '../game_object/go/misc'
import { sign_ } from '../game_object/util'
import { strReplaceAt } from '../other/index'
import { get_fall_scene_type, qual_fall_scene } from '../palette/fallScene'
import { get_pal_pos } from '../palette/palString'
import { change_pal } from '../palette/scenePalette'
import { notPorted } from '../pending'
import { is_exiting_ow } from '../room'
import { is_exiting_rm, rm_get_encounter_types } from '../room/index'
import { aud_play_sound, get_audio_theme_track } from '../sound'
// FIXED: this imported the `pendingSingleton('Audio')` proxy from `./gm`, which has no `set` trap, so
// every `Audio.* = ...` below landed on an empty object — room-body music was never re-enabled after a
// transition, the fall scene never muted, and the encounter sound instance was never recorded.
import { Audio } from '../sound/Audio'
import { tile_delete_all } from '../tile'
import { viewXC } from '../view/camera'
import {
  audio_group_stop_all,
  audiogroup_mus,
  floor,
  is_undefined,
  show_debug_message,
  string,
  string_length,
  surface_copy,
  surface_create,
  surface_exists,
  surface_get_height,
  surface_get_width,
  val,
} from './gm'
import { update_change_room_1a } from './update_change_room_1a'

/** `val(global.FallScene_dm[?k], d)` as a number — the map also holds `Surface`s, so `get` is not numeric. */
const fsNum = (k: string, d: number | string = 0): number => Number(val(p.FallScene_dm.get(k), d))

/** GML: update_change_room() */
export function update_change_room() {
  // GML `var` is function-scoped; locals hoisted here:
  let _C1: any,
    _DIR: any,
    _EXITING_OW: any,
    _EXITING_RM: any,
    _FALL_DIR: any,
    _FALL_SPEED: any,
    _Image_H: any,
    _Image_W: any,
    _PALETTE: any,
    _PARENT_PI: any,
    _RETURN: any,
    _TYPE_: any,
    _dk0: any,
    _dk1: any,
    _pi: any
  // NextLifeScreen: if (counter1==ROOM_CHANGE_CUE) ChangeRoom_timer = DUR_CHANGE_ROOM_ENTER_1 + 1;
  _EXITING_RM = is_exiting_rm()
  _EXITING_OW = is_exiting_ow()
  _RETURN = g.ChangeRoom_timer > 0 || _EXITING_RM || _EXITING_OW
  // ---------------------------------------------------------------------
  if (g.ChangeRoom_timer <= 0) {
    if (gmBool(_EXITING_RM)) {
      g.leave_rm_x = G.pc.xl
      g.leave_rm_y = G.pc.yt
      // MOD. To prevent GO's from drawing during room change
      set_go_can_draw_self(false)
    }
    if (gmBool(_EXITING_RM) || gmBool(_EXITING_OW)) {
      // Start room change process
      _C1 = qual_fall_scene()
      //if(_EXITING_OW && ow.exit_grid_xy==$61D3) sdm("get_fs_type(): "+string(get_fs_type())+", _C1: "+string(_C1)+", is_undefined(g.ow.enc_reen): "+string(is_undefined(g.ow.enc_reen)));
      if (gmBool(_C1)) {
        g.ChangeRoom_timer = g.ChangeRoom_LEAVE_DURATION2 // $05. Falling scene
      } else {
        g.ChangeRoom_timer = g.ChangeRoom_LEAVE_DURATION1 // $09
      }
      // Falling scene will NOT occur
      if (!gmBool(_C1)) {
        if (gmBool(_EXITING_OW)) {
          // Entering encounter
          // PC is on Dark Forest Kakusu tile
          if (
            !is_undefined(G.OVERWORLD.enc_reen) ||
            !is_undefined(G.OVERWORLD.dm.get(hex_str(G.OVERWORLD.pcrc) + STR_Special + STR_Encounter))
          ) {
            Audio.encounter_sound_inst = aud_play_sound(get_audio_theme_track(STR_Encounter + STR_Enter))
          }
        } else if (gmBool(_EXITING_RM)) {
          if (gmBool(rm_get_encounter_types(g.rm_name))) {
            Audio.encounter_sound_inst = aud_play_sound(get_audio_theme_track(STR_Encounter + STR_Leave))
          }
        }
      }
    }
  }
  // ------------------------------------------------------------------------------------------
  // ------------------------------------------------------------------------------------------
  if (g.ChangeRoom_timer <= 0) {
    g.ChangeRoom_timer = 0
    return _RETURN
  }
  // ------------------------------------------------------------------------------------------
  // ------------------------------------------------------------------------------------------
  if (gmBool(g.FallScene_timer)) {
    g.FallScene_timer--
  }
  // ------------------------------------------------------------------------------------------
  // ------------------------------------------------------------------------------------------
  g.ChangeRoom_timer -= 1 * G.delta_multiplier
  //
  if (g.ChangeRoom_timer <= 0) {
    g.ChangeRoom_timer = 0
    if (gmBool(_EXITING_RM) || gmBool(_EXITING_OW)) {
      if (qual_fall_scene()) {
        // Trigger Falling Scene -----------------------------------------
        g.ChangeRoom_timer = g.FallScene_DURATION1 // $6D(109)
        g.FallScene_timer = floor(g.ChangeRoom_timer) + 1
        //sdm("`update_change_room()`. fall scene triggered. FallScene_timer="+string(FallScene_timer)+", get_fall_scene_type()=$"+hex_str(get_fall_scene_type()));
        // let _dk0: any, _dk1, _pi: any;
        _FALL_DIR = get_fall_scene_type() // $1: RIGHT
        _DIR = sign_(_FALL_DIR & (0x01 | 0x04)) // $1: RIGHT
        _TYPE_ = string(1 + +((_FALL_DIR & (0x01 | 0x02)) !== 0)) // The type/id of this fall scene. "1": Classic blue vertical fall
        _FALL_SPEED = fsNum(STR_Current + STR_Fall + STR_Speed, 1) * _DIR
        _Image_W = val(p.FallScene_dm.get(_TYPE_ + STR_Image + STR_Width))
        _Image_H = val(p.FallScene_dm.get(_TYPE_ + STR_Image + STR_Height))
        p.FallScene_dm.set(STR_Counter, 1)
        p.FallScene_dm.set(STR_Current + STR_Type, _TYPE_)
        p.FallScene_dm.set(STR_Current + STR_Fall + STR_Direction, _FALL_DIR)
        p.FallScene_dm.set(STR_Current + STR_Fall + STR_Speed, _FALL_SPEED)
        p.FallScene_dm.set(`${STR_Current}_x`, viewXC())
        p.FallScene_dm.set(`${STR_Current}_y`, viewYC())
        // Horizontal fall with red vertical stripes. $1: RIGHT, $2: LEFT
        if (gmBool(_FALL_DIR & (0x01 | 0x02))) {
          // Red vertical stripes. Fast travel fall scene
          if (gmBool(_DIR)) {
            p.FallScene_dm.set(`${STR_Current}_x`, viewXL()) // falling RIGHT
          } else {
            p.FallScene_dm.set(`${STR_Current}_x`, viewXR()) // falling LEFT
          }
          p.FallScene_dm.set(`${STR_Current}_x`, fsNum(`${STR_Current}_x`) + fsNum(`${STR_Base}_X`) * _DIR)
          p.FallScene_dm.set(`${STR_Current}_x`, fsNum(`${STR_Current}_x`) - _FALL_SPEED) // So that x/y coords can update in `FallScene_update()` instead of in the draw
        } // Vertical fall with blue horizontal stripes. $4: DOWN, $8: UP
        else if (gmBool(_FALL_DIR & (0x04 | 0x08))) {
          // Blue horizontal stripes. Normal fall scene
          if (gmBool(_DIR)) {
            p.FallScene_dm.set(`${STR_Current}_y`, viewYT()) // falling DOWN
          } else {
            p.FallScene_dm.set(`${STR_Current}_y`, viewYB()) // falling UP
          }
          p.FallScene_dm.set(`${STR_Current}_y`, fsNum(`${STR_Current}_y`) + fsNum(`${STR_Base}_Y`) * _DIR)
          p.FallScene_dm.set(`${STR_Current}_y`, fsNum(`${STR_Current}_y`) - _FALL_SPEED) // So that x/y coords can update in `FallScene_update()` instead of in the draw
        }
        _dk0 = STR_Current + STR_Image // image that will be used for this fall scene
        _dk1 = _TYPE_ + STR_Image // image that this `_TYPE_` of fall scene uses
        if (!surface_exists(val(p.FallScene_dm.get(_dk0), -1))) {
          p.FallScene_dm.set(_dk0, surface_create(_Image_W, _Image_H))
        }
        if (surface_exists(val(p.FallScene_dm.get(_dk1), -1))) {
          surface_copy(p.FallScene_dm.get(_dk0), 0, 0, p.FallScene_dm.get(_dk1))
        }
        p.FallScene_dm.set(STR_Current + STR_Image + STR_Width, surface_get_width(p.FallScene_dm.get(_dk0)))
        p.FallScene_dm.set(STR_Current + STR_Image + STR_Height, surface_get_height(p.FallScene_dm.get(_dk0)))
        _dk0 = _TYPE_ + dk_PI
        _dk0 += hex_str(fsNum(dk_PI + STR_Sequence + STR_Index) + 1)
        p.FallScene_dm.set(STR_Current + dk_PI, val(p.FallScene_dm.get(_dk0), G.PI_GUI2))
        // Change palette colors for the fall scene
        _PARENT_PI = val(p.FallScene_dm.get(`${_dk0}_Parent`), G.PI_GUI2)
        _PALETTE = val(p.FallScene_dm.get(_TYPE_ + STR_Palette), p.PAL_GUI2)
        change_pal(strReplaceAt(p.pal_rm_new, get_pal_pos(_PARENT_PI), string_length(_PALETTE), _PALETTE))
        // This is to prevent a couple frames of a bright bgr color drawing clear before transitioning to the bgr color of the next scene
        p.BackgroundColor_scene = p.C_BLK1
        // delete all room tiles so falling scene has a clear screen to draw on
        tile_delete_all()
        audio_group_stop_all(audiogroup_mus)
        Audio.can_play_mus_rm_body = false
        Audio.can_play_boss_music = false
        aud_play_sound(get_audio_theme_track(dk_FallScene + STR_Sound))
      } else {
        // Triggers room_goto() ------------------------------------------
        //sdm("`update_change_room()`. no fall scene. FallScene_timer="+string(FallScene_timer)+", get_fall_scene_type()=$"+hex_str(get_fall_scene_type()));
        g.ChangeRoom_timer = g.ChangeRoom_ENTER_DURATION1 // $22
        update_change_room_1a()
      }
    } else {
      // --------------------------------------------------------------------------------------------------
      // --------------------  FINISHED CHANGING ROOMS  ------------------------------------------------------------------------------------
      g.FallScene_timer = g.FallScene_INACTIVE
      g.ChangeRoom_timer = 0
      if (g.room_type === 'A') {
        g.counter1 = 0x26 // simulating OG
      }
      Audio.can_play_mus_rm_body = true
      show_debug_message('update_change_room(). FINISHED CHANGING ROOMS')
    }
  }
  return _RETURN // $$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
}
