/**
 * ZALiA IDE folder `rando` — the randomizer.
 *
 * Entry point: `Rando_randomize_file(file num, quest num, seed, encoded settings)`, called by
 * `FileSelect_register_file` for every save that is registered. `installRando()` publishes it (and
 * `Rando_draw_seed` / `Rando_get_new_seed`) to the screens through `rooms/deps.ts`.
 *
 * `rando_debug` (`RandoDebug01_*`) is a dev-only batch-simulation object whose creation is commented out in
 * ZALiA (`FileSelect_Create.gml:514`) and whose `Rando_generate()` call site is stale
 * (`RandoDebug01_Step.gml:116`); it is dropped, not ported.
 */
import { gofDeps } from '../game_object/gof/deps'
import { setRandoDeps } from '../rooms/deps'
import { Rando_draw_seed, Rando_get_new_seed, Rando_randomize_file } from './randomizeFile'

export * from './enemyData'
export { Rando_generate } from './generate'
export { Rando_generate_hints, Rando_is_qual_hint_location, Rando_prepare_hints } from './hints'
export {
  Rando_randomize_items,
  Rando_randomize_items_1,
  Rando_randomize_items_1a,
  Rando_randomize_items_1a_1,
  Rando_randomize_items_2,
} from './items'
export { Rando_add_location, Rando_init_location_data } from './locationData'
export {
  Rando_place_container_pieces,
  Rando_place_keys,
  Rando_set_data_1a,
  Rando_set_loc_num_options,
  Rando_sweep_combo,
  Rando_sweep_keys,
  Rando_sweep_skills,
  Rando_sweep_spells,
} from './placement'
export { Rando_is_qual_location, Rando_is_qual_location_1a } from './qualLocation'
export { Rando } from './Rando'
export { Rando_draw_seed, Rando_get_new_seed, Rando_randomize_file } from './randomizeFile'
export * from './reach'

/** Publish the randomizer to `rooms/deps.ts` (called from `wireCore()`). */
export function installRando(): void {
  // `Cutscene_GameEnd_1B_update.gml:929` re-randomizes the file for "START – 2ND QUEST".
  gofDeps.Rando_randomize_file = (fileNum, questNum, seed, settings) => {
    Rando_randomize_file(fileNum, questNum, seed, settings)
  }
  setRandoDeps({
    Rando_get_new_seed,
    Rando_randomize_file: (fileNum, questNum, seed, settings) =>
      Rando_randomize_file(fileNum, questNum, seed, settings),
    Rando_draw_seed: (...a: unknown[]) =>
      Rando_draw_seed(a[0] as number, a[1] as number, a[2] as number, a[3] as number | undefined),
  })
}
