import {
  dk_Intro_CanPlay,
  STR_AudioGroup,
  STR_Body,
  STR_Count,
  STR_Default,
  STR_Intro,
  STR_Loop,
  STR_Music,
  STR_Num,
  STR_Set,
  STR_Sound,
  STR_Theme,
  STR_Track,
  STR_Unique,
  STR_Volume,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { Audio, type SoundId } from './Audio'
import type { AudioGroup } from './playback'

const val = <T>(v: T | undefined, dflt?: T): T | 0 => (v === undefined ? (dflt === undefined ? 0 : dflt) : v)

/**
 * `add_sound_data(sound resource, *volume, *music theme, *music set, *music intro, *will loop)`
 *
 * Registers a sound (and its optional intro) under a theme/set and maintains ZALiA's index maps:
 *
 *       THEME: | Title      Overworld  Battle     Dungeon1   Dungeon2
 * ------------------------------------------------------------------------
 * SET:
 * STR_Default  | sound id.  sound id.  sound id.  sound id.  sound id.
 * Chiming      | sound id.  sound id.  sound id.  sound id.  sound id.
 *
 * A SoundObject_DK (`theme+set`) is a unique key; per-theme track lists (`_Track`, `_Unique_Track`) drive the
 * RANDOM audio sets. Returns the sound.
 */
export function add_sound_data(
  sound: string,
  volume = 1,
  theme: string | 0 = 0,
  set: string = STR_Default,
  intro: SoundId = 0,
  loop: boolean | -1 = -1,
): string {
  const dm = Audio.dm
  const _VOLUME = Math.min(1, Math.max(0, volume))
  const _SOUND_NAME = sound
  const _INTRO_NAME = intro ? intro : 0

  const groupKey = `${STR_AudioGroup}_${_SOUND_NAME.slice(0, 3)}`
  const _AUDIO_GROUP = val(dm.get(groupKey), 'snd') as AudioGroup
  dm.set(_SOUND_NAME + STR_AudioGroup, _AUDIO_GROUP)
  dm.set(_SOUND_NAME + STR_Volume, val(dm.get(_SOUND_NAME + STR_Volume), _VOLUME))

  if (typeof theme === 'string') {
    let _num: number
    let _dk: string
    // When playing a sound, it needs more data than just the audio asset; what its intro or body is,
    // what its audiogroup is, what its volume is, etc. There are also scenarios where audio assets may be
    // found more than once in a theme if an audio set is re-using it.
    const _SoundObject_DK = theme + set
    if (dm.get(_SoundObject_DK) === undefined) dm.set(_SoundObject_DK, sound)
    if (loop !== -1) dm.set(_SoundObject_DK + STR_Loop, loop)
    if (dm.get(_SoundObject_DK + STR_Body) === undefined) dm.set(_SoundObject_DK + STR_Body, sound)
    if (_INTRO_NAME && dm.get(_SoundObject_DK + STR_Intro) === undefined)
      dm.set(_SoundObject_DK + STR_Intro, _INTRO_NAME)

    if (_INTRO_NAME) {
      dm.set(_INTRO_NAME + STR_AudioGroup, _AUDIO_GROUP)
      dm.set(_INTRO_NAME + STR_Volume, _VOLUME)
      dm.set(theme + dk_Intro_CanPlay, true)
      dm.set(_SOUND_NAME + dk_Intro_CanPlay, true)
      dm.set(_SOUND_NAME + STR_Intro, _INTRO_NAME) // _SOUND/_SOUND_NAME is the body
      dm.set(_INTRO_NAME + STR_Body, sound)
      dm.set(`${_INTRO_NAME}_Is${STR_Intro}`, true)
    }

    // --------------------------------------------------------
    const _dk_GROUP: string = _AUDIO_GROUP === 'snd' ? STR_Sound : STR_Music

    // Index all theme names
    _dk = STR_Theme + STR_Count
    if (dm.get(theme + STR_Num) === undefined) {
      dm.set(_dk, (val(dm.get(_dk)) as number) + 1)
      _num = dm.get(_dk) as number
      dm.set(STR_Theme + hexStr(_num), theme)
      dm.set(theme + STR_Num, _num)
    }
    // Index themes that have at least 1 _dk_GROUP track
    if (dm.get(theme + _dk_GROUP + STR_Num) === undefined) {
      dm.set(_dk + _dk_GROUP, (val(dm.get(_dk + _dk_GROUP)) as number) + 1)
      _num = dm.get(_dk + _dk_GROUP) as number
      dm.set(STR_Theme + _dk_GROUP + hexStr(_num), theme)
      dm.set(theme + _dk_GROUP + STR_Num, _num)
    }

    // --------------------------------------------------------
    // Indexing the tracks of this theme
    _dk = theme + STR_Track
    dm.set(_dk + STR_Count, (val(dm.get(_dk + STR_Count)) as number) + 1)
    _num = dm.get(_dk + STR_Count) as number
    dm.set(_dk + hexStr(_num), sound)
    dm.set(_dk + hexStr(_num) + STR_Set, set)
    dm.set(_dk + hexStr(_num) + STR_Body, sound)
    if (_INTRO_NAME) dm.set(_dk + hexStr(_num) + STR_Intro, _INTRO_NAME)

    dm.set(_dk + STR_Count + _dk_GROUP, (val(dm.get(_dk + STR_Count + _dk_GROUP)) as number) + 1)
    _num = dm.get(_dk + STR_Count + _dk_GROUP) as number
    dm.set(_dk + _dk_GROUP + hexStr(_num), sound)
    dm.set(_dk + _dk_GROUP + hexStr(_num) + STR_Set, set)
    dm.set(_dk + _dk_GROUP + hexStr(_num) + STR_Body, sound)
    if (_INTRO_NAME) dm.set(_dk + _dk_GROUP + hexStr(_num) + STR_Intro, _INTRO_NAME)

    // --------------------------------------------------------
    // Indexing the tracks of this theme as a list with no duplicates
    _dk = theme + STR_Unique + STR_Track
    if (dm.get(_dk + STR_Num + _SOUND_NAME) === undefined) {
      // if is a unique track for this theme
      dm.set(_dk + STR_Count, (val(dm.get(_dk + STR_Count)) as number) + 1)
      _num = dm.get(_dk + STR_Count) as number
      dm.set(_dk + STR_Num + _SOUND_NAME, _num)
      dm.set(_dk + hexStr(_num), sound)
      dm.set(_dk + hexStr(_num) + STR_Set, set)
      dm.set(_dk + hexStr(_num) + STR_Body, sound)
      if (_INTRO_NAME) dm.set(_dk + hexStr(_num) + STR_Intro, _INTRO_NAME)

      dm.set(_dk + STR_Count + _dk_GROUP, (val(dm.get(_dk + STR_Count + _dk_GROUP)) as number) + 1)
      _num = dm.get(_dk + STR_Count + _dk_GROUP) as number
      dm.set(_dk + STR_Num + _SOUND_NAME + _dk_GROUP, _num)
      dm.set(_dk + _dk_GROUP + hexStr(_num), sound)
      dm.set(_dk + _dk_GROUP + hexStr(_num) + STR_Set, set)
      dm.set(_dk + _dk_GROUP + hexStr(_num) + STR_Body, sound)
      if (_INTRO_NAME) dm.set(_dk + _dk_GROUP + hexStr(_num) + STR_Intro, _INTRO_NAME)
    }
  }
  return sound
}
