// Ported from ZALiA scripts/g_Room_Start_1a.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively
import {
  dk_SceneRando,
  STR_Enemy,
  STR_Height,
  STR_ID,
  STR_Idx,
  STR_Item,
  STR_Method,
  STR_OBJVER,
  STR_Object,
  STR_obj_idx,
  STR_Randomize,
  STR_Randomized,
  STR_Respawn,
  STR_Scene,
  STR_Spawn,
  STR_Spawn_Permission,
  STR_Type,
  STR_Version,
  STR_Width,
} from '@z2/data'
import { hexStr as hex_str } from '../../../nes/hexStr'
import { gmBool, isVal } from '../../../nes/math8'
import { f, G, g } from '../../../runtime/world'
import { get_defeated_dk } from '../../game_object_mgr/spawn'
import { str_hex } from '../../other/index'
import { cam_xl_range } from '../../view/camera'
import {
  ds_grid_create,
  ds_grid_destroy,
  ds_grid_height,
  ds_grid_read,
  ds_grid_resize,
  ds_grid_width,
  ds_grid_write,
  is_string,
  is_undefined,
  object_get_name,
  string_copy,
  string_length,
  val,
} from '../gm'

/** GML: g_Room_Start_1a(encoded grid, spawn datakey, scene is randomized) */
export function g_Room_Start_1a(...argument: any[]) {
  // GML `var` is function-scoped; locals hoisted here:
  let _SCENE_IS_RANDOMIZED: any,
    _SCENE_USED: any,
    _SPAWN_DATAKEY: any,
    _arg: any,
    _defeated_count: any,
    _dg: any,
    _dg_encoded: any,
    _h: any,
    _h_: any,
    _idx: any,
    _idx1: any,
    _item_id: any,
    _item_type: any,
    _len: any,
    _obj: any,
    _obj_name: any,
    _objver1: any,
    _objver2: any,
    _respawn_type: any,
    _spawn_permission: any,
    _spawn_permission1: any,
    _spawn_xc: any,
    _spawn_xl: any,
    _spawn_yc: any,
    _spawn_yt: any,
    _val: any,
    _val1: any,
    _val2: any,
    _ver: any,
    _w: any,
    _w_: any
  _arg = 0
  _dg_encoded = argument[_arg++]
  _SPAWN_DATAKEY = argument[_arg++]
  _SCENE_IS_RANDOMIZED = argument[_arg++]
  _obj = val(g.dm_spawn.get(_SPAWN_DATAKEY + STR_obj_idx))
  if (!gmBool(_obj)) {
    return _dg_encoded
  }
  // let _idx: any, _idx1, _val, _val1, _val2, _len: any;
  // let _w: any, _w_, _h, _h_: any;
  // let _ver: any, _obj_name: any;
  // let _spawn_xl: any, _spawn_xc, _spawn_yt, _spawn_yc: any;
  // let _defeated_count: any, _respawn_type: any;
  _spawn_permission = 0
  _spawn_permission1 = 0
  _item_id = undefined as any
  _item_type = undefined as any
  _objver1 = undefined as any
  _objver2 = undefined as any
  _dg = ds_grid_create(0, 0)
  ds_grid_read(_dg, _dg_encoded)
  _obj_name = object_get_name(_obj)
  _ver = val(g.dm_spawn.get(_SPAWN_DATAKEY + STR_Version))
  _objver1 = _obj_name + hex_str(_ver)
  _w = val(g.dm_go_prop.get(_obj_name + STR_Width), 0x10)
  _h = val(g.dm_go_prop.get(_obj_name + STR_Height), 0x10)
  _w_ = _w >> 1
  _h_ = _h >> 1
  _spawn_xl = val(g.dm_spawn.get(`${_SPAWN_DATAKEY}_x`)) // spawn XL
  _spawn_yt = val(g.dm_spawn.get(`${_SPAWN_DATAKEY}_y`)) // spawn YT
  _spawn_xc = _spawn_xl + _w_
  _spawn_yc = _spawn_yt + _h_
  _defeated_count = val(f.dm_quests.get(get_defeated_dk() + _SPAWN_DATAKEY))
  // respawn_type: Value representing if and when GO can respawn.
  // 0: never, 1: off screen, 2: refresh area, 3: refresh rm, 4: 30 seconds (on or off screen)
  _respawn_type = val(g.dm_go_prop.get(_objver1 + STR_Respawn))
  _spawn_permission1 = val(g.dm_spawn.get(_SPAWN_DATAKEY + STR_Spawn_Permission))
  // -1 never spawn again
  if (_respawn_type === 3 && _spawn_permission1 !== -1) {
    g.dm_spawn.set(_SPAWN_DATAKEY + STR_Spawn_Permission, 1)
  }
  _spawn_permission = val(g.dm_spawn.get(_SPAWN_DATAKEY + STR_Spawn_Permission))
  // --------------------------------------------------------------
  if (!gmBool(_SCENE_IS_RANDOMIZED)) {
    _item_id = val(g.dm_spawn.get(_SPAWN_DATAKEY + STR_Item + STR_ID + STR_Randomized))
    if (is_string(_item_id)) {
      _item_type = val(g.dm_spawn.get(_item_id + STR_Item + STR_Type))
      if (is_string(_item_type)) {
        _obj = val(g.dm_ITEM.get(_item_type + STR_Object))
        _ver = val(g.dm_spawn.get(_item_id + STR_Version), 1)
        _obj_name = object_get_name(_obj)
        _objver2 = _obj_name + hex_str(_ver)
        _val = val(g.dm_go_prop.get(_obj_name + STR_Width), 0x10)
        _w = _val
        _w_ = _w >> 1
        _spawn_xl = _spawn_xc - _w_
        _val = val(g.dm_go_prop.get(_obj_name + STR_Height), 0x10)
        _spawn_yt = _spawn_yt + _h - _val
        _h = _val
        _h_ = _h >> 1
        _spawn_yc = _spawn_yt + _h_
      }
    } else {
      if (
        gmBool(G.EnemyRando_enabled) &&
        gmBool(val(G.dm_save_file_settings.get(STR_Randomize + STR_Enemy + STR_Method)))
      ) {
        switch (val(G.dm_save_file_settings.get(STR_Randomize + STR_Enemy + STR_Method))) {
          default: {
            _objver2 = f.dm_rando.get(
              STR_Randomize + STR_Enemy + STR_Spawn + _SPAWN_DATAKEY + STR_OBJVER + STR_Randomized,
            )
            break
          }
          case 2: {
            _objver2 = f.dm_rando.get(
              STR_Randomize + STR_Enemy + STR_Type + _objver1 + STR_OBJVER + STR_Randomized,
            )
            break
          }
        } // _objver2 example: "Snaraa01". obj name + ver
        if (!is_undefined(_objver2)) {
          _len = string_length(_objver2)
          _val1 = string_copy(_objver2, 1, _len - 2) // obj name
          _val2 = g.dm_go_prop.get(_val1 + STR_Object + STR_Idx) // obj
          if (!is_undefined(_val2)) {
            if (gmBool(G.SceneRando_enabled)) {
              _SCENE_USED = val(
                f.dm_rando.get(dk_SceneRando + STR_Scene + STR_Randomized + g.rm_name),
                g.rm_name,
              )
            } else {
              _SCENE_USED = g.rm_name
            }
            // *** Cutscene_CreateWaterfall_update() checks for any hard skin enemies and if PC can defeat them
            // All enemies must be defeated in this rm
            // these enemies draw behind the wall so restrict them for now
            if (
              _SCENE_USED !== val(g.dm_rm.get('NabooruQuest_RM_NAME')) ||
              !isVal(_val2, 'GeldA', 'GlzmA', 'LeevA')
            ) {
              // Spawner_Mau, Spawner_Wosu, all need camera scroll to work
              if (gmBool(cam_xl_range()) || !isVal(_val2, 'SpMaA', 'SpWoA')) {
                _obj = _val2
                _obj_name = _val1
                _ver = string_copy(_objver2, _len - 1, 2)
                _ver = str_hex(_ver)
                _val = val(g.dm_go_prop.get(_obj_name + STR_Width), 0x10)
                _w = _val
                _w_ = _w >> 1
                _spawn_xl = _spawn_xc - _w_
                _val = val(g.dm_go_prop.get(_obj_name + STR_Height), 0x10)
                _spawn_yt = _spawn_yt + _h - _val
                _h = _val
                _h_ = _h >> 1
                _spawn_yc = _spawn_yt + _h_
                if (_obj === 'TektA') {
                  // Temporary fix bc Tektites are falling through bridges
                  _spawn_yt -= 0x10
                  _spawn_yc = _spawn_yt + _h_
                }
                g.dm_spawn.set(_SPAWN_DATAKEY + STR_Spawn_Permission, _spawn_permission1)
                _respawn_type = val(g.dm_go_prop.get(_objver2 + STR_Respawn))
                if (_respawn_type === 3) {
                  g.dm_spawn.set(_SPAWN_DATAKEY + STR_Spawn_Permission, 1)
                }
                _spawn_permission = val(g.dm_spawn.get(_SPAWN_DATAKEY + STR_Spawn_Permission))
              }
            }
          }
        }
      }
    }
  }
  // --------------------------------------------------------------
  _idx1 = ds_grid_width(_dg)
  ds_grid_resize(_dg, _idx1 + 1, ds_grid_height(_dg))
  _idx = 0
  _dg.set(_idx1, _idx++, _SPAWN_DATAKEY) //
  _dg.set(_idx1, _idx++, _obj) //
  _dg.set(_idx1, _idx++, _obj_name) //
  _dg.set(_idx1, _idx++, _ver) //
  //                                          //
  _dg.set(_idx1, _idx++, _spawn_xl) //
  _dg.set(_idx1, _idx++, _spawn_xc) //
  _dg.set(_idx1, _idx++, _spawn_yt) //
  _dg.set(_idx1, _idx++, _spawn_yc) //
  //                                          //
  _dg.set(_idx1, _idx++, _w) //
  _dg.set(_idx1, _idx++, _w_) //
  _dg.set(_idx1, _idx++, _h) //
  _dg.set(_idx1, _idx++, _h_) //
  //                                          //
  _dg.set(_idx1, _idx++, _respawn_type) //
  _dg.set(_idx1, _idx++, _defeated_count) //
  _dg.set(_idx1, _idx++, _spawn_permission) //
  //show_debug_message(_SPAWN_DATAKEY+", "+_obj_name+"-"+string(_ver)+", xl $"+hex_str(_spawn_xl)+" yt $"+hex_str(_spawn_yt)+", _w $"+hex_str(_w)+" _h $"+hex_str(_h)+", _respawn_type "+string(_respawn_type)+", _spawn_permission"+string(_spawn_permission));
  _dg_encoded = ds_grid_write(_dg)
  ds_grid_destroy(_dg)
  _dg = undefined as any
  return _dg_encoded
}
