/** GO_init_palidx, GO_add_palidx_set, GO_pal_qual_lit, GO_update_pal_flash (scripts/game_object/go) */
import { bitCount } from '../../../nes/math8'
import { type GameObject, Item } from '../classes'
import { deps } from '../deps'
import { pp } from '../pending'

/** Objects whose palette is "lit" even in dark rooms (GO_pal_qual_lit's is_ancestor_ list, by object name). */
const LIT_OBJECTS = new Set([
  'ElevA',
  'LoDoA',
  'ReFaA',
  'Blaze01',
  'FiRoA',
  'Fireball1',
  'Fireball2',
  'Flame1',
  'Flame2',
])

/** `GO_init_palidx(palette index, *palette permut num)` — permutation 0-5 reorders the base colours. */
export function GO_init_palidx(self: GameObject, palidx: number, permut?: number): void {
  self.palidx_def = palidx
  if (permut !== undefined) self.palidx_permut = permut
  const name = `${self.objectName} permut `
  switch (self.palidx_permut) {
    case 1:
      self.palidx_def = deps.add_pi_permut(self.palidx_def, 'WBRGYKMC', `${name}WBRGYKMC`)
      break // hsm
    case 2:
      self.palidx_def = deps.add_pi_permut(self.palidx_def, 'RWBGMYKC', `${name}RWBGMYKC`)
      break // mhs
    case 3:
      self.palidx_def = deps.add_pi_permut(self.palidx_def, 'RBWGMKYC', `${name}RBWGMKYC`)
      break // msh
    case 4:
      self.palidx_def = deps.add_pi_permut(self.palidx_def, 'BWRGKYMC', `${name}BWRGKYMC`)
      break // shm
    case 5:
      self.palidx_def = deps.add_pi_permut(self.palidx_def, 'BRWGKMYC', `${name}BRWGKMYC`)
      break // smh
  }
  self.palidx_base = self.palidx_def
  self.palidx = self.palidx_base
}

/** `GO_add_palidx_set()` — adds p.PI_LIT1 or p.PI_DRK1 to palidx_base */
export function GO_add_palidx_set(self: GameObject): void {
  if (deps.rm_pal_qual_lit() || GO_pal_qual_lit(self)) self.palidx_base += pp().PI_LIT1
  else self.palidx_base += pp().PI_DRK1
}

/** `GO_pal_qual_lit()` */
export function GO_pal_qual_lit(self: GameObject): boolean {
  return (
    self.state === self.state_EXPLODE ||
    self.state === self.state_DROP ||
    self instanceof Item ||
    LIT_OBJECTS.has(self.objectName)
  )
}

/** `GO_update_pal_flash(timer, per frames)` — cycles p.dg_PI_SEQ row 0 (reg/red/org/lnk) while stunned. */
export function GO_update_pal_flash(timer: number, perFrames: number): number {
  const _TIME = timer >> Math.max(0, bitNum(perFrames) - 1) // _timer >>0,1,2,3,4,5
  return (pp().dg_PI_SEQ.get(0, _TIME & 0x3) as number) + pp().PI_LIT1
}

/** GML `bitNum(x)`: number of bits needed to represent x (position of the highest set bit + 1). */
function bitNum(x: number): number {
  let n = 0
  let v = x >>> 0
  while (v) {
    n++
    v >>>= 1
  }
  return n || bitCount(0)
}
