/** `get_spawn_datakey(rm_name, type, spawn data index)` — pass -1 for the rm's spawn count key. */
export function get_spawn_datakey(rmName: string, type: string, spawnIdx: number): string {
  if (spawnIdx === -1) return rmName + type + STR_Count
  return rmName + type + hexStr(spawnIdx)
}

/** `get_defeated_dk()` */
export function get_defeated_dk(): string {
  return `${STR_File + STR_Quest + hexStr(fp().quest_num) + STR_Defeated}_`
}

/** `spawn_data_set_default()` — restore every spawn's x/y and permission from the defaults (new file / area refresh). */
export function spawn_data_set_default(): void {
  const g = gp()
  for (let _i = g.dl_AREA_NAME.size - 1; _i >= 0; _i--) {
    // Each area
    for (let _j = 0; _j < 0x100; _j++) {
      // Each room of the area
      const _rm_name = (g.dl_AREA_NAME.get(_i) as string) + hexStr(_j)
      for (let _k = 0; _k < 2; _k++) {
        // PRoXiMity type spawns, then PRIOrity type spawns
        const _spawn_trigger = _k ? STR_PRIO : STR_PRXM
        const _count = g.dm_spawn.val(_rm_name + _spawn_trigger + STR_Count) as number
        for (let _m = 0; _m < _count; _m++) {
          // Each gob/entity of the room
          const _dk = _rm_name + _spawn_trigger + hexStr(_m)
          g.dm_spawn.set(`${_dk}_x`, g.dm_spawn_DEFAULT.val(`${_dk}_x`))
          g.dm_spawn.set(`${_dk}_y`, g.dm_spawn_DEFAULT.val(`${_dk}_y`))
          if (g.dm_spawn.get(_dk + STR_Spawn_Permission) !== -1) g.dm_spawn.set(_dk + STR_Spawn_Permission, 1)
        }
      }
      let _count = 1
      let _dk = _rm_name + STR_Challenge + hexStr(_count++)
      while (g.dm_spawn.get(_dk + STR_obj_idx) !== undefined) {
        if (isAncestorName(g.dm_spawn.get(_dk + STR_obj_idx) as ObjectName, 'TogglingPathDirection')) {
          // 1: Forward, -1: Backward
          g.dm_spawn.set(_dk + STR_Direction, g.dm_spawn_DEFAULT.val(_dk + STR_Direction))
        }
        _dk = _rm_name + STR_Challenge + hexStr(_count++)
      }
    }
  }
}

/** `update_go_spawn_1d(object_index, version, inst spawn datakey)` → true if defeated and never respawns. */
export function update_go_spawn_1d(obj: ObjectName, ver: number, spawnDk: string): boolean {
  let _datakey = get_defeated_dk() + spawnDk
  const _DEFEATED_COUNT = fp().dm_quests.val(_datakey) as number // num of times defeated boss in this rm
  // respawn_type: 0: never, 1: off screen, 2: refresh area, 3: refresh rm, 4: 30 seconds (on or off screen)
  _datakey = obj + hexStr(ver) + STR_Respawn
  const _RESPAWN_TYPE = goData.dm_go_prop.val(_datakey) as number
  return !_RESPAWN_TYPE && !!_DEFEATED_COUNT // Has been defeated and never respawns
}

/** `go_spawn_enter_room()` — D5xx room-entry spawning: PRIO objects, then PRXM in the enlarged spawn area. */
export function go_spawn_enter_room(): void {
  const g = gp()
  const p = pc()
  p.state = p.state_SPAWN
  go_spawn_priorities() // PRIO only. Keys, Elevators, LockedDoors, etc...
  update_go_spawn_1b(true) // PRXM(proximity) spawn only
  // -------------------------------------------------------------------------------
  if (g.mod_SAFE_ENCOUNTER_ENEMIES && world.irandom(1)) {
    const _ENC_TYPES = deps.rm_get_encounter_types(g.rm_name)
    if (!_ENC_TYPES || _ENC_TYPES & g.ENC_FARY) return
    for (const e of world.instancesOf(GOB1)) {
      if (e.state === e.state_NORMAL) return // If there's an enemy spawned, this isn't a safe encounter rm.
    }
    if (!deps.is_safe_encounter_rm()) return
    // -------------------------------------------------------------------------------
    const _DIR = sign_(p.x < g.rm_w_)
    const _DIST1 = Math.abs(p.x - g.rm_w_) + g.rm_w_
    const _DIST2 = 0x3 << 3
    const _COUNT = world.irandom(1) + 1 // 1,2
    for (let _i = 0; _i < _COUNT; _i++) {
      let _x = Math.max(world.irandom(_DIST1 >> 3), 8)
      _x = p.x + (_x << 3) * _DIR
      _x = Math.min(Math.max(_x, _DIST2), g.rm_w - _DIST2)
      let _y = g.rm_rows - PAGE_ROWS // first row of btm-most page
      _y += 0x10
      _y = _y << 3
      _y = deps.get_ground_y(_x, _y, 1, _y)
      _y -= 0x10
      const inst = GameObject_create(_x, _y, 'Bot_A', world.irandom(1) + 1)
      if (inst) {
        const _clm = inst.x >> 3
        const _row = (inst.yb - 4) >> 3
        if (((GG().dg_solid.get(_clm, _row) as number) & 0xff) === TID_SOLID1) {
          let _y2 = _row << 3
          _y2 = deps.get_ground_y(inst.x, _y2, -1, _y2)
          set_xy(inst, inst.x, _y2 - inst.hh_)
        }
      }
    }
  }
}

/** `go_spawn_priorities()` — PRIO spawns: items, then GOB1/GOB2, pushables, fairy encounter, platforms. */
export function go_spawn_priorities(): void {
  const g = gp()
  const f = fp()
  const _RM_SPAWN_COUNT_PRIO = g.dg_spawn_prio.width
  const _SCENE_USED = GG().SceneRando_enabled
    ? ((f.dm_rando.get(dk_SceneRando + STR_Scene + STR_Randomized + g.rm_name) as string | undefined) ??
      g.rm_name)
    : g.rm_name
  //  ------------  Items  --------------------------------------------
  for (let _i = 0; _i < _RM_SPAWN_COUNT_PRIO; _i++) {
    const _dk_spawn = g.dg_spawn_prio.get(_i, 0) as string
    const _obj0 = g.dm_spawn.get(_dk_spawn + STR_obj_idx) as ObjectName | undefined
    if (_obj0 === undefined || !isAncestorName(_obj0, 'Item')) continue
    const _obj = g.dg_spawn_prio.get(_i, 1) as ObjectName
    const _ver = g.dg_spawn_prio.get(_i, 3) as number
    const _xl = g.dg_spawn_prio.get(_i, 4) as number
    const _yt = g.dg_spawn_prio.get(_i, 6) as number
    const _obj_name = _obj
    let _item_id = g.dm_spawn.get(_dk_spawn + STR_Item + STR_ID + STR_Randomized) as string | undefined
    if (_item_id === undefined) {
      _item_id = g.dm_spawn.get(_dk_spawn + STR_Item + STR_ID) as string | undefined
      if (_item_id === undefined) continue
    }
    let _item_type = g.dm_spawn.get(_dk_spawn + STR_Item + STR_Type)
    if (_item_type === undefined) {
      _item_type = g.dm_ITEM.get(_obj_name + STR_Item + STR_Type)
      if (_item_type === undefined) continue
    }
    if (!deps.item_acquired(_item_id)) {
      const inst = GameObject_create(_xl, _yt, _obj, _ver, _dk_spawn)
      if (inst) {
        inst.vspd = 1
        if (inst instanceof Item) inst.ITEM_ID = _item_id
      }
    }
  }
  //  ---------------------  PRIO GOB1&2  -------------------------
  for (let _i = 0; _i < _RM_SPAWN_COUNT_PRIO; _i++) {
    const _dk_spawn = g.dg_spawn_prio.get(_i, 0) as string
    if (!g.dm_spawn.val(_dk_spawn + STR_Spawn_Permission)) continue // already used/opened/defeated..
    if (
      deps.rm_get_encounter_types(_SCENE_USED) &&
      Math.sign(g.encounter_type & g.ENC_STRG) !==
        Math.sign(g.dm_spawn.val(_dk_spawn + STR_Strong + STR_Encounter) as number)
    ) {
      continue
    }
    const _obj = g.dg_spawn_prio.get(_i, 1) as ObjectName
    const _ver = g.dg_spawn_prio.get(_i, 3) as number
    const _xl = g.dg_spawn_prio.get(_i, 4) as number
    const _yt = g.dg_spawn_prio.get(_i, 6) as number
    if (isAncestorName(_obj, 'Item') || isAncestorName(_obj, 'PushA')) continue
    // if has been defeated and respawn type is NEVER
    if (update_go_spawn_1d(_obj, _ver, _dk_spawn)) continue
    GameObject_create(_xl, _yt, _obj, _ver, _dk_spawn)
    if (g.dm_spawn.get(_dk_spawn + STR_Spawn_Permission) !== undefined)
      g.dm_spawn.set(_dk_spawn + STR_Spawn_Permission, 0)
  }
  // Pushables: spawned at their saved (quest) position if they were moved to this scene
  const _obj_name = 'PushA'
  const _count = g.dm_spawn.val(_obj_name + STR_Count) as number
  for (let _i = 1; _i <= _count; _i++) {
    const _datakey1 = _obj_name + hexStr(_i)
    const _dk_spawn = g.dm_spawn.get(_datakey1 + STR_Spawn + STR_Datakey) as string | undefined
    if (_dk_spawn === undefined) continue
    if (!g.dm_spawn.val(_dk_spawn + STR_Spawn_Permission)) continue // already used/opened/defeated..
    let _qual = false
    const _scene_name = g.dm_spawn.val(_datakey1 + STR_Rm + STR_Name)
    const _val = f.dm_quests.get(_dk_spawn + STR_Rm)
    if (_SCENE_USED === _scene_name) {
      if (_val === undefined || _SCENE_USED === _val) _qual = true
    } else if (_val !== undefined && _SCENE_USED === _val) {
      _qual = true
    }
    if (_qual) {
      let _xl = g.dm_spawn.val(`${_dk_spawn}_x`) as number
      _xl = ((f.dm_quests.val(`${_dk_spawn}_XL`, _xl) as number) >> 3) << 3
      let _yt = g.dm_spawn.val(`${_dk_spawn}_y`) as number
      _yt = f.dm_quests.val(`${_dk_spawn}_YT`, _yt) as number
      const _ver = g.dm_spawn.val(_dk_spawn + STR_version, 1) as number
      GameObject_create(_xl, _yt, _obj_name, _ver, _dk_spawn)
      if (g.dm_spawn.get(_dk_spawn + STR_Spawn_Permission) !== undefined)
        g.dm_spawn.set(_dk_spawn + STR_Spawn_Permission, 0)
    }
  }
  // FAIRY ENCOUNTER -------------------------------------------------------
  if (g.encounter_type & g.ENC_FARY) {
    const _xl = g.rm_w_ - 4
    let _yt = g.rm_row0 << 3
    _yt = deps.get_ground_y(g.rm_w_, _yt, 1, (g.rm_row0 + 0x12) << 3)
    const inst = GameObject_create(_xl, _yt, 'ReFaA', 1)
    if (inst) set_xy(inst, g.rm_w_, inst.y)
  }
  //  ------------  Platforms  ---------------------------
  let _count2 = 1
  let _dk_spawn = _SCENE_USED + STR_Platform + hexStr(_count2++)
  while (g.dm_spawn.get(_dk_spawn + STR_obj_idx) !== undefined) {
    const _obj = g.dm_spawn.get(_dk_spawn + STR_obj_idx) as ObjectName
    const _ver = g.dm_spawn.get(_dk_spawn + STR_version) as number
    const _xl = g.dm_spawn.get(`${_dk_spawn}_x`) as number
    const _yt = g.dm_spawn.get(`${_dk_spawn}_y`) as number
    GameObject_create(_xl, _yt, _obj, _ver, _dk_spawn)
    _dk_spawn = _SCENE_USED + STR_Platform + hexStr(_count2++)
  }
}

/**
 * `update_go_spawn_1b(enter room spawning)` — proximity spawning from `g.dg_spawn_prxm`. On room entry
 * everything inside the view ± SPAWN_DIST1 spawns; per frame, `qual_spawn_3a` admits objects just outside
 * the view on the side the camera is moving toward. D625.
 */
export function update_go_spawn_1b(_ENTER_RM_SPAWN: boolean): void {
  const g = gp()
  if (g.encounter_type & g.ENC_FARY) return
  const _GO_COUNT = g.dg_spawn_prxm.width
  if (!_GO_COUNT) return
  // D625
  if (available_update_idx_gob(MAX_GOB1) === UIDX_NULL) return
  const _defeated_DK = get_defeated_dk()
  let _SpawnArea_XL = 0
  let _SpawnArea_YT = 0
  let _SpawnArea_W = 0
  let _SpawnArea_H = 0
  if (_ENTER_RM_SPAWN) {
    _SpawnArea_XL = deps.viewXL() - g.SPAWN_DIST1_X
    _SpawnArea_YT = deps.viewYT() - g.SPAWN_DIST1_Y
    _SpawnArea_W = deps.viewW() + (g.SPAWN_DIST1_X << 1)
    _SpawnArea_H = deps.viewH() + (g.SPAWN_DIST1_Y << 1)
  }
  for (let _i = 0; _i < _GO_COUNT; _i++) {
    let _a = 0
    const col = () => g.dg_spawn_prxm.get(_i, _a++)
    const _spawn_dk = col() as string
    // 1: avail to spawn, 0: spawned/can't respawn, -1: can't spawn again
    if (g.dm_spawn.val(_spawn_dk + STR_Spawn_Permission) !== 1) continue
    if (g.encounter_type) {
      const _val = !!g.dm_spawn.val(_spawn_dk + STR_Strong + STR_Encounter)
      if (_val !== !!(g.encounter_type & g.ENC_STRG)) continue
    }
    const _obj = col() as ObjectName
    col() // _obj_name
    const _ver = col() as number
    const _spawn_xl = col() as number
    const _spawn_xc = col() as number
    const _spawn_yt = col() as number
    const _spawn_yc = col() as number
    const _w = col() as number
    const _w_ = col() as number
    const _h = col() as number
    const _h_ = col() as number
    const _respawn_type = col() as number
    let _defeated_count = g.dg_spawn_prxm.get(_i, _a) as number
    if (!_defeated_count) g.dg_spawn_prxm.set(_i, _a, fp().dm_quests.val(_defeated_DK + _spawn_dk) as number)
    _defeated_count = g.dg_spawn_prxm.get(_i, _a++) as number
    // D658
    if (!_respawn_type && _defeated_count) continue // Has been defeated and respawn type is NEVER
    if (_ENTER_RM_SPAWN) {
      let _SpawnArea_xl = _SpawnArea_XL - _w_
      let _SpawnArea_yt = _SpawnArea_YT - _h_
      let _SpawnArea_w = _SpawnArea_W + _w
      let _SpawnArea_h = _SpawnArea_H + _h
      if (_respawn_type === 1) {
        // respawn type 1: off screen (infinite respawn) — match the extra dist in qual_spawn_3a()
        _SpawnArea_xl -= g.SPAWN_DIST2_X
        _SpawnArea_yt -= g.SPAWN_DIST2_Y
        _SpawnArea_w += g.SPAWN_DIST2_X << 1
        _SpawnArea_h += g.SPAWN_DIST2_Y << 1
      }
      if (!deps.pointInRect(_spawn_xc, _spawn_yc, _SpawnArea_xl, _SpawnArea_yt, _SpawnArea_w, _SpawnArea_h))
        continue
    } else if (!qual_spawn_3a(_spawn_xl, _w_, _spawn_yt, _h_, _respawn_type)) {
      continue
    }
    // Spawn GO -----------------------------------------------
    const _inst = GameObject_create(_spawn_xl, _spawn_yt, _obj, _ver, _spawn_dk)
    if (_inst !== NOONE) {
      if (g.dm_spawn.get(_spawn_dk + STR_Spawn_Permission) !== undefined)
        g.dm_spawn.set(_spawn_dk + STR_Spawn_Permission, 0)
      // OG spawned only 1 per frame; ZALiA turned that off 2022/03/19 (fast vertical camera missed spawns).
    }
  }
}

/** `qual_spawn_3a(spawn x, ww_, spawn y, hh_, *respawn type)` — is this spawn point just outside the view on the approach side? */
export function qual_spawn_3a(
  spawnX: number,
  ww_: number,
  spawnY: number,
  hh_: number,
  respawnType = 0,
): boolean {
  const g = gp()
  if ((g.view_lock & 0xf) === 0xf) return false
  const _XC = spawnX + ww_ // spawn xc
  const _YC = spawnY + hh_ // spawn yc
  let _RX = deps.viewXL() - ww_
  let _RY = deps.viewYT() - hh_
  let _RW = deps.viewW() + (ww_ << 1)
  let _RH = deps.viewH() + (hh_ << 1)
  if (respawnType === 1) {
    // respawn type 1: off screen (inifinite respawn)
    _RX -= g.SPAWN_DIST2_X
    _RW += g.SPAWN_DIST2_X << 1
    _RY -= g.SPAWN_DIST2_Y
    _RH += g.SPAWN_DIST2_Y << 1
  }
  if (
    deps.pointInRect(_XC, _YC, _RX, _RY, _RW, _RH) ||
    !deps.pointInRect(
      _XC,
      _YC,
      _RX - g.SPAWN_DIST1_X,
      _RY - g.SPAWN_DIST1_Y,
      _RW + (g.SPAWN_DIST1_X << 1),
      _RH + (g.SPAWN_DIST1_Y << 1),
    )
  ) {
    return false
  }
  let _QUADRANT = 0x0
  if (_XC >= _RX + _RW)
    _QUADRANT |= 0x1 // right
  else if (_XC <= _RX) _QUADRANT |= 0x2 // left
  if (_YC >= _RY + _RH)
    _QUADRANT |= 0x4 // bottom
  else if (_YC <= _RY) _QUADRANT |= 0x8 // top
  if (!_QUADRANT) return false
  if (_QUADRANT & 0x1) {
    // right
    if (gmBool(g.view_dir_x) && !(g.view_lock & 0x1)) {
      const _CLM1 = (_RX + _RW) >> 3
      const _CLM2 = (_RX + _RW + g.SPAWN_DIST1_X) >> 3
      return deps.inRange(_XC >> 3, _CLM1, _CLM2)
    }
  } else if (_QUADRANT & 0x2) {
    //  left
    if (!gmBool(g.view_dir_x) && !(g.view_lock & 0x2)) {
      const _CLM1 = _RX >> 3
      const _CLM2 = (_RX - g.SPAWN_DIST1_X) >> 3
      return deps.inRange(_XC >> 3, _CLM2, _CLM1)
    }
  }
  if (_QUADRANT & 0x4) {
    // bottom
    if (gmBool(g.view_dir_y) && !(g.view_lock & 0x4)) {
      const _ROW1 = (_RY + _RH) >> 3
      const _ROW2 = (_RY + _RH + g.SPAWN_DIST1_Y) >> 3
      return deps.inRange(_YC >> 3, _ROW1, _ROW2)
    }
  } else if (_QUADRANT & 0x8) {
    // top
    if (!gmBool(g.view_dir_y) && !(g.view_lock & 0x8)) {
      const _ROW1 = _RY >> 3
      const _ROW2 = (_RY - g.SPAWN_DIST1_Y) >> 3
      return deps.inRange(_YC >> 3, _ROW2, _ROW1)
    }
  }
  return false
}

