/**
 * Sprite metadata (`sprite_get_width/height/xoffset/yoffset`) for GameObjects, served by the single
 * provider in game/graphics/sprites.ts (sprites.json via `setSpriteManifest`). Tests may install a stub.
 */
import { hasSpriteInfo, spriteInfo } from '../graphics/sprites'

export interface SpriteMeta {
  width: number
  height: number
  xorig: number
  yorig: number
}

let override: ((sprite: string) => SpriteMeta | undefined) | undefined

export function setSpriteMetaProvider(fn: ((sprite: string) => SpriteMeta | undefined) | undefined): void {
  override = fn
}

export function spriteMeta(sprite: string): SpriteMeta {
  const m = override?.(sprite)
  if (m) return m
  if (hasSpriteInfo(sprite)) {
    const i = spriteInfo(sprite)
    return { width: i.width, height: i.height, xorig: i.originX, yorig: i.originY }
  }
  throw new Error(`sprite metadata for ${sprite} unavailable (manifest not loaded or unknown sprite)`)
}

/** Test helper: placement sprites by their `spr_Placement_WWxHH` name, centred origin like ZALiA's. */
export function stubSpriteMeta(extra: Record<string, SpriteMeta> = {}): void {
  setSpriteMetaProvider((s) => {
    if (extra[s]) return extra[s]
    const m = /^spr_Placement_(\d+)x(\d+)$/.exec(s)
    if (m) {
      const w = Number(m[1])
      const h = Number(m[2])
      return { width: w, height: h, xorig: w >> 1, yorig: h >> 1 }
    }
    return { width: 16, height: 16, xorig: 8, yorig: 8 }
  })
}
