/** `FiRoA` — ZALiA `gob1/fire_rope`: a chain of fireballs spinning around an anchor. */
import { CS_BD1, STR_Angle, STR_Duration, STR_Length, STR_MoveDir } from '@z2/data'
import { gmBool, gmRound as round } from '../../../../../nes/math8'
import { NOONE, type Ref } from '../../../../../runtime/instance'
import { G, g } from '../../../../../runtime/world'
import { rectInCirc, rectInRect } from '../../../../collision/geometry'
import { enemy_collide_pc_body } from '../../../../collision/pc'
import { drawPointCross } from '../../../../draw/index'
import { draw_sprite_rot } from '../../../../gui/deps'
import { registerObjectClass } from '../../../../other/registry'
import { pal_swap_reset, pal_swap_set } from '../../../../palette/scenePalette'
import { GOB2 } from '../../../classes'
import { GO_can_collide_this_frame, GO_update_cam_vars } from '../../../go/misc'
import { set_xy_len_ang } from '../../../go/movement'
import { pc } from '../../../goa/pc'
import { HostileFire_init_1, HostileFire_udp_1 } from '../../../goc/Projectile'
import { registerObject, registerScripts } from '../../../registry'
import { GameObjectB_init, update_EF11 } from '../../GameObjectB'
import { instancesOfName, lengthdir_x, lengthdir_y, sign } from '../shared'

const ROOM_SPEED = 60

/** ZALiA object `FiRoA` → parent GOB2 (objects/FiRoA.object.gmx). */
export class FiRoA extends GOB2 {
  readonly objectName = 'FiRoA' as const
  SPR_A: string = 'spr_Fireball2'
  FIREBALL_COUNT = 6
  fireball_count = 6
  SPIN_DIR = 1
  spin_dir = 1
  REV_DUR = 6
  rev_dur = 6
  SPEED1 = 1
  speed1 = 1
  ANGLE = 0
  angle = 0
  /** 0: No rot, 1: 90 deg, 2: 180 deg, 3: 270 deg — in degrees for draw_sprite_ */
  rotation = 0
}
registerObject('FiRoA', FiRoA)
registerObjectClass('FiRoA', FiRoA)

/** `FireRope_init1()` */
export function FireRope_init1(self: FiRoA): void {
  GameObjectB_init(self)
  self.SPR_A = 'spr_Fireball2'
  HostileFire_init_1(self as never, G.PI_MOB_ORG)
  self.FIREBALL_COUNT = 6
  self.fireball_count = self.FIREBALL_COUNT
  self.SPIN_DIR = 1 // 0: No spin. 1: Clockwise, -1: Counter-Clockwise
  self.spin_dir = self.SPIN_DIR
  self.REV_DUR = 6 // Duration (in seconds) it takes to make a full revolution
  self.rev_dur = self.REV_DUR
  self.SPEED1 = 1 // degree change per frame
  self.speed1 = self.SPEED1
  self.ANGLE = 0 // in degrees
  self.angle = self.ANGLE
  self.rotation = 0
}

/** `FireRope_init2()` */
export function FireRope_init2(self: FiRoA): void {
  HostileFire_init_1(self as never, G.PI_MOB_ORG)
  self.DRAW_YOFF = 0
  self.facing_dir = 1
  self.BodyHB_IDX = -1
  self.BodyHB_idx = self.BodyHB_IDX
  if (self.dk_spawn !== undefined) {
    const len = g.dm_spawn.get(self.dk_spawn + STR_Length)
    if (len !== undefined) self.FIREBALL_COUNT = len as number
    self.fireball_count = self.FIREBALL_COUNT
    const md = g.dm_spawn.get(self.dk_spawn + STR_MoveDir)
    if (md !== undefined) self.SPIN_DIR = md as number
    self.SPIN_DIR = sign(self.SPIN_DIR)
    self.spin_dir = self.SPIN_DIR
    const dur = g.dm_spawn.get(self.dk_spawn + STR_Duration)
    if (dur !== undefined) self.REV_DUR = dur as number
    self.rev_dur = self.REV_DUR
    const ang = g.dm_spawn.get(self.dk_spawn + STR_Angle)
    if (ang !== undefined) self.ANGLE = ang as number
    self.angle = self.ANGLE
  }
  self.SPEED1 = 360 / self.rev_dur / ROOM_SPEED
  self.speed1 = self.SPEED1
  set_xy_len_ang(self, self.spawn_xl, self.spawn_yt, self.fireball_count << 3, self.angle)
}

/** `FireRope_udp()` */
export function FireRope_udp(self: FiRoA): void {
  self.can_draw_self = true
  self.rotation = (((g.counter1 >> 2) & 0x03) ^ 0x03) * 90
  HostileFire_udp_1(self as never)
}

/** `colliding_FireRope(FireRope inst, XL, YT, W, H, *RADIUS)` — pass 0 to check all FireRopes. */
export function colliding_FireRope(
  inst: Ref<FiRoA> | 0,
  XL: number,
  YT: number,
  W: number,
  H: number,
  RADIUS = 0,
): Ref<FiRoA> {
  const ropes = inst ? [inst] : [...instancesOfName<FiRoA>('FiRoA')]
  for (const r of ropes) {
    r.BodyHB_can_draw = true
    for (let _i = r.fireball_count - 1; _i >= 0; _i--) {
      const _fireball_x = r.spawn_xl + round(lengthdir_x(_i << 3, r.angle))
      const _fireball_y = r.spawn_yt + round(lengthdir_y(_i << 3, r.angle))
      if (gmBool(RADIUS)) {
        if (rectInCirc(XL, YT, RADIUS, _fireball_x, _fireball_y, 1, 1)) return r
      } else if (rectInRect(XL, YT, W, H, _fireball_x, _fireball_y, 1, 1)) return r
    }
  }
  return NOONE
}

/** `FireRope_update()` */
export function FireRope_update(self: FiRoA): void {
  const P = pc()
  // You can set spin_dir to 0 to stop all movement.
  if (self.spin_dir !== 0) {
    set_xy_len_ang(self, self.spawn_xl, self.spawn_yt, self.fireball_count << 3, self.angle)
    self.angle += self.speed1 * -self.spin_dir // -spin_dir: bc, in degrees, clockwise goes backwards.
    if (self.angle <= 0) self.angle += 360
    else self.angle %= 360
  }
  GO_update_cam_vars(self)
  update_EF11(self)
  self.cs &= ~CS_BD1 // remove CS_LBD from cs
  if (
    self.state === self.state_NORMAL &&
    GO_can_collide_this_frame(self.update_idx) &&
    colliding_FireRope(self, P.BodyHB_xl, P.BodyHB_yt, P.BodyHB_w, P.BodyHB_h)
  )
    self.cs |= CS_BD1
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
}

/** `FireRope_draw()` */
export function FireRope_draw(self: FiRoA): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  for (let _i = self.fireball_count - 1; _i >= 0; _i--) {
    const _x = self.spawn_xl + round(lengthdir_x(_i << 3, self.angle))
    const _y = self.spawn_yt + round(lengthdir_y(_i << 3, self.angle))
    draw_sprite_rot(self.SPR_A, 0, _x, _y, -1, self.xScale, self.yScale, 0xffffff, 1, self.rotation)
  }
  pal_swap_reset()
  if (!gmBool(g.DevTools_state)) return
  if (!g.can_draw_hb) return
  if (!self.BodyHB_can_draw) return
  self.BodyHB_can_draw = false
  for (let _i = self.fireball_count - 1; _i >= 0; _i--) {
    const _x = self.spawn_xl + round(lengthdir_x(_i << 3, self.angle))
    const _y = self.spawn_yt + round(lengthdir_y(_i << 3, self.angle))
    drawPointCross(_x, _y)
  }
}

registerScripts({ FireRope_init1, FireRope_init2, FireRope_update, FireRope_udp, FireRope_draw })
