// GML string helpers (1-based) ---------------------------------------------------------------
const string_pos = (needle: string, hay: string) => hay.indexOf(needle) + 1
const string_copy = (s: string, index: number, count: number) => s.substr(index - 1, count)
const str_hex = (s: string) => {
  const v = Number.parseInt(s, 16)
  return Number.isNaN(v) ? 0 : v
}
/** `strR(str, pos)` — the string from 1-based `pos` to the end. */
const strR = (s: string, pos: number) => s.substring(pos - 1)

