      g.dg_anim_liquid.set(_i, 1, Math.max(0, bit1st(_dl_liquid_speed[_i] as number) - 1)) // 1: Speed. 0 or a single bit
      g.dg_anim_liquid.set(_i, 2, _dl_liquid_dir[_i]) // 2: Movement direction
      g.dg_anim_liquid.set(_i, 3, 0) // 3: Current x offset.
      g.dg_anim_liquid.set(_i, 4, 0) // 4: Current y offset.
      g.dg_anim_liquid.set(_i, 5, 0) // 5: Master x offset.
      const _val = _dl_liquid_yoff[_i] as number
      g.dg_anim_liquid.set(_i, 6, _val) // 6: Master y offset.
