/**
 * The overworld (`global.OVERWORLD`, ZALiA IDE folder `overworld`). Importing this module registers the
 * object's Create / Room Start hooks with the boot and room-change sequences; `Overworld_Step` and
 * `Overworld_Draw` are exported by their GML names for the game loop (`g_Step` room type "C" and the
 * Overworld draw event).
 */
import { G } from '../../runtime/world'
import { bootHooks } from '../obj_start/boot'
import { roomHooks } from '../rooms/roomChange'
import { createOverworld, type Overworld } from './Overworld'
import { Overworld_Room_Start } from './roomStart'

export * from './deps'
export * from './draw'
export * from './encounters'
export * from './helpers'
export * from './initData'
export * from './initData1'
export * from './Overworld'
export * from './roomStart'
export * from './step'
export * from './tiles'
export * from './udp'

/** `global.OVERWORLD` typed. */
export const overworld = (): Overworld => G.OVERWORLD as Overworld

/** Register the Overworld object's events with the boot / room-change sequences (idempotent). */
export function installOverworld(): void {
  bootHooks.Overworld_Create = () => {
    createOverworld()
  }
  roomHooks.roomStart.Overworld = () => {
    const ow = G.OVERWORLD as Overworld | undefined
    if (ow) Overworld_Room_Start(ow)
  }
}
// `installOverworld()` is called by `wireCore()` (calling it at import time hit the boot↔wire↔overworld import cycle).
