/**
 * GM `with (target) { … }` where the body also reads `other` (the enclosing instance). The callback
 * receives `(self, other)`. A class/constructor target iterates every live instance in creation order;
 * returning `true` from the callback is GML `break`.
 */
export function withOther<T, O>(
  target: T | Ref<any> | (abstract new (...a: any[]) => any) | undefined,
  outer: O,
  fn: (self: any, other: O) => unknown,
): unknown {
  if (target === undefined || target === NOONE || target === 0) return undefined
  if (typeof target === 'function') {
    for (const i of world.instancesOf(target as abstract new () => any))
      if (fn(i, outer) === true) return true
    return undefined
  }
  // A GML `return` inside `with(inst)` returns from the whole script: the callback's value is propagated.
  return fn(target, outer)
}

/** GML `real(str)` */
export const real = (v: any): number => (typeof v === 'number' ? v : Number.parseFloat(String(v)) || 0)

/** GM `background_colour` (read side: current clear colour; assignments go through set_background_color). */
export function background_colour(): number {
  return backgroundState.colour
}

/** `surface_resize(srf, w, h)` — surfaces are command lists here; resizing just records the size. */
export function surface_resize(s: Surface | unknown, w: number, h: number): void {
  if (surface_exists(s)) {
    const srf = s as unknown as { width: number; height: number }
    srf.width = w
    srf.height = h
  }
}
/** `draw_surface_part(srf, left, top, w, h, x, y)` */
export function draw_surface_part(
  s: unknown,
  left: number,
  top: number,
  w: number,
  h: number,
  x: number,
  y: number,
): void {
  draw_surface_part_ext(s, left, top, w, h, x, y, 1, 1, -1, 1)
}
export { surface_create }

/** `draw_sprite_` with the 10th GML argument (rotation) — rotated draws carry `rotation` degrees. */
export function draw_sprite_rot(
  sprite: string | 0 | undefined,
  subimg: number,
  x: number,
  y: number,
  palIdx: number,
  xscale: number,
  yscale: number,
  color: number,
  alpha: number,
  rotation: number,
): void {
  if (!sprite) return
  const swap = palIdx > 0.5 && (G.palette_image_w === undefined || palIdx < G.palette_image_w)
  pushCmd({
    kind: 'sprite',
    sprite,
    frame: subimg,
    x,
    y,
    xscale,
    yscale,
    palIdx: swap ? palIdx : -1,
    depth: drawState.depth,
    alpha,
    rotation,
    // GML colours are `$BBGGRR`; a `DrawCmd.tint` is 24-bit RGB (see `rooms/draw.ts`'s header).
    ...(color >= 0 ? { tint: bgrToRgb(color) } : {}),
  })
}

/**
 * `instance_number(obj)` — live instances of a class, or of an object *name*. GML object ids are
 * interchangeable with the names the port keeps on `objectName`, and the leaf classes the menus ask about
 * (`Ache01`, `Bot_A`) live in the entity ports, so the name form is the only one available here.
 */
export function instance_number(obj: (abstract new (...a: any[]) => any) | string): number {
  let n = 0
  if (typeof obj === 'string') {
    for (const i of world.instances) if (i.exists && (i as any).objectName === obj) n++
    return n
  }
  for (const _ of world.instancesOf(obj)) n++
  return n
}

/** `string_lettersdigits(str)` */
export const string_lettersdigits = (s: any): string => String(s).replace(/[^A-Za-z0-9]/g, '')

