// ---- audio playback queries (adapter fills Audio.playback) --------------------------------------------
export const audio_group_set_gain = (group: any, gain: number, _ms = 0): void =>
  (Audio as any).audio_group_set_gain(group, gain)
/** GML `x = !x` on a field that may be boolean or 0/1 number: keeps the field's type. */
export const toggle = <T extends number | boolean>(v: T): T =>
  (typeof v === 'boolean' ? !v : +!((v as number) > 0.5)) as T
export const audio_get_name = (snd: any): string => (Audio as any).audio_get_name?.(snd) ?? String(snd)
export const sound_get_name = audio_get_name
export const audio_sound_get_track_position = (inst: any): number => Audio.playback?.trackPosition(inst) ?? 0
/** `audio_sound_length(sound or instance)` in seconds; 0 while the asset's set is still unloaded. */
export const audio_sound_length = (snd: unknown): number =>
  typeof snd === 'string' || typeof snd === 'number' ? (snd ? (Audio.playback?.length(snd) ?? 0) : 0) : 0
export const audio_sound_set_track_position = (inst: any, seconds: number): void => {
  Audio.commands.push({ kind: 'position', inst, seconds } as any)
}

/** `Input_Create.gml:409-425` — the readable name of each gamepad button, keyed `<constant>_Name`. */
function buttonNames(): DsMap<any> {
  const m = new DsMap<any>()
  const names: [string, string][] = [
    [gp_padr, 'DPAD RIGHT'],
    [gp_padl, 'DPAD LEFT'],
    [gp_padd, 'DPAD DOWN'],
    [gp_padu, 'DPAD UP'],
    [gp_face1, 'FACE1'], // Xbox A button
    [gp_face2, 'FACE2'], // Xbox B button
    [gp_face3, 'FACE3'], // Xbox X button
    [gp_face4, 'FACE4'], // Xbox Y button
    [gp_start, 'START'],
    [gp_select, 'SELECT'],
    [gp_shoulderl, 'BUMP LEFT'],
    [gp_shoulderr, 'BUMP RIGHT'],
    [gp_shoulderlb, 'TRIG LEFT'],
    [gp_shoulderrb, 'TRIG RIGHT'],
  ]
  for (const [button, name] of names) m.set(button + STR_Name, name)
  return m
}

// ---- adapter / dev-tool seams ----------------------------------------------------------------------
export const guiSeams = {
  /** `show_debug_overlay(bool)` */
  show_debug_overlay: (on: boolean): void => {
    ;(G as any).Debug_Overlay_state = on
  },
  /**
   * `Input.Buttons_dm` — the button table `Input_Create.gml:409-425` fills. The `<button>_Name` rows are
   * what the Options menu's EDIT CONTROLS page prints; with the map empty every row fell back to the
   * literal `'BUTTON'`. The `_Sprite` / `_Controller_Make` rows (`:438+`, the per-make controller icons)
   * are still adapter work and stay unfilled.
   */
  Buttons_dm: buttonNames(),
  /** `game_end()` — the adapter closes the app (browser: return to title). */
  game_end: (): void => {
    world.emit({ kind: 'room', room: '__game_end__' })
  },
  PaletteEditor_initiate_bgr_edit_mode: notPorted('PaletteEditor_initiate_bgr_edit_mode') as () => void,
  PaletteEditor_initiate_pal_edit_mode: notPorted('PaletteEditor_initiate_pal_edit_mode') as () => void,
  /** `GraphicsEffectsEditor` instance (adapter-side effects editor); NOONE until the dev-tools port. */
  GraphicsEffectsEditor: NOONE as any,
  /** `item_acquired(item id)` — owned by `gob2/item`, bound by `installEntitySeams()`. */
  item_acquired: notPorted('item_acquired') as (itemId: string) => boolean,
  PaletteEditor: NOONE as any,
}
export const item_acquired = (itemId: string): boolean => guiSeams.item_acquired(itemId)
export const show_debug_overlay = (on: boolean): void => guiSeams.show_debug_overlay(on)
export const game_end = (): void => guiSeams.game_end()
export const PaletteEditor_initiate_bgr_edit_mode = (): void =>
  guiSeams.PaletteEditor_initiate_bgr_edit_mode()
export const PaletteEditor_initiate_pal_edit_mode = (): void =>
  guiSeams.PaletteEditor_initiate_pal_edit_mode()
