  self.Form3_DURATION2 = 0x20
  self.Form3_can_draw = false
  self.dg_Positions = ds_grid_create(0x04, 0x05)
  _i = 0
  self.dg_Positions.set(_i, 0x00, 0x00) // x offset current
  self.dg_Positions.set(_i, 0x01, -((0x05 << 3) + 0x04)) // y offset current
  self.dg_Positions.set(_i, 0x02, 1) // state.
  self.dg_Positions.set(_i, 0x03, 0) // timer
  _i++ //
  self.dg_Positions.set(_i, 0x00, -(sprite_get_width(self.SPRITE1) >> 1) + 0x04) // x offset attack
  self.dg_Positions.set(_i, 0x01, -(sprite_get_height(self.SPRITE1) >> 1) + ((0x03 << 3) + 0x08)) // y offset attack
