  _i++ //
  self.dg_Positions.set(_i, 0x00, self.dg_Positions.get(0x01, 0x00)) // x offset attack
  self.dg_Positions.set(_i, 0x01, self.dg_Positions.get(_i - 1, 0x01) + (0x09 << 3)) // y offset attack
  self.dg_Positions.set(_i, 0x02, 1) // state.
  self.dg_Positions.set(_i, 0x03, 0) // timer
  self.dg_Positions.set(_i, 0x04, 'Flame2')
  _i++ //
  self.dg_Positions.set(_i, 0x00, self.dg_Positions.get(0x01, 0x00)) // x offset attack
  self.dg_Positions.set(_i, 0x01, self.dg_Positions.get(_i - 1, 0x01) + (0x06 << 3)) // y offset attack
  self.dg_Positions.set(_i, 0x02, 1) // state.
  self.dg_Positions.set(_i, 0x03, 0) // timer
  self.dg_Positions.set(_i, 0x04, 'Rock1')
