/** GML: Ganon2_update_4() */
export function Ganon2_update_4(self: any) {
  //return y+hh_ >= GROUND_Y;
  return self.y + self.Slime_H_ >= self.GROUND_Y
}

/** GML: Ganon2_update_5() */
export function Ganon2_update_5(self: Ganon2, ...argument: any[]) {
  let _DIFF: any

  _DIFF = sign_(self.Crystal_y + 5 < self.GROUND_Y - (self.Slime_H_ << 1))
  self.Crystal_vspd = clamp(self.Crystal_vspd + _DIFF, 0, self.Crystal_TERM_VEL)
  self.Crystal_y += (self.Crystal_vspd >> 4) & 0x0f
  self.Crystal_y = min(self.Crystal_y, argument[0])
}

/** GML: Ganon2_update_6() */
export function Ganon2_update_6(self: any, ...argument: any[]) {
  // returns: y+Slime_H_ >= GROUND_Y
  if (gmBool(Ganon2_update_4(self))) {
    self.off_ground_reason = 0
    set_xy(self, self.x, self.GROUND_Y - self.Slime_H_)
    self.vspd = 0
    if (gmBool(Ganon2_update_6a(self, argument[0], argument[1]))) {
      Ganon_update_xy(self) // updateX(), updateY()
      aud_play_sound(self.Jump_SOUND1)
    }
    return false
  } else {
    Ganon_update_xy(self) // updateX(), updateY()
    // returns: y+Slime_H_ >= GROUND_Y
    if (gmBool(Ganon2_update_4(self))) {
      // LANDING
      return true
      //aud_play_sound(Audio.sound('SND_WLK_WTR1A'));
    }
  }
  return false
}

/** GML: Ganon2_update_6a() */
export function Ganon2_update_6a(self: Ganon2, ...argument: any[]) {
  if (!gmBool(world.irandom(0x07))) {
    // JUMP/HOP !!!!!!!!!!!
    self.off_ground_reason = OGR_JUMP
    self.hspd = argument[0] + world.irandom(4) * sign_(world.irandom(1))
    self.hspd = max(self.hspd, G.pc.HSPD_MAX1 + 8)
    //hspd = max( hspd, global.pc.hspd_max+8);
    self.hspd = byte(self.hspd * sign_(argument[1]))
    self.hspd_dir = sign_(self.hspd < 0x80)
    self.vspd = 0xe8 + world.irandom(4) * sign_(world.irandom(1))
    self.vspd_dir = sign_(self.vspd < 0x80)
    return true
  }
  return false
}

