import {
  Container_AMT,
  EXIT_NAME_GAME_START,
  SAVE_FILE_MAX,
  STAT_ATK,
  STAT_LEVEL_MAX,
  STAT_LIF,
  STAT_MAG,
  STR_Bridge,
  STR_Qualified,
  XP_MAX,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { DsGrid, DsList, DsMap } from '../../runtime/ds'
import type { GmJsonValue } from './json'

/**
 * The `f` singleton (GameMaker object `f`: "file" — save-file data, including player stats).
 * Fields ported from `f_init.gml` in source order; `f_init()` (f_init.ts) does the parts that need
 * the world (reading save files from storage).
 */
export class File {
  readonly objectName = 'f'

  // SDNAME: Save Data Name (keys inside SaveFile_N.txt)
  readonly SDNAME_saveCreated = 'save_created'
  readonly SDNAME_save_name = 'save_name'
  readonly SDNAME_questNum = 'quest_num'
  readonly SDNAME_deathCount = 'death_count'
  readonly SDNAME_level_atk = 'level_atk'
  readonly SDNAME_level_mag = 'level_mag'
  readonly SDNAME_level_lif = 'level_lif'
  readonly SDNAME_cont_pieces_hp = 'cont_pieces_hp'
  readonly SDNAME_cont_pieces_mp = 'cont_pieces_mp'
  readonly SDNAME_spells = 'spells'
  readonly SDNAME_items = 'items'
  readonly SDNAME_skills = 'skills'
  readonly SDNAME_crystals = 'crystals'
  readonly SDNAME_kakusu = 'kakusu'
  readonly SDNAME_takenKeys = 'keys'
  readonly SDNAME_openedLocks = 'locks'
  readonly SDNAME_takenPBags = 'pbags'
  readonly SDNAME_linkDolls = 'link_dolls'
  readonly SDNAME_quests = 'quests'
  readonly SDNAME_exploredRooms = 'visited_rooms'
  readonly SDNAME_fastTravel = 'fast_travel'
  readonly SDNAME_volume_sound = '_volume_sound'
  readonly SDNAME_volume_music = '_volume_music'

  /** "SaveFile_1".."SaveFile_3" */
  readonly dl_FILE_NAME_PREFIX = new DsList<string>()
  /** "SaveFile_1.txt".. */
  readonly dl_file_names = new DsList<string>()

  /** GML `global.dm_save_file` — the save file currently being played (decoded). */
  readonly dm_save_file = new DsMap<GmJsonValue>()
  /** GML `global.dm_save_file_data` — every slot's encoded text, keyed `_Save_File<hex>_Encoded`. */
  readonly dm_save_file_data = new DsMap<string>()
  /** GML `global.dm_save_file_settings` — decoded `_Save_File_Settings` (rando/start options) of the loaded slot. */
  readonly dm_save_file_settings = new DsMap<GmJsonValue>()
  /** Display names per slot (SAVE_NAME_NULL when free). */
  readonly dl_save_names = new DsList<string>()

  file_num = -1 // default -1 so I get an error if it's not in range
  quest_num = 1 // 1: first game play-through, 2: beat game once (new game +)
  game_completed_count = 0
  death_count = 0
  level_atk = 1
  level_mag = 1
  level_lif = 1

  readonly CONT_MIN = 3
  readonly CONT_MAX = 9
  readonly CONT_PIECE_PER = 3
  readonly CONT_PIECE_MAX = this.CONT_MAX * this.CONT_PIECE_PER
  readonly CONT_MIN_HP = this.CONT_MIN // Starting containers: Heart
  readonly CONT_MAX_HP = this.CONT_MAX
  readonly CONT_PIECE_PER_HP = this.CONT_PIECE_PER
  readonly CONT_PIECE_MIN_HP = this.CONT_MIN_HP * this.CONT_PIECE_PER_HP
  readonly CONT_PIECE_MAX_HP = this.CONT_MAX_HP * this.CONT_PIECE_PER_HP
  readonly CONT_MIN_MP = this.CONT_MIN // Starting containers: Magic
  readonly CONT_MAX_MP = this.CONT_MAX
  readonly CONT_PIECE_PER_MP = this.CONT_PIECE_PER
  readonly CONT_PIECE_MIN_MP = this.CONT_MIN_MP * this.CONT_PIECE_PER_MP
  readonly CONT_PIECE_MAX_MP = this.CONT_MAX_MP * this.CONT_PIECE_PER_MP
  readonly HP_MAX = this.CONT_MAX_HP * Container_AMT
  readonly MP_MAX = this.CONT_MAX_MP * Container_AMT

  /** Container pieces as hex pairs "<container><piece>" — e.g. "010102031101..." for 3 full containers. */
  readonly CONT_PIECES_HP_DEF = contPiecesDefault(this.CONT_MIN_HP, this.CONT_PIECE_PER_HP)
  readonly CONT_PIECES_MP_DEF = contPiecesDefault(this.CONT_MIN_MP, this.CONT_PIECE_PER_MP)
  cont_pieces_hp = this.CONT_PIECES_HP_DEF
  cont_pieces_mp = this.CONT_PIECES_MP_DEF
  hp = this.CONT_MIN_HP * Container_AMT // get_stat_max(STR_Heart) at init
  mp = this.CONT_MIN_MP * Container_AMT // get_stat_max(STR_Magic) at init

  spells = 0 // bits representing aquired spells
  items = 0 // bits representing aquired items
  skills = 0 // bits represent the aquired skills (SKILL_THD $01, SKILL_THU $02, ...)
  readonly CuccoSkill_THRUST_D = 1 << 0
  readonly CuccoSkill_THRUST_U = 1 << 1
  readonly CuccoSkill_BREAK1 = 1 << 2
  readonly CuccoSkill_PROJ1 = 1 << 3
  readonly CuccoSkill_PROJ2 = 1 << 4
  Cucco_skills = 0

  readonly dm_jars_DEFAULT = new DsMap<GmJsonValue>()
  dm_jars = new DsMap<GmJsonValue>() // Red bottles restock after leaving area
  readonly dm_1up_doll_DEFAULT = new DsMap<GmJsonValue>()
  dm_1up_doll = new DsMap<GmJsonValue>() // Which Link dolls have been taken
  readonly dm_PBags_DEFAULT = new DsMap<GmJsonValue>()
  dm_PBags = new DsMap<GmJsonValue>()
  // datakey structure for f.dm_keys depends on the spawn source of the key.
  readonly dm_keys_DEFAULT = new DsMap<GmJsonValue>()
  dm_keys = new DsMap<GmJsonValue>() // Which keys have been taken (defined) & if they've been used
  key_count = 0 // How many keys are in Link's possesion
  dm_openedLocks = new DsMap<GmJsonValue>() // Which locks have been opened
  // kakusu: hide, conceal, be hidden
  dm_kakusu = new DsMap<GmJsonValue>() // Which kakusu have been killed
  kakusu_count = 0
  dm_explored = new DsMap<GmJsonValue>()
  dm_quests = new DsMap<GmJsonValue>()
  dm_challenges = new DsMap<GmJsonValue>()
  dm_rando_full = new DsMap<GmJsonValue>() // all rando related data for the current loaded save file
  dm_rando = new DsMap<GmJsonValue>() // the core rando data for the current loaded save file
  dm_rando_dungeon_tileset = new DsMap<GmJsonValue>() // separate file: there's a lot of data for dungeon tileset rando

  readonly BuildBridge_QUAL_DK = STR_Bridge + STR_Qualified
  quests = '' // The dm_quests map encoded
  crystals = 0 // A bit based value representing WHICH crystals have been placed
  readonly LIVES_MAX = 99
  lives = 3 // g.STARTING_LIVES — set by f_init()
  xp = 0
  xpPending = 0
  xpNext = 0 // 50
  xpDrain = 0 // 05E8. For enemies that drain xp

  /** XP required for the next level, [stat, level]. ROM 9659-9688. */
  readonly dg_xp_next = xpNextDefault()
  readonly dg_xp_next_DEFAULT = xpNextDefault()

  cont_run_dngn_num = 0
  cont_run_town_num = 0
  // REEN: Rm Entry Exit Name
  readonly REEN_NEW_FILE = EXIT_NAME_GAME_START
  reen_new_run = this.REEN_NEW_FILE // Coming from FileSelect. This will be from saved data
  reen = this.reen_new_run // The exit to spawn at

  constructor() {
    for (let i = 0; i < SAVE_FILE_MAX; i++) {
      this.dl_FILE_NAME_PREFIX.add(`SaveFile_${i + 1}`)
      this.dl_file_names.add(`${this.dl_FILE_NAME_PREFIX.get(i)}.txt`)
    }
  }
}

function contPiecesDefault(containers: number, piecesPer: number): string {
  let s = ''
  for (let i = 1; i <= containers; i++) for (let j = 1; j <= piecesPer; j++) s += hexStr(i) + hexStr(j)
  return s
}

function xpNextDefault(): DsGrid<number> {
  const g = new DsGrid<number>(3, STAT_LEVEL_MAX + 1, 0)
  const atk = [100, 200, 500, 1000, 2000, 3000, 5000, 8000, 9900, XP_MAX]
  const mag = [70, 100, 300, 700, 1200, 2200, 3500, 6000, 9500, XP_MAX]
  const lif = [30, 50, 150, 400, 800, 1500, 2500, 4000, 9000, XP_MAX]
  for (let l = 0; l <= STAT_LEVEL_MAX; l++) {
    g.set(STAT_ATK, l, atk[l] as number)
    g.set(STAT_MAG, l, mag[l] as number)
    g.set(STAT_LIF, l, lif[l] as number)
  }
  return g
}
