import type { Caches } from '@z2/data'
import { File } from '../game/file/File'
import { Game } from '../game/Game/Game'
import { GameObjectMgr } from '../game/game_object_mgr/GameObjectMgr'
import { installGlobalAliases } from '../game/globalAliases'
import { Palette } from '../game/palette/Palette'
import { installPaletteGlobals } from '../game/palette/pi'
import { OgRandom } from '../nes/rng'
import { Input } from '../objects/Input'
import { DrawList } from './draw'
import { Globals } from './globals'
import { _resetInstanceIds, type Instance } from './instance'
import { EMPTY_RAW_INPUT, type RawInput } from './rawInput'
import { MemoryStorage, type Storage } from './storage'
import { MapStore } from './tiled'

export type RoomType = 'A' | 'B' | 'C'

/** Events the core emits for the adapter (audio, room changes). Cleared each step by the consumer. */
export type WorldEvent =
  | { kind: 'sound'; sound: string; loop?: boolean }
  | { kind: 'music'; theme: string | null }
  | { kind: 'room'; room: string }

/**
 * The whole game state for one frame-stepped simulation. Singletons keep their ZALiA names and are
 * exposed as live module bindings (`g`, `p`, `f`, `input`, …) so ported scripts read like the GML.
 */
/**
 * SplitMix32 finalizer — decorrelates the generator's state from the seed it was set with. Without it the
 * first draw after `random_set_seed(s)` is ≈ `s / 2^32` (see `random_set_seed`), and `s = 0` collapses onto
 * `s = 1`. GameMaker scrambles internally before its first draw; this is the port's equivalent.
 */
function mixSeed(s: number): number {
  let x = ((s >>> 0) + 0x9e3779b9) >>> 0
  x = Math.imul(x ^ (x >>> 16), 0x21f0aaad) >>> 0
  x = Math.imul(x ^ (x >>> 15), 0x735a2d97) >>> 0
  x = (x ^ (x >>> 15)) >>> 0
  return x || 1
}

export class World {
  readonly G = new Globals()
  readonly input = new Input()
  readonly g = new Game()
  readonly p = new Palette()
  readonly f = new File()
  readonly goMgr = new GameObjectMgr()
  readonly ogRandom = new OgRandom()
  readonly draw = new DrawList()
  /** Tiled scene/overworld maps by file stem (`rm_get_file_data` reads from here). */
  readonly maps = new MapStore()
  /** ZALiA's decoded data caches (SceneData01 etc.); set by the adapter/tests before boot. */
  caches: Caches | undefined
  readonly events: WorldEvent[] = []
  storage: Storage
  /** All live instances in creation order (GM `with(Obj)` iteration order). */
  readonly instances: Instance[] = []
  /** Deterministic PRNG for GM `irandom`/`random` (seeded; xorshift32 over a scrambled seed). */
  private seed = 0x9e3779b9

  constructor(opts: { storage?: Storage; seed?: number } = {}) {
    this.storage = opts.storage ?? new MemoryStorage()
    if (opts.seed) this.seed = mixSeed(opts.seed)
    // `p_init.gml` puts the palette indices/constants on `global.`; ~30 ported files read them as `G.PI_*`.
    installPaletteGlobals(this.G as never, this.p as never)
    // `g.dm_go_prop`, `G.dm_pi`, `G.dm_save_file*` were empty duplicates of maps that live on `goData`/`p`/`f`
    installGlobalAliases(this.G as never, this.g as never, this.p, this.f)
  }

  /** GM `irandom(n)`: integer in 0..n inclusive. */
  irandom(n: number): number {
    return Math.floor(this.random01() * (n + 1))
  }
  /** GM `random(n)`: float in [0, n). */
  random(n: number): number {
    return this.random01() * n
  }
  private random01(): number {
    let x = this.seed
    x ^= x << 13
    x ^= x >>> 17
    x ^= x << 5
    this.seed = x >>> 0
    return this.seed / 0x100000000
  }
  /** GM `randomize()` + `random_get_seed()` */
  randomize(entropy = Date.now()): number {
    this.seed = mixSeed(entropy)
    return this.seed
  }
  /**
   * GM `random_set_seed(s)`.
   *
   * The generator is a xorshift32 whose *state is* the seed, so seeding it with `s` directly left the first
   * draw correlated with `s`: over the seeds 1..4096, `irandom(58)` came out 0 for 6.7% of them where a
   * uniform draw gives 1.7%. That draw is what `choose(a, …)` and `ds_list_shuffle`'s first swap decide
   * from, and the randomizer re-anchors its stream 21 times per generation, so the bias landed on the
   * placement of JUMP, palette rando's offset and every shuffle. Scrambling the seed into the state fixes
   * it, and `s = 0` no longer folds onto `s = 1` (`s >>> 0 || 1` gave those two files the same game).
   */
  random_set_seed(s: number): void {
    this.seed = mixSeed(s)
  }

  register<T extends Instance>(inst: T): T {
    this.instances.push(inst)
    return inst
  }
  /** `with (Cls)` — every existing instance of the class (or subclass), creation order. */
  *instancesOf<T extends Instance>(cls: abstract new (...a: never[]) => T): Generator<T> {
    for (const i of this.instances) if (i.exists && i instanceof cls) yield i
  }
  /** Drop destroyed instances from the registry (called at the end of each step). */
  sweep(): void {
    let w = 0
    for (const i of this.instances) if (i.exists) this.instances[w++] = i
    this.instances.length = w
  }

  emit(e: WorldEvent): void {
    this.events.push(e)
  }

  /** Advance one 60 Hz frame. The game loop proper (g_Step) is wired in `core/game/step.ts`. */
  step(raw: RawInput = EMPTY_RAW_INPUT): void {
    this.draw.clear()
    this.G.App_frame_count++
    this.input.Input_update1(raw)
    this.stepHook?.(this)
    this.sweep()
  }
  /** Installed by the game module; kept as a hook so the runtime has no dependency on game code. */
  stepHook: ((w: World) => void) | undefined
}

// ---- live bindings ------------------------------------------------------------------------------
/** The current world. Ported scripts import `{ world, g, input, G }` and read them like GML globals. */
export let world: World = undefined as unknown as World
export let input: Input = undefined as unknown as Input
export let G: Globals = undefined as unknown as Globals
export let g: Game = undefined as unknown as Game
export let p: Palette = undefined as unknown as Palette
export let f: File = undefined as unknown as File
export let goMgr: GameObjectMgr = undefined as unknown as GameObjectMgr

export function setWorld(w: World): World {
  world = w
  input = w.input
  G = w.G
  g = w.g
  p = w.p
  f = w.f
  goMgr = w.goMgr
  return w
}

export function createWorld(opts: ConstructorParameters<typeof World>[0] = {}): World {
  _resetInstanceIds()
  return setWorld(new World(opts))
}
