const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v))

/** `cont_piece_cnt_hp()` / `cont_piece_cnt_mp()` — pieces are 4 hex chars each. */
export function cont_piece_cnt(stat: 'hp' | 'mp'): number {
  return (stat === 'hp' ? f.cont_pieces_hp : f.cont_pieces_mp).length >> 2
}
export const cont_piece_cnt_hp = () => cont_piece_cnt('hp')
export const cont_piece_cnt_mp = () => cont_piece_cnt('mp')

/** `cont_cnt_hp()` / `cont_cnt_mp()` — whole containers (ZALiA TODO asked to merge these; done). */
export function cont_cnt(stat: 'hp' | 'mp'): number {
  return Math.trunc(cont_piece_cnt(stat) / (stat === 'hp' ? f.CONT_PIECE_PER_HP : f.CONT_PIECE_PER_MP))
}
export const cont_cnt_hp = () => cont_cnt('hp')
export const cont_cnt_mp = () => cont_cnt('mp')

/** `get_stat_max(stat type str)` */
export function get_stat_max(statType: string): number {
  if (statType === STR_Heart) return cont_cnt_hp() * Container_AMT // Container_AMT=$20
  if (statType === STR_Magic) return cont_cnt_mp() * Container_AMT
  return 0
}

/** `get_xp_next(stat type)` */
export function get_xp_next(stat: number): number {
  switch (stat) {
    case STAT_ATK:
      return f.dg_xp_next.get(stat, f.level_atk) ?? XP_MAX
    case STAT_MAG:
      return f.dg_xp_next.get(stat, f.level_mag) ?? XP_MAX
    case STAT_LIF:
      return f.dg_xp_next.get(stat, f.level_lif) ?? XP_MAX
  }
  return XP_MAX
}

/** `adjust_stat(hp difference, mp difference)` */
export function adjust_stat(hpDiff: number, mpDiff: number): void {
  if (hpDiff !== 0) f.hp = clamp(f.hp + hpDiff, 0, get_stat_max(STR_Heart))
  if (mpDiff !== 0) f.mp = clamp(f.mp + mpDiff, 0, get_stat_max(STR_Magic))
}

/** `get_key_count(dungeon num)` — keys held (acquired and not used). */
export function get_key_count(dungeonNum: number): number {
  let count = 0
  const COUNT = Number(gd().dm_spawn.val(STR_Dungeon + hexStr(dungeonNum) + STR_Key + STR_Count))
  for (let i = 1; i <= COUNT; i++) {
    // key_datakey example: "0203", "0601"
    const keyId = STR_KEY + hexStr(dungeonNum) + hexStr(i)
    if (f.dm_keys.val(keyId + STR_Acquired) && !f.dm_keys.val(keyId + STR_Used)) count++
  }
  return count
}

/** `get_key_count_acquired(dungeon num)` */
export function get_key_count_acquired(dungeonNum: number): number {
  if (dungeonNum < 1 || dungeonNum > 6) return 0
  let count = 0
  const COUNT = Number(gd().dm_spawn.val(STR_Dungeon + hexStr(dungeonNum) + STR_Key + STR_Count))
  for (let i = 1; i <= COUNT; i++) {
    const keyId = STR_KEY + hexStr(dungeonNum) + hexStr(i)
    if (f.dm_keys.val(keyId + STR_Acquired)) count++
  }
  return count
}

/** `set_life_doll_data_to_default()` */
export function set_life_doll_data_to_default(): void {
  ds_map_copy(f.dm_1up_doll, f.dm_1up_doll_DEFAULT)
}

/** `get_life_doll_count()` */
export function get_life_doll_count(): number {
  let count = 0
  for (let i = Number(f.dm_1up_doll.val(STR_Count)); i >= 1; i--) {
    const itemId = f.dm_1up_doll.get(hexStr(i) + STR_Item + STR_ID)
    if (itemId !== undefined) count += Number(f.dm_1up_doll.val(String(itemId) + STR_Acquired))
  }
  return count
}

/** `get_kakusu_count()` */
export function get_kakusu_count(): number {
  return Number(f.dm_kakusu.val(STR_Defeated + STR_Count))
}

/** `get_jar_restore_dur(magic jar ver)` — ** This is equivilant to OG. */
export function get_jar_restore_dur(ver: number): number {
  let containerCnt = 0
  switch (ver) {
    case 1:
      containerCnt = cont_cnt_mp()
      break
    case 2:
      containerCnt = 1
      break
    case 3:
      containerCnt = 1
      break
    case 4:
      containerCnt = cont_cnt_mp()
      break
  }
  return (containerCnt * Container_AMT) >> 1 // >>1 bc amt restored each frame of adjustment = 2
}

/** `quest_is_complete(quest id)` */
export function quest_is_complete(questId: string): boolean {
  switch (questId) {
    case QuestID_Rauru_Spell:
      return true
    case QuestID_Ruto_Spell:
      return (f.items & ITM_TRPH) !== 0
    case QuestID_Saria_Spell:
      return (f.items & ITM_MIRR) !== 0
    case QuestID_Mido_Spell:
      return (f.items & ITM_MEDI) !== 0
    case QuestID_Nabooru_Spell: {
      const TOWN_NAME = String(gd().dm_town.val(STR_Town + STR_Name + hexStr(questId), STR_Nabooru))
      return Boolean(f.dm_quests.val(TOWN_NAME + STR_Quest + STR_Complete))
    }
    case QuestID_Darunia_Spell:
      return (f.items & ITM_CHLD) !== 0
    case QuestID_NewKasuto_Spell:
      return true
    case QuestID_OldKasuto_Spell:
      return true
    case QuestID_Bulblin_Spell:
      return true
    case QuestID_Saria_Bridge:
      return (f.items & ITM_NOTE) !== 0
    case QuestID_NewKasuto_Container:
      switch (gd().mod_QuestNewKasuto) {
        case 0:
          return cont_cnt_mp() >= f.CONT_MAX_MP - 1 // OG
        case 1:
          return true
      }
      break
  }
  return false
}

/** `update_xp()` — D433. xp uptick/drain */
export function update_xp(): void {
  const g = gd()
  const C1 = f.xpPending > 0 // XP Pending
  const C2 = f.xpDrain > 0 && f.xp > 0 // XP Drain
  if (C1) {
    let AMT = 1
    if (f.xpPending > 10) AMT = 10
    // if (xpPending>=10) _AMT = 10; // OG
    f.xpPending -= AMT
    f.xp += AMT
  } else if (C2) {
    // Search 6DD5 in google docs RAM data for info
    let AMT = 1
    if (f.xpDrain >= 10) AMT = 10
    f.xpDrain -= AMT
    f.xp -= AMT
  } else {
    // MOD. To prevent pending/leftover xpDrain when f.xp reaches 0 and xpDrain isn't completely used.
    // Making a rule that pending xpDrain is only allowed if it's waiting for xp uptick to finish.
    f.xpDrain = 0
  }
  if (C1 || C2) {
    f.xp = clamp(f.xp, 0, XP_MAX)
    const track = hooks.get_audio_theme_track(dk_XPTick)
    if (!hooks.audio_is_playing(track)) hooks.aud_play_sound(track)
  }
  // D4CE: JSR 968D       - Activate Level-up menu
  // TODO(ZALiA): I doubt this OG code is necessary since update_menus() takes care of it.
  if (g.gui_state === g.gui_state_NONE && !g.cutscene && f.xp >= f.xpNext) {
    // 2025/03/23. cutscene check added to prevent softlock during a cutscene
    g.gui_state = g.gui_state_LEVEL_UP
  }
}

/** `update_stat_restore()` — D3EF. Life & Magic restoration. */
export function update_stat_restore(): void {
  const g = gd()
  // ***** Keep mp even because spell costs are drawn as half of what the actual values are.
  const MAX_MP = get_stat_max(STR_Magic)
  if (f.items & ITM_NKLC && !g.StatRestore_timer_mp && f.mp < MAX_MP && !(g.counter0 & 0x7f)) {
    if (!(g.counter0 & 0xff) || f.mp & 0x4) adjust_stat(0, 2)
  }
  // D3EF
  if (!g.StatRestore_timer_hp && !g.StatRestore_timer_mp) return
  const track = hooks.get_audio_theme_track(dk_CursorSpellMenu)
  if (!hooks.audio_is_playing(track)) hooks.aud_play_sound(track)
  let TIMER = g.counter1
  if (g.mod_STAT_RESTORE_1) TIMER = g.counter0
  if (TIMER & 0x1 && g.StatRestore_timer_hp) {
    // every odd frame
    const MAX_HP = get_stat_max(STR_Heart)
    adjust_stat(2, 0)
    if (f.hp === MAX_HP) g.StatRestore_timer_hp = 0
    else g.StatRestore_timer_hp--
  }
  if (!(TIMER & 0x1) && g.StatRestore_timer_mp) {
    // every even frame
    adjust_stat(0, 2)
    if (f.mp === MAX_MP) g.StatRestore_timer_mp = 0
    else g.StatRestore_timer_mp--
  }
}

/** Microseconds per frame at the fixed 60 Hz step (GM `delta_time` was wall-clock microseconds). */
export const FRAME_US = 1000000 / 60

/** "H:MM:SS" as in `update_QuestTimer` (time in microseconds). */
export function questTimerText(timeUs: number): string {
  const SECONDS = Math.trunc(timeUs / 1000000)
  const MINUTES = Math.trunc(SECONDS / 60)
  const HOURS = Math.trunc(MINUTES / 60)
  const pad2 = (n: number) => String(n).padStart(2, '0')
  return `${HOURS}:${pad2(MINUTES % 60)}:${pad2(SECONDS % 60)}`
}

/** `update_QuestTimer()` */
export function update_QuestTimer(): void {
  const g = gd()
  const G = Gd()
  const inTimedRoom =
    g.room_type === 'A' || g.room_type === 'C' || g.room === 'rmB_Death' || g.room === 'rmB_NextLife'
  if (G.QuestTimer_state) {
    if (inTimedRoom) {
      if (g.room_type !== 'C' || !g.overworld_paused) {
        if (
          G.QuestTimer_state === 1 &&
          !g.game_end_state &&
          hooks.can_update_frame() &&
          g.gui_state !== g.gui_state_OPTIONS && // Options Menu
          g.gui_state !== g.gui_state_QUIT_APP && // Quit App Menu
          g.gui_state !== g.gui_state_EDIT_PAL && // Palette Editor
          g.gui_state !== g.gui_state_GEE // Graphics Effects Editor
        ) {
          G.QuestTimer_time += FRAME_US
        }
      }
      G.QuestTimer_text = questTimerText(G.QuestTimer_time)
      G.QuestTimer_xl = 0x4
      G.QuestTimer_yt = G.HUD_YOFF1
    }
  }
  if (
    G.QuestTimer_state &&
    G.QuestTimer_show &&
    g.gui_state !== g.gui_state_EDIT_PAL &&
    g.gui_state !== g.gui_state_GEE &&
    !g.game_end_state
  ) {
    if (inTimedRoom) G.QuestTimer_can_draw = true
  }
}

/** `get_continue_reen()` — reen: Room-Entry Exit-Name */
export function get_continue_reen(): string {
  const g = gd()
  if (g.mod_ContinueFrom) {
    // if can start at dungeon entrance or town last saved
    if (g.mod_ContinueFrom & g.mod_ContinueFrom_DNGN && g.coming_from !== g.coming_from_FILE) {
      const DATAKEY = String(g.dm_room_history.val(`${STR_Last + STR_Rm}A${STR_Datakey}`, STR_undefined))
      const RM_NAME = String(g.dm_room_history.val(DATAKEY + STR_RmName, RM_NAME_NPALACE))
      const dungeonNum = hooks.get_dungeon_num(RM_NAME) // Last rm player was in
      if (dungeonNum) {
        let exitName = String(g.dm_rm.val(hooks.get_dk_dungeon_entrance(dungeonNum), REEN_DEFAULT))
        exitName = String(f.dm_rando.val(RM_NAME + STR_Dungeon + STR_Entrance, exitName))
        return exitName
      }
    }
    if (g.mod_ContinueFrom & (g.mod_ContinueFrom_TWN1 | g.mod_ContinueFrom_TWN2)) {
      return String(
        g.dm_town.val(
          STR_Continue + STR_Exit + STR_Town + STR_Num + hexStr(f.cont_run_town_num),
          REEN_DEFAULT,
        ),
      )
    }
  }
  return REEN_DEFAULT
}
