/**
 * `update_kill_count()` — E880. Every `KILL_COUNT1`/`KILL_COUNT2`-th qualifying kill arms the guaranteed
 * Jar/P-Bag drop (E870-E87F drop tables). Called from `damage_gob` the frame the enemy's hp reaches 0.
 */
export function update_kill_count(self: GameObject): void {
  if (!gmBool(self.drop_bits)) return
  const g = gp()
  const _TYPE1_BITS = g.DROP_JAR1 | g.DROP_BAG1
  const _TYPE2_BITS = g.DROP_JAR2 | g.DROP_BAG3
  const _TYPE1 = (self.drop_bits & _TYPE1_BITS) === _TYPE1_BITS
  const _TYPE2 = (self.drop_bits & _TYPE2_BITS) === _TYPE2_BITS
  if (!_TYPE1 && !_TYPE2) return
  if (_TYPE1) g.kill_count1++
  else if (_TYPE2) g.kill_count2++
  if (g.kill_count1 < g.KILL_COUNT1 && g.kill_count2 < g.KILL_COUNT2) return
  // MOD. If true, don't drop pbag, only Jar $10, so pbags can't be farmed from infinite spawners
  let _C1 = false
  if (_TYPE1 && (self.is_from_spawner || self.respawn_type === 1 || self.respawn_type === 4)) {
    _C1 = true
    // Limit drops from infinite respawning GO
    let _count = 0
    for (const it of world.instancesOf(Item)) {
      // GML `with(Item)`: `exit` leaves the whole script, so the 6th drop aborts the kill count
      if (gmBool(it.state) && it.IS_DROP && (is_ver(it, 'ItmF0', 1) || is_ver(it, 'ItmE0', 2))) {
        _count++
        if (_count >= 6) return
      }
    }
  }
  // E870-E87F. TYPE1: "90 90 8A 90 90 90 90 90", TYPE2: "91 8C 91 8C 8C 91 8C 91"
  if (_TYPE1) {
    g.kill_count1 = 0
    if (isVal(rand(self) & 0x7, 2) && !_C1) {
      self.drop_item_obj = 'ItmF0' // PBag 50
      self.drop_item_ver = 1
    } else {
      self.drop_item_obj = 'ItmE0' // Jar $10
      self.drop_item_ver = 2
    }
  } else if (_TYPE2) {
    g.kill_count2 = 0
    if (isVal(rand(self) & 0x7, 1, 3, 4, 6)) {
      self.drop_item_obj = 'ItmF0' // PBag 200
      self.drop_item_ver = 4
    } else {
      self.drop_item_obj = 'ItmE0' // Jar full
      self.drop_item_ver = 1
    }
  }
}

/**
 * `pc_sword_colliding_solid_body()` — E654. The PC's sword hit a GOB shield or a solid body: *clink*, then
 * a down-thrust bounces, anything else pushes both apart. Bound onto `env.fn` by `registerEntities()`.
 */
export function pc_sword_colliding_solid_body(self: GameObject): void {
  deps.play_theme_sound(dk_StrikeSolid)
  const P = pc()
  if (P.behavior === P.behavior_STAB_DOWN) PC_set_bounce()
  else pushback_pc_and_go(self)
}

/** `GameObjectB_init()` — depth, ground offset, default step script. (init_vars_* are class fields.) */
export function GameObjectB_init(self: GameObjectB): void {
  // default GameObject draw YOff
  if (self instanceof GOB1) self.DRAW_YOFF = 1 // +1 for 1 pixel in ground
  if (self instanceof Enemy) GO_depth_init(self, DEPTH_ENEMY)
  else GO_depth_init(self, DEPTH_NPC)
  self.scr_step = GameObjectB_step as (self: GameObject) => void
}

/** `GameObjectB_step()` — the state machine every entity runs from the manager. D250, D254 */
export function GameObjectB_step(self: GameObjectB): void {
  if (!self.state) return
  self.SwordHB_collidable = false
  self.pc_sword_collided_solid_body = false
  // F27D
  GO_update_cam_vars(self)
  switch (self.state) {
    case self.state_NORMAL: {
      if (self.scr_update) self.scr_update(self)
      break
    }
    case self.state_EXPLODE: {
      // DCAE
      state_EXPLODE_step(self)
      break
    }
    case self.state_DROP: {
      if (self instanceof Target) {
        self.state = 0
        break
      }
      state_DROP_step(self)
      if (self.timer) return
      // Item drop or Boss key drop ------------------------
      const _IS_BOSS = self instanceof Boss
      if (self.drop_item_obj || _IS_BOSS) {
        // DE23
        let _item: Ref<GameObject> = NOONE
        if (_IS_BOSS) {
          const g = gp()
          if (g.mod_NoBossKeyDrop) {
            // Horizontal view lock for boss is released after arena doors are destroyed.
            if (![...world.instancesOf(ArenaGate)].length) {
              g.view_lock &= ~g.view_lock_boss
              g.view_lock |= g.view_lock_rm
              g.view_lock_boss = 0
              audioHooks.setCanPlayMusRmBody(true)
              if (self.objectName === 'Thunderbird01') deps.ViewCatchUp_init()
            }
          } else {
            _item = GameObject_create(self.xl, self.yt, 'ItmD0', 1) // Key
            if (_item) {
              _item.vspd = 0xc
              set_xy(_item, _item.x, _item.y + 1)
              ;(_item as Item).IS_DROP = true
              deps.play_theme_sound(dk_ItemDrop)
            }
          }
          if (!_item && self.objectName === 'Carock01' && self.ver === 2 && self.Item_OBJ) {
            // PENDANT or whatever rando puts here
            _item = GameObject_create(self.x - 4, self.y - 0x10, self.Item_OBJ, self.Item_VER)
            if (_item) {
              _item.vspd = 0
              _item.dk_spawn = self.Item_SPAWN_DATAKEY
              ;(_item as Item).ITEM_ID = self.Item_ITEM_ID
              ;(_item as Item).IS_DROP = true
              deps.play_theme_sound(dk_ItemDrop)
            }
          }
        } else {
          // Non-boss Enemy
          _item = GameObject_create(
            self.xl,
            self.yt,
            self.drop_item_obj as Exclude<typeof self.drop_item_obj, 0>,
            self.drop_item_ver,
          )
          if (_item) {
            _item.vspd = 0
            let _y = _item.yb - 1
            if (((GG().dg_solid.get(_item.x >> 3, _y >> 3) as number) & 0xff) === TID_SOLID1) {
              _y = ((_y >> 3) - 1) << 3
              _y = deps.get_ground_y(_item.x, _item.yb, -1, _y)
              set_xy(_item, _item.x, _y - _item.hh_)
            }
            ;(_item as Item).IS_DROP = true
            deps.play_theme_sound(dk_ItemDrop)
          }
        }
      }
      // DD34, DD3D. respawn_type 1 (off screen) and 4 (timed) get their spawn permission back.
      if (self.respawn_type === 1 || self.respawn_type === 4) GOB_despawn(self)
      if (self instanceof Enemy) GOB_update_data_defeated(self)
      self.state = 0
      break
    }
  }
  if (gp().mod_destroy_go_on_death && !self.state) GO_destroy_1a(self)
}

/** `GameObjectB_step2()` — minimal step (state NORMAL only) used by a few GOB2. */
export function GameObjectB_step2(self: GameObjectB): void {
  if (!self.state) return
  GO_update_cam_vars(self)
  if (self.state === self.state_NORMAL && self.scr_update) self.scr_update(self)
}

/** Audio-side hooks (Audio.can_play_mus_rm_body); installed by the Audio port. */
export const audioHooks = {
  setCanPlayMusRmBody: (_v: boolean): void => {},
}

/** `GOB_update_1(can update hspd_pushback)` — apply and decay push-back. */
export function GOB_update_1(self: GameObject, canUpdate: boolean | number): void {
  if (!self.hspd_pushback) return
  self.hspd = self.hspd_pushback
  if (canUpdate) {
    if (self.hspd_pushback & 0x80) self.hspd_pushback = (self.hspd_pushback + 1) & 0xff
    else self.hspd_pushback = (self.hspd_pushback - 1) & 0xff
  }
}

/** `GOB_update_2()` — DE40: camera vars, out-of-bounds/despawn checks, EF11 draw update and collisions. */
export function GOB_update_2(self: GameObject): void {
  GO_update_cam_vars(self)
  // DE46
  if (GOB_is_out_of_bounds_y(self)) {
    // Same as OG: if (yt>$FF). DD3D
    if (self instanceof Item) self.state = 0
    else GOB_despawn(self) // set state=0 && spawn permision=1
  } else if (deps.ocsHV1(self)) {
    // if any w AND h in ocs area. DE51: JSR EF11
    update_EF11(self)
    // DE54 & DE6C, DD3D. Despawn check
    GOB_update_2a(self) // GOB body to proj/sword/body collision checks
  } else {
    self.cs &= 0xf
    // DE6C, DD3D. Despawn check
    GOB_update_2b(self)
  }
}

/** Collision scripts of the gob folder that depend on the PC port; overridable seam. */
export const gobCollision = {
  GOB_body_collide_pc_proj: notPorted('GOB_body_collide_pc_proj') as (self: GameObject) => void,
  GOB_body_collide_pc_sword: notPorted('GOB_body_collide_pc_sword') as (self: GameObject) => void,
  GOB_body_collide_pc_body_1a: notPorted('GOB_body_collide_pc_body_1a') as (self: GameObject) => void,
}

/** `GOB_update_2a()` — DE54, DE63 */
export function GOB_update_2a(self: GameObject): void {
  if (deps.ocsHV2(self)) {
    // if (at least 8 of width AND any height) are in ocs area
    gobCollision.GOB_body_collide_pc_proj(self) // E48B - PC projectiles to enemy body
    gobCollision.GOB_body_collide_pc_sword(self) // E677 - PC sword to enemy body
    if (!self.pc_sword_collided_solid_body) gobCollision.GOB_body_collide_pc_body_1a(self) // E4D9 - Link body to enemy body
  } else {
    self.cs &= 0xf
    GOB_update_2b(self) // DE6C, DD3D. Despawn check
  }
}

/** `GOB_update_2b()` — DE6C: despawn PRXM GOB1 that are far enough from the camera. */
export function GOB_update_2b(self: GameObject): void {
  if (
    self instanceof GOB1 &&
    (self.dk_spawn === undefined || !self.dk_spawn.includes(STR_PRIO)) &&
    in_despawn_dist(self)
  ) {
    // DD3D. *** Is this necessary now with the raised spawn limits?
    GOB_despawn(self)
  }
}

/** `GOB_despawn(GOB instance)` — DD3D: let an unused/undefeated instance respawn later. */
export function GOB_despawn(inst: GameObject): void {
  if (inst.dk_spawn !== undefined) gp().dm_spawn.set(inst.dk_spawn + STR_Spawn_Permission, 1) // DD41. Allow obj to respawn
  inst.state = 0
}

/** `GOB_is_out_of_bounds_y(inst id)` — Same as OG: if (yt > $FF) */
export function GOB_is_out_of_bounds_y(inst: GameObject): boolean {
  return inst.yt >= deps.cam_yb_max() + (0x3 << 3)
}

/** `update_EF11()` — EF11: stun timer, draw properties (udp), palette set incl. stun flash. */
export function update_EF11(self: GameObject): void {
  if (self.stun_timer) self.stun_timer--
  // EF19
  GO_udp_1(self) // drawX=x; drawY=y; xScale=facingDir;
  self.palidx_base = self.palidx_def
  // udp: Update Draw Properties
  if (self.scr_udp) self.scr_udp(self)
  update_draw_xy(self)
  // F1BD
  GO_add_palidx_set(self) // add p.PI_LIT1 or p.PI_DRK1 to palidx_base
  if (self.stun_timer) self.palidx_base = GO_update_pal_flash(self.stun_timer, 2)
  self.palidx = self.palidx_base
}
stateHooks.update_EF11 = update_EF11

/** `damage_gob(gob inst id, damage amount, is projectile collision)` — E726. GOB take damage. */
export function damage_gob(inst: GameObject, damage: number, isProjCollision: boolean): void {
  if (inst instanceof Item || inst.objectName === 'FaBlA' || inst.objectName === 'CrHoA') return
  // *** stun_timer needs to be set BEFORE pushback_pc_and_go() *** (checked in set_go_hspd_pushbback)
  inst.stun_timer = inst.STUN_DURATION1 // $30
  inst.hp -= damage
  if (inst.hp <= 0) {
    inst.hspd_pushback = 0
    update_kill_count(inst) // kill count
    deps.play_theme_sound(dk_EnemyDeath)
    inst.timer = inst.explosion_DURATION1 // explosion_DURATION1=$25: 0.617s
    inst.state = inst.state_EXPLODE
  } else if (pc().behavior !== pc().behavior_STAB_DOWN) {
    if (isProjCollision)
      pushback_pc_and_go(inst, 0) // Proj collision: Won't push PC
    else pushback_pc_and_go(inst)
  }
  if (gp().mod_BossHPBarFlash && inst instanceof Boss) inst.HPBar_timer = inst.stun_timer
  deps.play_theme_sound(dk_StrikeEnemy)
}

/** `GOB_update_data_defeated(GOB instance id)` — count defeats per objver, per room and per spawn in f.dm_quests. */
export function GOB_update_data_defeated(inst: GameObject): void {
  const q = fp().dm_quests
  const bump = (k: string) => q.set(k, (q.val(k) as number) + 1)
  const _DK = get_defeated_dk()
  let _dk = _DK + inst.objectName + STR_Version + hexStr(inst.ver)
  bump(_dk)
  _dk += gp().rm_name
  bump(_dk)
  if (inst.dk_spawn === undefined) return
  _dk += STR_Spawn_Idx + inst.dk_spawn.slice(-2)
  bump(_dk)
  _dk = _DK + inst.dk_spawn
  bump(_dk)
}

/** `GOB_rm_end_clean_up_1()` — E18A: give remaining GOB permission to spawn again if pc returns. */
export function GOB_rm_end_clean_up_1(): void {
  for (let _i = goMgr.dl_gob1.size - 1; _i >= 0; _i--) {
    const inst = goMgr.dl_gob1.get(_i)
    if (!instanceExists(inst as GameObject | null | undefined)) continue
    const i = inst as GameObject
    if (i.state) {
      GOB_despawn(i)
      // Not sure why this sets the state to 1 since this function is called when exiting a room
      i.state = i.state_NORMAL
    }
  }
  for (let _i = goMgr.dl_gob2.size - 1; _i >= 0; _i--) {
    const inst = goMgr.dl_gob2.get(_i)
    if (!instanceExists(inst as GameObject | null | undefined)) continue
    const i = inst as GameObject
    if (i.state && i.dk_spawn !== undefined) gp().dm_spawn.set(i.dk_spawn + STR_Spawn_Permission, 1)
  }
}

/** `GOB_udp_1(timing)` — two-frame walk animation from dl_sprites[0]/[1]. */
export function GOB_udp_1(self: GameObject, timing: number): void {
  const s = self.dl_sprites
  if (!s) return
  GO_set_sprite(self, (gp().counter1 & timing ? s.get(1) : s.get(0)) as string)
}

/** `GOB_update_cs_2a()` — OG cs only checks the facing side; also check the other so Moa2 won't spawn a Flame in a solid. */
export function GOB_update_cs_2a(self: GameObject): void {
  goUpdateCs.GO_update_cs(self)
  if (self.hspd & 0x80) {
    if (deps.csRgtColliding(self) & TID_SOLID1) self.cs |= CS_RGT // Add Right
  } else if (deps.csLftColliding(self) & TID_SOLID1) self.cs |= CS_LFT // Add Left
}
/** GO_update_cs / GO_update_cs_1 live with the collision + player port (they read PC state); seam here. */
export const goUpdateCs = {
  GO_update_cs: (_self: GameObject): void => {
    throw new Error('GML script GO_update_cs is not ported yet')
  },
}

/** `GameObjectB_Draw()` — the draw event body. Debug overlays (hitboxes, eID/HP) are the dev-tools port's. */
export function GameObjectB_Draw(self: GameObject): void {
  // `Boss_Draw()` is the Boss layer's Draw event: `Boss_HPBar_draw(); event_inherited();` — its inherited
  // event is this one. The adapter dispatches draws on the concrete class, so the Boss half is a hook.
  if (self instanceof Boss) gobDrawHooks.Boss_HPBar_draw(self)
  GameObject_draw(self, self.state)
  GameObjectB_draw_1(self)
}

/** `Boss_Draw()` — installed by the boss port (`gob1/boss/registry.ts`) so this module stays acyclic. */
export const gobDrawHooks = {
  Boss_HPBar_draw: (_self: GameObject): void => {},
}
/** `GameObjectB_draw_1()` — Explosion & Rising XP */
export function GameObjectB_draw_1(self: GameObject): void {
  GOB_draw_death_explosions(self)
  GOB_draw_rising_xp(self)
}
/** `GameObjectB_draw_2()` */
export function GameObjectB_draw_2(self: GameObject): void {
  if (self.can_draw_self && self.sprite) GameObject_draw_1a(self, self.sprite, self.palidx) // draw self
  GameObjectB_draw_1(self)
}
/** `GOB_draw_death_explosions()` */
export function GOB_draw_death_explosions(self: GameObject): void {
  if (!self.explosion_can_draw_self) return
  self.explosion_can_draw_self = false
  if (!self.explosion_sprite) return
  for (let _i = 0; _i < self.explosion_count; _i++) {
    const _y = self.explosion_y + (_i << 4)
    draw_sprite_(
      self.explosion_sprite,
      0,
      self.drawX,
      _y,
      GG().PI_MOB_ORG,
      1,
      self.explosion_yscale,
      self.depth,
    )
    draw_sprite_(
      self.explosion_sprite,
      0,
      self.drawX,
      _y,
      GG().PI_MOB_ORG,
      -1,
      self.explosion_yscale,
      self.depth,
    )
  }
}
/** `GOB_draw_rising_xp()` — the XP number floating up from a defeated enemy. */
export function GOB_draw_rising_xp(self: GameObject): void {
  if (!self.xp_can_draw) return
  self.xp_can_draw = false
  const g = gp()
  const xp = self.xp
  let _x = 1 + (xp > 999 ? 1 : 0) + (xp > 99 ? 1 : 0) + (xp > 9 ? 1 : 0) // num of chars
  _x *= g.RisingXP_SPR_W >> 1 // half total w
  _x = self.drawX - _x
  for (let _i = 3; _i >= 0; _i--) {
    if (!Math.trunc(xp / 10 ** _i)) continue
    const _num = xp % 10 ** (_i + 1)
    const _digit = Math.trunc(_num / 10 ** _i)
    const spr = g.dl_rising_xp_spr.get(_digit) as string
    draw_sprite_(spr, 0, _x, self.yt, -1, 1, 1, self.depth)
    _x += g.RisingXP_SPR_W
  }
}

// `data_go_scr('GameObjectB', GameObjectB_init, 0, GameObjectB_step)` — the layer every GOB inherits.
registerScripts({ GameObjectB_init, GameObjectB_step, GameObjectB_step2 })
