// Ported from ZALiA: Menu_Create (parent object of PauseMenu, LevelUpMenu, DialogueWindow, OptionsMenu, QuitAppMenu).
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML state, typed progressively
import { DEPTH_MENU_WINDOW } from '@z2/data'
import { Instance } from '../../runtime/instance'

export class Menu extends Instance {
  readonly objectName: string = 'Menu'
  depth: number = DEPTH_MENU_WINDOW
  canDrawSections: any = 0
  /** WIDE VIEW (OG: $18 = dist from view_y top) */
  Y_BASE: number = 0x18 + 0x06 + 0x10
  drawX: number = 0
  drawY: number = 0
  timer: number = 0
  tmr_cursor_1: number = 0
  constructor() {
    super()
    Menu_Create(this)
  }
}

/** GML: Menu_Create() */
export function Menu_Create(self: Menu): void {
  self.depth = DEPTH_MENU_WINDOW
  self.canDrawSections = 0
  self.Y_BASE = 0x18 + 0x06 + 0x10 // WIDE VIEW
  //Y_BASE = $18; // OG.  dist from view_y top
  self.drawX = 0
  self.drawY = 0
  self.timer = 0
  self.tmr_cursor_1 = 0
}
