/**
 * The `Audio` singleton (GameMaker object `Audio`) — state ported from `Audio_Create.gml` (non-table part),
 * field names and comments are ZALiA's. The sound table itself is `audioTable.json` (see `Audio_Create.ts`).
 *
 * Sound ids are asset *names* (strings); `0` means "no sound" as in the GML. Sound instances are positive
 * numbers handed out by `aud_play_sound`. The dead `pitch1_*` experiment (all uses were commented out in
 * ZALiA) is dropped.
 */
import { STR_Default, STR_Title } from '@z2/data'
import { DsList, DsMap } from '../../runtime/ds'
import { type AudioCommand, type AudioGroup, type AudioPlayback, MemoryPlayback } from './playback'

export type SoundId = string | 0
export type SoundInst = number

export class AudioState {
  readonly objectName = 'Audio'
  testing_num = 0

  // ------------------------------------------------
  /** The big string-keyed audio data map (themes, sets, volumes, intros, indices …). */
  dm = new DsMap<string | number | boolean>()
  dl_AUDIO_SETS = new DsList<string>()
  /** Number of real sets (before the RANDOM pseudo-sets are appended). */
  AudioSets_COUNT = 0
  dl_random_custom = new DsList<string>()
  audio_set: string = STR_Default

  Volume_DEFAULT = 5
  snd_vol = this.Volume_DEFAULT
  mus_vol = this.Volume_DEFAULT

  SND_NONE: SoundId = 'snd_0' // snd_0: 1 frame of dead air
  /** `NAME = add_sound_data(...)` constants from Audio_Create (SND_FIRE_1A, MUS_Z1_DNGN1, …). */
  readonly named = new Map<string, string>()
  sound(name: string): SoundId {
    return this.named.get(name) ?? 0
  }

  SND_FIRE_VER = 1
  /** 0: current snd, 1: can play, 2: volume (-1 = default), 3: timer, 4: timer reset, 5..8: variants */
  dl_snd_fire = new DsList<SoundId | number>()

  PRIORITY_TOP = 0xff // highest priority
  PRIORITY_LOW = 0 // lowest  priority

  rm_music_theme: string = STR_Title
  rm_music_theme_prev: string = STR_Title
  current_theme_random_track: SoundId = 0
  dm_random_custom = new DsMap<boolean | number>()

  // intro of mus_rm_body
  mus_rm_intr: SoundId = 0
  // music track for current rm
  mus_rm_body: SoundId = 0
  // music track to play on any given frame when playing music is qualified
  mus_rm_curr: SoundId = 0
  // instance of music track to play on any given frame when playing music is qualified
  mus_rm_inst: SoundInst = 0
  // music body prev rm
  mus_rm_body_prev: SoundId = 0
  encounter_sound_inst: SoundInst = 0
  can_play_mus_rm_body = true
  mus_rm_started = false
  // This is just in case there is a boss intro track and the boss is defeated before the boss intro is
  // done and the boss body hasn't played yet
  can_play_boss_music = false
  // NOTE: GameMaker runs audio in a completely separate system from the game so tracking any sounds by
  // FRAME won't work. Updating these each frame and comparing them gives the ability to determine the
  // frame the song looped since the track pos on the loop frame is a fraction instead of an int.
  mus_rm_pos_prev = 0
  mus_rm_pos_curr = 0
  // The timing_sound_.. variables are used to loop the title screen scrolling properly
  timing_sound_position_prev = 0
  timing_sound_position_curr = 0
  timing_sound_inst: SoundInst = 0
  mus_rm_body_last_pos = 0
  mus_asset_name_interrupted: string | 0 = 0
  // Incremented in update_Sound if 'walk water' sound is to play. Bit 1 means the pitch is higher.
  walk_water_played_count = 0 // 07F6
  dm_music_inst = new DsMap<string | number | boolean>()
  LowHPSound_PLAY_LIMIT1 = 0x08 // How many times snd can play at OG speed
  LowHPSound_counter1 = 0
  LowHPSound_counter2 = 0
  LowHPSound_HP_AMT = 0x20 // Container_AMT
  TOGGLE_SOUND_KEY = 'N'
  TOGGLE_MUSIC_KEY = 'M'

  // ---- port boundary -----------------------------------------------------
  /** Commands for the adapter (see playback.ts). Drain each frame. */
  readonly commands: AudioCommand[] = []
  playback: AudioPlayback = new MemoryPlayback()
  /** instance handle → asset name (`audio_get_name(inst)`) */
  readonly instNames = new Map<number, string>()
  private nextInst = 1
  newInst(sound: string): SoundInst {
    const inst = this.nextInst++
    this.instNames.set(inst, sound)
    if (this.instNames.size > 0x400) {
      // keep the map bounded; old instances are long finished
      for (const k of this.instNames.keys()) {
        if (this.instNames.size <= 0x200) break
        this.instNames.delete(k)
      }
    }
    return inst
  }
  /** `audio_get_name(x)` for a sound name or an instance; '' for 0/unknown. */
  audio_get_name(x: SoundId | SoundInst | undefined): string {
    if (typeof x === 'string') return x
    if (!x) return ''
    return this.instNames.get(x) ?? ''
  }
  /** `audio_is_playing(x)` */
  audio_is_playing(x: SoundId | SoundInst | undefined): boolean {
    if (!x) return false
    return this.playback.isPlaying(x)
  }
  push(cmd: AudioCommand): void {
    this.commands.push(cmd)
    if (this.playback instanceof MemoryPlayback) this.playback.apply(cmd)
  }
  audio_group_set_gain(group: AudioGroup, gain: number): void {
    this.push({ kind: 'groupGain', group, gain })
  }
}

/** Module-level singleton, like the GML object `Audio`. Re-initialised by `Audio_Create()`. */
export const Audio = new AudioState()

export function setAudioPlayback(p: AudioPlayback): void {
  Audio.playback = p
}
