const DK1 = STR_Palette + STR_Index

/** `set_rm_brightness(value)` */
export function set_rm_brightness(value: number): void {
  const g = gd()
  g.rm_brightness = Math.min(Math.max(value, 0), g.RM_BRIGHTNESS_MAX)
}

/** `rm_pal_qual_lit()` — is the room fully lit (for palette purposes)? */
export function rm_pal_qual_lit(): boolean {
  const g = gd()
  switch (g.mod_RM_BRIGHTNESS_SYS) {
    case 0: // OG
      return p.pal_rm_dark_idx === -1 || !!(fd().items & ITM_CAND)
    case 1: // Light torches to brighten rm
    case 2: // CANDLE gives +1 brightness. Light torches to brighten rm
      return g.rm_brightness >= g.RM_BRIGHTNESS_MAX
    default:
      return false
  }
}

/** `update_rm_brightness()` — recompute `g.rm_brightness` from candle + lit torches; refresh dark palette on change. */
export function update_rm_brightness(): void {
  const g = gd()
  const G = Gd()
  const _BRIGHTNESS_PREV = g.rm_brightness
  const _SCENE_IS_RANDO =
    !!G.SceneRando_enabled &&
    g.rm_name !== fd().dm_rando.val(dk_SceneRando + STR_Scene + STR_Randomized + g.rm_name, g.rm_name)
  // SceneRando_scene_brightness_control: 1: All dark scenes during scene rando are max brightness. 2: Use dark scene setting of vanilla scene
  if (p.pal_rm_dark_idx < 0 || (_SCENE_IS_RANDO && G.SceneRando_scene_brightness_control === 1)) {
    set_rm_brightness(g.RM_BRIGHTNESS_MAX)
  } else if (!g.EnterRoom_SpawnGO_timer) {
    set_rm_brightness(0)
    if (fd().items & ITM_CAND) set_rm_brightness(g.rm_brightness + 1)
    if (g.rm_brightness < g.RM_BRIGHTNESS_MAX) {
      for (const go of eachBrightnessContributor()) {
        if (!go.state || !go.brightness) continue
        set_rm_brightness(g.rm_brightness + go.brightness)
        if (g.rm_brightness >= g.RM_BRIGHTNESS_MAX) break
      }
    }
  }
  if (g.rm_brightness !== _BRIGHTNESS_PREV) {
    tile_hidden_update_2a() // updates all tg(tile graphic) ids
    if (g.rm_brightness < g.RM_BRIGHTNESS_MAX) update_Pallete_1b() // update dark pal
  }
}

/** `update_Pallete_1b()` — swap in the dark-room palette set for the current brightness. */
export function update_Pallete_1b(): void {
  const g = gd()
  if (g.rm_brightness < g.RM_BRIGHTNESS_MAX && p.pal_rm_dark_idx + 1) {
    // -1 means not a dark rm
    const _DARK_PAL = p.dg_pal_rm_dark.get(p.pal_rm_dark_idx, g.rm_brightness) ?? ''
    change_pal(string_copy(p.pal_rm_new, 1, PAL_CHAR_PER_SET) + _DARK_PAL)
  }
}

/** `update_Pallete_1a()` — 8E23: JSR 9235. PC palette, background colour, flash timers. */
export function update_Pallete_1a(pcIsCucco: boolean): void {
  const g = gd()
  const pc = Gd().pc
  // 0: Green, 1: Red(SHIELD active || have RING), 2: Blue(SHIELD active && have RING)
  let _pi = PI_PC1
  const tunic = () =>
    (pcIsCucco ? PI_CUCCO1 : PI_PC1) +
    Math.sign(fd().items & ITM_RING) +
    Math.sign(g.spells_active & SPL_PRTC)
  if (g.game_end_state) {
    _pi = pcIsCucco ? PI_CUCCO1 : PI_PC1 // Switch to traditional green tunic for end game.
  } else if (gmBool(g.FallScene_timer)) {
    // GML truthiness: FallScene_INACTIVE (-1) is false
    _pi = tunic()
  } else if (p.SpellFlash_PC_timer) {
    const _idx = (p.SpellFlash_PC_timer - 1) & 0x3
    _pi = (p.dg_PI_SEQ.get(pcIsCucco ? 0x5 : 0x4, _idx) ?? PI_PC1) as number
  } else if (pc.Disguise_enabled) {
    _pi = pcIsCucco ? PI_DISGUISE_CUCCO : PI_DISGUISE_PC
  } else {
    _pi = tunic()
  }
  p.dg_PI_SEQ.set(0x0, 0x0, _pi)
  // Update background color
  let _color = p.BackgroundColor_scene
  if (g.all_bg_black_only) {
    _color = C.C_BLK1 // For patreon user Guardian's bg color issue
  } else if (p.Flash_Bgr_timer || p.Flash_Bgr_timer2) {
    // for Ganon3 spell and boss explosion
    if (p.Flash_Bgr_timer2)
      _color = C.C_RED3 // Ganon3_ProjRain_update() updates the bgr color
    else if (p.BackgroundFlash_setting === 1)
      _color = (p.dg_color_seq[0] as number[])[(p.Flash_Bgr_timer - 1) & 0x3] as number // Spell flash
    else if (p.BackgroundFlash_setting)
      _color = p.dl_BackgroundFlash_COLORS[p.BackgroundFlash_setting] ?? C.C_BLK1
  }
  set_background_color(_color)
  // Update spell flash timer 074B.  9245
  if (p.Flash_Pal_timer) p.Flash_Pal_timer--
  if (p.Flash_Bgr_timer) p.Flash_Bgr_timer--
  if (p.Flash_Bgr_timer2) p.Flash_Bgr_timer2--
  if (p.SpellFlash_PC_timer) p.SpellFlash_PC_timer--
  if (p.SpellFlash_GOB_timer) p.SpellFlash_GOB_timer--
  if (p.SpellReady_flash_timer) p.SpellReady_flash_timer--
  update_rm_brightness()
}

/** `triforce_pal_update()` — cycle the triforce palette every 4 frames. */
export function triforce_pal_update(): void {
  const _POS = get_pal_pos(p.triforce_pi) + PI_LIT1
  const _PAL = (p.dg_pal_seq[0] as string[])[(gd().counter1 >> 2) & 0x3] as string
  change_pal(strReplaceAt(p.pal_rm_new, _POS, _PAL.length, _PAL))
}

/**
 * `pal_swap_set_tiles(palette image, pal index, start layer, end layer)` — palette-swap whole tile layers.
 *
 * GM has no per-tile shader hook, so ZALiA brackets the depth range with `TileSwapperStart`/`TileSwapperEnd`
 * instances whose Draw events set and reset the shader around everything drawn between them. The port's
 * tile layers carry the index themselves, so the range collapses to the one depth every ZALiA caller passes.
 */
/** One of the string-keyed extras ZALiA writes next to the scene's Tiled map (`g.dm_tile_file` is a map). */
function sceneFileValue(key: string): unknown {
  const file = gd().dm_tile_file as unknown as { get?: (k: string) => unknown } | undefined
  return file?.get?.(key)
}

/**
 * The scene's parsed Tiled map. `g.dm_tile_file` is a `DsMap` that *carries* the map on `.map`
 * (`set_scene_tile_file`) and mirrors a few of its fields as entries; `decodeScenePalette` reads
 * `layers`/`width` as properties, so handing it the map wrapper returned `undefined` every time. GML gets
 * there by `json_encode`/`json_decode`-ing the file into a plain ds_map.
 */
function sceneFileMap(): TiledMapLike | undefined {
  const file = gd().dm_tile_file as unknown as { map?: TiledMapLike } | undefined
  return file?.map
}

export function pal_swap_set_tiles(paletteIndex: number, depth: number): void {
  if (!p.use_pal_swap || !gmBool(paletteIndex) || paletteIndex >= p.palette_image.width) return
  tileWorld().layer(depth)?.setPalIdx(paletteIndex)
}

/** The palette index `color_tiles` would apply to one pal-swap depth this frame, or -1 for no swap. */
function tileLayerPi(depth: number, darkLevel: number): number {
  const g = gd()
  const _idx = g.dl_TILE_DEPTHS.findIndex(depth)
  let _pi = (p.dg_depth_pi.get(_idx, 1) ?? 0) as number
  if (darkLevel) _pi = p.dm_pi.val(`${hexStr(_pi)}_Dark${darkLevel}`, _pi) as number
  // The `pal_swap_set_tiles` guards: an index it would reject leaves the layer unswapped.
  if (!p.use_pal_swap || !gmBool(_pi) || _pi >= p.palette_image.width) return -1
  return _pi
}

/**
 * `color_tiles()` — give every pal-swap tile layer the palette index it must draw with, once per frame
 * (`Surface_Step.gml:217`). Returns what it applied, for tests.
 *
 * Without this the room's own tile layers draw in the palette the tileset PNGs are stored in, which is
 * *every background in the game*. The port had the script but no caller, and it called `pal_swap_set` (the
 * sprite-side global) instead of the tile-layer swap.
 */
export function color_tiles(): { depth: number; pi: number }[] {
  const g = gd()
  const out: { depth: number; pi: number }[] = []
  // What each depth should be drawn with this frame. A depth that stops being set stops being swapped —
  // the TileSwapper instances deactivate each frame ("Stop calling it, or set the pal index to 0 to stop
  // palette swapping", `pal_swap_set_tiles.gml:4`) — so anything not in here is cleared below.
  const wanted = new Map<number, number>()
  if (p.pal_rm_def !== undefined) {
    const _DARK_LEVEL = rm_pal_qual_lit() ? 0 : 1
    for (let i = g.dl_pal_swap_depths.size - 1; i >= 0; i--) {
      // Note: All depths(tile layers) could use any mix of pi(Palette Index).
      const _depth = g.dl_pal_swap_depths.get(i) as number
      const _pi = tileLayerPi(_depth, _DARK_LEVEL)
      if (_pi >= 0) wanted.set(_depth, _pi)
      out.push({ depth: _depth, pi: _pi })
    }
  }
  // One assignment per layer per frame. Clearing every layer first and then re-setting it would change
  // each layer's palette index *twice* a frame, and `setPalIdx` bumps the version that tells the renderer
  // to rebuild — which had it destroying and re-creating every tile image of every layer, every frame.
  for (const [depth, layer] of tileWorld().layers) layer.setPalIdx(wanted.get(depth) ?? -1)
  return out
}

/** `get_pc_skin_palette(skin index, *return if not found)` — the 3 tunic palettes for a skin. */
export function get_pc_skin_palette(skinIdx: number, dflt?: string): string {
  const g = gd()
  const pc = Gd().pc
  const _PALETTE_COUNT = p.dm_pi.val(`PC${STR_Count}`, PC_COUNT) as number // each tunic color/armor
  let _return: string
  if (dflt !== undefined) _return = dflt
  else {
    _return = string_copy(p.PAL_SET_PC_1, 1, PAL_CHAR_PER_PAL * _PALETTE_COUNT)
    if (p.pal_rm_curr.length) _return = string_copy(p.pal_rm_curr, get_pal_pos(PI_PC1), _return.length)
  }
  if (skinIdx >= 0) {
    const _Skin_COUNT = pc.dm_skins.val(STR_Set + STR_Count) as number
    if (_Skin_COUNT && skinIdx < _Skin_COUNT) {
      const _DATAKEY = pc.dm_skins.get(hexStr(skinIdx) + STR_Datakey)
      if (_DATAKEY !== undefined) {
        let _Skin_palette = p.PAL_SET_PC_1 // default
        _Skin_palette = String(pc.dm_skins.val(String(_DATAKEY) + STR_Palette, _Skin_palette))
        _Skin_palette = String(pc.dm_skins.val(hexStr(skinIdx) + STR_Palette, _Skin_palette))
        if (g.RandoPalette_state) {
          const _PC_RANDO_PALETTE = fd().dm_rando.get(`${STR_Palette}_PC01`)
          if (_PC_RANDO_PALETTE !== undefined) {
            // Just need to set the tunic colors to their rando colors in _Skin_palette
            let _pos = Math.max(1, PAL_BASE_COLOR_ORDER.indexOf('R') + 1) // tunic position
            _pos-- // make it an index
            _pos *= PAL_CHAR_PER_COLOR
            _pos++ // ++ because string
            const _POS = _pos
            for (let i = 0; i < _PALETTE_COUNT; i++) {
              // Each armor/tunic level
              _pos = _POS + PAL_CHAR_PER_PAL * i
              const _color = string_copy(String(_PC_RANDO_PALETTE), _pos, PAL_CHAR_PER_COLOR)
              _Skin_palette = strReplaceAt(_Skin_palette, _pos, _color.length, _color)
            }
          }
        }
        _return = _Skin_palette
      }
    }
  }
  return _return // 3 palettes. The palettes of the 3 armor levels. Example: "F3182A36"+"F3181636"+"F3182236"
}

/** `p_Room_End()` */
export function p_Room_End(): void {
  p.pal_rm_def = undefined
  p.pal_rm_new = ''
  p.pal_rm_curr = ''
}

/** `p_Draw()` — end-of-frame: rebuild the palette image if the scene palette changed. */
export function p_Draw(): void {
  palSpr_changeColors()
}

/** `p_Game_End()` — nothing to free without GM resources. */
export function p_Game_End(): void {}

/** `dev_tile_highlighting()` */
export function dev_tile_highlighting(): void {
  const g = gd()
  if (g.can_show_t_solid) tile_layer_show(DEPTH_SOLIDS)
  else tile_layer_hide(DEPTH_SOLIDS)
  if (g.can_show_t_unique) tile_layer_show(DEPTH_UNIQUE)
  else tile_layer_hide(DEPTH_UNIQUE)
}

/** Which scene's data to use (scene rando may substitute another scene for `g.rm_name`). */
function sceneUsed(): string {
  const g = gd()
  if (!Gd().SceneRando_enabled) return g.rm_name
  return String(fd().dm_rando.val(dk_SceneRando + STR_Scene + STR_Randomized + g.rm_name, g.rm_name))
}

/**
 * `p_Room_Start()` — build the room's palette: fixed prefix (base, gui, pc, cucco) + BGR palettes from
 * the Tiled file + mob/npc set + dark set, then skin/rando/holiday/room overrides, then permutations.
 */
export function p_Room_Start(): void {
  const g = gd()
  const G = Gd()
  const _scene_used = sceneUsed()
  const dm = p.FallScene_dm
  dm.set(STR_Counter, 1)
  dm.set(dk_PI + STR_Sequence + STR_Index, 0)
  dm.set(STR_Current + STR_Fall + STR_Speed, dm.val(STR_Fall + STR_Speed + STR_Default, 2))
  dm.set(`${STR_Current}_y`, fall_scene_get_y_base())
  p.Flash_Pal_timer = 0 // 074B.
  p.Flash_Bgr_timer = 0
  p.SpellFlash_PC_timer = 0
  p.SpellFlash_GOB_timer = 0
  p.SpellReady_flash_timer = 0
  if (g.room !== 'rmB_Death') p.BackgroundColor_at_death = -1
  if (g.room_type === 'A')
    p.BackgroundColor_scene = g.dm_rm.val(g.rm_name + dk_BackgroundColor, C.C_BLK1) as number
  else if (g.room === 'rmB_GameOver') p.BackgroundColor_scene = p.GameOverScreen_BGR_COLOR
  else p.BackgroundColor_scene = C.C_BLK1
  if (g.room_type === 'A' && p.BackgroundColor_scene !== C.C_BLK1) {
    let _qualifies = !!G.Halloween1_enabled
    // 0: Off, 1: Dungeons & PC, 2: Dungeons, PC, and 2 BGR PI random palette when enter room
    if (!_qualifies && g.view_y_page_min === g.view_y_page_max && g.RandoPalette_state) {
      if ([C.C_VLT2, C.C_BLU2, C.C_BLU4, C.C_PUR3].includes(p.BackgroundColor_scene)) {
        // Town / Encounter / Old Kasuto / Cemetery sky
        _qualifies = !world.irandom(0xf)
      }
    }
    if (_qualifies) {
      const _INST = NIAO_create2(0, 0, 3, 'StarSky_1_init')
      if (_INST !== null) p.BackgroundColor_scene = C.C_BLK1
    }
  }
  if (G.SceneRando_enabled && _scene_used !== g.rm_name) {
    const _color = g.dm_rm.val(_scene_used + dk_BackgroundColor, p.BackgroundColor_scene) as number
    if (_color === C.C_BLK1) p.BackgroundColor_scene = C.C_BLK1
  }
  set_background_color(p.BackgroundColor_scene)
  // ------------------------------------------------------------------------------------------
  p.pal_rm_def = undefined // the rm's default palette. pal_rm_def, pal_rm_new, pal_rm_curr should all be equal by the end
  p.pal_rm_new = '' // Checked every frame. Triggers pal change if != pal_rm_curr
  p.pal_rm_curr = '' // the rm's current palette
  p.pal_rm_file = undefined // from .json Tiled file
  p.pal_rm_dark = p.pal_rm_dark_DEFAULT
  // ------------------------------------------------------------------------------------------
  const _FILE_CLEANING =
    !!g.FileCleaning01_STATE && g.room_type === 'A' && g.rm_name === g.FileCleaning01_rm_name
  let _dm_pal_data_datakey = g.rm_name
  switch (g.room_type) {
    case 'A': {
      if (_FILE_CLEANING) {
        const _file_map = sceneFileMap()
        if (_file_map !== undefined) p.pal_rm_file = decodeScenePalette(_file_map)
      } else {
        const _dk = g.dm_rm.get(_scene_used + dk_FileName + STR_Quest + hexStr(g.file_data_quest_num))
        if (_dk !== undefined) p.pal_rm_file = p.dm_scene_palette.get(`${_dk}${dk_BGR}`) as string | undefined
        if (p.pal_rm_file === undefined)
          p.pal_rm_file = paletteFromSceneFile(g.rm_name, g.file_data_quest_num)
      }
      break
    }
    case 'B': {
      // For rmB, TitleScreen is the only one w/ a Tiled file currently(2021/09/09).
      if (g.room === 'rmB_Title') {
        const _dk = 'Title_000'
        p.pal_rm_file = p.dm_scene_palette.get(`${_dk}${dk_BGR}`) as string | undefined
        if (p.pal_rm_file === undefined || _FILE_CLEANING) {
          const _map = sceneFileMap()
          // FIXED: the GML hands `_dk` ("Title_000", a *file* name) to `get_palette_via_file_data`, which
          // passes it to `rm_get_file_data` as a *scene* name — so the lookup fails there too and ZALiA
          // falls back to `dm_pal_data`, its hand-maintained `PaletteData01.txt` cache. This port dropped
          // that cache on purpose and decodes the palette from the scene's Tiled file instead (see
          // FIDELITY_NOTES), so it has to look the file up by the scene name it actually has. Without this
          // the title screen ran on `pal_rm_DEFAULT`: every scene palette came out red/gray/black, which is
          // why the sword drew red, the terrain red and gray, and the text and logo not at all.
          p.pal_rm_file =
            _FILE_CLEANING && _map
              ? decodeScenePalette(_map)
              : paletteFromSceneFile(g.rm_name, g.file_data_quest_num)
        }
      } else _dm_pal_data_datakey = g.room
      break
    }
    case 'C': {
      // Overworld
      p.pal_rm_def = p.OW_PAL
      break
    }
  }
  if (p.pal_rm_def === undefined) {
    if (p.pal_rm_file !== undefined) {
      // GUI, PC, CUCCO (by palette index — see Palette.litDefaultPalette)
      p.pal_rm_def = p.PAL_SET2
      // BGR
      const _count1 = BGR_COUNT * PAL_CHAR_PER_PAL
      p.pal_rm_def += string_copy(p.pal_rm_file, 1, _count1) // BGR
      // MOB
      const _val1 = p.dm_scene_palette.get(_scene_used + dk_MOB)
      if (_val1 !== undefined) p.pal_rm_def += String(_val1)
      else if (g.area_name === Area_TownA) p.pal_rm_def += p.PAL_NPC_SET1
      else if (g.area_name === Area_TownB) p.pal_rm_def += p.PAL_NPC_SET2
      else if (g.dungeon_num) p.pal_rm_def += p.PAL_MOB_SET2
      else p.pal_rm_def += p.PAL_MOB_SET1
      // dark
      p.pal_rm_def += p.pal_rm_dark
    } else {
      p.pal_rm_def = String(p.dm_pal_data.val(_dm_pal_data_datakey, p.pal_rm_DEFAULT))
      p.pal_rm_def += p.pal_rm_dark
    }
  }
  p_Room_Start_palette_rando()
  if (g.room !== 'rmB_Title' && g.room !== 'rmB_FileSelect') {
    const _idx = G.pc.dm_skins.val(STR_Current + STR_Idx) as number
    const _pal = get_pc_skin_palette(_idx)
    p.pal_rm_def = strReplaceAt(p.pal_rm_def, get_pal_pos(PI_PC1), _pal.length, _pal)
  }
  // ------------------------------------------------------------------------------------------
  // pal_rm_dark_idx == -1: Means this rm is NOT a dark rm
  p.pal_rm_dark_idx = g.dm_rm.val(g.rm_name + dk_DarkRoom, -1) as number
  p.pal_rm_dark_idx = Math.min(Math.max(p.pal_rm_dark_idx, -1), p.dg_pal_rm_dark.width - 1)
  if (p.pal_rm_def !== undefined && p.pal_rm_dark_idx + 1 && g.rm_brightness < g.RM_BRIGHTNESS_MAX) {
    const _idx = Math.min(Math.max(g.rm_brightness, 0), p.dg_pal_rm_dark.height - 1)
    p.pal_rm_dark = p.dg_pal_rm_dark.get(p.pal_rm_dark_idx, _idx) ?? p.pal_rm_dark
    p.pal_rm_def = string_copy(p.pal_rm_def, 1, PAL_CHAR_PER_SET)
    p.pal_rm_def += p.pal_rm_dark
  }
  // Make sure pal_rm_def has the correct number of chars.
  const _LEN1 = p.pal_rm_def.length
  if (_LEN1 < PAL_CHAR_PER_SCENE) p.pal_rm_def += '0'.repeat(PAL_CHAR_PER_SCENE - _LEN1)
  else p.pal_rm_def = string_copy(p.pal_rm_def, 1, PAL_CHAR_PER_SCENE)
  // ------------------------------------------------------------------------------------------
  if (G.Halloween1_enabled && g.room_type === 'A') applyHalloweenTownPalettes()
  const bm = g.burnable_mgr
  if (bm?.scene_has_burnable) {
    // Guarantee Burnable always has same color
    p.pal_rm_def = strReplaceAt(
      p.pal_rm_def,
      get_pal_pos(bm.Burnable_pi),
      bm.Burnable_PAL.length,
      bm.Burnable_PAL,
    )
  }
  // These are here, instead of the create events, because the objects are in the room assets causing
  // their create events to call before `p_Room_Start()`
  switch (g.room) {
    case 'rmB_GameOver': {
      const _pal = build_pal(C.C_WHT1, C.C_RED3, C.C_BLK1, C.C_BLK1, -2, -2, -2, -2)
      p.pal_rm_def = strReplaceAt(p.pal_rm_def, p.PAL_POS_MOB2, _pal.length, _pal) // PAL_POS_MOB2: MOB RED
      break
    }
    case 'rmB_ContinueSave': {
      const _pal = build_pal(C.C_RED2, C.C_RED3, C.C_BLK1, C.C_BLK1, -2, -2, -2, -2)
      p.pal_rm_def = strReplaceAt(p.pal_rm_def, p.PAL_POS_BGR1, _pal.length, _pal)
      break
    }
    default:
      break
  }
  // fall-scene permutations
  for (let i = (dm.val(STR_Type + STR_Count) as number) - 1; i >= 0; i--) {
    const _type_ = String(i + 1)
    const _count = dm.val(_type_ + dk_PI + STR_Count) as number
    for (let j = 0; j < _count; j++) {
      const _dk = _type_ + dk_PI + hexStr(j + 1)
      const _color_order = String(
        dm.val(_dk + C.PAL_BASE_COLOR_ORDER.length ? `${_dk}_Color${STR_Order}` : _dk, PAL_BASE_COLOR_ORDER),
      )
      const _parent = dm.val(`${_dk}_Parent`, PI_BGR1) as number
      const _name = String(dm.val(_dk + STR_Name, _dk))
      dm.set(_dk, add_pi_permut(_parent, _color_order, _name))
    }
  }
  p.spell_unaffordable_pi = add_pi_permut(PI_GUI1, 'BWRGKYMC', 'spell unaffordable')
  p.spell_futile_pi = add_pi_permut(PI_GUI1, 'RBWGMKYC', 'spell futile')
  // If colors "YMKC" are the base colors, have them use their "WRBG" counterpart
  for (let i = 0; i < BGR_COUNT; i++) {
    const _pi = p.dm_pi.val(`BGR${i + 1}${DK1}`) as number
    for (let j = 4; j < C.COLORS_PER_PALETTE; j++) {
      const ch = PAL_BASE_COLOR_ORDER[j] as string
      const _color = get_pal_color(p.pal_rm_def, _pi, ch)
      if (_color === C.BASE_COLORS[j]) {
        const _pos = get_pal_pos(_pi) + PAL_CHAR_PER_COLOR * j
        const counterpart = get_pal_color(p.pal_rm_def, _pi, PAL_BASE_COLOR_ORDER[j - 4] as string)
        p.pal_rm_def = strReplaceAt(p.pal_rm_def, _pos, PAL_CHAR_PER_COLOR, color_str(counterpart))
      }
    }
  }
  // ------------------------------------------------------------------------------------------
  p.pal_rm_def = change_pal(p.pal_rm_def)
  p.pal_rm_def = string_copy(p.pal_rm_def, 1, PAL_CHAR_PER_SCENE)
}

/** `get_palette_via_file_data(0, scene, quest)` — load the scene's Tiled file and decode its BGR palettes. */
export function paletteFromSceneFile(sceneName: string, questNum: number): string | undefined {
  const map = rm_get_file_data(sceneName, questNum)
  return map ? decodeScenePalette(map) : undefined
}

/** `p_Room_Start_palette_rando()` — randomizer palette overrides (BGR of dungeons, PC, cucco). */
export function p_Room_Start_palette_rando(): void {
  const g = gd()
  const _G = Gd()
  const _scene_used = sceneUsed()
  if (p.pal_rm_def === undefined) return
  // 0: Off, 1: Dungeons, PC, 2: Dungeons, 2 background PI of Non-dungeon scenes, PC
  if (g.room === 'rmB_Title' || g.room === 'rmB_FileSelect' || !g.RandoPalette_state) return
  if (g.room_type === 'A' && (g.dungeon_num || g.RandoPalette_state === 2)) {
    // `f.dm_rando[?STR_Palette+STR_Rando+scene]`: The palettes for PI_BGR1-PI_BGR4
    const _pal = fd().dm_rando.get(STR_Palette + STR_Rando + _scene_used)
    if (_pal !== undefined) {
      const pal = String(_pal)
      p.pal_rm_def = strReplaceAt(p.pal_rm_def, get_pal_pos(PI_BGR1), pal.length, pal)
      if (g.dungeon_num) {
        let _solid_wall_pi_pos = get_pal_pos(PI_BGR1)
        const layerPi = (needle: (name: string) => boolean): number | undefined => {
          for (let i = 0; i < g.dl_TILE_DEPTH_NAMES.size; i++) {
            const _dk = String(g.dl_TILE_DEPTH_NAMES.get(i)) // "BG01, BG02, ..."
            const _depth = g.dm_TILE_DEPTH.get(_dk)
            // `g.dm_tile_file` is a `DsMap` (`set_scene_tile_file`), so its entries are not own
            // properties: read through `.get`, as every other reader in the port does. As a property
            // access this was `undefined` for every layer, so the `FGWALL01_01` lookup always fell back
            // and the background-wall loop below never ran at all.
            const _layer_name = sceneFileValue(_dk + STR_Depth + STR_Layer + STR_Name)
            if (_depth === undefined || typeof _layer_name !== 'string' || !needle(_layer_name)) continue
            const _idx = g.dl_TILE_DEPTHS.findIndex(_depth as number)
            if (_idx !== -1) return (p.dg_depth_pi.get(_idx, 1) ?? undefined) as number | undefined
          }
          return undefined
        }
        // use "STRUCTURE_FGWALL01_02" in the layer name so this doesn't run
        const wallPi = layerPi((n) => n.includes('FGWALL01_01'))
        if (wallPi !== undefined) _solid_wall_pi_pos = get_pal_pos(wallPi)
        // "B" color(shadow-tone) of STRUCTURE_FGWALL01_01 palette
        const _color_shd = str_hex(
          string_copy(p.pal_rm_def, _solid_wall_pi_pos + PAL_CHAR_PER_COLOR * 2, PAL_CHAR_PER_COLOR),
        )
        const hsv = colour_get_hsv(_color_shd)
        const _LUM = Math.max(0x00, Math.floor(hsv.v * 0.8))
        let _color = make_colour_hsv(hsv.h, hsv.s, _LUM)
        if ([...C.BASE_COLORS, C.C_ALPHA0].includes(_color)) _color = C.C_BLK1
        // background walls / windows take the darkened shadow colour
        for (let i = 0; i < g.dl_TILE_DEPTH_NAMES.size; i++) {
          const _dk = String(g.dl_TILE_DEPTH_NAMES.get(i))
          const _depth = g.dm_TILE_DEPTH.get(_dk)
          const _layer_name = sceneFileValue(_dk + STR_Depth + STR_Layer + STR_Name)
          if (_depth === undefined || typeof _layer_name !== 'string') continue
          // use "STRUCTURE_BGWALL01_02" in the layer name if you dont want this to run
          if (_layer_name.includes('BGWALL01_01') || _layer_name.includes('WINDOW01')) {
            const _idx = g.dl_TILE_DEPTHS.findIndex(_depth as number)
            if (_idx !== -1) {
              const _pi = (p.dg_depth_pi.get(_idx, 1) ?? 0) as number // pi for the layer
              const _pos = get_pal_pos(_pi) + PAL_CHAR_PER_COLOR * 2
              const s = color_str(_color)
              p.pal_rm_def = strReplaceAt(p.pal_rm_def, _pos, s.length, s)
            }
          }
        }
      }
    }
  }
  // PC Palette
  const _pcPal = fd().dm_rando.get(`${STR_Palette}_PC01`)
  if (_pcPal !== undefined)
    p.pal_rm_def = strReplaceAt(p.pal_rm_def, get_pal_pos(PI_PC1), String(_pcPal).length, String(_pcPal))
  // Cucco Palette
  const _cuccoPal = fd().dm_rando.get(`${STR_Palette + STR_Cucco}01`)
  if (_cuccoPal !== undefined)
    p.pal_rm_def = strReplaceAt(
      p.pal_rm_def,
      get_pal_pos(PI_CUCCO1),
      String(_cuccoPal).length,
      String(_cuccoPal),
    )
}

/** Halloween town palettes (p_Room_Start). */
function applyHalloweenTownPalettes(): void {
  const g = gd()
  const bp = build_pal
  const towns = [
    STR_Rauru,
    STR_Ruto,
    STR_Saria,
    STR_Mido,
    STR_Nabooru,
    STR_Darunia,
    STR_New_Kasuto,
    STR_Old_Kasuto,
  ]
  if (!towns.includes(g.town_name) || p.pal_rm_def === undefined) return
  let _pal: string | 0 = 0
  let _mob_pal: string | 0 =
    bp(C.C_VLT1, C.C_VLT2, C.C_YLW4, C.C_BLK1, -2, -2, -2, -2) + // MOB ORG
    bp(C.C_VLT1, C.C_ORG3, C.C_BLK1, C.C_BLK1, -2, -2, -2, -2) + // MOB RED
    bp(C.C_RED3, C.C_ORG4, C.C_BLK1, C.C_BLK1, -2, -2, -2, -2) + // MOB BLU
    bp(C.C_VLT1, C.C_PNK3, C.C_BLK1, C.C_BLK1, -2, -2, -2, -2) // MOB PUR
  const bg = (a: number[], b: number[], c: number[], d: number[]) =>
    bp(a[0] as number, a[1] as number, a[2] ?? C.C_BLK1, C.C_BLK1, -2, -2, -2, -2) +
    bp(b[0] as number, b[1] as number, b[2] ?? C.C_BLK1, C.C_BLK1, -2, -2, -2, -2) +
    bp(c[0] as number, c[1] as number, c[2] ?? C.C_BLK1, C.C_BLK1, -2, -2, -2, -2) +
    bp(d[0] as number, d[1] as number, d[2] ?? C.C_BLK1, C.C_BLK1, -2, -2, -2, -2)
  if (g.dm_rm.val(g.rm_name + STR_Town + STR_House)) {
    _pal = bg(
      [C.C_BLU4, C.C_VLT4],
      [C.C_VLT3, C.C_BLK1],
      [C.C_BLU3, C.C_MGN4, C.C_YLW4],
      [C.C_YLW1, C.C_YGR3],
    )
  } else if (g.dm_rm.val(g.rm_name + STR_Town + STR_Outside)) {
    switch (g.town_name) {
      case STR_Rauru:
        _pal = bg(
          [C.C_ORG1, C.C_YLW3],
          [C.C_PUR3, C.C_GRY4],
          [C.C_BLK1, C.C_ORG3, C.C_YLW4],
          [C.C_BLU2, C.C_PUR3],
        )
        break
      case STR_Ruto:
        _pal = bg(
          [C.C_ORG4, C.C_BLK1, C.C_GRY4],
          [C.C_GRY2, C.C_YLW3],
          [C.C_GRY2, C.C_GRY4],
          [C.C_VLT4, C.C_PUR3],
        )
        break
      case STR_Saria:
        _pal = bg([C.C_GRY3, C.C_GRY4], [C.C_CYN3, C.C_VLT4], [C.C_GRY2, C.C_CYN4], [C.C_RED2, C.C_RED4])
        break
      case STR_Mido:
        _pal = bg(
          [C.C_YLW3, C.C_YLW4, C.C_PUR2],
          [C.C_GRN1, C.C_GRN3],
          [C.C_YLW4, C.C_GRN3],
          [C.C_VLT4, C.C_PUR3],
        )
        break
      case STR_Nabooru:
        _pal = bg([C.C_ORG1, C.C_YLW3], [C.C_PUR3, C.C_GRY4], [C.C_GRN3, C.C_YGR4], [C.C_BLU2, C.C_PUR3])
        break
      case STR_Darunia:
        _pal = bg([C.C_YLW3, C.C_PUR4], [C.C_VLT2, C.C_CYN4], [C.C_ORG1, C.C_ORG3], [C.C_PNK3, C.C_YLW4])
        break
      case STR_New_Kasuto:
        _pal = bg([C.C_ORG3, C.C_ORG4], [C.C_YLW3, C.C_YLW4], [C.C_GRY3, C.C_GRY4], [C.C_BLU2, C.C_PUR3])
        break
      case STR_Old_Kasuto:
        _pal = bg([C.C_GRY3, C.C_GRY4], [C.C_CYN3, C.C_VLT4], [C.C_GRY2, C.C_CYN4], [C.C_RED2, C.C_RED4])
        _mob_pal = 0
        break
      default:
        _pal = 0
        _mob_pal = 0
        break
    }
  } else {
    _mob_pal = 0
  }
  if (_pal !== 0) p.pal_rm_def = strReplaceAt(p.pal_rm_def, get_pal_pos(PI_BGR1), _pal.length, _pal)
  if (_mob_pal !== 0)
    p.pal_rm_def = strReplaceAt(p.pal_rm_def, get_pal_pos(PI_MOB_ORG), _mob_pal.length, _mob_pal)
}

/**
 * PC skin palettes read from the spritesheet (p_Draw_1): the palette colours for custom pc sprites are in
 * the top left of the $FF (bottom-right) box of the sprite sheet, as 3 rows of 3 4×4 colour squares, each
 * row separated by 1 pixel. `readPixel(x, y)` returns the packed BGR colour of that pixel of the box.
 */
export function skinPaletteFromPixels(readPixel: (x: number, y: number) => number): string {
  let _palette = ''
  for (let j = 0; j < 3; j++) {
    // each palette
    const cols: string[] = [p.C_WHT0_, p.C_RED0_, p.C_BLU0_]
    const _y = j * 5 // each palette is 5 pixels apart
    for (let k = 0; k < 3; k++) cols[k] = color_str(readPixel(k * 4, _y))
    _palette += build_pal(
      cols[0] as string,
      cols[1] as string,
      cols[2] as string,
      C.C_BLK1,
      C.C_SWDH,
      -2,
      -2,
      -2,
    )
  }
  return _palette
}
