/**
 * `Dev_StabToCheat` — a row of item icons floating at the PC's feet; stabbing one grants (or removes)
 * that item / skill / spell / container / level / XP, or kills the PC. Gated on `g.use_StabToCheat`
 * (Options → Dev Tools), created unconditionally at boot like ZALiA does.
 *
 * Dropped: `Dev_StabToCheat_end` (only freed ds_* structures — garbage collected here) and the
 * commented-out `ar_spr[]` twin of `dl_sprites`.
 *
 * Fixed (FIDELITY_NOTES): `Dev_StabToCheat_Step.gml:281` tests `_num == 22` twice in the level-up
 * branch, so LIFE could never be raised.
 */
import {
  CONT_PIECE_OBJ_HP,
  CONT_PIECE_OBJ_MP,
  dk_Fanfare,
  dk_GannonLaugh,
  dk_GetItem,
  dk_GetSpell,
  dk_StrikeEnemy,
  PC_H,
  SKILL_THD,
  SKILL_THU,
} from '@z2/data'
import { gmOr } from '../../nes/math8'
import { DsGrid, DsList } from '../../runtime/ds'
import { Instance } from '../../runtime/instance'
import { f, G, g } from '../../runtime/world'
import { rectInRect } from '../collision/geometry'
import { PC_update_sword_hb } from '../collision/hitbox'
import { get_ground_y } from '../collision/solid'
import { c_lime } from '../draw/index'
import {
  cont_cnt_hp,
  cont_cnt_mp,
  cont_piece_cnt_hp,
  cont_piece_cnt_mp,
  get_jar_restore_dur,
} from '../file/stats'
import { pc } from '../game_object/goa/pc'
import { inRange } from '../math/index'
import { hex_str, val } from '../other/index'
import { PI_GUI1, PI_MOB_BLU, PI_MOB_ORG, PI_MOB_RED, PI_PC1 } from '../palette/pi'
import { get_pi } from '../palette/scenePalette'
import { draw_rect_, draw_sprite, draw_sprite_, drawState } from '../rooms/draw'
import { aud_play_sound } from '../sound/play'
import { get_audio_theme_track } from '../sound/theme'

const OPTION_CNT = 0x20

export class Dev_StabToCheat extends Instance {
  readonly objectName = 'Dev_StabToCheat'
  /** `<persistent>-1</persistent>` in ZALiA's object definition — survives a room change. */
  override readonly persistent = true
  depth = 0
  OPTION_CNT = OPTION_CNT
  dl_sprites = new DsList<string>()
  dl_pi = new DsList<number>()
  is_active = false
  collided_cheat = false
  cheat_num = 0
  SND_REMOVE: string | 0 = 0
  CLM_BASE = 0x18
  ROW_BASE = 0x18
  CLM_OFF = 0x04
  ROW_OFF = 0x02
  dg_hb = new DsGrid<number>(OPTION_CNT, 4, 0)

  constructor() {
    super()
    Dev_StabToCheat_Create(this)
  }
  step(): void {
    Dev_StabToCheat_Step(this)
  }
  draw(): void {
    Dev_StabToCheat_Draw(this)
  }
  roomStart(): void {
    Dev_StabToCheat_Room_Start(this)
  }
  roomEnd(): void {
    Dev_StabToCheat_Room_End(this)
  }
}

/** `Dev_StabToCheat_Create()` */
export function Dev_StabToCheat_Create(self: Dev_StabToCheat): void {
  const SPR_CAND = 'spr_Item_Candle'
  const SPR_GLOV = 'spr_Item_Glove'
  const SPR_HAMM = 'spr_Item_Hammer'
  const SPR_RAFT = 'spr_Item_Raft'
  const SPR_BOOT = 'spr_Item_Boots'
  const SPR_FLUT = 'spr_Item_Flute'
  const SPR_CROS = g.SPR_ITEM_CROSS
  const SPR_MKEY = 'spr_Item_Magical_Key'
  const SPR_THDW = 'spr_arrow_6_dwn'
  const SPR_THUP = 'spr_arrow_6_up'
  const SPR_SPEL = 'spr_icon_bottle_1a'
  const SPR_HART = 'spr_Item_Heart_container'
  const SPR_MAGI = 'spr_Item_Magic_container'
  const SPR_LVLA = String(val(G.SPR_ICON_ATK, 'spr_icon_attack_1a'))
  const SPR_LVLM = String(val(G.SPR_ICON_MAG, 'spr_icon_magic_1a'))
  const SPR_LVLL = String(val(G.SPR_ICON_LIF, 'spr_icon_life_1a'))
  const SPR_PBAG = 'spr_Item_PBag'
  const SPR_BOTL = 'spr_Item_Bottle'

  const s = self.dl_sprites
  s.clear()
  // Major Items
  s.add(SPR_CAND, SPR_GLOV, SPR_RAFT, SPR_BOOT, SPR_FLUT, SPR_CROS, SPR_HAMM, SPR_MKEY) // $00-$07
  // Skills
  s.add(SPR_THDW, SPR_THUP) // $08, $09
  // Spells
  for (let _i = 0; _i < 8; _i++) s.add(SPR_SPEL) // $0A-$11
  // Heart & Magic Containers
  s.add(SPR_HART, SPR_MAGI) // $12, $13
  // Attack, Magic, Life Levels (up then down)
  s.add(SPR_LVLA, SPR_LVLM, SPR_LVLL, SPR_LVLA, SPR_LVLM, SPR_LVLL) // $14-$19
  // Magic Refill Jar
  s.add(SPR_BOTL) // $1A
  // P-Bags
  s.add(SPR_PBAG, SPR_PBAG, SPR_PBAG, SPR_PBAG) // $1B-$1E
  // Suicide
  s.add('spr_0') // $1F

  const pi = self.dl_pi
  pi.clear()
  const ORG = get_pi(PI_MOB_ORG)
  const BLU = get_pi(PI_MOB_BLU)
  const RED = get_pi(PI_MOB_RED)
  const PC1 = get_pi(PI_PC1)
  const GUI = get_pi(PI_GUI1)
  for (let _i = 0; _i < 8; _i++) pi.add(ORG) // items
  pi.add(PC1, PC1) // skills
  for (let _i = 0; _i < 8; _i++) pi.add(BLU) // spells
  pi.add(RED, RED) // containers
  pi.add(GUI, GUI, GUI) // levels up
  pi.add(GUI, GUI, GUI) // levels down (GML re-reads size-3, same values)
  pi.add(RED) // magic jar
  pi.add(ORG, ORG, ORG, ORG) // p-bags
  pi.add(PC1) // suicide

  self.is_active = false
  self.collided_cheat = false
  self.cheat_num = 0
  self.SND_REMOVE = get_audio_theme_track(dk_GannonLaugh)
  self.CLM_BASE = 0x18
  self.ROW_BASE = 0x18
  self.CLM_OFF = 0x04
  self.ROW_OFF = 0x02
  self.dg_hb = new DsGrid<number>(OPTION_CNT, 4, 0)
  Dev_StabToCheat_update_1a(self)
}

/** `Dev_StabToCheat_update_1a()` — lays the option hitboxes out on the ground under the PC. */
export function Dev_StabToCheat_update_1a(self: Dev_StabToCheat): void {
  const _HBW = 4
  const _HBH = 4
  let _x = self.CLM_BASE << 3
  const _X_INC = self.CLM_OFF << 3 // x increment
  const p = pc()
  let _Y = (p.yt >> 3) << 3
  _Y = get_ground_y(p.x, _Y, 1, _Y + PC_H)
  _Y += -PC_H
  _Y += 8

  const dg = self.dg_hb
  const at = (x: number, y: number): number => dg.get(x, y) ?? 0
  for (let _i = 0; _i < OPTION_CNT; _i++) {
    dg.set(_i, 0, _x + 2)
    dg.set(_i, 1, _Y)
    dg.set(_i, 2, _HBW)
    dg.set(_i, 3, _HBH)
    if (inRange(_i, 0, 7) || inRange(_i, 10, 17)) {
      // items & spells: the pair sits one row below
      _i++
      dg.set(_i, 0, at(_i - 1, 0))
      dg.set(_i, 1, at(_i - 1, 1) + 0x10)
      dg.set(_i, 2, at(_i - 1, 2))
      dg.set(_i, 3, at(_i - 1, 3))
    } else if (inRange(_i, 23, 25)) {
      // decrease level: under the matching increase
      dg.set(_i, 0, at(_i - 3, 0))
      dg.set(_i, 1, at(_i - 3, 1) + 0x10)
      dg.set(_i, 2, at(_i - 3, 2))
      dg.set(_i, 3, at(_i - 3, 3))
    } else if (inRange(_i, 26, 30)) {
      // Magic Refill Jar[26], P-Bags[27-30]
      dg.set(_i, 0, at(_i, 0) - (0x0c << 3))
      dg.set(_i, 1, _Y + ((_i & 0x1) << 4))
      dg.set(_i, 2, _HBW)
      dg.set(_i, 3, _HBH)
      if (!(_i & 0x1)) _x -= _X_INC
    }
    _x += _X_INC
  }
}

/** `dg_hb[#x, y]` with GM's "missing cell reads 0". */
function hb(self: Dev_StabToCheat, x: number, y: number): number {
  return self.dg_hb.get(x, y) ?? 0
}

/** `Dev_StabToCheat_Step()` */
export function Dev_StabToCheat_Step(self: Dev_StabToCheat): void {
  if (!g.use_StabToCheat) {
    self.is_active = false
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  if (!self.is_active) {
    self.is_active = true
    Dev_StabToCheat_update_1a(self) // Populate dg_hb[#]
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }

  const p = pc()
  if (!p.SwordHB_collidable) {
    self.collided_cheat = false
    return // !!!!!!!!!!!!!!!!!
  }
  if (self.collided_cheat) return // !!!!!!!!!!!!!!!!!

  // ------------------------------------------------------------
  let _num = 0
  PC_update_sword_hb()
  for (let _i = 0; _i < OPTION_CNT; _i++) {
    if (
      rectInRect(
        hb(self, _i, 0),
        hb(self, _i, 1),
        hb(self, _i, 2),
        hb(self, _i, 3),
        p.SwordHB_x,
        p.SwordHB_y,
        p.SwordHB_w,
        p.SwordHB_h,
      )
    ) {
      self.collided_cheat = true
      _num = _i + 1
      break
    }
  }
  if (!self.collided_cheat) return // !!!!!!!!!!!!!!!!!

  if (inRange(_num, 1, 8)) {
    // Major items -----------------------------------------------------
    const _bit = 0x1 << (_num - 1)
    if (!(f.items & _bit)) {
      f.items = gmOr(f.items, _bit) // 64-bit: the item bits reach bit 32
    } else {
      f.items &= ~_bit
      aud_play_sound(self.SND_REMOVE)
      return // !!!!!!!!!!!!!!!!!
    }
    p.HoldItem_timer = 0x20 // $70
    p.HoldItem_palidx = PI_MOB_ORG
    p.HoldItem_ver = 1
    p.HoldItem_object = `ItmA${_num - 1}`
    aud_play_sound(get_audio_theme_track(`${dk_GetItem}01`), -1, false, -1, `${dk_GetItem}01`)
  } else if (inRange(_num, 9, 10)) {
    // Skills -----------------------------------------------------
    const _bit = _num === 10 ? SKILL_THU : SKILL_THD
    if (f.skills & _bit) {
      f.skills &= ~_bit
      aud_play_sound(self.SND_REMOVE)
      return
    }
    f.skills |= _bit
    aud_play_sound(get_audio_theme_track(dk_GetSpell), -1, false, -1, dk_GetSpell)
  } else if (inRange(_num, 11, 18)) {
    // Spells -----------------------------------------------------
    const _bit = 1 << (_num - 11)
    if (f.spells & _bit) {
      f.spells &= ~_bit
      aud_play_sound(self.SND_REMOVE)
      return // !!!!!!!!!!!!!!!!!!
    }
    f.spells |= _bit
    aud_play_sound(get_audio_theme_track(dk_GetSpell), -1, false, -1, dk_GetSpell)
  } else if (inRange(_num, 19, 20)) {
    // Containers -----------------------------------------------------
    const stat = _num === 19 ? 'hp' : 'mp'
    if (stat === 'hp' ? cont_cnt_hp() === f.CONT_MAX_HP : cont_cnt_mp() === f.CONT_MAX_MP) return
    const _added = addContainerPieces(stat)
    if (_added.length) {
      if (stat === 'hp') g.StatRestore_timer_hp = 0xff
      else g.StatRestore_timer_mp = 0xff
      p.HoldItem_object = stat === 'hp' ? CONT_PIECE_OBJ_HP : CONT_PIECE_OBJ_MP
      p.HoldItem_timer = 0x20 // OG: $70
      p.HoldItem_palidx = PI_MOB_RED
      aud_play_sound(get_audio_theme_track(dk_Fanfare), -1, false, -1, dk_Fanfare)
    }
  } else if (inRange(_num, 21, 23)) {
    // Levels up -----------------------------------------------------
    // GML tested `_num == 22` twice, so LIFE was unreachable — the third case is `_num == 23`.
    if (_num === 21) {
      if (f.level_atk >= 8) return
      f.level_atk++
    } else if (_num === 22) {
      if (f.level_mag >= 8) return
      f.level_mag++
    } else {
      if (f.level_lif >= 8) return
      f.level_lif++
    }
    aud_play_sound(get_audio_theme_track(dk_Fanfare), -1, false, -1, dk_Fanfare)
  } else if (inRange(_num, 24, 26)) {
    // Levels down ---------------------------------------------------
    if (_num === 24) {
      if (f.level_atk < 1) return
      f.level_atk--
    } else if (_num === 25) {
      if (f.level_mag < 1) return
      f.level_mag--
    } else {
      if (f.level_lif < 1) return
      f.level_lif--
    }
    aud_play_sound(self.SND_REMOVE)
  } else if (inRange(_num, 27, 31)) {
    const _NUM = _num - 27
    switch (_NUM) {
      case 0:
        g.StatRestore_timer_mp += get_jar_restore_dur(1)
        break
      case 1:
        f.xpPending = (f.xpPending + 50) & 0xffff
        break
      case 2:
        f.xpPending = (f.xpPending + 100) & 0xffff
        break
      case 3:
        f.xpPending = (f.xpPending + 250) & 0xffff
        break
      case 4:
        f.xpPending = (f.xpPending + 500) & 0xffff
        break
    }
  } else if (_num === 32) {
    f.hp = 0
    p.is_dead = true
  }

  aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
}

/**
 * The container-piece top-up loop of `Dev_StabToCheat_Step` (identical for hp and mp in the GML, which
 * copy-pasted it): fills the current container up to the next whole one and returns the pieces added.
 */
function addContainerPieces(stat: 'hp' | 'mp'): string {
  const PER = stat === 'hp' ? f.CONT_PIECE_PER_HP : f.CONT_PIECE_PER_MP
  const MAX = stat === 'hp' ? f.CONT_PIECE_MAX_HP : f.CONT_PIECE_MAX_MP
  const count = () => (stat === 'hp' ? cont_piece_cnt_hp() : cont_piece_cnt_mp())
  const pieces = () => (stat === 'hp' ? f.cont_pieces_hp : f.cont_pieces_mp)
  let _added = ''
  const _COUNT = PER - (count() % PER)
  for (let _i = 0; _i < _COUNT; _i++) {
    for (let _j = 0; _j < MAX; _j++) {
      let _can_add = true
      const _str = hex_str(Math.trunc(_j / PER) + 1) + hex_str((_j % PER) + 1)
      const _count = count()
      for (let _k = 0; _k < _count; _k++) {
        if (pieces().substr(_k << 2, 4) === _str) {
          _can_add = false
          break // _k
        }
      }
      if (_can_add) {
        _added += _str
        if (stat === 'hp') f.cont_pieces_hp += _str
        else f.cont_pieces_mp += _str
        break // _j
      }
    }
  }
  return _added
}

/** `Dev_StabToCheat_Draw()` */
export function Dev_StabToCheat_Draw(self: Dev_StabToCheat): void {
  if (!g.use_StabToCheat || !self.is_active) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const depthCopy = drawState.depth
  drawState.depth = self.depth
  for (let i = 0; i < OPTION_CNT; i++) {
    const _x = hb(self, i, 0) + 2
    let _y = hb(self, i, 1) + 2
    draw_sprite_(self.dl_sprites.get(i), 0, _x, _y, self.dl_pi.get(i) ?? -1)
    if (g.can_draw_hb) draw_rect_(c_lime, _x - 2, _y - 2, hb(self, i, 2), hb(self, i, 3), 1, true)
    if (inRange(i, 10, 17)) {
      _y -= 14
      const spr = g.dl_rising_xp_spr.get(i - 9) as string | undefined
      if (spr) draw_sprite(spr, 0, _x, _y)
    }
  }
  drawState.depth = depthCopy
}

/** `Dev_StabToCheat_Room_Start()` */
export function Dev_StabToCheat_Room_Start(self: Dev_StabToCheat): void {
  g.use_StabToCheat = false
  self.is_active = false
}

/** `Dev_StabToCheat_Room_End()` */
export function Dev_StabToCheat_Room_End(self: Dev_StabToCheat): void {
  g.use_StabToCheat = false
  self.is_active = false
}
