import { FONT_LAYOUT } from '@z2/data'

/** ZALiA `draw_text_`: each character is frame `string_pos(char, FONT_LAYOUT) - 1` of a font sprite. */
export function glyphFrames(text: string, layout: string = FONT_LAYOUT): number[] {
  const out: number[] = []
  for (const ch of text) {
    const i = layout.indexOf(ch)
    out.push(i < 0 ? -1 : i)
  }
  return out
}

/** Depth: GameMaker draws higher depth first (further back); Phaser draws higher depth last. */
export function phaserDepth(gmDepth: number): number {
  return -gmDepth
}
