/** `Snaraa` — ZALiA `enemy/snaraa`: added enemy; hides as wall (bgr palette), lunges along a solid path, settles. */
import { CS_BD1, dk_AgroDistance, TID_SOLID1 } from '@z2/data'
import { abs8b, byte, gmBool, gmRound as round } from '../../../../../../nes/math8'
import { G, g, p } from '../../../../../../runtime/world'
import {} from '../../../../../collision/geometry'
import { ocsHV4 } from '../../../../../collision/ocs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { find_clm_solid } from '../../../../../collision/solid'
import { draw_rect } from '../../../../../draw/index'
import { background_colour } from '../../../../../gui/deps'
import { bit_dir, inRange, sign_ } from '../../../../../math/index'
import { registerObjectClass } from '../../../../../other/registry'
import { get_pal_color } from '../../../../../palette/palString'
import { draw_point_colour } from '../../../../../rooms/draw'
import { cam_x_range, cam_xl_min } from '../../../../../view/camera'
import { Enemy } from '../../../../classes'
import { GO_draw_sprite } from '../../../../go/draw'
import { GO_update_cam_vars, is_facing_pc_ } from '../../../../go/misc'
import { set_xy, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GameObjectB_init, GOB_update_2a, update_EF11 } from '../../../GameObjectB'
import { spawnDataAfter, str_hex } from '../../shared'

export class Snaraa extends Enemy {
  readonly objectName = 'Snaraa' as const
  pal_bgr = 0
  SUB_STATE_IDLE = 1
  SUB_STATE_AGRO = 2
  SUB_STATE_ATK1 = 3
  SUB_STATE_LNDG = 4
  SUB_STATE_SETL = 5
  sub_state = 1
  SPR_1: string = 'spr_Snaraa_1a_3_WRB'
  SPR_2: string = 'spr_Snaraa_1a_2_WRB'
  SPR_3: string = 'spr_Snaraa_1a_1_WRB'
  HSPD_MIN = 0x04
  HSPD_MAX = 0x30
  hspd_landing_start = 0
  path_dir = 0
  path_dist = 0
  rc_a = 0
  rc_b = 0
  rc_a2 = 0
  rc_b2 = 0
  dist_remain_landing_start = 0
  AGRO_DIST0 = 0xc0
  agro_distance = 0xc0
  AGRO_DUR = 0x30
  SETTLE_DUR = 0x1c
  COOLDOWN_DUR = 0xc0 - 0x1c
}
registerObject('Snaraa', Snaraa)
registerObjectClass('Snaraa', Snaraa)

/** `Snaraa_init1()` */
export function Snaraa_init1(self: Snaraa): void {
  GameObjectB_init(self)
  self.can_draw_self_exception = true
  self.pal_bgr = G.PI_BGR3
  GO_init_palidx(self, G.PI_MOB_BLU)
  self.palidx = self.pal_bgr
  self.DRAW_YOFF = 0
  let _a = 1
  self.SUB_STATE_IDLE = _a++ // IDLE
  self.SUB_STATE_AGRO = _a++ // AGgRO
  self.SUB_STATE_ATK1 = _a++ // ATtacK
  self.SUB_STATE_LNDG = _a++ // LaNDinG
  self.SUB_STATE_SETL = _a++ // SETtLe
  self.sub_state = self.SUB_STATE_IDLE
  // ZALiA has an `if (false)` branch with the sprite order reversed; the live order is kept.
  self.SPR_1 = 'spr_Snaraa_1a_3_WRB'
  self.SPR_2 = 'spr_Snaraa_1a_2_WRB'
  self.SPR_3 = 'spr_Snaraa_1a_1_WRB'
  self.HSPD_MIN = 0x04
  self.HSPD_MAX = 0x30
  self.hspd = 0
  self.hspd_landing_start = 0
  self.path_dir = 0
  self.path_dist = 0
  // a: start location, b: target location; rc_a/rc_b are the rc of id.x, rc_a2/rc_b2 the rc of solid tiles
  self.rc_a = 0
  self.rc_b = 0
  self.rc_a2 = 0
  self.rc_b2 = 0
  self.dist_remain_landing_start = 0
  self.AGRO_DIST0 = 0xc0
  self.agro_distance = self.AGRO_DIST0
  self.AGRO_DUR = 0x30
  self.SETTLE_DUR = 0x1c
  self.COOLDOWN_DUR = 0xc0 - self.SETTLE_DUR
}

/** `Snaraa_init2()` */
export function Snaraa_init2(self: Snaraa): void {
  if (((G.dg_solid.get((self.xl >> 3) - 1, self.yt >> 3) as number) & 0xff) === TID_SOLID1)
    self.facing_dir = 1
  else self.facing_dir = -1
  if (gmBool(self.facing_dir))
    self.path_dir = 0x01 // 1: RGT
  else self.path_dir = 0x02 // 2: LFT
  self.path_dist = Snaraa_update_1(self, self.x >> 3)
  Snaraa_update_2(self)
  self.timer = 0x40
  const agro = spawnDataAfter(self.dk_spawn, dk_AgroDistance, 0x10)
  if (agro !== undefined) self.agro_distance = str_hex(agro)
}

/** `Snaraa_update_1(start clm)` — path length to the next solid (or one page beyond the room). */
export function Snaraa_update_1(self: Snaraa, startClm: number): number {
  const _DIR = bit_dir(self.path_dir & 0x03)
  let _X = find_clm_solid(TID_SOLID1, startClm, self.y >> 3, _DIR, 0, startClm)
  if (_X === startClm) {
    // set new target 1 page beyond rm
    _X = cam_xl_min() + (cam_x_range() >> 1) + (cam_x_range() >> 1) * _DIR // target x
  } else {
    _X += gmBool(_DIR) ? 0 : 1
    _X = _X << 3
  }
  _X += 8 * -_DIR
  return Math.abs((startClm << 3) - _X)
}

/** `Snaraa_update_2()` */
export function Snaraa_update_2(self: Snaraa): void {
  const _DIR = bit_dir(self.path_dir & 0x03)
  const _ROW = (self.y >> 3) << 8
  self.rc_a = _ROW | ((self.x + 0) >> 3)
  self.rc_b = _ROW | ((self.x + self.path_dist * _DIR) >> 3)
  self.rc_a2 = self.rc_a + -_DIR - (gmBool(_DIR) ? 1 : 0)
  self.rc_b2 = self.rc_b + _DIR - (gmBool(_DIR) ? 0 : 1)
}

/** `Snaraa_update_3()` — dist remaining to wall */
export function Snaraa_update_3(self: Snaraa): number {
  return (((self.rc_b & 0xff) << 3) - self.x) * bit_dir(self.path_dir & 0x03)
}

/** `Snaraa_update_4()` — DE40 */
export function Snaraa_update_4(self: Snaraa): void {
  GO_update_cam_vars(self)
  update_EF11(self) // DE51: JSR EF11
  GOB_update_2a(self) // DE54 & DE6C, DD3D. Despawn check
}

/** `Snaraa_update()` */
export function Snaraa_update(self: Snaraa): void {
  const P = pc()
  self.BodyHB_idx = 0
  if (gmBool(self.stun_timer)) {
    Snaraa_update_4(self)
    return
  }
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE: {
      self.hspd = 0
      // if NOT all w AND NOT all h in ocs area
      if (
        gmBool(self.timer) ||
        !ocsHV4(self) ||
        !ocsHV4(P) ||
        !is_facing_pc_(self) ||
        Math.abs(self.x - P.x) > self.agro_distance ||
        !inRange(self.y, P.yt, P.yt + P.hh)
      )
        break
      self.timer = self.AGRO_DUR
      self.sub_state = self.SUB_STATE_AGRO
      break
    }
    case self.SUB_STATE_AGRO: {
      if (gmBool(self.timer)) break
      self.hspd = (self.HSPD_MIN * bit_dir(self.path_dir & 0x03)) & 0xff
      self.timer = 0x10 // Delay mouth open full.
      self.sub_state = self.SUB_STATE_ATK1
      break
    }
    case self.SUB_STATE_ATK1: {
      self.BodyHB_idx = self.BodyHB_IDX
      let _x = 0
      const _DIR = bit_dir(self.path_dir & 0x03)
      self.hspd = Math.min(Math.max(abs8b(self.hspd) + 1, self.HSPD_MIN), self.HSPD_MAX)
      self.hspd = (self.hspd * _DIR) & 0xff
      if (byte(G.dg_solid.get(self.rc_b2 & 0xff, self.rc_b2 >> 8) as number) !== TID_SOLID1) {
        // Just in case target no longer solid.
        _x = (self.rc_a & 0xff) << 3
        self.path_dist = Snaraa_update_1(self, _x >> 3)
        _x += self.path_dist * _DIR
        self.rc_b = (self.rc_b & 0xff00) | (_x >> 3)
        self.rc_b2 = self.rc_b + _DIR - (gmBool(_DIR) ? 0 : 1)
      }
      const _DIST = self.path_dist >> 2
      _x = ((self.rc_b & 0xff) << 3) + _DIST * -_DIR
      if (!gmBool((_x - self.x) * _DIR)) {
        self.dist_remain_landing_start = Math.abs(self.x - ((self.rc_b & 0xff) << 3))
        self.hspd_landing_start = abs8b(self.hspd)
        self.sub_state = self.SUB_STATE_LNDG
      }
      break
    }
    case self.SUB_STATE_LNDG: {
      self.BodyHB_idx = self.BodyHB_IDX
      let _DIR = bit_dir(self.path_dir & 0x03)
      const _dist_remain = Snaraa_update_3(self)
      const _dist_target = (0x04 << 3) * (self.facing_dir === _DIR ? 1 : 0) // num or 0
      const _MIN = 4
      let _hspd = _MIN
      if (gmBool(_dist_remain)) {
        _hspd = (self.hspd_landing_start - _MIN) * (_dist_remain / self.dist_remain_landing_start)
        _hspd = Math.min(round(_MIN + _hspd), self.HSPD_MAX)
      }
      self.hspd = (_hspd * _DIR) & 0xff
      if (_dist_remain <= _dist_target) {
        self.facing_dir = -_DIR
        if (!gmBool(_dist_target)) {
          set_xy(self, (self.rc_b & 0xff) << 3, self.y)
          self.vspd = 0
          self.hspd = 0
          self.hspd_landing_start = 0
          self.dist_remain_landing_start = 0
          self.path_dir = self.path_dir ^ 0x03
          self.path_dist = Snaraa_update_1(self, self.x >> 3)
          Snaraa_update_2(self)
          _DIR = bit_dir(self.path_dir & 0x03)
          if (byte(G.dg_solid.get(self.rc_a2 & 0xff, self.rc_a2 >> 8) as number) !== TID_SOLID1) {
            self.timer = 0x40
            self.sub_state = self.SUB_STATE_ATK1
          } else {
            self.timer = self.SETTLE_DUR
            self.sub_state = self.SUB_STATE_SETL
          }
        }
      }
      break
    }
    case self.SUB_STATE_SETL: {
      if (gmBool(self.timer)) break
      self.timer = self.COOLDOWN_DUR
      self.sub_state = self.SUB_STATE_IDLE
      break
    }
  }
  Snaraa_update_4(self)
  if (self.sub_state !== self.SUB_STATE_IDLE && self.cs & CS_BD1) enemy_collide_pc_body(self)
  if (gmBool(self.hspd)) updateX(self)
  if (gmBool(self.vspd)) updateY(self)
}

/** `Snaraa_udp()` */
export function Snaraa_udp(self: Snaraa): void {
  self.can_draw_self = true
  if (self.sub_state === self.SUB_STATE_IDLE || self.sub_state === self.SUB_STATE_AGRO)
    self.palidx = self.pal_bgr
  else self.palidx = self.palidx_def
  self.draw_yoff = 0
  if (self.sub_state === self.SUB_STATE_AGRO && !(self.timer & 0x03))
    self.draw_yoff = sign_(self.timer & 0x08)
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE:
      GO_set_sprite(self, self.SPR_1)
      self.palidx = self.pal_bgr
      break
    case self.SUB_STATE_AGRO: {
      let _CUE = self.AGRO_DUR >> 2 // less than 25% of AGRO time left
      _CUE += 0x08
      GO_set_sprite(self, self.SPR_1)
      if (self.timer < _CUE && self.timer & 0x02) self.palidx = self.palidx_def
      else self.palidx = self.pal_bgr
      break
    }
    case self.SUB_STATE_ATK1:
      if (gmBool(self.timer)) GO_set_sprite(self, self.SPR_2)
      else GO_set_sprite(self, self.SPR_3)
      break
    case self.SUB_STATE_LNDG:
      GO_set_sprite(self, self.SPR_3)
      break
    case self.SUB_STATE_SETL: {
      const _CUE = 0x08
      if (self.timer > self.SETTLE_DUR - 0x10) GO_set_sprite(self, self.SPR_3)
      else GO_set_sprite(self, self.SPR_2)
      if (self.timer > _CUE || self.timer & 0x02) self.palidx = self.palidx_def
      else self.palidx = self.pal_bgr
      break
    }
  }
}

/** `Snaraa_draw()` */
export function Snaraa_draw(self: Snaraa): void {
  if (!self.can_draw_self) return
  if (self.sub_state === self.SUB_STATE_IDLE || self.sub_state === self.SUB_STATE_AGRO) {
    draw_rect(background_colour(), self.xl, self.yt, self.ww, self.hh)
  }
  GO_draw_sprite(self, self.sprite, self.palidx)
  if (self.sprite === self.SPR_3) {
    // Eye
    draw_point_colour(
      self.drawX + (1 + (gmBool(self.xScale) ? 0 : 1)) * self.xScale,
      self.drawY - 2,
      get_pal_color(p.pal_rm_curr, self.palidx, 'W'),
    )
  }
}

/** `Snaraa_end()` — empty in ZALiA. */
export function Snaraa_end(_self: Snaraa): void {}

registerScripts({
  Snaraa_init1,
  Snaraa_init2,
  Snaraa_update,
  Snaraa_udp,
  Snaraa_draw,
  Snaraa_end,
})
