/** `Pushable_init2()` — object_index: PushA */
export function Pushable_init2(self: PushA): void {
  self.can_draw_self_exception = true
  switch (self.ver) {
    default:
    case 1:
    case 2:
      GO_sprite_init(self, g.Pushable_SPR1) // graphic height 45 (spr_Statue_4b)
      break
    case 3:
      GO_sprite_init(self, g.Pushable_SPR2) // graphic height 48 (spr_Statue_4d)
      break
  }
  let _pi = G.PI_BGR4
  if (self.dk_spawn !== undefined) {
    const _val = val(g.dm_spawn.get(self.dk_spawn + STR_pal_idx), -1) as number
    if (_val) _pi = _val
  }
  GO_init_palidx(self, _pi)
  // Guarantee Pushable always has same color
  const _PAL = build_pal(0xfcd4c4, 0x646464, p.C_BLK1, p.C_BLK1, -2, -2, -2, -2)
  const _LEN = _PAL.length
  change_pal(strReplaceAt(p.pal_rm_new, get_pal_pos(self.palidx + 1) - _LEN, _LEN, _PAL))
  self.spawn_xl = (self.spawn_xl >> 3) << 3
  set_xlyt(self, self.spawn_xl, self.spawn_yt)
  if (self.dk_spawn !== undefined) {
    // Remember last xy
    let _XL = f.dm_quests.get(`${self.dk_spawn}_XL`) as number | undefined
    const _YT = f.dm_quests.get(`${self.dk_spawn}_YT`) as number | undefined
    if (_XL !== undefined && _YT !== undefined) {
      // This also makes sure the data is aligned with grid.
      _XL = (_XL >> 3) << 3
      f.dm_quests.set(`${self.dk_spawn}_XL`, _XL)
      f.dm_quests.set(`${self.dk_spawn}_YT`, _YT)
      set_xlyt(self, _XL, _YT)
    }
    f.dm_quests.set(self.dk_spawn + STR_Rm, g.rm_name)
    f.dm_quests.set(`${self.dk_spawn}_XL`, self.xl)
    f.dm_quests.set(`${self.dk_spawn}_YT`, self.yt)
  }
  self.Y_DESPAWN = cam_yb_max() + (0x3 << 3)
  if (self.ver === 2 && self.yt >= self.Y_DESPAWN) {
    self.destroy()
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  switch (self.hh >> 3) {
    case 0x04:
      self.CS_OFF_IDX = 0x08
      break
    case 0x05:
      self.CS_OFF_IDX = 0x18
      break
    case 0x06:
      self.CS_OFF_IDX = 0x17
      break
  }
  self.cs_off_idx = self.CS_OFF_IDX
  self.facing_dir = 1
  self.BodyHB_w = self.ww
  self.BodyHB_h = self.hh
  self.BodyHB_xoff = -self.sprite_index_xoff
  self.BodyHB_yoff = -self.sprite_index_yoff
  if (
    isVal(
      self.sprite_index,
      'spr_Statue_4a',
      'spr_Statue_4b',
      'spr_Statue_5a',
      'spr_Statue_5b',
      'spr_Statue_7a',
      'spr_Statue_8a',
    )
  ) {
    // because graphic is shorter than image
    if (self.sprite_index === 'spr_Statue_5a') self.BodyHB_yoff += 1
    else self.BodyHB_yoff += 3
  }
  self.solid_type = TID_SOLID1
  add_to_solid_inst_list(self)
  self.vspd_grav = 4
  self.VSPD_MAX = 0x70
  self.TERMINAL_VELOCITY = 0x70
  self.PUSH_DUR = 0x16
  self.push_counter = 0
  self.moving_dir = 0
  self.MOVE_DIST1 = 0x10
  self.HSPD1 = 0x08
  self.home_xl = self.xl
}

/** `Pushable_update()` */
export function Pushable_update(self: PushA): void {
  if (self.state !== self.state_NORMAL) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const P = pc()
  switch (self.ver) {
    case 2:
      if (self.dk_spawn !== undefined) {
        f.dm_quests.set(`${self.dk_spawn}_XL`, (self.xl >> 3) << 3)
        f.dm_quests.set(`${self.dk_spawn}_YT`, self.yt)
      }
      if (self.yt >= self.Y_DESPAWN) self.destroy()
      break
    case 3:
      if (self.dk_spawn !== undefined) {
        f.dm_quests.set(`${self.dk_spawn}_XL`, (self.xl >> 3) << 3)
        f.dm_quests.set(`${self.dk_spawn}_YT`, self.yt)
      }
      break
  }
  update_EF11(self)
  self.can_draw_self = true
  GO_update_cam_vars(self)
  GO_update_cs(self)
  update_body_hb_3a(self) // uses x, instead of xx, to calculate bodyX & bodyY.
  if (self.moving_dir) self.push_counter = 0
  self.hspd = 0
  if (self.ver === 3 && self.dk_spawn !== undefined) {
    if (
      !rectInRect(self.xl, self.yt, self.ww, self.hh, 0, 0, g.rm_w, g.rm_h) ||
      !rectInRect(self.xl, self.yt, self.ww, self.hh, viewXL(), viewYT(), viewW(), viewH())
    ) {
      const _EXIT = collideRect(self.xl, self.yt, self.ww, self.hh, world.instancesOf(Exit)) as Exit | null
      if (
        _EXIT &&
        _EXIT.open &&
        (_EXIT.exit_type & g.EXIT_TYPE_STANDARD) === g.EXIT_TYPE_STANDARD &&
        (_EXIT.exitNum >> 4) & 0xf
      ) {
        if (!((_EXIT.exitNum >> 4) & 0x8) || self.moving_dir & 0x8) {
          if ((_EXIT.exitNum >> 4) & 0x4) {
            // DOWN Exit
            f.dm_quests.set(self.dk_spawn + STR_Rm, _EXIT.goToRoom as string)
            // TODO(ZALiA): If new room is not aligned with old room in the dungeon layout, xl needs to be adjusted
            f.dm_quests.set(`${self.dk_spawn}_XL`, (self.xl >> 3) << 3)
            f.dm_quests.set(`${self.dk_spawn}_YT`, -self.hh)
            g.dm_spawn.set(`${self.dk_spawn}_Spawn_Permission`, 1)
            self.destroy()
            return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
          }
        }
      }
    }
  }
  // --------------------------------------------------------------------------------
  if (!(self.cs & 0x4) && !(self.x & 0x7) && self.moving_dir !== 0x4) self.moving_dir = 0x4 // $4: DOWN
  if (self.moving_dir === 0x4) {
    // if moving down/falling
    self.vspd = Math.min(abs8b(self.vspd), self.VSPD_MAX) * byte_dir(self.vspd)
    self.vspd &= 0xff
    updateY(self)
    GO_update_cs(self)
    if (self.cs & 0x4) {
      if (self.cs_btm_inst)
        destroy_Pushable(self, true) // if landed on another Pushable
      else solid_clip_correction(self, false)
      self.moving_dir = 0
      self.vspd = 0
      self.home_xl = self.xl
      aud_play_sound(get_audio_theme_track(dk_BlockBreak))
    } else {
      update_body_hb_3a(self) // uses x, instead of xl, to calculate BodyHB_xl & BodyHB_yt.
      for (const e of world.instancesOf(Enemy)) {
        // Falling on an enemy kills them
        update_body_hb_1a(e)
        if (
          Math.max(e.yb - 8, e.y) >= self.yb &&
          e.state === e.state_NORMAL &&
          !e.stun_timer &&
          e.hp &&
          body_collide_body(self, [e])
        ) {
          damage_gob(e, e.hp, false)
        }
      }
      if (self.yb < P.csLft2Y) {
        const _DIST = 2
        if (
          rectInRect(
            self.BodyHB_xl + _DIST,
            self.BodyHB_yt + _DIST,
            self.BodyHB_w - (_DIST << 1),
            self.BodyHB_h - (_DIST << 1),
            P.csLft1X,
            P.csLft1Y,
            P.csRgt1X - P.csLft1X,
            P.csLft2Y - P.csLft1Y,
          )
        ) {
          // Falling on pc
          destroy_Pushable(self, true)
          aud_play_sound(get_audio_theme_track(dk_BlockBreak))
          enemy_collide_pc_body(self)
        }
      }
    }
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // --------------------------------------------------------------------------------
  if (!(self.x & 0x7) && self.moving_dir & 0x3) {
    // 0: NOT moving, 1: right, 2: left, 4: down, 8: up
    let _C1: number | boolean = self.cs & (self.moving_dir & 0x3)
    if (!_C1) {
      const _X = self.x + (self.ww_ + 1) * bit_dir(self.moving_dir)
      for (let _i = (self.hh >> 3) - 1; _i >= 0; _i--) {
        const _y = self.yt + (_i << 3) + 4
        if (collide_solid_inst(_X, _y) || collide_solid_grid(_X, _y)) {
          _C1 = 1
          break
        }
      }
    }
    if (_C1) {
      self.moving_dir = 0
      self.home_xl = self.xl
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
  }
  if (self.moving_dir & 0x3) {
    self.hspd = (self.HSPD1 * bit_dir(self.moving_dir)) & 0xff
    const _X_PREV = self.x
    updateX(self)
    aud_play_fire(true)
    if (!audio_is_playing(get_audio_theme_track(dk_ElevatorMove)))
      aud_play_sound(get_audio_theme_track(dk_ElevatorMove))
    const _DIFF = self.x - _X_PREV // positive if moved right, negative if moved left
    if (_DIFF !== 0) {
      let _push_pc_dir = 0
      // RGT & LFT
      let _COLLIDE_RGT: unknown = 0
      let _COLLIDE_LFT: unknown = 0
      if (self.moving_dir & 0x2) {
        // Pushable is moving LFT
        _COLLIDE_RGT =
          collideRect(P.csRgt1X, P.csRgt1Y, 1, 1, [self]) || collideRect(P.csRgt2X, P.csRgt2Y, 1, 1, [self])
      } else {
        // Pushable is moving RGT
        _COLLIDE_LFT =
          collideRect(P.csLft1X, P.csLft1Y, 1, 1, [self]) || collideRect(P.csLft2X, P.csLft2Y, 1, 1, [self])
      }
      if (_COLLIDE_RGT || _COLLIDE_LFT) _push_pc_dir = self.moving_dir
      // BTM.  Check if PC is on top of this.
      if (!_push_pc_dir && P.cs & 0x4 && !(P.cs & self.moving_dir)) {
        if (
          collideRect(P.csBtm1X, P.csBtm1Y, 1, 1, [self]) ||
          collideRect(P.csBtm2X, P.csBtm2Y, 1, 1, [self])
        )
          _push_pc_dir = self.moving_dir
      }
      if (_push_pc_dir) {
        set_xy(P, P.x + _DIFF, P.y) // move PC
        P.x_change += _DIFF
      }
    }
    if (Math.abs(self.xl - self.home_xl) >= self.MOVE_DIST1) {
      self.moving_dir = 0
      self.home_xl = self.xl
    }
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // --------------------------------------------------------------------------------
  let _qual = -1
  if (
    self.cs & 0x4 && // is on ground
    !self.moving_dir && // is NOT moving
    f.items & ITM_BRAC && // Have Power Bracelet
    !gmBool(P.ogr) && // PC is on ground
    !input.Down_held && // Down NOT held
    input.heldH // 1: Right OR 2: Left held
  ) {
    let _colliding_sides = 0
    const side = (pts: [number, number, number, number], edgeX: number, bit: number, pcOk: boolean) => {
      if (!pcOk) return
      const _C1 = collideRect(pts[0], pts[1], 1, 1, [self])
      const _C2 = collideRect(pts[2], pts[3], 1, 1, [self])
      if (_C1 || _C2) {
        if (
          (_C1 || !(collide_solid_grid(pts[0], pts[1]) & TID_SOLID1)) &&
          (_C2 || !(collide_solid_grid(pts[2], pts[3]) & TID_SOLID1))
        ) {
          for (let _i = (self.hh >> 3) - 1; _i >= 0; _i--) {
            const _y = self.yt + (_i << 3) + 4
            if (collide_solid_grid(edgeX, _y) || collide_solid_inst(edgeX, _y)) {
              _colliding_sides |= bit
              break
            }
          }
          if (!(_colliding_sides & bit)) _qual = 1
        }
      }
    }
    if (input.Right_held) side([P.csRgt1X, P.csRgt1Y, P.csRgt2X, P.csRgt2Y], self.xr + 1, 0x1, P.x <= self.x)
    else if (input.Left_held)
      side([P.csLft1X, P.csLft1Y, P.csLft2X, P.csLft2Y], self.xl - 1, 0x2, P.x >= self.x)
  }
  self.push_counter = Math.max(0, self.push_counter + _qual)
  if (self.push_counter >= self.PUSH_DUR) {
    self.push_counter = 0
    self.moving_dir = input.heldH
  }
}

/** `destroy_Pushable(id, reset to original spawn)` */
export function destroy_Pushable(inst: PushA, resetToOriginalSpawn = false): void {
  if (resetToOriginalSpawn && inst.dk_spawn !== undefined) {
    f.dm_quests.set(
      inst.dk_spawn + STR_Rm,
      val(g.dm_spawn.get(inst.dk_spawn + STR_Rm + STR_Name), g.rm_name) as string,
    )
    f.dm_quests.set(
      `${inst.dk_spawn}_XL`,
      val(g.dm_spawn.get(`${inst.dk_spawn}_x`), (inst.xl >> 3) << 3) as number,
    )
    f.dm_quests.set(
      `${inst.dk_spawn}_YT`,
      val(g.dm_spawn.get(`${inst.dk_spawn}_y`), (inst.yt >> 3) << 3) as number,
    )
  }
  inst.moving_dir = 0
  inst.vspd = 0
  inst.stun_timer = inst.STUN_DURATION1 // $30
  aud_play_sound(get_audio_theme_track(dk_EnemyDeath))
  inst.timer = inst.explosion_DURATION1 // $25: 0.617s
  inst.state = inst.state_EXPLODE // Explode
}

/** `PushableRefresher_init1()` */
export function PushableRefresher_init1(self: PushableRefresher): void {
  GO_depth_init(self, DEPTH_BG1)
  self.scr_step = GameObjectB_step2 as never
  self.sub_state = self.sub_state_IDLE
}

/** `PushableRefresher_init2()` */
export function PushableRefresher_init2(self: PushableRefresher): void {
  GO_sprite_init(self, 'spr_PillarHead01a')
  let _PI = G.PI_BGR1
  if (self.dk_spawn !== undefined) _PI = val(g.dm_spawn.get(self.dk_spawn + STR_pal_idx), _PI) as number
  GO_init_palidx(self, _PI)
  self.DURATION1 = 0x20
  self.DURATION2 = 0x100 - self.DURATION1
  self.Pushable_inst = NOONE
  self.Pushable_SPAWN_DATAKEY = undefined
  if (self.dk_spawn !== undefined) {
    const _DATAKEY = `PushA${dk_SpawnDatakey}`
    for (let _i = 1; _i < 0x10; _i++) {
      const _val = g.dm_spawn.get(self.dk_spawn + STR_Data + hexStr(_i))
      if (typeof _val === 'string' && _val.includes(_DATAKEY)) {
        self.Pushable_SPAWN_DATAKEY = _val.substring(_DATAKEY.length)
        break
      }
    }
  }
  for (let _i = (self.hh >> 3) - 1; _i >= 0; _i--)
    for (let _j = (self.ww >> 3) - 1; _j >= 0; _j--)
      tile_change_1a(0, self.xl + (_j << 3), self.yt + (_i << 3), -1, 0, TID_SOLID1)
}

/** `PushableRefresher_update()` */
export function PushableRefresher_update(self: PushableRefresher): void {
  switch (self.sub_state) {
    case self.sub_state_IDLE: {
      if (self.timer) break
      self.Pushable_inst = NOONE
      GOB_body_collide_pc_sword(self)
      if (self.cs & 0x20 /* CS_SW1 */) {
        const dk = self.Pushable_SPAWN_DATAKEY
        if (dk !== undefined) {
          for (const pu of world.instances) {
            if (!pu.exists) continue // GM's `with(Obj)` skips instances destroyed earlier this frame
            const o = pu as GameObject
            if (o.objectName === 'PushA' && o.dk_spawn !== undefined && o.dk_spawn === dk) {
              self.Pushable_inst = o
              destroy_Pushable(o as PushA, true)
              break
            }
          }
          f.dm_quests.set(dk + STR_Rm, val(g.dm_spawn.get(dk + STR_Rm + STR_Name), g.rm_name) as string)
          f.dm_quests.set(`${dk}_XL`, val(g.dm_spawn.get(`${dk}_x`)) as number)
          f.dm_quests.set(`${dk}_YT`, val(g.dm_spawn.get(`${dk}_y`)) as number)
        }
        aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
        self.timer = self.DURATION1 // DURATION1=$20
        self.sub_state = self.sub_state_TRIGGERED
      }
      break
    }
    case self.sub_state_TRIGGERED:
      if (self.timer) break
      self.timer = 0
      self.sub_state = self.sub_state_SPAWNING
      break
    case self.sub_state_SPAWNING: {
      if (self.timer) break
      if (!self.Pushable_inst || !self.Pushable_inst.exists) {
        const dk = self.Pushable_SPAWN_DATAKEY
        if (dk !== undefined) {
          const _XL = 0x17 << 3
          const _YT = viewYT() - sprite_get_height(g.Pushable_SPR2)
          f.dm_quests.set(`${dk}_XL`, _XL)
          f.dm_quests.set(`${dk}_YT`, _YT)
          const _VER = val(g.dm_spawn.get(dk + STR_Version), 0x3) as number
          GameObject_create(_XL, _YT, 'PushA', _VER, dk)
        }
        self.timer = self.DURATION2 // DURATION2=$100-DURATION1
        self.sub_state = self.sub_state_COOLDOWN
      }
      break
    }
    case self.sub_state_COOLDOWN:
      if (self.timer) break
      self.timer = 0
      self.sub_state = self.sub_state_IDLE
      break
  }
}

/** `PushableRefresher_draw()` */
export function PushableRefresher_draw(self: PushableRefresher): void {
  draw_sprite_at(self.depth, self.sprite, 0, self.x, self.y, self.palidx)
  const _YOFF = 4
  switch (self.sub_state) {
    case self.sub_state_IDLE: {
      let _ROT = (g.counter0 >> 1) & 0x3
      _ROT ^= 0x3
      _ROT *= 90
      draw_sprite_rot_at(self.depth, 'spr_Fireball2', 0, self.x, self.y + _YOFF, G.PI_MOB_ORG, 1, 1, _ROT)
      break
    }
    case self.sub_state_TRIGGERED: {
      const _COUNT = 3
      const _DURATION1 = 0x4
      const _DURATION2 = _DURATION1 * _COUNT
      const _CUE = self.DURATION1 - _DURATION2
      const _TIME = self.timer - _CUE
      // `timer` runs past `_CUE`, so `_TIME` goes negative — false in GM (`> 0.5`), truthy in JS.
      if (gmBool(_TIME)) {
        let _SPRITE: string
        if (_TIME <= _DURATION2 - _DURATION1 * 2) _SPRITE = 'spr_pop01_3'
        else if (_TIME <= _DURATION2 - _DURATION1 * 1) _SPRITE = 'spr_pop01_2'
        else _SPRITE = 'spr_pop01_1'
        let _XSCALE = 1
        // GML precedence: `_TIME-1 mod _DURATION1 < _DURATION1>>1` → ((_TIME-1) mod D) < (D>>1)
        if ((_TIME - 1) % _DURATION1 < _DURATION1 >> 1) _XSCALE = -1
        draw_sprite_at(self.depth, _SPRITE, 0, self.x, self.y + _YOFF, G.PI_MOB_ORG, _XSCALE)
      }
      break
    }
    case self.sub_state_SPAWNING:
      break
    case self.sub_state_COOLDOWN: {
      if (self.timer < 0x10) {
        if (self.timer < 0x8 || self.timer & 0x1) {
          const _XSCALE = self.timer < 0x8 ? sign_(self.timer & 0x1) : sign_(self.timer & 0x2)
          draw_sprite_at(self.depth, 'spr_Flame_Small_1a', 0, self.x, self.y + _YOFF, G.PI_MOB_ORG, _XSCALE)
        }
      }
      break
    }
  }
}

/** `PushableRefresher_udp()` — empty in ZALiA; registered because the object data points at it. */
export function PushableRefresher_udp(_self: PushableRefresher): void {}
