export class QuitAppMenu extends Menu {
  override readonly objectName = 'QuitAppMenu'
  /** `<persistent>-1</persistent>` in ZALiA's object definition — survives a room change. */
  override readonly persistent = true
  ANIM_FRAMES_DEF: any = undefined
  CLMS: any = undefined
  PI_MENU1: any = undefined
  ROWS: any = undefined
  RequestQuit_DUR1: any = undefined
  RequestQuit_timer: any = undefined
  TEXT_CONFIRM: any = undefined
  TEXT_WARNING: any = undefined
  anim_frame: any = undefined
  cnt_draw_rows: any = undefined
  cursor_option: any = undefined
  dl_tsrc_data: any = undefined
  gui_state_backup: any = undefined
  sub_state: any = undefined
  sub_state_CLOSING1: any = undefined
  sub_state_CLOSING2: any = undefined
  sub_state_CLOSING3: any = undefined
  sub_state_CLOSING_ANIM: any = undefined
  sub_state_IDLE_CLOSED: any = undefined
  sub_state_OPEN1: any = undefined
  sub_state_OPENING1: any = undefined
  sub_state_OPENING2: any = undefined
  sub_state_OPENING_ANIM: any = undefined
  will_go_to_continuesave: any = undefined
  constructor() {
    super()
    QuitAppMenu_Create(this)
  }
  draw(): void {
    QuitAppMenu_Draw(this)
  }
}

/** GML: QuitAppMenu_Create() */
export function QuitAppMenu_Create(self: QuitAppMenu) {
  let _START_TIME: any, _i: any, _a: any, _count: any, _TSRC_DATA1: any, _TSRC_DATA2: any, _TSRC_DATA3: any

  if (gmb(DEV)) {
    _START_TIME = current_time
  }

  g.QUIT_APP_MENU = self
  self.PI_MENU1 = G.PI_GUI1
  self.gui_state_backup = 0
  _a = 1
  self.sub_state_IDLE_CLOSED = _a++
  self.sub_state_OPENING1 = _a++
  self.sub_state_OPENING2 = _a++
  self.sub_state_OPENING_ANIM = _a++
  self.sub_state_OPEN1 = _a++
  self.sub_state_CLOSING1 = _a++
  self.sub_state_CLOSING2 = _a++
  self.sub_state_CLOSING_ANIM = _a++
  self.sub_state_CLOSING3 = _a++
  self.sub_state = self.sub_state_IDLE_CLOSED
  self.TEXT_CONFIRM = 'GO TO THE CONTINUE-SAVE SCREEN?'
  self.TEXT_WARNING = 'THIS IS CONSIDERED A GAME OVER.'
  /*
TEXT_CONFIRM    = "QUIT TO THE TITLE SCREEN?";
//TEXT_CONFIRM    = "ARE YOU SURE YOU WANT TO QUIT THE APP?";
TEXT_WARNING    = "ANY UNSAVED PROGRESS WILL BE LOST.";
//TEXT_WARNING    = "YOU WILL LOSE ANY UNSAVED PROGRESS.";
//TEXT_METR  = "....." + "....."; // broke in 5's so easy to read/count
*/
  self.cursor_option = 0 // 0: No, 1: Yes
  self.will_go_to_continuesave = false
  self.CLMS = max(string_length(self.TEXT_CONFIRM), string_length(self.TEXT_WARNING))
  self.CLMS += 4
  //CLMS  = g.GUI_WIN_CLMS2; // g.GUI_WIN_CLMS2 = 24
  self.ROWS = 0x0a //
  //ROWS  = g.pm.ROWS_WIN_DEF; // 8p tall
  self.ANIM_FRAMES_DEF = self.ROWS >> 1 // 11
  self.anim_frame = 0
  self.cnt_draw_rows = 0
  self.RequestQuit_DUR1 = 0x40
  self.RequestQuit_timer = 0
  _count = self.CLMS - 2
  // Top & Bottom
  _TSRC_DATA1 = '2' // 2: corner
  _TSRC_DATA1 += string_repeat('0', _count) // 0: bar hor
  _TSRC_DATA1 += '2' // 2: corner
  // Mid
  _TSRC_DATA2 = '1' // 1: bar ver
  _TSRC_DATA2 += string_repeat('&', _count) // &: blank
  _TSRC_DATA2 += '1' // 1: bar ver
  // Hor section bar
  _TSRC_DATA3 = '1' // 1: bar ver
  _TSRC_DATA3 += string_repeat('0', _count) // 0: bar hor
  _TSRC_DATA3 += '1' // 1: bar ver
  //
  self.dl_tsrc_data = ds_list_create()
  for (_i = 0; _i < self.ROWS; _i++) {
    ds_list_add(self.dl_tsrc_data, _TSRC_DATA2) // Mids
  }
  self.dl_tsrc_data.set(0, _TSRC_DATA1) // Top
  self.dl_tsrc_data.set(self.ROWS - 1, _TSRC_DATA1) // Bottom
  if (gmb(DEV)) {
  }
}

/** GML: QuitAppMenu_Draw() */
export function QuitAppMenu_Draw(self: QuitAppMenu) {
  let _i: any,
    _j: any,
    _x: any,
    _y: any,
    _data: any,
    _tsrc: any,
    _ts_x: any,
    _ts_y: any,
    _text: any,
    _XC: any,
    _CURS_X: any

  if (+!gmb(self.cnt_draw_rows)) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // ----------------------------------------------------------------------------------
  // ----------------------------------------------------------------------------------

  // ----------------------------------------------------------------------------------
  // Draw bg color of menu
  draw_sprite_(
    'spr_1x1_WHT',
    0,
    self.drawX,
    self.drawY,
    -1,
    self.CLMS << 3,
    self.cnt_draw_rows << 3,
    background_colour(),
  )
  //draw_gui_frame(ar_tdata, canDrawRows, drawX, drawY);

  // each row
  for (_i = 0; _i < self.cnt_draw_rows; _i++) {
    _data = self.dl_tsrc_data.get(_i)
    // 8x8. each column of the row
    for (_j = string_length(_data) - 1; _j >= 0; _j--) {
      _tsrc = string_char_at(_data, _j + 1)
      if (_tsrc === '0' || _tsrc === '1' || _tsrc === '2') {
        _tsrc = g.dl_MenuFrame_TSRC.get(real(_tsrc))
        _ts_x = ((_tsrc >> 0) & 0x0f) << 3
        _ts_y = ((_tsrc >> 4) & 0x0f) << 3
        _x = self.drawX + (_j << 3)
        _y = self.drawY + (_i << 3)
        draw_background_part(g.TS_MENU, _ts_x, _ts_y, 8, 8, _x, _y)
      }
    }
  }
  // ----------------------------------------------------------------------------------
  if (self.sub_state !== self.sub_state_OPEN1) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }

  _XC = self.drawX + ((self.CLMS << 3) >> 1)
  _CURS_X = _XC - (0x03 << 3)
  pal_swap_set(self.PI_MENU1)
  _text = self.TEXT_CONFIRM
  _x = _XC - ((string_length(_text) << 3) >> 1)
  _y = self.drawY + (0x01 << 3)
  draw_text_(_x, _y, _text)
  _text = self.TEXT_WARNING
  _x = _XC - ((string_length(_text) << 3) >> 1)
  _y += 0x01 << 3
  draw_text_(_x, _y, _text)
  _x = _CURS_X + 0x0c
  _y += (0x01 << 3) + 4
  draw_text_(_x, _y, 'YES')
  draw_text_(_x, _y + 8, 'NO')
  _y += (+!gmb(self.cursor_option) << 3) + 4
  draw_sprite_('spr_arrow_6_rgt', 0, _CURS_X + 4, _y)
  pal_swap_reset()
}

/** GML: update_QuitAppMenu() */
export function update_QuitAppMenu(self: QuitAppMenu) {
  let _qual: any, _val: any, _CONFIRM: any, _CANCEL: any

  const _ret = withOther(g.QUIT_APP_MENU, self, (self: any, _other) => {
    // --------------------------------------------------------------------------------
    switch (self.sub_state) {
      // ---------------------------------------------------------------------------------------------
      case self.sub_state_IDLE_CLOSED: {
        // ---------------------------------------------------------------------------------------------
        self.will_go_to_continuesave = false
        if (gmb(self.timer)) {
          self.timer--
          break
        }
        /*
        if (g.gui_state==g.gui_state_NONE 
        ||  g.gui_state==g.gui_state_PAUSE 
        ||  g.gui_state==g.gui_state_LEVEL_UP 
        ||  g.gui_state==g.gui_state_DIALOGUE1 
        ||  g.gui_state==g.gui_state_DIALOGUE2 
        ||  g.gui_state==g.gui_state_DIALOGUE3 )
        */
        if (g.gui_state !== g.gui_state_QUIT_APP) {
          //||  (g.room_type=="C" && !g.overworld.dest_dist)
          if (
            roomName() === 'rmB_Title' ||
            roomName() === 'rmB_FileSelect' ||
            (g.room_type === 'A' &&
              isVal(
                g.gui_state,
                g.gui_state_NONE,
                g.gui_state_PAUSE,
                g.gui_state_LEVEL_UP,
                g.gui_state_DIALOGUE1,
                g.gui_state_DIALOGUE2,
                g.gui_state_DIALOGUE3,
              ))
          ) {
            _qual = gmb(input.GP_Other5_held) && gmb(input.GP_Other6_held) && gmb(input.GP_Magic_held) // hold RT + hold LT + hold Select
            // toggling fullscreen can happen earlier in the frame, window_get_fullscreen() will not be accurate here
            if (+!gmb(_qual) && keyboard_check_pressed(vk_escape) && +!gmb(g.Fullscreen_toggled)) {
              _qual = true
              //with(PaletteEditor) _qual = state!=state_EDIT1A && state!=state_EDIT1B && state!=state_BGR_COLOR; // exiting these Dev_PalettePicker states gets priority
            }
            if (gmb(_qual)) {
              if (roomName() === 'rmB_Title' || roomName() === 'rmB_FileSelect') {
                //sdm("update_QuitAppMenu() -> case sub_state_IDLE_CLOSED -> game_end()");
                game_end() // Quit app
                return true
              } else {
                QuitAppMenu_trigger_open(self)
              }
            }
          }
          return false
        }
        break
      }
      // ---------------------------------------------------------------------------------------------
      case self.sub_state_OPENING1: {
        // ---------------------------------------------------------------------------------------------
        if (gmb(self.timer)) {
          self.timer--
          break
        }
        aud_play_sound(get_audio_theme_track(dk_OpenGUI))
        self.timer = 2
        self.sub_state = self.sub_state_OPENING_ANIM
        break
      }
      // ---------------------------------------------------------------------------------------------
      case self.sub_state_OPENING_ANIM: {
        // ---------------------------------------------------------------------------------------------
        if (gmb(self.timer)) {
          self.timer--
          break
        }
        QuitAppMenu_udp(self)
        self.anim_frame++
        if (self.anim_frame === self.ANIM_FRAMES_DEF) {
          self.timer = 0
          self.sub_state = self.sub_state_OPEN1
        }
        break
      }
      // ---------------------------------------------------------------------------------------------
      case self.sub_state_OPEN1: {
        // ---------------------------------------------------------------------------------------------
        if (gmb(self.timer)) {
          self.timer--
          break
        }

        QuitAppMenu_udp(self)
        _CONFIRM = input.Pause_pressed
        //var _CONFIRM =(Input.Pause_held && !(Input.heldPrev&Input.S))
        //             || keyboard_check_pressed(vk_enter);
        _CANCEL = gmb(input.Other1_pressed) || keyboard_check_pressed(vk_escape)
        // gp2: xbox 'B'
        if (gmb(_CONFIRM) || gmb(_CANCEL)) {
          if (gmb(_CONFIRM) && gmb(self.cursor_option)) {
            if (roomName() === 'rmB_Title' || roomName() === 'rmB_FileSelect') {
              //sdm("update_QuitAppMenu() -> case sub_state_OPEN1 -> game_end()");
              game_end() // Quit app
            } else {
              self.anim_frame = 0
              self.cnt_draw_rows = 0
              self.cursor_option = 0
              withOther(G.OPTIONS_MENU, self, (self: any, _other) => {
                self.sub_state = self.sub_state_IDLE_CLOSED
              })
              withOther(G.OPTIONS_MENU, self, (self: any, _other) => {
                self.gui_state_backup = 0
              })
              self.gui_state_backup = 0
              g.gui_state = g.gui_state_NONE
              self.timer = 0
              self.sub_state = self.sub_state_IDLE_CLOSED
              G.pc.state = G.pc.state_DEAD
              G.pc.can_draw_self = false
              _val = G.dm_save_file_settings.get(dk_ForceQuitPenalty)
              // If there was no choice made in the rando setup
              // The choice that was made in the rando setup. 1: Normal penalty, 0: No penalty
              //if (getSaved(f.file_num, STR_Rando+"_UP_A"+STR_XP+"_Penalty", true))
              //if(!getSaved(f.file_num, STR_Rando+STR_Active, false)
              //||  getSaved(f.file_num, STR_Rando+"_UP_A"+STR_XP+"_Penalty", true) )
              if (is_undefined(_val) || gmb(_val)) {
                f.xp = round(f.xp * g.mod_Gameover_XP_PENALTY)
                f.xp = clamp(f.xp, 0, XP_MAX)
              }
              f.death_count += f.lives // FIXED: unqualified `lives` — the counter is `f.lives`
              f.lives = 0
              //sdm("update_QuitAppMenu() -> case sub_state_IDLE_CLOSED -> game_end()");
              Audio.mus_rm_body = 0 // Need to do this so ContinueScreen music will play
              self.will_go_to_continuesave = true
              // Seems like the combination of getSaved() and room_goto_() can crash the app so I moved room_goto_(rmB_ContinueSave) to sub_state_CLOSING3
              //room_goto_(rmB_ContinueSave);
            }
            //break;//case sub_state_OPEN1
          }
          self.timer = 0
          self.sub_state = self.sub_state_CLOSING1 // Start close menu
          break //case sub_state_OPEN1
        }
        // 0,1
        if (gmb(abs(bit_dir(gui_tmr_cursor_v()))) || gmb(input.Magic_pressed)) {
          self.cursor_option ^= 0x01
          aud_play_sound(get_audio_theme_track(dk_CursorSpellMenu))
          break //case sub_state_OPEN1
        }
        break
      }
      // ---------------------------------------------------------------------------------------------
      case self.sub_state_CLOSING1: {
        // ---------------------------------------------------------------------------------------------
        if (gmb(self.timer)) {
          self.timer--
          break
        }
        // Closing menu.
        QuitAppMenu_udp(self)
        aud_play_sound(get_audio_theme_track(dk_OpenGUI))
        self.timer = 0
        self.sub_state = self.sub_state_CLOSING_ANIM
        break
      }
      // ---------------------------------------------------------------------------------------------
      case self.sub_state_CLOSING_ANIM: {
        // ---------------------------------------------------------------------------------------------
        if (gmb(self.timer)) {
          self.timer--
          break
        }
        if (gmb(self.anim_frame)) {
          QuitAppMenu_udp(self)
        } else {
          self.timer = 0
          self.sub_state = self.sub_state_CLOSING3
        }
        self.anim_frame--
        break
      }
      // ---------------------------------------------------------------------------------------------
      case self.sub_state_CLOSING3: {
        // ---------------------------------------------------------------------------------------------
        if (gmb(self.timer)) {
          self.timer--
          break
        }
        self.anim_frame = 0
        self.cnt_draw_rows = 0
        self.cursor_option = 0
        g.gui_state = g.gui_state_NONE
        //g.gui_state   = gui_state_backup;
        if (gmb(self.will_go_to_continuesave)) {
          room_goto_('rmB_ContinueSave')
        }
        self.will_go_to_continuesave = false
        self.timer = 0
        self.sub_state = self.sub_state_IDLE_CLOSED
        break
      }
    } //switch(sub_state)
  }) //with(g.QUIT_APP_MENU)
  if (typeof _ret === 'boolean') return _ret // GML: `return true/false` inside the with block
  return true
}

/** GML: QuitAppMenu_udp() */
export function QuitAppMenu_udp(self: QuitAppMenu) {
  self.drawX = viewXC() - ((self.CLMS >> 1) << 3)
  self.drawY = viewYT() + self.Y_BASE
  if (self.anim_frame === self.ANIM_FRAMES_DEF) {
    self.cnt_draw_rows = self.ROWS
  } else {
    self.cnt_draw_rows = self.anim_frame << 1
  }
}

/** GML: QuitAppMenu_trigger_open() */
export function QuitAppMenu_trigger_open(self: QuitAppMenu) {
  self.anim_frame = 0
  self.cnt_draw_rows = 0
  self.gui_state_backup = g.gui_state
  g.gui_state = g.gui_state_QUIT_APP
  self.timer = 0
  self.sub_state = self.sub_state_OPENING1
}
