/** Challenge_IntermittentPlatformSequence: timed appearing/disappearing rock platforms (4 layouts). */
import {
  dk_BlockBreak,
  dk_BridgeCrumble,
  PAGE_ROWS,
  STR_Data,
  STR_HIDDEN,
  STR_View,
  TID_HIDE_1,
  TID_SOLID1,
} from '@z2/data'
import { gmBool, isVal } from '../../../nes/math8'
import { DsGrid } from '../../../runtime/ds'
import { cam_xl_min, cam_xr_max, viewH } from '../../collision/env'
import { rectInRect, rectInView } from '../../collision/geometry'
import { str_hex } from '../../other/index'
import { rm_pal_qual_lit } from '../../palette/roomStart'
import { draw_sprite_ } from '../../rooms/draw'
import { aud_play_sound } from '../../sound/play'
import { get_audio_theme_track } from '../../sound/theme'
import { GG, gp, pc, pp } from '../pending'
import type { Challenge_IntermittentPlatformSequence } from './classes'

type IPS = Challenge_IntermittentPlatformSequence

/** [clm, row, clms, rows] per platform */
type Layout = [number, number, number, number][]

function setPlatforms(self: IPS, layout: Layout): void {
  self.PLATFORMS = layout.length
  self.dg_platform = new DsGrid<number>(self.PLATFORMS, 7, 0)
  layout.forEach(([clm, row, clms, rows], i) => {
    self.dg_platform.set(i, 0, self.State_SLEEP)
    self.dg_platform.set(i, 1, i === 0 ? self.DUR_START : 0)
    self.dg_platform.set(i, 2, clm)
    self.dg_platform.set(i, 3, row)
    self.dg_platform.set(i, 4, clms)
    self.dg_platform.set(i, 5, rows)
  })
}
function setRestart(self: IPS, x0: number, w0: number, w1End: number, h: number): void {
  self.dg_restart = new DsGrid<number>(2, 5, 0)
  const last = self.dg_platform.width - 1
  // dg_restart[#0 is anywhere left of first platform
  self.dg_restart.set(0, 0, 1) // sequence dir
  self.dg_restart.set(0, 1, x0)
  self.dg_restart.set(0, 2, 0)
  self.dg_restart.set(0, 3, ((self.dg_platform.get(0, 2) as number) << 3) - x0 + (w0 - w0))
  self.dg_restart.set(0, 4, h)
  // dg_restart[#1 is anywhere right of last platform
  const x1 =
    ((self.dg_platform.get(last, 2) as number) << 3) + ((self.dg_platform.get(last, 4) as number) << 3)
  self.dg_restart.set(1, 0, -1)
  self.dg_restart.set(1, 1, x1)
  self.dg_restart.set(1, 2, 0)
  self.dg_restart.set(1, 3, w1End - x1)
  self.dg_restart.set(1, 4, h)
}

export function Challenge_IntermittentPlatformSequence_init(self: IPS): void {
  self.palidx = GG().PI_BGR1
  self.State_SLEEP = 1 // not solid, no graphic
  self.State_TELL = 2 // not solid, appear tell/hint graphic
  self.State_ANIM_IN = 3 // not solid, animation in
  self.State_ANIM_OUT = 4 //     solid, animation out
  self.State_FULL = 5 //     solid, static graphic
  self.TELL_COLOR = 0xff0000 // Color for dev
  // _CASE 3 timings
  self.DUR_TELL = 0x18
  self.DUR_ANIM = 0x18 // For State_ANIM_IN, State_ANIM_OUT
  self.DUR_FULL = 0x90
  self.DUR_START = 0x80 // Restart delay
  self.DUR_SLEEP = 0xff
  self.SPR_PLAT_1A = 'spr_Platform_Rock_01a'
  self.SPR_PLAT_1B = 'spr_Platform_Rock_01b'
  self.SPR_PLAT_1C = 'spr_Platform_Rock_01c'
  self.HIDDEN_TYPE = 0
  if (self.dk_spawn !== undefined) {
    const _val = String(gp().dm_spawn.val(`${self.dk_spawn + STR_Data}01`))
    const _pos = _val.indexOf(STR_HIDDEN)
    if (_pos >= 0) self.HIDDEN_TYPE = str_hex(_val.substr(_pos + STR_HIDDEN.length, 2))
  }
  gp().dg_RmTile_TempSolid = new DsGrid<number>(GG().dg_solid_w, GG().dg_solid_h, 0)
  self.seq_dir = 1
  self.dg_restart = new DsGrid<number>(0, 5, 0)
  self.PLATFORMS = 1
  self.dg_platform = new DsGrid<number>(self.PLATFORMS, 7, 0)
  const rmH = gp().rm_h
  const rmW = gp().rm_w
  switch (self.ver) {
    case 1: {
      // 1st test
      setPlatforms(self, [
        [0x1e, 0x18, 2, 2],
        [0x26, 0x18, 2, 2],
        [0x2c, 0x18, 2, 2],
        [0x34, 0x18, 2, 2],
        [0x3c, 0x16, 2, 2],
        [0x3e, 0x12, 2, 2],
        [0x46, 0x11, 2, 2],
        [0x49, 0x18, 2, 2],
        [0x51, 0x18, 2, 2],
        [0x54, 0x17, 2, 2],
        [0x5a, 0x14, 2, 2],
        [0x64, 0x18, 2, 2],
      ])
      setRestart(self, cam_xl_min(), 0, cam_xr_max(), rmH)
      break
    }
    case 2: {
      // Tantari desert cave 1 (TROPHY cave 1)
      setPlatforms(self, [
        [0x2c, 0x0f, 2, 2],
        [0x2f, 0x13, 2, 2],
        [0x33, 0x17, 2, 2],
        [0x37, 0x14, 2, 2],
        [0x3a, 0x10, 2, 2],
        [0x3e, 0x14, 4, 2],
        [0x44, 0x18, 4, 2],
        [0x4a, 0x18, 2, 2],
        [0x50, 0x14, 4, 2],
      ])
      setRestart(self, 0, 0, rmW, rmH)
      break
    }
    case 3: {
      // EastA_B1,  Caves to Mount Dragmire
      setPlatforms(self, [
        [0x1c, 0x14, 4, 2],
        [0x24, 0x14, 2, 2],
        [0x28, 0x14, 2, 2],
        [0x30, 0x10, 2, 2],
        [0x35, 0x10, 2, 2],
        [0x3d, 0x0c, 2, 2],
        [0x42, 0x08, 2, 2],
        [0x46, 0x03, 2, 2],
        [0x4d, 0x07, 2, 2],
        [0x50, 0x0c, 2, 2],
        [0x53, 0x11, 2, 2],
      ])
      setRestart(self, 0, 0, rmW, rmH)
      break
    }
    case 4: {
      self.DUR_FULL = 0x40
      const _CLM = 0x12
      const _CLMS1 = 0x04 // clms to next platform
      const _ROW = gp().rm_rows - PAGE_ROWS + 0x10
      let _clm = _CLM
      const layout: Layout = []
      const add = (clms: number) => {
        layout.push([_clm, _ROW, clms, 2])
        _clm += _CLMS1
      }
      add(2)
      add(2)
      add(2)
      _clm += _CLMS1 // gap
      add(2)
      add(2)
      add(2)
      add(4)
      add(2)
      setPlatforms(self, layout)
      setRestart(self, 0, 0, rmW, viewH())
      break
    }
  }
  if ((gp().dm_rm.val(gp().rm_name + STR_View + STR_Data) as number) & 0x1 && gmBool(gp().rm_row0)) {
    // if rm is locked to bottom page
    for (let _i = 0; _i < self.PLATFORMS; _i++)
      self.dg_platform.set(_i, 3, (self.dg_platform.get(_i, 3) as number) + gp().rm_row0)
  }
}

function setSolid(self: IPS, _idx: number, value: number): void {
  const _CLM = self.dg_platform.get(_idx, 2) as number
  const _ROW = self.dg_platform.get(_idx, 3) as number
  const _CLMS = self.dg_platform.get(_idx, 4) as number
  const _ROWS = self.dg_platform.get(_idx, 5) as number
  for (let _j = _CLMS * _ROWS - 1; _j >= 0; _j--) {
    const _clm = _CLM + (_j % _CLMS)
    const _row = _ROW + Math.trunc(_j / _CLMS)
    GG().dg_solid.set(_clm, _row, value)
    self.dg_platform.set(_idx, 6, value) // 6: SOLID state
    gp().dg_RmTile_TempSolid.set(_clm, _row, value) // tells Rescue Fairy to not use these solid tiles
  }
}
function platInView(self: IPS, _idx: number): boolean {
  return rectInView(
    (self.dg_platform.get(_idx, 2) as number) << 3,
    (self.dg_platform.get(_idx, 3) as number) << 3,
    (self.dg_platform.get(_idx, 4) as number) << 3,
    (self.dg_platform.get(_idx, 5) as number) << 3,
  )
}

export function Challenge_IntermittentPlatformSequence_update(self: IPS): void {
  const player = pc()
  const dp = self.dg_platform
  for (let _i = self.dg_restart.width - 1; _i >= 0; _i--) {
    const _x = self.dg_restart.get(_i, 1) as number
    const _y = self.dg_restart.get(_i, 2) as number
    const _w = self.dg_restart.get(_i, 3) as number
    const _h = self.dg_restart.get(_i, 4) as number
    if (
      rectInRect(_x, _y, _w, _h, player.BodyHB_xl, player.BodyHB_yt, player.BodyHB_w, player.BodyHB_h) &&
      self.seq_dir !== self.dg_restart.get(_i, 0)
    ) {
      let _ready = true
      for (let _j = self.PLATFORMS - 1; _j >= 0; _j--) {
        if (dp.get(_j, 0) === self.State_SLEEP) continue
        if (!platInView(self, _j)) {
          // Set any platforms off screen to State_SLEEP so they don't activate others.
          dp.set(_j, 0, self.State_SLEEP)
          dp.set(_j, 1, 0)
        } else _ready = false // This platform is on screen and is not finished.
      }
      if (!_ready) break // Platform(s) are on screen and not finished.
      // All platforms on screen have finished.
      self.seq_dir = self.dg_restart.get(_i, 0) as number
      // FIDELITY: ZALiA tests `if (seq_dir)` which is only false for 0, so the backward (-1) restart
      // still armed platform 0 instead of the last one; intent (per the dg_restart comments) is "first
      // platform in sequence order".
      const _idx = self.seq_dir > 0 ? 0 : self.PLATFORMS - 1
      if (!gmBool(dp.get(_idx, 1)) || (dp.get(_idx, 1) as number) > self.DUR_START)
        dp.set(_idx, 1, self.DUR_START)
      break
    }
  }
  // ------------------------------------------------------------------------------------------------
  for (let _i = 0; _i < self.PLATFORMS; _i++) {
    const _idx = self.seq_dir > 0 ? _i : self.PLATFORMS - 1 - _i
    if (gmBool(dp.get(_idx, 1))) dp.set(_idx, 1, (dp.get(_idx, 1) as number) - 1) // timer
    switch (dp.get(_idx, 0)) {
      case self.State_SLEEP: {
        dp.set(_idx, 6, 0) // 6: SOLID state
        if (!_i) {
          // Only 1st platform wakes up by timer.
          if (!gmBool(dp.get(_idx, 1))) {
            dp.set(_idx, 0, self.State_TELL)
            dp.set(_idx, 1, self.DUR_TELL)
          }
        } else {
          const prev = _idx + -self.seq_dir
          if (
            dp.get(prev, 0) === self.State_FULL &&
            (dp.get(prev, 1) as number) <= 0x20 + (self.DUR_TELL + self.DUR_ANIM)
          ) {
            dp.set(_idx, 0, self.State_TELL)
            dp.set(_idx, 1, self.DUR_TELL)
          }
        }
        break
      }
      case self.State_TELL: {
        if (!gmBool(dp.get(_idx, 1))) {
          dp.set(_idx, 0, self.State_ANIM_IN)
          dp.set(_idx, 1, self.DUR_ANIM)
        }
        break
      }
      case self.State_ANIM_IN: {
        if (!gmBool(dp.get(_idx, 1))) {
          setSolid(self, _idx, TID_SOLID1)
          if (platInView(self, _idx)) aud_play_sound(get_audio_theme_track(dk_BlockBreak))
          dp.set(_idx, 0, self.State_FULL)
          dp.set(_idx, 1, self.DUR_FULL)
        }
        break
      }
      case self.State_FULL: {
        dp.set(_idx, 6, TID_SOLID1) // 6: SOLID state
        if (!gmBool(dp.get(_idx, 1))) {
          if (platInView(self, _idx)) aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
          dp.set(_idx, 0, self.State_ANIM_OUT)
          dp.set(_idx, 1, self.DUR_ANIM)
        }
        break
      }
      case self.State_ANIM_OUT: {
        if (!gmBool(dp.get(_idx, 1))) {
          setSolid(self, _idx, 0)
          dp.set(_idx, 0, self.State_SLEEP)
          dp.set(_idx, 1, self.DUR_SLEEP * (!_i ? 1 : 0)) // Only 1st platform wakes up by timer.
        }
        break
      }
    }
  }
}

export function Challenge_IntermittentPlatformSequence_draw(self: IPS): void {
  if (!gmBool(gp().rm_brightness) && self.HIDDEN_TYPE === (TID_HIDE_1 & 0xf)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const _pi = rm_pal_qual_lit() ? self.palidx + pp().PI_LIT1 : self.palidx + pp().PI_DRK1
  const dp = self.dg_platform
  for (let _i = 0; _i < self.PLATFORMS; _i++) {
    const _x = (dp.get(_i, 2) as number) << 3
    const _y = (dp.get(_i, 3) as number) << 3
    const _w = (dp.get(_i, 4) as number) << 3
    const _h = (dp.get(_i, 5) as number) << 3
    if (!rectInView(_x, _y, _w, _h)) continue
    const t = dp.get(_i, 1) as number
    let _spr: string | 0 = 0
    switch (dp.get(_i, 0)) {
      case self.State_SLEEP:
        break
      case self.State_TELL:
        if (!(t & 0x04)) break
        _spr = isVal(t, 5, 6) ? self.SPR_PLAT_1B : self.SPR_PLAT_1C
        _spr = 0 // (drawSprite is commented out in ZALiA — the tell is silent)
        break
      case self.State_ANIM_IN:
        if (t < 12) _spr = self.SPR_PLAT_1C
        if (t < 9) _spr = self.SPR_PLAT_1B
        if (t < 4) _spr = self.SPR_PLAT_1A // 1A: Full
        break
      case self.State_FULL:
        _spr = t >= 0x40 || t & 0x08 ? self.SPR_PLAT_1A : self.SPR_PLAT_1B
        break
      case self.State_ANIM_OUT:
        if (t > self.DUR_ANIM - 14) _spr = self.SPR_PLAT_1C
        if (t > self.DUR_ANIM - 12) _spr = self.SPR_PLAT_1B
        if (t > self.DUR_ANIM - 6) _spr = self.SPR_PLAT_1A
        break
    }
    if (_spr) {
      const _count = (dp.get(_i, 4) as number) >> 1
      for (let _j = 0; _j < _count; _j++) draw_sprite_(_spr, 0, _x + (_j << 4), _y, _pi)
    }
  }
}

export function Challenge_IntermittentPlatformSequence_end(self: IPS): void {
  self.dg_platform = new DsGrid<number>(0, 7, 0)
  self.dg_restart = new DsGrid<number>(0, 5, 0)
}
