/** `PC_update_attack_1()` — 95DC. Start attack. */
export function PC_update_attack_1(self: Lonk): void {
  const _C1 = gmBool(g.mod_StabFrenzy) && self.StabFrenzy_charge_counter > 0x80 && gmBool(input.Attack_held)
  if (!input.Attack_pressed && !_C1) return
  if ((!pcInput.dHeld && g.pc_lock & PC_LOCK_ATK1) || (pcInput.dHeld && g.pc_lock & PC_LOCK_ATK2)) return // $10/$20 lock stab
  // ------------------------------------------------------------------
  if (!self.ogr && !g.control1_timer && !_C1) {
    // if(!_C1): allows retention of some momentum during stab frenzy
    self.hspd = 0
  }
  if (self.Disguise_enabled) return
  const _PHASE0 = self.attack_phase === 0 // not attacking
  const _PHASE4 = self.attack_phase === 4 // 4: drawback after stab
  if (_PHASE0 || _PHASE4) {
    const _C2 = _PHASE0 || (_PHASE4 && self.attack_timer < self.attack_phase_DURATION2 - 1) // $20
    if (input.Attack_pressed || (_C1 && _C2)) {
      if (_PHASE4 || pcInput.dHeld || self.Cucco_crouching_state === 2) {
        // Going strait to stab instead of draw.
        aud_play_sound(get_audio_theme_track(STR_Stab))
      }
      self.attack_phase = 1 + (_PHASE4 ? 1 : 0) // Result 1 or 2
      self.attack_timer = self.attack_phase_DURATION1 // $06
      // Cucco_crouching_state==2:  Cucco crouch forced bc in 1 tile high passage.
      self.stab_type = !pcInput.dHeld && self.Cucco_crouching_state !== 2 ? 1 : 0 // 0(stab low) or 1(stab high)
      if (_C1) self.StabFrenzy_charge_counter--
    }
  }
}

/** `PC_update_attack_2()` — 9387 JSR: 9483 */
export function PC_update_attack_2(self: Lonk): void {
  if (!self.attack_phase) return
  if (self.attack_timer) {
    if (self.stab_type === 1) {
      // 1: STAND STAB
      switch (self.attack_phase) {
        case 1:
          PC_set_behavior(self.behavior_DRAWBACK)
          break
        case 2:
          PC_set_behavior(self.behavior_STAB_STAND)
          break
        case 3:
          PC_set_behavior(self.behavior_IDLE)
          break
        case 4:
          PC_set_behavior(self.behavior_DRAWBACK)
          break
      }
    } else {
      // 0: CROUCH STAB
      switch (self.attack_phase) {
        case 1:
          PC_set_behavior(self.behavior_STAB_CROUCH)
          break
        case 2:
          PC_set_behavior(self.behavior_CROUCH)
          break
      }
    }
  } else {
    // 949E
    if (
      (self.stab_type === 1 && self.attack_phase === 4) ||
      (self.stab_type === 0 && self.attack_phase === 2)
    ) {
      // 9486
      self.attack_phase = 0
      if (!self.ogr) self.hspd = 0
    } else {
      self.attack_phase++
      if (self.attack_phase === 4)
        self.attack_timer = self.attack_phase_DURATION2 // $20. for phase 4
      else self.attack_timer = self.attack_phase_DURATION1 // $06. for phases other than 4
      if (self.stab_type === 1 && self.attack_phase === 2) {
        // 94B3: JMP 960B
        aud_play_sound(get_audio_theme_track(STR_Stab))
      }
    }
  }
}

/** `PC_update_stab_frenzy_1()` */
export function PC_update_stab_frenzy_1(self: Lonk): void {
  if (!input.Attack_held) {
    self.StabFrenzy_charge_counter = 0
    return
  }
  if (f.items & ITM_SWRD && !(g.pc_lock & PC_LOCK_CSTB)) {
    if (self.StabFrenzy_charge_counter < self.StabFrenzy_charge_counter_DURATION) {
      self.StabFrenzy_charge_counter++
      return
    }
    if (self.StabFrenzy_charge_counter === self.StabFrenzy_charge_counter_DURATION) {
      // Only on this frame
      if (self.attack_phase === 0 || self.attack_phase === 4) {
        // attack_phase_DURATION1: $06 (num of frenzy stabs)
        self.StabFrenzy_charge_counter = 0x80 + self.attack_phase_DURATION1
      }
    }
  }
}

/**
 * `PC_update_SwordHB_xy()` — EC7F. Users: PC, ShadowBoss. Sets `attack_bits` (PC only) and the sword base
 * position used by `PC_update_sword_hb` next frame.
 */
// FIXED: `BIT_ATK1..4` are project macros (`$01..$08`), not instance fields. They were declared on
// `Lonk`, but `PC_update_SwordHB_xy` also runs on ShadowLonk01 (`ShadowBoss_udp.gml:31`), where the
// reads were `undefined` — `_bits` stayed 0 and Shadow Link's sword could never hit or be parried.
export function PC_update_SwordHB_xy(self: Lonk): void {
  // EC19
  self.SwordHB_collidable = false
  const P = pc()
  let _bits = 0
  if (self.behavior === P.behavior_STAB_STAND) _bits |= BIT_ATK1 // $01. high stab
  if (self.behavior === P.behavior_STAB_CROUCH) _bits |= BIT_ATK2 // $02. low  stab
  if (self.behavior === P.behavior_STAB_DOWN) _bits |= BIT_ATK3 // $04. down thrust
  if (self.behavior === P.behavior_STAB_UP) _bits |= BIT_ATK4 // $08. up   thrust
  if (self === P) self.attack_bits = _bits
  if (!_bits) return
  // -------------------------------------------------------------------------
  let _xOff = 0
  if (_bits & BIT_ATK1)
    _xOff = 4 + 20 * self.xScale // stab high
  else if (_bits & BIT_ATK2)
    _xOff = 4 + 20 * self.xScale // stab low
  else if (_bits & BIT_ATK3)
    _xOff = 8 // down thrust
  else if (gmBool(self.xScale))
    _xOff = 12 // up thrust right
  else _xOff = 0 // up thrust left
  let _yOff = 0
  if (_bits & BIT_ATK1)
    _yOff = 0 // stab high
  else if (_bits & BIT_ATK2)
    _yOff = 16 // stab low
  else if (_bits & BIT_ATK3)
    _yOff = 33 // down thrust
  else _yOff = -4 // up thrust
  if (self === P && self.is_cucco && _bits & (BIT_ATK2 | BIT_ATK3)) _yOff -= 16
  // swrdX_base not used if g.use_wide_view
  self.SwordHB_x_base = (self.view_xl_dist_og + _xOff) & 0xff
  self.SwordHB_y_base = self.yt + _yOff
  self.SwordHB_collidable = inRange(self.xl + _xOff, viewXL(), viewXR() - 1)
}

/** `PC_update_hold_item()` — MOD: moved from its OG spot between FAIRY & STUNNED update. */
export function PC_update_hold_item(self: Lonk): void {
  if (gmBool(g.mod_SKIP_HOLD_ITEM)) {
    self.HoldItem_timer = 0
    return
  }
  if (!self.HoldItem_timer) return
  // 934E
  if (!self.ogr) self.hspd = 0
  if (!(self.cs & 0x3)) PC_update_1b(self) // updateX(), update Audio.walk_water_played_count
  // Any Input reaction is bypassed in PC_update_vertical() if getItemTimer != 0
  if (self.ogr) PC_update_vertical(self)
  PC_update_1d(self) // update hspd_dir, PC_update_cs(), if (cs3()) hspd = 0;
  self.HoldItem_timer--
  if (!self.is_cucco) {
    const inst = self.HoldItem_inst
    if (!inst?.exists || inst.ww > 8)
      PC_set_behavior(self.behavior_HOLD_ITEM1) // both arms raised
    else PC_set_behavior(self.behavior_HOLD_ITEM3) // left arm  raised
  }
  // 9364
  self.HoldItem_x_scale = self.HoldItem_X_SCALE
  PC_update_hitboxes(self) // body, shield, sword
  PC_update_1e(self) // update g.lastX, g.lastY, g.lastXScale
}

/** `PC_take_damage(obj inst Enemy, *alt damage)` — E2EF & E45C, E314. */
export function PC_take_damage(_INST: GameObject | null, _ALT_DMG?: number): void {
  const self = pc()
  if (self.iframes_timer) return
  if (!_INST && _ALT_DMG === undefined) return
  // ---------------------------------------------------------------
  if (_INST) f.xpDrain = Number(g.dl_XP_DRAIN.get(_INST.xp_drain) ?? 0)
  // ---------------------------------------------------------------
  let _damage = 0
  if (_ALT_DMG !== undefined) {
    _damage = _ALT_DMG
  } else if (_INST) {
    const _DAMAGE = Number(g.dg_enemy_damage.get(f.level_lif - 1, _INST.attack_level) ?? 0)
    _damage = _DAMAGE
    if (_damage) {
      switch (Math.sign(g.spells_active & SPL_PRTC) + Math.sign(f.items & ITM_RING)) {
        case 1:
          _damage = _DAMAGE >> 1
          break
        case 2:
          _damage = round(_DAMAGE * 0.33) // changed 7/28/23
          break
        default:
          _damage = _DAMAGE
      }
      _damage = Math.max(1, _damage) // Added 7/28/23. I believe every dmg in OG is at least 1.
    }
  }
  if (g.DevTools_state) {
    // g.dev_invState. 2: skip all, 1 skip dmg, 0 regular
    if ((g.dev_invState & 0x3) === 2) return
    if ((g.dev_invState & 0x3) === 1) _damage = 0 // dev
  }
  adjust_stat(-_damage, 0)
  // ---------------------------------------------------------------
  self.attack_phase = 0
  self.iframes_timer = 4
  self.stun_timer = self.Stun_DURATION1 // $20
  if (self.is_cucco && self.CUCCO_KNOCKBACK_REDUCTION) self.stun_timer = self.Stun_DURATION2 // $1A
  if (f.hp <= 0) self.is_dead = true
  // Knockback --------------------------------------
  if (_INST) {
    let _AMOUNT = 0xd
    if (self.is_cucco && self.CUCCO_KNOCKBACK_REDUCTION) _AMOUNT = 0xc
    pushback_pc(_INST.x, _AMOUNT)
  } else {
    if ((gmBool(self.xScale) && !(self.cs & 0x2)) || (!gmBool(self.xScale) && !(self.cs & 0x1))) {
      self.hspd = (0xa * -self.xScale) & 0xff
    }
  }
  if (!self.HoldItem_timer && g.gui_state === g.gui_state_NONE) {
    // MOD; Added 2024/07/24. PC can't jump after taking damage with dialogue window open.
    if (!self.is_fairy) {
      self.cs &= ~CS_BTM // removes CS_BTM
      self.vspd = self.VSPD_DAMAGE // $FE. Low velocity
    }
  }
  // Cucco Fury --------------------------------------
  if (gmBool(g.mod_PC_CUCCO_3) && self.is_cucco && _damage) {
    self.Cucco_damaged_count++
    self.Cucco_damage_taken += _damage
    const _HP_MAX = get_stat_max('_Heart')
    if (
      _damage >= round(_HP_MAX * 0.5) || // If this hit is hard enough.
      self.Cucco_damage_taken >= round(_HP_MAX * 0.7) || // If total dmg taken is enough
      (self.Cucco_damage_taken >= round(_HP_MAX * 0.15) && self.Cucco_damaged_count >= 0x20) || // hit enough times
      (self.Cucco_damage_taken >= round(_HP_MAX * 0.4) && self.Cucco_damaged_count >= 0x03)
    ) {
      self.Cucco_rage_tokens++ // Triggers fury atk when ready.
      self.Cucco_damaged_count = 0
      self.Cucco_damage_taken = 0
    }
  }
  aud_play_sound(get_audio_theme_track(STR_PC + STR_Damage))
}

/** `PC_set_bounce()` — down-thrust bounce, per `g.mod_HowDownStabAffectsVSPD`. */
export function PC_set_bounce(): void {
  const self = pc()
  switch (g.mod_HowDownStabAffectsVSPD) {
    case 0:
      self.vspd = self.vspd_bounce // OG. vspd_bounce: $FE
      break
    case 1:
      if (abs8b(self.vspd) < abs8b(self.vspd_bounce)) self.vspd = self.vspd_bounce
      break
    case 2:
      self.vspd = (self.vspd + self.vspd_bounce) & 0xff
      break
  }
}

/** `get_pc_attack_damage()` */
export function get_pc_attack_damage(): number {
  const self = pc()
  let _damage = self.dl_ATTACK_DAMAGE[f.level_atk] ?? 0
  if (gmBool(g.mod_PC_CUCCO_2) && self.is_cucco) {
    // Gives PC Cucco extra atk dmg
    _damage += 1 + (f.level_atk >= 4 ? 1 : 0) + (f.level_atk >= 6 ? 1 : 0) // +1,2,3
  }
  return _damage
}

/** `walk_pc_to_x(x, max hspd)` — cutscene walking; returns true once x is reached. */
export function walk_pc_to_x(targetX: number, maxHspd: number): boolean {
  const self = pc()
  if (self.x === targetX) return true
  // ------------------------------------------------------
  const _DIR = -Math.sign(self.x - targetX)
  self.xScale = _DIR
  if (self.hspd !== ((maxHspd * _DIR) & 0xff)) {
    // Couldn't figure out right way so converting
    const _HSPD_TARG = maxHspd * _DIR // Target hspd
    const _HSPD_CURR = abs8b(self.hspd) * byte_dir(self.hspd) // Current hspd
    self.hspd = (_HSPD_CURR + -Math.sign(_HSPD_CURR - _HSPD_TARG)) & 0xff
  }
  self.hspd_dir = byte_dir(self.hspd)
  updateX(self)
  if (_DIR !== -Math.sign(self.x - targetX)) {
    // if overshot x
    set_xy(self, targetX, self.y)
  }
  PC_update_walk(self)
  return false
}

/** `PC_update_death()` — C2D5: JSR D385, C2E9: JSR D385, D3CC. Goes to rmB_Death if PC dead. */
export function PC_update_death(): boolean {
  const self = pc()
  if (gmBool(self.is_dead) && !self.stun_timer) {
    p.BackgroundColor_at_death = backgroundState.colour
    self.is_dead = 0
    self.state = self.state_DEAD
    Audio.commands.push({ kind: 'stopInst', inst: Audio.mus_rm_inst }) // audio_stop_sound(Audio.mus_rm_inst)
    aud_play_sound(get_audio_theme_track(STR_PC + STR_Death))
    room_goto_(RM.DEATH)
    return true
  }
  return false
}

/** For `PC_update_1` (DROWN): a rescue drop-off elevator, if any, else null. */
export function elevatorOrNull(e: GameObject | null | undefined): Elevator | null {
  return e instanceof Elevator && e.exists ? e : NOONE
}

