/**
 * IndexedDB store for user player-character skins — database `zalia`, object store `skins`.
 *
 * ZALiA read the sheets from `%localappdata%\ZALiA\custom_playercharacter_graphics` at boot. The browser
 * has no such folder, so the PNGs the player picks are kept here and re-registered on every load.
 * The IDB surface used is narrow (`open` + one `getAll`/`put`/`delete`/`clear` per transaction) so tests
 * can drive it with a small fake instead of a real browser database.
 */

/** One stored sheet. `data` is the raw file bytes; the sheet is decoded when the texture is created. */
export interface SkinRecord {
  /** `userSkinKey(name, creator)` — primary key. */
  id: string
  name: string
  creator: string
  /** Original file name, kept for the Options menu / re-export. */
  fileName: string
  /** The image file's bytes (`File.arrayBuffer()`). */
  data: ArrayBuffer
  /** `image/png` … — needed to turn the bytes back into a Blob. */
  type: string
  addedAt: number
}

export const SKIN_DB_NAME = 'zalia'
export const SKIN_STORE_NAME = 'skins'
const SKIN_DB_VERSION = 1

/** The slice of `IDBFactory` this module needs (so a fake can implement just this). */
export interface IdbFactoryLike {
  open(name: string, version?: number): IDBOpenDBRequest
}

function request<T>(req: IDBRequest<T>): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    req.onsuccess = () => resolve(req.result)
    req.onerror = () => reject(req.error ?? new Error('IndexedDB request failed'))
  })
}

/**
 * Opens (and upgrades) `zalia/skins`. Every method resolves to a value or rejects; callers treat a
 * rejection as "no user skins" so a private window or a blocked database never stops the game booting.
 */
export class SkinDb {
  private db: IDBDatabase | undefined
  constructor(private readonly factory: IdbFactoryLike) {}

  /** True when the environment has IndexedDB at all. */
  static available(factory: IdbFactoryLike | undefined): factory is IdbFactoryLike {
    return !!factory && typeof factory.open === 'function'
  }

  private async open(): Promise<IDBDatabase> {
    if (this.db) return this.db
    const req = this.factory.open(SKIN_DB_NAME, SKIN_DB_VERSION)
    req.onupgradeneeded = () => {
      const db = req.result
      if (!db.objectStoreNames.contains(SKIN_STORE_NAME))
        db.createObjectStore(SKIN_STORE_NAME, { keyPath: 'id' })
    }
    this.db = await request(req)
    return this.db
  }

  private async store(mode: IDBTransactionMode): Promise<IDBObjectStore> {
    const db = await this.open()
    return db.transaction(SKIN_STORE_NAME, mode).objectStore(SKIN_STORE_NAME)
  }

  /** Every stored sheet, oldest first (the order they are offered in the skin list). */
  async all(): Promise<SkinRecord[]> {
    const store = await this.store('readonly')
    const rows = await request(store.getAll() as IDBRequest<SkinRecord[]>)
    return [...rows].sort((a, b) => a.addedAt - b.addedAt || a.id.localeCompare(b.id))
  }

  /** Insert or replace one sheet (same `<Name>_<Creator>` replaces the previous file). */
  async put(rec: SkinRecord): Promise<void> {
    const store = await this.store('readwrite')
    await request(store.put(rec) as IDBRequest<unknown>)
  }

  async remove(id: string): Promise<void> {
    const store = await this.store('readwrite')
    await request(store.delete(id) as IDBRequest<unknown>)
  }

  async clear(): Promise<void> {
    const store = await this.store('readwrite')
    await request(store.clear() as IDBRequest<unknown>)
  }
}

/** `new SkinDb(indexedDB)`, or `undefined` where IndexedDB is unavailable (Node, blocked storage). */
export function openSkinDb(factory: IdbFactoryLike | undefined = globalThis.indexedDB): SkinDb | undefined {
  return SkinDb.available(factory) ? new SkinDb(factory) : undefined
}
