/** Mago (`MagoA`) — the teleporting wizard. Ported from `Mago_init2/update/udp.gml`. */
import { CS_BD1, MAX_GOC1, UIDX_NULL, VIEW_W_OG, VIEW_W_OG_ } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G, world } from '../../../../../../runtime/world'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { get_ground_y } from '../../../../../collision/solid'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { inRange, sign_ } from '../../../../../math/index'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { dir_to_pc } from '../../../../go/misc'
import { set_xy } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import type { ObjectName } from '../../../../objectNames'
import { gp, pc } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2, update_EF11 } from '../../../GameObjectB'
import { rand } from '../iron_knuckle/common'

export class MagoA extends Enemy {
  readonly objectName = 'MagoA' as const
  ATK_CUE = 0xd2
}

/** `Mago_init2()` */
export function Mago_init2(self: MagoA): void {
  GO_init_palidx(self, G.PI_MOB_ORG)
  self.projectile_OBJ = 'Flame1'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.ATK_CUE = 0xd2
}

/** `Mago_update()` — B7C5 */
export function Mago_update(self: MagoA): void {
  const g = gp()
  const P = pc()
  self.facing_dir = dir_to_pc(self)
  self.counter = (self.counter - 1) & 0xff
  if (inRange(self.counter, 0xe0, 0xff)) {
    // --------------   FADE IN  ----------------------- $FF-E0:  0.533s
    if (self.counter & 0x1) update_EF11(self)
  } else if (inRange(self.counter, 0xc0, 0xdf)) {
    // B807 ------ $DF-C0:  0.533s. B7D6
    if (self.counter === self.ATK_CUE - 2 && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
      const p = GOC1_create(
        self.x,
        self.y,
        self.facing_dir,
        self.projectile as ObjectName,
        self.projectile_ver,
      ) // Flame1
      p.spawn_xl = self.xl + 8 * p.facing_dir // OG: Gives right a +4 advantage
      if (gmBool(g.mod_MAGO_ADJ1)) {
        p.spawn_xl = self.x + 4 * p.facing_dir // 4 off from mago center
        p.spawn_xl -= p.ww_ // bc spawn_xl is considered xl position
      }
      p.spawn_yt = self.yb - p.hh
      set_xy(p, p.spawn_xl + p.ww_, p.spawn_yt + p.hh_)
      p.hspd = (0xc * p.facing_dir) & 0xff
    }
    // B815, DE40
    GOB_update_2(self)
    // E2EF
    if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  } else if (inRange(self.counter, 0xa0, 0xbf)) {
    // B81B ---------   FADE OUT  ----------------------- $BF-A0:  0.533s
    if (!(self.counter & 0x1)) update_EF11(self)
  } else if (inRange(self.counter, 0x00, 0x9f)) {
    // $9F-00:  2.667s
    self.stun_timer = 0
    if (self.counter === 0) {
      // B81E.  TELEPORT,  SET NEW X
      let _RAND = rand(self)
      let _x = g.view_xl_og + _RAND + self.ww_
      let _y = self.y
      // If only one Mago is spawned it teleports too far from PC too often; give a better chance in range.
      let sameCount = 0
      for (const i of world.instancesOf(Enemy)) if (i.objectName === self.objectName) sameCount++
      if (gmBool(g.mod_MAGO_ADJ3) && _RAND & 0x1 && sameCount === 1) {
        const _DIST = 0x06 << 3
        _x = Math.max(P.x - _DIST, Math.min(_x, P.x + _DIST))
        _x = Math.max(self.ww_, Math.min(_x, g.rm_w - self.ww_))
      }
      // 2021/10/16. Inst always teleports to spawn coords. Turned mod off.
      if (gmBool(g.mod_MAGO_ADJ2)) {
        // Prevent teleporting in walls and over pits
        _RAND = world.irandom(VIEW_W_OG - 1) // $00-$FF
        _x = g.view_xl_og + VIEW_W_OG_
        _x += (_RAND >> 1) * sign_(_RAND & 0x1)
        _x = Math.max(g.view_xl_og + self.ww_, Math.min(_x, g.view_xr_og + 1 - self.ww_))
        const _NULL = -1
        const _CLM = _x >> 3
        const _ROW = self.y >> 3
        const _clm = _CLM
        const _row = get_ground_y(_clm << 3, _ROW << 3, 1, self.yb)
        // TODO (ZALiA): Find better way of finding nearest ground.
        if (_row === _NULL) {
          // if no solid ground below new xy (For example: Elevator shaft)
          _x = self.spawn_xl + self.ww_
          _y = self.spawn_yt + self.hh_
        } else {
          if (_row === _ROW)
            _y = get_ground_y(_clm << 3, _ROW << 3, -1, self.yb) // search upward
          else _y = _row << 3
          _y -= self.hh_
        }
      }
      set_xy(self, _x, _y)
    }
  }
}

/** `Mago_udp()` */
export function Mago_udp(self: MagoA): void {
  self.can_draw_self = true
  // ATK_CUE = $D2
  if (self.counter <= self.ATK_CUE) GO_set_sprite(self, 'spr_Mago2')
  else GO_set_sprite(self, 'spr_Mago1')
}

export function registerMago(): void {
  registerObject('MagoA', MagoA)
  registerScripts({ Mago_init2, Mago_update, Mago_udp })
}
registerMago()
