/** Seams of the platform scripts: dev debug draws and the composite cloud sprite registration. */
import type { GameObject } from '../classes'

export interface CloudBody {
  tileset: string
  width: number
  height: number
  parts: { left: number; top: number; x: number; y: number }[]
}

let cloudSerial = 0
/** Registry of cloud bodies keyed by the sprite key handed to `GO_sprite_init` (adapter draws the parts). */
export const cloudBodies = new Map<string, CloudBody>()

export const godHooks = {
  /** `GO_draw_body_hb()` / `GO_draw_cs_points()` — dev visualisers (dev folder); no-ops until ported. */
  GO_draw_body_hb: (_self: GameObject): void => {},
  GO_draw_cs_points: (_self: GameObject): void => {},
  /** `sprite_create_from_surface` replacement: returns a composite sprite key. */
  registerCloudSprite: (body: CloudBody): string => {
    const key = `composite:PlatformCloud:${++cloudSerial}`
    cloudBodies.set(key, body)
    return key
  },
}
