/** GO_instance_end, GO_destroy_1a (scripts/game_object/go) — instance teardown and slot release. */

import { instanceExists } from '../../../runtime/instance'
import { goMgr } from '../../../runtime/world'
import { type GameObject, GameObjectB, GOB1, GOB2, ProjectileHostile } from '../classes'
import { gp } from '../pending'

/**
 * `GO_instance_end()` — runs once per instance from `Instance.destroy()` (ZALiA called it from the Destroy,
 * Game End and Room End events, up to 3×; see FIDELITY_NOTES).
 */
export function GO_instance_end(self: GameObject): void {
  self.ocs_draw_x = [0, 0, 0, 0, 0]
  self.ocs_draw_y = [0, 0, 0]
  if (self.scr_inst_end) self.scr_inst_end(self)
  const solids = gp().dl_solid_inst
  const idx = solids?.findIndex(self) ?? -1
  if (idx !== -1) solids.delete(idx)
  if (self instanceof GOB1) {
    self.dl_sprites = undefined
    self.dl_ProjVuln = undefined
  }
}

/** Wire GO_instance_end into every GameObject's destroy(). Called from create.ts on construction. */
export function installInstanceEnd(self: GameObject): void {
  self.instanceEndHook = GO_instance_end
}

/** `GO_destroy_1a()` — release the manager slot, wake the SpawnByStab spawner, then destroy. */
export function GO_destroy_1a(self: GameObject): void {
  if (self instanceof GOB1) {
    const _idx = goMgr.dl_gob1.findIndex(self)
    if (_idx !== -1) goMgr.dl_gob1.set(_idx, null)
  } else if (self instanceof ProjectileHostile) {
    const _idx = goMgr.dl_goc1.findIndex(self)
    if (_idx !== -1) goMgr.dl_goc1.set(_idx, null)
  } else if (self instanceof GOB2) {
    const _idx = goMgr.dl_gob2.findIndex(self)
    if (_idx !== -1) goMgr.dl_gob2.delete(_idx)
  }
  // SpawnByStab_inst: The SpawnByStab inst that created this inst
  const sbs = self.SpawnByStab_inst
  if (instanceExists(sbs) && self instanceof GameObjectB && self.objectName !== 'SpStA') {
    sbs.state = 0
    if (gp().mod_destroy_go_on_death) GO_destroy_1a(sbs)
  }
  self.destroy()
}
