/**
 * Core-owned replacement for GameMaker's room tile layer (`tile_add`, `tile_layer_find`, …).
 *
 * GM semantics kept (assumptions where the manual is silent are marked):
 * - `tile_add` returns a new numeric id (GM ids start at 10000000); `-1` is "no tile".
 * - Positions are the tile's top-left; `tile_set_scale(id, -1, 1)` mirrors the tile so it occupies
 *   `[x - w, x)` horizontally (that is why ZALiA adds one column to `x` for mirrored tiles).
 * - `tile_layer_find(depth, x, y)` returns the first tile (insertion order — ASSUMPTION; GM does not
 *   document which tile wins when several overlap) at `depth` whose box contains the point, else -1.
 * - `tile_layer_shift` moves every tile of the layer; `tile_layer_hide/show` toggle the whole layer.
 * - `background_assign(dst, src)` (used for animated tilesets) becomes a tileset *alias*: tiles keep
 *   `tileset = dst`, the renderer draws them with `resolveTileset(dst)`.
 *
 * Each `TileLayer` has a `version` counter bumped on every change so the Phaser adapter rebuilds only
 * the layers that changed; `aliasVersion` covers `background_assign`.
 */
import type { World } from '../../runtime/world'
import { world } from '../../runtime/world'

export interface Tile {
  readonly id: number
  /** Tileset (GM background) asset name. */
  tileset: string
  /** Source rect inside the tileset image. */
  left: number
  top: number
  width: number
  height: number
  /** Room position (top-left before mirroring). */
  x: number
  y: number
  readonly depth: number
  visible: boolean
  alpha: number
  /** 1 or -1 (`tile_set_scale`). */
  xscale: number
  yscale: number
}

export class TileLayer {
  readonly tiles = new Map<number, Tile>()
  visible = true
  /** Incremented on every change (add/delete/move/visibility/palette). Renderer diff key. */
  version = 0
  /**
   * Palette index the whole layer is drawn with; -1 = none. ZALiA swaps tile layers with
   * `pal_swap_set_tiles`, which brackets a depth range with `TileSwapperStart`/`End` instances that set the
   * shader for everything drawn between them — per layer, not per tile. `color_tiles()` re-applies this
   * every frame.
   */
  palIdx = -1
  constructor(readonly depth: number) {}
  touch(): void {
    this.version++
  }
  setPalIdx(pi: number): void {
    if (this.palIdx === pi) return
    this.palIdx = pi
    this.touch()
  }
}

const NO_TILE = -1

export class TileWorld {
  /** Layers by GM depth. */
  readonly layers = new Map<number, TileLayer>()
  private readonly byId = new Map<number, Tile>()
  private nextId = 10_000_000
  /** `background_assign(dst, src)` results: dst → src. */
  readonly tilesetAlias = new Map<string, string>()
  aliasVersion = 0
  /** Bumped by `clear()` so a renderer can drop everything at once. */
  clearVersion = 0

  layer(depth: number, create = false): TileLayer | undefined {
    let l = this.layers.get(depth)
    if (!l && create) {
      l = new TileLayer(depth)
      this.layers.set(depth, l)
    }
    return l
  }

  resolveTileset(name: string): string {
    return this.tilesetAlias.get(name) ?? name
  }

  // ---- GM builtins -------------------------------------------------------------------------
  tile_add(
    background: string,
    left: number,
    top: number,
    width: number,
    height: number,
    x: number,
    y: number,
    depth: number,
  ): number {
    const layer = this.layer(depth, true) as TileLayer
    const tile: Tile = {
      id: this.nextId++,
      tileset: background,
      left,
      top,
      width,
      height,
      x,
      y,
      depth,
      visible: true,
      alpha: 1,
      xscale: 1,
      yscale: 1,
    }
    layer.tiles.set(tile.id, tile)
    this.byId.set(tile.id, tile)
    layer.touch()
    return tile.id
  }

  tile_exists(id: number): boolean {
    return this.byId.has(id)
  }

  get(id: number): Tile | undefined {
    return this.byId.get(id)
  }

  tile_delete(id: number): void {
    const t = this.byId.get(id)
    if (!t) return
    this.byId.delete(id)
    const layer = this.layers.get(t.depth)
    if (layer) {
      layer.tiles.delete(id)
      layer.touch()
    }
  }

  tile_get_depth(id: number): number {
    return this.byId.get(id)?.depth ?? NO_TILE
  }
  tile_get_left(id: number): number {
    return this.byId.get(id)?.left ?? 0
  }
  tile_get_top(id: number): number {
    return this.byId.get(id)?.top ?? 0
  }
  tile_get_x(id: number): number {
    return this.byId.get(id)?.x ?? 0
  }
  tile_get_y(id: number): number {
    return this.byId.get(id)?.y ?? 0
  }
  tile_get_width(id: number): number {
    return this.byId.get(id)?.width ?? 0
  }
  tile_get_height(id: number): number {
    return this.byId.get(id)?.height ?? 0
  }
  tile_get_background(id: number): string {
    return this.byId.get(id)?.tileset ?? ''
  }
  tile_get_visible(id: number): boolean {
    return this.byId.get(id)?.visible ?? false
  }

  tile_set_visible(id: number, visible: boolean): void {
    const t = this.byId.get(id)
    if (!t || t.visible === visible) return
    t.visible = visible
    this.layers.get(t.depth)?.touch()
  }
  tile_set_scale(id: number, xscale: number, yscale: number): void {
    const t = this.byId.get(id)
    if (!t) return
    t.xscale = xscale
    t.yscale = yscale
    this.layers.get(t.depth)?.touch()
  }
  tile_set_alpha(id: number, alpha: number): void {
    const t = this.byId.get(id)
    if (!t) return
    t.alpha = alpha
    this.layers.get(t.depth)?.touch()
  }
  tile_set_position(id: number, x: number, y: number): void {
    const t = this.byId.get(id)
    if (!t) return
    t.x = x
    t.y = y
    this.layers.get(t.depth)?.touch()
  }

  /** Box a tile occupies, accounting for mirroring. */
  static bounds(t: Tile): { x0: number; y0: number; x1: number; y1: number } {
    const x0 = t.xscale < 0 ? t.x - t.width : t.x
    const y0 = t.yscale < 0 ? t.y - t.height : t.y
    return { x0, y0, x1: x0 + t.width, y1: y0 + t.height }
  }

  tile_layer_find(depth: number, x: number, y: number): number {
    const layer = this.layers.get(depth)
    if (!layer) return NO_TILE
    for (const t of layer.tiles.values()) {
      const b = TileWorld.bounds(t)
      if (x >= b.x0 && x < b.x1 && y >= b.y0 && y < b.y1) return t.id
    }
    return NO_TILE
  }

  tile_layer_delete(depth: number): void {
    const layer = this.layers.get(depth)
    if (!layer) return
    for (const id of layer.tiles.keys()) this.byId.delete(id)
    layer.tiles.clear()
    layer.touch()
    this.layers.delete(depth)
  }
  tile_layer_hide(depth: number): void {
    const layer = this.layer(depth, true) as TileLayer
    if (!layer.visible) return
    layer.visible = false
    layer.touch()
  }
  tile_layer_show(depth: number): void {
    const layer = this.layer(depth, true) as TileLayer
    if (layer.visible) return
    layer.visible = true
    layer.touch()
  }
  tile_layer_shift(depth: number, dx: number, dy: number): void {
    const layer = this.layers.get(depth)
    if (!layer || (dx === 0 && dy === 0)) return
    for (const t of layer.tiles.values()) {
      t.x += dx
      t.y += dy
    }
    layer.touch()
  }
  tile_layer_depth(depth: number, newDepth: number): void {
    const layer = this.layers.get(depth)
    if (!layer || depth === newDepth) return
    this.layers.delete(depth)
    const target = this.layer(newDepth, true) as TileLayer
    for (const t of layer.tiles.values()) {
      ;(t as { depth: number }).depth = newDepth
      target.tiles.set(t.id, t)
    }
    target.touch()
    layer.touch()
  }

  tile_get_ids(): number[] {
    return [...this.byId.keys()]
  }
  tile_get_ids_at_depth(depth: number): number[] {
    return [...(this.layers.get(depth)?.tiles.keys() ?? [])]
  }
  get tileCount(): number {
    return this.byId.size
  }

  /** `room_tile_clear(room)` */
  clear(): void {
    this.byId.clear()
    this.layers.clear()
    this.clearVersion++
  }

  /** `background_assign(dst, src)` — draw `dst` tiles with `src`'s image (animated tilesets). */
  background_assign(dst: string, src: string): void {
    const current = this.tilesetAlias.get(dst)
    if (current === src || (current === undefined && src === dst)) return
    if (src === dst) this.tilesetAlias.delete(dst)
    else this.tilesetAlias.set(dst, src)
    this.aliasVersion++
  }
}

// ---- per-world instance + GM-named free functions ----------------------------------------------
const instances = new WeakMap<World, TileWorld>()

/** The current world's tile layer state. */
export function tileWorld(): TileWorld {
  let tw = instances.get(world)
  if (!tw) {
    tw = new TileWorld()
    instances.set(world, tw)
  }
  return tw
}

/** Tileset names known to the asset manifest. `null` = accept any non-empty name (tests). */
let knownTilesets: Set<string> | null = null
export function setTilesetNames(names: Iterable<string> | null): void {
  knownTilesets = names ? new Set(names) : null
}
/** GM `background_exists(bg)`: ZALiA passes `0` for "no graphic". */
export function background_exists(bg: unknown): bg is string {
  return typeof bg === 'string' && bg !== '' && (knownTilesets === null || knownTilesets.has(bg))
}
export const background_get_name = (bg: string): string => bg

export const tile_add = (
  bg: string,
  l: number,
  t: number,
  w: number,
  h: number,
  x: number,
  y: number,
  depth: number,
) => tileWorld().tile_add(bg, l, t, w, h, x, y, depth)
export const tile_exists = (id: number) => tileWorld().tile_exists(id)
export const tile_delete = (id: number) => tileWorld().tile_delete(id)
export const tile_get_depth = (id: number) => tileWorld().tile_get_depth(id)
export const tile_get_left = (id: number) => tileWorld().tile_get_left(id)
export const tile_get_top = (id: number) => tileWorld().tile_get_top(id)
export const tile_get_x = (id: number) => tileWorld().tile_get_x(id)
export const tile_get_y = (id: number) => tileWorld().tile_get_y(id)
export const tile_get_background = (id: number) => tileWorld().tile_get_background(id)
export const tile_get_visible = (id: number) => tileWorld().tile_get_visible(id)
export const tile_set_visible = (id: number, v: boolean) => tileWorld().tile_set_visible(id, v)
export const tile_set_scale = (id: number, sx: number, sy: number) => tileWorld().tile_set_scale(id, sx, sy)
export const tile_set_alpha = (id: number, a: number) => tileWorld().tile_set_alpha(id, a)
export const tile_set_position = (id: number, x: number, y: number) => tileWorld().tile_set_position(id, x, y)
export const tile_layer_find = (depth: number, x: number, y: number) =>
  tileWorld().tile_layer_find(depth, x, y)
export const tile_layer_delete = (depth: number) => tileWorld().tile_layer_delete(depth)
export const tile_layer_hide = (depth: number) => tileWorld().tile_layer_hide(depth)
export const tile_layer_show = (depth: number) => tileWorld().tile_layer_show(depth)
export const tile_layer_shift = (depth: number, dx: number, dy: number) =>
  tileWorld().tile_layer_shift(depth, dx, dy)
export const tile_layer_depth = (depth: number, nd: number) => tileWorld().tile_layer_depth(depth, nd)
export const tile_get_ids = () => tileWorld().tile_get_ids()
export const tile_get_ids_at_depth = (depth: number) => tileWorld().tile_get_ids_at_depth(depth)
export const room_tile_clear = () => tileWorld().clear()
export const background_assign = (dst: string, src: string) => tileWorld().background_assign(dst, src)
