/**
 * Everything the collision scripts need from the rest of the game, injected so this folder has no
 * import dependency on singletons that are ported concurrently. `setCollisionEnv()` is called by the
 * game bootstrap (and by tests) with real providers; unset providers throw like `notPorted`.
 */
import type { DsGrid } from '../../runtime/ds'
import type { Ref } from '../../runtime/instance'
import { markPending } from '../pending'
import type { Body, GoBody, PcBody, ProjBody, SolidInst } from './body'

export interface ViewRect {
  XL: number
  XR: number
  YT: number
  YB: number
  W: number
  H: number
  YC: number
}

export interface CamRange {
  xl_min: number
  xr_max: number
  yt_min: number
  yb_max: number
  x_range: number
}

/** Fields read from `g`. */
export interface CollisionGame {
  counter1: number
  /** `g.dg_BODY_HB[# idx, 0..4]`: xoff, yoff, w, h, r */
  dg_BODY_HB: DsGrid<number>
  /** `g.dg_CS_OFF[# idx, 0..15]` */
  dg_CS_OFF: DsGrid<number>
  /** `g.dg_ShieldHB[# idx, 0..4]`: xoff right, xoff left, yoff, w, h */
  dg_ShieldHB: DsGrid<number>
  HB_ADJ_X: number
  HB_ADJ_Y: number
  mod_fix_og_swordhb_exploit: boolean
  view_lock_boss: number
  EnterRoom_control_timer: number
  rm_h: number
  DevTools_state: boolean
  dev_invState: number
  CuccoSpell2_Active: boolean
  can_draw_ocs: boolean
}

export interface CollisionEnv {
  pc(): PcBody
  view(): ViewRect
  cam(): CamRange
  /** `global.dg_solid`, `global.dg_solid_w/h` */
  solid(): { grid: DsGrid<number>; w: number; h: number }
  /** `g.dl_solid_inst` */
  solidInsts(): readonly (Ref<SolidInst> | undefined)[]
  /** `g.go_mgr.dl_goc2` (PC projectiles, size MAX_GOC2) */
  goc2(): readonly (Ref<ProjBody> | undefined)[]
  game(): CollisionGame
  file(): { items: number; level_atk: number }
  /** `Ganon1` instance if it exists (GO_update_cs) */
  ganon1(): (Body & { pc_is_inside: boolean }) | null
  roomWidth(): number
  fn: {
    damage_gob(self: GoBody, damage: number, fromProjectile: boolean): void
    set_go_hspd_pushbback(self: GoBody, hspd: number): void
    pc_sword_colliding_solid_body(self: GoBody): void
    PC_set_bounce(): void
    get_pc_attack_damage(): number
    PC_take_damage(attacker: GoBody): void
    pushback_pc_and_go(self: GoBody): void
    dir_to_pc(self: GoBody): number
    aud_play_sound(sound: string | number): void
    get_audio_theme_track(theme: string): string | number
    pc_is_cucco(): boolean
    pc_is_fairy(): boolean
    /** dev overlay hook (`db_GO_update_cam_vars`) */
    db_GO_update_cam_vars(self: GoBody, axis: 'x' | 'y', idx: number, value: number): void
  }
}

function missing(name: string): never {
  throw new Error(`collision env: ${name} is not provided (not ported yet)`)
}

/** A tagged placeholder for one env seam — see `pending.ts` and `seams.test.ts`. */
const pending = (name: string) => markPending((): never => missing(name), name) as unknown as never

export const env: CollisionEnv = {
  pc: pending('pc'),
  view: pending('view'),
  cam: pending('cam'),
  solid: pending('solid'),
  solidInsts: () => [],
  goc2: () => [],
  game: pending('game'),
  file: pending('file'),
  // Bound by `registerEntities()`. It was a silent `() => null`, so the Ganon-1 body sensors — the whole
  // `point_in_rect` block that folds CS_RGT/LFT/TOP/BTM into the PC's `cs`, and the `pc_is_inside` escape —
  // never ran, and the guard could not see it because a non-throwing default is not a pending placeholder.
  ganon1: pending('ganon1'),
  roomWidth: pending('roomWidth'),
  fn: {
    damage_gob: pending('damage_gob'),
    set_go_hspd_pushbback: pending('set_go_hspd_pushbback'),
    pc_sword_colliding_solid_body: pending('pc_sword_colliding_solid_body'),
    PC_set_bounce: pending('PC_set_bounce'),
    get_pc_attack_damage: pending('get_pc_attack_damage'),
    PC_take_damage: pending('PC_take_damage'),
    pushback_pc_and_go: pending('pushback_pc_and_go'),
    dir_to_pc: pending('dir_to_pc'),
    aud_play_sound: pending('aud_play_sound'),
    get_audio_theme_track: pending('get_audio_theme_track'),
    pc_is_cucco: pending('pc_is_cucco'),
    pc_is_fairy: pending('pc_is_fairy'),
    db_GO_update_cam_vars: () => {},
  },
}

export type CollisionEnvPatch = Partial<Omit<CollisionEnv, 'fn'>> & { fn?: Partial<CollisionEnv['fn']> }

export function setCollisionEnv(patch: CollisionEnvPatch): void {
  const { fn, ...rest } = patch
  Object.assign(env, rest)
  if (fn) Object.assign(env.fn, fn)
}

// GM view/camera accessor names, for readability in ported code
export const viewXL = () => env.view().XL
export const viewXR = () => env.view().XR
export const viewYT = () => env.view().YT
export const viewYB = () => env.view().YB
export const viewW = () => env.view().W
export const viewH = () => env.view().H
export const viewYC = () => env.view().YC
export const viewW_ = () => env.view().W >> 1
export const viewH_ = () => env.view().H >> 1
export const viewXC = () => env.view().XL + (env.view().W >> 1)
export const cam_xl_min = () => env.cam().xl_min
export const cam_xr_max = () => env.cam().xr_max
export const cam_yt_min = () => env.cam().yt_min
export const cam_yb_max = () => env.cam().yb_max
export const cam_x_range = () => env.cam().x_range
