/** `spr_x_at_x(sprite, x pos, *align 0_cen 1_rgt -1_lft)` — draw x so the sprite aligns to `x`. */
export function spr_x_at_x(sprite: string, x: number, align = 0): number {
  const a = Math.sign(align)
  const w_ = sprite_get_width(sprite) >> 1
  return x - (w_ - sprite_get_xoffset(sprite)) - w_ * a
}

/** `spr_y_at_y(sprite, y pos, *align 0_cen 1_btm -1_top)` */
export function spr_y_at_y(sprite: string, y: number, align = 0): number {
  const a = Math.sign(align)
  const h_ = sprite_get_height(sprite) >> 1
  return y - (h_ - sprite_get_yoffset(sprite)) - h_ * a
}

/** GM `background_colour` / `background_showcolour` — read by the adapter each frame. */
export const backgroundState = { colour: 0, show: false }

/** `set_background_color(color)` */
export function set_background_color(color: number): void {
  if (backgroundState.colour === color) return // !!! GML exits on the colour alone
  backgroundState.colour = color
  backgroundState.show = true
}

/** `can_blink_container_piece()` — PC hold-item timer in its last third, every 4 frames. */
export function can_blink_container_piece(pc: {
  HoldItem_timer: number
  HoldItem_DURATION: number
}): boolean {
  return pc.HoldItem_timer > round(pc.HoldItem_DURATION * 0.66) && !!(pc.HoldItem_timer & 0x4)
}

/**
 * `get_fairy_yoff(timing)` — EBBE yoff for Fairy / EC2F swamp walk: 1,2,3,4,3,2,1,0 pattern from
 * `g.counter1 >> timing`.
 */
export function get_fairy_yoff(counter1: number, timing: number): number {
  const v = counter1 >> timing
  if (!(v & 0x4)) return -((v & 0x3) + 1) // 1, 2, 3, 4
  return -((v & 0x3) ^ 3) || 0 // 3, 2, 1, 0
}

/** `get_hover_y_adj(timing)` — ±1 every 2^timing frames, 0 otherwise. */
export function get_hover_y_adj(counter1: number, timing: number): number {
  const t = 1 << Math.max(0, Math.min(timing, 5)) // $1,$2,$4,$8,$10,$20
  if (!(counter1 & (t - 1))) return sign_(counter1 & (t << 2)) // $4,$8,$10,$20,$40,$80
  return 0
}

export interface SkullOptions {
  xscale?: number
  yscale?: number
  palidx?: number
  preset?: number
  mouthOpen?: number
  mouth?: number
  horns?: number
  skull?: number
  nose?: number
  eyes?: number
  pupils?: number
  depth?: number
}

/**
 * `draw_skull_1a(x, y, ...)` — Ganon's skull composed from part sprites. Emits palette-swapped
 * sprite draw commands (GML: `pal_swap_set(palette_image, palidx)` … `pal_swap_reset()`).
 */
export function draw_skull_1a(
  draw: DrawList,
  x: number,
  y: number,
  defaultPalIdx: number,
  o: SkullOptions = {},
): void {
  const xscale = sign_(o.xscale ?? 1)
  const yscale = sign_(o.yscale ?? 1)
  const palIdx = o.palidx ?? defaultPalIdx
  let mouthOpen = o.mouthOpen ?? -1
  let mouth = o.mouth ?? 0
  let horns = o.horns ?? 0
  let skull = o.skull ?? 0
  let nose = o.nose ?? 0
  let eyes = o.eyes ?? 0
  let pupils = o.pupils ?? 0
  // You can choose a preset AND specify custom values for each property.
  const preset = o.preset ?? 0
  if (preset >= 1 && preset <= 3) {
    if (!(mouthOpen + 1)) mouthOpen = preset // 1: skull 0/mouth +1, 2: -1/+1, 3: -1/+2
    if (!mouth) mouth = preset === 1 ? 2 : 1
    if (!horns) horns = 1
    if (!skull) skull = 1
    if (!nose) nose = 1
    if (!eyes) eyes = 1 // Anger1 w/ top+btm
    if (!pupils) pupils = 2 // large
  }
  const MOUTH = ['', 'spr_GanonSkull_Mouth1a', 'spr_GanonSkull_Mouth2a', 'spr_GanonSkull_Mouth1b']
  const HORNS = ['', 'spr_GanonSkull_Horns1a']
  const SKULL = ['', 'spr_GanonSkull_Main1a', 'spr_GanonSkull_Main2a']
  const NOSE = ['', 'spr_GanonSkull_Nose1a']
  const EYES = [
    '',
    'spr_GanonSkull_Eyes1a',
    'spr_GanonSkull_Eyes1b',
    'spr_GanonSkull_Eyes2a',
    'spr_GanonSkull_Eyes2b',
    'spr_GanonSkull_Eyes1c',
    'spr_GanonSkull_Eyes1d',
  ]
  const PUPILS = ['', 'spr_GanonSkull_Pupils1a', 'spr_GanonSkull_Pupils2a']
  const yoffMouth = [0, 1, 1, 2][mouthOpen] ?? 0
  const yoffSkull = [0, 0, -1, -1][mouthOpen] ?? 0
  const depth = o.depth ?? 0
  const push = (sprite: string | undefined, yoff: number) => {
    // GML draws sprite index 0 of "sprite 0" for unset parts (draw_sprite_ of 0 → spr_0, invisible); skip.
    if (!sprite) return
    const cmd: DrawCmd = {
      kind: 'sprite',
      sprite,
      frame: 0,
      x,
      y: y + yoff,
      xscale,
      yscale,
      palIdx,
      depth,
      alpha: 1,
    }
    draw.push(cmd)
  }
  push(MOUTH[mouth], yoffMouth)
  push(HORNS[horns], yoffSkull)
  push(SKULL[skull], yoffSkull)
  push(NOSE[nose], yoffSkull)
  push(EYES[eyes], yoffSkull)
  push(PUPILS[pupils], yoffSkull)
}

let compositeSeq = 0

/**
 * `sprite_create_with_tiles(dl_ts idx data, tsrc data, rc off data, *flip data)` — builds a sprite out of
 * 8×8 tileset cells. The GML drew onto a surface; here the layout is recorded as a composite sprite the
 * adapter renders, and the sprite is registered so `sprite_get_*` work. Origin is the centre.
 * `tilesetAt(idx)` resolves `g.dl_tileset[|idx]` to a tileset name.
 */
export function sprite_create_with_tiles(
  tilesetAt: (idx: number) => string,
  tsIdxData: string,
  tsrcData: string,
  rcoffData?: string,
  flipData?: string,
): string {
  let charCount = tsrcData.length
  if (charCount < 2) return 'spr_0'
  let tsrc = tsrcData
  if (charCount & 1) {
    charCount--
    tsrc = tsrc.slice(0, charCount)
  }
  const tileCount = charCount >> 1
  const fit = (s: string, pad: string) =>
    s.length < charCount ? s + pad.repeat(charCount - s.length) : s.slice(0, charCount)
  const tsIdx = fit(tsIdxData, 'F')
  const rcoff = rcoffData === undefined ? '0'.repeat(charCount) : fit(rcoffData, 'F')
  const flip = flipData === undefined ? '0'.repeat(charCount) : fit(flipData, '0')
  let clms = 1
  let rows = 1
  for (let i = 0; i < tileCount; i++) {
    const rc = str_hex(rcoff, i)
    clms = Math.max(clms, (rc & 0xf) + 1)
    rows = Math.max(rows, ((rc >> 4) & 0xf) + 1)
  }
  const w = clms << 3
  const h = rows << 3
  const tiles: CompositeSprite['tiles'] = []
  for (let i = 0; i < tileCount; i++) {
    const tileset = tilesetAt(str_hex(tsIdx, i))
    const f = str_hex(flip, i)
    const xscale = -sign_(f & 0xf) as 1 | -1
    const yscale = -sign_((f >> 4) & 0xf) as 1 | -1
    const rc = str_hex(rcoff, i)
    // GML: _clm += !_xscale — with xscale ±1 that is always 0, so flipped tiles are drawn at the same cell.
    const x = (rc & 0xf) << 3
    const y = ((rc >> 4) & 0xf) << 3
    const src = str_hex(tsrc, i)
    tiles.push({ tileset, tsx: (src & 0xf) << 3, tsy: ((src >> 4) & 0xf) << 3, x, y, xscale, yscale })
  }
  const name = `composite_${++compositeSeq}`
  return addSprite({
    name,
    atlas: '',
    frames: 1,
    width: w,
    height: h,
    originX: w >> 1,
    originY: h >> 1,
    bbox: { left: 0, top: 0, right: w - 1, bottom: h - 1 },
    folder: 'composite',
    composite: { width: w, height: h, tiles },
  })
}
