/** Ported from `Cutscene_EnterFromChimney_init_2.gml`, `_update.gml`, `_update_1a.gml`. */
import { DEPTH_PC_MAIN, OGR_OTHR, PC_LOCK_ALL, PC_LOCK_VSPD, STR_Data, TID_SOLID1 } from '@z2/data'
import { gmBool } from '../../../nes/math8'
import { NOONE } from '../../../runtime/instance'
import { G, g } from '../../../runtime/world'
import { find_row_solid } from '../../collision/solid'
import { instancesNamed } from '../../Game/gm'
import { val } from '../../other'
import { set_xy } from '../go/movement'
import type { Cutscene_EnterFromChimney } from './classes'
import { gofDeps } from './deps'

/** `Cutscene_EnterFromChimney_init_2()` — only lives if the PC entered through this exit. */
export function Cutscene_EnterFromChimney_init_2(self: Cutscene_EnterFromChimney): void {
  self.scr_step = Cutscene_EnterFromChimney_update_1a as never
  self.CLM = self.xl >> 3
  self.ROW = self.yt >> 3
  let _EXIT_NAME = `${g.rm_name}00`
  if (self.dk_spawn !== undefined)
    _EXIT_NAME = val(g.dm_spawn.get(`${self.dk_spawn + STR_Data}01`), _EXIT_NAME) as string
  self.Exit_inst = NOONE
  for (const ex of instancesNamed('Exit')) {
    if (ex.exitName === _EXIT_NAME) {
      self.Exit_inst = ex
      break
    }
  }
  if (self.Exit_inst !== g.exit_enter) self.destroy()
}

/** `Cutscene_EnterFromChimney_update(x, y)` — PC drops in from the chimney, crouches, then is released. */
export function Cutscene_EnterFromChimney_update(
  self: Cutscene_EnterFromChimney,
  _X: number,
  _Y: number,
): void {
  if (!gmBool(g.mod_PC_ENTER_FROM_CHIMNEY) || g.ChangeRoom_timer > 0) return
  if (
    !gmBool(g.cutscene) &&
    g.EnterRoom_SpawnGO_timer <= 1 &&
    !(g.exit_enter.side & 0xf) // Chimney exit
  ) {
    g.cutscene = 1
    g.cutscene_part = 1
  }
  if (!gmBool(g.cutscene)) return
  const _DEPTH = g.TILE_DEPTH_MAX_BACK + 1
  const pc = G.pc
  pc.xScale = 1
  set_xy(pc, _X, pc.y)
  g.pc_lock = PC_LOCK_ALL ^ PC_LOCK_VSPD // Let vspd update
  switch (g.cutscene_part) {
    case 1: {
      if (gmBool(g.cutscene_timer)) break
      pc.depth_def = _DEPTH
      if (pc.state !== pc.state_NORMAL) break
      pc.ogr = OGR_OTHR // macro, not an instance field
      set_xy(pc, _X, 0x0a << 3)
      g.cutscene_part++
      break
    }
    case 2: {
      pc.depth_def = _DEPTH
      if (gmBool(g.cutscene_timer)) break
      if (pc.yt + pc.hh < find_row_solid(TID_SOLID1, _X >> 3, (_Y >> 3) + 4, 1) << 3) break
      gofDeps.PC_set_behavior(pc, pc.behavior_CROUCH) // crouch
      g.cutscene_timer = 0x08
      g.cutscene_part++
      break
    }
    case 3: {
      if (pc.landing_timer > 1) pc.depth_def = _DEPTH
      else pc.depth_def = DEPTH_PC_MAIN
      gofDeps.PC_set_behavior(pc, pc.behavior_CROUCH) // crouch
      if (gmBool(g.cutscene_timer)) break
      g.cutscene_timer = 0x08
      g.cutscene_part++
      break
    }
    case 4: {
      // [dropped: GML `if (0) { … }` disabled block]
      g.cutscene_part++
      break
    }
    case 5: {
      pc.depth_def = DEPTH_PC_MAIN
      gofDeps.PC_set_behavior(pc, pc.behavior_IDLE)
      if (gmBool(g.cutscene_timer)) break
      g.pc_lock = 0
      g.cutscene_part = 0
      g.cutscene = 0
      self.destroy()
      break
    }
  }
}

/** `Cutscene_EnterFromChimney_update_1a()` */
export function Cutscene_EnterFromChimney_update_1a(self: Cutscene_EnterFromChimney): void {
  Cutscene_EnterFromChimney_update(self, self.CLM << 3, self.ROW << 3)
}
