/** `Cutscene_CreateWaterfall_init_1()` */
export function Cutscene_CreateWaterfall_init_1(self: Cutscene_CreateWaterfall): void {
  Cutscene_init(self)
  self.spawn_xl = 0x2d << 3
  self.spawn_yt = (g.rm_rows - PAGE_ROWS + 0x10) << 3
  set_xlyt(self, self.spawn_xl, self.spawn_yt)
  self.sub_state = self.SUB_STATE_CHECK0
  self.counter = 0
  self.DUR1 = 0x30
  self.DUR2 = 0x10
  self.CLMS = 0x09
  self.ROWS = 0x10
  self.lead_row_y = self.yt
  self.rows_added = 0
  self.Waterfall_DEPTH = DEPTH_BG4
  self.Waterfall_DRAW_DEPTH = self.Waterfall_DEPTH
  self.Waterfall_SPEED = 0 // 0,1,3,7,15..
  self.Waterfall_TS = g.ts_Natural1_HMS
  self.Waterfall_TSRC1 = 0xf8 // water body
  self.Waterfall_TSRC2 = 0xf0 // water head
  self.Waterfall_DEPTH_IDX = g.dl_TILE_DEPTHS.findIndex(self.Waterfall_DEPTH)
  self.WaterfallPI_LIT = G.PI_BGR3 + p.PI_LIT1
  self.WaterfallPI_DARK = G.PI_BGR3 + p.PI_DRK1
  self.AquiferWater_DEPTH = DEPTH_FG2
  self.AquiferWater_Rise_SPEED = 0x04 - 1
  self.AquiferWater_yoff = 0
  self.AquiferWater_yoff_MAX = (0x02 << 3) + 4
  self.Block_DEPTH = DEPTH_BG2
  self.BlockTile_CLMS = 0x03
  self.BlockTile_ROWS = 0x03
  self.BlockTile_COUNT = self.BlockTile_CLMS * self.BlockTile_ROWS
  self.Blocks1_CLM = self.xl >> 3
  self.Blocks1_ROW = (self.yt >> 3) - 2
  self.Blocks1_CLMS = 0x03
  self.Blocks1_ROWS = 0x01
  self.Blocks1_COUNT = self.Blocks1_CLMS * self.Blocks1_ROWS
  self.Blocks1_TILE_COUNT = self.Blocks1_COUNT * self.BlockTile_COUNT
  self.Blocks2_CLM = 0x57
  self.Blocks2_ROW = g.rm_rows - PAGE_ROWS + 0x0f
  self.Blocks2_CLMS = 0x01
  self.Blocks2_ROWS = 0x02
  self.Blocks2_COUNT = self.Blocks2_CLMS * self.Blocks2_ROWS
  self.Blocks2_TILE_COUNT = self.Blocks2_COUNT * self.BlockTile_COUNT
  self.Block_Crumble_TS = 'ts_Man_made_1a_WRB'
  self.Block_Crumble_TSRC1 = 0x4f
  self.Block_Crumble_TSRC2 = self.Block_Crumble_TSRC1 + 0x10
  const dg = new DsGrid<number>(self.BlockTile_CLMS, self.BlockTile_ROWS, 0)
  const t1 = self.Block_Crumble_TSRC1
  const t2 = self.Block_Crumble_TSRC2
  dg.set(0, 0, t1)
  dg.set(0, 1, t1)
  dg.set(0, 2, t1)
  dg.set(1, 0, t1)
  dg.set(1, 1, t2)
  dg.set(1, 2, t1)
  dg.set(2, 0, t2)
  dg.set(2, 1, t2)
  dg.set(2, 2, t2)
  self.dg_Block_Crumble_TSRC = dg
  self.depth = self.Waterfall_DRAW_DEPTH
  self.LockedDoor_XL = 0x58 << 3
  self.LockedDoor_YT = (g.rm_rows - PAGE_ROWS + 0x0f) << 3
  self.dl_Tyell_SPAWN_DK = new DsList<string>()
}

/** `Cutscene_CreateWaterfall_init_2()` */
export function Cutscene_CreateWaterfall_init_2(self: Cutscene_CreateWaterfall): void {
  self.scr_step = Cutscene_CreateWaterfall_update as never
  self.depth = self.Waterfall_DRAW_DEPTH
  self.spawn_xl = 0x2d << 3
  self.spawn_yt = (g.rm_rows - PAGE_ROWS + 0x10) << 3
  set_xlyt(self, self.spawn_xl, self.spawn_yt)
  if (quest_is_complete(QuestID_Nabooru_Spell)) {
    tile_layer_delete(self.Block_DEPTH) // The 3 blocks blocking water at mouth
    tile_layer_show(self.Waterfall_DEPTH) // make waterfall visible
    tile_layer_shift(self.AquiferWater_DEPTH, 0, -self.AquiferWater_yoff_MAX) // raise the aquifer water
    g.pc_lock = 0
    self.destroy()
    return
  }
  GameObject_create(self.LockedDoor_XL, self.LockedDoor_YT, 'LoDoA', 3)
}

/** `Cutscene_CreateWaterfall_update()` — waits for every Tyell to die, then opens the waterfall. */
export function Cutscene_CreateWaterfall_update(self: Cutscene_CreateWaterfall): void {
  const dl = self.dl_Tyell_SPAWN_DK as DsList<string>
  switch (self.sub_state) {
    case self.SUB_STATE_CHECK0: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      // Make sure enemies have spawned
      let _spawned = false
      for (const e of world.instancesOf(Enemy)) {
        if (gmBool(e.state)) {
          _spawned = true
          break
        }
      }
      if (!_spawned) break
      for (const t of instancesNamed('TyellManager')) dl.add(t.dk_spawn)
      for (const t of instancesNamed('Tyell')) dl.add(t.dk_spawn)
      self.timer = 0
      self.sub_state = self.SUB_STATE_CHECK1
      break
    }
    case self.SUB_STATE_CHECK1: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      // Check if all enemies are dead.
      let _complete = true
      for (const e of world.instancesOf(Enemy)) {
        if (!gmBool(e.state)) continue
        // Make sure it's a defeatable enemy just in case Rando puts an un-defeatable enemy here
        if (isAncestorName(e.objectName, 'Tyell')) {
          _complete = false
          break
        }
        if (gmBool(e.react_sword)) {
          let _vulnerability = (e.react_sword >> 0) & 0xff
          const _SOLID = (e.react_sword >> 8) & 0xff
          let _ATK_BITS = BIT_ATK1 | BIT_ATK2
          if (f.skills & SKILL_THD) _ATK_BITS |= BIT_ATK3
          if (f.skills & SKILL_THU) _ATK_BITS |= BIT_ATK4
          if (f.items & ITM_SWRD) _vulnerability |= _SOLID
          else _vulnerability &= ~_SOLID
          _vulnerability &= _ATK_BITS
          if (gmBool(_vulnerability)) {
            _complete = false
            break
          }
        }
        if (
          e.react_proj & 0x1 || // if pc proj BEAM can damage
          (e.react_proj & 0x2 && f.spells & SPL_FIRE) // if pc proj FIRE can damage
        ) {
          _complete = false
          break
        }
        // Axe, Bullet1,Bullet2, Fireball1,Fireball2, Mace1,Mace2, Rock1,Rock2,Rock3, SoundWave
        const proj = e as unknown as { projectile?: string; projectile_ver?: number }
        if (f.spells & SPL_RFLC && proj.projectile) {
          const _PROJ_OBJVER = proj.projectile + hexStr(proj.projectile_ver ?? 1)
          if ((val(goData.dm_go_prop.get(_PROJ_OBJVER + dk_ReactShield)) as number) & 0x4) {
            // if projectile is REFLECT-able
            const _ENEMY_OBJVER = e.objectName + hexStr(e.ver)
            if (
              gmBool(val(goData.dm_go_prop.get(_ENEMY_OBJVER + STR_REFLECT + STR_Vulnerable + _PROJ_OBJVER)))
            ) {
              // if vulnerable to projectile
              _complete = false
              break
            }
          }
        }
      }
      if (_complete) {
        f.dm_quests.set(STR_Nabooru + STR_Quest + STR_Complete, 1)
        // Set Tyell spawn permission so they can't spawn again.
        // TODO(ZALiA): GO spawn_dk need to include save-file num and quest num.
        for (let _i = dl.size - 1; _i >= 0; _i--) g.dm_spawn.set(dl.get(_i) + STR_Spawn_Permission, 0)
        g.pc_lock = PC_LOCK_ALL
        self.timer = 0
        self.sub_state = self.SUB_STATE_ACTV0
      }
      break
    }
    case self.SUB_STATE_ACTV0: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      // remove waterfall blocks
      Cutscene_CreateWaterfall_update_1a(
        self,
        self.Blocks1_CLM << 3,
        self.Blocks1_ROW << 3,
        self.Blocks1_CLMS * self.BlockTile_CLMS,
        self.Blocks1_TILE_COUNT,
      )
      aud_play_combo1(3)
      for (const d of instancesNamed('LoDoA')) if (!gmBool(d.counter)) d.counter = -1 // -1: Tells LockedDoor to start opening process
      self.timer = self.DUR2 // Draw block crumble duration
      self.sub_state = self.SUB_STATE_ACTV1
      break
    }
    case self.SUB_STATE_ACTV1: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      // play quest completed sound
      if ((g.counter1 & 0x7) === 0x7) {
        aud_play_sound(get_audio_theme_track(dk_Fanfare), -1, false, -1, dk_Fanfare)
        self.timer = 0
        self.sub_state = self.SUB_STATE_ACTV2
      }
      break
    }
    case self.SUB_STATE_ACTV2: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      // animate waterfall to destination
      if (
        self.rows_added >= 0xd &&
        self.AquiferWater_yoff < self.AquiferWater_yoff_MAX &&
        !(g.counter1 & self.AquiferWater_Rise_SPEED)
      ) {
        self.AquiferWater_yoff++
        tile_layer_shift(self.AquiferWater_DEPTH, 0, -1)
      }
      if (!(g.counter1 & 0x7) && self.rows_added < self.ROWS) self.rows_added++
      if (self.rows_added >= self.ROWS) tile_layer_show(self.Waterfall_DEPTH)
      if (self.rows_added >= self.ROWS && self.AquiferWater_yoff >= self.AquiferWater_yoff_MAX) {
        self.timer = 0
        self.sub_state = self.SUB_STATE_DONE
      }
      break
    }
    case self.SUB_STATE_ACTV3: {
      // Exit blocks crumble
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      self.timer = 0
      self.sub_state = self.SUB_STATE_DONE
      break
    }
    case self.SUB_STATE_DONE: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      g.pc_lock = 0
      self.destroy()
      break
    }
  }
}

/** `Cutscene_CreateWaterfall_update_1a(blocks x, blocks y, tile clms, blocks tile count)` */
export function Cutscene_CreateWaterfall_update_1a(
  self: Cutscene_CreateWaterfall,
  _X: number,
  _Y: number,
  _Tile_CLMS: number,
  _BlocksTile_COUNT: number,
): void {
  for (let _i = 0; _i < _BlocksTile_COUNT; _i++) {
    const _x = _X + ((_i % _Tile_CLMS) << 3)
    const _y = _Y + (Math.trunc(_i / _Tile_CLMS) << 3)
    tile_change_1a(self.Block_DEPTH, _x, _y, 0, 0, 0)
  }
}

/** `Cutscene_CreateWaterfall_draw()` */
export function Cutscene_CreateWaterfall_draw(self: Cutscene_CreateWaterfall): void {
  if (self.sub_state === self.SUB_STATE_ACTV1) {
    self.depth = self.Block_DEPTH - 3
    pal_swap_set(G.PI_BGR2)
    Cutscene_CreateWaterfall_draw_1a(
      self,
      self.Blocks1_CLM << 3,
      self.Blocks1_ROW << 3,
      self.Blocks1_CLMS,
      self.Blocks1_ROWS,
      self.Blocks1_COUNT,
    )
    pal_swap_reset()
  }
  if (self.sub_state !== self.SUB_STATE_ACTV2 || !self.rows_added || self.rows_added >= self.ROWS) return
  self.depth = self.Waterfall_DRAW_DEPTH
  let _pi: number
  if (rm_pal_qual_lit()) _pi = self.WaterfallPI_LIT
  else _pi = self.WaterfallPI_DARK
  pal_swap_set(_pi)
  const _X = self.xl
  const _Y = self.yt + (g.counter1 & 0x7)
  const _COUNT = self.CLMS * self.rows_added
  const sx1 = ((self.Waterfall_TSRC1 >> 0) & 0xf) << 3
  const sy1 = ((self.Waterfall_TSRC1 >> 4) & 0xf) << 3
  for (let _i = 0; _i < _COUNT; _i++) {
    const _x = _X + ((_i % self.CLMS) << 3)
    const _y = _Y + (Math.trunc(_i / self.CLMS) << 3)
    draw_background_part(self.Waterfall_TS, sx1, sy1, 8, 8, _x, _y)
  }
  let _y = self.yt + (self.rows_added << 3) + (g.counter1 & 0x7)
  _y += 8 // for -1 yscale offset
  const sx2 = ((self.Waterfall_TSRC2 >> 0) & 0xf) << 3
  const sy2 = ((self.Waterfall_TSRC2 >> 4) & 0xf) << 3
  for (let _i = 0; _i < self.CLMS; _i++) {
    const _x = _X + (_i << 3)
    draw_background_part_ext(self.Waterfall_TS, sx2, sy2, 8, 8, _x, _y, 1, -1, 0xffffff, 1)
  }
  pal_swap_reset()
}

/** `Cutscene_CreateWaterfall_draw_1a(blocks x, blocks y, blocks clms, blocks rows, blocks count)` */
export function Cutscene_CreateWaterfall_draw_1a(
  self: Cutscene_CreateWaterfall,
  _X: number,
  _Y: number,
  _Blocks_CLMS: number,
  _Blocks_ROWS: number,
  _Blocks_COUNT: number,
): void {
  const dg = self.dg_Block_Crumble_TSRC as DsGrid<number>
  for (let _i = 0; _i < _Blocks_COUNT; _i++) {
    const _x0 = _X + (((_i % _Blocks_CLMS) * self.BlockTile_CLMS) << 3)
    const _y0 = _Y + ((Math.trunc(_i / _Blocks_CLMS) * self.BlockTile_ROWS) << 3)
    for (let _j = 0; _j < self.BlockTile_COUNT; _j++) {
      const _x = _x0 + ((_j % self.BlockTile_CLMS) << 3)
      const _y = _y0 + (Math.trunc(_j / self.BlockTile_CLMS) << 3)
      const _tsrc = dg.get(Math.trunc(_j / self.BlockTile_CLMS), _j % self.BlockTile_CLMS) as number
      draw_background_part(
        self.Block_Crumble_TS,
        ((_tsrc >> 0) & 0xf) << 3,
        ((_tsrc >> 4) & 0xf) << 3,
        8,
        8,
        _x,
        _y,
      )
    }
  }
}

/** `Cutscene_CreateWaterfall_end()` */
export function Cutscene_CreateWaterfall_end(self: Cutscene_CreateWaterfall): void {
  self.dl_Tyell_SPAWN_DK = undefined
  self.dg_Block_Crumble_TSRC = undefined
}
