/**
 * Reachability predicates — the randomizer's logic is hand-written region checks, not a graph solver.
 *
 * Ported from `Rando_is_attainable`, `Rando_are_attainable`, `Rando_attainable_key_count`, `Rando_is_spell`,
 * `Rando_can_reach_*` and `Rando_can_traverse_*`. Every one of them reads only the lists of already-placed
 * items/spells/skills/keys on `self`, so they answer "with what the player can have by now, is X reachable".
 *
 * Dead in ZALiA (no callers) but kept because they are the obvious parallel of the live ones and cost
 * nothing: `Rando_can_traverse_Rauru_town`, `_NewKasuto_town`, `_OldKasuto_town`, `_Bulblin_town`.
 * `Rando_can_reach_P5_key2_location` is an empty script in ZALiA and is dropped.
 */
import {
  STR_ALLKEY,
  STR_BOOTS,
  STR_BRACELET,
  STR_Bulblin,
  STR_CANDLE,
  STR_Count,
  STR_CROSS,
  STR_Darunia,
  STR_Dungeon,
  STR_ENIGMA,
  STR_FAIRY,
  STR_FIRE,
  STR_FLUTE,
  STR_GLOVE,
  STR_Great_Palace,
  STR_HAMMER,
  STR_HEAL,
  STR_Island_Palace,
  STR_JUMP,
  STR_KEY,
  STR_Key,
  STR_Maze_Island_Palace,
  STR_Mido,
  STR_Midoro_Palace,
  STR_Nabooru,
  STR_New_Kasuto,
  STR_NOTE,
  STR_Num,
  STR_Old_Kasuto,
  STR_Palace_On_The_Sea,
  STR_Parapa_Palace,
  STR_PROTECT,
  STR_RAFT,
  STR_Rando,
  STR_Rauru,
  STR_REFLECT,
  STR_Ruto,
  STR_Saria,
  STR_STABDOWN,
  STR_SUMMON,
  STR_THUNDER,
  STR_Three_Eye_Rock_Palace,
  STR_Town,
} from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { G, g } from '../../runtime/world'
import { val } from '../other/index'
import { inList } from './helpers'
import { Rando_is_qual_location } from './qualLocation'
import type { Rando } from './Rando'

/** `Rando_is_attainable(case, *case..)` — any of the ids has already been placed. */
export function Rando_is_attainable(self: Rando, ...cases: string[]): boolean {
  for (const c of cases) {
    if (
      inList(self.dl_items_placed, c) ||
      inList(self.dl_spells_placed, c) ||
      inList(self.dl_skills_placed, c) ||
      inList(self.dl_keys_placed, c)
    ) {
      return true
    }
  }
  return false
}

/** `Rando_are_attainable(case, *case..)` — all of the ids have already been placed. */
export function Rando_are_attainable(self: Rando, ...cases: string[]): boolean {
  for (const c of cases) {
    if (
      !inList(self.dl_items_placed, c) &&
      !inList(self.dl_spells_placed, c) &&
      !inList(self.dl_skills_placed, c) &&
      !inList(self.dl_keys_placed, c)
    ) {
      return false
    }
  }
  return true
}

/** `Rando_attainable_key_count(dungeon num)` */
export function Rando_attainable_key_count(self: Rando, dungeonNum: number): number {
  const _DUNGEON_NUM_ = hexStr(dungeonNum)
  let _count = 0
  let _num = 1
  const total = Number(g.dm_spawn.val(STR_Dungeon + _DUNGEON_NUM_ + STR_Key + STR_Count))
  for (let i = 0; i < total; i++) {
    if (Rando_is_attainable(self, STR_KEY + _DUNGEON_NUM_ + hexStr(_num++))) _count++
  }
  return _count
}

/** `Rando_is_spell(spell)` */
export function Rando_is_spell(id: unknown): boolean {
  return (
    id === STR_PROTECT ||
    id === STR_JUMP ||
    id === STR_HEAL ||
    id === STR_FAIRY ||
    id === STR_FIRE ||
    id === STR_REFLECT ||
    id === STR_ENIGMA ||
    id === STR_THUNDER ||
    id === STR_SUMMON
  )
}

// ---- town traversal ------------------------------------------------------------------------------
// `dm_save_data[?STR_Town+STR_Rando+<town>+"B"]` = which town inhabits <town>'s overworld location.
// Old Kasuto is behind the invisible-enemy fog, so it needs CROSS.
function canTraverseTown(self: Rando, town: string): boolean {
  if (
    val(self.dm_save_data.get(STR_Town + STR_Rando + town + 'B'), town) !== STR_Old_Kasuto ||
    Rando_is_attainable(self, STR_CROSS)
  ) {
    return true
  }
  return false
}

/** `Rando_can_traverse_Rauru_town()` (dead in ZALiA) */
export const Rando_can_traverse_Rauru_town = (self: Rando): boolean => canTraverseTown(self, STR_Rauru)
/** `Rando_can_traverse_Ruto_town()` */
export const Rando_can_traverse_Ruto_town = (self: Rando): boolean => canTraverseTown(self, STR_Ruto)
/** `Rando_can_traverse_Saria_town()` */
export const Rando_can_traverse_Saria_town = (self: Rando): boolean => canTraverseTown(self, STR_Saria)
/** `Rando_can_traverse_Mido_town()` */
export const Rando_can_traverse_Mido_town = (self: Rando): boolean => canTraverseTown(self, STR_Mido)
/** `Rando_can_traverse_Nabooru_town()` */
export const Rando_can_traverse_Nabooru_town = (self: Rando): boolean => canTraverseTown(self, STR_Nabooru)
/** `Rando_can_traverse_Darunia_town()` */
export const Rando_can_traverse_Darunia_town = (self: Rando): boolean => canTraverseTown(self, STR_Darunia)
/** `Rando_can_traverse_NewKasuto_town()` (dead in ZALiA) */
export const Rando_can_traverse_NewKasuto_town = (self: Rando): boolean =>
  canTraverseTown(self, STR_New_Kasuto)
/** `Rando_can_traverse_OldKasuto_town()` (dead in ZALiA — always needs CROSS) */
export const Rando_can_traverse_OldKasuto_town = (self: Rando): boolean =>
  canTraverseTown(self, STR_Old_Kasuto)
/** `Rando_can_traverse_Bulblin_town()` (dead in ZALiA) */
export const Rando_can_traverse_Bulblin_town = (self: Rando): boolean => canTraverseTown(self, STR_Bulblin)

// ---- passes --------------------------------------------------------------------------------------

/** `Rando_can_traverse_RauruPass()` — the boulder / River Devil next to Rauru. */
export function Rando_can_traverse_RauruPass(self: Rando): boolean {
  switch (G.Rando_RauruPass_VER) {
    case 1:
      if (Rando_is_attainable(self, STR_HAMMER)) return true
      break
    case 2:
      if (Rando_is_attainable(self, STR_FLUTE)) return true
      break
    case 3:
      if (Rando_is_attainable(self, STR_GLOVE, STR_BRACELET)) return true
      break
  }
  return false
}

/** `Rando_can_traverse_RauruToMidoroCave()` — the rando-only cave next to Rauru into Midoro Field. */
export function Rando_can_traverse_RauruToMidoroCave(self: Rando): boolean {
  return Rando_is_attainable(self, STR_GLOVE, STR_BRACELET)
}

/** `Rando_can_traverse_JUMPCave()` */
export function Rando_can_traverse_JUMPCave(self: Rando): boolean {
  if (self.ItemLocations_DARKROOM_DIFFICULTY > 0 || Rando_is_attainable(self, STR_CANDLE, STR_FIRE)) {
    if (Rando_is_attainable(self, STR_JUMP)) return true
  }
  return false
}

/** `Rando_can_traverse_DeathMtn()` */
export function Rando_can_traverse_DeathMtn(self: Rando): boolean {
  return self.ItemLocations_DARKROOM_DIFFICULTY >= 2 || Rando_is_attainable(self, STR_CANDLE, STR_FIRE)
}

/** `Rando_can_cross_SariaBridge()` */
export function Rando_can_cross_SariaBridge(self: Rando): boolean {
  if (Rando_is_attainable(self, STR_NOTE)) return true
  if (Rando_are_attainable(self, STR_JUMP, STR_FAIRY)) return true
  return false
}

/** `Rando_can_traverse_NIslMtnPass()` — North Islands mountain pass. */
export function Rando_can_traverse_NIslMtnPass(self: Rando): boolean {
  if (Rando_is_attainable(self, STR_HAMMER)) {
    if (Rando_is_attainable(self, STR_JUMP, STR_FAIRY)) return true
  }
  return false
}

/**
 * The `switch(global.Rando_RauruPass_VER)` block that opens
 * `Rando_can_reach_{MidoroField,MorugeSwamp,Saria2,RoyalCemetery,Z1Area,East}` and the `STR_Saria`/`STR_Mido`
 * cases of `Rando_is_qual_location` — identical in all eight, folded into one helper.
 */
export function Rando_can_reach_MidoroArea(self: Rando): boolean {
  switch (G.Rando_RauruPass_VER) {
    case 1:
    case 2:
      return (
        Rando_can_traverse_RauruPass(self) ||
        Rando_can_traverse_RauruToMidoroCave(self) ||
        Rando_can_traverse_JUMPCave(self)
      )
    case 3:
      return Rando_can_traverse_RauruPass(self) || Rando_can_traverse_JUMPCave(self)
  }
  return false
}

/** "Through Fire-Vines Cave, or raftway to Whale Isl → Mido" — the second half of the same eight scripts. */
export function Rando_can_reach_MidoArea(self: Rando): boolean {
  return (
    Rando_is_attainable(self, STR_FIRE) ||
    (Rando_is_attainable(self, STR_RAFT) && Rando_can_traverse_NIslMtnPass(self))
  )
}

// ---- regions -------------------------------------------------------------------------------------

/** `Rando_can_reach_RutoMtnRuins()` */
export function Rando_can_reach_RutoMtnRuins(self: Rando): boolean {
  if (Rando_is_qual_location(self, STR_Ruto)) {
    if (
      Rando_can_traverse_Ruto_town(self) && // in case Ruto is Old Kasuto and don't have CROSS
      Rando_is_attainable(self, STR_JUMP) && // Get to Ruto Mtn Lake
      Rando_is_attainable(self, STR_STABDOWN, STR_FAIRY) // Cross Ruto Mtn Lake
    ) {
      // Get through cave to bottom of ruins
      if (self.ItemLocations_DARKROOM_DIFFICULTY >= 1 || Rando_is_attainable(self, STR_CANDLE, STR_FIRE)) {
        return true
      }
    }
  }
  return false
}

/** `Rando_can_reach_MidoroField()` */
export function Rando_can_reach_MidoroField(self: Rando): boolean {
  if (Rando_can_reach_MidoroArea(self)) return true

  if (Rando_can_reach_MidoArea(self)) {
    // Mido boulder
    if (Rando_is_attainable(self, STR_HAMMER)) return true
    // Mido fast travel to Saria
    if (
      Rando_can_traverse_Mido_town(self) &&
      Rando_can_fast_travel_MidoToSaria() &&
      Rando_can_traverse_Saria_town(self)
    ) {
      return true
    }
    // Backway through Death Mtn
    if (
      Rando_can_get_from_RoyalCemeteryToZ1Area(self) &&
      Rando_can_traverse_DeathMtn(self) &&
      Rando_can_cross_SariaBridge(self) &&
      Rando_can_traverse_Saria_town(self)
    ) {
      return true
    }
  }
  return false
}

/** `Rando_can_reach_MorugeSwamp()` — identical to `Rando_can_reach_MidoroField` in ZALiA. */
export function Rando_can_reach_MorugeSwamp(self: Rando): boolean {
  return Rando_can_reach_MidoroField(self)
}

/** `Rando_can_reach_Saria2()` — Saria South Exit. */
export function Rando_can_reach_Saria2(self: Rando): boolean {
  // From Midoro/Morogue area
  if (Rando_can_reach_MidoroArea(self)) {
    // Through Saria
    if (Rando_can_traverse_Saria_town(self) && Rando_can_cross_SariaBridge(self)) return true
    // Backway through Death Mtn
    if (
      Rando_is_attainable(self, STR_HAMMER) &&
      Rando_can_get_from_RoyalCemeteryToZ1Area(self) &&
      Rando_can_traverse_DeathMtn(self)
    ) {
      return true
    }
  }

  // From Mido area
  if (Rando_can_reach_MidoArea(self)) {
    // Mido boulder
    if (
      Rando_is_attainable(self, STR_HAMMER) &&
      Rando_can_traverse_Saria_town(self) &&
      Rando_can_cross_SariaBridge(self)
    ) {
      return true
    }
    // Mido fast travel to Saria
    if (
      Rando_can_traverse_Mido_town(self) &&
      Rando_can_fast_travel_MidoToSaria() &&
      Rando_can_traverse_Saria_town(self) &&
      Rando_can_cross_SariaBridge(self)
    ) {
      return true
    }
    // Backway through Death Mtn
    if (Rando_can_get_from_RoyalCemeteryToZ1Area(self) && Rando_can_traverse_DeathMtn(self)) return true
  }
  return false
}

/** `Rando_can_reach_RoyalCemetery()` */
export function Rando_can_reach_RoyalCemetery(self: Rando): boolean {
  if (Rando_can_reach_MidoroArea(self)) {
    if (Rando_is_attainable(self, STR_HAMMER)) return true
    // Through Death Mtn
    if (
      Rando_can_traverse_Saria_town(self) &&
      Rando_can_cross_SariaBridge(self) &&
      Rando_can_traverse_DeathMtn(self)
    ) {
      return true
    }
  }
  // Raftway to Whale Isl to Mido
  if (Rando_can_reach_MidoArea(self)) return true
  return false
}

/** `Rando_can_fast_travel_MidoToSaria()` — always true in ZALiA. */
export function Rando_can_fast_travel_MidoToSaria(): boolean {
  return true
}

/** `Rando_can_get_from_RoyalCemeteryToZ1Area()` */
export function Rando_can_get_from_RoyalCemeteryToZ1Area(self: Rando): boolean {
  return (
    Rando_is_attainable(self, STR_BOOTS) ||
    self.ItemLocations_DARKROOM_DIFFICULTY >= 1 ||
    Rando_is_attainable(self, STR_CANDLE, STR_FIRE)
  )
}

/** `Rando_can_reach_Z1Area()` */
export function Rando_can_reach_Z1Area(self: Rando): boolean {
  if (Rando_can_reach_MidoroArea(self)) {
    // Midoro Field to RoyalCemetery to Z1Area
    if (Rando_is_attainable(self, STR_HAMMER)) {
      if (Rando_can_get_from_RoyalCemeteryToZ1Area(self)) return true
    }
    // Midoro Field to Saria to Death Mtn to Z1Area
    if (
      Rando_can_traverse_Saria_town(self) &&
      Rando_can_cross_SariaBridge(self) &&
      Rando_can_traverse_DeathMtn(self)
    ) {
      return true
    }
  }
  if (Rando_can_reach_MidoArea(self)) {
    if (Rando_can_get_from_RoyalCemeteryToZ1Area(self)) return true
  }
  return false
}

/** `Rando_can_reach_East()` */
export function Rando_can_reach_East(self: Rando): boolean {
  if (Rando_can_reach_MidoroArea(self)) {
    // Go through Mido Boulder Pass
    if (Rando_is_attainable(self, STR_HAMMER)) {
      if (Rando_is_attainable(self, STR_RAFT)) return true
    }
    // Go through Death Mtn from Saria
    if (
      Rando_can_traverse_Saria_town(self) &&
      Rando_can_cross_SariaBridge(self) &&
      Rando_can_traverse_DeathMtn(self)
    ) {
      if (Rando_is_attainable(self, STR_RAFT)) return true
    }
  }
  // Get to Mido through Raftway
  if (Rando_can_reach_MidoArea(self)) {
    if (Rando_is_attainable(self, STR_RAFT)) return true
  }
  return false
}

/** `Rando_can_get_in_NabooruWell()` */
export function Rando_can_get_in_NabooruWell(self: Rando): boolean {
  return Rando_are_attainable(self, STR_STABDOWN, STR_GLOVE)
}

/**
 * `Rando_can_get_from_NabooruToDaruniaField()` — always true: there is one cave in the way, but an
 * Acheman can light the torch when the player has no fire.
 */
export function Rando_can_get_from_NabooruToDaruniaField(): boolean {
  return true
}

/** `Rando_can_reach_DaruniaField()` */
export function Rando_can_reach_DaruniaField(self: Rando): boolean {
  return Rando_can_reach_East(self) && Rando_can_get_from_NabooruToDaruniaField()
}

/** `Rando_can_reach_MazeIsl()` */
export function Rando_can_reach_MazeIsl(self: Rando): boolean {
  return (
    Rando_can_reach_East(self) &&
    Rando_can_get_from_NabooruToDaruniaField() &&
    Rando_is_attainable(self, STR_STABDOWN)
  )
}

/** `Rando_can_reach_KasutoArea()` */
export function Rando_can_reach_KasutoArea(self: Rando): boolean {
  if (Rando_can_reach_East(self)) {
    // Get past River Devil
    if (Rando_is_attainable(self, STR_FLUTE)) return true
    // Through New Kasuto shortcut
    if (Rando_are_attainable(self, STR_BRACELET, STR_BOOTS)) return true
  }
  return false
}

/** `Rando_can_reach_Dragmire()` */
export function Rando_can_reach_Dragmire(self: Rando): boolean {
  return (
    Rando_can_reach_KasutoArea(self) &&
    Rando_is_attainable(self, STR_CROSS) && // VOD invisible enemies
    Rando_is_attainable(self, STR_BOOTS) && // Water path at bottom of VOD
    self.QUEST_NUM === 2 && // if have triforce for Barrier
    Rando_is_attainable(self, STR_RAFT) // VOD to Dragmire
  )
}

/** The overworld dungeon a randomized dungeon ended up in (`STR_Dungeon+STR_Rando+<name>+"A"`). */
const owDungeon = (self: Rando, name: string): string =>
  String(val(self.dm_save_data.get(STR_Dungeon + STR_Rando + name + 'A'), name))

/** Dungeon num from `g.dm_dungeon`, with the vanilla number as fallback. */
const dungeonNum = (name: string, dflt: number): number =>
  Number(val(g.dm_dungeon.get(STR_Dungeon + STR_Num + name), dflt))

/** `Rando_can_reach_CrystalHolder(dungeon name)` */
export function Rando_can_reach_CrystalHolder(self: Rando, DUNGEON_NAME: string): boolean {
  const hasAllKeysOr = (num: number, need: number): boolean =>
    Rando_is_attainable(self, STR_ALLKEY) || Rando_attainable_key_count(self, num) >= need

  switch (DUNGEON_NAME) {
    case STR_Parapa_Palace:
      if (Rando_is_qual_location(self, owDungeon(self, DUNGEON_NAME))) {
        if (self.ItemLocations_DARKROOM_DIFFICULTY >= 2 || Rando_is_attainable(self, STR_CANDLE, STR_FIRE)) {
          if (hasAllKeysOr(dungeonNum(DUNGEON_NAME, 1), 3)) return true
        }
      }
      break

    case STR_Midoro_Palace:
      if (Rando_is_qual_location(self, owDungeon(self, DUNGEON_NAME))) {
        if (Rando_is_attainable(self, STR_GLOVE)) {
          if (
            self.ItemLocations_DARKROOM_DIFFICULTY >= 2 ||
            Rando_is_attainable(self, STR_CANDLE, STR_FIRE)
          ) {
            if (hasAllKeysOr(dungeonNum(DUNGEON_NAME, 2), 4)) return true
          }
        }
      }
      break

    case STR_Island_Palace:
      if (Rando_is_qual_location(self, owDungeon(self, DUNGEON_NAME))) {
        if (Rando_is_attainable(self, STR_GLOVE) && Rando_is_attainable(self, STR_STABDOWN)) {
          // defeat Rebonack
          if (hasAllKeysOr(dungeonNum(DUNGEON_NAME, 3), 4)) return true
        }
      }
      break

    case STR_Maze_Island_Palace:
      if (Rando_is_qual_location(self, owDungeon(self, DUNGEON_NAME))) {
        if (hasAllKeysOr(dungeonNum(DUNGEON_NAME, 4), 6)) {
          if (Rando_is_attainable(self, STR_REFLECT)) return true // defeat Carock
        }
      }
      break

    case STR_Palace_On_The_Sea:
      if (Rando_is_qual_location(self, owDungeon(self, DUNGEON_NAME))) {
        if (Rando_is_attainable(self, STR_FAIRY)) {
          if (hasAllKeysOr(dungeonNum(DUNGEON_NAME, 5), 5)) return true
        }
      }
      break

    case STR_Three_Eye_Rock_Palace:
      if (Rando_is_qual_location(self, owDungeon(self, DUNGEON_NAME))) {
        if (
          Rando_is_attainable(self, STR_GLOVE) && // block wall
          Rando_are_attainable(self, STR_JUMP, STR_STABDOWN) // Dark Rebonack
        ) {
          if (hasAllKeysOr(dungeonNum(DUNGEON_NAME, 6), 6)) {
            if (Rando_is_attainable(self, STR_FAIRY)) return true // low passage to boss room
          }
        }
      }
      break
  }
  return false
}

/** `Rando_can_get_inside_P7()` — every crystal placed dispels the Great Palace barrier. */
export function Rando_can_get_inside_P7(self: Rando): boolean {
  if (Rando_is_qual_location(self, owDungeon(self, STR_Great_Palace))) {
    if (
      Rando_can_reach_CrystalHolder(self, STR_Parapa_Palace) &&
      Rando_can_reach_CrystalHolder(self, STR_Midoro_Palace) &&
      Rando_can_reach_CrystalHolder(self, STR_Island_Palace) &&
      Rando_can_reach_CrystalHolder(self, STR_Maze_Island_Palace) &&
      Rando_can_reach_CrystalHolder(self, STR_Palace_On_The_Sea) &&
      Rando_can_reach_CrystalHolder(self, STR_Three_Eye_Rock_Palace)
    ) {
      return true
    }
  }
  return false
}
