/**
 * 6502 / NES 8-bit arithmetic helpers, ported from ZALiA `scripts/math/*.gml`.
 * All inputs are masked to a byte; results are unsigned bytes unless noted.
 */

/** `adc(num1, num2, *carry)` — simulate 6502 ADD WITH CARRY (result byte only). */
export function adc(a: number, b: number, carry = 0): number {
  return ((a & 0xff) + (b & 0xff) + (carry > 0 ? 1 : 0)) & 0xff
}

/** `sbc(num1, num2, *carry)` — simulate 6502 SUBTRACT WITH CARRY (result byte only). */
export function sbc(a: number, b: number, carry = 0): number {
  return ((a & 0xff) + ((b & 0xff) ^ 0xff) + (carry > 0 ? 1 : 0)) & 0xff
}

/** `rol(byte)` — 8-bit rotate left (bit 7 wraps into bit 0). */
export function rol(v: number): number {
  return ((v << 1) | ((v & 0x80) >> 7)) & 0xff
}

/** `ror(byte)` — 8-bit rotate right (bit 0 wraps into bit 7). */
export function ror(v: number): number {
  return (((v & 0xff) >> 1) | ((v & 0x1) << 7)) & 0xff
}

/** `byte(int)` */
export function byte(v: number): number {
  return v & 0xff
}

/** `byte_to_int(byte)` — interpret a byte as signed (two's complement). */
export function byteToInt(v: number): number {
  return (v & 0xff) - ((v & 0x80) << 1)
}

/** `byte_negate(byte)` */
export function byteNegate(v: number): number {
  return ((v ^ 0xff) + 1) & 0xff
}

/** `abs8b(value)` — magnitude of a signed byte. */
export function abs8b(v: number): number {
  return v & 0x80 ? 0x100 - (v & 0xff) : v & 0xff
}

/** `sign8b(int)` — 0 for zero, -1 for negative byte, 1 otherwise. */
export function sign8b(v: number): -1 | 0 | 1 {
  if (!(v & 0xff)) return 0
  return v & 0x80 ? -1 : 1
}

/**
 * GML 1.4 truthiness: a real is true iff it is > 0.5 (so -1 is FALSE). Use for every ported
 * `if (x)` / `!x` where x may be a signed number such as a ±1 direction.
 */
export function gmBool(v: unknown): boolean {
  if (typeof v === 'boolean') return v
  if (typeof v === 'number') return v > 0.5
  if (v === undefined || v === null) return false
  // GML 1.4 errors on non-real conditions; ported code only reaches here through loosely typed
  // ds_map values that hold reals at runtime. Strings are treated as non-empty → true.
  if (typeof v === 'string') return v !== ''
  return true
}

/** `dir8b(direction)` — takes 1 (right) or -1 (left) to 1 or 2. GML: `if(!argument0) return 2; return 1;` */
export function dir8b(direction: number | boolean): 1 | 2 {
  return gmBool(direction) ? 1 : 2
}

/** `bitCount(uint)` */
export function bitCount(v: number): number {
  let n = 0
  let x = v >>> 0
  while (x !== 0) {
    n += x & 1
    x >>>= 1
  }
  return n
}

/** `bit1st(int)` — the lowest set bit as a mask, or 0. */
export function bit1st(v: number): number {
  const x = v >>> 0
  if (x === 0) return 0
  return x & -x
}

/** `isVal(base, ...compare)` — true if base equals at least one of the compare values. */
export function isVal<T>(base: T, ...compare: T[]): boolean {
  return compare.includes(base)
}

/**
 * GM 1.4 `round()` — a half goes to the nearest **even** integer (banker's rounding), where JS
 * `Math.round` takes a half up and `-0.5` toward +∞. The difference is reachable everywhere the GML
 * rounds a fraction of an integer: `round(_val * 0.25)` lands on a half for a quarter of all inputs, which
 * is how the randomizer sizes its HP/damage/spell-cost jitter windows. Lives here, the layer with no
 * dependencies, so every folder can reach it; `Game/gm.ts` re-exports it as the GM builtin.
 */
export function gmRound(v: number): number {
  const f = Math.floor(v)
  const d = v - f
  if (d > 0.5) return f + 1
  if (d < 0.5) return f
  return f % 2 === 0 ? f : f + 1
}

/**
 * GM's bitwise operators are 64-bit; JS's `&`/`|` truncate to a *signed 32-bit* int. ZALiA's item bitfield
 * reaches bit 32 (`ITEM_SPELL`), so a JS `f.items & ITEM_SPELL` is permanently 0 and a JS
 * `f.items |= ITEM_SPELL` silently drops the bit *and* truncates everything above 32 — and `ITM_WATR`
 * (bit 31) turns the whole field negative on the way. Use these wherever a mask can reach bit 31.
 * Cheap path first: below 2^31 the plain operators are already exact.
 */
const BIT31 = 0x8000_0000
export function gmAnd(a: number, b: number): number {
  if (a >= 0 && b >= 0 && a < BIT31 && b < BIT31) return a & b
  return Number(BigInt(Math.trunc(a)) & BigInt(Math.trunc(b)))
}
export function gmOr(a: number, b: number): number {
  if (a >= 0 && b >= 0 && a < BIT31 && b < BIT31) return a | b
  return Number(BigInt(Math.trunc(a)) | BigInt(Math.trunc(b)))
}
