/** Thin shim over the `@z2/data` GM resource-index manifest (`pnpm tool gm-index`); kept for the niao imports. */
import { GM_OBJECT_NAMES, GM_SCRIPT_NAMES, GM_SPRITE_NAMES } from '@z2/data'

export { GM_OBJECT_NAMES, GM_SCRIPT_NAMES, GM_SPRITE_NAMES }
export const gmScriptName = (i: number): string | undefined => GM_SCRIPT_NAMES[i]
export const gmSpriteName = (i: number): string | undefined => GM_SPRITE_NAMES[i]
export const gmObjectName = (i: number): string | undefined => GM_OBJECT_NAMES[i]
