/** GM colour constants used by the debug draws — `$BBGGRR`, converted by the draw wrappers (see rooms/draw.ts). */
export const c_black = 0x000000
export const c_white = 0xffffff
export const c_lime = 0x00ff00
export const c_purple = 0x800080
export const c_orange = 0x40a0ff // GM $BBGGRR: orange = 255,160,64

/** `draw_rect(color, x, y, w, h)` — light-weight solid rectangle. */
export function draw_rect(color: number, x: number, y: number, w: number, h: number): void {
  draw_rect_(color, x, y, w, h, 1, false)
}

/** `draw_circ_(color, x, y, radius, *alpha, *outline)` */
export function draw_circ_(
  color: number,
  x: number,
  y: number,
  radius: number,
  alpha = 1,
  outline: boolean | number = false,
): void {
  pushCmd({
    kind: 'circle',
    x: x - 1,
    y: y - 1,
    radius,
    color: bgrToRgb(color),
    alpha,
    outline: !!outline,
    depth: drawState.depth,
  })
}

/** `drawPointCross(x, y, *cross color, *point color)` — debug cross centred on the point. */
export function drawPointCross(x: number, y: number, crossColor = c_lime, pointColor = c_purple): void {
  const _cross = bgrToRgb(crossColor)
  pushCmd({ kind: 'line', x1: x, y1: y - 3, x2: x, y2: y + 2, color: _cross, depth: drawState.depth }) // vertical
  pushCmd({ kind: 'line', x1: x - 3, y1: y, x2: x + 2, y2: y, color: _cross, depth: drawState.depth }) // horizontal
  pushCmd({ kind: 'point', x, y, color: bgrToRgb(pointColor), depth: drawState.depth })
}

/** `drawSprOutline(sprite x, sprite y, sprite, color, *alpha)` — outline of the sprite's full frame. */
export function drawSprOutline(x: number, y: number, sprite: string, color: number, alpha = 0.4): void {
  const _x = x - sprite_get_xoffset(sprite)
  const _y = y - sprite_get_yoffset(sprite)
  draw_rect_(color, _x, _y, sprite_get_width(sprite), sprite_get_height(sprite), alpha, true)
}

/** `draw_sprite_index_outline()` — for an instance with x/y/sprite_index. */
export function draw_sprite_index_outline(self: { x: number; y: number; sprite_index: string }): void {
  drawSprOutline(self.x, self.y, self.sprite_index, c_orange, 1)
}

/**
 * `draw_sprite_part_(sprite, sub image, left, top, width, height, x, y, *pal index, *xscale, *yscale, *color, *alpha)`
 */
export function draw_sprite_part_(
  sprite: string | 0 | undefined,
  subimg: number,
  left: number,
  top: number,
  width: number,
  height: number,
  x: number,
  y: number,
  palIdx?: number,
  xscale = 1,
  yscale = 1,
  color = -1,
  alpha = 1,
): void {
  if (!sprite) return // !!!!!!!!!!!!!!!!!!!!!!
  const _IS_PAL_SWAP =
    palIdx !== undefined && palIdx > 0.5 && (G.palette_image_w === undefined || palIdx < G.palette_image_w)
  if (_IS_PAL_SWAP) pal_swap_set(palIdx as number) // Won't run if _palidx is out of range
  pushCmd({
    kind: 'spritePart',
    sprite,
    frame: subimg,
    left,
    top,
    width,
    height,
    x,
    y,
    xscale,
    yscale,
    palIdx: _IS_PAL_SWAP ? (palIdx as number) : -1,
    depth: drawState.depth,
    alpha,
    ...(color >= 0 ? { tint: bgrToRgb(color) } : {}),
  })
  if (_IS_PAL_SWAP) pal_swap_reset()
}

/** `draw_background_part_ext_(palidx, bg, bg_x,bg_y, w,h, x,y, xscale,yscale)` — palette-swapped tileset part. */
export function draw_background_part_ext_(
  palidx: number,
  bg: string,
  bgX: number,
  bgY: number,
  w: number,
  h: number,
  x: number,
  y: number,
  xscale: number,
  yscale: number,
): void {
  pal_swap_set(palidx)
  pushCmd({
    kind: 'tile',
    tileset: bg,
    left: bgX,
    top: bgY,
    w,
    h,
    x,
    y,
    xscale,
    yscale,
    palIdx: palidx,
    depth: drawState.depth,
    alpha: 1,
  })
  pal_swap_reset()
}

/** Border frame of a menu window from `ts_Menu01` ($20 horizontal, $21 vertical, $22 corner). */
function drawMenuFrame(XL0: number, YT0: number, CLMS: number, ROWS: number): void {
  for (let _i = 0; _i < ROWS; _i++) {
    for (let _j = 0; _j < CLMS; _j++) {
      let _type = +(!_i || _i === ROWS - 1)
      _type |= +(!_j || _j === CLMS - 1) << 1
      if (!_type) continue
      const _xl = XL0 + (_j << 3)
      const _yt = YT0 + (_i << 3)
      // tsrc: $20: horizontal, $21: vertical, $22: corner
      draw_background_part_ext_(G.PI_GUI1, 'ts_Menu01', (_type - 1) << 3, 0x2 << 3, 8, 8, _xl, _yt, 1, 1)
    }
  }
}

/** `draw_key_stats()` — dev/rando overlay: per-palace key counts. */
export function draw_key_stats(): void {
  const _DUNGEON_COUNT = 6
  const _CLMS = 0xe
  const _XL0 = viewXL() + (0x06 << 3)
  const _XL1 = _XL0 + (0x01 << 3)
  const _YDIST1 = 0xc
  const _YT0 = viewYT() + (0x06 << 3)
  const _YT1 = _YT0 + (0x01 << 3)
  const _YT2 = _YT1 + 0x10
  let _H = 0x20 + _DUNGEON_COUNT * _YDIST1
  _H += Math.sign(_H & 0x7) << 3
  const _ROWS = _H >> 3
  draw_sprite_('spr_1x1_WHT', 0, _XL0, _YT0, -1, _CLMS << 3, _H, c_black)
  drawMenuFrame(_XL0, _YT0, _CLMS, _ROWS)
  //    "--- KEYS ---"
  //    "P6  6-3 1-2"
  //    "P6  max-acquired used-unused"
  draw_text_(_XL1, _YT1, '--- KEYS ---', -1, G.PI_GUI1)
  let _yt = _YT2
  for (let _i = 1; _i <= _DUNGEON_COUNT; _i++) {
    let _xl = _XL1
    let _text = `P${_i}`
    draw_text_(_xl, _yt, _text, -1, G.PI_GUI1)
    _xl += _text.length << 3
    _xl += 0x10
    _text = String(get_key_count_acquired(_i))
    draw_text_(_xl, _yt, _text, -1, G.PI_GUI1)
    _xl += _text.length << 3
    draw_sprite_('spr_text_slash_forward', 0, _xl, _yt, G.PI_GUI1)
    _xl += 0x8
    const _count = val(g.dm_spawn.get(STR_Dungeon + hex_str(_i) + STR_Key + STR_Count))
    _text = String(_count)
    draw_text_(_xl, _yt, _text, -1, G.PI_GUI1)
    _xl += _text.length << 3
    _xl += 0x10
    draw_sprite_('spr_Key_icon', 0, _xl + 4, _yt + 4, G.PI_GUI1)
    _xl += 0x8
    draw_text_(_xl, _yt, '*', -1, G.PI_GUI1)
    _xl += 0x8
    _text = String(get_key_count(_i))
    draw_text_(_xl, _yt, _text, -1, G.PI_GUI1)
    _yt += _YDIST1
  }
}

/** `draw_rando_hints()` — the found-hints window next to the pause menu. */
export function draw_rando_hints(): void {
  const rec = g.dm_RandoHintsRecorder
  const _FOUND_NUMS = String(val(rec.get(STR_Found + STR_Hint + STR_Num), ''))
  const _pi = G.PI_GUI2
  add_pi_permut(_pi, 'RBWGMKYC', 'draw_rando_hints() dark text 1') // _PI_FOUND1 (registered, unused in ZALiA too)
  const _FOUND_COUNT = _FOUND_NUMS.length >> 1
  const _HEADER_TEXT = '--- HINTS ---'
  const _CLMS = g.RandoHintsRecorder_W >> 3
  let _XL0 = get_menu_x() - (0x01 << 3) - g.RandoHintsRecorder_W
  _XL0 = Math.max(_XL0, viewXL() + (0x01 << 3))
  _XL0 = (_XL0 >> 3) << 3
  const _XL1 = _XL0 + (0x01 << 3) + 2
  const _YT0 = viewYT() + (g.PAUSE_MENU as { Y_BASE: number }).Y_BASE // window yt
  const _YT1 = _YT0 + (0x01 << 3) // header yt
  const _YT2 = _YT1 + 0x8 + 3 // hints yt
  const _DIST1 = g.RandoHintsRecorder_Font_CHAR_SIZE + 2
  const _count = Math.max(_FOUND_COUNT, 1)
  let _H = 0x8 << 1 // borders
  _H += 0x8 // header text
  _H += 0x2 << 1 // top & bottom padding
  _H += _count * g.RandoHintsRecorder_Font_CHAR_SIZE
  _H += (_count - 1) * 2 // leading
  _H = (Math.trunc(_H / 8) << 3) + (Math.sign(_H % 8) << 3) // round up to 8
  const _ROWS = _H >> 3
  draw_sprite_('spr_1x1_WHT', 0, _XL0, _YT0, -1, g.RandoHintsRecorder_W, _H, c_black)
  drawMenuFrame(_XL0, _YT0, _CLMS, _ROWS)
  let _xl = _XL0 + ((_CLMS << 3) >> 1)
  _xl -= (_HEADER_TEXT.length << 3) >> 1
  draw_text_(_xl, _YT1, _HEADER_TEXT, G.dl_game_font.get(G.game_font_idx) as string, G.PI_GUI1)
  if (!_FOUND_COUNT) {
    draw_text_(_XL1, _YT2, 'NO HINTS FOUND YET!', g.RandoHintsRecorder_Font_SPRITE, G.PI_GUI1)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  let _yt = _YT2
  for (let _i = 0; _i < _FOUND_COUNT; _i++) {
    const _num_ = _FOUND_NUMS.substr(_i << 1, 2)
    const _item = rec.get(STR_Hint + _num_ + STR_Item)
    if (_item !== undefined) {
      const _item_found = val(rec.get(STR_Hint + _num_ + STR_Item + STR_Found))
      _xl = _XL1
      let _text = String(val(rec.get(`${STR_Hint + _num_ + STR_Text}01`), 'UNDEFINED'))
      draw_text_(_xl, _yt, _text, g.RandoHintsRecorder_Font_SPRITE, -1, _item_found ? p.C_GRY3 : p.C_WHT1)
      _xl += _text.length * g.RandoHintsRecorder_Font_CHAR_SIZE
      _text = String(val(rec.get(STR_Hint + _num_ + STR_Item), 'UNDEFINED')).replace(/[^A-Za-z]/g, '')
      draw_text_(_xl, _yt, _text, g.RandoHintsRecorder_Font_SPRITE, -1, _item_found ? p.C_GRY2 : p.C_GRN2)
      _xl += _text.length * g.RandoHintsRecorder_Font_CHAR_SIZE
      _text = String(val(rec.get(`${STR_Hint + _num_ + STR_Text}02`), 'UNDEFINED'))
      draw_text_(_xl, _yt, _text, g.RandoHintsRecorder_Font_SPRITE, -1, _item_found ? p.C_GRY3 : p.C_WHT1)
      _yt += _DIST1
    }
  }
}

/**
 * `Surface_Draw_End()` — the Surface object's Draw End event, i.e. everything GM draws *after* every
 * instance and screen: the falling-scene transition, the wide-view side masks, and the two randomizer
 * overlays. The Surface object itself is adapter work (application surface, screen shake, post-FX), so
 * only its game-logic half lives here; `frameHooks.Surface_Draw_End` calls it at the end of the frame.
 *
 * The F3/F4 gates are resolved here rather than in a Step: GML sets `can_draw_keys`/`can_draw_hints` in
 * `Surface_Step.gml:130-155` and reads them in this event of the same frame, and nothing in between can
 * change the keyboard or the settings.
 */
export function Surface_Draw_End(): void {
  const _depth_prev = drawState.depth
  drawState.depth = DEPTH_BASE_SURFACE // the Surface object's own depth: on top of everything
  if (g.FallScene_timer > 2) draw_falling_scene(DEPTH_BASE_SURFACE)
  if (gmBool(g.MaskWideView) && g.MaskWideView_w > 0) {
    // The black bars that narrow a wide view back to the original game's width.
    draw_sprite_('spr_1x1_WHT', 0, viewXL(), viewYT(), -1, g.MaskWideView_w, viewH(), p.C_BLK1)
    draw_sprite_(
      'spr_1x1_WHT',
      0,
      viewXR() - g.MaskWideView_w,
      viewYT(),
      -1,
      g.MaskWideView_w,
      viewH(),
      p.C_BLK1,
    )
  }
  // GUI: the randomizer key-stat and hint windows, held open with F4 / F3 (or the pad's Y / B) while the
  // pause menu is open on a page other than the map.
  let canDrawKeys = false
  let canDrawHints = false
  if (
    g.room_type === 'A' &&
    g.gui_state === g.gui_state_PAUSE &&
    (g.PAUSE_MENU as { state: number; state_MAP: number } | 0) !== 0 &&
    ((g.PAUSE_MENU as { state: number }).state & 0x3) !== (g.PAUSE_MENU as { state_MAP: number }).state_MAP
  ) {
    const _KEYS_REQUESTED = keyboard_check('F4') || gmBool(input.GP_Other2_held)
    const _HINT_REQUESTED = keyboard_check('F3') || gmBool(input.GP_Other1_held)
    if (
      _KEYS_REQUESTED &&
      !_HINT_REQUESTED &&
      gmBool(val(G.dm_save_file_settings.get(STR_Randomize + STR_Key + STR_Locations)))
    )
      canDrawKeys = true
    if (
      _HINT_REQUESTED &&
      !_KEYS_REQUESTED &&
      gmBool(G.RandoHints_enabled) &&
      gmBool(val(G.dm_save_file_settings.get(STR_Randomize + STR_Item + STR_Locations)))
    )
      canDrawHints = true
  }
  g.RandoKeys_can_draw_key_stats = canDrawKeys
  g.RandoHintsRecorder_can_draw = canDrawHints
  if (canDrawKeys) draw_key_stats()
  if (canDrawHints) draw_rando_hints()
  drawState.depth = _depth_prev
}
