import { DsMap } from '../../runtime/ds'

export type GmJsonValue = number | string
export type GmJsonObject = Record<string, GmJsonValue>

/** GM stores booleans as reals; keep the on-disk schema numeric. */
export const gmNum = (v: number | boolean): number => (typeof v === 'boolean' ? (v ? 1 : 0) : v)

/** `json_encode(ds_map)` */
export function json_encode(m: DsMap<GmJsonValue> | Map<string, GmJsonValue>): string {
  return JSON.stringify(Object.fromEntries(m))
}

/** `json_decode(str)` → DsMap, or `-1` on failure (GML contract). */
export function json_decode(s: string | number | undefined): DsMap<GmJsonValue> | -1 {
  if (typeof s !== 'string') return -1
  try {
    const obj: unknown = JSON.parse(s)
    if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) return -1
    const m = new DsMap<GmJsonValue>()
    for (const [k, v] of Object.entries(obj as Record<string, unknown>)) {
      if (typeof v === 'number' || typeof v === 'string') m.set(k, v)
      else if (typeof v === 'boolean') m.set(k, v ? 1 : 0)
      else if (v !== null && typeof v === 'object') m.set(k, JSON.stringify(v))
    }
    return m
  } catch {
    return -1
  }
}

/** `ds_map_copy(dst, src)` */
export function ds_map_copy<V>(dst: DsMap<V>, src: Map<string, V>): void {
  dst.clear()
  for (const [k, v] of src) dst.set(k, v)
}

/** Replace `dst` contents with the decoded map when decoding succeeds; else leave it cleared (GML semantics). */
export function fillFromJson(dst: DsMap<GmJsonValue>, encoded: GmJsonValue | undefined): boolean {
  dst.clear()
  const m = json_decode(encoded)
  if (m === -1) return false
  for (const [k, v] of m) dst.set(k, v)
  return true
}
