/**
 * NES sub-pixel movement and position setters (scripts/game_object/go): updateX, updateY, updateY2, set_xy,
 * set_xlyt, set_xy_len_ang, set_hspd_dir, set_vspd_dir, update_draw_xy, GO_udp_1, GO_vspd_update1.
 */

import { gmRound as round } from '../../../nes/math8'
import type { GameObject } from '../classes'

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v))

/**
 * `updateX()` — hspd is an NES byte: high nibble whole pixels (signed), low nibble 1/16 sub-pixels
 * accumulated in hspd_sub. Returns whether the sub-pixel carry overflowed.
 */
export function updateX(self: GameObject): boolean {
  if (!self.hspd) {
    self.hspd = (self.hspd + self.hspd_grav) & 0xff
    return false
  }
  let _hspd_sub_CARRY = 0
  if (self.hspd & 0xf) {
    self.hspd_sub += (self.hspd & 0xf) << 4
    _hspd_sub_CARRY = self.hspd_sub > 0xff ? 1 : 0
    self.hspd_sub &= 0xff
  }
  let _HSPD = self.hspd >> 4
  if (self.hspd & 0x80) _HSPD |= 0xf0
  let _X_CHANGE = (_HSPD + _hspd_sub_CARRY) & 0xff
  _X_CHANGE -= (_X_CHANGE & 0x80) << 1
  if (_X_CHANGE !== 0) {
    set_xy(self, self.x + _X_CHANGE, self.y)
    self.x_change += _X_CHANGE
  }
  const _HSPD_PREV = self.hspd
  self.hspd = (self.hspd + self.hspd_grav) & 0xff
  if (Math.abs(self.hspd_grav)) {
    // 2023/06/03. Prevent potential springing back and forth
    if (self.hspd_grav < 0 && _HSPD_PREV & 0x80) self.hspd = clamp(self.hspd, 0x80, 0xff)
    if (self.hspd_grav > 0 && _HSPD_PREV < 0x80) self.hspd = clamp(self.hspd, 0x00, 0x7f)
  }
  return _HSPD + _hspd_sub_CARRY > 0xff
}

/** `updateY()` — same scheme vertically. D247, D249 */
export function updateY(self: GameObject): boolean {
  if (!self.vspd) {
    self.vspd = (self.vspd + self.vspd_grav) & 0xff
    return false
  }
  let _vspd_sub_CARRY = 0
  if (self.vspd & 0xf) {
    self.vspd_sub += (self.vspd & 0xf) << 4
    _vspd_sub_CARRY = self.vspd_sub > 0xff ? 1 : 0
    self.vspd_sub &= 0xff
  }
  let _VSPD = self.vspd >> 4
  if (self.vspd & 0x80) _VSPD |= 0xf0
  let _Y_CHANGE = (_VSPD + _vspd_sub_CARRY) & 0xff
  _Y_CHANGE -= (_Y_CHANGE & 0x80) << 1
  if (_Y_CHANGE !== 0) {
    set_xy(self, self.x, self.y + _Y_CHANGE)
    self.y_change += _Y_CHANGE
  }
  const _VSPD_PREV = self.vspd
  self.vspd = (self.vspd + self.vspd_grav) & 0xff
  if (Math.abs(self.vspd_grav)) {
    // 2023/06/03. Prevent springing up and down in midair in tall rooms
    if (self.vspd_grav < 0 && _VSPD_PREV & 0x80) self.vspd = clamp(self.vspd, 0x80, 0xff)
    if (self.vspd_grav > 0 && _VSPD_PREV < 0x80) self.vspd = clamp(self.vspd, 0x00, 0x7f)
  }
  // D247, D249
  return _VSPD + _vspd_sub_CARRY > 0xff
}

/** `updateY2(gravity add, terminal velocity)` — D19B. vspd is whole pixels; vspd_grav is the sub-pixel accumulator. */
export function updateY2(self: GameObject, gravityAdd: number, terminalVelocity: number): void {
  const _Y_CHANGE = self.vspd - ((self.vspd & 0x80) << 1)
  set_xy(self, self.x, self.y + _Y_CHANGE)
  self.y_change += _Y_CHANGE
  self.vspd_grav += gravityAdd
  self.vspd += self.vspd_grav > 0xff ? 1 : 0
  self.vspd_grav &= 0xff
  self.vspd &= 0xff
  if (self.vspd < 0x80 && self.vspd >= terminalVelocity) {
    self.vspd_grav = 0
  }
}

/** `set_xy(id, new x, new y)` — moves the instance and refreshes xl/xc/xr/yt/yc/yb from the placement sprite. */
export function set_xy(inst: GameObject, newX: number, newY: number): void {
  if (inst.x !== newX) inst.x_change_dir = Math.sign(newX - inst.x)
  if (inst.y !== newY) inst.y_change_dir = Math.sign(newY - inst.y)
  inst.x = newX
  inst.y = newY
  inst.xl = inst.x - inst.sprite_index_xoff
  inst.yt = inst.y - inst.sprite_index_yoff
  inst.xc = inst.xl + inst.ww_
  inst.xr = inst.xl + inst.ww
  inst.yc = inst.yt + inst.hh_
  inst.yb = inst.yt + inst.hh
}

/** `set_xlyt(id, new XL, new YT)` */
export function set_xlyt(inst: GameObject, newXL: number, newYT: number): void {
  set_xy(inst, newXL + inst.sprite_index_xoff, newYT + inst.sprite_index_yoff)
}

/** `set_xy_len_ang(instance id, start x, start y, length, angle)` — GM lengthdir (degrees, y up is negative). */
export function set_xy_len_ang(
  inst: GameObject,
  startX: number,
  startY: number,
  len: number,
  angleDeg: number,
): void {
  const rad = (angleDeg * Math.PI) / 180
  set_xy(inst, startX + round(len * Math.cos(rad)), startY + round(-len * Math.sin(rad)))
}

/** `set_hspd_dir()` */
export function set_hspd_dir(self: GameObject): void {
  if (self.hspd) self.hspd_dir = self.hspd & 0x80 ? -1 : 1
}

/** `set_vspd_dir()` */
export function set_vspd_dir(self: GameObject): void {
  if (self.vspd) self.vspd_dir = self.vspd & 0x80 ? -1 : 1
}

/** `update_draw_xy()` */
export function update_draw_xy(self: GameObject): void {
  self.drawX = self.x + self.DRAW_XOFF + self.draw_xoff
  self.drawY = self.y + self.DRAW_YOFF + self.draw_yoff
}

/** `GO_udp_1()` — drawX=x; drawY=y; xScale=facing_dir */
export function GO_udp_1(self: GameObject): void {
  self.drawX = self.x
  self.drawY = self.y
  self.xScale = self.facing_dir
}

/** `GO_vspd_update1()` — stop upward vspd when the top is colliding. */
export function GO_vspd_update1(self: GameObject): void {
  if (self.cs & 0x8 && self.vspd & 0x80) self.vspd = 0x0
}
