import { G, g } from '../../runtime/world'

/** One tile of an animation frame: the datakeys `tile_anim_change_frame` reads (`hex(i)+STR_Depth`, …). */
export type TileAnimFrame = Record<string, number | string>

export const TS = {
  MANMADE_1A: 'ts_Man_made_1a_WRB',
  MANMADE_6A: 'ts_Man_made_6a_WRB',
  MANMADE_7A: 'ts_Man_made_7a_WRB',
  MANMADE_8A: 'ts_Man_made_8a_HMS',
  SOLID_COLORS: 'ts_SolidColors01_8x8',
  WALLSTYLE01: 'ts_WallStyle01_01',
  ANIM0301: 'ts_Animation0301',
  ANIM030101: 'ts_Animation030101',
  ANIM030102: 'ts_Animation030102',
  ANIM030103: 'ts_Animation030103',
  ANIM0401: 'ts_Animation0401',
} as const

const TSRC_EMPTY1_A = '00' + '00' + '00' + '00'
const hexPair = (s: string, i: number) => Number.parseInt(s.substr(i << 1, 2), 16) // str_hex(string_copy(s,(i<<1)+1,2))

/** Builds one animation's frames exactly like the repeated blocks in tile_data_init.gml. */
class AnimBuilder {
  cues = ''
  cue = 1
  readonly rcOff = [0x0000, 0x0001, 0x0100, 0x0101]
  depth: number[]
  ts: (string | 0)[]
  solid: number[]
  unique: number[]
  hide: string
  private lastTsrc = TSRC_EMPTY1_A
  constructor(
    readonly animKey: string,
    ts: string,
    solid: number,
    unique: number,
    hide: string,
  ) {
    const n = this.rcOff.length
    this.depth = new Array<number>(n).fill(-1) // -1: use depth of placed tile
    this.ts = new Array<string | 0>(n).fill(ts)
    this.solid = new Array<number>(n).fill(solid)
    this.unique = new Array<number>(n).fill(unique)
    this.hide = hide
  }
  setAll(field: 'ts' | 'solid' | 'unique', v: string | number): void {
    for (let i = 0; i < this.rcOff.length; i++) (this[field] as (string | number)[])[i] = v
  }
  /** Emit a frame with the given tsrc string (or the previous one). */
  frame(tsrc: string = this.lastTsrc): void {
    this.lastTsrc = tsrc
    const data: TileAnimFrame = {}
    for (let i = 0; i < this.rcOff.length; i++) {
      const dk = hex_str(i)
      data[dk + STR_Depth] = this.depth[i] as number
      data[dk + STR_rc_offset] = this.rcOff[i] as number
      data[dk + STR_Tileset] = this.ts[i] as string | 0
      data[dk + STR_Solid] = this.solid[i] as number
      data[dk + STR_unique] = this.unique[i] as number
      data[dk + STR_HIDDEN] = hexPair(this.hide, i)
      data[dk + STR_TSRC] = hexPair(tsrc, i)
    }
    this.cues += hex_str(this.cue)
    g.dm_tile.set(`${this.animKey}${STR_frame}${hex_str(this.cues.length >> 1)}`, data)
  }
  finish(loop = 0xff): void {
    g.dm_tile.set(this.animKey + STR_Sequence, this.cues) // cue string
    g.dm_tile.set(this.animKey + STR_Anim + STR_Loop, loop) // loop type
  }
}

/** `tile_data_init()` — fills `g.dm_tile`, `g.dm_TILE_ANIM`, `global.WallStyle0*_dm`. */
export function tile_data_init(): void {
  // TN: Tile Name. Tile names that are commonly written in code
  const TN = ['94', '95', '96', '97', '98'] // crumble bridge/block last frame, block 1a/1b, bridge 1a/1b
  // Tiles that aren't drawn due to certain conditions. Bits of the stored value determine what hides the tile:
  // 1: Hidden if room is NOT lit, 2: Hidden if room IS lit
  const _HIDE1 = TID_HIDE_1 & 0xf
  for (const tn of TN) g.dm_tile.set(STR_Tile_Hidden + tn, _HIDE1)
  for (const area of [
    Area_WestA,
    Area_EastA,
    Area_DthMt,
    Area_MazIs,
    Area_PalcA,
    Area_PalcB,
    Area_PalcC,
    Area_PalcD,
    Area_PalcE,
    Area_PalcF,
    Area_PalcG,
    Area_TownA,
    Area_TownB,
  ])
    for (const tn of TN) g.dm_tile.set(STR_Tile_Hidden + area + tn, _HIDE1)
  void TID_HIDE_2 // _HIDE2 is defined but unused in the GML

  const hide1x4 = hex_str(TID_HIDE_1 & 0xf).repeat(4) // '01010101'
  const hide0x4 = '00000000'

  // Crumble Bridge ------------------------------------
  let b = new AnimBuilder(STR_Anim + hex_str(TID_BREAK2), TS.MANMADE_1A, TID_SOLID1, 0x00, hide1x4)
  b.setAll('unique', TID_BREAK2)
  b.frame(TSRC_BREAK2_A) // Frame 1 (Reset). Unbroken.
  b.cue += 1
  b.setAll('unique', 0)
  b.frame(TSRC_BREAK2_A) // Frame 2 Unbroken.
  b.cue += 6
  b.frame(TSRC_BREAK2_B) // Frame 3 Cracked
  b.cue += 0x10
  b.frame(TSRC_BREAK1_C) // Frame 4 Dust
  b.cue += 9
  b.setAll('solid', 0)
  b.frame() // Frame 5. Dust. Only change solid
  b.cue += 7
  b.setAll('ts', 0) // 0 means remove room tile
  b.hide = hide0x4 // 0 means remove any hide properties
  b.frame(TSRC_EMPTY1_A) // Frame 6
  b.cue += 9
  b.frame() // Frame 7 (End)
  b.finish()

  // Regenerating Crumble Bridge ------------------------------------ (_CRUMBLE_FLOOR_REGEN_VER = 2)
  b = new AnimBuilder(STR_Anim + hex_str(TID_BREAK4), TS.MANMADE_1A, TID_SOLID1, 0x00, hide1x4)
  b.setAll('unique', TID_BREAK4)
  b.frame(TSRC_BREAK4_A) // Frame 1 (Reset). Unbroken.
  b.cue += 1
  b.setAll('unique', 0)
  b.frame(TSRC_BREAK4_A) // Frame 2 Unbroken.
  b.cue += 6
  b.frame(TSRC_BREAK4_B) // Frame 3 Cracked
  b.cue += 0x10
  b.frame(TSRC_BREAK4_C) // Frame 4 Shrinking object
  b.cue += 9
  b.setAll('solid', 0)
  b.frame() // Frame 5. Only change solid
  b.cue += 7
  b.frame(TSRC_BREAK4_D) // Frame 6 Small object
  b.cue += 0x40 // Regen delay. About 2 seconds
  b.frame() // Frame 7 (End)
  b.finish()

  // Breakable Block ------------------------------------
  b = new AnimBuilder(STR_Anim + hex_str(TID_BREAK1), TS.MANMADE_1A, TID_SOLID1, TID_BREAK1, hide1x4)
  b.frame(TSRC_BREAK1_A) // Frame 1 (Reset). Unbroken
  b.cue += 1
  b.setAll('solid', 0)
  b.setAll('unique', 0)
  b.frame(TSRC_BREAK1_B) // Frame 2 Cracked
  b.cue += 8
  b.frame(TSRC_BREAK1_C) // Frame 3. Dust
  b.cue += 8
  b.setAll('ts', 0)
  b.hide = hide0x4
  b.frame(TSRC_EMPTY1_A) // Frame 4
  b.cue += 1
  b.frame() // Frame 5 (End)
  b.finish()

  // Regenerating Breakable Block ------------------------------------
  b = new AnimBuilder(STR_Anim + hex_str(TID_BREAK3), TS.MANMADE_7A, TID_SOLID1, TID_BREAK3, hide1x4)
  b.frame(TSRC_BREAK3_A) // Frame 1 (Reset). Unbroken
  b.cue += 1
  b.setAll('solid', 0)
  b.setAll('unique', 0)
  b.frame(TSRC_BREAK3_B) // Frame 2 Cracked
  b.cue += 8
  b.setAll('ts', TS.MANMADE_1A)
  b.frame(TSRC_BREAK1_C) // Frame 3. Dust
  b.cue += 8
  b.setAll('ts', 0)
  b.hide = hide0x4
  b.frame(TSRC_EMPTY1_A) // Frame 4
  b.cue += 0x80 // Regen delay. About 2 seconds
  b.setAll('ts', TS.MANMADE_1A)
  b.hide = hide1x4
  b.frame(TSRC_BREAK1_C) // Frame 5. Dust
  b.cue += 8
  b.setAll('ts', TS.MANMADE_7A)
  b.frame(TSRC_BREAK3_B) // Frame 6 Cracked
  b.cue += 5
  b.setAll('solid', TID_SOLID1)
  b.setAll('unique', TID_BREAK3)
  b.frame(TSRC_BREAK3_A) // Frame 7 Unbroken
  b.cue += 1
  b.frame() // Frame 8 (End)
  b.finish()

  // Background tile animation data
  tile_data_init_1()

  wallStyleTables()
}

/**
 * `tile_data_init_1()` — animated tilesets. A container tileset (`ts_Animation0301`) is re-pointed
 * (`background_assign`) to one of its frame tilesets every game frame by `update_tile_anims`.
 */
export function tile_data_init_1(): void {
  g.BackgroundTileAnimations_VER = 1
  if (!g.BackgroundTileAnimations_VER) return
  g.dm_TILE_ANIM = new DsMap<number | string>()
  g.dl_scene_anims.clear() // Tile animations in the current scene.
  let num = 0
  const addAnim = (ts: string, frames: [duration: number, tileset: string][]) => {
    const dm = g.dm_TILE_ANIM as DsMap<number | string>
    const tsName = ts
    dm.set(STR_Anim + STR_Count, ++num)
    dm.set(`${STR_Anim}${hex_str(num)}${STR_Tileset}${STR_Name}`, tsName)
    dm.set(tsName + STR_Tileset, ts)
    dm.set(tsName + STR_Anim + STR_Num, num)
    dm.set(tsName + STR_Loop, -1) // Number of times anim will play. -1: play forever
    dm.set(tsName + STR_Frame + STR_Count, frames.length)
    for (let i = 0; i < frames.length; i++) {
      const [duration, frameTs] = frames[i] as [number, string]
      const dk3 = `${tsName}${STR_Frame}${hex_str(i + 1)}`
      dm.set(dk3 + STR_Tileset, frameTs)
      dm.set(dk3 + STR_Duration, duration)
      const cue = dm.val(tsName + STR_Duration) as number
      dm.set(dk3 + STR_Cue, cue)
      dm.set(`${tsName}${STR_Cue}${hex_str(cue)}${STR_Frame}${STR_Num}`, i + 1)
      dm.set(`${tsName}${STR_Cue}${hex_str(cue)}${STR_Frame}${STR_Datakey}`, dk3)
      dm.set(tsName + STR_Duration, (dm.val(tsName + STR_Duration) as number) + duration)
    }
  }
  addAnim(TS.ANIM0301, [
    [0x08, TS.ANIM030101],
    [0x08, TS.ANIM030102],
    [0x08, TS.ANIM030103],
  ])
  addAnim(TS.ANIM0401, [
    [0x08, TS.ANIM030101],
    [0x08, TS.ANIM030102],
    [0x08, TS.ANIM030103],
    [0x08, TS.ANIM030102],
  ])
}

/** `global.WallStyle02_dm` / `WallStyle01_dm` — wall-part → tileset index<<8 | tsrc tables. */
function wallStyleTables(): void {
  const idx = (ts: string) => g.dl_tileset.findIndex(ts)
  const _TS_IDX1 = idx(TS.MANMADE_6A)
  const _TS_IDX2 = idx(TS.MANMADE_7A)
  const _TS_IDX3 = idx(TS.MANMADE_8A)
  void idx(TS.SOLID_COLORS) // _TS_IDX4: only used by the dropped alternative table
  const w2 = new DsMap<number | string>()
  G.WallStyle02_dm = w2
  const thin = (part: string, wall: string, ts: number, tsrc: number) =>
    w2.set(`${STR_TSRC}_Thin${STR_Part}${part}${STR_Wall}${wall}`, (ts << 8) | tsrc)
  const full = (part: string, wall: string, ts: number, tsrc: number) =>
    w2.set(`${STR_TSRC}${STR_Part}${part}${STR_Wall}${wall}`, (ts << 8) | tsrc)
  // Single(1x1)
  thin('00', '05', _TS_IDX2, 0xb8)
  thin('00', '09', _TS_IDX2, 0xba)
  thin('00', '06', _TS_IDX2, 0xb9)
  thin('00', '0A', _TS_IDX2, 0xbb)
  thin('00', '01', _TS_IDX2, 0xbf)
  thin('00', '02', _TS_IDX2, 0xbd)
  thin('00', '04', _TS_IDX2, 0xbc)
  thin('00', '08', _TS_IDX2, 0xbe)
  thin('00', '10', _TS_IDX2, 0xcf)
  // Horizontal Right End
  for (const w of ['05', '09', '01']) thin('01', w, _TS_IDX3, 0xe9)
  for (const w of ['04', '08', '10']) thin('01', w, _TS_IDX3, 0xf9)
  // Horizontal Left End
  for (const w of ['06', '0A', '02']) thin('02', w, _TS_IDX3, 0xe8)
  for (const w of ['04', '08', '10']) thin('02', w, _TS_IDX3, 0xf8)
  // Horizontal Mid
  for (const w of ['04', '08', '10']) thin('03', w, _TS_IDX3, 0xcf)
  // Vertical Bottom End
  for (const w of ['05', '06', '01', '02', '04', '10']) thin('04', w, _TS_IDX3, 0xde)
  // Vertical Top End
  for (const w of ['09', '0A', '01', '02', '08', '10']) thin('08', w, _TS_IDX3, 0xce)
  // Vertical Mid
  for (const w of ['01', '02', '10']) thin('0C', w, _TS_IDX3, 0xdf)
  // Corner Right-Bottom
  for (const w of ['05', '01', '04']) full('05', w, _TS_IDX3, 0xdb)
  full('05', '10', _TS_IDX3, 0xfb)
  // Corner Right-Top
  for (const w of ['09', '01', '08']) full('09', w, _TS_IDX3, 0xcb)
  full('09', '10', _TS_IDX3, 0xeb)
  // Corner Left-Bottom
  for (const w of ['06', '02', '04']) full('06', w, _TS_IDX3, 0xda)
  full('06', '10', _TS_IDX3, 0xfa)
  // Corner Left-Top
  for (const w of ['0A', '02', '08']) full('0A', w, _TS_IDX3, 0xca)
  full('0A', '10', _TS_IDX3, 0xea)
  // Sides
  full('01', '01', _TS_IDX2, 0xd9) // Side Right
  full('01', '10', _TS_IDX2, 0xd9)
  full('02', '02', _TS_IDX2, 0xd8) // Side Left
  full('02', '10', _TS_IDX2, 0xd8)
  full('04', '04', _TS_IDX2, 0xd6) // Side Bottom
  full('04', '10', _TS_IDX2, 0xd6)
  full('08', '08', _TS_IDX2, 0xd1) // Side Top
  full('08', '10', _TS_IDX2, 0xd1)
  full('10', '10', _TS_IDX1, 0xea) // Fill

  const w1 = new DsMap<number | string>()
  G.WallStyle01_dm = w1
  w1.set(`${STR_Tileset}01`, TS.WALLSTYLE01)
  w1.set(`_Textures${STR_Offset}`, 0x30)
  // STR_Tile+"0": Single, Horizontal Left End, or Vertical Top End; "1": Mid; "2": Right End / Bottom End
  const s1 = (shape: string, tile: string, wall: string, tsrc: number) =>
    w1.set(`${STR_TSRC}${STR_Shape}${shape}${STR_Tile}${tile}${STR_Wall}${wall}`, tsrc)
  // Single
  s1('S', '0', '05', 0x03) // Wall Corner Right-Bottom
  s1('S', '0', '09', 0x01) // Wall Corner Right-Top
  s1('S', '0', '06', 0x02) // Wall Corner Left-Bottom
  s1('S', '0', '0A', 0x00) // Wall Corner Left-Top
  s1('S', '0', '01', 0x05) // Wall Side Right
  s1('S', '0', '02', 0x04) // Wall Side Left
  s1('S', '0', '04', 0x07) // Wall Side Bottom
  s1('S', '0', '08', 0x06) // Wall Side Top
  s1('S', '0', '10', 0x08) // Wall Fill
  // Horizontal
  s1('H', '2', '05', 0x13)
  s1('H', '2', '09', 0x11)
  s1('H', '0', '06', 0x12)
  s1('H', '0', '0A', 0x10)
  s1('H', '2', '01', 0x15)
  s1('H', '0', '02', 0x14)
  s1('H', '0', '04', 0x19)
  s1('H', '1', '04', 0x1a)
  s1('H', '2', '04', 0x1b)
  s1('H', '0', '08', 0x16)
  s1('H', '1', '08', 0x17)
  s1('H', '2', '08', 0x18)
  s1('H', '0', '10', 0x1c)
  s1('H', '1', '10', 0x1d)
  s1('H', '2', '10', 0x1e)
  // Vertical
  s1('V', '2', '05', 0x23)
  s1('V', '0', '09', 0x21)
  s1('V', '2', '06', 0x22)
  s1('V', '0', '0A', 0x20)
  s1('V', '0', '01', 0x27)
  s1('V', '1', '01', 0x28)
  s1('V', '2', '01', 0x29)
  s1('V', '0', '02', 0x24)
  s1('V', '1', '02', 0x25)
  s1('V', '2', '02', 0x26)
  s1('V', '2', '04', 0x2b)
  s1('V', '0', '08', 0x2a)
  s1('V', '0', '10', 0x2c)
  s1('V', '1', '10', 0x2d)
  s1('V', '2', '10', 0x2e)
}
