/**
 * Small GameObject helpers (scripts/game_object/go): dir_to_pc*, is_facing_pc*, is_ver, in_despawn_dist,
 * from_spawner_count, DC91_carry, add_to_solid_inst_list, set_go_can_draw_self, GO_can_collide_this_frame,
 * GO_update_cam_vars, GO_update_ocs, prevent_spawn_in_pc.
 */
import { MAX_GOB1, MAX_GOC1, MAX_GOC2 } from '@z2/data'
import { instanceExists } from '../../../runtime/instance'
import { goMgr, world } from '../../../runtime/world'
import { GameObject, GameObjectB } from '../classes'
import { deps } from '../deps'
import { isAncestorName, type ObjectName } from '../objectNames'
import { gp, pc } from '../pending'
import { sign_ } from '../util'
import { set_xy } from './movement'

/** `dir_to_pc(inst id)` — DC91 */
export function dir_to_pc(inst: GameObject): 1 | -1 {
  return inst.xl < pc().xl ? 1 : -1
}
/** `dir_to_pc_(inst id)` */
export function dir_to_pc_(inst: GameObject): 1 | -1 {
  return inst.x < pc().x ? 1 : -1
}
/**
 * `dir_to_pc_1()` — simulates OG: when spawned in go_spawn_enter_room() the PC xy are still the defaults,
 * so facing is computed against the PC's spawn xy.
 */
export function dir_to_pc_1(self: GameObject): 1 | -1 {
  const p = pc()
  if (!p.state) {
    const _PC_X = p.x
    const _PC_Y = p.y
    set_xy(p, p.ww_, p.hh_)
    const _DIR = dir_to_pc_(self)
    set_xy(p, _PC_X, _PC_Y)
    return _DIR
  }
  return dir_to_pc_(self)
}
/**
 * `DC91_carry(inst id)` — the carry flag DC91 leaves set: (xl left of pc.x-8), with the OG page-wrap quirk.
 */
export function DC91_carry(inst: GameObject): boolean {
  return inst.xl < pc().x - 8 || (pc().x - 8 < 0 && inst.xl >= 0)
}
/** `is_facing_pc(inst id)` */
export function is_facing_pc(inst: GameObject): boolean {
  return inst.facing_dir === dir_to_pc(inst)
}
/** `is_facing_pc_(inst id)` */
export function is_facing_pc_(inst: GameObject): boolean {
  return inst.facing_dir === dir_to_pc_(inst)
}
/** `is_ver(inst id, object_index, version)` — "is Version". */
export function is_ver(inst: GameObject, objectName: ObjectName, ver: number): boolean {
  return inst.objectName === objectName && inst.ver === ver
}
/** `in_despawn_dist(inst id)` — DE6C: more than $160 px outside the OG view. */
export function in_despawn_dist(inst: GameObject): boolean {
  const _DIST = 0x2c << 3 // $160
  return inst.x < gp().view_xl_og - _DIST || inst.x > gp().view_xr_og + _DIST
}
/** `from_spawner_count()` */
export function from_spawner_count(): number {
  let _count = 0
  for (const b of world.instancesOf(GameObjectB)) _count += b.state && b.is_from_spawner ? 1 : 0
  return _count
}
/** `prevent_spawn_in_pc(go inst, *pad)` */
export function prevent_spawn_in_pc(inst: GameObject, pad = 0): void {
  const _PAD = Math.abs(pad)
  deps.update_body_hb_1a(inst)
  if (deps.collide_pc_body(inst.BodyHB_xl, inst.BodyHB_yt, inst.BodyHB_w, inst.BodyHB_h, inst.BodyHB_r)) {
    const _DIST = (inst.ww_ + 8 + _PAD) * sign_(inst.x - pc().x)
    set_xy(inst, pc().x + _DIST, inst.y)
  }
}
/**
 * `add_to_solid_inst_list(inst id)`.
 * FIDELITY: GML `if (ds_list_find_index(list, inst)) exit;` — with GML truthiness (-1 and 0 are false) an
 * instance already at index 0 was re-added (duplicate); intent is "exit if already listed".
 */
export function add_to_solid_inst_list(inst: GameObject): void {
  const list = gp().dl_solid_inst
  if (list.findIndex(inst) !== -1) return
  const _COUNT = list.size
  for (let _i = 0; _i < _COUNT; _i++) {
    const cur = list.get(_i)
    if (
      cur === undefined ||
      !instanceExists(cur as GameObject | null | undefined) ||
      !(cur as GameObject).state
    ) {
      list.set(_i, inst)
      return
    }
  }
  list.add(inst)
}
/** `set_go_can_draw_self(can_draw_self)` — D250 */
export function set_go_can_draw_self(canDraw: boolean): void {
  const p = pc()
  p.can_draw_self = p.state ? canDraw : false
  p.SwordHB_can_draw = false
  p.SwordHB2_can_draw = false
  p.SCS_can_draw = false
  const apply = (inst: GameObject | 0 | null | undefined) => {
    if (!instanceExists(inst as GameObject | null | undefined)) return
    const i = inst as GameObject
    if (!i.state) i.can_draw_self = false
    else if (!i.can_draw_self_exception) i.can_draw_self = canDraw
  }
  for (let _i = 0; _i < MAX_GOB1; _i++) apply(goMgr.dl_gob1.get(_i))
  for (let _i = 0; _i < MAX_GOC1; _i++) apply(goMgr.dl_goc1.get(_i))
  for (let _i = 0; _i < MAX_GOC2; _i++) apply(goMgr.dl_goc2.get(_i))
  for (let _i = goMgr.dl_gob2.size - 1; _i >= 0; _i--) apply(goMgr.dl_gob2.get(_i))
  for (const go of world.instancesOf(GameObject)) {
    go.BodyHB_can_draw = false
    go.SwordHB_can_draw = false
    go.ShieldHB_can_draw = false
    go.canDrawCSHB = false
  }
}
/** `GO_can_collide_this_frame(uIdx)` — odd slots collide on even frames and vice versa. */
export function GO_can_collide_this_frame(uIdx: number): boolean {
  const odd = gp().counter1 & 0x1
  return (!!(uIdx & 0x1) && !odd) || (!(uIdx & 0x1) && !!odd)
}
/** `GO_update_cam_vars()` — F27D */
export function GO_update_cam_vars(self: GameObject): void {
  self.view_xl_dist_og = (self.xl - gp().view_xl_og) & 0xff // simulates OG
  self.view_yt_dist_og = (self.yt - gp().view_yt_og) & 0xff // simulates OG
  self.view_xl_dist = self.x - deps.viewXL()
  self.view_yt_dist = self.y - deps.viewYT()
  GO_update_ocs(self)
}
/**
 * `GO_update_ocs()` — ocs: Off Camera State.
 * X bits $1F: $04 sprite centre, $08/$02 one unit (8 or 4 px) in from each edge, $10/$01 the edges.
 * Y bits: $80 top pixel outside, $40 centre outside, $20 bottom pixel outside (area = view ± 8).
 */
export function GO_update_ocs(self: GameObject): void {
  self.ocs = 0
  const xr = deps.viewXR()
  const xl = deps.viewXL()
  for (let _i = 0; _i < 3; _i++) {
    let _xOff = 0
    switch (_i) {
      case 0:
        _xOff = self.ww_
        break // bit   $4      (center)
      case 1:
        _xOff = 8 >> (self.ww === 8 ? 1 : 0)
        break // bits  $8 & $2 (1 uw from edge)
      case 2:
        _xOff = 0
        break // bits $10 & $1 (edges)
    }
    let _x = self.x - self.ww_ + _xOff // LEFT
    if (_x >= xr || _x <= xl) self.ocs |= 0x4 << _i // bits $4, $8, $10
    self.ocs_draw_x[2 - _i] = _x
    _x = self.x + self.ww_ - _xOff // RIGHT
    if (_x >= xr || _x <= xl) self.ocs |= 0x4 >> _i // bits $4, $2, $1
    self.ocs_draw_x[2 + _i] = _x
  }
  const _YT = deps.viewYT() - 8 //   0. Y Top
  const _YB = deps.viewYB() + 8 // $F0. Y Bot
  if (self.y - self.hh_ >= _YB || self.y - self.hh_ < _YT) self.ocs |= 0x80 // top above or below
  if (self.y + self.hh_ <= _YT || self.y + self.hh_ > _YB) self.ocs |= 0x20 // btm above or below
  if (self.y < _YT || self.y > _YB) self.ocs |= 0x40 // mid above or below
  self.ocs_draw_y[0] = self.y - self.hh_
  self.ocs_draw_y[1] = self.y
  self.ocs_draw_y[2] = self.y + self.hh_
}
/** `is_ancestor(object_index, X)` by object name, for data-driven checks (e.g. `dm_spawn` object ids). */
export function objectIsAncestor(obj: ObjectName, parent: ObjectName): boolean {
  return isAncestorName(obj, parent)
}
