/** Cross-references the cutscene port needs from folders that are not ported yet (exact GML names). */
import { notPorted } from '../../pending'
import type { GameObject } from '../classes'
import { PC_set_behavior as goa_PC_set_behavior, pc_is_cucco as goa_pc_is_cucco } from '../goa/attackForm'
import { solid_clip_correction as goa_solid_clip_correction } from '../goa/movement'
import { draw_pc_skin as goa_draw_pc_skin } from '../goa/PC_draw'
import { PC_udp as goa_PC_udp } from '../goa/udp'

export const gofDeps = {
  PC_set_behavior: ((_self: GameObject, behavior: number) => goa_PC_set_behavior(behavior)) as (
    self: GameObject,
    behavior: number,
  ) => void,
  PC_udp: ((self: GameObject) => goa_PC_udp(self as never)) as (self: GameObject) => void,
  draw_pc_skin: ((...args: unknown[]) => (goa_draw_pc_skin as (...a: unknown[]) => void)(...args)) as (
    ...args: unknown[]
  ) => void,
  ShadowBoss_udp: notPorted('ShadowBoss_udp') as (self: GameObject) => void,
  Boss_play_battle_music: notPorted('Boss_play_battle_music') as (self: GameObject) => void,
  Zelda_update_talk_sound: notPorted('Zelda_update_talk_sound') as () => boolean,
  solid_clip_correction: ((self: GameObject, v: boolean) => {
    goa_solid_clip_correction(self, v)
  }) as (self: GameObject, v: boolean) => void,
  Rando_randomize_file: notPorted('Rando_randomize_file') as (
    fileNum: number,
    questNum: number,
    seed: number,
    settings: string,
  ) => void,
  /** `pc_is_cucco()` lives in the player port; the palette folder exposes a seam already. */
  pc_is_cucco: (): boolean => goa_pc_is_cucco(),
}
