import gm from '../generated/gmIndex.json' with { type: 'json' }

/**
 * GameMaker resource-index → name tables (project-tree order, generated by `pnpm tool gm-index`).
 * ZALiA's caches store numeric script/sprite/object ids in places (`_NIAO0_init`, `_obj_idx`, `_CutScene01_Object`).
 */
export const GM_SCRIPT_NAMES: readonly string[] = gm.scripts
export const GM_SPRITE_NAMES: readonly string[] = gm.sprites
export const GM_OBJECT_NAMES: readonly string[] = gm.objects
export const GM_SOUND_NAMES: readonly string[] = gm.sounds
export const GM_BACKGROUND_NAMES: readonly string[] = gm.backgrounds
export const GM_ROOM_NAMES: readonly string[] = gm.rooms

const lookup =
  (table: readonly string[], kind: string) =>
  (idx: number): string => {
    const n = table[idx]
    if (n === undefined) throw new Error(`unknown GM ${kind} index ${idx}`)
    return n
  }
export const gmScriptName = lookup(GM_SCRIPT_NAMES, 'script')
export const gmSpriteName = lookup(GM_SPRITE_NAMES, 'sprite')
export const gmObjectName = lookup(GM_OBJECT_NAMES, 'object')
export const gmSoundName = lookup(GM_SOUND_NAMES, 'sound')
/** Accepts a name or a numeric GM index. */
export const gmObjectNameOf = (v: string | number): string => (typeof v === 'number' ? gmObjectName(v) : v)
export const gmScriptNameOf = (v: string | number): string => (typeof v === 'number' ? gmScriptName(v) : v)
export const gmSpriteNameOf = (v: string | number): string => (typeof v === 'number' ? gmSpriteName(v) : v)
