/** `Myu_A` — ZALiA `enemy/myu`: Myu_init2, Myu_update (→ Bot_update), Myu_udp. Bot-like walker with spikes. */
import {
  ABL_WALK,
  Area_PalcC,
  Area_PalcD,
  Area_PalcE,
  Area_PalcF,
  Area_PalcG,
  Area_PalcH,
  STR_Enemy,
  STR_Method,
  STR_obj_idx,
  STR_Randomize,
  STR_Version,
  TID_SOLID1,
} from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { find_row_solid } from '../../../../../collision/solid'
import { gmObjectName } from '../../../../../niao/gmIndex.generated'
import { hex_str, val } from '../../../../../other/index'
import { registerObjectClass } from '../../../../../other/registry'
import { Enemy } from '../../../../classes'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import type { ObjectName } from '../../../../objectNames'
import { registerObject, registerScripts } from '../../../../registry'
import { dl } from '../../shared'
import { Bot_update, type BotWalker } from '../bot/Bot'

export class Myu_A extends Enemy {
  readonly objectName = 'Myu_A' as const
  // ---- init_vars_Bot (Bot, Myu)
  is_idle = 1 // $00AF,X. 1: still, 0: moving horizontal
  walk_dir = 1 // 0401,X
  HSPD_JUMP_DEF = 0x10
  HSPD_JUMP_1 = 0x20
  HSPD_JUMP_2 = 0x30
  hspd_jump = this.HSPD_JUMP_DEF
  HSPD_WALK1 = 0x20
  HSPD_WALK2 = 0x40
  hspd_walk = 0
  INIT_VEL_DEF = 0xe5
  INIT_VEL_HGH = 0x9e
  TERM_VEL_DEF = 0x50
  term_vel = this.TERM_VEL_DEF
  VSPD_INC_DEF = 2
  // FIXED: `Myu_init2.gml:4` calls `init_vars_Bot()`, whose `:35` is `vspd_grav = VSPD_INC_DEF`. Myu is
  // the only caller that does not route through `Bot_init2`, so it inherited the base default 0 and
  // never fell — it floated after every knock-up.
  override vspd_grav = 2
  VSPD_INC_HGH = 3
}
registerObject('Myu_A', Myu_A)
registerObjectClass('Myu_A', Myu_A)

/** `Myu_init2()` */
export function Myu_init2(self: Myu_A): void {
  // init_vars_Bot(): field initializers on Myu_A
  const s = dl(self)
  s.set(1, 'spr_Myu2') // spikes out
  s.set(0, 'spr_Myu1')
  GO_init_palidx(self, G.PI_MOB_BLU)
  self.abilities |= ABL_WALK
  const a = g.area_name
  if (a === Area_PalcC || a === Area_PalcD || a === Area_PalcE || a === Area_PalcF) {
    self.XP_IDX = 0x05
    self.xp = g.dl_XP.get(self.XP_IDX)
  }
  if (a === Area_PalcG || a === Area_PalcH) {
    self.ATTACK_LEVEL = 0x04
    self.attack_level = self.ATTACK_LEVEL
    self.HP_IDX = 0x0d
    self.hp = g.dl_HP.get(self.HP_IDX)
    self.XP_IDX = 0x0a
    self.xp = g.dl_XP.get(self.XP_IDX)
  }
  // Despawn inst because Myu is too short to see in water. If inst is from a rando location
  const dk = self.dk_spawn
  if (
    gmBool(G.EnemyRando_enabled) &&
    gmBool(val(G.dm_save_file_settings.get(STR_Randomize + STR_Enemy + STR_Method))) &&
    dk !== undefined &&
    g.dm_spawn.get(dk + STR_obj_idx) !== undefined &&
    g.dm_spawn.get(dk + STR_Version) !== undefined &&
    self.objectName + hex_str(self.ver) !==
      objName(g.dm_spawn.get(dk + STR_obj_idx)) + hex_str(g.dm_spawn.get(dk + STR_Version) as number) &&
    self.x >= 0 &&
    self.x < g.rm_w &&
    self.y >= 0 &&
    self.y < g.rm_h
  ) {
    const _CLM = self.x >> 3
    const _ROW = find_row_solid(TID_SOLID1, _CLM, self.y >> 3, 1, 0xff, self.y >> 3) - 1
    if (gmBool(g.dg_RmTile_Liquid.get(_CLM, _ROW))) self.state = 0
  }
}

/** `object_get_name(obj_idx)` — spawn data stores GM object indices (or names). */
function objName(v: unknown): string {
  if (typeof v === 'number') return gmObjectName(v) ?? String(v)
  return String(v)
}

/** `Myu_update()` */
export function Myu_update(self: Myu_A): void {
  Bot_update(self as unknown as BotWalker)
}

/** `Myu_udp()` */
export function Myu_udp(self: Myu_A): void {
  self.can_draw_self = true
  // idx 0: spikes in, idx 1: spikes out
  const idx = !gmBool(self.is_idle) && !(self.counter & 0x0c) ? 1 : 0
  GO_set_sprite(self, dl(self).get(idx) as string)
}

registerScripts({ Myu_init2, Myu_update, Myu_udp })
