/** `PC_Room_Start()` — per-room reset of the player (palette permutations, disguise, hitboxes, rescue state). */
import { STR_Count } from '@z2/data'
import type { DsList } from '../../../runtime/ds'
import { NOONE } from '../../../runtime/instance'
import { G, g, p, world } from '../../../runtime/world'
import { setCSOffsets } from '../../collision/cs'
import { PC_update_shield_hb } from '../../collision/hitbox'
import { val } from '../../other/index'
import { PI_MOB_ORG, PI_PC1, PI_SPELL_PC1 } from '../../palette/pi'
import { add_pi_permut } from '../../palette/scenePalette'
import { GO_init_palidx } from '../go/palette'
import { dev_start_pc_with } from './dev_start_pc_with'
import { PC_set_behavior } from './form'
import type { Lonk } from './Lonk'
import { pcInput } from './pc'

export function PC_Room_Start(self: Lonk): void {
  dev_start_pc_with() // Add items, spells, etc..
  self.depth = self.depth_def
  GO_init_palidx(self, PI_PC1)
  // Add cucco spell flash palettes. cucco spell flash permut: B W R . . . . . .
  let _color_order = 'BWRGKYMC' // permut color order
  if (_color_order !== p.PAL_BASE_COLOR_ORDER) {
    const _count1 = Number(val(G.dm_pi.get(`SPELL_PC${STR_Count}`)))
    for (let _i = 0; _i < _count1; _i++) {
      const _parent_pi = PI_SPELL_PC1 + _i
      const _new_pi = add_pi_permut(_parent_pi, _color_order, `cucco spell flash ${_i + 1}`)
      for (let _j = p.dg_PI_SEQ.height - 1; _j >= 0; _j--) {
        if (Number(p.dg_PI_SEQ.get(0x04, _j)) - PI_SPELL_PC1 === _i) p.dg_PI_SEQ.set(0x05, _j, _new_pi)
      }
    }
    _color_order = 'RWBGMYKC' // permut color order
    for (let _i = 1; _i < 4; _i++) {
      // _i=1: MOB ORG, _i=2: MOB RED, _i=3: MOB BLU
      p.dg_PI_SEQ.set(
        0x01,
        _i,
        add_pi_permut(Number(p.dg_PI_SEQ.get(0x00, _i)), _color_order, `cucco stun flash ${_i}`),
      )
    }
  }
  // April-fools draw randomisation table
  for (let y = 0; y < self.dg_UwU_.height; y++)
    for (let x = 0; x < self.dg_UwU_.width; x++) self.dg_UwU_.set(x, y, 0)
  for (let _i = self.dg_UwU_.width - 1; _i >= 0; _i--) {
    // _i is each behavior
    self.dg_UwU_.set(_i, 0, world.irandom(1) ? 1 : -1) // xscale
    self.dg_UwU_.set(_i, 1, world.irandom(1) ? 1 : -1) // yscale
    self.dg_UwU_.set(_i, 2, PI_PC1 + world.irandom(Number(val(G.dm_pi.get(`PC${STR_Count}`))) - 1)) // palidx
    self.dg_UwU_.set(_i, 4, world.irandom(3) * 90) // rotation
  }
  shuffle(self.dl_UwU_) // shuffle behaviors
  if (self.Disguise_enabled) {
    // keep walking behaviours mapped onto walking behaviours (ds_stack partition in the GML)
    const _SIZE = self.dl_UwU_.size
    const walk = [
      self.behavior_WALK1,
      self.behavior_WALK2,
      self.behavior_WALK3,
      self.behavior_IDLE,
      self.behavior_CROUCH,
    ]
    const _ds1: number[] = []
    const _ds2: number[] = []
    for (let _i = _SIZE - 1; _i >= 0; _i--) {
      const v = self.dl_UwU_.get(_i) as number
      if (walk.includes(v)) _ds1.push(v)
      else _ds2.push(v)
    }
    const _dl2: number[] = []
    for (let _i = 0; _i < _SIZE; _i++) _dl2.push((walk.includes(_i) ? _ds1.pop() : _ds2.pop()) as number)
    if (_dl2.length === _SIZE) {
      self.dl_UwU_.clear()
      self.dl_UwU_.add(..._dl2)
    }
  }
  self.state = self.state_NULL // 00B5
  self.Disguise_Head_idx = world.irandom(self.Disguise_Head_COUNT - 1)
  self.Cucco_disguise_sprite = 0
  self.dg_Cucco_DISGUISE_SPRITES_idx1 = world.irandom(self.dg_Cucco_DISGUISE_SPRITES.width - 1)
  self.dg_Cucco_DISGUISE_SPRITES_idx2 = world.irandom(1)
  self.RescueFairy_sprite = 0
  self.Rescue_x_start = 0
  self.Rescue_y_start = 0
  self.Rescue_x_end = 0
  self.Rescue_y_end = 0
  self.Rescue_x_dist = 0
  self.Rescue_y_dist = 0
  self.Rescue_x_duration = 0
  self.Rescue_y_duration = 0
  self.Rescue_x_time = 0 // number of frames since Rescue start
  self.Rescue_y_time = 0
  PC_set_behavior(self.behavior_IDLE) // 0080
  self.fairy_sprite = 0 // The fairy sprite to draw
  self.xScale = 1 // 009F
  self.Shadow_can_draw = false
  self.HoldItem_timer = 0 // 049C
  self.HoldItem_inst = NOONE
  self.HoldItem_object = 0 // 049D
  self.HoldItem_sprite = 0
  self.HoldItem_palidx = PI_MOB_ORG
  self.walk_frame = 0 // $00AE
  self.landing_timer = 0 // 0497
  self.WalkTo_active = false
  self.hspd_dir = self.xScale // 005F
  self.hspd_dir_spawn = self.hspd_dir
  self.x_change = 0 // 0014
  self.x_change_prev = 0
  self.vspd_dir = 1
  self.vspd_dir_spawn = self.vspd_dir
  self.y_change = 0
  self.y_change_prev = 0
  self.vspd_bounce = self.VSPD_BOUNCE1 // BV: Base Velocity
  self.vspd_grav = self.GRAVITY2 // $03E6
  self.ogr = 0 // $0479. ogr: Off Ground Reason
  self.attack_phase = 0 // $0400
  self.stab_type = 0 // 0495 stabType. 0: low, 1: high
  // So various updates can happen, like during stun timer, but death is ensured
  self.is_dead = false // 0494. true when pending death
  self.in_restore_house = false // 048D
  g.pc_lock = 0
  self.colliding_elevator = NOONE // 0754
  self.colliding_locked_door = 0x00 // 05E7
  pcInput.dHeld = false // 0: down NOT held, 1: down held
  self.control = 0 // control is flags for various purposes
  self.DrownLiquid_y = 0
  self.DrownLiquid_depth = 0
  self.Cucco_damage_taken = 0
  self.Cucco_damaged_count = 0
  self.Cucco_rage_state = 0
  self.Cucco_rage_timer = 0
  self.Cucco_rage_tokens = 0
  for (let y = 0; y < self.dg_Cucco_rage.height; y++)
    for (let x = 0; x < self.dg_Cucco_rage.width; x++) self.dg_Cucco_rage.set(x, y, 0)
  self.TransformHumanClipCorrect_timer = 0
  // ------------------------------------------------------------
  self.cs_btm_inst = NOONE
  setCSOffsets(self)
  // shield hb
  PC_update_shield_hb(pcInput.dHeld)
  // sword hb
  self.SwordHB_collidable = false
  self.SwordHB_can_draw = self.SwordHB_collidable
  self.SwordHB_x_base = 0 // 047E
  self.SwordHB_y_base = 0 // 0480
  self.SwordHB_xoff = 0
  self.SwordHB_yoff = 0
  self.SwordHB_x = 0
  self.SwordHB_y = 0
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
  // SCS: Sword Collide Solid
  self.SCS_can_draw = false
  self.SCS_x = 0 // 005D
  self.SCS_y = 0 // 0039
  self.SCS_draw_x = 0
  self.SCS_draw_y = 0
}

/** `ds_list_shuffle` with the world's seeded PRNG (Fisher–Yates). */
function shuffle(list: DsList<number>): void {
  const a = list.items
  for (let i = a.length - 1; i > 0; i--) {
    const j = world.irandom(i)
    const t = a[i] as number
    a[i] = a[j] as number
    a[j] = t
  }
}
