/** Fokkeru (ZALiA object `FokuA`, parent `Enemy`; the hopping flame spitter). `Fokkeru_init2/update/udp/draw.gml`. */
import { CS_BD1, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { GO_draw_sprite } from '../../../../go/draw'
import { dir_to_pc } from '../../../../go/misc'
import { GO_vspd_update1, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { solid_clip_correction } from '../../../../goa/movement'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_1, GOB_update_2 } from '../../../GameObjectB'
import { projOf, rand } from '../ache/_shared'

export class FokuA extends Enemy {
  readonly objectName = 'FokuA' as const
  sprBtm = 'spr_Fokkeru_btm1'
  VSPD_GRAV = 2
}

/** `Fokkeru_init2()` */
export function Fokkeru_init2(self: FokuA): void {
  self.projectile_OBJ = 'Flame2'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.sprBtm = 'spr_Fokkeru_btm1'
  GO_init_palidx(self, G.PI_MOB_RED)
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
}

/** `Fokkeru_update()` — 9E6B */
export function Fokkeru_update(self: FokuA): void {
  const _RAND = rand(self)
  // 9E6B
  GOB_update_1(self, true) // update hspd_pushback
  GO_update_cs(self)
  // 9E38
  if (!(self.cs & 0x3)) updateX(self)
  self.facing_dir = dir_to_pc(self)
  self.counter = (self.counter + 1) & 0xff
  if (!(self.counter & 0x3f) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
    const proj = GOC1_create(self.xl, self.yt, self.facing_dir, projOf(self), self.projectile_ver)
    proj.vspd = 0xe0
    proj.hspd = (0x10 * self.facing_dir) & 0xff
  }
  // 9E98
  updateY(self)
  GO_update_cs(self)
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // 9EA1
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    const _VAL = (_RAND >> 1) & 0x3
    self.hspd = 0x4 << +(_VAL > 1) // 4,8
    if (_VAL & 0x1) self.hspd = -self.hspd & 0xff
    self.vspd = (0xf0 << (_RAND & 0x1)) & 0xff
  }
  // MOD. Prevent clip into ceiling
  GO_vspd_update1(self)
}

/** `Fokkeru_udp()` */
export function Fokkeru_udp(self: FokuA): void {
  self.can_draw_self = true
  self.sprite = self.counter & 0x10 ? 'spr_Fokkeru_top2' : 'spr_Fokkeru_top1' // mouth open / closed
  self.sprBtm = self.counter & 0x08 ? 'spr_Fokkeru_btm2' : 'spr_Fokkeru_btm1' // legs open / closed
}

/** `Fokkeru_draw()` */
export function Fokkeru_draw(self: FokuA): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  GO_draw_sprite(self, self.sprBtm)
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

registerObject('FokuA', FokuA)
registerScripts({ Fokkeru_init2, Fokkeru_update, Fokkeru_udp, Fokkeru_draw })
