/** set_go_hspd_pushbback, pushback_pc, pushback_pc_and_go (scripts/game_object/go) */

import { CS_LFT, CS_RGT } from '@z2/data'
import { abs8b } from '../../../nes/math8'
import type { GameObject } from '../classes'
import { gp, pc } from '../pending'

import { sign_ } from '../util'

/**
 * `set_go_hspd_pushbback(go inst, new hspd pb)` — push back dir is which side of colliding-obj gob is on:
 * RIGHT($0C) when to the right of (or even with) colliding-obj, LEFT($F4) when to the left.
 */
export function set_go_hspd_pushbback(inst: GameObject, newHspdPb: number): void {
  if (inst.stun_timer) inst.hspd_pushback = (newHspdPb << 1) & 0xff
  else inst.hspd_pushback = newHspdPb
}

/** `pushback_pc(push source x, new hspd)` */
export function pushback_pc(sourceX: number, newHspd: number): void {
  const p = pc()
  if (!newHspd) return
  if (sourceX < p.x && p.cs & CS_RGT) return
  if (sourceX >= p.x && p.cs & CS_LFT) return
  p.hspd = abs8b(newHspd) * sign_(p.x - sourceX)
  p.hspd &= 0xff
}

/** `pushback_pc_and_go(push source inst, *alt PC push amount, *alt GO push amount)` — E371. Pass 0 to skip a side. */
export function pushback_pc_and_go(inst: GameObject, altPc = -1, altGo = -1): void {
  let _PC_AMT = 0x4 // default   amount
  if (altPc + 1) _PC_AMT = abs8b(Math.abs(altPc)) & 0xff // alternate amount
  let _GO_AMT = 0xc // default   amount
  if (altGo + 1) _GO_AMT = abs8b(Math.abs(altGo)) & 0xff // alternate amount
  if (_PC_AMT) {
    gp().control1_timer = pc().Pushback_DURATION // PC atk will NOT affect PC.hspd
    pushback_pc(inst.x, _PC_AMT)
  }
  if (_GO_AMT !== 0) {
    const _AMOUNT = abs8b(_GO_AMT & 0xff)
    if (inst.x >= pc().x) set_go_hspd_pushbback(inst, _AMOUNT & 0xff)
    else set_go_hspd_pushbback(inst, -_AMOUNT & 0xff)
  }
}
