/** `get_random_color*`, `get_random_palette2` — randomizer palette colour generation. */
import { p, world } from '../../runtime/world'
import * as C from './colors'
import { colour_get_hsv, get_color_brightness, make_colour_hsv } from './colors'
import { build_pal } from './palString'

const pick = (list: readonly number[]) => list[world.irandom(list.length - 1)] as number

/**
 * FIDELITY (`get_random_color_*` TODOs): when not using game colours the GML returned any colour; the
 * intent stated in the comments is highlight ≥ $80, midtone $40..$7F, shadow < $40 — enforced here.
 */
function randomWithBrightness(min: number, max: number): number {
  for (let tries = 0; tries < 64; tries++) {
    const c = world.irandom(0xffffff)
    const b = get_color_brightness(c)
    if (b >= min && b <= max) return c
  }
  return pick(p.dl_colors_m)
}

/** `get_random_color_highlight(use game colors)` */
export function get_random_color_highlight(useGameColors: boolean | number): number {
  return useGameColors ? pick(p.dl_colors_h) : randomWithBrightness(0x80, 0xff)
}
/** `get_random_color_midtone(use game colors)` */
export function get_random_color_midtone(useGameColors: boolean | number): number {
  return useGameColors ? pick(p.dl_colors_m) : randomWithBrightness(0x40, 0x7f)
}
/** `get_random_color_shadow(use game colors)` */
export function get_random_color_shadow(useGameColors: boolean | number): number {
  return useGameColors ? pick(p.dl_colors_s) : randomWithBrightness(0x00, 0x3f)
}

/** `get_random_color(use game colors, *tone: 0/"H"/"Y" highlight, 1/"M" midtone, 2/"S"/"K" shadow)` */
export function get_random_color(useGameColors: boolean | number, tone: number | string = -1): number {
  const t = typeof tone === 'string' ? tone.toUpperCase() : tone
  if (t === -1) {
    if (useGameColors) return pick(p.dl_COLORS_USED)
  } else {
    if (t === 0 || t === 'H' || t === 'Y') return get_random_color_highlight(useGameColors)
    if (t === 1 || t === 'M') return get_random_color_midtone(useGameColors)
    if (t === 2 || t === 'S' || t === 'K') return get_random_color_shadow(useGameColors)
    if (useGameColors) return pick(p.dl_COLORS_USED)
  }
  return world.irandom(0xffffff)
}

/** GM `choose(...)` */
function choose<T>(...vals: T[]): T {
  return vals[world.irandom(vals.length - 1)] as T
}

const grid = (row: number, col: number) => C.DL_COLOR01[row * C.ColorGrid_CLMS + col] as number

/**
 * `get_random_palette2(base hue)` — a highlight/midtone/shadow palette around a hue (-1 = random hue,
 * -2 = greyscale). Base colours are never returned (they would be treated as swap sources).
 */
export function get_random_palette2(baseHue: number): string {
  let _base_hue = baseHue < 0 ? world.irandom(0xff) : baseHue
  _base_hue &= 0xff
  // MID-TONE
  let _hue = _base_hue
  let _sat: number
  if (baseHue === -2) _sat = 0x00
  else {
    const _min = choose(0x30, 0x30, 0x50, 0x50, 0x50, 0x50, 0x50, 0x70, 0x70, 0x70, 0x70, 0x70, 0x70, 0x70)
    _sat = _min + world.irandom(0xe8 - _min)
  }
  let _lum: number
  {
    const _min = choose(0x1b, 0x1b, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x43, 0x43, 0x43, 0x43, 0x43)
    _lum = _min + world.irandom(0x77 - _min)
  }
  let _color_mid = make_colour_hsv(_hue, _sat, _lum)
  switch (_color_mid) {
    case C.C_WHT0:
      _color_mid = grid(0xd, 0x04)
      break
    case C.C_RED0:
      _color_mid = grid(0xc, 0x01)
      break
    case C.C_BLU0:
      _color_mid = grid(0x3, 0x02)
      break
    case C.C_GRN0:
      _color_mid = grid(0x7, 0x01)
      break
    case C.C_YLW0:
      _color_mid = grid(0x9, 0x02)
      break
    case C.C_MGN0:
      _color_mid = grid(0x0, 0x01)
      break
    case C.C_BLK0:
      _color_mid = grid(0xd, 0x02)
      break
    case C.C_CYN0:
      _color_mid = grid(0x5, 0x02)
      break
    case C.C_ALPHA0:
      _color_mid = grid(0xd, 0x05)
      break
    default:
      break
  }
  const mid = colour_get_hsv(_color_mid)
  // HIGHLIGHT
  _hue = _base_hue + 0x100
  _hue += world.irandom(0x1f) * choose(1, -1)
  _hue = _hue % 0x100
  if (baseHue === -2) _sat = 0x00
  else {
    const _min = Math.max(0x18, mid.s - 0xa0)
    const _max = Math.min(0xf0, mid.s + 0xa0)
    _sat = Math.min(Math.max(_min + world.irandom(_max - _min), 0x00), 0xff)
  }
  _lum = Math.min(Math.max(mid.v + 0x30 + world.irandom(0x30), 0x00), 0xff)
  let _color_hgh = make_colour_hsv(_hue, _sat, _lum)
  switch (_color_hgh) {
    case C.C_WHT0:
      _color_hgh = grid(0xd, 0x09)
      break
    case C.C_RED0:
      _color_hgh = grid(0xc, 0x03)
      break
    case C.C_BLU0:
      _color_hgh = grid(0x3, 0x03)
      break
    case C.C_GRN0:
      _color_hgh = grid(0x7, 0x02)
      break
    case C.C_YLW0:
      _color_hgh = grid(0x9, 0x03)
      break
    case C.C_MGN0:
      _color_hgh = grid(0x0, 0x03)
      break
    case C.C_BLK0:
      _color_hgh = grid(0xd, 0x07)
      break
    case C.C_CYN0:
      _color_hgh = grid(0x5, 0x03)
      break
    case C.C_ALPHA0:
      _color_hgh = grid(0xd, 0x07)
      break
    default:
      break
  }
  // SHADE
  _hue = _base_hue + 0x100
  _hue += world.irandom(0x1f) * choose(1, -1)
  _hue = _hue % 0x100
  if (baseHue === -2) _sat = 0x00
  else {
    const _min = Math.max(0x18, mid.s - 0xa0)
    const _max = Math.min(0xf0, mid.s + 0xa0)
    _sat = _min + world.irandom(_max - _min)
  }
  _lum = Math.min(Math.max(Math.floor(mid.v * 0.33), 0x00), 0xff)
  let _color_shd = make_colour_hsv(_hue, _sat, _lum)
  if ([...C.BASE_COLORS, C.C_ALPHA0].includes(_color_shd)) _color_shd = C.C_BLK1
  return build_pal(_color_hgh, _color_mid, _color_shd, C.C_BLK1, _color_hgh, _color_mid, _color_shd, C.C_BLK1)
}
