/** SpikeBall1 (ver 1 spike ball, ver 2 energy ball): init_1/init_2/init3/update/udp. */
import { abs8b, byteNegate, gmBool } from '../../../../nes/math8'
import { g } from '../../../../runtime/world'
import { pointInRect } from '../../../collision/geometry'
import { byte_dir } from '../../../math/index'
import { add_pi_permut } from '../../../palette/scenePalette'
import { deps } from '../../deps'
import { GO_set_sprite, GO_sprite_init } from '../../go/sprite'
import { pp } from '../../pending'
import { collisionProjCS, Projectile_init, Projectile_update_3a } from '../Projectile'
import type { SpikeBall1 } from './classes'

function setSprites(self: SpikeBall1): void {
  switch (self.ver) {
    case 1:
      self.dl_sprites?.set(1, 'spr_Spike_ball_4a')
      self.dl_sprites?.set(0, 'spr_Spike_ball_4a')
      break
    case 2:
      self.dl_sprites?.set(1, 'spr_EnergyBall_1b')
      self.dl_sprites?.set(0, 'spr_EnergyBall_1a')
      break
  }
}

export function SpikeBall1_init_1(self: SpikeBall1): void {
  Projectile_init(self)
  self.scr_init3 = SpikeBall1_init3 as (s: unknown) => void
  self.HSPD1 = 0x20
  self.VSPD1 = self.HSPD1
  setSprites(self)
  GO_sprite_init(self, self.dl_sprites?.get(0) ?? 'spr_Spike_ball_4a')
  self.timer = 0x140 // life duration
  self.collided_solid_counter = 0
}
export function SpikeBall1_init_2(self: SpikeBall1): void {
  setSprites(self)
  GO_sprite_init(self, self.dl_sprites?.get(0) ?? 'spr_Spike_ball_4a')
}
export function SpikeBall1_init3(self: SpikeBall1): void {
  if (self.ver === 2) {
    // Holds the flash pi's in its bytes for SpikeBall1_udp(). Example: $0C12130B.
    self.flash_pal_indices = 0
    const _dl_color_order = [pp().PAL_BASE_COLOR_ORDER as string, 'RBWGMKYC', 'BWRGKYMC', 'RBWGMKYC']
    for (let _i = 0; _i < _dl_color_order.length; _i++) {
      const _new_pi = add_pi_permut(
        self.palidx,
        _dl_color_order[_i] as string,
        `SpikeBall1 ver2 flash ${_i + 1}`,
      )
      self.flash_pal_indices |= _new_pi << (_i << 3)
    }
  }
}
export function SpikeBall1_update(self: SpikeBall1): void {
  let _can_explode = !gmBool(self.timer)
  if (!_can_explode) {
    const _EXTRA = 2
    let _collided = false
    const vx = deps.viewXL()
    const vy = deps.viewYT()
    const vw = deps.viewW()
    const vh = deps.viewH()
    let _off = ((abs8b(self.hspd) >> 4) + _EXTRA) * byte_dir(self.hspd)
    if (collisionProjCS(self, _off, 0) || !pointInRect(self.x + _off, self.y, vx, vy, vw, vh)) {
      self.hspd = byteNegate(self.hspd)
      self.hspd_dir = byte_dir(self.hspd)
      _collided = true
    }
    _off = ((abs8b(self.vspd) >> 4) + _EXTRA) * byte_dir(self.vspd)
    if (collisionProjCS(self, 0, _off) || !pointInRect(self.x, self.y + _off, vx, vy, vw, vh)) {
      self.vspd = byteNegate(self.vspd)
      self.vspd_dir = byte_dir(self.vspd)
      _collided = true
    }
    if (_collided) {
      self.collided_solid_counter++
      if (self.collided_solid_counter >= 0xa) _can_explode = true
    }
  }
  if (_can_explode) {
    self.disintegrate_counter = 0xf2
    self.state = self.state_EXPLODE
  } else {
    Projectile_update_3a(self, self.despawn_offscreen_hor)
  }
}
export function SpikeBall1_udp(self: SpikeBall1): void {
  self.can_draw_self = true
  switch (self.ver) {
    case 1:
      GO_set_sprite(self, self.dl_sprites?.get(0) ?? 'spr_Spike_ball_4a')
      break
    case 2: {
      GO_set_sprite(self, self.dl_sprites?.get(g.counter1 & 0x2 ? 0 : 1) ?? 'spr_EnergyBall_1a')
      const _SEQ_IDX = (g.counter1 >> 1) & 0x3 // 0,1,2,3
      self.palidx = (self.flash_pal_indices >> (_SEQ_IDX << 3)) & 0xff
      break
    }
  }
}
