const c_lime = 0x00ff00
const c_purple = 0x800080
const c_white = 0xffffff
const c_orange = 0xffa500

// ---- Platform base -----------------------------------------------------------------------------------
export function Platform_init_1(self: PlatformBase): void {
  GameObjectB_init(self as unknown as Parameters<typeof GameObjectB_init>[0])
  self.DRAW_YOFF = 0
  self.solid_type = TID_ONEWY1
  add_to_solid_inst_list(self)
  self.pc_xoff = 0 // pc.x diff from id.x
  self.path_dir = 1
  self.location_a = 0
  self.location_b = self.location_a
  self.hspd_dir = 1
  self.hspd1 = 0
  self.vspd_dir = 1
  self.vspd1 = 0
}

/**
 * `update_go_xy_on_moving_platform(diff x, diff y)` — carries every GameObject standing on this platform
 * (`cs_btm_inst == this`) by the platform's movement this frame.
 * FIDELITY: ZALiA's TODO "What happens when the platform moves pc into ceiling or floor?" is resolved:
 * horizontal carry keeps ZALiA's cs check (no push into walls); vertical carry now also refuses to push a
 * rider into a solid (cs bit for the movement direction), so a platform descending onto a floor or rising into
 * a ceiling stops carrying instead of embedding the rider.
 */
export function update_go_xy_on_moving_platform(
  platform: GameObject,
  _DIFF_X: number,
  _DIFF_Y: number,
): void {
  const player = pc() as unknown as GameObject
  for (const inst of world.instancesOf(GameObject)) {
    if (!(inst instanceof GameObjectA || inst instanceof GOB1 || inst instanceof NPC || inst instanceof Item))
      continue
    if (!instanceExists(inst.cs_btm_inst) || inst.cs_btm_inst !== platform) continue
    const isPc = inst === player
    // -----------------------------------------------------------
    if (Math.abs(_DIFF_X)) {
      const _HSPD_DIR = inst.hspd_dir
      const _HSPD = inst.hspd
      if (isPc) inst.hspd_dir = sign_(_DIFF_X)
      else inst.hspd = sign_(_DIFF_X) & 0xff // $01 or $FF
      GO_update_cs(inst)
      if (isPc) inst.hspd_dir = _HSPD_DIR
      else inst.hspd = _HSPD
      // a rider against a wall is still carried away from that wall
      if (!(inst.cs & 0x3) || sign_(inst.cs & 0x1) !== sign_(_DIFF_X)) {
        inst.x_change += _DIFF_X
        set_xy(inst, inst.x + _DIFF_X, inst.y)
      }
    }
    // -----------------------------------------------------------
    if (Math.abs(_DIFF_Y)) {
      // ZALiA left the guard commented out under a TODO ("platform moves pc into ceiling or floor?"). Its
      // own condition also refused *downward* carry, which can never work: a rider standing on the platform
      // always has cs4 set. Only the ceiling half is intended, so that is what is kept.
      let blocked = false
      if (_DIFF_Y < 0) {
        GO_update_cs(inst)
        blocked = (inst.cs & 0x8) !== 0 // the rider's head is against a ceiling
      }
      if (!blocked) {
        inst.y_change += _DIFF_Y
        set_xy(inst, inst.x, inst.y + _DIFF_Y)
      }
    }
  }
}

export function Platform_update_1a(self: PlatformBase): void {
  self.BodyHB_can_draw = true
  update_body_hb_1a(self)
  const _DIFF_X = self.x - self.x_prev
  const _DIFF_Y = self.y - self.y_prev
  if (_DIFF_X === 0 && _DIFF_Y === 0) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // updates all GameObject instances
  update_go_xy_on_moving_platform(self, _DIFF_X, _DIFF_Y)
}

// ---- PlatformA ---------------------------------------------------------------------------------------
export function PlatformA_init_1(self: PlatformA): void {
  Platform_init_1(self)
  self.Body_mid_segments = Math.max(0, (spriteInfo('spr_Elevator_2a_WRB').width >> 3) - 2)
  self.ww = 0x10 + (self.Body_mid_segments << 3)
  self.ww_ = self.ww >> 1
  self.hh = 0x8
  self.hh_ = self.hh >> 1
  self.BodyHB_w = self.ww
  self.BodyHB_h = self.hh
  self.Gear_SPRITE = 'spr_Elevator_gear_1a_WRB'
  self.Gear_yscale = 1
  self.Gear_TIMING1 = 0x8
  self.HSPD = 0x10
  self.VSPD = 0x10
  self.hspd1 = self.HSPD
  self.vspd1 = self.VSPD
  self.dg_path = new DsGrid<number>(1, 3, 0)
  self.DELAY1_DUR = 0x40
  self.DELAY2_DUR = 0x10
  self.radius = 0
  self.angle = 0
  self.REV_DUR = 6 // Duration (in seconds) it takes to make a full revolution
  self.rev_dur = self.REV_DUR
  self.SPEED1 = 1 // degree change per frame
}

function resizePath(self: PlatformA, count: number): void {
  self.dg_path = new DsGrid<number>(count, 3, 0)
}

export function PlatformA_init_2(self: PlatformA): void {
  self.BodyHB_idx = -1
  self.dg_path.set(0, 1, self.x)
  self.dg_path.set(0, 2, self.y)
  let _path: string | number = '00'
  let _start = 0
  let _width = self.ww
  const spawn = gp().dm_spawn
  if (self.dk_spawn !== undefined) {
    self.path_dir = Math.sign(spawn.val(self.dk_spawn + STR_Direction) as number)
    const p = spawn.get(self.dk_spawn + STR_Path)
    if (p !== undefined) _path = p as string | number
    const s = spawn.get(self.dk_spawn + STR_Start)
    if (s !== undefined) _start = spawn.val(self.dk_spawn + STR_Start) as number
    if (spawn.get(self.dk_spawn + STR_HSPD) !== undefined)
      self.hspd1 = spawn.val(self.dk_spawn + STR_HSPD) as number
    if (spawn.get(self.dk_spawn + STR_VSPD) !== undefined)
      self.vspd1 = spawn.val(self.dk_spawn + STR_VSPD) as number
    if (spawn.get(self.dk_spawn + STR_Width) !== undefined)
      _width = spawn.val(self.dk_spawn + STR_Width) as number
  }
  self.Body_mid_segments = Math.max(0, (_width >> 3) - 2) // Left + Right ends
  self.ww = 0x10 + (self.Body_mid_segments << 3)
  self.ww_ = self.ww >> 1
  self.hh = 0x8
  self.hh_ = self.hh >> 1
  self.sprite_index_xoff = self.ww_
  self.sprite_index_yoff = self.hh_
  // Sets cs offsets. GameObject_Create() runs setCSOffsets() after init2() making cs offsets only good for $18 wide platform
  self.scr_init3 = PlatformA_init3 as (s: unknown) => void
  self.BodyHB_w = self.ww
  self.BodyHB_h = self.hh
  switch (self.ver) {
    case 1: {
      // ------------  PATH MOVEMENT ---------------------
      self.path_dir = sign_(self.path_dir)
      const pathStr = String(_path)
      const _COUNT = pathStr.length >> 3
      resizePath(self, _COUNT)
      for (let _i = _COUNT - 1; _i >= 0; _i--) {
        self.dg_path.set(_i, 1, str_hex(pathStr.substr((_i << 3) + 4, 4)) + self.ww_)
        self.dg_path.set(_i, 2, str_hex(pathStr.substr(_i << 3, 4)) + self.hh_)
      }
      // -1 means don't set location_a.
      _start = Math.min(Math.max(_start, -1), _COUNT - 1)
      if (gmBool(_start + 1)) {
        self.location_a = _start
        self.location_b = self.location_a
      }
      if (_COUNT > 1) {
        // if more than 1 location in the path.
        if (!inRange(self.location_a + self.path_dir, 0, _COUNT - 1)) self.path_dir = -self.path_dir
        self.location_b = self.location_a + self.path_dir
      }
      set_xy(
        self,
        self.dg_path.get(self.location_a, 1) as number,
        self.dg_path.get(self.location_a, 2) as number,
      )
      self.timer = self.DELAY1_DUR
      break
    }
    case 2: {
      // --------------  CIRCLE MOVEMENT  ----------------
      resizePath(self, 2)
      self.location_a = 0
      self.location_b = self.location_a + 1
      self.spawn_xl = (self.spawn_xl << 3) - (self.ww >> 1)
      self.spawn_yt = (self.spawn_yt << 3) - (self.hh >> 1)
      set_xlyt(self, self.spawn_xl, self.spawn_yt)
      self.dg_path.set(self.location_a, 1, self.x)
      self.dg_path.set(self.location_a, 2, self.y)
      self.radius = str_hex(String(_path)) << 3
      self.angle = _start % 360 // Start angle. mod 360 just in case
      set_xy_len_ang(
        self,
        self.dg_path.get(self.location_a, 1) as number,
        self.dg_path.get(self.location_a, 2) as number,
        self.radius,
        self.angle,
      )
      self.dg_path.set(self.location_b, 1, self.x)
      self.dg_path.set(self.location_b, 2, self.y)
      self.REV_DUR = 3 * (self.radius >> 5)
      self.rev_dur = self.REV_DUR
      self.SPEED1 = 360 / self.rev_dur / 60 // room_speed
      self.speed1 = self.SPEED1
      break
    }
  }
  setBodyHb(self)
}

function setBodyHb(self: PlatformBase): void {
  self.BodyHB_xl = self.x - (self.BodyHB_w >> 1)
  self.BodyHB_xr = self.BodyHB_xl + self.BodyHB_w
  self.BodyHB_yt = self.y - (self.BodyHB_h >> 1)
  self.BodyHB_yb = self.BodyHB_yt + self.BodyHB_h
}

export function PlatformA_init3(self: PlatformA): void {
  switch (self.ver) {
    case 1:
      // CS_TOP
      self.csTop1_xoff = 4
      self.csTop1_yoff = -1
      self.csTop2_xoff = self.ww - self.csTop1_xoff - 1
      self.csTop2_yoff = self.csTop1_yoff
      // CS_BOT
      self.csBtm1_xoff = self.csTop1_xoff
      self.csBtm1_yoff = self.hh - self.csTop1_yoff - 1
      self.csBtm2_xoff = self.csTop2_xoff
      self.csBtm2_yoff = self.csBtm1_yoff
      // CS_LFT
      self.csLft1_xoff = -1
      self.csLft1_yoff = 2
      self.csLft2_xoff = self.csLft1_xoff
      self.csLft2_yoff = self.csRgt2_yoff
      // CS_RGT
      self.csRgt1_xoff = self.ww - self.csLft1_xoff - 1
      self.csRgt1_yoff = self.csLft1_yoff
      self.csRgt2_xoff = self.csRgt1_xoff
      self.csRgt2_yoff = self.hh - self.csRgt1_yoff - 1
      break
    case 2: // CIRCULAR MOVEMENT
      break
  }
}

export function PlatformA_update(self: PlatformA): void {
  self.x_prev = self.x
  self.y_prev = self.y
  GO_update_cam_vars(self)
  update_cs_points_1(self)
  GO_update_cs_1(self)
  update_EF11(self)
  switch (self.ver) {
    case 1: {
      // ------------  PATH MOVEMENT ---------------------
      if (self.dg_path.width <= 1) return // Only 1 location. Does not move.
      if (gmBool(self.timer)) {
        self.timer--
        if (!gmBool(self.timer)) {
          self.hspd_dir = Math.sign(
            (self.dg_path.get(self.location_b, 1) as number) -
              (self.dg_path.get(self.location_a, 1) as number),
          )
          self.hspd = (self.hspd1 * self.hspd_dir) & 0xff
          self.vspd_dir = Math.sign(
            (self.dg_path.get(self.location_b, 2) as number) -
              (self.dg_path.get(self.location_a, 2) as number),
          )
          self.vspd = (self.vspd1 * self.vspd_dir) & 0xff
        } else {
          return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
        }
      }
      if (gmBool(self.hspd) && !(self.cs & 0x3)) updateX(self)
      if (gmBool(self.vspd) && !(self.cs & 0xc)) updateY(self)
      update_cs_points_1(self)
      GO_update_cs_1(self)
      const _X_CS_COND =
        gmBool(self.hspd) && gmBool(self.cs & 0x3) && bit_dir(self.cs & 0x3) === sign8b(self.hspd)
      const _Y_CS_COND =
        gmBool(self.vspd) && gmBool(self.cs & 0xc) && bit_dir(self.cs & 0xc) === sign8b(self.vspd)
      if (_X_CS_COND || _Y_CS_COND) {
        let _x = self.x
        let _y = self.y
        if (_X_CS_COND) _x = (((self.xl >> 3) + (self.hspd & 0x80 && self.xl & 0x7 ? 1 : 0)) << 3) + self.ww_
        if (_Y_CS_COND) _y = (((self.yt >> 3) + (self.vspd & 0x80 && self.yt & 0x7 ? 1 : 0)) << 3) + self.hh_
        set_xy(self, _x, _y)
      }
      setBodyHb(self)
      const _X_DIST1 = (self.x - (self.dg_path.get(self.location_b, 1) as number)) * sign8b(self.hspd)
      const _Y_DIST1 = (self.y - (self.dg_path.get(self.location_b, 2) as number)) * sign8b(self.vspd)
      if ((_X_DIST1 >= 0 || _X_CS_COND) && (_Y_DIST1 >= 0 || _Y_CS_COND)) {
        if (_X_DIST1 >= 0) set_xy(self, self.dg_path.get(self.location_b, 1) as number, self.y)
        if (_Y_DIST1 >= 0) set_xy(self, self.x, self.dg_path.get(self.location_b, 2) as number)
        self.location_a = self.location_b
        if (!inRange(self.location_a + self.path_dir, 0, self.dg_path.width - 1)) {
          self.path_dir = -self.path_dir
          self.timer = self.DELAY1_DUR
        } else {
          self.timer = self.DELAY2_DUR
        }
        self.location_b = self.location_a + self.path_dir
        self.hspd = 0
        self.vspd = 0
      }
      break
    }
    case 2: {
      // --------------  CIRCULAR MOVEMENT  ----------------
      if (gmBool(self.timer)) {
        self.timer--
        break
      }
      if (self.path_dir !== 0) {
        // You can set spin_dir to 0 to stop all movement.
        self.angle += self.speed1 * -self.path_dir // -path_dir: bc, in degrees, clockwise goes backwards.
        if (self.angle <= 0) self.angle += 360
        else self.angle %= 360
        set_xy_len_ang(
          self,
          self.dg_path.get(self.location_a, 1) as number,
          self.dg_path.get(self.location_a, 2) as number,
          self.radius,
          self.angle,
        )
      }
      update_body_hb_1a(self)
      break
    }
  }
  Platform_update_1a(self)
  GO_update_cam_vars(self)
  update_EF11(self)
}

export function PlatformA_udp(self: PlatformA): void {
  self.can_draw_self = true
  if (abs8b(self.hspd) > abs8b(self.vspd)) self.Gear_yscale = sign_(self.xl & self.Gear_TIMING1)
  else self.Gear_yscale = sign_(self.yt & self.Gear_TIMING1)
}

export function PlatformA_draw(self: PlatformA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // Body: left end + mid segments + right end from spr_Elevator_2a_WRB (ZALiA pre-renders this to a surface)
  const _Body_SPRITE = 'spr_Elevator_2a_WRB'
  const bx = self.drawX - self.ww_
  const by = self.drawY - self.hh_
  pal_swap_set(self.palidx)
  draw_sprite_(self.Gear_SPRITE, 0, self.drawX - self.ww_ + 4, self.drawY, -1, 1, self.Gear_yscale)
  draw_sprite_(self.Gear_SPRITE, 0, self.drawX + self.ww_ - 4, self.drawY, -1, -1, self.Gear_yscale)
  let _clm = -1
  draw_sprite_part_(_Body_SPRITE, 0, 0, 0, 0x8, 0x8, bx + (++_clm << 3), by, self.palidx) // Left end
  for (let i = 0; i < self.Body_mid_segments; i++)
    draw_sprite_part_(_Body_SPRITE, 0, 0x8, 0, 0x8, 0x8, bx + (++_clm << 3), by, self.palidx)
  draw_sprite_part_(
    _Body_SPRITE,
    0,
    spriteInfo(_Body_SPRITE).width - 0x8,
    0,
    0x8,
    0x8,
    bx + self.ww - 0x8,
    by,
    self.palidx,
  ) // Right end
  pal_swap_reset()
  // ------------------------------------------------------------------------------
  if (!gmBool(gp().DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (!gp().can_draw_cs) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  self.depth = DEPTH_BASE_HUD
  godHooks.GO_draw_cs_points(self)
  for (let _i = self.dg_path.width - 1; _i >= 0; _i--) {
    drawPointCross(self.dg_path.get(_i, 1) as number, self.dg_path.get(_i, 2) as number, c_lime, c_purple)
  }
  drawPointCross(self.x, self.y, c_white, c_orange)
}

export function PlatformA_end(self: PlatformA): void {
  resizePath(self, 0)
}

// ---- PlatformB ---------------------------------------------------------------------------------------
/** `PlatformB_init_1()` — PlatformB: A cloud that can be stood on & ridden. */
export function PlatformB_init_1(self: PlatformB): void {
  Platform_init_1(self)
  self.hspd_dir = 1
  self.hspd1 = 0
  self.hspd = self.hspd1
  self.vspd1 = 0
  self.vspd = self.vspd1
  self.x_prev = self.x
  self.y_prev = self.y
  self.BodyHB_idx = self.BodyHB_IDX
}
export function PlatformB_init_2(self: PlatformB): void {
  const spawn = gp().dm_spawn
  if (self.dk_spawn !== undefined) {
    const _val = spawn.get(self.dk_spawn + STR_pal_idx)
    if (_val !== undefined) {
      if (gmBool((_val as number) + 1)) GO_init_palidx(self, _val as number)
      self.palidx_permut = 4 // 4:SHM.  Sharing water palette
    }
    self.hspd_dir = Math.sign(spawn.val(self.dk_spawn + STR_Direction) as number)
    // (STR_Path / STR_Start are read into locals ZALiA never uses)
  }
  self.hspd1 = 0x01 << 3
  self.hspd = (self.hspd1 * self.hspd_dir) & 0xff
  switch (self.ver) {
    case 1:
      GO_depth_init(self, DEPTH_FG4 - 1)
      GO_sprite_init(self, 'spr_cloud_2a')
      GO_init_palidx(self, GG().PI_CLOUD_1)
      self.palidx_permut = 2 // 2:MHS
      break
    case 2: // RAFT
      break
  }
}
export function PlatformB_update(self: PlatformB): void {
  self.x_prev = self.x
  self.y_prev = self.y
  GO_update_cam_vars(self)
  update_EF11(self)
  if (gmBool(self.hspd)) updateX(self)
  if (gmBool(self.vspd)) updateY(self)
  switch (self.ver) {
    case 1: // Cloud: wrap around the room
      if (gmBool(self.hspd_dir)) {
        if (self.x >= self.ww_ + gp().rm_w) set_xy(self, -(self.x & 0xff), self.y)
      } else if (self.x <= -self.ww_) set_xy(self, (self.x & 0xff) + gp().rm_w, self.y)
      break
    case 2:
      break
  }
  Platform_update_1a(self)
  GO_update_cam_vars(self)
  update_EF11(self)
}
export function PlatformB_udp(self: PlatformB): void {
  self.can_draw_self = true
  self.palidx_base = self.palidx_def
}
export function PlatformB_draw(self: PlatformB): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  switch (self.ver) {
    case 1: // Cloud
      if (self.sprite) draw_sprite_(self.sprite, 0, self.drawX, self.drawY, self.palidx)
      break
    case 2: {
      // Raft.  TODO(ZALiA): Pre-process raft graphic
      pal_swap_set(self.palidx_base)
      for (let _i = 0; _i < self.Tile_COUNT; _i++) {
        draw_background_part(self.Raft_TS, self.Raft_TS_X, self.Raft_TS_Y, 8, 8, self.xl + (_i << 3), self.yt)
      }
      pal_swap_reset()
      break
    }
  }
  godHooks.GO_draw_body_hb(self)
}

// ---- PlatformCloud -----------------------------------------------------------------------------------
export function PlatformCloud_init1(self: PlatformCloud): void {
  Platform_init_1(self)
  GO_depth_init(self, DEPTH_FG4 - 1)
  GO_init_palidx(self, GG().PI_CLOUD_1)
  self.CLMS_MIN = 6
  self.CLMS_MAX = gp().rm_clms + self.CLMS_MIN
  self.CLMS = self.CLMS_MIN
  self.BODY_XOFF = 4
  self.BODY_W = ((self.CLMS << 3) - Math.abs(self.BODY_XOFF)) << 1 // GML precedence: (a - b) << 1
  self.BodyHB_w = self.BODY_W
  self.Cloud_SPR1 = 0
}
export function PlatformCloud_init2(self: PlatformCloud): void {
  self.solid_type = TID_ONEWY1
  let _CloudMid_CNT = 0
  if (self.dk_spawn !== undefined) {
    const d = gp().dm_spawn.get(`${self.dk_spawn + STR_Data}01`)
    if (d !== undefined) _CloudMid_CNT = d as number
  }
  self.CLMS = self.CLMS_MIN + (_CloudMid_CNT << 1)
  self.CLMS = Math.min(Math.max(self.CLMS, self.CLMS_MIN), self.CLMS_MAX)
}
export function PlatformCloud_update(self: PlatformCloud): void {
  self.x_prev = self.x
  self.y_prev = self.y
  if (gmBool(self.hspd)) updateX(self)
  if (gmBool(self.vspd)) updateY(self)
  self.BodyHB_w = self.BODY_W
  self.BodyHB_h = 8
  self.BodyHB_xl = self.xl + self.BODY_XOFF
  self.BodyHB_xr = self.BodyHB_xl + self.BodyHB_w
  self.BodyHB_yt = self.y - (self.BodyHB_h >> 1)
  self.BodyHB_yb = self.BodyHB_yt + self.BodyHB_h
  self.BodyHB_can_draw = true
  Platform_update_1a(self)
  GO_update_cam_vars(self)
  update_EF11(self)
}
export function PlatformCloud_udp(self: PlatformCloud): void {
  self.can_draw_self = true
}
export function PlatformCloud_draw(self: PlatformCloud): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  PlatformCloud_draw_1a(self)
  GO_draw_sprite(self, self.Cloud_SPR1, self.palidx)
  if (!gmBool(gp().DevTools_state)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  godHooks.GO_draw_body_hb(self)
}
/**
 * `PlatformCloud_draw_1a()` — builds the cloud graphic once from `ts_Natural1_HMS` parts. ZALiA draws the
 * parts to a surface and makes a sprite; here the part list is registered as a composite sprite key.
 */
export function PlatformCloud_draw_1a(self: PlatformCloud): void {
  if (self.Cloud_SPR1) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const _TSRC0 = 0xc0
  const _TL0 = _TSRC0 // TL: TOP LFT
  const _TL1 = _TSRC0 + 0xd
  const _BL0 = _TSRC0 + 0x4 // BL: BTM LFT
  const _TR0 = _TSRC0 + 0x3 // TR: TOP RGT. Small one
  const _TR1 = _TSRC0 + 0x2
  const _BR0 = _TSRC0 + 0x7 // BR: BTM RGT
  const _TM0 = _TSRC0 + 0x1 // TM: TOP MID
  const _TM1 = _TSRC0 + 0xe
  let _a = 0x8
  const _MT0 = _TSRC0 + _a++ // MT: MID TOP
  const _MT1 = _TSRC0 + _a++
  const _MT2 = _TSRC0 + _a++
  _a = 0xb
  const _MB0 = _TSRC0 + _a++ // MB: MID BTM
  const _MB1 = _TSRC0 + _a++
  _a = 0x5
  const _BM0 = _TSRC0 + _a++ // BM: BTM MID
  const _BM1 = _TSRC0 + _a++
  const col = (r0: number, r1: number, r2: number, r3: number) =>
    (r0 << 0) + (r1 << 8) + (r2 << 16) + (r3 << 24)
  const _BM_00 = col(0, 0, _MB0, _BM0)
  const _BM_11 = col(0, 0, _MB1, _BM1)
  const _TM_00 = col(_TM0, _MT0, 0, 0)
  const _TM_01 = col(_TM0, _MT1, 0, 0)
  const _TM_02 = col(_TM0, _MT2, 0, 0)
  const _TM_10 = col(_TM1, _MT0, 0, 0)
  const _TM_11 = col(_TM1, _MT1, 0, 0)
  const _TM_12 = col(_TM1, _MT2, 0, 0)
  void _TM_11
  const _dl_tsrc: number[] = new Array(self.CLMS).fill(0)
  // RGT end CLMS
  let _idx = self.CLMS - 1
  _dl_tsrc[_idx--] = col(0, _TR0, _BR0, 0)
  _dl_tsrc[_idx--] = col(_TR0, _TR1, _BM0, _BR0)
  _dl_tsrc[_idx--] = col(_TM0, _MT1, _MB0, _BM0)
  // LFT end clms
  _idx = 0
  _dl_tsrc[_idx++] = col(0, _TL0, _BL0, 0)
  _dl_tsrc[_idx++] = col(_TL0, _TL1, _MB0, _BL0)
  _dl_tsrc[_idx++] = col(_TM0, _MT1, _MB0, _BM0)
  const _dl_mid = [
    _TM_02 + _BM_00,
    _TM_10 + _BM_11,
    _TM_01 + _BM_00,
    _TM_02 + _BM_11,
    _TM_00 + _BM_00,
    _TM_12 + _BM_11,
    _TM_00 + _BM_00,
    _TM_02 + _BM_11,
    _TM_10 + _BM_00,
    _TM_01 + _BM_11,
    _TM_00 + _BM_00,
    _TM_12 + _BM_11,
  ]
  const _COUNT1 = _dl_mid.length
  const _COUNT2 = self.CLMS_MIN >> 1
  const _COUNT3 = self.CLMS - self.CLMS_MIN
  for (let _i = 0; _i < _COUNT3; _i++) _dl_tsrc[_i + _COUNT2] = _dl_mid[_i % _COUNT1] as number
  self.CLMS = Math.min(Math.max(_dl_tsrc.length, self.CLMS_MIN), self.CLMS_MAX)
  const _ROWS = 4
  const _SURF_W = self.CLMS << 3
  const _SURF_H = _ROWS << 3
  const parts: CloudBody['parts'] = []
  for (let _i = 0; _i < self.CLMS; _i++) {
    // Each clm
    const _tsrc_clm = _dl_tsrc[_i] as number
    for (let _j = 0; _j < _ROWS; _j++) {
      // Each row/tsrc byte
      const _tsrc = (_tsrc_clm >> (_j << 3)) & 0xff
      if (!_tsrc) continue
      parts.push({ left: ((_tsrc >> 0) & 0xf) << 3, top: ((_tsrc >> 4) & 0xf) << 3, x: _i << 3, y: _j << 3 })
    }
  }
  self.Cloud_SPR1 = godHooks.registerCloudSprite({
    tileset: gp().ts_Natural1_HMS,
    width: _SURF_W,
    height: _SURF_H,
    parts,
  })
  GO_sprite_init(self, self.Cloud_SPR1)
  set_xy(self, self.xl + (_SURF_W >> 1), self.y)
  self.BODY_W = (self.CLMS << 3) - (Math.abs(self.BODY_XOFF) << 1)
}
export function PlatformCloud_end(self: PlatformCloud): void {
  self.Cloud_SPR1 = 0
}

// ---- PlatformRaft ------------------------------------------------------------------------------------
export function PlatformRaft_init_1(self: PlatformRaft): void {
  Platform_init_1(self)
  self.hspd_dir = 1
  self.hspd1 = 0
  self.hspd = self.hspd1
  self.vspd_dir = 1
  self.vspd1 = 0
  self.vspd = self.vspd1
  self.x_prev = self.x
  self.y_prev = self.y
  self.BodyHB_idx = self.BodyHB_IDX
  self.dock_state = self.dock_state_FREE0
  self.dock_xc = 0
}
export function PlatformRaft_init_2(self: PlatformRaft): void {
  if (!(fp().items & ITM_RAFT)) {
    self.destroy()
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  let _PATH: string | number = 0
  GO_depth_init(self, DEPTH_PC_MAIN - 1)
  self.Raft_TS = 'ts_Man_made_1a_WRB'
  self.Raft_TSRC1 = 0xa0
  self.Raft_TS_X = ((self.Raft_TSRC1 >> 0) & 0xf) << 3
  self.Raft_TS_Y = ((self.Raft_TSRC1 >> 4) & 0xf) << 3
  self.Tile_COUNT = self.ww >> 3
  self.dock_state = self.dock_state_FREE0
  const spawn = gp().dm_spawn
  const exitEnter = gp().exit_enter as { side: number } | null
  if (self.dk_spawn !== undefined) {
    const _val = spawn.get(self.dk_spawn + STR_pal_idx)
    if (_val !== undefined && gmBool((_val as number) + 1)) GO_init_palidx(self, _val as number)
    self.hspd_dir = Math.sign(spawn.val(self.dk_spawn + STR_Direction) as number)
    const p = spawn.get(self.dk_spawn + STR_Path)
    if (p !== undefined) _PATH = p as string | number
    // If this is a rm w/ a dock: is raft waiting for player or is player already riding raft going towards
    // the dock? Compare the raft dock launch dir to the side of g.exit_enter to determine.
    if (_PATH === STR_Dock) {
      if (exitEnter && exitEnter.side & 0x3 && (exitEnter.side & 0x3) !== dir8b(self.hspd_dir)) {
        // The exit dir is opposite of raft travel dir, raft will be docked waiting for player.
        self.dock_state = self.dock_state_DOCKED0 // Wait for player to board
      } else self.dock_state = self.dock_state_FREE1 // Player riding raft toward dock.
      self.dock_xc = self.x
    }
  }
  self.hspd1 = 0x01 << 3
  self.hspd = (self.hspd1 * self.hspd_dir) & 0xff
  switch (self.ver) {
    case 1: {
      // RAFT
      if (isVal(self.dock_state, self.dock_state_FREE0, self.dock_state_FREE1)) set_xy(self, pc().x, self.y)
      if (exitEnter && exitEnter.side & 0x3) self.hspd_dir = -sign_(exitEnter.side & 0x1)
      self.hspd1 = 0x0c
      self.hspd = (self.hspd1 * self.hspd_dir) & 0xff
      self.WaterUndulate_DUR1 = 0x30
      self.WaterUndulate_DUR2 = 0x14
      self.WaterUndulate_DUR3 = 0x0c
      self.WaterUndulate_dur = self.WaterUndulate_DUR1
      self.WaterUndulate_timer = self.WaterUndulate_dur
      self.WaterUndulate_yoff_MAX = 2 // -2,-1,0,1,2
      self.WaterUndulate_yoff = self.WaterUndulate_yoff_MAX
      self.WaterUndulate_dir = -sign_(self.WaterUndulate_yoff)
      self.DistantWater_DEPTH = DEPTH_BG7
      self.DistantWater_xoff = 0
      self.DistantWater_undulate = false // (ZALiA computes it from dl_pal_swap_depths then forces false)
      if (self.DistantWater_undulate) tile_layer_shift(self.DistantWater_DEPTH, 0, -4)
      break
    }
  }
}
export function PlatformRaft_update(self: PlatformRaft): void {
  self.x_prev = self.x
  self.y_prev = self.y
  GO_update_cam_vars(self)
  update_EF11(self)
  const player = pc() as unknown as GameObject
  if (self.dock_state === self.dock_state_FREE0 || self.dock_state === self.dock_state_FREE1) {
    if (gmBool(self.hspd)) updateX(self)
    if (gmBool(self.vspd)) updateY(self)
    if (self.dock_state === self.dock_state_FREE1) {
      const _SIGN = Math.sign(self.x - self.dock_xc)
      if (_SIGN === 0 || _SIGN === self.hspd_dir) {
        self.dock_state = self.dock_state_DOCKED1 // Docked and waiting for player to get off
        self.hspd_dir = -self.hspd_dir
        self.hspd = (self.hspd1 * self.hspd_dir) & 0xff
      }
    }
    // In the event PC is left stranded, the RAFT will reverse its direction if it gets far enough outside the room.
    if (player.cs_btm_inst !== self && !wINw(self.xl, self.ww, -self.ww, gp().rm_w + (self.ww << 1))) {
      self.hspd_dir = -self.hspd_dir
      self.hspd = (self.hspd1 * self.hspd_dir) & 0xff
      if (gmBool(self.dock_xc) && -Math.sign(self.x - self.dock_xc) === self.hspd_dir)
        self.dock_state = self.dock_state_FREE1
    }
  } else if (!gmBool(player.stun_timer) && !gmBool(player.ogr)) {
    switch (self.dock_state) {
      case self.dock_state_DOCKED0: // Docked and waiting for player to get on
        if (player.cs_btm_inst === self && inRange(player.x, self.x - 0x10, self.x + 0x10))
          self.dock_state = self.dock_state_FREE0
        break
      case self.dock_state_DOCKED1: // Docked and waiting for player to get off
        if (player.cs_btm_inst !== self) self.dock_state = self.dock_state_DOCKED0
        break
    }
  }
  if (gmBool(self.WaterUndulate_timer)) {
    self.WaterUndulate_timer--
    if (!gmBool(self.WaterUndulate_timer)) {
      set_xy(self, self.x, self.y + self.WaterUndulate_dir)
      tile_layer_shift(gp().dg_anim_liquid.get(0, 0) as number, 0, self.WaterUndulate_dir)
      self.WaterUndulate_yoff += self.WaterUndulate_dir
      if (Math.abs(self.WaterUndulate_yoff) === 2) self.WaterUndulate_dir = -self.WaterUndulate_dir
      switch (Math.abs(self.WaterUndulate_yoff)) {
        case 0:
          self.WaterUndulate_dur = self.WaterUndulate_DUR3
          break
        case 1:
          self.WaterUndulate_dur = self.WaterUndulate_DUR2
          break
        case 2:
          self.WaterUndulate_dur = self.WaterUndulate_DUR1
          break
      }
      self.WaterUndulate_timer = self.WaterUndulate_dur
    }
    if (self.DistantWater_undulate) {
      if (!(g.counter1 & 0x7)) {
        tile_layer_shift(self.DistantWater_DEPTH, self.DistantWater_xoff, 0)
        self.DistantWater_xoff++
        self.DistantWater_xoff &= 0x7
        tile_layer_shift(self.DistantWater_DEPTH, -self.DistantWater_xoff, 0)
      }
      if (self.WaterUndulate_timer === self.WaterUndulate_dur >> 2)
        tile_layer_shift(self.DistantWater_DEPTH, 0, -self.WaterUndulate_dir)
    }
  }
  Platform_update_1a(self)
  self.BodyHB_can_draw = true
  self.BodyHB_xoff = 0
  self.BodyHB_yoff = 0
  self.BodyHB_w = self.ww
  self.BodyHB_h = self.hh
  update_body_hb(self)
  GO_update_cam_vars(self)
  update_EF11(self)
}
export function PlatformRaft_udp(self: PlatformRaft): void {
  self.can_draw_self = true
  self.palidx_base = self.palidx_def
}
export function PlatformRaft_draw(self: PlatformRaft): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  pal_swap_set(self.palidx_base)
  for (let _i = 0; _i < self.Tile_COUNT; _i++) {
    // Each plank(tile) (ZALiA pre-renders these to Raft_SURF)
    draw_background_part(
      self.Raft_TS,
      self.Raft_TS_X,
      self.Raft_TS_Y,
      8,
      8,
      self.drawX - self.ww_ + (_i << 3),
      self.drawY - self.hh_,
    )
  }
  pal_swap_reset()
  godHooks.GO_draw_body_hb(self)
}
