/**
 * Spell cost rando — ported from `Rando_randomize_spell_costs.gml` (190 lines).
 *
 * Every spell's cost at every magic level is jittered around its vanilla cost (-25%..+10%), clamped to
 * 2..`_max_cost`, forced even (the NES MP bar steps in 2s) and forced to be no more expensive than the
 * previous (lower) magic level. `_max_cost` is the spell's `_Rando_Cost_Max` cap, further capped by its
 * own level-0 vanilla cost. `file_load` reads `STR_Spell+STR_Cost+<spell><level>` back into
 * `g.dg_spell_cost`.
 *
 * Dropped:
 * - `switch(3)` cases 1 (`:21-60`, "Version before 2024/06/23") and 2 (`:70-118`, "Version as of
 *   2024/06/23") — unreachable, the switch scrutinee is the literal `3`. Only case 3 (`:128-185`,
 *   "Version as of 2024/09/29") runs.
 * - the two `/* *\/` blocks at `:78-91` and `:137-150` (the hard-coded `_max_cost` tables that the
 *   `g.dm_Spell[?…_Rando_Cost_Max]` lookup replaced).
 * - the `if (0&&DEBUG){…}` spoiler-log blocks at `:52-57`, `:110-115` and `:173-182`, and the
 *   commented-out one at `:10`. `0&&DEBUG` is always false, so ZALiA emits no `dm_debug_data` line for
 *   spell costs at all — keeping them would *add* lines to the spoiler log.
 */
import { Container_AMT, STR_Cost, STR_Max, STR_Rando, STR_Spell } from '@z2/data'
import { gmRound as round } from '../../nes/math8'
import { g, world } from '../../runtime/world'
import { hex_str, val } from '../other/index'
import { clamp } from './helpers'
import type { Rando } from './Rando'

export function Rando_randomize_spell_costs(self: Rando): void {
  world.random_set_seed(self.Rando_SEED)

  const _datakey = STR_Spell + STR_Cost
  const _LEVEL_COUNT = g.dg_spell_cost.height

  // Version as of 2024/09/29
  for (let _i = g.dg_spell_cost.width - 1; _i >= 1; _i--) {
    // Each spell
    const _spell_bit = 0x1 << (_i - 1)
    let _max_cost = val(
      g.dm_Spell.get(hex_str(_spell_bit) + STR_Rando + STR_Cost + STR_Max),
      Container_AMT * 3,
    ) as number
    _max_cost = Math.min(_max_cost, g.dg_spell_cost.get(_i, 0) as number)

    let _val0 = _max_cost
    for (let _j = 0; _j < _LEVEL_COUNT; _j++) {
      // Each magic level
      let _val1 = g.dg_spell_cost.get(_i, _j) as number
      _val1 = Math.min(_val1, _max_cost)

      const _max = _val1 + round(_val1 * 0.1)
      const _min = _val1 - round(_val1 * 0.25)
      let _val = _min + world.irandom(_max - _min)

      _val = Math.min(_val, _val0 - 2 * (_j > 0 ? 1 : 0)) // cannot be more expensive than previous(_j-1: _val0) magic level
      _val = clamp(_val, 2, _max_cost)
      _val = (_val >> 1) << 1 // keep mp costs even

      _val0 = _val

      self.dm_save_data.set(_datakey + hex_str(_i) + hex_str(_j), _val)
    }
  }
}
