import type { GpButton, Key, RawInput } from '@z2/core'

/** Phaser key codes (`Phaser.Input.Keyboard.KeyCodes`) for the keys ZALiA reads. Values are DOM keyCodes. */
export const KEY_CODES: Record<Key, number> = {
  A: 65,
  D: 68,
  E: 69,
  F: 70,
  G: 71,
  H: 72,
  I: 73,
  J: 74,
  K: 75,
  L: 76,
  M: 77,
  N: 78,
  O: 79,
  R: 82,
  S: 83,
  T: 84,
  U: 85,
  V: 86,
  W: 87,
  Z: 90,
  vk_right: 39,
  vk_left: 37,
  vk_down: 40,
  vk_up: 38,
  vk_enter: 13,
  vk_control: 17,
  vk_backspace: 8,
  vk_space: 32,
  vk_escape: 27,
  vk_shift: 16,
  F1: 112,
  F2: 113,
  F3: 114,
  F8: 119,
}
export const ALL_KEYS = Object.keys(KEY_CODES) as Key[]

/**
 * W3C standard gamepad button indices → GameMaker button names (Xbox layout, what ZALiA's defaults assume).
 * https://w3c.github.io/gamepad/#remapping
 */
export const STANDARD_BUTTONS: Record<number, GpButton> = {
  0: 'gp_face1', // A / cross
  1: 'gp_face2', // B / circle
  2: 'gp_face3', // X / square
  3: 'gp_face4', // Y / triangle
  4: 'gp_shoulderl',
  5: 'gp_shoulderr',
  6: 'gp_shoulderlb', // LT
  7: 'gp_shoulderrb', // RT
  8: 'gp_select',
  9: 'gp_start',
  12: 'gp_padu',
  13: 'gp_padd',
  14: 'gp_padl',
  15: 'gp_padr',
}

/** Device snapshot independent of Phaser, so the mapping is unit-testable. */
export interface DeviceSnapshot {
  keysDown: ReadonlySet<Key>
  gamepad: { id: string; buttons: readonly boolean[]; axes: readonly number[] } | null
}

const AXIS_DEADZONE = 0.5

/** Keeps last-frame state to derive pressed/released edges (GM `*_check_pressed/released`). */
export class InputMapper {
  private prevKeys: ReadonlySet<Key> = new Set()
  private prevButtons: ReadonlySet<GpButton> = new Set()

  map(snap: DeviceSnapshot): RawInput {
    const keysPressed = new Set<Key>()
    for (const k of snap.keysDown) if (!this.prevKeys.has(k)) keysPressed.add(k)
    this.prevKeys = snap.keysDown

    let gamepad: RawInput['gamepad'] = null
    if (snap.gamepad) {
      const held = new Set<GpButton>()
      snap.gamepad.buttons.forEach((down, i) => {
        const name = STANDARD_BUTTONS[i]
        if (down && name) held.add(name)
      })
      const pressed = new Set<GpButton>()
      const released = new Set<GpButton>()
      for (const b of held) if (!this.prevButtons.has(b)) pressed.add(b)
      for (const b of this.prevButtons) if (!held.has(b)) released.add(b)
      this.prevButtons = held
      const [lh = 0, lv = 0] = snap.gamepad.axes
      gamepad = {
        connected: true,
        description: snap.gamepad.id,
        held,
        pressed,
        released,
        axisLH: Math.abs(lh) >= AXIS_DEADZONE ? Math.sign(lh) : 0,
        axisLV: Math.abs(lv) >= AXIS_DEADZONE ? Math.sign(lv) : 0,
        axisCount: snap.gamepad.axes.length,
      }
    } else {
      this.prevButtons = new Set()
    }
    return { keysHeld: snap.keysDown, keysPressed, gamepad }
  }
}
