/** `Overworld_Room_Start()` — reset movement/warp/bait state, rebuild the tile window, treasure-map and rando markers. */
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML state
import {
  dk_SpawnDatakey,
  ITM_MAP1,
  ITM_MAP2,
  MK_OWRC_NPAL1,
  STR_1UP,
  STR_Acquired,
  STR_Count,
  STR_Datakey,
  STR_Dungeon,
  STR_HEART,
  STR_ID,
  STR_Item,
  STR_Kakusu,
  STR_KEY,
  STR_Key,
  STR_Location,
  STR_Locations,
  STR_MAGIC,
  STR_Map,
  STR_Name,
  STR_Num,
  STR_Nums,
  STR_Object,
  STR_OWRC,
  STR_PBAG,
  STR_Qualified,
  STR_Quest,
  STR_Randomize,
  STR_Randomized,
  STR_Rm,
  STR_Spawn,
  STR_Total,
  STR_Type,
  STR_Varied,
} from '@z2/data'
import { bitCount, gmBool } from '../../nes/math8'
import { DsMap } from '../../runtime/ds'
import { f, g, p } from '../../runtime/world'
import { roomSize, view } from '../Game/gm'
import { hex_str, strReplaceAt, val } from '../other'
import { get_pal_pos } from '../palette/palString'
import { change_pal } from '../palette/scenePalette'
import { crystal_is_placed, item_acquired } from './deps'
import { gridResize, type Overworld } from './Overworld'
import { Overworld_refresh_tiles, WaterSparkle_refresh } from './tiles'

/** `Overworld_Room_Start()` */
export function Overworld_Room_Start(self: Overworld): void {
  if (g.room_type !== 'C') return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const SHIFT = self.SHIFT
  roomSize.width = self.DRAW_W
  roomSize.height = self.DRAW_H
  view.x = self.CAM_X
  view.y = self.CAM_Y
  self.exit_owrc = 0
  self.pc_x_scale = 1
  self.mot = 0 // mot: Mode Of Transportation.  0: not moving
  self.dest_dist = 0
  self.pc_step_counter = 1
  self.move_spd = 0 // 0: no movement
  self.move_x = 0
  self.move_y = 0
  self.move_speed = 0
  self.move_distance = 0
  self.flute_timer = 0 // 0566
  self.Warp_state = 0
  self.Warp_is_warping = false
  self.Warp_timer = 0
  self.Warp_owrc = 0x00
  self.Warp_x = 0
  self.Warp_y = 0
  self.Warp_yoff = 0
  self.Warp_speed = 0
  self.Warp_destination_num = 0
  self.BAIT_timer = 0
  self.BAIT_owrc = 0x00
  self.BAIT_ow_x = 0
  self.BAIT_ow_y = 0
  // enc_spawn_timer decrements every $14 frames when g.timer_b reaches -1 in update_game_timers()
  self.enc_spawn_timer = 8
  self.enc_spawn_timer += self.enc_spawn_timer_add // 2022/12/05. Attempting to balance enc difficulty
  self.enc_spawn_timer_add = 0
  for (const row of self.dg_enc_inst.cells) row.fill(0)
  self.enc_reen = undefined // reen: Room-Entry Exit-Name
  // pcrc & pc_dir are set in update_change_room_1a() when leaving rmA
  if (!gmBool(self.pc_dir)) self.pc_dir = 0x01
  // [dropped: `if (room == FileSelect)` compared a room index with an object index and never ran — see FIDELITY_NOTES]
  self.pcrc_spawn = self.pcrc
  self.pcrc_map = self.pcrc
  const _PC_CLM = (self.pcrc >> 0) & 0xff
  const _PC_ROW = (self.pcrc >> 8) & 0xff
  const _ow_x0 = (_PC_CLM << SHIFT) + (self.T_SIZE >> 1) - self.DRAW_W_
  const _ow_y0 = (_PC_ROW << SHIFT) + (self.T_SIZE >> 1) - self.DRAW_H_
  Overworld_refresh_tiles(self, _ow_x0, _ow_y0)
  change_pal(strReplaceAt(p.pal_rm_new, get_pal_pos(self.ENC_PI), self.ENC_PAL.length, self.ENC_PAL))
  WaterSparkle_refresh(self, self.pcrc)
  // ----------------------------------------------------------------------
  const TM = self.TreasureMaps_dg
  for (const row of TM.cells) row.fill(0)
  if (f.items & (ITM_MAP1 | ITM_MAP2)) {
    const _dg_map_HEIGHT = TM.height
    gridResize(TM, 0, _dg_map_HEIGHT)
    for (let _i = g.dl_MapItem_ITEM_IDS.size - 1; _i >= 0; _i--) {
      const _item_id = g.dl_MapItem_ITEM_IDS.get(_i) as string
      const _item_type = String(val(g.dm_spawn.get(_item_id + STR_Item + STR_Type)))
      if (_item_type === STR_KEY) {
        if (
          !gmBool(val(f.dm_save_file_settings.get(STR_Randomize + STR_Key + STR_Locations))) ||
          !g.RandoKeys_MAP_items_show_keys
        ) {
          continue //_i
        }
      }
      const _map_num = val(g.dm_spawn.get(_item_id + STR_Map + STR_Num)) as number
      if ((_map_num === 1 && f.items & ITM_MAP1) || (_map_num === 2 && f.items & ITM_MAP2)) {
        let _datakey = _item_id + STR_Spawn + STR_Datakey
        switch (_item_type) {
          case STR_HEART:
          case STR_MAGIC:
          case STR_1UP: {
            if (gmBool(val(f.dm_save_file_settings.get(STR_Randomize + STR_Item + STR_Locations))))
              _datakey += STR_Randomized
            break
          }
          case STR_Kakusu: {
            if (gmBool(val(f.dm_save_file_settings.get(STR_Randomize + STR_Kakusu + STR_Locations))))
              _datakey += STR_Randomized
            break
          }
          case STR_KEY: {
            if (gmBool(val(f.dm_save_file_settings.get(STR_Randomize + STR_Key + STR_Locations))))
              _datakey += STR_Randomized
            break
          }
        }
        const _spawn_datakey = g.dm_spawn.get(_datakey) as string | undefined
        const _qual_quests = val(
          g.dm_spawn.get(_item_id + STR_Qualified + STR_Quest + STR_Nums),
          hex_str(f.quest_num),
        ) as string
        if (_qual_quests.includes(hex_str(f.quest_num)) && _spawn_datakey !== undefined) {
          if (_item_id.includes(STR_Kakusu)) {
            // if defeated
            if (gmBool(val(f.dm_kakusu.get(_spawn_datakey)))) continue //_i
          } else {
            // CONTAINER PIECES, 1UPS, KEYS
            if (gmBool(item_acquired(_item_id))) continue //_i
          }
          const _rm_name = val(g.dm_spawn.get(_spawn_datakey + STR_Rm + STR_Name), 'undefined') as string
          // Make a default owrc right outside North Castle so errors are obvious.
          let _owrc = ((self.OW_ROWS >> 1) & 0xff) << 8
          _owrc |= ((self.OW_CLMS >> 1) & 0xff) << 0
          _owrc = val(g.dm_spawn.get(MK_OWRC_NPAL1), _owrc) as number
          _owrc += 0x08 // horizontal
          _owrc -= 0x0400 // vertical
          _owrc = val(g.dm_rm.get(_rm_name + STR_OWRC), _owrc) as number
          _owrc = val(f.dm_rando.get(_rm_name + STR_OWRC), _owrc) as number
          const _ow_x = (((_owrc >> 0) & 0xff) << 4) + 8
          const _ow_y = (((_owrc >> 8) & 0xff) << 4) + 8
          gridResize(TM, TM.width + 1, _dg_map_HEIGHT)
          const _idx = TM.width - 1
          TM.set(_idx, 0x00, _spawn_datakey)
          TM.set(_idx, 0x01, _owrc)
          TM.set(_idx, 0x02, _ow_x)
          TM.set(_idx, 0x03, _ow_y)
          TM.set(_idx, 0x04, val(g.dm_spawn.get(_item_id + STR_Object)))
          TM.set(_idx, 0x06, val(g.dm_spawn.get(_item_id + STR_Map + STR_Num)))
          TM.set(_idx, 0x07, _item_id)
          TM.set(_idx, 0x08, _item_type)
          TM.set(_idx, 0x09, false) // $9: can draw
        }
      }
    }
  }
  if (gmBool(val(f.dm_save_file_settings.get(STR_Randomize + STR_Item + STR_Locations)))) {
    const _dm1 = new DsMap<number>()
    self.dm_rando_locations.clear()
    const _count = val(f.dm_rando.get(STR_Total + STR_Location + STR_Count)) as number
    for (let _i = 1; _i <= _count; _i++) {
      let _c1: any = false
      const _datakey = STR_Location + hex_str(_i)
      const _item_id = f.dm_rando.get(_datakey + STR_Item + STR_ID + STR_Randomized) as string | undefined
      if (_item_id !== undefined) {
        const _item_type = String(val(g.dm_spawn.get(_item_id + STR_Item + STR_Type)))
        switch (_item_type) {
          case STR_PBAG:
            _c1 = val(f.dm_save_file_settings.get(STR_Randomize + STR_PBAG + STR_Locations))
            break
          case STR_KEY:
            _c1 = val(f.dm_save_file_settings.get(STR_Randomize + STR_Key + STR_Locations))
            break
          default:
            _c1 = true
            break
        }
        if (gmBool(_c1)) {
          const _spawn_datakey = g.dm_spawn.get(_item_id + STR_Spawn + STR_Datakey + STR_Randomized) as
            | string
            | undefined
          if (_spawn_datakey !== undefined) {
            const _rm_name = g.dm_spawn.get(_spawn_datakey + STR_Rm + STR_Name) as string | undefined
            if (_rm_name !== undefined) {
              let _owrc = g.dm_rm.get(_rm_name + STR_OWRC) as number | undefined
              _owrc = val(f.dm_rando.get(_rm_name + STR_OWRC), _owrc) as number | undefined
              if (_owrc !== undefined) {
                const _owrc_ = hex_str(_owrc)
                const _acquired = Math.sign(Number(item_acquired(_item_id)))
                const RL = self.dm_rando_locations
                RL.set(_datakey + STR_OWRC, _owrc)
                RL.set(_datakey + STR_Acquired, _acquired)
                const _count1 = (val(RL.get(_owrc_ + STR_Item + STR_Count)) as number) + 1
                RL.set(_owrc_ + STR_Item + STR_Count, _count1)
                const _count2 = (val(RL.get(_owrc_ + STR_Acquired + STR_Count)) as number) + _acquired
                RL.set(_owrc_ + STR_Acquired + STR_Count, _count2)
                if (_dm1.get(_owrc_) === undefined) _dm1.set(_owrc_, 0x00)
                if (_item_id.includes(STR_PBAG)) _dm1.set(_owrc_, (_dm1.get(_owrc_) as number) | 0x0100)
                else if (_item_id.includes(STR_KEY)) _dm1.set(_owrc_, (_dm1.get(_owrc_) as number) | 0x10)
                else _dm1.set(_owrc_, (_dm1.get(_owrc_) as number) | 0x01)
                if (bitCount(val(_dm1.get(_owrc_)) as number) > 1) RL.set(_owrc_ + STR_Varied, true)
              }
            }
          }
        }
      }
    }
  }
  let _all_conditions_met: any = true
  for (let _i = 1; _i <= 6; _i++) {
    const _dk1 = STR_Dungeon + hex_str(_i)
    const _datakey = `${_dk1}_FullCleared`
    if (!gmBool(val(f.dm_quests.get(_datakey)))) {
      _all_conditions_met = crystal_is_placed(_i)
      if (gmBool(_all_conditions_met)) {
        const _dk2 = _dk1 + STR_Item
        const _count1 = val(g.dm_spawn.get(_dk2 + STR_Count)) as number
        if (gmBool(_count1)) {
          for (let _j = 1; _j <= _count1; _j++) {
            if (!gmBool(_all_conditions_met)) break //_j
            const _dk3 = _dk2 + hex_str(_j)
            let _spawn_datakey = g.dm_spawn.get(_dk3 + dk_SpawnDatakey) as string | undefined
            if (_spawn_datakey !== undefined) {
              _spawn_datakey = val(
                g.dm_spawn.get(_spawn_datakey + STR_Spawn + STR_Datakey + STR_Randomized),
                _spawn_datakey,
              ) as string
              let _item_id = g.dm_spawn.get(_dk3 + STR_Item + STR_ID) as string | undefined
              _item_id = val(g.dm_spawn.get(_spawn_datakey + STR_Item + STR_ID + STR_Randomized), _item_id) as
                | string
                | undefined
              if (
                _item_id !== undefined &&
                val(g.dm_spawn.get(_spawn_datakey + STR_Dungeon + STR_Num)) === _i
              ) {
                const _item_type = g.dm_spawn.get(_item_id + STR_Item + STR_Type) as string | undefined
                if (_item_type !== undefined) {
                  switch (_item_type) {
                    case STR_Kakusu:
                      _all_conditions_met = val(f.dm_kakusu.get(_spawn_datakey))
                      break
                    default:
                      _all_conditions_met = item_acquired(_item_id)
                      break
                  }
                }
              }
            }
          }
        }
      }
      if (gmBool(_all_conditions_met)) f.dm_quests.set(_datakey, 1)
    }
  }
}
