/** Fireball1/2 and Flame1/2 — the HostileFire family (init/update/usd + Fireball_udp). */
import { abs8b, byteNegate, gmBool } from '../../../../nes/math8'
import { g } from '../../../../runtime/world'
import { byte_dir } from '../../../math/index'
import { aud_play_combo1, aud_play_fire } from '../../../sound/play'
import type { GameObjectC } from '../../classes'
import { set_xy } from '../../go/movement'
import { GO_set_sprite, GO_sprite_init } from '../../go/sprite'
import { GG, pc } from '../../pending'
import { sign_ } from '../../util'
import { collisionProjCS, HostileFire_init_1, HostileFire_udp_1, Projectile_update_3a } from '../Projectile'
import type { Flame1, Flame2 } from './classes'
import { rand } from './rand'

// ---- Fireball1 / Fireball2 -------------------------------------------------------------------------
/** `init_Fireball1()` — Ache, Aneru, Aruroda, Bago */
export function init_Fireball1(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Fireball1')
  HostileFire_init_1(self, GG().PI_MOB_ORG)
}
export function init_Fireball2(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Fireball2')
  HostileFire_init_1(self, GG().PI_MOB_RED)
  switch (self.ver) {
    case 1: // Barba
      break
    case 2: // Thunderbird
      self.vspd_adj = 1 // gravity
      break
    case 3: // Gooma
      self.timer = 0xff // Life duration
      break
  }
}
/** `update_Fireball1()` — 9627 */
export function update_Fireball1(self: GameObjectC): void {
  // Only Acheman & Aruroda Fireball makes sound.
  if (self.ver === 2) aud_play_fire(true) // Sound._00ED |= $40;
  // pID 3: 9C3D, 9C48.  pID 4: 962F, 9634
  Projectile_update_3a(self, self.despawn_offscreen_hor) // vspd_adj == 0;
}
/** `update_Fireball2()` — AD94: JSR BEF6 */
export function update_Fireball2(self: GameObjectC): void {
  // ver 1 Barba fireball normal, ver 3 Barba fireball bounce off walls: only Barba fireball makes sound.
  if (self.ver === 1 || self.ver === 3) aud_play_fire(true)
  let _can_expl = false
  if (self.ver === 3) {
    if (gmBool(self.timer)) self.timer--
    _can_expl = !gmBool(self.timer)
    if (!_can_expl) {
      const _EXTRA = 2
      let _off = ((abs8b(self.hspd) >> 4) + _EXTRA) * byte_dir(self.hspd)
      if (collisionProjCS(self, _off, 0)) {
        self.hspd = byteNegate(self.hspd)
        self.hspd_dir = byte_dir(self.hspd)
      }
      _off = ((abs8b(self.vspd) >> 4) + _EXTRA) * byte_dir(self.vspd)
      if (collisionProjCS(self, 0, _off)) {
        self.vspd = byteNegate(self.vspd)
      }
    }
  } else {
    _can_expl = collisionProjCS(self, 0, 0)
  }
  // pID 4: AD97, pID 8: 9BC8
  if (_can_expl) {
    // if (ogY(id) >= $90 && collisionProjCS(8)) // OG
    self.disintegrate_counter = 0xf2 // Barba fireball
    switch (self.ver) {
      case 1:
        self.disintegrate_counter = 0xf2
        break // ADA4. Barba
      case 2:
        self.disintegrate_counter = 0xf4
        break // 9BCD. Thunderbird
      case 3:
        self.disintegrate_counter = 0xf2
        break
    }
    self.state = self.state_EXPLODE
  } else {
    // pID 4: ADBF,  pID 8: 9C45, 9C48
    Projectile_update_3a(self, self.despawn_offscreen_hor) // pID 1D: vspd_adj == 1;
  }
}
export function Fireball_udp(self: GameObjectC): void {
  self.can_draw_self = true
  self.xScale = self.facing_dir
  self.yScale = g.counter1 & 0x4 ? -1 : 1
}
export function usd_Fireball1(self: GameObjectC): void {
  Fireball_udp(self)
  HostileFire_udp_1(self)
}
/** `usd_Fireball2()` — pID 4: AE20, pID 8: 9D18 */
export function usd_Fireball2(self: GameObjectC): void {
  Fireball_udp(self) // Takes care of yscale
  if (self.ver === 2 && g.counter1 & 0x2)
    self.xScale = 1 // Thunderbird
  else self.xScale = -1
  HostileFire_udp_1(self)
}

// ---- Flame1 ------------------------------------------------------------------------------------------
/** `init_Flame1()` — Mago, FieryMoa, Wosu(maybe), Drop Spawner, Kakusu */
export function init_Flame1(self: Flame1): void {
  GO_sprite_init(self, 'spr_Flame1')
  HostileFire_init_1(self, GG().PI_MOB_ORG)
  self.DRAW_YOFF = 0
  self.vspd_adj = 1
  self.timer = 0xff
  self.FADE_CUE1 = 0x50
  self.FADE_CUE2 = 0x38
  self.FADE_CUE3 = 0x1c
  // float_tmr: For Carock's Flame1 atk. Suspends vertical movement.
  self.float_tmr = 0
}
/** `update_Flame1()` — Carock, Mago, FieryMoa, Wosu, Kakusu, DropSpawner.  98B9 */
export function update_Flame1(self: Flame1): void {
  if (self.timer >= self.FADE_CUE2) aud_play_fire(true) // mod. Reduce sound duration (OG: no condition)
  if (self.timer < self.FADE_CUE2) self.brightness = 0
  // 98BC
  if (gmBool(self.timer)) {
    // 98C9
    if (gmBool(self.hspd) && !(self.timer & 0x7)) {
      if (self.hspd < 0x80) self.hspd = (self.hspd - 1) & 0xff
      else self.hspd = (self.hspd + 1) & 0xff
    }
    // 98D9
    if (collisionProjCS(self, 0, self.hh_)) {
      set_xy(self, self.x, (self.y >> 3) << 3)
      self.vspd = -self.vspd_adj & 0xff // counteract the upcoming adj
    }
    if (gmBool(self.float_tmr)) {
      // float_tmr is for Carock2's high flame attack
      self.float_tmr--
      self.vspd = -self.vspd_adj & 0xff // counteract the upcoming adj
    }
    // 9940
    Projectile_update_3a(self, self.despawn_offscreen_hor) // Projectile_update_1a(!isVal(pID, 6, 8));
  } else {
    // 995A
    self.state = 0
  }
}
/** `usd_Flame1()` — 999F, 99BE */
export function usd_Flame1(self: Flame1): void {
  self.can_draw_self = true
  // 99A6: Blinking.  FADE_CUE1==$50, FADE_CUE2==$38, FADE_CUE3==$1C
  if (self.timer < self.FADE_CUE1) {
    let _val = 0x1 // ON 1 frames. OFF 1 frames
    if (self.timer < self.FADE_CUE2) _val = 0x2 // ON 2 frames. OFF 2 frames
    if (self.timer < self.FADE_CUE3) _val = 0x4 // ON 4 frames. OFF 4 frames
    self.can_draw_self = !(g.counter1 & _val)
  }
  self.xScale = g.counter1 & 0x4 ? -1 : 1
  HostileFire_udp_1(self)
}

// ---- Flame2 ------------------------------------------------------------------------------------------
/**
 * `init_Flame2()` — ver 1: Rebonack wall statue, Ganon2, Ganon3, Atta, Fokkeru, Kakusu005, Kakusu008;
 * ver 2: Barba's Attack3.
 */
export function init_Flame2(self: Flame2): void {
  self.SPR_BALL = 'spr_Fireball2'
  self.SPR_FLAM = 'spr_Flame1'
  GO_sprite_init(self, self.SPR_BALL)
  HostileFire_init_1(self, GG().PI_MOB_RED)
  self.despawn_offscreen_hor = false
  self.vspd_adj = 1
  self.has_landed = false // 045E[pIndex]
  self.VSPD_BOUNCE = 0xf0
  self.BOUNCE_REQ = 0x20 // min vspd required to bounce
  self.FADE_CUE = 0x20
  self.HSPD1 = (0x10 * self.facing_dir) & 0xff
  self.VSPD1 = 0xe0
  self.Launch_timer = 0
  switch (self.ver) {
    case 1:
      self.will_slide = false
      self.Launch_timer = 0
      break
    case 2:
      self.will_slide = !gmBool(rand.irandom(9))
      self.Launch_timer = 0x10
      self.HSPD1 = (0x0e * self.facing_dir) & 0xff
      self.VSPD1 = 0xd4
      self.hspd = 0
      self.vspd = 0
      self.vspd_adj = 0
      break
  }
}
/** `update_Flame2()` — Gooma, Atta, Fokkeru, Kakusu, Barba.Attack3 */
export function update_Flame2(self: Flame2): void {
  if (gmBool(self.Launch_timer)) {
    self.Launch_timer--
    self.hspd = 0
    self.vspd = 0
    aud_play_fire(true)
    if (!gmBool(self.Launch_timer)) {
      self.hspd = self.HSPD1
      self.vspd = self.VSPD1
      self.vspd_adj = 1
      aud_play_combo1(0x13) // Launch sound
    }
  }
  // 9BE1
  else if (collisionProjCS(self, 0, self.hh_)) {
    if (self.ver === 1 && self.counter >= self.FADE_CUE) aud_play_fire(true) // mod. Reduce sound duration
    const _Y = self.y
    set_xy(self, self.x, (self.y >> 3) << 3) // 11/08/23. This works like OG but only rounds to $08 instead of $10
    if (collisionProjCS(self, 0, self.hh_ - 1)) {
      // if a clip correction happened, or not landed yet
      if (_Y & 0x7 || !self.has_landed) set_xy(self, self.x, self.y - 8)
    }
    // MOD. Bounce anytime vspd great enough when landing.
    if (self.vspd < 0x80 && self.vspd >= self.BOUNCE_REQ) {
      // Bounce
      self.vspd = self.VSPD_BOUNCE // $F0
      // MOD. Guarantee bounce. Certain grav values(like $F0) will cancel bounce.
      self.vspd_sub = 0x10 // grav = $10;
    } else {
      self.vspd = -self.vspd_adj & 0xff // counteract the upcoming adj
    }
    // 9BF2
    if (!self.has_landed) {
      self.has_landed = true
      if (self.ver === 1) self.will_slide = !(rand.og(self) & 0x3)
      if (self.will_slide) self.facing_dir = sign_(self.xl < pc().xl - 8)
      if (self.will_slide) self.hspd = (0x10 * self.facing_dir) & 0xff
      else self.hspd = 0
      self.counter = self.will_slide ? 0xff : 0x30
    } else {
      // 9C23
      if (gmBool(self.counter)) {
        if (!(self.counter & 0x7) && gmBool(self.hspd)) {
          if (self.hspd < 0x80) self.hspd = (self.hspd - 1) & 0xff
          else self.hspd = (self.hspd + 1) & 0xff
        }
        self.counter--
        // 9C3D
      } else {
        // 9C5B
        self.state = 0
      }
    }
  }
  // 9C45
  if (gmBool(self.state)) {
    Projectile_update_3a(self, self.despawn_offscreen_hor) // Projectile_update_1a(pID != 7);
  }
}
/** `usd_Flame2()` — 9CCE */
export function usd_Flame2(self: Flame2): void {
  self.can_draw_self = true
  self.xScale = 1
  self.yScale = 1
  self.draw_yoff = 0
  if (gmBool(self.Launch_timer) || self.has_landed) {
    GO_set_sprite(self, self.SPR_FLAM)
    const _TIMING = 0x2
    // 9CD6
    if (self.counter < self.FADE_CUE && g.counter1 & _TIMING) {
      // Fade effect.  9CE3
      self.can_draw_self = false
    } else {
      // 9CEB.  MOD. Issue fix: during fade, sprite shows same xscale bc it doesnt draw during the opposite xscale.
      if (self.counter < self.FADE_CUE) self.xScale = sign_(g.counter1 & (_TIMING << 1))
      else self.xScale = sign_(g.counter1 & _TIMING)
    }
    self.draw_yoff = -self.DRAW_YOFF
    if (self.ver === 2 && gmBool(self.Launch_timer)) {
      // Draw a little above the lava
      self.draw_yoff = -6
    }
  } else {
    GO_set_sprite(self, self.SPR_BALL)
    // 9D18
    self.xScale = g.counter1 & 0x2 ? 1 : -1
    self.yScale = g.counter1 & 0x4 ? -1 : 1
  }
  HostileFire_udp_1(self)
}
