import type { DsGrid } from '../../runtime/ds'
import { GameObject } from '../game_object/classes'

/**
 * NIAO: Non-Interactive Animated Object. In ZALiA these are plain `GameObject` instances
 * (`instance_create(0,0, GameObject)` in `NIAO_create.gml`) whose behaviour is chosen by the
 * `*_init` script stored in scene data (`<rm>_NIAO<n>_init`). One class covers every kind; the
 * per-kind fields below are set by the init scripts exactly as in the GML.
 */
export class NiaoObject extends GameObject {
  readonly objectName = 'GameObject' as const
  /** `NIAO_init`: default GameObject draw YOff */
  // Cloud_1
  DIST1 = 0
  DIST2 = 0
  DIST3 = 0
  can_move = false
  COPY_COUNT = 0
  SPR_1A = ''
  SPR_2A = ''
  CLOUD_COUNT = 0
  dg_cloud: DsGrid<number | string> | undefined = undefined
  CloudArea_W = 0
  CloudArea_H = 0
  CloudArea_XL = 0
  CloudArea_XR = 0
  CloudArea_YT = 0
  CloudArea_YB = 0
  // CloudCover1
  CloudSpr1 = ''
  CloudSpr1_W = 0
  CloudSpr1_W_ = 0
  CloudSpr1_CLMS = 0
  CloudSpr1_H = 0
  CloudSpr1_H_ = 0
  CloudSpr1_ROWS = 0
  CloudSpr1_COUNT_X = 0
  Clouds_DIR = -1
  dg_CloudLayers: DsGrid<number> | undefined = undefined
  CloudLayers_COUNT = 0
  // Fire1 / Fountain_1
  ANIM_SPEED = 0
  Water_SPR1 = ''
  Water_SPR2 = ''
  PALIDX = 0
  // Moon1 / StarSky_1
  CAM_LOCKED: boolean | number = false
  X_OFF = 0
  Y_OFF = 0
  ADJUST_DIST = 0
  X1 = 0
  Y1 = 0
  SPR_W = 0
  SPR_H = 0
  SPR_XOFF = 0
  SPR_YOFF = 0
  CLMS = 0
  ROWS = 0
  // AdditionalBGGraphics
  dg_xy: DsGrid<number> | undefined = undefined
  Sprite_COUNT = 0
  palidx_LIT = 0
  palidx_DARK = 0
}
