/**
 * Helpers shared by the enemy ports in this folder group (hosted here because `iron_knuckle/` also carries
 * the shared sword/shield AI): the per-slot OG random byte, `goDist1`, GML `point_direction`, the
 * `Input.dHeld`/`hHeld` aliases, and `Enemy_update_1` (shared by Moblin/Goriya/Daira in ZALiA).
 */
import { CS_LFT, CS_RGT } from '@z2/data'
import { byte, gmBool, isVal } from '../../../../../../nes/math8'
import { input, world } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { ocsH1 } from '../../../../../collision/ocs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { byte_dir, sign_ } from '../../../../../math/index'
import type { GameObject } from '../../../../classes'
import { dir_to_pc, dir_to_pc_ } from '../../../../go/misc'
import { updateX, updateY } from '../../../../go/movement'
import { solid_clip_correction } from '../../../../goa/movement'
import { gp, pc } from '../../../../pending'
import { GOB_update_1 } from '../../../GameObjectB'
import { rand } from '../../shared'

/**
 * `rand()` — this object's byte of the OG random register.
 * FIXED: this copy read `world.ogRandom`, a parallel register that nothing in the game advances
 * (`OgRandom.update()` has no production caller). The live one is `g.dl_RandomOG`, stepped every frame by
 * `update_og_rand`. Reading the dead one returned 0 forever: Iron Knuckle could never draw low and
 * attacked twice as often, Geru never raised its shield, Moblin/Goriya always picked the same behaviour,
 * and Moa never took the downward branch. Delegates to the folder's correct implementation.
 */
export { rand } from '../../shared'

/** `goDist1()` — DC91/DCA1: `pc.xl - xl` as the NES computes it into $000F (with the low-page carry quirk). */
export function goDist1(self: GameObject): number {
  const P = pc()
  let r = P.xl & 0xff
  r += byte(~(self.xl & 0xff))
  r += P.xl >= 0 && P.xl <= 7 ? 1 : 0 // carry
  return r & 0xff
}

/** GM `point_direction`: degrees counter-clockwise, 0 = right, y axis down. */
export function point_direction(x1: number, y1: number, x2: number, y2: number): number {
  let d = (Math.atan2(-(y2 - y1), x2 - x1) * 180) / Math.PI
  if (d < 0) d += 360
  return d
}

/** `Input.dHeld` — 1 if down is held, 0 if not. */
export const dHeld = (): number => (input.Down_held ? 1 : 0)
/** `Input.hHeld` — non-zero if right or left is held (the `heldH` mask). */
export const hHeld = (): number => input.heldH

/**
 * `Enemy_update_1()` — 9A2C. Shared by Moblin v1-3, Goriya v1-3 and Daira v1-2: gravity + walking with
 * pushback, then the attack-timing / aggro logic keyed on which enemy this is.
 */
/** Enemies using `Enemy_update_1` carry an `attack_dist` (Moblin/Goriya/Daira). */
export interface AttackDistGO extends GameObject {
  attack_dist: number
}

export function Enemy_update_1(self: AttackDistGO): void {
  const g = gp()
  const P = pc()
  // 9A2C
  if (self.cs & 0x10) enemy_collide_pc_body(self) // CS_BD1
  updateY(self)
  if (self.cs & 0x4) {
    solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
    self.vspd = 0
  }
  // 9A3B
  const _hspdPB_COPY = self.hspd_pushback
  GOB_update_1(self, true) // update hspd_pushback
  GO_update_cs(self)
  if (!(self.cs & 0x3)) updateX(self)
  if (gmBool(_hspdPB_COPY)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // 9A3E
  self.facing_dir = dir_to_pc(self)
  // ------------------------------------------------------------------------------------
  let _D1 = false // Daira  v1(orange)
  let _D2 = false // Daira  v2(red)
  let _G1 = false // Goriya v1(orange)
  let _G2 = false // Goriya v2(red)
  let _G3 = false // Goriya v3(blue)
  let _M1 = false // Moblin v1(orange)
  let _M2 = false // Moblin v2(red)
  let _M3 = false // Moblin v3(blue)
  switch (self.objectName) {
    case 'DairA':
      _D1 = self.ver === 1
      _D2 = self.ver === 2
      break
    case 'GoriA':
      _G1 = self.ver === 1
      _G2 = self.ver === 2
      _G3 = self.ver === 3
      break
    case 'MoblA':
      _M1 = self.ver === 1
      _M2 = self.ver === 2
      _M3 = self.ver === 3
      break
    default:
      break
  }
  const attack_dist = self.attack_dist
  const _InAttackDist_ORIG = ((goDist1(self) + attack_dist) & 0xff) < ((attack_dist << 1) & 0xff)
  const _InAttackDist_WIDE = Math.abs(self.x - P.x) < attack_dist
  const _InAggroDist_WIDE = ocsH1(self)
  const _CAN_AGGRO = (_D1 || _M1 || _M2 || _M3) && _InAggroDist_WIDE && !gmBool(self.behavior)
  const _RAND = rand(self)
  let _val = 0x1
  if (_InAttackDist_ORIG) {
    // 9A6B
    self.counter = (self.counter + 1) & 0xff
    // $1F: every 32 frames = 0.533s, $3F: every 64 = 1.067s, $7F: every 128 = 2.133s
    _val = 0x3f // m1,m2, g2,g3, d1,d2
    if (_M3) _val = 0x1f // m3
    if (_G1) _val = 0x7f // g1
    _val &= self.counter
    if (!_val) {
      // A chance to time the next atk with the shortest duration (32 frames) instead of 64/128.
      let _num = 0x1 // m2, m3        50%
      if (_M1 || _G3 || _D1) _num = 0x3 // g3, d1, m1    25%
      if (_G2 || _D2) _num = 0x7 // g2, d2        12.5%
      if (_G1) _num = 0xf // g1            6.25%
      if (!(_RAND & _num)) self.counter = 0xe0 // Next atk in 32 frames (about .5 seconds)
    }
  }
  if (_InAttackDist_ORIG || _CAN_AGGRO) {
    if (!_val || _CAN_AGGRO) {
      // 9982 -------------- START ATTACK --------------------------
      if (_D1 || _D2) {
        self.behavior = 1 // 1. atk high for Daira
      } else if (_M1) {
        // 9AA2
        self.behavior = 3 // 3. atk high
      } else {
        // m2,m3, g1,g2,g3. If PC crouching, high has a better chance; standing, low has a better chance.
        if (dHeld()) {
          if (isVal(_RAND & 0x7, 0, 2))
            self.behavior = 1 // 25%. 1: atk low
          else self.behavior = 3 // 75%. 3: atk high
        } else {
          if (isVal(_RAND & 0x7, 4, 6))
            self.behavior = 3 // 25%. 3: atk high
          else self.behavior = 1 // 75%. 1: atk low
        }
      }
      // 9AA6
      self.timer = 0x18 // $18: 0.400s.  Attack delay
    }
  }
  const _HSPD1 = (0x04 * sign_(g.counter1 & 0x40)) & 0xff // Attack mode pacing
  if (!_InAggroDist_WIDE) {
    self.hspd = _HSPD1
    self.facing_dir = byte_dir(self.hspd)
  } else {
    if (_InAttackDist_WIDE) {
      // 9AAB. ------------------- SET hspd ---------------------------------
      if (P.cs & (CS_RGT | CS_LFT)) self.hspd = 0
      else if (hHeld() && gmBool(P.hspd)) self.hspd = P.hspd
      else self.hspd = _HSPD1
      self.hspd = (self.hspd >> 1) | (self.hspd & 0x80)
    } else {
      self.facing_dir = dir_to_pc_(self)
      self.hspd = (0x10 * self.facing_dir) & 0xff
    }
  }
}
