/**
 * Palette swap — CPU implementation (primary).
 *
 * Contract with the core (mirrors ZALiA's `global.palette_image`, `palSpr_changeColors.gml`):
 *   `palettes: number[][]` — palette k is 8 colours in ZALiA's base-colour order `"WRBGYMKC"`, each a
 *   24-bit RGB number. Palette 0 is the *source* palette: the colours the sprite PNGs are drawn in. Palette k
 *   is what `pal_swap_set(k)` maps them to. `version` increments whenever the array changes so the adapter
 *   can drop derived textures.
 *   The special colour `ALPHA0_COLOR = 0x7F7F7F` becomes fully transparent (ZALiA `global.C_ALPHA0`).
 *
 * ZALiA did this with a GLSL shader (`shd_pal_swapper.shader`) that ZALiA's CONTRIBUTING.md says misbehaves
 * on some GPUs. Since NES sprites are tiny and palettes are only 8 colours, we remap pixels on the CPU once
 * per (sprite frame, palette) pair and cache the result as a canvas texture — batched, GPU-independent, and
 * unit-testable. `paletteSwapFilter.ts` keeps a GPU port for whole-layer use.
 */
import type Phaser from 'phaser'

export const ALPHA0_COLOR = 0x7f7f7f
export const PALETTE_SIZE = 8

export type Palettes = readonly (readonly number[])[]

/** Remap RGBA8 pixels in place: colours equal to `from[i]` become `to[i]`; `ALPHA0_COLOR` becomes alpha 0. */
export function remapRgba(
  px: Uint8ClampedArray,
  from: readonly number[],
  to: readonly number[],
): Uint8ClampedArray {
  const table = new Map<number, number>()
  for (let i = 0; i < from.length && i < to.length; i++) table.set(from[i] as number, to[i] as number)
  for (let o = 0; o < px.length; o += 4) {
    if (px[o + 3] === 0) continue
    const rgb = ((px[o] as number) << 16) | ((px[o + 1] as number) << 8) | (px[o + 2] as number)
    if (rgb === ALPHA0_COLOR) {
      px[o + 3] = 0
      continue
    }
    const t = table.get(rgb)
    if (t !== undefined) {
      px[o] = (t >> 16) & 0xff
      px[o + 1] = (t >> 8) & 0xff
      px[o + 2] = t & 0xff
    }
  }
  return px
}

/** Palette texture bytes for the GPU path: width = palettes.length, height = 8, one RGBA pixel per colour. */
export function paletteTextureBytes(palettes: Palettes): { data: Uint8Array; width: number; height: number } {
  const width = palettes.length
  const height = PALETTE_SIZE
  const data = new Uint8Array(width * height * 4)
  for (let x = 0; x < width; x++) {
    for (let y = 0; y < height; y++) {
      const c = palettes[x]?.[y] ?? 0
      const o = (y * width + x) * 4
      data[o] = (c >> 16) & 0xff
      data[o + 1] = (c >> 8) & 0xff
      data[o + 2] = c & 0xff
      data[o + 3] = 0xff
    }
  }
  return { data, width, height }
}

export const PALETTE_TEXTURE_KEY = 'palette_image'

/** (Re)build the GPU palette texture from the core's palette array (used by the filter path). */
export function uploadPalette(scene: Phaser.Scene, palettes: Palettes): void {
  const { data, width, height } = paletteTextureBytes(palettes)
  if (scene.textures.exists(PALETTE_TEXTURE_KEY)) scene.textures.remove(PALETTE_TEXTURE_KEY)
  scene.textures.addUint8Array(PALETTE_TEXTURE_KEY, data, width, height)
}

/** Cache key for a swapped frame texture. */
export function swappedKey(atlasKey: string, frame: string, palIdx: number, version: number): string {
  return `pal:${version}:${palIdx}:${atlasKey}:${frame}`
}

/**
 * Builds and caches palette-swapped copies of atlas frames as canvas textures.
 * Texture keys embed the palette version, so a palette change naturally misses the cache; stale
 * entries are purged when `setPalettes` is called with a new version.
 */
export class PaletteSwapCache {
  private palettes: Palettes = []
  private version = -1
  private keys = new Set<string>()

  constructor(private readonly scene: Phaser.Scene) {}

  setPalettes(palettes: Palettes, version: number): void {
    if (version === this.version) return
    for (const k of this.keys) this.scene.textures.remove(k)
    this.keys.clear()
    this.palettes = palettes
    this.version = version
  }

  /** Returns a texture key whose frame `__BASE` is `frame` of `atlasKey` recoloured to palette `palIdx`. */
  get(atlasKey: string, frame: string, palIdx: number): string {
    const key = swappedKey(atlasKey, frame, palIdx, this.version)
    if (this.keys.has(key)) return key
    const src = this.scene.textures.getFrame(atlasKey, frame)
    const canvas = document.createElement('canvas')
    canvas.width = src.width
    canvas.height = src.height
    const ctx = canvas.getContext('2d') as CanvasRenderingContext2D
    ctx.drawImage(
      src.source.image as CanvasImageSource,
      src.cutX,
      src.cutY,
      src.width,
      src.height,
      0,
      0,
      src.width,
      src.height,
    )
    const img = ctx.getImageData(0, 0, src.width, src.height)
    remapRgba(img.data, this.palettes[0] ?? [], this.palettes[palIdx] ?? [])
    ctx.putImageData(img, 0, 0)
    this.scene.textures.addCanvas(key, canvas)
    this.keys.add(key)
    return key
  }
}
