  g.dg_CS_OFF.set(0x1f, 0x04, g.dg_CS_OFF.get(0x1f, 0x00)) // CS_BTM Left   x
  g.dg_CS_OFF.set(0x1f, 0x05, _h) // CS_BTM Left   y
  g.dg_CS_OFF.set(0x1f, 0x06, g.dg_CS_OFF.get(0x1f, 0x02)) // CS_BTM Right  x
  g.dg_CS_OFF.set(0x1f, 0x07, g.dg_CS_OFF.get(0x1f, 0x05)) // CS_BTM Right  y
  // CS_RGT                                   //
  g.dg_CS_OFF.set(0x1f, 0x08, _w) // CS_RGT Top    x
  g.dg_CS_OFF.set(0x1f, 0x09, 7) // CS_RGT Top    y
  g.dg_CS_OFF.set(0x1f, 0x0a, g.dg_CS_OFF.get(0x1f, 0x08)) // CS_RGT Bottom x
  g.dg_CS_OFF.set(0x1f, 0x0b, _h - (g.dg_CS_OFF.get(0x1f, 0x09) + 1)) // CS_RGT Bottom y
  // CS_LFT                                   //
  g.dg_CS_OFF.set(0x1f, 0x0c, -1) // CS_LFT Top    x
  g.dg_CS_OFF.set(0x1f, 0x0d, g.dg_CS_OFF.get(0x1f, 0x09)) // CS_LFT Top    y
  g.dg_CS_OFF.set(0x1f, 0x0e, g.dg_CS_OFF.get(0x1f, 0x0c)) // CS_LFT Bottom x
  g.dg_CS_OFF.set(0x1f, 0x0f, g.dg_CS_OFF.get(0x1f, 0x0b)) // CS_LFT Bottom y
