/** `crystal_is_placed(dungeon num)` */
export function crystal_is_placed(dungeonNum: number): number {
  if (dungeonNum) return f.crystals & (0x1 << (dungeonNum - 1))
  return 0
}

/** `CrystalHolder_init2()` — eID = $14, $15 */
export function CrystalHolder_init2(self: CrHoA): void {
  GO_depth_init(self, DEPTH_ITEM)
  GO_init_palidx(self, G.PI_MOB_ORG) // This is the CRYSTAL's palidx
  // If the boss is rando'd, this should refer to the actual dungeon num the player is in, not the dungeon num the boss is from
  self.DUNGEON_NUM = val(f.dm_rando.get(g.rm_name + STR_Dungeon + STR_Num), g.dungeon_num) as number
  self.facing_dir = 1
  self.can_draw_self = false
  self.canDrawCrystal = 0 // 0081[eIndex]
  self.Flash_DUR = 0x62
  self.Flash_timer = 0 // 0767
  self.dl_COLOR_ID = new DsList<string>()
  self.dl_COLOR_ID.add(color_str(p.C_VLT3)) // 0: blue
  self.dl_COLOR_ID.add(color_str(p.C_WHT1)) // 1: white
  self.dl_COLOR_ID.add(color_str(p.C_GRN2)) // 2: green
  self.dl_COLOR_ID.add(color_str(p.C_RED3)) // 3: red
  // THIS ALGORITHM IS CORRECT, BUT YOU NEED TO KNOW THE CORRECT DEPTH FOR THE CRYSTAL HOLDER.
  self.midtone_PALDATA_POS =
    p.PAL_POS_BGR2 + p.PAL_CHAR_PER_COLOR * (p.PAL_BASE_COLOR_ORDER.indexOf('R') + 1 - 1)
  self.midtone_colorID_DEF = (p.pal_rm_def ?? '').substr(self.midtone_PALDATA_POS - 1, p.PAL_CHAR_PER_COLOR)
  self.midtone_colorID_cur = self.midtone_colorID_DEF
  self.GROUND_Y = (((self.spawn_yt >> 8) + 1) << 8) - (0x3 << 3)
  self.GROUND_Y = get_ground_y(self.x, self.GROUND_Y, -1, self.GROUND_Y)
  self.spawn_yt = self.GROUND_Y - (0x48 + 0x6)
  set_xlyt(self, self.spawn_xl, self.spawn_yt)
  if (crystal_is_placed(self.DUNGEON_NUM))
    self.counter = 0 // Only udp will update
  else self.counter = 1
  self.Fanfare_THEME = dk_PlaceCrystal
  self.Fanfare_MUSIC = get_audio_theme_track(self.Fanfare_THEME)
  self.fanfare_failsafe_timer = round(audio_sound_length(self.Fanfare_MUSIC) * ROOM_SPEED_BASE)
  self.fanfare_failsafe_timer += 8
  self.scr_inst_end = CrystalHolder_end as (s: unknown) => void
}

/**
 * FIXED (no counterpart in ZALiA): `CrystalHolder_update` takes `g.pc_lock = PC_LOCK_ALL` at `counter` 1
 * and gives it back at `counter` 4, once the hp/mp restore that follows the fanfare has drained — several
 * seconds later. Nothing in the shipped game destroys a crystal holder in that window (it does not run
 * `GOB_update_2`, so neither the out-of-bounds despawn nor the sword can reach it, and it never sets
 * `state = 0`), but the failure mode if anything ever does is the restore fairy's: `PC_LOCK_ALL` with no
 * one left to clear it, which is a total freeze with no recovery — `PC_Room_Start` clears the lock on a
 * room start and a locked player cannot walk to an exit. The lock is this instance's to hold, so it is
 * handed back when the instance ends. See `pcLock.test.ts` for the whole family.
 */
export function CrystalHolder_end(self: CrHoA): void {
  if (self.counter >= 2) g.pc_lock = 0
}

/** `CrystalHolder_update()` */
export function CrystalHolder_update(self: CrHoA): void {
  const P = pc()
  if (!self.counter) {
    CrystalHolder_udp(self)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // 9AD4: JSR 9B95
  if (self.Flash_timer) {
    // Flash the midtone color of the crystal holder graphic. 0: blue, 1: white, 2: green, 3: red
    self.Flash_timer--
    if (self.Flash_timer) self.midtone_colorID_cur = self.dl_COLOR_ID?.get(self.Flash_timer & 0x3) as string
    else self.midtone_colorID_cur = self.midtone_colorID_DEF
    change_pal(
      strReplaceAt(p.pal_rm_new, self.midtone_PALDATA_POS, p.PAL_CHAR_PER_COLOR, self.midtone_colorID_cur),
    )
  }
  CrystalHolder_udp(self)
  // 9ADE
  switch (self.counter) {
    // 00AF[eIndex]
    case 1: {
      // 9AEB
      if (self.ocs) break // ####################
      // 9AF4: JSR E4D9
      GOB_body_collide_pc_body_1a(self)
      if (self.cs & CS_BD1 && !P.ogr) {
        // colliding w/ PC body, PC confirmed to be on ground. 9B03
        g.pc_lock = PC_LOCK_ALL // Lock all
        PC_set_behavior(P.behavior_IDLE)
        set_xlyt(self, self.xl, P.yt)
        f.crystals |= 0x1 << (self.DUNGEON_NUM - 1)
        aud_play_sound(get_audio_theme_track(STR_Sword + STR_Beam))
        audio_group_stop_all('audiogroup_mus') // stop music?
        // stop mus_rm_body from playing until hp/mp restore is done
        Audio.can_play_mus_rm_body = false
        Audio.can_play_boss_music = false
        self.counter++
      }
      break
    }
    case 2: {
      // 9B2B
      set_xy(self, self.x, self.y - 1)
      if (self.yt <= self.spawn_yt) {
        set_xlyt(self, self.xl, self.spawn_yt) // just in case
        self.Flash_timer = self.Flash_DUR // $62
        P.hspd = 0
        aud_play_sound(get_audio_theme_track(dk_StrikeSolid))
        aud_play_sound(self.Fanfare_MUSIC as never, -1, false, -1, self.Fanfare_THEME)
        self.counter++
      }
      self.canDrawCrystal = self.yt
      break
    }
    case 3: {
      // 9B47
      if (self.fanfare_failsafe_timer) self.fanfare_failsafe_timer--
      if (!self.fanfare_failsafe_timer || !audio_is_playing(self.Fanfare_MUSIC)) {
        g.StatRestore_timer_mp = get_stat_max(STR_Magic)
        g.StatRestore_timer_hp = get_stat_max(STR_Heart)
        self.counter++
      }
      break
    }
    case 4: {
      // 9B56
      if (!g.StatRestore_timer_mp && !g.StatRestore_timer_hp) {
        g.pc_lock = 0
        f.xpPending = f.xpNext - f.xp
        // allow mus_rm_body to play again
        Audio.can_play_mus_rm_body = true
        self.counter = 0 // Indicates crystal has been placed
      }
      break
    }
  }
}

/** `CrystalHolder_udp()` — 9AD7 */
export function CrystalHolder_udp(self: CrHoA): void {
  if (!self.canDrawCrystal && self.counter) return // stat restoration NOT finished !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  // 9ADB: JSR 9A8B
  self.can_draw_self = true
  update_draw_xy(self)
  self.palidx = GO_update_pal_flash(g.counter1, 1)
}
