/**
 * User player-character skins in the browser.
 *
 * ZALiA scanned `%localappdata%\ZALiA\custom_playercharacter_graphics` for `<Name>_<Creator>.png` at boot
 * and registered up to four of them (`PC_init.gml:177-213`). Here the player picks the PNGs with a file
 * dialog (`openSkinPicker()`, or the always-available **Ctrl+Shift+S** shortcut), they are stored in
 * IndexedDB (`zalia/skins`) and re-registered as Phaser textures on every load, and the core reads them
 * through `setCustomSkinProvider`. The four-sheet cap is dropped — it was a GameMaker texture-page limit.
 *
 * A sheet is one 16-column × 6-row grid of 64 px cells (`PC_init.gml:91-114`, `Lonk.Spritesheet_W/H`),
 * i.e. 1024 × 384 px: columns are behaviours, rows are Shield01/02, Body01/02, Sword01/02. `PC_draw`
 * emits `{ kind: 'sheet' }` draw commands for them and `render/drawList.ts` resolves the texture as
 * `sheet:<key>`, so that is the key each sheet is registered under.
 */
import { applySkinPreference, hexStr, type Lonk, pc, setCustomSkinProvider } from '@z2/core'
import {
  STR_Count,
  STR_Creator,
  STR_Current,
  STR_Datakey,
  STR_Idx,
  STR_Name,
  STR_Set,
  STR_Sprite,
} from '@z2/data'
import type Phaser from 'phaser'
import { type IdbFactoryLike, openSkinDb, type SkinDb, type SkinRecord } from './db'
import { isSkinImageFile, parseSkinFileName, userSkinKey } from './parse'

/**
 * `CustomSkin` from `core/game/game_object/goa/skins.ts` — the shape `setCustomSkinProvider` returns.
 * Declared here because core's public index does not re-export the type yet.
 */
export interface CustomSkin {
  /** `<Name>` from `<Name>_<Creator>.png` */
  name: string
  creator: string
  /** Sprite key the sheet is registered under (`userSkinKey`). */
  key: string
}

/** `Lonk.Spritesheet_W/H` and the sheet layout `draw_pc_skin` expects. */
export const SKIN_CELL = 0x40
export const SKIN_COLS = 0x10
export const SKIN_ROWS = 6
export const SKIN_SHEET_W = SKIN_CELL * SKIN_COLS // 1024
export const SKIN_SHEET_H = SKIN_CELL * SKIN_ROWS // 384

/** The Phaser texture key for a skin sprite key — `render/drawList.ts` looks the sheet up under this. */
export const skinTextureKey = (key: string): string => `sheet:${key}`

let db: SkinDb | undefined
let scene: Phaser.Scene | undefined
let skins: CustomSkin[] = []
let shortcutInstalled = false

/** Everything currently registered, in the order `PC_init` adds them after the 44 built-ins. */
export function userSkins(): readonly CustomSkin[] {
  return skins
}

/** `{ id, name, creator }` for a stored sheet, for an Options-menu list. */
export async function listUserSkins(): Promise<SkinRecord[]> {
  return db ? await safely(() => db?.all(), []) : []
}

/** Forget one stored sheet (its texture stays until the next reload). */
export async function removeUserSkin(id: string): Promise<void> {
  await safely(() => db?.remove(id), undefined)
  skins = skins.filter((s) => s.key !== id)
}

/**
 * Load the stored sheets and register them, then hand them to the core. **Must resolve before
 * `bootWorld()`**: `PC_init` calls `customSkinProvider()` once while building `dm_skins`.
 * Never rejects — a private window or blocked storage just means "no user skins".
 */
export async function installUserSkins(
  s: Phaser.Scene,
  factory: IdbFactoryLike | undefined = globalThis.indexedDB,
): Promise<void> {
  scene = s
  db = openSkinDb(factory)
  setCustomSkinProvider(() => skins)
  installSkinShortcut()
  const records = await safely(() => db?.all(), [] as SkinRecord[])
  skins = []
  for (const rec of records ?? []) {
    if (await registerSkinTexture(rec)) skins.push({ name: rec.name, creator: rec.creator, key: rec.id })
  }
}

/**
 * `_PC_Sprite_Set` from `UserPreferences.txt`. `load_game_pref` restores the *index* into `dm_skins`
 * during `obj_start_Create`; ZALiA re-read the file inside `PC_init` to also swap `Skin_image`. Call this
 * right after `bootWorld()` to finish that: it is the one place the preference is applied.
 */
export function applySavedSkinPreference(): void {
  const self = pc()
  const idx = Number(self.dm_skins.get(STR_Current + STR_Idx) ?? 0)
  applySkinPreference(self, idx)
}

/**
 * Open the OS file dialog and add every picked image as a skin. Wired to the Options → skin menu and to
 * Ctrl+Shift+S. Resolves with the number of sheets added.
 */
export function openSkinPicker(): Promise<number> {
  if (typeof document === 'undefined') return Promise.resolve(0)
  return new Promise<number>((resolve) => {
    const el = document.createElement('input')
    el.type = 'file'
    el.multiple = true
    el.accept = 'image/*'
    el.style.display = 'none'
    el.addEventListener('change', () => {
      const files: File[] = el.files ? Array.from(el.files) : []
      el.remove()
      void addSkinFiles(files).then(resolve)
    })
    el.addEventListener('cancel', () => {
      el.remove()
      resolve(0)
    })
    document.body.appendChild(el)
    el.click()
  })
}

/** Store, register and expose the picked files. Files with an unusable name/extension are skipped. */
export async function addSkinFiles(files: readonly File[]): Promise<number> {
  let added = 0
  for (const file of files) {
    const rec = await recordFromFile(file)
    if (!rec) continue
    await safely(() => db?.put(rec), undefined)
    if (!(await registerSkinTexture(rec))) continue
    skins = skins.filter((s) => s.key !== rec.id)
    skins.push({ name: rec.name, creator: rec.creator, key: rec.id })
    addSkinToLivePc(rec)
    added++
  }
  return added
}

/** A picked file → a `SkinRecord`, or `undefined` when the name/extension is not a skin sheet. */
export async function recordFromFile(file: {
  name: string
  type: string
  arrayBuffer(): Promise<ArrayBuffer>
}): Promise<SkinRecord | undefined> {
  if (!isSkinImageFile(file.name)) return undefined
  const parsed = parseSkinFileName(file.name)
  if (!parsed?.name) return undefined
  return {
    id: userSkinKey(parsed.name, parsed.creator),
    name: parsed.name,
    creator: parsed.creator,
    fileName: file.name,
    data: await file.arrayBuffer(),
    type: file.type || 'image/png',
    addedAt: Date.now(),
  }
}

/** Decode the stored bytes into a Phaser texture named `sheet:<id>`. */
async function registerSkinTexture(rec: SkinRecord): Promise<boolean> {
  if (!scene || typeof document === 'undefined' || typeof URL === 'undefined') return false
  const key = skinTextureKey(rec.id)
  if (scene.textures.exists(key)) return true
  const url = URL.createObjectURL(new Blob([rec.data], { type: rec.type }))
  try {
    const img = await loadImage(url)
    if (img.width !== SKIN_SHEET_W || img.height !== SKIN_SHEET_H) {
      console.warn(
        `[skins] ${rec.fileName} is ${img.width}×${img.height}; a PC skin sheet is ` +
          `${SKIN_SHEET_W}×${SKIN_SHEET_H} (${SKIN_COLS}×${SKIN_ROWS} cells of ${SKIN_CELL}px). Cells will be misaligned.`,
      )
    }
    scene.textures.addImage(key, img)
    return true
  } catch {
    console.warn(`[skins] could not decode ${rec.fileName}`)
    return false
  } finally {
    URL.revokeObjectURL(url)
  }
}

function loadImage(url: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image()
    img.onload = () => resolve(img)
    img.onerror = () => reject(new Error('image decode failed'))
    img.src = url
  })
}

/**
 * Add a sheet to the *running* player. `PC_init` already ran, so a skin picked mid-session has to be
 * appended to `dm_skins` by hand — this mirrors `PC_init_add_spritesheet(sprite, name, creator, -1, true)`
 * exactly. It should become `import { PC_init_add_spritesheet } from '@z2/core'` once core exports it.
 */
function addSkinToLivePc(rec: SkinRecord): void {
  let self: Lonk
  try {
    self = pc()
  } catch {
    return // the world has not booted yet; `installUserSkins` covers that path
  }
  const dm = self.dm_skins
  const _IDX = Number(dm.get(STR_Set + STR_Count) ?? 0)
  dm.set(STR_Set + STR_Count, _IDX + 1)
  let _DATAKEY = `${rec.name}-${rec.creator}`
  if ((dm.get(_DATAKEY + STR_Sprite) ?? 0) !== 0) _DATAKEY += '01'
  dm.set(hexStr(_IDX) + STR_Name, rec.name)
  dm.set(hexStr(_IDX) + STR_Creator, rec.creator)
  dm.set(hexStr(_IDX) + STR_Datakey, _DATAKEY)
  dm.set(_DATAKEY + STR_Idx, _IDX)
  dm.set(_DATAKEY + STR_Sprite, rec.id)
  dm.set(`${hexStr(_IDX)}_source_is_file`, 1)
}

/** Ctrl+Shift+S opens the picker anywhere in the game (documented in README.md). */
export function installSkinShortcut(): void {
  if (shortcutInstalled || typeof window === 'undefined') return
  shortcutInstalled = true
  window.addEventListener('keydown', (e) => {
    if (e.ctrlKey && e.shiftKey && !e.altKey && (e.key === 'S' || e.key === 's')) {
      e.preventDefault()
      void openSkinPicker()
    }
  })
}

/** Run `fn`, swallowing any storage failure (the game must boot without user skins). */
async function safely<T>(fn: () => Promise<T> | undefined, fallback: T): Promise<T> {
  try {
    return (await fn()) ?? fallback
  } catch {
    return fallback
  }
}

export * from './db'
export * from './parse'
