/**
 * Bubble / GiantBubble / dormant & wall-clinging Bubbles (ZALiA object `BubbA`, parent `Enemy`). `ver` is a
 * bitfield: $02 FAST, $04 STAB (changes dir on stab), $08 GIANT, $10 DORMANT, $20 CLING.
 * `Bubble_init2/update/udp/draw/end.gml` + `Bubble_cling_init/update_1a..4a.gml`.
 */
import {
  Area_PalcG,
  CS_BD1,
  CS_PR1,
  CS_SW1,
  STR_Data,
  STR_Direction,
  STR_pal_idx,
  TID_SOLID1,
} from '@z2/data'
import { abs8b, bit1st, byte, byteNegate, gmBool, isVal } from '../../../../../../nes/math8'
import { DsGrid } from '../../../../../../runtime/ds'
import { G, g, world } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { cam_x_range, cam_xl_min } from '../../../../../collision/env'
import { pointInRect, rectInRect } from '../../../../../collision/geometry'
import { update_body_hb_1a } from '../../../../../collision/hitbox'
import { ocsV1 } from '../../../../../collision/ocs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { collide_solid_grid } from '../../../../../collision/solid'
import { adjust_stat } from '../../../../../file/stats'
import { c_white } from '../../../../../Game/gmConsts'
import { draw_sprite_rot } from '../../../../../gui/deps'
import { bit_dir, bitNum, byte_bit_dir, byte_dir, sign_ } from '../../../../../math/index'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { cam_y_range, cam_yt_min } from '../../../../../view/camera'
import { Enemy } from '../../../../classes'
import { GameObject_create } from '../../../../create'
import { draw_sprite_ } from '../../../../go/draw'
import { set_xlyt, set_xy, updateX, updateY } from '../../../../go/movement'
import { GO_init_palidx, GO_update_pal_flash } from '../../../../go/palette'
import { solid_clip_correction } from '../../../../goa/movement'
import { pc } from '../../../../goa/pc'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2 } from '../../../GameObjectB'
import { instancesNamed, randoSpawnDatakey } from '../ache/_shared'

export class BubbA extends Enemy {
  readonly objectName = 'BubbA' as const
  readonly VER_BIT_FAST = 0x02
  readonly VER_BIT_STAB = 0x04 // Changes dir on stab
  readonly VER_BIT_GIAN = 0x08
  readonly VER_BIT_DORM = 0x10 // DORMant
  readonly VER_BIT_CLNG = 0x20 // Cling to walls
  is_dormant = false
  SPR_SKUL_1 = 'spr_Skull_1a_WRB'
  SPR_SKUL_2 = 'spr_Skull_2a_WRB'
  spr_skul = 'spr_Skull_1a_WRB'
  SPR_AURA_1A = 'spr_Aura_1a_WRB'
  SPR_AURA_1B = 'spr_Aura_1a_WBR'
  spr_aura: string | 0 = 'spr_Aura_1a_WRB'
  SPR_GIAN_A = 'spr_GiantBubble1A'
  SPR_GIAN_B = 'spr_GiantBubble1B'
  mp_drain_counter = 0 // to help keep mp an even number
  stab_changed_dir = 0
  SPEED1 = 0x10
  SPEED2 = 0x20
  spdBase = 0x10
  CS_OFF_IDX_DORM = 0x0c
  // cling (Bubble_cling_init)
  CLING_VER = 2
  ROTATION_USE = true
  rotation = 0 // 0: 0/360, 1: 90, 2: 180, 3: 270
  ROTATION_TIMING = (1 << 3) - 1
  rotation_ctr = 0
  WALL_PAD = 4
  POINT_OFF = 0
  /**
   * 9×9 grid: [0,0] cling side, [0,1] cling side prev, [0,2]/[0,3] colliding sides (unused), [0,4] any point
   * colliding; [1-4] corner points, [5-8] centre points: [i,0] colliding, [i,1] x, [i,2] y, [i,3-5] previous;
   * [5-8, 6/8] the grid x of the two corners adjacent to each centre point.
   */
  dg_cling: DsGrid<number> | undefined = undefined
}

/** `Bubble_init2()` */
export function Bubble_init2(self: BubbA): void {
  self.is_dormant = (self.ver & self.VER_BIT_DORM) !== 0
  self.SPR_SKUL_1 = 'spr_Skull_1a_WRB'
  self.SPR_SKUL_2 = 'spr_Skull_2a_WRB'
  self.spr_skul = self.is_dormant ? self.SPR_SKUL_2 : self.SPR_SKUL_1
  self.SPR_AURA_1A = 'spr_Aura_1a_WRB'
  self.SPR_AURA_1B = 'spr_Aura_1a_WBR'
  self.spr_aura = self.is_dormant ? 0 : self.SPR_AURA_1A
  self.SPR_GIAN_A = 'spr_GiantBubble1A'
  self.SPR_GIAN_B = 'spr_GiantBubble1B'
  self.DRAW_YOFF = 0
  const _spawn_datakey = randoSpawnDatakey(self.dk_spawn)
  const pi = _spawn_datakey !== undefined ? g.dm_spawn.get(_spawn_datakey + STR_pal_idx) : undefined
  if (pi !== undefined) GO_init_palidx(self, pi as number)
  else GO_init_palidx(self, G.PI_MOB_BLU)
  let _DIR_DATA = 0x2 | 0x8 // Default: $A = LFT($2) & UP($8)
  if (_spawn_datakey !== undefined)
    _DIR_DATA = g.dm_spawn.val(_spawn_datakey + STR_Direction, _DIR_DATA) as number
  self.hspd_dir_spawn = bit_dir(_DIR_DATA & 0x3)
  self.hspd_dir = self.hspd_dir_spawn
  self.vspd_dir_spawn = bit_dir(_DIR_DATA & 0xc)
  self.vspd_dir = self.vspd_dir_spawn
  self.mp_drain_counter = 0
  self.stab_changed_dir = 0
  self.SPEED1 = 0x10
  self.SPEED2 = 0x20
  self.spdBase = self.ver & self.VER_BIT_FAST ? self.SPEED2 : self.SPEED1
  if (self.is_dormant) {
    self.hspd = 0
    self.vspd = 0
  } else {
    self.hspd = (self.spdBase * self.hspd_dir) & 0xff
    self.vspd = (self.spdBase * self.vspd_dir) & 0xff
  }
  if (self.ver & self.VER_BIT_CLNG) Bubble_cling_init(self, _DIR_DATA)
  if (g.area_name === Area_PalcG) {
    if (isVal(self.ver, 0x01, 0x02, 0x04, 0x06, 0x10, 0x12, 0x20, 0x22)) {
      GO_init_palidx(self, G.PI_MOB_BLU)
      self.HP_IDX = 0x1f
      self.hp = g.dl_HP.get(self.HP_IDX) as number
      self.ATTACK_LEVEL = 0x04
      self.attack_level = self.ATTACK_LEVEL
    }
  }
  self.CS_OFF_IDX_DORM = 0x0c
  if (self.is_dormant) {
    self.cs_off_idx = self.CS_OFF_IDX_DORM
    self.react_sword = 0
    self.react_proj = 0
    self.react_thunder = 0
    self.xp_drain = 0
    self.vspd_grav = 1
  }
}

/** `Bubble_update()` — 99D1 / A09F */
export function Bubble_update(self: BubbA): void {
  const P = pc()
  if (self.is_dormant) {
    updateX(self)
    updateY(self)
    GO_update_cs(self)
    if (self.cs & 0x3) self.hspd = 0
    if (self.cs & 0x8 && self.vspd & 0x80) self.vspd = 0
    if (self.cs & 0x4) {
      solid_clip_correction(self, gmBool(self.vspd) && self.vspd < 0x80)
      self.vspd = 0
    }
    GOB_update_2(self)
    update_body_hb_1a(self)
    for (const flame of instancesNamed('Flame1')) {
      if (
        rectInRect(
          flame.BodyHB_xl,
          flame.BodyHB_yt,
          flame.BodyHB_w,
          flame.BodyHB_h,
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_w,
          self.BodyHB_h,
        )
      ) {
        flame.state = 0
        self.is_dormant = false
        self.hspd = (self.spdBase * sign_(world.irandom(1))) & 0xff
        self.vspd = -self.spdBase & 0xff
        self.vspd_grav = 0
        self.react_sword = self.REACT_SWORD
        self.react_proj = self.REACT_PROJ
        self.react_thunder = self.REACT_THUNDER
        self.react_spell = self.REACT_SPELL
        self.xp_drain = self.XP_DRAIN
        self.cs_off_idx = self.CS_OFF_IDX
        break
      }
    }
    return
  }
  // 99D1
  if (gmBool(self.stun_timer)) {
    GOB_update_2(self)
    return
  }
  // 99D4
  updateX(self)
  updateY(self)
  GO_update_cs(self)
  if (self.ver & self.VER_BIT_CLNG) Bubble_cling_update_1a(self)
  GOB_update_2(self)
  if (self.cs & CS_BD1) {
    enemy_collide_pc_body(self)
    self.mp_drain_counter++ // to keep mp an even number
    if (!(self.mp_drain_counter & 0x1)) adjust_stat(0, -2)
  }
  if (self.ver & self.VER_BIT_CLNG) return
  // A09F Bubble $15 & GiantBubble
  if (self.ver & self.VER_BIT_GIAN && self.hp < (g.dl_HP.get(0x1b) as number)) {
    // $17, ver 3: GiantBubble splits into two fast Bubbles
    self.state = 0 // this should happen 1st
    const _DIR_H = byte_dir(self.hspd)
    const _DIR_V = byte_dir(self.vspd)
    const _SPEED = self.SPEED2
    const _VER = (self.ver & self.VER_BIT_STAB) | self.VER_BIT_FAST
    let _x = self.x - 0x10
    let _y = self.y - 0x10
    const b1 = GameObject_create(_x, _y, 'BubbA', _VER)
    if (b1) {
      b1.hspd = byte(_SPEED * _DIR_H)
      b1.vspd = byte(_SPEED * _DIR_V)
    }
    _x = self.x
    _y = self.y + +(self.vspd >= 0x80)
    const b2 = GameObject_create(_x, _y, 'BubbA', _VER)
    if (b2) {
      b2.hspd = byte(_SPEED * _DIR_H)
      b2.vspd = byte((_SPEED * _DIR_V) ^ 0xff)
    }
  }
  if (self.ver & self.VER_BIT_STAB && self.cs & (CS_SW1 | CS_PR1)) {
    if (!gmBool(self.stab_changed_dir)) {
      self.stun_timer = 0
      if (isVal(P.behavior, P.behavior_STAB_UP, P.behavior_STAB_DOWN)) {
        if (P.behavior === P.behavior_STAB_UP) self.vspd = -abs8b(self.vspd) & 0xff
        else self.vspd = abs8b(self.vspd) & 0xff
        updateY(self)
      } else {
        // GML `if (global.pc.xScale)`: -1 (facing left) is falsy
        if (gmBool(P.xScale)) self.hspd = abs8b(self.hspd) & 0xff
        else self.hspd = -abs8b(self.hspd) & 0xff
        self.hspd_dir = byte_dir(self.hspd)
        self.facing_dir = self.hspd_dir
        updateX(self)
      }
      self.stab_changed_dir = 0xf
    }
  } else self.stab_changed_dir = 0
  // 99FB, A0FB. Giant Bubble bounces when 4 pixels are off screen, regular when 8 are.
  let _OCS = self.ocs & 0x04 // at least half w is out of ocs area
  if (self.ver & self.VER_BIT_GIAN) _OCS = self.ocs & 0x1f // any w is out of ocs area
  if (_OCS || self.cs & 0x3) {
    // 9A07
    self.hspd = byteNegate(self.hspd)
    self.hspd_dir = byte_dir(self.hspd)
    self.facing_dir = self.hspd_dir
    updateX(self)
  }
  // 9A0D, A10D
  if (!ocsV1(self) || self.cs & 0xc) {
    // if NO height w/in ocs area
    self.vspd = byteNegate(self.vspd)
    updateY(self)
  }
}

/** `Bubble_udp()` */
export function Bubble_udp(self: BubbA): void {
  self.can_draw_self = true
  if (self.is_dormant) {
    self.spr_aura = 0
    self.spr_skul = self.SPR_SKUL_2
    self.xScale = 1
  } else {
    self.palidx_base = GO_update_pal_flash(g.counter1, 0x1 << Math.sign(self.ver & self.VER_BIT_GIAN))
    self.spr_aura = self.ver & self.VER_BIT_STAB ? self.SPR_AURA_1B : self.SPR_AURA_1A
    self.spr_skul = self.SPR_SKUL_1
  }
}

/** `Bubble_draw()` */
export function Bubble_draw(self: BubbA): void {
  if (!self.can_draw_self) return
  let _ROT = 0
  if (self.ver & self.VER_BIT_CLNG) _ROT = self.rotation * 90
  pal_swap_set(self.palidx)
  if (self.ver & self.VER_BIT_GIAN) {
    // GiantBubble: left half, right half (mirrored)
    draw_sprite_(self.SPR_GIAN_A, 0, self.drawX - 8, self.drawY - 8, -1, 1, 1, self.depth)
    draw_sprite_(self.SPR_GIAN_B, 0, self.drawX - 8, self.drawY + 8, -1, 1, 1, self.depth)
    draw_sprite_(self.SPR_GIAN_A, 0, self.drawX + 8, self.drawY - 8, -1, -1, 1, self.depth)
    draw_sprite_(self.SPR_GIAN_B, 0, self.drawX + 8, self.drawY + 8, -1, -1, 1, self.depth)
  } else {
    if (self.spr_aura)
      draw_sprite_(self.spr_aura, 0, self.drawX, self.drawY, -1, self.xScale, self.yScale, self.depth)
    // GML: `draw_sprite_(spr_skul,0, drawX,drawY, -1, xScale,yScale, c_white,1, _ROT)` — the 10-argument
    // form, which is what `draw_sprite_rot` is. It records through `pushCmd`, so the skull follows the
    // surface target and the `pal_swap_set(palidx)` above; a raw `world.draw.push` did neither.
    draw_sprite_rot(self.spr_skul, 0, self.drawX, self.drawY, -1, self.xScale, self.yScale, c_white, 1, _ROT)
  }
  pal_swap_reset()
}

/** `Bubble_end()` — freed `dg_cling` in ZALiA; nothing to do here. */
export function Bubble_end(self: BubbA): void {
  self.dg_cling = undefined
}

// ---------------------------------------------------------------------------------------------------
// Wall-cling Bubble

/** `Bubble_cling_init(direction)` */
export function Bubble_cling_init(self: BubbA, direction: number): void {
  self.CLING_VER = 2
  self.ROTATION_USE = true
  self.rotation = 0 // 0: 0/360, 1: 90, 2: 180, 3: 270
  self.ROTATION_TIMING = (1 << 3) - 1
  self.rotation_ctr = 0
  self.WALL_PAD = 4
  self.POINT_OFF = self.ww_ - self.WALL_PAD
  const _DEFAULT = 0x1 << world.irandom(3) // Default. 1,2,4,8
  let _direction = direction
  if (!gmBool(_direction)) _direction = _DEFAULT
  if (self.dk_spawn !== undefined) {
    const _val = g.dm_spawn.val(self.dk_spawn + STR_Direction)
    if (typeof _val !== 'string' && _val !== 0) _direction = _val
  }
  _direction = Math.max(0x1, Math.min(0x8, bit1st(_direction)))
  set_xlyt(self, (self.xl >> 3) << 3, (self.yt >> 3) << 3) // center on center of nearest tile
  if (self.is_dormant) {
    self.hspd = 0
    self.vspd = 0
  } else {
    // Should only set one; hspd or vspd
    self.hspd = byte(self.spdBase * bit_dir(_direction & 0x3))
    self.vspd = byte(self.spdBase * bit_dir(_direction & 0xc))
  }
  const dg = new DsGrid<number>(4 + 4 + 1, 3 + 3 + 3, 0)
  self.dg_cling = dg
  const _I2 = dg.width - 4 // 4 center points
  const _I1 = _I2 - 4 // 4 corner points
  const _I3 = dg.height - 2 // 2nd to last grid y
  dg.set(_I2 + 0, _I3 + 1, _I1 + 3) // RGT-BTM corner
  dg.set(_I2 + 0, _I3 - 1, _I1 + 1) // RGT-TOP corner
  dg.set(_I2 + 1, _I3 + 1, _I1 + 2) // LFT-BTM corner
  dg.set(_I2 + 1, _I3 - 1, _I1 + 0) // LFT-TOP corner
  dg.set(_I2 + 2, _I3 + 1, _I1 + 3) // BTM-RGT corner
  dg.set(_I2 + 2, _I3 - 1, _I1 + 2) // BTM-LFT corner
  dg.set(_I2 + 3, _I3 + 1, _I1 + 1) // TOP-RGT corner
  dg.set(_I2 + 3, _I3 - 1, _I1 + 0) // TOP-LFT corner
  dg.set(0, 0, (self.dk_spawn !== undefined ? g.dm_spawn.val(`${self.dk_spawn + STR_Data}02`) : 0) as number) // cling side
  dg.set(0, 0, Math.max(0x0, Math.min(0x8, bit1st(dg.get(0, 0) as number))))
  dg.set(0, 1, dg.get(0, 0) as number) // cling side prev frame
  dg.set(0, 2, -1) // -1 indicates hasn't determined colliding sides yet
  dg.set(0, 3, dg.get(0, 2) as number) // colliding sides prev frame
  Bubble_cling_update_2a(self)
  const c = (x: number, y: number) => dg.get(x, y) as number
  const _X_OFF_RGT = -(c(_I2 + 0, 1) & 0x7) // rgt
  const _X_OFF_LFT = 0x7 - (c(_I2 + 1, 1) & 0x7) // lft
  let _X_OFF = 0
  if (c(_I2 + 0, 0)) _X_OFF = _X_OFF_RGT
  if (c(_I2 + 1, 0)) _X_OFF = _X_OFF_LFT
  const _Y_OFF_BTM = -(c(_I2 + 2, 2) & 0x7) // btm
  const _Y_OFF_TOP = 0x7 - (c(_I2 + 3, 2) & 0x7) // top
  let _Y_OFF = 0
  if (c(_I2 + 2, 0)) _Y_OFF = _Y_OFF_BTM
  if (c(_I2 + 3, 0)) _Y_OFF = _Y_OFF_TOP
  set_xy(self, self.x + _X_OFF, self.y + _Y_OFF)
  Bubble_cling_update_2a(self)
  dg.set(0, 0, 0) // cling side: 0 or bit 1,2,4,8
  if (_direction & 0x3) {
    if (c(_I2 + 2, 0) || c(_I2 + 3, 0)) {
      // BTM or TOP colliding: cling to wall
      dg.set(0, 0, 0x4 << +(c(_I2 + 3, 0) !== 0))
    }
    if ((c(_I2 + 0, 0) && _direction & 0x1) || (c(_I2 + 1, 0) && _direction & 0x2)) {
      // RGT/LFT: cling to wall, set move speed
      dg.set(0, 0, _direction)
      self.hspd = 0
      if (c(_I2 + 2, 0))
        self.vspd = -self.spdBase & 0xff // move up
      else self.vspd = self.spdBase & 0xff // move down
    }
  } else {
    if (c(_I2 + 0, 0) || c(_I2 + 1, 0)) {
      // RGT or LFT colliding: cling to wall
      dg.set(0, 0, 0x1 << +(c(_I2 + 1, 0) !== 0))
    }
    if ((c(_I2 + 2, 0) && _direction & 0x4) || (c(_I2 + 3, 0) && _direction & 0x8)) {
      // BTM/TOP: cling to wall, set move speed
      dg.set(0, 0, _direction)
      self.vspd = 0
      if (c(_I2 + 0, 0))
        self.hspd = -self.spdBase & 0xff // move left
      else self.hspd = self.spdBase & 0xff // move right
    }
  }
  dg.set(0, 1, dg.get(0, 0) as number) // set cling side prev frame
  if (!dg.get(0, 0)) Bubble_cling_update_4a(self) // Set orientation for rotation
}

/** `Bubble_cling_update_1a()` — follow the wall: turn corners and wrap around wall ends. */
export function Bubble_cling_update_1a(self: BubbA): void {
  const dg = self.dg_cling
  if (!dg) return
  Bubble_cling_update_2a(self) // update collision points
  const c = (x: number, y: number) => dg.get(x, y) as number
  const _I2 = dg.width - 4 // 4 center points
  const _I3 = dg.height - 2 // 2nd to last grid y
  dg.set(0, 1, c(0, 0)) // set cling side prev frame
  const _MOVE_DIR = byte_bit_dir(self.hspd, self.vspd) // $0,$1,$2,$4,$8
  const _IDX = bitNum(_MOVE_DIR) - 1 // 0,1,2,3
  if (_IDX >= 0 && c(_I2 + _IDX, 0)) {
    // mid _MOVE_DIR point is colliding
    let _idx3 = 0 // RGT, LFT
    if (_IDX < 2) _idx3 = 2 // BTM, TOP
    _idx3 += _I2 // _I2: mid points
    let _NEW_DIR = -sign_(c(_idx3, 0))
    if (!c(_idx3, 0) && !c(_idx3 + 1, 0)) _NEW_DIR = sign_(world.irandom(1))
    _idx3 = 1 + Math.sign(_MOVE_DIR & 0xc) // 1: x, 2: y
    let _OFF = -(c(_I2 + _IDX, _idx3) & 0x7)
    if (_MOVE_DIR & 0xa) _OFF = 0x7 + _OFF
    let _X_OFF = _OFF
    let _Y_OFF = _OFF
    if (_MOVE_DIR & 0xc) _X_OFF = Math.abs(_OFF) * _NEW_DIR
    else _Y_OFF = Math.abs(_OFF) * _NEW_DIR
    set_xy(self, self.x + _X_OFF, self.y + _Y_OFF)
    self.hspd = 0
    self.vspd = 0
    if (!(_MOVE_DIR & 0x3)) self.hspd = (self.spdBase * _NEW_DIR) & 0xff
    else self.vspd = (self.spdBase * _NEW_DIR) & 0xff
    dg.set(0, 0, _MOVE_DIR) // cling side
    Bubble_cling_update_3a(self) // rotate
  } else if (c(0, 0)) {
    // cling side. Side that's anchored to the wall.
    let _IDX2 = bitNum(c(0, 0)) - 1 // 0-3 (should be 2-BTM or 3-TOP)
    _IDX2 += _I2
    const _IDX1 = c(_IDX2, _I3 + -bit_dir(_MOVE_DIR)) // get gridx of dg_cling
    if (!c(_IDX2, 0) && !c(_IDX1, 0)) {
      // center point and corner of cling side not colliding anymore
      const _NEW_DIR = bit_dir(c(0, 0))
      let _X_OFF = 0
      let _Y_OFF = 0
      let _x = 0
      let _y = 0
      switch (_MOVE_DIR) {
        case 1:
          _X_OFF = -((c(_IDX1, 1) & 0x7) + 1)
          _Y_OFF = Math.abs(_X_OFF) * _NEW_DIR
          _x = c(_IDX1, 1) + _X_OFF
          _y = c(_IDX1, 2) + 4 * _NEW_DIR
          break
        case 2:
          _X_OFF = 7 - (c(_IDX1, 1) & 0x7) + 1
          _Y_OFF = Math.abs(_X_OFF) * _NEW_DIR
          _x = c(_IDX1, 1) + _X_OFF
          _y = c(_IDX1, 2) + 4 * _NEW_DIR
          break
        case 4:
          _Y_OFF = -((c(_IDX1, 2) & 0x7) + 1)
          _X_OFF = Math.abs(_Y_OFF) * _NEW_DIR
          _x = c(_IDX1, 1) + 4 * _NEW_DIR
          _y = c(_IDX1, 2) + _Y_OFF
          break
        case 8:
          _Y_OFF = 7 - (c(_IDX1, 2) & 0x7) + 1
          _X_OFF = Math.abs(_Y_OFF) * _NEW_DIR
          _x = c(_IDX1, 1) + 4 * _NEW_DIR
          _y = c(_IDX1, 2) + _Y_OFF
          break
      }
      if (collide_solid_grid(_x, _y) & TID_SOLID1) {
        set_xy(self, self.x + _X_OFF, self.y + _Y_OFF)
        self.hspd = 0
        self.vspd = 0
        if (!(_MOVE_DIR & 0x3)) self.hspd = (self.spdBase * _NEW_DIR) & 0xff
        else self.vspd = (self.spdBase * _NEW_DIR) & 0xff
        // set cling side
        if (_MOVE_DIR & 0x3) dg.set(0, 0, _MOVE_DIR ^ 0x3)
        else dg.set(0, 0, _MOVE_DIR ^ 0xc)
        Bubble_cling_update_3a(self) // rotate
      } else if (!c(0, 4)) {
        // 0 if NO points are colliding
        dg.set(0, 0, 0)
        Bubble_cling_update_4a(self) // Set orientation for rotation
      }
    }
  }
}

/** `Bubble_cling_update_2a()` — UPDATE COLLISION POINTS */
export function Bubble_cling_update_2a(self: BubbA): void {
  const dg = self.dg_cling
  if (!dg) return
  const _COUNT1 = dg.width
  dg.set(0, 4, 0)
  for (let _i = 1; _i < _COUNT1; _i++) {
    const _a1 = _i < _COUNT1 - 4 // true: corners
    const _ib = (_i - 1) & 0x3 // 0-3
    // Record previous
    dg.set(_i, 3, dg.get(_i, 0) as number) // colliding state
    dg.set(_i, 4, dg.get(_i, 1) as number) // x
    dg.set(_i, 5, dg.get(_i, 2) as number) // y
    // Set new
    let _x = self.x
    let _y = self.y
    if (_a1) {
      // corners.  _ib=0 top lft, _ib=1 top rgt, _ib=2 btm lft, _ib=3 btm rgt
      _x = self.x + (self.POINT_OFF + +!(_ib & 0x1)) * sign_(_ib & 0x1)
      _y = self.y + (self.POINT_OFF + +!(_ib > 0x1)) * sign_(_ib > 0x1)
    } else {
      // centers.  _ib=0 rgt, _ib=1 lft, _ib=2 btm, _ib=3 top
      if (_ib > 1)
        _y = self.y + (self.POINT_OFF + (_ib & 0x1)) * sign_(!(_ib & 0x1)) // 2 btm, 3 top
      else _x = self.x + (self.POINT_OFF + (_ib & 0x1)) * sign_(!(_ib & 0x1)) // 0 rgt, 1 lft
    }
    dg.set(_i, 1, _x)
    dg.set(_i, 2, _y)
    dg.set(_i, 0, collide_solid_grid(_x, _y) & TID_SOLID1) // colliding state
    if (!dg.get(_i, 0)) {
      if (_x >= 0 && _y >= 0 && _x < g.rm_w && _y < g.rm_h && gmBool(G.dg_chain.get(_x >> 3, _y >> 3)))
        dg.set(_i, 0, TID_SOLID1)
    }
    // Check if out of rm bounds
    if (!dg.get(_i, 0) && !pointInRect(_x, _y, cam_xl_min(), cam_yt_min(), cam_x_range(), cam_y_range()))
      dg.set(_i, 0, TID_SOLID1)
    dg.set(0, 4, (dg.get(0, 4) as number) | (dg.get(_i, 0) as number))
  }
}

/** `Bubble_cling_update_3a()` — rotate the skull when turning a corner. */
export function Bubble_cling_update_3a(self: BubbA): void {
  const dg = self.dg_cling
  if (!self.ROTATION_USE || !dg) return
  const cling = dg.get(0, 0) as number
  if (gmBool(self.hspd) && self.rotation & 0x1) {
    // horz orientation
    self.rotation += byte_dir(self.hspd) * sign_(cling & 0x8)
    return
  }
  if (gmBool(self.vspd) && !(self.rotation & 0x1)) {
    // vert orientation
    self.rotation += byte_dir(self.vspd) * sign_(cling & 0x1)
  }
}

/** `Bubble_cling_update_4a()` — Orient vertical or sideways so orientation is correct when finding next wall. */
export function Bubble_cling_update_4a(self: BubbA): void {
  if (!self.ROTATION_USE) return
  if (gmBool(self.hspd)) self.rotation += (self.rotation & 0x1) * -byte_dir(self.hspd)
  else self.rotation += +!(self.rotation & 0x1) * -byte_dir(self.vspd)
  self.rotation &= 0x3
}

registerObject('BubbA', BubbA)
registerScripts({
  Bubble_init2,
  Bubble_update,
  Bubble_udp,
  Bubble_draw,
  Bubble_end,
  Bubble_cling_update_1a,
  Bubble_cling_update_2a,
  Bubble_cling_update_3a,
  Bubble_cling_update_4a,
})
