/**
 * Aruroda (ZALiA object `Aruroda01`, parent `Enemy`; the fire-breathing lizard with a shielding head).
 * `Aruroda_init2/update/udp/draw.gml`.
 */
import { CS_BD1, ITM_SWRD, MAX_GOC1, STR_obj_idx, STR_Version, TID_SOLID1, UIDX_NULL } from '@z2/data'
import { hexStr } from '../../../../../../nes/hexStr'
import { gmBool } from '../../../../../../nes/math8'
import { f, G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { GOB_shield_collision_1a } from '../../../../../collision/gob'
import { update_body_hb_1a } from '../../../../../collision/hitbox'
import { ocsH2 } from '../../../../../collision/ocs'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { collide_solid_grid, find_row_solid } from '../../../../../collision/solid'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { gmObjectName } from '../../../../../niao/gmIndex.generated'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { draw_sprite_, GO_draw_sprite } from '../../../../go/draw'
import { dir_to_pc } from '../../../../go/misc'
import { set_xy, updateX } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_set_sprite } from '../../../../go/sprite'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_1, GOB_update_2, update_EF11 } from '../../../GameObjectB'
import { Enemy_update_2, Enemy_update_3, projOf } from '../ache/_shared'

export class Aruroda01 extends Enemy {
  readonly objectName = 'Aruroda01' as const
  SPR_WALK = 'spr_Aruroda_body2' // legs closed
  SPR_IDLE = 'spr_Aruroda_body1' // legs open
  Head_sprite = 'spr_Aruroda_head1'
  tail_spr = 'spr_Aruroda_tail1'
  VSPD_GRAV = 2
  DUR_EYE_OPEN = 0x20
  tmr_eye_open = 0 // 0081,X
  DUR_TAIL_FORWARD = 0x10
  tmr_tail_forward = 0
  frwd_bkwd = 1
  attack_dist = 0
}

/** `Aruroda_init2()` */
export function Aruroda_init2(self: Aruroda01): void {
  GO_init_palidx(self, G.PI_MOB_BLU)
  self.SPR_WALK = 'spr_Aruroda_body2' // legs closed
  self.SPR_IDLE = 'spr_Aruroda_body1' // legs open
  self.Head_sprite = 'spr_Aruroda_head1'
  self.tail_spr = 'spr_Aruroda_tail1'
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.projectile_OBJ = 'Fireball1'
  self.projectile_VER = 2
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.ShieldHB_IDX = 0xff // $FF means use body hb dimensions
  self.ShieldHB_idx = self.ShieldHB_IDX
  self.DUR_EYE_OPEN = 0x20
  self.tmr_eye_open = 0 // 0081,X
  self.DUR_TAIL_FORWARD = 0x10
  self.tmr_tail_forward = 0
  self.frwd_bkwd = self.facing_dir
  // For Rando: when this spawn was randomized into a different objver, drop to the floor below.
  if (self.dk_spawn !== undefined) {
    const _obj = g.dm_spawn.val(self.dk_spawn + STR_obj_idx) as number
    const _ver = g.dm_spawn.val(self.dk_spawn + STR_Version) as number
    if (gmBool(_obj) && gmBool(_ver)) {
      if (gmObjectName(_obj) + hexStr(_ver) !== self.objectName + hexStr(self.ver)) {
        let _y = ((self.yb >> 3) - 1) << 3
        if (gmBool(collide_solid_grid(self.x, _y))) {
          _y = find_row_solid(0, self.x >> 3, _y >> 3, -1, 0, 0)
          _y = (_y + 1) << 3
          _y -= self.hh_
          set_xy(self, self.x, _y)
        }
      }
    }
  }
}

/** `Aruroda_update()` — 9AAE */
export function Aruroda_update(self: Aruroda01): void {
  // 9AAE
  GO_update_cs(self)
  Enemy_update_3(self) // update vertical, adjClipFloor()
  // 9AB1
  if (!gmBool(self.tmr_eye_open)) {
    update_EF11(self)
    update_body_hb_1a(self) // Aruroda shld copies its body hb values
    GOB_shield_collision_1a(self)
  }
  if (gmBool(self.tmr_eye_open)) self.tmr_eye_open--
  if (gmBool(self.tmr_tail_forward)) self.tmr_tail_forward--
  if (self.pc_sword_collided_solid_body && !(f.items & ITM_SWRD)) return // lvl2 sword can pierce
  // 9AC5
  GOB_update_2(self)
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  GOB_update_1(self, self.cs & 0x4) // update hspdPB
  GO_update_cs(self)
  if (!(self.cs & 0x3)) updateX(self)
  if (!(g.counter1 & 0x3f)) self.facing_dir = dir_to_pc(self)
  self.counter = (self.counter + 1) & 0xff
  self.hspd = 0
  Enemy_update_2(self) // set hspd
  const r1 = (g.dl_RandomOG.get(1 + self.update_idx) as number) ?? 0
  const r2 = (g.dl_RandomOG.get(2 + self.update_idx) as number) ?? 0
  if (!((r1 ^ 0xff) & 0xfc)) self.tmr_eye_open = self.DUR_EYE_OPEN // $20
  if (!(r2 & 0x3f)) self.tmr_tail_forward = self.DUR_TAIL_FORWARD // $10
  if (
    self.tmr_tail_forward === self.DUR_TAIL_FORWARD - 8 &&
    ocsH2(self) && // at least 8 (4 if ww == 8) pixels width w/in ocs area width
    avail_uidx_goc(MAX_GOC1) !== UIDX_NULL
  ) {
    // 9AFE.  Fireball1 pID $19
    GOC1_create(self.xl, self.yt, self.facing_dir, projOf(self), self.projectile_ver)
  }
}

/** `Aruroda_udp()` — 9E84 */
export function Aruroda_udp(self: Aruroda01): void {
  self.can_draw_self = true
  self.Head_sprite = gmBool(self.tmr_eye_open) ? 'spr_Aruroda_head2' : 'spr_Aruroda_head1'
  self.tail_spr = gmBool(self.tmr_tail_forward) ? 'spr_Aruroda_tail2' : 'spr_Aruroda_tail1'
  if (gmBool(self.hspd) && !(g.counter1 & 0x4)) GO_set_sprite(self, self.SPR_WALK)
  else GO_set_sprite(self, self.SPR_IDLE)
}

/** `Aruroda_draw()` */
export function Aruroda_draw(self: Aruroda01): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  GO_draw_sprite(self, self.sprite)
  GO_draw_sprite(self, self.tail_spr)
  draw_sprite_(
    self.Head_sprite,
    0,
    self.drawX + 0x10 * self.xScale,
    self.drawY,
    -1,
    self.xScale,
    1,
    self.depth,
  )
  pal_swap_reset()
}

registerObject('Aruroda01', Aruroda01)
registerScripts({ Aruroda_init2, Aruroda_update, Aruroda_udp, Aruroda_draw })
