/**
 * `d_l0__oo__0l_b()` — ZALiA's deliberately obfuscated easter-egg unlock, called every frame from `g_Step`.
 * Holding Up for ~60 s while a specific NPC (`g._8w8_` / `g._8x8_` dialogue datakeys) is talking toggles the
 * hidden features `g._YwY_` / `g._YxY_` (a combo sound confirms). Identifiers kept as in the GML.
 */
import { DEV, ROOM_SPEED_BASE } from '@z2/data'
import { gmBool } from '../../nes/math8'
import { g, input } from '../../runtime/world'
import { aud_play_combo1 } from '../sound/play'

export function d_l0__oo__0l_b(): void {
  // for enabling
  let _TIME1 = ROOM_SPEED_BASE * 60
  if (DEV) _TIME1 = 0x100
  // for disabling
  const _TIME2 = 0x100
  const _BUTTON_ENABLE = input.GP_Up_held
  const _BUTTON_DISABLE = _BUTTON_ENABLE
  const src = g.dialogue_source
  const _C1 =
    g.gui_state === g.gui_state_DIALOGUE1 &&
    gmBool(src) &&
    gmBool(src.is_talking) &&
    (_BUTTON_ENABLE || _BUTTON_DISABLE) &&
    !gmBool(input.heldH) &&
    !gmBool(input.heldSC)

  if (_C1 && src.dialogue_datakey === g._8w8_) {
    if (g._OwO_ >= 0) g._OwO_++
    if (
      (_BUTTON_ENABLE && !g._YwY_ && g._OwO_ >= _TIME1) ||
      (_BUTTON_DISABLE && g._YwY_ && g._OwO_ >= _TIME2)
    ) {
      g._YwY_ = !g._YwY_
      g._OwO_ = -1
      aud_play_combo1(g._YwY_ ? 0x11 : 0x12)
    }
  } else if (gmBool(g._OwO_)) g._OwO_--
  if (g._OwO_ === -1 && g.gui_state === g.gui_state_NONE) g._OwO_ = 0

  if (_C1 && src.dialogue_datakey === g._8x8_) {
    if (g._OxO_ >= 0) g._OxO_++
    if (
      (_BUTTON_ENABLE && !g._YxY_ && g._OxO_ >= _TIME1) ||
      (_BUTTON_DISABLE && g._YxY_ && g._OxO_ >= _TIME2)
    ) {
      g._YxY_ = !g._YxY_
      g._OxO_ = -1
      aud_play_combo1(g._YxY_ ? 0x11 : 0x12)
    }
  } else if (gmBool(g._OxO_)) g._OxO_--
  if (g._OxO_ === -1 && g.gui_state === g.gui_state_NONE) g._OxO_ = 0
}
