/**
 * Overworld biome rando — ported from `Rando_randomize_overworld_biomes.gml` (68 lines).
 *
 * Every biome that carries an encounter (`dm_enc[?_Rando_Biome<name>]`) is paired with a shuffled copy of
 * itself, and the pairing is emitted as a tile-source remap: the source biome's primary / secondary /
 * tertiary / special TSRC each map to the same slot of the biome that replaced it (falling back to the
 * replacement's primary TSRC). `file_load` reads the encoded map back into `OVERWORLD.dm_Rando_TSRC`
 * through `STR_Overworld+STR_TSRC+STR_Randomized`.
 *
 * Dropped: nothing — the GML has no dead blocks (only the commented-out alternate loop head at `:23`).
 */
import {
  STR_Biome,
  STR_Count,
  STR_Overworld,
  STR_Primary,
  STR_Rando,
  STR_Randomized,
  STR_Secondary,
  STR_Special,
  STR_Tertiary,
  STR_TSRC,
} from '@z2/data'
import { DsList, DsMap } from '../../runtime/ds'
import { G, world } from '../../runtime/world'
import { type GmJsonValue, json_encode } from '../file/json'
import { save_game_pref } from '../file/prefs'
import { gmBool } from '../math/index'
import { hex_str, val } from '../other/index'
import type { Overworld } from '../overworld/Overworld'
import { ds_list_copy, ds_list_shuffle } from './helpers'
import type { Rando } from './Rando'

export function Rando_randomize_overworld_biomes(self: Rando): void {
  G.can_rando_ow_tsrc = gmBool(self.OverworldBiomes_WILL_RANDOMIZE)
  save_game_pref()

  world.random_set_seed(self.Rando_SEED)

  const _dm_RANDO_OW_TSRC = new DsMap<GmJsonValue>()
  const _dl_RANDO_BIOME_A = new DsList<string>()
  const _dl_RANDO_BIOME_B = new DsList<string>()
  const _dk1 = STR_Rando + STR_Biome

  // `with(global.OVERWORLD)` — a `with` on a destroyed instance is a no-op in GML.
  const _ow = G.OVERWORLD as Overworld | undefined
  if (_ow) {
    const Biome_dm = _ow.Biome_dm
    const dm_enc = _ow.dm_enc

    const _COUNT1 = val(Biome_dm.get(STR_Biome + STR_Count)) as number
    for (let _i = 1; _i <= _COUNT1; _i++) {
      // Each biome
      const _val1 = val(Biome_dm.get(STR_Biome + hex_str(_i))) as string
      if (gmBool(val(dm_enc.get(_dk1 + String(_val1))) as number)) {
        _dl_RANDO_BIOME_A.add(_val1)
      }
    }

    ds_list_copy(_dl_RANDO_BIOME_B, _dl_RANDO_BIOME_A)
    ds_list_shuffle(_dl_RANDO_BIOME_B)

    for (let _i = _dl_RANDO_BIOME_A.size - 1; _i >= 0; _i--) {
      const _val1 = _dl_RANDO_BIOME_A.get(_i) as string
      const _val2 = _dl_RANDO_BIOME_B.get(_i) as string
      const _val4 = dm_enc.get(_dk1 + _val2 + STR_TSRC + STR_Primary) as number | undefined
      if (_val4 !== undefined) {
        for (const _slot of [STR_Primary, STR_Secondary, STR_Tertiary, STR_Special]) {
          const _val3 = dm_enc.get(_dk1 + _val1 + STR_TSRC + _slot) as number | undefined
          if (_val3 !== undefined) {
            _dm_RANDO_OW_TSRC.set(
              hex_str(_val3),
              val(dm_enc.get(_dk1 + _val2 + STR_TSRC + _slot) as number | undefined, _val4),
            )
          }
        }
      }
    }
  }

  const _val = json_encode(_dm_RANDO_OW_TSRC)
  self.dm_save_data.set(STR_Overworld + STR_TSRC + STR_Randomized, _val)
}
