import type { RawInput } from '@z2/core'
import type Phaser from 'phaser'
import { ALL_KEYS, type DeviceSnapshot, InputMapper, KEY_CODES } from './mapping'

/** Samples Phaser keyboard + first gamepad into a `RawInput` each frame. */
export class InputSampler {
  private readonly keys: Map<string, Phaser.Input.Keyboard.Key>
  private readonly mapper = new InputMapper()

  constructor(private readonly scene: Phaser.Scene) {
    const kb = scene.input.keyboard
    this.keys = new Map()
    if (kb) {
      for (const k of ALL_KEYS) this.keys.set(k, kb.addKey(KEY_CODES[k], false, false))
    }
  }

  sample(): RawInput {
    const keysDown = new Set<DeviceSnapshot['keysDown'] extends ReadonlySet<infer K> ? K : never>()
    for (const [name, key] of this.keys) if (key.isDown) keysDown.add(name as never)
    const pad = this.scene.input.gamepad?.pad1
    const snap: DeviceSnapshot = {
      keysDown,
      gamepad: pad?.connected
        ? { id: pad.id, buttons: pad.buttons.map((b) => b.pressed), axes: pad.axes.map((a) => a.getValue()) }
        : null,
    }
    return this.mapper.map(snap)
  }
}
