/** `Switch_init()` */
export function Switch_init(self: SwchA | SwchB): void {
  self.can_draw_self_exception = true
  self.DRAW_YOFF = 0
  GO_depth_init(self, DEPTH_BG3)
  self.scr_step = GameObjectB_step as never
  self.SND_PRESS_1 = get_audio_theme_track(STR_Stab)
  self.snd_press = self.SND_PRESS_1 as never
}

/** `SwitchA_init2()` */
export function SwitchA_init2(self: SwchA): void {
  GO_depth_init(self, DEPTH_BG4 + 1) // +1 so tile pal swap can work
  self.SPR_HEAD = 'spr_Switch_part_1a_1'
  self.SPR_POLE = 'spr_Switch_part_5a'
  self.sprite = self.SPR_HEAD // for GO_draw_sprite_outline()
  GO_set_sprite_index(self, self.SPR_HEAD)
  self.facing_dir = 1
  self.sub_state = self.SUB_ST_IDLE
  self.tmr_hold = 0
  self.timer = 0
  const dk = self.dk_spawn
  if (dk !== undefined && (val(g.dm_spawn.get(dk + STR_Duration)) as number) + 1)
    self.DUR_GOAL = g.dm_spawn.get(dk + STR_Duration) as number
  else self.DUR_GOAL = 0x80 // Default
  // 0: RGT(0 deg), 1: UP(90 deg), 2: LFT(180 deg), 3: DWN(270 deg)
  if (dk !== undefined && gmBool(val(g.dm_spawn.get(dk + STR_Direction)) as number))
    self.orientation = g.dm_spawn.get(dk + STR_Direction) as number
  else self.orientation = 0
  self.orientation &= 3 // Just in case value was set higher than 3.
  self.yScale = self.orientation & 2 ? -1 : 1
  self.IMG_ANG = self.orientation * 90
  if (dk !== undefined && gmBool(val(g.dm_spawn.get(dk + STR_Length)) as number))
    self.POLE_UNITS = g.dm_spawn.get(dk + STR_Length) as number
  else self.POLE_UNITS = 1
  self.MAX_LENGTH = self.POLE_UNITS << 3
  self.speed1 = 0
  self.SPD_I = 0x18 // speed IN
  self.SPD_O = 0x04 // speed OUT
  const _BODY_W = 2 // width
  const _BODY_L = 14 // length
  const _BODY_COFF = 8 - (_BODY_W >> 1) // C: Center
  self.GOAL_X = self.x
  self.GOAL_Y = self.y
  self.GOAL_XX = self.GOAL_X - sprite_get_xoffset(self.sprite_index)
  self.GOAL_YY = self.GOAL_Y - sprite_get_yoffset(self.sprite_index)
  self.DIR_IN = 1
  switch (self.orientation) {
    case 0:
    case 2: {
      self.DIR_IN = self.orientation === 0 ? -1 : 1
      self.x += self.MAX_LENGTH * -self.DIR_IN
      self.BodyHB_w = _BODY_W
      self.BodyHB_h = _BODY_L
      self.BodyHB_xoff = -(self.BodyHB_w >> 1) + _BODY_COFF * -self.DIR_IN
      self.BodyHB_yoff = -(self.BodyHB_h >> 1)
      break
    }
    case 1:
    case 3: {
      self.DIR_IN = self.orientation === 1 ? 1 : -1
      self.y += self.MAX_LENGTH * -self.DIR_IN
      self.BodyHB_w = _BODY_L
      self.BodyHB_h = _BODY_W
      self.BodyHB_xoff = -(self.BodyHB_w >> 1)
      self.BodyHB_yoff = -(self.BodyHB_h >> 1) + _BODY_COFF * -self.DIR_IN
      break
    }
  }
  self.xl = self.x - 8
  self.yt = self.y - 8
  update_draw_xy(self)
  update_body_hb_3a(self)
}

/** `SwitchA_update()` */
export function SwitchA_update(self: SwchA): void {
  const P = pc()
  if (
    self.sub_state === self.SUB_ST_IDLE ||
    (self.sub_state === self.SUB_ST_MOVE && Math.abs(self.speed1) <= self.SPD_O)
  ) {
    update_body_hb_3a(self)
    if (collide_pc_sword(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h)) {
      const _PUSH = 0xc
      let _qual = false
      switch (self.orientation) {
        case 0:
        case 2:
          if (isVal(P.behavior, P.behavior_STAB_STAND, P.behavior_STAB_CROUCH) && P.xScale === self.DIR_IN) {
            _qual = true
            g.control1_timer = P.Pushback_DURATION
            P.hspd = (_PUSH * -self.DIR_IN) & 0xff
          }
          break
        case 1:
          if (isVal(P.behavior, P.behavior_STAB_DOWN) && P.vspd && P.vspd < 0x80) {
            _qual = true
            PC_set_bounce()
          }
          break
        case 3:
          if (isVal(P.behavior, P.behavior_STAB_UP) && P.vspd && P.vspd & 0x80) {
            _qual = true
            P.vspd = 0
          }
          break
      }
      if (_qual) {
        self.speed1 = self.SPD_I
        aud_play_sound(get_audio_theme_track(dk_ElevatorMove))
        aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
        self.sub_state = self.SUB_ST_MOVE
      }
    }
  }
  switch (self.sub_state) {
    case self.SUB_ST_IDLE:
      break
    case self.SUB_ST_MOVE: {
      self.hspd = 0
      self.vspd = 0
      let _coord_a = 0
      let _coord_b = 0
      const _SPD = (self.speed1 * self.DIR_IN) & 0xff
      if (self.orientation & 1) {
        self.vspd = _SPD
        updateY(self)
        _coord_a = self.y
        _coord_b = self.GOAL_Y
      } else {
        self.hspd = _SPD
        updateX(self)
        _coord_a = self.x
        _coord_b = self.GOAL_X
      }
      // `SwitchA_update.gml:106` — `speed1` decays to `-SPD_O`, and GM's `if` is `> 0.5`: once negative it
      // takes the `else` (-1) branch, where a JS truthiness test keeps taking the -2 one.
      if (gmBool(self.speed1)) self.speed1 = Math.max(self.speed1 - 2, -self.SPD_O)
      else self.speed1 = Math.max(self.speed1 - 1, -self.SPD_O)
      self.hspd = 0
      self.vspd = 0
      if (Math.sign(_coord_a - _coord_b + self.DIR_IN) === self.DIR_IN) {
        self.xl = self.GOAL_XX
        self.yt = self.GOAL_YY
        set_xlyt(self, self.xl, self.yt)
        self.speed1 = 0
        self.timer = self.DUR_GOAL
        self.sub_state = self.SUB_ST_GOAL
      } else if (Math.abs(_coord_a - _coord_b) >= self.MAX_LENGTH) {
        self.xl = self.GOAL_XX
        self.yt = self.GOAL_YY
        if (self.orientation & 1) self.yt += self.MAX_LENGTH * -self.DIR_IN
        else self.xl += self.MAX_LENGTH * -self.DIR_IN
        set_xlyt(self, self.xl, self.yt)
        self.speed1 = 0
        self.sub_state = self.SUB_ST_IDLE
      }
      break
    }
    case self.SUB_ST_GOAL: {
      if (!self.timer) {
        // Nudge 1 pixel out to prevent SUB_ST_MOVE from setting sub_state back to SUB_ST_GOAL
        if (self.orientation & 1) set_xlyt(self, self.xl, self.yt + -self.DIR_IN)
        else set_xlyt(self, self.xl + -self.DIR_IN, self.yt)
        self.speed1 = -self.SPD_O
        self.sub_state = self.SUB_ST_MOVE
      }
      break
    }
    case self.SUB_ST_COMP:
      break
  }
  SwitchA_udp(self)
}

/** `SwitchA_udp()` */
export function SwitchA_udp(self: SwchA): void {
  self.can_draw_self = true
  update_draw_xy(self)
}

/** `SwitchA_draw()` */
export function SwitchA_draw(self: SwchA): void {
  for (let _i = 0; _i < self.POLE_UNITS; _i++) {
    let _x = self.x
    let _y = self.y
    if (self.orientation & 0x1) _y += (_i << 3) * self.DIR_IN
    else _x += (_i << 3) * self.DIR_IN
    draw_sprite_rot_at(
      self.depth,
      self.SPR_POLE,
      0,
      _x,
      _y,
      self.palidx,
      self.xScale,
      self.yScale,
      self.IMG_ANG,
    )
  }
  draw_sprite_rot_at(
    self.depth,
    self.SPR_HEAD,
    0,
    self.x,
    self.y,
    self.palidx,
    self.xScale,
    self.yScale,
    self.IMG_ANG,
  )
}

/** `SwitchB_init()` — floor switch */
export function SwitchB_init(self: SwchB): void {
  GO_depth_init(self, DEPTH_ENEMY)
  // if objects besides pc can press the switch
  self.other_objects_can_press = false
  let _pi = G.PI_BGR4
  if (self.dk_spawn !== undefined) {
    _pi = val(g.dm_spawn.get(self.dk_spawn + STR_pal_idx), _pi) as number
    for (let _i = 1; _i <= 0x10; _i++) {
      const _data = g.dm_spawn.get(self.dk_spawn + STR_Data + hexStr(_i))
      if (_data === undefined) break
      if (String(_data).includes('_Other_Objects_Can_Press')) self.other_objects_can_press = true
    }
  }
  GO_init_palidx(self, _pi)
  self.facing_dir = 1
  self.SPR_UP = 'spr_SwitchB_1a'
  self.SPR_DW = 'spr_SwitchB_1b'
  self.pressed = false
  self.complete = false // rm puzzle complete, stay pressed.
  self.pressed_count = 0
  self.GROUND_Y = self.yt + 8
  self.GROUND_Y = get_ground_y(self.x, self.GROUND_Y, -1, self.GROUND_Y)
  self.BodyHB_IDX = -1
  self.BodyHB_idx = self.BodyHB_IDX
  self.BodyHB_w = 0x0c
  self.BodyHB_h = 0x03
  self.BodyHB_xoff = (self.ww - self.BodyHB_w) >> 1
  self.BodyHB_yoff = self.GROUND_Y - self.yt // si_yoff = 8
  // Change tiles to solid.
  tile_change_1a(0, self.xl + 0, self.yt + 8, -1, 0, TID_SOLID1)
  tile_change_1a(0, self.xl + 8, self.yt + 8, -1, 0, TID_SOLID1)
}

/** `SwitchB_update()` */
export function SwitchB_update(self: SwchB): void {
  const P = pc()
  if (self.complete) self.pressed = true
  update_EF11(self)
  if (self.complete) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  update_body_hb_2a(self)
  // *** yt is 8 ABOVE the ground.
  let _qualifies = false
  if (
    ((G.dg_solid.get(self.xl >> 3, self.yt >> 3) ?? 0) & 0xff) === TID_SOLID1 || // if solid tile on top
    ((G.dg_solid.get((self.xl >> 3) + 1, self.yt >> 3) ?? 0) & 0xff) === TID_SOLID1 ||
    collide_solid_inst(self.x, self.y - 1) ||
    (P.cs & CS_BTM &&
      pointInRect(P.cp1X, P.cp1Y, self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h)) // if PC on top
  ) {
    _qualifies = true
  } else if (self.other_objects_can_press) {
    for (const o of world.instancesOf(GameObjectB)) {
      if (
        o.cs & 0x4 &&
        pointInRect(o.x, o.yb, self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h)
      ) {
        _qualifies = true
        break
      }
    }
  }
  if (_qualifies) {
    if (!self.pressed) {
      self.pressed_count++
      aud_play_sound(self.snd_press as never)
    }
    self.pressed = true
  } else {
    if (self.pressed) aud_play_sound(self.snd_press as never)
    self.pressed = false
  }
}

/** `SwitchB_udp()` */
export function SwitchB_udp(self: SwchB): void {
  self.can_draw_self = true
  GO_set_sprite(self, self.pressed ? self.SPR_DW : self.SPR_UP)
  self.xScale = 1
}
