/** `Overworld_Draw()` and `Overworld_Draw_BootsTileHint()` → draw commands on `world.draw`. */
import {
  dk_can_draw,
  STR_Count,
  STR_Location,
  STR_MAGIC,
  STR_Open,
  STR_RmName,
  STR_Sprite,
  STR_Text,
  STR_Total,
} from '@z2/data'
import { gmBool } from '../../nes/math8'
import { f, G, g, p } from '../../runtime/world'
import { rectInRect } from '../collision/geometry'
import { isVal } from '../math'
import { hex_str, val } from '../other'
import { pal_swap_reset, pal_swap_set } from '../palette/scenePalette'
import { draw_background_part, draw_point_colour, draw_sprite_, draw_text_, drawState } from '../rooms/draw'
import { tile_exists, tile_get_x, tile_get_y } from '../tile'
import { viewH, viewW, viewXL, viewYT } from '../view/camera'
import { draw_sprite_part_, pcView } from './deps'
import { ow_pc_xy } from './helpers'
import type { Overworld } from './Overworld'

const rectInView = (x: number, y: number, w: number, h: number) =>
  rectInRect(x, y, w, h, viewXL(), viewYT(), viewW(), viewH())

/** `Overworld_Draw()` */
export function Overworld_Draw(self: Overworld): void {
  const _C1 = g.room_type === 'C' && !self.exit_owrc
  const PM = g.PAUSE_MENU as { canDrawSections: number; ANIM_FRAMES_DEF: number } | 0
  const _A1 = g.room_type === 'A' && PM !== 0 && PM != null && PM.canDrawSections > PM.ANIM_FRAMES_DEF
  if (!_C1 && !_A1) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const prevDepth = drawState.depth
  drawState.depth = self.depth
  try {
    drawOverworld(self, _C1)
  } finally {
    drawState.depth = prevDepth
  }
}

function drawOverworld(self: Overworld, _C1: boolean): void {
  if (!self.Pause_ALLOW_BUFFERING && g.overworld_paused) {
    draw_text_(self.Pause_xl, self.Pause_yt, self.Pause_TEXT, self.Pause_FONT)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  const SHIFT = self.SHIFT
  const T_SIZE = self.T_SIZE
  let _x: number
  let _y: number
  const _SIGN_X = Math.sign(self.move_x)
  const _SIGN_Y = Math.sign(self.move_y)
  const _pc_clm = (self.pcrc >> 0) & 0xff
  const _pc_row = (self.pcrc >> 8) & 0xff
  let _ow_x = (_pc_clm << SHIFT) + (T_SIZE >> 1)
  let _ow_y = (_pc_row << SHIFT) + (T_SIZE >> 1)
  _ow_x -= self.DRAW_W_
  _ow_y -= self.DRAW_H_
  // -------------------------------------------------------------------
  if (self.BootsTileIndicator_can_draw) {
    self.BootsTileIndicator_can_draw = false
    Overworld_Draw_BootsTileHint(self)
  }
  if (self.HiddenExitIndicator_can_draw) {
    self.HiddenExitIndicator_can_draw = false
    const H = self.HiddenExitIndicator_dg
    for (let _i = H.width - 1; _i >= 0; _i--) {
      // $2: can draw
      if (H.get(_i, 0x02)) {
        H.set(_i, 0x02, false)
        _x = H.get(_i, 0x03) as number // $3: draw x
        _y = H.get(_i, 0x04) as number // $4: draw y
        draw_sprite_(
          self.HiddenExitIndicator_sprite,
          0,
          _x,
          _y,
          -1,
          self.HiddenExitIndicator_xscale,
          self.HiddenExitIndicator_yscale,
        )
      }
    }
  }
  // -------------------------------------------------------------------
  // ITM_MAP1,ITM_MAP2.   Kakusu, HP/MP containers, Life dolls
  // -------------------------------------------------------------------
  if (self.TreasureMaps_can_draw) {
    self.TreasureMaps_can_draw = false
    const TM = self.TreasureMaps_dg
    for (let _i = TM.width - 1; _i >= 0; _i--) {
      // $9: can draw
      if (TM.get(_i, 0x09)) {
        TM.set(_i, 0x09, false)
        _x = TM.get(_i, 0x0a) as number // $A: draw x
        _y = TM.get(_i, 0x0b) as number // $B: draw y
        const _spr = TM.get(_i, 0x0c) as string // $C: sprite
        const _pi = TM.get(_i, 0x0d) as number // $D: palette index
        pal_swap_set(_pi)
        // $8: item type
        if (TM.get(_i, 0x08) === STR_MAGIC) draw_sprite_(self.TreasureMaps_Magic_sprite1, 0, _x, _y) // bubbling liquid
        draw_sprite_(_spr, 0, _x, _y)
        pal_swap_reset()
      }
    }
  }
  // BAIT
  // -------------------------------------------------------------------
  if (self.BAIT_can_draw) {
    self.BAIT_can_draw = false
    draw_sprite_(self.BAIT_SPRITE, 0, self.BAIT_draw_x, self.BAIT_draw_y, G.PI_MOB_ORG)
  }
  // Encounter Enemies
  // -------------------------------------------------------------------
  if (self.Encounters_can_draw) {
    self.Encounters_can_draw = false
    const E = self.dg_enc_inst
    for (let _i = E.width - 1; _i >= 0; _i--) {
      if (!E.get(_i, 0)) continue
      const _idx = bitNumOf(E.get(_i, 0) as number) - 1
      _x = E.get(_i, 1) as number // enc obj center x
      _y = E.get(_i, 2) as number // enc obj center y
      const _pi = _idx === self.FAIRY_IDX ? G.PI_MOB_ORG : self.ENC_PI
      const _spr = self.dg_ENC_SPR.get(_idx, Math.sign(g.counter1 & 0x08)) as string
      draw_sprite_(_spr, 0, _x, _y, _pi)
    }
  }
  // PC
  // -------------------------------------------------------------------
  if (self.PC_can_draw) {
    self.PC_can_draw = false
    const pc = pcView()
    if (gmBool(self.PC_draw_is_sheet)) {
      self.PC_draw_is_sheet = false
      draw_sprite_part_(
        pc.Skin_image,
        0,
        self.PC_draw_sheet_xl,
        self.PC_draw_sheet_yt,
        pc.Spritesheet_W,
        pc.Spritesheet_H,
        self.PC_draw_x,
        self.PC_draw_y,
        G.PI_PC1,
        // GML passes 9 arguments (`Overworld_Draw.gml:258`). The 12th slot here is `color`, not depth —
        // `draw_sprite_part_` stamps `drawState.depth` itself — and passing 0 into it made the command
        // carry `tint: 0`, i.e. Link as a solid black silhouette whenever a user skin sheet is in use.
      )
    } else {
      draw_sprite_(pc.Skin_image, self.PC_draw_image_idx, self.PC_draw_x, self.PC_draw_y, G.PI_PC1)
    }
  }
  // WARP
  // -------------------------------------------------------------------
  if (self.Warp_can_draw) {
    self.Warp_can_draw = false
    draw_sprite_(
      self.Warp_sprite,
      0,
      self.Warp_draw_x,
      self.Warp_draw_y,
      self.Warp_pi,
      self.Warp_xscale,
      self.Warp_yscale,
    )
  }
  if (self.WarpText_can_draw) {
    self.WarpText_can_draw = false
    draw_text_(
      self.WarpText_draw_xl,
      self.WarpText_draw_yt,
      self.WarpText_text,
      self.WarpText_FONT,
      G.PI_GUI1,
    )
  }
  // -------------------------------------------------------------------
  // _C1:  g.room_type=="C" && !exit_grid_xy
  if (_C1 && self.Pause_ALLOW_BUFFERING && g.overworld_paused) {
    draw_text_(self.Pause_xl, self.Pause_yt, self.Pause_TEXT, self.Pause_FONT)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // Draw check mark over tile if the item has been acquired
  // -------------------------------------------------------------------
  if (self.ItemAcquiredIndicator_can_draw) {
    self.ItemAcquiredIndicator_can_draw = false
    const RL = self.dm_rando_locations
    const _count1 = val(f.dm_rando.get(STR_Total + STR_Location + STR_Count)) as number
    for (let _i = 1; _i <= _count1; _i++) {
      const _datakey1 = STR_Location + hex_str(_i)
      if (gmBool(val(RL.get(_datakey1 + dk_can_draw)))) {
        RL.set(_datakey1 + dk_can_draw, false)
        //
        const _spr = val(RL.get(_datakey1 + STR_Sprite), 'spr_0') as string
        _x = val(RL.get(`${_datakey1}_X`)) as number
        _y = val(RL.get(`${_datakey1}_Y`)) as number
        draw_sprite_(_spr, 0, _x, _y - 1)
        const _text = RL.get(_datakey1 + STR_Text) as string | undefined
        if (_text !== undefined) {
          const _xl = val(RL.get(`${_datakey1 + STR_Text}_XL`)) as number
          const _yt = val(RL.get(`${_datakey1 + STR_Text}_YT`)) as number
          draw_text_(_xl, _yt, _text, self.ItemAcquiredIndicator_FONT)
        }
      }
    }
  }
  // -------------------------------------------------------------------
  // DEBUG DRAW - ------------------------------------------------------
  if (_C1 && g.DevTools_state) {
    if (g.can_draw_Exit_hb || g.can_show_t_solid) {
      // each row
      for (let _i = 0; _i < self.DRAW_ROWS; _i++) {
        // each clm
        for (let _j = 0; _j < self.DRAW_CLMS; _j++) {
          const _tid = self.dg_tid.get(_j, _i) ?? -1
          if (!tile_exists(_tid)) continue
          _x = tile_get_x(_tid)
          _y = tile_get_y(_tid)
          if (rectInView(_x, _y, T_SIZE, T_SIZE)) {
            const _ow_clm = (_ow_x + (_j << SHIFT)) >> SHIFT
            const _ow_row = (_ow_y + (_i << SHIFT)) >> SHIFT
            const _owrc = (_ow_row << 8) | _ow_clm
            _x += -_SIGN_X // FIX. draw is 1 pixel off during movement
            _y += -_SIGN_Y // FIX. draw is 1 pixel off during movement
            // 'Z' to toggle
            if (g.can_show_t_solid) {
              const _tsrc = self.dg_solid.get(_ow_clm, _ow_row) ?? 0
              if (_tsrc) {
                const _ts_x = ((_tsrc >> 0) & 0x0f) << SHIFT
                const _ts_y = ((_tsrc >> 4) & 0x0f) << SHIFT
                draw_background_part(self.TILESET_TILEMARKER, _ts_x, _ts_y, T_SIZE, T_SIZE, _x, _y)
              }
            }
            // 'E' to toggle
            if (g.can_draw_Exit_hb) {
              const _dk = hex_str(_owrc)
              // if this owrc is an exit
              if (self.dm.get(_dk + STR_RmName) !== undefined) {
                const _tsrc = gmBool(self.dm.get(_dk + STR_Open)) ? 0xa0 /* $A0. Green */ : 0xb4 // $B4. Red
                const _ts_x = ((_tsrc >> 0) & 0x0f) << SHIFT
                const _ts_y = ((_tsrc >> 4) & 0x0f) << SHIFT
                draw_background_part(self.TILESET_TILEMARKER, _ts_x, _ts_y, T_SIZE, T_SIZE, _x, _y)
              }
            }
          }
        }
      }
    }
  }
}

/** `bitNum` for the encounter type bits (1,2,4 → 1,2,3). */
function bitNumOf(v: number): number {
  let n = 0
  let x = v
  while (x) {
    n++
    x >>= 1
  }
  return n
}

/** `Overworld_Draw_BootsTileHint()` — draw indicator on walkable water tiles that are always deep water graphic. */
export function Overworld_Draw_BootsTileHint(self: Overworld): void {
  const T_SIZE = self.T_SIZE
  switch (self.BootsTileIndicator_VER) {
    // ---------------------------------------------------------------
    case 1: {
      const _PC_X = ow_pc_xy(0) // pc view x
      const _PC_Y = ow_pc_xy(1) // pc view y
      if (self.WaterSparkle_timer >= self.WaterSparkle_CUE1) {
        // each owrc
        for (let _i = self.dg_WaterSparkle.width - 1; _i >= 1; _i--) {
          const _owrc = self.dg_WaterSparkle.get(_i, 0) as number
          // -1 means this ow tile doesn't sparkle
          if (_owrc >= 0) {
            // each sparkle pixel of this owrc
            for (let _j = 1; _j <= 4; _j++) {
              let _val = self.WaterSparkle_CUE1
              _val += (self.WaterSparkle_DURATION1 - self.WaterSparkle_DURATION2) * (_j - 1)
              if (
                self.WaterSparkle_timer >= _val &&
                self.WaterSparkle_timer < _val + self.WaterSparkle_DURATION1
              ) {
                const _ow_clm = (_owrc >> 0) & 0xff
                const _ow_row = (_owrc >> 8) & 0xff
                let _x = _ow_clm << 4
                let _y = _ow_row << 4
                _x += ((self.dg_WaterSparkle.get(_i, _j) as number) >> 0) & 0x0f
                _y += ((self.dg_WaterSparkle.get(_i, _j) as number) >> 4) & 0x0f
                _x = _PC_X + (_x - self.pc_ow_x) // ow x
                _y = _PC_Y + (_y - self.pc_ow_y) // ow y
                // This is to fix an unintended 1 pixel offset while pc is moving.
                _x += -self.move_x
                _y += -self.move_y
                if (self.WaterSparkle_timer < _val + (self.WaterSparkle_DURATION1 >> 1)) {
                  // 2nd half of pixel's duration moves slightly
                  _x++
                  _y--
                }
                draw_point_colour(_x, _y, p.C_WHT1)
              }
            }
          }
        }
      }
      break
    } //case 1
    // ---------------------------------------------------------------
    case 2: {
      const _PC_X = ow_pc_xy(0) // pc view x
      const _PC_Y = ow_pc_xy(1) // pc view y
      // each owrc that qualifies for drawing this frame
      for (let _i = self.dl_WaterSparkle_idx.size - 1; _i >= 0; _i--) {
        const _idx = self.dl_WaterSparkle_idx.get(_i) as number
        const _owrc = self.dg_BTI.get(_idx, 0) as number
        const _ow_clm = (_owrc >> 0) & 0xff
        const _ow_row = (_owrc >> 8) & 0xff
        let _x1 = _ow_clm << 4
        let _y1 = _ow_row << 4
        _x1 = _PC_X + (_x1 - self.pc_ow_x) // ow x
        _y1 = _PC_Y + (_y1 - self.pc_ow_y) // ow y
        // This is to fix an unintended 1 pixel offset while pc is moving.
        _x1 += -self.move_x
        _y1 += -self.move_y
        if (rectInRect(_x1, _y1, T_SIZE, T_SIZE, viewXL(), viewYT(), viewW(), viewH())) {
          // sparkle groups for this owrc
          for (let _j = 0; _j < 3; _j++) {
            const _idx1 = 2 + (_j << 1)
            const _val1 = self.dg_BTI.get(_idx, _idx1) as number
            if (_val1) {
              const _val2 = self.dg_BTI.get(_idx, _idx1 + 1) as number
              // 1 sparkle for each quadrant of the owrc
              for (let _k = 0; _k < 4; _k++) {
                if ((_j === 0 && isVal(_k, 1, 2)) || (_j === 1 && _k !== 1) || (_j === 2 && _k !== 2)) {
                  // Tweeking sparkle amount
                  continue
                }
                let _val = _val2 >> (_k << 3)
                _val &= 0xff
                let _x = _x1 + ((_val >> 0) & 0x0f)
                let _y = _y1 + ((_val >> 4) & 0x0f)
                if (_val1 === 2) {
                  _x++
                  _y--
                }
                draw_point_colour(_x, _y, p.C_WHT1)
              }
            }
          }
        }
      }
      break
    } //case 2
  } //switch(BootsTileHint_VER)
}
