/** Ported from `FallScene_update.gml` — the falling-transition overlay state (`global.FallScene_dm`). */
import {
  dk_can_draw,
  dk_PI,
  ITM_RING,
  SPL_PRTC,
  STR_Base,
  STR_Count,
  STR_Counter,
  STR_Current,
  STR_Direction,
  STR_Fall,
  STR_Index,
  STR_PC,
  STR_ScaleX,
  STR_Sequence,
  STR_Speed,
  STR_Type,
} from '@z2/data'
import { hexStr } from '../../../nes/hexStr'
import { gmBool } from '../../../nes/math8'
import { f, G, g, p } from '../../../runtime/world'
import { sign_ } from '../../math'
import { val } from '../../other'
import { viewXL, viewXR, viewYB, viewYT } from '../../view/camera'
import { gofDeps } from './deps'

export function FallScene_update(): void {
  if (!gmBool(g.FallScene_timer)) return
  const dm = p.FallScene_dm
  const n = (k: string, dflt = 0) => val(dm.get(k), dflt) as number
  const _ANIM_SPEED = 0x3 // OG is every 2 frames but that looks too fast in ZALiA. Every 4 frames looks too slow, but 3 looks fine.
  const _TYPE_ = val(dm.get(STR_Current + STR_Type), '1') as string // "1": vertical fall, "2": horizontal fall
  const _FALL_DIR = n(STR_Current + STR_Fall + STR_Direction, 0x1 << (2 * (_TYPE_ === '1' ? 1 : 0)))
  const _FALL_SPEED = n(STR_Current + STR_Fall + STR_Speed, sign_(_FALL_DIR & (0x1 | 0x4)))
  if (_FALL_DIR & (0x1 | 0x2)) dm.set(`${STR_Current}_x`, n(`${STR_Current}_x`) + _FALL_SPEED)
  if (_FALL_DIR & (0x4 | 0x8)) dm.set(`${STR_Current}_y`, n(`${STR_Current}_y`) + _FALL_SPEED)
  const _FALL_X = n(`${STR_Current}_x`)
  const _FALL_Y = n(`${STR_Current}_y`)
  if (!(n(STR_Counter) % _ANIM_SPEED)) {
    const _ANIM_DIR = sign_(_FALL_DIR & 0x5) // $5: RIGHT | DOWN
    const _COUNT = n(_TYPE_ + dk_PI + STR_Count, 3)
    let _idx = n(dk_PI + STR_Sequence + STR_Index)
    _idx = (_idx + _ANIM_DIR + _COUNT) % _COUNT
    dm.set(dk_PI + STR_Sequence + STR_Index, _idx)
    dm.set(STR_Current + dk_PI, val(dm.get(_TYPE_ + dk_PI + hexStr(_idx + 1)), G.PI_GUI2) as number)
  }
  dm.set(STR_Counter, n(STR_Counter) + 1)
  dm.set(STR_Current + STR_ScaleX, 1)
  if (_FALL_DIR & (0x4 | 0x8)) {
    // if vertical fall. $4: DOWN, $8: UP
    if (g.room_type === 'A') dm.set(STR_Current + STR_ScaleX, G.pc.xScale)
    else dm.set(STR_Current + STR_ScaleX, 1)
  } else if (_FALL_DIR & (0x1 | 0x2)) {
    // if horizontal fall. $1: RIGHT, $2: LEFT
    dm.set(STR_Current + STR_ScaleX, -sign_(_FALL_SPEED))
  }
  dm.set(STR_PC + dk_can_draw, 0)
  if (
    (_FALL_DIR & 0x4 && _FALL_Y > viewYT() + n(`${STR_Base}_Y`)) || // most likely
    (_FALL_DIR & 0x1 && _FALL_X > viewXL() + n(`${STR_Base}_X`)) ||
    (_FALL_DIR & 0x2 && _FALL_X < viewXR() - n(`${STR_Base}_X`)) ||
    (_FALL_DIR & 0x8 && _FALL_Y < viewYB() - n(`${STR_Base}_Y`)) // least likely
  ) {
    dm.set(STR_PC + dk_can_draw, 1)
    let _pi: number = G.PI_PC1
    const lvl = Math.sign(g.spells_active & SPL_PRTC) + Math.sign(f.items & ITM_RING)
    if (gofDeps.pc_is_cucco()) {
      switch (lvl) {
        default:
          _pi = G.PI_CUCCO1
          break
        case 1:
          _pi = G.PI_CUCCO2
          break
        case 2:
          _pi = G.PI_CUCCO3
          break
      }
    } else {
      switch (lvl) {
        default:
          _pi = G.PI_PC1
          break
        case 1:
          _pi = G.PI_PC2
          break
        case 2:
          _pi = G.PI_PC3
          break
      }
    }
    dm.set(STR_PC + dk_PI, _pi)
  }
}
