import type { AudioCommand, AudioGroup, AudioPlayback } from '@z2/core'
import Phaser from 'phaser'
import { ASSET_URL, type SoundEntry } from '../assets/manifest'
import { soundIndex } from './tracks'

/**
 * Executes the core's `Audio.commands` (drained each frame by `GameScene`) and implements `AudioPlayback`
 * so the core can poll what ZALiA polled from GameMaker (`audio_is_playing`, track position, group gain).
 * Sounds are loaded lazily per audio set; a `play` that arrives before its set is loaded is deferred until
 * the load completes (still ordered per instance). Which track plays for a theme, intro→body sequencing
 * and volumes are core logic (`game/sound`) — this file only plays instances.
 */
export class AudioPlayer implements AudioPlayback {
  private readonly sounds: Map<string, SoundEntry>
  private readonly loadedSets = new Map<string, Promise<void>>()
  /** Live Phaser sounds by core instance id. */
  private readonly insts = new Map<
    number,
    /** `base` is the instance's own volume (`audio_sound_gain`), before the group gain is applied. */
    { sound: Phaser.Sound.BaseSound; name: string; group: AudioGroup; base: number }
  >()
  private readonly groupGains: Record<AudioGroup, number> = { mus: 1, snd: 1 }

  constructor(
    private readonly scene: Phaser.Scene,
    sounds: readonly SoundEntry[],
  ) {
    this.sounds = soundIndex(sounds)
  }

  /** Queue every file of an audio set on the loader; resolves when loaded. */
  loadSet(set: string): Promise<void> {
    const existing = this.loadedSets.get(set)
    if (existing) return existing
    const p = new Promise<void>((resolve) => {
      for (const s of this.sounds.values())
        if (s.set === set && !this.scene.cache.audio.exists(s.name))
          this.scene.load.audio(s.name, ASSET_URL.audio(s.file))
      this.scene.load.once(Phaser.Loader.Events.COMPLETE, () => resolve())
      this.scene.load.start()
    })
    this.loadedSets.set(set, p)
    return p
  }

  private async ensure(name: string): Promise<boolean> {
    const e = this.sounds.get(name)
    if (!e) return false
    await this.loadSet(e.set)
    return this.scene.cache.audio.exists(name)
  }

  /** Length of a live core sound instance in seconds (GM `audio_sound_length`), or undefined if unknown. */
  durationSeconds(inst: number): number | undefined {
    const live = this.insts.get(inst)
    if (!live) return undefined
    const d = (live.sound as { duration?: number }).duration
    return typeof d === 'number' && d > 0 ? d : undefined
  }

  /** Drain a batch of core commands (call once per stepped frame, in order). */
  run(cmds: AudioCommand[]): void {
    for (const c of cmds) this.exec(c)
    cmds.length = 0
  }

  private exec(c: AudioCommand): void {
    switch (c.kind) {
      case 'play':
        void this.play(c)
        break
      case 'stop':
        for (const [id, i] of this.insts) if (i.name === c.sound) this.stopInst(id)
        for (const [id, p] of this.pending) if (p.name === c.sound) this.stopped.add(id)
        break
      case 'stopInst':
        this.stopInst(c.inst)
        break
      case 'stopGroup':
        for (const [id, i] of this.insts) if (i.group === c.group) this.stopInst(id)
        // …including the ones still loading: `aud_play_sound` stops the music group before starting the
        // next track, and a queued play that outlived its own stop is a second copy of the music.
        for (const [id, p] of this.pending) if (p.group === c.group) this.stopped.add(id)
        break
      case 'gain': {
        const i = this.insts.get(c.inst)
        if (i) {
          i.base = c.gain * (this.sounds.get(i.name)?.volume ?? 1) // GM multiplies the asset's own volume in
          if ('setVolume' in i.sound)
            (i.sound as Phaser.Sound.WebAudioSound).setVolume(c.gain * this.groupGains[i.group])
        }
        break
      }
      case 'groupGain':
        // GM's `audio_group_set_gain` moves the whole group *including what is already playing*. This
        // loop did nothing, so turning the music or sound slider in the Options menu left the current
        // track at its old volume until the next one started — the menu music kept the boot-time gain
        // while everything after it followed the setting.
        this.groupGains[c.group] = c.gain
        for (const i of this.insts.values())
          if (i.group === c.group && 'setVolume' in i.sound)
            (i.sound as Phaser.Sound.WebAudioSound).setVolume(i.base * c.gain)
        break
      case 'position': {
        const i = this.insts.get(c.inst)
        if (i && 'setSeek' in i.sound) (i.sound as Phaser.Sound.WebAudioSound).setSeek(c.seconds)
        break
      }
    }
  }

  private async play(c: Extract<AudioCommand, { kind: 'play' }>): Promise<void> {
    // GameMaker's `audio_play_sound` starts the instance *now*; here the set may still be loading, so the
    // instance is registered as pending first. Without that, `audio_is_playing()` answered false for a
    // sound the core had just started, and `update_Audio`'s "restart the room music if it is not playing"
    // check fired again on every frame of the load — every one of those queued plays then started at once
    // when the set arrived, which is why the title and file-select music came in many overlapping copies
    // and buried the sound effects until the sets were cached.
    this.pending.set(c.inst, { name: c.sound, group: c.group })
    const ready = await this.ensure(c.sound)
    this.pending.delete(c.inst)
    if (!ready) return
    // A stop may have arrived while loading.
    if (this.stopped.has(c.inst)) {
      this.stopped.delete(c.inst)
      return
    }
    const entry = this.sounds.get(c.sound) as SoundEntry
    const sound = this.scene.sound.add(c.sound, {
      loop: c.loop,
      volume: c.gain * entry.volume * this.groupGains[c.group],
    })
    this.insts.set(c.inst, { sound, name: c.sound, group: c.group, base: c.gain * entry.volume })
    sound.once(Phaser.Sound.Events.COMPLETE, () => {
      if (this.insts.get(c.inst)?.sound === sound) this.insts.delete(c.inst)
      sound.destroy()
    })
    sound.play()
  }

  private readonly stopped = new Set<number>()
  /** Instances the core has started that are still waiting on their audio set to load. */
  private readonly pending = new Map<number, { name: string; group: AudioGroup }>()
  private stopInst(inst: number): void {
    const i = this.insts.get(inst)
    if (!i) {
      this.stopped.add(inst) // cancels it if it is still loading
      return
    }
    i.sound.stop()
    i.sound.destroy()
    this.insts.delete(inst)
  }

  // ---- AudioPlayback -----------------------------------------------------------------------------
  isPlaying(x: string | number): boolean {
    // A pending instance counts as playing: GM had no load step, and the core polls this to decide whether
    // to restart the room music.
    if (typeof x === 'number') return this.insts.get(x)?.sound.isPlaying ?? this.pending.has(x)
    for (const i of this.insts.values()) if (i.name === x && i.sound.isPlaying) return true
    for (const p of this.pending.values()) if (p.name === x) return true
    return false
  }
  trackPosition(inst: number): number {
    const i = this.insts.get(inst)
    return i && 'seek' in i.sound ? (i.sound as Phaser.Sound.WebAudioSound).seek : 0
  }
  groupGain(group: AudioGroup): number {
    return this.groupGains[group]
  }
  /**
   * `audio_sound_length(x)` — GM takes a sound asset or a live instance. A decoded WebAudio buffer knows
   * its duration, so an asset only has a length once its set has loaded; 0 until then, which is what the
   * callers' own fallbacks are for (`FLUTE_DURATION1`, the fanfare failsafe timers).
   */
  length(x: string | number): number {
    if (typeof x === 'number') return this.durationSeconds(x) ?? 0
    const buf = this.scene.cache.audio.get(x) as { duration?: number } | undefined
    return typeof buf?.duration === 'number' ? buf.duration : 0
  }
}
