const c_orange = 0xffa500

function completeKey(self: { challenge_id: string }): string {
  return self.challenge_id + STR_Complete
}

/** Reads the `dk_spawn+STR_Data<N>` object/placement pairs (object, then "vvyyxx"*n) into created instances. */
function spawnFromData(self: GameObject, filter?: (obj: ObjectName, ver: number) => boolean): GameObject[] {
  const out: GameObject[] = []
  if (self.dk_spawn === undefined) return out
  const spawn = gp().dm_spawn
  let _count1 = 1
  let _dk = self.dk_spawn + STR_Data + hexStr(_count1++)
  while (spawn.get(_dk) !== undefined) {
    const _obj = spawn.get(_dk) as ObjectName | number
    _dk = self.dk_spawn + STR_Data + hexStr(_count1++)
    const _data = String(spawn.get(_dk) ?? '')
    const _count2 = Math.trunc(_data.length / 6)
    for (let _j = 0; _j < _count2; _j++) {
      const _ver = str_hex(_data.substr(_j * 6, 2))
      const objName = typeof _obj === 'number' ? (gmObjectName(_obj) ?? String(_obj)) : _obj
      if (filter && !filter(objName as ObjectName, _ver)) continue
      const _x = str_hex(_data.substr(_j * 6 + 4, 2)) << 3
      const _y = str_hex(_data.substr(_j * 6 + 2, 2)) << 3
      const inst = GameObject_create(_x, _y, objName as ObjectName, _ver)
      if (inst) out.push(inst)
    }
    _dk = self.dk_spawn + STR_Data + hexStr(_count1++)
  }
  return out
}

