export function Challenge_BlockConfiguration_init(self: Challenge_BlockConfiguration): void {
  init_vars_Challenge_2a(self)
  self.ST_SUB1_CHCK = 1
  self.ST_SUB1_CLEN = 2
  self.ST_SUB1_SPWN = 3
  self.ST_SUB1_END = 4
  self.sub_state = self.ST_SUB1_CHCK
  self.timer1 = 0
  // Shape of Bot
  let _data = '00000000000'
  self.CLMS = _data.length
  _data += '00011111000'
  _data += '00111111100'
  _data += '01110101110'
  _data += '11111111111'
  _data += '11111111111'
  _data += '01111111110'
  _data += '00000000000'
  self.ROWS = Math.trunc(_data.length / self.CLMS)
  self.dg_config = new DsGrid<number>(self.CLMS, self.ROWS, 0)
  for (let _i = self.CLMS * self.ROWS - 1; _i >= 0; _i--) {
    self.dg_config.set(_i % self.CLMS, Math.trunc(_i / self.CLMS), Number(_data[_i]))
  }
  switch (self.ver) {
    case 1: // (key spawn variant commented out in ZALiA)
      break
    case 2: {
      const _DEFEATED_DATAKEY = get_defeated_dk()
      const prxm = gp().dg_spawn_prxm
      for (let _i = prxm.width - 1; _i >= 0; _i--) {
        const _spawn_datakey = prxm.get(_i, 0) as string
        const _obj = prxm.get(_i, 1) as ObjectName
        const a = 13
        let _defeated_count = prxm.get(_i, a) as number
        if (!gmBool(_defeated_count))
          prxm.set(_i, a, fp().dm_quests.val(_DEFEATED_DATAKEY + _spawn_datakey) as number)
        _defeated_count = prxm.get(_i, a) as number
        if (isAncestorName(_obj, 'Kakusu')) {
          if (gmBool(_defeated_count)) {
            self.destroy()
            return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
          }
          if (gmBool(fp().dm_challenges.val(completeKey(self)))) {
            // In case the player completed the challenge, but left rm w/out defeating Kakusu
            self.sub_state = self.ST_SUB1_SPWN
          }
        }
      }
      break
    }
    case 3:
      break
  }
}

export function Challenge_BlockConfiguration_update(self: Challenge_BlockConfiguration): void {
  // The challenge is completed, but key has not been acquired.
  if (gmBool(self.timer1)) self.timer1--
  const brk = gp().dg_RmTile_Break
  switch (self.sub_state) {
    case self.ST_SUB1_CHCK: {
      for (let _i = 0; _i < self.ROWS; _i++) {
        for (let _j = 0; _j < self.CLMS; _j++) {
          const _clm = (self.xl >> 3) + (_j << 1)
          const _row = (self.yt >> 3) + (_i << 1)
          const _val1 = !!self.dg_config.get(_j, _i)
          const _val2 = (brk.get(_clm, _row) as number) & 0xff
          if (_val1 !== isVal(_val2, TID_BREAK1, TID_BREAK3)) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
        }
      }
      // All tiles match configuration
      fp().dm_challenges.set(completeKey(self), 1)
      // Stop BlockSpawner from spawning anymore blocks.
      for (const sp of instancesNamed('Spawner_FallingBlock')) {
        sp.state = 0
        if (gmBool(gp().mod_destroy_go_on_death) && !gmBool(sp.state)) GO_destroy_1a(sp)
        break
      }
      self.timer1 = 0xff // cleanup timeout in case cleanup doesnt complete
      self.timer = 0x20
      self.sub_state = self.ST_SUB1_CLEN
      break
    }
    case self.ST_SUB1_CLEN: {
      // Destroy any blocks above the block configuration.
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) return
      // Only 1 every 4 frames
      if (!(g.counter1 & 0x3)) return
      if (gmBool(self.timer1)) {
        // cleanup timeout in case the following loops forever (cleanup doesnt complete)
        let _Y = (viewYT() >> 4) << 4
        _Y += ((self.yt >> 3) & 0x1) << 3
        const _ROWS = (self.yt + 0x10 - _Y) >> 4
        const _COUNT = self.CLMS * _ROWS
        for (let _i = 0; _i < _COUNT; _i++) {
          const _clm = (self.xl >> 3) + ((_i % self.CLMS) << 1)
          const _row = (_Y >> 3) + (Math.trunc(_i / self.CLMS) << 1)
          if (isVal((brk.get(_clm, _row) as number) & 0xff, TID_BREAK1, TID_BREAK3)) {
            break_block(_clm, _row)
            return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
          }
        }
      }
      self.timer1 = 0
      self.timer = 0x0c
      self.sub_state = self.ST_SUB1_SPWN
      break
    }
    case self.ST_SUB1_SPWN: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) return
      switch (self.ver) {
        case 1:
          break
        case 2: {
          for (const b of instancesNamed<BlockBLike>('BlckB')) {
            if (gmBool(b.Chain_hang)) {
              b.Chain_connected = false
            } else {
              const _DEPTH = DEPTH_BG2
              const _X = b.xl - 8
              const _Y = b.yt + 8
              // Remove tiles under prize so it falls to the floor.
              tile_change_1a(_DEPTH, _X + (0x00 << 3), _Y + (0x00 << 3), 0, 0, 0)
              tile_change_1a(_DEPTH, _X + (0x03 << 3), _Y + (0x00 << 3), 0, 0, 0)
              tile_change_1a(_DEPTH, _X + (0x01 << 3), _Y + (0x01 << 3), 0, 0, 0)
              tile_change_1a(_DEPTH, _X + (0x02 << 3), _Y + (0x01 << 3), 0, 0, 0)
            }
            break
          }
          aud_play_sound(get_audio_theme_track(dk_BlockBreak))
          aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
          self.timer = 0x04 // delay secret sound
          self.sub_state = self.ST_SUB1_END
          break
        }
        case 3:
          break
      }
      break
    }
    case self.ST_SUB1_END: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) return
      aud_play_sound(get_audio_theme_track(STR_Secret))
      self.destroy()
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
  }
}
export function Challenge_BlockConfiguration_end(self: Challenge_BlockConfiguration): void {
  self.dg_config = new DsGrid<number>(0, 0, 0)
}

