export function Challenge_DefeatAllA_init_1(self: Challenge_DefeatAllA): void {
  Challenge_init(self)
  self.SUB_STATE_INCM_1 = 1
  self.SUB_STATE_CMPL_1 = 2
  self.SUB_STATE_CMPL_2 = 3
  self.SUB_STATE_CMPL_3 = 4
  self.sub_state = self.SUB_STATE_INCM_1
  self.DUR_DELAY_CMP1 = 0x40
  self.DUR_DELAY_CMP2 = 0x20
  self.locked_door = null
  self.dg_status = new DsGrid<GameObject | number>(0, 4, 0)
}
export function Challenge_DefeatAllA_init_2(self: Challenge_DefeatAllA): void {
  const _COMPLETE = gmBool(fp().dm_challenges.val(completeKey(self)))
  // respawn_type: 0 never, 1 off screen, 2 refresh area, 3 refresh rm, 4 30 seconds
  const insts = spawnFromData(
    self,
    (obj, ver) => !_COMPLETE || isVal(goData.dm_go_prop.val(obj + hexStr(ver) + STR_Respawn), 1, 3, 4),
  )
  self.dg_status = new DsGrid<GameObject | number>(insts.length, 4, 0)
  insts.forEach((inst, _i) => {
    self.dg_status.set(_i, 0, inst)
    self.dg_status.set(_i, 1, 1) // has spawned
  })
  switch (self.ver) {
    case 1:
      if (_COMPLETE) self.sub_state = self.SUB_STATE_CMPL_1
      else self.locked_door = GameObject_create(self.x, self.y, 'LoDoA', 3)
      break
    case 2:
    case 3:
      break
  }
}
export function Challenge_DefeatAllA_update(self: Challenge_DefeatAllA): void {
  switch (self.sub_state) {
    case self.SUB_STATE_INCM_1: {
      // INCoMplete
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      let _complete = true
      for (let _i = self.dg_status.width - 1; _i >= 0; _i--) {
        const inst = self.dg_status.get(_i, 0) as GameObject | number
        if (typeof inst === 'number' || !instanceExists(inst) || !gmBool(inst.state))
          self.dg_status.set(_i, 2, 1) // is defeated
        else _complete = false
      }
      if (!_complete) break
      fp().dm_challenges.set(completeKey(self), 1)
      self.timer = self.DUR_DELAY_CMP2
      self.sub_state = self.SUB_STATE_CMPL_1
      break
    }
    case self.SUB_STATE_CMPL_1: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      if (self.locked_door) (self.locked_door as LockedDoorLike).counter = -1 // Starts opening process
      self.timer = self.DUR_DELAY_CMP2
      self.sub_state = self.SUB_STATE_CMPL_2
      break
    }
    case self.SUB_STATE_CMPL_2: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      self.sub_state = self.SUB_STATE_CMPL_3
      break
    }
    case self.SUB_STATE_CMPL_3: {
      if (gmBool(self.timer)) self.timer--
      break
    }
  }
}
export function Challenge_DefeatAllA_end(self: Challenge_DefeatAllA): void {
  self.dg_status = new DsGrid<GameObject | number>(0, 4, 0)
}

