export function Challenge_LightTorchesA_init_1(self: Challenge_LightTorchesA): void {
  Challenge_init(self)
  self.SUB_STATE_INCM_1 = 1
  self.SUB_STATE_CMPL_1 = 2
  self.SUB_STATE_CMPL_2 = 3
  self.SUB_STATE_CMPL_3 = 4
  self.sub_state = self.SUB_STATE_INCM_1
  self.DUR_DELAY_CMP1 = 0x40
  self.DUR_DELAY_CMP2 = 0x20
  self.locked_door = null
  self.dg_torches = new DsGrid<GameObject | number | boolean>(0, 2, 0)
}
export function Challenge_LightTorchesA_init_2(self: Challenge_LightTorchesA): void {
  const torches = spawnFromData(self)
  self.dg_torches = new DsGrid<GameObject | number | boolean>(torches.length, 2, 0)
  torches.forEach((t, i) => {
    self.dg_torches.set(i, 0, t)
  })
  switch (self.ver) {
    case 1:
      if (gmBool(fp().dm_challenges.val(completeKey(self)))) {
        for (let i = self.dg_torches.width - 1; i >= 0; i--) {
          self.dg_torches.set(i, 1, true)
          ;(self.dg_torches.get(i, 0) as TorchLike).is_lit = true
        }
        self.sub_state = self.SUB_STATE_CMPL_1
      } else self.locked_door = GameObject_create(self.x, self.y, 'LoDoA', 3)
      break
    case 2:
    case 3:
      break
  }
}
export function Challenge_LightTorchesA_update(self: Challenge_LightTorchesA): void {
  switch (self.sub_state) {
    case self.SUB_STATE_INCM_1: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      let _complete = true
      for (let _i = self.dg_torches.width - 1; _i >= 0; _i--) {
        const lit = (self.dg_torches.get(_i, 0) as TorchLike).is_lit
        self.dg_torches.set(_i, 1, lit)
        if (!gmBool(lit)) _complete = false
      }
      if (!_complete) break
      fp().dm_challenges.set(completeKey(self), 1)
      self.timer = self.DUR_DELAY_CMP2
      self.sub_state = self.SUB_STATE_CMPL_1
      break
    }
    case self.SUB_STATE_CMPL_1: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      if (self.locked_door) (self.locked_door as LockedDoorLike).counter = -1 // Starts opening process
      self.timer = self.DUR_DELAY_CMP2
      self.sub_state = self.SUB_STATE_CMPL_2
      break
    }
    case self.SUB_STATE_CMPL_2: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      self.sub_state = self.SUB_STATE_CMPL_3
      break
    }
    case self.SUB_STATE_CMPL_3: {
      if (gmBool(self.timer)) self.timer--
      break
    }
  }
}
export function Challenge_LightTorchesA_end(self: Challenge_LightTorchesA): void {
  self.dg_torches = new DsGrid<GameObject | number | boolean>(0, 2, 0)
}

