export function Challenge_SpellSequence_init(self: Challenge_SpellSequenceA): void {
  Challenge_init(self)
  self.dl_spell_seq = new DsList<number>()
  self.SpellHist_COUNT1 = gp().dl_spell_history.size
  self.SpellHist_count = self.SpellHist_COUNT1
}
export function Challenge_SpellSequenceA_init_1(self: Challenge_SpellSequenceA): void {
  Challenge_SpellSequence_init(self)
  self.SUB_STATE_SEQU = 1 // Listening for spell sequence
  self.SUB_STATE_CMPL1 = 2 // Waiting for end of spell flash.
  self.SUB_STATE_CMPL2 = 3
  self.SUB_STATE_CMPL3 = 4
  self.sub_state = self.SUB_STATE_SEQU
  self.BLOCK_SPR = gp().Block1_SPR1
}
function spellSeqTiles(self: Challenge_SpellSequenceA, solid: number): void {
  for (let _i = 0; _i < 4; _i++) {
    // Change tiles to solid to block shaft.
    const _x = self.xl + ((_i & 1) << 3)
    const _y = self.yt + ((_i > 1 ? 1 : 0) << 3)
    tile_change_1a(0, _x, _y, -1, 0, solid)
  }
}
export function Challenge_SpellSequenceA_init_2(self: Challenge_SpellSequenceA): void {
  switch (self.ver) {
    case 1:
      if (gmBool(fp().dm_challenges.val(completeKey(self)))) self.destroy()
      else spellSeqTiles(self, TID_SOLID1)
      break
    case 2:
      break
  }
}
export function Challenge_SpellSequenceA_update(self: Challenge_SpellSequenceA): void {
  self.can_draw_self = true
  switch (self.sub_state) {
    case self.SUB_STATE_SEQU: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      Challenge_SpellSequenceA_update_1a(self)
      if (self.sub_state === self.SUB_STATE_CMPL1) fp().dm_challenges.set(completeKey(self), 1)
      break
    }
    case self.SUB_STATE_CMPL1: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      aud_play_sound(get_audio_theme_track(STR_Secret))
      self.sub_state = self.SUB_STATE_CMPL2
      break
    }
    case self.SUB_STATE_CMPL2: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      self.can_draw_self = false
      aud_play_sound(get_audio_theme_track(dk_EnemyDeath))
      aud_play_sound(get_audio_theme_track(dk_BlockBreak))
      self.sub_state = self.SUB_STATE_CMPL3
      break
    }
    case self.SUB_STATE_CMPL3: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      spellSeqTiles(self, 0)
      self.destroy()
      break
    }
  }
}
export function Challenge_SpellSequenceA_update_1a(self: Challenge_SpellSequenceA): void {
  const hist = gp().dl_spell_history
  const _COUNT = hist.size
  if (self.SpellHist_count < _COUNT) {
    // A spell has been cast
    self.SpellHist_count = _COUNT
    const _count = self.dl_spell_seq.size
    if (_count <= self.SpellHist_count - self.SpellHist_COUNT1) {
      const _idx = _COUNT - _count
      for (let _i = 0; _i < _count; _i++) {
        if (self.dl_spell_seq.get(_i) !== hist.get(_idx + _i)) break
        if (_i + 1 === _count) {
          self.timer = pp().SpellFlash_PC_timer + 4
          self.sub_state = self.SUB_STATE_CMPL1
        }
      }
    }
  }
}
/** `Challenge_SpellSequenceA_udp()` — empty in ZALiA (registered as the udp slot). */
export function Challenge_SpellSequenceA_udp(_self: Challenge_SpellSequenceA): void {}
export function Challenge_SpellSequenceA_draw(self: Challenge_SpellSequenceA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  draw_sprite_(self.BLOCK_SPR, 0, self.x, self.y, GG().PI_BGR2)
}
export function Challenge_SpellSequenceA_end(self: Challenge_SpellSequenceA): void {
  self.dl_spell_seq.clear()
}

