export function Challenge_SwitchA_init(self: Challenge_SwitchA): void {
  self.STATE_INCM = 1
  self.STATE_CMP1 = 2
  self.STATE_CMP2 = 3
  self.STATE_CMP3 = 4
  self.sub_state = self.STATE_INCM
  self.DUR_DELAY_CMP1 = 0x40
  self.DUR_DELAY_CMP2 = 0x20
  self.locked_door = null
  switch (self.ver) {
    case 1:
      if (gmBool(fp().dm_challenges.val(completeKey(self)))) self.sub_state = self.STATE_CMP1
      else self.locked_door = GameObject_create(self.x, self.y, 'LoDoA', 3)
      break
    case 2:
    case 3:
      break
  }
}
export function Challenge_SwitchA_update(self: Challenge_SwitchA): void {
  for (const sw of instancesNamed<SwitchALike>('SwchA')) if (sw.scr_update) sw.scr_update(sw)
  switch (self.sub_state) {
    case self.STATE_INCM: {
      let _complete = true
      for (const sw of instancesNamed<SwitchALike>('SwchA')) {
        if (sw.sub_state !== sw.SUB_ST_GOAL) {
          _complete = false
          break
        }
      }
      if (!_complete) break
      for (const sw of instancesNamed<SwitchALike>('SwchA')) sw.sub_state = sw.SUB_ST_COMP
      fp().dm_challenges.set(completeKey(self), 1)
      self.timer = self.DUR_DELAY_CMP1
      self.sub_state = self.STATE_CMP1
      break
    }
    case self.STATE_CMP1: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      for (const sw of instancesNamed<SwitchALike>('SwchA')) {
        const _diff = 3 * sw.DIR_IN
        if (sw.orientation & 0x1) set_xlyt(sw, sw.GOAL_XX, sw.GOAL_YY + _diff)
        else set_xlyt(sw, sw.GOAL_XX + _diff, sw.GOAL_YY)
        sw.sub_state = sw.SUB_ST_COMP
      }
      aud_play_sound(get_audio_theme_track(dk_ElevatorMove))
      aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
      aud_play_sound(get_audio_theme_track(STR_Stab))
      self.timer = self.DUR_DELAY_CMP2
      self.sub_state = self.STATE_CMP2
      break
    }
    case self.STATE_CMP2: {
      if (gmBool(self.timer)) self.timer--
      if (gmBool(self.timer)) break
      if (self.locked_door) (self.locked_door as LockedDoorLike).counter = -1 // Starts opening process
      self.sub_state = self.STATE_CMP3
      break
    }
    case self.STATE_CMP3: {
      if (gmBool(self.timer)) self.timer--
      break
    }
  }
}
