  self.DURATION2 = 0x80
  self.DURATION3 = 0x40
  self.counter1 = 0
  self.counter2 = -1
  self.item_inst = null
  self.REVEAL_TRACK = Audio.dm.val(STR_Cast + STR_Spell + STR_Default) as SoundId
