/** Gellzem (`GlzmA`) — a Geldarm with eyes that must all be struck. Ported from `Gellzem_*.gml`. */
import { BODY_HB_IDX_DYNAMIC, CS_BD1, dk_HitShield, dk_StrikeEnemy } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { DsList } from '../../../../../../runtime/ds'
import { GOB_body_collide_pc_body_1a } from '../../../../../collision/gob'
import { collide_pc_sword, enemy_collide_pc_body } from '../../../../../collision/pc'
import { spriteInfo } from '../../../../../graphics/sprites'
import { inRange, sign_ } from '../../../../../math/index'
import { pal_swap_reset } from '../../../../../palette/scenePalette'
import { draw_rect_, draw_sprite_, drawState } from '../../../../../rooms/draw'
import type { SoundId } from '../../../../../sound/Audio'
import { Audio } from '../../../../../sound/Audio'
import { aud_play_sound } from '../../../../../sound/play'
import { get_audio_theme_track } from '../../../../../sound/theme'
import { GO_update_pal_flash } from '../../../../go/palette'
import { pushback_pc_and_go } from '../../../../go/pushback'
import { PC_set_bounce } from '../../../../goa/attack'
import { gp, pc } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { damage_gob, update_EF11 } from '../../../GameObjectB'
import { GeldA, Geldarm_draw, Geldarm_init2, Geldarm_udp } from '../geldarm/Geldarm'

export class GlzmA extends GeldA {
  override readonly objectName = 'GlzmA' as const
  revive_type = 1 // 1: use timer, 2: PC not attacking
  eye_hit = false // true if any eye hit on current frame
  SND_HIT_EYE: SoundId = 0 as SoundId
  SND_HIT_BDY: SoundId = 0 as SoundId
  EYE_OPEN_SPR = 'spr_Eye_2a'
  EYE_CLSD_SPR = 'spr_Eye_2b'
  EYE_W = 0
  EYE_H = 0
  EYE_SPR_XOFF = 0
  EYE_SPR_YOFF = 0
  EYE_CNT = 3
  EYES_PAD = 0
  EYE_SPACING = 0
  EYE_BASE_Y = 0
  REVIVE_DELAY_0 = 0xff
  REVIVE_DELAY_1 = 0x30
  DUR_EYE_REMOVE_SPACING = 8
  DELAY_EXPL = 0
  dl_tmr_revive = new DsList<number>()
  dl_eye_spr = new DsList<string | 0>()
  dl_pal_idx = new DsList<number>()
  dl_xx = new DsList<number>()
  dl_yy = new DsList<number>()
  dl_xscale = new DsList<number>()
  dl_hb_x = new DsList<number>()
  dl_hb_y = new DsList<number>()
  canDraw_eye_hb = true
  EYE_HB_COLOR = 0x0000ff // c_red ($BBGGRR)
  EYE_HB_W = 4
  EYE_HB_H = 4
  EYE_HB_XOFF = 1 // off from the center
  EYE_HB_YOFF = 0
  eye_hb_xoff = 1
  eye_hb_yoff = 0
  BODY_XOFF = 1
  BODY_YOFF = 4
  BODY_W = 0
  BODY_H = 0
}

/** `Gellzem_init2()` */
export function Gellzem_init2(self: GlzmA): void {
  Geldarm_init2(self)
  self.revive_type = 1
  self.eye_hit = false
  self.SND_HIT_EYE = get_audio_theme_track(dk_StrikeEnemy)
  // TODO (ZALiA): Find proper sound for hitting body
  self.SND_HIT_BDY = get_audio_theme_track(dk_HitShield)
  self.SEGMENT_SPR = 'spr_Geldarm2_WRB'
  self.HEAD_SPR = 'spr_Geldarm1_WRB'
  self.EYE_OPEN_SPR = 'spr_Eye_2a'
  self.EYE_CLSD_SPR = 'spr_Eye_2b'
  const eye = spriteInfo(self.EYE_OPEN_SPR)
  self.EYE_W = eye.width
  self.EYE_H = eye.height
  self.EYE_SPR_XOFF = eye.originX
  self.EYE_SPR_YOFF = eye.originY
  self.EYE_CNT = 3 + (self.ver === 2 ? 1 : 0) // 3,4. (4 was pretty difficult)
  self.EYES_PAD = 0
  self.EYE_SPACING = self.EYE_H + self.EYES_PAD
  self.EYE_BASE_Y = self.GROUND_Y - (0x3 << 3)
  self.EYE_BASE_Y -= (self.EYE_CNT - 1) * self.EYE_SPACING
  self.REVIVE_DELAY_0 = 0xff
  self.REVIVE_DELAY_1 = 0x30
  self.DUR_EYE_REMOVE_SPACING = 8
  self.DELAY_EXPL = self.EYE_CNT * self.DUR_EYE_REMOVE_SPACING
  self.dl_tmr_revive = new DsList<number>()
  self.dl_eye_spr = new DsList<string | 0>()
  self.dl_pal_idx = new DsList<number>()
  self.dl_xx = new DsList<number>()
  self.dl_yy = new DsList<number>()
  self.dl_xscale = new DsList<number>()
  self.dl_hb_x = new DsList<number>()
  self.dl_hb_y = new DsList<number>()
  for (let _i = self.EYE_CNT - 1; _i >= 0; _i--) {
    self.dl_tmr_revive.set(_i, 0)
    self.dl_eye_spr.set(_i, self.EYE_OPEN_SPR)
    self.dl_pal_idx.set(_i, self.palidx_def)
    self.dl_xx.set(_i, 0)
    self.dl_yy.set(_i, 0)
    self.dl_xscale.set(_i, sign_(~_i & 1) * self.xScale)
    self.dl_hb_x.set(_i, 0)
    self.dl_hb_y.set(_i, 0)
  }
  self.canDraw_eye_hb = true
  self.EYE_HB_W = 4
  self.EYE_HB_H = 4
  self.EYE_HB_XOFF = 1
  self.EYE_HB_YOFF = (self.EYE_H - self.EYE_HB_H) >> 1
  self.eye_hb_xoff = self.EYE_HB_XOFF
  self.eye_hb_yoff = self.EYE_HB_YOFF
  self.canDrawScrunchHB = false
  self.BodyHB_IDX = BODY_HB_IDX_DYNAMIC
  self.BodyHB_idx = self.BodyHB_IDX
  self.BODY_XOFF = 1
  self.BODY_YOFF = 4
  self.BODY_W = self.ww - (self.BODY_XOFF << 1)
  self.BODY_H = self.GROUND_Y - self.MIN_Y - (self.BODY_YOFF << 1)
  self.BodyHB_xoff = self.BODY_XOFF
  self.BodyHB_yoff = self.BODY_YOFF
  self.BodyHB_w = self.BODY_W
  self.BodyHB_h = self.BODY_H
  self.BodyHB_xl = self.x - (self.BodyHB_w >> 1)
  self.BodyHB_xr = self.BodyHB_xl + self.BodyHB_w
  self.BodyHB_yt = self.MIN_Y + self.BODY_YOFF
  self.BodyHB_yb = self.BodyHB_yt + self.BodyHB_h
}

/** `Gellzem_end()` — ds_list cleanup; lists are garbage collected here. */
export function Gellzem_end(_self: GlzmA): void {}

/** `Gellzem_update()` */
export function Gellzem_update(self: GlzmA): void {
  const P = pc()
  update_EF11(self)
  if (gmBool(self.stun_timer)) {
    // During eye removal sequence, a strike sound will occur on each eye removal
    if (inRange(self.stun_timer, 1, self.DELAY_EXPL) && !(self.stun_timer & 0x7)) {
      aud_play_sound(get_audio_theme_track(dk_StrikeEnemy)) // play snd on each frame an eye is removed
    }
    if (self.stun_timer === 1) damage_gob(self, Math.max(self.hp, 0), false)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  let _alive_cnt = self.EYE_CNT
  for (let _i = 0; _i < self.EYE_CNT; _i++) _alive_cnt -= (self.dl_tmr_revive.get(_i) ?? 0) > 0 ? 1 : 0
  if (!_alive_cnt) {
    // Delay death to play extra pre death animation
    self.stun_timer = self.DELAY_EXPL // dur of eye removal sequence
    self.stun_timer += 0x21 // delay  eye removal sequence
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  self.eye_hit = false
  for (let _i = 0; _i < self.EYE_CNT; _i++) {
    self.dl_xscale.set(_i, sign_(~_i & 1))
    const xs = self.dl_xscale.get(_i) as number
    let xx = self.x - (self.EYE_W >> 1)
    xx += xs * (self.xScale === xs ? 1 : 0)
    self.dl_xx.set(_i, xx)
    self.dl_yy.set(_i, self.EYE_BASE_Y + self.EYE_SPACING * _i)
    if (gmBool(xs)) self.dl_hb_x.set(_i, xx - self.EYE_HB_XOFF + (self.EYE_W - self.EYE_HB_W))
    else self.dl_hb_x.set(_i, xx + self.EYE_HB_XOFF)
    self.dl_hb_y.set(_i, (self.dl_yy.get(_i) as number) + self.EYE_HB_YOFF)
    if (
      !gmBool(self.dl_tmr_revive.get(_i)) &&
      collide_pc_sword(
        self.dl_hb_x.get(_i) as number,
        self.dl_hb_y.get(_i) as number,
        self.EYE_HB_W,
        self.EYE_HB_H,
      )
    ) {
      self.eye_hit = true
      if (self.revive_type === 2) self.dl_tmr_revive.set(_i, self.REVIVE_DELAY_0)
      else self.dl_tmr_revive.set(_i, self.REVIVE_DELAY_1)
      if (P.behavior === P.behavior_STAB_DOWN) PC_set_bounce()
      aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
    }
    if (gmBool(self.dl_tmr_revive.get(_i)))
      self.dl_tmr_revive.set(_i, (self.dl_tmr_revive.get(_i) as number) - 1)
    if (self.revive_type === 2 && !gmBool(P.attack_phase)) self.dl_tmr_revive.set(_i, 0) // Must hit all eyes with 1 sword strike
  }
  // update_body_hb_1a();
  self.BodyHB_can_draw = true
  if (collide_pc_sword(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h)) {
    if (P.behavior === P.behavior_STAB_DOWN) PC_set_bounce()
    else pushback_pc_and_go(self, 0x8, 0) // Won't push GO
    if (!self.eye_hit) {
      if (!Audio.audio_is_playing(self.SND_HIT_EYE) && !Audio.audio_is_playing(self.SND_HIT_BDY)) {
        aud_play_sound(self.SND_HIT_BDY)
      }
    }
  } else {
    GOB_body_collide_pc_body_1a(self)
    if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  }
}

/** `Gellzem_udp()` */
export function Gellzem_udp(self: GlzmA): void {
  Geldarm_udp(self)
  const g = gp()
  for (let _i = 0; _i < self.EYE_CNT; _i++) {
    if (self.state !== self.state_NORMAL) self.dl_eye_spr.set(_i, 0)
    else if (gmBool(self.dl_tmr_revive.get(_i))) self.dl_eye_spr.set(_i, self.EYE_CLSD_SPR)
    else self.dl_eye_spr.set(_i, self.EYE_OPEN_SPR)
    if (gmBool(self.stun_timer)) self.dl_pal_idx.set(_i, GO_update_pal_flash(g.counter1, 2))
    else self.dl_pal_idx.set(_i, self.palidx_def)
  }
  if (self.state === self.state_NORMAL && inRange(self.stun_timer, 1, self.DELAY_EXPL)) {
    // dur of eye removal sequence
    let _time = 0
    for (let _i = 0; _i < self.EYE_CNT; _i++) {
      _time = _i << 3 // last frame this eye can draw
      if (inRange(self.stun_timer, _time, self.DELAY_EXPL)) {
        if (inRange(self.stun_timer, _time + 4, self.DELAY_EXPL)) {
          self.dl_eye_spr.set(_i, self.EYE_CLSD_SPR)
        } else {
          self.dl_eye_spr.set(_i, self.EYE_OPEN_SPR) // Open for 4 frames before stops drawing
          self.dl_pal_idx.set(_i, self.palidx_def) // Easier to see it opened
        }
      } else self.dl_eye_spr.set(_i, 0)
    }
  }
}

/** `Gellzem_draw()` */
export function Gellzem_draw(self: GlzmA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  Geldarm_draw(self)
  drawState.depth = self.depth
  for (let _i = 0; _i < self.EYE_CNT; _i++) {
    const spr = self.dl_eye_spr.get(_i)
    if (!spr) continue
    draw_sprite_(
      spr,
      0,
      (self.dl_xx.get(_i) as number) + self.EYE_SPR_XOFF,
      (self.dl_yy.get(_i) as number) + self.EYE_SPR_YOFF,
      self.dl_pal_idx.get(_i) as number,
      self.dl_xscale.get(_i) as number,
    )
  }
  pal_swap_reset()
  const g = gp()
  if (gmBool(g.DevTools_state) && gmBool(self.state) && g.can_draw_hb && self.canDraw_eye_hb) {
    for (let _i = 0; _i < self.EYE_CNT; _i++) {
      if (gmBool(self.dl_tmr_revive.get(_i))) continue
      draw_rect_(
        self.EYE_HB_COLOR,
        self.dl_hb_x.get(_i) as number,
        self.dl_hb_y.get(_i) as number,
        self.EYE_HB_W,
        self.EYE_HB_H,
        1,
        true,
      )
    }
  }
}

export function registerGellzem(): void {
  registerObject('GlzmA', GlzmA)
  registerScripts({ Gellzem_init2, Gellzem_end, Gellzem_update, Gellzem_udp, Gellzem_draw })
}
registerGellzem()
