// Ported from ZALiA scripts/update_game_timers.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively

import { gmBool } from '../../nes/math8'
import { G, g } from '../../runtime/world'
import { ds_grid_width } from './gm'

/** GML: update_game_timers() */
export function update_game_timers() {
  // C169
  g.timer_b-- // 0500
  if (g.timer_b < 0) {
    g.timer_b = g.timer_b_DURATION1 // timer_b_DURATION1 = $14
    // C177.  Update timers 0519-050E.
    // 0512
    if (gmBool(g.timer_b1)) {
      g.timer_b1--
    }
    // 0518
    if (gmBool(G.pc.iframes_timer)) {
      G.pc.iframes_timer--
    }
    // 0516
    if (gmBool(G.OVERWORLD.enc_spawn_timer)) {
      G.OVERWORLD.enc_spawn_timer--
    }
    if (g.room_type === 'C') {
      for (let _i = ds_grid_width(G.OVERWORLD.dg_enc_inst) - 1; _i >= 0; _i--) {
        // enc obj timers
        if (gmBool(G.OVERWORLD.dg_enc_inst.get(_i, G.OVERWORLD.ENC_INST_TMR_IDX))) {
          G.OVERWORLD.dg_enc_inst.set(
            _i,
            G.OVERWORLD.ENC_INST_TMR_IDX,
            G.OVERWORLD.dg_enc_inst.get(_i, G.OVERWORLD.ENC_INST_TMR_IDX) - 1,
          ) /* GML2TS-TODO: map-- used as a value */
        }
      }
    }
  }
  // 0501-050D timers
  // ----------------------------------------------------
  // 050D
  if (gmBool(g.boss_stun_timer)) {
    g.boss_stun_timer--
  }
  // 050C PC stun timer
  if (gmBool(G.pc.stun_timer)) {
    G.pc.stun_timer--
  }
  // 050A PC attack timer
  if (gmBool(G.pc.attack_timer)) {
    G.pc.attack_timer--
  }
  // 0503 Delay control of PC when entering a room
  if (gmBool(g.EnterRoom_control_timer)) {
    g.EnterRoom_control_timer--
  }
  // 0502
  if (gmBool(g.control1_timer)) {
    g.control1_timer--
  }
  // 0501 walkIndexTimer
  if (gmBool(g.WalkAnim_timer)) {
    g.WalkAnim_timer--
  }
  g.counter1 = (g.counter1 + 1) & 0xff // 0012
  g.timer_a1 = (g.timer_a1 + 1) & 0xffffffff
  g.timer_a2 += +!(g.counter1 & 0xff) // Every full    cycle
  g.timer_a3 += +!(g.counter1 & 0x3f) // Every quarter cycle
}
