/** GML: update_TitleScreen(self) */
export function update_TitleScreen(self: TitleScreen) {
  let _RESET: any, _count: any

  if (gmb(input.Pause_pressed)) {
    room_goto_('rmB_FileSelect')
    g.MaskWideView_w = 0
    g.MaskWideView = 0
  }
  // ---------------------------------------------------------------------
  _RESET =
    Audio.timing_sound_position_curr === 0 ||
    Audio.timing_sound_position_curr < Audio.timing_sound_position_prev
  _RESET = gmb(_RESET) && audio_is_playing('snd_Default_Title_no_volume') // GML: _RESET &= audio_is_playing(...)
  //
  if (gmb(_RESET)) {
    self.cycle_num++
  }
  if (gmb(_RESET)) {
    self.counter = self.COUNTER_START // COUNTER_START = -1
  }
  self.counter++
  // counter starts at $100 in TitleScreen_Create
  _count = self.counter >> 8
  // TITLE ---------------------------------------
  // every 4 frames
  if (!gmb(self.counter & 0x03)) {
    if (gmb(_RESET)) {
      self.title_y = self.TITLE_Y_RESET
    }
    // story scroll. SCROLL2_DELAY=8
    // title reveal scroll
    // FIDELITY (NES, not ZALiA): ZALiA rests the logo at `title_y > 0`, i.e. window row -16. Ours is
    // pixel-identical to the 256x240 capture's — the same row widths, the same 104..155 / 64..194 /
    // 86..190 spans — but 24 rows above it: the original's "ZELDA II" is on scanline 56 and "LINK" ends on
    // 111, ZALiA's on 32 and 87. Resting the scroll 24 lower puts it exactly on the original's rows, and
    // the story crawl keeps its spacing because `story_y` is `title_y + STORY_YOFF`.
    if (_count >= self.SCROLL2_DELAY || self.title_y > NES_TITLE_REST_Y) {
      self.title_y--
    }
  }
  // STORY -----------------------------------------------------
  self.story_y = self.title_y + self.STORY_YOFF
  // FG --------------------------------------------------------
  // COVER -------------------------------------------------------
  if (g.counter1 >= 4) {
    self.cover_can_draw = false
  }
  if (gmb(self.cover_can_draw)) {
    if (g.surf) g.surf.draw_clear_color = p.C_BLK1 // Surface object is adapter-side (may be NOONE)
  }
  // ********** End Step ***********
  // SHOOTING STAR ---------------------------------------
  if (self.cycle_num > 1 && self.counter === self.SSTAR_VISIBLE_DELAY) {
    self.sstar_moveNum = 0
  }
  self.sstar_can_draw = +(self.sstar_moveNum < self.SSTAR_MAX_MOVES)
  if (_count === 2 && !gmb(self.counter & 0x03) && self.sstar_moveNum < self.SSTAR_MAX_MOVES) {
    self.sstar_moveNum++
  }
  /*
if(!(g.timer0&$7F)){
var _str  =   'viewXL() '+string(viewXL()) + ', viewYT() '+string(viewYT());
    _str += ', viewW() ' +string(viewW())  + ', viewH() ' +string(viewH());
    _str += ', room_width ' +string(room_width) + ', room_height '+string(room_height);
    _str += ', g.rm_w ' +string(g.rm_w) + ', g.rm_h ' +string(g.rm_h);
    _str += ', x '+string(x)+', y '+string(y);

}
*/
  // viewXL() 16, viewYT() -17, viewW() 480, viewH() 270, room_width 512, room_height 256, g.rm_w 512, g.rm_h 256, x 112, y 46
  // viewXL()  0, viewYT()   0, viewW() 480, viewH() 270, room_width 512, room_height 256, g.rm_w 512, g.rm_h 256, x 112, y 46
}

