/**
 * Access to ZALiA's decoded data caches (`generated/caches/*.json`, produced by `pnpm tool caches`).
 * Values are exactly the string-keyed maps ZALiA reads at runtime (`g.dm_rm[?key]` etc.).
 */
export type CacheValue = number | string | CacheGridJson | CacheValue[] | { [k: string]: CacheValue }
export interface CacheGridJson {
  width: number
  height: number
  cells: CacheValue[][]
}
export type CacheMapJson = Record<string, CacheValue>

/** Entry names, grouped by the ZALiA file they came from. */
export const CACHE_NAMES = {
  sceneData: [
    'scene_data',
    'spawn_data',
    'dungeon_data',
    'town_data',
    'pbags_data',
    '1up_data',
    'keys_data',
    'jars_data',
    'scene_rando_data',
    'rando_hint_data',
    'rando_enemy_data',
    'palette_data',
    'audio_data',
    '_Tile_File_Dimensions',
    'dl_MapItem_ITEM_IDS',
    'dg_dngn_map_1',
    'dg_dngn_map_2',
    'dg_dngn_map_3',
    'dg_dngn_map_4',
    'dg_dngn_map_5',
    'dg_dngn_map_6',
    'dg_dngn_map_7',
    'dg_dngn_map_8',
  ],
  sceneWallData: ['scene_wall_data'],
  overworldData: [
    'dg_tsrc_def',
    'dg_solid_def',
    'dg_area',
    'dg_AreaNames',
    'dg_boulders',
    'dg_ChangeTiles_Boots',
    'HiddenExitIndicator_dg',
    '_Map0',
  ],
  tilesetData: ['TilesetData01'],
} as const

export type CacheName = (typeof CACHE_NAMES)[keyof typeof CACHE_NAMES][number]
export const ALL_CACHE_NAMES: readonly CacheName[] = Object.values(CACHE_NAMES).flat()

export interface Caches {
  map(name: CacheName): CacheMapJson
  grid(name: CacheName): CacheGridJson
  list(name: CacheName): CacheValue[]
}

/** Build a `Caches` view over already-loaded JSON (any source: fs, fetch, bundler import). */
export function cachesFrom(entries: Record<string, unknown>): Caches {
  const need = (name: CacheName) => {
    const v = entries[name]
    if (v === undefined) throw new Error(`cache ${name} not loaded`)
    return v
  }
  return {
    map: (name) => need(name) as CacheMapJson,
    grid: (name) => need(name) as CacheGridJson,
    list: (name) => need(name) as CacheValue[],
  }
}

/** Load with any async text reader, e.g. `(n) => fetch(`assets/data/${n}.json`).then(r => r.text())`. */
export async function loadCaches(readText: (name: CacheName) => Promise<string>): Promise<Caches> {
  const entries: Record<string, unknown> = {}
  await Promise.all(ALL_CACHE_NAMES.map(async (n) => (entries[n] = JSON.parse(await readText(n)))))
  return cachesFrom(entries)
}
