/** `Barrier_init2()` */
export function Barrier_init2(self: BarrA): void {
  self.can_draw_self = false
  self.can_draw_self_exception = true
  self.DEPTH1 = DEPTH_ENEMY
  self.DEPTH2 = DEPTH_BG6 + 1
  GO_depth_init(self, self.DEPTH1)
  self.DRAW_YOFF = 0x10
  self.dl_sprites?.set(1, 'spr_Barrier_1b')
  self.dl_sprites?.set(0, 'spr_Barrier_1a')
  self.dg_PI_SEQ_IDX = 0x08
  GO_init_palidx(self, p.dg_PI_SEQ.get(self.dg_PI_SEQ_IDX, 0) as number)
  p.dg_PI_SEQ.set(
    self.dg_PI_SEQ_IDX,
    2,
    add_pi_permut(p.dg_PI_SEQ.get(self.dg_PI_SEQ_IDX, 0) as number, 'WBRGYKMC', 'Barrier'),
  )
  self.Anim_VER = 1 // 0: OG, 1: Vertical Movement 1, 2: Vertical Movement 2
  self.Anim_yoff = 0
  self.facing_dir = -1
  self.CLMS_DEF = 0xc // Horizontal. 8x8 tile size
  self.clms = self.CLMS_DEF // current draw count horizontal
  self.ROWS_DEF = 0xe // Vertical. 8x8 tile size
  self.GROUND_Y = get_ground_y(self.xl - (0x2 << 3), self.yt + (0x2 << 3), 1, self.yt + (self.ROWS_DEF << 3))
  self.ROWS_DEF = (self.GROUND_Y - self.yt) >> 3 // Vertical. 8x8 tile size
  self.rows = self.ROWS_DEF // current draw count vertical
  self.draw_rows = self.rows
  self.draw_clms = self.clms
  self.sub_state = 0 // 00AF[eIndex]
  self.counter = 0 // 0071[eIndex]
  const _PAL = color_str(p.C_RED3) + color_str(p.C_VLT2) // the colors used by Barrier
  const _LEN = _PAL.length
  let _pos = self.palidx_def * G.PAL_CHAR_PER_PAL
  _pos += G.PAL_CHAR_PER_PAL - _LEN
  _pos++ // +1 bc string
  change_pal(strReplaceAt(p.pal_rm_new, _pos, _LEN, _PAL))
  if (g.mod_BARRIER_LOOK === 1) {
    self.DRAW_YOFF = 0
    set_xlyt(self, self.spawn_xl, self.spawn_yt)
    self.ROWS_DEF = 0x0c
    self.GROUND_Y = get_ground_y(
      self.xl - (0x2 << 3),
      self.yt + (0x2 << 3),
      1,
      self.yt + (self.ROWS_DEF << 3),
    )
    self.ROWS_DEF = (self.GROUND_Y - self.yt) >> 3
    self.barrier_state_IDLE = 0
    self.barrier_state_GREETING = 1
    self.barrier_state_RAISING = 2
    self.barrier_state_COMPLETE = 3
    self.BARRIER_COUNT = G.DungeonCrystals_COUNT
    self.dg_barrier_W = self.BARRIER_COUNT + 1 // ++: To reserve index 0 for general info
    self.dg_barrier = new DsGrid<number>(self.dg_barrier_W, 6, 0)
    const dg = self.dg_barrier
    dg.set(0, 0, 0) // raising/raised count. 0:Idle, 1:Crystals' greeting, 2:Raising, 3:Raise complete
    for (let _i = 1; _i < self.dg_barrier_W; _i++) {
      dg.set(_i, 0, val(f.dm_quests.get(g.rm_name + STR_Barrier + hexStr(_i) + STR_State)) as number)
      dg.set(0, 0, (dg.get(0, 0) as number) + (dg.get(_i, 0) === self.barrier_state_COMPLETE ? 1 : 0)) // 3: Raise complete
      dg.set(_i, 2, self.ROWS_DEF) // current num of rows left.
      dg.set(_i, 3, 0) // barrier can draw
    }
    if (!G.RandoDungeonRequirement_ADJUST_IN_GAME) {
      const _CRYSTALS_REQUIREMENT_COUNT = val(
        G.dm_save_file_settings.get(STR_Crystal + STR_Required + STR_Count),
        G.RandoDungeonRequirement_MAX,
      ) as number
      if (
        _CRYSTALS_REQUIREMENT_COUNT < G.RandoDungeonRequirement_MAX && // if dont have to place all the crystals
        _CRYSTALS_REQUIREMENT_COUNT <= bitCount(f.crystals) && // if have placed enough crystals
        gmBool(dg.get(0, 0)) && // if any barriers have been raised yet
        (dg.get(0, 0) as number) >= bitCount(f.crystals) // all that can be raised, have been raised
      ) {
        dg.set(0, 0, 0)
        for (let _i = 1; _i < self.dg_barrier_W; _i++) {
          dg.set(0, 0, (dg.get(0, 0) as number) + 1)
          dg.set(_i, 0, self.barrier_state_COMPLETE)
          f.dm_quests.set(g.rm_name + STR_Barrier + hexStr(_i) + STR_State, self.barrier_state_COMPLETE)
        }
      }
    }
    self.CRYSTAL_SPR_1A = 'spr_Crystal_1a' // 1a: Placing-Crystal spr. 10 pixel high graphic
    self.CRYSTAL_SPR_1B = 'spr_Crystal_1b' // 1b: Empty-Crystal ver of 1a.
    self.CRYSTAL_SPR_W = sprite_get_width(self.CRYSTAL_SPR_1A)
    self.SND_CRYSTAL = get_audio_theme_track(STR_Sword + STR_Beam)
    self.sub_state = self.SUB_STATE_IDLE
    self.BARRIER_W = 0x02 << 3
    self.BARRIER_H = self.ROWS_DEF << 3
    self.BARRIER_PAD = 0x02 << 3 // Dist between each barrier.
    self.BARRIER_AREA_W = self.BARRIER_W * self.BARRIER_COUNT + self.BARRIER_PAD * (self.BARRIER_COUNT - 1)
    self.BARRIER_AREA_H = self.BARRIER_H
    Barrier_update_2a(self) // set dg_barrier[#0,1] (curr barrier num being raised)
  }
  self.scr_inst_end = Barrier_end as (s: unknown) => void
}

/**
 * FIXED (no counterpart in ZALiA): both barrier looks take `g.pc_lock = PC_LOCK_ALL` when the player walks
 * up with the crystals placed and give it back only from the raising state that follows — `Barrier_update_1`
 * when `rows` runs out, `Barrier_update_2` when the last barrier completes. That release happens only while
 * this instance is still running. Nothing in the shipped game destroys a `BarrA` in that window (it does not
 * run `GOB_update_2` and never sets `state = 0`), but if anything ever did, the player would be left holding
 * `PC_LOCK_ALL` with no one to clear it — a total freeze with no recovery, since a locked player cannot walk
 * to an exit to reach `PC_Room_Start`. Hand the lock back when the instance ends, as the restore fairy does.
 */
export function Barrier_end(self: BarrA): void {
  const raising = g.mod_BARRIER_LOOK === 1 ? self.SUB_STATE_RAISING : 1
  if (self.sub_state === raising) g.pc_lock = 0
}

/** `Barrier_update()` */
export function Barrier_update(self: BarrA): void {
  switch (g.mod_BARRIER_LOOK) {
    case 0:
      Barrier_update_1(self)
      break
    case 1:
      Barrier_update_2(self)
      break
  }
}

/** `Barrier_update_1()` — A234 (OG look) */
export function Barrier_update_1(self: BarrA): void {
  const P = pc()
  switch (self.sub_state) {
    case 0: {
      if (wINw(self.xl, self.BodyHB_w, viewXL(), viewW())) {
        // A238
        const _REMAINING = G.DungeonCrystals_COUNT - bitCount(f.crystals)
        if (!_REMAINING) {
          const _DIST = Math.abs(self.xl + (self.BodyHB_w >> 1) - P.x)
          if (_DIST < (self.BodyHB_w >> 1) + 0x40) {
            // A249
            g.pc_lock = PC_LOCK_ALL // Lock all
            PC_set_behavior(P.behavior_IDLE)
            self.counter = 0 // 0071[eIndex]
            self.sub_state = 1 // 00AF[eIndex]
            aud_play_sound(get_audio_theme_track(dk_RaiseBarrier))
          }
        }
        // A25F
        if (!P.is_dead) {
          // MOD. So that PC can collide w/enemies: iframes_timer only zeroed if (cs&CS_BD1).
          GOB_body_collide_pc_body_1a(self) // A269: JSR E4D9
          if (self.cs & CS_BD1) P.iframes_timer = 0 // A26C: JSR D6C1
          if (self.cs & CS_BD1) enemy_collide_pc_body(self)
          // A26F
          if (self.cs & CS_BD1 && (pc_is_fairy() || pc_is_cucco())) P.is_dead = 1
        }
      }
      // A27C
      Barrier_udp(self)
      break
    }
    case 1: {
      // RAISING. A2A7, A2B7
      if (!self.rows) {
        g.pc_lock = 0
        return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
      }
      // A2C4
      self.counter = (self.counter + 1) & 0xff // 0071[eIndex]
      if (!(self.counter & 0x3)) {
        // A303
        self.rows--
        Barrier_udp(self)
      }
      break
    }
  }
}

/** `Barrier_update_2()` — mod_BARRIER_LOOK 1: per-crystal barriers */
export function Barrier_update_2(self: BarrA): void {
  const P = pc()
  const dg = self.dg_barrier
  self.Anim_yoff = (g.counter1 >> 1) & 0x7
  if (
    !P.is_dead &&
    !(P.ocs & 0x4) &&
    self.state === self.state_NORMAL &&
    GO_can_collide_this_frame(self.update_idx)
  ) {
    if ((dg.get(0, 0) as number) < self.BARRIER_COUNT) {
      // 0: raised count. A269: JSR E4D9
      for (let _i = 0; _i < self.BARRIER_COUNT; _i++) {
        if (gmBool(dg.get(_i + 1, 0))) continue // Already raised
        self.BodyHB_w = self.BARRIER_W
        self.BodyHB_h = self.BARRIER_H
        self.BodyHB_xl = self.spawn_xl + (self.BARRIER_W + self.BARRIER_PAD) * _i
        self.BodyHB_xr = self.BodyHB_xl + self.BodyHB_w
        self.BodyHB_yt = self.spawn_yt
        self.BodyHB_yb = self.BodyHB_yt + self.BodyHB_h
        if (collide_pc_body(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h)) self.cs |= CS_BD1
        else self.cs &= ~CS_BD1
        self.BodyHB_can_draw = true
        // A26C: JSR D6C1
        if (self.cs & CS_BD1) {
          P.iframes_timer = 0 // So the following scripts will run.
          enemy_collide_pc_body(self)
          // PC damage bounce AWAY from barrier.
          P.hspd = (abs8b(P.hspd) * self.facing_dir) & 0xff
          break
        }
      }
      // A26F
      if (self.cs & CS_BD1) {
        if (pc_is_cucco() || pc_is_fairy()) {
          P.is_dead = 1
          return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
        }
      }
    }
  }
  if (
    self.sub_state === self.SUB_STATE_IDLE ||
    (self.sub_state === self.SUB_STATE_RAISING && !(self.counter & 0x3))
  ) {
    for (let _i = 1; _i < self.dg_barrier_W; _i++) dg.set(_i, 3, 1) // barrier can draw
  }
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE: {
      if (self.timer) break
      if (!rectInViewAll(self.spawn_xl, self.spawn_yt, self.BARRIER_AREA_W, self.BARRIER_H)) break
      let _DIST = Math.abs(self.xl + (self.BARRIER_AREA_W >> 1) - P.x)
      _DIST -= self.BARRIER_AREA_W >> 1
      if (_DIST >= 0x30 || P.y < self.yt || P.y >= self.yt + self.BARRIER_H) break
      dg.set(0, 0, 0) // 0: raised count
      for (let _i = 1; _i < self.dg_barrier_W; _i++)
        dg.set(0, 0, (dg.get(0, 0) as number) + (dg.get(_i, 0) === 3 ? 1 : 0)) // 3: raise complete
      if (
        (dg.get(0, 0) as number) >= bitCount(f.crystals) &&
        gmBool(
          val(
            G.dm_save_file_settings.get(STR_Crystal + STR_Required + STR_Count),
            G.RandoDungeonRequirement_MAX,
          ) as number,
        )
      ) {
        break
      }
      // A249
      dg.set(0, 1, 0) // 0:Will trigger next barrier raise. dg_barrier[#0,1] (curr barrier num being raised)
      self.counter = 0
      g.pc_lock = PC_LOCK_ALL // Lock all
      self.timer = 0xc // Delay SUB_STATE_RAISING
      self.sub_state = self.SUB_STATE_RAISING
      break
    }
    case self.SUB_STATE_RAISING: {
      let _num = dg.get(0, 1) as number // dg_barrier[#0,1] (curr barrier num being raised)
      if (_num) {
        const _STATE = dg.get(_num, 0)
        switch (_STATE) {
          case 1: {
            // 1:Crystals' greeting
            if (self.timer && audio_is_playing(self.SND_CRYSTAL)) break // Whichever ends first progresses the barrier to its next state.
            if (!self.Anim_VER || !self.Anim_yoff) {
              aud_play_sound(get_audio_theme_track(dk_RaiseBarrier))
              dg.set(_num, 0, self.barrier_state_RAISING) // set to 2:Raising
            }
            break
          }
          case 2: {
            // 2:Raising
            if (!gmBool(dg.get(_num, 2))) {
              // if no more rows (fully raised)
              self.counter = 0
              dg.set(0, 1, 0) // 0:Will trigger next barrier raise
              dg.set(_num, 0, self.barrier_state_COMPLETE) // 3: Raise Complete
              break
            }
            // A2C4
            dg.set(_num, 3, 0) // barrier can draw
            self.counter++
            if (!(self.counter & 0x3)) {
              // A303
              dg.set(_num, 3, 1) // barrier can draw
              dg.set(_num, 2, (dg.get(_num, 2) as number) - 1) // decrement rows
            }
            break
          }
        }
      }
      _num = dg.get(0, 1) as number
      if (!_num) {
        // No barrier currently set to raise
        Barrier_update_2a(self) // set dg_barrier[#0,1] (curr barrier num being raised)
        _num = dg.get(0, 1) as number
        if (_num) {
          dg.set(_num, 0, self.barrier_state_GREETING) // 1: Crystals' greeting.  TRIGGERS RAISE.
          aud_play_sound('snd_Sword_Beam_1a' as never, 0xff, false, 0.8) // a little louder than normal(.6) to hear it over other sounds
          self.timer = 0x24
        } else {
          g.pc_lock = 0 // barrier num currently raising(Couldn't find any that qualify)
        }
      }
      break
    }
    case self.SUB_STATE_COMPLETE:
      if (self.timer) break
      g.pc_lock = 0
      break
  }
  self.can_draw_self = true
  if (self.sub_state === self.SUB_STATE_RAISING) {
    dg.set(0, 0, 0)
    for (let _i = 1; _i < self.dg_barrier_W; _i++) {
      dg.set(0, 0, (dg.get(0, 0) as number) + Math.sign(dg.get(_i, 0) as number)) // as long as it has started raising
      if (dg.get(_i, 0) === self.barrier_state_COMPLETE) {
        // if it has finished raising
        if (!G.RandoDungeonRequirement_ADJUST_IN_GAME || f.crystals & (0x1 << (_i - 1))) {
          f.dm_quests.set(g.rm_name + STR_Barrier + hexStr(_i) + STR_State, dg.get(_i, 0) as number)
        }
      }
    }
  }
}

/** `Barrier_update_2a()` — Decide next barrier to be raised */
export function Barrier_update_2a(self: BarrA): number {
  const dg = self.dg_barrier
  dg.set(0, 1, 0) // dg_barrier[#0,1]: Current barrier num being raised.
  for (let _i = 1; _i < self.dg_barrier_W; _i++) {
    if (!gmBool(dg.get(_i, 0)) && f.crystals & (0x1 << (_i - 1))) {
      dg.set(0, 1, _i)
      break
    }
  }
  if (
    !gmBool(dg.get(0, 1)) &&
    (dg.get(0, 0) as number) >= bitCount(f.crystals) &&
    (dg.get(0, 0) as number) >=
      (val(
        G.dm_save_file_settings.get(STR_Crystal + STR_Required + STR_Count),
        G.RandoDungeonRequirement_MAX,
      ) as number)
  ) {
    for (let _i = 1; _i < self.dg_barrier_W; _i++) {
      if (!gmBool(dg.get(_i, 0))) {
        dg.set(0, 1, _i)
        break
      }
    }
  }
  return dg.get(0, 1) as number
}

/** `Barrier_udp()` */
export function Barrier_udp(self: BarrA): void {
  self.draw_clms = self.clms
  self.draw_rows = self.rows
  self.can_draw_self = gmBool(self.draw_rows)
  self.palidx_base = self.palidx_def
}

/** `Barrier_draw()` */
export function Barrier_draw(self: BarrA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const dg = self.dg_barrier
  const _IDX = (g.counter1 >> 2) & 0x3
  const d = self.depth
  // BARRIER  -------------------------------------------------------------
  const _Y = self.spawn_yt
  pal_swap_set(p.dg_PI_SEQ.get(self.dg_PI_SEQ_IDX, _IDX) as number)
  for (let _i = 0; _i < self.BARRIER_COUNT; _i++) {
    // each barrier/crystal
    if (!gmBool(dg.get(_i + 1, 3))) continue // barrier can draw
    if (dg.get(_i + 1, 0) === 3) continue // if state is Raise Completed
    dg.set(_i + 1, 3, 0)
    const _c1 = gmBool(self.Anim_VER) && (dg.get(_i + 1, 0) as number) < 2
    const _x1 = self.spawn_xl + (self.BARRIER_W + self.BARRIER_PAD) * _i
    let _rows = dg.get(_i + 1, 2) as number
    _rows += _c1 ? 1 : 0
    for (let _j = _rows - 1; _j >= 0; _j--) {
      // each row
      for (let _k = (self.BARRIER_W >> 3) - 1; _k >= 0; _k--) {
        let _x = _x1
        _x += _k << 3
        let _y = _Y + (_j << 3)
        if (_c1) {
          const _dir = self.Anim_VER === 2 ? sign_(_k & 0x1) : -1
          _y += -((_dir === 1 ? 1 : 0) << 3)
          _y += self.Anim_yoff * _dir
        }
        draw_sprite_at(d, self.dl_sprites?.get(_j & 1) as string, 0, _x, _y, -1, self.xScale, self.yScale)
      }
    }
  }
  pal_swap_reset()
  const _Y1 = self.spawn_yt - 8
  const _Y2 = _Y1 + ((self.ROWS_DEF + 0x02) << 3)
  let _pi = G.PI_BGR2
  for (let _i = 0; _i < self.BARRIER_COUNT; _i++) {
    // each barrier
    let _x = self.spawn_xl + (self.BARRIER_W + self.BARRIER_PAD) * _i
    _x += 8
    draw_sprite_at(d, g.Block2_SPR1, 0, _x, _Y1, _pi)
    draw_sprite_at(d, g.Block2_SPR1, 0, _x, _Y2, _pi)
  }
  // CRYSTALS  -----------------------------------------------------------
  const _Yc = self.spawn_yt - 8
  for (let _i = 0; _i < self.BARRIER_COUNT; _i++) {
    // each barrier/crystal
    let _spr: string
    if (gmBool(dg.get(_i + 1, 0)) && f.crystals & (0x1 << _i))
      _spr = self.CRYSTAL_SPR_1A // if crystal state > 0 and placed in its palace.
    else _spr = self.CRYSTAL_SPR_1B
    if (_spr === self.CRYSTAL_SPR_1A)
      _pi = p.dg_PI_SEQ.get(0x00, (g.counter1 >> 1) & 0x3) as number // changes color every 2 frames
    else _pi = G.PI_GUI1
    let _x = self.spawn_xl + (self.BARRIER_W + self.BARRIER_PAD) * _i
    _x += 8 // horizontal center of this barrier
    draw_sprite_at(d, _spr, 0, _x, _Yc, _pi)
  }
}

// ---------------------------------------------------------------- Barrier2 (Triforce block barrier)
/**
 * `Barrier2_end()` — ZALiA frees the block grid here. FIXED (no counterpart in ZALiA): it also has to hand
 * back the PC lock. See `Barrier_end`: the Triforce barrier holds `PC_LOCK_ALL` from the moment the player
 * raises the Triforce until the last block has crumbled, and only its own update gives it back.
 */
export function Barrier2_end(self: Barrier2): void {
  if (self.sub_state === self.sub_state_ACTIVATING || self.sub_state === self.sub_state_REMOVING)
    g.pc_lock = 0
  self.dg_Blocks = undefined
}

/** `Barrier2_init1()` */
export function Barrier2_init1(self: Barrier2): void {
  GameObjectB_init(self)
  self.can_draw_self_exception = true
}

/** `Barrier2_init2()` */
export function Barrier2_init2(self: Barrier2): void {
  const P = pc()
  self.DRAW_YOFF = 0
  GO_depth_init(self, DEPTH_BG1 + 1)
  GO_init_palidx(self, G.PI_BGR4)
  self.sub_state = self.sub_state_IDLE1
  self.Barrier1_SCENE_NAME = val(g.dm_rm.get(`TriforceBarrier1${dk_SceneName}`), STR_undefined) as string
  self.Blocks_SPR = 'spr_Block_02a'
  self.Blocks_CLMS = 0x07
  self.Blocks_ROWS = 0x03
  self.Blocks_COUNT = self.Blocks_CLMS * self.Blocks_ROWS
  self.Blocks_W = self.Blocks_CLMS << 4
  self.Blocks_XC = self.spawn_xl
  self.Blocks_XL = self.Blocks_XC - (self.Blocks_W >> 1)
  self.Blocks_YT = self.spawn_yt
  self.Blocks_DUR1 = 0x25 // same as DUR_STATE_DED
  self.Blocks_CUE1 = 0x18
  self.Blocks_DUR2 = 0x08
  self.Blocks_CUE2 = self.Blocks_DUR1 - 0x08
  self.Activate_SOUND_THEME = dk_Fanfare
  self.Activate_SOUND = get_audio_theme_track(self.Activate_SOUND_THEME)
  self.Activate_DIST = (0x03 << 3) + (self.Blocks_W >> 1)
  self.PC_HOLD_BEHAVIOR = P.behavior_HOLD_ITEM1
  self.Triforce_PI1 = G.PI_MOB_ORG
  self.Triforce_PI2 = add_pi_permut(self.Triforce_PI1, 'RWBGMYKC', 'triforce flash')
  self.Triforce_pi = self.Triforce_PI1
  self.TriforceSymbol_SPR = 'spr_Triforce_2a'
  self.TriforceSymbol_XC = self.Blocks_XC
  self.TriforceSymbol_YC = self.Blocks_YT - 0x10
  self.TriforceSymbol_YC -= 0x01
  self.dg_Blocks = new DsGrid<number>(self.Blocks_COUNT, 6, 0)
  if (gmBool(val(f.dm_quests.get(self.Barrier1_SCENE_NAME + STR_Barrier + STR_State)) as number)) {
    self.sub_state = self.sub_state_IDLE2
  } else {
    setBarrier2Solids(self, TID_SOLID1)
    for (let _i = 0; _i < self.Blocks_COUNT; _i++) {
      self.dg_Blocks.set(_i, 0, 1) // state
      self.dg_Blocks.set(_i, 1, 0) // timer
      self.dg_Blocks.set(_i, 2, self.Blocks_XL + ((_i % self.Blocks_CLMS) << 4) + 8)
      self.dg_Blocks.set(_i, 3, self.Blocks_YT + (Math.trunc(_i / self.Blocks_CLMS) << 4) + 8)
    }
  }
}

function setBarrier2Solids(self: Barrier2, tid: number): void {
  const _CLM = self.Blocks_XL >> 3
  const _ROW = self.Blocks_YT >> 3
  const _clms = self.Blocks_CLMS << 1
  const _rows = self.Blocks_ROWS << 1
  for (let _i = _clms * _rows - 1; _i >= 0; _i--) {
    const _clm = _CLM + (_i % _clms)
    const _row = _ROW + Math.trunc(_i / _clms)
    G.dg_solid.set(_clm, _row, tid)
  }
}

/** `Barrier2_update()` */
export function Barrier2_update(self: Barrier2): void {
  const P = pc()
  const dg = self.dg_Blocks as DsGrid<number>
  Barrier2_udp(self)
  switch (self.sub_state) {
    case self.sub_state_IDLE1: {
      if (self.timer) break
      if (f.quest_num === 1) break
      if (Math.abs(P.x - self.Blocks_XC) <= self.Activate_DIST && !gmBool(P.ogr)) {
        g.pc_lock = PC_LOCK_ALL
        // Holding Triforce restores hp/mp
        g.StatRestore_timer_mp = get_stat_max(STR_Magic)
        g.StatRestore_timer_hp = get_stat_max(STR_Heart)
        audio_group_stop_all('audiogroup_mus')
        Audio.can_play_mus_rm_body = false
        Audio.can_play_boss_music = false
        aud_play_sound(self.Activate_SOUND as never, -1, false, -1, self.Activate_SOUND_THEME) // Activate_SND: Audio.MUS_GET_ITEM1
        self.timer = round(audio_sound_length(self.Activate_SOUND) * ROOM_SPEED_BASE)
        self.timer += 2
        self.sub_state = self.sub_state_ACTIVATING
      }
      break
    }
    case self.sub_state_ACTIVATING: {
      PC_set_behavior(self.PC_HOLD_BEHAVIOR) // both arms raised
      if (self.timer && audio_is_playing(self.Activate_SOUND)) break
      self.timer = 0
      const _i = world.irandom(self.Blocks_COUNT - 1)
      dg.set(_i, 0, 2) // state
      dg.set(_i, 1, self.Blocks_DUR1) // timer
      self.timer = 0
      self.sub_state = self.sub_state_REMOVING
      break
    }
    case self.sub_state_REMOVING: {
      if (self.timer) break
      let _complete = true
      for (let _i = 0; _i < self.Blocks_COUNT; _i++) {
        if (!gmBool(dg.get(_i, 1))) continue // timer
        _complete = false
        dg.set(_i, 1, (dg.get(_i, 1) as number) - 1)
        if (dg.get(_i, 1) === self.Blocks_CUE2) {
          const _dl_remaining: number[] = []
          for (let _j = 0; _j < self.Blocks_COUNT; _j++) if (dg.get(_j, 0) === 1) _dl_remaining.push(_j)
          if (_dl_remaining.length) {
            // ds_list_shuffle + take [0] == pick one uniformly
            const _idx = _dl_remaining[world.irandom(_dl_remaining.length - 1)] as number
            if (dg.get(_idx, 0) === 1) {
              // just in case
              dg.set(_idx, 0, 2) // state
              dg.set(_idx, 1, self.Blocks_DUR1) // timer
              aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
            }
          }
        } else if (!gmBool(dg.get(_i, 1))) {
          dg.set(_i, 0, 0) // state
        }
      }
      if (_complete) {
        setBarrier2Solids(self, 0) // Remove all solids
        f.dm_quests.set(self.Barrier1_SCENE_NAME + STR_Barrier + STR_State, 1) // Barrier has been removed
        g.pc_lock = 0
        PC_set_behavior(P.behavior_IDLE)
        Audio.can_play_mus_rm_body = true
        self.timer = 0
        self.sub_state = self.sub_state_IDLE2
      }
      break
    }
    case self.sub_state_IDLE2:
      break
  }
}

/** `Barrier2_udp()` */
export function Barrier2_udp(self: Barrier2): void {
  self.can_draw_self = true
  self.Triforce_pi = (g.counter1 >> 2) & 0x1 ? self.Triforce_PI2 : self.Triforce_PI1
}

/** `Barrier2_draw()` */
export function Barrier2_draw(self: Barrier2): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  const P = pc()
  const d = self.depth
  draw_sprite_at(d, self.TriforceSymbol_SPR, 0, self.TriforceSymbol_XC, self.TriforceSymbol_YC, G.PI_BGR2)
  if (self.sub_state === self.sub_state_IDLE2) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  if (P.behavior === self.PC_HOLD_BEHAVIOR)
    draw_sprite_at(d, 'spr_Triforce_1a', 0, P.x, P.yt - 0x08, self.Triforce_pi)
  const dg = self.dg_Blocks as DsGrid<number>
  const _PI = G.PI_MOB_ORG
  const _Y_SCALE = sign_(g.counter1 & 0x4)
  for (let _i = 0; _i < self.Blocks_COUNT; _i++) {
    if (!gmBool(dg.get(_i, 0))) continue
    const _x = dg.get(_i, 2) as number
    const _y = dg.get(_i, 3) as number
    if (dg.get(_i, 0) === 1 || (dg.get(_i, 0) === 2 && (dg.get(_i, 1) as number) >= self.Blocks_CUE1)) {
      draw_sprite_at(d, self.Blocks_SPR, 0, _x, _y, self.palidx)
    }
    if (dg.get(_i, 0) === 2 && gmBool(dg.get(_i, 1))) {
      const _spr = inRange(dg.get(_i, 1) as number, 8, 23) ? 'spr_Explosion1B' : 'spr_Explosion1A'
      draw_sprite_at(d, _spr, 0, _x, _y, _PI, 1, _Y_SCALE)
      draw_sprite_at(d, _spr, 0, _x, _y, _PI, -1, _Y_SCALE)
    }
  }
}
