/** Moblin (`MoblA`; v1 orange, v2 red, v3 blue) — spear stab/throw. Ported from `Moblin_init2/update/udp/draw.gml`. */
import { MAX_GOC1, UIDX_NULL } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { GO_update_cs } from '../../../../../collision/cs'
import { GOB_sword_collision_1a, GOB_sword_collision_2a } from '../../../../../collision/gob'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { inRange } from '../../../../../math/index'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { draw_sprite_, drawState } from '../../../../../rooms/draw'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { GO_draw_sprite } from '../../../../go/draw'
import { GO_set_sprite } from '../../../../go/sprite'
import type { ObjectName } from '../../../../objectNames'
import { gp, pc } from '../../../../pending'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_2, update_EF11 } from '../../../GameObjectB'
import { Enemy_update_1 } from '../iron_knuckle/common'

export class MoblA extends Enemy {
  readonly objectName = 'MoblA' as const
  attack_dist = 0x16
  BVR_IDL1 = 0 // idle 1:    spear not showing
  BVR_DRWL = 1 // idle 2:    spear showing
  BVR_ATKL = 2 // attack 1:  low attack.  Moblin3 & Moblin4
  BVR_DRWH = 3 // draw 1:    high attack draw
  BVR_ATKH = 4 // attack 2:  high attack. Moblin3
  BVR_THRW = 5 // throw:     throw spear. Moblin2 & Moblin4
  DUR_ATK_STAB = 0x10
  DUR_ATK_DRAW = 0x18
  HSPD_PACE = 2
  HSPD_CHASE = 0x10
  VSPD_GRAV = 2
  AGRO_DIST = 0xa0
  AGRO_BOR = 0x50
  agroDist = 0xa0
  ATCK_DIST1 = 0x60 // 96. eID $14
  ATCK_DIST2 = 0x16 // 22. eID $15,16
  SPEAR_SPR1 = 'spr_Spear_piece1'
  SPEAR_SPR2 = 'spr_Spear_piece2'
  spear_spr1: string | 0 = 0
  spear_spr2: string | 0 = 0
  canDrawSword = false
  spear_xscale = 1
  spear_xoff1 = 0
  spear_xoff2 = 0
  spear_yoff = 0
  SwordHB_XOFF1 = 4
  SwordHB_XOFF2 = 8
  SwordHB_YOFF = 9
  SwordHB_W = 14
  SwordHB_H = 1
}

/** `Moblin_init2()` */
export function Moblin_init2(self: MoblA): void {
  const g = gp()
  self.projectile_OBJ = 'Spear'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.BVR_IDL1 = 0
  self.BVR_DRWL = 1
  self.BVR_ATKL = 2
  self.BVR_DRWH = 3
  self.BVR_ATKH = 4
  self.BVR_THRW = 5
  self.behavior = self.BVR_IDL1
  self.DUR_ATK_STAB = 0x10
  self.DUR_ATK_DRAW = 0x18
  self.HSPD_PACE = 2
  self.HSPD_CHASE = 0x10
  self.hspd = (8 * self.facing_dir) & 0xff // $0071,X
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.counter = 0 // 0444,X
  self.AGRO_DIST = 0xa0
  self.AGRO_BOR = 0x50
  self.agroDist = self.AGRO_DIST
  self.ATCK_DIST1 = 0x60
  self.ATCK_DIST2 = 0x16
  self.attack_dist = self.ATCK_DIST2
  self.dl_sprites?.set(5, 'spr_Moblin_Low_Stab') // stab low
  self.dl_sprites?.set(4, 'spr_Moblin_Low_Draw') // draw low
  self.dl_sprites?.set(3, 'spr_Moblin_High_StabB') // stab high
  self.dl_sprites?.set(2, 'spr_Moblin_High_StabA') // stab high
  self.dl_sprites?.set(1, 'spr_Moblin_High_DrawB') // draw high
  self.dl_sprites?.set(0, 'spr_Moblin_High_DrawA') // draw high
  self.SPEAR_SPR1 = 'spr_Spear_piece1'
  self.SPEAR_SPR2 = 'spr_Spear_piece2'
  self.spear_spr1 = 0
  self.spear_spr2 = 0
  self.canDrawSword = false
  self.spear_xscale = 1
  self.spear_xoff1 = 0
  self.spear_xoff2 = 0
  self.spear_yoff = 0
  // sword hb
  self.SwordHB_XOFF1 = 4 + g.HB_ADJ_X
  self.SwordHB_XOFF2 = 8 + g.HB_ADJ_X
  self.SwordHB_YOFF = 9 + g.HB_ADJ_Y
  self.SwordHB_W = 14 + g.HB_ADJ_W
  self.SwordHB_H = 1 + g.HB_ADJ_H
  self.SwordHB_xoff = self.SwordHB_XOFF1 * self.facing_dir
  self.SwordHB_yoff = self.SwordHB_YOFF
  self.SwordHB_w = self.SwordHB_W
  self.SwordHB_h = self.SwordHB_H
}

/** `Moblin_update()` — v1 orange $14, v2 red $15, v3 blue $16 */
export function Moblin_update(self: MoblA): void {
  const g = gp()
  const P = pc()
  if (self.ver === 1)
    self.attack_dist = self.ATCK_DIST1 // $60
  else self.attack_dist = self.ATCK_DIST2 // $16
  if (self.behavior === self.BVR_ATKL || self.behavior === self.BVR_ATKH) {
    // 997A
    update_EF11(self) // updates swrd spr offs
    // 997D: JSR E558, E563: JSR E5F3
    if (!GOB_sword_collision_2a(self)) GOB_sword_collision_1a(self) // E579: JSR E5F3
  }
  // 9972
  if (gmBool(self.behavior) && !self.timer) {
    // 99C9
    if (self.behavior === self.BVR_DRWH) self.behavior = self.BVR_ATKH
    else if (self.behavior === self.BVR_DRWL) self.behavior = self.BVR_ATKL
    else self.behavior = 0
    if (
      self.behavior === self.BVR_ATKH &&
      (self.ver === 1 || self.ver === 3) &&
      avail_uidx_goc(MAX_GOC1) !== UIDX_NULL
    ) {
      // v1 orange, v3 blue
      if (inRange(self.x, g.view_xl_og, g.view_xr_og) || Math.abs(self.x - P.x) < self.attack_dist) {
        const _XL = self.xl + (self.ver === 3 ? 1 : 0)
        const _YT = self.yt + 5
        const p = GOC1_create(
          _XL,
          _YT,
          self.facing_dir,
          self.projectile as ObjectName,
          self.projectile_ver,
          self,
          self.palidx_def,
        )
        p.hspd = (0x28 * p.facing_dir) & 0xff
        p.vspd = 0xe8
      }
    }
    // 99E6
    if (gmBool(self.behavior)) self.timer = self.DUR_ATK_STAB // $10: 0.267s
  }
  // 9A29
  GO_update_cs(self)
  GOB_update_2(self)
  Enemy_update_1(self)
}

/** `Moblin_udp()` — 9C43, 9CA4 */
export function Moblin_udp(self: MoblA): void {
  const g = gp()
  self.can_draw_self = true
  self.spear_spr1 = 0
  self.spear_spr2 = 0
  let _bvr = self.behavior // _bvr: 05E4
  if (_bvr === self.BVR_ATKL && self.timer < 8) _bvr = 1
  let _sprites_idx = 5 // spr_Moblin_Low_Stab
  if (gmBool(self.hspd) && g.counter1 & 0x8) _sprites_idx = 4 // spr_Moblin_Low_Draw
  // 9CDF
  if (!self.ocs && gmBool(_bvr)) {
    // 9CEC
    if (_bvr > 2) self.spear_yoff = -8
    else self.spear_yoff = 0
    self.spear_xscale = self.facing_dir
    switch (_bvr) {
      case 1: {
        _sprites_idx = 4 // spr_Moblin_Low_Draw
        self.spear_spr1 = self.SPEAR_SPR1
        self.spear_xscale = -self.facing_dir
        self.spear_xoff1 = -8
        self.spear_xoff2 = 0
        if (inRange(self.timer, 3, 12)) {
          self.spear_xoff1 = -12
          self.spear_xoff2 = 0
        }
        break
      }
      case 2: {
        if (self.timer < 8)
          _sprites_idx = 4 // spr_Moblin_Low_Draw
        else _sprites_idx = 5 // spr_Moblin_Low_Stab
        if (inRange(self.timer, 8, 12)) self.spear_spr2 = self.SPEAR_SPR2
        self.spear_spr1 = self.SPEAR_SPR1
        self.spear_xoff1 = 12
        self.spear_xoff2 = 0
        if (self.timer < 13) {
          self.spear_xoff1 = 20
          self.spear_xoff2 = 12
        }
        if (self.timer < 8) {
          self.spear_xscale = -self.facing_dir
          self.spear_xoff1 = -12
          self.spear_xoff2 = 0
        }
        break
      }
      case 3: {
        _sprites_idx = 0 // spr_Moblin_High_DrawA
        self.spear_spr1 = self.SPEAR_SPR1
        self.spear_spr2 = self.SPEAR_SPR2
        self.spear_xoff1 = 12
        self.spear_xoff2 = -8
        if (inRange(self.timer, 3, 12)) {
          self.spear_xoff1 = 8
          self.spear_xoff2 = -12
        }
        break
      }
      case 4: {
        _sprites_idx = 2 // spr_Moblin_High_StabA
        if (inRange(self.timer, 3, 12)) self.spear_spr2 = self.SPEAR_SPR2
        self.spear_spr1 = self.SPEAR_SPR1
        self.spear_xoff1 = 12
        self.spear_xoff2 = 0
        if (inRange(self.timer, 3, 12)) {
          self.spear_xoff1 = 20
          self.spear_xoff2 = 12
        }
        break
      }
      case 5: {
        _sprites_idx = 2 // spr_Moblin_High_StabA
        break
      }
      default:
        break
    }
    self.spear_xoff1 *= self.facing_dir
    self.spear_xoff2 *= self.facing_dir
  }
  GO_set_sprite(self, self.dl_sprites?.get(_sprites_idx) as string)
}

/** `Moblin_draw()` */
export function Moblin_draw(self: MoblA): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  drawState.depth = self.depth
  pal_swap_set(self.palidx)
  draw_sprite_(
    self.spear_spr1,
    0,
    self.drawX + self.spear_xoff1,
    self.drawY + self.spear_yoff,
    -1,
    self.spear_xscale,
  )
  draw_sprite_(
    self.spear_spr2,
    0,
    self.drawX + self.spear_xoff2,
    self.drawY + self.spear_yoff,
    -1,
    self.spear_xscale,
  )
  GO_draw_sprite(self, self.sprite)
  pal_swap_reset()
}

export function registerMoblin(): void {
  registerObject('MoblA', MoblA)
  registerScripts({ Moblin_init2, Moblin_update, Moblin_udp, Moblin_draw })
}
registerMoblin()
