/**
 * GameMaker data-structure equivalents. ZALiA's whole data layer is string-keyed `ds_map`s, so these
 * keep GM semantics (missing → `undefined`, `val()` defaulting) rather than pretending to be typed.
 */

export class DsMap<V = number | string> extends Map<string, V> {
  /** GML `val(map[? k], dflt)` — 0 when absent and no default given. */
  val(key: string, dflt?: V): V | 0 {
    const v = this.get(key)
    if (v !== undefined) return v
    return dflt === undefined ? 0 : dflt
  }
  /** Bulk load from a decoded cache object. */
  static from<V>(obj: Record<string, V>): DsMap<V> {
    const m = new DsMap<V>()
    for (const k in obj) m.set(k, obj[k] as V)
    return m
  }
}

/**
 * `ds_list`: reads outside the range give `undefined`; writes past the end extend the list (GM fills with
 * 0 — here the gap is `undefined`, which every ZALiA read already treats as "empty" via is_undefined/noone).
 */
export class DsList<T> {
  readonly items: T[] = []
  constructor(size = 0, fill?: T) {
    for (let i = 0; i < size; i++) this.items.push(fill as T)
  }
  get size(): number {
    return this.items.length
  }
  get(i: number): T | undefined {
    return this.items[i]
  }
  set(i: number, v: T): void {
    while (this.items.length < i) this.items.push(undefined as T)
    this.items[i] = v
  }
  add(...v: T[]): void {
    this.items.push(...v)
  }
  delete(i: number): void {
    this.items.splice(i, 1)
  }
  findIndex(v: T): number {
    return this.items.indexOf(v)
  }
  clear(): void {
    this.items.length = 0
  }
  [Symbol.iterator](): Iterator<T> {
    return this.items[Symbol.iterator]()
  }
}

/** `ds_grid`: cells addressed `[x, y]`, stored row-major (`cells[y][x]`) like the decoded caches. */
export class DsGrid<T = number> {
  readonly cells: T[][]
  constructor(
    readonly width: number,
    readonly height: number,
    fill: T,
  ) {
    this.cells = Array.from({ length: height }, () => new Array<T>(width).fill(fill))
  }
  static from<T>(cells: T[][]): DsGrid<T> {
    const g = new DsGrid<T>(cells[0]?.length ?? 0, cells.length, undefined as T)
    for (let y = 0; y < cells.length; y++) g.cells[y] = [...(cells[y] as T[])]
    return g
  }
  get(x: number, y: number): T | undefined {
    return this.cells[y]?.[x]
  }
  set(x: number, y: number, v: T): void {
    const row = this.cells[y]
    if (row && x >= 0 && x < this.width) row[x] = v
  }
  inBounds(x: number, y: number): boolean {
    return x >= 0 && y >= 0 && x < this.width && y < this.height
  }
}
