/**
 * Keyboard bindings — completes ZALiA's open TODO (`OptionsMenu_InputConfig_update.gml:4`). Leaf module
 * (no game imports) so `Input_update2a` can consult it. Persisted by the gui port in
 * `input.dm_UserInputConfig` under `keyboard_<action>` (comma-joined key names).
 */
export type KeyAction = 'right' | 'left' | 'down' | 'up' | 'jump' | 'attack' | 'pause' | 'magic'
export const KEY_ACTIONS: readonly KeyAction[] = [
  'right',
  'left',
  'down',
  'up',
  'jump',
  'attack',
  'pause',
  'magic',
]

/** ZALiA's hard-coded keyboard (Input_update2a): each action accepts either key. */
export const KEYBOARD_DEFAULTS: Record<KeyAction, string[]> = {
  right: ['D', 'vk_right'],
  left: ['A', 'vk_left'],
  down: ['S', 'vk_down'],
  up: ['W', 'vk_up'],
  jump: ['vk_space'],
  attack: ['vk_control'],
  pause: ['vk_enter'],
  magic: ['T'],
}

/** Live keyboard bindings consulted by `Input_update2a`. */
export const keyboardBindings: Record<KeyAction, string[]> = {
  right: [...KEYBOARD_DEFAULTS.right],
  left: [...KEYBOARD_DEFAULTS.left],
  down: [...KEYBOARD_DEFAULTS.down],
  up: [...KEYBOARD_DEFAULTS.up],
  jump: [...KEYBOARD_DEFAULTS.jump],
  attack: [...KEYBOARD_DEFAULTS.attack],
  pause: [...KEYBOARD_DEFAULTS.pause],
  magic: [...KEYBOARD_DEFAULTS.magic],
}

export function keyboard_bindings_load(config: { get(k: string): unknown }): void {
  for (const a of KEY_ACTIONS) {
    const v = config.get(`keyboard_${a}`)
    keyboardBindings[a] = typeof v === 'string' && v.length ? v.split(',') : [...KEYBOARD_DEFAULTS[a]]
  }
}
export function keyboard_bindings_save(config: { set(k: string, v: string): unknown }): void {
  for (const a of KEY_ACTIONS) config.set(`keyboard_${a}`, keyboardBindings[a].join(','))
}
export function keyboard_bindings_reset(): void {
  for (const a of KEY_ACTIONS) keyboardBindings[a] = [...KEYBOARD_DEFAULTS[a]]
}
