/** `update_view_1()`, `update_view_1a()`, `ViewCatchUp_init()` — camera follow. D4FE: JSR 9925 */
import { gmBool, gmRound as round } from '../../nes/math8'
import { G, g } from '../../runtime/world'
import { sign_ } from '../math/index'
import { ease_in_out } from '../other/index'
import {
  cam_xl_max,
  cam_xl_min,
  cam_xl_range,
  cam_xr_max,
  cam_yb_max,
  cam_yt_max,
  cam_yt_min,
  cam_yt_range,
  clamp,
  pcView,
  set_camera_xy,
  update_view_og,
  viewH_,
  viewW_,
  viewXC,
  viewXL,
  viewXR,
  viewYB,
  viewYC,
  viewYT,
} from './camera'

const frac = (v: number) => v - Math.floor(v)

/** `update_view_1a(default, use smooth view, coord 1, coord 2)` */
export function update_view_1a(
  dflt: number,
  useSmooth: number | boolean,
  coord1: number,
  coord2: number,
): number {
  if (gmBool(useSmooth)) {
    // use smooth moving
    if (coord1 === coord2) return 0
    let diff = Math.abs(coord1 - coord2)
    diff = round(diff / 5)
    return diff * Math.sign(coord1 - coord2)
  }
  return dflt
}

/** `ViewCatchUp_init()` */
export function ViewCatchUp_init(): void {
  const pc = pcView()
  switch (G.ViewCatchUp_VER) {
    case 1: {
      G.ViewCatchUp_state = 0
      G.ViewCatchUp_move_x = 0
      G.ViewCatchUp_move_y = 0
      if (pc.x !== viewXC()) {
        if (!(g.view_lock & 0x1)) G.ViewCatchUp_state |= 0x1
        if (!(g.view_lock & 0x2)) G.ViewCatchUp_state |= 0x2
      }
      if (pc.y !== viewYC()) {
        if (!(g.view_lock & 0x4)) G.ViewCatchUp_state |= 0x4
        if (!(g.view_lock & 0x8)) G.ViewCatchUp_state |= 0x8
      }
      break
    }
    case 2: {
      if ((pc.x > viewXC() && !(g.view_lock & 0x1)) || (pc.x < viewXC() && !(g.view_lock & 0x2))) {
        if (pc.x > viewXC()) G.ViewCatchUp_state |= 0x1
        else G.ViewCatchUp_state |= 0x2
        G.ViewCatchUp_x_start = viewXC()
        G.ViewCatchUp_x_end = pc.x
        G.ViewCatchUp_x_distance = G.ViewCatchUp_x_end - G.ViewCatchUp_x_start
        G.ViewCatchUp_x_time = 0
        G.ViewCatchUp_x_duration = clamp(
          Math.floor(Math.abs(G.ViewCatchUp_x_distance) / G.ViewCatchUp_DIST2),
          G.ViewCatchUp_duration_MIN,
          G.ViewCatchUp_duration_MAX,
        )
      }
      if ((pc.y > viewYC() && !(g.view_lock & 0x4)) || (pc.y < viewYC() && !(g.view_lock & 0x8))) {
        if (pc.y > viewYC()) G.ViewCatchUp_state |= 0x4
        else G.ViewCatchUp_state |= 0x8
        G.ViewCatchUp_y_start = viewYC()
        G.ViewCatchUp_y_end = pc.y
        G.ViewCatchUp_y_distance = G.ViewCatchUp_y_end - G.ViewCatchUp_y_start
        G.ViewCatchUp_y_time = 0
        G.ViewCatchUp_y_duration = clamp(
          Math.floor(Math.abs(G.ViewCatchUp_y_distance) / G.ViewCatchUp_DIST2),
          G.ViewCatchUp_duration_MIN,
          G.ViewCatchUp_duration_MAX,
        )
      }
      break
    }
    default:
      break
  }
}

/** `update_view_1()` — D4FE: JSR 9925 */
export function update_view_1(): void {
  const pc = pcView()
  let _pad = 0
  let _diff = 0
  let _dist0 = 0
  let _PC_DIR_BITS = 0x0
  if (pc.x_change !== 0) _PC_DIR_BITS |= 0x1 << +!gmBool(pc.x_change_dir) // $1 or $2
  if (pc.y_change !== 0) _PC_DIR_BITS |= 0x4 << +!gmBool(pc.y_change_dir) // $4 or $8
  g.view_at_rm_edge = 0
  // ----------------------------------------------------------------------------
  // --------------  HORIZONTAL  -------------------------------------
  if (!cam_xl_range()) g.view_at_rm_edge |= 0x3
  if (!(g.view_at_rm_edge & 0x3) && !(g.view_lock & 0x3 & _PC_DIR_BITS)) {
    _diff = 0
    _pad = 2 // stop cam if less than 4 pixels from edge
    // RIGHT ----------------------------
    if (cam_xr_max() - viewXR() <= _pad) {
      // if view is close enough to its max
      if (gmBool(pc.x_change_dir) || pc.view_xl_dist > viewW_()) {
        g.view_at_rm_edge |= 0x1 // $1 right
      }
    }
    // LEFT ----------------------------
    if (viewXL() - cam_xl_min() <= _pad) {
      if (!gmBool(pc.x_change_dir) || pc.view_xl_dist < viewW_()) {
        g.view_at_rm_edge |= 0x2 // $2 left
      }
    }
    if (gmBool(g.use_smooth_cam_x) || !(g.view_at_rm_edge & 0x3)) {
      switch (G.ViewCatchUp_VER) {
        case 1: {
          if (
            (G.ViewCatchUp_state & 0x1 && pc.x > viewXC()) ||
            (G.ViewCatchUp_state & 0x2 && pc.x < viewXC())
          ) {
            _dist0 = Math.abs(pc.x - viewXC())
            G.ViewCatchUp_move_x += G.ViewCatchUp_SPEED_X * Math.min(_dist0 / G.ViewCatchUp_DIST1, 1.0)
            _diff = Math.min(Math.floor(G.ViewCatchUp_move_x), _dist0)
            _diff *= sign_(pc.x > viewXC())
            G.ViewCatchUp_move_x = frac(G.ViewCatchUp_move_x)
          } else {
            _diff = update_view_1a(pc.x_change, g.use_smooth_cam_x, pc.x, viewXC())
          }
          break
        }
        case 2: {
          if (G.ViewCatchUp_x_duration && G.ViewCatchUp_x_duration > G.ViewCatchUp_x_time) {
            const _X = Math.floor(
              ease_in_out(
                G.ViewCatchUp_x_start,
                G.ViewCatchUp_x_distance,
                G.ViewCatchUp_x_time,
                G.ViewCatchUp_x_duration,
              ),
            )
            _diff = _X - viewXC()
            G.ViewCatchUp_x_time++
            if (G.ViewCatchUp_x_time >= G.ViewCatchUp_x_duration) _diff = G.ViewCatchUp_x_end - viewXC()
          } else {
            _diff = update_view_1a(pc.x_change, g.use_smooth_cam_x, pc.x, viewXC())
          }
          break
        }
        default: {
          _diff = update_view_1a(pc.x_change, g.use_smooth_cam_x, pc.x, viewXC())
          break
        }
      }
      if (_diff !== 0) {
        const _viewXL = viewXL()
        const _XL = clamp(viewXL() + _diff, cam_xl_min(), cam_xl_max())
        set_camera_xy(_XL, viewYT())
        if (_viewXL !== viewXL()) g.view_dir_x = Math.sign(viewXL() - _viewXL)
      }
      switch (G.ViewCatchUp_VER) {
        case 1: {
          if (G.ViewCatchUp_state & 0x3) {
            if (pc.x === viewXC() || viewXL() - cam_xl_min() <= _pad || cam_xr_max() - viewXR() <= _pad) {
              if (viewXL() - cam_xl_min() <= _pad)
                g.view_at_rm_edge |= 0x2 // $2 left
              else if (cam_xr_max() - viewXR() <= _pad) g.view_at_rm_edge |= 0x1 // $1 right
              if (G.ViewCatchUp_state & 0x1) G.ViewCatchUp_state ^= 0x1
              if (G.ViewCatchUp_state & 0x2) G.ViewCatchUp_state ^= 0x2
              G.ViewCatchUp_move_x = 0
              g.pc_lock = 0
            }
          }
          break
        }
        case 2: {
          if (G.ViewCatchUp_x_duration) {
            if (
              G.ViewCatchUp_x_duration <= G.ViewCatchUp_x_time ||
              pc.x === viewXC() ||
              viewXL() - cam_xl_min() <= _pad ||
              cam_xr_max() - viewXR() <= _pad
            ) {
              if (viewXL() - cam_xl_min() <= _pad)
                g.view_at_rm_edge |= 0x2 // $2 left
              else if (cam_xr_max() - viewXR() <= _pad) g.view_at_rm_edge |= 0x1 // $1 right
              G.ViewCatchUp_x_start = 0
              G.ViewCatchUp_x_end = 0
              G.ViewCatchUp_x_distance = 0
              G.ViewCatchUp_x_time = 0
              G.ViewCatchUp_x_duration = 0
              g.pc_lock = 0
            }
          }
          if (!G.ViewCatchUp_x_duration) {
            if (G.ViewCatchUp_state & 0x1) G.ViewCatchUp_state ^= 0x1
            if (G.ViewCatchUp_state & 0x2) G.ViewCatchUp_state ^= 0x2
          }
          break
        }
        default:
          break
      }
    }
  }
  // ----------------------------------------------------------------------------
  // --------------  VERTICAL  -------------------------------------
  if (!cam_yt_range()) g.view_at_rm_edge |= 0xc
  if (!(g.view_at_rm_edge & 0xc) && !(g.view_lock & 0xc & _PC_DIR_BITS)) {
    _diff = 0
    _pad = 0
    // DOWN ----------------------------
    if (cam_yb_max() - viewYB() <= _pad) {
      if (gmBool(pc.y_change_dir) || pc.view_yt_dist > viewH_()) g.view_at_rm_edge |= 0x4 // $4 bottom
    }
    // UP ----------------------------
    if (viewYT() - cam_yt_min() <= _pad) {
      if (!gmBool(pc.y_change_dir) || pc.view_yt_dist < viewH_()) g.view_at_rm_edge |= 0x8 // $8 top
    }
    if (gmBool(g.use_smooth_cam_y) || !(g.view_at_rm_edge & 0xc)) {
      switch (G.ViewCatchUp_VER) {
        case 1: {
          if (
            (G.ViewCatchUp_state & 0x4 && pc.y > viewYC()) ||
            (G.ViewCatchUp_state & 0x8 && pc.y < viewYC())
          ) {
            _dist0 = Math.abs(pc.y - viewYC())
            G.ViewCatchUp_move_y += G.ViewCatchUp_SPEED_Y * Math.min(_dist0 / G.ViewCatchUp_DIST1, 1.0)
            _diff = Math.min(Math.floor(G.ViewCatchUp_move_y), _dist0)
            _diff *= sign_(pc.y > viewYC())
            G.ViewCatchUp_move_y = frac(G.ViewCatchUp_move_y)
          } else {
            _diff = update_view_1a(pc.y_change, g.use_smooth_cam_y, pc.y, viewYC())
          }
          break
        }
        case 2: {
          if (G.ViewCatchUp_y_duration && G.ViewCatchUp_y_duration > G.ViewCatchUp_y_time) {
            const _Y = Math.floor(
              ease_in_out(
                G.ViewCatchUp_y_start,
                G.ViewCatchUp_y_distance,
                G.ViewCatchUp_y_time,
                G.ViewCatchUp_y_duration,
              ),
            )
            _diff = _Y - viewYC()
            G.ViewCatchUp_y_time++
            if (G.ViewCatchUp_y_time >= G.ViewCatchUp_y_duration) _diff = G.ViewCatchUp_y_end - viewYC()
          } else {
            _diff = update_view_1a(pc.y_change, g.use_smooth_cam_y, pc.y, viewYC())
          }
          break
        }
        default: {
          _diff = update_view_1a(pc.y_change, g.use_smooth_cam_y, pc.y, viewYC())
          break
        }
      }
      if (_diff !== 0) {
        const _viewYT = viewYT()
        const _YT = clamp(viewYT() + _diff, cam_yt_min(), cam_yt_max())
        set_camera_xy(viewXL(), _YT)
        if (_viewYT !== viewYT()) g.view_dir_y = Math.sign(viewYT() - _viewYT)
      }
      switch (G.ViewCatchUp_VER) {
        case 1: {
          if (G.ViewCatchUp_state & 0xc) {
            if (pc.y === viewYC() || viewYT() - cam_yt_min() <= _pad || cam_yb_max() - viewYB() <= _pad) {
              if (viewYT() - cam_yt_min() <= _pad)
                g.view_at_rm_edge |= 0x8 // $8 top
              else if (cam_yb_max() - viewYB() <= _pad) g.view_at_rm_edge |= 0x4 // $4 bottom
              if (G.ViewCatchUp_state & 0x4) G.ViewCatchUp_state ^= 0x4
              if (G.ViewCatchUp_state & 0x8) G.ViewCatchUp_state ^= 0x8
              G.ViewCatchUp_move_y = 0
              g.pc_lock = 0
            }
          }
          break
        }
        case 2: {
          if (G.ViewCatchUp_y_duration) {
            if (
              G.ViewCatchUp_y_duration <= G.ViewCatchUp_y_time ||
              pc.y === viewYC() ||
              viewYT() - cam_yt_min() <= _pad ||
              cam_yb_max() - viewYB() <= _pad
            ) {
              if (viewYT() - cam_yt_min() <= _pad)
                g.view_at_rm_edge |= 0x8 // $8 top
              else if (cam_yb_max() - viewYB() <= _pad) g.view_at_rm_edge |= 0x4 // $4 bottom
              G.ViewCatchUp_y_start = 0
              G.ViewCatchUp_y_end = 0
              G.ViewCatchUp_y_distance = 0
              G.ViewCatchUp_y_time = 0
              G.ViewCatchUp_y_duration = 0
              g.pc_lock = 0
            }
          }
          if (!G.ViewCatchUp_y_duration) {
            if (G.ViewCatchUp_state & 0x4) G.ViewCatchUp_state ^= 0x4
            if (G.ViewCatchUp_state & 0x8) G.ViewCatchUp_state ^= 0x8
          }
          break
        }
        default:
          break
      }
    }
  }
  update_view_og()
  // Added 2023/11/01 so that if a GO moves PC and update_Camera_1() is called again after
  // GO update, it doesn't cause a double cam move.
  pc.x_change = 0
  pc.y_change = 0
}
