/**
 * ZALiA's retro post-processing chain as a Phaser 4 camera filter stack.
 *
 * ZALiA ping-pongs `application_surface` through four shaders in `Surface_Draw_GUI_Begin.gml`:
 * SaturationBrightness -> Scanlines -> Bloom -> Blur, each guarded by its own
 * `RetroShaders_*_can_draw`. Phaser's internal filter list *is* that ping-pong — each controller in
 * `camera.filters.internal` runs in list order, each pass reading the previous pass's target — so
 * the port is one controller per shader, added in the same order, toggled with `controller.active`.
 *
 * The widescreen bars go in front of them. ZALiA draws those in `Surface_Draw_End.gml:22-27`, i.e.
 * into `application_surface` before the shader chain runs, so they get scanlined and bloomed with
 * the rest of the frame; first in the internal list reproduces that.
 *
 * Not verified in a browser — this box has no GPU. See the file-level note in `nodes.ts` for the
 * Phaser APIs used and where each was checked.
 */
import { G, g, p, windowState } from '@z2/core'
import type Phaser from 'phaser'
import {
  BloomController,
  BlurController,
  registerRetroPostFxNodes,
  SaturationBrightnessController,
  ScanlinesController,
  WideMaskController,
} from './nodes'
import {
  C_BLK1,
  packRetroUniforms,
  type RetroSettings,
  type RetroSettingsSource,
  readRetroSettings,
  scanlineHeightFor,
} from './settings'

export class RetroPostFx {
  /** False on the Canvas renderer, where filters do not exist. `update()` then does nothing. */
  readonly supported: boolean
  private readonly mask?: WideMaskController
  private readonly saturationBrightness?: SaturationBrightnessController
  private readonly scanlines?: ScanlinesController
  private readonly bloom?: BloomController
  private readonly blur?: BlurController

  constructor(private readonly camera: Phaser.Cameras.Scene2D.Camera) {
    const renderer = camera.scene.game.renderer
    this.supported = 'renderNodes' in renderer
    if (!this.supported) return
    registerRetroPostFxNodes(renderer)
    // Order is the port's whole point: bars first (baked into the surface by ZALiA's Draw End),
    // then the Draw GUI Begin chain in its GML order.
    const list = camera.filters.internal
    this.mask = list.add(new WideMaskController(camera)) as WideMaskController
    this.saturationBrightness = list.add(
      new SaturationBrightnessController(camera),
    ) as SaturationBrightnessController
    this.scanlines = list.add(new ScanlinesController(camera)) as ScanlinesController
    this.bloom = list.add(new BloomController(camera)) as BloomController
    this.blur = list.add(new BlurController(camera)) as BlurController
    const blk = p?.C_BLK1 ?? C_BLK1
    this.mask.barColor = [((blk >> 16) & 0xff) / 255, ((blk >> 8) & 0xff) / 255, (blk & 0xff) / 255]
    // Inert until the first `update()` feeds real settings, so no pass ever runs on default uniforms.
    for (const c of [this.mask, this.saturationBrightness, this.scanlines, this.bloom, this.blur]) {
      c.active = false
    }
  }

  /**
   * Pull one frame of settings out of the core and push them onto the controllers.
   * Resolution-dependent uniforms are not touched here — the render nodes read
   * `drawingContext.width/height` per pass, so a resize needs no work from this class.
   */
  /**
   * Suppresses the wide-view side bars. They exist to letterbox the NES's 256-wide view inside ZALiA's
   * 480-wide one; when the adapter presents that window directly (`ogViewWindow()`), the camera *is* the
   * OG view and masking it again eats another 112/480 = 23.3% of the width from each side — 256 becomes a
   * 136px band, which is how this was found.
   */
  suppressWideMask = false

  update(settings: RetroSettings = readRetroSettings(coreSettingsSource())): void {
    if (!this.supported) return
    const u = packRetroUniforms(settings)

    if (this.mask) {
      this.mask.active = u.mask.enabled && !this.suppressWideMask
      this.mask.barFrac = u.mask.frac
    }
    if (this.saturationBrightness) {
      this.saturationBrightness.active = u.saturationBrightness.enabled
      this.saturationBrightness.saturation = u.saturationBrightness.saturation
      this.saturationBrightness.brightness = u.saturationBrightness.brightness
      this.saturationBrightness.effectType = u.saturationBrightness.effectType
    }
    if (this.scanlines) {
      this.scanlines.active = u.scanlines.enabled
      this.scanlines.lineBrightness = u.scanlines.brightness
      // ZALiA's line height is in scaled-application-surface rows; convert to this camera's rows.
      this.scanlines.lineHeight = scanlineHeightFor(
        u.scanlines.lineHeight,
        this.camera.height,
        settings.surfaceScale,
      )
    }
    if (this.bloom) {
      this.bloom.active = u.bloom.enabled
      this.bloom.params = u.bloom.params
    }
    if (this.blur) {
      this.blur.active = u.blur.enabled
      this.blur.alpha = u.blur.alpha
      this.blur.windowWidth = settings.windowWidth
      this.blur.windowHeight = settings.windowHeight
    }
  }
}

/**
 * Bind the read-only settings interface to the core's live module singletons.
 *
 * `G`, `g` and `windowState` are `export let` / plain-object singletons in `@z2/core`
 * (`runtime/world.ts`, `game/view/window.ts`) — the same polling pattern `GameScene` already uses
 * for `p.palette_image` and `windowState.fullscreen`. `g.surf` is typed `any` in the core and is
 * `NOONE` (null) until the `Surface` object port lands, so `readRetroSettings` falls back to
 * ZALiA's shipped defaults for every `GraphicsEffectsEditor` value.
 */
function coreSettingsSource(): RetroSettingsSource {
  return {
    globals: G as RetroSettingsSource['globals'],
    game: g as unknown as RetroSettingsSource['game'],
    window: windowState,
  }
}
