/** Town cucco (chicken) — ZALiA `gob2/cucco` (`Cucco_init`, `Cucco_update`, `Cucco_update_1`). */
import { ABL_JUMP, ABL_WALK, CS_BTM, CS_LFT, CS_RGT, CS_SW1 } from '@z2/data'
import { g, world } from '../../../../runtime/world'
import { GO_update_cs } from '../../../collision/cs'
import { sign_ } from '../../../math/index'
import { updateX, updateY } from '../../go/movement'
import { solid_clip_correction } from '../../goa/movement'
import { pc } from '../../goa/pc'
import { GameObjectB_step, GOB_update_2 } from '../GameObjectB'
import type { CuccoObject } from './classes'

/** `Cucco_init()` */
export function Cucco_init(self: CuccoObject): void {
  self.sub_state = self.SUB_STATE_IDLE
  self.HSPD1 = 0x08
  self.abilities |= ABL_WALK
  self.CS_IDX1 = 0x02 // norm
  self.CS_IDX2 = 0x03 // crouching
  self.struck_counter = 0
  self.PANIC_DUR = 0xff
  self.facing_dir_timer = 0
  self.scr_step = GameObjectB_step as never
}

/** `Cucco_init2()` — empty in ZALiA */
export function Cucco_init2(_self: CuccoObject): void {}

/**
 * `Cucco_udp()` — the whole body (body/legs/eye/wing sprite selection) is commented out in ZALiA, so the
 * cucco draws through `GameObjectB_draw_1`; kept as the registered no-op the object data points at.
 */
export function Cucco_udp(_self: CuccoObject): void {}

/** `Cucco_draw()` — empty in ZALiA. */
export function Cucco_draw(_self: CuccoObject): void {}

/** `Cucco_update()` */
export function Cucco_update(self: CuccoObject): void {
  const P = pc()
  if (self.cs & CS_SW1) {
    self.struck_counter++
    if (!self.stun_timer) {
      self.vspd = P.VSPD_DAMAGE // $FE. Low velocity
      if ((self.cs & CS_RGT && self.x > P.x) || (self.cs & CS_LFT && self.x <= P.x)) self.hspd = 0
      else self.hspd = (0xd * sign_(self.x > P.x)) & 0xff
      self.stun_timer = P.DamageFlash_DURATION
    }
    self.facing_dir_timer = 0
    self.timer = self.PANIC_DUR
    self.sub_state = self.SUB_STATE_PANIC
  }
  if (self.cs & CS_BTM) {
    solid_clip_correction(self, false)
    self.vspd = 0
  }
  if (self.facing_dir_timer) {
    self.facing_dir_timer--
    if (!self.facing_dir_timer) {
      self.facing_dir = sign_(world.irandom(1))
      self.facing_dir_timer = 0x30 + world.irandom(0x3f)
    }
  }
  if (self.abilities & ABL_JUMP && !(g.counter1 & 0x7f) && !world.irandom(0x3f)) {
    // JUMP
    self.vspd = 0xe8 | world.irandom(7)
    if (!self.hspd && world.irandom(7)) self.hspd = (self.HSPD1 * self.facing_dir) & 0xff
  }
  updateY(self)
  self.vspd = (self.vspd + 1) & 0xff
  updateX(self)
  GO_update_cs(self)
  GOB_update_2(self)
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE:
      if (self.cs & CS_BTM) {
        self.hspd = 0
        Cucco_update_1(self)
      }
      break
    case self.SUB_STATE_WALK1:
      if (self.cs & CS_BTM) {
        if (self.abilities & ABL_WALK) self.hspd = (self.HSPD1 * self.facing_dir) & 0xff
        else self.hspd = 0
        Cucco_update_1(self)
      }
      break
    case self.SUB_STATE_HOP1:
      Cucco_update_1(self)
      break
    case self.SUB_STATE_PECK1:
      if (self.cs & CS_BTM) {
        self.hspd = 0
        Cucco_update_1(self)
      }
      break
    case self.SUB_STATE_AGRO:
      break
    case self.SUB_STATE_PANIC:
      if (self.cs & CS_BTM) {
        self.hspd = (0x20 * sign_(self.x > P.x)) & 0xff
        Cucco_update_1(self)
        if (self.sub_state !== self.SUB_STATE_PANIC) self.facing_dir_timer = 1
      }
      break
    case self.SUB_STATE_FURY:
      break
  }
}

/** `Cucco_update_1()` — pick the next idle/walk behaviour once the timer runs out */
export function Cucco_update_1(self: CuccoObject): boolean {
  if (self.timer) return false
  self.sub_state = world.irandom(1) ? self.SUB_STATE_WALK1 : self.SUB_STATE_IDLE
  switch (self.sub_state) {
    case self.SUB_STATE_IDLE:
    case self.SUB_STATE_WALK1:
      self.timer = ((world.irandom(2) + 1) << 6) + world.irandom(0x1f)
      break
    case self.SUB_STATE_HOP1:
      self.timer = ((world.irandom(1) + 1) << 4) + world.irandom(0x1f)
      break
    case self.SUB_STATE_PECK1:
      self.timer = ((world.irandom(1) + 1) << 6) + world.irandom(0x1f)
      break
  }
  return true
}
