const choose = <T>(...v: T[]): T => v[world.irandom(v.length - 1)] as T

interface SpawnedEnemy extends GameObject {
  HSPD1?: number
  HSPD2?: number
  VSPD1?: number
  sub_state?: number
  sub_state_CHARGE?: number
}

/** Bago/Boggnipp/Moby/Grunt and the raft: `PlatformRaft` (other port) read through its object name. */
function platformRaft(): (GameObject & { hspd_dir: number }) | undefined {
  for (const r of instancesOfName<GameObject & { hspd_dir: number }>('PlatformRaft')) return r
  return undefined
}

/** `enemy_spawn_1(object_index, version)` — used by WosuSpawner & MauSpawner. B876 */
export function enemy_spawn_1(self: GameObject, _OBJ: ObjectName, _VER: number): SpawnedEnemy {
  const P = pc()
  const _facingDir = self.facing_dir
  if (gmBool(input.heldH)) self.facing_dir = -sign_(input.heldH & 0x01)
  else self.facing_dir = -sign_(rand(self) & 0x01)
  const e = GameObject_create(0, 0, _OBJ, _VER) as SpawnedEnemy
  // B876
  e.facing_dir = self.facing_dir
  self.facing_dir = _facingDir
  // WIDE VIEW
  let _XL = viewXL() + viewW() * (gmBool(e.facing_dir) ? 0 : 1) // left or right end of view
  _XL -= e.ww_ // half GO's width
  _XL += ((P.yt & 0xff) < 3 ? 1 : 0) * e.facing_dir // OG CARRY. 0, 1, -1
  const _YT = P.yt + P.hh - 0x22
  set_xlyt(e, _XL, _YT)
  e.hspd = ((e.HSPD1 ?? 0) * e.facing_dir) & 0xff
  e.counter = 0xff
  return e
}

/** `enemy_spawn_2(object_index, version)` — MobySpawner $66/Moby $A4, GruntSpawner $64/Grunt $A3. 9B48 */
export function enemy_spawn_2(self: GameObject, _OBJ: ObjectName, _VER: number): SpawnedEnemy {
  const _C1 = self.objectName === 'SpGrA' ? 1 : 0 // SpGrA: Grunt Spawner
  let _X = viewXC()
  if (_C1)
    _X += viewW_() * sign_(rand(self) & 0x01) // GruntSpawner
  else _X += 0x58 * sign_(rand(self) & 0x01) // MobySpawner
  _X -= 0x08
  _X += _C1
  const _Y = viewYT() - 0x10
  const e = GameObject_create(_X, _Y, _OBJ, _VER) as SpawnedEnemy
  e.HP_IDX = 0x03 // g.dl_HP_DEFAULT[|$03] = $03
  e.hp = g.dl_HP.get(e.HP_IDX) as number
  e.hspd = 0x00
  e.vspd = 0x20
  e.facing_dir = dir_to_pc(e)
  return e
}

/** Count of live instances of an object name weighted by `sign(state)` (ZALiA `with(X) _count += sign(state)`). */
function liveCount(name: string): number {
  let n = 0
  for (const i of instancesOfName(name)) n += sign(i.state)
  return n
}

function raftAdjust(e: GameObject, mode: 'bago' | 'moby' | 'boggnipp'): void {
  const raft = platformRaft()
  if (raft && gmBool(raft.hspd) && !(g.view_lock & 0x03) && viewXL() > 0 && viewXR() < g.rm_w) {
    if (mode === 'moby') {
      const _DIFF = e.facing_dir === raft.hspd_dir ? 0x50 * e.facing_dir : 0x50 * -e.facing_dir
      set_xy(e, e.x + _DIFF, e.y)
    } else if (e.facing_dir === raft.hspd_dir) {
      set_xy(e, raft.x + 0x80 * -e.facing_dir, e.y)
    } else if (mode === 'bago') {
      e.hspd = (0x18 * e.facing_dir) & 0xff
    }
  }
}

