/** `Spawner_Grunt_update()` */
export function Spawner_Grunt_update(self: SpGrA): void {
  if (g.counter1 & 0x7f) return
  if (available_update_idx_gob(MAX_GOB1) === UIDX_NULL) return
  if (liveCount('MoblB') >= 6) return
  // 9B48
  const e = enemy_spawn_2(self, 'MoblB', 1)
  e.is_from_spawner = true
  // If spawning on same side of rm edge
  if (g.view_at_rm_edge & 0x03 & dir8b(e.x > viewXC())) {
    // MOD. Stop spawns at edge of rm
    const _X = viewXC() - (e.x - viewXC())
    set_xy(e, _X, e.y)
  }
  // 9939
  e.HP_IDX = 0x02 // g.dl_HP_DEFAULT[|$02] = $02
  e.hp = g.dl_HP.get(e.HP_IDX) as number
  e.hspd = (0x10 * e.facing_dir) & 0xff
  set_xy(e, e.x, viewYT() + 0xa8)
}

