export function Spawner_Mau_init2(_self: SpMaA): void {}
/** `Spawner_Mau_update()` — B861, every 128 frames: 2.133s */
export function Spawner_Mau_update(self: SpMaA): void {
  if (g.counter1 & 0x7f || g.view_at_rm_edge & 0x03) return
  switch (g.mod_Mau_SPAWN_FREQ) {
    case 1: {
      // Wide screen makes rm much more difficult by allowing too many to spawn.
      let _count1 = 0
      let _count2 = 0
      for (const e of world.instancesOf(EnemyClass)) {
        if (e.state !== e.state_NORMAL) continue
        if (e.objectName === 'Mau_A') _count1++
        else _count2++
      }
      const _LIMIT = Math.max(3, 6 - Math.trunc(_count2 / 2)) // 3-6
      if (_LIMIT <= _count1) return
      break
    }
    case 2: {
      let _count1 = 0
      for (const m of instancesOfName('Mau_A')) _count1 += m.state === m.state_NORMAL && ocsH1(m) ? 1 : 0
      if (_count1 >= 3) return
      break
    }
  }
  // B876
  const e = enemy_spawn_1(self, 'Mau_A', 1)
  e.is_from_spawner = true
}

