export class SpRoA extends SpawnerHostile {
  readonly objectName = 'SpRoA' as const
  dl_YOFF: number[] = []
}
registerObject('SpRoA', SpRoA)
registerObjectClass('SpRoA', SpRoA)

/** `Spawner_Rock_init2()` — y offset values are stored in $DC47-DC4E. */
export function Spawner_Rock_init2(self: SpRoA): void {
  self.projectile_OBJ = 'Rock1'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  let _YOFF = 0
  const y = spawnDataAfter(self.dk_spawn, '_YOFF')
  if (y !== undefined) _YOFF = Number(y) // "_YOFF"+"-16" (decimal text in ZALiA)
  self.dl_YOFF = [0x00, 0x10, -0x10, -0x20, -0x30, -0x40, 0x00, 0x10] // $F0,$E0,$D0,$C0
  for (let _i = self.dl_YOFF.length - 1; _i >= 0; _i--) {
    self.dl_YOFF[_i] = (self.dl_YOFF[_i] as number) + 0x03 + _YOFF
  }
}
/** `Spawner_Rock_update()` — every 32 frames = 0.533s */
export function Spawner_Rock_update(self: SpRoA): void {
  GO_update_cam_vars(self)
  if (g.counter1 & 0x1f) return
  const _UIDX = avail_uidx_goc(4)
  if (_UIDX === UIDX_NULL) return
  const _IDX = rand(self) & 0x07
  let _DIR = -1
  if (_IDX & 0x01) _DIR = 1
  if (self.ver === 2) {
    const raft = platformRaft()
    if (raft) _DIR = -raft.hspd_dir // So it's not chasing PC
  }
  // WIDE VIEW
  let _XL = viewXC() + viewW_() * -_DIR
  _XL += 4 * _DIR
  _XL -= 8
  const _YT = pc().yt + (self.dl_YOFF[_IDX] as number) + 1
  goMgr.uIdxSwap_goc = _UIDX
  const r = GOC1_create(_XL, _YT, _DIR, self.projectile as ObjectName, self.projectile_ver)
  r.is_from_spawner = true
  GO_depth_init(r, (g.dl_TILE_DEPTHS.get(g.dl_TILE_DEPTHS.size - 1) as number) - 1) // in front of water & fg terrain
  r.hspd = (0x10 * r.facing_dir) & 0xff
}
/** `Spawner_Rock_end()` */
export function Spawner_Rock_end(_self: SpRoA): void {}

