import Phaser from 'phaser'
import { BootScene } from './assets/BootScene'
import { GameScene } from './GameScene'
import { registerPaletteSwapNode } from './render/paletteSwapFilter'

/** ZALiA's shipped wide view (`BASE_GAME_RESOLUTION_W/H`); the NES-native 256×240 is a sub-view of it. */
export const BASE_W = 480
export const BASE_H = 270

export function createGame(parent: HTMLElement): Phaser.Game {
  const game = new Phaser.Game({
    type: Phaser.AUTO,
    parent,
    width: BASE_W,
    height: BASE_H,
    pixelArt: true,
    backgroundColor: '#000000',
    input: { gamepad: true, keyboard: true },
    scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH, autoRound: true },
    scene: [BootScene, GameScene],
  })
  game.events.once(Phaser.Core.Events.READY, () => registerPaletteSwapNode(game.renderer))
  return game
}

export * from './assets/manifest'
export * from './render/paletteSwap'
export * from './storage/browserStorage'
export { BootScene, GameScene }
