/**
 * NIAO manager — ported from `NIAO_init.gml`, `NIAO_create.gml`, `NIAO_create2.gml`,
 * `NIAO_Room_Start.gml`, `NIAO_Room_End.gml`, `update_NIAO.gml`, `data_NIAO_1a.gml`.
 * Scene data keys: `<rm>_NIAO<i>_xy` (packed clm|row<<8), `_version`, `_init` (GM script index —
 * see gmIndex.generated.ts), `_pal_idx`, `_Data01..`.
 */
import { DEPTH_NIAO, PAGE_ROWS, STR_Data, STR_NIAO, STR_pal_idx, STR_version } from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { gmBool } from '../../nes/math8'
import { instanceExists, NOONE, type Ref } from '../../runtime/instance'
import { G, g, world } from '../../runtime/world'
import { installInstanceEnd } from '../game_object/go/lifecycle'
import { set_xlyt, update_draw_xy } from '../game_object/go/movement'
import { GO_init_palidx } from '../game_object/go/palette'
import { GO_depth_init } from '../game_object/go/sprite'
import { sign_ } from '../math'
import { viewXC, viewYC } from '../view/camera'
import { gmScriptName } from './gmIndex.generated'
import { NiaoObject } from './NiaoObject'
import { niaoInitScripts } from './registry'

export type NiaoInit = ((self: NiaoObject) => void) | string | number | 0 | undefined

/** Resolve an `_init` value (function, script name, or GM script index from the caches). */
export function resolveNiaoInit(init: NiaoInit): ((self: NiaoObject) => void) | undefined {
  if (!init) return undefined
  if (typeof init === 'function') return init
  const name = typeof init === 'number' ? gmScriptName(init) : init
  if (!name) throw new Error(`NIAO init script index ${init} is out of range`)
  const fn = niaoInitScripts[name]
  if (!fn) throw new Error(`NIAO init script ${name} is not registered`)
  return fn
}

/** `NIAO_init()` */
export function NIAO_init(self: NiaoObject): void {
  // init_vars_draw_1a / phys_1a / go_1a / go_4a are the class field defaults
  self.dk_spawn = undefined
  GO_depth_init(self, DEPTH_NIAO) // sets depth & depth_def
  // default GameObject draw YOff
  self.DRAW_YOFF = 0
}

/** `NIAO_create(xl, yt, version, init scr, *spawn datakey)` */
export function NIAO_create(
  xl: number,
  yt: number,
  ver: number,
  init: NiaoInit,
  spawnDk?: string,
): Ref<NiaoObject> {
  const self = world.register(new NiaoObject())
  installInstanceEnd(self)
  NIAO_init(self) // init vars
  self.xl = xl
  self.yt = yt
  self.ver = ver
  if (spawnDk !== undefined) self.dk_spawn = spawnDk
  const fn = resolveNiaoInit(init)
  if (fn) fn(self)
  if (instanceExists(self)) {
    set_xlyt(self, self.xl, self.yt)
    update_draw_xy(self)
    // DEV: debug_NIAO_spawn_1a() logging dropped
    if (!gmBool(self.ver)) self.ver = 1
    return self
  }
  return NOONE
}

/** `NIAO_create2(xl, yt, version, init scr)` — reuse the first free/dead slot of `g.dl_niao`. */
export function NIAO_create2(xl: number, yt: number, ver: number, init: NiaoInit): Ref<NiaoObject> {
  let inst: Ref<NiaoObject> = NOONE
  const dl = g.dl_niao
  for (let i = dl.size - 1; i >= 0; i--) {
    const cur = dl.get(i) as Ref<NiaoObject> | 0 | undefined
    if (cur === undefined) continue
    if (cur === NOONE || (cur && instanceExists(cur) && cur.state === 0)) {
      inst = NIAO_create(xl, yt, ver, init)
      if (cur !== NOONE && cur) cur.destroy()
      dl.set(i, inst)
      break
    }
  }
  return inst
}

/** `NIAO_Room_Start()` — (re)create every NIAO declared for `g.rm_name` into the `g.dl_niao` slots. */
export function NIAO_Room_Start(): void {
  const dl = g.dl_niao
  for (let i = dl.size - 1; i >= 0; i--) {
    const cur = dl.get(i) as Ref<NiaoObject> | 0 | undefined
    if (cur !== undefined && cur !== 0 && instanceExists(cur)) cur.destroy()
    dl.set(i, NOONE)
    //
    const dk = g.rm_name + STR_NIAO + String(i)
    const data = g.dm_rm.get(`${dk}_xy`) as number | undefined
    if (data === undefined) continue
    const x = ((data >> 0) & 0xff) << 3
    let y = (data >> 8) & 0xff
    if (g.view_lock_rm & 0xc) y = g.rm_rows - PAGE_ROWS + y
    y = y << 3
    const ver = g.dm_rm.get(dk + STR_version) as number
    const init = g.dm_rm.get(`${dk}_init`) as number | string
    const pi = g.dm_rm.get(dk + STR_pal_idx) as number | undefined
    const inst = NIAO_create(x, y, ver, init, dk)
    if (inst !== NOONE && instanceExists(inst)) {
      inst.state = 1
      dl.set(i, inst)
      // GML: `if (state && !is_undefined(_pi) && _pi+1)` → a palette index of -1 means "none"
      if (pi !== undefined && pi + 1) GO_init_palidx(inst, pi)
    }
  }
}

/** `NIAO_Room_End()` */
export function NIAO_Room_End(): void {
  const dl = g.dl_niao
  for (let i = dl.size - 1; i >= 0; i--) {
    const cur = dl.get(i) as Ref<NiaoObject> | 0 | undefined
    if (cur) {
      cur.scr_room_end?.(cur)
      cur.destroy()
    }
    dl.set(i, 0)
  }
}

/** `update_NIAO()` — per-frame update of the NIAO slots plus the rain scroller. */
export function update_NIAO(): void {
  const dl = g.dl_niao
  for (let i = dl.size - 1; i >= 0; i--) {
    const cur = dl.get(i) as Ref<NiaoObject> | 0 | undefined
    if (cur) {
      // GML `with(){ if(!state) break; }` — `break` inside `with` leaves the with block only.
      if (!gmBool(cur.state)) continue
      cur.scr_update?.(cur)
      cur.scr_udp?.(cur)
    }
  }
  if (G.Rain_is_active) {
    G.Rain_pi = G.PI_MOB_BLU
    G.Rain_xoff %= G.Rain1_LOOP_SIZE
    G.Rain_xoff += G.Rain_speed_x * G.Rain_direction_x
    G.Rain_yoff %= G.Rain1_LOOP_SIZE
    G.Rain_yoff += G.Rain_speed_y * G.Rain_direction_y
    G.Rain_xl = Math.trunc(Math.abs(viewXC()) / G.Rain1_LOOP_SIZE_) // num of `Rain1_LOOP_SIZE_` away from left room edge (0)
    G.Rain_xl += G.Rain_xl & 0x1 // round up if odd
    G.Rain_xl *= G.Rain1_LOOP_SIZE_
    G.Rain_xl *= sign_(viewXC()) // rain xc. rounded to nearest `Rain1_LOOP_SIZE`
    G.Rain_xl -= G.Rain1_srf_W >> 1 // rain home xl
    G.Rain_xl += Math.floor(G.Rain_xoff) // rain xl
    G.Rain_yt = Math.trunc(Math.abs(viewYC()) / G.Rain1_LOOP_SIZE_) // num of `Rain1_LOOP_SIZE_` away from top room edge (0)
    G.Rain_yt += G.Rain_yt & 0x1 // round up if odd
    G.Rain_yt *= G.Rain1_LOOP_SIZE_
    G.Rain_yt *= sign_(viewYC()) // rain yc. rounded to nearest `Rain1_LOOP_SIZE`
    G.Rain_yt -= G.Rain1_srf_H >> 1 // rain home yt
    G.Rain_yt += Math.floor(G.Rain_yoff) // rain yt
  }
}

/**
 * `data_NIAO_1a(instance key, xy data, version, init scr, *pal idx, *data, ..)` — room-data writer.
 * xy data example $1352: x = ($1352&$FF)<<3, y = ($1352>>8)<<3
 */
export function data_NIAO_1a(
  key: string,
  xy: number,
  version: number,
  init: NiaoInit,
  ...rest: unknown[]
): void {
  const m = g.dm_rm as unknown as Map<string, unknown>
  m.set(`${key}_xy`, xy)
  m.set(key + STR_version, version)
  m.set(`${key}_init`, typeof init === 'function' ? init.name : init)
  let a = 0
  if (rest.length > a) m.set(key + STR_pal_idx, rest[a++])
  else m.set(key + STR_pal_idx, -1)
  for (let i = 0; a + i < rest.length; i++) m.set(key + STR_Data + hexStr(i + 1), rest[a + i])
}
