/** `Cutscene_GameEnd_1B_update()` */
export function Cutscene_GameEnd_1B_update(self: Cutscene_GameEnd_1B): void {
  g.cutscene = 1
  if (g.ChangeRoom_timer > 0) return
  const pc = G.pc
  const dgC = self.dg_curtain as DsGrid<number>
  const dgCR = self.dg_CREDITS as DsGrid<number | string>
  const cr = (x: number, y: number) => dgCR.get(x, y) as number
  const crs = (x: number, y: number, v: number | string) => dgCR.set(x, y, v)
  g.pc_lock = PC_LOCK_ALL
  self.THE_END_can_draw = 0
  self.triforce_can_draw = 0
  if (g.gui_state !== g.gui_state_NONE) {
    const dw = g.DIALOGUE_WINDOW // DialogueWindow
    dw.drawX = viewXC() - ((dw.CLMS >> 1) << 3)
    dw.drawX = (dw.drawX >> 3) << 3
    dw.drawY = pc.yt - (dw.rows << 3)
    dw.drawY -= 0x01 << 3 // padding
    dw.drawY = (dw.drawY >> 3) << 3
  }
  if (!gmBool(g.cutscene_part)) g.cutscene_part = self.SUB_STATE_INIT_1A
  switch (g.cutscene_part) {
    case self.SUB_STATE_INIT_1A: {
      if (gmBool(g.cutscene_timer)) break
      g.pc_lock = PC_LOCK_ALL
      g.view_lock_rm = 0xf
      g.view_lock |= g.view_lock_rm
      set_camera_xy(g.rm_w_ - viewW_(), viewYT())
      self.GROUND_Y = (pc.spawn_yt >> 3) << 3
      self.GROUND_Y = get_ground_y(viewXC(), self.GROUND_Y, 1, self.GROUND_Y + PC_H)
      self.CEILNG_Y = find_row_solid(TID_SOLID1, viewXC() >> 3, (self.GROUND_Y >> 3) - 4, -1, 0, 0x08)
      self.CEILNG_Y = (self.CEILNG_Y + 1) << 3
      // ---------------------------------------------------
      let _CURTAIN_DEPTH: number = DEPTH_FG2
      for (let _i = g.dl_pal_swap_depths.size - 1; _i >= 0; _i--) {
        const _depth = g.dl_pal_swap_depths.get(_i) as number
        const _idx = g.dl_TILE_DEPTHS.findIndex(_depth)
        if (!(_idx + 1)) continue
        let _dk = g.dl_TILE_DEPTH_NAMES.get(_idx) as string // depth name:  "BG01", "BG02", .. "FG08"
        _dk += STR_Depth + STR_Layer + STR_Name
        const _layer_name = val(g.dm_tile_file.get(_dk), 'UNDEFINED') as string
        // FIDELITY: GML had `string_pos(_layer_name, 'CURTAIN')` (args swapped); intent is "layer name contains CURTAIN".
        if (!_layer_name.includes('CURTAIN')) continue
        _CURTAIN_DEPTH = _depth
        break
      }
      // ---------------------------------------------------
      const _X = self.CURTAIN_CLM << 3
      const _Y_START = (viewYC() >> 3) << 3
      for (let _i = self.CURTAIN_CLMS - 1; _i >= 0; _i--) {
        const _x = _X + (_i << 3)
        dgC.set(_i, 5, _CURTAIN_DEPTH) //  DEPTH
        let _y = get_ground_y(_x, _Y_START, 1, pc.spawn_yt + PC_H) //  GROUND ROW
        _y = _y >> 3
        dgC.set(_i, 4, _y) // ground row
        dgC.set(_i, 3, find_row_solid(TID_SOLID1, _x >> 3, _y - 4, -1, 0, 0x08) + 1) //  ROW UNDER CEILNG
        dgC.set(_i, 2, (dgC.get(_i, 3) as number) + 4) //  ROW UNDER CURTAIN
        if (self.curtain_lowest_row < (dgC.get(_i, 2) as number))
          self.curtain_lowest_row = dgC.get(_i, 2) as number
        dgC.set(_i, 1, 0) //  GOAL REACHED
        // STATE/SIDE: 0: NOT curtain clm,  1: left side of curtain,  2: right side of curtain
        _y = (dgC.get(_i, 2) as number) - 2 // ROW UNDER CURTAIN → move up to a curtain tile
        _y = _y << 3
        const _tsrc = tile_layer_get_tsrc(_CURTAIN_DEPTH, _x, _y)
        if (_tsrc + 1)
          dgC.set(_i, 0, 1 + (_tsrc & 0x1)) // 1: left, 2: right
        else dgC.set(_i, 0, 0) // 0: clm doesn't have curtain
      }
      g.cutscene_timer = 0
      g.cutscene_part = self.SUB_STATE_INIT_2A
      break
    }
    case self.SUB_STATE_INIT_2A: {
      if (gmBool(g.cutscene_timer)) break
      for (const z of instancesNamed('Zelda')) {
        // Wait for Zelda inst before going to next sub_state.
        const _X = g.rm_w_
        set_camera_xy(_X - viewW_(), viewYT())
        self.can_draw_L_and_Z = true
        z.xScale = -1
        set_xy(z, _X + 8 * -z.xScale, z.y)
        pc.xScale = -z.xScale
        set_xy(pc, z.x + 0x10 * z.xScale, z.y)
        if (gofDeps.pc_is_cucco()) {
          set_xy(pc, z.x - 0x0b, z.y - 0x03)
          z.depth = pc.depth - 1
        }
        z.sub_state = z.SUB_STATE_TALK1 // So correct sprite is drawn
        g.cutscene_timer = self.DUR1
        g.cutscene_part = self.SUB_STATE_DLOG_1A
      }
      break
    }
    case self.SUB_STATE_DLOG_1A: {
      // TRIGGER DIALOGUE
      if (gmBool(g.cutscene_timer)) break
      for (const z of instancesNamed('Zelda')) {
        g.gui_state = g.gui_state_DIALOGUE1
        g.dialogue_source = z
        z.dialogue_datakey = '0Z_00_'
        z.dialogue_ver = 'A'
        z.is_talking = true
        z.talked_to_count++
        z.sub_state = z.SUB_STATE_TALK1
      }
      g.DIALOGUE_WINDOW.depth = self.DLG_DEPTH
      g.cutscene_timer = 4 // wait for dlg window to build
      g.cutscene_part = self.SUB_STATE_DLOG_1B
      break
    }
    case self.SUB_STATE_DLOG_1B: {
      // WRITING DIALOGUE
      if (gmBool(g.cutscene_timer)) break
      if (!gmBool(g.DIALOGUE_WINDOW.writ_char_pos)) break
      if (gofDeps.Zelda_update_talk_sound()) break // Updates the talk sound.
      g.cutscene_timer = self.DUR1
      g.cutscene_part = self.SUB_STATE_CURT_1B
      break
    }
    case self.SUB_STATE_CURT_1B: {
      // CURTAINS MOVE DOWN — curtains stop when covering half of Zelda and PC
      if (gmBool(g.cutscene_timer)) break
      if (!Cutscene_GameEnd_1B_update_1a(self, 3, 1, 2)) break
      g.cutscene_timer = self.DUR1 // Kiss delay.
      g.cutscene_part = self.SUB_STATE_KISS_1A
      break
    }
    case self.SUB_STATE_KISS_1A: {
      // DELAY KISS
      if (gmBool(g.cutscene_timer)) break // Kiss delay
      // Move in for kiss.
      const _DIST = 4
      set_xy(pc, pc.x + _DIST * pc.xScale, pc.y)
      for (const z of instancesNamed('Zelda')) {
        set_xy(z, z.x + _DIST * z.xScale, z.y)
        z.sub_state = z.SUB_STATE_KISS
      }
      g.cutscene_timer = self.DUR1 // 'THE END' text delay.
      g.cutscene_part = self.SUB_STATE_OTHR_1A
      break
    }
    case self.SUB_STATE_OTHR_1A: {
      // 'THE END' TEXT - DELAY
      if (gmBool(g.cutscene_timer)) break
      g.cutscene_timer = 0
      g.cutscene_part = self.SUB_STATE_OTHR_1B
      break
    }
    case self.SUB_STATE_OTHR_1B: {
      // ADD 'THE END' TEXT
      self.THE_END_can_draw = 1
      if (gmBool(g.cutscene_timer)) break
      stopMusInst()
      const _BODY = get_audio_theme_track(dk_Credits)
      const _INTRO = get_audio_theme_track_intro(_BODY)
      const _MUSIC = _INTRO === _BODY ? _BODY : _INTRO
      if (_INTRO !== _BODY) Audio.mus_rm_intr = _INTRO
      Audio.mus_rm_body = _BODY
      const _will_loop = gmBool(val(Audio.dm.get(Audio.audio_get_name(_MUSIC) + STR_Loop), _INTRO === _BODY))
      if (!_will_loop) {
        Audio.mus_rm_intr = 0
        Audio.mus_rm_body = 0
      }
      aud_play_sound(_MUSIC, Audio.PRIORITY_TOP, _will_loop, -1, dk_Credits)
      g.cutscene_timer = self.DUR1
      g.cutscene_part = self.SUB_STATE_CURT_2A
      break
    }
    case self.SUB_STATE_CURT_2A: {
      // DELAY CURTAINS MOVE DOWN
      self.THE_END_can_draw = 1
      if (gmBool(g.cutscene_timer)) break
      g.cutscene_timer = 0
      g.cutscene_part = self.SUB_STATE_CURT_2B
      break
    }
    case self.SUB_STATE_CURT_2B: {
      // CURTAINS MOVE DOWN TO FLOOR
      self.THE_END_can_draw = 1
      if (gmBool(g.cutscene_timer)) break
      if (!Cutscene_GameEnd_1B_update_1a(self, 3, 1, 0)) break
      g.menu_state = g.DIALOGUE_WINDOW.SUB_STATE_CLOS1 // close dlg window
      self.can_draw_L_and_Z = false
      g.cutscene_timer = self.DUR1
      g.cutscene_part = self.SUB_STATE_CURT_3A
      break
    }
    case self.SUB_STATE_CURT_3A: {
      // DELAY CURTAINS MOVE UP. Make it so only the curtains between the 2 inner-most stone clms move up.
      if (gmBool(g.cutscene_timer)) break
      let _pillar_found = false
      let _dir = 1 // -1 left, 1 right
      const _IDX1 = dgC.width >> 1 // the middle-right curtain clm
      let _idx2 = _IDX1 - (gmBool(_dir) ? 0 : 1) // start at the left middle curtain if searching left
      for (let _i = 0; _i < 2; _i++) {
        // each dir search(right & left)
        for (let _j = 0; _j < _IDX1; _j++) {
          const _idx = _idx2 + _j * _dir
          if (_pillar_found) {
            dgC.set(_idx, 0, 0)
            continue
          }
          if (!gmBool(dgC.get(_idx, 0))) _pillar_found = true
        }
        _pillar_found = false
        _dir = -_dir // flip dirs
        _idx2 = _IDX1 - (gmBool(_dir) ? 0 : 1)
      }
      g.DIALOGUE_WINDOW.depth = self.DLG_DEPTH_DEF
      g.cutscene_timer = 0
      g.cutscene_part = self.SUB_STATE_CURT_3B
      break
    }
    case self.SUB_STATE_CURT_3B: {
      // CURTAINS MOVE UP
      if (gmBool(g.cutscene_timer)) break
      if (!Cutscene_GameEnd_1B_update_1a(self, 3, -1, 4)) break
      g.cutscene_timer = self.DUR1 + 2 // delay drawing "STAFF"
      g.cutscene_part = self.SUB_STATE_CRDT_1A
      break
    }
    case self.SUB_STATE_CRDT_1A: {
      // CREDITS DELAY
      if (gmBool(g.cutscene_timer)) break
      change_pal(strReplaceAt(p.pal_rm_new, self.CREDITS_STAF_PAL_POS, self.PAL_LEN, self.CREDITS_STAF_PAL1))
      crs(0, 3, 1) // allow "STAFF" text to draw
      crs(0, 2, self.CREDITS_DUR3) // sequence timer
      crs(0, 0, 1) // credits idx
      g.cutscene_timer = 0
      g.cutscene_part = self.SUB_STATE_CRDT_1B
      break
    }
    case self.SUB_STATE_CRDT_1B: {
      // CREDITS SEQUENCE
      if (gmBool(g.cutscene_timer)) break
      const titl = (pal: string) =>
        change_pal(strReplaceAt(p.pal_rm_new, self.CREDITS_TITL_PAL_POS, self.PAL_LEN, pal))
      const name = (pal: string) =>
        change_pal(strReplaceAt(p.pal_rm_new, self.CREDITS_NAME_PAL_POS, self.PAL_LEN, pal))
      if (gmBool(cr(0, 2))) {
        // timer
        crs(0, 2, cr(0, 2) - 1)
        if (!gmBool(cr(0, 2))) {
          if (gmBool(cr(0, 3)) && !(cr(0, 3) & 0x1) && cr(0, 1) === 0) crs(0, 3, cr(0, 3) + 1) // STAFF text faded out
          crs(0, 1, cr(0, 1) + 1) // state
          switch (cr(0, 1)) {
            // FADE IN TITLE
            case 1:
              crs(0, 4, 1)
              titl(self.CREDITS_TITL_PAL1)
              crs(0, 2, self.CREDITS_DUR2)
              break
            case 2:
              titl(self.CREDITS_TITL_PAL2)
              crs(0, 2, self.CREDITS_DUR2)
              break
            case 3:
              titl(self.CREDITS_TITL_PAL3)
              crs(0, 2, self.CREDITS_DUR2)
              break
            case 4:
              titl(self.CREDITS_TITL_PAL4)
              crs(0, 2, self.CREDITS_DUR1)
              break // Delay name text
            // FADE IN NAME
            case 5:
              crs(0, 5, 1)
              name(self.CREDITS_NAME_PAL1)
              crs(0, 2, self.CREDITS_DUR2)
              break
            case 6:
              name(self.CREDITS_NAME_PAL2)
              crs(0, 2, self.CREDITS_DUR2)
              break
            case 7:
              name(self.CREDITS_NAME_PAL3)
              crs(0, 2, self.CREDITS_DUR2)
              break
            case 8:
              name(self.CREDITS_NAME_PAL4)
              crs(0, 2, self.CREDITS_DUR1)
              if (cr(0, 0) === self.CREDITS_COUNT1 - 2) crs(0, 3, 0) // STAFF text state
              if (cr(0, 0) === self.CREDITS_COUNT1 - 1) crs(0, 0, self.CREDITS_COUNT1) // credits idx
              break
            // FADE OUT TITLE & NAME
            case 9:
              titl(self.CREDITS_TITL_PAL3)
              name(self.CREDITS_NAME_PAL3)
              crs(0, 2, self.CREDITS_DUR2)
              break
            case 10:
              titl(self.CREDITS_TITL_PAL2)
              name(self.CREDITS_NAME_PAL2)
              crs(0, 2, self.CREDITS_DUR2)
              if (cr(0, 0) + 1 < self.CREDITS_COUNT1 && dgCR.get(cr(0, 0), 5) !== dgCR.get(cr(0, 0) + 1, 5))
                crs(0, 3, cr(0, 3) + 1) // next credit's staff is diff
              break
            case 11:
              titl(self.CREDITS_TITL_PAL1)
              name(self.CREDITS_NAME_PAL1)
              crs(0, 2, self.CREDITS_DUR2)
              break
            case 12:
              crs(0, 0, cr(0, 0) + 1) // credits idx
              crs(0, 1, 0) // state/case
              crs(0, 2, self.CREDITS_DUR3) // timer
              crs(0, 4, 0) // 4: job title can draw
              crs(0, 5, 0)
              break
          }
        }
      }
      let _CAN_SKIP_TO_END = false
      if (gmBool(input.Pause_pressed) && (cr(0, 0) > 1 || cr(0, 1) >= 9)) {
        _CAN_SKIP_TO_END = true
        titl(self.CREDITS_TITL_PAL4)
        name(self.CREDITS_NAME_PAL4)
      }
      if (cr(0, 0) >= self.CREDITS_COUNT1 || _CAN_SKIP_TO_END) {
        crs(0, 1, 0) // state/case
        crs(0, 3, 0) // "STAFF" can draw
        crs(0, 4, 1) // 4: job title can draw
        crs(0, 5, 1) // 5: name can draw
        crs(0, 0, self.CREDITS_COUNT1 - 1) // keep drawing 'PRESS START TO REPLAY'
        g.cutscene_timer = 0x20
        g.cutscene_part = self.SUB_STATE_TRIF_1A
      }
      break
    }
    case self.SUB_STATE_TRIF_1A: {
      // ADD TRIFORCE
      if (gmBool(g.cutscene_timer)) break
      self.triforce_can_draw = 1
      triforce_pal_update()
      g.cutscene_timer = 8
      g.cutscene_part = self.SUB_STATE_RPLY_1A
      break
    }
    case self.SUB_STATE_RPLY_1A: {
      // WAIT FOR USER INPUT
      self.triforce_can_draw = 1
      triforce_pal_update()
      if (gmBool(g.cutscene_timer)) break
      if (gmBool(input.Pause_pressed) || gmBool(input.Magic_pressed)) {
        stopMusInst()
        Audio.mus_rm_body = 0 // Prevent 'Wake Zelda' music from restarting.
        G.QuestTimer_state = 0
        spawn_data_set_default()
        if (gmBool(input.Pause_pressed)) startSecondQuest()
        g.cutscene_timer = self.DUR1
        g.cutscene_part = self.SUB_STATE_RSET_1A
      }
      break
    }
    case self.SUB_STATE_RSET_1A: {
      // SIMULATING NES RESET
      if (g.surf) g.surf.draw_clear_color = p.C_BLK1 // Surface object is adapter-side (may be NOONE)
      if (gmBool(g.cutscene_timer)) break
      goto_title_rm()
      return
    }
  }
  // ------------------------------------------------------------------------
  pc.can_draw_self = false
  if (self.can_draw_L_and_Z) {
    gofDeps.PC_set_behavior(pc, pc.behavior_POSE1)
    gofDeps.PC_udp(pc)
    pc.xScale = 1
  }
  for (const z of instancesNamed('Zelda')) {
    z.can_draw_self = false
    if (!self.can_draw_L_and_Z) break
    update_EF11(z)
    z.xScale = -pc.xScale
    // `Cutscene_GameEnd_1B_update.gml:998` — `with(global.pc) other.depth = depth-1`: inside the inner
    // `with`, `other` is Zelda and `depth` is the PC's, so it is *Zelda* that goes one in front.
    z.depth = pc.depth - 1
  }
}

/** The "START - 2ND QUEST" branch of `SUB_STATE_RPLY_1A`: re-initialise the save for quest 2, carrying stats over. */
function startSecondQuest(): void {
  const _FILE_NUM = f.file_num
  const _QUEST_NUM = 2
  const _Cucco_SKILLS = f.Cucco_skills
  const _CuccoSpell2_ACQUIRED = g.CuccoSpell2_Acquired
  const _SKILLS = f.skills
  const _SPELLS = f.spells
  const _ATTACK_LEVEL = f.level_atk
  const _MAGIC_LEVEL = f.level_mag
  const _LIFE_LEVEL = f.level_lif
  f.game_completed_count++
  init_new_save_file(_FILE_NUM, _QUEST_NUM)
  f.Cucco_skills = _Cucco_SKILLS
  g.CuccoSpell2_Acquired = _CuccoSpell2_ACQUIRED
  if (_CuccoSpell2_ACQUIRED)
    set_saved_value(_FILE_NUM, `${STR_Cucco + STR_Spell}02${STR_Acquired}`, _CuccoSpell2_ACQUIRED)
  if (_Cucco_SKILLS) set_saved_value(_FILE_NUM, STR_Skill + STR_Cucco, _Cucco_SKILLS)
  f.skills = _SKILLS
  f.spells = _SPELLS
  f.level_atk = _ATTACK_LEVEL
  f.level_mag = _MAGIC_LEVEL
  f.level_lif = _LIFE_LEVEL
  set_saved_value(_FILE_NUM, f.SDNAME_skills, _SKILLS)
  set_saved_value(_FILE_NUM, f.SDNAME_spells, _SPELLS)
  set_saved_value(_FILE_NUM, f.SDNAME_level_atk, _ATTACK_LEVEL)
  set_saved_value(_FILE_NUM, f.SDNAME_level_mag, _MAGIC_LEVEL)
  set_saved_value(_FILE_NUM, f.SDNAME_level_lif, _LIFE_LEVEL)
  f.cont_run_town_num = 0
  set_saved_value(_FILE_NUM, STR_Save + STR_Town + STR_Num, f.cont_run_town_num)
  let _SEED = get_saved_value(_FILE_NUM, get_file_seed_dk(_FILE_NUM, _QUEST_NUM), undefined as never) as
    | number
    | undefined
  if (_SEED === undefined) {
    // Just in case a value wasn't found.
    _SEED = val(f.dm_rando.get(STR_Rando + STR_Seed), RUN_RANDOMIZATION_SEED) as number
    // `>>> 0`: GM's bitwise ops are not signed 32-bit, so the flipped seed stays positive there.
    if (f.quest_num === 1) _SEED = (_SEED ^ 0xffffffff) >>> 0
  }
  // Delete Rando Hints
  g.dm_RandoHintsRecorder.clear()
  const _RANDO_DATA_FILE_NAME = `${f.dl_FILE_NAME_PREFIX.get(_FILE_NUM - 1) + STR_Rando + STR_Data}.txt`
  const text = world.storage.readText(_RANDO_DATA_FILE_NAME)
  if (text !== undefined) {
    const _dm_rando_full = json_decode(text)
    if (_dm_rando_full !== -1) {
      _dm_rando_full.delete(STR_Found + STR_Hint)
      world.storage.writeText(_RANDO_DATA_FILE_NAME, json_encode(_dm_rando_full))
    }
  }
  if (gmBool(val(f.dm_save_file.get(dk_CanUseStartWithSelections)))) {
    const settings = f.dm_save_file_settings
    let _items = get_saved_value(_FILE_NUM, f.SDNAME_items, 0) as number
    _items |= val(settings.get(STR_File + STR_Start + STR_Items)) as number
    if (_items) set_saved_value(_FILE_NUM, f.SDNAME_items, _items)
    const pieces = (count: number, per: number) => {
      let _val = ''
      for (let _i = 1; _i <= count; _i++) for (let _j = 1; _j <= per; _j++) _val += hexStr(_i) + hexStr(_j)
      return _val
    }
    const _START_CONT_HP = val(settings.get(STR_File + STR_Start + STR_Container + STR_HP)) as number
    if (_START_CONT_HP >= cont_cnt_hp())
      set_saved_value(_FILE_NUM, f.SDNAME_cont_pieces_hp, pieces(_START_CONT_HP, f.CONT_PIECE_PER_HP))
    const _START_CONT_MP = val(settings.get(STR_File + STR_Start + STR_Container + STR_MP)) as number
    if (_START_CONT_MP >= cont_cnt_mp())
      set_saved_value(_FILE_NUM, f.SDNAME_cont_pieces_mp, pieces(_START_CONT_MP, f.CONT_PIECE_PER_MP))
    const _DOLL_COUNT = val(settings.get(STR_File + STR_Start + STR_Dolls)) as number
    if (_DOLL_COUNT) {
      for (let _i = 1; _i <= _DOLL_COUNT; _i++) {
        const _item_id = f.dm_1up_doll.get(hexStr(_i) + STR_Item + STR_ID)
        if (_item_id !== undefined) f.dm_1up_doll.set(_item_id + STR_Acquired, 1)
      }
      set_saved_value(_FILE_NUM, f.SDNAME_linkDolls, json_encode(f.dm_1up_doll as never))
    }
  }
  gofDeps.Rando_randomize_file(_FILE_NUM, _QUEST_NUM, _SEED, json_encode(f.dm_save_file_settings as never))
}

/**
 * `Cutscene_GameEnd_1B_update_1a(speed, dir, end pad)` — curtains slowly falling / rising.
 * speed: 0 every frame, 1 every 2, 2 every 4, 3 every 8… Returns true when all curtains reached their goal.
 */
export function Cutscene_GameEnd_1B_update_1a(
  self: Cutscene_GameEnd_1B,
  speed: number,
  dir: number,
  endPad: number,
): boolean {
  const _TIMING = 1 << speed
  // FIDELITY: GML `g.counter1&_TIMING-1` — GML precedence gives `g.counter1 & (_TIMING-1)`? No: `-` binds tighter
  // than `&` in GML too, so this is `counter1 & (_TIMING - 1)`.
  if (g.counter1 & (_TIMING - 1)) return false
  const _DIR = sign_(dir)
  const _END_PAD = endPad
  const dgC = self.dg_curtain as DsGrid<number>
  const dl = self.dl_curtain_tsrc as DsList<number>
  let _ts: string | 0 = self.CURTAIN_TS
  let _tsrc = 0
  self.curtain_frame += _DIR
  if (!self.curtain_frame) self.curtain_frame = self.CURTAIN_FRAMES
  else if (self.curtain_frame > self.CURTAIN_FRAMES) self.curtain_frame = 1
  // _C1: A row change up or down will happen this frame
  const _C1 =
    (gmBool(_DIR) && self.curtain_frame === 1) ||
    (!gmBool(_DIR) && self.curtain_frame === self.CURTAIN_FRAMES)
  let _complete = true
  for (let _i = (self.CURTAIN_CLMS >> 1) - 1; _i >= 0; _i--) {
    const _idx = _i << 1
    if (!gmBool(dgC.get(_idx, 0)) || gmBool(dgC.get(_idx, 1))) continue // NOT a curtain clm / reached goal
    // If moving up, this will wait for lower curtain to catch up.
    if (!gmBool(_DIR) && (dgC.get(_idx, 2) as number) < self.curtain_lowest_row) continue
    if (
      gmBool(_DIR) &&
      self.curtain_frame === 1 &&
      (dgC.get(_idx, 2) as number) >= (dgC.get(_idx, 4) as number)
    ) {
      // Don't go past ground.
      dgC.set(_idx, 1, 1)
      dgC.set(_idx + 1, 1, 1)
      continue
    }
    // CHANGE TILES
    const _depth = dgC.get(_idx, 5) as number
    const _x = (self.CURTAIN_CLM + _idx) << 3
    if (_C1) {
      // Row change up or down. Tile change 2 rows
      if (gmBool(_DIR))
        _ts = self.CURTAIN_TS // Moving down.
      else _ts = 0 // Moving up. 0: Only delete the tile.
      _tsrc = dl.get(0) as number // Mid curtain graphic
      let _y = (dgC.get(_idx, 2) as number) - 1 // curtain btm row
      _y = _y << 3
      tile_change_1a(_depth, _x, _y, _ts, _tsrc)
      tile_change_1a(_depth, _x + 8, _y, _ts, _tsrc + 1)
      dgC.set(_idx, 2, (dgC.get(_idx, 2) as number) + _DIR)
      dgC.set(_idx + 1, 2, (dgC.get(_idx + 1, 2) as number) + _DIR)
    }
    _ts = self.CURTAIN_TS
    _tsrc = dl.get(self.curtain_frame) as number
    let _y = (dgC.get(_idx, 2) as number) - 1
    _y = _y << 3
    tile_change_1a(_depth, _x, _y, _ts, _tsrc)
    tile_change_1a(_depth, _x + 8, _y, _ts, _tsrc + 1)
    // CHECK IF COMPLETE
    if (self.curtain_frame === self.CURTAIN_FRAMES) {
      const row = dgC.get(_idx, 2) as number
      if (gmBool(_DIR)) {
        // MOVING DOWN
        if (row >= (dgC.get(_idx, 4) as number) || row >= (self.GROUND_Y >> 3) - _END_PAD) {
          dgC.set(_idx, 1, 1)
          dgC.set(_idx + 1, 1, 1)
          continue
        }
      } else {
        // MOVING UP
        if (row <= (dgC.get(_idx, 3) as number) + 4 || row <= (self.CEILNG_Y >> 3) + _END_PAD) {
          dgC.set(_idx, 1, 1)
          dgC.set(_idx + 1, 1, 1)
          continue
        }
      }
    }
    _complete = false // NOT all curtains have reached their goal
  }
  // if all curtain reached goal, reset 'reached goal' to 0
  if (_complete) for (let _i = 0; _i < self.CURTAIN_CLMS; _i++) dgC.set(_i, 1, 0)
  if (_C1) {
    self.curtain_lowest_row = 0
    for (let _i = (self.CURTAIN_CLMS >> 1) - 1; _i >= 0; _i--) {
      const _idx = _i << 1
      if (gmBool(dgC.get(_idx, 0)) && !gmBool(dgC.get(_idx, 1))) {
        if (self.curtain_lowest_row < (dgC.get(_idx, 2) as number))
          self.curtain_lowest_row = dgC.get(_idx, 2) as number
      }
    }
  }
  return _complete
}

/** `Cutscene_GameEnd_1B_draw()` */
export function Cutscene_GameEnd_1B_draw(self: Cutscene_GameEnd_1B): void {
  const _ADJ1 = -(0x03 << 3) + 0x04
  if (gmBool(self.triforce_can_draw)) {
    let _x = viewXC() - (0x02 << 3)
    let _Y = self.GROUND_Y - (0x0e << 3)
    _Y += _ADJ1
    for (let _i = 0; _i < 3; _i++) {
      _x += 8
      const _y = _i === 1 ? _Y - 0x10 : _Y
      draw_sprite_(self.TRIFORCE_SPR, 0, _x, _y, p.triforce_pi)
    }
  }
  if (gmBool(self.THE_END_can_draw)) {
    const _DIST1 = 0xc
    const _DIST2 = 4 << 3
    const _X1 = g.rm_w_ - _DIST2 - _DIST1
    let _X2 = g.rm_w_ + _DIST2 - _DIST1
    _X2 -= 2 // Micro adjustment
    let _Y = self.GROUND_Y - (0x02 << 3)
    _Y += 3 // Micro adjustment
    draw_text_(_X1, _Y, 'THE', 0, self.THE_END_PI)
    draw_text_(_X2, _Y, 'END', 0, self.THE_END_PI)
  }
  const dgCR = self.dg_CREDITS as DsGrid<number | string>
  const idx = dgCR.get(0, 0) as number
  if (gmBool(idx)) {
    // credits idx
    const _LAST = idx === self.CREDITS_COUNT1 - 1
    const _ADJ = -((0x04 << 3) + 0x08)
    const _Y1 = self.GROUND_Y - (0x11 << 3) - 0x02
    const _Y2 = self.GROUND_Y - (0x10 << 3) + _ADJ1
    let _y = _LAST ? _Y2 : _Y1
    if ((dgCR.get(0, 3) as number) & 0x1) {
      // "STAFF" can draw
      const _text = dgCR.get(idx, 5) as string
      let _x = viewXC()
      _x -= (_text.length << 3) >> 1
      draw_text_(_x, _y, _text, 0, self.CREDITS_STAF_PI)
    }
    if (gmBool(dgCR.get(0, 4)) && typeof dgCR.get(idx, 0) === 'string') {
      // 4: job title can draw
      const _x = self.CREDITS_CLM2 << 3
      if (_LAST) _y += 0x04 << 3
      else _y += 0x03 << 3
      draw_text_(_x, _y, dgCR.get(idx, 0) as string, 0, self.CREDITS_TITL_PI)
    }
    if (gmBool(dgCR.get(0, 5))) {
      // 5: name can draw
      let _x = self.CREDITS_CLM1 << 3
      if (_LAST) _x += _ADJ
      else _x -= (0x02 << 3) + 0x04
      const _X1 = _x
      for (let _i = 1; _i < self.CREDITS_COUNT2 - 2; _i++) {
        const _text = dgCR.get(idx, _i)
        if (_text === 0) break
        _x = _X1
        if (gmBool(dgCR.get(idx, 6))) _x = viewXC() - ((String(_text).length << 3) >> 1) // indicator to center text
        _y += 0x02 << 3
        draw_text_(_x, _y, _text as string, 0, self.CREDITS_NAME_PI)
      }
    }
  }
  if (gmBool(self.triforce_can_draw)) {
    const _TEXT1 = '-CLEAR QUEST TIME-'
    const font = G.dl_game_font.get(G.game_font_idx) as string
    let _x = viewXC()
    _x -= (sprite_get_width(font) * _TEXT1.length) >> 1
    let _y = self.GROUND_Y - (0x6 << 3)
    draw_text_(_x, _y, _TEXT1)
    _x = viewXC()
    _x -= (sprite_get_width(font) * G.QuestTimer_text.length) >> 1
    _y += sprite_get_height(font)
    _y += 0x4
    draw_text_(_x, _y, G.QuestTimer_text, 0, self.CREDITS_STAF_PI)
  }
}

/** `Cutscene_GameEnd_1B_end()` */
export function Cutscene_GameEnd_1B_end(self: Cutscene_GameEnd_1B): void {
  self.dl_curtain_tsrc = undefined
  self.dg_curtain = undefined
  self.dg_CREDITS = undefined
}
