/** `Projectile_init()` — scr_init1 for every hostile projectile. */
export function Projectile_init(self: GameObjectC): void {
  GO_sprite_init(self, 'spr_Placement_08x16')
  GO_init_palidx(self, GG().PI_MOB_BLU)
  GO_depth_init(self, DEPTH_PC_MAIN - 1) // (ZALiA sets DEPTH_PROJECTILE then overrides with DEPTH_PC_MAIN-1)
  self.DRAW_YOFF = 1 // +1 for 1 pixel in ground
  self.update_idx = addToProjectileList(self)
  self.scr_step = Projectile_step as (self: GameObject) => void
}

/** `Projectile_step()` — state NORMAL runs scr_update; EXPLODE is the D55A disintegration animation. */
export function Projectile_step(self: GameObjectC): void {
  if (!self.state) return
  GO_update_cam_vars(self)
  switch (self.state) {
    case self.state_NORMAL: {
      if (self.scr_update) self.scr_update(self)
      break
    }
    case self.state_EXPLODE: {
      // D57D: disintegrating
      if (self.disintegrate_counter < 0x80) break
      // D55A
      self.can_draw_self = true
      self.disintegrate_counter = (self.disintegrate_counter + 1) & 0xff
      self.scr_udp = undefined
      Projectile_udd(self)
      if (isProjSprAdjFrame(self)) self.xScale = 1
      else self.xScale = self.facing_dir
      self.yScale = 1
      if (self.disintegrate_counter & 8) self.sprite = 'spr_Projectile_Disintegrate2'
      else self.sprite = 'spr_Projectile_Disintegrate1'
      if (!self.disintegrate_counter) self.state = 0
      break
    }
  }
  if (gp().mod_destroy_go_on_death && !self.state) GO_destroy_1a(self)
}

/** `Projectile_update_1a(can despawn if off screen horizontally)` — DED4: move, then collide or despawn. */
export function Projectile_update_1a(self: GameObjectC, canDespawnHor: boolean | number): void {
  // MOD. Prevent from doing endless wave
  if ((abs8b(self.vspd) & 0x7f) >= self.vspd_MAX) self.vspd = byte(self.vspd_MAX * sign_(self.vspd < 0x80))
  // DED4
  updateX(self)
  updateY(self)
  GO_update_cam_vars(self)
  if (deps.ocsHV1(self)) {
    // ocsHV1: if (any width AND any height) are in ocs area
    Projectile_udd(self)
    Projectile_collision_2a(self) // REFLECTed projectile colision
    Projectile_collision_1a(self)
    return
  }
  if (canDespawnHor || !deps.ocsV1(self)) self.state = 0 // ocsV1: any height is w/in ocs area height
}

/** `Projectile_update_3a(can despawn if off screen horizontally)` — vspd_adj then update_1a. */
export function Projectile_update_3a(self: GameObjectC, canDespawnHor: boolean | number): void {
  self.vspd = (self.vspd + self.vspd_adj) & 0xff
  Projectile_update_1a(self, canDespawnHor)
}

/** `Projectile_udd()` — draw properties + palette, incl. the reflected blink and dark-room visibility mod. */
export function Projectile_udd(self: GameObjectC): void {
  GO_udp_1(self) // drawX=x; drawY=y; xScale=facing_dir;
  self.palidx_base = self.palidx_def
  if (self.scr_udp) self.scr_udp(self)
  update_draw_xy(self)
  if (deps.rm_pal_qual_lit() || GO_pal_qual_lit(self)) {
    self.palidx_base += pp().PI_LIT1
  } else {
    if (!(gp().counter1 & 0x3) && self.objectName !== 'RisingBubble') {
      self.palidx_base = GG().PI_BGR2 // extra visibility in dark rooms
    }
    self.palidx_base += pp().PI_DRK1
  }
  if (isProjSprAdjFrame(self)) {
    self.palidx_base = GG().PI_PC1 // Lit, even in dark rm
    // MOD (OG always reset the scale here)
    if (deps.rm_pal_qual_lit() || FIRE_OBJECTS.has(self.objectName)) {
      self.xScale = self.facing_dir
      self.yScale = 1
    }
  } else if (self.reflected && !(gp().counter1 & 0x2)) {
    // MOD. Make projectile blink if it has been reflected
    self.palidx_base = GG().PI_PC1 // Lit, even in dark rm
  }
  self.palidx = self.palidx_base
}

/** `Projectile_udd_1a()` — 975B (Bolo), 97A9 (Boomerang), AE30 (Mace2): spinning sprite via scale flips. */
export function Projectile_udd_1a(self: GameObjectC): void {
  self.can_draw_self = true
  if (gp().counter1 & 0x8) {
    self.xScale = 1
    self.yScale = 1
  } else {
    self.xScale = -1
    self.yScale = -1
  }
  if (gp().counter1 & 0x4) self.yScale = -1
  self.xScale *= self.facing_dir // If facing left, xScale need to flip
}

/** `isProjSprAdjFrame()` — counter + uIdx ∈ {0, MAX_GOC1}: the one frame per cycle a projectile is drawn "lit". */
export function isProjSprAdjFrame(self: GameObject): boolean {
  return isVal(goMgr.counter + self.update_idx, 0, MAX_GOC1)
}

/** `collisionProjCS(x offset, y offset)` */
export function collisionProjCS(self: GameObjectC, xoff: number, yoff: number): boolean {
  const _VAL = deps.inst_collide_solid_type(self, self.x + xoff, self.y + yoff)
  return !!(_VAL & TID_SOLID1) || (!!(_VAL & TID_ONEWY1) && self.vspd < 0x80)
}

/** `despawn_all_goc()` */
export function despawn_all_goc(): void {
  for (let _i = goMgr.dl_goc1.size - 1; _i >= 0; _i--) {
    const inst = goMgr.dl_goc1.get(_i)
    if (!instanceExists(inst as GameObject | null | undefined)) continue
    const i = inst as GameObject
    i.state = 0
    if (gp().mod_destroy_go_on_death && !i.state) GO_destroy_1a(i)
  }
}

/** `GameObjectC_draw()` — scr_draw OR draw self (debug hb/ocs overlays are the dev-tools port's). */
export function GameObjectC_draw(self: GameObjectC): void {
  GameObject_draw(self, self.state)
}

/** `HostileFire_init_1(non-mod palidx)` — fire palette permutations per global.FIRE_PI_SYSTEM_VER. */
export function HostileFire_init_1(self: GameObjectC, palidx: number): void {
  const G = GG()
  const permut = (s: string, n: number) => deps.add_pi_permut(self.palidx, s, `Flame1 permut ${n}`)
  switch (G.FIRE_PI_SYSTEM_VER) {
    case 2:
      GO_init_palidx(self, G.PI_FIRE_HOSTILE1)
      self.PI1 = permut('RBWGMKYC', 1)
      self.PI2 = permut('BRWGMKYC', 2)
      break
    case 3:
      GO_init_palidx(self, G.PI_FIRE_HOSTILE1)
      self.PI1 = permut('WRBGMKYC', 1)
      self.PI2 = permut('WBRGMKYC', 2)
      break
    case 4:
      GO_init_palidx(self, G.PI_FIRE_HOSTILE1)
      self.PI1 = permut('WRBGMKYC', 1)
      self.PI2 = permut('BWRGMKYC', 2)
      self.PI3 = permut('RBWGMKYC', 3)
      break
    case 5:
      GO_init_palidx(self, G.PI_FIRE_HOSTILE1)
      self.PI1 = permut('WRBGMKYC', 1)
      self.PI2 = permut('WBRGMKYC', 2)
      break
    case 6:
      GO_init_palidx(self, G.PI_FIRE_HOSTILE1)
      self.PI1 = permut('WRBGMKYC', 1)
      self.PI2 = permut('RWBGMKYC', 2)
      break
    case 7: // No blinking
      GO_init_palidx(self, G.PI_FIRE_HOSTILE1)
      break
    default:
      GO_init_palidx(self, palidx)
      break
  }
}

/** `HostileFire_udp_1()` */
export function HostileFire_udp_1(self: GameObjectC): void {
  const c1 = gp().counter1
  switch (GG().FIRE_PI_SYSTEM_VER) {
    case 2:
    case 3:
    case 5:
    case 6:
      self.palidx_base = c1 & 0x8 ? self.PI1 : self.PI2
      break
    case 4:
      switch ((c1 >> 2) % 3) {
        case 0:
          self.palidx_base = self.PI1
          break
        case 1:
          self.palidx_base = self.PI2
          break
        case 2:
          self.palidx_base = self.PI3
          break
      }
      break
    case 7: // No blinking
      break
  }
}

/** `Projectile_collision_1a()` — E3CC: projectile vs PC shield (reverse/bounce/disintegrate) and PC body. */
export function Projectile_collision_1a(self: GameObjectC): void {
  if (self.collided_shield) return
  if (!self.react_body && !(self.react_shield & 0xff)) return
  if (!GO_can_collide_this_frame(self.update_idx)) return
  // E3CC ----------------------------------------------------------------------------------
  deps.update_body_hb_1a(self)
  if (
    self.react_shield & 0xff &&
    deps.collide_pc_shield(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h)
  ) {
    const _REFLECT_ACTIVE = gp().spells_active & SPL_RFLC
    const _LV2_SHIELD = fp().items & ITM_SHLD
    const _RVS = 0x04 // Reverse
    const _BNC = 0x02 // Bounce
    const _DSN = 0x01 // DSN: Disintegrate
    let _S1 = self.react_shield & 0xff // reaction types
    let _S2 = (self.react_shield >> 8) & 0xff // REFLECT  types
    _S2 &= _S1 // types that DO   require REFLECT to block
    _S1 ^= _S2 // types that DONT require REFLECT to block
    const _C1 = !!(_S1 & _RVS) || (!!(_S2 & _RVS) && !!_REFLECT_ACTIVE) // can reverse
    const _C2 = !!(_S1 & _BNC) || (!!(_S2 & _BNC) && !!(_REFLECT_ACTIVE || _LV2_SHIELD)) // can bounce
    const _C3 = !!(_S1 & _DSN) || (!!(_S2 & _DSN) && !!(_REFLECT_ACTIVE || _LV2_SHIELD)) // can disintegrate
    if (_C1 || _C2 || _C3) {
      self.collided_shield = true
      if (_C1) {
        // Reverse: SoundWave
        self.reflected = true
        if (gp().mod_REFLECT_more_obj) {
          self.facing_dir = -self.facing_dir
          self.vspd = 0
          self.vspd_adj = 0
        }
        self.hspd = Math.max(abs8b(self.hspd), 0x20)
        self.hspd = byte(self.hspd * sign_(self.x >= pc().x))
        if (self.objectName === 'SoundWave') {
          self.vspd = 0
          self.vspd_adj = 0
          self.counter = 0
        }
      } else if (_C2) {
        // Bounce. E431
        self.hspd = (8 * -self.facing_dir) & 0xff
        self.vspd = 0xf8
      } else {
        // _C3 Disintegrate. E413
        set_xy(self, self.x, self.y - 2)
        self.disintegrate_counter = 0xf2 // start disintegrate
        self.state = self.state_EXPLODE
      }
      // GML: `(react_shield>>$10)&$FF == $2` — GML binds & tighter than ==
      if (((self.react_shield >> 0x10) & 0xff) === 0x2)
        deps.play_theme_sound(dk_StrikeSolid) // Axe, Bolo, Mace. Need REFLECT active.
      else deps.play_theme_sound(dk_HitShield)
      return
    }
  }
  if (
    self.react_body &&
    !self.collided_shield &&
    deps.collide_pc_body(self.BodyHB_xl, self.BodyHB_yt, self.BodyHB_w, self.BodyHB_h, self.BodyHB_r)
  ) {
    // E442
    deps.enemy_collide_pc_body(self)
    // Only Flame1&2 are $01
    if ((self.react_body & 0xff) !== 0x01) self.state = 0
  }
}

/** `Projectile_collision_2a()` — a REFLECTed projectile hitting enemies that are vulnerable to it. */
export function Projectile_collision_2a(self: GameObjectC): void {
  if (!self.reflected) return
  if (!GO_can_collide_this_frame(self.update_idx)) return
  if (!gp().mod_REFLECT_more_obj && self.objectName !== 'SoundWave') return
  let _collided = false
  const _OBJVER = self.objectName + hexStr(self.ver)
  deps.update_body_hb_1a(self)
  for (let _i = goMgr.dl_gob1.size - 1; _i >= 0; _i--) {
    const e = goMgr.dl_gob1.get(_i)
    if (!instanceExists(e as GameObject | null | undefined)) continue
    const other = e as GameObject
    if (other.state !== other.state_NORMAL) continue
    if (other.ShieldHB_idx) {
      gobShield.GOB_update_shield_offsets(other)
      deps.update_shield_hb(other)
      if (!other.ShieldHB_r && self.BodyHB_r)
        _collided = deps.rectInCirc(
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_r,
          other.ShieldHB_x,
          other.ShieldHB_y,
          other.ShieldHB_w,
          other.ShieldHB_h,
        )
      else if (other.ShieldHB_r && !self.BodyHB_r)
        _collided = deps.rectInCirc(
          other.ShieldHB_x,
          other.ShieldHB_y,
          other.ShieldHB_r,
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_w,
          self.BodyHB_h,
        )
      else if (other.ShieldHB_r && self.BodyHB_r)
        _collided = deps.circInCirc(
          other.ShieldHB_x,
          other.ShieldHB_y,
          other.ShieldHB_r,
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_r,
        )
      else
        _collided = deps.rectInRect(
          other.ShieldHB_x,
          other.ShieldHB_y,
          other.ShieldHB_w,
          other.ShieldHB_h,
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_w,
          self.BodyHB_h,
        )
    }
    if (!_collided) {
      deps.update_body_hb_1a(other)
      let _C1: boolean
      if (!other.BodyHB_r && self.BodyHB_r)
        _C1 = deps.rectInCirc(
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_r,
          other.BodyHB_xl,
          other.BodyHB_yt,
          other.BodyHB_w,
          other.BodyHB_h,
        )
      else if (other.BodyHB_r && !self.BodyHB_r)
        _C1 = deps.rectInCirc(
          other.BodyHB_xl,
          other.BodyHB_yt,
          other.BodyHB_r,
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_w,
          self.BodyHB_h,
        )
      else if (other.BodyHB_r && self.BodyHB_r)
        _C1 = deps.circInCirc(
          other.BodyHB_xl,
          other.BodyHB_yt,
          other.BodyHB_r,
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_r,
        )
      else
        _C1 = deps.rectInRect(
          other.BodyHB_xl,
          other.BodyHB_yt,
          other.BodyHB_w,
          other.BodyHB_h,
          self.BodyHB_xl,
          self.BodyHB_yt,
          self.BodyHB_w,
          self.BodyHB_h,
        )
      if (_C1 && other.dl_ProjVuln && other.dl_ProjVuln.findIndex(_OBJVER) + 1) {
        // if this gob inst is vulnerable to the REFLECTed projectile
        _collided = true
        damage_gob(other, deps.get_pc_attack_damage(), true) // damage enemy
      }
    }
    if (_collided) {
      if (((self.react_shield >> 0x10) & 0xff) === 2)
        deps.play_theme_sound(dk_StrikeSolid) // Axe, Bolo, Mace.
      else deps.play_theme_sound(dk_HitShield)
      set_xy(self, self.x, self.y - 2)
      self.disintegrate_counter = 0xf2
      self.state = self.state_EXPLODE
      return
    }
  }
}

