// biome-ignore-all lint/suspicious/noExplicitAny: LoremEnv bridges untyped g fields
/**
 * Cross-subsystem references used by the file/save system. `g`, `p`, `G`, `Audio`, `pc` are ported by
 * other subsystems; the fields listed here are what ZALiA's `file` scripts read/write on them. Until
 * those ports land they are accessed through these typed views (runtime values must exist on the
 * singletons — see the field lists — or the calls throw like any other unported reference).
 */
import type { DsGrid, DsList, DsMap } from '../../runtime/ds'
import { G, g, input, p, world } from '../../runtime/world'
import { viewH, viewW } from '../collision/env'
import { can_update_frame } from '../Game/can_update_frame'
import { get_random_lorem_dlg } from '../other/index'
import { notPorted } from '../pending'
import { get_dk_dungeon_entrance, get_dungeon_num } from '../room/index'
import { Audio } from '../sound/Audio'
import { aud_play_sound } from '../sound/play'
import { get_audio_theme_track } from '../sound/theme'
import {
  window_get_fullscreen,
  window_get_scale,
  window_set_fullscreen,
  window_set_position_,
  window_set_scale,
  windowState,
} from '../view/window'

