  /** current room name (GM `room`), e.g. 'rmB_Death' */
  room: string
  overworld_paused: boolean
  counter0: number
  counter1: number
  STARTING_LIVES: number
  CuccoSpell2_Acquired: number
  CuccoSpell2_Option: boolean
  dm_RandoHintsRecorder: DsMap<number | string>
  dm_room_history: DsMap<number | string>
  dm_rm: DsMap<number | string>
  dm_spawn: DsMap<number | string>
  dm_town: DsMap<number | string>
  dm_dungeon: DsMap<number | string>
  dm_Spell: DsMap<number | string>
  dl_HP: DsList<number>
  dl_XP: DsList<number>
  dg_enemy_damage: DsGrid<number>
  dg_spell_cost: DsGrid<number>
  DIALOGUE_WINDOW: { dm_dialogue: DsMap<number | string> }
  gui_state: number
  gui_state_NONE: number
  gui_state_LEVEL_UP: number
  gui_state_OPTIONS: number
  gui_state_QUIT_APP: number
  gui_state_EDIT_PAL: number
  gui_state_GEE: number
  cutscene: number | boolean
  game_end_state: number | boolean
  StatRestore_timer_hp: number
  StatRestore_timer_mp: number
  mod_STAT_RESTORE_1: number | boolean
  mod_ContinueFrom: number
  mod_ContinueFrom_DNGN: number
  mod_ContinueFrom_TWN1: number
  mod_ContinueFrom_TWN2: number
  mod_QuestNewKasuto: number
  coming_from: number
  coming_from_FILE: number
  CHAR_END_LINE1: string
  // preferences
  WindowScale_scale: number
  ScreenShake_user_pref: number
  mod_DLG_SPEED: number
  mod_IndicateSpellActive: number
  torch_lighting_method: number
  mod_StabFrenzy: number
  HiddenExitIndicator_enabled: number | boolean
  RandoPalette_state: number
  RandoKeys_MAP_items_show_keys: number | boolean
  DevTools_state: number | boolean
  DoubleJump_state: number | boolean
  DevDash_state: number | boolean
  can_show_debug_overlay: number | boolean
  all_bg_black_only: number | boolean
