export interface PaletteFileDeps {
  BackgroundFlash_setting: number
}

export interface AudioFileDeps {
  snd_vol: number
  mus_vol: number
  audio_set: string
  dm_random_custom: DsMap<number | string>
}

export const gd = () => g as unknown as GameFileDeps
export const Gd = () => G as unknown as GlobalsFileDeps
export const pd = () => p as unknown as PaletteFileDeps
export const inputd = () => input

/**
 * Hooks into subsystems that are not ported yet. Real implementations replace these; tests override
 * them. Defaults throw (never silent).
 */
export const hooks = {
  /** The `Audio` singleton (Audio subsystem). */
  audio: (): AudioFileDeps => Audio as unknown as AudioFileDeps,
  get_audio_theme_track: get_audio_theme_track as unknown as (theme: string) => string,
  audio_is_playing: (sound: string) => Audio.audio_is_playing(sound),
  aud_play_sound: aud_play_sound as unknown as (sound: string) => void,
  can_update_frame,
  item_acquired: notPorted('item_acquired') as (itemId: string) => boolean,
  get_dungeon_num,
  get_dk_dungeon_entrance,
  /** `get_random_lorem_dlg(lines, single)` with the env ZALiA reads from `g`. */
  get_random_lorem_dlg: (count: number, flag: boolean): string =>
    get_random_lorem_dlg(
      {
        words: (g as any).dl_LOREM.items as string[],
        maxLines: (g as any).DIALOGUE_WINDOW.MAX_LINES as number,
        charPerLineMax: (g as any).DIALOGUE_WINDOW.CHAR_PER_LINE_MAX as number,
        endLine: gd().CHAR_END_LINE1,
        random: () => world.random(1),
      },
      count,
      flag,
    ),
  /**
   * `file_load.gml:176` — `ds_map_read(global.dm_randomized_tiles01, _val)`, the randomized dungeon-tile
   * blob. Deliberately a no-op: the only writer of `dm_save_data_dungeon_tileset[?"Randomized_Tiles01"]`
   * is inside the `/* *\/` block at `Rando_randomize_dungeon_tilesets.gml:86-137` that the author
   * disabled on 2025/08/11 ("Turning this off for now. Doesn't look good."), and it also needs
   * `other/TilesetData01.txt`, which ZALiA does not ship. No save can carry the key, so the read is dead
   * (FIDELITY_NOTES). Kept as a named seam so `scene_enter_add_tiles`'s reader stays traceable.
   */
  read_randomized_tiles01: (_blob: string): void => {},
  window_set_scale,
  window_get_scale,
  window_set_position_,
  window_set_fullscreen,
  window_get_fullscreen,
  viewW,
  viewH,
  audio_group_set_gain: (group: 'mus' | 'snd', gain: number) => Audio.audio_group_set_gain(group, gain),
  show_debug_overlay: (on: boolean) => {
    windowState.debugOverlay = on
  },
}
