/**
 * Local seams for the gob2 port: scripts owned by other (in-flight) folders. Exact GML names so the
 * wiring pass can re-point them. Plus depth-aware draw helpers (ZALiA draws at the instance's `depth`).
 */

import { draw_sprite_rot } from '../../../gui/deps'
import { draw_rect_, draw_sprite_ as drawSpriteRooms, drawState } from '../../../rooms/draw'
import { Audio } from '../../../sound/Audio'
import type { GameObject } from '../../classes'
import { Bot_draw, Bot_init2, Bot_udp } from '../gob1/enemy/bot/Bot'
import { colliding_FireRope } from '../gob1/fire_rope/FireRope'

export const gob2Deps = {
  /** gob1/enemy/bot — Bagu's Bot NPC (NPC_9 v5) reuses the enemy's init/udp/draw. */
  Bot_init2: Bot_init2 as unknown as (self: GameObject) => void,
  Bot_udp: Bot_udp as unknown as (self: GameObject) => void,
  Bot_draw: Bot_draw as unknown as (self: GameObject) => void,
  /** gob1/fire_rope — `colliding_FireRope(inst, x, y, w, h)` */
  colliding_FireRope: colliding_FireRope as unknown as (
    inst: GameObject,
    x: number,
    y: number,
    w: number,
    h: number,
  ) => boolean,
  /** dev folder — `db_NPC_create_1a(id)` (DEV only; no-op here) */
  db_NPC_create_1a: (_inst: GameObject): void => {},
}

/** `audio_is_playing(sound)` */
export const audio_is_playing = (snd: unknown): boolean => Audio.audio_is_playing(snd as never)

/** `draw_sprite_(...)` at a given depth, with the optional colour blend ZALiA's wrapper accepts. */
export function draw_sprite_at(
  depth: number,
  sprite: string | 0 | undefined,
  subimg: number,
  x: number,
  y: number,
  palIdx = -1,
  xscale = 1,
  yscale = 1,
  color = -1,
  alpha = 1,
): void {
  const prev = drawState.depth
  drawState.depth = depth
  drawSpriteRooms(sprite, subimg, x, y, palIdx, xscale, yscale, color, alpha)
  drawState.depth = prev
}

/** `draw_sprite_(..., c_white, 1, angle)` — the 10-arg rotated form (SwitchA, PushableRefresher). */
export function draw_sprite_rot_at(
  depth: number,
  sprite: string,
  subimg: number,
  x: number,
  y: number,
  palIdx: number,
  xscale: number,
  yscale: number,
  rotation: number,
): void {
  const prev = drawState.depth
  drawState.depth = depth
  draw_sprite_rot(sprite, subimg, x, y, palIdx, xscale, yscale, -1, 1, rotation)
  drawState.depth = prev
}

export function draw_rect_at(
  depth: number,
  color: number,
  x: number,
  y: number,
  w: number,
  h: number,
  alpha = 1,
): void {
  const prev = drawState.depth
  drawState.depth = depth
  draw_rect_(color, x, y, w, h, alpha)
  drawState.depth = prev
}
