/** Eyenocc (stab-to-move stone eye block) — ZALiA `gob2/eyenocc`. */
import { CS_SW1, DEPTH_NPC, STR_Count, STR_Num, STR_Sequence, TID_SOLID1 } from '@z2/data'
import { hexStr } from '../../../../nes/hexStr'
import { DsMap } from '../../../../runtime/ds'
import { f, G, g, p } from '../../../../runtime/world'
import { rectInRect } from '../../../collision/geometry'
import { GOB_body_collide_pc_sword } from '../../../collision/gob'
import { ocsHV1 } from '../../../collision/ocs'
import { str_hex, val } from '../../../other/index'
import { tile_change_1a } from '../../../tile/tileOps'
import { GameObject_draw_1a } from '../../go/draw'
import { GO_update_cam_vars } from '../../go/misc'
import { set_xlyt, set_xy, updateX, updateY } from '../../go/movement'
import { GO_init_palidx } from '../../go/palette'
import { GO_depth_init, GO_set_sprite, GO_sprite_init } from '../../go/sprite'
import { pc } from '../../goa/pc'
import { GameObjectB_step2, update_EF11 } from '../GameObjectB'
import type { Eyenocc } from './classes'
import { draw_sprite_at } from './deps'

/** `Eyenocc_end()` */
export function Eyenocc_end(self: Eyenocc): void {
  self.dm = undefined
}

/** `Eyenocc_init1()` */
export function Eyenocc_init1(self: Eyenocc): void {
  GO_depth_init(self, DEPTH_NPC)
  self.scr_step = GameObjectB_step2 as never
  self.sequence_num = 0x00
  self.SPEED1 = 0x20
  self.Jiggle_DURATION1 = 0x20
  self.Jiggle_timer = 0
}

/** `Eyenocc_init2()` */
export function Eyenocc_init2(self: Eyenocc): void {
  GO_init_palidx(self, G.PI_MOB_ORG)
  const dm = new DsMap<number | string>()
  self.dm = dm
  if (self.dk_spawn !== undefined) {
    // _DATA example: "086B186B_1852_". Each "_" is the end of a sequence num. Each 4 chars are a
    // sub-sequence num of the sequence and are the destination row & clm.
    let _DATA = g.dm_spawn.get(self.dk_spawn + STR_Sequence)
    if (typeof _DATA === 'string') {
      const _count = _DATA.split('_').length - 1
      dm.set(STR_Sequence + STR_Count, _count)
      for (let _i = 0; _i < _count; _i++) {
        const _len = _DATA.length
        const _pos = _DATA.indexOf('_') + 1
        const _str = _DATA.substring(0, _pos - 1)
        if (_len > _pos) _DATA = _DATA.substring(_pos)
        const _count1 = _str.length >> 2
        dm.set(`${STR_Sequence}${_i + 1}${STR_Count}`, _count1)
        for (let _j = 0; _j < _count1; _j++) {
          const _val = str_hex(_str.substr(_j << 2, 4))
          dm.set(`${STR_Sequence}${_i + 1}${_j + 1}_X`, ((_val >> 0) & 0xff) << 3)
          dm.set(`${STR_Sequence}${_i + 1}${_j + 1}_Y`, ((_val >> 8) & 0xff) << 3)
        }
      }
    }
  }
  self.sequence_num = 0x00
  if (self.dk_spawn !== undefined) {
    self.sequence_num = val(
      f.dm_quests.get(self.dk_spawn + STR_Sequence + STR_Num),
      self.sequence_num,
    ) as number
    const seqCount = val(dm.get(STR_Sequence + STR_Count)) as number
    if (self.sequence_num >> 4 >= seqCount) {
      self.sequence_num = (seqCount << 4) | Math.max(self.sequence_num & 0xf, 1)
      self.sequence_num =
        (self.sequence_num & 0xf0) |
        (val(
          dm.get(`${STR_Sequence}${self.sequence_num >> 4}${STR_Count}`),
          self.sequence_num & 0xf,
        ) as number)
    }
  }
  self.Source_xl = self.xl
  self.Source_yt = self.yt
  if (self.sequence_num) {
    self.Source_xl = val(dm.get(`${STR_Sequence + hexStr(self.sequence_num)}_X`), self.Source_xl) as number
    self.Source_yt = val(dm.get(`${STR_Sequence + hexStr(self.sequence_num)}_Y`), self.Source_yt) as number
  }
  set_xlyt(self, self.Source_xl, self.Source_yt)
  self.Destination_xl = self.xl
  self.Destination_yt = self.yt
  for (let _i = (self.hh >> 3) - 1; _i >= 0; _i--) {
    for (let _j = (self.ww >> 3) - 1; _j >= 0; _j--)
      tile_change_1a(0, self.xl + (_j << 3), self.yt + (_i << 3), -1, 0, TID_SOLID1)
  }
  self.sub_state = self.sub_state_IDLE
  self.Eye_state = self.Eye_state_OPEN_HALF
  if (self.sequence_num >> 4 === val(dm.get(STR_Sequence + STR_Count))) self.Eye_state = self.Eye_state_CLOSED
  switch (self.Eye_state) {
    default:
      GO_sprite_init(self, self.sprite_OPEN_FULL)
      break
    case self.Eye_state_OPEN_HALF:
      GO_sprite_init(self, self.sprite_OPEN_HALF)
      break
    case self.Eye_state_CLOSED:
      GO_sprite_init(self, self.sprite_CLOSED)
      break
  }
  self.Pupil_can_draw = false
  self.Pupil_xl = self.x - 1
  self.Pupil_yt = self.y - 0
  self.Pupil_h = 1
}

const seqKey = (self: Eyenocc, suffix: string) => `${STR_Sequence + hexStr(self.sequence_num)}${suffix}`

/** `Eyenocc_update()` */
export function Eyenocc_update(self: Eyenocc): void {
  const dm = self.dm as DsMap<number | string>
  GO_update_cam_vars(self)
  if (self.Jiggle_timer) self.Jiggle_timer--
  switch (self.sub_state) {
    case self.sub_state_IDLE: {
      if (self.timer) break
      self.Eye_state = self.Eye_state_OPEN_HALF
      if (self.sequence_num >> 4 < (val(dm.get(STR_Sequence + STR_Count)) as number)) {
        if (ocsHV1(self)) {
          // if any w AND h in ocs area. E677 - PC sword to enemy body
          GOB_body_collide_pc_sword(self)
          if (self.cs & CS_SW1) {
            self.Jiggle_timer = self.Jiggle_DURATION1
            self.hp = g.dl_HP.get(self.HP_IDX) as number
            self.sequence_num += 0x10
            self.sequence_num &= 0xf0
            self.sequence_num |= 0x01 // sequence_num&$F is the sub-sequence num.
            if (self.dk_spawn !== undefined)
              f.dm_quests.set(self.dk_spawn + STR_Sequence + STR_Num, self.sequence_num)
            self.Source_xl = self.xl
            self.Source_yt = self.yt
            self.Destination_xl = val(dm.get(seqKey(self, '_X')), self.Source_xl) as number
            self.Destination_yt = val(dm.get(seqKey(self, '_Y')), self.Source_yt) as number
            self.hspd = (self.SPEED1 * Math.sign(self.Destination_xl - self.Source_xl)) & 0xff
            self.vspd = (self.SPEED1 * Math.sign(self.Destination_yt - self.Source_yt)) & 0xff
            if (self.hspd || self.vspd) {
              self.timer = 0x0
              self.sub_state = self.sub_state_MOVING
            }
          }
        }
      } else {
        self.Eye_state = self.Eye_state_CLOSED
      }
      break
    }
    case self.sub_state_MOVING: {
      self.Eye_state = self.Eye_state_OPEN_FULL
      if (self.timer) break
      const _xl_PREV = self.xl
      const _yt_PREV = self.yt
      if (self.hspd) updateX(self)
      if (self.vspd) updateY(self)
      if (
        rectInRect(_xl_PREV, _yt_PREV, self.ww, self.hh, self.Source_xl, self.Source_yt, self.ww, self.hh) &&
        !rectInRect(self.xl, self.yt, self.ww, self.hh, self.Source_xl, self.Source_yt, self.ww, self.hh)
      ) {
        for (let _i = (self.hh >> 3) - 1; _i >= 0; _i--)
          for (let _j = (self.ww >> 3) - 1; _j >= 0; _j--)
            tile_change_1a(0, self.Source_xl + (_j << 3), self.Source_yt + (_i << 3), -1, 0, 0)
      }
      let _destination_reached = false
      if (self.hspd & 0x80) _destination_reached = self.xl <= self.Destination_xl
      else if (self.hspd) _destination_reached = self.xl >= self.Destination_xl
      else if (self.vspd & 0x80) _destination_reached = self.yt <= self.Destination_yt
      else if (self.vspd) _destination_reached = self.yt >= self.Destination_yt
      if (_destination_reached) {
        self.hspd = 0
        self.vspd = 0
        set_xy(self, self.Destination_xl + self.ww_, self.Destination_yt + self.hh_)
        self.Source_xl = self.xl
        self.Source_yt = self.yt
        for (let _i = (self.hh >> 3) - 1; _i >= 0; _i--)
          for (let _j = (self.ww >> 3) - 1; _j >= 0; _j--)
            tile_change_1a(0, self.xl + (_j << 3), self.yt + (_i << 3), -1, 0, TID_SOLID1)
        // sequence_num&$F is the sub-sequence num. The sequence num of movements for the last stab.
        if (
          (self.sequence_num & 0xf) <
          (val(dm.get(`${STR_Sequence}${self.sequence_num >> 4}${STR_Count}`)) as number)
        ) {
          self.sequence_num++
          self.Destination_xl = val(dm.get(seqKey(self, '_X')), self.Source_xl) as number
          self.Destination_yt = val(dm.get(seqKey(self, '_Y')), self.Source_yt) as number
          self.hspd = (self.SPEED1 * Math.sign(self.Destination_xl - self.Source_xl)) & 0xff
          self.vspd = (self.SPEED1 * Math.sign(self.Destination_yt - self.Source_yt)) & 0xff
          self.timer = 0x6
        } else {
          self.timer = 0
          self.sub_state = self.sub_state_IDLE
        }
      }
      break
    }
  }
  update_EF11(self)
}

/** `Eyenocc_udp()` */
export function Eyenocc_udp(self: Eyenocc): void {
  self.can_draw_self = true
  self.xScale = 1
  switch (self.Eye_state) {
    default:
      GO_set_sprite(self, self.sprite_OPEN_FULL)
      break
    case self.Eye_state_OPEN_HALF:
      GO_set_sprite(self, self.sprite_OPEN_HALF)
      break
    case self.Eye_state_CLOSED:
      GO_set_sprite(self, self.sprite_CLOSED)
      break
  }
  self.Pupil_can_draw = false
  switch (self.sprite) {
    case self.sprite_OPEN_FULL:
      self.Pupil_can_draw = true
      self.Pupil_xl = self.drawX - 1
      self.Pupil_yt = self.drawY - 1
      self.Pupil_h = 2
      break
    case self.sprite_OPEN_HALF: {
      self.Pupil_can_draw = true
      self.Pupil_xl = self.drawX - 1
      self.Pupil_yt = self.drawY - 0
      self.Pupil_h = 1
      const P = pc()
      if (P.x < self.x - 8) self.Pupil_xl--
      else if (P.x > self.x + 7) self.Pupil_xl++
      break
    }
  }
}

/** `Eyenocc_draw()` */
export function Eyenocc_draw(self: Eyenocc): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  let _PI = self.palidx
  if (self.Eye_state === self.Eye_state_CLOSED) _PI = G.PI_GUI2
  GameObject_draw_1a(self, self.sprite as string, _PI) // draw self
  if (self.Pupil_can_draw)
    draw_sprite_at(self.depth, 'spr_1x1_WHT', 0, self.Pupil_xl, self.Pupil_yt, -1, 2, self.Pupil_h, p.C_BLK1)
}
