import { registerObjectClass } from '../../../../other/registry'
import { pal_swap_reset, pal_swap_set } from '../../../../palette/scenePalette'
import { draw_background_part_ext, draw_sprite_ } from '../../../../rooms/draw'
import { aud_play_sound } from '../../../../sound/play'
import { get_audio_theme_track } from '../../../../sound/theme'
import { cam_xl_min, cam_xr_max, cam_yb_max, cam_yt_min } from '../../../../view/camera'
