/** `Rando_add_location(rm name, rm location num, category, obscurity, description, item type, rm item type num, *is safe location)` */
export function Rando_add_location(
  self: Rando,
  RM_NAME: string,
  RM_LOCATION_NUM: number,
  CATEGORY: string,
  OBSCURITY: number,
  DESCRIPTION: string,
  ITEM_TYPE: string,
  /** if there's more than one of the same item type in a rm */
  RM_ITEM_TYPE_NUM: number,
  IS_SAFE_LOCATION = 0,
): number {
  const _LOCATION_NUM = self.dl_location_NUMS.size + 1
  self.dl_location_NUMS.add(_LOCATION_NUM)
  self.dm_LOCATIONS.set(STR_Total + STR_Location + STR_Count, self.dl_location_NUMS.size)

  const _LOCATION_NUM_ = hexStr(_LOCATION_NUM)

  switch (ITEM_TYPE) {
    // ---------------------------------------------------
    default: {
      // main items, quest items, heart&magic pieces, 1up dolls
      if (ITEM_TYPE === STR_ALLKEY) {
        self.dm_LOCATIONS.set(STR_ALLKEY + STR_Location + STR_Num, _LOCATION_NUM)
      }
      self.dl_item_location_NUMS.add(_LOCATION_NUM)
      self.dm_LOCATIONS.set(STR_Item + STR_Location + STR_Count, self.dl_item_location_NUMS.size)
      if (gmBool(IS_SAFE_LOCATION) && gmBool(self.ItemLocations_WILL_RANDOMIZE)) {
        self.dl_SAFE_LOCATION_NUMS.add(_LOCATION_NUM)
      }
      break
    }

    // ---------------------------------------------------
    case STR_PBAG: {
      self.dl_pbag_location_NUMS.add(_LOCATION_NUM)
      self.dm_LOCATIONS.set(STR_PBAG + STR_Location + STR_Count, self.dl_pbag_location_NUMS.size)
      if (gmBool(IS_SAFE_LOCATION) && gmBool(self.ItemLocations_INCLUDE_PBAG)) {
        self.dl_SAFE_LOCATION_NUMS.add(_LOCATION_NUM)
      }
      break
    }

    // ---------------------------------------------------
    case STR_KEY: {
      self.dl_key_location_NUMS.add(_LOCATION_NUM)
      self.dm_LOCATIONS.set(STR_Key + STR_Location + STR_Count, self.dl_key_location_NUMS.size)

      const _ITEM_ID = String(
        val(
          g.dm_spawn.get(RM_NAME + STR_Key + STR_ID),
          STR_Key + STR_Num + hexStr(self.dl_key_location_NUMS.size),
        ),
      )
      self.dm_LOCATIONS.set(STR_Location + STR_Num + _LOCATION_NUM_ + STR_Key + STR_ID, _ITEM_ID)
      self.dm_LOCATIONS.set(_ITEM_ID + STR_Location + STR_Num, _LOCATION_NUM)
      if (self.FallingKey_RM_NAME === RM_NAME) {
        self.FallingKey_ITEM_ID = _ITEM_ID
      }
      if (gmBool(IS_SAFE_LOCATION) && gmBool(self.KeyLocations_WILL_RANDOMIZE)) {
        self.dl_SAFE_LOCATION_NUMS.add(_LOCATION_NUM)
      }
      break
    }

    // ---------------------------------------------------
    case STR_Spell: {
      self.dl_spell_location_NUMS.add(_LOCATION_NUM)
      self.dm_LOCATIONS.set(STR_Spell + STR_Location + STR_Count, self.dl_spell_location_NUMS.size)
      const _TOWN_NAME = String(val(g.dm_rm.get(RM_NAME + STR_Town + STR_Name), 'undefined'))
      self.dm_LOCATIONS.set(_TOWN_NAME + STR_Spell + STR_Location + STR_Num, _LOCATION_NUM)
      break
    }
  }

  self.dm_LOCATIONS.set(_LOCATION_NUM_ + STR_Rm + STR_Name, RM_NAME)
  self.dm_LOCATIONS.set(_LOCATION_NUM_ + STR_Rm + STR_Location + STR_Num, RM_LOCATION_NUM)
  self.dm_LOCATIONS.set(_LOCATION_NUM_ + STR_Location + STR_ID, RM_NAME + hexStr(RM_LOCATION_NUM))
  self.dm_LOCATIONS.set(_LOCATION_NUM_ + STR_Category, CATEGORY)
  self.dm_LOCATIONS.set(_LOCATION_NUM_ + STR_Obscure, OBSCURITY)
  self.dm_LOCATIONS.set(_LOCATION_NUM_ + STR_Description, DESCRIPTION)

  self.dm_LOCATIONS.set(_LOCATION_NUM_ + STR_Item + STR_Base + STR_Key, ITEM_TYPE)
  // if multiple of same item base key in a scene
  self.dm_LOCATIONS.set(_LOCATION_NUM_ + STR_Rm + STR_Item + STR_Base + STR_Key + STR_Num, RM_ITEM_TYPE_NUM)

  self.dm_LOCATIONS.set(_LOCATION_NUM_ + STR_Item + STR_Type, ITEM_TYPE)
  self.dm_LOCATIONS.set(_LOCATION_NUM_ + STR_Rm + STR_Item + STR_Type + STR_Num, RM_ITEM_TYPE_NUM)

  return _LOCATION_NUM
}

