/** Suffix of the `LocCatID_*` field `Rando_generate` filled in before this script runs. */
type LocCat =
  | 'West01'
  | 'West02'
  | 'Nabo01'
  | 'Daru01'
  | 'Kasu01'
  | 'DMtn01'
  | 'Maze01'
  | 'NIsl01'
  | 'VOD01'
  | 'Sari01'
  | 'RMtn01'
  | 'SCon01'
  | 'DragMr'
  | 'Dngn01'
  | 'Town01'

/** Prefix of the `*_WILL_RANDOMIZE` field a hint line is guarded by (`if(!X) …`). */
type HintCond = 'DungeonLocations' | 'DungeonBoss' | 'TownLocations'

/** A hint string, or one ZALiA only writes when that rando option is off. */
type Hint = string | readonly [HintCond, string]

/** The `if`/`switch` ZALiA wraps an individual `Rando_add_location` call in. */
type RowGuard = 'QUEST1' | 'QUEST2' | 'BOTTLE'

interface LocationRow {
  /** `rm name` — same as `rm_name`. */
  readonly rm: string
  /** `rm location num` */
  readonly num: number
  /** `category` — the `LocCatID_*` suffix. */
  readonly cat: LocCat
  /** `obscurity` */
  readonly obs: number
  /** `description` */
  readonly desc: string
  /** `item type` */
  readonly item: string
  /** `rm item type num` — if there's more than one of the same item type in a rm. */
  readonly inum: number
  /** `is safe location` */
  readonly safe?: 1
  /** `dm_LOCATIONS[?hex_str(_loc_num)+STR_ALLKEY+STR_Rating]` */
  readonly rating?: number
  /** `dm_LOCATIONS[?hex_str(_loc_num)+STR_Hint+hex_str(++_a)]`, in order. */
  readonly hints?: readonly Hint[]
  readonly when?: RowGuard
  /** `FallingKey_RM_NAME=Area_PalcF+'13';` — set right before the P6 Key 4 call. */
  readonly fallingKeyRm?: true
}

