export function Rando_init_location_data(self: Rando): void {
  for (const row of LOCATION_TABLE) {
    // The guards ZALiA writes around individual locations, kept in source order.
    switch (row.when) {
      case undefined:
        break
      // `if (INCLUDE_BOTTLE_LOCATION && QUEST_NUM==2)` — BOTTLE item, North Castle Zelda room.
      case 'BOTTLE':
        if (!(self.INCLUDE_BOTTLE_LOCATION && self.QUEST_NUM === 2)) continue
        break
      // `switch(QUEST_NUM){ case 1: …` — Great Palace 1up location.
      case 'QUEST1':
        if (self.QUEST_NUM !== 1) continue
        break
      // `if (QUEST_NUM==2){ … }` — the Dragmire block, the 2nd-quest PBag and the Bulblin wiseman.
      case 'QUEST2':
        if (self.QUEST_NUM !== 2) continue
        break
    }

    if (row.fallingKeyRm) self.FallingKey_RM_NAME = row.rm

    const _loc_num = Rando_add_location(
      self,
      row.rm,
      row.num,
      self[`LocCatID_${row.cat}`],
      row.obs,
      row.desc,
      row.item,
      row.inum,
      row.safe ?? 0,
    )
    const _loc_num_ = hexStr(_loc_num)

    if (row.rating !== undefined) self.dm_LOCATIONS.set(_loc_num_ + STR_ALLKEY + STR_Rating, row.rating)

    let _a = 0
    for (const hint of row.hints ?? []) {
      // A skipped `if(!…_WILL_RANDOMIZE)` hint does not consume a hint number: `++_a` is inside the write.
      if (typeof hint !== 'string' && gmBool(self[`${hint[0]}_WILL_RANDOMIZE`])) continue
      const text = typeof hint === 'string' ? hint : hint[1]
      self.dm_LOCATIONS.set(_loc_num_ + STR_Hint + hexStr(++_a), text)
    }
  }

  self.Location_COUNT = Number(self.dm_LOCATIONS.val(STR_Total + STR_Location + STR_Count))
  self.dm_save_data.set(STR_Total + STR_Location + STR_Count, self.Location_COUNT)

  self.ItemLocation_COUNT = Number(self.dm_LOCATIONS.val(STR_Item + STR_Location + STR_Count))
  self.dm_save_data.set(STR_Item + STR_Location + STR_Count, self.ItemLocation_COUNT)

  self.PBagLocation_COUNT = Number(self.dm_LOCATIONS.val(STR_PBAG + STR_Location + STR_Count))
  self.dm_save_data.set(STR_PBAG + STR_Location + STR_Count, self.PBagLocation_COUNT)

  self.SpellLocation_COUNT = Number(self.dm_LOCATIONS.val(STR_Spell + STR_Location + STR_Count))
  self.dm_save_data.set(STR_Spell + STR_Location + STR_Count, self.SpellLocation_COUNT)

  self.KeyLocation_COUNT = Number(self.dm_LOCATIONS.val(STR_Key + STR_Location + STR_Count))
  self.dm_save_data.set(STR_Key + STR_Location + STR_Count, self.KeyLocation_COUNT)

  // ******** FIND AND RECORD THE spawn_datakey EACH _loc_num ********
  // =================================================================================
  // `_dl_scenes` / `_dl_multiple_locations_scenes` are write-only in ZALiA: their only reader is the
  // commented-out debug print at `:2067-2068`. Kept because the `else if` is what stops a scene being
  // added twice, and the lists are cheap.
  const _dl_scenes = new DsList<string>()
  const _dl_multiple_locations_scenes = new DsList<string>()

  const _total_location_COUNT = self.dl_location_NUMS.size
  for (let _i = 0; _i < _total_location_COUNT; _i++) {
    const _loc_num = self.dl_location_NUMS.get(_i) as number

    if (inList(self.dl_spell_location_NUMS, _loc_num)) continue

    const _loc_num_ = hexStr(_loc_num)
    const _rm_name = String(
      val(
        self.dm_LOCATIONS.get(_loc_num_ + STR_Rm + STR_Name),
        `${STR_Location + STR_Num + _loc_num_ + STR_Rm + STR_Name} undefined`,
      ),
    )
    const _item_type = String(
      val(
        self.dm_LOCATIONS.get(_loc_num_ + STR_Item + STR_Base + STR_Key),
        `${STR_Location + STR_Num + _loc_num_ + STR_Item + STR_Type} undefined`,
      ),
    )
    const _num1 = Number(self.dm_LOCATIONS.val(_loc_num_ + STR_Rm + STR_Item + STR_Base + STR_Key + STR_Num))

    if (!inList(_dl_scenes, _rm_name)) _dl_scenes.add(_rm_name)
    else if (!inList(_dl_multiple_locations_scenes, _rm_name)) _dl_multiple_locations_scenes.add(_rm_name)

    let _num = 0
    const _count = Number(val(g.dm_spawn.get(get_spawn_datakey(_rm_name, STR_PRIO, -1))))
    for (let _j = 0; _j < _count; _j++) {
      const _spawn_datakey = get_spawn_datakey(_rm_name, STR_PRIO, _j)
      // GML: `_obj = val(g.dm_spawn[?…+STR_obj_idx], noone); if (_obj)` — "no object" is `undefined` here.
      const _obj = g.dm_spawn.get(_spawn_datakey + STR_obj_idx) as string | number | undefined
      if (_obj === undefined) continue

      // `object_get_name(_obj)` — the spawn cache stores GM object indices (or names).
      const _datakey = g.dm_ITEM.get(gmObjectNameOf(_obj) + STR_Item + STR_Type) as string | undefined
      if (_datakey === undefined || _item_type !== _datakey) continue

      _num++
      if (_num !== _num1) continue

      // Find and record the spawn_datakey for this _loc_num
      self.dm_LOCATIONS.set(_loc_num_ + STR_Spawn + STR_Datakey, _spawn_datakey) // item_id's vanilla spawn_datakey
      // The vanilla item_id for this _loc_num/_spawn_datakey
      const _item_id = String(
        val(
          g.dm_spawn.get(_spawn_datakey + STR_Item + STR_ID),
          'undefined.. g.dm_spawn[?_spawn_datakey+STR_Item+STR_ID]',
        ),
      )
      self.dm_LOCATIONS.set(_loc_num_ + STR_Item + STR_ID, _item_id) // _loc_num's vanilla item_id
      self.dm_LOCATIONS.set(_item_id + STR_Location + STR_Num, _loc_num) // item_id's vanilla _loc_num

      if (inList(self.dl_item_location_NUMS, _loc_num)) self.dl_ITEMS.add(_item_id)
      else if (inList(self.dl_pbag_location_NUMS, _loc_num)) self.dl_PBAGS.add(_item_id)
      else if (inList(self.dl_key_location_NUMS, _loc_num)) self.dl_KEYS.add(_item_id)

      break // _j
    }
  }
}
