// ---- port-only recursion guard -------------------------------------------------------------------

/** Deepest `Rando_is_qual_location` nesting the port allows; ZALiA's data never gets past ~5. */
const QUAL_DEPTH_LIMIT = 64

/** One warning per process, not one per placement attempt. */
let qualGuardWarned = false

// ---- repeated GML idioms -------------------------------------------------------------------------

/**
 * `val(dm_save_data[?STR_Dungeon+STR_Rando+<name>+"A"], <name>)` — `<name>+"A"` is "the overworld dungeon
 * that holds dungeon `<name>`", i.e. the palace the player has to walk up to.
 */
const owDungeon = (self: Rando, DUNGEON_NAME: string): string =>
  String(self.dm_save_data.val(STR_Dungeon + STR_Rando + DUNGEON_NAME + 'A', DUNGEON_NAME))

/** `val(dm_save_data[?STR_Town+STR_Rando+<name>+"A"], <name>)` — the overworld town that holds `<name>`. */
const owTown = (self: Rando, TOWN_NAME: string): string =>
  String(self.dm_save_data.val(STR_Town + STR_Rando + TOWN_NAME + 'A', TOWN_NAME))

/**
 * The key gate every dungeon case opens with:
 * `Rando_is_attainable(STR_ALLKEY) || Rando_attainable_key_count(val(g.dm_dungeon[?STR_Dungeon+STR_Num+
 * <name>], <vanilla num>)) >= <need>`
 */
function hasKeys(self: Rando, DUNGEON_NAME: string, VANILLA_NUM: number, need: number): boolean {
  if (Rando_is_attainable(self, STR_ALLKEY)) return true
  const _num = Number(g.dm_dungeon.val(STR_Dungeon + STR_Num + DUNGEON_NAME, VANILLA_NUM))
  return Rando_attainable_key_count(self, _num) >= need
}

/**
 * The spell-sequence puzzle loop shared by the SHIELD (`STR_Sequence+"01"`), PENDANT (`"02"`) and Kasuto
 * Cemetery Kakusu (`"03"`) checks: `_spell_seq` is a string of 4 two-char spell bits; the reward is only
 * reachable once every spell named in the sequence has been placed. A quest with no sequence recorded in
 * `f.dm_quests` is not qualified (ZALiA's `_return` stays false / `_count` is never incremented).
 */
function spellSequenceAttainable(self: Rando, _dk: string): boolean {
  const _quest_seq = f.dm_quests.get(_dk)
  if (_quest_seq === undefined) return false

  const _spell_seq = String(self.dm_save_data.val(_dk, _quest_seq))
  const _count = _spell_seq.length >> 1
  for (let _i = 0; _i < _count; _i++) {
    const _spell_name = g.dm_Spell.get(string_copy(_spell_seq, (_i << 1) + 1, 2) + STR_Name)
    if (_spell_name === undefined || !Rando_is_attainable(self, String(_spell_name))) {
      return false
    }
  }
  return true
}

// ---- Rando_is_qual_location ----------------------------------------------------------------------

/** `Rando_is_qual_location(location id, *item exception)` */
export function Rando_is_qual_location(self: Rando, LOCATION_ID: unknown, ITEM_ID = 'undefined'): boolean {
  // location id = rm name + rm item num. Some call sites pass a real (a location num), so coerce.
  const _LOCATION_ID = String(LOCATION_ID)

  if (self.qualStack.has(_LOCATION_ID) || self.qualDepth >= QUAL_DEPTH_LIMIT) {
    if (!qualGuardWarned) {
      qualGuardWarned = true
      sdm(`Rando_is_qual_location: recursion guard tripped on "${_LOCATION_ID}" (depth ${self.qualDepth})`)
    }
    return false
  }

  self.qualStack.add(_LOCATION_ID)
  self.qualDepth++
  try {
    return qualLocationBody(self, _LOCATION_ID, ITEM_ID)
  } finally {
    self.qualStack.delete(_LOCATION_ID)
    self.qualDepth--
  }
}

