/** `f_init()` / `f_Game_End()` — the parts of the f singleton's init that need the world. */
import { SAVE_FILE_MAX, SAVE_NAME_NULL, STR_Encoded, STR_File, STR_Save } from '@z2/data'
import { hexStr } from '../../nes/hexStr'
import { f, world } from '../../runtime/world'
import { gd } from './deps'
import { get_saved_value, init_save_data1 } from './save'

/** `f_init()` — read every slot's text into `dm_save_file_data`, names into `dl_save_names`, seed defaults. */
export function f_init(): void {
  f.dm_save_file.clear()
  f.dm_save_file_data.clear()
  for (let i = 0; i < SAVE_FILE_MAX; i++) {
    const name = f.dl_file_names.get(i) as string
    if (world.storage.exists(name)) {
      f.dm_save_file_data.set(
        STR_Save + STR_File + hexStr(i + 1) + STR_Encoded,
        world.storage.readText(name) ?? '',
      )
    }
  }
  f.dm_save_file_settings.clear()
  f.dl_save_names.clear()
  for (let i = 0; i < SAVE_FILE_MAX; i++) {
    f.dl_save_names.add(String(get_saved_value(i + 1, f.SDNAME_save_name, SAVE_NAME_NULL)))
  }
  f.lives = gd().STARTING_LIVES
  init_save_data1()
}

/** `f_Game_End()` — GML destroyed every ds_*; here the maps are simply cleared. */
export function f_Game_End(): void {
  for (const m of [
    f.dm_challenges,
    f.dm_keys,
    f.dm_keys_DEFAULT,
    f.dm_openedLocks,
    f.dm_kakusu,
    f.dm_PBags,
    f.dm_PBags_DEFAULT,
    f.dm_1up_doll,
    f.dm_1up_doll_DEFAULT,
    f.dm_explored,
    f.dm_jars,
    f.dm_jars_DEFAULT,
    f.dm_quests,
    f.dm_rando_full,
    f.dm_rando,
    f.dm_rando_dungeon_tileset,
    f.dm_save_file,
    f.dm_save_file_data,
    f.dm_save_file_settings,
  ])
    m.clear()
  f.dl_save_names.clear()
}
