// Ported from ZALiA scripts: DeathScreen_Create, DeathScreen_Step, DeathScreen_Draw (generated by rooms/_port/convert.py, then hand-finished).
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML state, typed progressively

import { Instance } from '../../runtime/instance'
import { f, G, g, p } from '../../runtime/world'
import { clamp, withInstance } from '../Game/gm'
import { set_background_color } from '../graphics/index'
import { gmBool } from '../math/index'
import { notPorted } from '../pending'
import { viewXL, viewXR, viewYB, viewYT } from '../view/camera'
import { draw_pc_skin, pc_is_cucco, pc_is_fairy, pcRef } from './deps'
import { draw_sprite_ } from './draw'
import { gmb } from './gmExtra'
import { room_goto_ } from './goto'
import { roomName } from './roomChange'

export class DeathScreen extends Instance {
  readonly objectName = 'DeathScreen'
  DEATH_FLASH_START_CUE: any = undefined
  DEATH_FLASH_TIMER_DUR: any = undefined
  DEATH_FLASH_TIMER_START_CUE: any = undefined
  DEATH_SCREEN_END_DUR: any = undefined
  counter: any = undefined
  deathFlashTimer: any = undefined
  deathScreenEndTimer: any = undefined
  constructor() {
    super()
    DeathScreen_Create(this)
  }
  step(): void {
    DeathScreen_Step(this)
  }
  draw(): void {
    DeathScreen_Draw(this)
  }
}

/** GML: DeathScreen_Create(self) */
export function DeathScreen_Create(self: DeathScreen) {
  self.counter = 0
  self.DEATH_FLASH_TIMER_START_CUE = 4
  self.DEATH_FLASH_TIMER_DUR = 7 // #$07 at $050E in RAM
  self.deathFlashTimer = 0
  self.DEATH_FLASH_START_CUE = 5
  self.DEATH_SCREEN_END_DUR = 3
  self.deathScreenEndTimer = 0
}

/** GML: DeathScreen_Step(self) */
export function DeathScreen_Step(self: DeathScreen) {
  if (gmb(self.deathScreenEndTimer)) {
    self.deathScreenEndTimer--
    if (!gmb(self.deathScreenEndTimer)) {
      f.death_count++
      // FIXED: GML `lives--` is unqualified on a DeathScreen that never declares it — the counter is
      // `f.lives` (`f_init`, HUD, NextLifeScreen, the 1-up doll). See FIDELITY_NOTES.
      f.lives--
      if (f.lives > 0) {
        room_goto_('rmB_NextLife')
      } else {
        room_goto_('rmB_GameOver')
      }
    }
  }
  // timer_b_DURATION1=$14, tmr_b resets at -1. So this happens every 21 frames
  if (gmb(self.deathFlashTimer) && g.timer_b === g.timer_b_DURATION1) {
    self.deathFlashTimer--
    if (!gmb(self.deathFlashTimer)) {
      self.deathScreenEndTimer = self.DEATH_SCREEN_END_DUR // DEATH_SCREEN_END_DUR = 3
    }
  }
  // DEATH_FLASH_TIMER_START_CUE = 4
  if (self.counter === self.DEATH_FLASH_TIMER_START_CUE) {
    self.deathFlashTimer = self.DEATH_FLASH_TIMER_DUR // DEATH_FLASH_TIMER_DUR = 7
  }
  self.counter++
}

/** GML: DeathScreen_Draw(self) */
export function DeathScreen_Draw(self: DeathScreen) {
  let _PAD: any, _X: any, _Y: any

  // -------------------------------------------------------------------------------
  // Before Flashing ---------------------------------------------------
  //&&  global.BackgroundColor_at_death>=0 )
  if (self.counter < self.DEATH_FLASH_START_CUE) {
    // NOT setting the background_colour here looks better.
    // Setting it here gives an abrupt-like, but brief(maybe less than 1 frame?), flash of the background color of the room that the death occured.
    //set_background_color(global.BackgroundColor_at_death);
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  /*
if (counter<DEATH_FLASH_START_CUE)
{
    //set_background_color(p.dl_COLOR.get(|p.background_color_index));
    exit; // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
}
*/
  // -------------------------------------------------------------------------------
  // During Flashing ---------------------------------------------------
  if (self.deathFlashTimer > 0) {
    if (p.BackgroundFlash_setting === 1) {
      set_background_color(p.dg_color_seq[0]?.[g.counter1 & 0x03] ?? 0)
    } else {
      set_background_color(p.C_RED3) // 20231107. I think this should only be red for death and matches the gameover bgr color
    }
    {
      // with(global.pc)
      const pc = pcRef()
      if (pc) {
        _PAD = 0x09
        _X = clamp(g.last_dist_from_view_x, viewXL() + _PAD, viewXR() - _PAD)
        _Y = clamp(g.last_dist_from_view_y, viewYT() + _PAD, viewYB() - _PAD)
        if (gmb(pc_is_cucco())) {
          draw_sprite_('spr_chicken_1a_damage_1a', 0, _X, _Y, -1, g.last_pc_xscale, 1, p.C_BLK1)
        } else if (gmb(pc_is_fairy())) {
          draw_sprite_(pc.fairy_sprite, 0, _X, _Y, -1, g.last_pc_xscale, 1, p.C_BLK1)
        } else {
          draw_pc_skin(_X, _Y, g.last_pc_xscale, 1, pc.behavior_DAMAGE, false, 1, 1, -1, p.C_BLK1)
        }
      }
    }
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // -------------------------------------------------------------------------------
  // After Flashing ----------------------------------------------------
  // DEATH_SCREEN_END_DUR=3
  if (self.deathScreenEndTimer === self.DEATH_SCREEN_END_DUR) {
    set_background_color(p.C_BLK1)
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
}
