/**
 * `get_palette_via_file_data` — decode a scene's BGR palettes (PI_BGR1..4) from the Tiled `palette` layer.
 *
 * Layout in the Tiled file (columns = palettes, rows = colours in `WRBGYMKC` order): for
 * `tile_data_system_v.03` and earlier the palette block starts at column 2 (col 0 = base colours,
 * col 1 = gui colours) and row 1 (row 0 is always black); from v.04 it starts at column 1, row 0.
 * A tile's low byte indexes `DL_COLOR` (v3) or `DL_COLOR01` (v4+); an empty cell means the base colour
 * (black for "G").
 *
 * ZALiA pre-decoded every scene into `PaletteData01.txt`; here the map is decoded on demand — the map is
 * already loaded for the scene's tiles, so nothing is lost.
 */
import {
  C_BLK1,
  ColorGrid_CLMS,
  color_str,
  DL_COLOR,
  DL_COLOR01,
  PAL_BASE_COLOR_ORDER,
  PAL_CHAR_PER_COLOR,
  str_hex,
} from './colors'
import type { TiledMapLike } from './deps'
import { build_pal, get_pal_color } from './palString'
import { BGR_COUNT } from './pi'

/** Base palette string (`p.PAL_BASE`) built without needing the singleton. */
const PAL_BASE = build_pal()

export function tileDataSystemVersion(map: TiledMapLike): number {
  for (const layer of map.layers ?? []) {
    const name = layer.name ?? ''
    if (name.includes('tile_data_system') || name.includes('palette-v.')) {
      const at = name.indexOf('v.')
      return str_hex(name.substr(at + 2, 2))
    }
  }
  return 3
}

/** Returns the concatenated BGR palettes (`BGR_COUNT` × 48 chars) or `undefined` if the map has no palette layer. */
export function decodeScenePalette(map: TiledMapLike): string | undefined {
  const layers = map.layers
  if (!layers) return undefined
  const ver = tileDataSystemVersion(map)
  for (const layer of layers) {
    const name = layer.name
    if (name === undefined || !name.includes('palette')) continue
    const tiles = layer.data
    const clms = map.width
    if (!tiles || clms === undefined) continue
    let out = ''
    for (let j = 0; j < BGR_COUNT; j++) {
      // each palette (clm)
      const cols: (number | string)[] = []
      for (let k = 0; k < PAL_BASE_COLOR_ORDER.length; k++) {
        // each color (row)
        const baseChar = PAL_BASE_COLOR_ORDER[k] as string
        let idx = clms * k + j
        idx++ // +1 to skip base color column
        if (ver < 4) {
          idx++ // +1 to skip gui colors column
          idx += clms // first row is GRN0 and is always black
        }
        let tsrc = tiles[idx] ?? 0
        let color: number | string
        if (tsrc !== 0) {
          // 0 means no tile here
          tsrc--
          tsrc = Math.abs(tsrc & 0x3fffffff) // just incase x or y flipped
          tsrc &= 0xff
          if (ver >= 4) {
            const gi = ((tsrc >> 4) & 0xf) * ColorGrid_CLMS + (tsrc & 0xf)
            color = color_str(DL_COLOR01[gi] ?? 0)
          } else {
            color = color_str(DL_COLOR[tsrc] ?? 0)
          }
        } else if (baseChar === 'G') color = C_BLK1
        else color = get_pal_color(PAL_BASE, 0, baseChar)
        cols.push(color)
      }
      out += build_pal(...cols)
    }
    return out
  }
  return undefined
}

/** Colour chars per palette, for callers that want the BGR block width. */
export const BGR_BLOCK_CHARS = BGR_COUNT * PAL_BASE_COLOR_ORDER.length * PAL_CHAR_PER_COLOR
