/** GO_sprite_init, GO_set_sprite, GO_set_sprite_index, GO_change_sprite_index, GO_depth_init (scripts/game_object/go) */
import type { GameObject } from '../classes'
import { spriteMeta } from '../sprites'
import { set_xy } from './movement'

/** `GO_sprite_init(sprite)` */
export function GO_sprite_init(self: GameObject, sprite: string): void {
  self.sprite = sprite
  GO_set_sprite_index(self, sprite)
}

/** `GO_set_sprite(instance id, sprite)` — sets the value of GameObject.sprite */
export function GO_set_sprite(inst: GameObject, sprite: string): void {
  inst.sprite = sprite
}

/** `GO_set_sprite_index(sprite)` — so that ww, hh, si_xoff, si_yoff are updated any time sprite_index changes. */
export function GO_set_sprite_index(self: GameObject, sprite: string): void {
  const m = spriteMeta(sprite)
  self.sprite_index = sprite
  self.sprite_index_xoff = m.xorig
  self.sprite_index_yoff = m.yorig
  self.ww = m.width
  self.hh = m.height
  self.ww_ = self.ww >> 1
  self.hh_ = self.hh >> 1
}

/** `GO_change_sprite_index(inst id, sprite, *alignment x, *alignment y)` — 0: center, 1: right, -1: left */
export function GO_change_sprite_index(inst: GameObject, sprite: string, alignX = 0, alignY = 0): void {
  const _ALIGN_X = Math.sign(alignX)
  const _ALIGN_Y = Math.sign(alignY)
  let _X = inst.x + inst.ww_ * _ALIGN_X
  let _Y = inst.y + inst.hh_ * _ALIGN_Y
  GO_set_sprite_index(inst, sprite)
  _X += inst.ww_ * -_ALIGN_X
  _Y += inst.hh_ * -_ALIGN_Y
  set_xy(inst, _X, _Y)
}

/** `GO_depth_init(default depth)` */
export function GO_depth_init(self: GameObject, depth: number): void {
  self.depth_def = depth
  self.depth = depth
}
