/** `ZoraA` — ZALiA `enemy/zora`: Zora that surfaces to stand and shoot. 9A2A */
import { CS_BD1, MAX_GOC1, UIDX_NULL } from '@z2/data'
import { gmBool } from '../../../../../../nes/math8'
import { G, g } from '../../../../../../runtime/world'
import { GO_update_cs } from '../../../../../collision/cs'
import { viewW, viewXL } from '../../../../../collision/env'
import { wINwAll } from '../../../../../collision/geometry'
import { enemy_collide_pc_body } from '../../../../../collision/pc'
import { avail_uidx_goc } from '../../../../../game_object_mgr/slots'
import { registerObjectClass } from '../../../../../other/registry'
import { pal_swap_reset, pal_swap_set } from '../../../../../palette/scenePalette'
import { draw_sprite_ } from '../../../../../rooms/draw'
import { Enemy } from '../../../../classes'
import { GOC1_create } from '../../../../create'
import { GO_draw_sprite } from '../../../../go/draw'
import { dir_to_pc } from '../../../../go/misc'
import { updateX } from '../../../../go/movement'
import { GO_init_palidx } from '../../../../go/palette'
import { GO_change_sprite_index, GO_set_sprite } from '../../../../go/sprite'
import type { ObjectName } from '../../../../objectNames'
import { registerObject, registerScripts } from '../../../../registry'
import { GOB_update_1, GOB_update_2 } from '../../../GameObjectB'
import { Enemy_update_2, Enemy_update_3, rand } from '../../shared'

export class ZoraA extends Enemy {
  readonly objectName = 'ZoraA' as const
  SPR_IDLE: string = 'spr_Zora_body_B'
  SPR_WALK: string = 'spr_Zora_body_A'
  SPR_HEAD: string = 'spr_Zora_head'
  SPR_STND: string = 'spr_Zora_stand'
  Head_xoff = 0
  VSPD_GRAV = 2
  shoot_timer = 0 // 0081,X
  frwd_bkwd = 0
  COLLISION_VER = 2
  BODY_HB_IDX_TALL = 0x2c
  BODY_HB_IDX_SHRT = 0x2b
  CS_OFF_IDX_TALL = 0x13
  CS_OFF_IDX_SHRT = 0x12
}
registerObject('ZoraA', ZoraA)
registerObjectClass('ZoraA', ZoraA)

/** `Zora_init2()` */
export function Zora_init2(self: ZoraA): void {
  GO_init_palidx(self, G.PI_MOB_BLU)
  self.SPR_IDLE = 'spr_Zora_body_B' // legs open
  self.SPR_WALK = 'spr_Zora_body_A' // legs closed
  self.SPR_HEAD = 'spr_Zora_head' // not standing
  self.SPR_STND = 'spr_Zora_stand' // attack stand
  self.Head_xoff = 0
  self.projectile_OBJ = 'Bullet2'
  self.projectile_VER = 1
  self.projectile = self.projectile_OBJ
  self.projectile_ver = self.projectile_VER
  self.VSPD_GRAV = 2
  self.vspd_grav = self.VSPD_GRAV
  self.shoot_timer = 0 // 0081,X
  self.frwd_bkwd = self.facing_dir
  self.COLLISION_VER = 2
  switch (self.COLLISION_VER as number) {
    case 1:
      self.BODY_HB_IDX_TALL = 0x02
      self.BODY_HB_IDX_SHRT = 0x0a
      self.BodyHB_idx = self.BODY_HB_IDX_SHRT
      self.CS_OFF_IDX_TALL = 0x05
      self.CS_OFF_IDX_SHRT = 0x05
      self.cs_off_idx = self.CS_OFF_IDX_SHRT
      break
    case 2:
      self.SPR_WALK = 'spr_Zora_Low_1a' // legs closed
      self.SPR_IDLE = 'spr_Zora_Low_1b' // legs open
      self.SPR_STND = 'spr_Zora_High_1a' // standing
      GO_change_sprite_index(self, self.SPR_IDLE, 0, 1)
      self.BODY_HB_IDX_TALL = 0x2c
      self.BODY_HB_IDX_SHRT = 0x2b
      self.BodyHB_idx = self.BODY_HB_IDX_SHRT
      self.CS_OFF_IDX_TALL = 0x13
      self.CS_OFF_IDX_SHRT = 0x12
      self.cs_off_idx = self.CS_OFF_IDX_SHRT
      break
  }
}

/** `Zora_udp()` */
export function Zora_udp(self: ZoraA): void {
  self.can_draw_self = true
  if (gmBool(self.shoot_timer)) self.Head_xoff = -self.facing_dir
  else self.Head_xoff = 0
  if (gmBool(self.timer)) {
    GO_set_sprite(self, self.SPR_STND)
  } else {
    GO_set_sprite(self, self.SPR_IDLE)
    if (gmBool(self.hspd)) {
      let _val = self.hspd
      if (self.hspd & 0x80) _val ^= 0xff
      if (_val < 9) _val = 8
      else _val = 4
      if (!(g.counter1 & _val)) GO_set_sprite(self, self.SPR_WALK)
    }
  }
}

/** `Zora_update()` */
export function Zora_update(self: ZoraA): void {
  if (gmBool(self.timer)) {
    // tall/standing
    self.BodyHB_idx = self.BODY_HB_IDX_TALL
    self.cs_off_idx = self.CS_OFF_IDX_TALL
  } else {
    // short
    self.BodyHB_idx = self.BODY_HB_IDX_SHRT
    self.cs_off_idx = self.CS_OFF_IDX_SHRT
  }
  // 9A2A
  if (!(g.counter1 & 0x3f) && rand(self) & 0x01) self.shoot_timer = 0x0a // $A: 0.167s
  GO_update_cs(self)
  Enemy_update_3(self) // update vertical
  // 9A3D
  const _OCS = self.ocs
  if (self.COLLISION_VER === 2) {
    const _BITS = 0x03 << (3 * (gmBool(self.facing_dir) ? 0 : 1)) // $03 or $18
    let _DIST = (self.ww_ - 4) * self.facing_dir
    if (gmBool(self.timer)) _DIST = 4 * self.facing_dir
    // if head is in view
    if (wINwAll(self.x + _DIST - 4, 8, viewXL(), viewW()))
      self.ocs &= ~_BITS // guarantee bits clear to allow collision checking
    else self.ocs |= _BITS // guarantee bits set to prevent collision checking
  }
  GOB_update_2(self) // collision checking
  if (self.COLLISION_VER === 2) self.ocs = _OCS
  if (self.cs & CS_BD1) enemy_collide_pc_body(self)
  // 9A4F
  GOB_update_1(self, self.cs & 0x04) // update hspdPB
  GO_update_cs(self)
  if (!(self.cs & 0x03)) updateX(self)
  // 9A52
  if (!(g.counter1 & 0x3f)) self.facing_dir = dir_to_pc(self)
  self.hspd = 0
  // 9A5F. NOT standing
  if (!gmBool(self.timer)) {
    // 9A64.  Stand up
    if (!gmBool(g.counter1)) self.timer = 0x50 // $50: 1.333s
    self.counter = (self.counter + 1) & 0xff // for updating hspd
    Enemy_update_2(self) // update hspd
  }
  // 9A70
  if (gmBool(self.shoot_timer)) {
    self.shoot_timer--
    if (!gmBool(self.shoot_timer) && avail_uidx_goc(MAX_GOC1) !== UIDX_NULL) {
      // 9A78
      let _xl = self.xl
      let _yt = self.yt
      if (gmBool(g.mod_ZoraProjectileXY)) {
        // More accurately spawn near mouth.
        const _YOFF = 4
        if (gmBool(self.timer)) {
          // if standing
          _xl = gmBool(self.facing_dir) ? self.x : self.x - 8
          _yt = self.yt + _YOFF
        } else {
          _xl = gmBool(self.facing_dir) ? self.x + 8 : self.xl
          _yt = self.y
        }
      } else {
        // if standing
        if (gmBool(self.timer)) _xl += gmBool(self.facing_dir) ? 14 : -8
        _yt += gmBool(self.timer) ? 4 : 12
      }
      // Bullet2, pID $11. PI_MOB2: red
      GOC1_create(
        _xl,
        _yt,
        self.facing_dir,
        self.projectile as ObjectName,
        self.projectile_ver,
        self,
        G.PI_MOB_RED,
      )
    }
  }
}

/** `Zora_draw()` */
export function Zora_draw(self: ZoraA): void {
  if (!self.can_draw_self) return
  pal_swap_set(self.palidx)
  GO_draw_sprite(self, self.sprite)
  if (self.COLLISION_VER === 1 && self.sprite !== self.SPR_STND) {
    draw_sprite_(
      self.SPR_HEAD,
      0,
      self.drawX + 0x10 * self.xScale + self.Head_xoff,
      self.drawY,
      -1,
      self.xScale,
    )
  }
  pal_swap_reset()
}

registerScripts({ Zora_init2, Zora_update, Zora_udp, Zora_draw })
