/** `data_go_prop1/2/3`, `data_REFLECT_vuln` — writers of `g.dm_go_prop` (ported from scripts of the same name). */
import {
  dk_AttackLevel,
  dk_FullName,
  dk_ReactBody,
  dk_ReactEnigma,
  dk_ReactProj,
  dk_ReactShield,
  dk_ReactSword,
  dk_ReactThun,
  STR_BodyHB,
  STR_Brightness,
  STR_CS_Off,
  STR_Drop,
  STR_Height,
  STR_HP,
  STR_Idx,
  STR_Object,
  STR_Placement_spr,
  STR_pal_idx,
  STR_REFLECT,
  STR_Respawn,
  STR_Vulnerable,
  STR_Width,
  STR_XP,
  STR_XP_Drain,
} from '@z2/data'
import { hexStr } from '../../../nes/hexStr'
import { goData } from '../goData'
import { isAncestorName, type ObjectName } from '../objectNames'
import { spriteMeta } from '../sprites'

/** `data_go_prop1(object_index, obj full name, placement sprite)` → object name */
export function data_go_prop1(object: ObjectName, fullName: string, sprite: string): ObjectName {
  const m = goData.dm_go_prop
  m.set(object + STR_Object + STR_Idx, object)
  m.set(object + dk_FullName, fullName)
  m.set(object + STR_Placement_spr, sprite)
  const meta = spriteMeta(sprite)
  m.set(object + STR_Width, meta.width)
  m.set(object + STR_Height, meta.height)
  return object
}

/**
 * `data_go_prop2(objver, *palette idx, *body hb id, *cs off id, *hp idx, *atk lvl, *xp idx, *respawn,
 *   *drop id, *react sword, *react proj, *react THUNDER, *react SPELL, *xp drain, *brightness)`
 * `_OBJVER` example: "MoblA01" — "MoblA" is the object, "01" the version. Negative/omitted = keep.
 */
export function data_go_prop2(
  objver: string,
  palidx = -1,
  bodyHb = -1,
  csOff = -1,
  hpIdx = -1,
  atkLvl = -1,
  xpIdx = -1,
  respawn = -1,
  dropId = -1,
  reactSw = -1,
  reactPr = -1,
  reactTh = -1,
  reactSp = -1,
  xpDrain = -1,
  bright = -1,
): void {
  const m = goData.dm_go_prop
  if (palidx >= 0) m.set(objver + STR_pal_idx, palidx)
  if (bodyHb >= 0) m.set(objver + STR_BodyHB, bodyHb)
  if (csOff >= 0) m.set(objver + STR_CS_Off, csOff)
  if (hpIdx >= 0) m.set(objver + STR_HP, hpIdx)
  if (atkLvl >= 0) m.set(objver + dk_AttackLevel, atkLvl)
  if (xpIdx >= 0) m.set(objver + STR_XP, xpIdx)
  if (respawn >= 0) m.set(objver + STR_Respawn, respawn)
  if (dropId >= 0) m.set(objver + STR_Drop, dropId)
  if (reactSw >= 0) m.set(objver + dk_ReactSword, reactSw)
  if (reactPr >= 0) m.set(objver + dk_ReactProj, reactPr)
  if (reactTh >= 0) m.set(objver + dk_ReactThun, reactTh)
  if (reactSp >= 0) m.set(objver + dk_ReactEnigma, reactSp)
  if (xpDrain >= 0) m.set(objver + STR_XP_Drain, xpDrain)
  if (bright >= 0) m.set(objver + STR_Brightness, bright)
  // objver = object name + 2 hex digits (hex_str(ver)); the object lookup is by the object name.
  const objName = objver.slice(0, -2) as ObjectName
  const obj = m.get(objName + STR_Object + STR_Idx) as ObjectName | undefined
  if (
    obj &&
    isAncestorName(obj, 'Enemy') &&
    !isAncestorName(obj, 'Boss') &&
    !isAncestorName(obj, 'Kakusu') &&
    goData.dl_Enemy_OBJVER.findIndex(objver) === -1
  ) {
    goData.dl_Enemy_OBJVER.add(objver)
  }
}

/** `data_go_prop3(objver, *react PC Body, *react PC shield)` */
export function data_go_prop3(objver: string, reactBody = -1, reactShield = -1): void {
  const m = goData.dm_go_prop
  if (reactBody >= 0) m.set(objver + dk_ReactBody, reactBody)
  if (reactShield >= 0) m.set(objver + dk_ReactShield, reactShield)
}

/** `data_REFLECT_vuln(obj name + ver, projectile obj name + ver, *projectile obj name + ver..)` */
export function data_REFLECT_vuln(objver: string, ...projectiles: string[]): void {
  if (projectiles.length < 1) return
  const dk = objver + STR_REFLECT + STR_Vulnerable
  projectiles.forEach((p, i) => {
    goData.dm_go_prop.set(dk + hexStr(i + 1), p)
    goData.dm_go_prop.set(dk + p, true)
  })
}
