/**
 * `dev_start_pc_with()` — dev preload of items/spells/levels, gated by ZALiA's `switch(0)`: case 0 exits, so
 * the presets never run in the shipped build. Kept as a selectable preset table (`DEV_START_PRESET` = 0 →
 * off) so dev tooling can enable it later; the full GML case bodies are reproduced for the used ones.
 */
import {
  ITM_CAND,
  ITM_FTHR,
  ITM_GLOV,
  ITM_SKEY,
  SKILL_THD,
  SKILL_THU,
  SPL_FARY,
  SPL_FIRE,
  SPL_JUMP,
  SPL_LIFE,
  SPL_PRTC,
  SPL_RFLC,
  SPL_SPEL,
  SPL_THUN,
  STR_Heart,
  STR_Magic,
} from '@z2/data'
import { f } from '../../../runtime/world'
import { cont_piece_cnt_hp, cont_piece_cnt_mp, get_stat_max } from '../../file/stats'
import { hex_str } from '../../other/index'

/** 0: off (ZALiA's `switch(0)`); 1..13 select a preset (2 = Thunderbird testing, 9 = feather only, …). */
export const devStart = { preset: 0 }

function addContainers(stat: 'hp' | 'mp', count: number): void {
  const per = f.CONT_PIECE_PER
  const cur = stat === 'hp' ? cont_piece_cnt_hp() : cont_piece_cnt_mp()
  for (let _i = cur + 1; _i <= count * per; _i++) {
    const _str = hex_str(Math.trunc(_i / per)) + hex_str((_i % per) + 1)
    if (stat === 'hp') f.cont_pieces_hp += _str
    else f.cont_pieces_mp += _str
  }
}

export function dev_start_pc_with(): void {
  switch (devStart.preset) {
    case 0:
      return
    case 2: {
      // Testing Thunderbird
      f.items |= ITM_CAND | ITM_SKEY
      f.level_atk = 8
      f.level_mag = 8
      f.level_lif = 8
      addContainers('hp', 8)
      addContainers('mp', 8)
      f.mp = get_stat_max(STR_Magic)
      f.spells |= SPL_PRTC | SPL_JUMP | SPL_LIFE | SPL_FARY | SPL_FIRE | SPL_RFLC | SPL_SPEL | SPL_THUN
      f.skills |= SKILL_THD | SKILL_THU
      break
    }
    case 4: {
      // Testing Carock
      f.items |= ITM_CAND
      f.level_mag = 5
      f.spells |= SPL_RFLC
      addContainers('mp', 8)
      break
    }
    case 9:
      f.items |= ITM_FTHR
      break
    case 11: {
      f.items |= ITM_CAND | ITM_GLOV
      f.skills |= SKILL_THD
      f.hp = get_stat_max(STR_Heart)
      break
    }
    default:
      break
  }
}
