/** `NPC_B_end()` */
export function NPC_B_end(self: NPC_B): void {
  if (self.ver === 3) Audio.can_play_mus_rm_body = true // Darunia pogo minigame
}

/** `NPC_B_init()` — MiniGame NPC */
export function NPC_B_init(self: NPC_B): void {
  GO_sprite_init(self, NPC_get_init_sprite(self))
  update_body_hb_1a(self)
  self.sub_state = self.sub_state_IDLE
  self.hspd = 0
  self.dialogue_ver = 'A'
  self.game_requested = false
  self.COST = 0
  self.Minigame_timer = 0
  self.Minigame_DUR1 = 60 * ROOM_SPEED_BASE
  self.Minigame_display_timer_can_draw = false
  self.MINIGAME_OBJ = NOONE
  self.MINIGAME_VER = 1
  self.minigame_inst = 0
  self.MINIGAME_X = 0
  self.PRIZE_AREA_CLMS = 0x06
  self.PRIZE_AREAS_PAD = 0x05
  self.PRIZE_1_OBJ = NOONE
  self.PRIZE_1_VER = 1
  self.prize_1_inst = NOONE
  self.PRIZE_1_CLM = 0x05
  self.PRIZE_2_OBJ = NOONE
  self.PRIZE_2_VER = 1
  self.prize_2_inst = NOONE
  self.PRIZE_2_CLM = self.PRIZE_1_CLM + self.PRIZE_AREA_CLMS + self.PRIZE_AREAS_PAD
  self.PRIZE_3_OBJ = NOONE
  self.PRIZE_3_VER = 1
  self.prize_3_inst = NOONE
  self.PRIZE_3_CLM = self.PRIZE_2_CLM + self.PRIZE_AREA_CLMS + self.PRIZE_AREAS_PAD
  self.prize_obj = 0
  self.prize_ver = 0
  self.prize_num = 0
  self.POINTS_PRIZE_1 = 0 // need max - val
  self.POINTS_PRIZE_2 = 0
  self.POINTS_PRIZE_3 = 0
  const brownOutline = () => {
    // give npc a brown outline so they contrast with the black background (C_YLW4: Darkest NES Brown)
    change_pal(
      strReplaceAt(
        p.pal_rm_new,
        get_pal_col_pos(self.palidx, 'B'),
        p.PAL_CHAR_PER_COLOR,
        color_str(p.C_YLW4),
      ),
    )
    change_pal(
      strReplaceAt(
        p.pal_rm_new,
        get_pal_col_pos(self.palidx, 'K'),
        p.PAL_CHAR_PER_COLOR,
        color_str(p.C_YLW4),
      ),
    )
  }
  const placementW = (obj: string) =>
    sprite_get_width(val(goData.dm_go_prop.get(obj + STR_Placement_spr), 'spr_Placement_08x16') as string)
  switch (self.ver) {
    case 1: {
      // Target game 1
      self.MINIGAME_OBJ = 'MnGmA' // Target game
      self.MINIGAME_VER = 1 // Target game 1
      self.minigame_inst = 0
      self.MINIGAME_X = 0x40 << 3
      self.POINTS_PRIZE_1 = 0 // need: max - POINTS_PRIZE_1 (30-0=30)
      self.POINTS_PRIZE_2 = self.POINTS_PRIZE_1 + 2 // need: max - POINTS_PRIZE_2 (30-2=28)
      self.POINTS_PRIZE_3 = Math.max(self.POINTS_PRIZE_1 + 4, self.POINTS_PRIZE_2 + 2) // need: max - POINTS_PRIZE_3 (30-4=26)
      const _Y = (g.rm_row0 + 0x8) << 3
      let _w = self.PRIZE_AREA_CLMS << 3
      let _x = self.PRIZE_1_CLM << 3
      self.PRIZE_1_OBJ = 'ItmF0' // ItmF0: PBag
      self.PRIZE_1_VER = 3 // v3: 150P
      for (const it of world.instancesOf(Item)) {
        if (wINw(it.xc, 1, _x, _w)) {
          self.PRIZE_1_OBJ = it.objectName
          self.PRIZE_1_VER = it.ver
          self.prize_1_inst = it
          break
        }
      }
      _w = placementW(self.PRIZE_1_OBJ)
      _x = (self.PRIZE_1_CLM << 3) + ((self.PRIZE_AREA_CLMS << 3) >> 1) - (_w >> 1)
      if (self.prize_1_inst) set_xlyt(self.prize_1_inst, _x, _Y)
      else self.prize_1_inst = GameObject_create(_x, _Y, self.PRIZE_1_OBJ, self.PRIZE_1_VER)
      self.PRIZE_2_OBJ = 'ItmF0' // ItmF0: PBag
      self.PRIZE_2_VER = 2 // v2: 100P
      _w = placementW(self.PRIZE_2_OBJ)
      _x = (self.PRIZE_2_CLM << 3) + ((self.PRIZE_AREA_CLMS << 3) >> 1) - (_w >> 1)
      self.prize_2_inst = GameObject_create(_x, _Y, self.PRIZE_2_OBJ, self.PRIZE_2_VER)
      self.PRIZE_3_OBJ = 'ItmF0' // ItmF0: PBag
      self.PRIZE_3_VER = 1 // v1: 50P
      _w = placementW(self.PRIZE_3_OBJ)
      _x = (self.PRIZE_3_CLM << 3) + ((self.PRIZE_AREA_CLMS << 3) >> 1) - (_w >> 1)
      self.prize_3_inst = GameObject_create(_x, _Y, self.PRIZE_3_OBJ, self.PRIZE_3_VER)
      self.COST = 60
      brownOutline()
      break
    }
    case 2: {
      self.MINIGAME_OBJ = 'MnGmA' // Target game
      self.MINIGAME_VER = 2 // Target game 2
      self.minigame_inst = 0
      self.MINIGAME_X = 0x40 << 3
      self.POINTS_PRIZE_1 = 0 // need max - val
      self.POINTS_PRIZE_2 = 4
      self.PRIZE_1_OBJ = CONT_PIECE_OBJ_HP // Heart container
      self.PRIZE_1_VER = CONT_PIECE_OBJ_VER_HP // Piece of Heart
      self.COST = 20
      self.COST = 0 // testing (kept as in ZALiA)
      break
    }
    case 3: {
      // Downstab Pogo to the Top
      self.scr_draw = NPC_B_draw as never
      self.PRIZE_1_OBJ = 'ItmF0' // ItmF0: PBag
      self.PRIZE_1_VER = 5 // PBag v5: 250
      let anyItem = false
      for (const _ of world.instancesOf(Item)) {
        anyItem = true
        break
      }
      if (!anyItem) GameObject_create(0x37 << 3, 0x0e << 3, self.PRIZE_1_OBJ, self.PRIZE_1_VER) // Heart piece didn't spawn bc player already acquired it.
      self.COST = 80
      self.MINIGAME_X = 0x24 << 3
      self.Goal_XL = 0x31 << 3
      self.Goal_YB = 0x10 << 3
      self.Minigame_DUR1 = 60 * ROOM_SPEED_BASE
      self.SND_GAME_START = get_audio_theme_track(STR_Encounter + STR_Enter)
      self.SND_GAME_DONE = get_audio_theme_track(STR_Encounter + STR_Leave)
      self.MUS_GAME_THEME = `${dk_Minigame}01`
      self.MUS_GAME_ACTIVE = get_audio_theme_track(self.MUS_GAME_THEME)
      brownOutline()
      break
    }
  }
}

/** `NPC_B_update()` */
export function NPC_B_update(self: NPC_B): void {
  const P = pc()
  self.hspd = 0
  if (!NPC_update_1(self)) {
    // when NOT talking
    Merchant_update_1(self) // update_EF11(), set facingDir, counter = 0;
    if (self.sub_state === self.sub_state_IDLE || self.sub_state === self.sub_state_DONE) NPC_update_2(self)
  }
  if (self.ver === 3) {
    // Pogo to Top challenge
    if (self.Minigame_timer) {
      self.Minigame_timer--
      if (!self.Minigame_timer) {
        // Destroy all Blooby so PC cannot continue challenge w/out paying again.
        for (const b of world.instances) {
          if (!b.exists) continue // GM's `with(Obj)` skips instances destroyed earlier this frame
          const o = b as GameObject
          if (o.objectName === 'Blooby') damage_gob(o, Math.max(o.hp, 0), false)
        }
      }
    }
  }
  const DW = g.DIALOGUE_WINDOW
  switch (self.sub_state) {
    case self.sub_state_IDLE: {
      if (self.timer) break
      self.prize_num = 0
      self.dialogue_ver = 'A'
      self.Minigame_timer = 0
      self.Minigame_display_timer_can_draw = false
      if (self.is_talking && g.dialogue_source === self) {
        g.gui_state = g.gui_state_DIALOGUE3
        self.sub_state = self.sub_state_OFFER
      }
      break
    }
    case self.sub_state_OFFER: {
      // Player is offered to play minigame with "YES" or "NO" options.
      if (self.timer) break
      if (g.gui_state !== g.gui_state_NONE) break
      self.Minigame_display_timer_can_draw = false
      // A choice has been made.
      if (DW.cursor_option === input.L) {
        // "YES". Player accepted offer to play minigame.
        if (f.xp >= self.COST) {
          f.xpDrain += self.COST
          if (self.ver === 3) {
            // Pogo to Top challenge
            if (pc_is_fairy() || (pc_is_cucco() && !(f.Cucco_skills & f.CuccoSkill_THRUST_D))) {
              g.spells_active &= ~SPL_FARY
              const _DURATION = p.SpellFlash_DURATION1 // SpellFlash_DURATION1=$20. bit $80 mean flash bgr
              p.Flash_Pal_timer = _DURATION
              p.SpellFlash_PC_timer = _DURATION
              aud_play_sound(get_audio_theme_track('_Cast_Spell'))
              PC_update_1a(P) // set properties specific to PC form(cucco, fairy, Lonk)
              set_xy(P, P.x, self.yb - P.hh_)
            }
            for (const d of world.instances) {
              if (!d.exists) continue // GM's `with(Obj)` skips instances destroyed earlier this frame
              const o = d as GameObject
              if (o.objectName === 'LoDoA') o.counter = -1 // Starts opening process
            }
            self.timer = 0
            self.sub_state = self.sub_state_UNLOCK
            break
          }
          if (self.ver === 2) g.StatRestore_timer_hp = Math.max(0xff, get_stat_max(STR_Heart)) // HP
          self.minigame_inst = GameObject_create(
            self.MINIGAME_X - 8,
            self.yt,
            self.MINIGAME_OBJ as never,
            self.MINIGAME_VER,
          )
          // Go to 'during minigame' state.
          self.sub_state = self.sub_state_GAME
        } else {
          NPC_activate_dialogue(self) // Open Dialogue
          self.sub_state = self.sub_state_LOWP // Not enough money.
        }
      } else {
        self.sub_state = self.sub_state_IDLE // "NO". Player declined minigame offer.
      }
      break
    }
    case self.sub_state_LOWP: {
      // Not enough P (money)
      self.Minigame_display_timer_can_draw = false
      self.dialogue_ver = 'B'
      if (self.timer) break
      if (g.gui_state !== g.gui_state_NONE) break
      self.timer = 0
      self.sub_state = self.sub_state_IDLE
      break
    }
    case self.sub_state_UNLOCK: {
      self.Minigame_display_timer_can_draw = false
      if (self.timer) break
      let doorExists = false
      for (const d of world.instances)
        if ((d as GameObject).objectName === 'LoDoA' && d.exists) doorExists = true
      if (doorExists) break
      self.timer = 0
      self.sub_state = self.sub_state_WALK_PC
      break
    }
    case self.sub_state_WALK_PC: {
      self.Minigame_display_timer_can_draw = false
      if (self.timer) break
      if (gmBool(P.ogr)) break
      self.timer = 1 // Delay game start sound
      self.sub_state = self.sub_state_PRE_GAME1
      break
    }
    case self.sub_state_PRE_GAME1: {
      self.Minigame_display_timer_can_draw = false
      if (self.timer) break
      self.Minigame_timer = Math.max(0, self.Minigame_DUR1 - 1)
      self.Minigame_display_timer_can_draw = true
      aud_play_sound(self.SND_GAME_START as never)
      audio_group_stop_all('audiogroup_mus')
      Audio.can_play_mus_rm_body = false
      Audio.can_play_boss_music = false
      self.timer = round(audio_sound_length(self.SND_GAME_START) * ROOM_SPEED_BASE)
      self.timer += 2
      self.sub_state = self.sub_state_PRE_GAME2
      break
    }
    case self.sub_state_PRE_GAME2: {
      self.Minigame_display_timer_can_draw = true
      if (self.timer && audio_is_playing(self.SND_GAME_START)) break
      self.timer = 0
      const _POSITIONS = `${'6F2C'}${'5E2C'}${'4D25'}${'3C28'}${'2C24'}${'232C'}${'1527'}`
      for (let _i = (_POSITIONS.length >> 2) - 1; _i >= 0; _i--) {
        const _x = Number.parseInt(_POSITIONS.substr((_i << 2) + 2, 2), 16) << 3
        const _y = Number.parseInt(_POSITIONS.substr(_i << 2, 2), 16) << 3
        const b = GameObject_create(_x, _y, 'Blooby', 1)
        if (b) {
          b.hspd = 0
          const ex = GOC1_create(b.xl + 4, b.yt, 1, 'BossExplosion', 1, b)
          if (ex) GO_depth_init(ex, b.depth - 1)
        }
      }
      aud_play_sound(Audio.sound('SND_STEP_1A'))
      aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
      aud_play_sound(self.MUS_GAME_ACTIVE as never, Audio.PRIORITY_TOP, true, -1, self.MUS_GAME_THEME)
      self.timer = 0
      self.sub_state = self.sub_state_GAME
      break
    }
    case self.sub_state_GAME: {
      self.Minigame_display_timer_can_draw = true
      if (self.ver === 3) {
        // Pogo to Top Minigame Challenge
        g.pc_lock = 0
        NPC_B_update_1(self)
        break
      }
      const mg = self.minigame_inst as GameObject & {
        sub_state: number
        ST_SUB1_NPC1: number
        points: number
        POINTS_MAX: number
      }
      if (mg && mg.sub_state === mg.ST_SUB1_NPC1) {
        // minigame_inst has signaled game is done
        const _POINTS = mg.points
        const _MAX = mg.POINTS_MAX
        if (_POINTS >= _MAX - self.POINTS_PRIZE_1) self.prize_num = 1
        else if (_POINTS >= _MAX - self.POINTS_PRIZE_2) self.prize_num = 2
        else if (_POINTS >= _MAX - self.POINTS_PRIZE_3) self.prize_num = 3
        else self.prize_num = 0
        self.dialogue_ver = self.prize_num ? 'C' : 'D'
        NPC_activate_dialogue(self) // Open Dialogue
        self.timer = 0
        self.sub_state = self.sub_state_RESULT
      }
      break
    }
    case self.sub_state_POST_GAME1: {
      self.Minigame_display_timer_can_draw = true
      if (self.timer) break
      aud_play_sound(self.SND_GAME_DONE as never)
      aud_play_sound(get_audio_theme_track(dk_StrikeEnemy))
      audio_group_stop_all('audiogroup_mus')
      self.timer = round(audio_sound_length(self.SND_GAME_START) * ROOM_SPEED_BASE)
      self.timer += 2
      self.sub_state = self.sub_state_POST_GAME2
      break
    }
    case self.sub_state_POST_GAME2: {
      self.Minigame_display_timer_can_draw = true
      if (self.timer && audio_is_playing(self.SND_GAME_DONE)) break
      self.timer = 0
      if (self.Minigame_timer) self.Minigame_timer = 1
      self.timer = 0x10 // $10: 0.267s Let rm music play some before opening dlg
      self.sub_state = self.sub_state_POST_GAME3
      break
    }
    case self.sub_state_POST_GAME3: {
      self.Minigame_display_timer_can_draw = !!self.Minigame_timer
      if (self.timer) break
      Audio.can_play_mus_rm_body = true
      self.timer = 0
      self.sub_state = self.sub_state_POST_GAME4
      break
    }
    case self.sub_state_POST_GAME4: {
      self.Minigame_display_timer_can_draw = Math.sign(self.Minigame_timer)
      if (self.timer) break
      self.timer = 0
      self.sub_state = self.sub_state_DONE
      break
    }
    case self.sub_state_RESULT: {
      if (self.timer) break
      if (g.gui_state !== g.gui_state_NONE) break
      if (self.prize_num) {
        if (self.ver === 1 || self.ver === 2) {
          let _X = self.PRIZE_1_CLM + (self.PRIZE_AREA_CLMS + self.PRIZE_AREAS_PAD) * (self.prize_num - 1)
          _X = _X << 3
          let _Y = g.rm_rows - PAGE_ROWS + 0x0a
          _Y = _Y << 3
          for (let _i = 0; _i < self.PRIZE_AREA_CLMS; _i++) {
            // Remove tiles under prize so it falls to the floor.
            tile_change_1a(DEPTH_BG4, _X + (_i << 3), _Y, 0, 0, 0)
          }
          aud_play_sound(get_audio_theme_track(dk_BlockBreak))
          aud_play_sound(get_audio_theme_track(dk_BridgeCrumble))
        }
        self.timer = 0
        self.sub_state = self.sub_state_DONE
      } else {
        self.timer = 0
        self.sub_state = self.sub_state_IDLE
      }
      break
    }
    case self.sub_state_DONE: {
      // Player will have to refresh rm to play again.
      self.Minigame_display_timer_can_draw = Math.sign(self.Minigame_timer)
      if (self.timer) break
      self.dialogue_ver = 'E' // "COME BACK ANY TIME"
      break
    }
  }
}

/** `NPC_B_update_1()` — For pogo minigame */
export function NPC_B_update_1(self: NPC_B): void {
  const P = pc()
  if (!gmBool(P.ogr)) {
    if (P.xr >= self.Goal_XL && P.yb <= self.Goal_YB) {
      // Player made it to the goal
      self.prize_num = 1
      self.timer = 0
      self.sub_state = self.sub_state_POST_GAME1
      return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
    }
    if (!self.Minigame_timer) {
      // Player has NOT made it to the goal in time.
      self.timer = 0
      self.sub_state = self.sub_state_POST_GAME1
    }
  }
}

/** `NPC_B_draw()` — Minigame */
export function NPC_B_draw(self: NPC_B): void {
  if (!self.can_draw_self) return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  self.depth = self.depth_def
  GameObject_draw_1a(self, self.sprite as string, self.palidx)
  if (self.ver === 3 && gmBool(self.Minigame_display_timer_can_draw)) {
    self.depth = DEPTH_HUD
    let _TIME = 0
    if (self.Minigame_timer) _TIME = Math.trunc((self.Minigame_timer + ROOM_SPEED_BASE) / ROOM_SPEED_BASE)
    let _TEXT = String(_TIME)
    _TEXT = '0'.repeat(3 - _TEXT.length) + _TEXT
    const prev = drawState.depth
    drawState.depth = DEPTH_HUD
    draw_text_(0x22 << 3, viewYT() + (0x08 << 3), _TEXT)
    drawState.depth = prev
  }
}
