// Ported from ZALiA scripts/update_tile_anims.gml (draft via gml2ts). DEV timing/logging blocks dropped.
// biome-ignore-all lint/suspicious/noExplicitAny: ported GML, typed progressively
import {
  STR_Anim,
  STR_Cue,
  STR_Datakey,
  STR_Duration,
  STR_Frame,
  STR_frame,
  STR_Sequence,
  STR_Tileset,
} from '@z2/data'
import { hexStr as hex_str } from '../../nes/hexStr'
import { gmBool } from '../../nes/math8'
import { g } from '../../runtime/world'
import { bit_dir } from '../math/index'
import { str_hex } from '../other/index'
import { notPorted } from '../pending'
import { tile_anim_change_frame } from '../tile'
import {
  background_assign,
  background_exists,
  ds_grid_width,
  ds_list_size,
  is_undefined,
  string_copy,
  string_length,
  tile_layer_shift,
  val,
} from './gm'

/** GML: update_tile_anims() */
export function update_tile_anims() {
  // GML `var` is function-scoped; locals hoisted here:
  let _COUNT: any,
    _CUE_END: any,
    _anim_dir: any,
    _anim_duration: any,
    _anim_frame: any,
    _clm: any,
    _count: any,
    _counter: any,
    _cue: any,
    _cues: any,
    _datakey1: any,
    _datakey2: any,
    _dir: any,
    _game_frame: any,
    _i: any,
    _row: any,
    _ts1: any,
    _ts2: any,
    _val: any
  // D510: JSR A6D2, A6D6: JSR A6DD
  // let _i: any, _clm, _row, _val, _dir: any;
  // let _datakey1: any;
  // let _count: any, _counter, _cue, _cues, _CUE_END, _anim_frame, _anim_dir: any;
  _COUNT = ds_grid_width(g.dg_tile_anim)
  //for(_i=0; _i<g.T_ANIM_MAX; _i++) // 1st $10 rows reserved for crumble bridge & breakable blocks
  for (_i = 0; _i < _COUNT; _i++) {
    _counter = g.dg_tile_anim.get(_i, 1) // anim frame
    if (!gmBool(_counter)) {
      continue // >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
    }
    // ------------------------------------------------------------------
    _datakey1 = STR_Anim + hex_str(g.dg_tile_anim.get(_i, 0)) // 0: anim name
    _cues = g.dm_tile.get(_datakey1 + STR_Sequence)
    _anim_frame = g.dg_tile_anim.get(_i, 3) // 3: Anim frame num
    _anim_dir = g.dg_tile_anim.get(_i, 7) // 7: 1(normal), -1(reverse)
    // 1: Play anim in reverse at end of anim once.
    // 2: Play anim in reverse at end of anim endlessly.
    _val = g.dg_tile_anim.get(_i, 8) // 8: other, special instructions or codes
    // increment counter
    _counter += _anim_dir
    g.dg_tile_anim.set(_i, 1, _counter)
    _CUE_END = str_hex(string_copy(_cues, string_length(_cues) - 1, 2)) // last cue
    // Check for end anim
    if (gmBool(_anim_dir)) {
      _cue = _CUE_END
    } else {
      _cue = 0 // reverse anim
    }
    // End of anim
    if (_counter === _cue) {
      // FE: will loop
      // 1: play anim in opposite dir once
      if (g.dg_tile_anim.get(_i, 4) === 0xfe || _val === 1) {
        if (_val === 1) {
          _anim_dir = -_anim_dir
        }
        if (gmBool(_anim_dir)) {
          _counter = 1
        } else {
          _counter = _CUE_END
        }
        if (gmBool(_anim_dir)) {
          _anim_frame = 1
        } else {
          _anim_frame = (string_length(_cues) >> 1) - 1
        }
        if (_val !== 1 && _val !== 2) {
          _clm = (g.dg_tile_anim.get(_i, 5) >> 0) & 0xff // rm clm
          _row = (g.dg_tile_anim.get(_i, 5) >> 8) & 0xff // rm row
          _datakey1 += STR_frame + hex_str(_anim_frame)
          tile_anim_change_frame(_i, _datakey1, _clm, _row)
        }
        if (_val === 1) {
          g.dg_tile_anim.set(_i, 8, 0) // 8:other, special instructions or codes
        }
      } else {
        _counter = 0
        _anim_frame = 0
        _anim_dir = 1
      }
      g.dg_tile_anim.set(_i, 1, _counter) // set counter
      g.dg_tile_anim.set(_i, 3, _anim_frame) // set Anim frame num
      g.dg_tile_anim.set(_i, 7, _anim_dir)
    } else {
      // Check for change tile
      // Need to be >= 2. In reverse, 1 is last anim frame.
      if (gmBool(_anim_dir) || gmBool(_anim_frame - 1)) {
        _cue = _anim_frame - +!_anim_dir
        _cue = str_hex(string_copy(_cues, (_cue << 1) + 1, 2))
        //_cue  = str_hex(string_copy(_cues, ((_anim_frame - !_anim_dir)<<1)+1, 2));
        if (_cue === _counter) {
          // TODO: if changing from clear to solid,
          // make sure a falling block(BlckB) is not
          // in the way.
          // Otherwise, don't let a falling block rest
          // where there could be a pending tile anim
          // that will change solid states.
          //if (tile_anims_upadate_1a(_anim_frame,_anim_frame+_anim_dir) != 1  // if changing from clear to solid
          _anim_frame += _anim_dir
          g.dg_tile_anim.set(_i, 3, _anim_frame) // Anim frame num
          _clm = (g.dg_tile_anim.get(_i, 5) >> 0) & 0xff // rm clm
          _row = (g.dg_tile_anim.get(_i, 5) >> 8) & 0xff // rm row
          _datakey1 += STR_frame + hex_str(_anim_frame)
          tile_anim_change_frame(_i, _datakey1, _clm, _row)
        }
      }
    }
  }
  if (gmBool(g.mod_ANIMATE_LIQUID)) {
    for (_i = ds_grid_width(g.dg_anim_liquid) - 1; _i >= 0; _i--) {
      if (gmBool(g.counter1 & g.dg_anim_liquid.get(_i, 1))) {
        continue
      }
      _dir = g.dg_anim_liquid.get(_i, 2)
      if (gmBool(_dir & 0x03)) {
        g.dg_anim_liquid.set(_i, 3, g.dg_anim_liquid.get(_i, 3) + 1) /* GML2TS-TODO: map++ used as a value */
        g.dg_anim_liquid.set(_i, 3, g.dg_anim_liquid.get(_i, 3) & 0x07)
        _val = bit_dir(_dir & 0x03) // shift 1, -1
        if (!gmBool(g.dg_anim_liquid.get(_i, 3) & 0x07)) {
          _val *= -7 // Position reset to default.
        }
        tile_layer_shift(g.dg_anim_liquid.get(_i, 0), _val, 0)
      }
      if (gmBool(_dir & 0x0c)) {
        g.dg_anim_liquid.set(_i, 4, g.dg_anim_liquid.get(_i, 4) + 1) /* GML2TS-TODO: map++ used as a value */
        g.dg_anim_liquid.set(_i, 4, g.dg_anim_liquid.get(_i, 4) & 0x07)
        _val = bit_dir(_dir & 0x0c) // shift 1, -1
        if (!gmBool(g.dg_anim_liquid.get(_i, 4) & 0x07)) {
          _val *= -7 // Position reset to default.
        }
        tile_layer_shift(g.dg_anim_liquid.get(_i, 0), 0, _val)
      }
    }
  }
  if (gmBool(g.mod_CLOUD_MOVEMENT)) {
    for (_i = ds_grid_width(g.dg_anim_clouds) - 1; _i >= 0; _i--) {
      if (gmBool(g.counter1 & g.dg_anim_clouds.get(_i, 1))) {
        continue
      }
      _dir = g.dg_anim_clouds.get(_i, 2)
      if (gmBool(_dir & 0x03)) {
        g.dg_anim_clouds.set(_i, 3, g.dg_anim_clouds.get(_i, 3) + 1) /* GML2TS-TODO: map++ used as a value */
        g.dg_anim_clouds.set(_i, 3, g.dg_anim_clouds.get(_i, 3) & 0x07)
        _val = bit_dir(_dir & 0x03) // shift 1, -1
        if (!gmBool(g.dg_anim_clouds.get(_i, 3) & 0x07)) {
          _val *= -7 // Position reset to default.
        }
        tile_layer_shift(g.dg_anim_clouds.get(_i, 0), _val, 0)
      }
      if (gmBool(_dir & 0x0c)) {
        g.dg_anim_clouds.set(_i, 4, g.dg_anim_clouds.get(_i, 4) + 1) /* GML2TS-TODO: map++ used as a value */
        g.dg_anim_clouds.set(_i, 4, g.dg_anim_clouds.get(_i, 4) & 0x07)
        _val = bit_dir(_dir & 0x0c) // shift 1, -1
        if (!gmBool(g.dg_anim_clouds.get(_i, 4) & 0x07)) {
          _val *= -7 // Position reset to default.
        }
        tile_layer_shift(g.dg_anim_clouds.get(_i, 0), 0, _val)
      }
    }
  }
  if (gmBool(g.BackgroundTileAnimations_VER)) {
    _count = ds_list_size(g.dl_scene_anims)
    if (gmBool(_count)) {
      // let _datakey2: any;
      // let _ts1: any, _ts2: any;
      // let _game_frame: any, _anim_duration: any;
      for (_i = 0; _i < _count; _i++) {
        _datakey1 = g.dl_scene_anims.get(_i)
        _ts1 = g.dm_TILE_ANIM.get(_datakey1 + STR_Tileset)
        if (!is_undefined(_ts1) && background_exists(_ts1)) {
          _anim_duration = val(g.dm_TILE_ANIM.get(_datakey1 + STR_Duration))
          if (gmBool(_anim_duration)) {
            _game_frame = g.counter1 % _anim_duration
            _datakey2 = g.dm_TILE_ANIM.get(
              _datakey1 + STR_Cue + hex_str(_game_frame) + STR_Frame + STR_Datakey,
            )
            if (!is_undefined(_datakey2)) {
              _ts2 = g.dm_TILE_ANIM.get(_datakey2 + STR_Tileset)
              if (!is_undefined(_ts2) && background_exists(_ts2)) {
                background_assign(_ts1, _ts2)
              }
            }
          }
        }
      }
    }
  }
  /*
else
{
    // Fire pit, 
    //if (g.counter1&$8) background_assign(ts_Anim_1,ts_Anim_1a);
    //else               background_assign(ts_Anim_1,ts_Anim_1b);
}
*/
}
