  Caution_H: any = undefined
  Caution_W: any = undefined
  Caution_XL: any = undefined
  Caution_YT: any = undefined
  Caution_dl_text: any = undefined
  Caution_srf: any = undefined
  Cursor_SPRITE: any = undefined
  Cursor_XC: any = undefined
