/** GML: ContinueSaveScreen_init(self) */
export function ContinueSaveScreen_init(self: ContinueSaveScreen) {
  let _i: any, _clms: any, _rows: any, _ROWS1: any

  _i = 0
  self.state_DELAY1 = _i++ // Only first couple frames draw solid black screen
  self.state_IDLE = _i++ // Waiting for user input
  self.state_SELECTED = _i++ // Action of selection made
  self.state = self.state_DELAY1
  self.timer = 0
  self.counter = 0
  self.READY_CUE = 0x02
  self.TITLE_SCREEN_CUE1 = 0x48
  self.TITLE_SCREEN_CUE2 = 0x20
  self.NEXT_LIFE_SCREEN_CUE = 0x08
  self.SaveFlash_LIMIT = 8
  self.SaveFlash_count = 0
  if (gmb(G.DB0)) {
  }
  //SaveFlash_PAL   = build_pal(p.C_RED2,p.C_RED3,p.C_BLK1,p.C_BLK1,-2,-2,-2,-2);
  if (gmb(G.DB0)) {
  }
  //change_pal(strReplaceAt(p.pal_rm_curr, p.PAL_POS_BGR1, string_length(SaveFlash_PAL), SaveFlash_PAL));
  if (gmb(G.DB0)) {
  }
  self.Caution_srf = 0
  self.Caution_dl_text = ds_list_create()
  ds_list_add(self.Caution_dl_text, 'CAUTION')
  ds_list_add(self.Caution_dl_text, 'TO AVOID DAMAGING GAME')
  ds_list_add(self.Caution_dl_text, 'INFO  SAVED,  HOLD  IN')
  ds_list_add(self.Caution_dl_text, 'RESET  BUTTON  AS  YOU')
  ds_list_add(self.Caution_dl_text, 'TURN POWER OFF.')
  _clms = 0
  for (_i = ds_list_size(self.Caution_dl_text) - 1; _i >= 0; _i--) {
    _clms = max(_clms, string_length(self.Caution_dl_text.get(_i)))
  }
  _clms += _clms & 0x01
  self.Caution_dl_text.set(
    0,
    string_repeat(' ', (_clms >> 1) - (string_length(self.Caution_dl_text.get(0)) >> 1)) +
      self.Caution_dl_text.get(0),
  )
  _clms += 0x04
  self.Caution_W = _clms << 3
  self.Caution_H = ds_list_size(self.Caution_dl_text) + (ds_list_size(self.Caution_dl_text) - 1)
  self.Caution_H += 0x04
  self.Caution_H = self.Caution_H << 3
  if (gmb(G.DB0)) {
  }
  self.Options_dg = ds_grid_create(0, 4)
  //                                              //
  //                                              //
  ds_grid_resize(self.Options_dg, ds_grid_width(self.Options_dg) + 1, ds_grid_height(self.Options_dg))
  _i = ds_grid_width(self.Options_dg) - 1
  self.Option_CONT = _i
  self.Options_dg.set(_i, 0, 'CONTINUE')
  //                                              //
  //                                              //
  ds_grid_resize(self.Options_dg, ds_grid_width(self.Options_dg) + 1, ds_grid_height(self.Options_dg))
  _i = ds_grid_width(self.Options_dg) - 1
  self.Option_SAVE = _i
  self.Options_dg.set(_i, 0, 'SAVE & QUIT')
  //                                              //
  //                                              //
  ds_grid_resize(self.Options_dg, ds_grid_width(self.Options_dg) + 1, ds_grid_height(self.Options_dg))
  _i = ds_grid_width(self.Options_dg) - 1
  self.Option_QUIT = _i
  self.Options_dg.set(_i, 0, 'QUIT ONLY')
  //                                              //
  //                                              //
  self.Options_idx = self.Option_CONT
  self.Options_COUNT = ds_grid_width(self.Options_dg)
  if (gmb(G.DB0)) {
  }
  _ROWS1 = 0x02
  self.PAD1 = 0x02 << 3
  self.CLMS = self.Caution_W >> 3
  self.ROWS = self.Caution_H >> 3
  self.ROWS += self.Options_COUNT << 1
  self.ROWS += _ROWS1 // pad between option text and warning
  self.Options_XL = viewXC() - (0x05 << 3)
  self.Options_YT = viewYC() - ((self.ROWS << 3) >> 1)
  self.Caution_XL = viewXC() - (self.Caution_W >> 1)
  self.Caution_YT = self.Options_YT
  self.Caution_YT += (self.Options_COUNT << 1) << 3
  self.Caution_YT += _ROWS1 << 3 // pad between option text and warning
  self.Cursor_SPRITE = 'spr_menu_bottle_icon'
  self.Cursor_XC = self.Options_XL - (0x01 << 3)
  self.Cursor_XC += 4
  self.Cursor_XC -= 1 // Text padding
  self.Cursor_YC = self.Options_YT + 4
  self.Cursor_yc = self.Cursor_YC
  self.Cursor_yc += self.Options_idx * self.PAD1
  for (_i = 0; _i < self.Options_COUNT; _i++) {
    self.Options_dg.set(_i, 1, self.Options_XL)
    self.Options_dg.set(_i, 2, self.Options_YT + self.PAD1 * _i)
    self.Options_dg.set(_i, 3, G.PI_GUI1)
  }
}

/** GML: ContinueSaveScreen_step(self) */
export function ContinueSaveScreen_step(self: ContinueSaveScreen) {
  let _cursor_dir: any

  if (gmb(self.timer)) {
    self.timer--
  }
  switch (self.state) {
    // -----------------------------------------------------
    // -----------------------------------------------
    case self.state_DELAY1: {
      if (gmb(self.timer)) {
        break //case state_DELAY1
      }
      if (self.counter >= self.READY_CUE) {
        self.state = self.state_IDLE
      }
      break
    }
    // -----------------------------------------------------
    // -----------------------------------------------
    case self.state_IDLE: {
      if (gmb(self.timer)) {
        break //case state_IDLE
      }
      _cursor_dir = 0
      switch (G.GUI_NAV1_VER) {
        default: {
          _cursor_dir = input.Magic_pressed
          //_cursor_dir = Input.GP_Select_pressed || Input.Magic_pressed;
          break
        }
        case 2: {
          _cursor_dir = bit_dir(gui_tmr_cursor_v())
          if (_cursor_dir === 0) {
            _cursor_dir = sign(input.Magic_pressed)
          }
          //{   _cursor_dir = Input.GP_Select_pressed || Input.Magic_pressed;  }
          break
        }
      } //switch(global.GUI_NAV1_VER)
      if (_cursor_dir !== 0) {
        self.Options_idx = (self.Options_idx + _cursor_dir + self.Options_COUNT) % self.Options_COUNT
        aud_play_sound(get_audio_theme_track(dk_CursorSpellMenu))
        break //case state_IDLE
      }
      //if (Input.GP_Start_pressed
      //||  Input.Pause_pressed )  // Start button pressed
      if (gmb(input.Pause_pressed)) {
        if (self.Options_idx === self.Option_SAVE) {
          // moved these saves to the moment of button press to prevent possible app crash that I think can occur when changing rooms right after accessing a file.
          file_save(f.file_num, false)
          // Save new xp amount ------------------------
          // The exploit: When player saves here, then reload game,
          // they retain all progress AND get back the xp they
          // had when they last saved with an NPC.
          setSaved(f.file_num, STR_XP, f.xp)
        }
        self.counter = self.Options_idx
        aud_play_sound(get_audio_theme_track(dk_ItemDrop))
        self.state = self.state_SELECTED // An option has been selected
      }
      break
    }
    // -----------------------------------------------------
    // -----------------------------------------------
    case self.state_SELECTED: {
      switch (self.Options_idx) {
        // -----------------------------------------------------
        case self.Option_CONT: {
          if (gmb(self.timer)) {
            break
          }
          if (self.counter >= self.NEXT_LIFE_SCREEN_CUE) {
            audio_group_stop_all(audiogroup_mus)
            room_goto_('rmB_NextLife')
            return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
          }
          break
        }
        // -----------------------------------------------------
        case self.Option_SAVE: {
          if (gmb(self.timer)) {
            break
          }
          if (self.counter >= self.TITLE_SCREEN_CUE1) {
            goto_title_rm()
          }
          if ((self.counter & 0x07) === 0x04) {
            self.SaveFlash_count++
          }
          break
        }
        // -----------------------------------------------------
        case self.Option_QUIT: {
          if (gmb(self.timer)) {
            break
          }
          if (self.counter >= self.TITLE_SCREEN_CUE2) {
            goto_title_rm()
          }
          break
        }
      } //switch(Options_idx)
      break
    }
  } //switch(state)
  self.counter++
}

/** GML: ContinueSaveScreen_draw(self) */
export function ContinueSaveScreen_draw(self: ContinueSaveScreen) {
  let _i: any,
    _text: any,
    _xl: any,
    _yt: any,
    _pi: any,
    _j: any,
    _tsrc: any,
    _ts_x: any,
    _ts_y: any,
    _CLMS1: any,
    _ROWS1: any,
    _XL1: any,
    _YT1: any

  set_background_color(p.C_BLK1)
  if (self.state === self.state_DELAY1) {
    return // !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  }
  // -------------------------------------------------------------------------------

  _pi = G.PI_GUI1
  if (!surface_exists(self.Caution_srf)) {
    _CLMS1 = self.Caution_W >> 3
    _ROWS1 = self.Caution_H >> 3
    self.Caution_srf = surface_create(self.Caution_W, self.Caution_H)
    surface_set_target(self.Caution_srf)
    draw_clear_alpha(c_black, 0)
    for (_i = 0; _i < _ROWS1; _i++) {
      for (_j = 0; _j < _CLMS1; _j++) {
        if (_j === 0 || _j === _CLMS1 - 1 || _i === 0 || _i === _ROWS1 - 1) {
          _xl = _j << 3
          _yt = _i << 3
          if ((_j === 0 || _j === _CLMS1 - 1) && (_i === 0 || _i === _ROWS1 - 1)) {
            _tsrc = 0x22
          } /* Corner */ else if (_j === 0 || _j === _CLMS1 - 1) {
            _tsrc = 0x21
          } /* Vertical */ else {
            _tsrc = 0x20 // Horizontal
          }
          _ts_x = ((_tsrc >> 0) & 0x0f) << 3
          _ts_y = ((_tsrc >> 4) & 0x0f) << 3
          draw_background_part('ts_Menu01', _ts_x, _ts_y, 8, 8, _xl, _yt)
        }
      }
    }
    _XL1 = self.PAD1
    _YT1 = self.PAD1
    for (_i = ds_list_size(self.Caution_dl_text) - 1; _i >= 0; _i--) {
      _yt = _YT1 + self.PAD1 * _i
      draw_text_(_XL1, _yt, self.Caution_dl_text.get(_i), -1, 0)
    }
    surface_reset_target()
  }
  if (surface_exists(self.Caution_srf)) {
    pal_swap_set(G.PI_BGR1)
    draw_surface(self.Caution_srf, self.Caution_XL, self.Caution_YT)
    pal_swap_reset()
  }
  // -------------------------------------------------------------------------------
  if (
    self.state === self.state_SELECTED &&
    self.Options_idx === self.Option_SAVE &&
    self.SaveFlash_count <= self.SaveFlash_LIMIT &&
    gmb(self.counter & 0x04)
  ) {
    _pi = G.PI_BGR1
  } else {
    _pi = G.PI_GUI1
  }
  self.Options_dg.set(self.Option_SAVE, 3, _pi)
  for (_i = 0; _i < self.Options_COUNT; _i++) {
    _text = self.Options_dg.get(_i, 0)
    _xl = self.Options_dg.get(_i, 1)
    _yt = self.Options_dg.get(_i, 2)
    _pi = self.Options_dg.get(_i, 3)
    draw_text_(_xl, _yt, _text, -1, _pi)
  }
  // -------------------------------------------------------------------------------
  draw_sprite_(
    self.Cursor_SPRITE,
    0,
    self.Cursor_XC,
    self.Cursor_YC + self.Options_idx * self.PAD1,
    G.PI_GUI1,
  )
}

