/**
 * `global.palette_image` as data. ZALiA draws the current scene palette string into a
 * `PAL_PER_SCENE(+permutations)` × 8 sprite (`palSpr_changeColors`) that the palette-swap shader samples.
 * Here it is an array of palettes × 8 RGB colours plus a version counter; the adapter uploads it as a
 * texture whenever `version` changes. `pal_swap_set/reset` become the current palette index that draw
 * commands carry (`DrawCmd.palIdx`).
 *
 * FIDELITY: ZALiA kept both `global.palette_image_w` and `global.palette_image_W` (and `_h/_H`); the
 * uppercase ones were write-only. There is one `width`/`height` here.
 */
import { bgrToRgb, COLORS_PER_PALETTE } from './colors'
import { palettesOf } from './palString'

export class PaletteImage {
  /** `palettes[pi][colorIdx]` as `0xRRGGBB` (renderer order). */
  palettes: number[][] = []
  /** Bumped on every change; the adapter compares it to know when to re-upload. */
  version = 0
  /** `global.palette_image_w` — number of palettes (texture width). */
  get width(): number {
    return this.palettes.length
  }
  /** `global.palette_image_h` — colours per palette (texture height). */
  get height(): number {
    return COLORS_PER_PALETTE
  }
  /** Rebuild from a palette string (`pal_rm_curr`). */
  setFromString(pal: string): void {
    this.palettes = palettesOf(pal).map((row) => row.map(bgrToRgb))
    this.version++
  }
  /** Flat RGBA bytes, row-major by colour (y) then palette (x): what a texture upload wants. */
  toRgba(): Uint8Array {
    const w = this.width
    const h = this.height
    const out = new Uint8Array(w * h * 4)
    for (let x = 0; x < w; x++) {
      for (let y = 0; y < h; y++) {
        const c = this.palettes[x]?.[y] ?? 0
        const o = (y * w + x) * 4
        out[o] = (c >> 16) & 0xff
        out[o + 1] = (c >> 8) & 0xff
        out[o + 2] = c & 0xff
        out[o + 3] = 0xff
      }
    }
    return out
  }
}
