/** ocs: Off Camera State. w bits 0001 1111 (edges→centre: $10 $8 $4 $2 $1), h bits 1110 0000 ($80 top, $40 mid, $20 btm). */
import type { GoBody } from './body'
import { env, viewXL, viewXR, viewYB, viewYT } from './env'

/** `GO_update_ocs()` */
export function GO_update_ocs(self: GoBody): void {
  const g = env.game()
  const DEBUG1 = g.can_draw_ocs && g.DevTools_state
  self.ocs = 0
  // X axis: bit $04 centre; $10/$01 outer edges; $08/$02 one unit width (8, or 4 if ww==8) in from the edges
  for (let i = 0; i < 3; i++) {
    let xOff = 0
    switch (i) {
      case 0:
        xOff = self.ww_ // bit $4 (center)
        break
      case 1:
        xOff = 8 >> +(self.ww === 8) // bits $8 & $2 (1 uw from edge)
        break
      default:
        xOff = 0 // bits $10 & $1 (edges)
    }
    // LEFT
    let x = self.x - self.ww_ + xOff
    if (x >= viewXR() || x <= viewXL()) self.ocs |= 0x4 << i // bits $4, $8, $10
    if (DEBUG1) env.fn.db_GO_update_cam_vars(self, 'x', 2 - i, x)
    // RIGHT
    x = self.x + self.ww_ - xOff
    if (x >= viewXR() || x <= viewXL()) self.ocs |= 0x4 >> i // bits $4, $2, $1
    if (DEBUG1) env.fn.db_GO_update_cam_vars(self, 'x', 2 + i, x)
  }
  // Y axis: $80 top pixel outside, $40 more than half outside, $20 bottom pixel outside
  const YT = viewYT() - 8 // 0. Y Top
  const YB = viewYB() + 8 // $F0. Y Bot
  if (self.y - self.hh_ >= YB || self.y - self.hh_ < YT) self.ocs |= 0x80 // top above or below
  if (self.y + self.hh_ <= YT || self.y + self.hh_ > YB) self.ocs |= 0x20 // btm above or below
  if (self.y < YT || self.y > YB) self.ocs |= 0x40 // mid above or below
  if (DEBUG1) {
    env.fn.db_GO_update_cam_vars(self, 'y', 0, self.y - self.hh_)
    env.fn.db_GO_update_cam_vars(self, 'y', 1, self.y)
    env.fn.db_GO_update_cam_vars(self, 'y', 2, self.y + self.hh_)
  }
}

type O = { ocs: number }
/** `ocsH1` — any width on camera. GML: `ocs&$1F < $1F` (bitwise binds tighter). */
export const ocsH1 = (o: O): boolean => (o.ocs & 0x1f) < 0x1f
/** `ocsH2` — at least 8 (4 if ww==8) px of width on camera: $18 clear OR $3 clear. */
export const ocsH2 = (o: O): boolean => !(o.ocs & 0x18) || !(o.ocs & 0x3)
/** `ocsH3` — all width on camera. */
export const ocsH3 = (o: O): boolean => (o.ocs & 0x1f) === 0
/** `ocsH4` — at least half width on camera. */
export const ocsH4 = (o: O): boolean => !(o.ocs & 0x4)
/** `ocsV1` — any height on camera. */
export const ocsV1 = (o: O): boolean => (o.ocs & 0xe0) < 0xe0
/** `ocsV3` — all height on camera. */
export const ocsV3 = (o: O): boolean => (o.ocs & 0xe0) === 0
/** `ocsHV1` — any width AND any height. */
export const ocsHV1 = (o: O): boolean => ocsH1(o) && o.ocs < 0xe0
/** `ocsHV2` — ≥4/8 px width AND any height. */
export const ocsHV2 = (o: O): boolean => ocsH2(o) && o.ocs < 0xe0
/** `ocsHV3` — at least half width AND any height. */
export const ocsHV3 = (o: O): boolean => !(o.ocs & 0x4) && o.ocs < 0xe0
/** `ocsHV4` — all width AND all height. */
export const ocsHV4 = (o: O): boolean => ocsH3(o) && ocsV3(o)
